// p5.js 1.11 — a still painting, with no external assets.
function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();

  const c = drawingContext;
  background("#d8cdb7");

  // The exposed, lightly flecked paper.
  noStroke();
  for (let i = 0; i < 26000; i++) {
    fill(95, 75, 55, random(3, 14));
    ellipse(random(width), random(height), random(0.5, 2.3));
  }

  // An imperfect painted edge.
  const field = new Path2D();
  field.moveTo(53, 54);
  for (let x = 53; x <= 1547; x += 9)
    field.lineTo(x, 54 + random(-2.5, 2.5));
  for (let y = 54; y <= 1946; y += 9)
    field.lineTo(1547 + random(-2.5, 2.5), y);
  for (let x = 1547; x >= 53; x -= 9)
    field.lineTo(x, 1946 + random(-2.5, 2.5));
  for (let y = 1946; y >= 54; y -= 9)
    field.lineTo(53 + random(-2.5, 2.5), y);
  field.closePath();

  c.save();
  c.clip(field);

  let ground = c.createLinearGradient(180, 90, 1360, 1940);
  ground.addColorStop(0, "#111e31");
  ground.addColorStop(0.48, "#25383c");
  ground.addColorStop(1, "#141f2b");
  c.fillStyle = ground;
  c.fillRect(0, 0, width, height);

  glow(790, 925, 675, 940, [
    [0, "rgba(167,135,78,0.48)"],
    [0.55, "rgba(97,104,77,0.23)"],
    [1, "rgba(40,52,53,0)"]
  ]);

  // Quiet vertical scumbling in the surrounding darkness.
  for (let i = 0; i < 12500; i++) {
    let x = random(50, 1550);
    let y = random(50, 1950);
    let n = noise(x * 0.003, y * 0.003);
    c.strokeStyle = n > 0.5
      ? "rgba(151,161,139,0.035)"
      : "rgba(4,15,31,0.065)";
    c.lineWidth = random(1, 12);
    c.beginPath();
    c.moveTo(x, y);
    c.lineTo(x + random(-8, 8), y + random(8, 75));
    c.stroke();
  }

  // A low, almost submerged horizon.
  for (let i = 0; i < 160; i++) {
    const y = random(1550, 1900);
    c.strokeStyle = `rgba(154,137,100,${random(0.012, 0.045)})`;
    c.lineWidth = random(1, 9);
    c.beginPath();
    c.moveTo(30, y);
    c.bezierCurveTo(470, y - 70, 1130, y + 65, 1580, y - 18);
    c.stroke();
  }

  // Light occupies the interval, rather than either figure.
  glow(801, 892, 374, 589, [
    [0, "rgba(255,237,183,0.94)"],
    [0.23, "rgba(245,211,139,0.81)"],
    [0.55, "rgba(214,161,79,0.42)"],
    [0.8, "rgba(170,121,62,0.14)"],
    [1, "rgba(155,108,53,0)"]
  ]);

  // The two forms are neither duplicates nor a closed enclosure.
  const left = new Path2D(
    "M 747 315 " +
    "C 490 340 310 590 315 890 " +
    "C 318 1140 455 1280 551 1445 " +
    "C 623 1576 570 1672 407 1753 " +
    "C 641 1769 801 1611 723 1420 " +
    "C 662 1264 510 1150 499 938 " +
    "C 487 711 590 495 747 315 Z"
  );

  const right = new Path2D(
    "M 862 388 " +
    "C 1100 430 1303 654 1279 931 " +
    "C 1258 1175 1078 1317 1039 1480 " +
    "C 1009 1610 1123 1717 1293 1760 " +
    "C 1027 1794 842 1640 870 1460 " +
    "C 896 1280 1092 1139 1103 931 " +
    "C 1114 727 1018 521 862 388 Z"
  );

  paintForm(left, [300, 310, 510, 1475],
    [300, 800, 785, 1000],
    ["#112f3c", "#285e68", "#739b93", "#c3caa4"],
    ["#173e51", "#55877f", "#b8c29b", "#091f33"]);

  paintForm(right, [840, 380, 470, 1415],
    [1300, 790, 860, 1060],
    ["#472c3b", "#a44e43", "#d38a60", "#eac897"],
    ["#713d42", "#c9704e", "#f0b57b", "#3e2938"]);

  // Directional brushwork, following the long bodies.
  c.save();
  c.clip(left);
  for (let i = 0; i < 115; i++) {
    const d = random(-95, 100);
    c.strokeStyle = i % 4 === 0
      ? "rgba(209,215,173,0.13)"
      : "rgba(10,39,53,0.15)";
    c.lineWidth = random(0.6, 3.7);
    c.beginPath();
    c.moveTo(741 + d * 0.3, 319);
    c.bezierCurveTo(360 + d, 651, 371 + d, 960, 541 + d, 1243);
    c.bezierCurveTo(748 + d, 1550, 632 + d, 1640, 420 + d, 1755);
    c.stroke();
  }
  c.restore();

  c.save();
  c.clip(right);
  for (let i = 0; i < 115; i++) {
    const d = random(-90, 100);
    c.strokeStyle = i % 4 === 0
      ? "rgba(255,211,146,0.17)"
      : "rgba(85,36,45,0.14)";
    c.lineWidth = random(0.6, 3.7);
    c.beginPath();
    c.moveTo(865 + d * 0.2, 388);
    c.bezierCurveTo(1190 + d, 636, 1250 + d, 958, 1072 + d, 1210);
    c.bezierCurveTo(864 + d, 1518, 955 + d, 1649, 1298 + d, 1764);
    c.stroke();
  }
  c.restore();

  // Broken reflected light along the inward-facing edges.
  edgeLight(
    [747, 315, 590, 495, 487, 711, 499, 938],
    70, [208, 218, 166]
  );
  edgeLight(
    [499, 938, 510, 1150, 662, 1264, 723, 1420],
    75, [239, 205, 134]
  );
  edgeLight(
    [862, 388, 1018, 521, 1114, 727, 1103, 931],
    80, [255, 215, 151]
  );
  edgeLight(
    [1103, 931, 1092, 1139, 896, 1280, 870, 1460],
    70, [255, 203, 126]
  );

  // Fine, irregular strands make a shared cradle, not a binding knot.
  for (let i = 0; i < 77; i++) {
    const t = random();
    const sx = lerp(520, 650, t) + random(-12, 12);
    const sy = lerp(1065, 1290, t) + random(-20, 20);
    const ex = lerp(1088, 957, t) + random(-12, 12);
    const ey = lerp(1080, 1324, t) + random(-20, 20);
    c.strokeStyle = `rgba(245,202,123,${random(0.09, 0.33)})`;
    c.lineWidth = random(0.45, 1.8);
    c.beginPath();
    c.moveTo(sx, sy);
    c.bezierCurveTo(
      652 + random(-45, 45), 1430 + t * 85,
      938 + random(-45, 45), 1425 + t * 85,
      ex, ey
    );
    c.stroke();
  }

  // The shelter opens outward into the world.
  for (let side of [-1, 1]) {
    for (let i = 0; i < 31; i++) {
      const x = side < 0 ? random(425, 565) : random(1140, 1280);
      const y = random(1703, 1758);
      c.strokeStyle = side < 0
        ? `rgba(134,176,157,${random(0.05, 0.18)})`
        : `rgba(220,155,110,${random(0.05, 0.18)})`;
      c.lineWidth = random(0.5, 2.2);
      c.beginPath();
      c.moveTo(x, y);
      c.bezierCurveTo(
        x + side * 100, y + random(35, 95),
        x + side * 235, y - random(10, 75),
        x + side * random(270, 510), y + random(30, 135)
      );
      c.stroke();
    }
  }

  // An unowned, soft concentration of light.
  glow(803, 854, 113, 162, [
    [0, "rgba(255,249,218,0.68)"],
    [0.3, "rgba(255,237,181,0.35)"],
    [1, "rgba(255,220,145,0)"]
  ]);

  // Suspended pigment: densest near the warm interval.
  noStroke();
  for (let i = 0; i < 2400; i++) {
    const x = random(340, 1260);
    const y = random(330, 1500);
    const d = sq((x - 800) / 345) + sq((y - 880) / 550);
    if (random() > exp(-d * 1.8) * 0.45) continue;
    fill(255, random(211, 244), random(142, 193), random(16, 78));
    const r = random(0.6, 2.5);
    ellipse(x, y, r, r * random(0.7, 1.6));
  }

  // A few distant flecks keep the darkness inhabited.
  for (let i = 0; i < 135; i++) {
    const x = random(110, 1490);
    const y = random(150, 1870);
    if (abs(x - 800) < 480 && y < 1510) continue;
    fill(201, 177, 123, random(17, 58));
    ellipse(x, y, random(0.8, 2.6));
  }

  // Final granular veil across the painted surface.
  for (let i = 0; i < 49000; i++) {
    const x = random(50, 1550);
    const y = random(50, 1950);
    fill(random() < 0.5 ? 255 : 0, random(2, 9));
    rect(x, y, random(0.5, 1.8), random(0.5, 2.8));
  }

  c.restore();
}

function glow(x, y, rx, ry, stops) {
  const c = drawingContext;
  c.save();
  c.translate(x, y);
  c.scale(rx, ry);
  const g = c.createRadialGradient(0, 0, 0, 0, 0, 1);
  for (const [at, col] of stops) g.addColorStop(at, col);
  c.fillStyle = g;
  c.fillRect(-1, -1, 2, 2);
  c.restore();
}

function paintForm(path, box, axis, colors, pigments) {
  const c = drawingContext;
  const g = c.createLinearGradient(...axis);
  colors.forEach((col, i) => g.addColorStop(i / (colors.length - 1), col));
  c.fillStyle = g;
  c.fill(path);

  c.save();
  c.clip(path);
  c.lineCap = "round";

  for (let i = 0; i < 12500; i++) {
    const x = random(box[0], box[0] + box[2]);
    const y = random(box[1], box[1] + box[3]);
    const a = atan2((y - 930) * 0.65, x - 800) + HALF_PI;
    const len = random(3, 39);
    const col = color(random(pigments));
    col.setAlpha(random(9, 34));
    c.strokeStyle = col.toString();
    c.lineWidth = random(0.8, 7);
    c.beginPath();
    c.moveTo(x, y);
    c.quadraticCurveTo(
      x + cos(a + 0.16) * len * 0.5,
      y + sin(a + 0.16) * len * 0.5,
      x + cos(a) * len,
      y + sin(a) * len
    );
    c.stroke();
  }

  // Small dark pores and pale, dry-brush skips.
  for (let i = 0; i < 5000; i++) {
    c.fillStyle = i % 3 === 0
      ? "rgba(249,232,187,0.12)"
      : "rgba(12,25,30,0.11)";
    const x = random(box[0], box[0] + box[2]);
    const y = random(box[1], box[1] + box[3]);
    c.fillRect(x, y, random(0.5, 2.2), random(1, 5));
  }
  c.restore();
}

function edgeLight(p, count, rgb) {
  const c = drawingContext;
  for (let i = 0; i < count; i++) {
    const t = random(0.015, 0.975);
    const dt = random(0.002, 0.018);
    const offset = random(-2.8, 2.8);
    const x1 = bezierPoint(p[0], p[2], p[4], p[6], t);
    const y1 = bezierPoint(p[1], p[3], p[5], p[7], t);
    const x2 = bezierPoint(p[0], p[2], p[4], p[6], t + dt);
    const y2 = bezierPoint(p[1], p[3], p[5], p[7], t + dt);
    c.strokeStyle = `rgba(${rgb.join(",")},${random(0.12, 0.48)})`;
    c.lineWidth = random(0.7, 3);
    c.beginPath();
    c.moveTo(x1 + offset, y1);
    c.lineTo(x2 + offset, y2);
    c.stroke();
  }
}

// p5.js 1.11 — a still painting, with no external assets.
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(24, 29, 36);
  ground();

  // Light belongs to the interval, rather than to either form.
  bloom(795, 1000, 600, 790, [166, 116, 65], 0.25);
  bloom(805, 1030, 370, 560, [221, 177, 101], 0.27);
  bloom(805, 990, 185, 370, [248, 215, 153], 0.20);

  underpainting();
  membrane();

  const earth = makeRibbon([
    [565, 350], [290, 470], [235, 950], [420, 1230],
    [525, 1430], [800, 1525], [1030, 1450]
  ], 0);

  const water = makeRibbon([
    [1080, 395], [1285, 585], [1330, 1050], [1090, 1280],
    [940, 1445], [690, 1555], [540, 1465]
  ], 1);

  paintRibbon(earth, 0);
  paintRibbon(water, 1);

  exchangedLight(earth, 0);
  exchangedLight(water, 1);
  suspendedPigment();
  grain();
}

function ground() {
  noStroke();

  // A mottled, stained ground, not a perfectly flat digital field.
  for (let y = 0; y < height; y += 10) {
    for (let x = 0; x < width; x += 10) {
      const n = noise(x * 0.0024, y * 0.0024);
      const warm = noise(x * 0.0015 + 30, y * 0.002);
      fill(
        19 + n * 21 + warm * 9,
        25 + n * 20,
        33 + n * 22,
        180
      );
      rect(x, y, 11, 11);
    }
  }

  bloom(265, 820, 470, 850, [105, 54, 47], 0.15);
  bloom(1335, 1000, 420, 900, [30, 88, 90], 0.14);
  bloom(810, 1640, 690, 250, [91, 51, 55], 0.15);

  for (let i = 0; i < 18000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.005, y * 0.005);
    stroke(135 + n * 30, 122 + n * 25, 110 + n * 25, random(2, 12));
    strokeWeight(random(0.4, 1.8));
    line(x, y, x + random(-3, 3), y + random(3, 18));
  }

  // Long, nearly buried traces of the brush.
  for (let i = 0; i < 180; i++) {
    const x = random(90, 1510);
    const y = random(100, 1900);
    stroke(185, 153, 119, random(2, 7));
    strokeWeight(random(1, 5));
    noFill();
    bezier(x, y, x - 15, y + 30, x + 15, y + 75,
           x + random(-15, 15), y + random(85, 190));
  }
}

function bloom(x, y, rx, ry, rgb, opacity) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(rx, ry);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
  g.addColorStop(0, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${opacity})`);
  g.addColorStop(0.48, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${opacity * 0.48})`);
  g.addColorStop(1, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);
  ctx.fillStyle = g;
  ctx.fillRect(-1, -1, 2, 2);
  ctx.restore();
}

function underpainting() {
  noStroke();
  for (let i = 0; i < 5200; i++) {
    const x = random(370, 1220);
    const y = random(450, 1510);
    const d = sq((x - 805) / 365) + sq((y - 1010) / 560);
    if (d > 1 || random() > (1 - d) * 0.8) continue;
    const n = noise(x * 0.009, y * 0.009);
    fill(181 + 52 * n, 136 + 50 * n, 76 + 50 * n, random(3, 14));
    push();
    translate(x, y);
    rotate(-0.35 + n * 0.6);
    ellipse(0, 0, random(3, 20), random(8, 45));
    pop();
  }

  // Quiet deposits below the meeting of the two currents.
  for (let i = 0; i < 450; i++) {
    const x = randomGaussian(800, 230);
    const y = randomGaussian(1620, 55);
    stroke(151, 112, 94, random(3, 13));
    strokeWeight(random(1, 4));
    line(x, y, x + random(8, 70), y + random(-3, 3));
  }
}

function membrane() {
  noFill();
  for (let i = 0; i < 64; i++) {
    const t = i / 63;
    const y = 760 + t * 485;
    stroke(234, 196, 130, random(8, 27));
    strokeWeight(random(0.5, 1.5));
    bezier(
      365 + 100 * t, y + 45,
      650, y - 120 + 125 * t,
      960, y + 125 - 100 * t,
      1230 - 65 * t, y - 35
    );
  }

  for (let i = 0; i < 18; i++) {
    const x = 650 + i * 17;
    stroke(237, 206, 153, random(5, 14));
    strokeWeight(0.7);
    bezier(x, 650, x - 90, 920, x + 95, 1160, x - 25, 1370);
  }
}

function cubic(a, b, c, d, t) {
  const u = 1 - t;
  return u * u * u * a + 3 * u * u * t * b +
         3 * u * t * t * c + t * t * t * d;
}

function curvePosition(points, t) {
  let p, u;
  if (t <= 0.72) {
    p = points.slice(0, 4);
    u = t / 0.72;
  } else {
    p = points.slice(3, 7);
    u = (t - 0.72) / 0.28;
  }
  return {
    x: cubic(p[0][0], p[1][0], p[2][0], p[3][0], u),
    y: cubic(p[0][1], p[1][1], p[2][1], p[3][1], u)
  };
}

function makeRibbon(points, id) {
  const result = [];
  for (let i = 0; i <= 320; i++) {
    const t = i / 320;
    const p = curvePosition(points, t);
    const a = curvePosition(points, max(0, t - 0.001));
    const b = curvePosition(points, min(1, t + 0.001));
    const length = Math.hypot(b.x - a.x, b.y - a.y);
    let w = 9 + 151 * pow(sin(PI * t), 0.78) * (1 - 0.29 * t);
    w *= 0.94 + 0.12 * noise(t * 8, id * 17);
    result.push({
      x: p.x, y: p.y,
      nx: -(b.y - a.y) / length,
      ny: (b.x - a.x) / length,
      w: w, t: t
    });
  }
  return result;
}

function ribbonPoint(r, i, f, rough = 0) {
  const p = r[constrain(i, 0, r.length - 1)];
  const offset = f * p.w + rough;
  return { x: p.x + p.nx * offset, y: p.y + p.ny * offset };
}

function silhouette(r, dx, dy) {
  beginShape();
  for (let i = 0; i < r.length; i++) {
    const p = ribbonPoint(r, i, 1, (noise(i * 0.19, 3) - 0.5) * 5);
    vertex(p.x + dx, p.y + dy);
  }
  for (let i = r.length - 1; i >= 0; i--) {
    const p = ribbonPoint(r, i, -1, (noise(i * 0.19, 8) - 0.5) * 5);
    vertex(p.x + dx, p.y + dy);
  }
  endShape(CLOSE);
}

function pigment(id, f, t) {
  const inner = id === 0 ? (1 - f) / 2 : (1 + f) / 2;
  const dark = id === 0 ? color(103, 47, 42) : color(28, 75, 81);
  const middle = id === 0 ? color(191, 87, 60) : color(62, 129, 127);
  const light = id === 0 ? color(241, 176, 130) : color(175, 201, 175);
  let c = inner < 0.6
    ? lerpColor(dark, middle, inner / 0.6)
    : lerpColor(middle, light, (inner - 0.6) / 0.4);
  const variation = noise(t * 7, f * 3 + 15, id * 5);
  c = lerpColor(c, color(222, 170, 108), max(0, variation - 0.48) * 0.5);
  return c;
}

function paintRibbon(r, id) {
  noStroke();
  fill(8, 19, 25, 35);
  silhouette(r, 12, 22);
  fill(id === 0 ? color(150, 67, 49) : color(42, 99, 102));
  silhouette(r, 0, 0);

  noFill();
  strokeCap(ROUND);

  // Broad broken strokes leave irregular mineral-colored islands.
  for (let k = 0; k < 1050; k++) {
    const start = floor(random(0, 310));
    const end = min(320, start + floor(random(5, 45)));
    const f = random(-0.94, 0.94);
    const c = pigment(id, f, start / 320);
    c.setAlpha(random(22, 77));
    stroke(c);
    strokeWeight(random(3, 15));
    beginShape();
    for (let i = start; i <= end; i++) {
      const wobble = (noise(i * 0.065, k * 0.08) - 0.5) * 8;
      const p = ribbonPoint(r, i, f, wobble);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Fine bristles follow the turning surface.
  for (let k = 0; k < 800; k++) {
    const f = random(-0.995, 0.995);
    const start = floor(random(0, 285));
    const end = min(320, start + floor(random(20, 170)));
    const c = pigment(id, f, start / 320);
    c.setAlpha(random(35, 110));
    stroke(c);
    strokeWeight(random(0.45, 2));
    beginShape();
    for (let i = start; i <= end; i++) {
      const p = ribbonPoint(
        r, i, f,
        (noise(i * 0.045, k * 0.12 + 50) - 0.5) * 5
      );
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Small exposed flecks interrupt the smoothness of the paint.
  noStroke();
  for (let k = 0; k < 2800; k++) {
    const i = floor(random(r.length));
    const f = random(-0.98, 0.98);
    const p = ribbonPoint(r, i, f);
    const c = pigment(id, f, i / 320);
    c.setAlpha(random(25, 95));
    fill(c);
    ellipse(p.x, p.y, random(0.7, 3.2), random(1, 5));
  }
}

function exchangedLight(r, id) {
  noFill();
  const side = id === 0 ? -1 : 1;

  // The lit edges are discontinuous: contact, not a metallic outline.
  for (let k = 0; k < 95; k++) {
    const start = floor(random(30, 294));
    const end = min(320, start + floor(random(4, 31)));
    const f = side * random(0.84, 1.01);
    stroke(246, 207, 143, random(18, 75));
    strokeWeight(random(0.45, 2.5));
    beginShape();
    for (let i = start; i <= end; i++) {
      const p = ribbonPoint(r, i, f, (noise(i * 0.12, k) - 0.5) * 3);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // A few hues have crossed over without erasing either current.
  for (let k = 0; k < 45; k++) {
    const start = floor(random(230, 307));
    const end = min(320, start + floor(random(5, 20)));
    const f = random(-0.75, 0.75);
    stroke(id === 0 ? color(141, 188, 168, 42) : color(230, 154, 111, 48));
    strokeWeight(random(1, 4));
    beginShape();
    for (let i = start; i <= end; i++) {
      const p = ribbonPoint(r, i, f);
      vertex(p.x, p.y);
    }
    endShape();
  }
}

function suspendedPigment() {
  noStroke();
  for (let i = 0; i < 1100; i++) {
    const y = randomGaussian(1030, 220);
    const axis = 800 + 63 * sin((y - 750) * 0.006);
    const x = randomGaussian(axis, 78);
    if (y < 560 || y > 1370) continue;
    const n = noise(x * 0.012, y * 0.012);
    if (n < 0.43) continue;
    fill(242, 205, 139, random(5, 38));
    const s = random(0.6, 3.1);
    ellipse(x, y, s, s * random(0.7, 1.8));
  }

  // Sparse, soft residue around the upper opening.
  for (let i = 0; i < 200; i++) {
    const x = randomGaussian(820, 125);
    const y = randomGaussian(520, 105);
    fill(189, 164, 122, random(3, 14));
    ellipse(x, y, random(1, 3), random(2, 7));
  }
}

function grain() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = 4 * (y * width + x);
      const tooth = random(-3.2, 3.2);
      const weave = (x % 3 === 0 ? -0.6 : 0.25) +
                    (y % 4 === 0 ? -0.6 : 0.2);
      pixels[i]     = constrain(pixels[i]     + tooth + weave, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + tooth + weave, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + tooth + weave, 0, 255);
    }
  }
  updatePixels();
}

// Self-contained p5.js 1.11 sketch.
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  noStroke();
}

function draw() {
  paintGround();

  const warm = {
    dark: color(69, 28, 43),
    middle: color(181, 77, 61),
    light: color(249, 179, 113),
    pale: color(255, 216, 154)
  };

  const cool = {
    dark: color(15, 48, 58),
    middle: color(48, 113, 119),
    light: color(129, 179, 158),
    pale: color(214, 221, 174)
  };

  const left = makePath([
    [830, 1785, 655, 1660, 425, 1480, 395, 1180],
    [395, 1180, 365, 875, 460, 615, 660, 510],
    [660, 510, 755, 458, 834, 483, 894, 424]
  ], 158, 13);

  const right = makePath([
    [804, 1785, 1010, 1695, 1226, 1400, 1195, 1110],
    [1195, 1110, 1179, 820, 1070, 618, 987, 547],
    [987, 547, 949, 510, 963, 459, 1018, 433]
  ], 143, 71);

  undercurrents();
  floatingPigment();

  paintRibbon(right, cool, -1, 71);
  paintRibbon(left, warm, 1, 13);

  // A few cool passages cross the warm foot: neither current owns the join.
  for (let i = 0; i < 95; i++) {
    let t = random(0.012, 0.13);
    let a = random(-0.72, 0.65);
    let c = lerpColor(cool.middle, cool.light, random(0.2, 0.8));
    c.setAlpha(random(35, 100));
    fill(c);
    strip(right, t, min(t + random(0.025, 0.11), 0.24),
          a, a + random(0.012, 0.06), i + 100);
  }

  sharedThreads();
  goldDust();
  surfaceGrain();
}

function paintGround() {
  // Broad pigment washes, with fine irregularities inside every tile.
  noStroke();
  for (let y = 0; y < height; y += 4) {
    for (let x = 0; x < width; x += 4) {
      let dx = (x - 801) / 370;
      let dy = (y - 990) / 620;
      let light = exp(-1.45 * (dx * dx + dy * dy));
      let halo = exp(-0.49 * (dx * dx + dy * dy));

      let redWash = exp(
        -sq((x - 370) / 400) - sq((y - 1080) / 760)
      );
      let blueWash = exp(
        -sq((x - 1250) / 440) - sq((y - 1000) / 850)
      );

      let cloud = noise(x * 0.003, y * 0.003);
      let grain = (noise(x * 0.19, y * 0.19) - 0.5) * 10;
      let r = 17 + 35 * redWash + 42 * halo;
      let g = 24 + 19 * blueWash + 28 * halo;
      let b = 36 + 21 * blueWash + 9 * halo;

      let amount = constrain(light * 1.15 + (cloud - 0.5) * 0.065, 0, 1);
      r = lerp(r, 250, amount);
      g = lerp(g, 226, amount);
      b = lerp(b, 170, amount);

      fill(r + grain, g + grain, b + grain);
      rect(x, y, 4, 4);
    }
  }

  // Thin scumbles remain visible in the outer dark.
  for (let i = 0; i < 21000; i++) {
    let x = random(width);
    let y = random(height);
    let c = random() < 0.5 ? color(168, 131, 111) : color(8, 23, 33);
    c.setAlpha(random(3, 15));
    fill(c);
    ellipse(x, y, random(1, 4), random(2, 15));
  }

  // Quiet vertical abrasions in the ground.
  strokeWeight(0.6);
  for (let i = 0; i < 230; i++) {
    let x = random(70, 1530);
    let y = random(80, 1920);
    stroke(205, 181, 140, random(3, 12));
    line(x, y, x + random(-4, 4), y + random(15, 110));
  }
  noStroke();
}

function makePath(segments, broadness, seed) {
  let points = [];
  const count = 420;

  for (let i = 0; i <= count; i++) {
    let t = i / count;
    let u = t * segments.length;
    let index = min(floor(u), segments.length - 1);
    let v = t === 1 ? 1 : u - index;
    let s = segments[index];

    let x = bezierPoint(s[0], s[2], s[4], s[6], v);
    let y = bezierPoint(s[1], s[3], s[5], s[7], v);
    let tx = bezierTangent(s[0], s[2], s[4], s[6], v);
    let ty = bezierTangent(s[1], s[3], s[5], s[7], v);
    let length = sqrt(tx * tx + ty * ty);
    let w = 2 + broadness * pow(sin(PI * t), 0.65);
    w *= 0.87 + noise(t * 5, seed) * 0.27;

    points.push({
      x, y,
      nx: -ty / length,
      ny: tx / length,
      w
    });
  }
  return points;
}

function pathAt(path, t) {
  let index = constrain(t, 0, 1) * (path.length - 1);
  let a = floor(index);
  let b = min(a + 1, path.length - 1);
  let f = index - a;
  return {
    x: lerp(path[a].x, path[b].x, f),
    y: lerp(path[a].y, path[b].y, f),
    nx: lerp(path[a].nx, path[b].nx, f),
    ny: lerp(path[a].ny, path[b].ny, f),
    w: lerp(path[a].w, path[b].w, f)
  };
}

function strip(path, start, end, a, b, seed) {
  let steps = max(8, ceil((end - start) * 220));
  beginShape();
  for (let side = 0; side < 2; side++) {
    for (let j = 0; j <= steps; j++) {
      let f = side === 0 ? j / steps : 1 - j / steps;
      let t = lerp(start, end, f);
      let p = pathAt(path, t);
      let offset = side === 0 ? a : b;
      let rag = (noise(t * 95, seed) - 0.5) * 0.037;
      // Rounded, irregular ends rather than hard rectangular brush marks.
      let taper = 0.3 + 0.7 * pow(sin(PI * f), 0.25);
      let center = (a + b) / 2;
      offset = center + (offset - center) * taper + rag;
      vertex(p.x + p.nx * p.w * offset,
             p.y + p.ny * p.w * offset);
    }
  }
  endShape(CLOSE);
}

function paintRibbon(path, palette, inward, seed) {
  noStroke();

  push();
  translate(9, 24);
  fill(9, 17, 25, 65);
  strip(path, 0, 1, -1.08, 1.08, seed);
  pop();

  fill(palette.dark);
  strip(path, 0, 1, -1, 1, seed);

  // Broad underpainting.
  for (let i = 0; i < 175; i++) {
    let a = random(-0.94, 0.82);
    let t = random(0, 0.92);
    let c = lerpColor(palette.dark, palette.middle, random(0.5, 1));
    c.setAlpha(random(90, 165));
    fill(c);
    strip(path, t, min(1, t + random(0.12, 0.42)),
          a, min(0.98, a + random(0.08, 0.26)), seed + i);
  }

  // Dry, lengthwise strokes build the body of the paint.
  for (let i = 0; i < 1500; i++) {
    let a = random(-0.95, 0.95);
    let t = random(0.005, 0.98);
    let inner = a * inward;
    let illumination = constrain(map(inner, -1, 1, 0.05, 0.93), 0, 1);
    illumination *= 0.64 + 0.36 * sin(PI * t);

    let c = lerpColor(palette.middle, palette.light, illumination);
    if (random() < 0.23) {
      c = lerpColor(c, palette.dark, random(0.15, 0.65));
    }
    c.setAlpha(random(32, 120));
    fill(c);

    strip(path, t, min(0.998, t + random(0.012, 0.19)),
          a, a + random(0.006, 0.07), seed + i * 0.17);
  }

  // Broken light catches the inward-facing edges.
  for (let i = 0; i < 170; i++) {
    let t = random(0.10, 0.94);
    let a = inward * random(0.72, 0.98);
    let c = lerpColor(palette.light, palette.pale, random());
    c.setAlpha(random(35, 145));
    fill(c);
    strip(path, t, min(0.99, t + random(0.008, 0.075)),
          a, a + random(0.004, 0.023), seed + 500 + i);
  }

  // Pigment granulation and little exposed islands of underpaint.
  for (let i = 0; i < 10500; i++) {
    let t = random(0.015, 0.985);
    let p = pathAt(path, t);
    let a = random(-0.98, 0.98);
    let x = p.x + p.nx * p.w * a;
    let y = p.y + p.ny * p.w * a;
    let c = random() < 0.66 ? palette.dark : palette.pale;
    fill(red(c), green(c), blue(c), random(8, 42));
    ellipse(x, y, random(0.7, 3.7), random(0.8, 4.5));
  }
}

function undercurrents() {
  noFill();
  for (let i = 0; i < 150; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let x = 805 + side * random(60, 260);
    let y = random(1510, 1650);
    if (side < 0) stroke(183, 109, 79, random(12, 45));
    else stroke(85, 147, 145, random(12, 45));
    strokeWeight(random(0.5, 3));
    bezier(x, y,
           x + side * 15, 1740,
           800 - side * random(40, 155), 1770,
           800 + side * random(60, 255), random(1830, 1940));
  }
  noStroke();
}

function floatingPigment() {
  noStroke();
  for (let i = 0; i < 4500; i++) {
    let x = randomGaussian(800, 210);
    let y = randomGaussian(1010, 330);
    if (x < 485 || x > 1110 || y < 470 || y > 1570) continue;
    let size = random(1, 9);
    fill(246, 216, 149, random(3, 19));
    ellipse(x, y, size, size * random(0.5, 2.8));
  }
}

function sharedThreads() {
  noFill();

  // A loose, imperfect weave spans the lower opening.
  for (let i = 0; i < 100; i++) {
    let f = i / 99;
    let x1 = lerp(507, 652, f) + random(-10, 10);
    let x2 = lerp(1110, 987, f) + random(-10, 10);
    let y1 = lerp(1190, 1530, f) + random(-15, 15);
    let y2 = lerp(1285, 1495, f) + random(-20, 20);

    stroke(239, 194, 125, random(15, 65));
    strokeWeight(random(0.45, 1.6));
    bezier(x1, y1,
           680, y1 + random(90, 180),
           902, y2 + random(60, 155),
           x2, y2);
  }

  // Sparse finer strands reach farther into the light.
  for (let i = 0; i < 19; i++) {
    let y = random(910, 1270);
    stroke(255, 230, 175, random(20, 65));
    strokeWeight(random(0.4, 1));
    bezier(545 + random(-15, 25), y,
           715, y + 160,
           903, y - 30,
           1053 + random(-20, 25), y + random(45, 170));
  }
  noStroke();
}

function goldDust() {
  for (let i = 0; i < 1200; i++) {
    let x = randomGaussian(808, 115);
    let y = randomGaussian(1100, 235);
    if (y < 605 || y > 1510) continue;

    let size = random() < 0.96 ? random(0.7, 2.7) : random(3, 6);
    fill(255, 238, 183, random(25, 105));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    beginShape();
    vertex(-size, 0);
    vertex(-size * 0.2, -size * 0.65);
    vertex(size * 0.8, -size * 0.25);
    vertex(size * 0.3, size);
    endShape(CLOSE);
    pop();
  }
}

function surfaceGrain() {
  noStroke();
  for (let i = 0; i < 95000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.52) fill(255, 238, 208, random(3, 13));
    else fill(10, 16, 24, random(3, 15));
    rect(x, y, random(0.5, 1.6), random(0.5, 2));
  }
}

// p5.js 1.11 — self-contained, deterministic, still image.
const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();

  paintGround();
  groundMarks();

  const warm = {
    cx: 790, cy: 1010, rx: 425, ry: 615,
    a: 1.23, b: 4.67, width: 190, seed: 13,
    inner: [247, 219, 170],
    middle: [194, 100, 75],
    outer: [85, 45, 64]
  };

  const cool = {
    cx: 830, cy: 1020, rx: 425, ry: 650,
    a: -1.31, b: 1.76, width: 168, seed: 51,
    inner: [235, 225, 181],
    middle: [91, 150, 140],
    outer: [28, 74, 85]
  };

  ribbonShadow(warm);
  ribbonShadow(cool);
  paintRibbon(warm);
  paintRibbon(cool);

  // The shared light brushes both inward-facing surfaces.
  innerScumble(warm);
  innerScumble(cool);

  joiningThreads();
  loosePigment(warm);
  loosePigment(cool);
  quietDust();
  canvasGrain();
}

function paintGround() {
  const g = createGraphics(400, 500);
  g.pixelDensity(1);
  g.loadPixels();

  for (let y = 0; y < g.height; y++) {
    for (let x = 0; x < g.width; x++) {
      const X = x * 4;
      const Y = y * 4;
      const dx = (X - 805) / 455;
      const dy = (Y - 1030) / 675;
      const cloud = noise(X * 0.003, Y * 0.003);
      const light = constrain(
        exp(-(dx * dx + dy * dy) * 1.13) +
        (cloud - 0.5) * 0.065,
        0, 1
      );

      const violet = exp(
        -sq((X - 290) / 520) - sq((Y - 580) / 650)
      );
      const teal = exp(
        -sq((X - 1250) / 550) - sq((Y - 1510) / 610)
      );

      const tooth = (noise(X * 0.047, Y * 0.047) - 0.5) * 8;
      const i = 4 * (x + y * g.width);

      g.pixels[i] =
        lerp(17 + violet * 20, 247, light) + tooth;
      g.pixels[i + 1] =
        lerp(27 + teal * 13, 223, light) + tooth;
      g.pixels[i + 2] =
        lerp(41 + violet * 12 + teal * 8, 178, light) + tooth;
      g.pixels[i + 3] = 255;
    }
  }

  g.updatePixels();
  image(g, 0, 0, W, H);
  g.remove();
}

function groundMarks() {
  noFill();

  // Broad, nearly submerged movements in the underpainting.
  for (let i = 0; i < 190; i++) {
    const side = random() < 0.5 ? -1 : 1;
    const x = 800 + side * random(480, 850);
    const y = random(150, 1900);
    stroke(
      side < 0 ? 118 : 66,
      side < 0 ? 74 : 126,
      side < 0 ? 91 : 133,
      random(2, 7)
    );
    strokeWeight(random(12, 55));
    bezier(
      x, y,
      x - side * 100, y - 190,
      x - side * 210, y - 300,
      x - side * 140, y - 480
    );
  }

  // Small broken weave marks, not a uniform digital texture.
  strokeWeight(1);
  for (let i = 0; i < 11000; i++) {
    const x = random(W);
    const y = random(H);
    const pale = random() < 0.48;
    stroke(pale ? 220 : 8, pale ? 204 : 19, pale ? 172 : 30,
           random(3, 12));
    const len = random(1, 7);
    line(x, y, x + random(-0.7, 0.7), y + len);
  }
}

function ribbonPoint(r, t, s) {
  const a = lerp(r.a, r.b, t);
  const envelope = pow(max(0, sin(PI * t)), 0.62);
  const breathing = 0.82 + 0.23 * noise(r.seed, t * 4);
  const width = r.width * envelope * breathing;

  const waviness =
    (noise(r.seed + 10, t * 8) - 0.5) * 27 +
    sin(t * 19 + r.seed) * 4;

  // The oval leans; its surfaces swell independently.
  const x = r.cx + r.rx * cos(a) + 88 * sin(a);
  const y = r.cy + r.ry * sin(a);

  const nx = cos(a);
  const ny = sin(a) * 0.77;
  const n = sqrt(nx * nx + ny * ny);

  const rough =
    (noise(r.seed + 40 + s * 2, t * 49) - 0.5) *
    (3 + abs(s) * 8);

  return {
    x: x + (s * width + waviness + rough) * nx / n,
    y: y + (s * width + waviness + rough) * ny / n,
    nx: nx / n,
    ny: ny / n
  };
}

function ribbonColor(r, s) {
  const u = constrain((s + 1) / 2, 0, 1);
  if (u < 0.51) {
    return lerpColor(color(...r.inner), color(...r.middle), u / 0.51);
  }
  return lerpColor(
    color(...r.middle), color(...r.outer), (u - 0.51) / 0.49
  );
}

function ribbonShadow(r) {
  noFill();
  for (let k = 10; k >= 1; k--) {
    stroke(12, 27, 35, 3);
    strokeWeight(r.width * 1.4 + k * 10);
    beginShape();
    for (let j = 8; j <= 112; j++) {
      const p = ribbonPoint(r, j / 120, 0.15);
      vertex(p.x + 13, p.y + 19);
    }
    endShape();
  }
}

function paintRibbon(r) {
  noStroke();
  const bands = 112;
  const steps = 170;

  // Narrow, irregular strips behave like a loaded, broad brush.
  for (let k = 0; k < bands; k++) {
    const s0 = map(k, 0, bands, -1, 1);
    const s1 = map(k + 1.4, 0, bands, -1, 1);
    const c = ribbonColor(r, (s0 + s1) / 2);
    const variation = random(-7, 7);
    fill(
      red(c) + variation,
      green(c) + variation,
      blue(c) + variation,
      238
    );

    beginShape();
    for (let j = 0; j <= steps; j++) {
      const p = ribbonPoint(r, j / steps, s0);
      vertex(p.x, p.y);
    }
    for (let j = steps; j >= 0; j--) {
      const p = ribbonPoint(r, j / steps, s1);
      vertex(p.x, p.y);
    }
    endShape(CLOSE);
  }

  noFill();
  strokeCap(ROUND);

  // Individual bristles: long direction, short interruptions.
  for (let i = 0; i < 4900; i++) {
    const t0 = random(0.012, 0.975);
    const t1 = min(0.993, t0 + random(0.003, 0.068));
    const s = random(-1.035, 1.035);
    const c = ribbonColor(r, s);
    const lift = random(-38, 38);
    stroke(
      red(c) + lift,
      green(c) + lift * 0.85,
      blue(c) + lift * 0.65,
      random(20, 83)
    );
    strokeWeight(random(0.45, 2.9));

    beginShape();
    for (let j = 0; j <= 9; j++) {
      const t = lerp(t0, t1, j / 9);
      const p = ribbonPoint(r, t, s + sin(j * 0.5) * 0.007);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Granular deposits of pigment and small dry-brush absences.
  noStroke();
  for (let i = 0; i < 5700; i++) {
    const t = random(0.02, 0.98);
    const s = random(-1, 1);
    const p = ribbonPoint(r, t, s);
    const c = ribbonColor(r, s);
    const d = random(-45, 32);
    fill(red(c) + d, green(c) + d, blue(c) + d, random(12, 55));
    ellipse(p.x, p.y, random(0.8, 4.8), random(1, 6));
  }
}

function innerScumble(r) {
  noFill();
  for (let i = 0; i < 350; i++) {
    const t0 = random(0.12, 0.86);
    const length = random(0.004, 0.04);
    const s = random(-1.07, -0.72);
    stroke(255, 233, 182, random(10, 45));
    strokeWeight(random(0.5, 2.6));
    beginShape();
    for (let j = 0; j <= 8; j++) {
      const p = ribbonPoint(r, t0 + length * j / 8, s);
      vertex(p.x, p.y);
    }
    endShape();
  }
}

function joiningThreads() {
  noFill();

  // A few strands of warmth cross the lower opening.
  // Their spacing stays irregular, more fibers than ornament.
  for (let i = 0; i < 30; i++) {
    const q = random(-30, 30);
    stroke(239, 193 + random(-12, 20), 125, random(12, 48));
    strokeWeight(random(0.6, 2.1));
    bezier(
      478 + q * 0.3, 1210 + q,
      495 + q, 1540 + q,
      1025 + q, 1790 - q * 0.3,
      1194 + q * 0.25, 1280 - q
    );
  }

  // The upper opening is intentionally not closed.
  for (let i = 0; i < 16; i++) {
    const q = random(-17, 17);
    stroke(225, 213, 170, random(9, 30));
    strokeWeight(random(0.5, 1.4));
    bezier(
      430 + q, 751,
      457 + q, 554,
      601 + q, 398,
      743 + q * 0.4, 397 + q
    );
  }
}

function loosePigment(r) {
  noStroke();
  for (let i = 0; i < 750; i++) {
    const t = random(0.035, 0.97);
    const s = random() < 0.6 ? random(1, 1.17) : random(-1.15, -1);
    const p = ribbonPoint(r, t, s);
    const c = ribbonColor(r, constrain(s, -1, 1));
    fill(red(c), green(c), blue(c), random(8, 65));
    const size = random(0.6, 3.4);
    ellipse(p.x + random(-3, 3), p.y + random(-3, 3), size, size * 1.4);
  }
}

function quietDust() {
  noStroke();

  // Sparse, almost invisible material in the luminous empty space.
  for (let i = 0; i < 1100; i++) {
    const x = random(545, 1060);
    const y = random(610, 1450);
    const d = sq((x - 805) / 260) + sq((y - 1030) / 430);
    if (d > 1 || random() > 0.55) continue;
    fill(135, 111, 83, random(3, 13));
    ellipse(x, y, random(0.5, 2), random(0.5, 3));
  }
}

function canvasGrain() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    const row = (y % 4 === 0) ? -0.7 : 0.2;
    for (let x = 0; x < W; x++) {
      const i = 4 * (x + y * W);
      const grain = random(-3.5, 3.5) + row;
      const thread = (x % 5 === 0) ? 0.5 : 0;
      pixels[i] += grain + thread;
      pixels[i + 1] += grain + thread;
      pixels[i + 2] += grain;
    }
  }
  updatePixels();
}

// p5.js 1.11 — self-contained, still image
let shores = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  paintGround();

  shores = [
    {
      p: [
        { x: 704, y: 275 },
        { x: 140, y: 426 },
        { x: 200, y: 1400 },
        { x: 757, y: 1712 }
      ],
      inward: -1,
      width: 185,
      phase: 2.8,
      dark: color(75, 43, 44),
      middle: color(157, 73, 53),
      light: color(234, 164, 104)
    },
    {
      p: [
        { x: 1057, y: 354 },
        { x: 1510, y: 626 },
        { x: 1428, y: 1487 },
        { x: 827, y: 1744 }
      ],
      inward: 1,
      width: 172,
      phase: 8.1,
      dark: color(20, 55, 65),
      middle: color(39, 100, 106),
      light: color(155, 184, 151)
    }
  ];

  // Broad, translucent shadows let the forms inhabit the ground.
  for (let s of shores) {
    for (let k = 15; k >= 1; k--) {
      silhouette(s, 1 + k * 0.025, color(12, 24, 30, 3), 10, 19);
    }
  }

  for (let s of shores) paintShore(s);

  paintConnections();
  paintGerm();
  paintMotes();
  surfaceGrain();
}

function paintGround() {
  background(18, 29, 40);
  loadPixels();

  // A granular underpainting, rather than a perfectly smooth gradient.
  const step = 4;
  for (let y = 0; y < height; y += step) {
    for (let x = 0; x < width; x += step) {
      const dx = (x - 808) / 538;
      const dy = (y - 996) / 824;
      const cloud = noise(x * 0.0028, y * 0.0028);
      const light = constrain(
        exp(-1.48 * (dx * dx + dy * dy)) +
        (cloud - 0.5) * 0.105,
        0, 1
      );
      const tooth = random(-3.4, 3.4);
      const r = 17 + light * 203 + tooth;
      const g = 29 + light * 150 + tooth;
      const b = 40 + light * 70 + tooth;

      for (let yy = y; yy < min(y + step, height); yy++) {
        for (let xx = x; xx < min(x + step, width); xx++) {
          const i = 4 * (xx + yy * width);
          pixels[i] = r;
          pixels[i + 1] = g;
          pixels[i + 2] = b;
          pixels[i + 3] = 255;
        }
      }
    }
  }
  updatePixels();

  // Scumbled brush residue.
  noFill();
  for (let i = 0; i < 23500; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.006, y * 0.006);
    stroke(
      i % 3 === 0 ? color(221, 192, 139, random(3, 12))
                  : color(9, 26, 37, random(3, 11))
    );
    strokeWeight(random(0.5, 2.4));
    const a = -0.3 + n * 1.2;
    const len = random(2, 15);
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }

  // Quiet, almost erased sediment near the foot of the painting.
  for (let j = 0; j < 95; j++) {
    const y = random(1720, 1930);
    stroke(110, 126, 119, random(2, 9));
    strokeWeight(random(0.5, 2));
    beginShape();
    const start = random(180, 650);
    const end = random(960, 1450);
    for (let x = start; x < end; x += 18) {
      vertex(x, y + 13 * noise(x * 0.004, j * 0.1));
    }
    endShape();
  }
}

function frameAt(s, t) {
  t = constrain(t, 0, 1);
  const p = s.p;
  const x = bezierPoint(p[0].x, p[1].x, p[2].x, p[3].x, t);
  const y = bezierPoint(p[0].y, p[1].y, p[2].y, p[3].y, t);
  let tx = bezierTangent(p[0].x, p[1].x, p[2].x, p[3].x, t);
  let ty = bezierTangent(p[0].y, p[1].y, p[2].y, p[3].y, t);
  const len = sqrt(tx * tx + ty * ty);
  tx /= len;
  ty /= len;

  const w = s.width * pow(max(0, sin(PI * t)), 0.58) *
    (0.92 + 0.12 * sin(t * TWO_PI + s.phase) +
     0.065 * (noise(t * 8, s.phase) - 0.5));

  return { x, y, tx, ty, nx: -ty, ny: tx, w };
}

function shorePoint(s, t, u, scale = 1) {
  const f = frameAt(s, t);
  const irregularity =
    (noise(t * 32, u * 2 + 6, s.phase) - 0.5) *
    7 * sin(PI * constrain(t, 0, 1));
  const d = f.w * u * scale + irregularity;
  return { x: f.x + f.nx * d, y: f.y + f.ny * d };
}

function silhouette(s, scale, c, ox = 0, oy = 0) {
  noStroke();
  fill(c);
  beginShape();
  for (let i = 0; i <= 240; i++) {
    const p = shorePoint(s, i / 240, -1, scale);
    vertex(p.x + ox, p.y + oy);
  }
  for (let i = 240; i >= 0; i--) {
    const p = shorePoint(s, i / 240, 1, scale);
    vertex(p.x + ox, p.y + oy);
  }
  endShape(CLOSE);
}

function pigment(s, t, u) {
  const facing = (u * s.inward + 1) * 0.5;
  const variation = noise(t * 9, u * 3 + 7, s.phase);
  const body = lerpColor(s.dark, s.middle, 0.25 + variation * 0.72);
  return lerpColor(body, s.light, pow(facing, 3.2) * 0.81);
}

function paintShore(s) {
  silhouette(s, 1, s.dark);

  // Small overlapping patches build up the body of the paint.
  noStroke();
  for (let i = 0; i < 255; i++) {
    const t0 = i / 255;
    const t1 = min(1, (i + 1.7) / 255);
    for (let j = 0; j < 27; j++) {
      const u0 = map(j, 0, 27, -1, 1);
      const u1 = map(j + 1.15, 0, 27, -1, 1);
      const a = shorePoint(s, t0, u0);
      const b = shorePoint(s, t0, min(1, u1));
      const c = shorePoint(s, t1, min(1, u1));
      const d = shorePoint(s, t1, u0);
      fill(pigment(s, t0, (u0 + u1) / 2));
      quad(a.x, a.y, b.x, b.y, c.x, c.y, d.x, d.y);
    }
  }

  // Broken longitudinal bristles preserve the sweep of a hand.
  noFill();
  for (let i = 0; i < 8500; i++) {
    const t = random(0.012, 0.988);
    const u = random(-0.99, 0.99);
    const span = random(0.002, 0.021);
    let c = pigment(s, t, u);
    c = lerpColor(
      c,
      random() < 0.58 ? s.light : s.dark,
      random(0.1, 0.48)
    );
    c.setAlpha(random(22, 108));
    stroke(c);
    strokeWeight(random(0.45, 3.2));
    beginShape();
    for (let k = 0; k <= 5; k++) {
      const tt = constrain(t + span * (k / 5 - 0.5), 0, 1);
      const uu = constrain(u + 0.012 * sin(k + t * 37), -1, 1);
      const p = shorePoint(s, tt, uu);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Intermittent light on the edge, never a hard outline.
  for (let j = 0; j < 160; j++) {
    const t = random(0.08, 0.94);
    const u = s.inward * random(0.91, 0.998);
    const a = shorePoint(s, t, u);
    const b = shorePoint(s, min(0.99, t + random(0.003, 0.015)), u);
    stroke(red(s.light), green(s.light), blue(s.light), random(35, 100));
    strokeWeight(random(0.6, 2.1));
    line(a.x, a.y, b.x, b.y);
  }

  // Pinholes and granular pigment.
  noStroke();
  for (let i = 0; i < 6500; i++) {
    const t = random(0.018, 0.982);
    const u = random(-0.98, 0.98);
    const p = shorePoint(s, t, u);
    fill(random() < 0.5 ? color(246, 212, 158, 15)
                        : color(10, 29, 37, 24));
    ellipse(p.x, p.y, random(0.7, 3.5), random(0.8, 4.5));
  }
}

function paintConnections() {
  noFill();

  // Loose, unequal filaments: a cradle, not a cage.
  for (let i = 0; i < 52; i++) {
    const tL = random(0.51, 0.79);
    const tR = constrain(tL + random(-0.08, 0.085), 0.43, 0.86);
    const a = shorePoint(shores[0], tL, -random(0.86, 0.99));
    const b = shorePoint(shores[1], tR, random(0.86, 0.99));
    const sag = random(70, 210);

    stroke(44, 53, 45, 13);
    strokeWeight(3.2);
    bezier(a.x, a.y + 3,
           680, a.y + sag + 3,
           927, b.y + sag + 3,
           b.x, b.y + 3);

    stroke(235, 190, 119, random(17, 58));
    strokeWeight(random(0.45, 1.25));
    bezier(a.x, a.y,
           680, a.y + sag,
           927, b.y + sag,
           b.x, b.y);
  }

  // A few strands reach the unfinished center.
  for (let side = 0; side < 2; side++) {
    const s = shores[side];
    for (let i = 0; i < 16; i++) {
      const a = shorePoint(s, random(0.56, 0.7), s.inward * 0.97);
      const ex = 808 + random(-10, 12);
      const ey = 1110 + random(-2, 20);
      stroke(241, 209, 148, random(15, 47));
      strokeWeight(random(0.5, 1.1));
      bezier(a.x, a.y,
             lerp(a.x, ex, 0.45), a.y + random(35, 105),
             ex + (side === 0 ? -45 : 45), ey + 90,
             ex, ey);
    }
  }
}

function paintGerm() {
  // A light with no owner.
  noStroke();
  for (let k = 65; k >= 1; k--) {
    fill(255, 221, 153, 1.5);
    ellipse(809, 1081, 34 + k * 3.0, 58 + k * 3.8);
  }

  push();
  translate(809, 1080);
  rotate(-0.18);

  fill(174, 125, 70, 90);
  ellipse(4, 8, 37, 70);

  fill(248, 225, 175);
  beginShape();
  vertex(-2, -39);
  bezierVertex(22, -30, 23, 3, 9, 28);
  bezierVertex(4, 40, -6, 40, -13, 19);
  bezierVertex(-24, -4, -16, -26, -2, -39);
  endShape(CLOSE);

  for (let i = 0; i < 460; i++) {
    const x = random(-18, 18);
    const y = random(-35, 34);
    if (sq(x / 18) + sq(y / 37) < 0.84) {
      fill(255, 248, 216, random(12, 53));
      ellipse(x - 3, y - 3, random(0.6, 3), random(1, 4));
    }
  }
  pop();
}

function paintMotes() {
  noStroke();
  for (let i = 0; i < 115; i++) {
    const x = randomGaussian(804, 139);
    const y = randomGaussian(1030, 245);
    if (x < 560 || x > 1050 || y < 560 || y > 1480) continue;
    const r = random(0.8, 3.1);
    fill(248, 220, 159, random(15, 77));
    ellipse(x, y, r, r * random(0.8, 1.8));
  }

  // Flecks of each shore's color appear in the other.
  for (let side = 0; side < 2; side++) {
    const s = shores[side];
    const c = shores[1 - side].middle;
    for (let i = 0; i < 125; i++) {
      const p = shorePoint(s, random(0.39, 0.91),
                           s.inward * random(0.35, 0.94));
      fill(red(c), green(c), blue(c), random(20, 65));
      ellipse(p.x, p.y, random(1, 4), random(2, 8));
    }
  }
}

function surfaceGrain() {
  noStroke();
  for (let i = 0; i < 65000; i++) {
    const x = random(width);
    const y = random(height);
    fill(random() < 0.5 ? color(255, 243, 214, random(3, 13))
                        : color(6, 15, 23, random(3, 12)));
    rect(x, y, random(0.5, 1.6), random(0.6, 2.1));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);

  const Lx = 800, Ly = 1180;      // flame center region
  const Cx = 800, Cy = 1290;      // cup center
  const innerR = 230;

  // background gradient
  const top = color(14, 16, 42), bot = color(4, 4, 14);
  for (let y = 0; y < height; y++) {
    stroke(lerpColor(top, bot, y / height));
    line(0, y, width, y);
  }

  // faint stars
  noStroke();
  for (let i = 0; i < 450; i++) {
    fill(200, 210, 255, random(10, 70));
    circle(random(width), random(height * 0.75), random(0.8, 2.4));
  }

  // wind flow lines bending around the shelter
  const cool = color(90, 110, 175);
  const warm = color(255, 178, 92);
  for (let i = 0; i < 1900; i++) {
    let x = random(-300, 1700);
    let y = random(-200, 2100);
    const w = random(0.6, 1.7);
    strokeWeight(w);
    for (let s = 0; s < 170; s++) {
      let a = 0.3 + (noise(x * 0.0014, y * 0.0014) - 0.5) * 1.7;
      let vx = cos(a), vy = sin(a);
      let dx = x - Cx, dy = y - (Cy - 60);
      let d = sqrt(dx * dx + dy * dy);
      if (d < 360) break;
      if (d < 580) {
        let f = pow((580 - d) / 580, 1.4) * 3.2;
        vx += (dx / d) * f;
        vy += (dy / d) * f;
      }
      let m = sqrt(vx * vx + vy * vy);
      vx /= m; vy /= m;
      let nx = x + vx * 4, ny = y + vy * 4;
      let t = constrain(map(d, 360, 780, 1, 0), 0, 1);
      let c = lerpColor(cool, warm, t * t);
      c.setAlpha(28 + 70 * t);
      stroke(c);
      line(x, y, nx, ny);
      x = nx; y = ny;
      if (x > width + 50 || y > height + 50) break;
    }
  }

  // glow of the flame
  const ctx = drawingContext;
  let g = ctx.createRadialGradient(Lx, Ly, 0, Lx, Ly, 760);
  g.addColorStop(0, 'rgba(255,215,140,0.55)');
  g.addColorStop(0.18, 'rgba(255,165,80,0.25)');
  g.addColorStop(0.5, 'rgba(180,80,60,0.08)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // the shelter: two cupped crescents
  noFill();
  const gold = color(250, 190, 100);
  const dark = color(34, 28, 58);
  const rim = color(80, 100, 165);
  function hand(a0, a1, side) {
    for (let j = 160; j >= 0; j--) {
      let k = j / 160;
      let c = lerpColor(gold, dark, pow(k, 0.6));
      if (k > 0.86) c = lerpColor(c, rim, map(k, 0.86, 1, 0, 0.7));
      c.setAlpha(150);
      stroke(c);
      strokeWeight(random(1.5, 3.5));
      beginShape();
      for (let u = 0; u <= 1.0001; u += 0.02) {
        let a = radians(lerp(a0, a1, u));
        let thick = 115 * pow(sin(PI * u), 0.6);
        let r = innerR + k * thick + (noise(u * 4, k * 6, side * 10) - 0.5) * 16;
        curveVertex(Cx + r * cos(a), Cy + r * sin(a));
      }
      endShape();
    }
    // lit inner edge
    stroke(255, 230, 170, 160);
    strokeWeight(2.5);
    beginShape();
    for (let u = 0; u <= 1.0001; u += 0.02) {
      let a = radians(lerp(a0, a1, u));
      curveVertex(Cx + (innerR - 2) * cos(a), Cy + (innerR - 2) * sin(a));
    }
    endShape();
  }
  hand(98, 212, 0);
  hand(-32, 82, 1);

  // the flame
  noStroke();
  function flameShape(cx, by, w, h, lean) {
    beginShape();
    vertex(cx - w, by);
    bezierVertex(cx - w, by - h * 0.45, cx + lean * 0.3 - w * 0.3, by - h * 0.7, cx + lean, by - h);
    bezierVertex(cx + lean * 0.3 + w * 0.3, by - h * 0.7, cx + w, by - h * 0.45, cx + w, by);
    bezierVertex(cx + w, by + w * 0.9, cx - w, by + w * 0.9, cx - w, by);
    endShape(CLOSE);
  }
  const fRed = color(215, 70, 35, 40);
  const fWhite = color(255, 248, 220, 70);
  for (let j = 0; j <= 34; j++) {
    let s = 1 - j / 34;
    let c = lerpColor(fRed, fWhite, j / 34);
    fill(c);
    flameShape(Lx, 1270, 48 * s + 5, 220 * s + 18, 34 * s);
  }
  fill(255, 255, 240, 220);
  flameShape(Lx, 1268, 9, 30, 3);

  // sparks carried by the wind
  for (let i = 0; i < 70; i++) {
    let up = random(80, 700);
    let x = Lx + up * random(0.3, 0.9) + random(-30, 30);
    let y = 1060 - up * random(0.6, 1.0);
    let r = random(1.5, 4.5) * map(up, 80, 700, 1, 0.4);
    fill(255, 160, 70, 40);
    circle(x, y, r * 4);
    fill(255, 220, 150, 200 * map(up, 80, 700, 1, 0.3));
    circle(x, y, r);
  }

  // grain
  for (let i = 0; i < 70000; i++) {
    stroke(random() < 0.5 ? 0 : 255, 10);
    strokeWeight(1);
    point(random(width), random(height));
  }
}

let A, B, C, R;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function rayWall(o, ux, uy) {
  // distance along ray from o in direction u to the shared wall (circle C,R)
  let ox = o.x - C.x, oy = o.y - C.y;
  let b = ux * ox + uy * oy;
  let c = ox * ox + oy * oy - R * R;
  let disc = b * b - c;
  if (disc < 0) return Infinity;
  let s = sqrt(disc);
  let t1 = -b - s, t2 = -b + s;
  if (t1 > 0) return t1;
  if (t2 > 0) return t2;
  return Infinity;
}

function drawSystem(o, cInner, cOuter, step, maxR, off) {
  const N = 720;
  const gold = color(255, 214, 140);
  let r = step * 0.6;
  let ringIndex = 0;
  while (r < maxR) {
    let wgt = random(0.7, 2.6);
    let alpha = random(110, 210);
    if (ringIndex % 7 === 0) { wgt *= 1.8; alpha = 230; }
    let base = lerpColor(cInner, cOuter, constrain(r / 1600, 0, 1));
    let prev = null;
    for (let i = 0; i <= N; i++) {
      let a = TWO_PI * i / N;
      let ux = cos(a), uy = sin(a);
      let tb = rayWall(o, ux, uy);
      let amp = min(r * 0.16, 110);
      let w = r + (noise(ux * 1.3 + off, uy * 1.3 + off, r * 0.004) - 0.5) * amp;
      w = max(w, 1);
      let rr = w, f = 0;
      if (isFinite(tb)) {
        let lim = tb * 0.997;
        rr = w / pow(1 + pow(w / lim, 5), 1 / 5);
        f = constrain(rr / lim, 0, 1);
      }
      let x = o.x + ux * rr, y = o.y + uy * rr;
      if (prev) {
        let g = pow((f + prev.f) * 0.5, 7);
        let col = lerpColor(base, gold, g);
        col.setAlpha(alpha * (0.75 + 0.25 * g));
        stroke(col);
        strokeWeight(wgt * (1 - 0.45 * g));
        line(prev.x, prev.y, x, y);
      }
      prev = { x, y, f };
    }
    r += step * random(0.6, 1.4);
    ringIndex++;
  }
}

function glow(x, y, rad, col) {
  noStroke();
  for (let i = rad; i > 0; i -= 2) {
    let t = i / rad;
    fill(red(col), green(col), blue(col), 10 * (1 - t));
    circle(x, y, i * 2);
  }
}

function draw() {
  // background
  for (let y = 0; y < height; y++) {
    let t = y / height;
    stroke(lerpColor(color(12, 7, 22), color(32, 11, 28), t));
    line(0, y, width, y);
  }

  A = createVector(600, 1430);
  B = createVector(1010, 720);
  R = 1350;
  let d = p5.Vector.sub(B, A).normalize();
  let P = p5.Vector.lerp(A, B, 0.6);
  C = p5.Vector.add(P, p5.Vector.mult(d, R));

  // soft fields of light around each center
  glow(A.x, A.y, 700, color(200, 50, 90));
  glow(B.x, B.y, 520, color(240, 130, 60));

  blendMode(ADD);
  drawSystem(A, color(235, 90, 120), color(110, 25, 70), 13, 2600, 3.7);
  drawSystem(B, color(255, 170, 90), color(150, 55, 45), 10, 2600, 11.2);

  // the shared wall
  let ctx = drawingContext;
  noFill();
  for (let pass = 0; pass < 3; pass++) {
    ctx.shadowBlur = [70, 30, 8][pass];
    ctx.shadowColor = 'rgba(255,205,120,0.9)';
    stroke(255, 220, 150, [90, 160, 255][pass]);
    strokeWeight([10, 4, 1.6][pass]);
    beginShape();
    for (let i = 0; i <= 2000; i++) {
      let a = TWO_PI * i / 2000;
      let x = C.x + cos(a) * R, y = C.y + sin(a) * R;
      if (x > -100 && x < width + 100 && y > -100 && y < height + 100) {
        vertex(x, y);
      } else {
        endShape();
        beginShape();
      }
    }
    endShape();
  }
  ctx.shadowBlur = 0;

  // seeds of each life
  glow(A.x, A.y, 60, color(255, 200, 210));
  glow(B.x, B.y, 50, color(255, 225, 180));
  blendMode(BLEND);

  // grain
  noStroke();
  for (let i = 0; i < 70000; i++) {
    let v = random() < 0.5 ? 0 : 255;
    fill(v, v, v, random(6, 16));
    rect(random(width), random(height), 1.5, 1.5);
  }

  // vignette
  noFill();
  for (let i = 0; i < 260; i++) {
    stroke(8, 4, 14, map(i, 0, 260, 3, 0));
    strokeWeight(4);
    rect(i * 2, i * 2, width - i * 4, height - i * 4);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Background: deep indigo fading into warm umber
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(14, 12, 30), color(36, 20, 18), t);
    stroke(c);
    line(0, y, width, y);
  }
  // Vignette
  noStroke();
  for (let r = 0; r < 60; r++) {
    fill(0, 0, 0, 4);
    let inset = r * 14;
    rectMode(CORNER);
    beginShape();
    vertex(0, 0); vertex(width, 0); vertex(width, height); vertex(0, height);
    beginContour();
    vertex(inset, inset); vertex(inset, height - inset);
    vertex(width - inset, height - inset); vertex(width - inset, inset);
    endContour();
    endShape(CLOSE);
  }

  const cx = width / 2;
  const turns = 3.5;
  const yStart = -60, yEnd = height + 60;
  const gold = color(240, 172, 78);
  const blue = color(72, 118, 225);

  function pathPhase(t) { return t * TWO_PI * turns; }
  function amp(t) { return 340 * (0.75 + 0.25 * sin(t * PI)); }

  // Glows at crossings
  blendMode(ADD);
  noStroke();
  for (let k = 1; k <= turns * 2; k++) {
    let t = (k * PI) / (TWO_PI * turns);
    let y = lerp(yStart, yEnd, t);
    if (y < 0 || y > height) continue;
    for (let r = 420; r > 0; r -= 6) {
      let a = map(r, 420, 0, 0, 7);
      fill(150, 110, 120, a * 0.5);
      ellipse(cx + (noise(k) - 0.5) * 60, y, r * 1.5, r);
    }
  }

  // The two strands
  const nLines = 70;
  const steps = 520;
  for (let s = 0; s < 2; s++) {
    let sign = s === 0 ? 1 : -1;
    let own = s === 0 ? gold : blue;
    let other = s === 0 ? blue : gold;
    for (let i = 0; i < nLines; i++) {
      let baseOff = (i / (nLines - 1) - 0.5) * 170;
      let take = 0.55 + random(0.9);
      let seed = s * 1000 + i * 7.3;
      let w = random(0.6, 1.8);
      let alpha = random(10, 26);
      let px, py;
      for (let j = 0; j <= steps; j++) {
        let t = j / steps;
        let y = lerp(yStart, yEnd, t);
        let p = pathPhase(t);
        let crossings = p / PI;
        let m = 0.5 * (1 - pow(0.62, crossings)) * take;
        m = constrain(m, 0, 0.62);
        // spread opens slightly at crossings, like a breath
        let near = pow(abs(cos(p)), 6);
        let off = baseOff * (1 + 0.5 * near);
        let wob = (noise(seed, t * 4) - 0.5) * 90 + (noise(seed + 50, t * 18) - 0.5) * 14;
        let x = cx + sign * amp(t) * sin(p) + off + wob;
        if (j > 0) {
          let c = lerpColor(own, other, m);
          stroke(red(c), green(c), blue(c), alpha * (1 + 0.8 * near));
          strokeWeight(w);
          line(px, py, x, y);
        }
        px = x; py = y;
      }
    }
  }

  // Motes: small exchanged lights drifting near the meetings
  noStroke();
  for (let k = 1; k <= turns * 2; k++) {
    let t = (k * PI) / (TWO_PI * turns);
    let y0 = lerp(yStart, yEnd, t);
    for (let n = 0; n < 60; n++) {
      let ang = random(TWO_PI);
      let rr = abs(randomGaussian(0, 140));
      let x = cx + cos(ang) * rr * 1.4;
      let y = y0 + sin(ang) * rr * 0.8;
      let c = random() < 0.5 ? gold : blue;
      let sz = random(1.5, 5);
      for (let g = 4; g > 0; g--) {
        fill(red(c), green(c), blue(c), 14);
        ellipse(x, y, sz * g * 1.6);
      }
      fill(255, 240, 220, 120);
      ellipse(x, y, sz * 0.6);
    }
  }
  blendMode(BLEND);

  // Grain
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = (random() - 0.5) * 16;
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const W = 1600, H = 2000, G = 1830;
  const topL = 560, topR = 470;
  let cx = [], gw = [], oL = [], iL = [], iR = [], oR = [];

  for (let y = 0; y < H; y++) {
    let c = 800 + (noise(y * 0.0025) - 0.5) * 320 + (noise(y * 0.011 + 9) - 0.5) * 40;
    let w = 12 + pow(noise(y * 0.005 + 40), 2) * 230;
    cx[y] = c; gw[y] = w;

    // left form
    let a = 150 + (noise(y * 0.004 + 100) - 0.5) * 90;
    let b = c - w / 2;
    if (y < topL || y >= G) { a = 1; b = 0; }
    else {
      let t = y - topL, R = 380;
      if (t < R) a += R - sqrt(R * R - (R - t) * (R - t));
      let r = 90;
      if (t < r) b -= r - sqrt(r * r - (r - t) * (r - t));
    }
    oL[y] = a; iL[y] = b;

    // right form
    let d = 1450 + (noise(y * 0.004 + 200) - 0.5) * 90;
    let e = c + w / 2;
    if (y < topR || y >= G) { d = 0; e = 1; }
    else {
      let t = y - topR, R = 400;
      if (t < R) d -= R - sqrt(R * R - (R - t) * (R - t));
      let r = 90;
      if (t < r) e += r - sqrt(r * r - (r - t) * (r - t));
    }
    oR[y] = d; iR[y] = e;
  }

  loadPixels();
  for (let y = 0; y < H; y++) {
    let ty = constrain(y / G, 0, 1);
    let sr = lerp(6, 46, pow(ty, 1.6));
    let sg = lerp(8, 30, pow(ty, 1.6));
    let sb = lerp(28, 62, pow(ty, 1.4));
    let v = y >= topL ? 1 : exp(-(topL - y) / 650);
    let spread = 30 + max(0, topL - y) * 0.3;

    for (let x = 0; x < W; x++) {
      let r, g, bl;
      let dx = abs(x - cx[y]) - gw[y] / 2;
      let inLeft = y < G && iL[y] > oL[y] && x >= oL[y] && x <= iL[y];
      let inRight = y < G && oR[y] > iR[y] && x >= iR[y] && x <= oR[y];

      if (inLeft || inRight) {
        let dd = inLeft ? iL[y] - x : x - iR[y];
        let od = inLeft ? x - oL[y] : oR[y] - x;
        let n = noise(x * 0.006 + (inLeft ? 0 : 50), y * 0.006);
        let f = noise(x * 0.05, y * 0.05);
        let tex = 0.6 + 0.5 * n + 0.25 * (f - 0.5);
        let br, bg, bb;
        if (inLeft) { br = 34; bg = 22; bb = 34; } else { br = 24; bg = 22; bb = 38; }
        r = br * tex; g = bg * tex; bl = bb * tex;
        let light = exp(-dd / 120) * 0.85 + exp(-dd / 7) * 0.7;
        light *= (0.65 + 0.5 * n);
        r += 255 * light; g += 170 * light; bl += 85 * light;
        let rim = exp(-od / 18) * 0.18;
        r += 70 * rim; g += 80 * rim; bl += 140 * rim;
        let foot = exp(-(G - y) / 60) * 0.25;
        r *= 1 - foot; g *= 1 - foot; bl *= 1 - foot;
      } else if (y < G) {
        let pd = max(dx, 0);
        let gl = v * (exp(-pd / spread) * 0.9 + exp(-pd / 420) * 0.22);
        r = sr + 255 * gl; g = sg + 175 * gl; bl = sb + 90 * gl;
        if (dx < 0) {
          let k = min(1, -dx / (gw[y] / 2 + 0.001));
          k = pow(k, 0.7) * v;
          r = lerp(r, 255, k); g = lerp(g, 246, k); bl = lerp(bl, 215, k);
        }
      } else {
        let t = y - G;
        let gc = cx[G - 1];
        let n = noise(x * 0.01, y * 0.03 + 300);
        r = 16 + 10 * n; g = 13 + 8 * n; bl = 22 + 12 * n;
        let refl = exp(-abs(x - gc) / (25 + t * 2.4)) * exp(-t / 160);
        let spill = exp(-abs(x - gc) / 420) * 0.3 * exp(-t / 90);
        let streak = 0.75 + 0.5 * noise(x * 0.08, y * 0.4);
        let L = (refl * streak + spill);
        r += 255 * L; g += 185 * L; bl += 100 * L;
      }

      let idx = 4 * (y * W + x);
      pixels[idx] = constrain(r, 0, 255);
      pixels[idx + 1] = constrain(g, 0, 255);
      pixels[idx + 2] = constrain(bl, 0, 255);
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();

  function inForm(x, y) {
    x = floor(x); y = floor(y);
    if (y < 0 || y >= H) return true;
    if (y >= G) return true;
    return (iL[y] > oL[y] && x >= oL[y] && x <= iL[y]) || (oR[y] > iR[y] && x >= iR[y] && x <= oR[y]);
  }

  blendMode(ADD);
  noStroke();

  // stars
  for (let i = 0; i < 700; i++) {
    let x = random(W), y = pow(random(), 1.5) * 1500;
    if (inForm(x, y)) continue;
    let s = random() < 0.08 ? random(2, 3.5) : random(0.8, 1.8);
    fill(200, 210, 255, random(40, 140));
    circle(x, y, s);
  }

  // rising motes of light from the gap
  for (let i = 0; i < 1400; i++) {
    let y = topL + 200 - pow(random(), 0.8) * (topL + 200);
    let yi = constrain(floor(y), 0, H - 1);
    let sp = 15 + max(0, topL - y) * 0.45;
    let x = cx[yi] + randomGaussian() * sp;
    if (inForm(x, y)) continue;
    let a = map(y, 0, topL + 200, 30, 160);
    let s = random(1, 3.2);
    fill(255, 200, 120, a * 0.35);
    circle(x, y, s * 3);
    fill(255, 235, 190, a);
    circle(x, y, s);
  }

  // motes inside the gap itself
  for (let i = 0; i < 600; i++) {
    let y = random(topL, G);
    let yi = floor(y);
    let x = cx[yi] + randomGaussian() * gw[yi] * 0.25;
    if (inForm(x, y)) continue;
    fill(255, 250, 230, random(40, 120));
    circle(x, y, random(1, 2.5));
  }
  blendMode(BLEND);
}

let G = 880;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  drawSky();
  drawSoil();

  // fine roots first (background)
  for (let k = 0; k < 9; k++) {
    let tx = random() < 0.6 ? random(820, 1200) : random(150, 600);
    root(480 + random(-30, 30), G + 20, PI / 2 + random(-0.9, 0.9), random(5, 11),
      color(200, 120, 65, 200), tx, random(1150, 1900), 0);
  }
  for (let k = 0; k < 9; k++) {
    let tx = random() < 0.6 ? random(400, 780) : random(1000, 1450);
    root(1120 + random(-30, 30), G + 20, PI / 2 + random(-0.9, 0.9), random(5, 11),
      color(150, 185, 210, 200), tx, random(1150, 1900), 0);
  }

  // core glow beneath braids
  glow(800, 1330, 520, color(255, 170, 90), 2.2);

  // braided roots
  braid(470, 1130, G + 30, 300, 22, 4, 16);
  braid(480, 1120, G + 35, 430, 30, 5, 22);
  braid(490, 1110, G + 40, 570, 38, 6, 14);

  // light at the knot
  glow(800, 1330, 260, color(255, 210, 150), 3);

  // trees above
  tree(480, -PI / 2 - 0.07, color(60, 32, 24), [color(214, 120, 60), color(180, 70, 50), color(240, 170, 90)]);
  tree(1120, -PI / 2 + 0.07, color(30, 38, 46), [color(80, 140, 140), color(60, 100, 120), color(140, 185, 170)]);

  // grass line
  stroke(25, 20, 18);
  for (let x = 0; x < width; x += 3) {
    strokeWeight(random(1, 2.5));
    let h = random(4, 18) * (0.5 + noise(x * 0.01));
    line(x, G + 2, x + random(-4, 4), G - h);
  }

  // grain
  noStroke();
  for (let i = 0; i < 30000; i++) {
    fill(random() < 0.5 ? 255 : 0, random(4, 12));
    rect(random(width), random(height), 1.5, 1.5);
  }
}

function drawSky() {
  for (let y = 0; y <= G; y++) {
    let t = pow(y / G, 1.6);
    let c = lerpColor(color(26, 28, 60), color(238, 168, 118), t);
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();
  for (let i = 0; i < 120; i++) {
    fill(255, 240, 220, random(40, 140));
    let s = random(1, 3);
    circle(random(width), random(0, G * 0.45), s);
  }
  glow(800, G - 20, 300, color(255, 190, 120), 2.5);
}

function drawSoil() {
  for (let y = G; y < height; y++) {
    let t = (y - G) / (height - G);
    stroke(lerpColor(color(72, 46, 32), color(14, 10, 10), pow(t, 0.8)));
    line(0, y, width, y);
  }
  // strata
  for (let i = 0; i < 70; i++) {
    let y0 = random(G + 30, height);
    let x = random(-200, width);
    let len = random(200, 800);
    stroke(random() < 0.5 ? color(110, 75, 50, 30) : color(0, 0, 0, 40));
    strokeWeight(random(2, 8));
    noFill();
    beginShape();
    for (let s = 0; s < len; s += 20) {
      vertex(x + s, y0 + (noise(x * 0.01 + s * 0.005, y0) - 0.5) * 40);
    }
    endShape();
  }
  // stones
  noStroke();
  for (let i = 0; i < 45; i++) {
    let x = random(width), y = random(G + 60, height), w = random(14, 60);
    fill(20, 16, 15, 200);
    ellipse(x, y, w, w * random(0.5, 0.8));
    fill(120, 100, 85, 50);
    ellipse(x - w * 0.12, y - w * 0.1, w * 0.5, w * 0.25);
  }
}

function glow(x, y, r, c, a) {
  blendMode(ADD);
  noStroke();
  for (let rr = r; rr > 0; rr -= 6) {
    fill(red(c), green(c), blue(c), a * (1 - rr / r) * 1.2);
    circle(x, y, rr * 2);
  }
  blendMode(BLEND);
}

function adiff(a, b) {
  return atan2(sin(a - b), cos(a - b));
}

function root(x, y, a, th, col, tx, ty, gen) {
  let steps = floor(random(60, 140));
  for (let i = 0; i < steps; i++) {
    let want = atan2(ty - y, tx - x);
    a += adiff(want, a) * 0.035 + (noise(x * 0.006, y * 0.006, gen * 3.1) - 0.5) * 0.35;
    if (y < G + 25) a = lerp(a, PI / 2, 0.3);
    let nx = x + cos(a) * 7, ny = y + sin(a) * 7;
    stroke(col);
    strokeWeight(th);
    line(x, y, nx, ny);
    x = nx; y = ny;
    th *= 0.988;
    if (th < 0.6 || y > height - 10) return;
    if (random() < 0.045 && gen < 4 && th > 1.2) {
      root(x, y, a + random(-0.9, 0.9), th * 0.6, col,
        tx + random(-250, 250), ty + random(-100, 250), gen + 1);
    }
  }
}

function braid(xa, xb, yb, sag, amp, freq, wmax) {
  let N = 400;
  let A = [], B = [];
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let x = lerp(xa, xb, t);
    let base = yb + sin(PI * t) * sag + (noise(t * 3, yb) - 0.5) * 40;
    let off = sin(t * TWO_PI * freq) * amp * sin(PI * t + 0.2);
    A.push([x, base + off, lerp(wmax, 2, t)]);
    B.push([x, base - off, lerp(2, wmax, t)]);
  }
  let warm = color(222, 140, 70), cool = color(160, 195, 220);
  let regions = freq * 2;
  for (let k = 0; k < regions; k++) {
    let i0 = floor(k * N / regions), i1 = floor((k + 1) * N / regions);
    let overA = k % 2 === 0;
    let under = overA ? B : A, over = overA ? A : B;
    let cu = overA ? cool : warm, co = overA ? warm : cool;
    strandPart(under, i0, i1, cu);
    strandPart(over, i0, i1, co);
  }
}

function strandPart(P, i0, i1, c) {
  for (let pass = 0; pass < 3; pass++) {
    for (let i = i0; i < i1; i++) {
      let p = P[i], q = P[i + 1];
      if (pass === 0) { stroke(10, 6, 6, 220); strokeWeight(p[2] + 5); }
      else if (pass === 1) { stroke(c); strokeWeight(p[2]); }
      else { stroke(255, 240, 210, 70); strokeWeight(max(1, p[2] * 0.3)); }
      line(p[0], p[1] - (pass === 2 ? p[2] * 0.2 : 0), q[0], q[1] - (pass === 2 ? q[2] * 0.2 : 0));
    }
  }
}

function tree(x, a0, barkCol, leafCols) {
  let H = 380;
  let tx = x + cos(a0) * H, ty = G + 10 + sin(a0) * H;
  // trunk
  noStroke();
  fill(barkCol);
  beginShape();
  let pts = 30;
  for (let i = 0; i <= pts; i++) {
    let t = i / pts;
    let w = lerp(60, 15, t) + 45 * pow(1 - t, 6);
    let cx = lerp(x, tx, t) + (noise(t * 2, x) - 0.5) * 20;
    vertex(cx - w, lerp(G + 15, ty, t));
  }
  for (let i = pts; i >= 0; i--) {
    let t = i / pts;
    let w = lerp(60, 15, t) + 45 * pow(1 - t, 6);
    let cx = lerp(x, tx, t) + (noise(t * 2, x) - 0.5) * 20;
    vertex(cx + w, lerp(G + 15, ty, t));
  }
  endShape(CLOSE);

  let tips = [];
  for (let k = -1; k <= 1; k++) {
    branch(tx, ty, a0 + k * 0.45, 120, 20, 6, barkCol, tips);
  }
  noStroke();
  for (let tp of tips) {
    for (let j = 0; j < 14; j++) {
      let c = random(leafCols);
      fill(red(c), green(c), blue(c), random(50, 130));
      let r = random(0, 55);
      let ang = random(TWO_PI);
      let s = random(10, 34);
      ellipse(tp[0] + cos(ang) * r, tp[1] + sin(ang) * r * 0.8, s, s * random(0.6, 1));
    }
  }
}

function branch(x, y, a, len, w, d, col, tips) {
  let x2 = x + cos(a) * len, y2 = y + sin(a) * len;
  stroke(col);
  strokeWeight(w);
  line(x, y, x2, y2);
  if (d === 0) { tips.push([x2, y2]); return; }
  let n = random() < 0.3 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let na = a + (i - (n - 1) / 2) * 0.55 + random(-0.3, 0.3);
    na = lerp(na, -PI / 2, 0.08);
    branch(x2, y2, na, len * random(0.66, 0.8), w * 0.66, d - 1, col, tips);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(7, 8, 16);

  // Define the two distinct entities and their shared center
  let pA = createVector(480, 780);
  let pB = createVector(1120, 1220);
  let mid = p5.Vector.add(pA, pB).mult(0.5);

  // 1. Deep Atmospheric Undertone (Painterly Wash)
  noStroke();
  for (let i = 0; i < 3500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let dMid = dist(x, y, mid.x, mid.y);

    let r = map(n, 0, 1, 8, 32);
    let g = map(n, 0, 1, 10, 22);
    let b = map(n, 0, 1, 20, 48);

    if (dMid < 900) {
      let f = pow(1 - dMid / 900, 2);
      r += f * 45;
      g += f * 18;
      b += f * 25;
    }

    fill(r, g, b, 12);
    push();
    translate(x, y);
    rotate(n * TWO_PI * 2);
    ellipse(0, 0, random(80, 350), random(40, 180));
    pop();
  }

  // 2. Ambient Core Glows
  blendMode(ADD);
  drawGlow(pA.x, pA.y, 850, color(230, 65, 45), 0.14);
  drawGlow(pA.x, pA.y, 350, color(255, 160, 80), 0.25);

  drawGlow(pB.x, pB.y, 850, color(30, 135, 190), 0.14);
  drawGlow(pB.x, pB.y, 350, color(90, 210, 255), 0.25);

  drawGlow(mid.x, mid.y, 1100, color(190, 90, 150), 0.12);
  drawGlow(mid.x, mid.y, 550, color(255, 200, 140), 0.22);

  // 3. The Woven Field of Connection (Trajectories of Empathy)
  let numBridge = 9000;
  for (let i = 0; i < numBridge; i++) {
    let startA = (i % 2 === 0);
    let origin = startA ? pA : pB;
    let target = startA ? pB : pA;

    let angle = random(TWO_PI);
    let rad = randomGaussian(0, 50);
    let pos = createVector(origin.x + cos(angle) * rad, origin.y + sin(angle) * rad);

    let swirlDir = random() < 0.5 ? 1 : -1;
    let swirlStrength = random(0.3, 1.8) * swirlDir;
    let cVar = random(-25, 25);

    noFill();
    strokeWeight(random(0.4, 2.0));

    let maxSteps = 550;
    for (let step = 0; step < maxSteps; step++) {
      let dTarget = p5.Vector.dist(pos, target);
      if (dTarget < 25) break;

      let dOrigin = p5.Vector.dist(pos, origin);
      let t = constrain(dOrigin / (dOrigin + dTarget), 0, 1);

      // Direction toward the other
      let dir = p5.Vector.sub(target, pos).normalize();
      let perp = createVector(-dir.y, dir.x);

      // Organic turbulence and orbital pull
      let n = noise(pos.x * 0.0025, pos.y * 0.0025, i * 0.0005);
      let nAngle = map(n, 0, 1, -PI, PI);
      let nVec = createVector(cos(nAngle), sin(nAngle));

      let arcShape = sin(t * PI); // Widest in the space between
      let pullStrength = map(t, 0, 1, 0.7, 2.8);

      let vel = createVector(0, 0);
      vel.add(p5.Vector.mult(dir, pullStrength));
      vel.add(p5.Vector.mult(perp, arcShape * swirlStrength));
      vel.add(p5.Vector.mult(nVec, arcShape * 1.3));
      vel.normalize().mult(3.5);

      let nextPos = p5.Vector.add(pos, vel);

      // Color alchemy: transitioning from self to shared resonance to the other
      let r, g, b;
      let progress = startA ? t : (1 - t);

      if (progress < 0.5) {
        let lt = progress * 2;
        r = lerp(245 + cVar, 255, lt);
        g = lerp(75 + cVar * 0.5, 195, lt);
        b = lerp(60, 165, lt);
      } else {
        let lt = (progress - 0.5) * 2;
        r = lerp(255, 45, lt);
        g = lerp(195, 175 + cVar * 0.5, lt);
        b = lerp(165, 235 + cVar, lt);
      }

      // Brighten at the central nexus
      let dMid = p5.Vector.dist(pos, mid);
      let midBoost = constrain(1 - dMid / 420, 0, 1);
      r = lerp(r, 255, midBoost * 0.65);
      g = lerp(g, 240, midBoost * 0.65);
      b = lerp(b, 215, midBoost * 0.65);

      let alpha = sin(t * PI) * 14 + midBoost * 10;
      stroke(r, g, b, alpha);
      line(pos.x, pos.y, nextPos.x, nextPos.y);

      pos = nextPos;
    }
  }

  // 4. Individual Resonance (History & Solitude extending outward)
  let numAura = 4500;
  for (let i = 0; i < numAura; i++) {
    let isA = (i % 2 === 0);
    let origin = isA ? pA : pB;
    let angle = random(TWO_PI);
    let pos = createVector(origin.x + cos(angle) * random(5, 90), origin.y + sin(angle) * random(5, 90));

    strokeWeight(random(0.5, 1.5));
    let c = isA ? color(255, random(90, 160), random(60, 110), 9) : color(random(50, 110), random(170, 230), 255, 9);
    stroke(c);

    for (let step = 0; step < 220; step++) {
      let n = noise(pos.x * 0.002, pos.y * 0.002, step * 0.005);
      let a = map(n, 0, 1, -TWO_PI, TWO_PI);

      // Subtle gravity toward the partner even in private thoughts
      let toMid = p5.Vector.sub(mid, pos).normalize().mult(0.35);
      let vel = createVector(cos(a), sin(a)).add(toMid).normalize().mult(3);

      let nextPos = p5.Vector.add(pos, vel);
      line(pos.x, pos.y, nextPos.x, nextPos.y);
      pos = nextPos;
    }
  }

  // 5. Harmonic Rings in the Shared Space (The Third Thing)
  for (let i = 0; i < 1800; i++) {
    let rad = randomGaussian(220, 130);
    let angle = random(TWO_PI);
    let pos = createVector(mid.x + cos(angle) * rad, mid.y + sin(angle) * rad * 1.25);

    strokeWeight(random(0.4, 1.4));
    for (let step = 0; step < 90; step++) {
      let rel = p5.Vector.sub(pos, mid);
      let tang = createVector(-rel.y, rel.x).normalize();
      let n = noise(pos.x * 0.004, pos.y * 0.004);
      tang.rotate(map(n, 0, 1, -0.5, 0.5));

      let nextPos = p5.Vector.add(pos, tang.mult(3));
      let d = p5.Vector.dist(pos, mid);
      let a = constrain(1 - d / 550, 0, 1) * 16;

      stroke(255, 225, 185, a);
      line(pos.x, pos.y, nextPos.x, nextPos.y);
      pos = nextPos;
    }
  }

  // 6. Distinct Cores (Remaining whole while opening up)
  drawCore(pA.x, pA.y, color(255, 230, 200), color(255, 90, 50));
  drawCore(pB.x, pB.y, color(210, 245, 255), color(30, 150, 255));

  // 7. Sparks of Grace & Canvas Texture
  noStroke();
  for (let i = 0; i < 3500; i++) {
    let t = random(1);
    let spine = p5.Vector.lerp(pA, pB, t);
    let spread = sin(t * PI) * 380 + 70;
    let x = spine.x + randomGaussian(0, spread);
    let y = spine.y + randomGaussian(0, spread);

    if (random() < 0.25) {
      fill(255, 245, 225, random(20, 90));
      circle(x, y, random(1, 3.5));
    } else {
      let c = lerpColor(color(255, 110, 80, 35), color(80, 200, 255, 35), t);
      fill(c);
      circle(x, y, random(0.5, 2));
    }
  }

  // Fine tactile grain
  blendMode(OVERLAY);
  strokeWeight(1);
  for (let i = 0; i < 90000; i++) {
    let x = random(width);
    let y = random(height);
    stroke(random() < 0.5 ? 255 : 0, 10);
    point(x, y);
  }

  blendMode(BLEND);
}

function drawGlow(x, y, maxRad, col, maxAlpha) {
  noStroke();
  let steps = 90;
  for (let i = steps; i > 0; i--) {
    let t = i / steps;
    let r = maxRad * t;
    let a = pow(1 - t, 2.2) * maxAlpha * 255;
    fill(red(col), green(col), blue(col), a);
    circle(x, y, r * 2);
  }
}

function drawCore(x, y, innerCol, outerCol) {
  for (let i = 0; i < 450; i++) {
    let r = abs(randomGaussian(0, 38));
    let a = random(TWO_PI);
    let px = x + cos(a) * r;
    let py = y + sin(a) * r;
    let c = lerpColor(innerCol, outerCol, constrain(r / 75, 0, 1));
    stroke(red(c), green(c), blue(c), random(25, 75));
    strokeWeight(random(0.8, 2.8));
    let len = random(4, 18);
    let dir = a + PI / 2 + random(-0.4, 0.4);
    line(px, py, px + cos(dir) * len, py + sin(dir) * len);
  }
  drawGlow(x, y, 140, innerCol, 0.5);
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Deep Atmospheric Background
  drawBackground();

  // 2. Distant Cosmic/Cellular Dust
  drawStardust();

  // 3. The Two Distinct Selves (Cores)
  // Core A: Deep, cool, oceanic/indigo (lower left)
  // Core B: Warm, rising, terracotta/amber (upper right)
  let coreA = createVector(460, 1280);
  let coreB = createVector(1140, 720);

  drawAura(coreA.x, coreA.y, 700, color(20, 60, 140), color(40, 160, 200));
  drawAura(coreB.x, coreB.y, 700, color(160, 30, 50), color(240, 130, 40));

  // 4. The Great Braid: Thousands of trajectories bending toward each other
  drawEntangledFlows(coreA, coreB);

  // 5. The Shared Hearth: The luminous third space created in the center
  let centerHearth = p5.Vector.lerp(coreA, coreB, 0.5);
  drawResonanceField(centerHearth, coreA, coreB);

  // 6. Kintsugi of the Heart: Golden filaments of vulnerability & connection
  drawGoldenTethers(coreA, coreB, centerHearth);

  // 7. Inner Sanctuary Details (Rings of identity that remain intact)
  drawCoreIdentity(coreA, false);
  drawCoreIdentity(coreB, true);

  // 8. Fine Canvas & Paint Texture Overlay
  applyPainterlyTexture();
}

function drawBackground() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    let ny = y / height;
    for (let x = 0; x < width; x++) {
      let nx = x / width;

      // Diagonal gradient from cool abyss to warm twilight
      let diag = (nx + (1.0 - ny)) * 0.5;
      let n = noise(nx * 2.5, ny * 2.5) * 0.15;
      let val = constrain(diag + n, 0, 1);

      // Deep indigo-slate to deep plum-umber
      let r = lerp(10, 32, val);
      let g = lerp(14, 12, val);
      let b = lerp(28, 24, val);

      // Subtle vignette
      let d = dist(nx, ny, 0.5, 0.5);
      let vig = constrain(map(d, 0.3, 0.75, 1.0, 0.4), 0.4, 1.0);

      let idx = (x + y * width) * 4;
      pixels[idx] = r * vig;
      pixels[idx + 1] = g * vig;
      pixels[idx + 2] = b * vig;
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();
}

function drawStardust() {
  noStroke();
  for (let i = 0; i < 6000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.45) {
      let sz = pow(random(1), 3) * 3.5;
      let alpha = random(10, 60) * map(n, 0.45, 1, 0.2, 1.5);
      if (random() < 0.5) {
        fill(255, 220, 190, alpha);
      } else {
        fill(170, 210, 255, alpha);
      }
      circle(x, y, sz);
    }
  }
}

function drawAura(cx, cy, maxR, colDeep, colBright) {
  noStroke();
  let steps = 180;
  for (let i = steps; i > 0; i--) {
    let t = i / steps;
    let r = maxR * pow(t, 0.85);
    let c = lerpColor(colBright, colDeep, pow(t, 0.6));
    c.setAlpha(map(t, 0, 1, 8, 1.5));
    fill(c);

    beginShape();
    let vCount = 80;
    for (let j = 0; j < vCount; j++) {
      let ang = (j / vCount) * TWO_PI;
      let nv = noise(cx * 0.01 + cos(ang) * 1.8, cy * 0.01 + sin(ang) * 1.8, t * 2.5);
      let rad = r * map(nv, 0, 1, 0.65, 1.35);
      vertex(cx + cos(ang) * rad, cy + sin(ang) * rad);
    }
    endShape(CLOSE);
  }
}

function drawEntangledFlows(coreA, coreB) {
  let numStreams = 4200;
  let center = p5.Vector.lerp(coreA, coreB, 0.5);
  let axis = p5.Vector.sub(coreB, coreA);
  let axisDist = axis.mag();
  let axisAngle = axis.heading();

  // Palette for Soul A (Cool/Water/Depth)
  let palA = [
    color(18, 45, 95),
    color(32, 95, 155),
    color(65, 165, 195),
    color(140, 225, 235),
    color(90, 110, 210)
  ];

  // Palette for Soul B (Warm/Fire/Earth)
  let palB = [
    color(115, 22, 48),
    color(185, 45, 55),
    color(230, 95, 45),
    color(250, 165, 65),
    color(215, 110, 135)
  ];

  // Palette for Transcendence (The Meeting)
  let palMeet = [
    color(255, 240, 215),
    color(255, 200, 160),
    color(230, 175, 220),
    color(255, 225, 130)
  ];

  noFill();

  for (let i = 0; i < numStreams; i++) {
    let isFromA = (i % 2 === 0);
    let origin = isFromA ? coreA : coreB;
    let target = isFromA ? coreB : coreA;

    // Spawn around origin with organic distribution
    let spawnAng = random(TWO_PI);
    let spawnRad = pow(random(1), 1.6) * 520;
    let p = createVector(
      origin.x + cos(spawnAng) * spawnRad,
      origin.y + sin(spawnAng) * spawnRad
    );

    let baseCol = isFromA ? random(palA) : random(palB);
    let meetCol = random(palMeet);

    let steps = int(random(90, 240));
    let stepSize = random(3.5, 6.5);
    let strokeW = random(0.6, 3.2);
    let baseAlpha = random(12, 42);

    // Individual stream curl bias
    let swirlBias = random(-1, 1) > 0 ? 1 : -1;

    for (let s = 0; s < steps; s++) {
      let progress = s / steps;

      // Vectors to key points
      let toTarget = p5.Vector.sub(target, p);
      let dTarget = toTarget.mag();
      let toOrigin = p5.Vector.sub(origin, p);
      let dOrigin = toOrigin.mag();
      let toCenter = p5.Vector.sub(center, p);
      let dCenter = toCenter.mag();

      // 1. Multi-scale Perlin flow field
      let n1 = noise(p.x * 0.0018, p.y * 0.0018);
      let n2 = noise(p.x * 0.006, p.y * 0.006, i * 0.01);
      let flowAng = n1 * TWO_PI * 3.0 + (n2 - 0.5) * PI;
      let vFlow = p5.Vector.fromAngle(flowAng);

      // 2. Mutual Gravity: pulled toward the other soul
      let vPull = toTarget.copy().normalize();

      // 3. Orbital Embrace: swirl around the shared center
      let vOrbit = createVector(-toCenter.y, toCenter.x).normalize();
      if (isFromA) {
        vOrbit.mult(swirlBias * 0.8);
      } else {
        vOrbit.mult(-swirlBias * 0.8);
      }

      // Combine forces based on position
      let centerProximity = constrain(map(dCenter, 0, 550, 1, 0), 0, 1);

      let dir = createVector(0, 0);
      dir.add(vFlow.mult(1.1 - centerProximity * 0.3));
      dir.add(vPull.mult(0.75 + progress * 0.8));
      dir.add(vOrbit.mult(centerProximity * 1.35));
      dir.normalize();

      let nextP = p5.Vector.add(p, p5.Vector.mult(dir, stepSize));

      // Color alchemy: as the stream approaches the center or the other core, it transforms
      let harmony = constrain(map(dCenter, 480, 40, 0, 1), 0, 1);
      let reachOther = constrain(map(dTarget, 600, 100, 0, 1), 0, 1);
      let transformFactor = max(harmony * 0.85, reachOther * 0.7);

      let c = lerpColor(baseCol, meetCol, pow(transformFactor, 1.4));

      // Fade in at birth, fade out at end
      let env = sin(progress * PI);
      c.setAlpha(baseAlpha * env * (1 + harmony * 0.6));

      stroke(c);
      strokeWeight(strokeW * (0.5 + 0.8 * env));
      line(p.x, p.y, nextP.x, nextP.y);

      p = nextP;

      // Stop if deeply absorbed into target core
      if (dTarget < 25) break;
    }
  }
}

function drawResonanceField(center, coreA, coreB) {
  // The "Third Body" — where the two overlap, a luminous, breathing geometric nebula forms
  push();
  translate(center.x, center.y);
  let axisAngle = p5.Vector.sub(coreB, coreA).heading();
  rotate(axisAngle);

  noFill();
  // Intersecting vesica piscis / harmonic waves
  for (let i = 0; i < 450; i++) {
    let t = i / 450;
    let w = lerp(60, 750, pow(t, 0.7));
    let h = lerp(40, 520, pow(t, 0.9));

    let angOffset = (noise(i * 0.05) - 0.5) * 0.6;
    push();
    rotate(angOffset);

    let c1 = color(255, 220, 175);
    let c2 = color(235, 140, 175);
    let c3 = color(130, 215, 235);

    let col = (i % 3 === 0) ? c1 : ((i % 3 === 1) ? c2 : c3);
    col.setAlpha(map(t, 0, 1, 35, 2));
    stroke(col);
    strokeWeight(random(0.5, 2.2));

    // Draw organic broken ellipse
    beginShape();
    let startA = random(TWO_PI);
    let span = random(PI * 0.4, PI * 1.6);
    for (let a = startA; a < startA + span; a += 0.08) {
      let n = noise(cos(a) * 2 + i * 0.02, sin(a) * 2 + i * 0.02);
      let rx = (w * 0.5) * map(n, 0, 1, 0.82, 1.18);
      let ry = (h * 0.5) * map(n, 0, 1, 0.82, 1.18);
      vertex(cos(a) * rx, sin(a) * ry);
    }
    endShape();
    pop();
  }

  // Intense central radiance (the spark of recognition)
  noStroke();
  for (let r = 320; r > 0; r -= 4) {
    let normR = r / 320;
    let c = lerpColor(color(255, 250, 240), color(245, 170, 130), pow(normR, 0.5));
    c.setAlpha(map(normR, 0, 1, 14, 0));
    fill(c);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let nv = noise(cos(a) * 1.5 + normR * 2, sin(a) * 1.5);
      let rad = r * map(nv, 0, 1, 0.7, 1.3);
      vertex(cos(a) * rad * 1.15, sin(a) * rad * 0.85);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawGoldenTethers(coreA, coreB, center) {
  // Delicate, high-contrast filaments of gold and pearl that bridge the two cores directly
  noFill();
  let numTethers = 140;

  for (let i = 0; i < numTethers; i++) {
    let spread = pow(random(1), 1.3) * 420 * (random() < 0.5 ? 1 : -1);

    // Perpendicular vector to the main axis
    let axis = p5.Vector.sub(coreB, coreA).normalize();
    let perp = createVector(-axis.y, axis.x);

    let startPt = p5.Vector.add(coreA, p5.Vector.mult(perp, random(-90, 90)));
    startPt.add(p5.Vector.random2D().mult(random(10, 80)));

    let endPt = p5.Vector.add(coreB, p5.Vector.mult(perp, random(-90, 90)));
    endPt.add(p5.Vector.random2D().mult(random(10, 80)));

    let midPt = p5.Vector.add(center, p5.Vector.mult(perp, spread));
    midPt.add(p5.Vector.random2D().mult(random(20, 120)));

    let ctrl1 = p5.Vector.lerp(startPt, midPt, 0.55);
    ctrl1.add(p5.Vector.mult(perp, random(-180, 180)));

    let ctrl2 = p5.Vector.lerp(midPt, endPt, 0.45);
    ctrl2.add(p5.Vector.mult(perp, random(-180, 180)));

    let isGold = random() < 0.7;
    let baseC = isGold ? color(255, 215, 125) : color(255, 245, 235);

    let segs = 120;
    let prevX = startPt.x;
    let prevY = startPt.y;

    for (let s = 1; s <= segs; s++) {
      let t = s / segs;
      let bx = bezierPoint(startPt.x, ctrl1.x, ctrl2.x, endPt.x, t);
      let by = bezierPoint(startPt.y, ctrl1.y, ctrl2.y, endPt.y, t);

      // Organic tremor
      let n = noise(bx * 0.008, by * 0.008, i * 0.1);
      let offAng = n * TWO_PI * 2;
      let offMag = sin(t * PI) * 28 * (noise(t * 5, i) - 0.5);

      let cx = bx + cos(offAng) * offMag;
      let cy = by + sin(offAng) * offMag;

      let alpha = sin(t * PI) * map(abs(spread), 0, 420, 110, 25);
      baseC.setAlpha(alpha);
      stroke(baseC);
      strokeWeight(sin(t * PI) * random(0.8, 2.4));

      line(prevX, prevY, cx, cy);

      // Occasional luminous nodes (moments of grace/insight)
      if (random() < 0.018 && t > 0.2 && t < 0.8) {
        noStroke();
        fill(255, 250, 230, alpha * 1.4);
        circle(cx, cy, random(2.5, 6));
        fill(255, 210, 120, alpha * 0.4);
        circle(cx, cy, random(8, 18));
      }

      prevX = cx;
      prevY = cy;
    }
  }
}

function drawCoreIdentity(core, isWarm) {
  // Love does not destroy the self; each core retains its own sacred inner geometry,
  // yet holds a seed of the other within it (quiet reciprocity).
  push();
  translate(core.x, core.y);

  // Outer protective rings of the self
  noFill();
  for (let i = 0; i < 160; i++) {
    let r = map(pow(random(1), 1.4), 0, 1, 15, 220);
    let c;
    if (isWarm) {
      c = lerpColor(color(255, 220, 160), color(190, 45, 60), r / 220);
    } else {
      c = lerpColor(color(200, 245, 255), color(25, 75, 145), r / 220);
    }
    c.setAlpha(random(15, 65));
    stroke(c);
    strokeWeight(random(0.6, 2.0));

    let a1 = random(TWO_PI);
    let a2 = a1 + random(PI * 0.2, PI * 1.1);
    beginShape();
    for (let a = a1; a < a2; a += 0.06) {
      let nv = noise(cos(a) * 2 + i * 0.1, sin(a) * 2 + (isWarm ? 10 : 0));
      let rad = r * map(nv, 0, 1, 0.86, 1.14);
      vertex(cos(a) * rad, sin(a) * rad);
    }
    endShape();
  }

  // Deep inner glow
  noStroke();
  for (let r = 85; r > 0; r -= 2) {
    let t = r / 85;
    let c = isWarm 
      ? lerpColor(color(255, 250, 240), color(245, 120, 50), pow(t, 0.7))
      : lerpColor(color(245, 252, 255), color(50, 165, 210), pow(t, 0.7));
    c.setAlpha(map(t, 0, 1, 22, 0));
    fill(c);
    circle(0, 0, r * 2);
  }

  // The Seed of the Other: a quiet presence of the partner's color held at the very center
  for (let i = 0; i < 45; i++) {
    let ang = random(TWO_PI);
    let d = pow(random(1), 2) * 38;
    let x = cos(ang) * d;
    let y = sin(ang) * d;
    let seedCol = isWarm ? color(110, 220, 255, 70) : color(255, 160, 90, 70);
    fill(seedCol);
    circle(x, y, random(2, 7));
  }

  pop();
}

function applyPainterlyTexture() {
  // 1. Subtle impasto / bristle scratches across the canvas
  noFill();
  for (let i = 0; i < 18000; i++) {
    let x = random(width);
    let y = random(height);
    let ang = noise(x * 0.002, y * 0.002) * TWO_PI * 2;
    let len = random(8, 28);

    if (random() < 0.5) {
      stroke(255, 245, 235, random(2, 7));
    } else {
      stroke(10, 12, 20, random(3, 9));
    }
    strokeWeight(random(0.4, 1.1));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // 2. Organic tactile grain at pixel level
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = random(-10, 10);
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();

  // 1. Deep Atmospheric Void & Warmth
  background(7, 8, 16);
  drawAtmosphere();

  // 2. Distant Cosmic Dust & Ambient Resonance
  drawStardust();

  // 3. The Two Sovereign Currents (Blue/Teal & Crimson/Coral)
  drawInterweavingFlows();

  // 4. The Hearth (The Third Space of Union)
  drawUnionCore();

  // 5. Fine Luminous Filaments (Delicate Bonds)
  drawGoldenTethers();

  // 6. Painterly Canvas Texture & Glaze
  applyCanvasTexture();
}

function drawAtmosphere() {
  noStroke();

  // Deep indigo/violet ambient shadows
  for (let i = 0; i < 60; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(400, 1200);
    drawSoftCircle(x, y, r, color(16, 12, 32, 8));
  }

  // Cool origin aura (Upper Left)
  for (let i = 0; i < 40; i++) {
    let x = random(200, 750);
    let y = random(350, 950);
    let r = random(300, 900);
    drawSoftCircle(x, y, r, color(12, 65, 95, 6));
  }

  // Warm origin aura (Lower Right)
  for (let i = 0; i < 40; i++) {
    let x = random(850, 1400);
    let y = random(1050, 1650);
    let r = random(300, 900);
    drawSoftCircle(x, y, r, color(110, 20, 45, 6));
  }

  // Central alchemical glow (Where they meet)
  for (let i = 0; i < 50; i++) {
    let x = 800 + randomGaussian(0, 180);
    let y = 1000 + randomGaussian(0, 180);
    let r = random(200, 800);
    drawSoftCircle(x, y, r, color(190, 95, 50, 5));
  }
}

function drawSoftCircle(x, y, radius, col) {
  let steps = 25;
  let rCol = red(col);
  let gCol = green(col);
  let bCol = blue(col);
  let aCol = alpha(col);

  for (let i = steps; i > 0; i--) {
    let currR = map(i, 0, steps, 0, radius);
    let currAlpha = aCol * pow(1 - i / steps, 1.8);
    fill(rCol, gCol, bCol, currAlpha);
    circle(x, y, currR * 2);
  }
}

function drawStardust() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 2500; i++) {
    let x = random(width);
    let y = random(height);
    let dCenter = dist(x, y, 800, 1000);

    if (random() < map(dCenter, 0, 1200, 0.85, 0.15)) {
      let sz = random(0.8, 3.2);
      let n = noise(x * 0.004, y * 0.004);
      if (n > 0.55) {
        fill(255, 220, 170, random(15, 70));
      } else if (x < 800) {
        fill(110, 210, 255, random(15, 60));
      } else {
        fill(255, 120, 150, random(15, 60));
      }
      circle(x, y, sz);
    }
  }
  blendMode(BLEND);
}

function drawInterweavingFlows() {
  let originA = createVector(460, 660);   // Cool Sovereignty
  let originB = createVector(1140, 1340); // Warm Sovereignty
  let center = createVector(800, 1000);   // The Hearth

  // Soft Painterly Underpainting Ribbons
  blendMode(BLEND);
  drawFlowPass(1200, originA, originB, center, false);

  // Luminous Braided Currents
  blendMode(ADD);
  drawFlowPass(3800, originA, originB, center, true);
  blendMode(BLEND);

  // Subtle definition around the two distinct origins
  blendMode(ADD);
  drawSoftCircle(originA.x, originA.y, 260, color(30, 160, 220, 4));
  drawSoftCircle(originA.x, originA.y, 90, color(160, 235, 255, 8));

  drawSoftCircle(originB.x, originB.y, 260, color(230, 50, 85, 4));
  drawSoftCircle(originB.x, originB.y, 90, color(255, 180, 150, 8));
  blendMode(BLEND);
}

function drawFlowPass(numParticles, originA, originB, center, isGlowing) {
  noFill();

  for (let i = 0; i < numParticles; i++) {
    let type = (i % 2 === 0) ? 0 : 1;
    let home = (type === 0) ? originA : originB;
    let other = (type === 0) ? originB : originA;

    // Spawn mostly near origins, some in the broader field
    let p;
    let spawnRoll = random();
    if (spawnRoll < 0.72) {
      let ang = random(TWO_PI);
      let rad = abs(randomGaussian(0, 170));
      p = createVector(home.x + cos(ang) * rad, home.y + sin(ang) * rad);
    } else {
      p = createVector(random(100, width - 100), random(100, height - 100));
    }

    let steps = isGlowing ? int(random(90, 210)) : int(random(50, 100));
    let stepSize = isGlowing ? 3.5 : 6.0;

    for (let s = 0; s < steps; s++) {
      let prevP = p.copy();

      // 1. Organic Curl Noise Field
      let nScale = 0.0016;
      let eps = 0.05;
      let n1 = noise(p.x * nScale, p.y * nScale + eps);
      let n2 = noise(p.x * nScale, p.y * nScale - eps);
      let n3 = noise(p.x * nScale + eps, p.y * nScale);
      let n4 = noise(p.x * nScale - eps, p.y * nScale);
      let curl = createVector(n1 - n2, -(n3 - n4)).normalize();

      // 2. Orbit around Own Origin
      let toHome = p5.Vector.sub(home, p);
      let dHome = max(toHome.mag(), 30);
      toHome.normalize();
      let tangentHome = createVector(-toHome.y, toHome.x);

      // 3. Longing / Bridge toward the Other Origin
      let toOther = p5.Vector.sub(other, p);
      let dOther = max(toOther.mag(), 30);
      toOther.normalize();

      // 4. Shared Vortex around the Center (The Dance)
      let toCenter = p5.Vector.sub(center, p);
      let dCenter = max(toCenter.mag(), 20);
      toCenter.normalize();
      let tangentCenter = createVector(-toCenter.y, toCenter.x);

      // Combine forces into a graceful choreography
      let vel = createVector(0, 0);
      vel.add(p5.Vector.mult(curl, 1.35));

      // As the particle ages, it surrenders its private orbit and reaches across
      let progress = s / steps;
      let reach = map(progress, 0, 1, 0.25, 1.85);

      vel.add(p5.Vector.mult(tangentHome, 160 / (dHome + 90)));
      vel.add(p5.Vector.mult(toOther, 0.85 * reach));

      // Central embrace
      let centerInfluence = map(constrain(dCenter, 0, 650), 0, 650, 1.8, 0.15);
      vel.add(p5.Vector.mult(tangentCenter, centerInfluence * 1.15));
      vel.add(p5.Vector.mult(toCenter, centerInfluence * 0.55));

      vel.normalize().mult(stepSize);
      p.add(vel);

      // Color alchemy: transformation through proximity
      let proximityToCenter = constrain(map(dCenter, 480, 30, 0, 1), 0, 1);
      let proximityToOther = constrain(map(dOther, 750, 120, 0, 1), 0, 1);
      let alchemy = max(proximityToCenter * 0.9, proximityToOther * 0.65);

      let col = getStreamColor(type, alchemy, progress, isGlowing);

      let sw = isGlowing 
        ? map( sin(progress * PI), 0, 1, 0.4, 2.4 ) * map(proximityToCenter, 0, 1, 0.9, 1.6)
        : map( sin(progress * PI), 0, 1, 4, 18 );

      strokeWeight(sw);
      stroke(col);
      line(prevP.x, prevP.y, p.x, p.y);
    }
  }
}

function getStreamColor(type, alchemy, progress, isGlowing) {
  let baseCol, midCol, unionCol;

  if (type === 0) {
    // Cool Soul: Deep Cerulean -> Luminous Turquoise -> Warm Champagne Gold
    baseCol = color(15, 105, 175);
    midCol = color(65, 215, 230);
    unionCol = color(255, 225, 165);
  } else {
    // Warm Soul: Deep Crimson/Magenta -> Coral Vermilion -> Warm Champagne Gold
    baseCol = color(175, 22, 68);
    midCol = color(255, 95, 70);
    unionCol = color(255, 225, 165);
  }

  let c;
  if (alchemy < 0.45) {
    c = lerpColor(baseCol, midCol, map(alchemy, 0, 0.45, 0, 1));
  } else {
    c = lerpColor(midCol, unionCol, map(alchemy, 0.45, 1.0, 0, 1));
  }

  let fade = sin(progress * PI);
  let alphaVal = isGlowing ? (fade * 19) : (fade * 14);

  return color(red(c), green(c), blue(c), alphaVal);
}

function drawUnionCore() {
  blendMode(ADD);
  let cx = 800;
  let cy = 1000;

  // Nested rings of light where the two currents fuse
  noFill();
  for (let i = 0; i < 900; i++) {
    let ang1 = random(TWO_PI);
    let ang2 = ang1 + random(0.4, 1.8);

    // Elliptical tilt aligned with the two origins
    push();
    translate(cx, cy);
    rotate(PI / 4 + randomGaussian(0, 0.25));

    let rx = abs(randomGaussian(0, 160));
    let ry = rx * random(0.55, 0.95);

    let warmth = map(rx, 0, 300, 1, 0);
    let c = lerpColor(color(255, 120, 160), color(255, 240, 195), constrain(warmth, 0, 1));

    stroke(red(c), green(c), blue(c), random(4, 16));
    strokeWeight(random(0.6, 2.2));

    beginShape();
    for (let a = ang1; a < ang2; a += 0.1) {
      let n = noise(cos(a) * 2 + i * 0.01, sin(a) * 2) * 35;
      let x = cos(a) * (rx + n);
      let y = sin(a) * (ry + n);
      vertex(x, y);
    }
    endShape();
    pop();
  }

  // Radiant heart glow
  noStroke();
  drawSoftCircle(cx, cy, 380, color(255, 160, 90, 6));
  drawSoftCircle(cx, cy, 190, color(255, 225, 175, 10));
  drawSoftCircle(cx, cy, 75, color(255, 250, 235, 14));

  blendMode(BLEND);
}

function drawGoldenTethers() {
  // Delicate direct harmonic curves bridging the two origins through the center
  blendMode(ADD);
  noFill();

  let originA = createVector(460, 660);
  let originB = createVector(1140, 1340);

  for (let i = 0; i < 240; i++) {
    let spreadA = p5.Vector.random2D().mult(random(10, 220));
    let spreadB = p5.Vector.random2D().mult(random(10, 220));

    let p0 = p5.Vector.add(originA, spreadA);
    let p3 = p5.Vector.add(originB, spreadB);

    // Control points pulling into an S-curve embrace around the center
    let side = (i % 2 === 0) ? 1 : -1;
    let perp = createVector(-(p3.y - p0.y), p3.x - p0.x).normalize();
    let pull = random(80, 420) * side;

    let mid1 = p5.Vector.lerp(p0, p3, 0.35).add(p5.Vector.mult(perp, pull));
    let mid2 = p5.Vector.lerp(p0, p3, 0.65).sub(p5.Vector.mult(perp, pull * 0.8));

    let segs = 70;
    strokeWeight(random(0.4, 1.3));

    for (let s = 0; s < segs; s++) {
      let t1 = s / segs;
      let t2 = (s + 1) / segs;

      let x1 = bezierPoint(p0.x, mid1.x, mid2.x, p3.x, t1);
      let y1 = bezierPoint(p0.y, mid1.y, mid2.y, p3.y, t1);
      let x2 = bezierPoint(p0.x, mid1.x, mid2.x, p3.x, t2);
      let y2 = bezierPoint(p0.y, mid1.y, mid2.y, p3.y, t2);

      // Add subtle organic tremor
      let n1 = (noise(x1 * 0.005, y1 * 0.005, i) - 0.5) * 25;
      let n2 = (noise(x2 * 0.005, y2 * 0.005, i) - 0.5) * 25;

      let colA = color(90, 220, 255);
      let colMid = color(255, 235, 185);
      let colB = color(255, 110, 140);

      let c = (t1 < 0.5) 
        ? lerpColor(colA, colMid, t1 * 2) 
        : lerpColor(colMid, colB, (t1 - 0.5) * 2);

      let alpha = sin(t1 * PI) * 22;
      stroke(red(c), green(c), blue(c), alpha);
      line(x1 + n1, y1 + n1, x2 + n2, y2 + n2);
    }
  }
  blendMode(BLEND);
}

function applyCanvasTexture() {
  // Subtle oil-on-linen tooth and warm vignette
  loadPixels();
  let cx = width * 0.5;
  let cy = height * 0.5;
  let maxDist = dist(0, 0, cx, cy);

  for (let y = 0; y < height; y++) {
    let weaveY = sin(y * 0.9) * 2.5;
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Fine canvas weave + organic grain
      let weaveX = sin(x * 0.9) * 2.5;
      let grain = (random() - 0.5) * 10 + (weaveX + weaveY) * 0.6;

      // Gentle vignette to hold the light inward
      let d = dist(x, y, cx, cy);
      let vig = map(pow(d / maxDist, 1.6), 0, 1, 1.03, 0.72);

      pixels[idx]     = constrain(pixels[idx] * vig + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * vig + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * vig + grain, 0, 255);
    }
  }
  updatePixels();
}

let bgPalette, leftPalette, rightPalette, unityPalette;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  bgPalette = [
    color(10, 12, 28),
    color(18, 15, 36),
    color(28, 18, 42),
    color(8, 10, 20)
  ];

  // Deep cerulean, indigo, violet, teal (Calm, depth, the infinite)
  leftPalette = [
    color(18, 45, 92),
    color(32, 82, 138),
    color(58, 128, 168),
    color(72, 60, 140),
    color(110, 175, 205),
    color(25, 30, 75)
  ];

  // Crimson, burnt sienna, coral, deep rose (Warmth, vitality, earth)
  rightPalette = [
    color(120, 22, 42),
    color(178, 45, 58),
    color(218, 88, 62),
    color(238, 135, 85),
    color(155, 35, 75),
    color(90, 18, 35)
  ];

  // Gold, peach, soft magenta, incandescent white (The emergent third)
  unityPalette = [
    color(255, 215, 120),
    color(255, 180, 145),
    color(245, 140, 165),
    color(255, 242, 205),
    color(220, 170, 235),
    color(255, 252, 245)
  ];
}

function draw() {
  background(10, 12, 24);

  // 1. Deep Atmospheric Underpainting
  drawAtmosphere();

  // 2. The Core Radiance (The shared space of meeting)
  drawUnityGlow();

  // 3. The Flow of Two Essences (Currents of paint/threads)
  drawEssenceFlows();

  // 4. Impasto & Textured Brushwork along the embrace
  drawEmbraceBrushwork();

  // 5. The Golden Threshold (Kintsugi-like filaments of connection)
  drawGoldenFilaments();

  // 6. Luminous Spores & Stardust (What rises from love)
  drawAscendantLight();

  // 7. Physical Canvas Texture Overlay
  applyCanvasTexture();
}

function getSoulSpine(side, y) {
  let t = y / height;
  // Two paths that start apart, lean into an embrace around y = 0.52, and gently spiral
  let meetingY = 0.52;
  let distFromMeeting = abs(t - meetingY);

  // Smooth bell-like curve for proximity
  let proximity = exp(-pow((t - meetingY) * 2.8, 2));

  let baseSpread = map(t, 0, 1, 520, 460);
  let currentSpread = baseSpread * (1 - proximity * 0.78);

  // Add a gentle, harmonious sway
  let sway = sin(t * PI * 2.5 - 0.5) * 65 * proximity;
  let organicNoise = (noise(side * 10, t * 3) - 0.5) * 90;

  let x = width * 0.5 + side * currentSpread + sway + organicNoise;
  return x;
}

function drawAtmosphere() {
  noStroke();
  // Thousands of large, translucent wash dabs
  for (let i = 0; i < 6000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);

    let leftX = getSoulSpine(-1, y);
    let rightX = getSoulSpine(1, y);

    let dLeft = dist(x, y, leftX, y);
    let dRight = dist(x, y, rightX, y);

    let c;
    if (dLeft < dRight) {
      let inter = constrain(map(dLeft, 0, 700, 0, 1), 0, 1);
      c = lerpColor(random(leftPalette), random(bgPalette), pow(inter, 0.7));
    } else {
      let inter = constrain(map(dRight, 0, 700, 0, 1), 0, 1);
      c = lerpColor(random(rightPalette), random(bgPalette), pow(inter, 0.7));
    }

    fill(red(c), green(c), blue(c), random(8, 22));
    push();
    translate(x, y);
    rotate(n * TWO_PI * 2);
    let w = random(80, 260);
    let h = random(40, 140);
    ellipse(0, 0, w, h);
    pop();
  }
}

function drawUnityGlow() {
  push();
  blendMode(SCREEN);
  noStroke();

  let centerY = height * 0.51;
  let centerX = width * 0.5;

  // Layered radiant washes at the heart of the canvas
  for (let i = 0; i < 900; i++) {
    let angle = random(TWO_PI);
    let r = pow(random(), 1.6) * 650;
    let x = centerX + cos(angle) * r * 0.85;
    let y = centerY + sin(angle) * r * 1.25;

    let c = random(unityPalette);
    let alpha = map(r, 0, 650, 16, 1);
    fill(red(c), green(c), blue(c), alpha);

    let sz = map(r, 0, 650, 220, 60) * random(0.6, 1.4);
    ellipse(x, y, sz, sz * random(0.7, 1.3));
  }
  pop();
}

function drawEssenceFlows() {
  // Flowing ribbons that belong to each being, curving toward the other
  let numStreams = 3400;

  for (let i = 0; i < numStreams; i++) {
    let side = (i % 2 === 0) ? -1 : 1;
    let startY = random(-100, height + 100);
    let spineX = getSoulSpine(side, constrain(startY, 0, height));

    // Cluster around the spine, with wider dispersion further away
    let spread = (randomGaussian() * 140);
    let x = spineX + spread;
    let y = startY;

    let palette = (side === -1) ? leftPalette : rightPalette;
    let baseCol = random(palette);
    let strokeW = random(1.2, 5.5);
    let steps = int(random(35, 95));

    noFill();

    for (let s = 0; s < steps; s++) {
      let t = constrain(y / height, 0, 1);
      let lSpine = getSoulSpine(-1, y);
      let rSpine = getSoulSpine(1, y);
      let midX = (lSpine + rSpine) * 0.5;

      // Distance to the central meeting zone
      let distToCenter = dist(x, y, midX, height * 0.51);
      let unityFactor = constrain(map(distToCenter, 420, 40, 0, 1), 0, 1);

      // Color shifts toward gold/luminous peach as it nears the other
      let currentCol = baseCol;
      if (unityFactor > 0.05) {
        let uCol = unityPalette[(i + int(s * 0.2)) % unityPalette.length];
        currentCol = lerpColor(baseCol, uCol, pow(unityFactor, 1.3));
      }

      let alpha = sin(map(s, 0, steps, 0, PI)) * map(unityFactor, 0, 1, 75, 130);
      stroke(red(currentCol), green(currentCol), blue(currentCol), alpha);
      strokeWeight(strokeW * sin(map(s, 0, steps, 0, PI)));

      // Vector field combining upward/inward yearning and organic curl
      let n = noise(x * 0.0025, y * 0.0025, side * 5);
      let angle = map(n, 0, 1, -PI, PI);

      // Pull toward the spine and toward the partner's spine near the middle
      let targetX = lerp(side === -1 ? lSpine : rSpine, midX, unityFactor * 0.75);
      let pullAngle = atan2((height * 0.48) - y, targetX - x);

      // Swirl around the center of embrace
      let dx = x - midX;
      let dy = y - height * 0.51;
      let swirlAngle = atan2(dy, dx) + PI * 0.42 * side;

      let finalAngle = lerpAngle(angle, pullAngle, 0.45);
      if (unityFactor > 0.2) {
        finalAngle = lerpAngle(finalAngle, swirlAngle, unityFactor * 0.55);
      }

      let nx = x + cos(finalAngle) * 6;
      let ny = y + sin(finalAngle) * 6;

      line(x, y, nx, ny);
      x = nx;
      y = ny;
    }
  }
}

function drawEmbraceBrushwork() {
  // Rich, tactile oil-paint strokes that define the bodies of the two forces
  let numStrokes = 4500;

  for (let i = 0; i < numStrokes; i++) {
    let t = random(0.04, 0.96);
    // Weight distribution toward the middle embrace
    if (random() < 0.55) {
      t = constrain(randomGaussian(0.51, 0.18), 0.05, 0.95);
    }

    let y = t * height;
    let side = (random() < 0.5) ? -1 : 1;
    let spineX = getSoulSpine(side, y);
    let otherSpineX = getSoulSpine(-side, y);
    let midX = (spineX + otherSpineX) * 0.5;

    let offset = randomGaussian() * map(abs(t - 0.51), 0, 0.5, 95, 190);
    let x = spineX + offset;

    let distToPartner = abs(x - otherSpineX);
    let distToMid = abs(x - midX);
    let bridgeFactor = constrain(map(distToMid, 220, 0, 0, 1), 0, 1) * exp(-pow((t - 0.51) * 3.2, 2));

    let palette = (side === -1) ? leftPalette : rightPalette;
    let c = random(palette);

    // Sometimes borrow a hue from the other side — empathy / reflection
    if (random() < bridgeFactor * 0.45) {
      c = random(side === -1 ? rightPalette : leftPalette);
    }
    // Transform into light at the nexus
    if (bridgeFactor > 0.25 && random() < bridgeFactor * 0.85) {
      c = lerpColor(c, random(unityPalette), pow(bridgeFactor, 0.8));
    }

    // Follow the contour of the spine
    let yNext = y + 10;
    let spineNext = getSoulSpine(side, yNext);
    let spineAngle = atan2(10, spineNext - spineX);
    let nAngle = (noise(x * 0.005, y * 0.005) - 0.5) * 1.2;

    // Angle bridges across the gap in the middle
    let strokeAngle = spineAngle + nAngle;
    if (bridgeFactor > 0.35 && random() < 0.5) {
      let acrossAngle = atan2((noise(i) - 0.5) * 60, otherSpineX - spineX);
      strokeAngle = lerpAngle(strokeAngle, acrossAngle, bridgeFactor * 0.7);
    }

    let len = random(18, 65) * (1 - bridgeFactor * 0.3);
    let thick = random(4, 16);

    drawImpastoStroke(x, y, strokeAngle, len, thick, c, bridgeFactor);
  }
}

function drawImpastoStroke(x, y, angle, len, thick, col, glow) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();

  // Subtle dark underside for physical relief
  fill(10, 8, 20, 45);
  ellipse(2, 3, len * 1.02, thick * 0.95);

  // Main pigment body with bristle striations
  let bristles = int(map(thick, 4, 16, 3, 7));
  for (let b = 0; b < bristles; b++) {
    let by = map(b, 0, bristles - 1, -thick * 0.4, thick * 0.4);
    let jitter = (noise(x * 0.1, y * 0.1, b) - 0.5) * 25;
    let r = constrain(red(col) + jitter, 0, 255);
    let g = constrain(green(col) + jitter, 0, 255);
    let bl = constrain(blue(col) + jitter, 0, 255);

    fill(r, g, bl, random(150, 220));
    ellipse(random(-2, 2), by, len * random(0.85, 1.05), thick / bristles * 1.6);
  }

  // Catch-light on the ridge of the paint stroke
  if (glow > 0.2 || random() < 0.25) {
    fill(255, 245, 225, map(glow, 0, 1, 35, 130));
    ellipse(0, -thick * 0.22, len * 0.75, thick * 0.22);
  }
  pop();
}

function drawGoldenFilaments() {
  // Delicate, luminous threads weaving between the two cores—vulnerability and trust
  for (let i = 0; i < 420; i++) {
    let t = constrain(randomGaussian(0.51, 0.19), 0.12, 0.90);
    let yLeft = t * height + random(-60, 60);
    let yRight = t * height + random(-60, 60);

    let xLeft = getSoulSpine(-1, yLeft) + random(-70, 50);
    let xRight = getSoulSpine(1, yRight) + random(-50, 70);

    let midX = (xLeft + xRight) * 0.5;
    let midY = (yLeft + yRight) * 0.5;

    // Arching control points
    let arch = (random() - 0.48) * 260;
    let cp1x = lerp(xLeft, midX, 0.5) + random(-50, 50);
    let cp1y = yLeft + arch;
    let cp2x = lerp(midX, xRight, 0.5) + random(-50, 50);
    let cp2y = yRight - arch * random(0.3, 1.0);

    let c = random(unityPalette);
    let steps = 50;

    noFill();
    for (let s = 0; s < steps; s++) {
      let u1 = s / steps;
      let u2 = (s + 1) / steps;

      let px1 = bezierPoint(xLeft, cp1x, cp2x, xRight, u1);
      let py1 = bezierPoint(yLeft, cp1y, cp2y, yRight, u1);
      let px2 = bezierPoint(xLeft, cp1x, cp2x, xRight, u2);
      let py2 = bezierPoint(yLeft, cp1y, cp2y, yRight, u2);

      // Add subtle organic tremor
      let tremor1 = (noise(px1 * 0.02, py1 * 0.02, i) - 0.5) * 12;
      let tremor2 = (noise(px2 * 0.02, py2 * 0.02, i) - 0.5) * 12;

      let alpha = sin(u1 * PI) * random(50, 170);
      stroke(red(c), green(c), blue(c), alpha);
      strokeWeight(sin(u1 * PI) * random(0.8, 2.8));
      line(px1, py1 + tremor1, px2, py2 + tremor2);
    }
  }
}

function drawAscendantLight() {
  // Fine luminous embers and soft bokeh rising from the union into the upper canvas
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let t = pow(random(), 1.3); 
    let y = map(t, 0, 1, height * 0.85, height * 0.03);

    let lSpine = getSoulSpine(-1, y);
    let rSpine = getSoulSpine(1, y);
    let midX = (lSpine + rSpine) * 0.5;

    // Spread widens as it ascends into a shared sky
    let spread = map(y, height * 0.7, 0, 90, 480);
    let x = midX + randomGaussian() * spread;

    let c = random(unityPalette);
    if (random() < 0.3) {
      c = (x < midX) ? lerpColor(c, leftPalette[4], 0.5) : lerpColor(c, rightPalette[3], 0.5);
    }

    let sz = random(1.5, 7.5);
    if (random() < 0.06) sz = random(10, 26); // Occasional soft halo

    if (sz > 9) {
      fill(red(c), green(c), blue(c), random(12, 35));
      ellipse(x, y, sz * 2.2, sz * 2.2);
      fill(255, 250, 235, random(60, 120));
      ellipse(x, y, sz * 0.45, sz * 0.45);
    } else {
      fill(red(c), green(c), blue(c), random(80, 230));
      ellipse(x, y, sz, sz);
    }
  }
}

function applyCanvasTexture() {
  // Subtle woven linen tooth and fine pigment grain
  noFill();
  for (let y = 0; y < height; y += 3) {
    let alpha = random(4, 10);
    stroke(255, 248, 235, alpha);
    strokeWeight(1);
    line(0, y, width, y);
  }
  for (let x = 0; x < width; x += 3) {
    let alpha = random(3, 8);
    stroke(10, 8, 18, alpha);
    strokeWeight(1);
    line(x, 0, x, height);
  }

  // Gentle vignette to hold the eye in the emotional core
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let angle = random(TWO_PI);
    let r = random(780, 1300);
    let x = width * 0.5 + cos(angle) * r * 0.85;
    let y = height * 0.5 + sin(angle) * r * 1.05;
    fill(6, 7, 16, random(8, 20));
    ellipse(x, y, random(120, 300), random(120, 300));
  }
}

function lerpAngle(a, b, t) {
  let diff = b - a;
  while (diff < -PI) diff += TWO_PI;
  while (diff > PI) diff -= TWO_PI;
  return a + diff * t;
}

let coldPalette = ['#070b19', '#0f1e36', '#1b3b5c', '#2c5e8a', '#4682b4', '#7ba7cc', '#b8d8e8'];
let warmPalette = ['#1f070b', '#3d0c16', '#6b1522', '#9e2a2b', '#c94a29', '#e07a5f', '#f4a261'];
let unionPalette = ['#ffbe0b', '#fb5607', '#ff006e', '#ffd166', '#ffffff', '#fff0f3', '#ffe5ec'];

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(6, 5, 10);

  let cx = width * 0.5;
  let cy = height * 0.48;

  // Two distinct origins, leaning into one another
  let focusA = createVector(cx - 180, cy - 80);
  let focusB = createVector(cx + 180, cy + 80);

  // 1. Deep atmospheric foundation
  drawAtmosphere(cx, cy);

  // 2. Distant cosmic dust
  drawStarfield(cx, cy);

  // 3. The painting's body: thousands of textured, painterly ribbons
  // Organized in layers from deep background to luminous foreground
  drawFlowLayer(focusA, focusB, 3500, 140, 0.0015, 0.12, true);
  drawFlowLayer(focusA, focusB, 5000, 70, 0.0025, 0.25, true);
  drawFlowLayer(focusA, focusB, 7000, 30, 0.004, 0.45, false);
  drawFlowLayer(focusA, focusB, 5000, 12, 0.006, 0.75, false);

  // 4. The Sanctuary: filaments of connection bridging the two souls
  drawBridges(focusA, focusB, cx, cy);

  // 5. The vulnerability: glowing embers rising from the union
  drawEmbers(cx, cy);

  // 6. Tactile canvas finish
  applyCanvasTexture();
}

function drawAtmosphere(cx, cy) {
  noStroke();
  for (let r = 2200; r > 0; r -= 15) {
    let inter = map(r, 0, 2200, 1, 0);
    let c = lerpColor(color(45, 20, 35), color(6, 5, 10), pow(1 - inter, 0.6));
    fill(red(c), green(c), blue(c), 18);
    ellipse(cx, cy, r, r * 1.25);
  }
}

function drawStarfield(cx, cy) {
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, cx, cy);
    let alpha = map(d, 0, 1200, 120, 10, true);
    stroke(255, 240, 230, random(alpha));
    strokeWeight(random(0.5, 2.5));
    point(x, y);
  }
}

function getFlowAngle(x, y, focusA, focusB, noiseScale) {
  let n = noise(x * noiseScale, y * noiseScale);

  // Angle around Entity A (pulling clockwise and inward)
  let dxA = x - focusA.x;
  let dyA = y - focusA.y;
  let angleA = atan2(dyA, dxA) + PI * 0.42;

  // Angle around Entity B (pulling counter-clockwise and inward)
  let dxB = x - focusB.x;
  let dyB = y - focusB.y;
  let angleB = atan2(dyB, dxB) - PI * 0.42;

  let dA = sqrt(dxA * dxA + dyA * dyA);
  let dB = sqrt(dxB * dxB + dyB * dyB);

  // Smoothly blend the two gravitational fields using vectors
  let weightA = 1 / (pow(dA, 1.35) + 1);
  let weightB = 1 / (pow(dB, 1.35) + 1);

  let vx = cos(angleA) * weightA + cos(angleB) * weightB;
  let vy = sin(angleA) * weightA + sin(angleB) * weightB;
  let baseAngle = atan2(vy, vx);

  // Add organic turbulence
  return baseAngle + (n - 0.5) * TWO_PI * 1.2;
}

function drawFlowLayer(focusA, focusB, count, baseWeight, noiseScale, alphaMult, isBackground) {
  let cx = (focusA.x + focusB.x) * 0.5;
  let cy = (focusA.y + focusB.y) * 0.5;

  for (let i = 0; i < count; i++) {
    // Bias starting points toward the center of the canvas
    let x, y;
    if (random() < 0.65 && !isBackground) {
      let angle = random(TWO_PI);
      let r = pow(random(), 0.7) * 750;
      x = cx + cos(angle) * r;
      y = cy + sin(angle) * r * 1.25;
    } else {
      x = random(-100, width + 100);
      y = random(-100, height + 100);
    }

    let dA = dist(x, y, focusA.x, focusA.y);
    let dB = dist(x, y, focusB.x, focusB.y);
    let dCenter = dist(x, y, cx, cy);

    // Determine the emotional color of the stroke based on its origin
    let col;
    let harmony = exp(-dCenter * 0.0038) * exp(-abs(dA - dB) * 0.0045);

    if (random() < harmony * 1.4) {
      col = color(random(unionPalette));
      blendMode(SCREEN);
    } else {
      blendMode(BLEND);
      let pA = (dB) / (dA + dB + 0.001);
      if (random() < pow(pA, 1.5)) {
        col = color(random(coldPalette));
      } else {
        col = color(random(warmPalette));
      }
      // Deepen colors at the outer edges
      if (dCenter > 550 && random() < 0.75) {
        col = lerpColor(col, color(6, 5, 12), map(dCenter, 550, 1100, 0, 0.85, true));
      }
    }

    let steps = int(random(15, 45));
    let stepSize = map(baseWeight, 12, 140, 5, 18);

    // Draw the brushstroke
    for (let s = 0; s < steps; s++) {
      let angle = getFlowAngle(x, y, focusA, focusB, noiseScale);
      let nx = x + cos(angle) * stepSize;
      let ny = y + sin(angle) * stepSize;

      let progress = s / steps;
      let taper = sin(progress * PI); // Taper at both ends
      let w = baseWeight * taper * random(0.85, 1.15);

      let a = 255 * alphaMult * taper * 0.25;

      // Multi-bristle effect for finer layers
      if (baseWeight <= 30) {
        stroke(red(col), green(col), blue(col), a * 0.7);
        strokeWeight(w * 0.6);
        line(x, y, nx, ny);

        // Highlight bristle
        stroke(min(red(col) + 30, 255), min(green(col) + 30, 255), min(blue(col) + 30, 255), a * 0.4);
        let off = w * 0.25;
        line(x + off, y - off, nx + off, ny - off);
      } else {
        stroke(red(col), green(col), blue(col), a);
        strokeWeight(w);
        line(x, y, nx, ny);
      }

      x = nx;
      y = ny;
    }
  }
  blendMode(BLEND);
}

function drawBridges(focusA, focusB, cx, cy) {
  blendMode(ADD);
  noFill();

  // Golden and white filaments directly tying the two cores together
  for (let i = 0; i < 650; i++) {
    let spread = 240;
    let x1 = focusA.x + randomGaussian() * spread;
    let y1 = focusA.y + randomGaussian() * spread;
    let x4 = focusB.x + randomGaussian() * spread;
    let y4 = focusB.y + randomGaussian() * spread;

    // Arching through the center of union
    let pull = random(-450, 450);
    let angle = atan2(focusB.y - focusA.y, focusB.x - focusA.x) + HALF_PI;

    let x2 = lerp(x1, cx, 0.5) + cos(angle) * pull + random(-80, 80);
    let y2 = lerp(y1, cy, 0.5) + sin(angle) * pull + random(-80, 80);
    let x3 = lerp(x4, cx, 0.5) + cos(angle) * pull + random(-80, 80);
    let y3 = lerp(y4, cy, 0.5) + sin(angle) * pull + random(-80, 80);

    let col = color(random(unionPalette));
    let alpha = random(4, 22);
    stroke(red(col), green(col), blue(col), alpha);
    strokeWeight(random(0.5, 3.0));

    bezier(x1, y1, x2, y2, x3, y3, x4, y4);
  }

  // The soft, blinding heart where their boundaries dissolve
  noStroke();
  for (let r = 450; r > 0; r -= 5) {
    let inter = map(r, 0, 450, 1, 0);
    let c = lerpColor(color(255, 160, 100), color(255, 250, 245), inter);
    fill(red(c), green(c), blue(c), pow(inter, 2.5) * 4.5);

    push();
    translate(cx, cy);
    rotate(PI * 0.2);
    ellipse(0, 0, r * 1.1, r * 1.6);
    pop();
  }

  // Distinct, quiet glow for each individual core so they are not lost
  for (let r = 300; r > 0; r -= 10) {
    let inter = map(r, 0, 300, 1, 0);
    fill(100, 180, 255, pow(inter, 2) * 3);
    ellipse(focusA.x, focusA.y, r, r);

    fill(255, 100, 80, pow(inter, 2) * 3);
    ellipse(focusB.x, focusB.y, r, r);
  }

  blendMode(BLEND);
}

function drawEmbers(cx, cy) {
  blendMode(ADD);
  for (let i = 0; i < 1200; i++) {
    let angle = random(TWO_PI);
    let distFromCenter = pow(random(), 1.6) * 850;
    let x = cx + cos(angle) * distFromCenter;
    let y = cy + sin(angle) * distFromCenter * 1.25;

    let col = color(random(unionPalette));
    let sz = map(distFromCenter, 0, 850, random(1.5, 6), random(0.5, 2.5));
    let alpha = map(distFromCenter, 0, 850, random(80, 220), random(10, 60));

    noStroke();
    fill(red(col), green(col), blue(col), alpha * 0.25);
    ellipse(x, y, sz * 3.5, sz * 3.5);

    fill(255, 250, 240, alpha);
    ellipse(x, y, sz, sz);
  }
  blendMode(BLEND);
}

function applyCanvasTexture() {
  // Subtle woven linen effect and tonal vignette
  loadPixels();
  let d = pixelDensity();
  let w = width * d;
  let h = height * d;
  let cx = w * 0.5;
  let cy = h * 0.48;
  let maxDist = sqrt(cx * cx + cy * cy);

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let idx = (x + y * w) * 4;

      // Canvas weave
      let weave = (sin(x * 1.5) + sin(y * 1.5)) * 2.5;
      let grain = random(-9, 9) + weave;

      // Vignette
      let dx = x - cx;
      let dy = y - cy;
      let distSq = sqrt(dx * dx + dy * dy);
      let vig = map(distSq, maxDist * 0.45, maxDist, 1.0, 0.35, true);

      pixels[idx] = constrain((pixels[idx] + grain) * vig, 0, 255);
      pixels[idx + 1] = constrain((pixels[idx + 1] + grain) * vig, 0, 255);
      pixels[idx + 2] = constrain((pixels[idx + 2] + grain) * vig, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  angleMode(RADIANS);
  ellipseMode(CENTER);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  colorMode(RGB, 255);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  noiseDetail(4, 0.5);
  blendMode(BLEND);
  paint();
}

function paint() {
  ground();
  upperAir();
  veils();
  coolFlanks();
  darkBreath();
  sharedEarth();
  spill();
  presence(-1);
  presence(1);
  rootBraid();
  reaches(-1);
  reaches(1);
  thirdWarmth();
  filaments();
  risingBreath();
  impasto(-1);
  impasto(1);
  embers();
  motes();
  vignette();
  grain();
}

function ground() {
  background(8, 5, 12);
  noFill();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let n = noise(y * 0.0037, 0.4);
    let r = lerp(16, 6, t) + n * 7;
    let g = lerp(9, 4, t) + n * 3;
    let b = lerp(24, 12, t) + n * 5;
    let warm = Math.exp(-Math.pow((t - 0.78) / 0.22, 2)) * 12;
    stroke(r + warm, g + warm * 0.28, b + warm * 0.05);
    line(0, y, width, y);
  }
}

function upperAir() {
  noStroke();
  for (let i = 12; i >= 1; i--) {
    fill(14, 20, 46, 6);
    ellipse(800, 80, 1700 * i / 12, 820 * i / 12);
  }
  for (let i = 8; i >= 1; i--) {
    fill(22, 18, 48, 5);
    ellipse(760, 260, 1200 * i / 8, 640 * i / 8);
  }
}

function veils() {
  noStroke();
  for (let i = 18; i >= 1; i--) {
    fill(42, 12, 24, 4);
    ellipse(800, 1180, 860 * i / 18 + 80, 1280 * i / 18);
  }
  for (let i = 14; i >= 1; i--) {
    fill(28, 14, 40, 4);
    ellipse(820, 620, 980 * i / 14, 760 * i / 14);
  }
}

function coolFlanks() {
  noStroke();
  for (let i = 8; i >= 1; i--) {
    fill(8, 14, 34, 7);
    ellipse(150, 980, 560 * i / 8, 1500 * i / 8);
    ellipse(1460, 1020, 580 * i / 8, 1560 * i / 8);
  }
}

function darkBreath() {
  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(height);
    let dx = (x - 810) / 460;
    let dy = (y - 1000) / 640;
    if (dx * dx + dy * dy < 1.05) continue;
    let ang = noise(x * 0.0014, y * 0.0014) * Math.PI * 2;
    let len = random(18, 76);
    if (y < 860) stroke(24, 28, 52, random(7, 16));
    else stroke(40, 16, 24, random(7, 15));
    strokeWeight(random(0.7, 2.3));
    line(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len);
  }
}

function sharedEarth() {
  noStroke();
  for (let i = 10; i >= 1; i--) {
    fill(32, 9, 14, 8);
    ellipse(800, 1920, 1560 * i / 10, 460 * i / 10);
  }
  for (let i = 8; i >= 1; i--) {
    fill(78, 24, 20, 6);
    ellipse(830, 1765, 1040 * i / 8, 280 * i / 8);
  }
  for (let i = 5; i >= 1; i--) {
    fill(128, 42, 28, 5);
    ellipse(800, 1690, 560 * i / 5, 140 * i / 5);
  }
}

function spill() {
  let c = holdingCenter();
  noStroke();
  for (let i = 9; i >= 1; i--) {
    fill(110, 42, 24, 4);
    ellipse(c.x, c.y + 10, 980 * i / 9, 300 * i / 9);
  }
}

function presence(side) {
  bodyShadow(side);
  bodyBed(side);
  bodyVolume(side);
  bodyCore(side);
  bodyRim(side);
  knifeMarks(side);
  nucleus(side, side < 0 ? 0.5 : 0.52);
}

function bodyShadow(side) {
  noStroke();
  for (let i = 0; i < 36; i++) {
    let t = random(0.06, 0.94);
    let p = spineSmooth(side, t);
    let n = inwardNormal(side, spineAngle(side, t));
    let g = girth(side, t);
    fill(5, 2, 8, 13);
    ellipse(p.x - n.x * (g * 0.85 + 18), p.y + 18, g * 1.5, g * 2.1);
  }
}

function bodyBed(side) {
  noStroke();
  for (let i = 0; i <= 30; i++) {
    let t = i / 30;
    let p = spineSmooth(side, t);
    let g = girth(side, t);
    let col = bodyColor(side, t, 0.35);
    fill(col[0], col[1], col[2], 8);
    ellipse(p.x, p.y, g * 2.3, g * 2.8);
    fill(col[0], col[1], col[2], 11);
    ellipse(p.x, p.y, g * 1.35, g * 1.8);
  }
}

function bodyVolume(side) {
  let stations = 120;
  for (let i = 0; i < stations; i++) {
    let t = i / (stations - 1);
    let p = spine(side, t);
    let ang = spineAngle(side, t);
    let n = inwardNormal(side, ang);
    let g = girth(side, t);
    for (let k = 0; k < 14; k++) {
      let s0 = random(-1, 1);
      let s = (s0 < 0 ? -1 : 1) * Math.pow(Math.abs(s0), 0.58);
      let x = p.x + n.x * s * g * random(0.88, 1.02) + random(-5, 5);
      let y = p.y + n.y * s * g * random(0.88, 1.02) + random(-5, 5);
      let col = bodyColor(side, t, s);
      if (random() < 0.12) {
        let other = side < 0 ? [176, 58, 68] : [206, 132, 52];
        col = lerpArr(col, other, 0.32);
      }
      col = jitterCol(col, 11);
      let edge = Math.abs(s);
      let a = lerp(50, 9, edge);
      a *= lerp(0.72, 1.18, Math.exp(-Math.pow((t - 0.5) / 0.26, 2)));
      let along = random() < 0.72;
      let w = along ? random(18, 52) : random(10, 26);
      let h = along ? random(3.2, 8.5) : random(8, 18);
      let rot = ang + (along ? random(-0.28, 0.28) : random(-1.1, 1.1));
      dab(x, y, w, h, rot, col, a);
    }
  }
}

function bodyCore(side) {
  for (let i = 0; i < 56; i++) {
    let t = random() < 0.62 ? 0.5 + random(-0.14, 0.14) : random(0.08, 0.92);
    t = constrain(t, 0.05, 0.95);
    let p = spine(side, t);
    let n = inwardNormal(side, spineAngle(side, t));
    let s = random(-0.15, 0.5);
    let g = girth(side, t);
    let x = p.x + n.x * s * g;
    let y = p.y + n.y * s * g;
    let col = bodyColor(side, t, s + 0.15);
    col = lerpArr(col, [255, 244, 232], 0.1);
    dab(x, y, random(12, 30), random(8, 20), random(Math.PI * 2), col, random(58, 98));
  }
}

function bodyRim(side) {
  for (let i = 0; i < 64; i++) {
    let t = random(0.08, 0.92);
    let p = spineSmooth(side, t);
    let ang = spineAngle(side, t);
    let n = inwardNormal(side, ang);
    let g = girth(side, t);
    let x = p.x - n.x * g * random(0.82, 1.05);
    let y = p.y - n.y * g * random(0.82, 1.05);
    dab(x, y, random(10, 28), random(2.4, 5.5), ang + random(-0.4, 0.4), [78, 74, 108], random(16, 34));
    dab(x + n.x * 7, y + n.y * 7, random(8, 18), random(2, 4), ang, [24, 10, 16], random(20, 40));
  }
}

function knifeMarks(side) {
  for (let i = 0; i < 11; i++) {
    let t = random(0.14, 0.86);
    let p = spine(side, t);
    let ang = spineAngle(side, t);
    let n = inwardNormal(side, ang);
    let s = random(-0.2, 0.65);
    let g = girth(side, t);
    let col = bodyColor(side, t, s);
    col = lerpArr(col, [255, 228, 206], 0.22);
    dab(
      p.x + n.x * s * g,
      p.y + n.y * s * g,
      random(34, 78),
      random(6, 13),
      ang + random(-0.55, 0.55),
      col,
      random(24, 42)
    );
  }
}

function nucleus(side, t) {
  let p = spineSmooth(side, t);
  let n = inwardNormal(side, spineAngle(side, t));
  let deep = side < 0 ? [168, 78, 16] : [150, 32, 46];
  let hot = side < 0 ? [255, 228, 188] : [255, 212, 202];
  dab(p.x - n.x * 6, p.y + 4, 36, 48, -Math.PI / 2 + (side < 0 ? -0.18 : 0.14), deep, 60);
  dab(p.x + n.x * 9, p.y - 2, 22, 28, random(-0.35, 0.35), hot, 82);
  softGlow(p.x, p.y, 62, 255, side < 0 ? 150 : 72, side < 0 ? 48 : 58, 10);
}

function rootBraid() {
  for (let i = 0; i < 16; i++) {
    let from = random() < 0.5 ? -1 : 1;
    let t0 = random(0.02, 0.26);
    let t1 = constrain(t0 + random(0.04, 0.12), 0.04, 0.34);
    let a = spineSmooth(from, t0);
    let b = spineSmooth(-from, t1);
    let na = inwardNormal(from, spineAngle(from, t0));
    let nb = inwardNormal(-from, spineAngle(-from, t1));
    let x1 = a.x + na.x * girth(from, t0) * 0.25;
    let y1 = a.y + na.y * girth(from, t0) * 0.2;
    let x2 = b.x + nb.x * girth(-from, t1) * 0.25;
    let y2 = b.y + nb.y * girth(-from, t1) * 0.2;
    let mx = (x1 + x2) / 2 + random(-24, 24);
    let my = (y1 + y2) / 2 + random(-18, 16);
    let col = from < 0 ? [124, 52, 32] : [112, 36, 52];
    if (random() < 0.3) col = lerpArr(col, [186, 96, 62], 0.45);
    noFill();
    for (let pass = 0; pass < 2; pass++) {
      stroke(col[0], col[1], col[2], 18);
      strokeWeight(random(1.4, 3.4));
      beginShape();
      for (let s = 0; s <= 16; s++) {
        let u = s / 16;
        let pt = qpoint(x1, y1, mx, my, x2, y2, u);
        vertex(pt.x, pt.y);
      }
      endShape();
    }
  }
}

function reaches(side) {
  let ts = [0.42, 0.47, 0.51, 0.56, 0.61];
  for (let i = 0; i < ts.length; i++) {
    let t = ts[i] + (side < 0 ? -0.01 : 0.012);
    let p = spineSmooth(side, t);
    let ang = spineAngle(side, t);
    let n = inwardNormal(side, ang);
    let g = girth(side, t);
    let x1 = p.x + n.x * g * 0.32;
    let y1 = p.y + n.y * g * 0.32;
    let len = 36 + i * 6;
    let x2 = x1 + n.x * len;
    let y2 = y1 + n.y * len - side * 6;
    let col = side < 0 ? [255, 208, 158] : [255, 188, 178];
    noFill();
    for (let pass = 3; pass >= 1; pass--) {
      stroke(col[0], col[1], col[2], 5 * pass);
      strokeWeight(pass * 0.75);
      beginShape();
      for (let s = 0; s <= 10; s++) {
        let u = s / 10;
        vertex(
          lerp(x1, x2, u),
          lerp(y1, y2, u) + Math.sin(u * Math.PI) * (side < 0 ? -7 : 7)
        );
      }
      endShape();
    }
  }
}

function thirdWarmth() {
  for (let i = 0; i <= 34; i++) {
    let t = lerp(0.36, 0.64, i / 34);
    let L = spineSmooth(-1, t);
    let R = spineSmooth(1, t);
    let mx = (L.x + R.x) / 2;
    let my = (L.y + R.y) / 2;
    let span = dist(L.x, L.y, R.x, R.y);
    let near = constrain(1.2 - span / 300, 0, 1);
    let wob = random(-0.35, 0.35);
    dab(mx, my, 58 * near + 8, 20, wob, [255, 204, 166], 30 * near);
    dab(mx + random(-6, 6), my + random(-5, 5), 26 * near + 4, 12, wob, [255, 236, 216], 38 * near);
  }
  let c = holdingCenter();
  for (let i = 0; i < 6; i++) {
    dab(
      c.x + random(-22, 22),
      c.y + random(-28, 28),
      random(70, 130),
      random(14, 26),
      random(-0.7, 0.7),
      [255, 198, 158],
      8
    );
  }
  softGlow(c.x - 8, c.y - 14, 86, 255, 186, 120, 18);
  softGlow(c.x - 4, c.y - 10, 28, 255, 236, 214, 12);
  dab(c.x + 14, c.y + 6, 16, 11, 0.5, [146, 196, 190], 34);
}

function filaments() {
  let ts = [0.37, 0.42, 0.47, 0.505, 0.55, 0.6, 0.66, 0.73];
  let sags = [-16, 12, -28, 2, -10, 18, -34, 6];
  for (let i = 0; i < ts.length; i++) filament(ts[i], sags[i]);
}

function filament(t, sag) {
  let L = spineSmooth(-1, t);
  let R = spineSmooth(1, t);
  let nL = inwardNormal(-1, spineAngle(-1, t));
  let nR = inwardNormal(1, spineAngle(1, t));
  let x1 = L.x + nL.x * girth(-1, t) * 0.5;
  let y1 = L.y + nL.y * girth(-1, t) * 0.4;
  let x2 = R.x + nR.x * girth(1, t) * 0.5;
  let y2 = R.y + nR.y * girth(1, t) * 0.4;
  let span = dist(L.x, L.y, R.x, R.y);
  let fade = constrain(1.35 - span / 390, 0.04, 1);
  let cx = (x1 + x2) / 2 + random(-10, 10);
  let cy = (y1 + y2) / 2 + sag;
  noFill();
  for (let pass = 3; pass >= 1; pass--) {
    for (let i = 0; i < 26; i++) {
      let u0 = i / 26;
      let u1 = (i + 1) / 26;
      let a = qpoint(x1, y1, cx, cy, x2, y2, u0);
      let b = qpoint(x1, y1, cx, cy, x2, y2, u1);
      let col = lerpArr([255, 214, 150], [255, 188, 182], u0);
      stroke(col[0], col[1], col[2], 6 * pass * fade);
      strokeWeight(pass * 0.65);
      line(a.x, a.y, b.x, b.y);
    }
  }
}

function risingBreath() {
  let c = holdingCenter();
  for (let pth = 0; pth < 4; pth++) {
    let x = c.x + (pth - 1.5) * 18;
    let y = c.y - 10;
    for (let i = 0; i < 70; i++) {
      let nx = x + (noise(i * 0.12, pth * 3.7) - 0.5) * 34;
      let ny = y - random(6, 11);
      if (ny < 150) break;
      let a = lerp(13, 0, i / 70) * (pth === 1 || pth === 2 ? 1 : 0.55);
      stroke(255, 214, 182, a);
      strokeWeight(lerp(2.6, 0.4, i / 70));
      line(x, y, nx, ny);
      x = nx;
      y = ny;
    }
  }
}

function impasto(side) {
  for (let k = 0; k < 9; k++) {
    let t = 0.5 + random(-0.07, 0.09);
    let p = spineSmooth(side, t);
    let n = inwardNormal(side, spineAngle(side, t));
    let s = random(0.12, 0.58);
    let g = girth(side, t);
    let col = random() < 0.45 ? [255, 242, 224] : [255, 220, 176];
    dab(
      p.x + n.x * g * s,
      p.y + n.y * g * s,
      random(16, 34),
      random(3.5, 7),
      random(-0.8, 0.8),
      col,
      random(42, 76)
    );
  }
}

function embers() {
  noStroke();
  for (let i = 0; i < 28; i++) {
    fill(255, random(96, 150), 42, random(14, 38));
    ellipse(random(600, 1040), random(1640, 1930), random(3, 8), random(2, 5));
  }
}

function motes() {
  noStroke();
  for (let i = 0; i < 150; i++) {
    let u = Math.pow(random(), 0.62);
    let y = lerp(1080, 150, u);
    let spread = lerp(40, 230, u);
    let x = 790 + random(-spread, spread) + lerp(10, -50, u);
    let a = random(18, 86) * lerp(1, 0.35, u);
    let hot = random() < 0.7;
    if (hot) fill(255, random(190, 230), random(150, 200), a);
    else fill(255, random(170, 200), random(180, 200), a * 0.8);
    let s = random() < 0.25 ? random(5, 11) : random(1.5, 3.6);
    ellipse(x, y, s, s * random(0.7, 1.3));
  }
  for (let i = 0; i < 36; i++) {
    fill(255, random(140, 190), 120, random(10, 28));
    ellipse(random(640, 1000), random(1280, 1600), random(2, 5), random(2, 4));
  }
}

function vignette() {
  noStroke();
  for (let i = 6; i >= 1; i--) {
    fill(5, 3, 10, 9);
    ellipse(800, 0, 1900 * i / 6, 520 * i / 6);
  }
  let corners = [
    [0, 0],
    [width, 0],
    [0, height],
    [width, height]
  ];
  for (let c = 0; c < corners.length; c++) {
    for (let i = 10; i >= 1; i--) {
      fill(4, 2, 8, 9);
      ellipse(corners[c][0], corners[c][1], 1040 * i / 10, 1280 * i / 10);
    }
  }
  for (let i = 0; i < 2600; i++) {
    let x = random(width);
    let y = random(height);
    let dx = Math.abs(x - width / 2) / (width / 2);
    let dy = Math.abs(y - height / 2) / (height / 2);
    let v = Math.pow(Math.min(1, Math.max(dx * 0.9, dy * 0.72)), 1.7);
    if (random() > v * 0.9) continue;
    fill(5, 2, 9, 15 * v);
    ellipse(x, y, random(48, 150), random(36, 120));
  }
}

function grain() {
  for (let i = 0; i < 18000; i++) {
    let v = random(30, 255);
    stroke(v, random(4, 13));
    point(random(width), random(height));
  }
  noStroke();
  for (let i = 0; i < 1800; i++) {
    if (random() < 0.5) fill(255, random(170, 220), random(130, 180), random(3, 9));
    else fill(random(130, 180), random(140, 190), 255, random(3, 8));
    ellipse(random(width), random(height), random(1, 2.2), random(1, 2.2));
  }
}

function spineSmooth(side, t) {
  t = constrain(t, 0, 1);
  let x;
  let y;
  if (side < 0) {
    x = keyLerp([0, 0.2, 0.5, 0.75, 1], [620, 490, 705, 655, 595], t);
    y = keyLerp([0, 0.2, 0.5, 0.75, 1], [1860, 1500, 940, 500, 180], t);
  } else {
    x = keyLerp([0, 0.18, 0.52, 0.78, 1], [990, 1140, 905, 985, 1045], t);
    y = keyLerp([0, 0.18, 0.52, 0.78, 1], [1880, 1560, 990, 560, 210], t);
  }
  return { x: x, y: y };
}

function spine(side, t) {
  let p = spineSmooth(side, t);
  p.x += (noise(t * 1.7, side * 4.2 + 1.7) - 0.5) * 32;
  p.y += (noise(t * 1.25 + 8.0, side * 6.4) - 0.5) * 18;
  return p;
}

function spineAngle(side, t) {
  let dt = 0.01;
  let a = spineSmooth(side, Math.max(0, t - dt));
  let b = spineSmooth(side, Math.min(1, t + dt));
  return Math.atan2(b.y - a.y, b.x - a.x);
}

function girth(side, t) {
  let g = 18;
  g += 88 * Math.pow(1 - t, 1.65);
  g += 56 * Math.exp(-Math.pow((t - 0.5) / 0.14, 2));
  g += 22 * Math.exp(-Math.pow((t - 0.68) / 0.09, 2));
  g += 14 * Math.exp(-Math.pow((t - 0.14) / 0.1, 2));
  if (side > 0) g *= 0.94;
  return g;
}

function inwardNormal(side, ang) {
  let dx = Math.cos(ang);
  let dy = Math.sin(ang);
  let px = -dy;
  let py = dx;
  if (side > 0) {
    px = -px;
    py = -py;
  }
  let hx = side < 0 ? 1 : -1;
  let nx = px * 0.3 + hx * 0.7;
  let ny = py * 0.3;
  let len = Math.sqrt(nx * nx + ny * ny) || 1;
  return { x: nx / len, y: ny / len };
}

function bodyColor(side, t, s) {
  let root;
  let heart;
  let crown;
  let shadow;
  let lit;
  if (side < 0) {
    root = [70, 24, 12];
    heart = [240, 164, 48];
    crown = [255, 220, 180];
    shadow = [30, 11, 14];
    lit = [255, 226, 176];
  } else {
    root = [64, 14, 28];
    heart = [214, 64, 82];
    crown = [255, 200, 196];
    shadow = [24, 9, 20];
    lit = [255, 206, 196];
  }
  let along = t < 0.5
    ? lerpArr(root, heart, smoothstep(t / 0.5))
    : lerpArr(heart, crown, smoothstep((t - 0.5) / 0.5));
  let lightK = constrain((s + 0.85) / 1.5, 0, 1);
  lightK = Math.pow(lightK, 1.35);
  let col = lerpArr(shadow, along, 0.22 + 0.78 * lightK);
  if (s > 0.02 && t > 0.26 && t < 0.74) {
    let k = constrain((s - 0.02) / 0.72, 0, 1);
    k *= Math.exp(-Math.pow((t - 0.5) / 0.2, 2));
    col = lerpArr(col, lit, k * 0.7);
  }
  return col;
}

function holdingCenter() {
  let L = spineSmooth(-1, 0.5);
  let R = spineSmooth(1, 0.5);
  return { x: (L.x + R.x) / 2, y: (L.y + R.y) / 2 };
}

function dab(x, y, w, h, rot, col, a) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(col[0], col[1], col[2], a);
  ellipse(0, 0, Math.max(0.4, w), Math.max(0.4, h));
  pop();
}

function softGlow(x, y, r, cr, cg, cb, strength) {
  blendMode(ADD);
  noStroke();
  let layers = 16;
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    fill(cr, cg, cb, strength * t * t);
    ellipse(x, y, r * 2 * t, r * 2 * t);
  }
  blendMode(BLEND);
}

function keyLerp(ts, vs, t) {
  let n = ts.length;
  if (t <= ts[0]) return vs[0];
  if (t >= ts[n - 1]) return vs[n - 1];
  let i = 0;
  while (i < n - 2 && t > ts[i + 1]) i++;
  let u = (t - ts[i]) / (ts[i + 1] - ts[i]);
  u = (1 - Math.cos(u * Math.PI)) / 2;
  return lerp(vs[i], vs[i + 1], u);
}

function lerpArr(a, b, t) {
  return [
    lerp(a[0], b[0], t),
    lerp(a[1], b[1], t),
    lerp(a[2], b[2], t)
  ];
}

function smoothstep(u) {
  u = constrain(u, 0, 1);
  return u * u * (3 - 2 * u);
}

function qpoint(x1, y1, cx, cy, x2, y2, u) {
  return {
    x: lerp(lerp(x1, cx, u), lerp(cx, x2, u), u),
    y: lerp(lerp(y1, cy, u), lerp(cy, y2, u), u)
  };
}

function jitterCol(col, amt) {
  return [
    constrain(col[0] + random(-amt, amt), 0, 255),
    constrain(col[1] + random(-amt, amt), 0, 255),
    constrain(col[2] + random(-amt * 0.55, amt * 0.7), 0, 255)
  ];
}

function setup() {
  pixelDensity(1);
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255, 255, 255, 255);
  ellipseMode(CENTER);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  paint();
}

function paint() {
  const earthA = [
    { x: 260, y: 1980 },
    { x: 310, y: 1740 },
    { x: 370, y: 1520 },
    { x: 450, y: 1320 },
    { x: 540, y: 1160 },
    { x: 640, y: 1040 },
    { x: 740, y: 960 },
    { x: 830, y: 910 }
  ];
  const earthR = [250, 215, 175, 140, 105, 68, 36, 15];
  const skyA = [
    { x: 1420, y: 20 },
    { x: 1360, y: 220 },
    { x: 1260, y: 440 },
    { x: 1160, y: 650 },
    { x: 1080, y: 840 },
    { x: 1130, y: 1040 },
    { x: 1190, y: 1260 },
    { x: 1230, y: 1500 },
    { x: 1200, y: 1720 },
    { x: 1160, y: 1940 }
  ];
  const skyR = [58, 88, 125, 165, 120, 145, 125, 92, 58, 36];
  const earthT = [
    { x: 560, y: 1120 },
    { x: 680, y: 1040 },
    { x: 800, y: 970 },
    { x: 900, y: 935 }
  ];
  const earthTR = [52, 34, 20, 9];
  const skyT = [
    { x: 1100, y: 760 },
    { x: 1040, y: 830 },
    { x: 990, y: 890 },
    { x: 950, y: 925 }
  ];
  const skyTR = [46, 30, 18, 8];

  const earthStops = [
    { t: 0.0, r: 92, g: 28, b: 40 },
    { t: 0.35, r: 158, g: 42, b: 62 },
    { t: 0.68, r: 206, g: 86, b: 90 },
    { t: 1.0, r: 246, g: 176, b: 162 }
  ];
  const skyStops = [
    { t: 0.0, r: 255, g: 228, b: 186 },
    { t: 0.32, r: 236, g: 176, b: 78 },
    { t: 0.66, r: 214, g: 128, b: 46 },
    { t: 1.0, r: 244, g: 196, b: 140 }
  ];

  paintBackground();
  paintAtmosphere();
  paintGround();

  sweep(earthA, earthR, 2.2, 36, 46, 18, 26, 7, 2.6);
  sweep(skyA, skyR, 8.6, 30, 36, 22, 58, 6, 2.3);

  paintForm(earthA, earthR, earthStops, {
