    vr: 72, vg: 18, vb: 30, veinA: 15,
    rimA: 10, lightA: 9
  });
  paintForm(skyA, skyR, skyStops, {
    seed: 8.6, wob: 30, steps: 86, stretch: 1.85,
    ur: 42, ug: 24, ub: 62, underA: 11,
    bodyA: 8, coreA: 14,
    vr: 118, vg: 72, vb: 32, veinA: 11,
