  });

  notchOuter(earthA, earthR, 2.2, 36, -1);
  notchOuter(skyA, skyR, 8.6, 30, 1);

  paintForm(earthT, earthTR, earthStops, {
    seed: 4.4, wob: 10, steps: 32, stretch: 1.7,
    ur: 70, ug: 28, ub: 36, underA: 8,
    bodyA: 14, coreA: 18,
    vr: 90, vg: 30, vb: 40, veinA: 8,
