    vr: 130, vg: 84, vb: 40, veinA: 7,
    rimA: 5, lightA: 14
  });

  facingPetals(earthA, earthR, 2.2, 36, 1, 244, 186, 174);
  facingPetals(skyA, skyR, 8.6, 30, -1, 255, 220, 168);

  const eTip = along(earthT, earthTR, 1, 4.4, 10);
  const sTip = along(skyT, skyTR, 1, 12.8, 10);
  const mx = (eTip.x + sTip.x) / 2;
  const my = (eTip.y + sTip.y) / 2;

