  paintFilaments(earthA, earthR, skyA, skyR, earthT, earthTR, skyT, skyTR);
  paintCore(mx, my);
  paintTipSparks(eTip, sTip);
  fallenPetals();
  risingEmbers(mx, my);
  paintMotes(mx, my);
  paintGrain();
