function paintBackground() {
  background(8, 7, 16);
  noStroke();
  for (let y = 0; y < height; y += 4) {
    const t = y / height;
    const base = bgAt(t);
    for (let x = 0; x < width; x += 48) {
      const n = noise(x * 0.0018, y * 0.0022);
      const n2 = noise(x * 0.006 + 3, y * 0.005, 4);
      const dx = (x - 920) / 860;
      const dy = (y - 930) / 1000;
      const warm = Math.exp(-(dx * dx * 1.35 + dy * dy * 0.85));
      fill(
        base.r + (n - 0.5) * 20 + (n2 - 0.5) * 8 + warm * 62,
        base.g + (n - 0.5) * 12 + warm * 24,
        base.b + (n - 0.5) * 16 + warm * 12
      );
      rect(x, y, 48, 4);
    }
  }
}

function bgAt(t) {
  if (t < 0.4) {
    const u = t / 0.4;
    return { r: lerp(11, 44, u), g: lerp(13, 24, u), b: lerp(34, 56, u) };
  } else if (t < 0.68) {
    const u = (t - 0.4) / 0.28;
    return { r: lerp(44, 26, u), g: lerp(24, 13, u), b: lerp(56, 30, u) };
  }
  const u = (t - 0.68) / 0.32;
  return { r: lerp(26, 14, u), g: lerp(13, 7, u), b: lerp(30, 11, u) };
}

function paintAtmosphere() {
  dab(260, 320, 460, 0.2, 18, 26, 72, 7, 5, 1.15);
  dab(180, 180, 280, 0, 14, 16, 48, 9, 4, 1);
  dab(1480, 160, 320, -0.4, 255, 196, 130, 5, 5, 1.6);
  dab(360, 1760, 520, 0.1, 86, 22, 34, 8, 5, 1.25);
  dab(900, 460, 640, 0, 32, 24, 58, 5, 4, 2.8);
  for (let i = 0; i < 16; i++) {
    const t = i / 15;
    const x = lerp(1520, 1120, t) + (noise(t * 2, 21) - 0.5) * 26;
    const y = lerp(-20, 620, t);
    dab(x, y, lerp(200, 70, t), -0.7, 255, 198, 140, 4.5, 4, 2.6);
  }
}

function paintGround() {
  noStroke();
  for (let y = 1560; y < height; y += 5) {
    const depth = constrain((y - 1560) / 440, 0, 1);
    const feather = constrain((y - 1500) / 90, 0, 1);
    for (let x = 0; x < width; x += 36) {
      const u = x / width;
      const n = noise(x * 0.012, y * 0.01);
      let r = lerp(78, 118, u);
      let g = lerp(26, 68, u);
      let b = lerp(30, 26, u);
      r = r * (1 - depth * 0.62) + n * 12;
      g = g * (1 - depth * 0.55) + n * 8;
      b = b * (1 - depth * 0.5) + n * 6;
      fill(r, g, b, 210 * feather);
      rect(x, y, 36, 5);
    }
  }
  for (let i = 0; i < 10; i++) {
    const y = 1588 + i * 18;
    dab(860, y, 280 - i * 8, 0, 196, 118, 78, 5, 3, 3.4);
  }
  dab(780, 1680, 220, 0.05, 140, 48, 52, 6, 4, 2.2);
  dab(1080, 1700, 200, -0.05, 170, 110, 48, 6, 4, 2.2);
}

function sweep(anchors, radii, seed, wob, cr, cg, cb, ca, stretch) {
  for (let i = 0; i <= 42; i++) {
    const t = i / 42;
    const p = along(anchors, radii, t, seed, wob);
    dab(p.x, p.y, p.r * 1.35, p.ang, cr, cg, cb, ca, 4, stretch);
  }
}

function paintForm(anchors, radii, stops, o) {
  for (let i = 0; i <= o.steps; i++) {
    const t = i / o.steps;
    const p = along(anchors, radii, t, o.seed, o.wob);
    dab(p.x + 16, p.y + 22, p.r * 1.05, p.ang, o.ur, o.ug, o.ub, o.underA, 5, o.stretch);
  }
  for (let i = 0; i <= o.steps; i++) {
    const t = i / o.steps;
    const p = along(anchors, radii, t, o.seed, o.wob);
    const c = colorAt(stops, t);
    const drift = (noise(t * 5.5, o.seed + 2) - 0.5) * 20;
    const stretch = o.stretch * (0.82 + noise(t * 3.3, o.seed + 7) * 0.42);
    dab(p.x, p.y, p.r, p.ang + drift * 0.003, c.r + drift * 0.45, c.g + drift * 0.2, c.b, o.bodyA, 5, stretch);
  }
  for (let i = 0; i <= o.steps; i++) {
    const t = i / o.steps;
    const p = along(anchors, radii, t, o.seed, o.wob);
    const c = colorAt(stops, t);
    dab(
      p.x - 4, p.y - 3, p.r * 0.62, p.ang,
      min(255, c.r + 14), min(255, c.g + 6), min(255, c.b + 2),
      o.coreA, 4, o.stretch * 0.82
    );
  }
  for (let i = 0; i <= o.steps; i += 1) {
    const t = i / o.steps;
    const p = along(anchors, radii, t, o.seed, o.wob);
    dab(p.x + 5, p.y + 7, max(2, p.r * 0.16), p.ang, o.vr, o.vg, o.vb, o.veinA, 3, 2.5);
  }
  for (let i = 0; i <= o.steps; i += 2) {
    const t = i / o.steps;
    const p = along(anchors, radii, t, o.seed, o.wob);
    dab(p.x + p.r * 0.34, p.y + p.r * 0.4, p.r * 0.26, p.ang, 92, 78, 148, o.rimA, 3, 1.7);
  }
  for (let i = 0; i <= o.steps; i++) {
    const t = i / o.steps;
    const p = along(anchors, radii, t, o.seed, o.wob);
    const c = colorAt(stops, t);
    dab(
      p.x - p.r * 0.22, p.y - p.r * 0.28, p.r * 0.36, p.ang,
      min(255, c.r + 52), min(255, c.g + 40), min(255, c.b + 30),
      o.lightA, 4, o.stretch * 0.72
    );
  }
  for (let i = 0; i <= o.steps; i += 4) {
    const t = i / o.steps;
    const p = along(anchors, radii, t, o.seed, o.wob);
    const c = colorAt(stops, t);
    dab(p.x, p.y, p.r * 1.12, p.ang, c.r, c.g, c.b, 5, 3, 1.35);
  }
}

function notchOuter(anchors, radii, seed, wob, sign) {
  for (let k = 0; k < 6; k++) {
    const t = 0.12 + k * 0.12;
    const p = along(anchors, radii, t, seed, wob);
    const n = noise(t * 9.0, seed + 19);
    dab(
      p.x + sign * p.r * 0.74,
      p.y + (n - 0.5) * 16,
      p.r * (0.16 + n * 0.18),
      p.ang,
      8, 6, 16, 30, 3, 1.35
    );
  }
}

function facingPetals(anchors, radii, seed, wob, toward, cr, cg, cb) {
  for (let k = 0; k < 5; k++) {
    const t = 0.48 + k * 0.08;
    const p = along(anchors, radii, t, seed, wob);
    const n = noise(t * 7.0, seed + 15);
    const x = p.x + toward * p.r * (0.62 + n * 0.18);
    const y = p.y - 6 + n * 14;
    const len = 16 + n * 26;
    const wid = 6 + noise(t * 6.0, seed + 16) * 9;
    const ang = toward > 0 ? -0.45 + n * 0.5 : Math.PI + 0.15 - n * 0.45;
    petal(x, y, ang, len, wid, cr, cg, cb, 16 + n * 10);
  }
}

function petal(x, y, ang, len, wid, cr, cg, cb, ca) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  for (let i = 6; i >= 1; i--) {
    const f = i / 6;
    fill(cr, cg, cb, ca * Math.pow(1 - f, 1.35));
    ellipse(0, 0, len * f, wid * f);
  }
  fill(min(255, cr + 24), min(255, cg + 18), min(255, cb + 12), ca * 0.45);
  ellipse(len * 0.06, 0, len * 0.28, wid * 0.28);
  pop();
}

function paintHalo(x, y) {
  for (let i = 0; i < 6; i++) {
    const jx = (noise(i, 40) - 0.5) * 18;
    const jy = (noise(i, 41) - 0.5) * 16;
    dab(x + jx, y + jy, 430 - i * 8, 0, 132, 42, 64, 6, 5, 1);
  }
  for (let i = 0; i < 5; i++) {
    const jx = (noise(i, 42) - 0.5) * 12;
    const jy = (noise(i, 43) - 0.5) * 12;
    dab(x + jx, y + jy + 8, 280, 0, 228, 150, 70, 7, 5, 1.05);
  }
  dab(x, y, 168, 0, 255, 206, 168, 10, 5, 1);
  dab(x - 4, y - 2, 96, 0, 255, 228, 206, 12, 4, 1);
}

function paintFilaments(earthA, earthR, skyA, skyR, earthT, earthTR, skyT, skyTR) {
  const mains = [
    { te: 0.58, ts: 0.42, reach: 0.46, bend: 42, ca: 22 },
    { te: 0.64, ts: 0.48, reach: 0.62, bend: -30, ca: 26 },
    { te: 0.7, ts: 0.4, reach: 1.0, bend: 18, ca: 34 },
    { te: 0.76, ts: 0.5, reach: 0.55, bend: -18, ca: 20 },
    { te: 0.82, ts: 0.46, reach: 0.72, bend: 26, ca: 24 },
    { te: 0.88, ts: 0.38, reach: 1.0, bend: -12, ca: 30 },
    { te: 0.6, ts: 0.55, reach: 0.4, bend: 16, ca: 16 },
    { te: 0.73, ts: 0.52, reach: 0.84, bend: -36, ca: 22 }
  ];
  for (let k = 0; k < mains.length; k++) {
    const L = mains[k];
    const e = along(earthA, earthR, L.te, 2.2, 36);
    const s = along(skyA, skyR, L.ts, 8.6, 30);
    e.x += e.r * 0.48;
    s.x -= s.r * 0.42;
    thread(e.x, e.y, s.x, s.y, L.bend, L.reach, L.ca, k);
  }
  const tips = [
    { te: 0.72, ts: 0.7, reach: 0.8, bend: -14, ca: 36 },
    { te: 0.86, ts: 0.84, reach: 0.66, bend: 12, ca: 28 },
    { te: 1.0, ts: 1.0, reach: 1.0, bend: 6, ca: 48 }
  ];
  for (let k = 0; k < tips.length; k++) {
    const L = tips[k];
    const e = along(earthT, earthTR, L.te, 4.4, 10);
    const s = along(skyT, skyTR, L.ts, 12.8, 10);
    thread(e.x, e.y, s.x, s.y, L.bend, L.reach, L.ca, 20 + k);
  }
}

function thread(x1, y1, x2, y2, bend, reach, ca, seed) {
  const mx = (x1 + x2) / 2;
  const my = (y1 + y2) / 2;
  const ang = Math.atan2(y2 - y1, x2 - x1);
  const cx = mx + Math.cos(ang + HALF_PI) * bend;
  const cy = my + Math.sin(ang + HALF_PI) * bend;
  const steps = 34;
  const last = Math.floor(steps * reach);
  for (let i = 0; i <= last; i++) {
    const t = i / steps;
    const x = bez(x1, cx, x2, t);
    const y = bez(y1, cy, y2, t);
    const x2b = bez(x1, cx, x2, min(1, t + 0.025));
    const y2b = bez(y1, cy, y2, min(1, t + 0.025));
    const a = Math.atan2(y2b - y, x2b - x);
    const fade = 0.55 + 0.45 * Math.sin(t * Math.PI);
    const w = lerp(2.6, 0.7, t);
    dab(x, y, w, a, 255, 214, 176, ca * fade * 0.42, 3, 2.3);
  }
  const tx = bez(x1, cx, x2, reach);
  const ty = bez(y1, cy, y2, reach);
  if (reach < 0.97) {
    dab(tx, ty, 3.2 + noise(seed, 9), 0, 255, 236, 214, 70, 3, 1);
    dab(tx, ty, 7, 0, 255, 196, 140, 16, 3, 1);
  }
}

function paintCore(x, y) {
  dab(x, y, 54, 0, 255, 232, 210, 18, 4, 1);
  blendMode(ADD);
  dab(x, y, 28, 0, 255, 228, 198, 28, 4, 1);
  dab(x - 2, y - 2, 10, 0, 255, 248, 238, 36, 3, 1);
  blendMode(BLEND);
}

function paintTipSparks(eTip, sTip) {
  blendMode(ADD);
  dab(eTip.x, eTip.y, 7, 0, 255, 220, 200, 34, 3, 1);
  dab(sTip.x, sTip.y, 7, 0, 255, 230, 190, 34, 3, 1);
  dab(eTip.x - 1, eTip.y - 1, 2.4, 0, 255, 252, 246, 50, 2, 1);
  dab(sTip.x - 1, sTip.y - 1, 2.4, 0, 255, 252, 246, 50, 2, 1);
  blendMode(BLEND);
}

function fallenPetals() {
  for (let i = 0; i < 6; i++) {
    const x = lerp(620, 1120, noise(i, 31));
    const y = lerp(1660, 1930, noise(i, 32));
    const ang = noise(i, 33) * Math.PI;
    const rose = noise(i, 34) > 0.5;
    const len = 14 + noise(i, 35) * 18;
    const wid = 5 + noise(i, 36) * 6;
    if (rose) petal(x, y, ang, len, wid, 196, 92, 96, 18);
    else petal(x, y, ang, len, wid, 214, 156, 72, 16);
  }
}

function risingEmbers(x0, y0) {
  for (let i = 0; i < 18; i++) {
    const t = i / 17;
    const x = x0 + (noise(i, 50) - 0.5) * (24 + t * 90);
    const y = y0 - t * 380 - noise(i, 51) * 30;
    const rad = lerp(4.2, 1.1, t);
    dab(x, y, rad * 2.4, 0, 255, lerp(170, 210, t), lerp(100, 160, t), lerp(22, 6, t), 3, 1);
    dab(x, y, rad, 0, 255, 236, 214, lerp(40, 8, t), 2, 1);
  }
}

function paintMotes(x0, y0) {
  for (let i = 0; i < 52; i++) {
    const x = constrain(x0 + randomGaussian() * 150, 60, 1540);
    const y = constrain(y0 + randomGaussian() * 170, 80, 1500);
    const rad = random(1.1, 3.6);
    const g = random(186, 230);
    dab(x, y, rad * 3.2, 0, 255, g, random(120, 180), 14, 3, 1);
    dab(x, y, rad, 0, 255, 246, 232, random(40, 80), 2, 1);
  }
  for (let i = 0; i < 16; i++) {
    const x = random(80, 1520);
    const y = random(60, 700);
    if (dist(x, y, x0, y0) < 240) continue;
    dab(x, y, random(0.7, 1.8), 0, 255, 214, 170, random(16, 36), 2, 1);
  }
}

function paintGrain() {
  strokeWeight(1);
  for (let i = 0; i < 12000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.55) stroke(255, 236, 216, random(3, 10));
    else stroke(6, 4, 12, random(4, 13));
    point(x, y);
  }
  noStroke();
}

function paintVignette() {
  noStroke();
  for (let i = 0; i < 26; i++) {
    const a = map(i, 0, 25, 20, 0);
    fill(4, 3, 10, a);
    rect(0, i * 7, width, 7);
    rect(0, height - (i + 1) * 7, width, 7);
    rect(i * 6, 0, 6, height);
    rect(width - (i + 1) * 6, 0, 6, height);
  }
}

function along(anchors, radii, t, seed, wobAmp) {
  const n = anchors.length - 1;
  const ft = constrain(t, 0, 1) * n;
  const i = min(floor(ft), n - 1);
  const u = ft - i;
  const s = u * u * (3 - 2 * u);
  const a = anchors[i];
  const b = anchors[i + 1];
  const ang = Math.atan2(b.y - a.y, b.x - a.x);
  const wob = (noise(t * 3.2, seed) - 0.5) * wobAmp;
  const px = -Math.sin(ang);
  const py = Math.cos(ang);
  const nr = 0.9 + 0.2 * noise(t * 4.1, seed + 5);
  return {
    x: lerp(a.x, b.x, s) + px * wob,
    y: lerp(a.y, b.y, s) + py * wob,
    r: max(1.5, lerp(radii[i], radii[i + 1], s) * nr),
    ang: ang
  };
}

function colorAt(stops, t) {
  const t0 = constrain(t, 0, 1);
  let i = 0;
  while (i < stops.length - 2 && stops[i + 1].t < t0) i++;
  const a = stops[i];
  const b = stops[i + 1];
  const u = (t0 - a.t) / (b.t - a.t);
  return {
    r: lerp(a.r, b.r, u),
    g: lerp(a.g, b.g, u),
    b: lerp(a.b, b.b, u)
  };
}

function dab(x, y, rad, ang, cr, cg, cb, ca, n, stretch) {
  if (rad < 0.4 || ca < 0.15) return;
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  for (let i = n; i >= 1; i--) {
    const f = i / n;
    const a = ca * Math.pow(1 - f, 1.5);
    fill(
      constrain(cr, 0, 255),
      constrain(cg, 0, 255),
      constrain(cb, 0, 255),
      constrain(a, 0, 255)
    );
    ellipse(0, 0, rad * 2 * f * stretch, rad * 2 * f);
  }
  pop();
}

function bez(a, c, b, t) {
  const u = 1 - t;
  return u * u * a + 2 * u * t * c + t * t * b;
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  ellipseMode(CENTER);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  paint();
}

function paint() {
  background(12, 8, 18);
  wash();
  coolMist();
  warmField();
  hearth();

  let left = buildSpine(leftAnchors(), 1.7, 170);
  let right = buildSpine(rightAnchors(), 8.3, 170);

  halo(left, [168, 46, 70]);
  halo(right, [176, 98, 46]);
  presence(left, 0);
  presence(right, 1);
  flowLines(left, 0);
  flowLines(right, 1);
  innerLight(left, 0);
  innerLight(right, 1);
  privateCores(left, right);
  fallingLight();
  theBetween();
  threads(left, right);
  impasto(left, 0);
  impasto(right, 1);
  embers();
  motes();
  grain();
  vignette();
  jewels();
}

function leftAnchors() {
  return [
    { x: 600, y: 400 },
    { x: 545, y: 700 },
    { x: 625, y: 970 },
    { x: 675, y: 1175 },
    { x: 635, y: 1450 },
    { x: 590, y: 1730 }
  ];
}

function rightAnchors() {
  return [
    { x: 1060, y: 470 },
    { x: 1135, y: 750 },
    { x: 1020, y: 990 },
    { x: 945, y: 1195 },
    { x: 1010, y: 1470 },
    { x: 1070, y: 1750 }
  ];
}

function buildSpine(anchors, seed, steps) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let p = along(anchors, t);
    let jx = (noise(seed, t * 2.1) - 0.5) * 32;
    let jy = (noise(seed + 4, t * 1.7) - 0.5) * 14;
    pts.push({ x: p.x + jx, y: p.y + jy, t: t });
  }
  return pts;
}

function along(anchors, t) {
  let n = anchors.length - 1;
  let x = constrain(t, 0, 1) * n;
  let i = min(floor(x), n - 1);
  let u = x - i;
  u = u * u * (3 - 2 * u);
  return {
    x: lerp(anchors[i].x, anchors[i + 1].x, u),
    y: lerp(anchors[i].y, anchors[i + 1].y, u)
  };
}

function spineAt(pts, t) {
  let t2 = constrain(t, 0, 1);
  let x = t2 * (pts.length - 1);
  let i = min(floor(x), pts.length - 2);
  let u = x - i;
  return {
    x: lerp(pts[i].x, pts[i + 1].x, u),
    y: lerp(pts[i].y, pts[i + 1].y, u),
    t: t2
  };
}

function edgeFade(t) {
  if (t < 0.1) return t / 0.1;
  if (t > 0.9) return (1 - t) / 0.1;
  return 1;
}

function bodyRadius(t) {
  let bulk = pow(sin(t * PI), 0.72);
  let rad = lerp(22, 146, bulk);
  let d = (t - 0.58) * 5.4;
  let reach = Math.exp(-d * d);
  return rad * (1 - 0.42 * reach);
}

function wash() {
  let stops = [
    { t: 0.0, r: 12, g: 10, b: 28 },
    { t: 0.16, r: 32, g: 14, b: 44 },
    { t: 0.34, r: 52, g: 18, b: 42 },
    { t: 0.5, r: 78, g: 26, b: 44 },
    { t: 0.66, r: 104, g: 36, b: 40 },
    { t: 0.8, r: 70, g: 22, b: 30 },
    { t: 1.0, r: 14, g: 6, b: 12 }
  ];
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let i = 0;
    while (i < stops.length - 2 && t > stops[i + 1].t) i++;
    let a = stops[i];
    let b = stops[i + 1];
    let u = (t - a.t) / (b.t - a.t);
    let r = lerp(a.r, b.r, u) + (noise(y * 0.0035, 1.2) - 0.5) * 7;
    let g = lerp(a.g, b.g, u) + (noise(y * 0.0035, 2.4) - 0.5) * 4;
    let bl = lerp(a.b, b.b, u) + (noise(y * 0.0035, 3.6) - 0.5) * 5;
    for (let s = 0; s < 4; s++) {
      let x0 = (s * width) / 4;
      let x1 = ((s + 1) * width) / 4;
      let cx = (x0 + x1) / 2;
      let boost = (1 - abs(cx - 810) / 820) * 9;
      stroke(r + boost, g + boost * 0.32, bl + boost * 0.15);
      strokeWeight(2);
      line(x0, y, x1, y);
    }
  }
}

function coolMist() {
  noStroke();
  for (let i = 0; i < 20; i++) {
    fill(56, 50, 98, 3.5);
    ellipse(
      lerp(280, 1320, noise(i, 70)),
      lerp(30, 500, noise(i, 71)),
      lerp(260, 780, noise(i, 72)),
      lerp(70, 220, noise(i, 73))
    );
  }
}

function warmField() {
  noStroke();
  for (let i = 0; i < 22; i++) {
    let f = 1 - i / 22;
    fill(104, 30, 46, 2.4);
    ellipse(808 + (noise(i, 80) - 0.5) * 30, 1140, 720 * f + 240, 1180 * f + 180);
  }
}

function hearth() {
  noStroke();
  for (let i = 0; i < 16; i++) {
    fill(112, 32, 30, 4);
    ellipse(820 + (noise(i, 85) - 0.5) * 40, 1600, 1000 - i * 28, 300 - i * 8);
  }
}

function halo(pts, rgb) {
  noStroke();
  for (let i = 0; i < pts.length; i += 2) {
    let p = pts[i];
    let f = sin(p.t * PI);
    let rad = 64 + 210 * f;
    fill(rgb[0], rgb[1], rgb[2], 4.2 * f);
    ellipse(p.x, p.y, rad * 1.6, rad * 1.9);
  }
}

function presence(pts, kind) {
  for (let pass = 0; pass < 2; pass++) {
    let dabs = pass === 0 ? 5 : 8;
    for (let i = 0; i < pts.length; i++) {
      let p = pts[i];
      let fade = edgeFade(p.t);
      if (fade < 0.02) continue;
      let rad = bodyRadius(p.t);
      let i0 = max(0, i - 1);
      let i1 = min(pts.length - 1, i + 1);
      let ang = atan2(pts[i1].y - pts[i0].y, pts[i1].x - pts[i0].x);
      let px = cos(ang + HALF_PI);
      let py = sin(ang + HALF_PI);
      for (let k = 0; k < dabs; k++) {
        let across = (k / (dabs - 1)) * 2 - 1;
        let reach = rad * (pass === 0 ? 0.42 : 0.58);
        let x = p.x + px * across * reach;
        let y = p.y + py * across * reach * 0.8;
        if (pass === 0) {
          x += 12;
          y += 18;
        }
        x += (noise(p.t * 3.2, k, kind + 1) - 0.5) * 14;
        y += (noise(p.t * 2.6, k, kind + 6) - 0.5) * 10;
        let inward = 1 - constrain(abs(x - 810) / 470, 0, 1);
        let col;
        if (pass === 0) {
          col = color(36, 10, 20, 10 * fade);
        } else if (kind === 0) {
          let skin = lerpColor(color(84, 26, 46), color(216, 84, 100), inward);
          skin = lerpColor(skin, color(255, 198, 186), pow(inward, 1.35) * (1 - abs(across) * 0.5));
          if (inward < 0.2) skin = lerpColor(skin, color(74, 66, 122), 0.4);
          col = color(red(skin), green(skin), blue(skin), (9 + inward * 11) * fade);
        } else {
          let skin = lerpColor(color(90, 38, 32), color(204, 116, 60), inward);
          skin = lerpColor(skin, color(255, 214, 168), pow(inward, 1.35) * (1 - abs(across) * 0.45));
          if (inward < 0.2) skin = lerpColor(skin, color(68, 62, 118), 0.45);
          col = color(red(skin), green(skin), blue(skin), (9 + inward * 11) * fade);
        }
        noStroke();
        fill(col);
        push();
        translate(x, y);
        rotate(ang * 0.35 + (noise(k, p.t, kind + 2) - 0.5) * 1.1);
        let ew = rad * (kind === 0 ? 0.4 : 0.58) * (0.72 + noise(p.t, k, 11) * 0.5);
        let eh = rad * (kind === 0 ? 0.72 : 0.46) * (0.68 + noise(p.t, k, 12) * 0.5);
        ellipse(0, 0, ew, eh);
        pop();
      }
    }
  }
}

function flowLines(pts, kind) {
  noFill();
  for (let n = 0; n < 6; n++) {
    let offset = (noise(n * 1.3, kind + 2) - 0.5) * 40;
    stroke(255, 206, 184, kind === 0 ? 12 : 11);
    strokeWeight(0.7 + noise(n, kind) * 0.9);
    beginShape();
    for (let i = 8; i < pts.length - 8; i += 2) {
      let p = pts[i];
      let j = min(pts.length - 1, i + 1);
      let ang = atan2(pts[j].y - p.y, pts[j].x - p.x);
      vertex(
        p.x + cos(ang + HALF_PI) * offset,
        p.y + sin(ang + HALF_PI) * offset
      );
    }
    endShape();
  }
}

function innerLight(pts, kind) {
  noStroke();
  for (let i = 4; i < pts.length - 4; i += 2) {
    let p = pts[i];
    let fade = edgeFade(p.t) * sin(p.t * PI);
    let dir = 810 - p.x;
    let d = abs(dir) + 0.01;
    let x = p.x + (dir / d) * (26 + noise(i * 0.2, kind) * 16);
    let y = p.y + (noise(i * 0.15, 3) - 0.5) * 12;
    if (kind === 0) fill(255, 188, 172, 15 * fade);
    else fill(255, 206, 160, 14 * fade);
    ellipse(x, y, 26 + 18 * fade, 58 * fade + 8);
  }
}

function privateCores(left, right) {
  softGlow(spineAt(left, 0.38), 52, 255, 168, 158, 6, 8);
  softGlow(spineAt(right, 0.66), 58, 255, 188, 132, 6, 8);
}

function softGlow(p, r, cr, cg, cb, a, n) {
  noStroke();
  for (let i = n; i >= 1; i--) {
    let t = i / n;
    fill(cr, cg, cb, a * t);
    ellipse(
      p.x + (noise(i, p.x * 0.02) - 0.5) * 8,
      p.y + (noise(i, p.y * 0.02) - 0.5) * 8,
      r * 2 * t,
      r * 2.15 * t
    );
  }
}

function fallingLight() {
  noStroke();
  for (let i = 0; i < 20; i++) {
    let t = i / 19;
    fill(170, 78, 58, 5 * (1 - t * 0.65));
    ellipse(812 + sin(t * PI) * 8, lerp(1320, 1630, t), lerp(130, 54, t), 64);
  }
}

function theBetween() {
  noStroke();
  for (let i = 0; i < 34; i++) {
    let y = lerp(1000, 1360, noise(i * 0.2, 2));
    let x = 812 + (noise(i * 0.3, 3) - 0.5) * 46;
    fill(255, 198, 170, 5);
    ellipse(x, y, 70 + noise(i, 4) * 64, 110);
  }
  blendMode(ADD);
  for (let i = 0; i < 36; i++) {
    let y = lerp(1060, 1310, noise(i * 0.21, 6));
    let x = 814 + (noise(i * 0.25, 7) - 0.5) * 36;
    fill(255, 186, 140, 5);
    ellipse(x, y, 44 + noise(i, 8) * 52, 84);
  }
  for (let i = 0; i < 12; i++) {
    let x = 816 + (noise(i, 9) - 0.5) * 18;
    let y = 1184 + (noise(i, 10) - 0.5) * 30;
    fill(255, 236, 214, 7);
    ellipse(x, y, 18 + noise(i, 11) * 16, 26);
  }
  blendMode(BLEND);
}

function threads(left, right) {
  noFill();
  for (let n = 0; n < 8; n++) {
    let t = lerp(0.36, 0.7, noise(n * 0.85, 15));
    let a = spineAt(left, t);
    let b = spineAt(right, constrain(t + (noise(n, 16) - 0.5) * 0.03, 0, 1));
    let bow = (noise(n, 19) - 0.5) * 56;
    let ls = lerp(0.34, 0.44, noise(n, 17));
    stroke(214, 154, 118, lerp(26, 54, noise(n, 20)));
    thread(
      a.x + 16,
      a.y,
      lerp(a.x, b.x, ls),
      lerp(a.y, b.y, ls) + (noise(n, 18) - 0.5) * 12,
      bow,
      lerp(0.6, 1.4, noise(n, 21)),
      3 + n
    );
    let rs = lerp(0.34, 0.44, noise(n, 22));
    stroke(206, 142, 96, lerp(22, 48, noise(n, 24)));
    thread(
      b.x - 14,
      b.y,
      lerp(b.x, a.x, rs),
      lerp(b.y, a.y, rs) + (noise(n, 23) - 0.5) * 12,
      -bow * 0.55,
      lerp(0.5, 1.2, noise(n, 25)),
      30 + n
    );
  }
  for (let n = 0; n < 5; n++) {
    let t = lerp(0.76, 0.9, noise(n, 26));
    let a = spineAt(left, t);
    let b = spineAt(right, t);
    stroke(168, 92, 62, 16 + noise(n, 27) * 14);
    thread(
      a.x,
      a.y,
      b.x,
      b.y,
      (noise(n, 28) - 0.5) * 36,
      lerp(1.4, 2.8, noise(n, 29)),
      50 + n
    );
  }
}

function thread(x0, y0, x1, y1, bow, sw, seed) {
  strokeWeight(sw);
  noFill();
  beginShape();
  let steps = 26;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let x = lerp(x0, x1, u) + (noise(seed, u * 2.2) - 0.5) * 14;
    let y = lerp(y0, y1, u) + sin(u * PI) * bow + (noise(seed + 2, u * 2.2) - 0.5) * 8;
    vertex(x, y);
  }
  endShape();
}

function impasto(pts, kind) {
  noStroke();
  for (let n = 0; n < 190; n++) {
    let i = floor(random(10, pts.length - 10));
    let p = pts[i];
    let toward = p.x < 820 ? 1 : -1;
    let side = random(1) < 0.62 ? toward : -toward;
    let x = p.x + side * random(0, 48);
    let y = p.y + random(-16, 16);
    if (x > 755 && x < 875 && y > 1040 && y < 1330) continue;
    let inward = 1 - constrain(abs(x - 820) / 480, 0, 1);
    let base = kind === 0 ? color(160, 54, 72) : color(170, 86, 48);
    let hot = kind === 0 ? color(255, 186, 168) : color(255, 206, 150);
    let col = lerpColor(base, hot, inward);
    fill(red(col), green(col), blue(col), lerp(28, 62, inward) * edgeFade(p.t));
    push();
    translate(x, y);
    rotate(random(-1, 1));
    ellipse(0, 0, random(8, 26), random(4, 13));
    pop();
  }
}

function embers() {
  noStroke();
  for (let i = 0; i < 70; i++) {
    let x = lerp(500, 1140, noise(i, 33));
    let y = lerp(1500, 1760, noise(i, 34));
    fill(196, 84, 52, random(8, 26));
    ellipse(x, y, random(2, 6.5), random(1.6, 4.5));
