}

function motes() {
  noStroke();
  for (let i = 0; i < 480; i++) {
    let roll = random(1);
    let x;
    let y;
    if (roll < 0.5) {
      x = 812 + (random(-1, 1) + random(-1, 1)) * 150;
      y = 1180 + (random(-1, 1) + random(-1, 1)) * 200;
