}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  ground();
  sharedField();
  form(0);
  form(1);
  accents();
  thirdLight();
  braid();
  reaching();
  sediment();
  embers();
  motes();
  vignette();
  grain();
}

function ground() {
  blendMode(BLEND);
  background(274, 46, 6);
  noStroke();
  for (let y = 0; y < height; y += 3) {
    let t = y / height;
    let n = noise(t * 1.6, 4.4);
    let h = 262 + n * 28 + sin(t * PI) * 10;
    let s = 34 + t * 10 + (n - 0.5) * 8;
    let b = 6.5 + pow(sin(t * PI), 0.85) * 7.5 + n * 1.5;
    fill(h, constrain(s, 0, 100), constrain(b, 0, 100), 62);
    rect(0, y, width, 4);
  }
  pigment(260, 280, 560, 460, 228, 38, 11, 14, 1.3);
  pigment(1360, 220, 500, 400, 292, 32, 9, 13, 2.2);
  pigment(180, 1680, 420, 520, 262, 36, 7, 12, 3.4);
  pigment(1240, 1760, 520, 480, 330, 34, 8, 12, 4.8);
  pigment(800, 1880, 780, 340, 16, 28, 9, 10, 5.1);
}

function sharedField() {
  blendMode(BLEND);
  softGlow(760, 980, 520, 640, 350, 42, 30, 4.5);
  softGlow(860, 1100, 400, 500, 24, 36, 32, 3.6);
  softGlow(800, 1020, 220, 340, 40, 28, 48, 2.8);
  pigment(800, 1060, 360, 480, 8, 28, 20, 5, 6.6);
}

function form(side) {
  let steps = 76;
  let tStart = side === 0 ? -0.045 : 0.0;
  let tEnd = side === 0 ? 1.0 : 1.055;
  for (let pass = 0; pass < 2; pass++) {
    for (let i = 0; i < steps; i++) {
      let t = lerp(tStart, tEnd, i / (steps - 1));
      if (pass === 0) paintFormLight(side, t, i);
      else paintFormPigment(side, t, i);
    }
  }
}

function paintFormLight(side, t, i) {
  let g = metrics(side, t);
  let inward = side === 0 ? 1 : -1;
  let h = side === 0 ? lerp(344, 356, g.tc) : lerp(20, 34, g.tc);
  if (i % 2 === 0) {
    pigment(
      g.x - inward * g.rad * 0.42,
      g.y,
      g.rad * 0.34,
      g.rad * 0.2,
      side === 0 ? 330 : 18,
      32,
      8,
      4.5,
      10 + side * 3 + t
    );
  }
  softGlow(g.x, g.y, g.rad * 0.52, g.rad * 0.7, h, 46, 52 + g.heart * 12, 5.5);
  softGlow(
    g.x + inward * (22 + g.rad * 0.06),
    g.y,
    g.rad * 0.26,
    g.rad * 0.36,
    side === 0 ? 8 : 16,
    40,
    68 + g.heart * 8,
    3.8
  );
  if (g.tc > 0.16 && g.tc < 0.8 && i % 4 === 0) {
    softGlow(g.x - inward * g.rad * 0.46, g.y, 14, 26, 170, 30, 46, 3.2);
  }
}

function paintFormPigment(side, t, i) {
  let g = metrics(side, t);
  let inward = side === 0 ? 1 : -1;
  for (let k = 0; k < 5; k++) {
    let n1 = noise(side * 4.1, t * 3.2, k * 1.7);
    let n2 = noise(k * 2.3, t * 1.1, side + 3);
    let goIn = n2 > 0.74;
    let dir = goIn ? inward : -inward;
    let reach = pow(n1, 0.65) * g.rad * (goIn ? 0.34 : 0.5);
    let x = g.x + dir * reach;
    let y = g.y + (noise(t, k, side + 6) - 0.5) * g.rad * 0.22;
    let along = g.ang + (noise(t, k, 9) - 0.5) * 1.1;
    let len = 22 + noise(t, k, 10) * 64;
    let wt = 2.4 + noise(t, k, 11) * 9 * (0.35 + g.body);
    let edge = reach / (g.rad * 0.5 + 0.01);
    let h = side === 0 ? lerp(354, 338, constrain(edge, 0, 1)) : lerp(20, 38, constrain(edge, 0, 1));
    if (goIn) h = side === 0 ? 7 : 16;
    let s = constrain(46 + edge * 18 + (n2 - 0.5) * 8, 32, 78);
    let b = constrain(62 - edge * 26 + g.heart * 10 + g.body * 8, 20, 84);
    if (goIn) b = min(88, b + 8);
    let a = 6 + (1 - min(1, edge)) * 9;
    if (k === 0) {
      dab(g.x, g.y, g.ang, 78 + g.body * 36, 16 + g.body * 8, side === 0 ? 350 : 26, 38, 34 + g.body * 14, 4.5);
    }
    dab(x, y, along, len, wt, h, s, b, a);
  }
}

function accents() {
  blendMode(BLEND);
  for (let side = 0; side < 2; side++) {
    let inward = side === 0 ? 1 : -1;
    for (let k = 0; k < 5; k++) {
      let t = 0.4 + k * 0.028;
      let g = metrics(side, t);
      let h = side === 0 ? 6 : 22;
      dab(g.x + inward * g.rad * 0.22, g.y, g.ang + inward * 0.55, 70 + k * 4, 11, h, 40, 82, 11);
    }
  }
}

function thirdLight() {
  let C = metrics(0, 0.46);
  let D = metrics(1, 0.46);
  let mx = (C.x + D.x) / 2;
  let my = (C.y + D.y) / 2;
  blendMode(BLEND);
  softGlow(mx, my, 130, 170, 40, 30, 68, 4);
  blendMode(ADD);
  for (let i = 0; i < 64; i++) {
    let t = 0.2 + (i / 63) * 0.62;
    let L = metrics(0, t);
    let R = metrics(1, t);
    let x = (L.x + R.x) / 2 + (noise(t * 6.0, 11) - 0.5) * 12;
    let y = (L.y + R.y) / 2;
    let heart = exp(-pow((t - 0.46) / 0.13, 2));
    let rx = 22 + heart * 74;
    let ry = 30 + heart * 108;
    softGlow(x, y, rx, ry, 44, 26 - heart * 12, 92, 2.3 + heart * 2.1);
    if (heart > 0.55) {
      softGlow(x, y - 6, rx * 0.32, ry * 0.3, 48, 8, 100, heart * 3.2);
    }
  }
  blendMode(BLEND);
  for (let i = 0; i < 28; i++) {
    let t = 0.3 + (i / 27) * 0.38;
    let L = metrics(0, t);
    let R = metrics(1, t);
    let x = (L.x + R.x) / 2 + (noise(i * 0.31, 15) - 0.5) * 18;
    let y = (L.y + R.y) / 2;
    dab(
      x,
      y,
      HALF_PI + (noise(i, 16) - 0.5) * 0.4,
      24 + noise(i, 17) * 36,
      3 + noise(i, 18) * 3.5,
      46,
      16,
      96,
      7 + noise(i, 19) * 6
    );
  }
}

function braid() {
  blendMode(BLEND);
  for (let i = 0; i < 22; i++) {
    let t = 0.36 + (i / 21) * 0.2;
    let L = metrics(0, t);
    let R = metrics(1, t);
    let x = (L.x + R.x) / 2;
    let y = (L.y + R.y) / 2;
    let s = i % 2 === 0 ? -1 : 1;
    let h = s < 0 ? 356 : 26;
    dab(x + s * 14, y, HALF_PI, 28, 5, h, 38, 58, 8);
  }
}

function reaching() {
  blendMode(BLEND);
  noFill();
  for (let i = 0; i < 12; i++) {
    let t = 0.4 + noise(i, 40) * 0.12;
    let L = metrics(0, t);
    let R = metrics(1, t);
    let mid = (L.x + R.x) / 2;
    let my = (L.y + R.y) / 2 + (noise(i, 41) - 0.5) * 20;
    stroke(8, 35, 75, 9);
    strokeWeight(1.4 + noise(i, 42) * 1.6);
    bezier(L.x + 16, L.y, L.x + 86, L.y - 12, mid - 36, my, mid - 10, my);
    stroke(24, 35, 78, 9);
    strokeWeight(1.4 + noise(i, 43) * 1.6);
    bezier(R.x - 16, R.y, R.x - 86, R.y + 12, mid + 36, my, mid + 10, my);
  }
}

function sediment() {
  blendMode(BLEND);
  noFill();
  for (let i = 0; i < 64; i++) {
    let y = 1560 + noise(i * 0.37, 21) * 340;
    let x1 = 220 + noise(i, 22) * 180;
    let x2 = 1380 - noise(i, 23) * 180;
    let bulge = (noise(i, 24) - 0.5) * 36;
    let h = noise(i, 26) > 0.55 ? lerp(18, 36, noise(i, 27)) : lerp(348, 32, noise(i, 25));
    stroke(h, 42, 16 + noise(i, 28) * 18, 5 + noise(i, 29) * 7);
    strokeWeight(2 + noise(i, 30) * 8);
    bezier(x1, y, 620, y + bulge, 980, y - bulge, x2, y);
  }
  softGlow(800, 1780, 480, 110, 16, 35, 28, 5);
  softGlow(640, 1740, 200, 70, 350, 30, 24, 4);
  softGlow(980, 1800, 220, 80, 28, 32, 26, 4);
}

function embers() {
  blendMode(ADD);
  for (let i = 0; i < 18; i++) {
    if (noise(i * 0.45, 31) < 0.42) continue;
    let y = 700 - i * 26;
    let x = 800 + (noise(i, 32) - 0.5) * 30;
    softGlow(x, y, 5 + noise(i, 33) * 7, 8, 42, 22, 95, 2.8);
  }
  blendMode(BLEND);
}

function motes() {
  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let y = random(height);
    let dx = (x - 800) / 560;
    let dy = (y - 960) / 760;
    let near = exp(-(dx * dx + dy * dy));
    let high = constrain(map(y, 900, 180, 0, 1), 0, 1);
    let a = 1.5 + near * 9 + high * 3.5;
    let r = random(0.8, 2.8);
    let roll = random();
    noStroke();
    if (roll < 0.06) {
      blendMode(ADD);
      softGlow(x, y, r * 5, r * 5, 44, 18, 100, a * 0.45);
      blendMode(BLEND);
    } else {
      let h = roll < 0.5 ? 42 : roll < 0.72 ? 8 : 28;
      fill(h, 20, 96, a);
      ellipse(x, y, r, r * random(0.7, 1.3));
    }
  }
}

function vignette() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 130; i++) {
    let a = pow(1 - i / 130, 1.7) * 14;
    fill(268, 40, 4, a);
    rect(0, i * 3.4, width, 5);
  }
  for (let i = 0; i < 90; i++) {
    let a = pow(1 - i / 90, 1.5) * 12;
    fill(272, 38, 4, a);
    rect(0, height - 5 - i * 3.0, width, 5);
  }
  for (let i = 0; i < 80; i++) {
    let a = pow(1 - i / 80, 1.5) * 13;
    fill(268, 36, 4, a);
    rect(i * 2.6, 0, 5, height);
    rect(width - 5 - i * 2.6, 0, 5, height);
