}

function grain() {
  blendMode(BLEND);
  strokeWeight(1);
  for (let i = 0; i < 24000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.55) stroke(36, 12, 92, random(2, 7));
    else stroke(270, 18, 8, random(2, 8));
    point(x, y);
  }
}

function metrics(side, t) {
  let tc = constrain(t, 0, 1);
  let heart = exp(-pow((tc - 0.46) / 0.155, 2));
  let root = exp(-pow((tc - 0.9) / 0.09, 2));
  let pull = heart * 206 + root * 78;
  let n = noise(side * 3.7 + 1.1, tc * 1.7);
  let x = (side === 0 ? 488 : 1112) + (side === 0 ? pull : -pull);
  x += (n - 0.5) * 48 + sin(tc * TWO_PI * 1.15 + side * 2.0) * 14;
  let y = lerp(310, 1690, t);
  y += (noise(side + 8.2, tc * 2.4) - 0.5) * 26;
  let t2 = t + 0.012;
  let tc2 = constrain(t2, 0, 1);
  let heart2 = exp(-pow((tc2 - 0.46) / 0.155, 2));
  let root2 = exp(-pow((tc2 - 0.9) / 0.09, 2));
  let pull2 = heart2 * 206 + root2 * 78;
  let n2 = noise(side * 3.7 + 1.1, tc2 * 1.7);
  let x2 = (side === 0 ? 488 : 1112) + (side === 0 ? pull2 : -pull2);
  x2 += (n2 - 0.5) * 48 + sin(tc2 * TWO_PI * 1.15 + side * 2.0) * 14;
  let y2 = lerp(310, 1690, t2) + (noise(side + 8.2, tc2 * 2.4) - 0.5) * 26;
  let ang = atan2(y2 - y, x2 - x);
  let body = pow(sin(tc * PI), 0.62);
  let widthMul = side === 0 ? 0.84 : 1.06;
  let rad = (64 + body * 108 + heart * 26) * widthMul;
  return { x: x, y: y, ang: ang, rad: rad, body: body, heart: heart, tc: tc };
}

function softGlow(x, y, rx, ry, h, s, b, maxA) {
  noStroke();
  let steps = 10;
  for (let i = steps; i >= 1; i--) {
    let u = i / steps;
    let alpha = maxA * pow(1 - u, 2);
    fill(
      wrapHue(h),
      constrain(s * lerp(0.85, 1.05, 1 - u), 0, 100),
      constrain(b * lerp(0.7, 1.05, 1 - u), 0, 100),
      alpha
    );
    ellipse(x, y, rx * 2 * u, ry * 2 * u);
  }
}

function dab(x, y, ang, len, wt, h, s, b, a) {
  noStroke();
  let n = 4;
  for (let i = 0; i < n; i++) {
    let u = i / (n - 1);
    let taper = sin(u * PI);
    let px = x + cos(ang) * (u - 0.5) * len;
    let py = y + sin(ang) * (u - 0.5) * len;
    fill(wrapHue(h), constrain(s, 0, 100), constrain(b, 0, 100), a * taper);
    ellipse(px, py, max(0.5, wt * taper * 1.35), max(0.5, wt * taper * 0.72));
  }
}

function pigment(cx, cy, rx, ry, h, s, b, a, seed) {
  noStroke();
  fill(wrapHue(h), constrain(s, 0, 100), constrain(b, 0, 100), a);
  beginShape();
  let n = 48;
  for (let i = 0; i < n; i++) {
    let ang = (TWO_PI * i) / n;
    let wob = 0.82 + noise(seed, cos(ang) * 1.3, sin(ang) * 1.3) * 0.36;
    vertex(cx + cos(ang) * rx * wob, cy + sin(ang) * ry * wob);
  }
  endShape(CLOSE);
}

function wrapHue(h) {
  return ((h % 360) + 360) % 360;
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255);
  ellipseMode(CENTER);
  rectMode(CORNER);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  background(8, 4, 8);
  paintGround();
  paintClearing();
  paintAtmosphere();
  paintWeather();
  paintWeights();
  paintCradle();
  paintFloor();
  paintBody(600, 810, 260, 220, 1);
  paintBody(1050, 1000, 210, 230, -1);
  paintBetween();
  paintCurrents();
  paintFilaments();
  paintOrbits();
  paintMotes();
  paintVignette();
  paintGrain();
}

function paintGround() {
  strokeWeight(1);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let dusk = Math.exp(-Math.pow((y - 960) / 500, 2));
    let n = noise(y * 0.0032, 1.4);
    let r = lerp(8, 46, Math.pow(t, 1.18)) + dusk * 24 + (n - 0.5) * 10;
    let g = lerp(4, 18, Math.pow(t, 1.08)) + dusk * 8 + (n - 0.5) * 4;
    let b = lerp(9, 16, t) + dusk * 5 + (noise(y * 0.0022, 7.1) - 0.5) * 5;
    stroke(r, g, b);
    line(0, y, width, y);
  }
}

function paintClearing() {
  noStroke();
  for (let i = 7; i >= 0; i--) {
    let t = i / 7;
    fill(36, 44, 72, lerp(16, 52, 1 - t));
    ellipse(290 + (noise(i, 2) - 0.5) * 18, 248, lerp(70, 480, t), lerp(54, 340, t));
  }
  for (let i = 0; i < 5; i++) {
    fill(86, 96, 124, 12);
    ellipse(318, 228, 160 + i * 26, 100 + i * 14);
  }
}

function paintAtmosphere() {
  noStroke();
  for (let i = 0; i < 16; i++) {
    fill(78, 30, 38, random(4, 10));
    ellipse(random(width), random(180, 1500), random(160, 540), random(70, 220));
  }
  for (let i = 0; i < 7; i++) {
    fill(26, 16, 34, random(5, 11));
    ellipse(random(160, 1440), random(60, 680), random(180, 460), random(50, 160));
  }
}

function paintWeather() {
  noFill();
  for (let i = 0; i < 7; i++) {
    if (i % 3 === 0) stroke(86, 62, 76, random(10, 18));
    else stroke(168, 86, 66, random(12, 22));
    strokeWeight(random(8, 16));
    let y = lerp(600, 1090, i / 6);
    bezier(40, y, 460, y + random(-34, 34), 1140, y + random(-34, 34), 1560, y + random(-14, 14));
  }
}

function paintWeights() {
  softCloud(600, 870, 880, 700, 42, 12, 18);
  softCloud(1040, 1050, 780, 740, 30, 16, 24);
}

function softCloud(cx, cy, dw, dh, r, g, b) {
  noStroke();
  for (let i = 6; i >= 0; i--) {
    let t = i / 6;
    fill(r, g, b, lerp(5, 15, 1 - t));
    ellipse(
      cx + (noise(i, cx * 0.01) - 0.5) * 24,
      cy + (noise(i, cy * 0.01) - 0.5) * 18,
      dw * lerp(0.72, 1.22, t),
      dh * lerp(0.68, 1.18, t)
    );
  }
}

function paintCradle() {
  noFill();
  for (let i = 0; i < 12; i++) {
    stroke(96, 34, 36, 14 + i * 1.5);
    strokeWeight(lerp(18, 1.4, i / 11));
    bezier(
      160 + i * 4, 1330 + i * 5,
      540, 1560 + i * 2,
      1120, 1470 - i * 4,
      1470 - i * 3, 1188 + i * 7
    );
  }
}

function paintFloor() {
  noStroke();
  for (let i = 0; i < 8; i++) {
    fill(118, 44, 26, 8);
    ellipse(830, 1660, 1500 - i * 36, 220 + i * 22);
  }
}

function bodyAlpha(t) {
  if (t < 0.38) return lerp(208, 44, t / 0.38);
  let u = (t - 0.38) / 0.62;
  return lerp(44, 0, Math.pow(u, 0.62));
}

function paintBody(cx, cy, halfW, halfH, toward) {
  noStroke();
  let core = toward > 0 ? color(255, 226, 208) : color(255, 238, 224);
  let mid = toward > 0 ? color(198, 74, 58) : color(198, 126, 78);
  let edge = toward > 0 ? color(76, 20, 28) : color(56, 34, 40);

  for (let i = 30; i >= 0; i--) {
    let t = i / 30;
    let col = t < 0.42 ? lerpColor(core, mid, t / 0.42) : lerpColor(mid, edge, (t - 0.42) / 0.58);
    let grow = lerp(0.15, 1.68, t);
    let jw = 1 + (noise(t * 5, 3.2) - 0.5) * 0.07;
    let jh = 1 + (noise(t * 5, 4.4) - 0.5) * 0.07;
    let ox = cx + toward * (1 - t) * 28 + (noise(t * 4, 2.2) - 0.5) * 20;
    let oy = cy + (noise(t * 4, 8.5) - 0.5) * 14;
    fill(red(col), green(col), blue(col), bodyAlpha(t));
    ellipse(ox, oy, halfW * 2 * grow * jw, halfH * 2 * grow * jh);
  }

  for (let i = 0; i < 210; i++) {
    let ang = random(TWO_PI);
    let rad = random() < 0.22 ? random(0.52, 1.02) : Math.pow(random(), 1.32);
    let x = cx + Math.cos(ang) * halfW * rad + toward * (1 - rad) * 22;
    let y = cy + Math.sin(ang) * halfH * rad;
    let broad = random() < 0.1;
    let sz = broad ? random(34, 88) : random(5, 26);
    let cr;
    let cg;
    let cb;
    let a;
    if (rad < 0.28) {
      cr = random(242, 255);
      cg = random(214, 242);
      cb = random(200, 226);
      a = random(12, 28);
    } else if (ang > 0.12 && ang < 1.28 && rad > 0.4) {
      cr = random(84, 118);
      cg = random(22, 40);
      cb = random(26, 40);
      a = random(16, 34);
    } else if (toward > 0) {
      cr = random(168, 208);
      cg = random(68, 98);
      cb = random(58, 82);
      a = random(10, 22);
    } else {
      cr = random(178, 214);
      cg = random(108, 148);
      cb = random(72, 98);
      a = random(10, 22);
    }
    fill(cr, cg, cb, a);
    push();
    translate(x, y);
    rotate(ang + random(-0.5, 0.5));
    ellipse(0, 0, sz, sz * random(0.34, 0.72));
    pop();
  }

  noStroke();
  for (let i = 6; i >= 0; i--) {
    let t = i / 6;
    fill(255, 242, 228, lerp(34, 8, t));
    ellipse(cx + toward * 32, cy - 4, halfW * lerp(0.2, 0.6, t), halfH * lerp(0.15, 0.46, t));
  }

  if (toward < 0) {
    for (let i = 0; i < 18; i++) {
      fill(164, 198, 206, random(22, 44));
      push();
      translate(cx + toward * 22 + random(-16, 12), cy + random(-12, 10));
      rotate(random(-0.6, 0.6));
      ellipse(0, 0, random(6, 16), random(2.5, 6));
      pop();
    }
  } else {
    for (let i = 0; i < 14; i++) {
      fill(150, 34, 44, random(16, 36));
      push();
      translate(cx + toward * 16 + random(-10, 14), cy + random(-9, 9));
      rotate(random(-0.5, 0.5));
      ellipse(0, 0, random(5, 13), random(2.5, 5.5));
      pop();
    }
  }

  for (let i = 0; i < 8; i++) {
    push();
    translate(
      cx + random(-halfW * 0.35, halfW * 0.35) + toward * 8,
      cy + random(-halfH * 0.3, halfH * 0.3)
    );
    rotate(random(-0.7, 0.35));
    if (toward > 0) fill(214, 108, 82, random(14, 28));
    else fill(206, 146, 108, random(14, 28));
    ellipse(0, 0, random(28, 66), random(3.5, 8));
    pop();
  }

  for (let i = 0; i < 14; i++) {
    let ang = random(PI * 1.02, PI * 1.4);
    let rad = random(0.3, 0.76);
    push();
    translate(cx + Math.cos(ang) * halfW * rad, cy + Math.sin(ang) * halfH * rad);
    rotate(ang + 0.55);
    fill(255, 248, 238, random(24, 56));
    ellipse(0, 0, random(14, 46), random(2.2, 5.5));
    pop();
  }

  for (let i = 5; i >= 0; i--) {
    fill(22, 6, 10, 7);
    ellipse(cx + 34, cy + 40, halfW * 2.15 + i * 18, halfH * 2.05 + i * 14);
  }
}

function paintBetween() {
  noStroke();
  for (let i = 8; i >= 0; i--) {
    let t = i / 8;
    fill(206, 82, 62, lerp(26, 4, t));
    ellipse(788, 888, lerp(22, 230, t), lerp(16, 160, t));
    fill(198, 130, 82, lerp(24, 4, t));
    ellipse(892, 962, lerp(20, 210, t), lerp(14, 170, t));
  }
  for (let i = 8; i >= 0; i--) {
    let t = i / 8;
    fill(255, 230, 202, lerp(64, 5, t));
    ellipse(838, 916, lerp(8, 108, t), lerp(5, 68, t));
  }
  push();
  translate(841, 910);
  rotate(-0.35);
  fill(255, 252, 246, 210);
  ellipse(0, 0, 13, 3.2);
  pop();
  push();
  translate(830, 924);
  rotate(0.2);
  fill(255, 236, 214, 80);
  ellipse(0, 0, 16, 4);
  pop();
}

function currentX(side, s, t) {
  let origin = side < 0 ? 650 : 1010;
  let near = side < 0 ? 752 : 908;
  let far = side < 0 ? 390 : 1230;
  let x;
  if (t < 0.34) {
    let u = t / 0.34;
    u = u * u * (3 - 2 * u);
    x = lerp(origin, near, u);
  } else {
    let u = constrain((t - 0.34) / 0.66, 0, 1);
    u = u * u * (3 - 2 * u);
    x = lerp(near, far, u);
  }
  x += Math.sin(t * 5.1 + s * 0.62 + side * 1.4) * 13;
  x += (noise(t * 1.35, s * 0.16, side + 5) - 0.5) * 34;
  x += (s - 8) * 3.3;
  return x;
}

function paintCurrents() {
  noStroke();
  for (let i = 0; i < 32; i++) {
    let t = random(0.05, 0.96);
    let y = lerp(1160, 1920, t);
    let fade = Math.pow(1 - t, 0.42);
    fill(146, 44, 40, 14 * fade + 3);
    ellipse(currentX(-1, 8, t) + random(-8, 8), y, random(28, 70), random(64, 150));
    fill(174, 102, 56, 14 * fade + 3);
    ellipse(currentX(1, 8, t) + random(-8, 8), y, random(26, 64), random(64, 140));
  }

  noFill();
  for (let side = -1; side <= 1; side += 2) {
    for (let s = 0; s < 16; s++) {
      let prev = null;
      for (let y = 1136; y <= 1964; y += 12) {
        let t = (y - 1136) / 828;
        let x = currentX(side, s, t);
        if (prev) {
          let fade = Math.pow(1 - t, 0.36) * constrain(t / 0.055, 0, 1);
          let a = fade * (72 + (s % 4) * 12);
          if (s % 6 === 0) stroke(216, 170, 106, a * 0.8);
          else if (side < 0) stroke(176, 60, 52, a);
          else stroke(198, 118, 68, a);
          strokeWeight(lerp(6.2, 1.15, t) * (0.55 + (s % 3) * 0.2));
          line(prev[0], prev[1], x, y);
        }
        prev = [x, y];
      }
    }
  }

  for (let s = 0; s < 7; s++) {
    let prev = null;
    for (let y = 1068; y <= 1936; y += 13) {
      let t = (y - 1068) / 868;
      let x = 832 + Math.sin(t * 4.1 + s * 0.85) * 16;
      x += (noise(t * 1.7, s * 0.28, 11) - 0.5) * 28 + (s - 3) * 3;
      if (prev) {
        let a = Math.pow(Math.sin(Math.min(t, 1) * Math.PI), 0.65) * 34;
        stroke(224, 176, 110, a);
        strokeWeight(lerp(2.2, 0.55, t));
        line(prev[0], prev[1], x, y);
      }
      prev = [x, y];
    }
  }

  noStroke();
  for (let i = 0; i < 36; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let t = random(0.07, 0.9);
    let x = currentX(side, floor(random(16)), t);
    let y = lerp(1168, 1948, t);
    fill(255, 198, 146, Math.pow(1 - t, 0.32) * 145);
    ellipse(x + random(-5, 5), y, random(1.8, 4.2), random(1.8, 4.2));
  }
}

function strand(x1, y1, cx1, cy1, cx2, cy2, x2, y2, r, g, b, weight, fadeOut) {
  noFill();
  let px = x1;
  let py = y1;
  let steps = 15;
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let x = bezierPoint(x1, cx1, cx2, x2, t);
    let y = bezierPoint(y1, cy1, cy2, y2, t);
    let env = fadeOut ? Math.pow(1 - t, 0.48) : Math.sin(t * Math.PI);
    stroke(r, g, b, env * 88);
    strokeWeight(Math.max(0.28, weight * env));
    line(px, py, x, y);
    px = x;
    py = y;
  }
}

function paintFilaments() {
  for (let i = 0; i < 11; i++) {
    let y1 = 800 + random(-100, 120);
    let y2 = 960 + random(-100, 120);
    let lift = random(-100, 40);
    let r = 255;
    let g = 208;
    let b = 170;
    if (i % 5 === 0) {
      r = 186;
      g = 208;
      b = 214;
    }
    strand(
      700 + random(-34, 36), y1,
      770, y1 + lift,
      910, y2 + lift * 0.8,
      1004 + random(-28, 18), y2,
      r, g, b,
      random(0.55, 1.45),
      false
    );
  }
  for (let i = 0; i < 4; i++) {
    strand(
      688 + random(-16, 28), 830 + random(-70, 70),
      750, 800 + random(-30, 24),
      800, 860,
      834 + random(-6, 14), 908 + random(-18, 18),
      255, 214, 180,
      random(0.4, 0.95),
      true
    );
    strand(
      990 + random(-18, 22), 990 + random(-56, 48),
      930, 950,
      888, 930,
      858 + random(-8, 10), 916 + random(-14, 14),
      238, 204, 172,
      random(0.4, 0.95),
      true
    );
  }
  for (let i = 0; i < 5; i++) {
    let x = 748 + random(0, 180);
    strand(
      x, 848 + random(-16, 28),
      x + random(-28, 28), 620,
      x + random(-46, 46), 400,
      x + random(-36, 36), 230 + random(0, 90),
      255, 220, 198,
      random(0.35, 0.85),
      true
    );
  }
}

function paintOrbits() {
  noFill();
  for (let n = 0; n < 2; n++) {
    let cx = n === 0 ? 600 : 1050;
    let cy = n === 0 ? 810 : 1000;
    let sc = n === 0 ? 1 : 0.88;
    for (let i = 0; i < 6; i++) {
      stroke(236, 196, 166, random(13, 30));
      strokeWeight(random(0.45, 1.25));
      let start = random(TWO_PI);
      arc(
        cx + random(-10, 10),
        cy + random(-10, 10),
        random(300, 430) * sc,
        random(240, 360) * sc,
        start,
        start + random(0.35, 1.3)
      );
    }
  }
  for (let i = 0; i < 11; i++) {
    stroke(230, 186, 148, random(11, 26));
    strokeWeight(random(0.45, 1.4));
    let start = random(TWO_PI);
    arc(
      830 + random(-18, 18),
      908 + random(-18, 18),
      random(660, 1000),
      random(500, 780),
      start,
      start + random(0.28, 1.12)
    );
  }
}

function paintMotes() {
  noStroke();
  for (let i = 0; i < 46; i++) {
    let x = random(70, 1530);
    let y = random(150, 620);
    let s = random(1.1, 3.1);
    if (random() < 0.3) fill(180, 196, 206, random(28, 76));
    else fill(255, 214, 184, random(46, 130));
    ellipse(x, y, s, s);
  }
  for (let i = 0; i < 16; i++) {
    fill(255, 234, 210, random(36, 100));
    ellipse(838 + random(-46, 46), 916 + random(-26, 26), random(1.3, 2.8), random(1.3, 2.8));
  }
}

function paintVignette() {
  noStroke();
  for (let i = 0; i < 190; i++) {
    let a = map(i, 0, 190, 34, 0);
    fill(5, 2, 4, a);
    rect(0, i, width, 1);
    rect(i, 0, 1, height);
    rect(width - 1 - i, 0, 1, height);
  }
  for (let i = 0; i < 110; i++) {
    fill(6, 2, 4, map(i, 0, 110, 26, 0));
    rect(0, height - 1 - i, width, 1);
  }
  for (let k = 0; k < 5; k++) {
    fill(4, 1, 3, 9);
    ellipse(0, 0, 760, 840);
    ellipse(width, 0, 760, 840);
    ellipse(0, height, 880, 620);
    ellipse(width, height, 880, 620);
  }
}

function paintGrain() {
  strokeWeight(1);
  for (let i = 0; i < 68000; i++) {
    if (random() < 0.5) stroke(255, random(4, 12));
    else stroke(0, random(5, 15));
    point(random(width), random(height));
  }
}

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255);
  noLoop();
  drawPainting();
}

function drawPainting() {
  background(15, 8, 25);
  drawBackground();
  drawGlows();
  drawOrganicForms();
  drawSpiral();
  drawFilaments();
  drawParticles();
  drawVignette();
}

function drawBackground() {
  noStroke();
  for (let y = 0; y < H; y += 5) {
    let t = y / H;
    let bg = lerpColor(color(20, 10, 30), color(60, 25, 55), t);
    fill(bg);
    rect(0, y, W, 5);
  }

  for (let i = 0; i < 200; i++) {
    let x = random(W);
    let y = random(H);
    let r = 150 + random(250);
    let a = random(4, 15);
    let col = color(random(80, 150), random(20, 60), random(50, 100), a);
    fill(col);
    ellipse(x, y, r, r);
  }
}

function drawGlows() {
  push();
  blendMode(ADD);

  for (let r = 500; r > 0; r -= 6) {
    let a = map(r, 0, 500, 30, 0);
    fill(255, 200, 120, a);
    ellipse(800, 950, r * 2, r * 2);
  }

  for (let r = 120; r > 0; r -= 3) {
    let a = map(r, 0, 120, 120, 0);
    fill(255, 250, 230, a);
    ellipse(800, 950, r * 2, r * 2);
  }

  for (let r = 400; r > 0; r -= 6) {
    let a = map(r, 0, 400, 22, 0);
    fill(255, 110, 70, a);
    ellipse(420, 850, r * 2, r * 2);
  }

  for (let r = 400; r > 0; r -= 6) {
    let a = map(r, 0, 400, 22, 0);
    fill(80, 140, 255, a);
    ellipse(1180, 850, r * 2, r * 2);
  }

  pop();
}

function drawOrganicForms() {
  let warmCols = [
    color(255, 100, 65),
    color(255, 150, 80),
    color(255, 210, 120)
  ];

  let leftPts = [
    [300, 550, 130, warmCols[0]],
    [390, 640, 160, warmCols[1]],
    [470, 780, 180, warmCols[0]],
    [500, 930, 190, warmCols[2]],
    [560, 1080, 170, warmCols[0]],
    [640, 1190, 140, warmCols[1]],
    [720, 1240, 110, warmCols[2]],
    [780, 1120, 80, warmCols[0]]
  ];

  for (let p of leftPts) {
    organicBlob(p[0], p[1], p[2], p[3], 45);
  }

  let coolCols = [
    color(70, 120, 255),
    color(130, 110, 255),
    color(180, 160, 255)
  ];

  let rightPts = [
    [1300, 550, 130, coolCols[0]],
    [1210, 640, 160, coolCols[1]],
    [1130, 780, 180, coolCols[0]],
    [1100, 930, 190, coolCols[2]],
    [1040, 1080, 170, coolCols[0]],
    [960, 1190, 140, coolCols[1]],
    [880, 1240, 110, coolCols[2]],
    [820, 1120, 80, coolCols[0]]
  ];

  for (let p of rightPts) {
    organicBlob(p[0], p[1], p[2], p[3], 45);
  }

  organicBlob(800, 1350, 120, color(255, 210, 150), 55);
}

function organicBlob(cx, cy, baseR, col, alpha) {
  noStroke();
  fill(red(col), green(col), blue(col), alpha);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.03) {
    let xoff = cos(a) + cx * 0.002;
    let yoff = sin(a) + cy * 0.002;
    let r = baseR * (0.55 + 0.7 * noise(xoff, yoff));
    vertex(cx + cos(a) * r, cy + sin(a) * r);
  }
  endShape(CLOSE);
}

function drawSpiral() {
  push();
  blendMode(ADD);
  noFill();
  strokeWeight(1.5);
  let cx = 800;
  let cy = 950;

  stroke(255, 220, 150, 70);
  beginShape();
  for (let a = 0; a < 7 * TWO_PI; a += 0.08) {
    let r = a * 5.5;
    vertex(cx + cos(a) * r, cy + sin(a) * r);
  }
  endShape();

  stroke(180, 140, 255, 50);
  beginShape();
  for (let a = PI; a < PI + 7 * TWO_PI; a += 0.08) {
    let r = (a - PI) * 5.5;
    vertex(cx + cos(a) * r, cy + sin(a) * r);
  }
  endShape();

  pop();
}

function drawFilaments() {
  push();
  blendMode(ADD);
  noFill();

  for (let i = 0; i < 120; i++) {
    let x1 = random(280, 600);
    let y1 = random(500, 1400);
