    let x2 = random(700, 950);
    let y2 = random(800, 1300);
    stroke(100, 150, 255, random(8, 30));
    strokeWeight(random(0.3, 1.8));
    drawThreadCurve(x1, y1, x2, y2, random(0.5, 1.5), random(20, 80), i);
  }

  for (let i = 0; i < 80; i++) {
    let x1 = random(600, 1000);
    let y1 = random(700, 1400);
    let x2 = random(600, 1000);
    let y2 = random(700, 1400);
    stroke(255, 220, 130, random(8, 35));
    strokeWeight(random(0.2, 1.2));
    drawThreadCurve(x1, y1, x2, y2, random(0.3, 1.0), random(20, 50), i);
  }

  pop();
}

function drawThreadCurve(x1, y1, x2, y2, noiseScale, shift, seedOff) {
  noFill();
  beginShape();
  let steps = 50;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    let n1 = noise(t * 1.5 + seedOff, seedOff * 0.01);
    let n2 = noise(t * 1.5 + seedOff + 100, seedOff * 0.01 + 50);
    let env = sin(t * PI);
    x += (n1 - 0.5) * shift * env;
    y += (n2 - 0.5) * shift * env;
    vertex(x, y);
  }
  endShape();
}

function drawParticles() {
  push();
  blendMode(ADD);
  noStroke();

  for (let i = 0; i < 1500; i++) {
    let x = random(W);
    let y = random(H);
