function drawAmbientGlows() {
  drawRadialGlow(CX, CY, 1000, color(255, 160, 120), color(20, 10, 45), 55);
  drawRadialGlow(350, 300, 650, color(100, 150, 255), color(10, 5, 25), 45);
  drawRadialGlow(1250, 1750, 650, color(190, 110, 170), color(10, 5, 25), 45);
}

function drawRadialGlow(x, y, r, innerC, outerC, alphaMax) {
  let ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, `rgba(${red(innerC)},${green(innerC)},${blue(innerC)},${alphaMax})`);
  g.addColorStop(1, `rgba(${red(outerC)},${green(outerC)},${blue(outerC)},0)`);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TWO_PI);
  ctx.fill();
  ctx.restore();
}

function getSpiralPoint(t, theta0, theta1, r0, r1, seedPhase) {
  let theta = lerp(theta0, theta1, t);
  let rad = lerp(r0, r1, t);
  rad += 22 * sin(theta * 3.0 + seedPhase * 1.7);
  rad += 16 * sin(theta * 7.0 + seedPhase * 3.1);
  return {x: CX + rad * cos(theta), y: CY + rad * sin(theta)};
}

function drawRibbon(theta0, theta1, r0, r1, seedPhase, c1, c2) {
  const steps = 500;
  push();
  blendMode(ADD);
  noFill();
  strokeCap(ROUND);
  strokeJoin(ROUND);
  const passes = [
    {alpha: 14, wMax: 56, wMin: 20},
    {alpha: 38, wMax: 28, wMin: 8},
    {alpha: 85, wMax: 9, wMin: 2}
  ];
  for (let p = 0; p < passes.length; p++) {
    let pass = passes[p];
    for (let i = 0; i < steps; i++) {
      let t = i / steps;
      let tn = (i + 1) / steps;
      let p1 = getSpiralPoint(t, theta0, theta1, r0, r1, seedPhase);
      let p2 = getSpiralPoint(tn, theta0, theta1, r0, r1, seedPhase);
      let cc = lerpColor(c1, c2, t);
      let fade = 0.45 + 0.55 * sin(PI * t);
      stroke(red(cc), green(cc), blue(cc), pass.alpha * fade);
      strokeWeight(lerp(pass.wMax, pass.wMin, t));
      line(p1.x, p1.y, p2.x, p2.y);
    }
  }
  pop();
}

function drawRibbons() {
  let warm1 = color(255, 115, 80);
  let warm2 = color(255, 225, 175);
  let cool1 = color(65, 135, 255);
  let cool2 = color(185, 225, 255);

  drawRibbon(-1.35 * PI, -1.35 * PI + 4.8 * PI, 720, 100, 0.5, warm1, warm2);
  drawRibbon(0.65 * PI, 0.65 * PI - 4.8 * PI, 720, 100, 2.8, cool1, cool2);
}

function drawFilaments() {
  push();
  blendMode(ADD);
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < 150; i++) {
    let baseAngle = i * TWO_PI / 150 + noise(i * 0.2) * 0.7;
    let len = 420 + noise(i * 1.9) * 430;
    let warm = (i % 2 === 0);
    stroke(warm ? color(255, 190, 130, 8) : color(130, 190, 255, 8));
    strokeWeight(1.3);
    beginShape();
    for (let s = 0; s <= 32; s++) {
      let t = s / 32;
      let rr = t * len;
      let ang = baseAngle + noise(i * 0.15, t * 1.9) * 0.55 - 0.28;
      let px = CX + rr * cos(ang + t * 0.18);
      let py = CY + rr * sin(ang + t * 0.18);
      vertex(px, py);
    }
    endShape();
  }
  pop();
}

function drawPetals() {
  push();
  blendMode(ADD);
  noStroke();
  const layers = [
    {count: 10, lenBase: 330, wBase: 90, col1: color(255, 145, 95, 60), col2: color(105, 165, 255, 55), phase: 0.4},
    {count: 14, lenBase: 230, wBase: 68, col1: color(255, 200, 140, 80), col2: color(170, 210, 255, 70), phase: 0.9},
    {count: 18, lenBase: 150, wBase: 46, col1: color(255, 235, 180, 100), col2: color(220, 235, 255, 90), phase: 0.1}
  ];
  for (let L = 0; L < layers.length; L++) {
    let layer = layers[L];
    for (let i = 0; i < layer.count; i++) {
      let angle = layer.phase + i * TWO_PI / layer.count;
      let len = layer.lenBase + (noise(i * 1.1 + L * 3.7) - 0.5) * 95;
      let w = layer.wBase + (noise(i * 0.8 + L * 5.1) - 0.5) * 55;
      let c = (i % 2 === 0) ? layer.col1 : layer.col2;
      push();
      translate(CX, CY);
      rotate(angle);
      fill(c);
      beginShape();
      vertex(0, -w * 0.5);
      bezierVertex(len * 0.12, -w * 1.0, len * 0.75, -w * 0.8, len, 0);
      bezierVertex(len * 0.75, w * 0.8, len * 0.12, w * 1.0, 0, w * 0.5);
      endShape(CLOSE);
      pop();
    }
  }
  pop();
}

function drawCore() {
  drawRadialGlow(CX, CY, 280, color(255, 240, 210), color(255, 160, 90), 110);
  drawRadialGlow(CX, CY, 120, color(255, 255, 250), color(255, 225, 160), 150);
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 24; i > 0; i--) {
    let t = i / 24;
    fill(255, 250, 240, 20 * (1 - t));
    ellipse(CX, CY, 150 * t * 2);
  }
  fill(255, 255, 255, 220);
  ellipse(CX, CY, 22, 22);
  pop();
}

function drawParticles() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 160; i++) {
    let x = random() * width;
    let y = random() * height;
    let d = dist(x, y, CX, CY);
    if (d > 260) {
      let sz = random(1, 3.5);
      let bright = random(60, 200);
      let cc = random() < 0.5 ? color(255, 220, 160, bright) : color(180, 210, 255, bright);
      fill(cc);
      ellipse(x, y, sz, sz);
    }
  }
  for (let i = 0; i < 80; i++) {
    let t = random();
    let pt;
    if (i % 2 === 0) {
      pt = getSpiralPoint(t, -1.35 * PI, -1.35 * PI + 4.8 * PI, 720, 100, 0.5);
    } else {
      pt = getSpiralPoint(t, 0.65 * PI, 0.65 * PI - 4.8 * PI, 720, 100, 2.8);
    }
    let sz = random(1.5, 5);
    fill(255, 245, 220, 160);
    ellipse(pt.x, pt.y, sz);
  }
  pop();
}

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  colorMode(RGB, 255);
}

function draw() {
  drawBackground();

  blendMode(ADD);

  const warm = [255, 120, 105];
  const cool = [160, 130, 255];
  const gold = [255, 205, 150];

  radialGlow(500, 760, 380, warm, 0.16);
  radialGlow(1100, 1160, 380, cool, 0.16);
  radialGlow(800, 970, 650, gold, 0.20);

  // Source glows at the ends of the two strands
  radialGlow(470, H - 170, 150, warm, 0.18);
  radialGlow(1130, H - 170, 150, cool, 0.18);
  radialGlow(700, 190, 120, warm, 0.16);
  radialGlow(900, 190, 120, cool, 0.16);

  drawRings();

  const ptsA = makeStrand(470, 700, H - 170, 190, 0.5, 270, 8.0, 1.2);
  const ptsB = makeStrand(1130, 900, H - 170, 190, 0.5 + Math.PI, 270, 8.0, 2.4);

  drawConnections(ptsA, ptsB);
  drawRibbon(ptsA, warm, 8);
  drawRibbon(ptsB, cool, 7);

  drawEmbers(ptsA);
  drawEmbers(ptsB);
  drawDust(1400);

  // Central hearth
  radialGlow(800, 970, 340, [255, 225, 205], 0.40);
  radialGlow(800, 970, 140, [255, 250, 245], 0.72);

  blendMode(BLEND);
  drawGrain(5000);
  noLoop();
}

function drawBackground() {
  const ctx = drawingContext;

  const lin = ctx.createLinearGradient(0, 0, 0, H);
  lin.addColorStop(0, '#070510');
  lin.addColorStop(0.55, '#0f091c');
  lin.addColorStop(1, '#1c1028');
  ctx.fillStyle = lin;
  ctx.fillRect(0, 0, W, H);

  const rad = ctx.createRadialGradient(W / 2, H / 2, 180, W / 2, H / 2, 1450);
  rad.addColorStop(0, 'rgba(0,0,0,0)');
  rad.addColorStop(1, 'rgba(0,0,0,0.62)');
  ctx.fillStyle = rad;
  ctx.fillRect(0, 0, W, H);
}

function radialGlow(x, y, r, col, aMax) {
  const ctx = drawingContext;
  const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
  grad.addColorStop(0, `rgba(${col[0]},${col[1]},${col[2]},${aMax})`);
  grad.addColorStop(0.2, `rgba(${col[0]},${col[1]},${col[2]},${aMax * 0.42})`);
  grad.addColorStop(0.6, `rgba(${col[0]},${col[1]},${col[2]},${aMax * 0.10})`);
  grad.addColorStop(1, `rgba(${col[0]},${col[1]},${col[2]},0)`);
  ctx.save();
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function makeStrand(x0, x1, y0, y1, phase, ampBase, twists, noiseOff) {
  const pts = [];
  const n = 900;
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const e = t * t * (3 - 2 * t);
    const y = lerp(y0, y1, e);
    const xBase = lerp(x0, x1, e);
    const breathe = 0.72 + 0.28 * noise(t * 4.2 + noiseOff, 7.0);
    const amp = ampBase * sin(t * Math.PI) * breathe;
    const twist = sin(t * Math.PI * twists + phase);
    const x = xBase + twist * amp;
    const yWobble = (noise(t * 5.1 + noiseOff, 13.0) - 0.5) * 70 * sin(t * Math.PI);
    pts.push(createVector(x, y + yWobble));
  }
  return pts;
}

function drawConnections(pA, pB) {
  noFill();
  for (let i = 0; i < pA.length; i += 3) {
    const t = i / pA.length;
    const fade = sin(t * Math.PI);
    strokeWeight(1.1);
    stroke(255, 210, 190, 24 * fade);
    line(pA[i].x, pA[i].y, pB[i].x, pB[i].y);

    if (i < pA.length - 2) {
      stroke(255, 190, 220, 13 * fade);
      line(pA[i].x, pA[i].y, pB[i + 2].x, pB[i + 2].y);
    }
  }
}

function drawRibbon(points, col, size) {
  noFill();
  strokeJoin(ROUND);

  strokeWeight(size * 5.0);
  stroke(col[0], col[1], col[2], 20);
  beginShape();
  for (const p of points) vertex(p.x, p.y);
  endShape();

  strokeWeight(size * 2.1);
  stroke(col[0], col[1], col[2], 75);
  beginShape();
  for (const p of points) vertex(p.x, p.y);
  endShape();

  strokeWeight(size * 0.8);
  stroke(255, 245, 240, 190);
  beginShape();
  for (const p of points) vertex(p.x, p.y);
  endShape();
}

function drawEmbers(points) {
  noStroke();
  for (let i = 0; i < points.length; i += 5) {
    const t = i / points.length;
    const sz = random(1.3, 4.6) * (0.55 + 0.55 * sin(t * Math.PI));
    const alpha = 70 + 150 * sin(t * Math.PI);
    fill(255, 230, 210, alpha);
    const px = points[i].x + random(-14, 14);
    const py = points[i].y + random(-14, 14);
    ellipse(px, py, sz, sz);
  }
}

function drawDust(num) {
  noStroke();
  for (let i = 0; i < num; i++) {
    const x = random(0, W);
    const y = random(0, H);
    const d = dist(x, y, W / 2, 965);
    const closeness = constrain(1.0 - d / 850.0, 0, 1);
    const alpha = 95 * closeness * random(0.35, 1);
    if (alpha > 6) {
      fill(255, 215, 180, alpha);
      ellipse(x, y, random(0.8, 2.7));
    }
  }
}

function drawRings() {
  noFill();
  for (let i = 0; i < 8; i++) {
    const r = 300 + i * 85;
    const alpha = 22 - i * 2.4;
    if (alpha <= 0) continue;
    stroke(255, 215, 190, alpha);
    strokeWeight(1.1);
    ellipse(800, 960, r * 1.5, r * 1.8);
  }
}

function drawGrain(num) {
  noStroke();
  for (let i = 0; i < num; i++) {
    const x = random(0, W);
    const y = random(0, H);
    fill(255, 220, 200, random(4, 16));
    rect(x, y, 1, 1);
  }
}

const HEART_SCALE = 44;
const CENTER_X = 800;
const CENTER_Y = 930;

let heartPolyCache = [];

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);
}

function draw() {
  background(8, 6, 16);
  drawBackgroundGradient();
  drawCentralGlows();
  drawHeartSilhouette();
  drawHeartTendrils();
  drawHeartParticles();
  drawBackgroundStars();
  drawVignette();
}

function heartX(t) {
  return 16 * Math.pow(Math.sin(t), 3);
}

function heartY(t) {
  return 13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t);
}

function heartPoint(t, scaleF = 1) {
  return createVector(
    CENTER_X + heartX(t) * HEART_SCALE * scaleF,
    CENTER_Y - heartY(t) * HEART_SCALE * scaleF
  );
}

function drawBackgroundGradient() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(CENTER_X, CENTER_Y, 150, CENTER_X, CENTER_Y, 1400);
  g.addColorStop(0, '#311824');
  g.addColorStop(0.55, '#1c1020');
  g.addColorStop(1, '#08060e');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawCentralGlows() {
  const ctx = drawingContext;
  blendMode(ADD);

  let g1 = ctx.createRadialGradient(CENTER_X, CENTER_Y, 80, CENTER_X, CENTER_Y, 800);
  g1.addColorStop(0, 'rgba(255,190,190,0.15)');
  g1.addColorStop(0.6, 'rgba(220,120,180,0.05)');
  g1.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g1;
  ctx.fillRect(0, 0, width, height);

  let g2 = ctx.createRadialGradient(CENTER_X - 300, CENTER_Y, 100, CENTER_X - 300, CENTER_Y, 700);
  g2.addColorStop(0, 'rgba(120,170,255,0.10)');
  g2.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, width, height);

  let g3 = ctx.createRadialGradient(CENTER_X + 300, CENTER_Y, 100, CENTER_X + 300, CENTER_Y, 700);
  g3.addColorStop(0, 'rgba(255,150,100,0.10)');
  g3.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g3;
  ctx.fillRect(0, 0, width, height);

  blendMode(BLEND);
}

function drawHeartSilhouette() {
  const ctx = drawingContext;
  blendMode(ADD);

  ctx.save();
  ctx.beginPath();
  const pts = 220;
  for (let i = 0; i <= pts; i++) {
    const t = (i / pts) * TWO_PI;
    const p = heartPoint(t, 1.0);
    if (i === 0) ctx.moveTo(p.x, p.y);
    else ctx.lineTo(p.x, p.y);
  }
  ctx.closePath();

  const grad = ctx.createRadialGradient(CENTER_X, CENTER_Y + 60, 100, CENTER_X, CENTER_Y + 60, 750);
  grad.addColorStop(0, 'rgba(255,220,220,0.20)');
  grad.addColorStop(0.5, 'rgba(200,130,200,0.09)');
  grad.addColorStop(1, 'rgba(40,20,60,0.03)');
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.restore();

  blendMode(BLEND);
}

function drawHeartTendrils() {
  blendMode(ADD);
  noFill();

  for (let i = 0; i < 320; i++) {
    const rightSide = (i % 2 === 0);
    let tStart = rightSide ? 0 : PI;
    let tEnd = rightSide ? PI : TWO_PI;
    if (random(1) < 0.25) {
      let tmp = tStart;
      tStart = tEnd;
      tEnd = tmp;
    }

    const noiseOffset = random(10000);
    const scaleF = random(0.82, 1.28);
    const wav = random(5, 42);
    const weight = random(0.8, 5);
    const alpha = random(10, 36);

    beginShape();
    for (let j = 0; j <= 90; j++) {
      const frac = j / 90;
      const t = lerp(tStart, tEnd, frac);
      const dt = 0.03;

      const pPrev = heartPoint(t - dt, scaleF);
      const pNext = heartPoint(t + dt, scaleF);
      const tangent = createVector(pNext.x - pPrev.x, pNext.y - pPrev.y).normalize();
      const normal = createVector(-tangent.y, tangent.x);

      const base = heartPoint(t, scaleF);
      const n = noise(noiseOffset + t * 0.65, j * 0.18);
      const off = (n - 0.5) * wav;

      const px = base.x + normal.x * off;
      const py = base.y + normal.y * off;

      const warm = color(255, 160 + 30 * Math.sin(frac * PI), 110);
      const cool = color(120, 150 + 40 * Math.sin(frac * PI), 255);
      const merge = color(255, 225, 242);

      let col = rightSide ? lerpColor(warm, merge, frac) : lerpColor(cool, merge, frac);
      col.setAlpha(alpha);
      stroke(col);
      strokeWeight(weight);
      vertex(px, py);
    }
    endShape();
  }

  blendMode(BLEND);
}

function getHeartPolygon() {
  if (heartPolyCache.length === 0) {
    const pts = 220;
    for (let i = 0; i < pts; i++) {
      const t = (i / pts) * TWO_PI;
      heartPolyCache.push(heartPoint(t, 1.0));
    }
  }
  return heartPolyCache;
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i].x;
    const yi = poly[i].y;
    const xj = poly[j].x;
    const yj = poly[j].y;
    if ((yi > y) !== (yj > y)) {
      const xIntersect = (xj - xi) * (y - yi) / (yj - yi) + xi;
      if (x < xIntersect) inside = !inside;
    }
  }
  return inside;
}

function drawHeartParticles() {
  const poly = getHeartPolygon();
  blendMode(ADD);
  noStroke();

  let placed = 0;
  const want = 5500;
  let attempts = 0;
  while (placed < want && attempts < want * 4) {
    attempts++;
    const x = random(90, 1510);
    const y = random(350, 1720);
    if (pointInPoly(x, y, poly)) {
      placed++;
      const size = random(0.7, 5.8);
      const alpha = random(5, 38);
      if (abs(x - CENTER_X) < 130) {
        fill(255, 220, 240, alpha);
      } else if (x < CENTER_X) {
        fill(110 + random(-18, 18), 160 + random(-10, 10), 255, alpha);
      } else {
        fill(255, 150 + random(-15, 15), 110 + random(-15, 15), alpha);
      }
      ellipse(x, y, size, size);
    }
  }

  const outlineCount = 3500;
  for (let i = 0; i < outlineCount; i++) {
    const t = random(TWO_PI);
    const scaleF = random(0.78, 1.32);
    const base = heartPoint(t, scaleF);
    const jitterAngle = random(TWO_PI);
    const jitterMag = Math.pow(random(1), 2) * 55;
    const x = base.x + Math.cos(jitterAngle) * jitterMag;
    const y = base.y + Math.sin(jitterAngle) * jitterMag;
    const size = random(0.6, 4.8);
    const alpha = random(6, 45);

    if (abs(x - CENTER_X) < 120) {
      fill(255, 225, 242, alpha);
    } else if (x < CENTER_X) {
      fill(120 + random(-15, 15), 165 + random(-10, 10), 255, alpha);
    } else {
      fill(255, 150 + random(-10, 10), 105 + random(-15, 15), alpha);
    }
    ellipse(x, y, size, size);
  }

  blendMode(BLEND);
}

function drawBackgroundStars() {
