function catmullRom(p0, p1, p2, p3, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  const x = 0.5 * (2*p1.x + (-p0.x + p2.x) * t + (2*p0.x - 5*p1.x + 4*p2.x - p3.x) * t2 + (-p0.x + 3*p1.x - 3*p2.x + p3.x) * t3);
  const y = 0.5 * (2*p1.y + (-p0.y + p2.y) * t + (2*p0.y - 5*p1.y + 4*p2.y - p3.y) * t2 + (-p0.y + 3*p1.y - 3*p2.y + p3.y) * t3);
  return { x, y };
}

function sampleSpline(controls, samples = 280) {
  const pts = [];
  const segs = controls.length - 1;
  const perSeg = Math.max(1, Math.floor(samples / segs));
  for (let i = 0; i < segs; i++) {
    for (let k = 0; k < perSeg; k++) {
      const t = k / perSeg;
      const p0 = controls[Math.max(0, i - 1)];
      const p1 = controls[i];
      const p2 = controls[i + 1];
      const p3 = controls[Math.min(controls.length - 1, i + 2)];
      pts.push(catmullRom(p0, p1, p2, p3, t));
    }
  }
  pts.push(controls[controls.length - 1]);
  return pts;
}

function perturb(pts, seed, amp = 35) {
  return pts.map((p, i) => {
    const nx = noise(seed * 10 + i * 0.04, seed * 20 + 0.1);
    const ny = noise(seed * 10 + i * 0.038 + 55, seed * 20 + 1.3);
    return {
      x: p.x + (nx - 0.5) * amp,
      y: p.y + (ny - 0.5) * amp
    };
  });
}

function colorFromStops(t, stops) {
  t = constrain(t, 0, 1);
  const seg = t * (stops.length - 1);
  const i = Math.floor(seg);
  const f = seg - i;
  const c1 = stops[Math.min(i, stops.length - 1)];
  const c2 = stops[Math.min(i + 1, stops.length - 1)];
  return lerpColor(c1, c2, f);
}

function drawRibbonPath(pts, stops) {
  const n = pts.length;
  for (let pass = 0; pass < 3; pass++) {
    for (let i = 0; i < n - 1; i++) {
      const t = i / (n - 1);
      const c = colorFromStops(t, stops);
      let w, a;
      if (pass === 0) {
        w = 100 * (0.35 + 0.65 * sin(PI * t));
        a = 12;
      } else if (pass === 1) {
        w = 32 * (0.6 + 0.4 * sin(PI * t));
        a = 68;
      } else {
        w = 8 * (0.7 + 0.5 * sin(PI * t));
        a = 190;
      }
      stroke(red(c), green(c), blue(c), a);
      strokeWeight(w);
      line(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
    }
  }
}

function drawRibbons() {
  const cA = [
    { x: 90, y: 1960 },
    { x: 430, y: 1640 },
    { x: 650, y: 1260 },
    { x: 800, y: 1000 },
    { x: 955, y: 820 },
    { x: 1180, y: 520 },
    { x: 1515, y: 130 }
  ];
  const cB = [
    { x: 1510, y: 1960 },
    { x: 1170, y: 1640 },
    { x: 950, y: 1260 },
    { x: 800, y: 1000 },
    { x: 645, y: 820 },
    { x: 420, y: 520 },
    { x: 85, y: 130 }
  ];
  ribbonA = perturb(sampleSpline(cA, 280), 0.35, 38);
  ribbonB = perturb(sampleSpline(cB, 280), 1.15, 38);

  push();
  noFill();
  strokeCap(ROUND);
  blendMode(ADD);
  drawRibbonPath(ribbonA, warmStops);
  drawRibbonPath(ribbonB, coolStops);
  pop();
}

function drawRibbonSparkles() {
  const arrs = [
    { pts: ribbonA, stops: warmStops },
    { pts: ribbonB, stops: coolStops }
  ];
  push();
  blendMode(ADD);
  noStroke();
  for (const arr of arrs) {
    const pts = arr.pts;
    const stops = arr.stops;
    for (let i = 0; i < pts.length; i += 4) {
      const t = i / (pts.length - 1);
      const c = colorFromStops(t, stops);
      fill(red(c), green(c), blue(c), random(70, 190));
      const jx = random(-12, 12);
      const jy = random(-12, 12);
      ellipse(pts[i].x + jx, pts[i].y + jy, random(2, 7), random(2, 7));
    }
  }
  pop();
}

function drawStarParticles() {
  const cx = width / 2;
