// THE INCLINATION — a painting about what love is
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();

  paintSky();
  drawGround();
  drawThreads(300, 1.0, false);   // far threads, bending inward
  drawThreads(95, 1.0, true);     // threads that sink into roots
  presence(-1);
  presence(1);
  drawThreads(70, 0.5, false);    // a few threads arriving in front
  tendrils();
  meeting();
  embers();
  halo();
  grain();
  vignette();
}
function draw() {}

function paintSky() {
  background(6, 9, 20);
  noStroke();
  for (let y = 0; y <= 2000; y += 4) {
    let t = y / 2000, c;
    if (t < 0.45) c = lerpColor(color(6, 9, 20), color(26, 17, 38), t / 0.45);
    else c = lerpColor(color(26, 17, 38), color(9, 10, 20), (t - 0.45) / 0.55);
    fill(c); rect(0, y, 1600, 4);
  }
  for (let i = 0; i < 5200; i++) {           // nebulous drift
    let x = random(1600), y = random(2000);
    let n = noise(x * 0.0013, y * 0.0013);
    fill(50 + n * 70, 34 + n * 50, 80 + n * 80, 5 + n * 9);
    circle(x, y, 30 + n * 110);
  }
  for (let i = 0; i < 260; i++) {            // quiet far sparks
    fill(210, 220, 235, random(15, 70));
    circle(random(1600), random(720), random(1, 2.6));
  }
}

function drawGround() {
  noStroke();
  for (let b = 0; b < 7; b++) {
    let y0 = 1430 + b * 82;
    fill(12 + b * 3, 10 + b * 2, 20 + b * 3, 95);
    beginShape();
    vertex(0, 2000);
    for (let x = 0; x <= 1600; x += 40) vertex(x, y0 + noise(x * 0.004, b) * 70 - 35);
    vertex(1600, 2000);
    endShape(CLOSE);
  }
}

function drawThreads(count, aMul, roots) {
  noFill();
  for (let i = 0; i < count; i++) {
    let ang = roots ? random(PI * 0.15, PI * 0.85) : random(TWO_PI);
    let rad = random(430, 1180);
    let x = 800 + cos(ang) * rad * 0.92;
    let y = 930 + sin(ang) * rad * 1.18;
    let swirl = (random() < 0.5 ? -1 : 1) * (0.55 + random(0.6));
    let pts = [[x, y]];
    for (let s = 0; s < 210; s++) {
      let dx = 800 - x, dy = 930 - y, d = max(1, sqrt(dx * dx + dy * dy));
      if (d < 170) break;
      let a = atan2(dy, dx) + swirl * constrain(d / 620, 0.22, 1)
              + (noise(x * 0.004, y * 0.004) - 0.5) * 1.5;
      x += cos(a) * 6; y += sin(a) * 6;
      pts.push([x, y]);
    }
    if (roots) {
      for (let s = 0; s < 150; s++) {
        x += (noise(x * 0.01, y * 0.01) - 0.5) * 6;
        y += 5 + noise(y * 0.01) * 4;
        pts.push([x, y]);
        if (y > 1980) break;
      }
    }
    let h = floor(pts.length / 2);
    threadPath(pts, 0, h, color(186, 202, 228, 26 * aMul));
    threadPath(pts, h, pts.length - 1,
      roots ? color(196, 140, 104, 52 * aMul) : color(242, 192, 132, 55 * aMul));
  }
}
function threadPath(pts, a, b, col) {
  if (b - a < 2) return;
  stroke(col); strokeWeight(1.15); noFill();
  beginShape();
  for (let k = a; k <= b; k++) vertex(pts[k][0], pts[k][1]);
  endShape();
}

function presence(s) {
  const CYp = 950, baseX = 800 - s * 235, layers = 26;
  const outerC = s < 0 ? color(34, 56, 104) : color(80, 36, 88);
  const innerC = s < 0 ? color(216, 118, 108) : color(238, 158, 92);
  noStroke();
  for (let k = layers - 1; k >= 0; k--) {
    let tt = 1 - k / (layers - 1);
    let c = lerpColor(outerC, innerC, tt);
    fill(red(c), green(c), blue(c), 30);
    pShape(baseX - s * k * 3.2, CYp - k * 1.5, s, 1 - k * 0.031, s * 23.7 + k * 0.61);
  }
  noFill();                                    // rings of accumulated years
  for (let k = 2; k < layers; k += 4) {
    let c = lerpColor(outerC, innerC, 1 - k / (layers - 1));
    stroke(red(c), green(c), blue(c), 26); strokeWeight(1);
    pShape(baseX - s * k * 3.2, CYp - k * 1.5, s, 1 - k * 0.031, s * 23.7 + k * 0.61);
  }
}
function pShape(cx, cy, s, sc, seed) {
  beginShape();
  const N = 96;
  for (let i = 0; i <= N; i++) {
    let t = i / N * TWO_PI;
    let px = cos(t) * 240, py = sin(t) * 415;
    let up = constrain(-sin(t), 0, 1);
    px *= (1 - 0.24 * up);
    py -= 46 * up;
    let oy = 415 * 0.86;
    let lean = s * (0.12 + 0.06 * up);
    let rx2 = px * cos(lean) - (py - oy) * sin(lean);
    let ry2 = px * sin(lean) + (py - oy) * cos(lean);
    px = rx2; py = ry2 + oy;
    px += (noise(seed + cos(t) + 2, sin(t) + 2) - 0.5) * 30 * sc;
    py += (noise(seed * 1.7 + cos(t) * 1.3 + 6, sin(t) * 1.3 + 6) - 0.5) * 30 * sc;
    vertex(cx + px * sc, cy + py * sc);
  }
  endShape(CLOSE);
}

function tendrils() {                          // reaching, almost touching
  noFill();
  for (let s of [-1, 1]) {
    stroke(246, 232, 206, 110); strokeWeight(2);
    beginShape();
    for (let i = 0; i <= 26; i++) {
      let t = i / 26;
      let x = lerp(800 + s * 150, 800 + s * 24, t) + (noise(9 + s * 3 + t * 2) - 0.5) * 22;
      let y = lerp(585, 448, t * t) - sin(t * PI) * 30 + (noise(20 + s * 5 + t * 2) - 0.5) * 14;
      vertex(x, y);
    }
    endShape();
  }
  noStroke();
  fill(255, 200, 130, 26); circle(800, 438, 26);
  fill(255, 240, 205, 200); circle(800, 438, 5);
}

function meeting() {                           // where the warmth is made
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 560; i++) {
    let yy = constrain(930 + randomGaussian() * 170, 600, 1260);
    let narrow = 1 - abs(yy - 930) / 360;
    let xx = 800 + randomGaussian() * (20 + 70 * narrow);
    let rh = 20 + random(120) * narrow;
    fill(255, 190, 105, 5);
    ellipse(xx, yy, rh * 0.62, rh);
  }
  for (let i = 0; i < 200; i++) {
    fill(255, 234, 190, 7);
    ellipse(800 + randomGaussian() * 24, 930 + randomGaussian() * 70,
            random(10, 42), random(18, 64));
  }
  blendMode(BLEND);
  noFill();                                    // the bright seam
  stroke(255, 240, 205, 120); strokeWeight(2.4);
  beginShape();
  for (let y = 610; y <= 1245; y += 12) vertex(800 + (noise(3.1 + y * 0.017) - 0.5) * 24, y);
  endShape();
  stroke(255, 246, 222, 55); strokeWeight(6);
  beginShape();
  for (let y = 640; y <= 1215; y += 18) vertex(800 + (noise(3.1 + y * 0.017) - 0.5) * 24, y);
  endShape();
}

function embers() {
  noStroke();
  for (let i = 0; i < 230; i++) {
    let x = 800 + randomGaussian() * 170;
    let y = random() < 0.3 ? 930 + random(0, 260)
                           : 930 - abs(randomGaussian()) * 240 - random(0, 260);
    let r = random(1.2, 2.8);
    fill(255, 190, 120, 10); circle(x, y, r * 7);
    fill(255, 235, 195, 90 + random(80)); circle(x, y, r);
  }
}

function halo() {                              // held inside one circle
  noFill();
  stroke(238, 228, 206, 34); strokeWeight(1.4);
  drawingContext.setLineDash([1.5, 13]);
  ellipse(800, 940, 1210, 1210);
  stroke(238, 228, 206, 16);
  drawingContext.setLineDash([1, 19]);
  ellipse(800, 940, 1300, 1300);
  drawingContext.setLineDash([]);
}

function grain() {
  noStroke();
  for (let i = 0; i < 15000; i++) {
    let x = random(1600), y = random(2000);
    let d = dist(x, y, 800, 930);
    if (d < 520 && random() < 0.5) fill(255, 236, 205, random(5, 14));
    else if (random() < 0.5) fill(4, 6, 14, random(10, 26));
    else fill(200, 210, 230, random(4, 10));
    rect(x, y, random(1, 2.6), random(1, 2.6));
  }
}

function vignette() {
  noFill();
  for (let i = 0; i < 20; i++) {
    stroke(4, 5, 12, 3 + i * 0.9); strokeWeight(15);
    rect(i * 7 - 10, i * 7 - 10, 1600 + 20 - i * 14, 2000 + 20 - i * 14);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  const WARM = { x: 812, y: 1502, r: 212 };
  const COOL = { x: 788, y: 500, r: 186 };
  const MID = { x: 800, y: 1002 };

  background(10, 13, 24);

  function gradE(x, y, r, sx, sy, stops) {
    const c = drawingContext;
    c.save();
    c.translate(x, y);
    c.scale(sx, sy);
    const g = c.createRadialGradient(0, 0, 0, 0, 0, r);
    for (const s of stops) {
      g.addColorStop(s[0], 'rgba(' + s[1][0] + ',' + s[1][1] + ',' + s[1][2] + ',' + s[1][3] + ')');
    }
    c.fillStyle = g;
    c.fillRect(-r, -r, 2 * r, 2 * r);
    c.restore();
  }

  // deep washes
  gradE(800, 1950, 1250, 1, 1, [[0, [64, 26, 24, 0.35]], [0.5, [40, 18, 26, 0.18]], [1, [40, 18, 26, 0]]]);
  gradE(800, 60, 1200, 1, 1, [[0, [26, 40, 78, 0.4]], [0.55, [20, 28, 56, 0.18]], [1, [20, 28, 56, 0]]]);
  gradE(150, 190, 760, 1, 1, [[0, [52, 28, 66, 0.22]], [1, [52, 28, 66, 0]]]);
  gradE(1460, 1830, 760, 1, 1, [[0, [52, 28, 66, 0.22]], [1, [52, 28, 66, 0]]]);

  // tonal brush fields
  noStroke();
  for (let i = 0; i < 150; i++) {
    const x = random(0, 1600), y = random(0, 2000);
    const pick = random();
    const c = pick < 0.4 ? [22, 28, 48] : pick < 0.75 ? [16, 20, 36] : [34, 24, 40];
    fill(c[0], c[1], c[2], 5 + random() * 7);
    ellipse(x, y, random(160, 560), random(120, 420));
  }

  // breath column between the two
  blendMode(ADD);
  gradE(MID.x, MID.y, 760, 0.5, 1.1, [[0, [255, 140, 175, 0.10]], [0.6, [200, 120, 210, 0.05]], [1, [200, 120, 210, 0]]]);

  function paintOrb(o, p, otherCol, toward) {
    blendMode(ADD);
    gradE(o.x, o.y, o.r * 3.3, 1.05, 1.05, [[0, [p.halo[0], p.halo[1], p.halo[2], 0.30]], [0.4, [p.halo[0], p.halo[1], p.halo[2], 0.10]], [1, [p.halo[0], p.halo[1], p.halo[2], 0]]]);
    gradE(o.x, o.y, o.r * 1.7, 1, 1, [[0, [p.body[0], p.body[1], p.body[2], 0.55]], [0.6, [p.deep[0], p.deep[1], p.deep[2], 0.28]], [1, [p.deep[0], p.deep[1], p.deep[2], 0]]]);
    gradE(o.x - o.r * 0.12, o.y + toward * o.r * 0.06, o.r * 0.98, 1, 1, [[0, [p.core[0], p.core[1], p.core[2], 0.95]], [0.55, [p.body[0], p.body[1], p.body[2], 0.75]], [1, [p.body[0], p.body[1], p.body[2], 0]]]);
    strokeCap(ROUND);
    for (let k = 0; k < 46; k++) {
      const a = random(TWO_PI);
      const rr = o.r * (0.15 + 0.75 * pow(random(), 0.7));
      const x = o.x + cos(a) * rr, y = o.y + sin(a) * rr;
      stroke(p.core[0], p.core[1], p.core[2], 18 + random() * 34);
      strokeWeight(1 + random() * 2.2);
      const L = 6 + random() * 18;
      line(x - cos(a) * L * 0.5, y - sin(a) * L * 0.5, x + cos(a) * L * 0.5, y + sin(a) * L * 0.5);
    }
    // each orb keeps a spark of the other inside itself
    gradE(o.x, o.y + toward * o.r * 0.32, o.r * 0.4, 1, 1, [[0, [otherCol[0], otherCol[1], otherCol[2], 0.4]], [1, [otherCol[0], otherCol[1], otherCol[2], 0]]]);
    // painted rim
    for (let a = 0; a < TWO_PI; a += 0.034) {
      const n = noise(cos(a) * 0.9 + 4 + o.y * 0.001, sin(a) * 0.9 + 7);
      const rr = o.r * (0.95 + 0.13 * (n - 0.5) * 2);
      stroke(p.body[0], p.body[1], p.body[2], 8 + 66 * n);
      strokeWeight(1.2 + 2.2 * n);
      const x1 = o.x + cos(a) * rr, y1 = o.y + sin(a) * rr;
      line(x1 - sin(a) * 4, y1 + cos(a) * 4, x1 + sin(a) * 4, y1 - cos(a) * 4);
    }
    blendMode(BLEND);
  }

  const warmPal = { halo: [255, 118, 70], deep: [150, 44, 40], body: [236, 120, 76], core: [255, 216, 172] };
  const coolPal = { halo: [118, 158, 235], deep: [54, 80, 150], body: [136, 176, 236], core: [238, 246, 255] };
  paintOrb(WARM, warmPal, [150, 190, 255], -1);
  paintOrb(COOL, coolPal, [255, 160, 110], +1);

  // wanderers: reachings that do not arrive
  blendMode(ADD);
  for (let k = 0; k < 16; k++) {
    const fromWarm = k < 10;
    const o = fromWarm ? WARM : COOL;
    const side = (k % 2 === 0) ? 1 : -1;
    const a0 = fromWarm ? radians(-90 + side * (30 + random() * 52)) : radians(90 + side * (28 + random() * 48));
    const sx = o.x + cos(a0) * o.r * 0.96;
    const sy = o.y + sin(a0) * o.r * 0.96;
    const len = 240 + random() * 420;
    const ex = sx + side * (70 + random() * 230);
    const ey = sy + (fromWarm ? -len : len);
    const cx = lerp(sx, ex, 0.45) + side * (50 + random() * 170);
    const cy = lerp(sy, ey, 0.45) + (fromWarm ? -30 : 30);
    const col = fromWarm ? [255, 152, 100] : [172, 202, 255];
    let px = sx, py = sy;
    const segs = 26;
    for (let q = 1; q <= segs; q++) {
      const t = q / segs;
      const x = bezierPoint(sx, cx, cx, ex, t);
      const y = bezierPoint(sy, cy, cy, ey, t);
      const al = 30 * sin(PI * min(t * 1.35, 1)) * (1 - 0.5 * t);
      stroke(col[0], col[1], col[2], max(0, al));
      strokeWeight(1 + 1.3 * (1 - t));
      line(px, py, x, y);
      px = x; py = y;
    }
  }

  // the loom: threads braided between the two
  const threads = [];
  const NT = 430;
  for (let i = 0; i < NT; i++) {
    const s = (i % 2 === 0) ? 1 : -1;
    const taut = random() < 0.11;
    const fine = random() < 0.05;
    const m = taut ? 12 + random() * 28 : 42 + 515 * pow(random(), 1.4);
    const aA = radians(-90 + (random() - 0.5) * 118);
    const aB = radians(90 + (random() - 0.5) * 118);
    const rA = WARM.r * (0.88 + 0.24 * random());
    const rB = COOL.r * (0.88 + 0.24 * random());
    const A = { x: WARM.x + cos(aA) * rA, y: WARM.y + sin(aA) * rA };
    const B = { x: COOL.x + cos(aB) * rB, y: COOL.y + sin(aB) * rB };
    const jx = (random() - 0.5) * 80, jy = (random() - 0.5) * 60;
    const p1 = { x: lerp(A.x, B.x, 0.33) + s * m + jx * 0.4, y: lerp(A.y, B.y, 0.33) + jy };
    const p2 = { x: lerp(A.x, B.x, 0.67) - s * m * 0.75 + jx * 0.4, y: lerp(A.y, B.y, 0.67) - jy * 0.6 };
    const steps = 30;
    const humA = (random() < 0.32) ? (taut ? 2 + random() * 4 : 4 + random() * 8) : 0;
    const humF = 2 + floor(random() * 4);
    const ph = random() * TWO_PI;
    const wob = 3 + random() * 8;
    const pts = [];
    for (let k = 0; k <= steps; k++) {
      const t = k / steps;
      let x = bezierPoint(A.x, p1.x, p2.x, B.x, t);
      let y = bezierPoint(A.y, p1.y, p2.y, B.y, t);
      const env = t * (1 - t) * 4;
      const nn = (noise(i * 0.37 + t * 2.3, i * 0.11) - 0.5) * 2 * wob;
      const hum = humA ? sin(t * humF * TWO_PI + ph) * humA * env : 0;
      pts.push({ x: x + nn + hum, y: y + (noise(i * 0.53, t * 1.7) - 0.5) * 4 });
    }
    threads.push({
      pts: pts, steps: steps,
      w: fine ? 0.9 + random() * 0.5 : taut ? 1.1 + random() * 0.9 : (random() < 0.08 ? 2.5 + random() * 1.3 : 1.1 + random() * 1.5),
      alpha: fine ? 95 + random() * 40 : taut ? 45 + random() * 30 : 22 + random() * 38,
      cA: color(255, 118 + random() * 30, 78 + random() * 22),
      cB: color(138 + random() * 26, 182 + random() * 22, 255)
    });
  }

  blendMode(ADD);
  strokeCap(ROUND);
  for (let i = 0; i < threads.length; i++) {
    const th = threads[i];
    for (let k = 0; k < th.steps; k++) {
      const t = k / th.steps;
      const fade = (t < 0.07) ? t / 0.07 : (t > 0.93) ? (1 - t) / 0.07 : 1;
      const c = lerpColor(th.cA, th.cB, t);
      stroke(red(c), green(c), blue(c), th.alpha * fade);
      strokeWeight(th.w);
      line(th.pts[k].x, th.pts[k].y, th.pts[k + 1].x, th.pts[k + 1].y);
    }
  }

  // the third light, woven
  gradE(MID.x, MID.y, 300, 0.85, 0.6, [[0, [255, 150, 185, 0.14]], [1, [255, 150, 185, 0]]]);
  gradE(MID.x, MID.y, 150, 1, 1, [[0, [255, 205, 220, 0.12]], [1, [255, 205, 220, 0]]]);

  // knots where threads hold
  for (let k = 0; k < 150; k++) {
    const th = threads[floor(random() * threads.length)];
    const t = constrain(0.5 + randomGaussian(0, 0.13), 0.12, 0.88);
    const p = th.pts[floor(t * th.steps)];
    const c = lerpColor(th.cA, th.cB, t);
    const sz = 1.6 + pow(random(), 2.2) * 4.5;
    noStroke();
    fill(red(c), green(c), blue(c), 140 + random() * 90);
    circle(p.x, p.y, sz);
    if (random() < 0.1) gradE(p.x, p.y, sz * 8, 1, 1, [[0, [255, 235, 225, 0.30]], [1, [255, 235, 225, 0]]]);
  }
  for (let k = 0; k < 5; k++) {
    const t = (k + 1) / 6;
    const x = lerp(WARM.x, COOL.x, t) + (noise(k * 3.1 + 9) - 0.5) * 130;
    const y = lerp(WARM.y, COOL.y, t) + (noise(k * 7.7 + 2) - 0.5) * 70;
    gradE(x, y, 30, 1, 1, [[0, [255, 238, 228, 0.45]], [1, [255, 238, 228, 0]]]);
    stroke(255, 242, 232, 170);
    strokeWeight(1.5);
    const L = 11 + random() * 15;
    line(x - L, y, x + L, y);
    line(x, y - L, x, y + L);
    noStroke();
    fill(255, 250, 244, 235);
    circle(x, y, 6.5);
  }

  // drifting motes
  for (let k = 0; k < 620; k++) {
    const x = constrain(randomGaussian(800, 360), 40, 1560);
    const y = random(120, 1880);
    const w = y > 1000;
    noStroke();
    fill(w ? 255 : 190, w ? 178 : 208, w ? 140 : 255, 12 + random() * 30);
    circle(x, y, 1 + random() * 2.6);
  }
  for (let k = 0; k < 42; k++) {
    const x = constrain(randomGaussian(800, 330), 60, 1540);
    const y = random(180, 1820);
    const c = y > 1000 ? [255, 170, 130] : [180, 205, 255];
    gradE(x, y, 7 + random() * 11, 1, 1, [[0, [c[0], c[1], c[2], 0.20]], [1, [c[0], c[1], c[2], 0]]]);
  }

  // quiet arcs of attention flanking the weave
  for (const R of [480, 560]) {
    for (let a = 0; a < 360; a += 1.4) {
      const ar = radians(a);
      if (abs(cos(ar)) < 0.55) continue;
      if (noise(cos(ar) * 1.3 + R * 0.01, sin(ar) * 1.3) > 0.44) {
        const rr = R + (noise(a * 0.05, R * 0.1) - 0.5) * 22;
        const x1 = MID.x + cos(ar) * rr, y1 = MID.y + sin(ar) * rr;
        const L = 4 + noise(a * 0.12, R) * 10;
        stroke(255, 214, 205, 8 + noise(a * 0.3, R) * 12);
        strokeWeight(1.2);
        line(x1, y1, x1 + cos(ar) * L, y1 + sin(ar) * L);
      }
    }
  }

  blendMode(BLEND);

  // the keeper line
  stroke(255, 205, 165, 15);
  strokeWeight(1.6);
  noFill();
  const M = 46;
  beginShape();
  for (let x = M; x <= 1600 - M; x += 14) vertex(x, M + (noise(x * 0.012) - 0.5) * 6);
  endShape();
  beginShape();
  for (let x = M; x <= 1600 - M; x += 14) vertex(x, 2000 - M + (noise(x * 0.012 + 40) - 0.5) * 6);
  endShape();
  beginShape();
  for (let y = M; y <= 2000 - M; y += 14) vertex(M + (noise(y * 0.012 + 80) - 0.5) * 6, y);
  endShape();
  beginShape();
  for (let y = M; y <= 2000 - M; y += 14) vertex(1600 - M + (noise(y * 0.012 + 120) - 0.5) * 6, y);
  endShape();

  // vignette
  gradE(800, 1000, 1320, 1, 1, [[0, [7, 9, 18, 0]], [0.55, [7, 9, 18, 0]], [0.8, [7, 9, 18, 0.26]], [1, [7, 9, 18, 0.6]]]);

  // canvas grain
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const g = (random() - 0.5) * 14;
    pixels[i] += g;
    pixels[i + 1] += g;
    pixels[i + 2] += g;
  }
  updatePixels();
}

const W = 1600, H = 2000;

let warmC, coolC, midP, axisAng;
const warmR = 300, coolR = 278;

const WARM_PAL = [
  [255, 238, 200], [255, 196, 128], [243, 138, 92],
  [203, 84, 84], [128, 46, 68], [58, 24, 44]
];
const COOL_PAL = [
  [238, 250, 255], [176, 224, 240], [116, 170, 212],
  [70, 116, 172], [40, 66, 120], [20, 32, 64]
];

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);

  warmC = createVector(585, 775);
  coolC = createVector(1030, 1235);
  midP = p5.Vector.lerp(warmC, coolC, 0.5);
  axisAng = atan2(coolC.y - warmC.y, coolC.x - warmC.x);

  background(6, 8, 16);
  paintBackground();
  paintMotes();
  paintOrbits();
  paintBetweenHalo();
  paintThreads(false);
  paintRadiants();
  paintOrb(warmC, warmR, WARM_PAL, coolC, 13.7);
  paintOrb(coolC, coolR, COOL_PAL, warmC, 47.2);
  rimLight(warmC, warmR, coolC);
  rimLight(coolC, coolR, warmC);
  paintThreads(true);
  paintBetweenCore();
  paintGrain();
  paintVignette();
}

function paintBackground() {
  noStroke();
  for (let y = 0; y < H; y += 2) {
    let t = y / H;
    let n = (noise(t * 4.7) - 0.5) * 8;
    fill(7 + 8 * t + n, 9 + 8 * t + n, 17 + 14 * t + n);
    rect(0, y, W, 2);
  }
  for (let i = 0; i < 2400; i++) {
    let x = random(W), y = random(H);
    let n = noise(x * 0.0015, y * 0.0015);
    if (n > 0.52) {
      fill(66, 86, 138, (n - 0.52) * 46);
      ellipse(x, y, 40 + n * 160, 26 + n * 100);
    }
  }
  for (let i = 0; i < 900; i++) {
    let a = random(TWO_PI);
    let rr = pow(random(), 0.7);
    fill(126, 82, 52, 2.4 * (1 - rr));
    ellipse(midP.x + cos(a) * rr * 560, midP.y + sin(a) * rr * 560,
      70 + rr * 130, 46 + rr * 90);
  }
}

function paintMotes() {
  noStroke();
  for (let i = 0; i < 540; i++) {
    let x = random(W), y = random(H);
    let tw = constrain(1 - dist(x, y, warmC.x, warmC.y) / 820, 0, 1);
    let tm = constrain(1 - dist(x, y, midP.x, midP.y) / 480, 0, 1);
    fill(150 + 105 * max(tw, tm), 168 + 52 * tm + 24 * tw, 205 - 60 * tm, random(16, 66));
    let s = random(0.9, 2.7);
    ellipse(x, y, s, s);
  }
  blendMode(ADD);
  for (let i = 0; i < 12; i++) {
    let x = random(W), y = random(H);
    fill(200, 215, 255, 26); ellipse(x, y, 10, 10);
    fill(230, 240, 255, 60); ellipse(x, y, 3.4, 3.4);
  }
  blendMode(BLEND);
}

function paintOrbits() {
  for (let L = 0; L < 3; L++) {
    let Rx = 620 + L * 118;
    let Ry = Rx * 0.60;
    let steps = 620;
    for (let s = 0; s < steps; s++) {
      if (noise(s * 0.05, L * 9.1) < 0.42) continue;
      let t0 = (s / steps) * TWO_PI;
      let t1 = ((s + 1.6) / steps) * TWO_PI;
      let p0 = orbitPoint(t0, Rx, Ry);
      let p1 = orbitPoint(t1, Rx, Ry);
      let fade = 0.5 + 0.5 * sin(t0 * 2 + L * 1.7);
      stroke(148, 168, 212, 6 + 11 * fade);
      strokeWeight(0.9);
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }
}

function orbitPoint(t, Rx, Ry) {
  let wob = 1 + (noise(cos(t) * 1.2 + 31.4, sin(t) * 1.2 + 31.4) - 0.5) * 0.06;
  let ex = cos(t) * Rx * wob;
  let ey = sin(t) * Ry * wob;
  return createVector(
    midP.x + ex * cos(axisAng) - ey * sin(axisAng),
    midP.y + ex * sin(axisAng) + ey * cos(axisAng)
  );
}

function paintBetweenHalo() {
  blendMode(ADD);
  noStroke();
  push();
  translate(midP.x, midP.y);
  rotate(axisAng);
  for (let i = 0; i < 30; i++) {
    let t = i / 30;
    fill(255, 178 + 30 * t, 96 + 60 * t, 2.6 * (1 - t));
    let rx = 60 + t * 660;
    ellipse(0, 0, rx * 2, rx * 1.35);
  }
  pop();
  blendMode(BLEND);
}

function paintThreads(front) {
  let count = front ? 26 : 214;
  for (let i = 0; i < count; i++) {
    let s = random();
    let strong = front || s > 0.88;
    let spread = front ? 0.62 : 1.55;
    let a1 = axisAng + random(-spread, spread);
    let a2 = axisAng + PI + random(-spread, spread);
    let r1 = warmR * (front ? 1.01 : random(0.86, 0.985));
    let r2 = coolR * (front ? 1.01 : random(0.86, 0.985));
    let x1 = warmC.x + cos(a1) * r1, y1 = warmC.y + sin(a1) * r1;
    let x2 = coolC.x + cos(a2) * r2, y2 = coolC.y + sin(a2) * r2;
    let bend = random(-1, 1) * (70 + random(170));
    let col = strong ? [255, 206, 132] : (random() < 0.5 ? [186, 202, 234] : [236, 178, 148]);
    let alph = strong ? random(34, 62) : random(7, 24);
    let wgt = strong ? random(1.1, 1.8) : random(0.5, 1.05);
    if (strong) thread(x1, y1, x2, y2, col, alph * 0.35, wgt * 3.4, bend, false);
    let m = thread(x1, y1, x2, y2, col, alph, wgt, bend, false);
    if (strong) {
      blendMode(ADD);
      noStroke();
      fill(255, 226, 160, 46); ellipse(m.mx, m.my, 5.5, 5.5);
      fill(255, 196, 116, 14); ellipse(m.mx, m.my, 18, 18);
      blendMode(BLEND);
    }
  }
}

function thread(x1, y1, x2, y2, col, baseAlpha, wgt, bend, fadeOut) {
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let px = -dy / len, py = dx / len;
  let n1 = noise(x1 * 0.008, y1 * 0.008);
  let n2 = noise(x2 * 0.008, y2 * 0.008);
  let c1x = x1 + dx * 0.32 + px * bend * (0.55 + n1 * 0.5);
  let c1y = y1 + dy * 0.32 + py * bend * (0.55 + n1 * 0.5);
  let c2x = x1 + dx * 0.68 + px * bend * (1.0 + n2 * 0.4);
  let c2y = y1 + dy * 0.68 + py * bend * (1.0 + n2 * 0.4);
  let steps = 24;
  noFill();
  for (let s = 0; s < steps; s++) {
    let t0 = s / steps, t1 = (s + 1) / steps;
    let a = baseAlpha;
    if (fadeOut) a *= sq(1 - t0);
    if (a < 1.2) continue;
    stroke(col[0], col[1], col[2], a);
    strokeWeight(wgt);
    line(
      bezierPoint(x1, c1x, c2x, x2, t0), bezierPoint(y1, c1y, c2y, y2, t0),
      bezierPoint(x1, c1x, c2x, x2, t1), bezierPoint(y1, c1y, c2y, y2, t1)
    );
  }
  return {
    mx: bezierPoint(x1, c1x, c2x, x2, 0.5),
    my: bezierPoint(y1, c1y, c2y, y2, 0.5)
  };
}

function paintRadiants() {
  for (let i = 0; i < 14; i++) radiate(warmC, warmR, axisAng + PI);
  for (let i = 0; i < 14; i++) radiate(coolC, coolR, axisAng);
}

function radiate(c, R, away) {
  let a = away + random(-1.9, 1.9);
  let x1 = c.x + cos(a) * R * 0.98;
  let y1 = c.y + sin(a) * R * 0.98;
  let a2 = a + random(-0.5, 0.5);
  let reach = random(180, 540);
  thread(x1, y1, x1 + cos(a2) * reach, y1 + sin(a2) * reach,
    random() < 0.5 ? [214, 190, 168] : [168, 182, 214],
    random(14, 30), random(0.6, 1.1), random(-90, 90), true);
}

function paintOrb(c, R, pal, toward, seed) {
  let dir = p5.Vector.sub(toward, c).setMag(1);
  let lightAng = atan2(dir.y, dir.x);

  noStroke();
  let rings = 36;
  for (let i = 0; i < rings; i++) {
    let t = i / (rings - 1);
    let col = samplePalette(pal, 1 - t);
    fill(col[0], col[1], col[2], 25);
    beginShape();
    for (let k = 0; k <= 46; k++) {
      let ang = (k / 46) * TWO_PI;
      let w = 1 + (noise(cos(ang) * 1.25 + seed + t * 7, sin(ang) * 1.25 + seed) - 0.5) * 0.15;
      let rr = R * (1 - t) * w;
      vertex(c.x + dir.x * R * 0.15 * t + cos(ang) * rr,
             c.y + dir.y * R * 0.15 * t + sin(ang) * rr);
    }
    endShape(CLOSE);
  }

  for (let i = 0; i < 1150; i++) {
    let ang = random(TWO_PI);
    let rt = pow(random(), 0.75);
    let facing = constrain(cos(ang - lightAng), -1, 1);
    let col = samplePalette(pal, rt);
    let br = 0.72 + 0.42 * max(facing, 0);
    stroke(col[0] * br, col[1] * br, col[2] * br, random(12, 40));
    strokeWeight(random(0.7, 2.6));
    noFill();
    let span = random(0.07, 0.42);
    beginShape();
    for (let s = 0; s <= 6; s++) {
      let aa = ang + (span * s) / 6;
      let rw = R * rt * (1 + (noise(cos(aa) * 1.25 + seed, sin(aa) * 1.25 + seed) - 0.5) * 0.15);
      rw *= 1 + (noise(aa * 3.1, rt * 8 + seed) - 0.5) * 0.07;
      vertex(c.x + dir.x * R * 0.15 * rt + cos(aa) * rw,
             c.y + dir.y * R * 0.15 * rt + sin(aa) * rw);
    }
    endShape();
  }

  for (let i = 0; i < 430; i++) {
    let ang = lightAng + random(-1.2, 1.2);
    let rt = random(0.3, 1.0);
    let rw = R * rt * (1 + (noise(cos(ang) * 1.25 + seed, sin(ang) * 1.25 + seed) - 0.5) * 0.15);
    let x = c.x + dir.x * R * 0.15 * rt + cos(ang) * rw;
    let y = c.y + dir.y * R * 0.15 * rt + sin(ang) * rw;
    let g = random();
    stroke(255, 226 + g * 20, 178 + g * 40, random(16, 52));
    strokeWeight(random(0.8, 2.6));
    let tang = ang + HALF_PI;
    let L = random(3, 12);
    line(x - cos(tang) * L, y - sin(tang) * L, x + cos(tang) * L, y + sin(tang) * L);
  }

  blendMode(ADD);
  noStroke();
  let halo = samplePalette(pal, 0.45);
  for (let i = 0; i < 34; i++) {
    let t = i / 34;
    fill(halo[0], halo[1], halo[2], 2.1 * (1 - t));
    let d = R * 2 * (1.02 + t * 0.85);
    ellipse(c.x + dir.x * R * 0.1, c.y + dir.y * R * 0.1, d, d);
  }
  blendMode(BLEND);
}

function rimLight(c, R, toward) {
  let a0 = atan2(toward.y - c.y, toward.x - c.x);
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 70; i++) {
    let ang = a0 + random(-1.35, 1.35);
    let rr = R * random(0.92, 1.06);
    fill(255, 198, 118, random(2.5, 8));
    let s = random(12, 46);
    ellipse(c.x + cos(ang) * rr, c.y + sin(ang) * rr, s, s);
  }
  blendMode(BLEND);
}

function paintBetweenCore() {
  blendMode(ADD);
  noStroke();
  push();
  translate(midP.x, midP.y);
  rotate(axisAng);
  for (let i = 0; i < 34; i++) {
    let t = i / 34;
    let r = lerp(280, 18, t);
    fill(255, lerp(150, 242, t), lerp(70, 205, t), 2.4);
    ellipse(0, 0, r * 2, r * 1.45);
  }
  pop();
  for (let i = 0; i < 130; i++) {
    let a = random(TWO_PI);
    let rr = pow(random(), 1.6) * 300;
    fill(255, 214, 140, random(8, 40));
    let s = random(1.5, 4);
    ellipse(midP.x + cos(a) * rr, midP.y + sin(a) * rr * 0.8, s, s);
  }
  blendMode(BLEND);
}

function paintGrain() {
  for (let i = 0; i < 26000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.55) stroke(255, 250, 240, random(2, 7));
    else stroke(4, 6, 14, random(3, 10));
    strokeWeight(1);
    point(x, y);
  }
}

function paintVignette() {
  noStroke();
  let n = 46;
  for (let i = 0; i < n; i++) {
    let t = i / n;
    let a = 30 * pow(1 - t, 1.8);
    fill(3, 4, 10, a);
    let sh = 430 / n + 1, sv = 330 / n + 1;
    let dy = t * 430, dx = t * 330;
    rect(0, dy, W, sh);
    rect(0, H - dy - sh, W, sh);
    rect(dx, 0, sv, H);
    rect(W - dx - sv, 0, sv, H);
  }
}

function samplePalette(pal, t) {
  t = constrain(t, 0, 1);
  let f = t * (pal.length - 1);
  let i = Math.floor(f);
  if (i >= pal.length - 1) return pal[pal.length - 1].slice();
  let u = f - i;
  return [
    lerp(pal[i][0], pal[i + 1][0], u),
    lerp(pal[i][1], pal[i + 1][1], u),
    lerp(pal[i][2], pal[i + 1][2], u)
  ];
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255, 255, 255, 255);

  // Two currents, their shared lens, and the weave center
  const A = { x: 500, y: 1040, R: 430 };
  const B = { x: 1100, y: 920, R: 430 };
  const RR = 408;            // working radius of each current
  const WX = 800, WY = 980;  // heart of the between

  backgroundGradient();
  nebulae();
  speckles();
  stars();

  // Radii that love sends outward (behind the figures)
  halo(300, 40, 1.2);
  halo(440, 30, 1.1);
  halo(600, 22, 1.0);
  halo(790, 16, 0.9);
  halo(1000, 11, 0.9);

  glow(800, 230, 430, 255, 232, 196, 22, 28); // faint dawn the threads rise toward

  drawForm(A, [96, 26, 34], [216, 86, 52], [255, 171, 94], [255, 122, 70], 3.7,
    Math.atan2(B.y - A.y, B.x - A.x));
  drawForm(B, [18, 42, 86], [62, 124, 168], [150, 200, 255], [122, 172, 235], 9.2,
    Math.atan2(A.y - B.y, A.x - B.x));

  // The weave: the between making its own light
  glow(WX, WY, 330, 255, 210, 140, 46, 30);
  glow(WX, WY, 150, 255, 240, 205, 70, 26);
  warpThreads();
  weftThreads();
  lensOutline();

  filaments();   // what rises
  roots();       // what grounds
  petals();
  embers();
  pool();
  redThread();   // the one that belongs to neither
  grain();
  vignette();

  // ---------- helpers ----------

  function backgroundGradient() {
    noStroke();
    const top = color(9, 11, 32), mt = color(21, 15, 44);
    const mb = color(28, 13, 34), bot = color(10, 6, 18);
    for (let y = 0; y < 2000; y++) {
      let c;
      if (y < 800) c = lerpColor(top, mt, y / 800);
      else if (y < 1300) c = lerpColor(mt, mb, (y - 800) / 500);
      else c = lerpColor(mb, bot, (y - 1300) / 700);
      fill(c);
      rect(0, y, 1600, 1);
    }
  }

  function glow(x, y, r, cr, cg, cb, peakA, layers) {
    noStroke();
    for (let i = 0; i < layers; i++) {
      const t = i / (layers - 1);
      const rr = r * (1 - t * 0.94);
      fill(cr, cg, cb, peakA * t * t);
      ellipse(x, y, rr * 2, rr * 2);
    }
  }

  function nebulae() {
    glow(300, 400, 500, 30, 40, 80, 26, 20);
    glow(1300, 300, 420, 46, 34, 70, 20, 20);
    glow(1350, 1500, 520, 40, 26, 54, 22, 20);
    glow(260, 1600, 460, 22, 40, 58, 22, 20);
    glow(WX, WY, 620, 110, 52, 58, 16, 24);
  }

  function speckles() {
    noStroke();
    for (let i = 0; i < 16000; i++) {
      const x = random(1600), y = random(2000);
      const n = noise(x * 0.004, y * 0.004);
      let r, g, b;
      if (n < 0.42) { r = 30; g = 38; b = 80; }
      else if (n < 0.68) { r = 48; g = 30; b = 70; }
      else if (n < 0.86) { r = 24; g = 48; b = 64; }
      else { r = 58; g = 34; b = 52; }
      fill(r, g, b, 4 + random() * 11);
      const s = 1 + random() * 2.2;
      ellipse(x, y, s, s);
    }
  }

  function stars() {
    noStroke();
    for (let i = 0; i < 240; i++) {
      const x = random(1600), y = random(40, 640);
      const a = 40 + 150 * (1 - y / 640);
      fill(random() < 0.7 ? color(235, 240, 255, a) : color(255, 230, 180, a));
      ellipse(x, y, 0.8 + random() * 1.3, 0.8 + random() * 1.3);
    }
  }

  function halo(R0, alp, wgt) {
    noFill();
    stroke(255, 226, 168, alp);
    strokeWeight(wgt);
    let drawing = false;
    beginShape();
    for (let a = 0; a <= TWO_PI + 0.02; a += 0.045) {
      const gap = noise(20 + Math.cos(a) * 1.5, 20 + Math.sin(a) * 1.5, R0 * 0.013) < 0.10;
      if (gap) { if (drawing) { endShape(); drawing = false; } continue; }
      if (!drawing) { beginShape(); drawing = true; }
      const rr = R0 + (noise(40 + Math.cos(a) * 2 + R0 * 0.05, 40 + Math.sin(a) * 2) - 0.5) * 26;
      vertex(WX + Math.cos(a) * rr, WY + Math.sin(a) * rr * 1.04);
    }
    if (drawing) endShape();
  }

  function blobPath(cx, cy, R, scale, zoff, noff) {
    beginShape();
    const n = 96;
    for (let i = 0; i <= n; i++) {
      const a = i / n * TWO_PI;
      const w = noise(noff + Math.cos(a) * 1.3 + 3, noff + Math.sin(a) * 1.3 + 7, zoff);
      const rr = R * scale * (0.80 + 0.34 * w);
      vertex(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr * 1.06);
    }
    endShape(CLOSE);
  }

  function drawForm(f, deep, mid, bright, edge, noff, faceAng) {
    glow(f.x, f.y, f.R * 1.15, deep[0], deep[1], deep[2], 30, 26);
    const L = 26;
    for (let k = 0; k < L; k++) {
      const t = k / (L - 1);
      const s = 1.05 - t * 0.8;
      const c = lerpColor(color(deep[0], deep[1], deep[2], 12),
        color(bright[0], bright[1], bright[2], 22), t);
      fill(c); noStroke();
      blobPath(f.x + (noise(noff + k * 0.31) - 0.5) * 30,
        f.y + (noise(noff + 40 + k * 0.27) - 0.5) * 30, f.R, s, k * 0.34, noff);
    }
    for (let k = 0; k < 16; k++) {           // veils
      const t = k / 15, s = 1.05 - t * 0.82;
      stroke(edge[0], edge[1], edge[2], 8 + 24 * t);
      strokeWeight(0.8); noFill();
      blobPath(f.x, f.y, f.R, s, k * 0.37 + 2.5, noff + 13);
    }
    for (let k = 0; k < 10; k++) {           // bright rim turned toward the other
      const t = k / 9, s = 1.02 - t * 0.7;
      stroke(bright[0], bright[1], bright[2], 14 + 40 * t);
      strokeWeight(1.0); noFill();
      beginShape();
      for (let a = faceAng - 1.15; a <= faceAng + 1.15; a += 0.06) {
        const w = noise(noff + 13 + Math.cos(a) * 1.3 + 3, noff + 13 + Math.sin(a) * 1.3 + 7, k * 0.4 + 2.5);
        const rr = f.R * s * (0.80 + 0.34 * w);
        vertex(f.x + Math.cos(a) * rr, f.y + Math.sin(a) * rr * 1.06);
      }
      endShape();
    }
    glow(f.x, f.y, f.R * 0.5, mid[0], mid[1], mid[2], 34, 24);
  }

  function lensBoundsY(y) {
    const dyA = y - A.y, dyB = y - B.y;
    if (Math.abs(dyA) > RR || Math.abs(dyB) > RR) return null;
    const hA = Math.sqrt(RR * RR - dyA * dyA), hB = Math.sqrt(RR * RR - dyB * dyB);
    const lo = Math.max(A.x - hA, B.x - hB), hi = Math.min(A.x + hA, B.x + hB);
    return (hi - lo < 14) ? null : [lo, hi];
  }

  function lensBoundsX(x) {
    const dxA = x - A.x, dxB = x - B.x;
    if (Math.abs(dxA) > RR || Math.abs(dxB) > RR) return null;
    const vA = Math.sqrt(RR * RR - dxA * dxA), vB = Math.sqrt(RR * RR - dxB * dxB);
    const lo = Math.max(A.y - vA, B.y - vB), hi = Math.min(A.y + vA, B.y + vB);
    return (hi - lo < 16) ? null : [lo, hi];
  }

  function warpThreads() {
    noFill();
    for (let j = 0; j < 40; j++) {
      const x = WX + (random() - 0.5) * 185;
      const b = lensBoundsX(x);
      if (!b) continue;
      stroke(255, 236, 190, 14 + random() * 22);
      strokeWeight(0.7 + random() * 0.6);
      beginShape();
      for (let y = b[0] + 8; y <= b[1] - 8; y += 14) {
        const xx = x + Math.sin((y - b[0]) * 0.02 + j) * 6 + (noise(j * 3.1, y * 0.01) - 0.5) * 18;
        vertex(xx, y);
      }
      endShape();
    }
  }

  function weftThreads() {
    noFill();
    for (let i = 0; i < 190; i++) {
      const y = random(660, 1300);
      const b = lensBoundsY(y);
      if (!b) continue;
      let xL = b[0] + random() * 12, xR = b[1] - random() * 12;
      const bow = (noise(i * 0.37) - 0.5) * 96;
      const pick = random();
      let r, g, bl, al;
      if (pick < 0.62) { r = 255; g = 222; bl = 152; al = 20 + random() * 38; }
      else if (pick < 0.84) { r = 255; g = 240; bl = 214; al = 16 + random() * 30; }
      else { r = 255; g = 176; bl = 120; al = 14 + random() * 26; }
      stroke(r, g, bl, al);
      strokeWeight(0.7 + random() * 1.1);
      bezier(xL, y, xL + (xR - xL) * 0.34, y + bow, xL + (xR - xL) * 0.66, y + bow * 0.55, xR, y);
    }
  }

  function arcPoly(cx, cy, r, a0, a1, zoff) {
    if (a1 < a0) a1 += TWO_PI;
    const n = 64;
    beginShape();
    for (let i = 0; i <= n; i++) {
      const a = lerp(a0, a1, i / n);
      const rr = r + (noise(zoff + Math.cos(a) * 1.8, zoff + Math.sin(a) * 1.8) - 0.5) * 14;
      vertex(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
    }
    endShape();
  }

  function lensOutline() {
    const Mx = (A.x + B.x) / 2, My = (A.y + B.y) / 2;
    const d = dist(A.x, A.y, B.x, B.y);
    const h = Math.sqrt(RR * RR - d * d / 4);
    const ux = (B.x - A.x) / d, uy = (B.y - A.y) / d;
    const px = -uy, py = ux;
    const P1 = [Mx + px * h, My + py * h], P2 = [Mx - px * h, My - py * h];
    const aA2 = Math.atan2(P2[1] - A.y, P2[0] - A.x), aA1 = Math.atan2(P1[1] - A.y, P1[0] - A.x);
    const aB1 = Math.atan2(P1[1] - B.y, P1[0] - B.x), aB2 = Math.atan2(P2[1] - B.y, P2[0] - B.x);
    noFill();
    stroke(255, 226, 168, 26); strokeWeight(3.2);
    arcPoly(A.x, A.y, RR, aA2, aA1, 61); arcPoly(B.x, B.y, RR, aB1, aB2, 77);
    stroke(255, 236, 185, 90); strokeWeight(1.3);
    arcPoly(A.x, A.y, RR, aA2, aA1, 61); arcPoly(B.x, B.y, RR, aB1, aB2, 77);
  }

  function filaments() {
    for (let i = 0; i < 260; i++) {
      let x, y;
      if (i < 170) { x = random(700, 900); y = random(860, 1150); }
      else {
        const f = random() < 0.5 ? A : B;
        x = f.x + (random() - 0.5) * f.R * 1.3;
        y = f.y - random(f.R * 0.2, f.R * 0.95);
      }
      const steps = floor(random(40, 92));
      const gold = random() < 0.75;
      const r = 255, g = gold ? 222 : 244, b = gold ? 160 : 235;
      let px = x, py = y;
      for (let s = 0; s < steps; s++) {
        const ang = -HALF_PI + (noise(x * 0.0024 + 3.1, y * 0.0024 + 8.7) - 0.5) * 2.6 + (x - WX) * 0.00018;
        x += Math.cos(ang) * 7; y += Math.sin(ang) * 7;
        const fade = 1 - s / steps;
        stroke(r, g, b, (10 + 55 * fade) * random(0.5, 1));
        strokeWeight(0.6 + fade * 0.8);
        line(px, py, x, y);
        px = x; py = y;
      }
    }
  }

  function roots() {
    for (let i = 0; i < 110; i++) {
      const f = random() < 0.5 ? A : B;
      const warm = (f === A);
      let x = f.x + (random() - 0.5) * f.R * 1.1;
      let y = f.y + f.R * random(0.45, 0.85);
      let px = x, py = y;
      const steps = floor(random(30, 70));
      for (let s = 0; s < steps; s++) {
        const ang = HALF_PI + (noise(x * 0.003 + 12.3, y * 0.003 + 4.6) - 0.5) * 1.8;
        x += Math.cos(ang) * 6; y += Math.sin(ang) * 6;
        const fade = 1 - s / steps;
        stroke(warm ? color(200, 120, 86, 8 + 30 * fade) : color(110, 140, 190, 8 + 30 * fade));
        strokeWeight(0.5 + fade * 0.8);
        line(px, py, x, y);
        px = x; py = y;
        if (y > 1950) break;
      }
    }
  }

  function petals() {
    noFill();
    for (let i = 0; i < 46; i++) {
      const x = random(1600), y = random(500, 1600);
      if (Math.abs(x - WX) < 230 && Math.abs(y - WY) < 420) continue;
      const s = random(8, 26);
      const warm = x < WX;
      stroke(warm ? color(255, 170, 120, 26 + random() * 40) : color(150, 185, 240, 26 + random() * 40));
      strokeWeight(1);
      const a0 = random(TWO_PI);
      arc(x, y, s, s, a0, a0 + random(0.9, 2.6));
    }
  }

  function embers() {
    for (let i = 0; i < 1500; i++) {
      const x = WX + (random() + random() - 1) * 900;
      const y = 990 + (random() + random() - 1) * 860;
      if (x < 0 || x > 1600 || y < 0 || y > 2000) continue;
      let r, g, b;
      const dx = x - WX;
      if (Math.abs(dx) < 170) { r = 255; g = 224; b = 168; }
      else if (dx < 0) { r = 255; g = 150; b = 100; }
      else { r = 160; g = 190; b = 240; }
      const sz = 0.8 + random() * 2.4;
      noStroke();
      fill(r, g, b, 30 + random() * 130);
      ellipse(x, y, sz, sz);
      if (random() < 0.03) glow(x, y, sz * 5, r, g, b, 26, 10);
    }
  }

  function pool() {
    glow(800, 1900, 400, 90, 40, 34, 32, 24);
    noStroke();
    for (let i = 0; i < 520; i++) {
      const x = 800 + (random() + random() - 1) * 540;
      const y = 1905 + (random() + random() - 1) * 95;
      if (y < 1810 || y > 1995) continue;
      const pick = random();
      fill(pick < 0.6 ? color(255, 190, 120, 30 + random() * 120)
        : pick < 0.85 ? color(190, 160, 220, 24 + random() * 90)
          : color(255, 235, 200, 40 + random() * 120));
      const s = 1 + random() * 2.4;
      ellipse(x, y, s, s);
    }
  }

  function redThread() {
    const pts = [];
    const N = 280;
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const x = -60 + t * 1720;
      let y = lerp(1790, 235, t) + (noise(5.2 + t * 3.6) - 0.5) * 360;
      const pull = Math.exp(-Math.pow((x - WX) / 330, 2));
      y = lerp(y, WY, pull * 0.4);
      pts.push([x, y]);
    }
    function pass(wgt, r, g, b, al) {
      stroke(r, g, b, al); strokeWeight(wgt); noFill();
      beginShape();
      curveVertex(pts[0][0], pts[0][1]);
      for (const p of pts) curveVertex(p[0], p[1]);
      curveVertex(pts[N][0], pts[N][1]);
      endShape();
    }
    pass(6, 170, 38, 52, 26);
    pass(2.1, 208, 54, 64, 120);
    pass(0.9, 255, 122, 112, 210);
    for (const k of [70, 140, 215]) {
      glow(pts[k][0], pts[k][1], 10, 225, 60, 66, 80, 12);
      noStroke(); fill(255, 130, 118, 225);
      ellipse(pts[k][0], pts[k][1], 4, 4);
    }
  }

  function grain() {
    noStroke();
    for (let i = 0; i < 5200; i++) {
      const v = random() < 0.5 ? 215 : 18;
      fill(v, v, v, 3 + random() * 4);
      rect(random(1600), random(2000), 1, 1);
    }
  }

  function vignette() {
    for (let x = 0; x < 240; x += 2) {
      const tt = 1 - x / 240;
      stroke(7, 5, 16, 24 * tt * tt); strokeWeight(2);
      line(x, 0, x, 2000);
      line(1600 - x, 0, 1600 - x, 2000);
    }
    for (let y = 0; y < 240; y += 2) {
      const tt = 1 - y / 240;
      stroke(7, 5, 16, 22 * tt * tt); strokeWeight(2);
      line(0, y, 1600, y);
    }
    for (let y = 0; y < 340; y += 2) {
      const tt = 1 - y / 340;
      stroke(7, 5, 16, 24 * tt * tt); strokeWeight(2);
      line(0, 2000 - y, 1600, 2000 - y);
    }
    noFill();
    for (let d = 1620; d <= 2700; d += 30) {
      const t = (d - 1620) / 1080;
      stroke(7, 5, 16, 3 + 16 * t); strokeWeight(34);
      ellipse(800, 1000, d, d * 1.25);
    }
  }
}

let A, B, Mv, DAB;
const W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  blendMode(BLEND);
  A = createVector(640, 720);
  B = createVector(960, 1280);
  Mv = createVector((A.x + B.x) / 2, (A.y + B.y) / 2);
  DAB = p5.Vector.dist(A, B);

  paintGround();
  blendMode(SCREEN);
  paintDust();
  paintFlows();
  paintVesica();
  paintHeartGlow();
  paintBraid();
  paintWell(A, [255, 158, 110], [255, 214, 165]);
  paintWell(B, [150, 212, 195], [255, 228, 185]);
  paintGoldenPath();
  paintDriftEmbers();
  blendMode(BLEND);
  paintVignette();
  paintGrain();
}

function paintGround() {
  noStroke();
  const top = [12, 19, 24], bot = [26, 17, 21];
  for (let y = 0; y < H; y += 4) {
    const t = y / H;
    fill(lerp(top[0], bot[0], t), lerp(top[1], bot[1], t), lerp(top[2], bot[2], t));
    rect(-10, y, W + 20, 5);
  }
  const tints = [[28, 58, 62], [66, 30, 38], [64, 50, 26], [24, 44, 54],
                 [58, 26, 44], [40, 52, 34], [52, 34, 26], [30, 40, 52]];
  for (let i = 0; i < 8; i++) {
    radialGlow(random(W), random(H), random(380, 860), tints[i % tints.length], random(0.05, 0.11));
  }
}

function paintDust() {
  noStroke();
  for (let i = 0; i < 620; i++) {
    const warm = random() < 0.35;
    fill(warm ? color(255, 226, 180, random(14, 52)) : color(190, 214, 224, random(14, 52)));
    circle(random(W), random(H), random(0.8, 2.4));
  }
}

function paintFlows() {
  noFill();
  const wells = [{ p: A, s: 1 }, { p: B, s: -1 }];
  function field(x, y) {
    let vx = 1.0, vy = 0.05 + (noise(x * 0.0011, y * 0.0011) - 0.5) * 0.85;
    for (const w of wells) {
      const dx = x - w.p.x, dy = y - w.p.y;
      const r = Math.max(Math.hypot(dx, dy), 24);
      const ux = dx / r, uy = dy / r;
      const pull = 2.35 * 67600 / (67600 + r * r);
      vx -= ux * pull; vy -= uy * pull;
      const sw = 1.3 * Math.exp(-(r * r) / 96000);
      if (w.s > 0) { vx += -uy * sw; vy += ux * sw; }
      else { vx += uy * sw; vy += -ux * sw; }
    }
    return { x: vx, y: vy };
  }
  const lines = [];
  const NL = 1000;
  for (let i = 0; i < NL; i++) {
    let x = -30 - random(90), y = random(-140, H + 140);
    const pts = [];
    let dmin = 1e9, absorbed = false;
    for (let s = 0; s < 900; s++) {
      if (s % 2 === 0) pts.push([x, y]);
      const dm = Math.hypot(x - Mv.x, y - Mv.y);
      if (dm < dmin) dmin = dm;
      const f = field(x, y);
      const m = Math.hypot(f.x, f.y) || 1;
      x += f.x / m * 2.4; y += f.y / m * 2.4;
      if (x > W + 50 || y < -180 || y > H + 180) break;
      if (Math.hypot(x - A.x, y - A.y) < 34 || Math.hypot(x - B.x, y - B.y) < 34) {
        absorbed = true; pts.push([x, y]); break;
      }
    }
    lines.push({ pts, dmin, absorbed, hero: false });
  }
  for (let h = 0; h < 22; h++) lines[floor(random(NL))].hero = true;

  for (const L of lines) {
    const n = L.pts.length;
    if (n < 8) continue;
    const t = constrain(map(L.dmin, 740, 60, 0, 1), 0, 1);
    let c;
    if (t < 0.55) c = mix3([112, 148, 168], [228, 122, 104], t / 0.55);
    else c = mix3([228, 122, 104], [255, 208, 130], (t - 0.55) / 0.45);
    let al = 8 + t * 22 + (L.absorbed ? 7 : 0);
    let wg = 0.7 + t * 1.15;
    if (L.hero) { al = min(64, al * 1.9); wg += 0.7; c = mix3(c, [255, 240, 214], 0.35); }
    const last = L.pts[n - 1];
    const endScale = (last[0] > W + 30 || L.absorbed) ? 1 : 0.18;
    const i1 = floor(n * 0.07), i2 = floor(n * 0.9);
    polySeg(L.pts, 0, i1, c, al * 0.25, wg);
    polySeg(L.pts, i1, i2, c, al, wg);
    polySeg(L.pts, i2, n - 1, c, al * endScale, wg);
    if (L.absorbed) radialGlow(last[0], last[1], 30, [255, 232, 190], 0.5);
  }
}

function paintVesica() {
  noStroke();
  const ang = atan2(B.y - A.y, B.x - A.x);
  dottedArc(A.x, A.y, DAB, ang - 0.85, ang + 0.85);
  dottedArc(B.x, B.y, DAB, ang + PI - 0.85, ang + PI + 0.85);
}

function dottedArc(cx, cy, r, a0, a1) {
  for (let a = a0; a <= a1; a += 0.013) {
    const x = cx + cos(a) * r, y = cy + sin(a) * r;
    if (x < -10 || x > W + 10 || y < -10 || y > H + 10) continue;
    fill(238, 210, 152, 24);
    circle(x, y, 2.1);
  }
}

function paintHeartGlow() {
  radialGlow(Mv.x, Mv.y, 360, [255, 178, 100], 0.16);
  radialGlow(Mv.x, Mv.y, 190, [255, 208, 140], 0.22);
  radialGlow(Mv.x, Mv.y, 90, [255, 236, 190], 0.30);
}

function paintBraid() {
  noFill();
  const dir = p5.Vector.sub(B, A).normalize();
  const perp = createVector(-dir.y, dir.x);
  const NT = 26;
  for (let k = 0; k < NT; k++) {
    const u = (k + 0.5) / NT;
    const off = (u - 0.5) * 2;
    const bulge = off * 140 + random(-16, 16);
    const p0 = p5.Vector.add(A, p5.Vector.add(p5.Vector.mult(dir, 20), p5.Vector.mult(perp, random(-30, 30))));
    const p1 = p5.Vector.add(B, p5.Vector.add(p5.Vector.mult(dir, -20), p5.Vector.mult(perp, random(-30, 30))));
    const ctrl = p5.Vector.add(Mv, p5.Vector.mult(perp, bulge * 1.7));
    const pts = [];
    const S = 64;
    for (let s = 0; s <= S; s++) {
      const t = s / S;
      const x = (1 - t) * (1 - t) * p0.x + 2 * (1 - t) * t * ctrl.x + t * t * p1.x;
      const y = (1 - t) * (1 - t) * p0.y + 2 * (1 - t) * t * ctrl.y + t * t * p1.y;
      const wob = (noise(k * 13.7 + t * 4.2, t * 3.1) - 0.5) * 26 * sin(t * PI);
      pts.push([x + perp.x * wob, y + perp.y * wob]);
    }
    const central = 1 - abs(off);
    const heroT = central > 0.8 && k % 4 === 0;
    const base = mix3([255, 196, 128], [255, 232, 190], random());
    const segs = 8;
    for (let g = 0; g < segs; g++) {
      const i0 = floor(g * S / segs), i1 = floor((g + 1) * S / segs);
      const tm = (g + 0.5) / segs;
      const col = mix3(base, [255, 240, 214], 0.35 * sin(tm * PI));
      stroke(col[0], col[1], col[2], (14 + central * 26) * (heroT ? 1.8 : 1));
      strokeWeight(heroT ? 2.2 : 0.9 + central * 1.1);
      beginShape();
      for (let i = i0; i <= i1; i++) vertex(pts[i][0], pts[i][1]);
      endShape();
    }
  }
}

function paintWell(P, glowC, ringC) {
  radialGlow(P.x, P.y, 330, glowC, 0.16);
  radialGlow(P.x, P.y, 150, glowC, 0.28);
  radialGlow(P.x, P.y, 60, [255, 242, 222], 0.55);
  noStroke();
  fill(255, 248, 236, 240);
  circle(P.x, P.y, 13);
  noFill();
  const ctx = drawingContext;
  const radii = [92, 148, 212];
  for (let i = 0; i < radii.length; i++) {
    const r = radii[i] + random(-8, 8);
    const a0 = random(TWO_PI);
    ctx.setLineDash([2, 9]);
    stroke(ringC[0], ringC[1], ringC[2], 34 + i * 6);
    strokeWeight(1.1);
    arc(P.x, P.y, r * 2, r * 2, a0, a0 + random(2.4, 5.4));
  }
  ctx.setLineDash([]);
  noStroke();
  for (let i = 0; i < 74; i++) {
    const r = radii[floor(random(radii.length))] + random(-16, 16);
    const a = random(TWO_PI);
    const x = P.x + cos(a) * r, y = P.y + sin(a) * r;
    const s = random(1.6, 4.4);
    const c = mix3(glowC, [255, 246, 226], random() * 0.7);
    if (random() < 0.14) {
      fill(c[0], c[1], c[2], 26);
      circle(x, y, s * 3.4);
    }
    fill(c[0], c[1], c[2], random(70, 190));
    circle(x, y, s);
  }
}

function paintGoldenPath() {
  const pts = [];
  pts.push([230, -80]);
  pts.push([360, 300]);
  for (let a = 205; a >= 40; a -= 5) pts.push([A.x + cos(radians(a)) * 132, A.y + sin(radians(a)) * 132]);
  pts.push([Mv.x + 10, Mv.y]);
  for (let a = 240; a <= 430; a += 5) pts.push([B.x + cos(radians(a)) * 150, B.y + sin(radians(a)) * 150]);
  pts.push([1180, 1680]);
  pts.push([1310, 2140]);
  for (let i = 0; i < pts.length; i++) {
    pts[i][0] += (noise(i * 0.31, 7.7) - 0.5) * 16;
    pts[i][1] += (noise(i * 0.31, 17.3) - 0.5) * 16;
  }
  noFill();
  curveTightness(0.05);
  const passes = [[8.5, 26, [255, 172, 104]], [3.6, 90, [255, 212, 148]], [1.7, 210, [255, 240, 206]]];
  for (const p of passes) {
    stroke(p[2][0], p[2][1], p[2][2], p[1]);
    strokeWeight(p[0]);
    beginShape();
    curveVertex(pts[0][0], pts[0][1]);
    for (const q of pts) curveVertex(q[0], q[1]);
    curveVertex(pts[pts.length - 1][0], pts[pts.length - 1][1]);
    endShape();
  }
}

function paintDriftEmbers() {
  noStroke();
  const dir = p5.Vector.sub(B, A).normalize();
  const perp = createVector(-dir.y, dir.x);
  for (let i = 0; i < 46; i++) {
    const t = random(-0.25, 1.25);
    const o = random(-190, 190);
    const x = Mv.x + dir.x * (t - 0.5) * DAB * 1.3 + perp.x * o;
    const y = Mv.y + dir.y * (t - 0.5) * DAB * 1.3 + perp.y * o;
    if (x < 0 || x > W || y < 0 || y > H) continue;
    const c = mix3([255, 208, 140], [255, 240, 214], random());
    fill(c[0], c[1], c[2], random(36, 130));
    circle(x, y, random(1.4, 3.6));
  }
}

function paintVignette() {
  blendMode(MULTIPLY);
  const ctx = drawingContext;
  let g = ctx.createRadialGradient(W / 2, H * 0.49, 560, W / 2, H * 0.49, 1480);
  g.addColorStop(0, 'rgba(10,12,16,0)');
  g.addColorStop(1, 'rgba(10,12,16,0.62)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  g = ctx.createLinearGradient(0, H * 0.78, 0, H);
  g.addColorStop(0, 'rgba(8,10,14,0)');
  g.addColorStop(1, 'rgba(8,10,14,0.5)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  g = ctx.createLinearGradient(0, 0, 0, H * 0.14);
  g.addColorStop(0, 'rgba(8,10,14,0.4)');
  g.addColorStop(1, 'rgba(8,10,14,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  blendMode(BLEND);
}

function paintGrain() {
  noStroke();
  for (let i = 0; i < 6200; i++) {
    if (random() < 0.55) fill(4, 6, 12, random(8, 20));
    else fill(255, 236, 208, random(5, 14));
    rect(random(W), random(H), random(1, 2.1), random(1, 2.1));
  }
}

function radialGlow(x, y, r, c, a) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, `rgba(${c[0]},${c[1]},${c[2]},${a})`);
  g.addColorStop(0.55, `rgba(${c[0]},${c[1]},${c[2]},${a * 0.45})`);
  g.addColorStop(1, `rgba(${c[0]},${c[1]},${c[2]},0)`);
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function polySeg(pts, i0, i1, c, al, wg) {
  if (i1 <= i0) return;
  stroke(c[0], c[1], c[2], al);
  strokeWeight(wg);
  beginShape();
  for (let i = i0; i <= i1; i++) vertex(pts[i][0], pts[i][1]);
  endShape();
}

function mix3(c1, c2, t) {
  return [lerp(c1[0], c2[0], t), lerp(c1[1], c2[1], t), lerp(c1[2], c2[2], t)];
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  background(11, 13, 23);

  softGlow(800, 1030, 850, 1050, [61, 34, 54], 1.5, 110);
  softGlow(800, 1000, 570, 820, [105, 57, 45], 1.1, 100);
  paintGround();

  const left = {
    cx: 535, cy: 1030, rx: 410, ry: 690,
    tilt: -0.10, phase: 2.1, side: -1,
    base: [116, 40, 55],
    light: [213, 107, 87],
    palette: [
      [83, 29, 48], [121, 39, 52], [158, 52, 58],
      [187, 72, 67], [211, 105, 82], [230, 151, 112]
    ]
  };

  const right = {
    cx: 1060, cy: 970, rx: 385, ry: 655,
    tilt: 0.09, phase: 7.7, side: 1,
    base: [20, 66, 80],
    light: [102, 165, 150],
    palette: [
      [15, 43, 62], [20, 65, 79], [27, 91, 101],
      [46, 119, 120], [85, 149, 139], [151, 184, 156]
    ]
  };

  paintForm(left);
  paintForm(right);

  softGlow(800, 1000, 370, 690, [193, 112, 61], 1.25, 130);
  softGlow(800, 1000, 205, 520, [232, 165, 91], 1.0, 110);
  paintSharedAtmosphere();
  paintFilaments();
  paintGoldDust();

  softGlow(800, 1000, 112, 255, [248, 216, 153], 1.6, 90);
  blendMode(SCREEN);
  noStroke();
  fill(247, 220, 165, 125);
  lensPath(0.27);
  fill(255, 241, 205, 115);
  lensPath(0.17);
  blendMode(BLEND);

  paintSurfaceGrain();
  paintVignette();

  noLoop();
}

function softGlow(x, y, rx, ry, c, alpha, steps) {
  blendMode(SCREEN);
  noStroke();
  for (let i = steps; i > 0; i--) {
    const t = i / steps;
    fill(c[0], c[1], c[2], alpha);
    ellipse(x, y, 2 * rx * t, 2 * ry * t);
  }
  blendMode(BLEND);
}

function paintGround() {
  const colors = [
    [79, 42, 61], [31, 48, 70],
    [91, 52, 43], [39, 38, 57], [24, 29, 44]
  ];

  for (let i = 0; i < 2100; i++) {
    const x = random(width);
    const y = random(height);
    const c = random(colors);
    const a = (noise(x * 0.0015, y * 0.0015) - 0.5) * 3.4 - HALF_PI;
    const len = random(18, 145);

    stroke(c[0], c[1], c[2], random(4, 17));
    strokeWeight(random(1, 8));
    line(
      x - cos(a) * len * 0.5,
      y - sin(a) * len * 0.5,
      x + cos(a) * len * 0.5,
      y + sin(a) * len * 0.5
    );
  }
}

function formPoint(f, a, s) {
  const n = noise(
    f.phase + 3 + cos(a) * 1.45,
    f.phase + 8 + sin(a) * 1.45
  );
  const r = s * (
    1 +
    0.038 * sin(3 * a + f.phase) +
    0.022 * sin(7 * a - f.phase) +
    0.055 * (n - 0.5)
  );

  const px = f.rx * r * cos(a);
  const py = f.ry * r * sin(a);

  return {
    x: f.cx + px * cos(f.tilt) - py * sin(f.tilt),
    y: f.cy + px * sin(f.tilt) + py * cos(f.tilt)
  };
}

function closedCurve(points) {
  beginShape();
  const last = points[points.length - 1];
  curveVertex(last.x, last.y);
  for (const p of points) curveVertex(p.x, p.y);
  curveVertex(points[0].x, points[0].y);
  curveVertex(points[1].x, points[1].y);
  endShape(CLOSE);
}

function formContour(f, s) {
  const points = [];
  for (let i = 0; i < 180; i++) {
    points.push(formPoint(f, i / 180 * TWO_PI, s));
  }
  return points;
}

function sampleInForm(f, limit) {
  while (true) {
    const x = random(f.cx - f.rx * 1.05, f.cx + f.rx * 1.05);
    const y = random(f.cy - f.ry * 1.05, f.cy + f.ry * 1.05);
    const dx = x - f.cx;
    const dy = y - f.cy;
    const ux = dx * cos(f.tilt) + dy * sin(f.tilt);
    const uy = -dx * sin(f.tilt) + dy * cos(f.tilt);
    const q = sq(ux / f.rx) + sq(uy / f.ry);
    if (q < limit) return { x, y };
  }
}

function paintForm(f) {
  noStroke();
  fill(f.base[0], f.base[1], f.base[2], 210);
  closedCurve(formContour(f, 1));

  const dark = color(f.base[0], f.base[1], f.base[2]);
  const light = color(f.light[0], f.light[1], f.light[2]);

  for (let j = 0; j < 24; j++) {
    const c = lerpColor(dark, light, j / 25);
    c.setAlpha(7);
    fill(c);
    closedCurve(formContour(f, 0.985 - j * 0.019));
  }

  for (let i = 0; i < 210; i++) {
    const p = sampleInForm(f, 0.78);
    const c = random(f.palette);
    const a = -HALF_PI +
      (noise(p.x * 0.002, p.y * 0.002, f.phase) - 0.5) * 1.5;
    const len = random(90, 290);

    stroke(c[0], c[1], c[2], random(3, 9));
    strokeWeight(random(10, 34));
    line(
      p.x - cos(a) * len * 0.5,
      p.y - sin(a) * len * 0.5,
      p.x + cos(a) * len * 0.5,
      p.y + sin(a) * len * 0.5
    );
  }

  for (let i = 0; i < 6200; i++) {
    const p = sampleInForm(f, 0.94);
    let index = floor(pow(random(), 1.5) * f.palette.length);

    const facing = f.side < 0
      ? (p.x - (f.cx - f.rx)) / (2 * f.rx)
      : ((f.cx + f.rx) - p.x) / (2 * f.rx);

    if (facing > 0.7 && random() < 0.32) {
      index = min(f.palette.length - 1, index + 1);
    }

    const c = f.palette[index];
    const a = -HALF_PI +
      (noise(p.x * 0.0027, p.y * 0.0027, f.phase) - 0.5) * 1.8;
    const len = random(8, 54) * (random() < 0.035 ? 2.8 : 1);

    stroke(c[0], c[1], c[2], random(9, 39));
    strokeWeight(random(0.6, 3.6));
    line(
      p.x - cos(a) * len * 0.5,
      p.y - sin(a) * len * 0.5,
      p.x + cos(a) * len * 0.5,
      p.y + sin(a) * len * 0.5
    );
  }

  noFill();
  for (let i = 0; i < 340; i++) {
    const start = random(TWO_PI);
    const span = random(0.018, 0.13);
    const scale = random(0.80, 1.015);
    const c = random(f.palette);

    stroke(c[0], c[1], c[2], random(12, 48));
    strokeWeight(random(0.5, 2.1));
    beginShape();
    for (let j = 0; j <= 9; j++) {
      const p = formPoint(f, start + span * j / 9, scale);
      vertex(p.x, p.y);
    }
    endShape();
  }
}

function lensPath(s) {
  const points = [];

  for (let i = 0; i < 180; i++) {
    const a = i / 180 * TWO_PI;
    const sy = sin(a);
    const side = sy > 0 ? 1 : 0.86;
    const wobble = 1 + 0.035 * sin(5 * a + 1.4) + 0.018 * sin(9 * a);

    points.push({
      x: 800 +
        145 * s * sy * pow(abs(sy), 0.52) * side * wobble +
        9 * s * sin(2 * a),
      y: 1000 - 580 * s * cos(a) + 6 * s * sin(3 * a)
    });
  }

  closedCurve(points);
}

function paintSharedAtmosphere() {
  blendMode(SCREEN);
  noStroke();
  fill(192, 112, 65, 24);
  lensPath(1.04);

  for (let i = 0; i < 74; i++) {
    const t = i / 73;
    fill(
      212 + 22 * t,
      133 + 35 * t,
      72 + 28 * t,
      1.8
    );
    lensPath(1.03 - 0.85 * t);
  }
  blendMode(BLEND);
}

function paintFilaments() {
  noFill();

  for (let i = 0; i < 88; i++) {
    const y1 = random(500, 1500);
    const y2 = constrain(y1 + random(-170, 170), 470, 1530);
    const x1 = random(625, 770);
    const x2 = random(830, 975);
    const warm = random() < 0.72;

    if (warm) {
      stroke(235, 185, 111, random(20, 78));
    } else {
      stroke(249, 220, 161, random(22, 68));
    }

    strokeWeight(random(0.35, 1.45));
    bezier(
      x1, y1,
      random(690, 805), y1 + random(-240, 240),
      random(795, 910), y2 + random(-240, 240),
      x2, y2
    );
  }

  for (let i = 0; i < 48; i++) {
    const rx = random(65, 255);
    const ry = random(170, 510);
