function radialGlow(x, y, r, sx, sy, strength) {
  push();
  translate(x, y);
  scale(sx, sy);
  blendMode(SCREEN);

  const ctx = drawingContext;
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
  g.addColorStop(0, `rgba(255,225,174,${0.19 * strength})`);
  g.addColorStop(0.22, `rgba(246,180,125,${0.13 * strength})`);
  g.addColorStop(0.52, `rgba(197,106,100,${0.065 * strength})`);
  g.addColorStop(1, "rgba(120,70,100,0)");

  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, TWO_PI);
  ctx.fill();
  pop();
  blendMode(BLEND);
}

