function contourPoint(cx, cy, rx, ry, rot, phase, a, sc = 1) {
  const ca = cos(a);
  const sa = sin(a);
  const n = noise(ca * 1.4 + phase, sa * 1.4 + phase * 0.61);
  const rr = (
    0.89 +
    0.17 * n +
    0.035 * sin(3 * a + phase) +
    0.018 * sin(7 * a - phase)
  ) * sc;

  let u = rx * ca * rr;
  const v = ry * sa * rr;

  u *= 0.94 + 0.09 * sa;
  u += rx * 0.045 * sin((v / ry) * 2.2 + phase) * sc;

  return {
    x: cx + u * cos(rot) - v * sin(rot),
    y: cy + u * sin(rot) + v * cos(rot)
  };
}

function presencePath(cx, cy, rx, ry, rot, phase, sc = 1, dx = 0, dy = 0) {
  beginShape();
  for (let i = 0; i <= 160; i++) {
    const a = (i / 160) * TWO_PI;
    const p = contourPoint(cx + dx, cy + dy, rx, ry, rot, phase, a, sc);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);
}

function paintPresence(cx, cy, rx, ry, rot, phase, facing, pal) {
  push();
  noStroke();

  fill(7, 9, 18, 105);
  presencePath(cx + 14, cy + 25, rx, ry, rot, phase, 1.055);

  fill(pal[0][0], pal[0][1], pal[0][2], 255);
  presencePath(cx, cy, rx, ry, rot, phase, 1.02);

  const low = color(pal[1][0], pal[1][1], pal[1][2]);
  const high = color(pal[4][0], pal[4][1], pal[4][2]);

  for (let i = 0; i < 46; i++) {
    const t = i / 45;
    const c = lerpColor(low, high, 0.12 + 0.82 * pow(t, 0.8));
    c.setAlpha(11);
    fill(c);
    presencePath(
      cx, cy, rx, ry, rot, phase,
      1.025 - 0.24 * t,
      facing * 28 * t,
      -30 * t
    );
  }

  for (let i = 0; i < 34; i++) {
    const c = pal[floor(random(1, pal.length))];
    fill(c[0], c[1], c[2], random(2, 7));
    presencePath(
      cx, cy, rx, ry, rot, phase,
      random(0.67, 1.0),
      random(-18, 18),
      random(-22, 22)
    );
  }
  pop();

  const cr = cos(rot);
  const sr = sin(rot);

  push();
  for (let i = 0; i < 5800; i++) {
    const u = random(-rx, rx);
    const v = random(-ry, ry);
    const q = (u * u) / (rx * rx) + (v * v) / (ry * ry);
    if (q > 0.79) continue;

    const x = cx + u * cr - v * sr;
    const y = cy + u * sr + v * cr;
    const toward = (u / rx) * facing;

    let idx = floor(random(1, pal.length));
    if (toward > 0.2 && random() < 0.42) {
      idx = random() < 0.55 ? 4 : pal.length - 1;
    }
    const c = pal[idx];
    const len = random(8, 56) * (1.05 - q * 0.25);
    const ang = rot + HALF_PI + 0.30 * sin(v * 0.004 + phase) + random(-0.43, 0.43);

    stroke(c[0], c[1], c[2], random(7, 29) * (1.1 - q * 0.25));
    strokeWeight(random(0.6, 4.8));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  for (let i = 0; i < 520; i++) {
    const u = random(-rx, rx);
    const v = random(-ry, ry);
    const q = (u * u) / (rx * rx) + (v * v) / (ry * ry);
    if (q > 0.72) continue;

    const x = cx + u * cr - v * sr;
    const y = cy + u * sr + v * cr;
    const c = pal[floor(random(1, pal.length))];
    const len = random(28, 115);
    const ang = rot + HALF_PI + random(-0.5, 0.5);

    stroke(c[0], c[1], c[2], random(3, 11));
    strokeWeight(random(5, 22));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
  pop();

  push();
  noStroke();
  for (let i = 0; i < 1050; i++) {
    const u = random(-rx, rx);
    const v = random(-ry, ry);
    const q = (u * u) / (rx * rx) + (v * v) / (ry * ry);
    if (q > 0.82) continue;

    const x = cx + u * cr - v * sr;
    const y = cy + u * sr + v * cr;
    const c = pal[floor(random(1, pal.length))];
    fill(c[0], c[1], c[2], random(4, 17));
    ellipse(x, y, random(1.5, 8), random(3, 20));
  }
  pop();

  push();
  noFill();
  for (let k = 0; k < 54; k++) {
    const centerAngle = (facing === 1 ? 0 : PI) + random(-0.45, 0.45);
    const span = random(0.35, 1.25);
    const sc = random(0.965, 1.018);
    const c = random() < 0.7 ? pal[pal.length - 1] : pal[5];

    stroke(c[0], c[1], c[2], random(7, 35));
    strokeWeight(random(0.8, 5.2));
    beginShape();
    for (let j = 0; j <= 25; j++) {
      const a = centerAngle - span * 0.5 + span * (j / 25);
      const p = contourPoint(cx, cy, rx, ry, rot, phase, a, sc);
      vertex(p.x, p.y);
    }
    endShape();
  }
  pop();
}

function paintThreads() {
  const colors = [
    [238, 188, 137],
    [218, 133, 118],
    [157, 177, 161],
    [244, 216, 171]
  ];
  const threads = [];

  for (let i = 0; i < 22; i++) {
    const y1 = random(680, 1480);
    const y2 = constrain(y1 + random(-220, 220), 620, 1530);
    const x1 = random(700, 790);
    const x2 = random(880, 970);

    threads.push([
      x1, y1,
      x1 + random(25, 165), y1 + random(-185, 185),
      x2 - random(25, 165), y2 + random(-185, 185),
      x2, y2
    ]);
  }

  push();
  noFill();
  for (let i = 0; i < threads.length; i++) {
    const t = threads[i];
    const c = colors[floor(random(colors.length))];

    stroke(c[0], c[1], c[2], random(20, 76));
    strokeWeight(random(0.55, 2.15));
    bezier(t[0], t[1], t[2], t[3], t[4], t[5], t[6], t[7]);

    if (i % 4 === 0) {
      stroke(c[0], c[1], c[2], 16);
      strokeWeight(0.6);
      bezier(
        t[0], t[1] + 4,
        t[2] + 3, t[3] + 5,
        t[4] - 2, t[5] + 3,
        t[6], t[7] + 4
      );
    }
  }

  for (let side = 0; side < 2; side++) {
    const dir = side === 0 ? 1 : -1;
    for (let i = 0; i < 8; i++) {
      const x = side === 0 ? random(400, 665) : random(1020, 1230);
      const y = random(720, 1400);
      const c = side === 0 ? colors[1] : colors[2];
