      bezier(
        x, y,
        x + dir * random(55, 170), y - random(45, 170),
        x + dir * random(50, 180), y + random(90, 220),
        x + random(-25, 25), y + random(100, 240)
      );
    }
  }
  pop();

  push();
  noStroke();
  for (let i = 0; i < 46; i++) {
    const t = threads[floor(random(threads.length))];
    const u = random(0.13, 0.87);
    const x = bezierPoint(t[0], t[2], t[4], t[6], u);
    const y = bezierPoint(t[1], t[3], t[5], t[7], u);
    const c = colors[floor(random(colors.length))];
    fill(c[0], c[1], c[2], random(35, 105));
    const s = random(1.2, 3.8);
    ellipse(x, y, s, s);
  }
  pop();
}

