function ellipticalGlow(x, y, rx, ry, stops) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(rx, ry);

  const gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
  for (const stop of stops) {
    gradient.addColorStop(stop[0], stop[1]);
  }

  ctx.fillStyle = gradient;
  ctx.fillRect(-1, -1, 2, 2);
  ctx.restore();
}

function baseCurrent(kind, t) {
  t = constrain(t, 0, 1);
  let a, x, y;

  if (kind === 0) {
    a = lerp(-1.70, -4.58, t);
    x = 800 + 522 * cos(a);
    y = 1000 + 735 * sin(a);
    x += 26 * sin(t * PI * 3 + 0.7);
    y += 28 * sin(t * PI * 2 - 0.4);
    x += 34 * (noise(t * 2.2, 3.1) - 0.5);
    y += 28 * (noise(t * 2.0, 8.7) - 0.5);
  } else {
    a = lerp(-1.39, 1.50, t);
    x = 800 + 535 * cos(a);
    y = 1000 + 735 * sin(a);
    x += 32 * sin(t * PI * 2.6 + 2.1);
    y += 24 * sin(t * PI * 3.1 + 0.8);
    x += 38 * (noise(t * 2.4, 14.2) - 0.5);
    y += 30 * (noise(t * 2.1, 19.6) - 0.5);
  }

  return { x, y };
}

function currentWidth(kind, t) {
  const body = kind === 0 ? 245 : 225;
  return 34 + body * pow(max(0, sin(PI * t)), 0.82) *
    (0.94 + 0.12 * noise(t * 3, kind + 20));
}

function strandPoint(kind, t, q, phase, wild) {
  const p = baseCurrent(kind, t);
  const before = baseCurrent(kind, t - 0.002);
  const after = baseCurrent(kind, t + 0.002);
  const dx = after.x - before.x;
  const dy = after.y - before.y;
  const d = sqrt(dx * dx + dy * dy) || 1;
  const tx = dx / d;
  const ty = dy / d;
  const nx = -ty;
  const ny = tx;

  const w = currentWidth(kind, t);
  const flutter = sin(t * 10 + phase) * 9 * wild;
  const ragged = (noise(t * 5.5 + phase * 0.017, q * 3.1 + kind * 11 + 20) - 0.5) *
    32 * wild;
  const along = (noise(t * 7 + phase * 0.011, q + 31) - 0.5) * 18 * wild;
  const offset = q * w + flutter + ragged;

  return {
    x: p.x + nx * offset + tx * along,
    y: p.y + ny * offset + ty * along,
    tx,
    ty
  };
}

function traceStrand(kind, q, phase, wild, t0, t1, steps = 112) {
  beginShape();
  for (let j = 0; j <= steps; j++) {
    const t = lerp(t0, t1, j / steps);
    const p = strandPoint(kind, t, q, phase, wild);
    vertex(p.x, p.y);
  }
  endShape();
}

function paintAtmosphere() {
  noStroke();

  for (let i = 0; i < 2100; i++) {
    const kind = random() < 0.5 ? 0 : 1;
    const t = random(0.01, 0.99);
    const q = (random() < 0.5 ? -1 : 1) * random(0.96, 1.72);
    const p = strandPoint(kind, t, q, random(1000), 1.4);
    const c = random() < 0.18
      ? pick(THREAD_LIGHT)
      : pick(kind === 0 ? WARM : COOL);

    fill(c[0], c[1], c[2], random(7, 42));
    const r = random(0.7, 4.6);
    ellipse(p.x, p.y, r, r * random(0.6, 1.5));
  }
}

function paintCurrent(kind) {
  const innerSign = kind === 0 ? -1 : 1;
  const palette = kind === 0 ? WARM : COOL;
  const deep = kind === 0 ? WARM_DEEP : COOL_DEEP;
  const light = kind === 0 ? WARM_LIGHT : COOL_LIGHT;

  noFill();

  for (let i = 0; i < 84; i++) {
    const q = random(-1.06, 1.06);
    const c = random() < 0.8 ? pick(deep) : pick(palette);
    stroke(c[0], c[1], c[2], random(8, 24));
    strokeWeight(random(25, 92));
    traceStrand(
      kind, q, random(1000), 0.35,
      random(0, 0.018), random(0.982, 1), 96
    );
  }

  for (let i = 0; i < 270; i++) {
    let q = random(-1.09, 1.09);
    if (random() < 0.22) q = innerSign * random(0.64, 1.03);

    const inward = q * innerSign > 0.55;
    const c = inward && random() < 0.52 ? pick(light) : pick(palette);
    const t0 = random() < 0.82 ? random(0, 0.015) : random(0.02, 0.14);
    const t1 = random() < 0.82 ? random(0.985, 1) : random(0.86, 0.985);

    stroke(c[0], c[1], c[2], random(18, 66));
    strokeWeight(random(2, 16));
    traceStrand(kind, q, random(1000), 0.8, t0, t1, 118);
  }

  for (let i = 0; i < 190; i++) {
    const q = random(-1.13, 1.13);
    const c = random() < 0.16 ? pick(light) : pick(palette);
    const t0 = random() < 0.68 ? random(0, 0.02) : random(0.02, 0.18);
    const t1 = random() < 0.68 ? random(0.98, 1) : random(0.82, 0.99);

    stroke(c[0], c[1], c[2], random(28, 112));
    strokeWeight(random(0.45, 3.3));
    traceStrand(kind, q, random(1000), 1.2, t0, t1, 118);
  }

  for (let i = 0; i < 44; i++) {
    const q = innerSign * random(0.83, 1.08);
    const c = random() < 0.58 ? pick(THREAD_LIGHT) : pick(light);
    stroke(c[0], c[1], c[2], random(35, 122));
    strokeWeight(random(0.6, 4.1));
    traceStrand(
      kind, q, random(1000), 0.85,
      random(0, 0.07), random(0.93, 1), 124
    );
  }

  for (let i = 0; i < 950; i++) {
    const t = random(0.02, 0.98);
    const q = random(-1.16, 1.16);
    const p = strandPoint(kind, t, q, random(1000), 1.25);
    const inward = q * innerSign > 0.55;
    const c = inward && random() < 0.45 ? pick(light) : pick(palette);
    const len = random(3, 32);

    stroke(c[0], c[1], c[2], random(15, 72));
    strokeWeight(random(0.5, 4.8));
    line(
      p.x - p.tx * len * 0.5,
      p.y - p.ty * len * 0.5,
      p.x + p.tx * len * 0.5,
      p.y + p.ty * len * 0.5
    );
  }
}

function innerPoint(kind, t) {
  const innerSign = kind === 0 ? -1 : 1;
  return strandPoint(
    kind, t, innerSign * random(0.89, 1.04), random(1000), 0.5
  );
}

function paintExchange() {
  const bridges = [];

  for (let i = 0; i < 20; i++) {
    const tw = random(0.19, 0.81);
    const tc = constrain(tw + random(-0.11, 0.11), 0.16, 0.84);
    const p0 = innerPoint(0, tw);
    const p3 = innerPoint(1, tc);
    const p1 = {
      x: p0.x + random(120, 290),
      y: p0.y + random(-95, 95)
    };
    const p2 = {
      x: p3.x - random(120, 290),
      y: p3.y + random(-95, 95)
    };
    const c = pick(THREAD_LIGHT);

    noFill();
    stroke(c[0], c[1], c[2], random(34, 91));
    strokeWeight(random(0.65, 2.25));
    bezier(p0.x, p0.y, p1.x, p1.y, p2.x, p2.y, p3.x, p3.y);

    bridges.push({ p0, p1, p2, p3 });

    if (random() < 0.7) {
      noStroke();
      fill(255, 218, 165, random(45, 100));
      ellipse(p0.x, p0.y, random(2, 5));
      ellipse(p3.x, p3.y, random(2, 5));
    }
  }

  for (let i = 0; i < 34; i++) {
    const kind = random() < 0.5 ? 0 : 1;
    const direction = kind === 0 ? 1 : -1;
    const p0 = innerPoint(kind, random(0.16, 0.84));
    const p3 = {
      x: random(680, 920),
      y: p0.y + random(-170, 170)
    };
    const p1 = {
      x: p0.x + direction * random(80, 185),
      y: p0.y + random(-80, 80)
    };
    const p2 = {
      x: p3.x - direction * random(30, 105),
      y: p3.y + random(-55, 55)
    };
    const c = pick(THREAD_LIGHT);

    noFill();
    stroke(c[0], c[1], c[2], random(20, 62));
    strokeWeight(random(0.5, 1.65));
    bezier(p0.x, p0.y, p1.x, p1.y, p2.x, p2.y, p3.x, p3.y);
  }

  return bridges;
}

function paintSharedMotes(bridges) {
  noStroke();

  for (const bridge of bridges) {
    const count = floor(random(4, 11));
    for (let j = 0; j < count; j++) {
      const t = random(0.07, 0.93);
      const x = bezierPoint(
        bridge.p0.x, bridge.p1.x, bridge.p2.x, bridge.p3.x, t
      );
      const y = bezierPoint(
        bridge.p0.y, bridge.p1.y, bridge.p2.y, bridge.p3.y, t
      );
      const c = pick(THREAD_LIGHT);
      const r = random(0.8, 3.4);

      fill(c[0], c[1], c[2], random(40, 132));
      ellipse(x, y, r);
    }
  }

  for (let i = 0; i < 330; i++) {
    const x = 800 + randomGaussian() * 130;
    const y = 1000 + randomGaussian() * 275;
    const d = pow((x - 800) / 340, 2) + pow((y - 1000) / 650, 2);
    if (d > 1) continue;

    const c = random() < 0.76 ? pick(THREAD_LIGHT) : [255, 239, 207];
    const r = random(0.5, 2.8);
    fill(c[0], c[1], c[2], random(18, 92));
    ellipse(x, y, r);
  }
}

function paintPigmentExchange() {
  noStroke();

  for (let i = 0; i < 340; i++) {
    const target = i % 2;
    const t = random(0.09, 0.91);
    const q = random(-0.84, 0.84);
    const p = strandPoint(target, t, q, random(1000), 1.1);
    const c = target === 0 ? pick(COOL_LIGHT) : pick(WARM_LIGHT);
    const r = random(0.8, 5.2);

    fill(c[0], c[1], c[2], random(22, 91));
    ellipse(p.x, p.y, r, r * random(0.65, 1.4));
  }
}

function paintSurface() {
  for (let i = 0; i < 38000; i++) {
    const x = random(width);
    const y = random(height);

    if (random() < 0.53) {
      stroke(255, 238, 215, random(3, 12));
    } else {
      stroke(4, 7, 16, random(3, 14));
    }

    strokeWeight(random(0.35, 1.1));
    point(x, y);
  }

  for (let i = 0; i < 1100; i++) {
    const x = random(width);
    const y = random(height);
    const angle = random(TWO_PI);
    const len = random(5, 45);

    stroke(235, 216, 199, random(2, 8));
    strokeWeight(0.4);
    line(x, y, x + cos(angle) * len, y + sin(angle) * len);
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const gradient = ctx.createRadialGradient(
    800, 960, 480,
    800, 960, 1450
  );
  gradient.addColorStop(0, "rgba(7,7,18,0)");
