}

function draw() {
  const leftPath = new Path2D(
    "M -120 210 C 100 120 280 120 430 205 C 560 278 705 238 690 405 C 680 525 548 555 548 700 C 548 825 665 864 635 1010 C 608 1145 505 1195 560 1350 C 608 1485 735 1545 681 1718 C 628 1880 280 1940 -120 1810 Z"
  );
  const rightPath = new Path2D(
    "M 1720 190 C 1500 105 1320 160 1180 235 C 1040 310 895 260 920 430 C 942 560 1055 610 1030 748 C 1008 875 900 920 946 1060 C 990 1195 1100 1250 1045 1398 C 995 1535 875 1605 925 1750 C 1000 1900 1340 1935 1720 1790 Z"
  );

  const warm = [
    color(71, 35, 54), color(113, 48, 61), color(151, 65, 67),
    color(190, 87, 75), color(218, 117, 91), color(231, 153, 112)
  ];
  const cool = [
    color(20, 48, 66), color(25, 75, 85), color(39, 103, 108),
    color(60, 128, 124), color(105, 153, 139), color(91, 102, 132)
  ];

  strokeCap(ROUND);
  strokeJoin(ROUND);
  drawGround();
  drawHalo();

  const ctx = drawingContext;
  ctx.save();
  ctx.fillStyle = "rgb(113,51,64)";
  ctx.fill(leftPath);
  ctx.fillStyle = "rgb(27,72,83)";
  ctx.fill(rightPath);
  ctx.restore();

  paintField(leftPath, warm, -1);
  paintField(rightPath, cool, 1);

  ctx.save();
  ctx.lineJoin = "round";
  ctx.strokeStyle = "rgba(242,151,116,0.15)";
  ctx.lineWidth = 25;
  ctx.stroke(leftPath);
  ctx.strokeStyle = "rgba(251,188,134,0.32)";
  ctx.lineWidth = 2.2;
  ctx.stroke(leftPath);
  ctx.strokeStyle = "rgba(144,206,187,0.14)";
  ctx.lineWidth = 25;
  ctx.stroke(rightPath);
  ctx.strokeStyle = "rgba(176,218,191,0.28)";
