function paintedCurve(x, y, a, len, bend) {
  const dx = cos(a) * len;
  const dy = sin(a) * len;
  const nx = -sin(a) * bend;
  const ny = cos(a) * bend;
  bezier(
    x, y,
    x + dx * 0.33 + nx, y + dy * 0.33 + ny,
    x + dx * 0.68 - nx * 0.4, y + dy * 0.68 - ny * 0.4,
    x + dx, y + dy
  );
}

function drawGround() {
  background(22, 25, 43);
  const palette = [
    color(40, 43, 67), color(52, 42, 64), color(30, 55, 70),
    color(75, 51, 61), color(42, 62, 75), color(91, 67, 65)
  ];

  noFill();
  for (let i = 0; i < 850; i++) {
    const x = random(-150, 1750);
    const y = random(-100, 2100);
    const c = random(palette);
    stroke(red(c), green(c), blue(c), random(5, 19));
    strokeWeight(random(12, 76));
    paintedCurve(
      x, y,
      -HALF_PI + random(-0.48, 0.48),
      random(80, 410),
      random(-90, 90)
    );
  }

  noStroke();
  for (let i = 0; i < 150; i++) {
    const c = random(palette);
    fill(red(c), green(c), blue(c), random(3, 10));
    ellipse(random(width), random(height), random(80, 420), random(50, 330));
  }
}

function organicOval(cx, cy, rx, ry, phase) {
  beginShape();
  for (let i = 0; i <= 120; i++) {
    const a = map(i, 0, 120, 0, TWO_PI);
    const w = 1 + 0.055 * sin(3 * a + phase) + 0.035 * sin(7 * a - phase);
    vertex(cx + cos(a) * rx * w, cy + sin(a) * ry * w);
  }
  endShape(CLOSE);
}

function drawHalo() {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(800, 1030);
  ctx.scale(0.76, 1.22);
  const g = ctx.createRadialGradient(0, 0, 15, 0, 0, 680);
  g.addColorStop(0, "rgba(255,222,155,0.31)");
  g.addColorStop(0.38, "rgba(224,153,113,0.15)");
  g.addColorStop(0.72, "rgba(142,100,119,0.06)");
  g.addColorStop(1, "rgba(70,60,90,0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, 680, 0, TWO_PI);
  ctx.fill();
  ctx.restore();

  noStroke();
  for (let j = 0; j < 15; j++) {
    fill(239, 175 + j * 2, 127 + j * 3, 2.6);
    organicOval(800, 1020, 210 + j * 24, 440 + j * 27, j * 0.41);
  }

  noFill();
  for (let i = 0; i < 12; i++) {
    stroke(220, 174, 130, random(8, 22));
    strokeWeight(random(0.8, 2.4));
    const y = 400 + i * 108;
    bezier(
      random(-100, 180), y + random(-100, 100),
      350, y - random(120, 330),
      1230, y + random(120, 330),
      random(1420, 1720), y + random(-100, 100)
    );
  }
}

function paintField(path, palette, side) {
  const ctx = drawingContext;
  ctx.save();
  ctx.clip(path);

  let glaze;
  if (side < 0) {
    glaze = ctx.createLinearGradient(0, 0, 790, 0);
    glaze.addColorStop(0, "rgba(42,23,49,0.28)");
    glaze.addColorStop(1, "rgba(255,165,116,0.20)");
  } else {
    glaze = ctx.createLinearGradient(1600, 0, 810, 0);
    glaze.addColorStop(0, "rgba(12,33,57,0.30)");
    glaze.addColorStop(1, "rgba(155,211,178,0.18)");
  }
  ctx.fillStyle = glaze;
  ctx.fillRect(0, 0, width, height);

  const xmin = side < 0 ? -140 : 820;
  const xmax = side < 0 ? 780 : 1740;

  noFill();
  for (let i = 0; i < 900; i++) {
    const x = random(xmin, xmax);
    const y = random(130, 1910);
    const n = noise(x * 0.0022, y * 0.0022, side + 4);
    const a = -HALF_PI + (n - 0.5) * 2.3 + side * 0.16 * sin(y * 0.004);
    const c = random(palette);
    stroke(red(c), green(c), blue(c), random(8, 31));
    strokeWeight(random(7, 47));
    paintedCurve(x, y, a, random(45, 250), random(-75, 75));
  }

  for (let i = 0; i < 700; i++) {
    const x = random(xmin, xmax);
    const y = random(150, 1900);
    const n = noise(x * 0.003, y * 0.003, side + 9);
    const c = random(palette);
    stroke(red(c), green(c), blue(c), random(18, 60));
    strokeWeight(random(0.7, 5.5));
    paintedCurve(
      x, y,
      -HALF_PI + (n - 0.5) * 2.8,
      random(15, 105),
      random(-24, 24)
    );
  }

  noStroke();
  for (let i = 0; i < 850; i++) {
    const c = random(palette);
    fill(red(c), green(c), blue(c), random(4, 18));
    ellipse(
      random(xmin, xmax), random(150, 1900),
      random(3, 38), random(2, 19)
    );
  }
  ctx.restore();
}

function lightCenter(y) {
  return 800 + 44 * sin(y * 0.0045) + 20 * sin(y * 0.011);
}

function drawCentralLight() {
  noStroke();
  for (let j = 0; j < 34; j++) {
    const q = j / 33;
    const spread = lerp(215, 20, q);
    fill(255, 198 + 42 * q, 132 + 70 * q, 2.2 + 4.5 * q);
    beginShape();
    for (let y = 320; y <= 1760; y += 28) {
      const u = (y - 320) / 1440;
      const env = pow(max(0, sin(PI * u)), 0.55);
      const w = spread * env * (0.84 + 0.25 * noise(y * 0.008, j * 0.06));
      vertex(lightCenter(y) - w, y);
    }
    for (let y = 1760; y >= 320; y -= 28) {
      const u = (y - 320) / 1440;
      const env = pow(max(0, sin(PI * u)), 0.55);
      const w = spread * env * (0.84 + 0.25 * noise(y * 0.008, j * 0.06 + 2));
      vertex(lightCenter(y) + w, y);
    }
    endShape(CLOSE);
  }

  noFill();
  for (let i = 0; i < 430; i++) {
    const y = random(355, 1725);
    const u = (y - 320) / 1440;
    const env = pow(max(0, sin(PI * u)), 0.55);
    const x = lightCenter(y) + random(-195, 195) * env;
    const warm = random() < 0.65;
    if (warm) stroke(255, random(215, 242), random(155, 205), random(8, 42));
    else stroke(244, random(158, 196), random(137, 170), random(7, 30));
    strokeWeight(random(0.6, 4.8));
    paintedCurve(x, y, -HALF_PI + random(-0.18, 0.18), random(20, 135), random(-15, 15));
  }

  for (let i = 0; i < 85; i++) {
    const y = random(390, 1690);
    const x = lightCenter(y) + random(-28, 28);
    stroke(255, 246, 218, random(35, 125));
    strokeWeight(random(0.7, 3.1));
    paintedCurve(x, y, -HALF_PI + random(-0.12, 0.12), random(18, 90), random(-8, 8));
  }
}

function edgeX(table, y) {
  for (let i = 0; i < table.length - 1; i++) {
    if (y <= table[i + 1][0]) {
      return map(y, table[i][0], table[i + 1][0], table[i][1], table[i + 1][1]);
    }
  }
  return table[table.length - 1][1];
}

function threadSegment(x1, y1, c1x, c1y, c2x, c2y, x2, y2, t0, t1) {
  beginShape();
  for (let j = 0; j <= 18; j++) {
    const t = lerp(t0, t1, j / 18);
    vertex(
      bezierPoint(x1, c1x, c2x, x2, t),
      bezierPoint(y1, c1y, c2y, y2, t)
    );
  }
  endShape();
}

function drawThreads() {
  const left = [[405,690],[700,548],[1010,635],[1350,560],[1718,681]];
  const right = [[430,920],[748,1030],[1060,946],[1398,1045],[1750,925]];
  const palette = [
    color(255,231,184), color(239,163,145),
    color(158,208,194), color(220,183,115)
  ];

  noFill();
  for (let i = 0; i < 96; i++) {
    const y1 = random(455, 1680);
    const y2 = constrain(y1 + random(-220, 220), 440, 1710);
    const x1 = edgeX(left, y1) - random(5, 115);
    const x2 = edgeX(right, y2) + random(5, 115);
    const c1x = lerp(x1, 800, random(0.45, 0.9));
    const c2x = lerp(x2, 800, random(0.45, 0.9));
    const c1y = y1 + random(-145, 145);
    const c2y = y2 + random(-145, 145);
    const c = random(palette);
    stroke(red(c), green(c), blue(c), random(32, 112));
    strokeWeight(random(0.55, 2.8));

    if (random() < 0.43) {
      bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);
    } else {
      const a = random(0.16, 0.29);
      const b = random(0.39, 0.48);
      threadSegment(x1,y1,c1x,c1y,c2x,c2y,x2,y2,0,a);
      threadSegment(x1,y1,c1x,c1y,c2x,c2y,x2,y2,b,0.76);
      threadSegment(x1,y1,c1x,c1y,c2x,c2y,x2,y2,0.84,1);
    }
  }
}

function drawRoots() {
  noFill();
  for (let i = 0; i < 40; i++) {
    const x1 = random(90, 710);
    const x2 = random(890, 1510);
    const y1 = random(1670, 1870);
    const y2 = random(1670, 1880);
    if (i % 3 === 0) stroke(230, 177, 116, random(18, 55));
    else if (i % 3 === 1) stroke(208, 126, 116, random(14, 45));
    else stroke(125, 181, 169, random(14, 45));
    strokeWeight(random(0.6, 2.4));
    bezier(
      x1, y1,
      random(480, 760), random(1830, 2070),
      random(840, 1120), random(1830, 2070),
      x2, y2
    );
  }
}

function mend(points) {
  noFill();
  stroke(28, 25, 42, 105);
  strokeWeight(7);
  beginShape();
  for (const p of points) vertex(p[0], p[1]);
  endShape();

  stroke(237, 181, 107, 58);
  strokeWeight(1.2);
  beginShape();
  for (const p of points) vertex(p[0], p[1]);
  endShape();

  for (let i = 0; i < points.length - 1; i++) {
    const a = points[i];
    const b = points[i + 1];
    const d = dist(a[0], a[1], b[0], b[1]);
    const steps = max(1, floor(d / 38));
    const dx = (b[0] - a[0]) / d;
    const dy = (b[1] - a[1]) / d;
    for (let j = 0; j < steps; j++) {
      const t = (j + 0.5) / steps;
      const x = lerp(a[0], b[0], t);
      const y = lerp(a[1], b[1], t);
      const s = random(8, 17);
      stroke(239, 190, 115, random(110, 190));
      strokeWeight(random(1.2, 2.7));
      line(x + dy * s, y - dx * s, x - dy * s, y + dx * s);
      stroke(255, 226, 158, 95);
      strokeWeight(0.7);
      line(x + dy * s, y - dx * s - 1, x - dy * s, y + dx * s - 1);
    }
  }
}

function drawDrift() {
