}

function traceForm(ctx, side) {
  ctx.beginPath();
  if (side === 0) {
    ctx.moveTo(190, 1740);
    ctx.bezierCurveTo(95, 1450, 120, 1030, 255, 720);
    ctx.bezierCurveTo(355, 485, 520, 315, 690, 238);
    ctx.bezierCurveTo(742, 214, 785, 232, 764, 292);
    ctx.bezierCurveTo(665, 508, 557, 675, 536, 882);
    ctx.bezierCurveTo(504, 1145, 596, 1352, 746, 1498);
    ctx.bezierCurveTo(786, 1538, 778, 1574, 733, 1562);
    ctx.bezierCurveTo(581, 1521, 501, 1638, 417, 1744);
    ctx.bezierCurveTo(341, 1840, 229, 1841, 190, 1740);
  } else {
    ctx.moveTo(1412, 1746);
    ctx.bezierCurveTo(1504, 1462, 1488, 1100, 1374, 806);
    ctx.bezierCurveTo(1288, 582, 1124, 384, 936, 302);
    ctx.bezierCurveTo(879, 276, 840, 291, 866, 350);
    ctx.bezierCurveTo(982, 554, 1080, 731, 1058, 948);
    ctx.bezierCurveTo(1036, 1177, 962, 1342, 866, 1476);
    ctx.bezierCurveTo(828, 1527, 841, 1565, 886, 1548);
    ctx.bezierCurveTo(1037, 1492, 1130, 1628, 1210, 1748);
    ctx.bezierCurveTo(1280, 1852, 1370, 1840, 1412, 1746);
  }
  ctx.closePath();
}

function traceInner(ctx, side) {
  ctx.beginPath();
  if (side === 0) {
    ctx.moveTo(764, 292);
    ctx.bezierCurveTo(665, 508, 557, 675, 536, 882);
    ctx.bezierCurveTo(504, 1145, 596, 1352, 746, 1498);
  } else {
    ctx.moveTo(866, 350);
    ctx.bezierCurveTo(982, 554, 1080, 731, 1058, 948);
    ctx.bezierCurveTo(1036, 1177, 962, 1342, 866, 1476);
  }
}

function foldCurve(side, u, j) {
  if (side === 0) {
    bezier(
      lerp(145, 742, u) + j, 1840,
      lerp(35, 462, u) + j * 0.35, 1390,
      lerp(190, 520, u) - j * 0.25, 610,
      lerp(690, 764, u), 245 + j * 0.25
    );
  } else {
    bezier(
      lerp(1455, 886, u) - j, 1845,
      lerp(1570, 1140, u) - j * 0.35, 1400,
      lerp(1390, 1080, u) + j * 0.25, 650,
      lerp(936, 866, u), 300 - j * 0.2
    );
  }
}

function paintForm(side) {
  const left = side === 0;
  const ctx = drawingContext;

  ctx.save();
  traceForm(ctx, side);

  const base = left
    ? ctx.createLinearGradient(100, 0, 790, 0)
    : ctx.createLinearGradient(1500, 0, 830, 0);

  if (left) {
    base.addColorStop(0, "#3c233c");
    base.addColorStop(0.35, "#7e3044");
    base.addColorStop(0.68, "#c85451");
    base.addColorStop(0.88, "#e88664");
    base.addColorStop(1, "#f0b078");
  } else {
    base.addColorStop(0, "#142c43");
    base.addColorStop(0.32, "#17505f");
    base.addColorStop(0.66, "#287e7c");
    base.addColorStop(0.88, "#72aa94");
    base.addColorStop(1, "#d1c797");
  }

  ctx.fillStyle = base;
  ctx.shadowColor = left
    ? "rgba(45,7,30,0.55)"
    : "rgba(3,22,39,0.58)";
  ctx.shadowBlur = 42;
  ctx.shadowOffsetY = 14;
  ctx.fill();

  ctx.shadowColor = "rgba(0,0,0,0)";
  ctx.shadowBlur = 0;
  ctx.clip();

  const shade = ctx.createLinearGradient(0, 200, 0, 1860);
  shade.addColorStop(0, "rgba(8,13,31,0.18)");
  shade.addColorStop(0.38, "rgba(8,13,31,0)");
  shade.addColorStop(1, "rgba(9,10,27,0.30)");
  ctx.fillStyle = shade;
  ctx.fillRect(0, 0, width, height);

  if (left) {
    radiance(620, 630, 500, [
      [0, "rgba(255,177,114,0.23)"],
      [1, "rgba(255,150,100,0)"]
    ], "screen");
    radiance(360, 1400, 560, [
      [0, "rgba(139,37,78,0.20)"],
      [1, "rgba(90,20,65,0)"]
    ]);
    radiance(585, 1030, 310, [
      [0, "rgba(49,161,150,0.09)"],
      [1, "rgba(49,161,150,0)"]
    ], "screen");
  } else {
    radiance(985, 650, 520, [
      [0, "rgba(185,216,162,0.20)"],
      [1, "rgba(160,210,170,0)"]
    ], "screen");
    radiance(1320, 1390, 550, [
      [0, "rgba(7,40,75,0.27)"],
      [1, "rgba(7,40,75,0)"]
    ]);
    radiance(1010, 1080, 310, [
      [0, "rgba(231,115,94,0.085)"],
      [1, "rgba(231,115,94,0)"]
    ], "screen");
  }

  push();
  noFill();
  strokeCap(ROUND);

  for (let i = 0; i < 26; i++) {
    const u = constrain((i + random(-0.3, 0.3)) / 25, 0, 1);
    if (left) {
      if (i % 3 === 0) stroke(53, 20, 54, random(5, 10));
      else stroke(255, 181, 128, random(3, 8));
    } else {
      if (i % 3 === 0) stroke(7, 35, 58, random(5, 10));
      else stroke(188, 220, 180, random(3, 8));
    }
    strokeWeight(random(13, 40));
    foldCurve(side, u, random(-13, 13));
  }

  for (let i = 0; i < 180; i++) {
    const u = constrain((i + random(-0.35, 0.35)) / 179, 0, 1);
    const c = left
      ? lerpColor(color(105, 41, 63), color(255, 199, 143), pow(u, 0.75))
      : lerpColor(color(25, 69, 86), color(199, 220, 176), pow(u, 0.8));
    stroke(red(c), green(c), blue(c), random(7, 24));
    strokeWeight(random(0.55, 2.5));
    foldCurve(side, u, random(-8, 8));
  }
  pop();

  for (let i = 0; i < 9000; i++) {
    const x = left ? random(80, 800) : random(830, 1520);
    const y = random(220, 1850);
    const n = noise(x * 0.004, y * 0.004, side * 7 + 1);
    if (n < 0.24) continue;

    const q = random();
    const a = random(4, 16) * (0.55 + n);

    if (left) {
      if (q < 0.45) stroke(255, 194, 147, a);
      else if (q < 0.80) stroke(238, 112, 88, a);
      else if (q < 0.96) stroke(63, 23, 57, a);
      else stroke(76, 169, 153, a * 1.3);
    } else {
      if (q < 0.45) stroke(192, 221, 182, a);
      else if (q < 0.80) stroke(70, 145, 139, a);
      else if (q < 0.96) stroke(10, 46, 70, a);
      else stroke(231, 132, 102, a * 1.3);
    }

    strokeWeight(random(0.5, 2.2));
    line(x, y, x + random(-3, 3), y + random(2, 15));
  }

  ctx.restore();

  ctx.save();
  traceForm(ctx, side);
  ctx.lineWidth = 1.4;
  ctx.strokeStyle = left
    ? "rgba(245,154,112,0.20)"
    : "rgba(141,195,170,0.18)";
  ctx.stroke();
  ctx.restore();

  const passes = left
    ? [
        [26, "rgba(255,174,113,0.025)"],
        [7, "rgba(255,197,142,0.13)"],
        [1.6, "rgba(255,224,170,0.50)"]
      ]
    : [
        [26, "rgba(168,223,187,0.025)"],
        [7, "rgba(183,222,187,0.13)"],
        [1.6, "rgba(219,231,182,0.47)"]
      ];

  ctx.save();
  ctx.lineCap = "round";
  ctx.globalCompositeOperation = "screen";
  for (const p of passes) {
    traceInner(ctx, side);
    ctx.lineWidth = p[0];
    ctx.strokeStyle = p[1];
    ctx.stroke();
  }
  ctx.restore();
}

function cubic(a, b, c, d, t) {
  const u = 1 - t;
  return u * u * u * a +
    3 * u * u * t * b +
    3 * u * t * t * c +
    t * t * t * d;
}

function paintExchange() {
  radiance(801, 920, 390, [
    [0, "rgba(255,236,190,0.065)"],
    [0.5, "rgba(255,211,159,0.025)"],
    [1, "rgba(255,200,150,0)"]
  ], "screen");

  const threads = [
    [550, 790, 690, 590, 895, 705, 1010, 640],
    [534, 990, 690, 850, 895, 1100, 1048, 955],
    [585, 1240, 710, 1130, 860, 1305, 982, 1240]
  ];

  const ctx = drawingContext;
  ctx.save();
  ctx.lineCap = "round";

  for (const p of threads) {
    const g = ctx.createLinearGradient(p[0], 0, p[6], 0);
    g.addColorStop(0, "rgba(244,157,109,0.04)");
    g.addColorStop(0.18, "rgba(244,173,121,0.48)");
    g.addColorStop(0.5, "rgba(255,233,185,0.78)");
    g.addColorStop(0.82, "rgba(164,211,181,0.45)");
    g.addColorStop(1, "rgba(140,202,180,0.04)");

    for (const pass of [[13, 0.10], [1.25, 0.78]]) {
      ctx.beginPath();
      ctx.moveTo(p[0], p[1]);
      ctx.bezierCurveTo(p[2], p[3], p[4], p[5], p[6], p[7]);
      ctx.strokeStyle = g;
      ctx.globalAlpha = pass[1];
      ctx.lineWidth = pass[0];
      ctx.stroke();
    }
  }
  ctx.restore();

  push();
  noStroke();
  const warm = color(244, 164, 116);
  const cool = color(158, 211, 184);

  for (let i = 0; i < 460; i++) {
    const p = threads[floor(random(threads.length))];
    const t = random();
    const spread = 8 + 38 * sin(PI * t);
    const x = cubic(p[0], p[2], p[4], p[6], t) +
      randomGaussian() * spread;
    const y = cubic(p[1], p[3], p[5], p[7], t) +
      randomGaussian() * spread * 0.65;
    const c = lerpColor(warm, cool, t);
    const a = random(28, 125) * (0.35 + 0.65 * sin(PI * t));
    const r = random() < 0.06 ? random(3, 5) : random(0.6, 2.6);

    if (r > 3) {
      fill(red(c), green(c), blue(c), a * 0.09);
      ellipse(x, y, r * 7, r * 7);
    }
    fill(red(c), green(c), blue(c), a);
    ellipse(x, y, r * 2, r * 2);
  }

  for (let i = 0; i < 90; i++) {
    const y = random(280, 1560);
    const envelope = sin(PI * (y - 280) / 1280);
    const x = 800 + randomGaussian() * 72 * envelope;
    const r = random(0.6, 2.3);
    fill(246, 224, 177, random(12, 55) * envelope);
    ellipse(x, y, r * 2, r * 2);
  }
  pop();
}

function paintSurface() {
  const ctx = drawingContext;
  ctx.save();
  const v = ctx.createRadialGradient(800, 950, 500, 800, 950, 1500);
  v.addColorStop(0, "rgba(4,7,18,0)");
  v.addColorStop(0.72, "rgba(4,7,18,0.06)");
  v.addColorStop(1, "rgba(3,5,15,0.64)");
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  for (let i = 0; i < 52000; i++) {
    const pale = random() > 0.48;
    if (pale) stroke(245, 238, 220, random(2, 7));
    else stroke(2, 5, 14, random(2, 8));
    strokeWeight(random() < 0.97 ? 0.7 : 1.3);
    point(random(width), random(height));
  }

  for (let i = 0; i < 1400; i++) {
    const x = random(width);
    const y = random(height);
    stroke(225, 215, 200, random(1.5, 4.5));
    strokeWeight(0.55);
    line(x, y, x + random(3, 18), y + random(-0.7, 0.7));
  }
}

// THE LIGHT BETWEEN
// Two beings lean toward each other. Where their auras overlap,
// a lens of light is born — made by neither alone.
// Beneath the earth, their roots were already entangled.

let tips = [];
let bloomPts = [];
let glints = [];
let crossings = [];

const LENS = { y: 650, r: 430, dx: 160 };
LENS.hh = sqrt(LENS.r * LENS.r - LENS.dx * LENS.dx);

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function paint() {
  const ctx = drawingContext;

  // ---- night ----
  const bg = ctx.createLinearGradient(0, 0, 0, 2000);
  bg.addColorStop(0, '#07091a');
  bg.addColorStop(0.45, '#0d0c20');
  bg.addColorStop(0.78, '#150f24');
  bg.addColorStop(1, '#0a0614');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, 1600, 2000);

  // ---- nebular breath ----
  blendMode(SCREEN);
  const nebs = [[70, 58, 125], [100, 52, 95], [45, 58, 112], [86, 62, 68]];
  for (let i = 0; i < 12; i++) {
    softGlow(random(60, 1540), random(40, 1250), random(200, 560),
             nebs[floor(random(nebs.length))], random(5, 10));
  }
  blendMode(BLEND);

  // ---- stars ----
  noStroke();
  for (let i = 0; i < 160; i++) {
    const sx = random(20, 1580);
    const sy = random(20, 1380);
    if (insideLens(sx, sy, 30) && random() < 0.75) continue;
    fill(206, 215, 255, random(25, 165));
    circle(sx, sy, random(1, 2.6));
  }
  blendMode(SCREEN);
  for (let i = 0; i < 7; i++) {
    softGlow(random(60, 1540), random(40, 620), 30, [210, 220, 255], 55);
  }
  blendMode(BLEND);

  // ---- two auras; only their overlap makes the light ----
  blendMode(SCREEN);
  softGlow(640, 650, 470, [255, 108, 150], 78);   // rose aura
  softGlow(960, 650, 470, [255, 186, 92], 78);    // gold aura
  softGlow(800, 655, 300, [255, 244, 224], 64);   // shared heart of the lens
  blendMode(BLEND);

  // ---- each being glows brightest on the side that faces the other ----
  blendMode(SCREEN);
  softGlow(690, 930, 430, [255, 118, 152], 50);
  softGlow(910, 930, 430, [255, 192, 102], 50);
  softGlow(600, 870, 170, [255, 142, 172], 60);
  softGlow(1000, 870, 170, [255, 212, 132], 60);
  blendMode(BLEND);

  // ---- the two beings ----
  grow(430, 1512, -HALF_PI + 0.2, 232, 10, 0);
  grow(1170, 1512, -HALF_PI - 0.15, 242, 10, 1);

  // ---- earth ----
  const sg = ctx.createLinearGradient(0, 1488, 0, 2000);
  sg.addColorStop(0, 'rgba(17,12,25,1)');
  sg.addColorStop(0.5, 'rgba(10,7,17,1)');
  sg.addColorStop(1, 'rgba(4,3,9,1)');
  ctx.fillStyle = sg;
  ctx.fillRect(0, 1488, 1600, 512);

  // ---- roots, secretly entangled ----
  root(430, 1520, 0.95, 130, 7, 0);
  root(430, 1520, 0.35, 100, 6, 0);
  root(430, 1520, 1.4, 92, 6, 0);
  root(430, 1520, 0.1, 78, 5, 0);
  root(1170, 1520, PI - 0.95, 130, 7, 1);
  root(1170, 1520, PI - 0.35, 100, 6, 1);
  root(1170, 1520, PI - 1.4, 92, 6, 1);
  root(1170, 1520, PI - 0.1, 78, 5, 1);
  blendMode(SCREEN);
  softGlow(800, 1770, 300, [118, 128, 185], 26);  // the hidden field
  softGlow(800, 1866, 95, [255, 226, 192], 70);   // where they secretly meet
  noStroke();
  for (const c of crossings) {
    fill(255, 226, 195, random(28, 65));
    circle(c[0], c[1], random(1.6, 3.6));
  }
  for (let i = 0; i < 16; i++) {
    fill(255, 232, 205, random(16, 42));
    circle(800 + (random() - 0.5) * 190, 1840 + (random() - 0.5) * 110, random(1, 2.4));
  }
  blendMode(BLEND);

  // ---- ground mist; light pools where the petals gather ----
  blendMode(SCREEN);
  ctx.save();
  ctx.translate(800, 1497);
  ctx.scale(1, 0.1);
  let g1 = ctx.createRadialGradient(0, 0, 0, 0, 0, 780);
  g1.addColorStop(0, 'rgba(198,204,236,0.15)');
  g1.addColorStop(1, 'rgba(198,204,236,0)');
  ctx.fillStyle = g1;
  ctx.fillRect(-780, -780, 1560, 1560);
  ctx.restore();
  ctx.save();
  ctx.translate(800, 1502);
  ctx.scale(1, 0.13);
  let g2 = ctx.createRadialGradient(0, 0, 0, 0, 0, 330);
  g2.addColorStop(0, 'rgba(255,208,168,0.22)');
  g2.addColorStop(1, 'rgba(255,208,168,0)');
  ctx.fillStyle = g2;
  ctx.fillRect(-330, -330, 660, 660);
  ctx.restore();
  blendMode(BLEND);

  // ---- blossoms of light, densest on the facing sides ----
  blossoms();

  // ---- the lens ----
  const poly = lensPoly(0, 0);
  noStroke();
  fill(255, 246, 228, 20);
  drawPoly(poly);
  blendMode(SCREEN);
  softGlow(800, 950, 250, [255, 240, 214], 42);
  softGlow(800, 690, 210, [255, 250, 236], 36);
  blendMode(BLEND);
  noFill();
  stroke(255, 240, 214, 58);
  strokeWeight(2);
  drawPoly(poly);
  stroke(255, 240, 214, 24);
  strokeWeight(1);
  drawPoly(lensPoly(5, -4));

  // ---- motes rising through the lens ----
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 70; i++) {
    let my;
    if (random() < 0.72) my = lerp(LENS.y, LENS.y + LENS.hh, pow(random(), 0.7));
    else my = lerp(LENS.y - LENS.hh, LENS.y, random());
    const dy = abs(my - LENS.y);
    const hw = sqrt(max(0, LENS.r * LENS.r - dy * dy));
    const lo = 800 + LENS.dx - hw;
    const hi = 800 - LENS.dx + hw;
    if (hi <= lo) continue;
    const mx = random(lo, hi);
    const s = random(1.4, 4.2);
    fill(255, 242, 220, random(22, 85) * (my > 850 ? 1.15 : 0.75));
    ellipse(mx, my, s * 0.7, s * 1.7);
  }
  // ---- fireflies of attention ----
  for (let i = 0; i < 46; i++) {
    fill(255, 240, 212, random(25, 80));
    circle(800 + (random() + random() - 1) * 340, random(560, 1450), random(1.4, 3.4));
  }
  blendMode(BLEND);

  // ---- the almost-touch; threads of light between ----
  let best = nearestPairs(930);
  if (best.length === 0) best = nearestPairs(-1e9);
  if (best.length > 0) {
    const m0 = best[0];
    const mx = (m0.a.x + m0.b.x) / 2;
    const my = (m0.a.y + m0.b.y) / 2;
    blendMode(SCREEN);
    softGlow(800, 1060, 130, [255, 240, 220], 26); // light rising from the touch
    noStroke();
    for (let k = 0; k < min(5, best.length); k++) {
      const pr = best[k];
      const ax = pr.a.x, ay = pr.a.y, bx = pr.b.x, by = pr.b.y;
      const cx = (ax + bx) / 2 + (random() - 0.5) * 70;
      const cy = min(ay, by) - 70 - random() * 70;
      for (let i = 0; i <= 40; i++) {
        const t = i / 40;
        const x = (1 - t) * (1 - t) * ax + 2 * (1 - t) * t * cx + t * t * bx;
        const y = (1 - t) * (1 - t) * ay + 2 * (1 - t) * t * cy + t * t * by;
        fill(255, 240, 212, 20 + 70 * pow(sin(PI * t), 2) * random(0.5, 1));
        circle(x, y, 1.3 + 1.5 * sin(PI * t));
      }
    }
    softGlow(mx, my, 140, [255, 246, 226], 100);
    softGlow(mx, my, 44, [255, 255, 250], 150);
    for (let i = 0; i < 14; i++) {
      fill(255, 250, 236, random(55, 130));
      circle(mx + (random() - 0.5) * 96, my + (random() - 0.5) * 84, random(1.4, 3.4));
    }
    noFill();
    stroke(255, 244, 222, 15);
    strokeWeight(1.2);
    circle(mx, my, 150);
    circle(mx, my, 235);
    blendMode(BLEND);
  }

  // ---- petals of shared light ----
  const PP = [[236, 110, 144], [255, 178, 196], [240, 178, 84], [255, 226, 168], [255, 240, 218]];
  for (let i = 0; i < 110; i++) {
    let px, py;
    if (random() < 0.8) {
      px = 800 + (random() + random() - 1) * 300;
      py = random(980, 1462);
    } else {
      px = 800 + (random() - 0.5) * 860;
      py = random(720, 1462);
    }
    petal(px, py, random(7, 14), PP);
  }
  for (let i = 0; i < 24; i++) {  // fallen light gathered on the earth
    petal(800 + (random() + random() - 1) * 240, random(1468, 1496), random(7, 12), PP);
  }

  // ---- grain ----
  noStroke();
  for (let i = 0; i < 12000; i++) {
    const gx = random(1600);
    const gy = random(2000);
    if (random() < 0.5) fill(255, 255, 255, random(3, 10));
    else fill(0, 0, 0, random(3, 10));
    rect(gx, gy, 1.3, 1.3);
  }

  // ---- vignette ----
  const vg = ctx.createRadialGradient(800, 980, 430, 800, 1030, 1520);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.65, 'rgba(2,1,8,0.16)');
  vg.addColorStop(1, 'rgba(3,1,9,0.5)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, 1600, 2000);
}

// ---------- helpers ----------

function softGlow(cx, cy, r, c, a) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
  g.addColorStop(0, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + (a / 255).toFixed(4) + ')');
  g.addColorStop(0.55, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + (a * 0.32 / 255).toFixed(4) + ')');
  g.addColorStop(1, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0)');
  ctx.fillStyle = g;
  ctx.fillRect(cx - r, cy - r, 2 * r, 2 * r);
}

function insideLens(x, y, pad) {
  const d1 = dist(x, y, 800 - LENS.dx, LENS.y);
  const d2 = dist(x, y, 800 + LENS.dx, LENS.y);
  return d1 < LENS.r + pad && d2 < LENS.r + pad;
}

function lensPoly(offX, offY) {
  const pts = [];
  const c1x = 800 - LENS.dx + offX;
  const c2x = 800 + LENS.dx + offX;
  const cy = LENS.y + offY;
  const t1 = atan2(LENS.hh, -LENS.dx);
  const t2 = TWO_PI - t1;
  for (let i = 0; i <= 44; i++) {
    const a = lerp(t1, t2, i / 44);
    pts.push([c2x + LENS.r * cos(a), cy + LENS.r * sin(a)]);
  }
  const u1 = atan2(LENS.hh, LENS.dx);
  for (let i = 0; i <= 44; i++) {
    const a = lerp(-u1, u1, i / 44);
    pts.push([c1x + LENS.r * cos(a), cy + LENS.r * sin(a)]);
  }
  return pts;
}

function drawPoly(pts) {
  beginShape();
  for (const p of pts) vertex(p[0], p[1]);
  endShape(CLOSE);
}

function grow(x, y, ang, len, depth, side) {
  if (depth <= 0) {
    tips.push({ x: x, y: y, side: side });
    return;
  }
  const segs = 7;
  const step = len / segs;
  let a = ang;
  let px = x, py = y;
  const pts = [[x, y]];
  const w = map(depth, 1, 10, 1.1, 23);
  const col = side === 0 ? [35, 22, 32] : [33, 26, 17];
  noFill();
  for (let i = 0; i < segs; i++) {
    a += (noise(px * 0.006 + side * 97, py * 0.006 + depth * 13) - 0.5) * 0.4;
    const nx = px + cos(a) * step;
    const ny = py + sin(a) * step;
    const tv = (noise(i * 0.8 + side * 40, depth * 5) - 0.5) * 16;
    strokeWeight(lerp(w, w * 0.5, i / (segs - 1)));
    stroke(col[0] + tv, col[1] + tv, col[2] + tv, 200 + noise(i, depth * 7) * 40);
    line(px, py, nx, ny);
    px = nx;
    py = ny;
    pts.push([px, py]);
  }
  if (depth <= 5 && random() < 0.8) bloomPts.push({ x: px, y: py, side: side });
  const spread = 0.5 + random() * 0.38;
  const kids = depth >= 8 ? 2 : (random() < 0.8 ? 2 : (random() < 0.5 ? 1 : 3));
  const bias = side === 0 ? 0.055 : -0.055; // each leans toward the other
  for (let k = 0; k < kids; k++) {
    const t = kids === 1 ? random(-0.6, 0.6) : (k / (kids - 1)) * 2 - 1;
    const ca = a + t * spread + bias + (random() - 0.5) * 0.26;
    let cl = len * (0.7 + random() * 0.13);
    if ((side === 0 && t > 0) || (side === 1 && t < 0)) cl *= 1.07;
    const idx = k === 0 ? segs : floor(random(3, segs + 0.99));
    const sp = pts[idx];
    grow(sp[0] + (random() - 0.5) * 4, sp[1] + (random() - 0.5) * 4, ca, cl, depth - 1, side);
  }
}

function root(x, y, ang, len, depth, side) {
  if (depth <= 0 || len < 6) {
    if (abs(x - 800) < 140 && y > 1640) crossings.push([x, y]);
    return;
  }
  const segs = 5;
  const step = len / segs;
  let a = ang;
  let px = x, py = y;
  const w = map(depth, 1, 7, 0.7, 3.4);
  noFill();
  strokeWeight(w);
  for (let i = 0; i < segs; i++) {
    // steer gently toward the deep meeting place
    const target = atan2(1868 - py, 800 - px);
    a += angDelta(target - a) * 0.06 + (noise(px * 0.012 + side * 71, py * 0.012) - 0.5) * 0.34;
    const nx = px + cos(a) * step;
    const ny = py + sin(a) * step;
    stroke(148, 160, 205, random(30, 60));
    line(px, py, nx, ny);
    px = nx;
    py = ny;
  }
  const kids = depth >= 6 ? 2 : (random() < 0.75 ? 2 : 1);
  for (let k = 0; k < kids; k++) {
    const t = kids === 1 ? random(-0.7, 0.7) : (k / (kids - 1)) * 2 - 1;
    root(px, py,
         a + t * (0.4 + random() * 0.35) + (random() - 0.5) * 0.2,
         len * (0.72 + random() * 0.1),
         depth - 1, side);
  }
}

function angDelta(d) {
  while (d > PI) d -= TWO_PI;
  while (d < -PI) d += TWO_PI;
  return d;
}

function blossoms() {
  noStroke();
  const all = tips.concat(bloomPts);
  for (const p of all) {
    const inner = p.side === 0
      ? constrain(map(p.x, 470, 810, 0.35, 1.35), 0.3, 1.35)
      : constrain(map(p.x, 1130, 790, 0.35, 1.35), 0.3, 1.35);
    if (random() > 0.22 + inner * 0.6) continue;
    const pal = p.side === 0
      ? [[212, 66, 106], [236, 110, 144], [255, 168, 190], [255, 216, 226]]
      : [[204, 130, 38], [240, 178, 84], [255, 214, 140], [255, 241, 209]];
    const n = floor(random(4, 9) * (0.6 + inner * 0.55));
    for (let i = 0; i < n; i++) {
      const c = pal[floor(random(4))];
      let r = random(2, 7.5) * (0.6 + inner * 0.55);
      if (random() < 0.05) r *= 2;
      const ox = p.x + (random() - 0.5) * 38 * (0.45 + inner * 0.5);
      const oy = p.y + (random() - 0.5) * 34;
      fill(c[0], c[1], c[2], min(255, random(55, 145) * inner));
      circle(ox, oy, r * 2);
    }
    if (random() < 0.5) {
      glints.push([p.x + (random() - 0.5) * 24 * inner, p.y + (random() - 0.5) * 20, p.side]);
    }
  }
  blendMode(SCREEN);
  for (const g of glints) {
    const c = g[2] === 0 ? [255, 200, 214] : [255, 236, 190];
    fill(c[0], c[1], c[2], random(25, 70));
    circle(g[0], g[1], random(3, 9));
  }
  blendMode(BLEND);
}

function nearestPairs(minY) {
  let best = [];
  for (let i = 0; i < tips.length; i++) {
    if (tips[i].side !== 0) continue;
    for (let j = 0; j < tips.length; j++) {
      if (tips[j].side !== 1) continue;
      if (min(tips[i].y, tips[j].y) < minY) continue;
      const d = dist(tips[i].x, tips[i].y, tips[j].x, tips[j].y);
      if (d > 460) continue;
      if (best.length < 8 || d < best[best.length - 1].d) {
        best.push({ a: tips[i], b: tips[j], d: d });
        best.sort(function (p, q) { return p.d - q.d; });
        if (best.length > 8) best.pop();
      }
    }
  }
  return best;
}

function petal(x, y, s, pal) {
  const c = pal[floor(random(pal.length))];
  push();
  translate(x, y);
  rotate(random(TWO_PI));
  noStroke();
  fill(c[0], c[1], c[2], random(55, 135));
  ellipse(0, 0, s, s * 0.42);
  fill(255, 242, 228, random(18, 46));
  ellipse(-s * 0.16, -s * 0.07, s * 0.5, s * 0.2);
  pop();
  // a whisper of falling
  stroke(c[0], c[1], c[2], 16);
  strokeWeight(1);
  line(x, y + 5, x + (random() - 0.5) * 5, y + 15 + random(12));
}

// "Toward Each Other" — a painting about what love is.
// Two currents of light, rose and teal, pour out of the dark and into
// each other; where they meet, color dissolves into radiance.

const W = 1600, H = 2000;
const CX = 800, CY = 1060;

let warm, cool;

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  warm = {
    n: 1080, hue: 356, hueJit: 15, sat: 64, satJit: 15, bri: 71, briJit: 21,
    th0: radians(224), thSpread: radians(76),
    rMin: 470, rMax: 1080, zoff: 0, wobble: 36,
    glowRGB: '255,110,125', other: 197
  };
  cool = {
    n: 1080, hue: 196, hueJit: 13, sat: 60, satJit: 15, bri: 68, briJit: 21,
    th0: radians(46), thSpread: radians(76),
    rMin: 470, rMax: 1080, zoff: 100, wobble: 36,
    glowRGB: '70,185,215', other: 356
  };
}

function draw() {
  background(228, 60, 7);

  paintWashes();
  paintRipples();
  paintDust();
  paintArmGlow(warm);
  paintArmGlow(cool);
  paintStream(warm);
  paintStream(cool);

  // an ember of the other's color, carried inside each current
  paintSeed(898, 668, '110,235,238', [188, 60, 96]);
  paintSeed(689, 1448, '255,128,162', [350, 58, 96]);

  paintCore();
  paintForegroundDust();
  paintGrain();
  paintVignette();
}

function radial(x, y, r, stops) {
  const g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  drawingContext.fillStyle = g;
  drawingContext.fillRect(x - r, y - r, r * 2, r * 2);
}

function paintWashes() {
  // lift the middle of the dark, keep the corners deep
  radial(CX, CY, 1150, [[0, 'rgba(40,52,92,0.30)'], [0.5, 'rgba(26,34,66,0.15)'], [1, 'rgba(12,16,32,0)']]);
  radial(340, 330, 720, [[0, 'rgba(46,66,140,0.10)'], [1, 'rgba(46,66,140,0)']]);
  radial(1260, 470, 640, [[0, 'rgba(150,42,86,0.09)'], [1, 'rgba(150,42,86,0)']]);
  radial(420, 1660, 700, [[0, 'rgba(22,110,132,0.09)'], [1, 'rgba(22,110,132,0)']]);
  radial(1180, 1520, 780, [[0, 'rgba(92,60,150,0.08)'], [1, 'rgba(92,60,150,0)']]);
  radial(CX, CY, 980, [[0, 'rgba(255,145,115,0.06)'], [0.6, 'rgba(255,120,110,0.025)'], [1, 'rgba(255,120,110,0)']]);
}

// faint irregular rings: the meeting radiates outward
function paintRipples() {
  noFill();
  for (let i = 0; i < 8; i++) {
    const baseR = 255 + i * 92;
    const warmish = i % 2 === 0;
    stroke(warmish ? 42 : 195, 30, 96, map(baseR, 255, 900, 6.5, 3));
    strokeWeight(0.8 + random() * 0.7);
    beginShape();
    for (let a = 0; a <= TWO_PI + 0.02; a += TWO_PI / 160) {
      const wob = (noise(cos(a) * 1.7 + i * 9.1, sin(a) * 1.7 + i * 4.7) - 0.5) * (14 + i * 7);
      const r = baseR + wob;
      vertex(CX + r * cos(a), CY + r * sin(a));
    }
    endShape(CLOSE);
  }
}

// dim dust over the whole sky, thicker and brighter near the center:
// everything solitary drifts toward the light
function paintDust() {
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let x, y;
    if (random() < 0.34) {
      x = random(W); y = random(H);
    } else {
      const a = random(TWO_PI);
      const r = 1350 * pow(random(), 1.5);
      x = CX + r * cos(a);
      y = CY + r * sin(a);
      if (x < 4 || x > W - 4 || y < 4 || y > H - 4) continue;
    }
    const d = dist(x, y, CX, CY);
    const boost = exp(-d / 520);
    const k = random();
    let h, s, b;
    if (k < 0.72) { h = 45; s = 12 + random() * 15; b = 92 + random() * 8; }
    else if (k < 0.86) { h = 350; s = 40; b = 82; }
    else { h = 192; s = 38; b = 84; }
    fill(h, s, b, 6 + boost * 20 + random() * 8);
    const sz = (random() < 0.06 + boost * 0.3) ? 2 + random() * 1.6 : 1 + random() * 1.3;
    circle(x, y, sz);
  }
  for (let i = 0; i < 26; i++) {
    const a = random(TWO_PI);
    const r = 1250 * pow(random(), 1.2);
    const x = CX + r * cos(a);
    const y = CY + r * sin(a);
    if (x < 12 || x > W - 12 || y < 12 || y > H - 12) continue;
    radial(x, y, 10, [[0, 'rgba(255,240,210,0.30)'], [1, 'rgba(255,240,210,0)']]);
    fill(45, 15, 100, 45 + random() * 30);
    circle(x, y, 1.8 + random() * 1.4);
  }
}

// a soft river of the current's color beneath the strokes
function paintArmGlow(cfg) {
  const r0 = 880, sweep = 3.15;
  for (let i = 0; i <= 15; i++) {
    const t = i / 15;
    const th = cfg.th0 + sweep * t;
    const r = r0 * exp(-0.742 * sweep * t);
    const x = CX + r * cos(th);
    const y = CY + r * sin(th);
    const br = lerp(330, 150, t);
    const a = lerp(0.07, 0.13, t);
    radial(x, y, br, [[0, 'rgba(' + cfg.glowRGB + ',' + a + ')'], [1, 'rgba(' + cfg.glowRGB + ',0)']]);
  }
}

// thousands of fine spiral trails: the leaning itself
function paintStream(cfg) {
  for (let i = 0; i < cfg.n; i++) {
    const th0 = cfg.th0 + (random() - 0.5) * cfg.thSpread;
    const r0 = lerp(cfg.rMin, cfg.rMax, pow(random(), 0.85));
    const rEnd = 60 + random() * 74;
    const sweep = 2.55 + random() * 0.95;
    const decay = log(r0 / rEnd) / sweep;
    const steps = floor(120 + random() * 140);

    const cross = random() < 0.07;   // a strand of the other's color
    const accent = random() < 0.06;  // a broader painterly stroke
    let h = cross ? cfg.other + (random() - 0.5) * 12 : cfg.hue + (random() - 0.5) * cfg.hueJit;
    h = (h % 360 + 360) % 360;
    const s = constrain(cfg.sat + (random() - 0.5) * 2 * cfg.satJit, 25, 92);
    const b = constrain(cfg.bri + (random() - 0.5) * 2 * cfg.briJit + (accent ? 12 : 0), 40, 96);
    const wgt = accent ? 2.6 + random() * 2.4 : 0.8 + random() * 1.7;
    let al = accent ? 6 + random() * 8 : 9 + random() * 24;
    if (cross) al *= 0.75;
    strokeWeight(wgt);

    let px = null, py = 0;
    for (let k = 0; k <= steps; k++) {
      const prog = k / steps;
      const theta = th0 + sweep * prog;
      const r = r0 * exp(-decay * sweep * prog);
      const bx = CX + r * cos(theta);
      const by = CY + r * sin(theta);
      const nx = (noise(bx * 0.0022 + cfg.zoff, by * 0.0022) - 0.5) * 2;
      const ny = (noise(bx * 0.0022 + cfg.zoff + 37.7, by * 0.0022 + 91.3) - 0.5) * 2;
      const amp = cfg.wobble * (r / 620);
      const x = bx + nx * amp;
      const y = by + ny * amp;

      if (px !== null) {
        // near the meeting, color lets go and becomes light
        const fA = constrain(map(r, 430, 275, 0, 1), 0, 1);
        const fB = constrain(map(r, 275, 152, 0, 1), 0, 1);
        const s2 = lerp(s, 10, fA);
        const b2 = lerp(b, 94, fA);
        const dh = ((46 - h + 540) % 360) - 180;
        const h2 = (h + dh * fB * 0.85 + 360) % 360;
        const s3 = lerp(s2, 38, fB * 0.55);
        const b3 = lerp(b2, 100, fB);
        const ramp = min(1, k / 16);
        stroke(h2, s3, b3, al * ramp);
        line(px, py, x, y);
      }
      px = x; py = y;
    }
  }
}

// the ember: a small heart of the other's color, turning inside a current
function paintSeed(x, y, rgb, hsb) {
  radial(x, y, 115, [[0, 'rgba(' + rgb + ',0.30)'], [0.5, 'rgba(' + rgb + ',0.12)'], [1, 'rgba(' + rgb + ',0)']]);
  noFill();
  for (let i = 0; i < 16; i++) {
    const r = 18 + random() * 50;
    const a0 = random(TWO_PI);
    const len = 0.5 + random() * 0.9;
    const dir = random() < 0.5 ? 1 : -1;
    stroke(hsb[0], hsb[1], hsb[2], 16 + random() * 30);
    strokeWeight(0.9 + random() * 1.7);
    beginShape();
    for (let t = 0; t <= 1.001; t += 0.25) {
      const a = a0 + dir * len * t;
      const rr = r + (noise(a * 2.2 + x * 0.01, i * 5.3) - 0.5) * 10;
      vertex(x + rr * cos(a), y + rr * sin(a));
    }
    endShape();
  }
  radial(x, y, 34, [[0, 'rgba(255,255,255,0.5)'], [0.55, 'rgba(' + rgb + ',0.4)'], [1, 'rgba(' + rgb + ',0)']]);
  noStroke();
  fill(hsb[0], hsb[1] * 0.55, 100, 92);
  circle(x, y, 7.5);
}

// the meeting point: where the two become light
function paintCore() {
  radial(CX, CY, 400, [[0, 'rgba(255,150,140,0.16)'], [0.45, 'rgba(255,118,118,0.07)'], [1, 'rgba(255,110,110,0)']]);
  radial(CX, CY, 260, [[0, 'rgba(255,250,240,0.95)'], [0.28, 'rgba(255,226,164,0.60)'], [0.6, 'rgba(255,196,122,0.24)'], [1, 'rgba(255,188,112,0)']]);
  noFill();
  for (let i = 0; i < 120; i++) {
    const a = random(TWO_PI);
    const r0 = 50 + random() * 75;
    let len = 30 + random() * 150;
    if (random() < 0.18) len *= 1.6;
    const x0 = CX + r0 * cos(a), y0 = CY + r0 * sin(a);
    const a1 = a + (random() - 0.5) * 0.55;
    const x1 = CX + (r0 + len) * cos(a1), y1 = CY + (r0 + len) * sin(a1);
    const bend = (random() - 0.5) * len * 0.5;
    const mx = (x0 + x1) / 2 + cos(a + HALF_PI) * bend;
    const my = (y0 + y1) / 2 + sin(a + HALF_PI) * bend;
    stroke(42 + random() * 10, 20 + random() * 45, 96 + random() * 4, 8 + random() * 34);
    strokeWeight(0.7 + random() * 1.6);
    bezier(x0, y0, lerp(x0, mx, 0.6), lerp(y0, my, 0.6), mx, my, x1, y1);
  }
  noStroke();
  for (let i = 0; i < 80; i++) {
    const a = random(TWO_PI);
    const r = 90 + random() * 190;
    fill(45, 25 + random() * 40, 100, 16 + random() * 45);
    circle(CX + r * cos(a), CY + r * sin(a), 0.9 + random() * 1.5);
  }
  radial(CX, CY, 90, [[0, 'rgba(255,255,252,0.95)'], [0.45, 'rgba(255,248,228,0.55)'], [1, 'rgba(255,240,205,0)']]);
}

function paintForegroundDust() {
  noStroke();
  for (let i = 0; i < 220; i++) {
    const a = random(TWO_PI);
    const r = 150 + 750 * pow(random(), 1.4);
    const x = CX + r * cos(a);
    const y = CY + r * sin(a);
    if (x < 0 || x > W || y < 0 || y > H) continue;
    fill(45, 8 + random() * 15, 95 + random() * 5, 10 + random() * 22);
    circle(x, y, 1 + random() * 1.6);
  }
}

// canvas tooth
function paintGrain() {
  noStroke();
  for (let i = 0; i < 22000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) fill(230, 40, 3, 4 + random() * 5);
    else fill(45, 20, 100, 3 + random() * 4);
    rect(x, y, 1, 1);
  }
}

function paintVignette() {
  const g = drawingContext.createRadialGradient(CX, CY, 520, CX, CY, 1520);
  g.addColorStop(0, 'rgba(4,6,14,0)');
  g.addColorStop(0.75, 'rgba(4,6,14,0.18)');
  g.addColorStop(1, 'rgba(3,4,10,0.58)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

/* "The Field Between" — a painting about love
   p5.js 1.11 — still image, 1600 x 2000 */

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  paint();
}

function paint() {
  const W = 1600, H = 2000;
  const ctx = drawingContext;

  // ---- geometry of the two presences ----
  const M = { x: 800, y: 843 }; // the meeting point

  const L = {
    seed: 3.7,
    body: { x: 505, y: 975, rx: 232, ry: 328 },
    disks: [{ x: 618, y: 915, r: 128 }, { x: 662, y: 880, r: 88 }, { x: 702, y: 850, r: 56 }],
    heart: { x: 560, y: 948 },
    ramp: [[28,7,22],[74,16,48],[126,36,68],[184,68,91],[232,112,95],[255,168,135],[255,217,189]],
    amb: '150, 42, 72',
    glowS: '255, 190, 145',
    glow: [255, 190, 145],
    other: [90, 219, 196],
    coreC: [26, 8, 18],
  };

  const Rm = {
    seed: 9.1,
    body: { x: 1095, y: 975, rx: 232, ry: 328 },
    disks: [{ x: 982, y: 915, r: 128 }, { x: 938, y: 880, r: 88 }, { x: 898, y: 850, r: 56 }],
    heart: { x: 1040, y: 948 },
    ramp: [[4,20,26],[6,43,48],[10,74,76],[16,105,107],[43,163,152],[90,219,196],[194,245,230]],
    amb: '26, 112, 108',
    glowS: '160, 240, 215',
    glow: [160, 240, 215],
    other: [255, 168, 135],
    coreC: [5, 22, 26],
  };

  // ---- helpers ----
  const insideBody = (f, x, y) => {
    const b = f.body;
    const wob = 0.86 + 0.30 * noise(x * 0.005 + f.seed, y * 0.005 - f.seed);
    const dx = (x - b.x) / (b.rx * wob);
    const dy = (y - b.y) / (b.ry * wob);
    return dx * dx + dy * dy < 1;
  };

  const insideForm = (f, x, y) => {
    if (insideBody(f, x, y)) return true;
    for (const d of f.disks) {
      const wob = 0.84 + 0.32 * noise(x * 0.006 - f.seed, y * 0.006 + f.seed);
      if (dist(x, y, d.x, d.y) < d.r * wob) return true;
    }
    return false;
  };

  const rampColor = (ramp, t) => {
    const tt = constrain(t, 0, 1) * (ramp.length - 1);
    const i = floor(tt);
    const k = tt - i;
    const c1 = ramp[i], c2 = ramp[min(i + 1, ramp.length - 1)];
    return [lerp(c1[0], c2[0], k), lerp(c1[1], c2[1], k), lerp(c1[2], c2[2], k)];
  };

  const ringPath = (cx, cy, r, seed) => {
    beginShape();
    for (let a = 0; a <= 360; a += 3) {
      const th = radians(a);
      const rr = r + (noise(cos(th) * 1.4 + seed, sin(th) * 1.4 + seed * 0.5) - 0.5) * 30;
      vertex(cx + cos(th) * rr, cy + sin(th) * rr);
    }
    endShape(CLOSE);
  };

  // ================= 1. the night =================
  background(7, 9, 18);
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, 'rgba(20, 26, 52, 0.5)');
  sky.addColorStop(0.5, 'rgba(8, 10, 22, 0)');
  sky.addColorStop(1, 'rgba(3, 4, 10, 0.75)');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  noStroke();
  for (let i = 0; i < 9000; i++) { // dark tooth of the canvas
    const x = random(W), y = random(H), v = random();
    if (v < 0.45) fill(13, 18, 34, 9);
    else if (v < 0.8) fill(4, 6, 12, 11);
    else fill(22, 28, 52, 6);
    const s = random(0.6, 2.4);
    ellipse(x, y, s, s);
  }

  for (let i = 0; i < 200; i++) { // cold stars
    const x = random(W), y = random(H);
    if (insideForm(L, x, y) || insideForm(Rm, x, y)) continue;
    if (dist(x, y, M.x, M.y) < 250) continue;
    if (dist(x, y, 800, 1740) < 220) continue;
    const sp = i % 9 === 0;
    if (sp) { ctx.shadowBlur = 9; ctx.shadowColor = 'rgba(190, 205, 255, 0.8)'; }
    fill(205, 216, 255, random(15, 70));
    const r = sp ? random(1.1, 2.0) : random(0.4, 1.4);
    ellipse(x, y, r, r);
    ctx.shadowBlur = 0;
  }

  blendMode(ADD);
  for (let i = 0; i < 340; i++) { // faint warm dust in the dark
    fill(217, 185, 138, random(3, 10));
    ellipse(random(W), random(H), random(0.5, 1.6), random(0.5, 1.6));
  }
  blendMode(BLEND);

  // the quiet boundary of the field
  noFill();
  stroke(245, 223, 174, 10);
  strokeWeight(2.2);
  ringPath(800, 960, 575, 0);
  stroke(245, 223, 174, 6);
  strokeWeight(1.2);
  ringPath(800, 960, 591, 7);

  // ================= 2. ground and roots =================
  ctx.save();
  ctx.translate(800, 1300);
  ctx.scale(1, 0.3);
  const pool = ctx.createRadialGradient(0, 0, 0, 0, 0, 520);
  pool.addColorStop(0, 'rgba(58, 20, 18, 0.55)');
  pool.addColorStop(1, 'rgba(58, 20, 18, 0)');
  ctx.fillStyle = pool;
  ctx.fillRect(-520, -520, 1040, 1040);
  ctx.restore();

  ctx.save();
  ctx.translate(800, 1760);
  ctx.scale(1, 0.34);
  const pool2 = ctx.createRadialGradient(0, 0, 0, 0, 0, 430);
  pool2.addColorStop(0, 'rgba(44, 15, 11, 0.5)');
  pool2.addColorStop(1, 'rgba(44, 15, 11, 0)');
  ctx.fillStyle = pool2;
  ctx.fillRect(-430, -430, 860, 860);
  ctx.restore();

  noFill();
  strokeCap(ROUND);
  for (const side of [{ x: 520, y: 1272 }, { x: 1080, y: 1272 }]) {
    for (let i = 0; i < 24; i++) { // roots descending from each body
      const sx = side.x + random(-70, 70);
      const sy = side.y + random(-15, 35);
      const ex = 800 + random(-55, 55);
      const ey = 1745 + random(-45, 35);
      stroke(52, 22, 12, random(25, 60));
      strokeWeight(random(0.8, 3.2));
      bezier(sx, sy,
        lerp(sx, ex, 0.3) + random(-50, 50), lerp(sy, ey, 0.35) + random(-40, 40),
        lerp(sx, ex, 0.7) + random(-60, 60), lerp(sy, ey, 0.7) + random(-50, 50),
        ex, ey);
    }
  }

  for (let i = 0; i < 400; i++) { // the root-knot: love also goes down
    const a = random(TWO_PI);
    const rr = (0.2 + 0.8 * random()) * 140;
    const x = 800 + cos(a) * rr;
    const y = 1740 + sin(a) * rr * 0.85;
    const c = rampColor([[23,10,6],[46,18,10],[74,33,19],[110,52,30]], 1 - rr / 170);
    stroke(c[0], c[1], c[2], random(18, 55));
    strokeWeight(random(1, 3.6));
    const ang = random(TWO_PI);
    const ln = random(6, 24);
    line(x, y, x + cos(ang) * ln, y + sin(ang) * ln);
  }

  blendMode(ADD);
  const ember = ctx.createRadialGradient(800, 1742, 0, 800, 1742, 230);
  ember.addColorStop(0, 'rgba(190, 75, 28, 0.22)');
  ember.addColorStop(0.4, 'rgba(140, 50, 20, 0.10)');
  ember.addColorStop(1, 'rgba(120, 40, 15, 0)');
  ctx.fillStyle = ember;
  ctx.fillRect(540, 1480, 520, 520);
  noStroke();
  for (let i = 0; i < 70; i++) {
    const a = random(TWO_PI);
    const rr = random() * 150;
    fill(217, 106, 46, random(8, 55));
    ellipse(800 + cos(a) * rr, 1740 + sin(a) * rr * 0.85, random(0.5, 1.9), random(0.5, 1.9));
  }
  blendMode(BLEND);

  // ================= 3. the two presences =================
  drawPresence(L);
  drawPresence(Rm);

  function drawPresence(f) {
    const sgn = f.body.x < M.x ? 1 : -1;
    const b = f.body;
    const tip = f.disks[2];
    const sh = f.disks[0];

    // ambient presence in the dark
    blendMode(ADD);
    const amb = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, 640);
    amb.addColorStop(0, 'rgba(' + f.amb + ', 0.13)');
    amb.addColorStop(1, 'rgba(' + f.amb + ', 0)');
    ctx.fillStyle = amb;
    ctx.fillRect(b.x - 640, b.y - 640, 1280, 1280);
    blendMode(BLEND);

    // soft underlay: body and reaching arm
    noStroke();
    for (let i = 0; i < 13; i++) {
      const sc = 0.5 + 0.55 * (i / 12);
      const c = rampColor(f.ramp, 0.43 + random(-0.08, 0.08));
      fill(c[0], c[1], c[2], 11);
      ellipse(b.x + random(-28, 28), b.y + random(-34, 34), b.rx * 2 * sc, b.ry * 2 * sc);
    }
    for (let i = 0; i <= 14; i++) {
      const t = i / 14;
      const x = lerp(sh.x, tip.x, t), y = lerp(sh.y, tip.y, t);
      const r = lerp(118, 56, t) * random(0.9, 1.05);
      const c = rampColor(f.ramp, 0.5 + random(-0.15, 0.2));
      fill(c[0], c[1], c[2], 9);
      ellipse(x, y, r * 2, r * 2);
    }

    // painterly strokes: the flesh
    for (let i = 0; i < 4200; i++) {
      const x = random(b.x - b.rx - 40, b.x + b.rx + 60);
      const y = random(b.y - b.ry - 40, b.y + b.ry + 40);
      if (!insideForm(f, x, y)) continue;
      const nb = sqrt(((x - b.x) / b.rx) ** 2 + ((y - b.y) / b.ry) ** 2);
      const dh = dist(x, y, f.heart.x, f.heart.y) / 250;
      const dM = dist(x, y, M.x, M.y) / 620;
      const inLobe = dist(x, y, tip.x, tip.y) < 150;
      let t = 0.72 * (1 - dh) + 0.52 * (1 - dM) - 0.30 * min(nb, 1.1);
      if (inLobe) t += 0.34;
      t += (noise(x * 0.01 + f.seed * 3, y * 0.01) - 0.5) * 0.34;
      let c = rampColor(f.ramp, t);
      if (inLobe) { // each takes on a little of the other
        const k = 0.22 * (1 - dist(x, y, tip.x, tip.y) / 150);
        c = [lerp(c[0], f.other[0], k), lerp(c[1], f.other[1], k), lerp(c[2], f.other[2], k)];
      }
      if (dM < 0.34) { // gold catches them near the meeting
        const k = ((0.34 - dM) / 0.34) * 0.65;
        c = [lerp(c[0], 255, k), lerp(c[1], 210, k), lerp(c[2], 130, k)];
      }
      stroke(c[0], c[1], c[2], random(5, 16));
      strokeWeight(random(1.5, 7));
      const ang = atan2(y - b.y, x - b.x);
      let dir = ang + HALF_PI * sgn + (noise(x * 0.008, y * 0.008 + f.seed) - 0.5) * 1.6;
      if (inLobe) dir = lerp(dir, atan2(M.y - y, M.x - x), 0.45);
      const ln = random(9, 34);
      line(x, y, x + cos(dir) * ln, y + sin(dir) * ln);
    }

    // contour arcs: slow turning toward the other
    noFill();
    const dirToM = atan2(M.y - b.y, M.x - b.x);
    for (let i = 0; i < 55; i++) {
      const fr = random(0.55, 1.06);
      const a0 = random(TWO_PI);
      const span = random(0.5, 2.2);
      const facing = cos(a0 + span / 2 - dirToM);
      const t = 0.30 + 0.28 * (1 - fr) + 0.34 * max(0, facing) + random(-0.1, 0.1);
      const c = rampColor(f.ramp, t);
      stroke(c[0], c[1], c[2], random(10, 24));
      strokeWeight(random(2.5, 8));
      beginShape();
      for (let s = 0; s <= 26; s++) {
        const th = a0 + (span * s) / 26;
        const wob = 0.9 + 0.24 * noise(cos(th) * 2.2 + f.seed, sin(th) * 2.2 - f.seed);
        vertex(b.x + cos(th) * b.rx * fr * wob, b.y + sin(th) * b.ry * fr * wob);
      }
      endShape();
    }

    // long reaching gestures
    for (let i = 0; i < 12; i++) {
      const sy = random(880, 1100);
      const sx = b.x + sgn * random(60, 170);
      const ex = tip.x + random(-25, 25);
      const ey = tip.y + random(-28, 28);
      const c = rampColor(f.ramp, 0.62 + random(-0.15, 0.2));
      stroke(c[0], c[1], c[2], random(22, 48));
      strokeWeight(random(1.8, 4.5));
      bezier(sx, sy,
        lerp(sx, ex, 0.5) + sgn * random(-70, 30), lerp(sy, ey, 0.5) - random(10, 90),
        lerp(sx, ex, 0.75) + sgn * random(-30, 30), lerp(sy, ey, 0.8) - random(0, 40),
        ex, ey);
    }

    // the heart: light...
    blendMode(ADD);
    const hg = ctx.createRadialGradient(f.heart.x, f.heart.y, 0, f.heart.x, f.heart.y, 230);
    hg.addColorStop(0, 'rgba(' + f.glowS + ', 0.30)');
    hg.addColorStop(1, 'rgba(' + f.glowS + ', 0)');
    ctx.fillStyle = hg;
    ctx.fillRect(f.heart.x - 230, f.heart.y - 230, 460, 460);
    for (let i = 0; i < 240; i++) {
      const a = random(TWO_PI);
      const rr = random(62, 185);
      const x = f.heart.x + cos(a) * rr, y = f.heart.y + sin(a) * rr;
      const c = rampColor(f.ramp, 0.78 + random(0, 0.22));
      stroke(c[0], c[1], c[2], random(6, 16));
      strokeWeight(random(1, 4));
      const ln = random(6, 20);
      line(x, y, x + cos(a + HALF_PI) * ln, y + sin(a + HALF_PI) * ln);
    }
    // the inner face, lit by the shared fire
    const fg = ctx.createRadialGradient(tip.x + sgn * 34, tip.y, 0, tip.x + sgn * 34, tip.y, 150);
    fg.addColorStop(0, 'rgba(' + f.glowS + ', 0.30)');
    fg.addColorStop(1, 'rgba(' + f.glowS + ', 0)');
    ctx.fillStyle = fg;
    ctx.fillRect(tip.x - 170, tip.y - 150, 340, 300);
    blendMode(BLEND);

    // ...and the shadow it holds
    noStroke();
    for (let i = 0; i < 5; i++) {
      fill(f.coreC[0], f.coreC[1], f.coreC[2], 42);
      const rr = 62 - i * 7 + random(-6, 6);
      ellipse(f.heart.x + random(-5, 5), f.heart.y + random(-5, 5), rr * 2, rr * 2);
    }
    // rim of brightness cradling the shadow
    blendMode(ADD);
    noStroke();
    for (let i = 0; i < 60; i++) {
      const a = random(TWO_PI);
      const rr = random(52, 76);
      fill(f.glow[0], f.glow[1], f.glow[2], random(20, 70));
      ellipse(f.heart.x + cos(a) * rr, f.heart.y + sin(a) * rr, random(0.8, 2.2), random(0.8, 2.2));
    }
    blendMode(BLEND);
  }

  // ================= 4. the between =================
  const tipL = L.disks[2], tipR = Rm.disks[2];
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < 95; i++) { // threads woven across the gap
    const major = i < 7;
    const aL = random(-1.15, 1.15);
    const aR = PI + random(-1.15, 1.15);
    const p1x = tipL.x + cos(aL) * (tipL.r * random(0.9, 1.25));
    const p1y = tipL.y + sin(aL) * (tipL.r * random(0.9, 1.25));
    const p2x = tipR.x + cos(aR) * (tipR.r * random(0.9, 1.25));
    const p2y = tipR.y + sin(aR) * (tipR.r * random(0.9, 1.25));
    const cx = 800 + random(-30, 30);
    const cy = (p1y + p2y) / 2 + random(-75, 55);
    stroke(255, 232, 176, major ? 55 : random(10, 40));
    strokeWeight(major ? 2.6 : random(0.5, 1.7));
    bezier(p1x, p1y, cx, cy, cx + random(-25, 25), cy + random(-20, 20), p2x, p2y);
    if (random() < 0.5) {
      stroke(255, 240, 200, random(6, 14));
      strokeWeight(0.6);
      bezier(p1x, p1y + 2, cx, cy + 3, cx + random(-20, 20), cy + 2, p2x, p2y + 2);
    }
  }
  for (let i = 0; i < 10; i++) { // the connection also deepens downward
    const p1x = 728 + random(-8, 8), p1y = 920 + random(-25, 25);
    const p2x = 872 + random(-8, 8), p2y = 920 + random(-25, 25);
    stroke(255, 232, 176, random(8, 18));
    strokeWeight(random(0.6, 1.4));
    bezier(p1x, p1y, 800 + random(-30, 30), 1090 + random(-50, 60),
      800 + random(-30, 30), 1150 + random(-40, 40), p2x, p2y);
  }

  // the shared fire
  blendMode(ADD);
  const bloom = ctx.createRadialGradient(M.x, M.y, 0, M.x, M.y, 210);
  bloom.addColorStop(0, 'rgba(255, 248, 226, 0.9)');
  bloom.addColorStop(0.18, 'rgba(255, 226, 160, 0.5)');
  bloom.addColorStop(0.55, 'rgba(255, 196, 110, 0.16)');
  bloom.addColorStop(1, 'rgba(255, 180, 90, 0)');
  ctx.fillStyle = bloom;
  ctx.fillRect(M.x - 210, M.y - 210, 420, 420);
  noStroke();
  for (let i = 0; i < 800; i++) { // gold sparks
    const gx = M.x + (random() + random() + random() - 1.5) * 128;
    const gy = M.y + (random() + random() + random() - 1.5) * 100;
    const fall = constrain(1 - dist(gx, gy, M.x, M.y) / 260, 0.15, 1);
    fill(255, 205 + random(50), 140 + random(80), random(20, 150) * fall + 8);
    const r = random(0.5, 2.3) * (0.5 + 0.5 * fall);
    ellipse(gx, gy, r, r);
  }
  for (let i = 0; i < 14; i++) {
    ctx.shadowBlur = 14;
    ctx.shadowColor = 'rgba(255, 210, 130, 0.9)';
    fill(255, 236, 190, random(80, 170));
    ellipse(M.x + random(-90, 90), M.y + random(-70, 70), random(2.5, 5), random(2.5, 5));
  }
  ctx.shadowBlur = 0;

  // seeds of light falling between them, toward the root
  for (let i = 0; i < 90; i++) {
    fill(255, 210, 140, random(5, 16));
    ellipse(800 + random(-60, 60), 920 + random(0, 360), random(0.6, 1.8), random(0.6, 1.8));
  }

  // sparks rising, cooling into stars
  for (let i = 0; i < 30; i++) {
    let x = M.x + random(-75, 75);
    let y = 815 + random(-25, 45);
    const topY = random(150, 430);
    const drift = random(-190, 190);
    const step = random(7, 13);
    const nSteps = max(1, (y - topY) / step);
    let n = 0;
    while (y > topY && n < 220) {
      const t = constrain((815 - y) / (815 - topY + 1), 0, 1);
      const cool = min(1, t * 0.9);
      const cr = lerp(255, 205, cool);
      const cg = lerp(216, 218, cool);
      const cb = lerp(150, 255, cool);
      const al = lerp(180, 10, pow(t, 0.75)) * random(0.5, 1);
      if (n % 14 === 0) {
        ctx.shadowBlur = 10;
        ctx.shadowColor = 'rgba(220, 215, 235, 0.8)';
      }
      fill(cr, cg, cb, al);
      const sz = lerp(2.4, 0.7, t) * random(0.7, 1.3);
      ellipse(x, y, sz, sz);
      ctx.shadowBlur = 0;
      y -= step * random(0.7, 1.3);
      x += (noise(i * 0.7 + 20, n * 0.06) - 0.5) * 26 + drift / nSteps;
      n++;
    }
  }
  blendMode(BLEND);

  // ================= 5. air and vignette =================
  const vig = ctx.createRadialGradient(800, 1000, 500, 800, 1000, 1380);
  vig.addColorStop(0, 'rgba(2, 3, 8, 0)');
  vig.addColorStop(0.7, 'rgba(2, 3, 8, 0.18)');
  vig.addColorStop(1, 'rgba(2, 3, 8, 0.55)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, W, H);

  noStroke();
  for (let i = 0; i < 5500; i++) { // final grain
    if (random() < 0.5) fill(200, 208, 228, random(2, 5));
    else fill(0, 0, 0, random(2, 6));
    ellipse(random(W), random(H), random(0.5, 1.5), random(0.5, 1.5));
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  paintNight();
  paintMottle();
  paintStars();
  paintForms();
  paintStream();
  paintBloom();
  paintRings();
  paintSparks();
  paintVignette();
  paintGrain();
}

function softCircle(x, y, r, rgb, a) {
  if (r <= 0 || a <= 0) return;
  const g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + rgb + ',' + a + ')');
  g.addColorStop(1, 'rgba(' + rgb + ',0)');
  drawingContext.fillStyle = g;
  drawingContext.beginPath();
  drawingContext.arc(x, y, r, 0, Math.PI * 2);
  drawingContext.fill();
}

function paintNight() {
  const g = drawingContext.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#251b48');
  g.addColorStop(0.45, '#181236');
  g.addColorStop(1, '#0a0719');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);
}

function paintMottle() {
  for (let i = 0; i < 240; i++) {
    const x = random(width);
    const y = random(height);
    const r = random(140, 460);
    if (noise(x * 0.0016, y * 0.0016) > 0.5) {
      softCircle(x, y, r, '96,74,150', random(0.025, 0.06));
    } else {
      softCircle(x, y, r, '10,7,24', random(0.03, 0.07));
    }
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 280; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.55) {
      const ang = random(TWO_PI);
      const d = pow(random(1), 1.7) * 950;
      x = constrain(800 + cos(ang) * d * 1.15, 0, width);
      y = constrain(1010 + sin(ang) * d * 1.35, 0, height);
    }
    const s = random(0.6, 2.6);
    const a = random(0.12, 0.65);
    const warm = random() < 0.35;
    if (warm) fill(255, 228, 196, a * 255);
    else fill(198, 208, 255, a * 255);
    circle(x, y, s);
    if (s > 1.8) {
      softCircle(x, y, s * 6, warm ? '255,220,180' : '190,200,255', a * 0.22);
    }
  }
}

function drawBlob(cx, cy, rx, ry, rgb, coreRgb, n, off) {
  for (let i = 0; i < n; i++) {
    const ang = random(TWO_PI);
    const wob = 0.7 + 0.6 * noise(cos(ang) * 1.7 + off, sin(ang) * 1.7 + off * 0.63);
    const d = pow(random(1), 0.55);
    const x = cx + cos(ang) * rx * d * wob;
    const y = cy + sin(ang) * ry * d * wob;
    softCircle(x, y, random(24, 85), rgb, random(0.015, 0.05));
  }
  for (let i = 0; i < n * 0.55; i++) {
    const ang = random(TWO_PI);
    const d = pow(random(1), 0.85) * 0.6;
    const x = cx + cos(ang) * rx * d;
    const y = cy + sin(ang) * ry * d;
    softCircle(x, y, random(18, 60), coreRgb, random(0.03, 0.07));
  }
}

function paintForms() {
  drawBlob(490, 1090, 440, 390, '255,148,88', '255,206,152', 850, 3.1);
  drawBlob(690, 1045, 265, 245, '255,172,102', '255,216,164', 420, 7.7);
  drawBlob(1115, 1000, 415, 375, '224,82,132', '255,142,178', 850, 9.3);
  drawBlob(915, 1025, 255, 240, '242,112,152', '255,172,192', 420, 4.2);
}

function paintStream() {
  for (let i = 0; i < 540; i++) {
    const t = i / 539;
    let x = bezierPoint(600, 745, 875, 1005, t);
    let y = bezierPoint(1065, 915, 1125, 985, t);
    x += (noise(t * 8, 3.3) - 0.5) * 80;
    y += (noise(t * 8, 7.1) - 0.5) * 80;
    const mid = sin(PI * t);
    softCircle(x, y, random(5, 12) + mid * 15, '255,236,196', 0.035 + mid * 0.2);
  }
}

function paintBloom() {
  softCircle(800, 1010, 780, '255,188,105', 0.05);
  softCircle(800, 1010, 540, '255,204,128', 0.07);
  softCircle(800, 1010, 370, '255,220,160', 0.10);
  softCircle(800, 1010, 245, '255,236,196', 0.16);
  softCircle(800, 1010, 155, '255,246,222', 0.28);
  softCircle(800, 1010, 88, '255,250,236', 0.5);
  softCircle(816, 996, 52, '255,253,244', 0.6);
  softCircle(800, 1010, 34, '255,255,252', 0.9);
}

function paintRings() {
  drawingContext.save();
  drawingContext.shadowColor = 'rgba(255,224,175,0.9)';
  drawingContext.shadowBlur = 28;
  noFill();
  stroke(255, 232, 192, 80);
  strokeWeight(2.5);
  circle(800, 1010, 590);
  stroke(255, 232, 192, 45);
  strokeWeight(2);
  circle(800, 1010, 680);
  drawingContext.restore();
}

function paintSparks() {
  noStroke();
  for (let i = 0; i < 230; i++) {
    const ang = random(TWO_PI);
    const d = pow(random(1), 1.6) * 780;
    const x = 800 + cos(ang) * d * 1.15;
    const y = 1010 + sin(ang) * d * 1.3;
    const s = random(1, 4.6);
    const a = map(d, 0, 820, 0.95, 0.04, true);
    const warm = random() < 0.72;
    if (warm) fill(255, 226, 168, a * 255);
    else fill(255, 205, 235, a * 255);
    circle(x, y, s);
    if (random() < 0.22) softCircle(x, y, s * 5, '255,226,170', a * 0.3);
  }
}

function paintVignette() {
  const vg = drawingContext.createRadialGradient(800, 1010, 320, 800, 1010, 1500);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.72, 'rgba(6,3,16,0.18)');
  vg.addColorStop(1, 'rgba(4,2,12,0.66)');
  drawingContext.fillStyle = vg;
  drawingContext.fillRect(0, 0, width, height);
}

function paintGrain() {
  noStroke();
  for (let i = 0; i < 5200; i++) {
    const a = random(0.015, 0.05);
    if (random() < 0.5) fill(255, 255, 255, a * 255);
    else fill(2, 2, 10, a * 255);
    rect(random(width), random(height), 1.4, 1.4);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // deep indigo background, vertical gradient
  const cTop = color(7, 5, 20);
  const cBot = color(24, 17, 40);
  noStroke();
  for (let y = 0; y < height; y += 4) {
    fill(lerpColor(cTop, cBot, y / height));
    rect(0, y, width, 5);
  }

  // the two lights and the bloom between them
  const L = { x: 500, y: 1270 };
  const R = { x: 1100, y: 1270 };
  const B = { x: 800, y: 850 };

  const rose = color(255, 138, 112);
  const roseDeep = color(255, 96, 78);
  const gold = color(255, 208, 130);
  const goldDeep = color(255, 168, 78);
  const cream = color(255, 246, 228);

  drawingContext.globalCompositeOperation = 'lighter';

  // cool starfield dust
  for (let i = 0; i < 2400; i++) {
    const x = random(width), y = random(height);
    const n = noise(x * 0.0013, y * 0.0013, 3.1);
    if (n > 0.5) {
      fill(160 + n * 90, 130 + n * 80, 210, map(n, 0.5, 1, 0, 40));
      ellipse(x, y, random(2, 12), random(2, 9));
    }
  }

  // warm dust gathered toward the middle
  for (let i = 0; i < 3000; i++) {
    const x = width / 2 + (random() + random() + random() - 1.5) * 640;
    const y = height * 0.6 + (random() + random() + random() - 1.5) * 780;
    const n = noise(x * 0.002, y * 0.002, 9.7);
    fill(255, 195 + n * 60, 150 + n * 70, map(n, 0.35, 1, 0, 24));
    ellipse(x, y, random(1.5, 8), random(1.5, 6));
  }

  // scattered stars
  for (let i = 0; i < 240; i++) {
    const x = random(width), y = random(height);
    const s = random(1, 3.2);
    fill(255, 250, 240, random(40, 150));
    ellipse(x, y, s * 2, s * 2);
  }

  // faint ambient halos
  glow(L.x, L.y, 720, rose, color(40, 14, 30), 9);
  glow(R.x, R.y, 720, gold, color(40, 26, 10), 9);
  glow(B.x, B.y, 640, cream, color(60, 30, 20), 7);

  // bodies of light rising from the bottom edge, leaning inward
  lightFigure(300, 2140, 330, 1700, 400, 1420, L.x, L.y + 30, 165, 66, rose, 7);
  lightFigure(1300, 2140, 1270, 1700, 1200, 1420, R.x, R.y + 30, 165, 66, gold, 7);

  // the two heads — solid glowing cores
  drawingContext.globalCompositeOperation = 'source-over';
  glow(L.x, L.y, 440, color(255, 216, 192), roseDeep, 165, 1.06);
  glow(L.x, L.y, 195, color(255, 246, 234), color(255, 158, 128), 210, 1.06);
  glow(R.x, R.y, 440, color(255, 242, 208), goldDeep, 165, 1.06);
  glow(R.x, R.y, 195, color(255, 253, 242), color(255, 216, 152), 210, 1.06);

  drawingContext.globalCompositeOperation = 'lighter';

  // motes orbiting each head
  for (let i = 0; i < 90; i++) {
    const h = i % 2 === 0 ? L : R;
    const ang = random(TWO_PI);
    const rad = random(190, 470);
    fill(255, 230, 200, random(50, 160));
    ellipse(h.x + cos(ang) * rad, h.y + sin(ang) * rad * 0.9, random(2, 6), random(2, 6));
  }

  // beams of light streaming from each head toward the shared bloom
  const beams = [];
  for (let i = 0; i < 110; i++) {
    const h = i % 2 === 0 ? L : R;
    const baseCol = i % 2 === 0 ? rose : gold;
    beams.push({
      x0: h.x + random(-150, 150),
      y0: h.y + random(-70, 100),
      x1: lerp(h.x, B.x, 0.3) + random(-170, 170),
      y1: lerp(h.y, B.y, 0.35) + random(-130, 130),
      x2: lerp(h.x, B.x, 0.72) + random(-100, 100),
      y2: lerp(h.y, B.y, 0.72) + random(-70, 70),
      x3: B.x + random(-210, 210),
      y3: B.y + random(-170, 160),
      w: random(1, 4.2),
      a: random(16, 64),
      c: lerpColor(baseCol, cream, random(0.25, 0.9))
    });
  }
  // a few broad, soft beams
  for (let i = 0; i < 10; i++) {
    const h = i % 2 === 0 ? L : R;
    beams.push({
      x0: h.x + random(-60, 60), y0: h.y - 40,
      x1: lerp(h.x, B.x, 0.35) + random(-120, 120), y1: lerp(h.y, B.y, 0.4) - 60,
      x2: lerp(h.x, B.x, 0.7) + random(-70, 70), y2: lerp(h.y, B.y, 0.7),
      x3: B.x + random(-120, 120), y3: B.y + random(-90, 90),
      w: random(9, 22), a: random(5, 11),
      c: lerpColor(h === L ? rose : gold, cream, 0.5)
    });
  }
  noFill();
  for (const b of beams) {
    stroke(red(b.c), green(b.c), blue(b.c), b.a);
    strokeWeight(b.w);
    bezier(b.x0, b.y0, b.x1, b.y1, b.x2, b.y2, b.x3, b.y3);
  }

  // braid of light directly between the two heads
  for (let i = 0; i < 60; i++) {
    const t = i / 60;
    const c = lerpColor(rose, gold, constrain(t + random(-0.15, 0.15), 0, 1));
    stroke(red(c), green(c), blue(c), random(14, 52));
    strokeWeight(random(1, 3.6));
    bezier(
      L.x + random(-60, 80), L.y + random(-50, 70),
      620 + random(-140, 140), 1090 + random(-120, 120),
      980 + random(-140, 140), 1090 + random(-120, 120),
      R.x + random(-80, 60), R.y + random(-70, 50)
    );
  }
  // bright core strand linking the two heads
  for (let w = 46; w > 4; w -= 6) {
    stroke(255, 232, 205, map(w, 46, 4, 4, 26));
    strokeWeight(w);
    bezier(L.x + 20, L.y + 10, 700, 1180, 900, 1180, R.x - 20, R.y + 10);
  }

  // the bloom — brightest point, above and between
  glow(B.x, B.y, 560, cream, color(255, 186, 138), 12, 1.12);
  glow(B.x, B.y, 330, color(255, 250, 238), color(255, 200, 150), 46, 1.12);
  glow(B.x, B.y, 130, color(255, 255, 252), color(255, 236, 210), 150, 1.1);

  // organic ripples radiating from the bloom
  noFill();
  for (let r = 150; r <= 1000; r += 62) {
    stroke(255, 226, 192, map(r, 150, 1000, 40, 3));
    strokeWeight(2.4);
    beginShape();
    for (let a = 0; a <= TWO_PI + 0.06; a += 0.045) {
      const wob = (noise(cos(a) * 1.7 + r * 0.013, sin(a) * 1.7, r * 0.008) - 0.5) * 60;
      const rr = r + wob;
      vertex(B.x + cos(a) * rr, B.y + sin(a) * rr * 1.1);
    }
    endShape(CLOSE);
  }

  // particles riding the beams
  for (const b of beams) {
    const n = floor(random(1, 5));
    for (let k = 0; k < n; k++) {
      const t = random();
      const p = bezierPoint(b.x0, b.y0, b.x1, b.y1, b.x2, b.y2, b.x3, b.y3, t);
      const s = random(1.6, 5.4);
      noStroke();
      fill(255, 236 + random(19), 205 + random(40), random(90, 220));
      ellipse(p.x, p.y, s * 2, s * 2);
      if (random() < 0.28) {
        stroke(255, 252, 240, 190);
        strokeWeight(1.2);
        const Ln = s * random(3, 6.5);
        line(p.x - Ln, p.y, p.x + Ln, p.y);
        line(p.x, p.y - Ln, p.x, p.y + Ln);
      }
    }
  }

  // sparkles around the bloom
  for (let i = 0; i < 60; i++) {
    const ang = random(TWO_PI);
    const rad = random(60, 620);
    const x = B.x + cos(ang) * rad;
    const y = B.y + sin(ang) * rad * 1.05;
    const s = random(1.4, 4);
    noStroke();
    fill(255, 250, 235, random(80, 220));
    ellipse(x, y, s * 2, s * 2);
    if (random() < 0.4) {
      stroke(255, 252, 242, 210);
      strokeWeight(1.1);
      const Ln = s * random(3, 7);
      line(x - Ln, y, x + Ln, y);
      line(x, y - Ln, x, y + Ln);
    }
  }

  // film grain
  drawingContext.globalCompositeOperation = 'source-over';
  for (let i = 0; i < 9000; i++) {
    fill(random(255), random(255), random(255), random(3, 9));
    rect(random(width), random(height), 1.6, 1.6);
  }

  // vignette to pull the eye to the center
  noFill();
  for (let r = 900; r <= 1750; r += 14) {
    stroke(4, 3, 12, map(r, 900, 1750, 0, 120));
    strokeWeight(15);
    ellipse(width / 2, height * 0.52, r * 2, r * 2 * 1.18);
  }
}

// soft radial glow, drawn center-out
function glow(x, y, r, cIn, cOut, maxA, sy) {
  sy = sy || 1;
  const steps = 44;
  noStroke();
  for (let i = 0; i <= steps; i++) {
    const f = i / steps;
    const rr = r * f;
    const c = lerpColor(cIn, cOut, f);
    fill(red(c), green(c), blue(c), maxA * pow(1 - f, 2.2));
    ellipse(x, y, rr * 2, rr * 2 * sy);
  }
}

// tapering column of light along a bezier (a leaning body of light)
function lightFigure(x0, y0, x1, y1, x2, y2, x3, y3, r0, r1, col, maxA) {
  const steps = 80;
  noStroke();
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const p = bezierPoint(x0, y0, x1, y1, x2, y2, x3, y3, t);
    const r = lerp(r0, r1, t) * (0.85 + noise(t * 6, 4.2) * 0.35);
    const fade = sin(PI * constrain(t * 1.12, 0, 1));
    fill(red(col), green(col), blue(col), maxA * (0.25 + 0.75 * fade));
    ellipse(p.x, p.y, r * 2, r * 2 * 1.15);
  }
}

let W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  noLoop();
}

function glow(x, y, maxR, r, g, b, ma) {
  noStroke();
  const S = 48;
  for (let i = S; i >= 1; i--) {
    const t = i / S;
    const a = ma * pow(1 - t, 2.2);
    fill(r, g, b, a);
    ellipse(x, y, maxR * t * 2, maxR * t * 2);
  }
}

function drawArm(P, cH, cM, cC) {
  const N = 120;
  const pts = [], rads = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const tm = max(0, t - 0.008);
    const xa = bezierPoint(P[0], P[1], P[2], P[3], tm);
    const ya = bezierPoint(P[4], P[5], P[6], P[7], tm);
    const xb = bezierPoint(P[0], P[1], P[2], P[3], t);
    const yb = bezierPoint(P[4], P[5], P[6], P[7], t);
    pts.push({ x: xb, y: yb, ang: atan2(yb - ya, xb - xa) });
    rads.push((165 * pow(1 - t, 0.8) + 26) * (1 + 0.05 * sin(t * 13)));
  }
  const passes = [
    { s: 2.1, col: cH, a: 15 },
    { s: 1.3, col: cM, a: 40 },
    { s: 0.8, col: cC, a: 110 }
  ];
  noStroke();
  for (const p of passes) {
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const c = lerpColor(p.col, color(255, 250, 240), t * 0.65);
      fill(red(c), green(c), blue(c), p.a);
      const r = rads[i] * p.s;
      push();
      translate(pts[i].x, pts[i].y);
      rotate(pts[i].ang);
      ellipse(0, 0, r * 1.55, r);
      pop();
    }
  }
  // fingertips reaching
  const tip = pts[N];
  const rt = rads[N];
  const fingers = [
    { o: 38, w: 0, r: 0.90 },
    { o: 24, w: 18, r: 0.68 },
    { o: 24, w: -18, r: 0.68 },
    { o: 13, w: 31, r: 0.54 },
    { o: 13, w: -31, r: 0.54 }
  ];
  for (const p of passes) {
    const c = lerpColor(p.col, color(255, 252, 246), 0.85);
    fill(red(c), green(c), blue(c), min(255, p.a * 1.15));
    push();
    translate(tip.x, tip.y);
    rotate(tip.ang);
    for (const f of fingers) {
      const r = rt * p.s * f.r;
      ellipse(f.o, f.w, r * 2.2, r * 1.5);
    }
    pop();
  }
}

function draw() {
  background(12, 10, 28);

  // organic background mottling
  noStroke();
  for (let y = 0; y < H; y += 36) {
    for (let x = 0; x < W; x += 36) {
      const n = noise(x * 0.0016, y * 0.0016);
      if (n > 0.52) {
        fill(110, 100, 190, (n - 0.52) * 90);
        rect(x, y, 36, 36);
      }
    }
  }

  // deep ambient halo
  glow(800, 640, 1050, 80, 66, 150, 20);

  // distant dust
  for (let i = 0; i < 420; i++) {
    const x = random(W), y = random(H * 0.92);
    const s = random(0.8, 2.6), a = random(12, 60);
    const c = lerpColor(color(140, 150, 230), color(255, 210, 220), random());
    fill(red(c), green(c), blue(c), a);
    circle(x, y, s);
  }

  // two reaching forms
  const L = [120, 2080, 140, 1250, 430, 680, 742, 438];
  const R = [1480, 2080, 1460, 1250, 1170, 680, 858, 438];
  drawArm(L, color(150, 40, 90), color(215, 70, 125), color(255, 130, 170));
  drawArm(R, color(170, 100, 30), color(235, 150, 60), color(255, 205, 120));

  // light catching the fingertips
  glow(742, 438, 170, 255, 150, 185, 60);
  glow(858, 438, 170, 255, 218, 140, 60);

  // rays from the point between them
  push();
  translate(800, 430);
  noStroke();
  for (let k = 0; k < 14; k++) {
    const a = k * TWO_PI / 14 + random(0.25);
    const len = 240 + random(430);
    const wd = 6 + random(26);
    fill(255, 225, 170, random(5, 14));
    push();
    rotate(a);
    ellipse(len * 0.55, 0, len, wd);
    pop();
  }
  pop();

  // the light born in the gap
  glow(800, 430, 640, 255, 214, 150, 120);
  glow(800, 430, 310, 255, 240, 200, 170);
  glow(800, 430, 140, 255, 252, 238, 215);
  glow(800, 430, 58, 255, 255, 255, 235);

  // sparks gathered near the light
  for (let i = 0; i < 240; i++) {
    const x = 800 + randomGaussian(0, 120 + 300 * random());
    const y = 430 + randomGaussian(0, 140 + 240 * random());
    const s = random(1, 5.5), a = random(40, 190);
    const pick = random();
    const c = pick < 0.4 ? color(255, 235, 200)
            : pick < 0.75 ? color(255, 170, 200)
            : color(200, 190, 255);
    if (s > 4) {
      fill(red(c), green(c), blue(c), a * 0.25);
      circle(x, y, s * 5);
    }
    fill(red(c), green(c), blue(c), a);
    circle(x, y, s);
  }

  // embers rising from the light
  for (let i = 0; i < 110; i++) {
    const h = pow(random(), 1.7) * 820;
    const x = 800 + randomGaussian(0, 26 + h * 0.38);
    const y = 430 - h;
    const a = map(h, 0, 820, 230, 8, true);
    const s = random(1.2, 4.6);
    const c = random() < 0.6 ? color(255, 215, 150) : color(255, 160, 190);
    fill(red(c), green(c), blue(c), a);
    circle(x, y, s);
  }

  // light spilling down between the arms
  for (let i = 0; i < 50; i++) {
    const h = pow(random(), 1.5) * 520;
    const x = 800 + randomGaussian(0, 30 + h * 0.3);
    const y = 430 + h;
    const a = map(h, 0, 520, 120, 6, true);
    const c = random() < 0.6 ? color(255, 225, 170) : color(255, 175, 200);
    fill(red(c), green(c), blue(c), a);
    circle(x, y, random(1.2, 4));
  }

  // vignette
  noStroke();
  for (let i = 1; i <= 46; i++) {
    const t = i / 46;
    fill(5, 4, 13, 78 * pow(t, 2.4));
    ellipse(W / 2, H / 2, 1560 * t * 2, 1560 * t * 2);
  }

  // film grain
  strokeWeight(1);
  for (let i = 0; i < 6500; i++) {
    stroke(random(130, 255), random(120, 240), random(150, 255), random(2.5, 9));
    point(random(W), random(H));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  const W = width, H = height;
  const ctx = drawingContext;

  // deep background
  blendMode(BLEND);
  const bg = ctx.createLinearGradient(0, 0, W * 0.3, H);
  bg.addColorStop(0, '#2d1d52');
  bg.addColorStop(0.4, '#1a1132');
  bg.addColorStop(0.75, '#0d0820');
  bg.addColorStop(1, '#060310');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // distant nebulae
  blendMode(ADD);
  nebula(330, 430, 800, 'rgba(125,85,225,0.055)');
  nebula(1300, 680, 720, 'rgba(60,145,225,0.05)');
  nebula(480, 1680, 840, 'rgba(205,75,145,0.05)');
  nebula(1270, 1620, 780, 'rgba(95,65,205,0.06)');
  nebula(800, 1000, 950, 'rgba(255,150,120,0.045)');

  // the two lights
  const A = { x: 600, y: 700, r: 430, wob: 0.16, ox: 11.7, oy: 3.2 };
  const B = { x: 1000, y: 1300, r: 470, wob: 0.18, ox: 47.3, oy: 29.8 };

  // soft halos
  paintBlob(A, 1.38, [
    [0, 'rgba(255,120,90,0.10)'],
    [0.55, 'rgba(240,90,110,0.055)'],
    [1, 'rgba(220,70,120,0)']
  ]);
  paintBlob(B, 1.38, [
    [0, 'rgba(110,170,255,0.10)'],
    [0.55, 'rgba(90,120,240,0.055)'],
    [1, 'rgba(70,80,220,0)']
  ]);

  // main bodies
  paintBlob(A, 1.0, [
    [0, 'rgba(255,210,155,0.85)'],
    [0.35, 'rgba(255,150,105,0.55)'],
    [0.7, 'rgba(235,95,95,0.30)'],
    [0.9, 'rgba(220,80,110,0.12)'],
    [1, 'rgba(210,70,110,0)']
  ]);
  paintBlob(B, 1.0, [
    [0, 'rgba(195,228,255,0.85)'],
    [0.35, 'rgba(120,165,255,0.55)'],
    [0.7, 'rgba(95,105,240,0.28)'],
    [0.9, 'rgba(85,90,230,0.11)'],
    [1, 'rgba(80,80,225,0)']
  ]);

  // hot cores
  paintBlob(A, 0.52, [
    [0, 'rgba(255,244,220,0.9)'],
    [0.6, 'rgba(255,200,150,0.45)'],
    [1, 'rgba(255,170,120,0)']
  ]);
  paintBlob(B, 0.52, [
    [0, 'rgba(240,250,255,0.9)'],
    [0.6, 'rgba(170,210,255,0.45)'],
    [1, 'rgba(140,180,255,0)']
  ]);

  // the golden meeting
  const gx = (A.x + B.x) / 2, gy = (A.y + B.y) / 2;
  const ang = atan2(B.y - A.y, B.x - A.x);

  goldGlow(gx, gy, ang, 480, [[0, 'rgba(255,215,150,0.28)'], [0.5, 'rgba(255,190,110,0.15)'], [1, 'rgba(255,180,100,0)']], 0.52);
  goldGlow(gx, gy, ang, 310, [[0, 'rgba(255,225,165,0.42)'], [0.55, 'rgba(255,195,120,0.20)'], [1, 'rgba(255,185,105,0)']], 0.55);
  goldGlow(gx, gy, ang, 165, [[0, 'rgba(255,238,195,0.72)'], [0.6, 'rgba(255,210,140,0.32)'], [1, 'rgba(255,200,120,0)']], 0.6);
  goldGlow(gx, gy, ang, 72, [[0, 'rgba(255,250,232,0.95)'], [1, 'rgba(255,225,170,0)']], 0.65);

  // ripple rings of resonance
  noFill();
  for (let i = 0; i < 6; i++) {
    const rr = 150 + i * 115;
    stroke(255, 220, 160, 26 - i * 4);
    strokeWeight(1.7 - i * 0.2);
    push();
    translate(gx, gy);
    rotate(ang);
    ellipse(0, 0, rr * 2, rr * 2 * 0.55);
    pop();
  }

  // filaments woven between the two lights
  for (let i = 0; i < 60; i++) {
    const a1 = random(TWO_PI), a2 = random(TWO_PI);
    const r1 = edgeR(a1, A), r2 = edgeR(a2, B);
    const x1 = A.x + cos(a1) * r1, y1 = A.y + sin(a1) * r1;
    const x2 = B.x + cos(a2) * r2, y2 = B.y + sin(a2) * r2;
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
    stroke(255, 228, 175, random(12, 58));
    strokeWeight(random(0.5, 2.3));
    noFill();
    bezier(x1, y1,
      mx + random(-290, 290), my + random(-290, 290),
      mx + random(-290, 290), my + random(-290, 290),
      x2, y2);
  }

  // rays falling outward from the glow
  for (let i = 0; i < 30; i++) {
    const a = random(TWO_PI);
    const len = random(320, 950);
    const x1 = gx + cos(a) * random(30, 120), y1 = gy + sin(a) * random(30, 120);
    const x2 = gx + cos(a) * len + random(-140, 140), y2 = gy + sin(a) * len + random(-140, 140);
    stroke(255, 224, 170, random(8, 26));
    strokeWeight(random(0.5, 1.6));
    noFill();
    bezier(x1, y1,
      lerp(x1, x2, 0.35) + random(-70, 70), lerp(y1, y2, 0.35) + random(-70, 70),
      lerp(x1, x2, 0.7) + random(-70, 70), lerp(y1, y2, 0.7) + random(-70, 70),
      x2, y2);
  }

  // drifting sparks
  noStroke();
  for (let i = 0; i < 280; i++) {
    let x, y;
    if (random() < 0.5) {
      const a = random(TWO_PI), d = random(40, 640);
      x = gx + cos(a) * d * 1.15;
      y = gy + sin(a) * d * 0.85;
    } else {
      x = random(W);
      y = random(H);
    }
    x = constrain(x, 0, W);
    y = constrain(y, 0, H);
    const dG = dist(x, y, gx, gy);
    const warm = dG < 460;
    const s = random(0.8, 3.2);
    const al = random(0.15, 0.8);
    if (s > 2.5) {
      fill(warm ? `rgba(255,220,170,${al * 0.15})` : `rgba(170,205,255,${al * 0.15})`);
      circle(x, y, s * 7);
    }
    fill(warm ? `rgba(255,222,170,${al})` : `rgba(175,208,255,${al * 0.85})`);
    circle(x, y, s * 2);
  }

  // soft bokeh orbs
  for (let i = 0; i < 9; i++) {
    const bx = random(W), by = random(H);
    const warm = random() < 0.5;
    const br = random(70, 200);
    const g = ctx.createRadialGradient(bx, by, br * 0.1, bx, by, br);
    g.addColorStop(0, warm ? 'rgba(255,200,150,0.07)' : 'rgba(150,190,255,0.07)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(bx, by, br, 0, TWO_PI);
    ctx.fill();
  }

  // vignette
  blendMode(BLEND);
  const v = ctx.createRadialGradient(W / 2, H / 2, H * 0.25, W / 2, H / 2, H * 0.78);
  v.addColorStop(0, 'rgba(4,2,10,0)');
  v.addColorStop(1, 'rgba(3,1,8,0.62)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, W, H);

  // film grain
  const gr = createGraphics(400, 500);
  gr.loadPixels();
  for (let i = 0; i < gr.pixels.length; i += 4) {
    const val = random(0, 255);
    gr.pixels[i] = val;
    gr.pixels[i + 1] = val;
    gr.pixels[i + 2] = val;
    gr.pixels[i + 3] = random(8, 30);
  }
  gr.updatePixels();
  image(gr, 0, 0, W, H);
}

function edgeR(a, b) {
  const n = noise(cos(a) * 1.4 + b.ox, sin(a) * 1.4 + b.oy);
  return b.r * (1 + (n - 0.5) * 2 * b.wob);
}

function paintBlob(b, scale, stops) {
  const ctx = drawingContext;
  const steps = 240;
  ctx.beginPath();
  for (let i = 0; i <= steps; i++) {
    const a = ((i % steps) / steps) * TWO_PI;
    const r = edgeR(a, b) * scale;
    const x = b.x + cos(a) * r;
    const y = b.y + sin(a) * r;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  const gr = b.r * 1.3 * scale;
  const g = ctx.createRadialGradient(b.x, b.y, gr * 0.05, b.x, b.y, gr);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.fill();
}

function nebula(x, y, r, c) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, r * 0.1, x, y, r);
  g.addColorStop(0, c);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TWO_PI);
  ctx.fill();
}

function goldGlow(gx, gy, ang, R, stops, squash) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(gx, gy);
  ctx.rotate(ang);
  ctx.scale(1, squash);
  const g = ctx.createRadialGradient(0, 0, R * 0.05, 0, 0, R);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, R, 0, TWO_PI);
  ctx.fill();
  ctx.restore();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function paint() {
  let ctx = drawingContext;

  // deep background
  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0, '#060818');
  bg.addColorStop(0.5, '#0d1128');
  bg.addColorStop(1, '#1c1132');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  noStroke();

  // fine grain
  for (let i = 0; i < 6000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    fill(255, 250, 255, n > 0.55 ? random(3, 9) : random(1, 4));
    rect(x, y, 1.3, 1.3);
  }

  // scattered souls in the dark
  let cool = [
    [140, 170, 255],
    [190, 160, 255],
    [110, 200, 255],
    [225, 210, 255],
    [160, 140, 240]
  ];
  for (let i = 0; i < 750; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, 800, 1000) / 1100;
    let s = random(0.7, 2.6) * (1.25 - min(d, 1) * 0.55);
    let c = random(cool);
    fill(c[0], c[1], c[2], random(25, 115));
    circle(x, y, s);
  }

  // warm motes gathered near the meeting place
  for (let i = 0; i < 170; i++) {
    let t = random(1);
    let x = lerp(600, 1000, t) + (noise(i * 0.7, 3) - 0.5) * 460;
    let y = 1000 + (noise(i * 1.3, 7) - 0.5) * 460;
    fill(255, random(150, 225), random(110, 185), random(40, 130));
    circle(x, y, random(0.8, 2.8));
  }

  // faint threads pulling distant points inward
  strokeWeight(0.6);
  for (let i = 0; i < 90; i++) {
    let x = random(width);
    let y = random(height);
    let tx = random() < 0.5 ? 600 : 1000;
    let ty = 1000 + random(-170, 170);
    stroke(200, 190, 255, random(8, 20));
    line(x, y, lerp(x, tx, 0.86), lerp(y, ty, 0.86));
  }
  noStroke();

  blendMode(ADD);

  // soft bokeh lights
  for (let i = 0; i < 14; i++) {
    let x = random(width);
    let y = random(height * 0.8);
    let r = random(35, 140);
    let c = random() < 0.5 ? color(140, 150, 255) : color(255, 165, 185);
    glow(x, y, r, c, 7);
  }

  // wide halos
  glow(600, 1000, 560, color(255, 105, 150), 22);
  glow(1000, 1000, 560, color(255, 185, 95), 22);
  glow(800, 1000, 430, color(255, 220, 190), 30);

  // orbit rings
  noFill();
  stroke(210, 190, 255, 26);
  strokeWeight(1);
  push(); translate(800, 1000); rotate(-0.18); ellipse(0, 0, 1180, 580); pop();
  push(); translate(800, 1000); rotate(0.13); ellipse(0, 0, 920, 450); pop();
  stroke(255, 200, 165, 20);
  push(); translate(600, 1000); rotate(0.32); ellipse(0, 0, 600, 320); pop();
  push(); translate(1000, 1000); rotate(-0.27); ellipse(0, 0, 600, 320); pop();
  noStroke();

  // woven bridge of light between the two cores
  for (let s = 0; s < 48; s++) {
    let base = map(s, 0, 47, -155, 155);
    let wob = random(24, 70);
    let steps = 56;
    let px = 600, py = 1000 + base;
    for (let i = 1; i <= steps; i++) {
      let t = i / steps;
      let x = lerp(600, 1000, t);
      let y = 1000 + base * sin(PI * t) + (noise(s * 0.45, i * 0.16) - 0.5) * wob * 2 * sin(PI * t);
      let c = lerpColor(color(255, 140, 175), color(255, 220, 140), t);
      stroke(red(c), green(c), blue(c), 25 + 115 * sin(PI * t));
      strokeWeight(map(sin(PI * t), 0, 1, 0.6, 3.4));
      line(px, py, x, y);
      px = x; py = y;
    }
  }
  noStroke();

  // the two cores
  glow(600, 1000, 250, color(255, 135, 170), 95);
  glow(560, 955, 130, color(255, 170, 200), 70);
  glow(1000, 1000, 250, color(255, 210, 135), 95);
  glow(1040, 1050, 130, color(255, 235, 170), 70);
  glow(800, 1000, 190, color(255, 240, 215), 120);

  // hot centers
  fill(255, 235, 235, 170); circle(600, 1000, 74);
  fill(255, 248, 220, 170); circle(1000, 1000, 74);
  fill(255, 255, 250, 215); circle(800, 1000, 52);

  // rising embers
  for (let i = 0; i < 170; i++) {
    let h = pow(random(1), 1.4);
    let y = 950 - h * 840;
    let spread = 36 + h * 340;
    let x = 800 + (noise(i * 0.9, h * 3) - 0.5) * 2 * spread + random(-1, 1) * spread * 0.35;
    let s = lerp(3.4, 0.7, h) * random(0.7, 1.3);
    let a = lerp(160, 6, h);
    if (random(1) < 0.78) {
      fill(255, random(170, 235), random(110, 175), a);
    } else {
      fill(225, 205, 255, a * 0.8);
    }
    circle(x, y, s);
  }

  // reflection pool below
  glow(800, 1520, 460, color(255, 175, 115), 9);
  glow(800, 1600, 320, color(255, 135, 150), 6);
  for (let i = 0; i < 46; i++) {
    let x = 800 + (noise(i * 0.8, 11) - 0.5) * 520;
    let y = 1130 + random(520);
    stroke(255, 200, 160, random(3, 12));
    strokeWeight(random(1, 3));
    line(x, y, x + random(-16, 16), y + random(24, 100));
  }
  noStroke();
  blendMode(BLEND);

  // vignette
  let vg = ctx.createRadialGradient(800, 1020, 320, 800, 1020, 1330);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.7, 'rgba(3,3,12,0.18)');
  vg.addColorStop(1, 'rgba(2,2,9,0.6)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

function glow(x, y, R, c, peak) {
  noStroke();
  for (let r = R; r > 0; r -= 2) {
    let t = 1 - r / R;
    let a = peak * pow(t, 2.4);
    let cc = lerpColor(c, color(255, 255, 255), pow(t, 3) * 0.85);
    fill(red(cc), green(cc), blue(cc), a);
    circle(x, y, r * 2);
  }
}

