function mix(a, b, t) {
  return a.map((v, i) => v + (b[i] - v) * t);
}

function sky() {
  noFill();
  for (let y = 0; y < H; y++) {
    const t = y / H;
    let c;
    if (t < 0.43)
      c = mix([25,43,56], [126,139,123], t / 0.43);
    else
      c = mix([126,139,123], [207,160,111], (t - 0.43) / 0.57);
    stroke(...c);
    line(0, y, W, y);
  }

  glow(800, 1040, 670, [247,199,128], 0.52);
  glow(800, 1180, 340, [255,222,161], 0.38);

  // Broad, translucent scumbles keep the sky from looking digital.
  noStroke();
  for (let i = 0; i < 11500; i++) {
    const x = random(W), y = random(1550);
    const n = noise(x * 0.003, y * 0.003);
    fill(224, 200, 157, 3 + n * 9);
    ellipse(x, y, random(6, 34), random(2, 10));
  }
}

function glow(x, y, radius, rgb, alpha) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x,y,0,x,y,radius);
  g.addColorStop(0, `rgba(${rgb.join(",")},${alpha})`);
  g.addColorStop(1, `rgba(${rgb.join(",")},0)`);
  ctx.save();
  ctx.fillStyle = g;
  ctx.fillRect(x-radius, y-radius, radius*2, radius*2);
  ctx.restore();
