function samplePath(segments) {
  let points = [];
  for (let s = 0; s < segments.length; s++) {
    const a = segments[s];
    for (let i = 0; i <= 90; i++) {
      if (s > 0 && i === 0) continue;
      let t = i/90;
      let x = bezierPoint(a[0],a[2],a[4],a[6],t);
      let y = bezierPoint(a[1],a[3],a[5],a[7],t);
      let dx = bezierTangent(a[0],a[2],a[4],a[6],t);
      let dy = bezierTangent(a[1],a[3],a[5],a[7],t);
      let len = sqrt(dx*dx+dy*dy) || 1;
      points.push({x,y,nx:-dy/len,ny:dx/len});
    }
  }
  return points;
}

function wood(segments, base, tip, palette) {
  const pts = samplePath(segments);
  const widths = pts.map((p,i) => {
    const t = i/(pts.length-1);
    return (tip+(base-tip)*pow(1-t,0.85)) *
      (0.9+0.18*noise(p.x*0.008,p.y*0.008));
  });

  noStroke();
  fill(...palette[0]);
  beginShape();
  for (let i=0; i<pts.length; i++) {
    const p=pts[i], w=widths[i]/2;
    vertex(p.x+p.nx*w,p.y+p.ny*w);
  }
  for (let i=pts.length-1; i>=0; i--) {
    const p=pts[i], w=widths[i]/2;
    vertex(p.x-p.nx*w,p.y-p.ny*w);
  }
  endShape(CLOSE);

  // Long fibers follow the living curves of the trunks.
  for (let k=0; k<95; k++) {
    const side=random(-0.96,0.96);
    const col=palette[floor(random(palette.length))];
    stroke(...col,random(75,170));
    strokeWeight(random(0.7,3.8));
    noFill();
    beginShape();
    for (let i=0; i<pts.length; i++) {
      const p=pts[i];
      const wobble=(noise(k*0.4,i*0.065)-0.5)*0.15;
      const offset=(side+wobble)*widths[i]*0.48;
      vertex(p.x+p.nx*offset,p.y+p.ny*offset);
    }
    endShape();
  }

  // Short, broken impasto marks over the fibers.
  for (let k=0; k<base*13; k++) {
    const i=floor(random(pts.length-2));
    const p=pts[i], next=pts[min(i+2,pts.length-1)];
    const off=random(-0.43,0.43)*widths[i];
    const c=random(palette);
    stroke(...c,random(45,135));
    strokeWeight(random(1,4));
    line(p.x+p.nx*off,p.y+p.ny*off,
         next.x+next.nx*off,next.y+next.ny*off);
  }
}

