// Opaque underpainting followed by translucent, dry-brush pigment.
// Bounds are [left, top, right, bottom].
function pigment(p, bounds, base, colors, count, opacity, direction) {
  const c = drawingContext;
  c.save();
  c.fillStyle = base;
  c.fill(p);
  c.clip(p);
  c.lineCap = "round";

  for (let i = 0; i < count; i++) {
    const x = random(bounds[0], bounds[2]);
    const y = random(bounds[1], bounds[3]);
    const a = direction + random(-0.7, 0.7);
    const len = random(7, 65);
    const dx = cos(a) * len, dy = sin(a) * len;
    c.strokeStyle = random(colors);
    c.globalAlpha = random(0.025, opacity);
    c.lineWidth = random(1, 15);
    c.beginPath();
    c.moveTo(x, y);
    c.quadraticCurveTo(
      x + dx * 0.45 + random(-5, 5),
      y + dy * 0.45,
      x + dx, y + dy
    );
    c.stroke();

    if (i % 3 === 0) {
      c.lineWidth = random(0.5, 1.8);
      c.globalAlpha *= 1.5;
      c.beginPath();
      c.moveTo(x + 3, y);
      c.lineTo(x + dx + 3, y + dy);
      c.stroke();
    }
  }
  c.restore();
}

function ribbon(s, colorValue, weight, opacity) {
  const c = drawingContext;
  c.save();
  c.strokeStyle = colorValue;
  c.globalAlpha = opacity;
  c.lineWidth = weight;
  c.lineCap = "round";
  c.lineJoin = "round";
  c.stroke(path(s));
  c.restore();
}

const W = 1600, H = 2000, G = 1060;
const CX = 800, CY = 1520;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  drawSky();
  drawHills();
  drawSoil();
  drawUndergroundGlow();

  // roots: left tree reaches right, right tree reaches left
  let leftRootCol = color(92, 62, 48);
  let rightRootCol = color(118, 58, 44);
  for (let i = 0; i < 7; i++) {
    let a = map(i, 0, 6, PI * 0.18, PI * 0.82);
    drawRoot(520 + random(-15, 15), G + 10, a, 34 - abs(i - 3) * 3, 5,
             createVector(1180 + random(-80, 80), 1650 + random(-150, 200)), leftRootCol);
  }
  for (let i = 0; i < 7; i++) {
    let a = map(i, 0, 6, PI * 0.18, PI * 0.82);
    drawRoot(1080 + random(-15, 15), G + 10, a, 34 - abs(i - 3) * 3, 5,
             createVector(420 + random(-80, 80), 1650 + random(-150, 200)), rightRootCol);
  }

  drawGroundLine();

  // trees above
  drawTree(520, G + 5, 0.07, color(44, 84, 78));
  drawTree(1080, G + 5, -0.07, color(96, 100, 52));

  drawGrass();
  grain();
}

function drawSky() {
  let c1 = color(22, 26, 58), c2 = color(92, 70, 112), c3 = color(236, 160, 118);
  for (let y = 0; y < G; y++) {
    let t = y / G;
    let c = t < 0.55 ? lerpColor(c1, c2, t / 0.55) : lerpColor(c2, c3, pow((t - 0.55) / 0.45, 1.3));
    stroke(c);
    line(0, y, W, y);
  }
  // warm light between the trees
  noStroke();
  for (let r = 700; r > 0; r -= 8) {
    fill(255, 200, 140, 3);
    ellipse(CX, G - 40, r * 2.2, r * 1.2);
  }
  // stars
  for (let i = 0; i < 220; i++) {
    let x = random(W), y = pow(random(), 1.8) * G * 0.6;
    let s = random(1, 3.2);
    fill(255, 245, 225, random(60, 200));
    ellipse(x, y, s, s);
  }
}

function drawHills() {
  noStroke();
  let layers = [
    [color(120, 92, 128, 200), G - 150, 120, 0.002],
    [color(84, 66, 100, 230), G - 70, 80, 0.003]
  ];
  for (let L of layers) {
    fill(L[0]);
    beginShape();
    vertex(0, G + 5);
    for (let x = 0; x <= W; x += 10) {
      vertex(x, L[1] + noise(x * L[3], L[1]) * L[2] - L[2] * 0.3);
    }
    vertex(W, G + 5);
    endShape(CLOSE);
  }
}

function surfaceY(x) {
  return G + (noise(x * 0.004, 50) - 0.5) * 30;
}

function drawSoil() {
  let c1 = color(96, 62, 40), c2 = color(48, 28, 22), c3 = color(18, 11, 10);
  for (let y = G - 30; y < H; y++) {
    let t = (y - G) / (H - G);
    t = constrain(t, 0, 1);
    let c = t < 0.4 ? lerpColor(c1, c2, t / 0.4) : lerpColor(c2, c3, (t - 0.4) / 0.6);
    stroke(c);
    line(0, y, W, y);
  }
  // cover sky gap above uneven surface handled in drawGroundLine
  // strata
  noFill();
  for (let i = 0; i < 40; i++) {
    let y0 = random(G + 40, H);
    stroke(random() < 0.5 ? color(140, 96, 64, 22) : color(10, 6, 5, 30));
    strokeWeight(random(2, 14));
    beginShape();
    for (let x = -20; x <= W + 20; x += 20) {
      curveVertex(x, y0 + (noise(x * 0.003, i) - 0.5) * 80);
    }
    endShape();
  }
  // stones
  noStroke();
  for (let i = 0; i < 110; i++) {
    let x = random(W), y = random(G + 60, H);
    let s = random(6, 38) * (0.5 + (y - G) / (H - G));
    fill(70 + random(40), 58 + random(30), 50 + random(25), 150);
    ellipse(x, y, s * random(1, 1.8), s);
    fill(200, 170, 140, 25);
    ellipse(x - s * 0.15, y - s * 0.15, s * 0.6, s * 0.4);
  }
}

function drawUndergroundGlow() {
  noStroke();
  for (let r = 560; r > 0; r -= 6) {
    let a = map(r, 560, 0, 1, 6);
    fill(255, 186, 90, a);
    ellipse(CX, CY, r * 1.6, r * 1.25);
  }
}

function drawRoot(x, y, a, w, depth, target, col) {
  let steps = floor(random(45, 85));
  for (let i = 0; i < steps; i++) {
    let desired = atan2(target.y - y, target.x - x);
    let diff = desired - a;
    while (diff > PI) diff -= TWO_PI;
    while (diff < -PI) diff += TWO_PI;
    a += diff * 0.035 + (noise(x * 0.01, y * 0.01, depth) - 0.5) * 0.35;
    let step = 9;
    let nx = x + cos(a) * step, ny = y + sin(a) * step;
    if (ny < G + 8) ny = G + 8;

    let d = dist(nx, ny, CX, CY);
    let warmth = constrain(map(d, 420, 60, 0, 1), 0, 1);
    let c = lerpColor(col, color(214, 150, 78), warmth * 0.7);

    stroke(20, 12, 10, 120);
    strokeWeight(w + 2);
    line(x, y, nx, ny);
    stroke(c);
    strokeWeight(w);
    line(x, y, nx, ny);
    if (w > 3) {
      stroke(255, 210, 150, 25 + warmth * 90);
      strokeWeight(max(1, w * 0.25));
      line(x - w * 0.2, y - w * 0.2, nx - w * 0.2, ny - w * 0.2);
    }
    if (warmth > 0.3) {
      stroke(255, 220, 140, warmth * 70);
      strokeWeight(w + 6);
      point(nx, ny);
    }

    x = nx; y = ny;
    w *= 0.985;
    if (w < 0.6 || y > H + 20 || x < -20 || x > W + 20) return;

    if (depth > 0 && random() < 0.05) {
      let t2 = createVector(target.x + random(-260, 260), target.y + random(-200, 260));
      drawRoot(x, y, a + random(-0.9, 0.9), w * 0.62, depth - 1, t2, col);
    }
  }
}

function drawGroundLine() {
  // re-fill sky above uneven surface, and soil top
  noStroke();
  fill(96, 62, 40);
  beginShape();
  vertex(0, G + 40);
  for (let x = 0; x <= W; x += 8) vertex(x, surfaceY(x));
  vertex(W, G + 40);
  endShape(CLOSE);
}

function drawTree(x, y, lean, leafCol) {
  // trunk flare
  noStroke();
  fill(34, 24, 26);
  beginShape();
  vertex(x - 46, y + 8);
  bezierVertex(x - 24, y - 20, x - 20, y - 80, x - 18, y - 140);
  vertex(x + 18, y - 140);
  bezierVertex(x + 20, y - 80, x + 24, y - 20, x + 46, y + 8);
  endShape(CLOSE);
  branch(x, y - 100, -HALF_PI + lean, 210, 36, 7, leafCol);
}

function branch(x, y, a, len, w, d, leafCol) {
  let mx = x + cos(a) * len * 0.5 + random(-len * 0.06, len * 0.06);
  let my = y + sin(a) * len * 0.5;
  let x2 = x + cos(a) * len, y2 = y + sin(a) * len;
  noFill();
  stroke(34, 24, 26);
  strokeWeight(w);
  bezier(x, y, mx, my, mx, my, x2, y2);
  // rim light from the warm center
  let side = x < CX ? 1 : -1;
  stroke(240, 160, 110, 60);
  strokeWeight(max(1, w * 0.18));
  bezier(x + side * w * 0.35, y, mx + side * w * 0.35, my, mx + side * w * 0.3, my, x2 + side * w * 0.3, y2);

  if (d === 0) {
    leaves(x2, y2, leafCol);
    return;
  }
  let n = random() < 0.6 ? 2 : 3;
  for (let i = 0; i < n; i++) {
    let na = a + (i - (n - 1) / 2) * 0.55 + random(-0.3, 0.3);
    na = constrain(na, -PI + 0.25, -0.25);
    branch(x2, y2, na, len * random(0.68, 0.8), w * 0.66, d - 1, leafCol);
  }
}

function leaves(x, y, base) {
  noStroke();
  let warm = color(240, 170, 100);
  for (let i = 0; i < 16; i++) {
    let lx = x + randomGaussian() * 26, ly = y + randomGaussian() * 20;
    let light = constrain(1 - abs(lx - CX) / 700, 0, 1) * 0.5 + random(-0.1, 0.15);
    let c = lerpColor(base, warm, constrain(light, 0, 0.7));
    c = lerpColor(c, color(20, 22, 34), random(0, 0.35));
    fill(red(c), green(c), blue(c), 150);
    let s = random(8, 20);
    push();
    translate(lx, ly);
    rotate(random(TWO_PI));
    ellipse(0, 0, s, s * 0.6);
    pop();
  }
}

function drawGrass() {
  for (let x = 0; x < W; x += 3) {
    let y = surfaceY(x);
    let h = random(8, 26) * (0.6 + noise(x * 0.01, 9));
    stroke(lerpColor(color(40, 50, 40), color(150, 120, 80), random(0.1, 0.5)));
    strokeWeight(random(1, 2.5));
    line(x, y + 4, x + random(-6, 6), y - h);
  }
  // thin line marking the surface
  noFill();
  stroke(20, 14, 12, 160);
  strokeWeight(3);
  beginShape();
  for (let x = 0; x <= W; x += 8) vertex(x, surfaceY(x) + 6);
  endShape();
}

function grain() {
  for (let i = 0; i < 60000; i++) {
    stroke(random() < 0.5 ? 255 : 0, random(6, 16));
    strokeWeight(random(1, 2));
    point(random(W), random(H));
  }
}

const W = 1600, H = 2000, GROUND = 1050;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  strokeCap(ROUND);
}

function draw() {
  drawSky();
  drawSun();
  drawEarth();
  drawGlow(800, 1580, 620);
  drawRoots();
  drawGroundSurface();

  const goldPal = [color(245, 190, 80), color(230, 150, 50), color(255, 215, 120), color(210, 120, 40)];
  const rosePal = [color(215, 85, 85), color(240, 130, 110), color(180, 60, 75), color(250, 165, 135)];

  branch(450, GROUND + 8, 215, -HALF_PI - 0.06, 46, 9, goldPal);
  branch(1150, GROUND + 8, 215, -HALF_PI + 0.06, 46, 9, rosePal);

  drawFallenLeaves(goldPal, rosePal);
  drawFireflies();
}

function drawSky() {
  const top = color(28, 36, 78), mid = color(120, 80, 120), low = color(252, 185, 135);
  for (let y = 0; y < GROUND + 20; y++) {
    let t = y / GROUND;
    let c = t < 0.6 ? lerpColor(top, mid, t / 0.6) : lerpColor(mid, low, (t - 0.6) / 0.4);
    stroke(c);
    line(0, y, W, y);
  }
  noStroke();
  for (let i = 0; i < 140; i++) {
    let y = random(0, 500);
    fill(255, 245, 230, map(y, 0, 500, 180, 0) * random(0.3, 1));
    let s = random(1.5, 3.5);
    ellipse(random(W), y, s, s);
  }
}

function drawSun() {
  noStroke();
  for (let r = 420; r > 0; r -= 6) {
    fill(255, 200, 140, map(r, 420, 0, 0, 14));
    ellipse(800, GROUND - 20, r * 2, r * 2);
  }
  fill(255, 236, 200);
  ellipse(800, GROUND - 10, 170, 170);
}

function drawEarth() {
  const a = color(78, 50, 34), b = color(18, 11, 10);
  for (let y = GROUND; y < H; y++) {
    stroke(lerpColor(a, b, (y - GROUND) / (H - GROUND)));
    line(0, y, W, y);
  }
  noFill();
  for (let s = 0; s < 14; s++) {
    let base = GROUND + 60 + s * 68;
    stroke(0, 0, 0, 30);
    strokeWeight(random(2, 8));
    beginShape();
    for (let x = -20; x <= W + 20; x += 20) {
      vertex(x, base + (noise(x * 0.003, s * 3) - 0.5) * 70);
    }
    endShape();
  }
  noStroke();
  for (let i = 0; i < 260; i++) {
    let y = random(GROUND + 30, H);
    let s = random(4, 22);
    fill(random(60, 110), random(45, 75), random(35, 55), random(60, 140));
    ellipse(random(W), y, s, s * random(0.6, 0.9));
  }
}

function drawGlow(cx, cy, r) {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
  g.addColorStop(0, 'rgba(255,190,110,0.55)');
  g.addColorStop(0.4, 'rgba(230,120,80,0.22)');
  g.addColorStop(1, 'rgba(120,50,40,0)');
  ctx.fillStyle = g;
  ctx.fillRect(cx - r, cy - r, r * 2, r * 2);
}

function growRoot(x, y, ang, w, tx, ty, paths, depth, seed) {
  let pts = [];
  let steps = int(random(150, 230));
  for (let i = 0; i < steps; i++) {
    pts.push({ x: x, y: y, w: w });
    let desired = atan2(ty - y, tx - x);
    let diff = atan2(sin(desired - ang), cos(desired - ang));
    ang += diff * 0.035 + (noise(seed, i * 0.04) - 0.5) * 0.28;
    x += cos(ang) * 6;
    y += sin(ang) * 6;
    if (y < GROUND + 25) { y = GROUND + 25; ang = abs(ang); }
    x = constrain(x, 10, W - 10);
    y = min(y, H - 15);
    w *= 0.988;
    if (w < 1) break;
    if (depth < 3 && random() < 0.025) {
      growRoot(x, y, ang + random(-1, 1), w * 0.6,
        tx + random(-300, 300), ty + random(-200, 200), paths, depth + 1, seed + 17 + i);
    }
  }
  paths.push(pts);
}

function drawRoots() {
  let left = [], right = [];
  for (let i = 0; i < 8; i++) {
    let a = map(i, 0, 7, 0.25, PI - 0.25) + random(-0.1, 0.1);
    growRoot(450, GROUND + 15, a, random(14, 24), random(650, 1250), random(1300, 1900), left, 0, i * 10);
    let b = map(i, 0, 7, PI - 0.25, 0.25) + random(-0.1, 0.1);
    growRoot(1150, GROUND + 15, b, random(14, 24), random(350, 950), random(1300, 1900), right, 0, 500 + i * 10);
  }
  let all = [];
  let n = max(left.length, right.length);
  for (let i = 0; i < n; i++) {
    if (i < left.length) all.push({ p: left[i], c: [250, 195, 95] });
    if (i < right.length) all.push({ p: right[i], c: [240, 125, 115] });
  }
  noFill();
  for (let r of all) {
    for (let j = 1; j < r.p.length; j++) {
      let a = r.p[j - 1], b = r.p[j];
      stroke(10, 5, 5, 120);
      strokeWeight(b.w + 5);
      line(a.x, a.y, b.x, b.y);
    }
    for (let j = 1; j < r.p.length; j++) {
      let a = r.p[j - 1], b = r.p[j];
      let d = dist(b.x, b.y, 800, 1580);
      let glow = constrain(map(d, 0, 650, 1, 0.35), 0.35, 1);
      stroke(r.c[0] * glow, r.c[1] * glow, r.c[2] * glow, 230);
      strokeWeight(b.w);
      line(a.x, a.y, b.x, b.y);
      stroke(255, 235, 200, 90 * glow);
      strokeWeight(max(1, b.w * 0.25));
      line(a.x - b.w * 0.2, a.y - b.w * 0.2, b.x - b.w * 0.2, b.y - b.w * 0.2);
    }
  }
}

function drawGroundSurface() {
  noStroke();
  fill(42, 40, 30);
  beginShape();
  vertex(0, GROUND + 30);
  for (let x = 0; x <= W; x += 10) vertex(x, GROUND - 6 + noise(x * 0.01) * 14);
  vertex(W, GROUND + 30);
  endShape(CLOSE);
  for (let i = 0; i < 900; i++) {
    let x = random(W);
    let h = random(8, 30);
    stroke(random(40, 75), random(50, 80), random(30, 45), 220);
    strokeWeight(random(1.5, 3));
    let y = GROUND + random(-2, 10);
    line(x, y, x + random(-6, 6), y - h);
  }
}

function branch(x, y, len, ang, w, d, pal) {
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  stroke(38, 26, 30);
  strokeWeight(w);
  line(x, y, x2, y2);
  if (d === 0) {
    noStroke();
    for (let k = 0; k < 10; k++) {
      let c = color(pal[int(random(pal.length))]);
      c.setAlpha(190);
      fill(c);
      push();
      translate(x2 + random(-20, 20), y2 + random(-20, 20));
      rotate(random(TWO_PI));
      ellipse(0, 0, random(8, 16), random(5, 10));
      pop();
    }
    return;
  }
  let n = random() < 0.3 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let a = ang + map(i, 0, n - 1, -1, 1) * random(0.25, 0.55) + random(-0.1, 0.1);
    branch(x2, y2, len * random(0.68, 0.8), a, w * 0.68, d - 1, pal);
  }
}

function drawFallenLeaves(goldPal, rosePal) {
  noStroke();
  for (let i = 0; i < 70; i++) {
    let fromLeft = random() < 0.5;
    let pal = fromLeft ? goldPal : rosePal;
    let x = fromLeft ? random(200, 900) : random(700, 1400);
    let c = color(pal[int(random(pal.length))]);
    c.setAlpha(210);
    fill(c);
    push();
    translate(x, GROUND + random(-4, 10));
    rotate(random(TWO_PI));
    ellipse(0, 0, random(9, 15), random(4, 7));
    pop();
  }
}

function drawFireflies() {
  noStroke();
  for (let i = 0; i < 30; i++) {
    let x = random(600, 1000), y = random(650, 1000);
    for (let r = 20; r > 0; r -= 4) {
      fill(255, 230, 150, map(r, 20, 0, 0, 60));
      ellipse(x, y, r, r);
    }
    fill(255, 250, 220);
    ellipse(x, y, 3, 3);
  }
}

let groundY = [];
let leafTipsA = [];
let leafTipsB = [];

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function gy(x) {
  let xi = constrain(floor(x), 0, width - 1);
  return groundY[xi];
}

function draw() {
  for (let x = 0; x < width; x++) {
    groundY[x] = 1050 + 28 * sin(x * 0.0032 + 0.6) + (noise(x * 0.004) - 0.5) * 50;
  }
  basePixels();
  skyStrokes();
  stars();
  soilTexture();
  rootGlow();
  minorRoots();
  mainRoots();
  trees();
  grassLine();
  grain();
}

function basePixels() {
  let top = color(22, 30, 62), mid = color(96, 72, 118), low = color(236, 160, 104);
  let s1 = color(62, 40, 26), s2 = color(18, 11, 8);
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let g = groundY[x];
      let r, gg, b;
      if (y < g) {
        let t = y / g;
        let n = (noise(x * 0.003, y * 0.006) - 0.5) * 0.12;
        t = constrain(t + n, 0, 1);
        let c;
        if (t < 0.6) c = lerpColor(top, mid, t / 0.6);
        else c = lerpColor(mid, low, (t - 0.6) / 0.4);
        r = red(c); gg = green(c); b = blue(c);
      } else {
        let t = constrain((y - g) / 900, 0, 1);
        let strata = noise(x * 0.0015, y * 0.018) - 0.5;
        let c = lerpColor(s1, s2, constrain(t + strata * 0.35, 0, 1));
        r = red(c); gg = green(c); b = blue(c);
      }
      let i = 4 * (y * width + x);
      pixels[i] = r; pixels[i + 1] = gg; pixels[i + 2] = b; pixels[i + 3] = 255;
    }
  }
  updatePixels();
}

function skyStrokes() {
  noFill();
  for (let i = 0; i < 2600; i++) {
    let x = random(width);
    let y = random(0, 1050);
    if (y > gy(x) - 10) continue;
    let t = y / 1050;
    let c = t > 0.65 ? color(255, random(170, 210), random(110, 150), 18)
                     : color(random(80, 150), random(70, 110), random(130, 170), 16);
    stroke(c);
    strokeWeight(random(4, 14));
    let l = random(40, 160);
    line(x, y, x + l, y + random(-4, 4));
  }
}

function stars() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = random(width), y = random(0, 480);
    let a = random(60, 200) * (1 - y / 520);
    fill(255, 245, 225, a);
    let s = random(1, 3.4);
    ellipse(x, y, s, s);
  }
}

function soilTexture() {
  noStroke();
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(980, height);
    if (y < gy(x) + 4) continue;
    let d = (y - 1050) / 950;
    fill(random(60, 110) * (1 - d * 0.6), random(38, 70) * (1 - d * 0.6), random(22, 45) * (1 - d * 0.6), 30);
    ellipse(x, y, random(10, 50), random(3, 10));
  }
  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let y = random(1080, height);
    if (y < gy(x) + 15) continue;
    let s = random(4, 18);
    fill(random(70, 120), random(60, 95), random(50, 80), 150);
    ellipse(x, y, s, s * random(0.6, 0.9));
    fill(255, 230, 200, 25);
    ellipse(x - s * 0.15, y - s * 0.15, s * 0.5, s * 0.35);
  }
}

// braid geometry
const CX = 800, BY0 = 1440, BY1 = 1960;
function braidAt(t) {
  let y = lerp(BY0, BY1, t);
  let cx = CX + (noise(t * 2.5, 7) - 0.5) * 60;
  let amp = 30 * (1 - t * 0.5);
  let p = HALF_PI + t * 16;
  return { y: y, cx: cx, amp: amp, p: p };
}

function rootGlow() {
  noStroke();
  for (let k = 0; k < 120; k++) {
    let t = k / 119;
    let b = braidAt(t);
    let s = 320 * (1 - t * 0.6);
    fill(255, 170, 90, 3.2 * (1 - t * 0.7));
    ellipse(b.cx, b.y, s, s * 0.8);
  }
  for (let r = 380; r > 0; r -= 12) {
    fill(255, 190, 110, 3.5);
    ellipse(CX, BY0 + 10, r * 1.4, r);
  }
}

function bez(p0, p1, p2, p3, t) {
  return createVector(
    bezierPoint(p0.x, p1.x, p2.x, p3.x, t),
    bezierPoint(p0.y, p1.y, p2.y, p3.y, t)
  );
}

function rootStroke(x1, y1, x2, y2, w, c) {
  stroke(red(c) * 0.45, green(c) * 0.45, blue(c) * 0.45, 230);
  strokeWeight(w + 3);
  line(x1, y1, x2, y2);
  stroke(c);
  strokeWeight(w);
  line(x1, y1, x2, y2);
  stroke(255, 240, 210, 60);
  strokeWeight(max(1, w * 0.25));
  line(x1 - w * 0.2, y1 - w * 0.15, x2 - w * 0.2, y2 - w * 0.15);
}

function mainRoots() {
  let cA = color(196, 128, 116), cB = color(214, 180, 118);
  let b0 = braidAt(0);
  let endA = createVector(b0.cx - sin(b0.p) * b0.amp, b0.y);
  let endB = createVector(b0.cx + sin(b0.p) * b0.amp, b0.y);
  let pathA = [createVector(430, gy(430) + 10), createVector(440, 1280), createVector(640, 1260), endA];
  let pathB = [createVector(1170, gy(1170) + 10), createVector(1160, 1280), createVector(960, 1260), endB];
  strokeCap(ROUND);
  let N = 80;
  for (let pass = 0; pass < 2; pass++) {
    let path = pass === 0 ? pathA : pathB;
    let c = pass === 0 ? cA : cB;
    let prev = bez(path[0], path[1], path[2], path[3], 0);
    for (let i = 1; i <= N; i++) {
      let t = i / N;
      let p = bez(path[0], path[1], path[2], path[3], t);
      p.x += (noise(t * 6, pass * 10) - 0.5) * 14 * sin(t * PI);
      rootStroke(prev.x, prev.y, p.x, p.y, lerp(42, 20, t), c);
      prev = p;
    }
  }
  // braid: back segments first, then front
  let M = 400;
  for (let layer = 0; layer < 2; layer++) {
    for (let i = 0; i < M; i++) {
      let t0 = i / M, t1 = (i + 1) / M;
      let a = braidAt(t0), b = braidAt(t1);
      let w = lerp(20, 6, t0);
      let ax0 = a.cx - sin(a.p) * a.amp, ax1 = b.cx - sin(b.p) * b.amp;
      let bx0 = a.cx + sin(a.p) * a.amp, bx1 = b.cx + sin(b.p) * b.amp;
      let aFront = cos(a.p) > 0;
      if ((layer === 0 && !aFront) || (layer === 1 && aFront)) {
        rootStroke(ax0, a.y, ax1, b.y, w, layer === 0 ? lerpColor(cA, color(40, 25, 20), 0.35) : cA);
      }
      if ((layer === 0 && aFront) || (layer === 1 && !aFront)) {
        rootStroke(bx0, a.y, bx1, b.y, w, layer === 0 ? lerpColor(cB, color(40, 25, 20), 0.35) : cB);
      }
    }
  }
}

function minorRoots() {
  strokeCap(ROUND);
  let bases = [{ x: 430, c: color(176, 120, 108) }, { x: 1170, c: color(190, 160, 108) }];
  for (let b of bases) {
    for (let k = 0; k < 9; k++) {
      let a = random(PI * 0.05, PI * 0.95);
      rootBranch(b.x + random(-20, 20), gy(b.x) + 15, a, random(18, 26), 4, b.c);
    }
  }
}

function rootBranch(x, y, a, steps, depth, c) {
  let w = depth * 2.6 + 1;
  for (let i = 0; i < steps; i++) {
    let nx = x + cos(a) * 12, ny = y + sin(a) * 12;
    if (ny < gy(nx) + 8) { a += 0.4; ny = gy(nx) + 8; }
    stroke(red(c), green(c), blue(c), 150);
    strokeWeight(w * (1 - i / steps * 0.6));
    line(x, y, nx, ny);
    x = nx; y = ny;
    a += (noise(x * 0.01, y * 0.01, depth) - 0.5) * 0.5;
    a = lerp(a, HALF_PI, 0.03);
    if (depth > 1 && random() < 0.12) {
      rootBranch(x, y, a + random(-0.8, 0.8), floor(steps * 0.6), depth - 1, c);
    }
  }
}

function branch(x, y, a, len, w, d, tips) {
  let segs = 6;
  let px = x, py = y;
  for (let i = 1; i <= segs; i++) {
    let t = i / segs;
    let aa = a + (noise(x * 0.01 + t, y * 0.01, d) - 0.5) * 0.4;
    let nx = px + cos(aa) * len / segs;
    let ny = py + sin(aa) * len / segs;
    stroke(38, 26, 32);
    strokeWeight(lerp(w, w * 0.72, t));
    line(px, py, nx, ny);
    px = nx; py = ny;
  }
  if (d === 0) { tips.push(createVector(px, py)); return; }
  let n = (d > 4 && random() < 0.3) ? 3 : 2;
  for (let k = 0; k < n; k++) {
    let off = n === 2 ? (k === 0 ? -1 : 1) * random(0.28, 0.55) : (k - 1) * random(0.4, 0.6);
    let na = a + off;
    na = lerp(na, -HALF_PI, 0.12);
    branch(px, py, na, len * random(0.68, 0.8), w * 0.68, d - 1, tips);
  }
  if (d < 3) tips.push(createVector(px, py));
}

function trees() {
  strokeCap(ROUND);
  branch(430, gy(430) + 20, -HALF_PI - 0.04, 230, 40, 8, leafTipsA);
  branch(1170, gy(1170) + 20, -HALF_PI + 0.05, 220, 38, 8, leafTipsB);
  foliage(leafTipsA, [color(178, 52, 62), color(214, 88, 84), color(140, 34, 52), color(236, 130, 110)]);
  foliage(leafTipsB, [color(214, 160, 52), color(238, 196, 90), color(180, 122, 40), color(250, 220, 140)]);
}

function foliage(tips, pal) {
  noStroke();
  for (let p of tips) {
    for (let i = 0; i < 14; i++) {
      let c = pal[floor(random(pal.length))];
      let r = random(6, 20);
      let ox = randomGaussian() * 26, oy = randomGaussian() * 20;
      let shade = map(oy, -40, 40, 1.1, 0.75);
      fill(red(c) * shade, green(c) * shade, blue(c) * shade, random(110, 190));
      push();
      translate(p.x + ox, p.y + oy);
      rotate(random(TWO_PI));
      ellipse(0, 0, r, r * 0.6);
      pop();
    }
  }
}

function grassLine() {
  strokeCap(ROUND);
  for (let x = 0; x < width; x += 2) {
    let y = gy(x);
    stroke(30, 22, 24, 200);
    strokeWeight(random(1.5, 3));
    let h = random(6, 26);
    line(x, y + 4, x + random(-5, 5), y - h);
  }
  stroke(20, 14, 12);
  strokeWeight(5);
  noFill();
  beginShape();
  for (let x = 0; x < width; x += 8) vertex(x, gy(x) + 3);
  endShape();
}

function grain() {
  noStroke();
  for (let i = 0; i < 70000; i++) {
    let v = random() < 0.5 ? 0 : 255;
    fill(v, v, v, random(6, 16));
    rect(random(width), random(height), 1.5, 1.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function skyCol(y) {
  const stops = [
    [0, color(24, 34, 74)],
    [450, color(78, 66, 120)],
    [850, color(196, 112, 132)],
    [1150, color(244, 160, 110)],
    [1300, color(252, 206, 140)]
  ];
  for (let i = 0; i < stops.length - 1; i++) {
    if (y <= stops[i + 1][0]) {
      let t = (y - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      return lerpColor(stops[i][1], stops[i + 1][1], constrain(t, 0, 1));
    }
  }
  return stops[stops.length - 1][1];
}

function draw() {
  // Sky
  for (let y = 0; y < 1300; y++) {
    stroke(skyCol(y));
    line(0, y, width, y);
  }
  // Painterly sky strokes
  for (let i = 0; i < 5000; i++) {
    let y = random(0, 1300);
    let x = random(-50, width + 50);
    let c = skyCol(y);
    let j = 14;
    stroke(red(c) + random(-j, j), green(c) + random(-j, j), blue(c) + random(-j, j), 80);
    strokeWeight(random(3, 11));
    let len = random(20, 90);
    let a = (noise(x * 0.002, y * 0.004) - 0.5) * 0.25;
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
  // Soft clouds
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let y = random(500, 1100);
    let n = noise(x * 0.003, y * 0.01);
    if (n > 0.58) {
      fill(255, 170 + random(-20, 20), 150, 22);
      ellipse(x, y, random(60, 160), random(10, 24));
    }
  }

  // Sun glow
  for (let r = 700; r > 0; r -= 5) {
    fill(255, 205, 140, 3);
    ellipse(800, 1285, r * 2, r * 1.3);
  }
  fill(255, 236, 196);
  ellipse(800, 1275, 130, 130);
  fill(255, 248, 225, 120);
  ellipse(800, 1275, 100, 100);

  // Far hills
  fill(150, 96, 112);
  beginShape();
  vertex(0, 1320);
  for (let x = 0; x <= width; x += 8) {
    vertex(x, 1262 - noise(x * 0.003, 3) * 70);
  }
  vertex(width, 1320);
  endShape(CLOSE);
  fill(112, 80, 92);
  beginShape();
  vertex(0, 1330);
  for (let x = 0; x <= width; x += 8) {
    vertex(x, 1292 - noise(x * 0.005, 9) * 40);
  }
  vertex(width, 1330);
  endShape(CLOSE);

  // Field base
  for (let y = 1295; y < height; y++) {
    let t = (y - 1295) / (height - 1295);
    let c = lerpColor(color(214, 156, 88), color(42, 44, 38), pow(t, 0.7));
    stroke(c);
    strokeWeight(1);
    line(0, y, width, y);
  }

  // Grass strokes
  for (let i = 0; i < 16000; i++) {
    let y = 1295 + pow(random(), 0.85) * 705;
    let d = (y - 1295) / 705;
    let x = random(-20, width + 20);
    let len = 4 + d * 45 + random(-2, 6);
    let c = lerpColor(color(232, 176, 96), color(48, 64, 42), pow(d, 0.6));
    let glow = max(0, 1 - abs(x - 800) / 700) * (1 - d) * 40;
    stroke(red(c) + glow + random(-15, 15), green(c) + glow * 0.7 + random(-15, 15), blue(c) + random(-10, 10), 200);
    strokeWeight(1 + d * 3);
    let lean = (noise(x * 0.01, y * 0.01) - 0.5) * len * 0.8;
    line(x, y, x + lean, y - len);
  }

  // Shadows merging toward viewer
  noStroke();
  fill(30, 28, 62, 70);
  beginShape();
  vertex(480, 1628); vertex(1120, 1628); vertex(1460, 2000); vertex(140, 2000);
  endShape(CLOSE);
  fill(26, 22, 56, 90);
  quad(500, 1626, 690, 1626, 640, 2000, 220, 2000);
  quad(1100, 1626, 910, 1626, 960, 2000, 1380, 2000);
  fill(26, 22, 56, 80);
  beginShape();
  vertex(640, 1720); vertex(960, 1720); vertex(1000, 1880); vertex(600, 1880);
  endShape(CLOSE);

  // Grass over shadows for texture
  for (let i = 0; i < 4000; i++) {
    let y = random(1630, 2000);
    let d = (y - 1295) / 705;
    let x = random(150, 1450);
    let len = 6 + d * 35;
    stroke(40 + random(-10, 20), 46 + random(-10, 20), 50 + random(-10, 20), 90);
    strokeWeight(1 + d * 2);
    line(x, y, x + random(-6, 6), y - len);
  }

  // Chairs
  drawChair(580, 1400, 1);
  drawChair(1020, 1400, -1);

  // Blanket
  drawBlanket();

  // Post caps peeking over blanket
  noStroke();
  fill(58, 36, 26);
  ellipse(672, 1088, 18, 14);
  ellipse(928, 1088, 18, 14);
  fill(250, 180, 100, 180);
  ellipse(672, 1084, 10, 5);
  ellipse(928, 1084, 10, 5);

  // Fireflies
  for (let i = 0; i < 26; i++) {
    let x = random(200, 1400);
    let y = random(1350, 1750);
    for (let r = 24; r > 0; r -= 3) {
      fill(255, 220, 130, 8);
      ellipse(x, y, r, r);
    }
    fill(255, 240, 190, 220);
    ellipse(x, y, 3, 3);
  }

  // Foreground tall grass
  for (let i = 0; i < 700; i++) {
    let x = random(width);
    let y = random(1940, 2010);
    let len = random(60, 160);
    stroke(28 + random(10), 34 + random(14), 28 + random(10), 220);
    strokeWeight(random(2, 5));
    noFill();
    let bend = random(-40, 40);
    bezier(x, y, x, y - len * 0.4, x + bend * 0.5, y - len * 0.7, x + bend, y - len);
  }

  // Vignette
  noFill();
  for (let i = 0; i < 260; i++) {
    stroke(10, 8, 24, map(i, 0, 260, 2.2, 0));
    strokeWeight(6);
    rect(i * 3, i * 3, width - i * 6, height - i * 6);
  }
}

function drawChair(cx, sy, m) {
  push();
  translate(cx, sy);
  scale(m, 1);
  let wood = color(62, 40, 28);
  let woodDark = color(44, 28, 20);
  let rim = color(250, 176, 98);

  // Back legs
  stroke(woodDark);
  strokeWeight(13);
  line(100, -30, 102, 172);
  line(-60, -40, -62, 160);

  // Back posts
  stroke(wood);
  strokeWeight(15);
  line(-60, -40, -70, -318);
  line(100, -30, 92, -310);

  // Back slats
  noStroke();
  fill(wood);
  for (let k = 0; k < 3; k++) {
    let t = 0.15 + k * 0.22;
    let y1L = lerp(-40, -318, t), y1R = lerp(-30, -310, t);
    let xL = lerp(-60, -70, t), xR = lerp(100, 92, t);
    quad(xL, y1L - 34, xR, y1R - 34, xR, y1R, xL, y1L);
    stroke(rim);
    strokeWeight(2);
    line(xL, y1L - 34, xR, y1R - 34);
    noStroke();
  }
  fill(wood);
  quad(-70, -318, 92, -310, 92, -280, -70, -288);

  // Seat
  fill(wood);
  quad(-60, -40, 100, -30, 80, 30, -90, 20);
  fill(woodDark);
  quad(-90, 20, 80, 30, 80, 44, -90, 34);

  // Front legs
  stroke(woodDark);
  strokeWeight(15);
  line(-88, 30, -92, 222);
  line(78, 40, 82, 230);
  strokeWeight(9);
  line(-90, 150, 80, 160);

  // Rim light on edges facing sun
  stroke(rim);
  strokeWeight(3);
  line(-60, -40, 100, -30);
  line(-70, -318, 92, -310);
  strokeWeight(2);
  line(-66, -50, -74, -310);
  line(96, -40, 88, -300);
  pop();
}

function drawBlanket() {
  let tops = [], bots = [];
  for (let x = 596; x <= 1004; x += 3) {
    let ty;
    if (x < 672) ty = 1090 + (672 - x) * 0.55;
    else if (x > 928) ty = 1090 + (x - 928) * 0.55;
    else ty = 1090 + 165 * sin(PI * (x - 672) / 256);
    let hang = (max(0, 672 - x) + max(0, x - 928)) * 2.6;
    let by = ty + 95 + 14 * sin(x * 0.07) + 8 * noise(x * 0.05) + hang;
    tops.push([x, ty]);
    bots.push([x, by]);
  }
  noStroke();
  fill(158, 30, 42);
  beginShape();
  for (let p of tops) vertex(p[0], p[1]);
  for (let i = bots.length - 1; i >= 0; i--) vertex(bots[i][0], bots[i][1]);
  endShape(CLOSE);

  // Folds and knit texture
  for (let i = 0; i < tops.length; i++) {
    let x = tops[i][0];
    let shade = 0.5 + 0.5 * sin(x * 0.07);
    stroke(90, 14, 26, 90 * (1 - shade));
    strokeWeight(3);
    line(x, tops[i][1] + 4, bots[i][0], bots[i][1]);
  }
  for (let i = 0; i < 1400; i++) {
    let idx = floor(random(tops.length));
    let f = random();
    let x = tops[idx][0] + random(-2, 2);
    let y = lerp(tops[idx][1], bots[idx][1], f);
    stroke(190 + random(-30, 30), 50 + random(-20, 20), 56, 110);
    strokeWeight(2);
    point(x, y);
  }

  // Stripes
  noFill();
  let stripes = [[0.22, color(238, 214, 176)], [0.3, color(238, 214, 176)], [0.72, color(214, 150, 70)]];
  for (let s of stripes) {
    stroke(s[1]);
    strokeWeight(5);
    beginShape();
    for (let i = 0; i < tops.length; i++) {
      vertex(tops[i][0], lerp(tops[i][1], bots[i][1], s[0]));
    }
    endShape();
  }

  // Fringe
  stroke(200, 140, 100);
  strokeWeight(2);
  for (let i = 0; i < bots.length; i += 2) {
    line(bots[i][0], bots[i][1], bots[i][0] + random(-2, 2), bots[i][1] + random(8, 16));
  }

  // Rim light along top edge
  stroke(255, 196, 124);
  strokeWeight(3);
  noFill();
  beginShape();
  for (let p of tops) vertex(p[0], p[1]);
  endShape();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

const DOOR = { x: 800, y: 395 };

function draw() {
  paintSnow();
  doorGlow();
  treeShadow(1690, 520, 1500, 50);
  treeShadow(1700, 1230, 1350, 42);
  treeShadow(1660, 1760, 950, 34);
  grassTufts();
  trails();
  cabin();
  smoke();
  sparkle();
  vignette();
}

function paintSnow() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let br = lerp(253, 196, t), bg = lerp(244, 208, t), bb = lerp(232, 234, t);
    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.0018, y * 0.0035);
      let n2 = noise(x * 0.01 + 100, y * 0.02 + 50);
      let s = (n - 0.5) * 42 + (n2 - 0.5) * 10;
      let g = random(-4, 4);
      let i = 4 * (y * width + x);
      pixels[i] = br + s * 0.85 + g;
      pixels[i + 1] = bg + s * 0.85 + g;
      pixels[i + 2] = bb + s * 0.55 + g;
      pixels[i + 3] = 255;
    }
  }
  updatePixels();
}

function doorGlow() {
  noStroke();
  for (let r = 900; r > 10; r -= 6) {
    fill(255, 180, 95, 2.6);
    ellipse(DOOR.x, DOOR.y + 60, r * 1.3, r * 0.95);
  }
  for (let r = 260; r > 6; r -= 5) {
    fill(255, 200, 120, 3);
    ellipse(670, 400, r * 1.2, r * 0.7);
    ellipse(930, 400, r * 1.2, r * 0.7);
  }
}

function treeShadow(x0, y0, len, w) {
  let a = PI - 0.36;
  branch(x0, y0, a, len, w, 0);
}

function branch(x0, y0, a, len, w, depth) {
  strokeCap(ROUND);
  let px = x0, py = y0;
  let steps = floor(len / 6);
  for (let i = 1; i <= steps; i++) {
    let s = i * 6;
    let t = s / len;
    let wob = (noise(s * 0.004, x0 * 0.01 + depth * 10) - 0.5) * 50;
    let x = x0 + cos(a) * s + cos(a + HALF_PI) * wob;
    let y = y0 + sin(a) * s + sin(a + HALF_PI) * wob;
    stroke(100, 118, 172, 26);
    strokeWeight(lerp(w, w * 0.12, t));
    line(px, py, x, y);
    if (depth < 2 && t > 0.25 && random() < 0.035) {
      let side = random() < 0.5 ? -1 : 1;
      branch(x, y, a + side * random(0.4, 0.9), random(90, 300) * (1 - t) * (depth == 0 ? 1 : 0.6), w * (1 - t) * 0.45, depth + 1);
    }
    px = x; py = y;
  }
}

function grassTufts() {
  for (let k = 0; k < 260; k++) {
    let x = random(width), y = random(500, height);
    if (abs(x - 800) < 120 && y < 1200) continue;
    let n = floor(random(3, 8));
    for (let j = 0; j < n; j++) {
      let a = -HALF_PI + random(-0.7, 0.7);
      let l = random(5, 18);
      stroke(105, 90, 68, random(120, 200));
      strokeWeight(random(1, 2));
      line(x + random(-3, 3), y, x + cos(a) * l, y + sin(a) * l);
    }
    noStroke();
    fill(120, 135, 180, 40);
    ellipse(x - 6, y + 4, 18, 6);
  }
}

function bez(p0, p1, p2, p3, n) {
  let out = [];
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    out.push({ x: bezierPoint(p0.x, p1.x, p2.x, p3.x, t), y: bezierPoint(p0.y, p1.y, p2.y, p3.y, t) });
  }
  return out;
}

function trails() {
  let M = { x: 800, y: 1180 };
  let D = { x: DOOR.x, y: DOOR.y + 12 };
  let shared = bez(M, { x: 765, y: 980 }, { x: 855, y: 700 }, D, 320);
  let A1 = bez({ x: 170, y: 2080 }, { x: 240, y: 1700 }, { x: 690, y: 1370 }, M, 320);
  let B1 = bez({ x: 1450, y: 2080 }, { x: 1390, y: 1680 }, { x: 910, y: 1370 }, M, 320);
  let A = buildPath(A1, shared, -20, 3.1);
  let B = buildPath(B1, shared, 20, 9.7);
  drawTrail(A);
  drawTrail(B);
}

function buildPath(seg, shared, off, seed) {
  let all = seg.concat(shared.slice(1));
  let n1 = seg.length;
  let out = [];
  for (let i = 0; i < all.length; i++) {
    let amp = i < n1 ? lerp(32, 4, pow(i / n1, 1.4)) : 4;
    let ramp = i < n1 ? constrain(i / n1, 0, 1) : 1;
    let wx = (noise(i * 0.018 + seed) - 0.5) * amp * 2;
    let wy = (noise(i * 0.018 + seed + 40) - 0.5) * amp;
    out.push({ x: all[i].x + wx + off * ramp, y: all[i].y + wy });
  }
  return out;
}

function drawTrail(pts) {
  let acc = 0, side = 1, next = random(10, 40);
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i].x - pts[i - 1].x, dy = pts[i].y - pts[i - 1].y;
    let l = sqrt(dx * dx + dy * dy);
    acc += l;
    if (acc >= next && l > 0) {
      let a = atan2(dy, dx);
      let nx = -dy / l, ny = dx / l;
      let px = pts[i].x + nx * 8 * side;
      let py = pts[i].y + ny * 8 * side;
      side *= -1;
      let scl = map(py, 400, 2000, 0.85, 1.1);
      drawPrint(px, py, a, scl);
      next += random(33, 40) * scl;
    }
  }
}

function drawPrint(x, y, a, s) {
  let d = dist(x, y, DOOR.x, DOOR.y);
  let w = pow(constrain(1 - d / 760, 0, 1), 1.4);
  let sh = lerpColor(color(104, 122, 172), color(188, 128, 86), w);
  let dk = lerpColor(color(78, 94, 145), color(150, 92, 62), w);
  push();
  translate(x, y);
  rotate(a + random(-0.12, 0.12));
  scale(s);
  noStroke();
  fill(red(sh), green(sh), blue(sh), 70);
  ellipse(1.5, 2, 32, 18);
  fill(red(sh), green(sh), blue(sh), 165);
  ellipse(0, 0, 26, 12.5);
  fill(red(dk), green(dk), blue(dk), 120);
  ellipse(-6, 0, 10, 8.5);
  ellipse(6, 0, 12, 9.5);
  noFill();
  stroke(255, 250, 240, 170);
  strokeWeight(2);
  arc(0, 0, 28, 15, PI + 0.3, TWO_PI - 0.3);
  noStroke();
  fill(255, 255, 255, 180);
  for (let k = 0; k < 4; k++) ellipse(random(-16, 16), random(-11, 11), random(1.5, 3));
  pop();
}

function cabin() {
  noStroke();
  // shadow on snow
  fill(95, 110, 165, 70);
  quad(590, 385, 1010, 385, 950, 440, 530, 440);
  quad(530, 70, 590, 70, 590, 385, 530, 440);
  // roof halves
  fill(192, 198, 222);
  rect(585, 60, 215, 322);
  fill(250, 245, 236);
  rect(800, 60, 215, 322);
  // roof snow texture
  for (let k = 0; k < 500; k++) {
