  // door & windows light under eave
  fill(255, 212, 140);
  rect(782, 383, 36, 9);
  fill(255, 200, 120);
  rect(655, 384, 30, 6);
  rect(915, 384, 30, 6);
  // chimney
  fill(90, 100, 140, 90);
  quad(895, 190, 935, 190, 905, 225, 865, 225);
  fill(122, 84, 68);
  rect(895, 150, 40, 40);
  fill(45, 36, 36);
  rect(901, 156, 28, 28);
}

function smoke() {
  noStroke();
  let x = 915, y = 170;
  for (let i = 0; i < 160; i++) {
    let t = i / 160;
    x += -2.2 + (noise(i * 0.05) - 0.5) * 4;
    y += -1.1 + (noise(i * 0.05 + 30) - 0.5) * 3;
    fill(235, 235, 240, 14 * (1 - t));
    ellipse(x, y, 20 + t * 140, 16 + t * 100);
  }
}

function sparkle() {
  for (let k = 0; k < 2600; k++) {
    let x = random(width), y = random(height);
    let d = dist(x, y, DOOR.x, DOOR.y);
    if (d < 600 && random() < 0.4) stroke(255, 235, 190, random(140, 255));
    else stroke(255, 255, 255, random(110, 230));
    strokeWeight(random(1, 2.6));
    point(x, y);
  }
}

function vignette() {
  noFill();
  for (let i = 0; i < 140; i++) {
    let t = 1 - i / 140;
    stroke(35, 45, 90, t * t * 7);
    strokeWeight(5);
    rect(i * 4, i * 4, width - i * 8, height - i * 8);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  colorMode(HSB, 360, 100, 100, 1.0);

  // Deep void background
  background(240, 65, 6, 1.0);

  // 1. Textured Background Nebulae & Canvas Grain
  drawBackgroundAtmosphere();

  // 2. Ambient Glow at the Core of Connection
  drawCoreRadiance();

  // 3. The Two Entities (Flowing Ribbons/Brushes)
  drawIntertwiningForms();

  // 4. Golden Kintsugi / Connection Threads
  drawConnectionThreads();

  // 5. Rising Sparks / Memories
  drawEmbers();

  // 6. Final Painterly Texture Overlay
  drawCanvasTexture();
}

function drawBackgroundAtmosphere() {
  noStroke();
  // Soft atmospheric washes
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, width * 0.5, height * 0.45);
    let maxD = dist(0, 0, width * 0.5, height * 0.45);
    let normD = constrain(d / maxD, 0, 1);

    let n = noise(x * 0.002, y * 0.002);

    // Shift hue from deep indigo at edges to warm plum near center
    let h = lerp(290, 225, normD) + map(n, 0, 1, -20, 20);
    let s = lerp(50, 75, normD);
    let b = lerp(35, 6, pow(normD, 0.7)) * n * 1.5;

    fill(h, s, b, 0.04);
    let r = random(150, 500);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, r, r * random(0.4, 0.9));
    pop();
  }
}

function drawCoreRadiance() {
  // Additive blending for the spiritual warmth of the embrace
  blendMode(ADD);
  noStroke();

  let cx = width * 0.5;
  let cy = height * 0.45;

  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let distFromCenter = abs(randomGaussian(0, 220));
    let x = cx + cos(angle) * distFromCenter * 0.8;
    let y = cy + sin(angle) * distFromCenter * 1.3;

    // Colors shifting from gold/peach in center to magenta/violet outside
    let h = map(distFromCenter, 0, 600, 35, 320, true) + random(-10, 10);
    let s = map(distFromCenter, 0, 500, 40, 85, true);
    let b = map(distFromCenter, 0, 600, 40, 5, true);

    fill(h % 360, s, b, 0.015);
    let r = random(100, 450);
    ellipse(x, y, r, r);
  }
  blendMode(BLEND);
}

// Defines the spine of the two lovers
function getSpine(isLeft, t) {
  let y = lerp(height * 1.08, height * 0.12, t);
  let x;

  if (isLeft) {
    if (t < 0.35) {
      // Sweeping in from bottom left
      x = map(pow(t / 0.35, 0.8), 0, 1, width * 0.15, width * 0.36);
    } else if (t < 0.8) {
      // Twisting together in the middle
      let localT = map(t, 0.35, 0.8, 0, PI * 1.15);
      x = width * 0.5 - cos(localT) * (width * 0.14) * (1 - (t - 0.35) * 0.7);
    } else {
      // Gently resting together at the crown (head/heart)
      let localT = map(t, 0.8, 1.0, 0, 1);
      let startX = width * 0.5 - cos(PI * 1.15) * (width * 0.14) * (1 - 0.45 * 0.7);
      x = lerp(startX, width * 0.47, pow(localT, 0.5));
      y += sin(localT * PI) * 40; // Slight arch
    }
  } else {
    if (t < 0.35) {
      // Sweeping in from bottom right
      x = map(pow(t / 0.35, 0.8), 0, 1, width * 0.85, width * 0.64);
    } else if (t < 0.8) {
      // Twisting together
      let localT = map(t, 0.35, 0.8, 0, PI * 1.15);
      x = width * 0.5 + cos(localT) * (width * 0.14) * (1 - (t - 0.35) * 0.7);
    } else {
      // Gently resting together
      let localT = map(t, 0.8, 1.0, 0, 1);
      let startX = width * 0.5 + cos(PI * 1.15) * (width * 0.14) * (1 - 0.45 * 0.7);
      x = lerp(startX, width * 0.53, pow(localT, 0.5));
      y += sin(localT * PI) * 40;
    }
  }
  return createVector(x, y);
}

function drawIntertwiningForms() {
  let numStrands = 3200;
  let steps = 110;

  // Pre-generate strands so we can sort or interleave them naturally
  let strands = [];
  for (let i = 0; i < numStrands; i++) {
    strands.push({
      isLeft: i % 2 === 0,
      offset: randomGaussian(0, 1), // Normalized offset from spine
      seed: random(10000),
      thickness: random(1.5, 14),
      alphaScale: random(0.3, 1.0)
    });
  }

  // Shuffle to ensure true intertwining (overlapping strokes of both entities)
  for (let i = strands.length - 1; i > 0; i--) {
    let j = floor(random(i + 1));
    let temp = strands[i];
    strands[i] = strands[j];
    strands[j] = temp;
  }

  noFill();

  for (let s of strands) {
    let startT = constrain(randomGaussian(0.1, 0.15), 0, 0.6);
    let endT = constrain(startT + random(0.3, 0.85), 0.2, 1.0);

    // Base color identity
    // Left: Warm (Coral, Crimson, Gold, Peach)
    // Right: Cool (Teal, Cerulean, Indigo, Lavender)
    let baseHue = s.isLeft ? random(335, 395) : random(175, 245);
    let baseSat = random(55, 95);
    let baseBri = random(45, 95);

    // Core strands are brighter and tighter, outer strands are darker and looser
    let distFactor = abs(s.offset);
    if (distFactor > 1.2) {
      baseBri *= 0.6;
      baseSat *= 0.8;
    }

    for (let step = 0; step < steps; step++) {
      let t1 = map(step, 0, steps, startT, endT);
      let t2 = map(step + 1, 0, steps, startT, endT);

      let p1 = getPointOnStrand(s, t1);
      let p2 = getPointOnStrand(s, t2);

      // Calculate proximity to the OTHER entity's spine at this height
      let otherSpine = getSpine(!s.isLeft, t1);
      let dToOther = dist(p1.x, p1.y, otherSpine.x, otherSpine.y);

      // Color alchemy: as they get close, colors shift toward warm gold/magenta/white
      let mixFactor = map(dToOther, 350, 40, 0, 1, true);
      mixFactor = pow(mixFactor, 1.5);

      // Target love/harmony color (Golden Peach / Soft Rose)
      let targetHue = s.isLeft ? 45 : 310; 
      if ( !s.isLeft && baseHue < 200 ) targetHue = 150; // Teal shifts to mint-gold

      let h = lerp(baseHue, targetHue, mixFactor * 0.7) % 360;
      let sat = lerp(baseSat, 35, pow(mixFactor, 2)); // Desaturate slightly toward glowing white-gold
      let bri = lerp(baseBri, 100, mixFactor * 0.8);

      // Fade at the ends of the stroke
      let stepNorm = step / steps;
      let fade = sin(stepNorm * PI); 

      // Global vertical fade (darker at bottom roots)
      let rootFade = map(t1, 0, 0.2, 0.2, 1.0, true);

      let alpha = fade * rootFade * s.alphaScale * map(distFactor, 0, 2.5, 0.5, 0.05, true);

      // Dynamic brush thickness
      let sw = s.thickness * fade * map(t1, 0, 1, 1.4, 0.5);

      strokeWeight(sw);
      stroke(h, sat, bri * rootFade, alpha);
      line(p1.x, p1.y, p2.x, p2.y);

      // Occasional impasto highlight on the upper/inner curves
      if (mixFactor > 0.6 && step % 6 === 0 && random() < 0.15) {
        strokeWeight(sw * 0.4);
        stroke(45, 20, 100, alpha * 1.5);
        line(p1.x, p1.y, p2.x, p2.y);
      }
    }
  }
}

function getPointOnStrand(s, t) {
  let spine = getSpine(s.isLeft, t);
  let otherSpine = getSpine(!s.isLeft, t);

  // Width of the figure tapers as it goes up, swells at the embrace
  let profile = sin(t * PI) * 180 + 50;
  if (t > 0.75) {
    // Form a more cohesive "head/heart" aura at the top
    profile = map(t, 0.75, 1.0, 180, 20);
  }

  // Organic turbulence
  let nAngle = noise(s.seed * 0.1, t * 3.5) * TWO_PI * 2;
  let nRad = noise(s.seed * 0.1 + 50, t * 2.5) * profile;

  let offsetX = s.offset * profile + cos(nAngle) * (nRad * 0.4);
  let offsetY = sin(nAngle) * (nRad * 0.4);

  let x = spine.x + offsetX;
  let y = spine.y + offsetY;

  // Gravitational pull toward the other lover in the middle section
  if (t > 0.3 && t < 0.85) {
    let pull = sin(map(t, 0.3, 0.85, 0, PI));
    // Inner strands get pulled more strongly across the boundary
    let isInner = (s.isLeft && s.offset > 0) || (!s.isLeft && s.offset < 0);
    if (isInner) {
      x = lerp(x, otherSpine.x, pull * 0.35 * noise(s.seed, t * 5));
    }
  }

  return createVector(x, y);
}

function drawConnectionThreads() {
  // Delicate, luminous filaments bridging the two figures
  noFill();
  for (let i = 0; i < 450; i++) {
    let t = random(0.28, 0.92);
    let pLeft = getSpine(true, t);
    let pRight = getSpine(false, t);

    // Scatter attachment points around the spines
    pLeft.x += randomGaussian(0, 70);
    pLeft.y += randomGaussian(0, 50);
    pRight.x += randomGaussian(0, 70);
    pRight.y += randomGaussian(0, 50);

    let d = dist(pLeft.x, pLeft.y, pRight.x, pRight.y);
    if (d > 500) continue;

    // Control points for a graceful, swooping bezier bridge
    let cp1x = lerp(pLeft.x, pRight.x, 0.3) + random(-80, 80);
    let cp1y = lerp(pLeft.y, pRight.y, 0.3) + random(40, 150); // Droop or arch
    let cp2x = lerp(pLeft.x, pRight.x, 0.7) + random(-80, 80);
    let cp2y = lerp(pLeft.y, pRight.y, 0.7) - random(40, 150);

    let alpha = map(d, 0, 500, 0.35, 0.02);
    strokeWeight(random(0.5, 2.2));

    // Warm gold to rose-gold hues
    let h = random(25, 55);
    let s = random(20, 60);
    stroke(h, s, 100, alpha);

    bezier(pLeft.x, pLeft.y, cp1x, cp1y, cp2x, cp2y, pRight.x, pRight.y);

    // Draw tiny glowing nodes along some threads
    if (random() < 0.3) {
      let bt = random(0.2, 0.8);
      let bx = bezierPoint(pLeft.x, cp1x, cp2x, pRight.x, bt);
      let by = bezierPoint(pLeft.y, cp1y, cp2y, pRight.y, bt);
      noStroke();
      fill(45, 30, 100, alpha * 2);
      circle(bx, by, random(2, 6));
      noFill();
    }
  }
}

function drawEmbers() {
  // Sparks of light born from the union, drifting upward
  noStroke();
  for (let i = 0; i < 900; i++) {
    // Concentrated around the upper-middle canvas
    let t = pow(random(1), 0.7); 
    let spineL = getSpine(true, t);
    let spineR = getSpine(false, t);
    let center = p5.Vector.lerp(spineL, spineR, random(0.2, 0.8));

    let spread = map(t, 0, 1, 500, 180);
    // Wider spread at the very top as they ascend into the ether
    if (t > 0.85) spread = map(t, 0.85, 1, 180, 600);

    let x = center.x + randomGaussian(0, spread);
    let y = center.y + randomGaussian(0, spread * 0.6);

    // Distance from central axis
    let d = dist(x, y, width * 0.5, height * 0.45);

    let h = random() < 0.6 ? random(25, 55) : (x < width * 0.5 ? random(340, 380) % 360 : random(180, 220));
    let s = random(10, 70);
    let b = 100;

    let r = pow(random(1), 3) * 14 + 1.5;
    let alpha = map(r, 1.5, 15.5, 0.6, 0.1) * map(d, 0, 900, 1, 0.1, true);

    // Soft glow behind larger embers
    if (r > 6) {
      fill(h, s + 20, b, alpha * 0.25);
      circle(x, y, r * 3.5);
      fill(h, s, b, alpha * 0.5);
      circle(x, y, r * 1.8);
    }

    // Core of the ember
    fill(h, s * 0.5, b, alpha);

    // Slight painterly dab shape
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, r, r * random(0.6, 1.0));
    pop();
  }
}

function drawCanvasTexture() {
  // Subtle fine-art tooth and tonal glaze
  noFill();

  // Horizontal & Vertical linen weave simulation (very subtle)
  strokeWeight(1);
  for (let y = 0; y < height; y += 3) {
    stroke(30, 20, 90, 0.012);
    line(0, y + random(-0.5, 0.5), width, y + random(-0.5, 0.5));
  }

  // Scumbling / dry-brush texture across the whole piece
  noStroke();
  for (let i = 0; i < 45000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);

    if (random() < 0.5) {
      // Tiny warm highlights
      fill(40, 20, 100, 0.025 * n);
    } else {
      // Tiny deep tooth shadows
      fill(240, 70, 5, 0.035 * (1 - n));
    }
    rect(x, y, random(1, 3), random(1, 3));
  }

  // Vignette to frame the intimacy
  for (let i = 0; i < 1200; i++) {
    let angle = random(TWO_PI);
    // Push toward edges
    let rad = map(pow(random(1), 0.25), 0, 1, 0.65, 1.15);
    let x = width * 0.5 + cos(angle) * (width * 0.55) * rad;
    let y = height * 0.5 + sin(angle) * (height * 0.55) * rad;

    fill(245, 75, 4, 0.04);
    let s = random(150, 400);
    ellipse(x, y, s, s);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(12, 14, 24);

  // 1. Deep Atmospheric Background (Impasto Canvas Texture)
  drawBackgroundAtmosphere();

  // 2. Ambient Glow at the Nexus of Embrace
  drawNexusGlow(800, 1020);

  // 3. The Two Flowing Forces (Painterly Ribbon Currents)
  drawEntwinedCurrents();

  // 4. Luminous Filaments (Golden Threads of Connection)
  drawConnectionThreads();

  // 5. Drifting Embers & Spores of Light
  drawLuminousSpores();

  // 6. Fine Canvas Grain & Surface Texture
  applyCanvasTexture();
}

function drawBackgroundAtmosphere() {
  noStroke();
  for (let i = 0; i < 18000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);

    // Distance from the central embrace
    let d = dist(x, y, 800, 1020);
    let normD = constrain(d / 1200, 0, 1);

    // Color shifts from deep twilight indigo at edges to warm plum/ochre near center
    let cDark = color(10, 15, 30, 18);
    let cMid = color(45, 22, 48, 15);
    let cWarm = color(95, 35, 45, 12);

    let col;
    if (normD > 0.5) {
      col = lerpColor(cMid, cDark, map(normD, 0.5, 1, 0, 1));
    } else {
      col = lerpColor(cWarm, cMid, map(normD, 0, 0.5, 0, 1));
    }

    // Add slight tonal variation
    let shift = map(n, 0, 1, -15, 15);
    fill(red(col) + shift, green(col) + shift, blue(col) + shift, alpha(col));

    push();
    translate(x, y);
    rotate(n * TWO_PI * 2);
    let w = random(30, 140);
    let h = random(15, 60);
    ellipse(0, 0, w, h);
    pop();
  }
}

function drawNexusGlow(cx, cy) {
  push();
  blendMode(SCREEN);
  noStroke();

  // Layered soft radial glow
  for (let r = 900; r > 20; r -= 8) {
    let inter = map(r, 20, 900, 1, 0);
    let interSq = pow(inter, 2.5);

    let c1 = color(255, 220, 160, 4 * interSq);
    let c2 = color(210, 70, 90, 2.5 * interSq);
    let col = lerpColor(c2, c1, inter);

    fill(col);
    let ox = random(-15, 15);
    let oy = random(-15, 15);
    ellipse(cx + ox, cy + oy, r * 1.1, r * 1.4);
  }
  pop();
}

// Spine position for Entity A (Warm: Rose, Coral, Amber, Gold)
function getSpineA(t) {
  let y = t * height;
  let ease = exp(-pow((t - 0.51) * 4.2, 2)); // Peaks at the embrace (t = 0.51)

  let startX = 250 + sin(t * PI) * 180;
  let embraceX = 800 + sin((t - 0.51) * 13) * 110;

  let x = lerp(startX, embraceX, ease);
  x += (noise(t * 3.5, 10) - 0.5) * 140;
  return createVector(x, y);
}

// Spine position for Entity B (Cool: Teal, Cerulean, Violet, Pearl)
function getSpineB(t) {
  let y = (1 - t) * height; // Flows from bottom to top, meeting A in the middle
  let tNorm = 1 - t;
  let ease = exp(-pow((tNorm - 0.51) * 4.2, 2));

  let startX = 1350 - sin(tNorm * PI) * 180;
  let embraceX = 800 - sin((tNorm - 0.51) * 13) * 110;

  let x = lerp(startX, embraceX, ease);
  x += (noise(tNorm * 3.5, 20) - 0.5) * 140;
  return createVector(x, y);
}

function drawEntwinedCurrents() {
  let numStrands = 1100;

  // Interleave drawing of both entities so their strokes naturally overlap and weave
  for (let i = 0; i < numStrands; i++) {
    let isEntityA = (i % 2 === 0);
    let spread = pow(random(), 1.4) * (random() < 0.5 ? -1 : 1) * 280;
    let noiseOffset = random(1000);

    // Start and end along the flow
    let tStart = random(0, 0.35);
    let tEnd = tStart + random(0.35, 0.65);
    tEnd = constrain(tEnd, 0, 1);

    let steps = 110;
    let baseWeight = random(2, 16);

    // Pick base palette for this strand
    let cBase, cHighlight, cMerge;
    if (isEntityA) {
      let p = random();
      if (p < 0.4) cBase = color(185, 35, 65);       // Deep Crimson Rose
      else if (p < 0.75) cBase = color(235, 85, 60); // Warm Coral Vermilion
      else cBase = color(245, 155, 65);              // Golden Ochre
      cHighlight = color(255, 225, 170);
    } else {
      let p = random();
      if (p < 0.4) cBase = color(20, 75, 115);       // Prussian Cerulean
      else if (p < 0.75) cBase = color(35, 145, 155);// Luminous Teal
      else cBase = color(95, 70, 155);               // Twilight Violet
      cHighlight = color(190, 240, 255);
    }
    cMerge = color(255, 240, 210); // Incandescent Pearl-Gold where they touch

    let prevPos = null;

    for (let s = 0; s <= steps; s++) {
      let f = s / steps;
      let t = lerp(tStart, tEnd, f);

      let spinePos = isEntityA ? getSpineA(t) : getSpineB(t);
      let otherT = isEntityA ? (1 - t) : (1 - t);
      let otherPos = isEntityA ? getSpineB(otherT) : getSpineA(otherT);

      // Dynamic width contraction near the embrace (pulls tighter together, then flares)
      let yNorm = spinePos.y / height;
      let embraceFactor = exp(-pow((yNorm - 0.51) * 4.5, 2));
      let currentSpread = spread * lerp(1.1, 0.55, embraceFactor);

      // Organic curl using Perlin noise
      let nAngle = noise(spinePos.x * 0.003, spinePos.y * 0.003, noiseOffset) * TWO_PI * 2;
      let ox = currentSpread + cos(nAngle) * 45;
      let oy = sin(nAngle) * 45;

      let px = spinePos.x + ox;
      let py = spinePos.y + oy;

      // Pull strands slightly toward the partner's spine when close
      let dToOther = dist(px, py, otherPos.x, otherPos.y);
      let pull = constrain(map(dToOther, 0, 500, 0.35, 0), 0, 0.35);
      px = lerp(px, otherPos.x, pull);
      py = lerp(py, otherPos.y, pull);

      if (prevPos !== null) {
        // Taper stroke at ends
        let taper = sin(f * PI);
        let sw = baseWeight * taper * random(0.8, 1.2);

        // Color transformation based on proximity to the other entity
        let proximity = constrain(map(dToOther, 60, 420, 1, 0), 0, 1);
        proximity = pow(proximity, 1.8);

        let col = lerpColor(cBase, cHighlight, noise(f * 4, noiseOffset) * 0.6);
        col = lerpColor(col, cMerge, proximity * 0.85);

        let alphaVal = lerp(45, 150, proximity) * taper;

        // Draw painterly multi-bristle segment
        strokeWeight(sw);
        stroke(red(col), green(col), blue(col), alphaVal);
        line(prevPos.x, prevPos.y, px, py);

        // Subtle impasto edge highlight
        if (sw > 6 && random() < 0.4) {
          strokeWeight(sw * 0.3);
          stroke(red(cMerge), green(cMerge), blue(cMerge), alphaVal * 0.6);
          line(prevPos.x + 2, prevPos.y - 2, px + 2, py - 2);
        }
      }
      prevPos = createVector(px, py);
    }
  }
}

function drawConnectionThreads() {
  // Delicate, glowing golden and rose-quartz filaments bridging the two currents
  push();
  blendMode(ADD);
  noFill();

  for (let i = 0; i < 320; i++) {
    // Focus mostly around the central embrace, with some trailing up and down
    let yNorm = constrain(randomGaussian(0.51, 0.16), 0.08, 0.92);
    let tA = yNorm;
    let tB = 1 - yNorm;

    let posA = getSpineA(tA);
    let posB = getSpineB(tB);

    // Offset slightly from core spines
    posA.x += random(-120, 120);
    posA.y += random(-60, 60);
    posB.x += random(-120, 120);
    posB.y += random(-60, 60);

    let d = dist(posA.x, posA.y, posB.x, posB.y);
    if (d < 650) {
      let alpha = map(d, 0, 650, 90, 8);
      let sw = map(d, 0, 650, 2.2, 0.5) * random(0.6, 1.4);

      let c1 = color(255, 210, 140, alpha);
      let c2 = color(255, 140, 165, alpha);
      let c3 = color(140, 230, 255, alpha);

      let col = random() < 0.5 ? c1 : (random() < 0.5 ? c2 : c3);
      stroke(col);
      strokeWeight(sw);

      // Bezier control points with gentle upward/swirling drift
      let midX = (posA.x + posB.x) * 0.5;
      let midY = (posA.y + posB.y) * 0.5;
      let ctrl1X = lerp(posA.x, midX, 0.5) + random(-140, 140);
      let ctrl1Y = lerp(posA.y, midY, 0.5) + random(-140, 140);
      let ctrl2X = lerp(posB.x, midX, 0.5) + random(-140, 140);
      let ctrl2Y = lerp(posB.y, midY, 0.5) + random(-140, 140);

      bezier(posA.x, posA.y, ctrl1X, ctrl1Y, ctrl2X, ctrl2Y, posB.x, posB.y);
    }
  }
  pop();
}

function drawLuminousSpores() {
  // Particles of light where each force carries pieces of the other into the dark
  noStroke();

  for (let i = 0; i < 2400; i++) {
    let yNorm = random(0.02, 0.98);
    let isNearCenter = abs(yNorm - 0.51) < 0.22;

    let spineA = getSpineA(yNorm);
    let spineB = getSpineB(1 - yNorm);

    let basePos = random() < 0.5 ? spineA : spineB;
    let spread = isNearCenter ? randomGaussian(0, 220) : randomGaussian(0, 340);

    let x = basePos.x + spread;
    let y = basePos.y + randomGaussian(0, 60);

    // Deliberately swap colors occasionally: warm embers in the cool stream, cool stars in the warm stream
    let warmSpore = random() < 0.55;
    let col;
    if (warmSpore) {
      col = lerpColor(color(255, 160, 90), color(255, 240, 190), random());
    } else {
      col = lerpColor(color(80, 210, 240), color(210, 245, 255), random());
    }

    let dToCenter = dist(x, y, 800, 1020);
    let size = random(1.5, 6.5) * map(constrain(dToCenter, 0, 900), 0, 900, 1.3, 0.5);
    let alpha = random(40, 210);

    // Soft outer halo for larger spores
    if (size > 4 && random() < 0.35) {
      fill(red(col), green(col), blue(col), alpha * 0.2);
      ellipse(x, y, size * 4.5, size * 4.5);
    }

    // Core daub of paint
    fill(red(col), green(col), blue(col), alpha);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, size * random(0.8, 1.5), size);
    pop();
  }
}

function applyCanvasTexture() {
  // Subtle woven linen texture and tonal vignette over the entire painting
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Fine canvas weave pattern
      let weave = (sin(x * 1.6) + sin(y * 1.6)) * 2.2;
      let grain = random(-5, 5) + weave;

      // Gentle vignette at the outer corners
      let d = dist(x, y, 800, 1000);
      let vig = map(constrain(d, 650, 1350), 650, 1350, 1, 0.72);

      pixels[idx]     = constrain((pixels[idx] + grain) * vig, 0, 255);
      pixels[idx + 1] = constrain((pixels[idx + 1] + grain) * vig, 0, 255);
      pixels[idx + 2] = constrain((pixels[idx + 2] + grain) * vig, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(HSB, 360, 100, 100, 1.0);
  background(240, 65, 8);

  // 1. Deep atmospheric base (Impasto background blocks)
  for (let i = 0; i < 4500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let dToCenter = dist(x, y, width * 0.5, height * 0.45);

    let h, s, b;
    if (x < width * 0.5 + (n - 0.5) * 450) {
      h = random(195, 245); // Cool abyssal blues
      s = random(40, 80);
      b = map(dToCenter, 0, 1200, 35, 6);
    } else {
      h = random(335, 385) % 360; // Warm crimson and plum
      s = random(50, 85);
      b = map(dToCenter, 0, 1200, 40, 6);
    }
    b = constrain(b, 4, 45);
    drawPainterlyBlock(x, y, random(60, 220), random(60, 220), color(h, s, b, 0.18), n * TWO_PI);
  }

  // 2. Define the geometry of the two leaning figures
  let leftSpine = [
    createVector(250, 2100),
    createVector(320, 1500),
    createVector(460, 1100),
    createVector(660, 860),
    createVector(690, 650) // HeadL
  ];

  let rightSpine = [
    createVector(1350, 2100),
    createVector(1280, 1500),
    createVector(1140, 1100),
    createVector(940, 860),
    createVector(850, 680) // HeadR
  ];

  let embraceCenter = createVector(775, 740);

  // 3. The Aura of Connection (Warm glow behind the figures)
  for (let i = 0; i < 3500; i++) {
    let angle = random(TWO_PI);
    let r = pow(random(), 1.6) * 850;
    let x = embraceCenter.x + cos(angle) * r;
    let y = embraceCenter.y + sin(angle) * r * 1.25;

    let h = map(r, 0, 850, 45, 10);
    let s = map(r, 0, 850, 30, 85);
    let b = map(r, 0, 850, 100, 20);
    let a = map(r, 0, 850, 0.12, 0.02);

    let strokeAngle = angle + HALF_PI + (noise(x * 0.004, y * 0.004) - 0.5);
    drawBrushStroke(x, y, random(50, 160), random(15, 45), color(h, s, b, a), strokeAngle);
  }

  // 4. Paint the Left Figure (Cerulean, Teal, Indigo)
  paintFigure(leftSpine, true);

  // 5. Paint the Right Figure (Terracotta, Rose, Ochre, Gold)
  paintFigure(rightSpine, false);

  // 6. The Shared Flow (Ribbons of energy binding them together)
  for (let i = 0; i < 2200; i++) {
    let t = random();
    let idx = floor(random(1, leftSpine.length));
    let pL = leftSpine[idx];
    let pR = rightSpine[idx];

    let startPt = p5.Vector.lerp(pL, pR, t);
    startPt.x += random(-120, 120);
    startPt.y += random(-120, 120);

    let pt = startPt.copy();

    // Blend colors from Left to Right, peaking in brightness at the center
    let centerProx = 1.0 - abs(t - 0.5) * 2.0; 
    let h = (t < 0.5) ? map(t, 0, 0.5, 205, 45) : map(t, 0.5, 1, 45, 12);
    if (random() < 0.25) h = 345; // Occasional rose threads
    let s = map(centerProx, 0, 1, 75, 25);
    let b = map(centerProx, 0, 1, 65, 100);

    let steps = floor(random(12, 35));
    let w = random(4, 16);

    for (let sIdx = 0; sIdx < steps; sIdx++) {
      let dToHeart = dist(pt.x, pt.y, embraceCenter.x, embraceCenter.y);
      let angleToHeart = atan2(embraceCenter.y - pt.y, embraceCenter.x - pt.x);
      let nAngle = noise(pt.x * 0.003, pt.y * 0.003, i * 0.01) * TWO_PI * 2;

      // Swirl around the heart center
      let swirlAngle = angleToHeart + HALF_PI * (t < 0.5 ? 1 : -1) * 0.65;
      let finalAngle = lerp(swirlAngle, nAngle, 0.35);

      let alpha = map(sin(map(sIdx, 0, steps, 0, PI)), 0, 1, 0.02, 0.35);
      if (dToHeart > 650) alpha *= 0.3;

      drawBristleSegment(pt.x, pt.y, w, finalAngle, color(h, s, b, alpha));

      pt.x += cos(finalAngle) * 7;
      pt.y += sin(finalAngle) * 7;
    }
  }

  // 7. Sculptural Volume of the Heads (Tenderness and focus)
  drawHead(leftSpine[4].x, leftSpine[4].y, 115, true, 0.35);
  drawHead(rightSpine[4].x, rightSpine[4].y, 110, false, -0.4);

  // 8. The Nexus (Intense luminous impasto where they touch)
  for (let i = 0; i < 900; i++) {
    let r = pow(random(), 2.2) * 260;
    let a = random(TWO_PI);
    let x = embraceCenter.x + cos(a) * r * 0.85;
    let y = embraceCenter.y + sin(a) * r * 1.3;

    let h = random([38, 45, 50, 18, 195, 350]);
    let s = map(r, 0, 260, 10, 75) + random(-10, 10);
    let b = map(r, 0, 260, 100, 85);
    let strokeAngle = a + HALF_PI + random(-0.4, 0.4);

    if (r < 65) { 
      s = random(0, 20); 
      b = 100; 
    }

    drawImpastoDab(x, y, random(12, 42), random(5, 16), color(h, constrain(s, 0, 100), b, random(0.3, 0.75)), strokeAngle);
  }

  // 9. Rising Embers & Falling Grace (Vertical paint drips and sparks)
  for (let i = 0; i < 450; i++) {
    let x = embraceCenter.x + randomGaussian() * 260;
    let y = random(height * 0.25, height);
    let len = random(40, 280);
    let isGold = random() < 0.55;
    let c = isGold ? color(42, random(20, 65), 100, random(0.15, 0.5)) : 
                     (x < width * 0.5 ? color(200, 75, 90, 0.25) : color(12, 80, 90, 0.25));

    let dripY = y;
    let w = random(1.5, 4.5);
    let dir = (y < embraceCenter.y && isGold) ? -1 : 1; // Gold rises above, drips fall below

    for (let d = 0; d < len; d += 3) {
      fill(c);
      noStroke();
      let wobble = (noise(x * 0.02, dripY * 0.02) - 0.5) * 2.5;
      ellipse(x + wobble, dripY, w * map(d, 0, len, 1, 0.2));
      dripY += 3 * dir;
    }
    if (isGold && random() < 0.35) {
      fill(45, 15, 100, 0.85);
      ellipse(x, y, w * 2.8);
    }
  }

  // 10. Tactile Canvas Weave & Oil Glaze Finish
  applyCanvasTexture();
}

function paintFigure(spine, isLeft) {
  let numStrokes = 3800;
  for (let i = 0; i < numStrokes; i++) {
    let seg = floor(random(spine.length - 1));
    let t = random();
    let p1 = spine[seg];
    let p2 = spine[seg + 1];

    let basePos = p5.Vector.lerp(p1, p2, t);
    let spineAngle = atan2(p2.y - p1.y, p2.x - p1.x);

    // Taper body width from base to head
    let widthFactor = map(seg + t, 0, spine.length - 1, 300, 75);
    let offset = (random() + random() + random() - 1.5) * widthFactor;

    let perpAngle = spineAngle + HALF_PI;
    let x = basePos.x + cos(perpAngle) * offset;
    let y = basePos.y + sin(perpAngle) * offset;

    let n = noise(x * 0.004, y * 0.004);
    let strokeAngle = spineAngle + (n - 0.5) * 1.1;

    // Calculate lighting relative to the inner chest/head area
    let dToLight = dist(x, y, 775, 740);
    let lightEffect = constrain(map(dToLight, 50, 750, 1, 0), 0, 1);
    lightEffect = pow(lightEffect, 1.4);

    let h, s, b;
    if (isLeft) {
      h = lerp(225, 185, lightEffect) + random(-12, 12);
      s = lerp(75, 35, pow(lightEffect, 2));
      b = lerp(18, 95, lightEffect) + random(-8, 8);
      // Warm reflection on the inner edge facing the partner
      if (offset > widthFactor * 0.15 && lightEffect > 0.35) {
        h = lerp(h, 40, 0.65);
        s = lerp(s, 55, 0.5);
      }
    } else {
      h = lerp(345, 42, lightEffect) + random(-12, 12);
      if (h < 0) h += 360;
      h = h % 360;
      s = lerp(82, 40, pow(lightEffect, 2));
      b = lerp(18, 98, lightEffect) + random(-8, 8);
      // Cool reflection on the inner edge facing the partner
      if (offset < -widthFactor * 0.15 && lightEffect > 0.35) {
        h = lerp(h, 200, 0.45);
      }
    }

    let len = map(seg, 0, spine.length - 1, 130, 45) * random(0.6, 1.4);
    let wid = map(seg, 0, spine.length - 1, 38, 12) * random(0.6, 1.4);

    drawBrushStroke(x, y, len, wid, color(h, constrain(s, 0, 100), constrain(b, 0, 100), random(0.2, 0.55)), strokeAngle);
  }
}

function drawHead(cx, cy, radius, isLeft, tilt) {
  let strokes = 850;
  for (let i = 0; i < strokes; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 0.75) * radius;

    // Shape into a tilted oval
    let ox = cos(a) * r * 0.82;
    let oy = sin(a) * r * 1.15;

    let rx = ox * cos(tilt) - oy * sin(tilt);
    let ry = ox * sin(tilt) + oy * cos(tilt);

    let x = cx + rx;
    let y = cy + ry;

    // Contour angle follows the oval's perimeter, flowing inward
    let strokeAngle = a + HALF_PI + tilt;

    // Distance to the point where their foreheads/faces meet (775, 675)
    let dToTouch = dist(x, y, 775, 675);
    let glow = constrain(map(dToTouch, 15, 220, 1, 0), 0, 1);

    let h, s, b;
    if (isLeft) {
      h = lerp(215, 45, pow(glow, 1.3));
      s = lerp(70, 20, glow);
      b = lerp(25, 100, glow);
    } else {
      h = lerp(8, 48, pow(glow, 1.3));
      s = lerp(78, 20, glow);
      b = lerp(28, 100, glow);
    }

    let w = map(r, 0, radius, 16, 7);
    let l = map(r, 0, radius, 45, 22);
    drawBrushStroke(x, y, l, w, color(h, s, b, random(0.3, 0.7)), strokeAngle);
  }
}

function drawPainterlyBlock(x, y, w, h, col, angle) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  fill(col);
  rectMode(CENTER);
  rect(0, 0, w, h, 12);
  pop();
}

function drawBrushStroke(x, y, len, wid, col, angle) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();

  let bristles = floor(constrain(wid * 0.45, 3, 14));
  let h = hue(col);
  let s = saturation(col);
  let b = brightness(col);
  let a = alpha(col);

  for (let i = 0; i < bristles; i++) {
    let offset = map(i, 0, bristles - 1, -wid * 0.5, wid * 0.5);
    let bVar = b + random(-7, 7);
    let hVar = (h + random(-4, 4) + 360) % 360;

    fill(hVar, s, constrain(bVar, 0, 100), a);
    let bLen = len * random(0.75, 1.15);
    let bWid = (wid / bristles) * random(1.3, 2.4);

    ellipse(random(-len * 0.08, len * 0.08), offset, bLen, bWid);
  }
  pop();
}

function drawBristleSegment(x, y, wid, angle, col) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  fill(col);
  ellipse(0, 0, 11, wid * 0.65);

  // Subtle highlight ridge for 3D paint effect
  fill(hue(col), saturation(col) * 0.7, min(100, brightness(col) * 1.25), alpha(col) * 0.6);
  ellipse(0, -wid * 0.2, 9, wid * 0.25);
  pop();
}

function drawImpastoDab(x, y, len, wid, col, angle) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();

  // Dark under-edge (shadow of thick paint)
  fill(hue(col), saturation(col), brightness(col) * 0.45, alpha(col) * 0.8);
  ellipse(2, 2, len, wid);

  // Main body of paint
  fill(col);
  ellipse(0, 0, len, wid);

  // Specular ridge
  fill(hue(col), saturation(col) * 0.3, 100, alpha(col) * 0.85);
  ellipse(-1, -1, len * 0.65, wid * 0.35);
  pop();
}

function applyCanvasTexture() {
  loadPixels();
  let d = pixelDensity();
  let totalWidth = width * d;
  let totalHeight = height * d;

  for (let y = 0; y < totalHeight; y++) {
    for (let x = 0; x < totalWidth; x++) {
      let idx = 4 * (y * totalWidth + x);

      // Fine linen canvas weave + organic grain
      let weave = (sin(x * 0.85) * cos(y * 0.85)) * 5;
      let grain = (random() - 0.5) * 12;

      // Subtle vignette to frame the intimacy
      let distFromCenter = dist(x / d, y / d, width * 0.5, height * 0.48);
      let vig = map(distFromCenter, 400, 1300, 1.0, 0.72);
      vig = constrain(vig, 0.72, 1.0);

      let delta = weave + grain;

      pixels[idx]     = constrain((pixels[idx] + delta) * vig, 0, 255);
      pixels[idx + 1] = constrain((pixels[idx + 1] + delta) * vig, 0, 255);
      pixels[idx + 2] = constrain((pixels[idx + 2] + delta) * vig, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  background(12, 14, 24);

  // 1. Deep Atmospheric Background (Impasto brushwork)
  drawAtmosphere();

  // 2. Ambient Golden Glow at the Nexus
  drawAmbientGlow(800, 920);

  // 3. The Two Entities (Flowing, distinct textured forms)
  drawEntities();

  // 4. The Golden Bridges (Connection threads where they meet)
  drawBridges();

  // 5. Rising Sparks & Shared Light
  drawEmbers();

  // 6. Physical Canvas Texture Overlay
  applyCanvasTexture();
}

function drawAtmosphere() {
  noStroke();
  for (let i = 0; i < 35000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let d = dist(x, y, 800, 920);

    let c;
    if (d < 650) {
      let amt = map(d, 0, 650, 1, 0);
      c = lerpColor(color(30, 20, 38), color(85, 40, 45), amt * n);
    } else {
      c = lerpColor(color(10, 13, 24), color(26, 20, 36), n);
    }

    fill(red(c), green(c), blue(c), random(15, 45));
    push();
    translate(x, y);
    rotate(n * TWO_PI * 2);
    rectMode(CENTER);
    rect(0, 0, random(30, 120), random(8, 30), 6);
    pop();
  }
}

function drawAmbientGlow(gx, gy) {
  noStroke();
  for (let r = 800; r > 0; r -= 8) {
    let inter = map(r, 0, 800, 1, 0);
    let c = lerpColor(color(255, 140, 60, 0), color(255, 220, 150, 5), pow(inter, 2));
    fill(c);
    circle(gx, gy, r * 2);
  }
}

function getLeftSpine(t) {
  // Starts bottom-left, curves in toward the nexus, then cradles upward
  let x = lerp(250, 790, pow(t, 0.65)) + sin(t * PI * 1.4) * 160;
  let y = lerp(2050, 480, t);
  return createVector(x, y);
}

function getRightSpine(t) {
  // Starts bottom-right, sweeps up and leans down into the left entity
  let x = lerp(1350, 810, pow(t, 0.65)) - sin(t * PI * 1.4) * 160;
  let y = lerp(2050, 520, t) - sin(t * PI) * 70;
  return createVector(x, y);
}

function drawEntities() {
  // Interleave drawing of both forms so they visually weave together
  let totalStrands = 2600;
  for (let i = 0; i < totalStrands; i++) {
    let isLeft = (i % 2 === 0);
    let tStart = random(0, 0.88);
    // Concentrate more brushwork near the upper embrace
    if (random() < 0.4) tStart = random(0.45, 0.88);

    let offsetScale = map(tStart, 0, 1, 320, 70);
    let offset = randomGaussian(0, offsetScale);

    let basePaletteLeft = [
      color(20, 55, 105),
      color(35, 110, 150),
      color(75, 175, 200),
      color(50, 45, 115),
      color(160, 220, 240)
    ];

    let basePaletteRight = [
      color(140, 25, 55),
      color(205, 55, 65),
      color(235, 110, 55),
      color(250, 165, 85),
      color(100, 20, 45)
    ];

    let baseCol = isLeft ? random(basePaletteLeft) : random(basePaletteRight);
    let goldCol = color(255, 235, 175);
    let coreWhite = color(255, 250, 240);

    let steps = int(random(20, 55));
    let tStep = 0.0045;

    noFill();
    let prevPt = null;

    for (let s = 0; s < steps; s++) {
      let t = tStart + s * tStep;
      if (t > 1) break;

      let spine = isLeft ? getLeftSpine(t) : getRightSpine(t);
      let nextSpine = isLeft ? getLeftSpine(t + 0.01) : getRightSpine(t + 0.01);
      let tangent = p5.Vector.sub(nextSpine, spine).normalize();
      let normal = createVector(-tangent.y, tangent.x);

      let n = noise(spine.x * 0.004, spine.y * 0.004, i * 0.02);
      let curOffset = offset * map(t, 0, 1, 1, 0.25) + map(n, 0, 1, -70, 70);

      let pt = p5.Vector.add(spine, p5.Vector.mult(normal, curOffset));

      // Pull strands toward the other entity when in the nexus zone
      let otherSpine = isLeft ? getRightSpine(t) : getLeftSpine(t);
      let dToOther = dist(pt.x, pt.y, otherSpine.x, otherSpine.y);

      if (dToOther < 350 && t > 0.35) {
        let pull = map(dToOther, 0, 350, 0.35, 0);
        pt.x = lerp(pt.x, otherSpine.x, pull * 0.15);
        pt.y = lerp(pt.y, otherSpine.y, pull * 0.15);
      }

      if (prevPt) {
        // Color shifts toward radiant gold/white as it nears the other form
        let glowAmt = constrain(map(dToOther, 40, 380, 1, 0), 0, 1);
        glowAmt = pow(glowAmt, 1.6);

        let c = lerpColor(baseCol, goldCol, glowAmt);
        if (glowAmt > 0.75) {
          c = lerpColor(c, coreWhite, map(glowAmt, 0.75, 1, 0, 0.8));
        }

        let alpha = map( sin(map(s, 0, steps, 0, PI)), 0, 1, 10, 170);
        stroke(red(c), green(c), blue(c), alpha);
        strokeWeight(map(s, 0, steps, 14, 2) * random(0.7, 1.3));
        line(prevPt.x, prevPt.y, pt.x, pt.y);
      }
      prevPt = pt;
    }
  }
}

function drawBridges() {
  // Delicate filaments of light explicitly tying the two forms together
  noFill();
  for (let i = 0; i < 650; i++) {
    let t = random(0.38, 0.96);
    let pL = getLeftSpine(t);
    let pR = getRightSpine(t + random(-0.06, 0.06));

    pL.add(random(-90, 60), random(-60, 60));
    pR.add(random(-60, 90), random(-60, 60));

    let d = pL.dist(pR);
    if (d < 480) {
      let mid = p5.Vector.lerp(pL, pR, 0.5);
      mid.y += random(-100, 100);
      mid.x += random(-50, 50);

      let alpha = map(d, 0, 480, 140, 10);
      if (random() < 0.3) {
        stroke(255, 245, 210, alpha);
        strokeWeight(random(1, 3.5));
      } else {
        let bridgeCol = lerpColor(color(100, 210, 245), color(255, 140, 90), random());
        stroke(red(bridgeCol), green(bridgeCol), blue(bridgeCol), alpha * 0.8);
        strokeWeight(random(1, 5));
      }

      beginShape();
      vertex(pL.x, pL.y);
      quadraticVertex(mid.x, mid.y, pR.x, pR.y);
      endShape();
    }
  }
}

function drawEmbers() {
  // Daubs of pure light & paint flecks rising from the embrace
  noStroke();
  for (let i = 0; i < 1600; i++) {
    let angle = random(TWO_PI);
    let r = abs(randomGaussian(0, 260));
    let x = 800 + cos(angle) * r;
    let y = 850 + sin(angle) * r * 1.4 - pow(random(), 2) * 550;

    let dToCenter = dist(x, y, 800, 820);
    let size = map(dToCenter, 0, 900, random(3, 14), random(1, 5));
    size = constrain(size, 1, 14);

    let c;
    let choice = random();
    if (choice < 0.5) {
      c = color(255, 240, 195, random(80, 230)); // Gold light
    } else if (choice < 0.75) {
      c = color(255, 150, 95, random(60, 190));  // Warm coral
    } else {
      c = color(130, 225, 250, random(60, 190)); // Cool cyan
    }

    fill(c);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, size, size * random(0.5, 1.8));
    pop();
  }
}

function applyCanvasTexture() {
  // Subtle woven linen texture and organic color grain
  loadPixels();
  for (let y = 0; y < height; y++) {
    let weaveY = sin(y * 0.9);
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;
      let weaveX = sin(x * 0.9);
      let weave = (weaveX + weaveY) * 3.5;
      let grain = random(-7, 7);

      // Slight vignette at the very edges
      let d = dist(x, y, 800, 1000);
      let vig = map(d, 700, 1300, 0, -18, true);

      let mod = weave + grain + vig;
      pixels[idx]     = constrain(pixels[idx] + mod, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + mod, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + mod, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // 1. Deep Atmospheric Background
  background(12, 10, 24);

  drawBackgroundWash();

  // 2. Distant Nebula / Ambient Glow
  blendMode(SCREEN);
  drawAmbientGlow(width * 0.48, height * 0.42, 1100, color(90, 20, 50, 3));
  drawAmbientGlow(width * 0.35, height * 0.6, 900, color(20, 50, 90, 3));
  drawAmbientGlow(width * 0.65, height * 0.6, 900, color(100, 35, 20, 3));
  drawAmbientGlow(width * 0.48, height * 0.40, 600, color(255, 160, 80, 5));

  // 3. The Two Entities (Flowing Ribbons of Essence)
  blendMode(BLEND);
  let numStrands = 2200;

  // We interleave the drawing of both entities so they genuinely entwine in depth
  for (let i = 0; i < numStrands; i++) {
    let progress = i / numStrands;
    let isEntityA = (i % 2 === 0);
    drawLoveStrand(isEntityA, progress);
  }

  // 4. The Core of Union (Intense Soft Light at the Embrace)
  blendMode(ADD);
  drawUnionCore();

  // 5. Golden Embers / Sparks of Connection
  drawSparks();

  // 6. Painterly Canvas Texture & Vignette
  blendMode(MULTIPLY);
  drawVignette();

  blendMode(OVERLAY);
  drawCanvasTexture();
}

function drawBackgroundWash() {
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);

    // Gradient from deep slate blue (left/bottom) to deep wine (right/top)
    let c1 = color(15, 22, 42, 12);
    let c2 = color(38, 12, 28, 12);
    let c3 = color(8, 6, 16, 18);

    let col = lerpColor(c1, c2, (x / width) * 0.7 + n * 0.3);
    col = lerpColor(col, c3, pow(y / height, 1.5));

    fill(col);

    push();
    translate(x, y);
    rotate(n * TWO_PI * 2);
    let w = random(80, 300);
    let h = random(30, 120);
    ellipse(0, 0, w, h);
    pop();
  }
}

function drawAmbientGlow(x, y, maxRad, col) {
  noStroke();
  fill(col);
  for (let r = maxRad; r > 20; r -= 15) {
    let jitX = random(-15, 15);
    let jitY = random(-15, 15);
    ellipse(x + jitX, y + jitY, r, r * 1.15);
  }
}

function getCenterA(t) {
  // Entity A: Rises from bottom-left, sweeps right, curls into the center embrace
  let p0 = {x: 150, y: 2150};
  let p1 = {x: 120, y: 1200};
  let p2 = {x: 1100, y: 850};
  let p3 = {x: 680, y: 420};

  let x = bezierPoint(p0.x, p1.x, p2.x, p3.x, t);
  let y = bezierPoint(p0.y, p1.y, p2.y, p3.y, t);

  // Add a secondary spiral motion near the top (the embrace)
  if (t > 0.5) {
    let embraceFactor = map(t, 0.5, 1.0, 0, 1);
    embraceFactor = pow(embraceFactor, 1.5);
    let angle = embraceFactor * PI * 1.2;
    x += sin(angle) * 140 * embraceFactor;
    y += cos(angle) * 80 * embraceFactor;
  }
  return createVector(x, y);
}

function getCenterB(t) {
  // Entity B: Rises from bottom-right, sweeps left, cradles Entity A
  let p0 = {x: 1450, y: 2150};
  let p1 = {x: 1480, y: 1300};
  let p2 = {x: 450, y: 950};
  let p3 = {x: 860, y: 400};

  let x = bezierPoint(p0.x, p1.x, p2.x, p3.x, t);
  let y = bezierPoint(p0.y, p1.y, p2.y, p3.y, t);

  if (t > 0.5) {
    let embraceFactor = map(t, 0.5, 1.0, 0, 1);
    embraceFactor = pow(embraceFactor, 1.5);
    let angle = embraceFactor * PI * 1.2 + PI;
    x += sin(angle) * 140 * embraceFactor;
    y += cos(angle) * 80 * embraceFactor;
  }
  return createVector(x, y);
}

function drawLoveStrand(isA, depthProgress) {
  let steps = 140;

  // Each strand has its own personality and offset from the main spine
  let radialBias = pow(random(1), 1.6); // Denser near the core
  let baseSpread = 380 * radialBias;
  let strandAngle = random(TWO_PI);
  let noiseOffset = random(10000);

  // Base palettes
  // Entity A: Cool (Teal, Cerulean, Indigo, Lavender)
  let cool1 = color(25, 95, 135);
  let cool2 = color(65, 175, 195);
  let cool3 = color(95, 85, 175);

  // Entity B: Warm (Crimson, Terracotta, Coral, Rose)
  let warm1 = color(165, 30, 60);
  let warm2 = color(235, 85, 65);
  let warm3 = color(215, 60, 110);

  // Love/Union Palette: Gold, Peach, Incandescent White
  let union1 = color(255, 190, 110);
  let union2 = color(255, 240, 210);

  let baseColor;
  let rCol = random(1);
  if (isA) {
    baseColor = rCol < 0.4 ? cool1 : (rCol < 0.8 ? cool2 : cool3);
  } else {
    baseColor = rCol < 0.4 ? warm1 : (rCol < 0.8 ? warm2 : warm3);
  }

  // Slightly vary the individual strand's base color
  baseColor = lerpColor(baseColor, color(255), random(-0.1, 0.15));

  // Determine start and end of this specific stroke (some are full length, some are wispy fragments)
  let tStart = random(0, 0.3);
  if (random(1) < 0.4) tStart = random(0.3, 0.7); // Extra density in the middle/embrace
  let tEnd = constrain(tStart + random(0.3, 0.85), 0, 1);

  let prevPos = null;

  for (let s = 0; s <= steps; s++) {
    let t = map(s, 0, steps, tStart, tEnd);

    let cA = getCenterA(t);
    let cB = getCenterB(t);

    let myCenter = isA ? cA : cB;
    let otherCenter = isA ? cB : cA;

    // As they rise, the spread tightens slightly then blooms at the top
    let spreadProfile = sin(t * PI) * 0.6 + 0.5;
    if (t > 0.75) spreadProfile += pow(map(t, 0.75, 1, 0, 1), 2) * 0.8;

    let currentSpread = baseSpread * spreadProfile;

    // Organic turbulence
    let nTheta = noise(t * 2.5, noiseOffset) * TWO_PI * 2;
    let nRad = noise(t * 3.5, noiseOffset + 500);

    let offsetX = cos(strandAngle + nTheta * 0.5) * currentSpread * nRad;
    let offsetY = sin(strandAngle + nTheta * 0.5) * currentSpread * nRad * 0.6;

    let pos = createVector(myCenter.x + offsetX, myCenter.y + offsetY);

    // Calculate proximity to the OTHER entity's spine and current position
    let distToOther = p5.Vector.dist(pos, otherCenter);

    // Pull strands toward each other when they get close (magnetic attraction of love)
    let attraction = constrain(map(distToOther, 550, 80, 0, 1), 0, 1);
    attraction = pow(attraction, 1.8);

    // Swirl around the midpoint between A and B when attraction is high
    let midPoint = p5.Vector.lerp(cA, cB, 0.5);
    pos = p5.Vector.lerp(pos, midPoint, attraction * 0.45);

    // Add fine fluid curl
    let curlAngle = noise(pos.x * 0.004, pos.y * 0.004, noiseOffset * 0.01) * TWO_PI * 2;
    pos.x += cos(curlAngle) * 25 * (1 - radialBias * 0.5);
    pos.y += sin(curlAngle) * 25 * (1 - radialBias * 0.5);

    if (prevPos !== null) {
      // Color transformation based on connection (attraction) and height (t)
      let connectionGlow = constrain(map(distToOther, 420, 40, 0, 1), 0, 1);
      connectionGlow = pow(connectionGlow, 1.4);

      // Blend toward the other's color slightly, then strongly toward gold/light
      let oppositeColor = isA ? warm2 : cool2;
      letmixedCol = lerpColor(baseColor, oppositeColor, connectionGlow * 0.4);
      let finalCol = lerpColor(letmixedCol, union1, connectionGlow * 0.85);

      if (connectionGlow > 0.65) {
        finalCol = lerpColor(finalCol, union2, map(connectionGlow, 0.65, 1, 0, 0.9));
      }

      // Fade in at start of strand, fade out at end
      let edgeFade = sin(map(s, 0, steps, 0, PI));
      let alpha = map(depthProgress, 0, 1, 15, 75) * edgeFade;
      if (connectionGlow > 0.5) alpha *= 1.3;

      // Brushstroke thickness
      let sw = map(radialBias, 0, 1, 8, 1.2) * edgeFade;
      sw *= map(noise(t * 8, noiseOffset), 0, 1, 0.4, 1.8);

      // Painterly dab/stroke
      stroke(red(finalCol), green(finalCol), blue(finalCol), constrain(alpha, 0, 255));
      strokeWeight(sw);
      line(prevPos.x, prevPos.y, pos.x, pos.y);

      // Occasional soft wide bristle marks for texture
      if (s % 6 === 0 && random(1) < 0.35) {
        noStroke();
        fill(red(finalCol), green(finalCol), blue(finalCol), alpha * 0.35);
        push();
        translate(pos.x, pos.y);
        rotate(atan2(pos.y - prevPos.y, pos.x - prevPos.x));
        ellipse(0, 0, sw * 5, sw * 2.2);
        pop();
      }
    }
    prevPos = pos.copy();
  }
}

function drawUnionCore() {
  // The heart of the painting where the two paths cross and merge (around y = 500 to 950)
  noStroke();
  for (let i = 0; i < 350; i++) {
    let t = random(0.42, 0.95);
    let cA = getCenterA(t);
    let cB = getCenterB(t);
    let mid = p5.Vector.lerp(cA, cB, random(0.2, 0.8));

    let d = p5.Vector.dist(cA, cB);
    if (d < 350) {
      let intensity = map(d, 350, 0, 0.2, 1);
      let rad = random(30, 220) * intensity;
      let ox = randomGaussian(0, 70 * intensity);
      let oy = randomGaussian(0, 70 * intensity);

      // Warm incandescent golds and roses
      let c = lerpColor(color(255, 110, 60, 4), color(255, 220, 160, 7), random(1));
      fill(c);
      ellipse(mid.x + ox, mid.y + oy, rad, rad * random(0.8, 1.3));
    }
  }
}

function drawSparks() {
  // Delicate motes of light rising from the embrace
  for (let i = 0; i < 650; i++) {
    let t = random(0.3, 1.0);
    let cA = getCenterA(t);
    let cB = getCenterB(t);
    let mid = p5.Vector.lerp(cA, cB, random(0, 1));

    let spread = map(t, 0.3, 1.0, 120, 480);
    let angle = random(TWO_PI);
    let r = pow(random(1), 1.5) * spread;

    let x = mid.x + cos(angle) * r;
    let y = mid.y + sin(angle) * r - random(0, 180 * t); // Drift upward

    let sz = random(1.5, 6.5);
    let alpha = random(30, 180) * (1 - r / spread);

    let sparkCol;
    let rType = random(1);
    if (rType < 0.6) {
      sparkCol = color(255, 215, 140, alpha); // Gold
    } else if (rType < 0.8) {
      sparkCol = color(255, 140, 120, alpha); // Warm coral
    } else {
      sparkCol = color(150, 230, 255, alpha); // Soft cyan
    }

    noStroke();
    fill(sparkCol);
    ellipse(x, y, sz, sz);

    // Soft halo around larger sparks
    if (sz > 4.5) {
      fill(red(sparkCol), green(sparkCol), blue(sparkCol), alpha * 0.25);
      ellipse(x, y, sz * 3.5, sz * 3.5);
    }
  }
}

function drawVignette() {
  noFill();
  let maxDim = max(width, height);
  for (let r = maxDim * 0.75; r < maxDim * 1.35; r += 8) {
    let alpha = map(r, maxDim * 0.75, maxDim * 1.35, 0, 120);
    stroke(18, 12, 28, alpha * 0.08);
    strokeWeight(12);
    ellipse(width * 0.5, height * 0.48, r * 0.85, r);
  }
}

function drawCanvasTexture() {
  // Subtle linen/impasto weave using fast procedural lines
  strokeWeight(1);
  for (let i = 0; i < 25000; i++) {
    let x = random(width);
    let y = random(height);
    let len = random(15, 60);

    if (random(1) < 0.5) {
      stroke(255, 250, 240, 6);
    } else {
      stroke(10, 5, 15, 8);
    }

    // Slight organic wave to the texture
    if (i % 2 === 0) {
      line(x, y, x + len, y + random(-2, 2));
    } else {
      line(x, y, x + random(-2, 2), y + len);
    }
  }
}

