  paintLock(708, 792, 630, 930, 588, 1130, 13, color(46, 22, 28));
  paintLock(706, 778, 760, 748, 824, 792, 8, color(150, 82, 54));
  paintLock(992, 868, 1090, 990, 1152, 1170, 20, color(24, 14, 22));
  paintLock(958, 842, 1030, 970, 1004, 1150, 12, color(48, 24, 30));
  paintLock(902, 1024, 862, 1066, 828, 1124, 5, color(132, 70, 54));

  claspedHands(822, 1326);
  noStroke();
