}

function skyAt(t) {
  t = constrain(t, 0, 1);
  const stops = [
    [0.00, color(8, 10, 28)],
    [0.18, color(24, 22, 58)],
    [0.34, color(72, 36, 78)],
    [0.46, color(150, 64, 82)],
    [0.56, color(214, 112, 90)],
    [0.64, color(242, 186, 122)],
    [0.73, color(104, 50, 56)],
    [0.84, color(34, 16, 28)],
    [1.00, color(12, 6, 12)]
  ];
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      let u = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      u = u * u * (3 - 2 * u);
      return lerpColor(stops[i][1], stops[i + 1][1], u);
    }
  }
  return stops[stops.length - 1][1];
}

function paintSky() {
  noFill();
  strokeWeight(2);
  for (let y = 0; y < height; y++) {
    const c = skyAt(y / height);
    const n = noise(0.15, y * 0.0035);
    stroke(
      red(c) + (n - 0.5) * 10,
      green(c) + (n - 0.5) * 6,
      blue(c) + (n - 0.5) * 8
    );
    line(0, y, width, y);
  }
}

function skyStrokes() {
