    const n = noise(x * 0.004, y * 0.004);
    stroke(red(c) + 22, green(c) + 10, blue(c) + 6, 12 + n * 20);
    strokeWeight(random(1, 2.4));
    const len = random(18, 74);
    line(x, y, x + len, y + random(-2, 2));
  }
}

function stars() {
  noStroke();
  for (let i = 0; i < 90; i++) {
