function hill(yBase, amp, c, seed) {
  noStroke();
  fill(c);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 12) {
    vertex(x, yBase - noise(x * 0.0028, seed) * amp);
