  vertex(width, height);
  endShape(CLOSE);
}

function thicket() {
  noStroke();
  fill(16, 14, 20, 165);
  beginShape();
  vertex(0, 1560);
  for (let x = 0; x <= width; x += 8) {
    const n = noise(x * 0.012, 4.4);
    const spike = n > 0.52 ? (n - 0.52) * 240 : 0;
    vertex(x, 1368 - spike);
  }
  vertex(width, 1560);
  endShape(CLOSE);
}

function canopy(x, y, s) {
  noStroke();
  for (let i = 0; i < 20; i++) {
    const a = random(TWO_PI);
    const rr = random(10, 76) * s;
    if (random() > 0.84) fill(64, 44, 38, 190);
    else fill(14, 20, 18, 225);
    ellipse(
      x + cos(a) * rr * 0.52,
      y + sin(a) * rr * 0.38,
      random(34, 86) * s,
      random(26, 60) * s
    );
  }
}

function frameTree(x, y, s) {
  noStroke();
  fill(12, 14, 16, 220);
  rect(x - 4 * s, y, 8 * s, 150 * s, 3);
  canopy(x, y, s);
}

function lamps() {
  const pts = [
    [250, 1410],
    [410, 1466],
    [590, 1438],
    [1120, 1452],
    [1294, 1404]
  ];
  for (let i = 0; i < pts.length; i++) {
