function softDisc(x, y, r, c, maxA) {
  noStroke();
  const rings = 14;
  for (let i = rings; i >= 1; i--) {
    const t = i / rings;
    fill(red(c), green(c), blue(c), (maxA / 6.5) * (1 - t));
    ellipse(x, y, r * 2 * t, r * 2 * t);
  }
}

function poly(pts) {
  beginShape();
  for (let i = 0; i < pts.length; i++) vertex(pts[i][0], pts[i][1]);
  endShape(CLOSE);
}

function softEdge(pts, c, rad) {
  noStroke();
  fill(red(c), green(c), blue(c), 32);
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    const steps = max(1, dist(a[0], a[1], b[0], b[1]) / 8);
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      ellipse(lerp(a[0], b[0], t), lerp(a[1], b[1], t), rad, rad);
    }
  }
}

function insidePoly(x, y, pts) {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const xi = pts[i][0];
    const yi = pts[i][1];
    const xj = pts[j][0];
    const yj = pts[j][1];
    const hit = (yi > y) !== (yj > y) &&
      x < ((xj - xi) * (y - yi)) / ((yj - yi) || 1e-6) + xi;
    if (hit) inside = !inside;
  }
  return inside;
}

function bounds(pts) {
  let minX = 1e9;
  let minY = 1e9;
  let maxX = -1e9;
  let maxY = -1e9;
  for (let i = 0; i < pts.length; i++) {
    minX = min(minX, pts[i][0]);
    minY = min(minY, pts[i][1]);
    maxX = max(maxX, pts[i][0]);
    maxY = max(maxY, pts[i][1]);
  }
  return [minX, minY, maxX, maxY];
}

function robeTexture(pts, base, alt) {
  const b = bounds(pts);
  noStroke();
  for (let i = 0; i < 3200; i++) {
    const x = random(b[0], b[2]);
    const y = random(b[1], b[3]);
    if (!insidePoly(x, y, pts)) continue;
    const n = noise(x * 0.008, y * 0.008);
    const c = lerpColor(base, alt, n);
    fill(red(c), green(c), blue(c), random(14, 38));
    push();
    translate(x, y);
    rotate(random(-0.4, 0.4) + 1.2);
    ellipse(0, 0, random(4, 8), random(14, 40));
    pop();
    if (random() < 0.025) {
      fill(220, 180, 110, 36);
      ellipse(x, y, 2.2, 2.2);
    }
  }
}

function paintRobe(pts, base, alt) {
  softEdge(pts, base, 20);
  noStroke();
  fill(base);
  poly(pts);
  robeTexture(pts, base, alt);
}

function emberEdge(x1, y1, x2, y2) {
  for (let i = 0; i < 26; i++) {
    const t = i / 25;
    const x = lerp(x1, x2, t);
    const y = lerp(y1, y2, t);
    stroke(255, 196, 150, random(14, 52));
    strokeWeight(random(1.4, 3.2));
    line(x, y, x + random(3, 8), y + random(-1, 1));
  }
}

function smoothShawl(pts, w, c, a) {
  noFill();
  stroke(red(c), green(c), blue(c), a);
  strokeWeight(w);
  beginShape();
  curveVertex(pts[0][0], pts[0][1]);
  for (let i = 0; i < pts.length; i++) curveVertex(pts[i][0], pts[i][1]);
  curveVertex(pts[pts.length - 1][0], pts[pts.length - 1][1]);
  endShape();
}

function crPoint(pts, t) {
  const n = pts.length;
  const i = constrain(floor(t), 0, n - 2);
  const u = t - i;
  const p0 = pts[max(i - 1, 0)];
  const p1 = pts[i];
  const p2 = pts[min(i + 1, n - 1)];
  const p3 = pts[min(i + 2, n - 1)];
  const u2 = u * u;
  const u3 = u2 * u;
  const x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * u + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3);
  const y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * u + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3);
  return [x, y];
}

function paintArm(pts, sleeve, skin) {
  noStroke();
  const last = pts.length - 1;
  for (let i = 0; i <= 56; i++) {
    const u = i / 56;
    const p = crPoint(pts, u * last);
    const w = lerp(42, 15, u);
    let c;
    if (u < 0.48) c = sleeve;
    else if (u > 0.66) c = skin;
    else c = lerpColor(sleeve, skin, (u - 0.48) / 0.18);
    const n = noise(p[0] * 0.02, p[1] * 0.02);
    fill(red(c) + n * 14 - 6, green(c) + n * 8 - 4, blue(c) + n * 6 - 4, 242);
    ellipse(p[0], p[1], w, w * 0.78);
  }
}

function drawHead(cx, cy, rot, dir, skin, shadow, hair) {
  push();
  translate(cx, cy);
  rotate(rot);
  noStroke();

  fill(hair);
  ellipse(-16 * dir, -6, 148, 186);
  ellipse(-6 * dir, -48, 130, 96);
  ellipse(-42 * dir, 18, 52, 96);

  fill(shadow);
  rectMode(CENTER);
  rect(-2 * dir, 112, 42, 96, 12);
  fill(skin);
  rect(4 * dir, 108, 30, 78, 10);

  fill(shadow);
  ellipse(-4 * dir, 8, 116, 150);
  fill(skin);
  ellipse(10 * dir, 2, 112, 146);

  fill(shadow);
  ellipse(-52 * dir, 16, 22, 34);
  fill(skin);
  ellipse(-50 * dir, 16, 14, 22);
  fill(shadow);
  ellipse(-50 * dir, 18, 6, 12);

  fill(hair);
  ellipse(-40 * dir, -8, 34, 64);
  ellipse(6 * dir, -66, 92, 34);

  fill(255, 214, 186, 40);
  ellipse(16 * dir, -28, 36, 22);
  fill(255, 188, 156, 48);
  ellipse(30 * dir, 18, 34, 26);
  fill(186, 92, 96, 34);
  ellipse(26 * dir, 24, 28, 16);
  fill(140, 82, 78, 30);
  ellipse(6 * dir, 52, 40, 16);
  fill(186, 92, 84, 150);
  ellipse(4 * dir, 86, 30, 14);

  stroke(120, 68, 66);
  strokeWeight(1.7);
  noFill();
  bezier(8 * dir, -24, 18 * dir, -30, 30 * dir, -28, 40 * dir, -20);
  stroke(96, 52, 56);
  strokeWeight(2);
  arc(24 * dir, -6, 28, 12, 0.18, PI - 0.18);

  stroke(168, 104, 96);
  strokeWeight(1.6);
  bezier(34 * dir, -2, 50 * dir, 4, 52 * dir, 16, 38 * dir, 22);
  noStroke();
  fill(150, 86, 80, 80);
  ellipse(40 * dir, 20, 7, 5);

  stroke(158, 74, 80);
  strokeWeight(1.8);
  noFill();
  arc(28 * dir, 36, 16, 8, 0.25, PI - 0.25);
  pop();
}

function paintLock(x0, y0, cx, cy, x1, y1, w, col) {
  noStroke();
  for (let i = 0; i <= 18; i++) {
    const t = i / 18;
    const it = 1 - t;
    const x = it * it * x0 + 2 * it * t * cx + t * t * x1;
    const y = it * it * y0 + 2 * it * t * cy + t * t * y1;
    const ww = w * (1 - t * 0.72);
    fill(red(col), green(col), blue(col), 225);
    ellipse(x, y, ww, ww * 1.4);
  }
}

function claspedHands(x, y) {
  push();
  translate(x, y);
  noStroke();
  fill(90, 48, 46, 46);
  ellipse(0, 10, 64, 36);
  fill(196, 132, 112);
  ellipse(-22, 6, 40, 30);
  fill(224, 168, 140);
  ellipse(-8, -2, 36, 28);
  fill(176, 114, 98);
  ellipse(24, 8, 38, 28);
  fill(210, 150, 124);
  ellipse(10, 2, 34, 26);
  fill(228, 176, 148);
  ellipse(-16, -16, 13, 20);
  ellipse(18, -14, 12, 18);
  fill(200, 126, 108, 90);
  ellipse(-6, -12, 8, 6);
  ellipse(2, -11, 8, 6);
  ellipse(10, -9, 7, 5);
  fill(255, 226, 196, 70);
  ellipse(0, -2, 18, 10);
  pop();
}

function bloom(x, y, r, petal, heart) {
  push();
  translate(x, y);
  rotate(random(TWO_PI));
  noStroke();
  const n = random() < 0.55 ? 5 : 6;
  for (let i = 0; i < n; i++) {
    rotate(TWO_PI / n);
    fill(petal);
    ellipse(r * 0.42, 0, r * 0.95, r * 0.52);
  }
  fill(heart);
  ellipse(0, 0, r * 0.34, r * 0.34);
  pop();
}

function flower(x, y, s) {
  const stem = 36 + s * 2.2;
  stroke(26, 38, 30, 160);
  strokeWeight(1.2);
  line(x, y, x + random(-7, 7), y + stem);
  noStroke();
  fill(30, 46, 34, 170);
  ellipse(x + 8, y + stem * 0.42, 13, 6);
  const petal = random() < 0.5 ? color(236, 198, 176, 215) : color(196, 96, 102, 205);
  bloom(x, y, s, petal, color(232, 176, 92, 225));
}

function meadow(back) {
  const count = back ? 9 : 15;
  for (let i = 0; i < count; i++) {
    let x = random(40, width - 40);
    let y = random(back ? 1480 : 1640, back ? 1700 : 1940);
    if (!back && x > 640 && x < 1000 && y < 1780) {
      x = x < 820 ? x - 220 : x + 220;
    }
    flower(x, y, random(7, back ? 13 : 19));
  }
}

function grasses(y0, y1, n, a) {
  for (let i = 0; i < n; i++) {
    const x = random(width);
    const y = random(y0, y1);
    stroke(16 + random(22), 26 + random(18), 18, a);
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + random(-11, 11), y - random(16, 62));
  }
}

function petals() {
  noStroke();
  for (let i = 0; i < 26; i++) {
    const x = random(60, 1540);
    const y = random(160, 1540);
    if (x > 650 && x < 1060 && y > 750 && y < 1160) continue;
    const c = random() < 0.5
      ? color(214, 122, 112, random(130, 200))
      : color(255, 222, 184, random(130, 210));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(c);
    ellipse(0, 0, random(5, 9), random(12, 22));
    pop();
  }
}

function motes() {
  noStroke();
  for (let i = 0; i < 64; i++) {
    fill(255, 214, 160, random(18, 86));
    ellipse(random(180, 1420), random(680, 1500), random(1.4, 3.2), random(1.4, 3.2));
  }
}

function groundFade() {
  noFill();
  for (let y = 1680; y < height; y++) {
    stroke(8, 4, 8, map(y, 1680, height, 0, 150));
    strokeWeight(1);
    line(0, y, width, y);
  }
}

function vignette() {
  noStroke();
  for (let i = 0; i < 280; i++) {
    const a = map(i, 0, 280, 40, 0);
    fill(4, 2, 8, a);
    rect(0, i, width, 1);
    rect(0, height - 1 - i, width, 1);
    rect(i, 0, 1, height);
    rect(width - 1 - i, 0, 1, height);
  }
}

function grain() {
  for (let i = 0; i < 34000; i++) {
    stroke(random(255), random(6, 16));
    point(random(width), random(height));
  }
  strokeWeight(1);
  for (let i = 0; i < 5000; i++) {
    const x = random(width);
    const y = random(height);
    stroke(48, 24, 20, random(4, 11));
    line(x, y, x + random(3, 8), y + random(-0.4, 0.4));
  }
}

