}

function sky() {
  noStroke();
  for (let y = 0; y < height; y += 5) {
    let t = y / height;
    let cool = constrain(1 - y / 820, 0, 1);
    let r = lerp(30, 62, Math.pow(t, 0.85)) - cool * 10;
    let g = lerp(15, 30, t) - cool * 2;
    let b = lerp(22, 32, t) + cool * 14;
    if (t > 0.7) {
      let u = (t - 0.7) / 0.3;
      r = lerp(r, 22, u);
      g = lerp(g, 12, u);
      b = lerp(b, 16, u);
    }
    fill(r, g, b);
    rect(0, y, width, 8);
  }
  for (let i = 0; i < 160; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0014, y * 0.0014);
    let cool = constrain(1 - y / 700, 0, 1) * constrain(1 - x / 900, 0, 1);
    fill(36 + n * 34 - cool * 8, 16 + n * 14, 20 + n * 18 + cool * 16, random(6, 15));
    ellipse(x, y, random(140, 420), random(70, 260));
  }
}

function lamp() {
  noStroke();
  for (let i = 16; i >= 1; i--) {
    fill(150, 78, 42, 3.2);
    ellipse(1088, 188, i * 86, i * 64);
  }
  for (let i = 8; i >= 1; i--) {
    fill(255, 196, 130, 5);
    ellipse(1096, 168, i * 26, i * 20);
  }
}

function beam() {
  noStroke();
  for (let i = 0; i < 180; i++) {
    let t = random();
    let y = lerp(120, 760, Math.pow(t, 0.85));
    let x = lerp(1100, 860, t) + (noise(i * 0.2, t * 3) - 0.5) * 70;
    fill(255, 186, 120, random(2, 7));
    ellipse(x, y, random(10, 46), random(24, 80));
  }
}

function halo() {
  noStroke();
  for (let i = 18; i >= 1; i--) {
    fill(156, 58, 40, 4.5);
    ellipse(800, 1080, 480 + i * 46, 640 + i * 50);
  }
  for (let i = 10; i >= 1; i--) {
    fill(196, 112, 64, 3.5);
    ellipse(800, 740, 220 + i * 28, 280 + i * 26);
  }
}

function surround() {
  noStroke();
  for (let a = 0; a < TWO_PI; a += 0.18) {
    let x = 810 + cos(a) * 610;
    let y = 1080 + sin(a) * 700;
    fill(12, 7, 14, 16);
    ellipse(x, y, 340, 400);
  }
}

function floorPlane() {
  noStroke();
  for (let i = 0; i < 700; i++) {
    let y = random(1560, 1990);
    let x = random(120, 1480);
    let t = constrain((y - 1560) / 420, 0, 1);
    let mid = constrain(1 - abs(x - 820) / 520, 0, 1);
    let r = lerp(54, 20, t) + mid * 28;
    let g = lerp(22, 10, t) + mid * 10;
    let b = lerp(24, 14, t);
    fill(r, g, b, lerp(28, 8, t));
    push();
    translate(x, y);
    rotate(random(-0.04, 0.04));
    ellipse(0, 0, random(70, 240), random(5, 14));
    pop();
  }
  fill(18, 8, 12, 36);
  ellipse(840, 1690, 820, 150);
}

function coreAlong(pts, widths, c, a, scale) {
  noStroke();
  for (let i = 0; i < pts.length - 1; i++) {
    for (let s = 0; s <= 8; s++) {
      let t = s / 8;
      let x = lerp(pts[i][0], pts[i + 1][0], t);
      let y = lerp(pts[i][1], pts[i + 1][1], t);
      let w = lerp(widths[i], widths[i + 1], t) * scale;
      fill(red(c), green(c), blue(c), a);
      ellipse(x, y, w, w * 0.9);
      fill(min(255, red(c) + 28), min(255, green(c) + 14), min(255, blue(c) + 8), a * 0.4);
      ellipse(x - w * 0.06, y - w * 0.05, w * 0.58, w * 0.5);
    }
  }
}

function shifted(pts, dx, dy) {
  let out = [];
  for (let i = 0; i < pts.length; i++) out.push([pts[i][0] + dx, pts[i][1] + dy]);
  return out;
}

