function paintStrokeMass(pts, widths, colorFn, layers, stamps) {
  for (let layer = 0; layer < layers; layer++) {
    for (let i = 0; i < pts.length - 1; i++) {
      let ax = pts[i][0];
      let ay = pts[i][1];
      let bx = pts[i + 1][0];
      let by = pts[i + 1][1];
      let ang = atan2(by - ay, bx - ax);
      let len = dist(ax, ay, bx, by);
      let steps = max(2, floor(len / 11));
      for (let s = 0; s <= steps; s++) {
        let t = s / steps;
        let w = lerp(widths[i], widths[i + 1], t);
        let breathe = (noise(ax * 0.003 + s, ay * 0.003, layer + i) - 0.5) * w * 0.1;
        let x = lerp(ax, bx, t) + cos(ang + HALF_PI) * breathe;
        let y = lerp(ay, by, t) + sin(ang + HALF_PI) * breathe;
        for (let k = 0; k < stamps; k++) {
          let g = constrain((random() + random() + random() - 1.5) / 1.5, -1, 1);
          let px = x + cos(ang + HALF_PI) * g * w * 0.48;
          let py = y + sin(ang + HALF_PI) * g * w * 0.48;
          let edge = abs(g);
          let ww = max(3, w * lerp(0.26, 0.09, edge) * random(0.7, 1.3));
          let hh = max(2, ww * random(0.45, 1.0));
          dab(px, py, ww, hh, colorFn(px, py, edge, layer), ang + random(-0.7, 0.7));
        }
      }
    }
  }
}

function fleshFn(side) {
  return function (x, y, edge, layer) {
    let n = noise(x * 0.007, y * 0.007, side * 2.0 + layer * 0.17);
    let inward = constrain(1 - abs(x - 810) / 250, 0, 1);
    let lift = constrain((1 - edge) * 0.4 + inward * 0.4 + n * 0.28, 0, 1);
    let a = layer === 0 ? random(28, 50) : random(15, 36);
    if (random() < 0.045) return color(34, 76, 72, a * 0.8);
    if (random() < 0.03) return color(255, 228, 196, a);
    if (side === 0) {
      return color(lerp(112, 244, lift), lerp(34, 150, lift), lerp(28, 112, lift), a);
    }
    return color(lerp(74, 208, lift), lerp(30, 112, lift), lerp(92, 178, lift), a);
  };
}

function clothFn(x, y, edge, layer) {
  let n = noise(x * 0.004, y * 0.0035);
  let t = constrain((x - 460) / 700 + (n - 0.5) * 0.18, 0, 1);
  let mid = 1 - abs(t - 0.48) * 2.1;
  mid = constrain(mid, 0, 1);
  let r = lerp(116, 78, t) + (1 - edge) * 36 + mid * 62;
  let g = lerp(40, 32, t) + (1 - edge) * 14 + mid * 30;
  let b = lerp(44, 72, t) + mid * 8;
  return color(r, g, b, random(16, 34));
}

