function paintHand(x, y, rot, side) {
  for (let i = 0; i < 140; i++) {
    let px = x + random(-30, 36);
    let py = y + random(-20, 20);
    dab(px, py, random(12, 30), random(9, 20), fleshFn(side)(px, py, random(0.15, 0.75), 1), rot + random(-0.3, 0.3));
  }
  dab(x - 2, y - 5, 28, 13, color(255, 214, 184, 40), rot);
}

function hairCol(side, t, x, y) {
  let n = noise(x * 0.02, y * 0.02);
  let a = random(20, 48);
  if (side === 0) {
    let r = lerp(96, 36, t) + n * 22;
    let g = lerp(38, 16, t);
    let b = lerp(30, 18, t);
    if (n > 0.74 && t < 0.45) {
      r = 186;
      g = 112;
      b = 68;
      a = 22;
    }
    return color(r, g, b, a);
  }
  let r = lerp(64, 26, t) + n * 14;
  let g = lerp(30, 14, t);
  let b = lerp(74, 36, t);
  if (n > 0.76 && t < 0.4) {
    r = 168;
    g = 124;
    b = 148;
    a = 20;
  }
  return color(r, g, b, a);
}

function hairBack() {
  hairMass(648, 652, 0);
