}

function hairMass(cx, cy, side) {
  for (let i = 0; i < 420; i++) {
    let a = random(TWO_PI);
    let rad = Math.sqrt(random());
    let px = cx + cos(a) * 128 * rad;
    let py = cy + sin(a) * 146 * rad;
    if (side === 0 && px > 760 && py > 640) continue;
    if (side === 1 && px < 840 && py > 660) continue;
    dab(px, py, random(18, 48), random(22, 54), hairCol(side, rad, px, py), a);
  }
}

