function headCore(cx, cy, c, rot, sc) {
  push();
  translate(cx, cy);
  rotate(rot);
  noStroke();
  fill(red(c), green(c), blue(c), 48);
  ellipse(0, 0, 228 * sc, 272 * sc);
  fill(min(255, red(c) + 36), min(255, green(c) + 20), min(255, blue(c) + 12), 32);
  ellipse(-16, -18, 120 * sc, 150 * sc);
  pop();
}

function headDabs(cx, cy, rx, ry, rot, side) {
  let otherx = side === 0 ? 894 : 706;
  for (let i = 0; i < 980; i++) {
    let a = random(TWO_PI);
    let rad = Math.sqrt(random());
    let ex = cos(a) * rx * rad;
    let ey = sin(a) * ry * rad;
    let px = cx + ex * cos(rot) - ey * sin(rot);
    let py = cy + ex * sin(rot) + ey * cos(rot);
    let faceIn = constrain(1 - dist(px, py, otherx, cy - 10) / 240, 0, 1);
    let upLight = constrain((cy - py) / ry, -1, 1) * 0.5 + 0.5;
    let n = noise(px * 0.012, py * 0.012);
    let lift = constrain((1 - rad) * 0.28 + faceIn * 0.48 + upLight * 0.22 + n * 0.16, 0, 1);
    let col;
    if (side === 0) {
      col = color(lerp(132, 255, lift), lerp(64, 196, lift), lerp(52, 154, lift), random(20, 46));
    } else {
      col = color(lerp(118, 242, lift), lerp(58, 166, lift), lerp(86, 176, lift), random(20, 46));
    }
    dab(px, py, random(16, 44), random(12, 36), col, rot + random(-0.5, 0.5));
  }
}

function hairFront() {
  strands(0);
  strands(1);
}

function strands(side) {
  let cx = side === 0 ? 706 : 894;
  let cy = side === 0 ? 698 : 730;
  for (let i = 0; i < 48; i++) {
    let outward = side === 0 ? -1 : 1;
    let x = cx + outward * random(16, 108) + random(-16, 12);
    let y = cy - random(30, 120);
    let len = floor(random(16, 34));
    for (let s = 0; s < len; s++) {
      let fall = s / len;
      let ang = HALF_PI + outward * lerp(0.85, 0.28, fall) + (noise(i * 0.31, s * 0.1) - 0.5) * 0.7;
      let ww = lerp(13, 3.5, fall) * random(0.75, 1.25);
      dab(x, y, ww * 1.3, ww * 2.3, hairCol(side, fall, x, y), ang);
      x += cos(ang) * random(5, 9);
      y += sin(ang) * random(7, 12);
      if (y > cy + 300) break;
    }
  }
}

