function ribbon(pts, weight, col, offset) {
  for (let i = 0; i < pts.length - 1; i++) {
    let steps = 10;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let x = lerp(pts[i][0], pts[i + 1][0], t);
      let y = lerp(pts[i][1], pts[i + 1][1], t);
      let ang = atan2(pts[i + 1][1] - pts[i][1], pts[i + 1][0] - pts[i][0]);
      let px = x + cos(ang + HALF_PI) * offset;
      let py = y + sin(ang + HALF_PI) * offset;
      dab(px, py, weight * random(0.8, 1.6), weight * random(0.35, 0.7), col, ang);
    }
  }
}

