function nightWash() {
  for (let y = 0; y < height; y++) {
    const t = y / height;
    const n = noise(y * 0.003, 1.7);
    const r = lerp(14, 38, t) + n * 12;
    const g = lerp(8, 16, t) + n * 5;
    const b = lerp(32, 26, t) + (1 - n) * 10;
    stroke(r, g, b);
    strokeWeight(1);
    line(0, y, width, y);
  }
  noStroke();
  for (let i = 0; i < 8; i++) {
    fill(6, 4, 16, 28);
    ellipse(-80, 1000, 620, 2400);
    ellipse(1680, 1000, 620, 2400);
  }
}

