function bodyRadius(t) {
  if (t > 0.84) return lerp(64, 30, (t - 0.84) / 0.16);
  if (t > 0.5) return lerp(118, 64, (t - 0.5) / 0.34);
  return lerp(78, 124, t / 0.5);
}

function figureColor(x, y, side, shadow, mid, light) {
  const toward = constrain(1 - abs(x - 812) / 230, 0, 1);
  const high = constrain((1500 - y) / 820, 0, 1);
  let k = constrain(toward * 0.72 + high * 0.32 + (1 - abs(side)) * 0.08, 0, 1);
  if (abs(x - 812) > 200) {
    shadow = [shadow[0] * 0.85, shadow[1] * 0.9, shadow[2] + 16];
  }
  let c;
  if (k < 0.5) c = mix(shadow, mid, k / 0.5);
  else c = mix(mid, light, (k - 0.5) / 0.5);
  const a = 210 * (1 - Math.pow(abs(side), 1.45) * 0.62);
  return [c[0], c[1], c[2], a];
}

function head(cx, cy, rx, ry, tilt, shadow, mid, light) {
  noStroke();
  fill(light[0], light[1], light[2], 22);
  ellipse(cx, cy, rx * 2.8, ry * 3);
  for (let i = 0; i < 220; i++) {
    const a = random(TWO_PI);
    const u = Math.pow(random(), 0.5);
    let lx = cos(a) * rx * u;
    let ly = sin(a) * ry * u;
    const x = cx + lx * cos(tilt) - ly * sin(tilt);
    const y = cy + lx * sin(tilt) + ly * cos(tilt);
    const col = litColor(x, y, shadow, mid, light);
    dab(x, y, rx * random(0.32, 0.62), ry * random(0.2, 0.4), random(TWO_PI), col[0], col[1], col[2], 200 * (1 - u * 0.25));
  }
}

function litColor(x, y, shadow, mid, light) {
  const toward = constrain(1 - abs(x - 812) / 210, 0, 1);
  const k = constrain(toward * 0.85 + 0.2, 0, 1);
  if (k < 0.5) return mix(shadow, mid, k / 0.5);
  return mix(mid, light, (k - 0.5) / 0.5);
}

function ribbon(pts, steps, radiusAt, colorAt) {
  const samples = sampleCurve(pts, steps);
  let ang = -HALF_PI;
  for (let i = 1; i < samples.length; i++) {
    const x = samples[i][0];
    const y = samples[i][1];
    const dx = x - samples[i - 1][0];
    const dy = y - samples[i - 1][1];
    if (abs(dx) + abs(dy) > 0.001) ang = atan2(dy, dx);
    const t = i / (samples.length - 1);
    const rad = radiusAt(t);
    const nx = -sin(ang);
    const ny = cos(ang);
    const bands = 9;
    for (let k = 0; k < bands; k++) {
      const side = (k / (bands - 1)) * 2 - 1;
      const spread = rad * 0.52;
      const jx = (noise(i * 0.08, k * 0.17) - 0.5) * rad * 0.2;
      const jy = (noise(k * 0.11, i * 0.06) - 0.5) * 8;
      const px = x + nx * side * spread + jx;
      const py = y + ny * side * spread * 0.72 + jy;
      const col = colorAt(px, py, side);
      const w = rad * (0.42 + noise(i * 0.3, k) * 0.45);
      const h = max(6, rad * (0.16 + noise(k, i * 0.25) * 0.14));
      dab(px, py, w, h, ang + (noise(i * 0.2, k * 0.4) - 0.5) * 0.9, col[0], col[1], col[2], col[3]);
    }
  }
}

function sampleCurve(pts, steps) {
  const p = [pts[0].slice()];
  for (let i = 0; i < pts.length; i++) p.push(pts[i].slice());
  p.push(pts[pts.length - 1].slice());
  const out = [];
  for (let i = 1; i < p.length - 2; i++) {
    const p0 = p[i - 1];
    const p1 = p[i];
    const p2 = p[i + 1];
    const p3 = p[i + 2];
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const t2 = t * t;
      const t3 = t2 * t;
      const x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      const y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      out.push([x, y]);
    }
  }
  return out;
}

function dab(x, y, w, h, rot, r, g, b, a) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(r, g, b, a);
  ellipse(0, 0, w, h);
  pop();
}

function mix(a, b, t) {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  ];
}

