function skyAt(y) {
  const stops = [
    { y: 0, c: [16, 10, 36] },
    { y: 220, c: [36, 18, 64] },
    { y: 480, c: [78, 32, 86] },
    { y: 720, c: [150, 52, 88] },
    { y: 960, c: [204, 86, 78] },
    { y: 1140, c: [240, 140, 90] },
    { y: 1288, c: [255, 216, 164] },
    { y: 1420, c: [232, 148, 88] },
    { y: 1560, c: [138, 70, 50] },
    { y: 1720, c: [70, 34, 32] },
    { y: 1880, c: [34, 18, 20] },
    { y: 2000, c: [16, 9, 12] }
  ];
  for (let i = 0; i < stops.length - 1; i++) {
    if (y <= stops[i + 1].y) {
      let t = (y - stops[i].y) / (stops[i + 1].y - stops[i].y);
      t = t * t * (3 - 2 * t);
      return [
        lerp(stops[i].c[0], stops[i + 1].c[0], t),
        lerp(stops[i].c[1], stops[i + 1].c[1], t),
        lerp(stops[i].c[2], stops[i + 1].c[2], t)
      ];
    }
  }
  return stops[stops.length - 1].c;
}

function paintSky() {
  for (let y = 0; y < height; y++) {
    const c = skyAt(y);
    const n = noise(y * 0.012, 0.4) - 0.5;
