function cypress(x, baseY, h) {
  noStroke();
  fill(30, 14, 28, 120);
  beginShape();
  vertex(x, baseY);
  vertex(x + h * 0.09, baseY - h * 0.34);
  vertex(x + h * 0.02, baseY - h * 0.55);
  vertex(x + h * 0.11, baseY - h * 0.78);
  vertex(x, baseY - h);
  vertex(x - h * 0.13, baseY - h * 0.7);
  vertex(x - h * 0.04, baseY - h * 0.46);
  vertex(x - h * 0.11, baseY - h * 0.2);
  endShape(CLOSE);
}

