function meadow(y0, y1, count) {
  for (let i = 0; i < count; i++) {
    const x = random(width);
    const y = random(y0, y1);
    const t = constrain((y - 1320) / 680, 0, 1);
    const n = noise(x * 0.004, y * 0.004);
    let r = lerp(150, 32, t) + (n - 0.5) * 30;
    let g = lerp(86, 24, t) + (n - 0.5) * 16;
    let b = lerp(48, 22, t);
    if (random() < 0.07) {
      r = 196;
      g = 132;
      b = 64;
    } else if (random() < 0.04) {
      r = 150;
      g = 62;
      b = 58;
    }
    stroke(r, g, b, random(30, 100));
    strokeWeight(random(0.4, 1.5));
    const h = random(5, 20) * (0.45 + t);
    line(x, y, x + random(-2.2, 1.2), y - h);
  }
}

