function cardinal(p0, p1, p2, p3, t, tension) {
  const s = (1 - tension) * 0.5;
  const t2 = t * t;
  const t3 = t2 * t;
  const h00 = 2 * t3 - 3 * t2 + 1;
  const h10 = t3 - 2 * t2 + t;
  const h01 = -2 * t3 + 3 * t2;
  const h11 = t3 - t2;
  const m0x = s * (p2[0] - p0[0]);
  const m0y = s * (p2[1] - p0[1]);
  const m1x = s * (p3[0] - p1[0]);
  const m1y = s * (p3[1] - p1[1]);
  return [
    h00 * p1[0] + h10 * m0x + h01 * p2[0] + h11 * m1x,
    h00 * p1[1] + h10 * m0y + h01 * p2[1] + h11 * m1y
  ];
}

function smoothClosed(pts, segs) {
  const out = [];
  const n = pts.length;
  const tension = 0.42;
  for (let i = 0; i < n; i++) {
    const p0 = pts[(i - 1 + n) % n];
    const p1 = pts[i];
    const p2 = pts[(i + 1) % n];
    const p3 = pts[(i + 2) % n];
    for (let s = 0; s < segs; s++) {
      out.push(cardinal(p0, p1, p2, p3, s / segs, tension));
    }
  }
  return out;
}

function poly(pts) {
  beginShape();
  for (let i = 0; i < pts.length; i++) vertex(pts[i][0], pts[i][1]);
  endShape(CLOSE);
}

function drawBody(pts, base) {
  const s = smoothClosed(pts, 8);

  noFill();
  strokeJoin(ROUND);
  stroke(255, 196, 140, 22);
  strokeWeight(14);
  poly(s);
  stroke(255, 214, 176, 40);
  strokeWeight(4);
  poly(s);

  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.moveTo(s[0][0], s[0][1]);
  for (let i = 1; i < s.length; i++) drawingContext.lineTo(s[i][0], s[i][1]);
  drawingContext.closePath();
  drawingContext.clip();

  noStroke();
  fill(base[0], base[1], base[2]);
  rect(0, 0, width, height);

  for (let i = 0; i < 14; i++) {
    fill(92, 32, 28, 6);
    ellipse(LIGHT_X, 1240, 160 + i * 18, 620);
  }

  for (let i = 0; i < 120; i++) {
    stroke(base[0] + 28, base[1] + 10, base[2] + 8, random(10, 28));
    strokeWeight(random(0.6, 2));
    const x = random(380, 1220);
    const y = random(980, 1880);
    line(x, y, x + random(-7, 7), y + random(10, 32));
  }
  drawingContext.restore();

  fretEdge(s);
}

function fretEdge(s) {
  for (let i = 0; i < s.length; i += 3) {
    const p = s[i];
    const q = s[(i + 1) % s.length];
    const ang = atan2(q[1] - p[1], q[0] - p[0]);
    stroke(18, 8, 10, random(30, 70));
    strokeWeight(random(0.6, 1.8));
    const len = random(4, 12);
    line(p[0], p[1], p[0] + cos(ang) * len, p[1] + sin(ang) * len);
    if (p[1] < 1400 && random() < 0.45) {
      stroke(255, 206, 150, random(12, 32));
      strokeWeight(random(0.5, 1.6));
      line(p[0], p[1], p[0] + cos(ang + HALF_PI) * random(2, 7), p[1] + sin(ang + HALF_PI) * random(2, 7));
    }
  }
}

