function taperedCurve(p0, p1, p2, w0, w1, col, a) {
  noStroke();
  fill(red(col), green(col), blue(col), a);
  const steps = 42;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const u = 1 - t;
    const x = u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0];
    const y = u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1];
    const w = lerp(w0, w1, t);
    ellipse(x, y, w, w * 0.8);
  }
}

