function smoothstep(t) {
  return t * t * (3 - 2 * t);
}

function pathPoint(t, side) {
  let tt = constrain(t, 0, 1);
  let y = lerp(320, 1580, smoothstep(tt) * 0.82 + tt * 0.18);
  y += (side === 0 ? -1 : 1) * 14 * sin(tt * PI);
  let fade = pow(1 - tt, 1.6);
  let base = (side === 0 ? -420 : 420) * fade;
  let env = sin(tt * PI);
  let amp = 300 * pow(env, 0.65) + 12;
  let phase = side === 0 ? -0.35 : PI - 0.35;
  let theta = tt * TWO_PI * 1.25 + phase;
  let n = (noise(tt * 1.15, side * 4.0 + 1.7) - 0.5) * 26;
  let x = 800 + base + sin(theta) * amp + n;
  return { x: x, y: y };
}

function ribbonWidth(t) {
  let mid = sin(constrain(t, 0, 1) * PI);
  return 70 + mid * 52 + noise(t * 2.4, 6.5) * 16;
}

function dab(x, y, len, ang, thick, h, s, b, a) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill((h % 360 + 360) % 360, s, b, a);
  ellipse(0, 0, len, thick);
  pop();
}

function softDisc(x, y, r, h, s, b, aMax) {
  noStroke();
  let layers = 16;
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    fill((h % 360 + 360) % 360, s * lerp(0.22, 1, t), min(100, b + (1 - t) * 8), aMax * pow(1 - t, 1.2));
    ellipse(x, y, r * 2 * t, r * 2 * t * 0.94);
  }
}

function paintSky() {
  for (let y = 0; y < height; y += 2) {
    let ny = y / height;
    let n = noise(0.35, y * 0.0017);
    let h = lerp(226, 252, ny) + n * 8;
    let s = lerp(46, 30, ny);
    let b = lerp(6, 13, ny) + n * 3.2;
    if (ny > 0.58) {
      let k = pow((ny - 0.58) / 0.42, 1.15);
      h = lerp(h, 18, k * 0.62);
      s = lerp(s, 38, k * 0.7);
      b = lerp(b, 18, k);
    }
    stroke(h, s, b, 100);
    strokeWeight(3);
    line(0, y, width, y);
  }
}

