function paintWeave() {
  let segments = 8;
  for (let s = 0; s < segments; s++) {
    let t0 = s / segments;
    let t1 = (s + 1) / segments + 0.014;
    if (s % 2 === 0) {
      paintRibbon(0, t0, t1);
      paintRibbon(1, t0, t1);
    } else {
      paintRibbon(1, t0, t1);
      paintRibbon(0, t0, t1);
    }
  }
}

function paintRibbon(side, t0, t1) {
  let steps = 56;
  for (let i = 0; i <= steps; i++) {
    let t = lerp(t0, min(t1, 1), i / steps);
    let p = pathPoint(t, side);
    let q = pathPoint(min(t + 0.007, 1), side);
    let ang = atan2(q.y - p.y, q.x - p.x);
    let w = ribbonWidth(t);
    let bands = 12;
    for (let k = 0; k < bands; k++) {
      let u = (k / (bands - 1)) * 2 - 1;
      let ox = cos(ang + HALF_PI) * u * w * 0.5;
      let oy = sin(ang + HALF_PI) * u * w * 0.5;
      let edge = abs(u);
      let flick = (noise(t * 4.6, k * 0.65 + side * 2.8) - 0.5) * 6;
      let h, s, b;
      if (side === 0) {
        h = lerp(4, 14, edge) + flick;
        s = lerp(34, 62, edge);
        b = lerp(100, 38, pow(edge, 1.12));
      } else {
        h = lerp(42, 26, edge) + flick * 0.5;
        s = lerp(30, 64, edge);
        b = lerp(100, 36, pow(edge, 1.12));
      }
      let a = lerp(16, 3.5, edge);
      let len = lerp(36, 13, edge) * random(0.85, 1.15);
      let thick = lerp(12, 4.5, edge);
      let jitter = (noise(t * 8, k + side) - 0.5) * 0.5;
      dab(p.x + ox, p.y + oy, len, ang + jitter, thick, h, s, b, a);
      if (edge > 0.84) {
        dab(p.x + ox, p.y + oy, len * 0.75, ang, thick * 0.65, side === 0 ? 2 : 18, 50, 24, 6);
      }
      if (edge < 0.14) {
        dab(p.x + ox, p.y + oy, len * 0.45, ang, thick * 0.45, 44, 14, 100, 7);
      }
    }
    if (random() < 0.4) {
      let u = random(-0.28, 0.28);
      let ox = cos(ang + HALF_PI) * u * w * 0.5;
      let oy = sin(ang + HALF_PI) * u * w * 0.5;
      dab(p.x + ox, p.y + oy, random(7, 15), ang, random(2.5, 5.5), 46, 10, 100, 15);
    }
  }
}

function paintUnion() {
  for (let i = 0; i <= 100; i++) {
    let uT = i / 100;
    let t = lerp(0.78, 1, uT);
    let a = pathPoint(t, 0);
    let b = pathPoint(t, 1);
    let x = (a.x + b.x) / 2;
    let y = (a.y + b.y) / 2;
    let w = lerp(28, 96, smoothstep(uT));
    for (let k = 0; k < 10; k++) {
      let u = (k / 9) * 2 - 1;
      let edge = abs(u);
      let h = k % 2 === 0 ? 8 : 40;
      if (edge < 0.35) h = 36;
      dab(x + u * w * 0.5, y, lerp(30, 12, edge), HALF_PI, lerp(11, 4.5, edge), h, lerp(16, 36, edge), lerp(100, 68, edge), lerp(11, 3, edge));
    }
  }
  let a = pathPoint(1, 0);
  let b = pathPoint(1, 1);
  let x = (a.x + b.x) / 2;
  let y = (a.y + b.y) / 2;
  for (let i = 0; i <= 56; i++) {
    let yy = y + i * 5.4;
    let w = lerp(96, 230, i / 56);
    let fade = pow(1 - i / 56, 0.85);
    for (let k = 0; k < 11; k++) {
      let u = (k / 10) * 2 - 1;
      let h = k % 2 === 0 ? 12 : 38;
      dab(x + u * w * 0.46, yy, 24, HALF_PI + (noise(i, k) - 0.5) * 0.3, 9, h, 20, 96, 7.5 * fade * (1 - abs(u) * 0.75));
    }
  }
  softDisc(x, y + 30, 160, 34, 26, 100, 6.5);
  softDisc(x, y + 110, 240, 22, 24, 92, 3.6);
  softDisc(x, y + 200, 300, 14, 20, 70, 2.4);
}

function paintOrbs() {
  for (let side = 0; side <= 1; side++) {
    let p = pathPoint(0, side);
    let h = side === 0 ? 6 : 40;
    softDisc(p.x, p.y - 16, 168, h, 32, 62, 5.5);
    softDisc(p.x, p.y - 8, 78, h, 24, 100, 7.5);
    softDisc(p.x, p.y, 24, 46, 8, 100, 13);
    softDisc(p.x + (side === 0 ? 20 : -20), p.y + 4, 14, side === 0 ? 40 : 6, 28, 100, 7);
  }
}

function paintMeeting() {
  for (let i = 0; i <= 180; i++) {
    let t = i / 180;
    let a = pathPoint(t, 0);
    let b = pathPoint(t, 1);
    let d = dist(a.x, a.y, b.x, b.y);
    if (d < 130) {
      let m = pow((130 - d) / 130, 1.35);
      let x = (a.x + b.x) / 2;
      let y = (a.y + b.y) / 2;
      noStroke();
      fill(44, 16, 100, 7 * m);
      ellipse(x, y, 8 + m * 20, 8 + m * 20);
      fill(8, 20, 100, 4 * m);
      ellipse(x, y, 18 + m * 28, 14 + m * 18);
    }
  }
}

function bloom(x, y, s, h) {
  push();
  translate(x, y);
  rotate(random(TWO_PI));
  noStroke();
  for (let i = 0; i < 5; i++) {
    rotate(TWO_PI / 5);
    fill(h, 40, 95, 18);
    ellipse(s * 0.36, 0, s * 0.82, s * 0.5);
    fill(h, 22, 100, 10);
    ellipse(s * 0.34, 0, s * 0.36, s * 0.22);
  }
  fill(42, 24, 100, 36);
  ellipse(0, 0, s * 0.34, s * 0.34);
  pop();
}

function paintBlooms() {
  bloom(640, 1696, 30, 6);
  bloom(735, 1772, 40, 38);
  bloom(868, 1804, 34, 10);
  bloom(968, 1744, 28, 42);
  bloom(1068, 1678, 24, 8);
  bloom(578, 1624, 20, 36);
  bloom(800, 1888, 26, 28);
}

function paintPetals() {
  for (let i = 0; i < 100; i++) {
    let t = random(0.02, 0.98);
    let side = random() < 0.5 ? 0 : 1;
    let p = pathPoint(t, side);
    let ang = random(TWO_PI);
    let rad = random(100, 340);
    let x = p.x + cos(ang) * rad;
    let y = p.y + sin(ang) * rad * 0.5;
    if (x < 36 || x > width - 36 || y < 36 || y > height - 36) continue;
    let h = side === 0 ? random(2, 16) : random(28, 46);
    dab(x, y, random(8, 18), ang + random(-0.4, 0.4), random(3.5, 7.5), h, random(28, 52), random(72, 100), random(9, 20));
  }
}

function paintMotes() {
  noStroke();
  for (let i = 0; i < 320; i++) {
    let t = random();
    let side = random() < 0.5 ? 0 : 1;
    let p = pathPoint(t, side);
    let x = p.x + random(-48, 48);
    let y = p.y + random(-36, 36);
    fill(48, 12, 100, random(10, 36));
    ellipse(x, y, random(1.4, 3.4), random(1.4, 3.4));
  }
}

function paintVignette() {
  noStroke();
  for (let i = 0; i < 150; i++) {
    let a = map(i, 0, 150, 18, 0);
    fill(228, 42, 3, a * 0.2);
    rect(0, i * 1.15, width, 3);
    rect(0, height - i * 1.7, width, 4);
    rect(i * 1.35, 0, 3.2, height);
    rect(width - i * 1.35, 0, 3.2, height);
  }
}

const CX = 800;
const CY = 950;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  strokeCap(ROUND);
  noLoop();
}

function draw() {
  drawBackdrop();
  blendMode(ADD);
  drawAmbientWashes();
  drawDust();
  drawSpiralArm(2.04, color(175, 42, 115), color(255, 212, 185), 11.0, 1);
  drawSpiralArm(1.08, color(165, 25, 55), color(255, 207, 125), 27.0, -1);
  drawHeartConstellation();
  drawCentralCore();
  blendMode(BLEND);
  drawVignette();
}

function drawBackdrop() {
  blendMode(BLEND);
  background(8, 4, 14);
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(CX, CY, 100, CX, CY, 1600);
  g.addColorStop(0, '#2c1324');
  g.addColorStop(0.55, '#160a1a');
  g.addColorStop(1, '#08040d');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawGlowCircle(x, y, radius, rc, gc, bc, maxAlpha, step) {
  noStroke();
  for (let rr = radius; rr > 0; rr -= step) {
    let a = map(rr, radius, 0, 0, maxAlpha);
    fill(rc, gc, bc, a);
    ellipse(x, y, rr * 2, rr * 2);
  }
}

function drawAmbientWashes() {
  drawGlowCircle(250, 1640, 350, 255, 80, 125, 2.6, 24);
  drawGlowCircle(1350, 1640, 350, 255, 175, 85, 2.6, 24);
  drawGlowCircle(CX, CY, 780, 215, 80, 155, 2.2, 32);
}

function drawDust() {
  noStroke();
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);
    let d = random(0.6, 2.6);
    let a = random(8, 58);
    if (random(1) < 0.62) {
      fill(255, 225, 210, a);
    } else {
      fill(195, 175, 255, a);
    }
    ellipse(x, y, d, d);
  }
}

function drawHeartConstellation() {
  noStroke();
  let sc = 21.5;
  let offY = -110;
  for (let i = 0; i < 1400; i++) {
    let t = random(-PI, PI);
    let hx = 16 * pow(sin(t), 3);
    let hy = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
    let jx = (noise(i * 0.12 + 10) - 0.5) * 18;
    let jy = (noise(i * 0.12 + 90) - 0.5) * 18;
    let x = CX + (hx + jx) * sc;
    let y = CY + offY + (hy + jy) * sc;
    let d = random(0.8, 3.2);
    let a = random(16, 62);
    fill(255, 200, 212, a);
    ellipse(x, y, d, d);
  }
}

function drawSpiralArm(startAngle, colOuter, colInner, seedOff, dir) {
  noStroke();
  const strands = 9;
  const steps = 1200;
  const turns = 3.1;
  for (let s = 0; s < strands; s++) {
    let phase = startAngle + (s - strands / 2) * 0.012;
    let yScale = 0.72 + (s % 4) * 0.006;
    for (let i = 0; i < steps; i++) {
      let t = i / (steps - 1);
      let r = 45 + 1060 * pow(1 - t, 1.45);
      let theta = phase + dir * t * turns * TWO_PI;
      let x = CX + r * cos(theta);
      let y = CY + r * sin(theta) * yScale;

      let jitterAmp = 85 * sin(t * PI);
      let nx = (noise(i * 0.006 + seedOff, s * 0.35) - 0.5) * jitterAmp;
      let ny = (noise(i * 0.006 + seedOff + 61, s * 0.35) - 0.5) * jitterAmp;
      x += nx;
      y += ny;

      let c = lerpColor(colOuter, colInner, pow(t, 0.65));
      let wid = 2.0 + 11.0 * (1 - t) * (0.7 + 0.5 * noise(i * 0.03 + s + seedOff));
      let a = 16 + 100 * pow(t, 0.85) * (0.75 + 0.25 * noise(i * 0.02 + s + seedOff));

      fill(red(c), green(c), blue(c), a);
      ellipse(x, y, wid, wid);
    }
  }
}

function drawCentralCore() {
  noStroke();
  drawGlowCircle(CX, CY, 430, 255, 95, 145, 4.5, 22);
  drawGlowCircle(CX, CY, 185, 255, 210, 170, 28, 8);
  drawGlowCircle(CX, CY, 72, 255, 250, 245, 85, 4);

  for (let i = 0; i < 240; i++) {
    let ang = random(TWO_PI);
    let rad = random(35, 215);
    let x = CX + cos(ang) * rad;
    let y = CY + sin(ang) * rad * 0.85;
    let d = random(2, 7);
    let a = random(20, 85);
    fill(255, 226, 210, a);
    ellipse(x, y, d, d);
  }
}

function drawVignette() {
  blendMode(BLEND);
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(CX, CY, 250, CX, CY, 1550);
  g.addColorStop(0, 'rgba(8,4,14,0)');
  g.addColorStop(0.7, 'rgba(8,4,14,0)');
  g.addColorStop(1, 'rgba(8,4,14,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  colorMode(RGB, 255);
}

function draw() {
  drawBackgroundGradient();

  // Filled heart base
  drawHeartFill(800, 1050, 30, color(70, 10, 30, 120));

  // Layered heart outlines
  drawHeartLayers(800, 1050, 30, 22);

  // Additive glow and light
  blendMode(ADD);
  drawBackgroundGlows();
  drawSouls();
  drawRibbons();
  drawParticles();
  blendMode(BLEND);

  drawGrain();
}

function drawBackgroundGradient() {
  noStroke();
  let c1 = color(8, 5, 18);
  let c2 = color(28, 12, 40);
  let c3 = color(10, 7, 18);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = t < 0.5 ? lerpColor(c1, c2, t * 2) : lerpColor(c2, c3, (t - 0.5) * 2);
    fill(c);
    rect(0, y, width, 1);
  }
}

function drawGlow(x, y, radius, col, maxAlpha) {
  noStroke();
  for (let r = radius; r > 0; r -= 8) {
    let a = maxAlpha * pow(r / radius, 2);
    fill(red(col), green(col), blue(col), a);
    ellipse(x, y, r * 2, r * 2);
  }
}

function heartPoint(t, cx, cy, s) {
  let x = 16 * pow(sin(t), 3);
  let y = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
  return { x: cx + x * s, y: cy + y * s };
}

function heartColor(t) {
  let cTop = color(255, 220, 210);
  let cRightLobe = color(255, 130, 100);
  let cBottom = color(220, 40, 100);
  let cLeftLobe = color(210, 80, 190);

  if (t < PI) {
    let a = t / PI;
    if (a < 0.5) return lerpColor(cTop, cRightLobe, a * 2);
    else return lerpColor(cRightLobe, cBottom, (a - 0.5) * 2);
  } else {
    let a = (t - PI) / PI;
    if (a < 0.5) return lerpColor(cBottom, cLeftLobe, a * 2);
    else return lerpColor(cLeftLobe, cTop, (a - 0.5) * 2);
  }
}

function drawHeartFill(cx, cy, s, col) {
  noStroke();
  fill(red(col), green(col), blue(col), alpha(col));
  beginShape();
  for (let t = 0; t <= TWO_PI; t += 0.02) {
    let p = heartPoint(t, cx, cy, s);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);
}

function drawHeartLayers(cx, cy, s, layers) {
  noFill();
  for (let l = 0; l < layers; l++) {
    let mult = 1 + l * 0.025;
    let sw = map(l, 0, layers - 1, 20, 1);
    let alpha = map(l, 0, layers - 1, 220, 25);
    strokeWeight(sw);
    for (let t = 0; t <= TWO_PI; t += 0.015) {
      let p1 = heartPoint(t, cx, cy, s * mult);
      let p2 = heartPoint(t + 0.015, cx, cy, s * mult);
      let col = heartColor(t);
      stroke(red(col), green(col), blue(col), alpha);
      line(p1.x, p1.y, p2.x, p2.y);
    }
  }
}

function drawBackgroundGlows() {
  drawGlow(800, 1050, 700, color(120, 30, 80), 20);
  drawGlow(650, 950, 260, color(255, 100, 110), 40);
  drawGlow(950, 950, 260, color(220, 80, 180), 40);
  drawGlow(800, 1300, 220, color(255, 180, 140), 50);
  drawGlow(520, 500, 300, color(255, 100, 70), 30);
  drawGlow(1080, 500, 300, color(200, 70, 180), 30);
}

function drawSouls() {
  // trails
  for (let i = 0; i < 50; i++) {
    let off = (noise(i * 0.08, 3) - 0.5) * 120;
    let alpha = map(i, 0, 50, 160, 15);
    strokeWeight(2);
    noFill();
    stroke(255, 160, 120, alpha);
    bezier(520 + off, 500 + off * 0.3, 480 + off * 2, 700 + off, 400 + off * 1.5, 920 + off, 350 + off, 950 + off * 0.5);
    stroke(210, 100, 190, alpha);
    bezier(1080 - off, 500 - off * 0.3, 1120 - off * 2, 700 - off, 1200 - off * 1.5, 920 - off, 1250 - off, 950 - off * 0.5);
  }

  // orb glows
  drawGlow(520, 500, 220, color(255, 140, 80), 60);
  drawGlow(1080, 500, 220, color(220, 80, 200), 60);

  // core orbs
  for (let r = 80; r > 0; r -= 5) {
    fill(255, 200, 170, 35);
    ellipse(520, 500, r * 2, r * 2);
    fill(230, 150, 220, 35);
    ellipse(1080, 500, r * 2, r * 2);
  }
}

function drawRibbons() {
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    let off = (noise(i * 0.06, 0) - 0.5) * 120;
    let off2 = (noise(i * 0.06, 1) - 0.5) * 120;
    let alpha = map(i, 0, 60, 180, 20);
    strokeWeight(map(i, 0, 60, 12, 1));
    noFill();

    let colL = lerpColor(color(255, 120, 100), color(255, 220, 160), t);
    let colR = lerpColor(color(220, 80, 200), color(255, 220, 160), t);

    stroke(red(colL), green(colL), blue(colL), alpha);
    bezier(800 + off, 1560 + off * 0.3, 580 + off * 1.2, 1450 + off * 0.8, 390 + off * 1.6, 1150 + off * 0.6, 360 + off, 920 + off * 0.4);

    stroke(red(colR), green(colR), blue(colR), alpha);
    bezier(800 - off2, 1560 - off2 * 0.3, 1020 - off2 * 1.2, 1450 - off2 * 0.8, 1210 - off2 * 1.6, 1150 - off2 * 0.6, 1240 - off2, 920 - off2 * 0.4);
  }
}

function drawParticles() {
  for (let i = 0; i < 1000; i++) {
    let x = random(width);
    let y = random(height);
    if (dist(x, y, 800, 1050) < 750) {
      let a = random(10, 70);
      let r = random(2, 8);
      let col = random([color(255, 160, 120), color(255, 90, 120), color(255, 220, 180), color(200, 90, 200)]);
      fill(red(col), green(col), blue(col), a);
      noStroke();
      ellipse(x, y, r, r);
    }
  }
}

function drawGrain() {
  strokeWeight(1);
  for (let i = 0; i < 3000; i++) {
    stroke(255, random(8, 25));
    point(random(width), random(height));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 1);
}

function draw() {
  drawPainting();
  noLoop();
}

const CX = 800;
const CY = 1000;
const S = 45;

function heartCanvas(t, cx, cy, s) {
  let x = 16 * Math.pow(Math.sin(t), 3);
  let y = 13 * Math.cos(t) - 5 * Math.cos(2*t) - 2 * Math.cos(3*t) - Math.cos(4*t);
  return {x: cx + x * s, y: cy - y * s};
}

function heartNormalCanvas(t) {
  let dx = 48 * Math.pow(Math.sin(t), 2) * Math.cos(t);
  let dy = -13 * Math.sin(t) + 10 * Math.sin(2*t) + 6 * Math.sin(3*t) + 4 * Math.sin(4*t);
  let len = Math.hypot(dx, dy);
  if (len < 0.0001) return {x: 0, y: -1};
  return {x: dy / len, y: dx / len};
}

function traceHeartPath(scale = 1) {
  beginShape();
  for (let i = 0; i <= 260; i++) {
    let theta = map(i, 0, 260, 0.01, TAU - 0.02);
    let p = heartCanvas(theta, CX, CY, S * scale);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);
}

function computeHeartPoint(theta, phase, offsetAmp) {
  let p = heartCanvas(theta, CX, CY, S);
  let n = heartNormalCanvas(theta);
  let nz = noise(theta * 3.1 + phase * 0.7);
  let warp = Math.sin(theta * 4 + phase) * (0.65 + 0.6 * nz);
  let off = offsetAmp * warp;
  return {x: p.x + n.x * off, y: p.y + n.y * off};
}

function drawBackground() {
  let ctx = drawingContext;
  ctx.globalCompositeOperation = 'source-over';
  let grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, '#170712');
  grad.addColorStop(0.55, '#0b0308');
  grad.addColorStop(1, '#200a10');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
}

function drawBackgroundWashes() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 14; i++) {
    let x = CX + random(-480, 480);
    let y = CY + random(-700, 700);
    let r = random(160, 460);
    let c = color(255, 80, 100);
    if (i % 3 === 0) c = color(255, 150, 90);
    else if (i % 3 === 1) c = color(180, 60, 110);
    c.setAlpha(random(0.018, 0.05));
    fill(c);
    ellipse(x, y, r * 2, r * 1.6);
  }
  pop();
}

function drawCentralGlow() {
  push();
  blendMode(ADD);
  noStroke();
  for (let r = 520; r > 0; r -= 22) {
    let a = map(r, 0, 520, 0.12, 0);
    fill(255, 100, 90, a);
    ellipse(CX, CY, r * 2, r * 1.9);
  }
  for (let r = 240; r > 0; r -= 12) {
    let a = map(r, 0, 240, 0.32, 0);
    fill(255, 210, 140, a);
    ellipse(CX, CY, r * 2, r * 1.8);
  }
  pop();
}

function drawLightRays() {
  push();
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 36; i++) {
    let angle = random(0, TAU);
    let r1 = random(180, 500);
    let r2 = r1 + random(250, 650);
    let x1 = CX + Math.cos(angle) * r1;
    let y1 = CY + Math.sin(angle) * r1;
    let x2 = CX + Math.cos(angle) * r2;
    let y2 = CY + Math.sin(angle) * r2;
    stroke(255, 140, 110, random(0.02, 0.06));
    strokeWeight(random(20, 50));
    line(x1, y1, x2, y2);
  }
  pop();
}

function drawHeartFill() {
  push();
  drawingContext.save();
  drawingContext.shadowColor = 'rgba(255, 80, 100, 0.45)';
  drawingContext.shadowBlur = 100;
  noStroke();
  fill(70, 10, 25, 0.35);
  traceHeartPath();
  drawingContext.restore();
  noFill();
  stroke(255, 110, 130, 0.16);
  strokeWeight(3);
  traceHeartPath(1.01);
  pop();
}

function drawInnerGlow() {
  push();
  blendMode(ADD);
  noStroke();
  let coreX = CX;
  let coreY = CY + 140;
  for (let r = 260; r > 0; r -= 14) {
    let a = map(r, 0, 260, 0.22, 0);
    fill(255, 170, 120, a);
    ellipse(coreX, coreY, r * 2, r * 1.7);
  }
  for (let r = 80; r > 0; r -= 8) {
    let a = map(r, 0, 80, 0.5, 0);
    fill(255, 220, 160, a);
    ellipse(coreX, coreY, r * 2, r * 1.6);
  }
  pop();
}

function drawStrand(phase, c1, c2, offsetAmp, weight, alpha, steps = 220) {
  noFill();
  strokeCap(ROUND);
  let prev = null;
  for (let i = 0; i <= steps; i++) {
    let theta = map(i, 0, steps, 0.01, TAU - 0.02);
    let p = computeHeartPoint(theta, phase, offsetAmp);
    if (prev) {
      let amt = i / steps;
      let c = lerpColor(c1, c2, amt);
      c.setAlpha(alpha * (0.7 + 0.3 * Math.sin(theta * 5 + phase)));
      stroke(c);
      strokeWeight(weight * (0.7 + 0.3 * Math.sin(theta * 5 + phase)));
      line(prev.x, prev.y, p.x, p.y);
    }
    prev = p;
  }
}

function drawRibbonBundle(basePhase, spread, c1, c2, count, maxOffset, minW, maxW, alpha) {
  for (let i = 0; i < count; i++) {
    let phase = basePhase + random(-spread, spread);
    let off = maxOffset * random(0.4, 1.0);
    let w = random(minW, maxW);
    drawStrand(phase, c1, c2, off, w, alpha, 220);
  }
}

function drawRibbonBundles() {
  let cA1 = color(255, 40, 60);
  let cA2 = color(255, 180, 80);
  let cB1 = color(255, 200, 90);
  let cB2 = color(220, 40, 100);
  blendMode(ADD);
  drawRibbonBundle(0, 0.9, cA1, cA2, 22, 70, 2, 6, 0.10);
  drawRibbonBundle(PI, 0.9, cB1, cB2, 22, 70, 2, 6, 0.10);
  drawRibbonBundle(PI / 2, 0.6, cA2, cB2, 10, 45, 1.5, 4, 0.07);
  blendMode(BLEND);
}

function drawMainRibbons() {
  let cA1 = color(255, 70, 90);
  let cA2 = color(255, 190, 100);
  let cB1 = color(255, 210, 100);
  let cB2 = color(225, 40, 100);
  blendMode(ADD);
  drawStrand(0, cA1, cA2, 55, 9, 0.65, 300);
  drawStrand(PI, cB1, cB2, 55, 9, 0.65, 300);
  drawStrand(0, color(255, 160, 130), color(255, 230, 160), 35, 3, 0.5, 300);
  drawStrand(PI, color(255, 230, 160), color(255, 140, 150), 35, 3, 0.5, 300);
  blendMode(BLEND);
}

function drawParticles() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 350; i++) {
    let theta = random(0, TAU);
    let p = heartCanvas(theta, CX, CY, S);
    let n = heartNormalCanvas(theta);
    let off = random(-90, 90);
    let x = p.x + n.x * off;
    let y = p.y + n.y * off;
    let sz = random(1, 4.5);
    let a = random(0.2, 0.8);
    fill(255, random(130, 220), random(80, 130), a);
    ellipse(x, y, sz);
  }
  for (let i = 0; i < 45; i++) {
    let theta = random(0, TAU);
    let p = heartCanvas(theta, CX, CY, S);
    let n = heartNormalCanvas(theta);
    let off = random(-50, 50);
