  drawSoulTrail(800, 1000, PI * 0.8, 4.0, 750, 90, 0.45, [255, 80, 120], [255, 160, 200], 60, 0.3);

  // Additional smaller trails interweaving
  drawSoulTrail(800, 1000, PI * 0.1, 3.0, 680, 140, 0.55, [255, 140, 60], [255, 220, 180], 40, 0.2);
  drawSoulTrail(800, 1000, -PI * 0.2, 3.2, 700, 120, 0.5, [200, 80, 200], [255, 180, 220], 50, 0.25);

