  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(1, 3);
    let a = random(2, 8);
    fill(255, 180, 200, a);
    ellipse(x, y, r, r);
  }
}

function drawSoulTrail(cx, cy, startAngle, rotations, startRadius, endRadius, noiseAmp, colStart, colEnd, count, baseAlpha) {
  let points = [];
  let steps = 500;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let angle = startAngle + t * rotations * TWO_PI + noise(t * 10) * noiseAmp;
    let r = lerp(startRadius, endRadius, t) + noise(t * 15) * 40;
    let x = cx + r * cos(angle);
    let y = cy + r * sin(angle);
    points.push({x, y, t});
  }

  noStroke();
  for (let i = 0; i < points.length; i++) {
    let p = points[i];
    let t = p.t;
    let alpha = baseAlpha * (0.5 + 0.5 * sin(t * PI)) * 255;
    let size = lerp(25, 8, t) * (0.6 + 0.4 * noise(t * 20));
    // Color interpolation
    let r = lerp(colStart[0], colEnd[0], t);
    let g = lerp(colStart[1], colEnd[1], t);
    let b = lerp(colStart[2], colEnd[2], t);
    fill(r, g, b, alpha);
    ellipse(p.x, p.y, size, size);

    // draw smaller satellite dots for texture
    if (i % 3 === 0) {
      let offsetX = (noise(t * 30, 1) - 0.5) * 50;
      let offsetY = (noise(t * 30, 2) - 0.5) * 50;
      let s = size * 0.4;
      fill(r, g, b, alpha * 0.4);
      ellipse(p.x + offsetX, p.y + offsetY, s, s);
    }
  }
}

function drawSparks(num) {
  noStroke();
  for (let i = 0; i < num; i++) {
    let t = random(1);
    let angle = random(TWO_PI);
    let r = random(50, 500);
    let x = width/2 + r * cos(angle);
    let y = height/2 + r * sin(angle);
    let size = random(2, 6);
    let alpha = random(40, 120);
    let hue = random(200, 255);
    fill(255, hue, 200, alpha);
    ellipse(x, y, size, size);

    // occasional larger glow
    if (random() < 0.1) {
      fill(255, 200, 150, alpha * 0.3);
      ellipse(x, y, size * 3, size * 3);
    }
  }
}

