const CX = 800;
const CY = 750;
const S = 42;

function heartX(t) {
  return 16 * Math.pow(Math.sin(t), 3);
}

function heartY(t) {
  return -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t));
}

function draw() {
  background(9, 7, 24);
  noStroke();

  // Background nebula
  blendMode(ADD);
  for (let r = 1000; r > 0; r -= 15) {
    let a = map(r, 0, 1000, 22, 0);
    fill(70, 30, 120, a);
    ellipse(CX, CY + 6 * S, r * 2, r * 2);
  }
  for (let r = 520; r > 0; r -= 8) {
    let a = map(r, 0, 520, 30, 0);
    fill(255, 60, 90, a);
    ellipse(CX, CY + 6 * S, r * 2, r * 2);
  }
  blendMode(BLEND);

  drawStreams();
  drawHeartCore();
  drawHeartRibbons();
  drawHeartParticles();
  drawEmbers();
  drawVignette();
}

function drawStreams() {
  blendMode(ADD);
  noFill();
  for (let k = 0; k < 5; k++) {
    let off = (k - 2) * 9;
    stroke(255, 80, 140, 55);
    strokeWeight(3 + k * 0.7);
    beginShape();
    vertex(180 + off, 1850);
    bezierVertex(300 + off, 1580, 700 + off, 1520, 800, 1450);
    endShape();

    stroke(255, 170, 80, 55);
    beginShape();
    vertex(1420 - off, 1850);
    bezierVertex(1300 - off, 1580, 900 - off, 1520, 800, 1450);
    endShape();
  }
  blendMode(BLEND);
}

function drawHeartCore() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 22; i++) {
    let s = lerp(38, 22, i / 22);
    fill(255, 55, 90, 6);
    beginShape();
    for (let t = 0; t <= TWO_PI + 0.05; t += 0.05) {
      let x = heartX(t) * s + CX;
      let y = heartY(t) * s + CY;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
  blendMode(BLEND);
}

function drawHeartRibbons() {
  blendMode(ADD);
  noFill();
  let leftCol = color(255, 70, 120, 80);
  let rightCol = color(255, 170, 80, 80);
  for (let k = 0; k < 7; k++) {
    let off = (k - 3) * 6;

    stroke(leftCol);
    strokeWeight(2.5);
    beginShape();
    for (let t = PI; t <= TWO_PI + 0.05; t += 0.04) {
      let n = noise(cos(t) * 1.5 + 1, sin(t) * 1.5 + 1, k * 0.3) * 50 - 25;
      let s = S + off + n * 0.25;
      let x = heartX(t) * s + CX;
      let y = heartY(t) * s + CY;
      vertex(x, y);
    }
    endShape();

    stroke(rightCol);
    beginShape();
    for (let t = 0; t <= PI + 0.05; t += 0.04) {
      let n = noise(cos(t) * 1.5 + 1, sin(t) * 1.5 + 1, k * 0.3) * 50 - 25;
      let s = S + off + n * 0.25;
      let x = heartX(t) * s + CX;
      let y = heartY(t) * s + CY;
      vertex(x, y);
    }
    endShape();
  }
  blendMode(BLEND);
}

function drawHeartParticles() {
  blendMode(ADD);
  noStroke();
  let colors = [
    color(255, 80, 110, 110),
    color(255, 150, 80, 110),
    color(255, 50, 150, 110),
    color(255, 210, 120, 110)
  ];
  for (let i = 0; i < 6000; i++) {
    let t = random(TWO_PI);
    let s = S * random(0.88, 1.12);
    let x = heartX(t) * s + CX + random(-14, 14);
    let y = heartY(t) * s + CY + random(-14, 14);
    let c = colors[Math.floor(random(colors.length))];
    let d = random(1.2, 5.6);
    fill(c);
    ellipse(x, y, d, d);
  }

  for (let i = 0; i < 110; i++) {
    let t = random(TWO_PI);
    let s = S * random(0.92, 1.08);
    let x = heartX(t) * s + CX;
    let y = heartY(t) * s + CY;
    fill(255, 120, 150, 14);
    ellipse(x, y, random(70, 150), random(70, 150));
  }
  blendMode(BLEND);
}

function drawEmbers() {
  blendMode(ADD);
