  ctx.fillRect(0, 0, W, H);

  let g2 = ctx.createLinearGradient(0, 0, W, 0);
  g2.addColorStop(0, 'rgba(10, 20, 40, 0.35)');
  g2.addColorStop(0.5, 'rgba(0, 0, 0, 0)');
  g2.addColorStop(1, 'rgba(20, 10, 35, 0.35)');
