      let c;
      if (n2 < 0.35) c = color(35, 30, 80, 6);
      else if (n2 < 0.65) c = color(80, 20, 60, 5);
      else c = color(120, 35, 45, 4);
      fill(c);
      let s = 20 + n2 * 180;
      ellipse(x, y, s, s * random(0.5, 1.3));
