}

function drawHalo() {
  blendMode(BLEND);
  let ctx = drawingContext;
  ctx.save();
  let g = ctx.createRadialGradient(W / 2, H * 0.47, 40, W / 2, H * 0.47, W * 0.68);
  g.addColorStop(0, 'rgba(255, 185, 110, 0.26)');
  g.addColorStop(0.28, 'rgba(255, 95, 90, 0.17)');
  g.addColorStop(0.60, 'rgba(120, 35, 85, 0.09)');
