  let g2 = ctx.createRadialGradient(W / 2, H * 0.52, 20, W / 2, H * 0.52, W * 0.35);
  g2.addColorStop(0, 'rgba(255, 235, 190, 0.18)');
  g2.addColorStop(1, 'rgba(255, 235, 190, 0)');
