}

function drawAura(side, base) {
  let pts = ribbonPoints(side);
  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < pts.length; i += 2) {
    let p = pts[i];
    let r = 260 + noise(10 + i * 0.17 + side * 9) * 220;
    let a = 3 + 3 * noise(20 + i * 0.11);
    fill(red(base), green(base), blue(base), a);
    ellipse(p.x, p.y, r * 1.35, r * 0.92);
  }
  pop();
}

function drawFigures() {
  let warmPalette = [
    color(255, 70, 66),
    color(255, 122, 64),
    color(255, 190, 110),
    color(215, 36, 98),
    color(150, 22, 70)
  ];
  let coolPalette = [
    color(64, 110, 255),
    color(72, 205, 220),
    color(170, 115, 255),
    color(255, 214, 165),
    color(28, 60, 140)
  ];

  drawRibbon(-1, warmPalette);
  drawRibbon(1, coolPalette);

  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 220; i++) {
    let x = W / 2 + randomGaussian() * 80;
    let y = H * 0.475 + randomGaussian() * 170;
    let s = 6 + 46 * pow(random(), 1.7);
    let a = 2 + 5 * noise(x * 0.01, y * 0.01);
    fill(255, 205, 165, a);
    ellipse(x, y, s, s * random(0.7, 1.2));
  }
  pop();
}

function drawRibbon(side, palette) {
  let pts = ribbonPoints(side);
  let normals = [];
  for (let i = 0; i < pts.length; i++) {
    let a = pts[max(i - 1, 0)];
    let b = pts[min(i + 1, pts.length - 1)];
    let dx = b.x - a.x;
    let dy = b.y - a.y;
    let m = max(1e-5, sqrt(dx * dx + dy * dy));
    normals.push(createVector(-dy / m, dx / m));
  }

  push();
  blendMode(SCREEN);
  noFill();
  curveTightness(-0.15);
  let strandCount = 130;
  for (let s = 0; s < strandCount; s++) {
    let u = s / (strandCount - 1);
    let baseOffset = (u - 0.5) * 240;
    let ia = floor(noise(s * 0.11, 30 + side * 3.3) * palette.length) % palette.length;
    let ib = floor(noise(s * 0.17 + 20, 60 + side * 5.1) * palette.length) % palette.length;
    let c = lerpColor(palette[ia], palette[ib], noise(s * 0.05, 90 + side * 9.9));
    c.setAlpha(5 + 18 * noise(s * 0.2, 120 + side * 4));
    stroke(c);
    strokeWeight(0.6 + 4.5 * noise(s * 0.31, 150 + side * 7.7));

    beginShape();
    let p0 = offsetPoint(pts[0], normals[0], baseOffset, s, 0, pts.length, side);
    curveVertex(p0.x, p0.y);
    for (let i = 0; i < pts.length; i++) {
      let p = offsetPoint(pts[i], normals[i], baseOffset, s, i, pts.length, side);
      curveVertex(p.x, p.y);
    }
    let p1 = offsetPoint(pts[pts.length - 1], normals[pts.length - 1], baseOffset, s, pts.length - 1, pts.length, side);
    curveVertex(p1.x, p1.y);
    endShape();
  }
  pop();

  push();
  blendMode(BLEND);
  noFill();
  stroke(10, 5, 12, 16);
  strokeWeight(26);
  beginShape();
  curveVertex(pts[0].x, pts[0].y);
  for (let i = 0; i < pts.length; i++) {
    curveVertex(pts[i].x, pts[i].y);
  }
  curveVertex(pts[pts.length - 1].x, pts[pts.length - 1].y);
  endShape();
  pop();
}

function offsetPoint(p, n, baseOffset, strandIndex, i, total, side) {
  let t = total <= 1 ? 0 : i / (total - 1);
  let envelope = sin(PI * t);
  let wiggle = (noise(strandIndex * 0.07, i * 0.06, 200 + side * 2.2) - 0.5) * 150;
  let off = baseOffset * (0.25 + 0.75 * envelope) + wiggle;
  return createVector(p.x + n.x * off, p.y + n.y * off);
}

function ribbonPoints(side) {
  let pts = [];
  let steps = 34;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let y = lerp(-80, H + 80, t);
    let centerPull = exp(-sq((y - H * 0.475) / (H * 0.22)));
    let separation = lerp(360, 90, centerPull);
    let swing = sin(t * PI * 1.2 + side * 0.7) * 80;
    let n = noise(100 + side * 37.3 + t * 2.2, 50 + side * 11.7) - 0.5;
    let x = W / 2 + side * separation + swing + n * 260;
    pts.push(createVector(x, y));
  }
  return pts;
}

function drawEmbraceThreads() {
  push();
  blendMode(ADD);
  noFill();
  for (let j = 0; j < 36; j++) {
    let c = lerpColor(color(255, 214, 150), color(255, 110, 120), noise(j * 0.18));
    c.setAlpha(6 + 12 * noise(j * 0.4));
    stroke(c);
    strokeWeight(0.5 + 2.2 * noise(j * 0.5));
    let pts = [];
    let yStart = H * 0.15 + j * (H * 0.012) + random(-25, 25);
    let yEnd = H * 0.80 + j * (H * 0.005) + random(-25, 25);
    for (let i = 0; i <= 32; i++) {
      let t = i / 32;
      let y = lerp(yStart, yEnd, t);
      let centerPull = exp(-sq((y - H * 0.475) / (H * 0.18)));
      let x = W / 2 + sin(t * PI * 2.2 + j * 0.55) * (170 - 110 * centerPull) + (noise(j * 0.25, t * 1.3) - 0.5) * 220;
      pts.push(createVector(x, y));
    }
    drawCurvePath(pts);
  }
  pop();
}

function drawCurvePath(pts) {
  if (pts.length < 2) return;
  beginShape();
  curveVertex(pts[0].x, pts[0].y);
  for (let i = 0; i < pts.length; i++) {
    curveVertex(pts[i].x, pts[i].y);
  }
  curveVertex(pts[pts.length - 1].x, pts[pts.length - 1].y);
  endShape();
}

function drawSparks() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 750; i++) {
    let x = W / 2 + randomGaussian() * 240;
    let y = H * 0.475 + randomGaussian() * 430;
    let n = noise(x * 0.008, y * 0.008);
    if (n > 0.35) {
      let r = pow(random(), 2) * 9 + 1;
      let h = noise(i * 0.02);
      let c;
      if (h < 0.45) c = color(255, 220, 170, 4 + 26 * n);
      else if (h < 0.75) c = color(255, 110, 120, 4 + 20 * n);
      else c = color(120, 190, 255, 3 + 18 * n);
      fill(c);
      ellipse(x, y, r, r);
      if (random() < 0.06) {
        stroke(c);
        strokeWeight(0.6);
        line(x - r * 3, y, x + r * 3, y);
        line(x, y - r * 3, x, y + r * 3);
        noStroke();
      }
    }
  }
  pop();
}

function drawTexture() {
  push();
  blendMode(BLEND);
  for (let i = 0; i < 2800; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.003, y * 0.003);
    let a = 2 + 8 * n;
    let c;
    if (noise(i * 0.01) < 0.5) c = color(255, 230, 210, a * 0.35);
    else c = color(8, 6, 14, a);
    stroke(c);
    strokeWeight(0.5 + noise(i * 0.07) * 2.2);
    let ang = noise(x * 0.004, y * 0.004) * TWO_PI * 2;
    let len = 8 + noise(x * 0.01, y * 0.01) * 36;
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
  pop();
}

function drawVignette() {
  blendMode(BLEND);
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(W / 2, H * 0.46, W * 0.18, W / 2, H * 0.46, W * 0.95);
  g.addColorStop(0, 'rgba(0, 0, 0, 0)');
  g.addColorStop(0.72, 'rgba(0, 0, 0, 0.08)');
  g.addColorStop(1, 'rgba(0, 0, 0, 0.50)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  let lg = ctx.createLinearGradient(0, 0, 0, H);
  lg.addColorStop(0, 'rgba(0, 0, 0, 0.30)');
  lg.addColorStop(0.18, 'rgba(0, 0, 0, 0)');
  lg.addColorStop(0.82, 'rgba(0, 0, 0, 0)');
  lg.addColorStop(1, 'rgba(0, 0, 0, 0.35)');
  ctx.fillStyle = lg;
  ctx.fillRect(0, 0, W, H);
}

