  [0.30, [15, 30, 58]],
  [0.58, [20, 50, 76]],
  [0.80, [22, 42, 60]],
  [1.00, [10, 14, 24]]
];

function baseSky(y) {
  const t = constrain(y / height, 0, 1);
  for (let i = 1; i < SKY.length; i++) {
    if (t <= SKY[i][0]) {
      const a = SKY[i - 1], b = SKY[i];
      const u = (t - a[0]) / (b[0] - a[0]);
      return [
        lerp(a[1][0], b[1][0], u),
        lerp(a[1][1], b[1][1], u),
        lerp(a[1][2], b[1][2], u)
      ];
    }
  }
  return SKY[SKY.length - 1][1];
}

function lerp3(a, b, t) {
  t = constrain(t, 0, 1);
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}

function jitter3(c, amt) {
  return [c[0] + random(-amt, amt), c[1] + random(-amt, amt), c[2] + random(-amt, amt)];
}

function paintSky() {
  const g = ctx.createLinearGradient(0, 0, 0, height);
  for (const s of SKY) g.addColorStop(s[0], `rgb(${s[1][0]},${s[1][1]},${s[1][2]})`);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < 13500; i++) {
    const x = random(width), y = random(height);
    const n = noise(x * 0.0016, y * 0.0016);
    const ang = n * TWO_PI * 2;
    const len = 8 + random(16);
    let c = baseSky(y);
    const r0 = random();
    if (r0 < 0.08) c = lerp3(c, [36, 86, 96], 0.5);
    else if (r0 < 0.15) c = lerp3(c, [64, 40, 74], 0.45);
    c = jitter3(c, 12);
    stroke(c[0], c[1], c[2], 16 + random(30));
    strokeWeight(2 + random(3.5));
    line(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len);
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 120; i++) {
    const x = random(width), y = random(0, height * 0.62);
    if (dist(x, y, 560, 500) < 480) continue;
    fill(210, 225, 255, 25 + random(70));
    circle(x, y, random(1, 2.6));
    if (random() < 0.07) {
      stroke(215, 228, 255, 50);
      strokeWeight(0.8);
      const L = 5 + random(9);
      line(x - L, y, x + L, y);
      line(x, y - L, x, y + L);
      noStroke();
    }
  }
}

function ridgeY1(x) { return 1520 + 90 * noise(x * 0.0012 + 7.3); }
function ridgeY2(x) { return 1780 + 70 * noise(x * 0.0014 + 2.1); }

function paintGround() {
  noStroke();
  fill(16, 22, 38);
  beginShape();
  vertex(-20, height + 20);
  for (let x = -20; x <= width + 20; x += 20) vertex(x, ridgeY1(x));
  vertex(width + 20, height + 20);
  endShape(CLOSE);

  for (let i = 0; i < 2400; i++) {
    const x = random(width);
    const y = ridgeY1(x) + random(-2, 26);
    const w = Math.exp(-sq(x - 1062) / (2 * 300 * 300));
    let c = lerp3([22, 30, 50], [150, 88, 56], w * 0.75);
    c = jitter3(c, 8);
    stroke(c[0], c[1], c[2], 60 + random(90));
    strokeWeight(1 + random(1.6));
    const L = 5 + random(13);
    const lean = (noise(x * 0.01, 3.3) - 0.5) * 1.2;
    line(x, y, x + Math.sin(lean) * L, y - Math.cos(lean) * L);
  }

  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 12; i++) {
    fill(80, 105, 120, 7 + random(7));
    ellipse(random(width), 1600 + random(120), 300 + random(400), 26 + random(46));
  }
  pop();

  noStroke();
  fill(9, 13, 24);
  beginShape();
  vertex(-20, height + 20);
  for (let x = -20; x <= width + 20; x += 20) vertex(x, ridgeY2(x));
  vertex(width + 20, height + 20);
  endShape(CLOSE);

  for (let i = 0; i < 1500; i++) {
    const x = random(width);
    const y = ridgeY2(x) + random(-2, 30);
    const w = Math.exp(-sq(x - 1062) / (2 * 340 * 340));
    let c = lerp3([16, 22, 38], [120, 72, 48], w * 0.6);
    stroke(c[0], c[1], c[2], 70 + random(90));
    strokeWeight(1.2 + random(2));
    const L = 8 + random(20);
    const lean = (noise(x * 0.008, 9.1) - 0.5) * 1.4;
    line(x, y, x + Math.sin(lean) * L, y - Math.cos(lean) * L);
  }
}

function radialGlow(cx, cy, rad, stops) {
  push();
  blendMode(SCREEN);
  const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, rad);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, rad, 0, Math.PI * 2);
  ctx.fill();
  pop();
}

function distantGlow() {
  radialGlow(560, 500, 620, [
    [0, 'rgba(255,150,100,0.30)'],
    [0.4, 'rgba(230,90,80,0.12)'],
    [1, 'rgba(0,0,0,0)']
  ]);
  radialGlow(1062, 1432, 680, [
    [0, 'rgba(255,170,110,0.30)'],
    [0.4, 'rgba(235,110,80,0.12)'],
    [1, 'rgba(0,0,0,0)']
  ]);
}

function catmull(p0, p1, p2, p3, t) {
  const t2 = t * t, t3 = t2 * t;
  const f = (a, b, c, d) =>
    0.5 * (2 * b + (c - a) * t + (2 * a - 5 * b + 4 * c - d) * t2 + (3 * b - a - 3 * c + d) * t3);
  return { x: f(p0[0], p1[0], p2[0], p3[0]), y: f(p0[1], p1[1], p2[1], p3[1]) };
}

function threadPoints() {
  const P = [
    [556, 516], [610, 660], [700, 800], [800, 880],
    [930, 950], [975, 1060], [880, 1150], [760, 1095],
    [755, 985], [860, 860], [985, 925], [1030, 1030],
    [1050, 1170], [1058, 1300], [1062, 1432]
  ];
  const pts = [];
  const STEPS = 34;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[Math.max(i - 1, 0)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(i + 2, P.length - 1)];
    for (let s = 0; s < STEPS; s++) pts.push(catmull(p0, p1, p2, p3, s / STEPS));
  }
  pts.push({ x: P[P.length - 1][0], y: P[P.length - 1][1] });
  for (let i = 0; i < pts.length; i++) {
    pts[i].x += (noise(i * 0.06, 11.2) - 0.5) * 7;
    pts[i].y += (noise(i * 0.06, 27.9) - 0.5) * 7;
  }
  return pts;
}

function drawPass(pts, i0, i1, colFn, wFn, ox, oy) {
  for (let i = Math.max(1, i0); i <= Math.min(pts.length - 1, i1); i++) {
    const a = pts[i - 1], b = pts[i];
    const c = colFn(i);
    stroke(c[0], c[1], c[2], c[3]);
    strokeWeight(wFn(i));
    line(a.x + ox, a.y + oy, b.x + ox, b.y + oy);
  }
}

function paintThread() {
  const pts = threadPoints();
  const n = pts.length;
  const taper = i => 0.35 + 0.65 * constrain(Math.min(i, n - i) / 46, 0, 1);

  push();
  blendMode(SCREEN);
  drawPass(pts, 0, n - 1, () => [255, 120, 80, 7], () => 40, 0, 0);
  drawPass(pts, 0, n - 1, () => [255, 145, 95, 9], () => 22, 0, 0);
  pop();

  drawPass(pts, 0, n - 1, () => [8, 10, 22, 60], i => 11 * taper(i), 4, 7);
  drawPass(pts, 0, n - 1, () => [96, 18, 22, 200], i => 8.6 * taper(i), 0, 0);
  drawPass(pts, 0, n - 1,
    i => { const c = lerp3([172, 34, 30], [236, 76, 44], noise(i * 0.02, 4.4)); return [c[0], c[1], c[2], 235]; },
    i => (4.4 + 2.8 * noise(i * 0.03, 1.7)) * taper(i), 0, 0);
  drawPass(pts, 0, n - 1, () => [255, 150, 110, 105], i => 1.6 * taper(i), -1.5, -1.5);

  let iOver = -1, best = 1e9;
  const a0 = Math.floor(n * 0.52), a1 = Math.floor(n * 0.75);
  for (let i = a0; i < a1; i++) {
    const d = dist(pts[i].x, pts[i].y, 830, 896);
    if (d < best) { best = d; iOver = i; }
  }
  const R = 14;
  const sky = baseSky(896);
  for (let pass = 0; pass < 4; pass++) {
    for (let i = Math.max(1, iOver - R); i <= Math.min(n - 1, iOver + R); i++) {
      const fa = constrain(Math.min(i - (iOver - R), (iOver + R) - i) / 8, 0, 1);
      const p = pts[i - 1], q = pts[i];
      let c, w;
      if (pass === 0) { c = [sky[0], sky[1], sky[2], 245 * fa]; w = 15 * taper(i); }
      else if (pass === 1) { c = [96, 18, 22, 220 * fa]; w = 8.6 * taper(i); }
      else if (pass === 2) {
        const b = lerp3([178, 36, 30], [238, 80, 46], noise(i * 0.02, 4.4));
        c = [b[0], b[1], b[2], 240 * fa]; w = (4.6 + 2.6 * noise(i * 0.03, 1.7)) * taper(i);
      } else { c = [255, 155, 115, 120 * fa]; w = 1.6 * taper(i); }
      stroke(c[0], c[1], c[2], c[3]);
      strokeWeight(w);
      line(p.x, p.y, q.x, q.y);
    }
  }

  for (let k = 0; k < 300; k++) {
    const i = Math.floor(random(n));
    const p = pts[i];
    const q = pts[constrain(i + 3, 0, n - 1)];
    const dx = q.x - p.x, dy = q.y - p.y;
    const m = Math.hypot(dx, dy) || 1;
    const off = (random() < 0.5 ? -1 : 1) * (12 + pow(random(), 1.6) * 110);
    const x = p.x + (-dy / m) * off + random(-8, 8);
    const y = p.y + (dx / m) * off + random(-8, 8);
    const c = lerp3([226, 190, 120], [255, 150, 100], random());
    stroke(c[0], c[1], c[2], 50 + random(120));
    strokeWeight(0.8 + random(1.6));
    const L = 1.5 + random(4.5), ang = random(TWO_PI);
    line(x, y, x + Math.cos(ang) * L, y + Math.sin(ang) * L);
  }
}

function paintSun(cx, cy, r, variant) {
  radialGlow(cx, cy, r * 4.3, variant === 0
    ? [[0, 'rgba(255,170,120,0.42)'], [0.3, 'rgba(240,110,85,0.18)'], [0.7, 'rgba(160,60,80,0.05)'], [1, 'rgba(0,0,0,0)']]
    : [[0, 'rgba(255,185,120,0.44)'], [0.3, 'rgba(242,120,80,0.20)'], [0.7, 'rgba(170,70,75,0.06)'], [1, 'rgba(0,0,0,0)']]);

  for (let k = 0; k < 1500; k++) {
    const a = random(TWO_PI);
    const rr = r * (0.18 + Math.pow(random(), 0.6) * 1.6);
    const x = cx + Math.cos(a) * rr;
    const y = cy + Math.sin(a) * rr * 0.98;
    const t = rr / r;
    let c;
    if (t < 0.55) c = lerp3([255, 238, 190], [255, 175, 105], t / 0.55);
    else if (t < 1) c = lerp3([255, 175, 105], [232, 92, 72], (t - 0.55) / 0.45);
    else c = lerp3([232, 92, 72], [140, 45, 62], constrain((t - 1) / 0.75, 0, 1));
    if (variant === 1) c = lerp3(c, [255, 205, 130], 0.15);
    const al = map(t, 0.18, 1.78, 190, 22) * random(0.55, 1);
    const ang = a + HALF_PI + (noise(x * 0.004, y * 0.004) - 0.5) * 1.3;
    const L = 5 + r * 0.05 * random();
    stroke(c[0], c[1], c[2], al);
    strokeWeight(1.6 + random(3.2));
    line(x, y, x + Math.cos(ang) * L, y + Math.sin(ang) * L);
  }

  push();
  blendMode(SCREEN);
  for (let k = 0; k < 240; k++) {
    const a = random(TWO_PI);
    const rr = r * (1.05 + random(1.15));
    const x = cx + Math.cos(a) * rr, y = cy + Math.sin(a) * rr;
    stroke(255, 160 + random(60), 100, 12 + random(26));
    strokeWeight(0.8 + random(1.6));
    const L = 4 + random(14);
    line(x, y, x + Math.cos(a) * L, y + Math.sin(a) * L);
  }
  ctx.save();
  ctx.shadowBlur = 70;
  ctx.shadowColor = 'rgba(255,190,120,0.9)';
  ctx.fillStyle = variant === 0 ? 'rgba(255,232,180,0.95)' : 'rgba(255,224,160,0.95)';
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.58, 0, Math.PI * 2); ctx.fill();
  ctx.shadowBlur = 34;
  ctx.fillStyle = 'rgba(255,246,220,0.95)';
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.30, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
  pop();

  noFill();
  for (let k = 0; k < 3; k++) {
    const rad = r * (2.1 + k * 0.85);
    const start = random(TWO_PI);
    stroke(255, 170, 120, 14 + random(10));
    strokeWeight(1.2 + random(0.8));
    arc(cx, cy, rad * 2, rad * 2, start, start + 0.5 + random(1.4));
  }
}

function paintFireflies() {
  push();
  blendMode(SCREEN);
  for (let i = 0; i < 130; i++) {
    const x = random(width * 0.05, width * 0.95);
    const y = 860 + Math.pow(random(), 0.85) * 1080;
    if (dist(x, y, 560, 500) < 300 || dist(x, y, 1062, 1432) < 330) continue;
    const pk = random();
    const c = pk < 0.45 ? [255, 205, 130] : pk < 0.8 ? [255, 160, 105] : [255, 125, 120];
    ctx.save();
    ctx.shadowBlur = 9;
    ctx.shadowColor = `rgba(${c[0]},${c[1]},${c[2]},0.9)`;
    ctx.fillStyle = `rgba(${c[0]},${c[1]},${c[2]},${(0.35 + random(0.55)).toFixed(3)})`;
    ctx.beginPath(); ctx.arc(x, y, 1.2 + random(2.6), 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
  pop();
}

function finish() {
  const g = ctx.createRadialGradient(800, 960, 620, 800, 960, 1620);
  g.addColorStop(0, 'rgba(4,6,14,0)');
  g.addColorStop(1, 'rgba(4,6,14,0.58)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < 4200; i++) {
    const x = random(width), y = random(height);
    const d = random() < 0.5 ? 0 : 255;
    stroke(d, d, d, 3 + random(7));
    strokeWeight(1);
    point(x, y);
  }
}

let W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  paintSky();
  milkyWay();
  drawStars();
  horizonGlow();
  drawMoon();
  paintSnow();
  treeline();
  snowTexture();
  moonPath();
  snowSparkles();

  footprints(430, 80, 1596);
  footprints(1175, 1530, 1604);
  mound(470, 1578, 330);
  mound(1130, 1590, 300);
  mound(800, 1616, 270);
  warmPool(470, 1580, 110);
  warmPool(1130, 1592, 100);
  warmPool(800, 1612, 250);

  drawFigure(470, 1572, 240, 0.02, 1);
  drawFigure(1130, 1585, 222, -0.02, -1);
  drawLantern(800, 1608);
  drawThread();

  fallingSnow();
  grain();
  vignette();
}

function paintSky() {
  noStroke();
  for (let y = 0; y < 1260; y += 2) {
    fill(skyCol(y));
    rect(0, y, W, 3);
  }
  for (let i = 0; i < 9000; i++) {
    let y = pow(random(), 1.15) * 1250;
    let x = random(W);
    let c = skyCol(y);
    let n = noise(x * 0.0021, y * 0.0037);
    let d = (n - 0.5) * 34 + random(-7, 7);
    stroke(
      constrain(red(c) + d, 0, 255),
      constrain(green(c) + d * 0.8, 0, 255),
      constrain(blue(c) + d * 0.6, 0, 255),
      26
    );
    strokeWeight(random(6, 24));
    let len = random(30, 130);
    let sl = (noise(x * 0.003 + 37, y * 0.003) - 0.5) * 16;
    line(x - len / 2, y + sl, x + len / 2, y - sl);
  }
}

function skyCol(y) {
  let t = constrain(y / 1250, 0, 1);
  if (t < 0.5) return lerpColor(color(12, 16, 44), color(27, 43, 82), t / 0.5);
  if (t < 0.82) return lerpColor(color(27, 43, 82), color(88, 110, 138), (t - 0.5) / 0.32);
  return lerpColor(color(88, 110, 138), color(180, 158, 150), (t - 0.82) / 0.18);
}

function milkyWay() {
  noStroke();
  for (let i = 0; i < 1100; i++) {
    let t = random();
    let x = lerp(60, 1560, t), y = lerp(120, 860, t);
    let off = randomGaussian() * 110;
    x += off * 0.35; y += off * 0.9;
    let a = random(6, 20) * (1 - abs(off) / 260);
    if (a > 1) { fill(210, 220, 240, a); ellipse(x, y, random(1, 2.6)); }
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 380; i++) {
    let x = random(W), y = pow(random(), 1.1) * 1180;
    if (dist(x, y, 1168, 392) < 300) continue;
    fill(225, 230, 245, random(50, 170));
    let s = random(1, 3);
    ellipse(x, y, s, s);
  }
  for (let i = 0; i < 14; i++) {
    let x = random(W), y = random(60, 1000);
    if (dist(x, y, 1168, 392) < 340) continue;
    let s = random(2.6, 4.4);
    fill(240, 242, 250, 190);
    ellipse(x, y, s, s);
    stroke(235, 238, 248, 60);
    strokeWeight(1);
    line(x - s * 4, y, x + s * 4, y);
    line(x, y - s * 4, x, y + s * 4);
    noStroke();
  }
}

function horizonGlow() {
  for (let i = 0; i < 260; i++) {
    let y = random(1050, 1250);
    let x = random(W);
    stroke(190, 190, 200, map(y, 1050, 1250, 4, 16) * random(0.5, 1));
    strokeWeight(random(4, 10));
    let len = random(80, 260);
    line(x - len / 2, y, x + len / 2, y + random(-4, 4));
  }
}

function drawMoon() {
  let mx = 1168, my = 392, mr = 146;
  noStroke();
  for (let r = mr + 300; r > mr; r -= 12) {
    fill(236, 229, 206, map(r, mr, mr + 300, 30, 0) * 0.55);
    ellipse(mx, my, r * 2, r * 2);
  }
  fill(246, 241, 220);
  ellipse(mx, my, mr * 2, mr * 2);
  for (let i = 0; i < 80; i++) {
    let a = random(TWO_PI), rr = sqrt(random()) * mr * 0.9;
    fill(224, 218, 194, random(8, 24));
    ellipse(mx + cos(a) * rr, my + sin(a) * rr, random(5, 24), random(5, 24));
  }
  fill(214, 209, 188, 36);
  ellipse(mx - mr * 0.22, my + mr * 0.18, mr * 1.7, mr * 1.7);
  fill(246, 241, 220, 90);
  ellipse(mx + mr * 0.18, my - mr * 0.16, mr * 1.3, mr * 1.3);
  noFill();
  stroke(250, 246, 228, 70);
  strokeWeight(2.5);
  ellipse(mx, my, mr * 2 + 4, mr * 2 + 4);
}

function paintSnow() {
  hill(1206, 46, 3.7, 176, 186, 212);
  hill(1285, 70, 9.2, 158, 170, 204);
  hill(1400, 80, 15.8, 180, 190, 220);
  hill(1500, 90, 22.3, 202, 209, 233);
}

function hill(off, amp, sd, r, g, b) {
  noStroke();
  fill(r, g, b);
  beginShape();
  vertex(-60, H + 80);
  for (let x = -60; x <= W + 60; x += 18) {
    vertex(x, off + noise(x * 0.0011 + sd) * amp);
  }
  vertex(W + 60, H + 80);
  endShape(CLOSE);
}

function treeline() {
  noStroke();
  for (let i = 0; i < 26; i++) {
    let x = random(W);
    if (abs(x - 800) < 380) continue;
    let y = 1285 + noise(x * 0.0011 + 9.2) * 70;
    let h = random(16, 42);
    fill(70, 82, 120, 190);
    triangle(x - h * 0.3, y, x + h * 0.3, y, x, y - h);
  }
}

function snowCol(y) {
  let t = constrain((y - 1206) / (H - 1206), 0, 1);
  if (t < 0.34) return lerpColor(color(198, 206, 231), color(168, 180, 214), t / 0.34);
  if (t < 0.62) return lerpColor(color(168, 180, 214), color(188, 197, 226), (t - 0.34) / 0.28);
  return lerpColor(color(188, 197, 226), color(210, 215, 238), (t - 0.62) / 0.38);
}

function snowTexture() {
  for (let i = 0; i < 12000; i++) {
    let y = 1215 + pow(random(), 0.9) * (H - 1215);
    let x = random(W);
    let c = snowCol(y);
    let d = (noise(x * 0.004, y * 0.004) - 0.5) * 46 + random(-6, 6);
    stroke(
      constrain(red(c) + d, 0, 255),
      constrain(green(c) + d * 0.9, 0, 255),
      constrain(blue(c) + d * 0.7, 0, 255),
      32
