function catmull(p, res) {
  let out = [];
  for (let i = 0; i < p.length - 1; i++) {
    let p0 = p[max(i - 1, 0)], p1 = p[i], p2 = p[i + 1], p3 = p[min(i + 2, p.length - 1)];
    for (let s = 0; s < res; s++) {
      let t = s / res;
      out.push(createVector(
        curvePoint(p0.x, p1.x, p2.x, p3.x, t),
        curvePoint(p0.y, p1.y, p2.y, p3.y, t)
      ));
    }
  }
  out.push(p[p.length - 1].copy());
  return out;
}

