// ---------- vessel silhouette ----------
const PROF = [
  [548, 120], [562, 131], [592, 103], [664, 92], [744, 112], [860, 222],
  [980, 322], [1100, 388], [1260, 332], [1400, 222], [1500, 150],
  [1560, 141], [1594, 168], [1630, 178]
];

function cr(a, b, c, d, t) {
  const t2 = t * t, t3 = t2 * t;
  return 0.5 * (2 * b + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t2 + (-a + 3 * b - 3 * c + d) * t3);
}

let OUTLINE = null;
function outline() {
  if (OUTLINE) return OUTLINE;
  const pts = PROF, S = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(i - 1, 0)], p1 = pts[i],
          p2 = pts[i + 1], p3 = pts[Math.min(i + 2, pts.length - 1)];
    const n = Math.max(3, Math.floor((p2[0] - p1[0]) / 3));
    for (let s = 0; s < n; s++) {
      const t = s / n;
      S.push([cr(p0[0], p1[0], p2[0], p3[0], t), cr(p0[1], p1[1], p2[1], p3[1], t)]);
    }
  }
  S.push(pts[pts.length - 1].slice());
  OUTLINE = S;
  return S;
}

function hwAt(y) {
  const S = outline();
  for (let i = 0; i < S.length - 1; i++) {
    if (y >= S[i][0] && y <= S[i + 1][0]) {
      const t = (y - S[i][0]) / Math.max(0.001, S[i + 1][0] - S[i][0]);
      return lerp(S[i][1], S[i + 1][1], t);
    }
  }
  return 0;
}

function vesselPath(ctx) {
  const S = outline();
  ctx.beginPath();
  ctx.moveTo(800 + S[0][1], S[0][0]);
  for (let i = 1; i < S.length; i++) ctx.lineTo(800 + S[i][1], S[i][0]);
  ctx.quadraticCurveTo(800, 1648, 800 - S[S.length - 1][1], S[S.length - 1][0]);
  for (let i = S.length - 2; i >= 0; i--) ctx.lineTo(800 - S[i][1], S[i][0]);
  ctx.quadraticCurveTo(800, 536, 800 + S[0][1], S[0][0]);
  ctx.closePath();
}

// ---------- the lacquer vessel with kintsugi seams ----------
