// ---------- crack generation ----------
function jag(anchors, amp, step, kink) {
  const pts = [];
  for (let i = 0; i < anchors.length - 1; i++) {
    const x1 = anchors[i][0], y1 = anchors[i][1];
    const x2 = anchors[i + 1][0], y2 = anchors[i + 1][1];
    const d = dist(x1, y1, x2, y2);
    const n = Math.max(2, Math.floor(d / step));
    for (let s = 0; s < n; s++) {
      const t = s / n;
      let x = lerp(x1, x2, t), y = lerp(y1, y2, t);
      if (!(i === 0 && s === 0)) {
        const a = atan2(y2 - y1, x2 - x1) + HALF_PI;
        let off = random(-1, 1) * amp * (0.35 + noise(x * 0.02, y * 0.02));
        if (random() < kink) off *= 2.4;
        x += Math.cos(a) * off;
        y += Math.sin(a) * off;
      }
      pts.push([x, y]);
    }
  }
  pts.push(anchors[anchors.length - 1].slice());
  return pts;
}

// ---------- render a gold seam ----------
function seam(ctx, pts, w) {
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const cA = color(196, 138, 44), cB = color(255, 224, 138);
  for (let i = 0; i < pts.length - 1; i++) {
    const x1 = pts[i][0], y1 = pts[i][1];
    const x2 = pts[i + 1][0], y2 = pts[i + 1][1];
    const ww = w * (0.7 + 0.7 * noise(x1 * 0.01, y1 * 0.01));

    ctx.strokeStyle = 'rgba(8,4,2,0.7)';
    ctx.lineWidth = ww + 2.5;
    ctx.beginPath(); ctx.moveTo(x1 + 2, y1 + 3); ctx.lineTo(x2 + 2, y2 + 3); ctx.stroke();

    ctx.strokeStyle = 'rgba(255,170,60,0.16)';
    ctx.lineWidth = ww * 3.1;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();

    const c = lerpColor(cA, cB, noise(x1 * 0.02, y1 * 0.02));
    ctx.strokeStyle = `rgba(${red(c) | 0},${green(c) | 0},${blue(c) | 0},1)`;
    ctx.lineWidth = ww;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();

    ctx.strokeStyle = 'rgba(255,244,200,0.55)';
    ctx.lineWidth = Math.max(0.8, ww * 0.3);
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  }
  for (let i = 0; i < pts.length; i += 4) {
    if (random() < 0.55) {
      const x = pts[i][0], y = pts[i][1];
      ctx.fillStyle = `rgba(255,214,120,${random(0.25, 0.85)})`;
      ctx.beginPath();
      ctx.arc(x + random(-w, w) * 1.6, y + random(-w, w) * 1.6, random(0.6, 1.9), 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function seams(ctx) {
  const A = jag([[742, 560], [698, 724], [636, 906], [556, 1082], [600, 1262], [704, 1432], [758, 1560], [792, 1626]], 7, 13, 0.10);
  const B = jag([[1020, 830], [958, 1004], [1042, 1180], [1008, 1352], [938, 1502], [958, 1596]], 6, 13, 0.10);
  const C = jag([[776, 958], [870, 980], [958, 1004]], 5, 12, 0.12);
  const D = jag([[556, 1082], [500, 1150], [474, 1236]], 4, 11, 0.14);
  const E = jag([[872, 558], [904, 656], [862, 768], [880, 852]], 3.6, 11, 0.12);
  const F = jag([[742, 1318], [806, 1390], [788, 1470], [806, 1540]], 3.2, 10, 0.12);
  const G = jag([[640, 904], [688, 928]], 3, 8, 0.10);
  seam(ctx, A, 7); seam(ctx, B, 6.4); seam(ctx, C, 5);
  seam(ctx, G, 4); seam(ctx, D, 4.2); seam(ctx, E, 3.8); seam(ctx, F, 3.2);
}

// ---------- mouth and lip of the vessel ----------
function rim(ctx) {
  ctx.fillStyle = '#0a0608';
  ctx.beginPath(); ctx.ellipse(800, 556, 131, 30, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#040304';
  ctx.beginPath(); ctx.ellipse(800, 557, 104, 21, 0, 0, Math.PI * 2); ctx.fill();

  let rg = ctx.createRadialGradient(786, 556, 4, 786, 556, 90);
  rg.addColorStop(0, 'rgba(255,180,90,0.10)');
  rg.addColorStop(1, 'rgba(255,180,90,0)');
  ctx.save();
  ctx.beginPath(); ctx.ellipse(800, 557, 104, 21, 0, 0, Math.PI * 2); ctx.clip();
  ctx.fillStyle = rg;
  ctx.fillRect(690, 530, 220, 60);
  ctx.restore();

  ctx.strokeStyle = 'rgba(255,220,160,0.28)';
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.ellipse(800, 556, 131, 30, 0, Math.PI * 0.12, Math.PI * 0.88); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,240,200,0.5)';
  ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.ellipse(800, 557, 131, 30, 0, Math.PI * 0.3, Math.PI * 0.7); ctx.stroke();
}

// ---------- rim light on the silhouette ----------
function edgeLight(ctx) {
  const S = outline();
  ctx.lineCap = 'round';
  for (let i = 2; i < S.length - 1; i++) {
    const y = S[i][0], h = S[i][1];
    ctx.strokeStyle = `rgba(255,150,80,${0.05 + 0.10 * noise(y * 0.01)})`;
    ctx.lineWidth = 4.5;
    ctx.beginPath(); ctx.moveTo(800 + h - 2, S[i - 1][0]); ctx.lineTo(800 + h - 2, y); ctx.stroke();

    ctx.strokeStyle = `rgba(150,170,255,${0.03 + 0.07 * noise(y * 0.013 + 40)})`;
    ctx.lineWidth = 3.5;
    ctx.beginPath(); ctx.moveTo(800 - h + 2, S[i - 1][0]); ctx.lineTo(800 - h + 2, y); ctx.stroke();
  }
}

// ---------- drifting gold motes ----------
function dust(ctx) {
  for (let i = 0; i < 110; i++) {
    const x = constrain(800 + randomGaussian() * 230, 60, 1540);
    const y = random(180, 1620);
    const r = random(0.7, 3.2);
    const col = random() < 0.8 ? '255,208,130' : '235,225,255';
    const a = random(0.10, 0.65) * (r / 3.2 + 0.3);
    if (r > 2.2) {
      const rg = ctx.createRadialGradient(x, y, 0, x, y, r * 4);
      rg.addColorStop(0, `rgba(${col},${a * 0.5})`);
      rg.addColorStop(1, `rgba(${col},0)`);
      ctx.fillStyle = rg;
      ctx.beginPath(); ctx.arc(x, y, r * 4, 0, Math.PI * 2); ctx.fill();
    }
    ctx.fillStyle = `rgba(${col},${a})`;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  }
  for (let i = 0; i < 7; i++) {
    const x = random(160, 1440), y = random(200, 1500), r = random(12, 30);
    const rg = ctx.createRadialGradient(x, y, 0, x, y, r);
    rg.addColorStop(0, 'rgba(255,200,120,0.06)');
    rg.addColorStop(0.7, 'rgba(255,200,120,0.03)');
    rg.addColorStop(1, 'rgba(255,200,120,0)');
    ctx.fillStyle = rg;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  }
}

// ---------- film grain ----------
function grain(ctx) {
  for (let i = 0; i < 5200; i++) {
    const x = random(1600), y = random(2000);
    ctx.fillStyle = random() < 0.86
      ? `rgba(255,235,200,${random(0.015, 0.06)})`
      : `rgba(0,0,0,${random(0.03, 0.10)})`;
    ctx.fillRect(x, y, random() < 0.5 ? 1 : 2, 1);
  }
}

// ---------- vignette ----------
function vignette(ctx) {
  let rg = ctx.createRadialGradient(800, 920, 560, 800, 980, 1450);
  rg.addColorStop(0, 'rgba(6,4,10,0)');
  rg.addColorStop(1, 'rgba(6,4,10,0.6)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, 1600, 2000);

  let lg = ctx.createLinearGradient(0, 0, 0, 2000);
  lg.addColorStop(0, 'rgba(4,2,8,0.35)');
  lg.addColorStop(0.18, 'rgba(4,2,8,0)');
  lg.addColorStop(0.85, 'rgba(4,2,8,0)');
  lg.addColorStop(1, 'rgba(4,2,8,0.5)');
  ctx.fillStyle = lg;
  ctx.fillRect(0, 0, 1600, 2000);
}

let cx = 800;
let halfW = new Array(2001).fill(0);

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  noLoop();

  buildProfile();
  paintBackground();
  paintAura();
  paintGround();
  paintVessel();
  paintRim();
  paintSeams();
  paintReflection();
  paintSparks();
  paintFinish();
}

function buildProfile() {
  const P = [
    [540, 128], [596, 150], [642, 145], [718, 161], [832, 206],
    [962, 318], [1092, 416], [1232, 464], [1372, 420],
    [1522, 338], [1648, 268], [1734, 242]
  ];
  const raw = [];
  for (let i = 1; i < P.length - 2; i++) {
    const p0 = P[i - 1], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2];
    for (let s = 0; s < 30; s++) {
      const t = s / 30, t2 = t * t, t3 = t2 * t;
      const y = 0.5 * (2 * p1[0] + (-p0[0] + p2[0]) * t +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      const w = 0.5 * (2 * p1[1] + (-p0[1] + p2[1]) * t +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      raw.push([y, w]);
    }
  }
  raw.push([P[P.length - 2][0], P[P.length - 2][1]]);
  raw.sort((a, b) => a[0] - b[0]);
  let j = 0;
  const y0 = Math.ceil(raw[0][0]), y1 = Math.floor(raw[raw.length - 1][0]);
  for (let y = y0; y <= y1; y++) {
    while (j < raw.length - 2 && raw[j + 1][0] < y) j++;
    const a = raw[j], b = raw[j + 1];
    const t = b[0] === a[0] ? 0 : constrain((y - a[0]) / (b[0] - a[0]), 0, 1);
    halfW[y] = lerp(a[1], b[1], t);
  }
}

function profW(y) {
  return halfW[Math.round(constrain(y, 0, 2000))] || 0;
}

function paintBackground() {
  const top = color(26, 14, 22);
  const bot = color(9, 5, 8);
  for (let y = 0; y < height; y += 2) {
    const t = y / height;
    stroke(lerpColor(top, bot, t * t * (3 - 2 * t)));
    strokeWeight(2.5);
    line(0, y, width, y + 1);
  }
  for (let i = 0; i < 1500; i++) {
    const x = random(width), y = random(height);
    const a = noise(x * 0.0011, y * 0.0011) * TWO_PI * 2;
    const len = random(40, 150);
    const r = random();
    stroke(r < 0.45 ? color(44, 24, 38, 9) : r < 0.8 ? color(74, 32, 40, 7) : color(14, 8, 13, 10));
    strokeWeight(random(7, 26));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
}

function paintAura() {
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 26; i++) {
    const x0 = random(-100, 420), y0 = random(-60, 260);
    stroke(255, 150, 70, random(2.5, 6));
    strokeWeight(random(18, 46));
    line(x0, y0, x0 + random(500, 760), y0 + random(560, 860));
  }
  for (let r = 90; r < 860; r += 5) {
    const t = r / 860;
    stroke(255, 138, 58, (15 * pow(1 - t, 1.7) + 0.6) * random(0.7, 1.25));
    strokeWeight(random(5, 9));
    ellipse(cx + random(-6, 6), 1170 + random(-6, 6), r * 2 * 0.9, r * 2);
  }
  for (let r = 40; r < 420; r += 6) {
    stroke(200, 60, 40, 5 * (1 - r / 420));
    strokeWeight(random(6, 12));
    ellipse(cx, 1620, r * 2 * 1.4, r * 2 * 0.6);
  }
  blendMode(BLEND);
}

function paintGround() {
  for (let y = 1730; y < height; y += 3) {
    const t = (y - 1730) / (height - 1730);
    stroke(lerpColor(color(34, 18, 24), color(11, 6, 9), t));
    strokeWeight(3.4);
    line(0, y, width, y + 1);
  }
  for (let i = 0; i < 60; i++) {
    const y = random(1732, 1990), x = random(-100, 1200);
    stroke(230, 160, 110, random(3, 8));
    strokeWeight(random(2, 5));
    line(x, y, x + random(200, 600), y);
  }
  noStroke();
  for (let i = 0; i < 34; i++) {
    const t = i / 34;
    fill(5, 2, 6, 7);
    ellipse(cx + random(-14, 14), 1742 + random(-4, 6), lerp(900, 320, t), lerp(150, 44, t));
  }
}

function paintVessel() {
  const yTop = 614, yBot = 1718;
  for (let y = yTop; y <= yBot; y += 3) {
    const w = profW(y);
    if (w < 30) continue;
    const left = cx - w, right = cx + w;
    let x = left;
    while (x < right - 4) {
      const seg = min(random(48, 100), right - x);
      stroke(potColor((x + seg * 0.5 - cx) / w, y));
      strokeWeight(random(2.8, 4.4));
      const jy = random(-1.4, 1.4);
      line(x, y + jy, x + seg, y + jy + random(-2, 2));
      x += seg;
    }
  }
  for (let i = 0; i < 46; i++) {
    const ys = random(650, 1560);
    const x = cx + random(-0.85, 0.85) * profW(ys);
    stroke(random() < 0.4 ? color(235, 150, 120, 10) : color(24, 8, 14, 12));
    strokeWeight(random(5, 14));
    line(x, ys, x + random(-16, 16), ys + random(120, 340));
  }
  for (let y = yTop; y <= yBot; y += 4) {
    const w = profW(y);
    if (w < 30) continue;
    stroke(8, 3, 8, 60); strokeWeight(3);
    line(cx - w - 2, y, cx - w - 2, y + 4);
    line(cx + w + 2, y, cx + w + 2, y + 4);
    stroke(255, 150, 90, 14); strokeWeight(2.4);
    line(cx - w + 3, y, cx - w + 3, y + 4);
  }
  noStroke();
  fill(30, 11, 17, 180);
  ellipse(cx, 1720, profW(1716) * 2 + 8, 34);
}

function potColor(nx, y) {
  const highlight = Math.exp(-Math.pow((nx + 0.34) / 0.52, 2));
  const refl = 0.16 * Math.exp(-Math.pow((nx - 0.82) / 0.22, 2));
  const edge = Math.pow(Math.abs(nx), 3) * 0.5;
  const band = Math.sin(y * 0.045 + noise(y * 0.013) * 5) * 0.06;
  const vert = map(y, 614, 1718, 0.10, -0.10);
  let t = constrain(0.30 + highlight * 0.58 + refl - edge + band + vert +
    (noise(nx * 2.1 + 7, y * 0.012) - 0.5) * 0.12, 0, 1);
  const c1 = [42, 14, 24], c2 = [116, 36, 42], c3 = [219, 122, 96];
  let r, g, b;
  if (t < 0.5) {
    const u = t * 2;
    r = lerp(c1[0], c2[0], u); g = lerp(c1[1], c2[1], u); b = lerp(c1[2], c2[2], u);
  } else {
    const u = (t - 0.5) * 2;
    r = lerp(c2[0], c3[0], u); g = lerp(c2[1], c3[1], u); b = lerp(c2[2], c3[2], u);
  }
  return color(r, g, b, 238);
}

function paintRim() {
  noStroke();
  fill(20, 8, 12);
  ellipse(cx, 616, 292, 54);
  blendMode(ADD);
  glow(800, 618, 46, [255, 140, 60], 60);
  glow(800, 618, 18, [255, 200, 120], 90);
  blendMode(BLEND);
  noFill();
  stroke(214, 128, 100, 170); strokeWeight(4.4);
  arc(cx, 616, 296, 56, PI * 1.02, TWO_PI - 0.02);
  stroke(96, 30, 34, 190); strokeWeight(4);
  arc(cx, 616, 296, 56, 0.05, PI - 0.05);
}

function glow(x, y, rad, col, a0) {
  noStroke();
  for (let r = rad; r > 0.5; r -= rad / 14) {
    const t = r / rad;
    fill(col[0], col[1], col[2], a0 * (1 - t) * (1 - t) + a0 * 0.06);
    ellipse(x, y, r * 2, r * 2);
  }
}

function crackPath(x0, y0, steps, stepLen, ang0, bias) {
  const pts = [];
  let x = x0, y = y0;
  for (let i = 0; i <= steps; i++) {
    pts.push([x, y]);
    const n = noise(x * 0.006, y * 0.006);
    let a = ang0 + (n - 0.5) * 1.5 + bias * (i / steps);
    let nx = x + cos(a) * stepLen;
    let ny = y + sin(a) * stepLen;
    const wl = profW(ny);
    if (wl < 20 || Math.abs(nx - cx) > wl * 0.93 || ny > 1712) {
      a = Math.atan2(1200 - y, cx - x);
      nx = x + cos(a) * stepLen;
      ny = y + sin(a) * stepLen;
      if (ny > 1712) break;
    }
    x = nx; y = ny;
  }
  return pts;
}

function drawSeam(pts, wCore) {
  noFill();
  stroke(16, 6, 10, 210); strokeWeight(wCore + 5);
  poly(pts, 1.5, 1.5);
  stroke(96, 62, 18, 235); strokeWeight(wCore + 2.4);
  poly(pts, 0, 0);
  const dc = drawingContext;
  dc.shadowColor = 'rgba(255,196,90,0.85)';
  dc.shadowBlur = 22;
  stroke(216, 168, 74, 255); strokeWeight(wCore);
  poly(pts, 0, 0);
  dc.shadowBlur = 8;
  stroke(255, 230, 150, 230); strokeWeight(Math.max(1.2, wCore * 0.42));
  poly(pts, -0.6, -0.6);
  dc.shadowBlur = 0;
  blendMode(ADD);
  stroke(255, 170, 60, 16); strokeWeight(wCore + 12);
  poly(pts, 0, 0);
  blendMode(BLEND);
}

function poly(pts, ox, oy) {
  beginShape();
  for (const p of pts) vertex(p[0] + ox, p[1] + oy);
  endShape();
}

function goldPatch(x, y, rad) {
  const dc = drawingContext;
  dc.shadowColor = 'rgba(255,196,90,0.9)';
  dc.shadowBlur = 20;
  noStroke();
  fill(196, 142, 58);
  beginShape();
  for (let a = 0; a < TWO_PI; a += TWO_PI / 14) {
    const r = rad * (0.7 + noise(x * 0.05 + cos(a) * 2, y * 0.05 + sin(a) * 2) * 0.7);
    vertex(x + cos(a) * r, y + sin(a) * r * 0.8);
  }
  endShape(CLOSE);
  fill(255, 228, 150);
  ellipse(x - rad * 0.15, y - rad * 0.15, rad * 0.9, rad * 0.7);
  dc.shadowBlur = 0;
}

function paintSeams() {
  const seams = [
    crackPath(742, 620, 86, 13, HALF_PI, 0.10),
    crackPath(874, 624, 46, 13, HALF_PI, -0.30),
    crackPath(756, 1006, 34, 15, 0.12, 0.05),
    crackPath(700, 1420, 16, 9, HALF_PI + 0.4, 0),
    crackPath(920, 1260, 14, 9, HALF_PI - 0.5, 0),
    crackPath(830, 840, 12, 8, -0.4, 0)
  ];
  for (const s of seams) drawSeam(s, s.length > 40 ? 5 : 3.4);
  goldPatch(756, 1006, 26);
  goldPatch(874, 640, 18);
  goldPatch(806, 1700, 22);
}

function paintReflection() {
  for (let i = 0; i < 30; i++) {
    const x = cx + random(-250, 250);
    stroke(random() < 0.7 ? color(180, 70, 60, random(16, 30)) : color(60, 22, 30, random(18, 30)));
    strokeWeight(random(4, 9));
    line(x, 1736, x + random(-8, 8), 1736 + random(36, 120));
  }
  for (let i = 0; i < 7; i++) {
    const x = cx + random(-160, 160);
    stroke(230, 180, 90, random(10, 22));
    strokeWeight(random(2, 4));
    line(x, 1738, x + random(-4, 4), 1738 + random(26, 70));
  }
}

function paintSparks() {
  blendMode(ADD);
  for (let i = 0; i < 130; i++) {
    let x, y;
    if (random() < 0.6) {
      x = cx + randomGaussian(0, 300);
      y = 1120 + randomGaussian(0, 320);
    } else {
      x = random(160, 1440);
      y = random(280, 1780);
    }
    glow(x, y, random(1.2, 4.6), [255, 190, 90], random(20, 70));
  }
  for (let i = 0; i < 7; i++) {
    const t = i / 6;
    glow(lerp(908, 958, t) + random(-8, 8), lerp(600, 512, t) + random(-8, 8),
      lerp(2.5, 4.5, t), [255, 200, 110], 40 + t * 30);
  }
  glow(958, 504, 9, [255, 214, 130], 200);
  glow(958, 504, 22, [255, 160, 70], 60);
  glow(1004, 542, 7, [255, 214, 130], 190);
  glow(1004, 542, 17, [255, 160, 70], 55);
  blendMode(BLEND);
}

function paintFinish() {
  noFill();
  for (let i = 0; i < 110; i++) {
    const t = i / 110;
    const a = 96 * pow(1 - t, 2.2);
    const d = t * 330;
    stroke(6, 3, 8, a);
    strokeWeight(5);
    line(d, 0, d, height);
    line(width - d, 0, width - d, height);
    line(0, d, width, d);
    line(0, height - d, width, height - d);
  }
  noStroke();
  for (let i = 0; i < 24; i++) {
    fill(5, 2, 7, 5);
    ellipse(random() < 0.5 ? 0 : width, random() < 0.5 ? 0 : height, random(700, 1100));
  }
  for (let i = 0; i < 13000; i++) {
    const x = random(width), y = random(height);
    if (random() < 0.5) fill(255, 236, 214, random(2.5, 8));
    else fill(8, 4, 9, random(4, 12));
    rect(x, y, random() < 0.85 ? 1 : 2, 1);
  }
}

let boughs = [];
let dabs = [];
let leafPalettes = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  smooth();
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  leafPalettes = [
    [
      color(36, 78, 91),
      color(45, 108, 111),
      color(74, 137, 128),
      color(111, 157, 139),
      color(62, 83, 111),
      color(206, 165, 96)
    ],
    [
      color(102, 42, 65),
      color(145, 55, 68),
      color(180, 76, 73),
      color(203, 111, 82),
      color(218, 145, 94),
      color(233, 185, 112)
    ]
  ];

  paintBackground();
  paintSharedLight();

  makeTree(410, 1650, 360, -1.36, 108, 8, 0);
  makeTree(1190, 1650, 360, -1.79, 108, 8, 1);
  makeTree(455, 1450, 230, -2.05, 42, 5, 0);
  makeTree(1145, 1450, 230, -1.10, 42, 5, 1);
  makeTree(500, 1310, 230, -0.88, 38, 5, 0);
  makeTree(1100, 1310, 230, -2.26, 38, 5, 1);

  paintRoots();
  paintCanopyHaze();

  for (let d of dabs) {
    if (!d.front) paintDab(d);
  }

  paintBoughs();

  for (let d of dabs) {
    if (d.front) paintDab(d);
  }

  paintPollen();
  paintSurface();
}

function paintBackground() {
  let top = color(13, 17, 34);
  let bottom = color(39, 20, 38);

  for (let y = 0; y <= height; y += 4) {
    let c = lerpColor(top, bottom, y / height);
    stroke(c);
    strokeWeight(5);
    line(0, y, width, y);
  }

  noStroke();
  for (let r = 900; r > 80; r -= 12) {
    fill(119, 59, 75, 1.6);
    ellipse(800, 760, r * 1.65, r * 1.35);
  }

  let washes = [
    color(70, 76, 105),
    color(116, 67, 87),
    color(43, 86, 94),
    color(151, 91, 75),
    color(202, 151, 105)
  ];

  for (let i = 0; i < 2700; i++) {
    let x = random(-100, width);
    let y = random(height);
    let len = random(25, 180);
    let c = random(washes);
    let drift = (noise(x * 0.002, y * 0.002) - 0.5) * 32;

    stroke(red(c), green(c), blue(c), random(4, 16));
    strokeWeight(random(1, 7));
    noFill();
    bezier(
      x, y,
      x + len * 0.3, y + drift,
      x + len * 0.7, y - drift * 0.4,
      x + len, y + random(-8, 8)
    );
  }
}

function paintSharedLight() {
  noStroke();

  for (let r = 560; r > 312; r -= 5) {
    fill(232, 165, 94, 2.2);
    ellipse(800, 650, r * 2.05, r * 2.05);
  }

  let core = color(250, 231, 184);
  let edge = color(211, 157, 103);

  for (let r = 318; r > 0; r -= 2) {
    let c = lerpColor(core, edge, r / 318);
    fill(c);
    ellipse(800, 650, r * 2, r * 2);
  }

  let moonMarks = [
    color(255, 242, 203),
    color(183, 120, 88),
    color(228, 183, 124),
    color(246, 213, 159)
  ];

  for (let i = 0; i < 1750; i++) {
    let a = random(TWO_PI);
    let r = 312 * sqrt(random());
    let x = 800 + cos(a) * r;
    let y = 650 + sin(a) * r;
    let len = random(2, 22);
    let c = random(moonMarks);

    stroke(red(c), green(c), blue(c), random(8, 34));
    strokeWeight(random(1, 5));
    line(x - len * 0.5, y, x + len * 0.5, y + random(-3, 3));
  }

  noFill();
  for (let i = 0; i < 6; i++) {
    stroke(236, 193, 123, 16 - i);
    strokeWeight(1.2);
    arc(
      800, 650,
      730 + i * 58, 730 + i * 58,
      -2.85 + i * 0.12,
      -0.28 + i * 0.08
    );
  }
}

function makeTree(x, y, len, ang, w, depth, side) {
  let nx = -sin(ang);
  let ny = cos(ang);
  let bend = random(-0.18, 0.18) * len;
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;

  let b = {
    x: x,
    y: y,
    c1x: x + cos(ang) * len * 0.34 + nx * bend,
    c1y: y + sin(ang) * len * 0.34 + ny * bend,
    c2x: x + cos(ang) * len * 0.73 - nx * bend * 0.6,
    c2y: y + sin(ang) * len * 0.73 - ny * bend * 0.6,
    x2: x2,
    y2: y2,
    w: w,
    ang: ang,
    side: side
  };
  boughs.push(b);

  if (depth === 0 || len < 24) {
    let count = int(random(15, 27));
    let spread = random(25, 48);

    for (let i = 0; i < count; i++) {
      let lx = x2 + randomGaussian() * spread;
      let ly = y2 + randomGaussian() * spread * 0.72;
      let dx = (lx - 800) / 285;
      let dy = (ly - 650) / 300;

      if (dx * dx + dy * dy < 0.82 && random() < 0.94) continue;

      let tone = floor(random(leafPalettes[side].length - 1));
      if (random() < 0.055) tone = leafPalettes[side].length - 1;

      dabs.push({
        x: lx,
        y: ly,
        side: side,
        tone: tone,
        s: random(2.5, 8.5),
        l: random(7, 24),
        a: ang + random(-1.4, 1.4),
        alpha: random(95, 205),
        front: random() < 0.3
      });
    }
    return;
  }

  let children = depth > 4 && random() < 0.16 ? 3 : 2;

  for (let j = 0; j < children; j++) {
    let direction = children === 2 ? (j === 0 ? -1 : 1) : j - 1;
    let spread = children === 2 ? random(0.28, 0.62) : random(0.28, 0.55);
    let nextAngle = ang + direction * spread + random(-0.16, 0.16);

    nextAngle = lerp(nextAngle, -HALF_PI, 0.08);
    nextAngle = constrain(nextAngle, -2.72, -0.42);

    makeTree(
      x2,
      y2,
      len * random(0.65, 0.78),
      nextAngle,
      w * random(0.59, 0.71),
      depth - 1,
      side
    );
  }
}

function paintCanopyHaze() {
  noStroke();

  for (let i = 0; i < dabs.length; i += 11) {
    let d = dabs[i];
    let c = leafPalettes[d.side][d.tone];
    fill(red(c), green(c), blue(c), 8);
    ellipse(d.x, d.y, d.s * 6, d.s * 4);
  }
}

function paintDab(d) {
  let c = leafPalettes[d.side][d.tone];
  let alpha = d.front ? d.alpha : d.alpha * 0.58;
  let dx = cos(d.a) * d.l * 0.5;
  let dy = sin(d.a) * d.l * 0.5;

  stroke(red(c), green(c), blue(c), alpha);
  strokeWeight(d.s);
  line(d.x - dx, d.y - dy, d.x + dx, d.y + dy);

  if (d.front && d.s > 6) {
    stroke(245, 213, 153, alpha * 0.12);
    strokeWeight(max(0.7, d.s * 0.16));
    line(d.x - dx * 0.7, d.y - dy * 0.7, d.x + dx * 0.7, d.y + dy * 0.7);
  }
}

function paintBoughs() {
  noFill();

  for (let b of boughs) {
    let t = constrain(1 - b.w / 110, 0, 1);
    let base = b.side === 0 ? color(22, 43, 57) : color(67, 31, 49);
    let tip = b.side === 0 ? color(75, 123, 117) : color(157, 76, 75);
    let c = lerpColor(base, tip, pow(t, 0.65));

    stroke(7, 11, 23, 145);
    strokeWeight(b.w * 1.12 + 3);
    bezier(b.x, b.y, b.c1x, b.c1y, b.c2x, b.c2y, b.x2, b.y2);

    stroke(red(c), green(c), blue(c), 238);
    strokeWeight(b.w);
    bezier(b.x, b.y, b.c1x, b.c1y, b.c2x, b.c2y, b.x2, b.y2);

    let off = b.w * 0.18;
    let ox = -sin(b.ang) * off;
    let oy = cos(b.ang) * off;

    if (b.side === 0) {
      stroke(166, 194, 164, 42);
    } else {
      stroke(238, 174, 121, 39);
    }

    strokeWeight(max(0.65, b.w * 0.065));
    bezier(
      b.x + ox, b.y + oy,
      b.c1x + ox, b.c1y + oy,
      b.c2x + ox, b.c2y + oy,
      b.x2 + ox, b.y2 + oy
    );

    if (b.w > 24) {
      stroke(8, 16, 26, 35);
      strokeWeight(max(1, b.w * 0.045));
      bezier(
        b.x - ox * 1.5, b.y - oy * 1.5,
        b.c1x - ox, b.c1y - oy,
        b.c2x - ox * 0.5, b.c2y - oy * 0.5,
        b.x2, b.y2
      );
    }
  }
}

function paintRoots() {
  noStroke();

  for (let i = 0; i < 14; i++) {
    fill(5, 9, 20, 9);
    ellipse(800, 1740, 1500 - i * 28, 410 - i * 10);
  }

  for (let i = 0; i < 38; i++) {
    for (let side = 0; side < 2; side++) {
      let baseX = side === 0 ? 410 : 1190;
      let outward = i < 15;
      let sx = baseX + random(-48, 48);
      let sy = 1628 + random(-18, 42);
      let ex;

      if (outward) {
        ex = side === 0 ? random(30, 720) : random(880, 1570);
      } else {
        ex = side === 0 ? random(610, 970) : random(630, 990);
      }

      let ey = random(1790, 2070);
      let c1x;

      if (outward) {
        c1x = sx + random(-190, 190);
      } else {
        c1x = sx + (side === 0 ? 1 : -1) * random(40, 180);
      }

      let p0 = { x: sx, y: sy };
      let p1 = { x: c1x, y: sy + random(80, 230) };
      let p2 = { x: ex + random(-170, 170), y: ey - random(100, 260) };
      let p3 = { x: ex, y: ey };
      let previous = p0;
      let rootWidth = outward ? random(6, 19) : random(3, 12);
      let rc = side === 0 ? color(52, 105, 108) : color(157, 77, 73);

      if (i % 9 === 0) rc = color(164, 125, 79);

      for (let j = 1; j <= 28; j++) {
        let t = j / 28;
        let p = cubicPoint(p0, p1, p2, p3, t);
        let sw = max(0.7, rootWidth * (1 - t) + 0.5);

        stroke(6, 10, 20, 155);
        strokeWeight(sw + 2.4);
        line(previous.x, previous.y, p.x, p.y);

        stroke(red(rc), green(rc), blue(rc), 175 * (1 - t) + 42);
        strokeWeight(sw);
        line(previous.x, previous.y, p.x, p.y);

        if (i % 3 === 0) {
          stroke(224, 183, 120, 28);
          strokeWeight(max(0.45, sw * 0.17));
          line(previous.x, previous.y - 1, p.x, p.y - 1);
        }

        previous = p;
      }
    }
  }

  noStroke();
  for (let r = 100; r > 10; r -= 8) {
    fill(225, 160, 86, 1.8);
    ellipse(800, 1810, r * 2, r * 0.85);
  }

  fill(244, 207, 137, 175);
  ellipse(800, 1805, 8, 15);
}

function cubicPoint(p0, p1, p2, p3, t) {
  let u = 1 - t;
  return {
    x: u * u * u * p0.x +
       3 * u * u * t * p1.x +
       3 * u * t * t * p2.x +
       t * t * t * p3.x,
    y: u * u * u * p0.y +
       3 * u * u * t * p1.y +
       3 * u * t * t * p2.y +
       t * t * t * p3.y
  };
}

function paintPollen() {
  noStroke();

  for (let i = 0; i < 105; i++) {
    let a = random(TWO_PI);
    let r = random(320, 510);
    let x = 800 + cos(a) * r * 0.88;
    let y = 650 + sin(a) * r;
    let s = random(1, 4.5);

    fill(239, 194, 116, random(35, 145));
    ellipse(x, y, s, s);
  }

  for (let i = 0; i < 38; i++) {
    let y = random(900, 1580);
    let x = 800 + randomGaussian() * map(y, 900, 1580, 75, 35);
    let s = random(1, 3.5);

    fill(237, 188, 111, random(25, 105));
    ellipse(x, y, s, s);
  }
}

function paintSurface() {
  for (let i = 0; i < 6200; i++) {
    let x = random(width);
    let y = random(height);

    if (random() < 0.5) {
      stroke(246, 222, 184, random(2, 8));
    } else {
      stroke(3, 6, 16, random(3, 10));
    }

    strokeWeight(random(0.4, 1.2));
    point(x, y);
  }

  noFill();
  for (let i = 0; i < 34; i++) {
    stroke(5, 7, 18, 3);
    strokeWeight(18);
    rect(i * 3, i * 3, width - i * 6, height - i * 6, 24);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  angleMode(RADIANS);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  paintSky();
  paintHalo();
  paintEarth();
  paintRoots();
  paintCanopyMist();

  paintBranch(700, 670, 230, -1.38, 7, 0);
  paintBranch(900, 670, 230, -1.76, 7, 1);

  drawTrunk(0);
  drawTrunk(1);
  sharedLight();
  surfaceGrain();
}

function rgba(c, a) {
  return color(red(c), green(c), blue(c), a);
}

function paintSky() {
  let top = color(16, 25, 43);
  let middle = color(52, 43, 59);
  let horizon = color(111, 68, 69);

  for (let y = 0; y < height; y += 3) {
    let t = constrain(y / 1450, 0, 1);
    let c;
    if (t < 0.64) {
      c = lerpColor(top, middle, t / 0.64);
    } else {
      c = lerpColor(middle, horizon, (t - 0.64) / 0.36);
    }
    stroke(c);
    strokeWeight(4);
    line(0, y, width, y);
  }

  for (let i = 0; i < 650; i++) {
    let x = random(-180, width);
    let y = random(0, 1450);
    let c = random() < 0.5 ? color(126, 100, 112) : color(42, 74, 91);
    stroke(rgba(c, random(3, 10)));
    strokeWeight(random(8, 42));
    noFill();
    bezier(
      x, y,
      x + random(40, 160), y + random(-22, 22),
      x + random(160, 320), y + random(-22, 22),
      x + random(260, 520), y + random(-12, 12)
    );
  }
}

function paintHalo() {
  let ctx = drawingContext;

  let halo = ctx.createRadialGradient(800, 570, 20, 800, 570, 650);
  halo.addColorStop(0, "rgba(247,201,137,0.29)");
  halo.addColorStop(0.42, "rgba(231,166,117,0.14)");
  halo.addColorStop(1, "rgba(220,145,110,0)");
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, width, 1300);

  noStroke();
  fill(238, 188, 123, 12);
  circle(800, 560, 690);
  fill(246, 205, 147, 10);
  circle(800, 560, 550);

  let passage = ctx.createRadialGradient(800, 1110, 10, 800, 1110, 520);
  passage.addColorStop(0, "rgba(237,177,111,0.14)");
  passage.addColorStop(0.55, "rgba(209,137,99,0.055)");
  passage.addColorStop(1, "rgba(209,137,99,0)");
  ctx.fillStyle = passage;
  ctx.fillRect(240, 570, 1120, 900);
}

function paintEarth() {
  noStroke();
  fill(14, 22, 31);
  beginShape();
  vertex(0, 1445);
  for (let x = 0; x <= width; x += 25) {
    let y = 1435 + noise(x * 0.004, 4) * 48 + sin(x * 0.006) * 9;
    vertex(x, y);
  }
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  let soilColors = [
    color(91, 65, 66),
    color(47, 63, 72),
    color(128, 88, 72),
    color(38, 49, 60)
  ];

  for (let i = 0; i < 1100; i++) {
    let x = random(-60, width);
    let y = random(1460, height);
    let len = random(20, 260);
    let c = random(soilColors);
    stroke(rgba(c, random(8, 30)));
    strokeWeight(random(1, 7));
    line(x, y, x + len, y + random(-5, 5));
  }
}

function taperedCurve(x0, y0, x1, y1, x2, y2, x3, y3, c, w, alpha = 160) {
  let steps = 46;
  for (let j = 0; j < steps; j++) {
    let t = j / steps;
    let u = (j + 1) / steps;
    let ax = bezierPoint(x0, x1, x2, x3, t);
    let ay = bezierPoint(y0, y1, y2, y3, t);
    let bx = bezierPoint(x0, x1, x2, x3, u);
    let by = bezierPoint(y0, y1, y2, y3, u);
    stroke(rgba(c, alpha * (1 - t * 0.35)));
    strokeWeight(w * pow(1 - t, 1.35) + 0.35);
    line(ax, ay, bx, by);
  }
}

function paintRoots() {
  for (let side = 0; side < 2; side++) {
    let baseColor = side === 0 ? color(160, 86, 74) : color(64, 124, 126);

    for (let i = 0; i < 24; i++) {
      let inward = i < 13;
      let x0 = side === 0 ? random(500, 615) : random(985, 1100);
      let y0 = random(1435, 1490);
      let ex;

      if (side === 0) {
        ex = inward ? random(720, 985) : random(150, 500);
      } else {
        ex = inward ? random(615, 880) : random(1100, 1450);
      }

      let ey = random(1630, 1960);
      let cx1 = x0 + random(-105, 105);
      let cy1 = y0 + random(65, 155);
      let cx2 = ex + random(-140, 140);
      let cy2 = ey - random(80, 240);
      let c = lerpColor(baseColor, color(199, 151, 99), random(0, 0.25));
      let w = random(6, 19);

      taperedCurve(x0, y0, cx1, cy1, cx2, cy2, ex, ey, c, w, random(85, 155));

      if (random() < 0.8) {
        let t = random(0.35, 0.7);
        let px = bezierPoint(x0, cx1, cx2, ex, t);
        let py = bezierPoint(y0, cy1, cy2, ey, t);
        let rx = px + random(-95, 95);
        let ry = py + random(45, 125);
        taperedCurve(
          px, py,
          px + random(-25, 25), py + 25,
          rx + random(-35, 35), ry - 20,
          rx, ry,
          c, random(1.5, 4), 85
        );
      }
    }
  }

  let gold = color(209, 162, 105);
  for (let i = 0; i < 16; i++) {
    let side = i % 2;
    let x0 = side === 0 ? random(535, 600) : random(1000, 1065);
    let y0 = random(1450, 1490);
    let ex = random(690, 910);
    let ey = random(1700, 1940);
    let cx1 = side === 0 ? random(590, 760) : random(840, 1010);
    let cx2 = side === 0 ? random(720, 940) : random(660, 880);

    taperedCurve(
      x0, y0,
      cx1, random(1530, 1650),
      cx2, ey - random(90, 220),
      ex, ey,
      gold, random(2, 5.5), 105
    );
  }
}

function paintCanopyMist() {
  let leftColors = [
    color(160, 75, 74),
    color(200, 112, 88),
    color(126, 76, 91)
  ];
  let rightColors = [
    color(48, 106, 111),
    color(77, 132, 126),
    color(91, 99, 132)
  ];

  for (let i = 0; i < 1000; i++) {
    let side = random() < 0.5 ? 0 : 1;
    let x = randomGaussian(side === 0 ? 590 : 1010, 230);
    let y = randomGaussian(500, 180);
    if (y < 60 || y > 860) continue;

    let c = random(side === 0 ? leftColors : rightColors);
    let meeting = constrain(1 - abs(x - 800) / 390, 0, 1);
    c = lerpColor(c, color(220, 166, 105), meeting * 0.42);

    push();
    translate(x, y);
    rotate(random(-PI, PI));
    noStroke();
    fill(rgba(c, random(5, 16)));
    ellipse(0, 0, random(70, 210), random(30, 100));
    pop();
  }
}

function upwardAngle(a) {
  return constrain(a, -PI + 0.1, -0.1);
}

function paintBranch(x, y, len, a, depth, side) {
  let aa = a + random(-0.16, 0.16);
  let ex = x + cos(aa) * len;
  let ey = y + sin(aa) * len;
  let mx = (x + ex) * 0.5 + random(-18, 18);
  let my = (y + ey) * 0.5 + random(-12, 12);

  let base = side === 0 ? color(126, 67, 65) : color(38, 82, 92);
  let tip = side === 0 ? color(211, 128, 96) : color(96, 153, 146);
  let tipMix = map(depth, 0, 7, 1, 0);
  let bc = lerpColor(base, tip, tipMix);

  let warmth = constrain(1 - abs((x + ex) * 0.5 - 800) / 320, 0, 1) * 0.45;
  bc = lerpColor(bc, color(215, 163, 103), warmth * (1 - depth / 10));

  let w = map(depth, 0, 7, 1.1, 26);

  noFill();
  stroke(10, 18, 27, 100);
  strokeWeight(w + 3);
  bezier(x, y, mx, my, mx, my, ex, ey);

  stroke(rgba(bc, 225));
  strokeWeight(w);
  bezier(x, y, mx, my, mx, my, ex, ey);

  let highlight = lerpColor(bc, color(240, 205, 150), 0.35);
  stroke(rgba(highlight, 80));
  strokeWeight(max(0.6, w * 0.18));
  bezier(x + 1, y, mx + 1, my, mx + 1, my, ex, ey);

  if (depth <= 2 && (depth <= 1 || random() < 0.5)) {
    leafCluster(ex, ey, len * 0.8 + 10, side, depth);
  }

  if (depth > 0) {
    let spread = depth > 4 ? random(0.34, 0.62) : random(0.25, 0.52);
    let a1 = upwardAngle(aa - spread * random(0.8, 1.2));
    let a2 = upwardAngle(aa + spread * random(0.8, 1.2));

    paintBranch(ex, ey, len * random(0.69, 0.79), a1, depth - 1, side);
    paintBranch(ex, ey, len * random(0.69, 0.79), a2, depth - 1, side);

    if (depth > 3 && random() < 0.16) {
      paintBranch(
        ex, ey,
        len * 0.62,
        upwardAngle(aa + random(-0.12, 0.12)),
        depth - 1,
        side
      );
    }
  }
}

function leafCluster(x, y, r, side, depth) {
  let palette = side === 0 ? [
    [190, 93, 80],
    [218, 132, 94],
    [226, 160, 107],
    [139, 78, 91]
  ] : [
    [55, 116, 116],
    [83, 144, 132],
    [126, 161, 144],
    [96, 107, 140]
  ];

  let n = depth === 0 ? int(random(8, 15)) : int(random(4, 9));

  for (let i = 0; i < n; i++) {
    let ang = random(TWO_PI);
    let rad = r * sqrt(random());
    let px = x + cos(ang) * rad * 1.25;
    let py = y + sin(ang) * rad * 0.75;
    let rgb = random(palette);
    let c = color(rgb[0], rgb[1], rgb[2]);

    let meeting = constrain(1 - abs(px - 800) / 340, 0, 1);
    meeting *= constrain((950 - py) / 350, 0, 1);
    if (random() < meeting * 0.85) {
      c = lerpColor(c, color(238, 190, 113), meeting * 0.85);
    }

    let ll = random(14, 36);
    let ww = random(5, 14);

    push();
    translate(px, py);
    rotate(random(-PI, PI));
    noStroke();
    fill(rgba(c, random(95, 195)));
    ellipse(0, 0, ll, ww);

    if (random() < 0.28) {
      let hc = lerpColor(c, color(248, 213, 155), 0.35);
      fill(rgba(hc, 55));
      ellipse(2, -1, ll * 0.55, ww * 0.45);
    }
    pop();
  }
}

function drawTrunk(side) {
  let base = side === 0 ? color(125, 65, 64) : color(40, 80, 90);
  let light = side === 0 ? color(218, 132, 102) : color(112, 172, 165);
  let shadow = side === 0 ? color(61, 42, 53) : color(24, 48, 62);

  push();
  if (side === 1) {
    translate(width, 0);
    scale(-1, 1);
  }

  noStroke();
  fill(base);
  beginShape();
  vertex(455, 1485);
  bezierVertex(490, 1320, 475, 1190, 540, 1030);
  bezierVertex(590, 900, 665, 790, 665, 660);
  bezierVertex(665, 625, 700, 605, 733, 635);
  bezierVertex(745, 760, 690, 905, 650, 1040);
  bezierVertex(600, 1200, 630, 1360, 670, 1485);
  bezierVertex(600, 1510, 520, 1510, 455, 1485);
  endShape(CLOSE);

  for (let i = 0; i < 84; i++) {
    let o = random(-62, 62);
    let baseX = 560 + o * 1.35;
    let endX = 700 + o * 0.26;
    let c = random([base, light, shadow]);

    noFill();
    stroke(rgba(c, random(25, 78)));
    strokeWeight(random(1, 7));
    bezier(
      baseX, random(1460, 1510),
      510 + o * 0.9, random(1220, 1320),
      650 + o * 0.45, random(850, 960),
      endX, random(660, 735)
    );
  }

  noFill();
  stroke(rgba(light, 105));
  strokeWeight(5);
  bezier(650, 1460, 600, 1210, 705, 900, 731, 650);

  stroke(rgba(shadow, 125));
  strokeWeight(9);
  bezier(474, 1460, 505, 1240, 520, 1070, 668, 675);

  for (let i = 0; i < 9; i++) {
    let y = random(820, 1390);
    let x = map(y, 650, 1490, 700, 560) + random(-38, 38);
    stroke(rgba(light, random(25, 55)));
    strokeWeight(random(1, 3));
    bezier(x - 14, y, x - 4, y - 8, x + 8, y + 8, x + 20, y - 2);
  }

  pop();
}

function sharedLight() {
  noStroke();

  for (let i = 0; i < 240; i++) {
    let x = randomGaussian(800, 150);
    let y = randomGaussian(475, 180);
    if (y < 70 || y > 800) continue;

    let c = lerpColor(color(226, 164, 100), color(249, 213, 146), random());
    fill(rgba(c, random(30, 115)));
    push();
    translate(x, y);
    rotate(random(-PI, PI));
    ellipse(0, 0, random(5, 22), random(2, 8));
    pop();
  }

  for (let i = 0; i < 90; i++) {
    let y = random(760, 1410);
    let spread = 35 + (y - 760) * 0.09;
    let x = randomGaussian(800, spread);
    let a = map(y, 760, 1410, 95, 15);
    fill(232, 184, 117, a);
    ellipse(x, y, random(2, 8), random(2, 6));
  }
}

function surfaceGrain() {
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let y = random(height);
    let warm = random() < 0.5;
    stroke(
      warm ? 238 : 108,
      warm ? 205 : 135,
      warm ? 164 : 151,
      random(2, 8)
    );
    strokeWeight(random(0.5, 2.2));
    line(x, y, x + random(-35, 35), y + random(-3, 3));
  }

  for (let i = 0; i < 18000; i++) {
    let v = random() < 0.5 ? 235 : 5;
    stroke(v, random(2, 7));
    strokeWeight(random(0.4, 1.5));
    point(random(width), random(height));
  }

  let ctx = drawingContext;
  let vignette = ctx.createRadialGradient(800, 850, 500, 800, 900, 1260);
  vignette.addColorStop(0, "rgba(5,8,15,0)");
  vignette.addColorStop(0.72, "rgba(5,8,15,0.08)");
  vignette.addColorStop(1, "rgba(5,8,15,0.48)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
