  );
  drawHead(
    950, 435, -1, -0.03,
    color(220, 176, 126),
    color(145, 99, 79)
  );

  drawFlame();
  drawSparks();
  drawGrain();
}

function drawBackground() {
  background(20, 19, 32);

  const top = color(19, 20, 35);
  const bottom = color(54, 31, 45);

  for (let y = 0; y < height + 4; y += 4) {
    stroke(lerpColor(top, bottom, y / height));
    strokeWeight(5);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 240; i++) {
    const x = random(-100, width + 100);
    const y = random(-100, height + 100);
    const r = random(70, 340);
    fill(
      random(65, 105),
      random(43, 76),
      random(65, 96),
      random(2, 7)
    );
    ellipse(x, y, r * random(1, 2.2), r);
  }

  for (let r = 720; r > 45; r -= 10) {
    const t = 1 - r / 720;
    fill(194, 119, 79, 1.4 + t * 1.1);
    ellipse(800, 900, r * 1.16, r * 1.36);
  }

  noFill();
  for (let i = 0; i < 6; i++) {
    stroke(209, 158, 98, 22 - i * 2);
    strokeWeight(i === 0 ? 3 : 1.2);
    roughEllipse(
      800, 960,
      655 + i * 10,
      855 + i * 8,
      i * 1.73
    );
  }

  for (let i = 0; i < 145; i++) {
    const x = random(90, 1510);
    const y = random(100, 1820);
    const d = dist(x, y, 800, 900);
    if (d > 430) {
      const r = random(0.8, 3.2);
      fill(224, 185, 124, random(18, 70));
      ellipse(x, y, r, r);
    }
  }
}

function roughEllipse(cx, cy, rx, ry, phase) {
  beginShape();
  for (let i = 0; i <= 180; i++) {
    const a = TWO_PI * i / 180;
    const wobble =
      1 +
      0.009 * sin(a * 5 + phase) +
      0.018 * (noise(cos(a) * 2 + phase, sin(a) * 2) - 0.5);
    vertex(
      cx + cos(a) * rx * wobble,
      cy + sin(a) * ry * wobble
    );
  }
  endShape(CLOSE);
}

function drawGroundAndRoots() {
  noStroke();
  for (let i = 0; i < 24; i++) {
    fill(8, 12, 24, 5);
    ellipse(800, 1770, 1380 - i * 35, 210 - i * 5);
  }

  for (let i = 0; i < 48; i++) {
    const fromLeft = i % 2 === 0;
    const x0 = fromLeft ? random(250, 730) : random(870, 1350);
    const x3 = fromLeft ? random(540, 1110) : random(490, 1060);
    const y0 = random(1610, 1740);
    const y3 = random(1810, 1930);

    noFill();
    if (i % 3 === 0) {
      stroke(211, 155, 88, random(35, 90));
    } else if (fromLeft) {
      stroke(76, 119, 127, random(25, 65));
    } else {
      stroke(174, 91, 94, random(25, 65));
    }

    strokeWeight(random(1, 4));
    bezier(
      x0, y0,
      x0 + random(-220, 220), random(1740, 1840),
      x3 + random(-220, 220), random(1760, 1900),
      x3, y3
    );

    if (i % 5 === 0) {
      noStroke();
      fill(218, 168, 99, 70);
      ellipse(x3, y3, random(3, 7), random(3, 7));
    }
  }
}

function leftRobePath() {
  const c = drawingContext;
  c.beginPath();
  c.moveTo(605, 610);
  c.bezierCurveTo(490, 625, 385, 700, 335, 835);
  c.bezierCurveTo(270, 1010, 250, 1240, 180, 1510);
  c.bezierCurveTo(160, 1590, 135, 1660, 110, 1720);
  c.bezierCurveTo(360, 1780, 610, 1770, 825, 1710);
  c.bezierCurveTo(765, 1560, 720, 1430, 725, 1290);
  c.bezierCurveTo(730, 1140, 800, 1050, 820, 920);
  c.bezierCurveTo(840, 790, 760, 680, 700, 630);
  c.bezierCurveTo(670, 610, 640, 605, 605, 610);
  c.closePath();
}

function rightRobePath() {
  const c = drawingContext;
  c.beginPath();
  c.moveTo(995, 625);
  c.bezierCurveTo(1110, 640, 1215, 720, 1265, 850);
  c.bezierCurveTo(1330, 1020, 1350, 1250, 1420, 1510);
  c.bezierCurveTo(1440, 1600, 1465, 1670, 1490, 1720);
  c.bezierCurveTo(1240, 1780, 990, 1770, 775, 1710);
  c.bezierCurveTo(835, 1560, 880, 1430, 875, 1290);
  c.bezierCurveTo(870, 1140, 800, 1050, 780, 920);
  c.bezierCurveTo(760, 790, 840, 690, 900, 640);
  c.bezierCurveTo(930, 620, 960, 620, 995, 625);
  c.closePath();
}

function paintRobe(side) {
  const left = side === 0;
  const c = drawingContext;

  const top = left ? color(45, 82, 96) : color(148, 79, 89);
  const bottom = left ? color(23, 36, 62) : color(72, 35, 62);
  const light = left ? color(105, 145, 145) : color(211, 125, 115);
  const dark = left ? color(14, 28, 52) : color(57, 25, 51);

  c.save();
  if (left) leftRobePath();
  else rightRobePath();
  c.clip();

  noStroke();
  for (let y = 580; y < 1790; y += 8) {
    const t = constrain((y - 580) / 1200, 0, 1);
    fill(lerpColor(top, bottom, t));
    rect(0, y, width, 9);
  }

  noFill();
  for (let i = 0; i < 85; i++) {
    const x = left ? random(150, 870) : random(730, 1450);
    const y = random(650, 1740);
    const col = random() > 0.48 ? light : dark;

    stroke(red(col), green(col), blue(col), random(7, 22));
    strokeWeight(random(18, 78));
    bezier(
      x, y,
      x + random(-150, 150), y + random(100, 260),
      x + random(-160, 160), y + random(260, 480),
      x + random(-110, 110), y + random(420, 680)
    );
  }

  for (let i = 0; i < 950; i++) {
    const x = left ? random(90, 880) : random(720, 1510);
    const y = random(610, 1770);
    const col = random() > 0.5 ? light : dark;

    stroke(red(col), green(col), blue(col), random(5, 22));
    strokeWeight(random(0.7, 4));
    line(
      x, y,
      x + random(-15, 15),
      y + random(9, 62)
    );
  }

  noFill();
  for (let i = 0; i < 27; i++) {
    const x = left ? random(310, 790) : random(810, 1290);
    const y = random(680, 900);
    stroke(red(light), green(light), blue(light), random(18, 48));
    strokeWeight(random(1, 4));
    bezier(
      x, y,
      x + random(-100, 100), 1030,
      x + random(-160, 160), 1410,
      x + random(-180, 180), 1760
    );
  }

  for (let i = 0; i < 100; i++) {
    const x = left ? random(100, 860) : random(740, 1500);
    const y = random(740, 1720);

    push();
    translate(x, y);
    rotate(random(-PI, PI));

    if (left) {
      const r = random(1.5, 5);
      noStroke();
      fill(224, 188, 119, random(30, 105));
      ellipse(0, 0, r, r);

      if (i % 7 === 0) {
        stroke(224, 188, 119, 55);
        strokeWeight(1.2);
        line(-7, 0, 7, 0);
        line(0, -7, 0, 7);
      }
    } else {
      stroke(239, 172, 139, random(30, 80));
      strokeWeight(1.5);
      noFill();
      arc(0, 0, 18, 27, -1.2, 1.4);
      noStroke();
      fill(239, 172, 139, random(30, 80));
      ellipse(-4, -2, 4, 10);
      ellipse(5, 4, 4, 9);
    }
    pop();
  }

  c.restore();

  if (left) leftRobePath();
  else rightRobePath();
  c.strokeStyle = left
    ? "rgba(139,174,169,0.25)"
    : "rgba(235,157,132,0.24)";
  c.lineWidth = 3;
  c.stroke();
}

