function headShape() {
  beginShape();
  vertex(-105, 120);
  bezierVertex(-150, 45, -138, -94, -55, -145);
  bezierVertex(18, -190, 112, -143, 128, -67);
  bezierVertex(137, -28, 116, 4, 105, 22);
  bezierVertex(101, 36, 139, 43, 137, 61);
  bezierVertex(134, 74, 109, 71, 106, 89);
  bezierVertex(100, 127, 65, 148, 35, 166);
  bezierVertex(9, 184, 8, 220, 15, 245);
  bezierVertex(-48, 246, -93, 209, -105, 120);
  endShape(CLOSE);
}

function drawHead(x, y, flip, tilt, skin, shadow) {
  push();
  translate(x, y);
  rotate(tilt);
  scale(flip, 1);

  noStroke();
  fill(skin);
  headShape();

  fill(shadow);
  beginShape();
  vertex(-105, 120);
  bezierVertex(-150, 45, -138, -94, -55, -145);
  bezierVertex(-90, -80, -75, 60, -30, 135);
  bezierVertex(-15, 170, -10, 210, 15, 245);
  bezierVertex(-48, 246, -93, 209, -105, 120);
  endShape(CLOSE);

  noFill();
  stroke(255, 229, 193, 52);
  strokeWeight(7);
  bezier(-58, -135, 24, -172, 101, -115, 112, -57);

  stroke(255, 229, 193, 65);
  strokeWeight(3);
  bezier(108, 21, 104, 39, 139, 44, 136, 60);

  stroke(255, 229, 193, 30);
  strokeWeight(5);
  bezier(-30, 160, -45, 190, -30, 220, -25, 235);

  pop();
}

