function drawSparks() {
  noStroke();
  for (let i = 0; i < 95; i++) {
    const y = random(560, 1320);
    const proximity = 1 - abs(y - 960) / 650;
    const spread = random(35, 210) * (0.6 + proximity * 0.4);
    const x = 800 + random(-spread, spread);
    const r = random(1, 4.5);

    fill(244, 195, 112, random(25, 125));
    ellipse(x, y, r, r * random(1, 1.8));
