}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  smooth();
  noLoop();

  paintGround();
  paintAura();

  fillBody(1);
  fillBody(-1);
  textureBody(1);
  textureBody(-1);
  paintRim(1);
  paintRim(-1);

  paintRoots();
  paintArm(1);
  paintArm(-1);
  paintInnerLight();
  finishSurface();
}

function paintGround() {
  const ctx = drawingContext;
  const ground = ctx.createLinearGradient(0, 0, 0, 2000);
  ground.addColorStop(0, "#14172a");
  ground.addColorStop(0.46, "#2c2438");
  ground.addColorStop(1, "#111b29");
  ctx.fillStyle = ground;
  ctx.fillRect(0, 0, 1600, 2000);

  const warmth = ctx.createRadialGradient(800, 900, 30, 800, 950, 1000);
  warmth.addColorStop(0, "rgba(196,119,85,0.38)");
  warmth.addColorStop(0.38, "rgba(122,75,84,0.22)");
  warmth.addColorStop(1, "rgba(17,21,38,0)");
  ctx.fillStyle = warmth;
  ctx.fillRect(0, 0, 1600, 2000);

  const pigments = [
    [114, 91, 124],
    [62, 96, 111],
    [170, 105, 94],
    [216, 158, 112]
  ];

  noFill();
  for (let i = 0; i < 1900; i++) {
    const x = random(-80, 1680);
    const y = random(-60, 2060);
    const c = pick(pigments);
    const a = noise(x * 0.0013, y * 0.0013) * TWO_PI * 1.7;
    const len = random(25, 190);
    const dx = cos(a) * len;
    const dy = sin(a) * len;
    const bend = random(-45, 45);

    stroke(c[0], c[1], c[2], random(3, 13));
    strokeWeight(random(2, 18));
    bezier(
      x, y,
      x + dx * 0.33 - bend * sin(a),
      y + dy * 0.33 + bend * cos(a),
      x + dx * 0.66 + bend * sin(a),
      y + dy * 0.66 - bend * cos(a),
      x + dx, y + dy
    );
  }

  for (let i = 0; i < 55; i++) {
    const r = random(380, 1050);
    const start = random(TWO_PI);
    stroke(224, 170, 118, random(2, 8));
    strokeWeight(random(1, 4));
    arc(800, 960, r * 1.25, r * 1.55, start, start + random(0.2, 1.3));
  }
}

function paintAura() {
  const ctx = drawingContext;
  ctx.save();
  const aura = ctx.createRadialGradient(800, 970, 0, 800, 970, 470);
  aura.addColorStop(0, "rgba(255,211,139,0.34)");
  aura.addColorStop(0.28, "rgba(238,165,105,0.18)");
  aura.addColorStop(0.68, "rgba(188,109,91,0.06)");
  aura.addColorStop(1, "rgba(188,109,91,0)");
  ctx.fillStyle = aura;
  ctx.fillRect(300, 440, 1000, 1100);
  ctx.restore();
}

function traceBody(ctx, side) {
  const X = x => side === 1 ? x : 1600 - x;

  ctx.beginPath();
  ctx.moveTo(X(145), 1840);
  ctx.bezierCurveTo(X(220), 1600, X(190), 1310, X(285), 1030);
  ctx.bezierCurveTo(X(340), 860, X(425), 740, X(500), 625);
  ctx.bezierCurveTo(X(535), 575, X(545), 545, X(525), 510);
  ctx.bezierCurveTo(X(460), 410, X(500), 275, X(605), 250);
  ctx.bezierCurveTo(X(710), 225, X(775), 315, X(750), 410);
  ctx.bezierCurveTo(X(735), 465, X(690), 500, X(650), 535);
  ctx.bezierCurveTo(X(610), 575, X(620), 650, X(665), 720);
  ctx.bezierCurveTo(X(725), 815, X(735), 900, X(700), 1030);
  ctx.bezierCurveTo(X(650), 1210, X(590), 1340, X(620), 1510);
  ctx.bezierCurveTo(X(650), 1680, X(740), 1760, X(760), 1840);
  ctx.closePath();
}

function fillBody(side) {
  const ctx = drawingContext;
  traceBody(ctx, side);

  let g;
  if (side === 1) {
    g = ctx.createLinearGradient(180, 500, 780, 900);
    g.addColorStop(0, "#142f3e");
    g.addColorStop(0.55, "#285e66");
    g.addColorStop(1, "#6b9b88");
  } else {
    g = ctx.createLinearGradient(1420, 500, 820, 900);
    g.addColorStop(0, "#4b2940");
    g.addColorStop(0.55, "#914952");
    g.addColorStop(1, "#cf8069");
  }

  ctx.fillStyle = g;
  ctx.fill();
}

function textureBody(side) {
  const cool = side === 1;
  const pal = cool ? [
    color(15, 43, 56),
    color(42, 91, 96),
    color(84, 137, 126),
    color(151, 181, 151),
    color(206, 190, 137)
  ] : [
    color(67, 36, 55),
    color(123, 55, 65),
    color(177, 83, 76),
    color(217, 128, 101),
    color(239, 177, 126)
  ];

  drawingContext.save();
  traceBody(drawingContext, side);
  drawingContext.clip();

  for (let i = 0; i < 95; i++) {
    const x = cool ? random(100, 830) : random(770, 1500);
    const y = random(220, 1860);
    const c = pick(pal);
    noStroke();
    fill(red(c), green(c), blue(c), random(4, 15));
    ellipse(x, y, random(50, 240), random(120, 420));
  }

  noFill();
  strokeCap(ROUND);

  for (let i = 0; i < 2800; i++) {
    const x = cool ? random(100, 830) : random(770, 1500);
    const y = random(220, 1840);
    const c = pick(pal);
    const len = random(25, 150);
    const flow = (noise(x * 0.004, y * 0.003) - 0.5) * 80;
    const drift = cool ? flow : -flow;
    const bend = random(-35, 35);
    const x2 = x + drift * 0.35 + random(-12, 12);

    stroke(red(c), green(c), blue(c), random(7, 34));
    strokeWeight(random(1, 8));
    bezier(
      x, y,
      x + bend * 0.2, y + len * 0.3,
      x + bend, y + len * 0.7,
      x2, y + len
    );
  }

  for (let i = 0; i < 170; i++) {
    const x = cool ? random(140, 800) : random(800, 1460);
    const y = random(240, 1580);
    const len = random(180, 520);
    const c = pick(pal);
    const sway = random(-100, 100);

    stroke(red(c), green(c), blue(c), random(6, 20));
    strokeWeight(random(1, 4));
    bezier(
      x, y,
      x + sway * 0.25, y + len * 0.3,
      x + sway, y + len * 0.72,
      x + sway * 0.45, y + len
    );
  }

  drawingContext.restore();
}

function paintRim(side) {
