      X(720 + off), 475,
      X(650 + off), 535
    );
    bezier(
      X(650 + off), 535,
      X(600 + off), 610,
      X(635 + off), 675,
      X(680 + off), 760
    );
    bezier(
      X(680 + off), 760,
      X(760 + off), 930,
