}

function draw() {
  paintGround();

  radialWash(
    800, 900, 540,
    "rgba(246,205,126,0.25)",
    "rgba(246,205,126,0)",
    1.25
  );
  drawAura();

  const leftPath = makePath([
    { x: 420, y: 1840, w: 95 },
    { x: 480, y: 1580, w: 150 },
    { x: 475, y: 1340, w: 170 },
    { x: 620, y: 1110, w: 140 },
    { x: 570, y: 900, w: 150 },
    { x: 625, y: 690, w: 120 },
    { x: 720, y: 510, w: 85 },
    { x: 742, y: 300, w: 0 }
  ]);

  const rightPath = makePath([
    { x: 1180, y: 1840, w: 100 },
    { x: 1125, y: 1580, w: 155 },
    { x: 1130, y: 1340, w: 170 },
    { x: 985, y: 1110, w: 140 },
    { x: 1035, y: 900, w: 150 },
    { x: 975, y: 690, w: 120 },
    { x: 885, y: 510, w: 85 },
    { x: 858, y: 340, w: 0 }
