  paintRoots(leftPalette, rightPalette);
  paintBody(leftPath, leftPalette, 17);
  paintBody(rightPath, rightPalette, 43);

  crownFilaments(leftPath, leftPalette, 1);
  crownFilaments(rightPath, rightPalette, -1);

  drawExchange();
  paintSeed();
  paintMotes();
  finishSurface();
