function paintGround() {
  const top = color(240, 233, 217);
  const bottom = color(214, 196, 169);

  noStroke();
  for (let y = 0; y < H; y += 4) {
    fill(lerpColor(top, bottom, y / H));
    rect(0, y, W, 5);
  }

  radialWash(
    740, 680, 950,
    "rgba(255,250,229,0.32)",
    "rgba(255,250,229,0)"
  );
  radialWash(
    180, 400, 680,
    "rgba(164,78,62,0.065)",
    "rgba(164,78,62,0)"
  );
  radialWash(
    1430, 1290, 720,
    "rgba(42,94,99,0.06)",
    "rgba(42,94,99,0)"
  );
  radialWash(
    260, 1830, 570,
    "rgba(112,71,53,0.055)",
    "rgba(112,71,53,0)"
  );

  for (let i = 0; i < 20; i++) {
    const y = random(80, 1940);
    noFill();
    stroke(112, 88, 64, random(3, 8));
    strokeWeight(random(0.8, 2.8));
    bezier(
      random(-250, 200), y,
      random(350, 650), y + random(-260, 260),
