    const len = random(5, 48);
    stroke(84, 66, 48, random(3, 10));
    strokeWeight(random(0.35, 0.9));
    line(x, y, x + cos(a) * len, y + sin(a) * len * 0.35);
  }

  for (let k = 0; k < 36; k++) {
    stroke(k % 2 ? 255 : 75, k % 2 ? 250 : 61, k % 2 ? 229 : 45, 9);
    strokeWeight(0.7);
    beginShape(POINTS);
    for (let j = 0; j < 300; j++) {
      vertex(random(W), random(H));
    }
    endShape();
  }
}

function drawAura() {
  for (let k = 0; k < 11; k++) {
    const rx = 175 + k * 28;
    const ry = 260 + k * 37;
    const start = random(-PI, PI);
    const sweep = random(PI * 0.65, PI * 1.55);

    noFill();
    stroke(145, 107, 61, random(7, 15));
    strokeWeight(random(0.8, 1.8));
    beginShape();
    for (let j = 0; j <= 120; j++) {
      const a = start + sweep * j / 120;
      const wobble = (noise(cos(a) * 2 + 8, sin(a) * 2 + k * 0.3) - 0.5) * 15;
      const x = 800 + (rx + wobble) * cos(a);
      const y = 910 + (ry + wobble) * sin(a);
      vertex(x, y);
    }
    endShape();
  }
}

function makePath(raw) {
  const points = [];
  const steps = 55;

  for (let i = 0; i < raw.length - 1; i++) {
    const p0 = raw[max(0, i - 1)];
    const p1 = raw[i];
    const p2 = raw[i + 1];
    const p3 = raw[min(raw.length - 1, i + 2)];

    for (let j = 0; j < steps; j++) {
      const t = j / steps;
      const smooth = t * t * (3 - 2 * t);
      points.push({
        x: catmull(p0.x, p1.x, p2.x, p3.x, t),
        y: catmull(p0.y, p1.y, p2.y, p3.y, t),
        w: lerp(p1.w, p2.w, smooth)
      });
    }
  }

  const last = raw[raw.length - 1];
  points.push({ x: last.x, y: last.y, w: last.w });

  for (let i = 0; i < points.length; i++) {
    const a = points[max(0, i - 1)];
    const b = points[min(points.length - 1, i + 1)];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const m = max(0.0001, sqrt(dx * dx + dy * dy));
    const p = points[i];
    p.tx = dx / m;
    p.ty = dy / m;
    p.nx = -p.ty;
    p.ny = p.tx;
  }

  return points;
}

function catmull(a, b, c, d, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  return 0.5 * (
    2 * b +
    (-a + c) * t +
    (2 * a - 5 * b + 4 * c - d) * t2 +
    (-a + 3 * b - 3 * c + d) * t3
  );
}

function ribbonShape(s, c, scaleAmount, shift, ragged, seed, dx = 0, dy = 0) {
  noStroke();
  fill(c);
  beginShape();

  for (let i = 0; i < s.length; i++) {
    const p = s[i];
    const t = i / (s.length - 1);
    const fade = sin(PI * t);
    const center = shift * fade;
    const rough = (noise(i * 0.045, seed) - 0.5) * ragged * fade;
    const w = max(0, p.w * scaleAmount + rough);
    vertex(
      p.x + p.nx * (center + w) + dx,
      p.y + p.ny * (center + w) + dy
    );
  }

  for (let i = s.length - 1; i >= 0; i--) {
    const p = s[i];
    const t = i / (s.length - 1);
    const fade = sin(PI * t);
    const center = shift * fade;
    const rough = (noise(i * 0.047, seed + 20) - 0.5) * ragged * fade;
    const w = max(0, p.w * scaleAmount + rough);
    vertex(
      p.x + p.nx * (center - w) + dx,
      p.y + p.ny * (center - w) + dy
    );
  }

  endShape(CLOSE);
}

function paintBody(s, palette, seed) {
  ribbonShape(s, color(61, 42, 37, 17), 1.19, 9, 18, seed, 12, 18);
  ribbonShape(s, fadeColor(palette[0], 30), 1.12, 0, 15, seed + 1);
  ribbonShape(s, fadeColor(palette[0], 238), 1, 0, 4, seed + 2);

  for (let k = 0; k < 18; k++) {
    ribbonShape(
      s,
      fadeColor(random(palette), random(9, 25)),
      random(0.72, 1.02),
      random(-34, 34),
      random(3, 11),
      seed + 10 + k
    );
  }

  ribbonShape(
    s,
    fadeColor(palette[4], 24),
    0.48,
    random(-20, 20),
    4,
    seed + 80
  );

  for (let k = 0; k < 155; k++) {
    const lateral = random(-0.94, 0.94);
    const i0 = floor(random(0, s.length * 0.34));
    const i1 = floor(random(s.length * 0.56, s.length - 2));
    const c = random(palette);

    noFill();
    stroke(fadeColor(c, random(20, 72)));
    strokeWeight(random(0.55, 3.1));
    beginShape();

    for (let i = i0; i <= i1; i += 2) {
      const p = s[i];
      const off = lateral * p.w * 0.92 +
        sin(i * 0.085 + k * 0.7) * 1.7;
      vertex(p.x + p.nx * off, p.y + p.ny * off);
    }
    endShape();
  }

  for (let k = 0; k < 190; k++) {
    const i = floor(random(4, s.length - 5));
    const p = s[i];
    const side = random() < 0.5 ? -1 : 1;
    const off = side * p.w * random(0.93, 1.05);
    const x = p.x + p.nx * off;
    const y = p.y + p.ny * off;
    const len = random(2, 15);

    stroke(fadeColor(random(palette), random(18, 48)));
    strokeWeight(random(0.4, 1.7));
    line(
      x, y,
      x + p.nx * side * len + p.tx * random(-9, 9),
      y + p.ny * side * len + p.ty * random(-9, 9)
    );
  }

  noStroke();
  for (let k = 0; k < 420; k++) {
    const p = random(s);
    const off = random(-1.08, 1.08) * p.w;
    const x = p.x + p.nx * off + random(-2, 2);
    const y = p.y + p.ny * off + random(-2, 2);
    const d = random(0.5, 3.2);
    fill(fadeColor(random(palette), random(12, 48)));
    ellipse(x, y, d, d * random(0.5, 1.6));
  }
}

function paintRoots(leftPalette, rightPalette) {
  for (let side = 0; side < 2; side++) {
    const fromLeft = side === 0;
    const palette = fromLeft ? leftPalette : rightPalette;

    for (let i = 0; i < 18; i++) {
      const sx = (fromLeft ? 420 : 1180) + random(-90, 90);
      const sy = random(1740, 1840);
      const ex = fromLeft ? random(690, 1120) : random(480, 910);
      const ey = random(1970, 2030);
      const c1x = sx + (fromLeft ? 1 : -1) * random(40, 250);
      const c1y = random(1810, 1900);
      const c2x = ex + random(-220, 220);
      const c2y = random(1810, 1970);
      const c = i % 6 === 0 ? color(164, 121, 62) : random(palette);
      const weight = random(0.8, 3.8);

      noFill();
      stroke(fadeColor(c, 13));
      strokeWeight(weight + 5);
      bezier(sx, sy, c1x, c1y, c2x, c2y, ex, ey);

      stroke(fadeColor(c, random(35, 78)));
      strokeWeight(weight);
      bezier(sx, sy, c1x, c1y, c2x, c2y, ex, ey);
    }
  }
}

function crownFilaments(s, palette, toward) {
  for (let k = 0; k < 11; k++) {
    const i = floor(random(s.length * 0.79, s.length * 0.98));
    const p = s[i];
    const off = random(-0.8, 0.8) * p.w;
    const sx = p.x + p.nx * off;
    const sy = p.y + p.ny * off;
    const ex = 800 + random(-34, 34);
    const ey = random(225, 395);
    const c = k % 4 === 0 ? color(171, 125, 60) : random(palette);

    noFill();
    stroke(fadeColor(c, random(28, 67)));
    strokeWeight(random(0.5, 1.8));
    bezier(
      sx, sy,
      sx + toward * random(15, 85), sy - random(20, 95),
      ex - toward * random(5, 70), ey + random(20, 105),
      ex, ey
    );
  }
}

function drawExchange() {
  for (let i = 0; i < 9; i++) {
    const t = i / 8;
    const y = lerp(690, 1130, t);
    const xl = 723 + 45 * sin(t * PI) + random(-8, 8);
    const xr = 877 - 45 * sin(t * PI) + random(-8, 8);
    const bend = sin(i * 1.7) * 90;

    noFill();
    stroke(174, 125, 55, random(25, 58));
    strokeWeight(random(0.65, 1.65));
    bezier(
      xl, y,
      766, y - 70 + bend,
      834, y + 70 - bend,
      xr, y + random(-20, 20)
    );
  }
}

function paintSeed() {
  radialWash(
    800, 900, 245,
    "rgba(249,208,120,0.27)",
    "rgba(249,208,120,0)",
    1.25
  );

  const ctx = drawingContext;
  const path = new Path2D();
  path.moveTo(800, 772);
  path.bezierCurveTo(861, 840, 866, 948, 800, 1028);
  path.bezierCurveTo(734, 948, 739, 840, 800, 772);
  path.closePath();

  ctx.save();
  ctx.shadowColor = "rgba(210,145,52,0.45)";
  ctx.shadowBlur = 45;
  ctx.fillStyle = "rgba(198,133,47,0.72)";
  ctx.fill(path);
  ctx.shadowBlur = 0;
  ctx.clip(path);

  const glow = ctx.createRadialGradient(790, 872, 4, 800, 910, 150);
  glow.addColorStop(0, "rgba(255,253,228,1)");
  glow.addColorStop(0.28, "rgba(255,237,177,0.98)");
  glow.addColorStop(0.62, "rgba(236,183,85,0.94)");
  glow.addColorStop(1, "rgba(177,107,38,0.9)");
  ctx.fillStyle = glow;
  ctx.fillRect(720, 750, 160, 310);
  ctx.restore();

  noFill();
  stroke(255, 247, 214, 155);
  strokeWeight(2);
  beginShape();
  vertex(793, 810);
  bezierVertex(770, 860, 770, 918, 792, 966);
  endShape();

  noStroke();
  fill(255, 252, 226, 215);
  ellipse(791, 873, 15, 27);
}

function paintMotes() {
  for (let i = 0; i < 135; i++) {
    const a = random(TWO_PI);
    const r = random(90, 365);
    const x = 800 + cos(a) * r * random(0.65, 0.9);
    const y = 905 + sin(a) * r * random(0.9, 1.25);
    const alpha = map(r, 90, 365, 135, 15);
    const d = random(1, 4.6);

    noStroke();
    fill(random(185, 230), random(128, 179), random(48, 91), alpha);
    ellipse(x, y, d, d * random(0.7, 1.5));

    if (i % 9 === 0) {
      stroke(190, 137, 57, alpha * 0.65);
      strokeWeight(0.8);
      line(x, y, x + cos(a + 1.2) * 9, y + sin(a + 1.2) * 9);
    }
  }
}

function finishSurface() {
  const ctx = drawingContext;
  ctx.save();
  const vignette = ctx.createRadialGradient(800, 900, 550, 800, 900, 1360);
  vignette.addColorStop(0, "rgba(49,31,27,0)");
  vignette.addColorStop(0.76, "rgba(49,31,27,0.025)");
  vignette.addColorStop(1, "rgba(49,31,27,0.19)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();

  for (let k = 0; k < 20; k++) {
    stroke(k % 2 ? 255 : 65, k % 2 ? 246 : 48, k % 2 ? 221 : 39, 8);
    strokeWeight(0.65);
    beginShape(POINTS);
    for (let j = 0; j < 220; j++) {
      vertex(random(W), random(H));
    }
    endShape();
  }
}

function radialWash(x, y, r, inner, outer, sy = 1) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, sy);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
  g.addColorStop(0, inner);
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(-r, -r, r * 2, r * 2);
  ctx.restore();
}

function fadeColor(c, a) {
  return color(red(c), green(c), blue(c), a);
}

// "The Grafting" — two trees lean together at dusk.
// Their crowns merge into one blossom; beneath the soil,
// their roots cross the dark, braid together, and share one ember.
// A still painting: everything is drawn once.

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

const W = 1600, H = 2000, HOR = 1150;

let segs = [];                 // trunk/branch segments [x1,y1,w1,x2,y2,w2]
let tips = [];                 // blossom anchor points
const trunkPts = { L: null, R: null };

// ---------- gradients ----------
const SKY_STOPS = [
  [0.00, [20, 11, 46]], [0.28, [52, 24, 76]], [0.52, [110, 42, 82]],
  [0.72, [166, 66, 80]], [0.88, [214, 120, 82]], [1.00, [242, 172, 100]]
];
const SOIL_STOPS = [
  [0.0, [40, 24, 36]], [0.5, [21, 12, 22]], [1.0, [10, 5, 12]]
];

function gradCol(stops, t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    const a = stops[i], b = stops[i + 1];
    if (t >= a[0] && t <= b[0]) {
      const k = (t - a[0]) / ((b[0] - a[0]) || 1);
      return [lerp(a[1][0], b[1][0], k), lerp(a[1][1], b[1][1], k), lerp(a[1][2], b[1][2], k)];
    }
  }
  return stops[stops.length - 1][1].slice();
}

// ---------- sky ----------
function sky() {
  noStroke();
  for (let y = 0; y < HOR; y += 3) {
    const t = y / HOR;
    const c = gradCol(SKY_STOPS, t);
    const j = (noise(0.3, y * 0.01) - 0.5) * 22;
    fill(c[0] + j, c[1] + j * 0.7, c[2] + j * 0.9);
    rect(0, y, W, 3.4);
  }
  for (let i = 0; i < 300; i++) {          // painterly streaks, denser near horizon
    const t = Math.pow(random(), 0.62);
    const y = t * (HOR - 8);
    const c = gradCol(SKY_STOPS, t);
    const x = random(-100, W + 100);
    const l = random(90, 540);
    fill(c[0] + random(-16, 18), c[1] + random(-12, 12), c[2] + random(-8, 16), random(14, 44));
    rect(x - l / 2, y + random(-3, 3), l, random(1.5, 5));
  }
}

function stars() {
  for (let i = 0; i < 170; i++) {
    fill(247, 236, 208, random(40, 205));
    circle(random(W), random(HOR * 0.52), random(0.8, 2.7));
  }
  for (let i = 0; i < 12; i++) {
    const x = random(W), y = random(HOR * 0.4);
    fill(255, 240, 210, 22); circle(x, y, random(9, 16));
    fill(255, 244, 220, 180); circle(x, y, 2.6);
  }
}

function moon() {
  const mx = 1292, my = 232;
  for (let d = 640; d > 172; d -= 12) {
    fill(255, 206, 140, map(d, 640, 172, 1.5, 11));
    circle(mx, my, d);
  }
  fill(224, 203, 174); circle(mx + 5, my + 4, 156);
  fill(247, 233, 204); circle(mx - 3, my - 4, 152);
  fill(214, 192, 166, 70);
  circle(mx - 20, my - 10, 22); circle(mx + 18, my + 14, 15); circle(mx + 2, my - 24, 10);
}

function hills() {
  fill(88, 50, 82, 150);
  beginShape();
  vertex(0, HOR);
  for (let x = 0; x <= W; x += 24) vertex(x, HOR - 78 - 46 * noise(x * 0.0028, 90));
  vertex(W, HOR);
  endShape(CLOSE);
  fill(56, 30, 56, 235);
  beginShape();
  vertex(0, HOR);
  for (let x = 0; x <= W; x += 20) vertex(x, HOR - 34 - 26 * noise(x * 0.004, 40));
  vertex(W, HOR);
  endShape(CLOSE);
}

function horizonGlow() {                   // the light that pools between them
  for (let d = 2100; d > 180; d -= 12) {
    fill(255, 148, 78, map(d, 2100, 180, 1.5, 9));
    circle(800, 1172, d);
  }
}

function blob(x, y, r, col, a) {
  const rr = [1, 0.72, 0.48, 0.28], aa = [0.3, 0.45, 0.7, 1];
  for (let i = 0; i < 4; i++) {
    fill(col[0], col[1], col[2], a * aa[i]);
    circle(x, y, r * 2 * rr[i]);
  }
}

function canopyMass() {
  blob(800, 450, 400, [128, 38, 66], 34);
  blob(640, 505, 270, [104, 30, 60], 26);
  blob(960, 505, 270, [104, 30, 60], 26);
  blob(800, 415, 210, [178, 66, 78], 20);
}

// ---------- soil (cross-section) ----------
function soil() {
  noStroke();
  for (let y = HOR; y < H; y += 3) {
    const t = (y - HOR) / (H - HOR);
    const c = gradCol(SOIL_STOPS, t);
    const j = (noise(9.1, y * 0.012) - 0.5) * 16;
    fill(c[0] + j, c[1] + j * 0.7, c[2] + j * 0.9);
    rect(0, y, W, 3.4);
  }
  for (let i = 0; i < 7; i++) {            // strata
    const by = HOR + 120 + i * 108 + random(-18, 18);
    fill(64, 40, 54, 26 - i * 2.4);
    beginShape();
    vertex(0, by + 24);
    for (let x = 0; x <= W; x += 44) vertex(x, by + 13 * noise(x * 0.003, i * 7.7));
    vertex(W, by + 24);
    endShape(CLOSE);
  }
  for (let i = 0; i < 52; i++) {           // stones
    const x = random(30, W - 30), y = random(HOR + 40, H - 30);
    if (dist(x, y, 800, 1668) < 190) continue;
    const rx = random(7, 24), ry = rx * random(0.5, 0.72);
    push(); translate(x, y); rotate(random(TWO_PI));
    fill(56, 40, 52, 200); ellipse(0, 0, rx * 2, ry * 2);
    fill(84, 62, 72, 90); ellipse(-rx * 0.25, -ry * 0.3, rx * 1.1, ry * 0.7);
    pop();
  }
}

// ---------- trees ----------
function taper(x1, y1, w1, x2, y2, w2) {
  for (let i = 0; i < 3; i++) {
    const t0 = i / 3, t1 = (i + 1) / 3;
    segs.push([lerp(x1, x2, t0), lerp(y1, y2, t0), lerp(w1, w2, t0),
               lerp(x1, x2, t1), lerp(y1, y2, t1), lerp(w1, w2, t1)]);
  }
}

function drawSegs() {
  noFill();
  stroke(26, 14, 30);
  strokeCap(ROUND);
  for (const s of segs) {
    strokeWeight(Math.max(s[2], 0.8));
    line(s[0], s[1], s[3], s[4]);
  }
  noStroke();
}

function trunkW(t) { return lerp(30, 82, 1 - t) + 40 * Math.pow(1 - t, 2.4); }

function trunk(baseX, lean) {
  const topX = baseX + lean;
  const n = 26, pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n, u = 1 - t;
    pts.push({
      x: u*u*u*baseX + 3*u*u*t*(baseX - lean * 0.15) + 3*u*t*t*(baseX + lean * 0.55) + t*t*t*topX,
      y: u*u*u*1174 + 3*u*u*t*950 + 3*u*t*t*780 + t*t*t*652
    });
  }
  for (let i = 0; i < n; i++) {
    taper(pts[i].x, pts[i].y, trunkW(i / n), pts[i + 1].x, pts[i + 1].y, trunkW((i + 1) / n));
  }
  return pts;
}

const TARGETS = { L: { x: 795, y: 415 }, R: { x: 805, y: 415 } };

function grow(x, y, ang, len, w, depth, tree, steer) {
  const tg = TARGETS[tree];
  let dx = Math.cos(ang), dy = Math.sin(ang);
  const tx = tg.x - x, ty = tg.y - y;
  const m = Math.sqrt(tx * tx + ty * ty) || 1;
  dx += steer * tx / m;
  dy += steer * ty / m;
  let a = Math.atan2(dy, dx);
  a += (noise(x * 0.008, y * 0.008, tree === 'L' ? 11 : 77) - 0.5) * 0.55;
  const L = len * (0.9 + 0.2 * random());
  const ex = x + Math.cos(a) * L, ey = y + Math.sin(a) * L;

  let k = 1;                                // keep the crown on the canvas
  if (ey < 200) k = Math.min(k, (y - 200) / (y - ey || 1));
  if (ex < 205) k = Math.min(k, (x - 205) / (x - ex || 1));
  if (ex > 1395) k = Math.min(k, (x - 1395) / (x - ex || 1));
  k = constrain(k, 0, 1);
  const fx = lerp(x, ex, k), fy = lerp(y, ey, k);

  taper(x, y, w, fx, fy, w * 0.64);

  if (k < 1 || depth <= 0 || w * 0.64 < 1.5) {
    tips.push({ x: fx, y: fy, tree, back: random() < 0.42,
                n: 5 + floor(random() * 8), spread: 22 + random() * 32 });
    return;
  }
  let kids = random() < 0.18 ? 1 : 2;
  if (random() < 0.07 && depth > 3) kids = 3;
  const spread = 0.36 + 0.3 * random();
  for (let j = 0; j < kids; j++) {
    const na = a + (j - (kids - 1) / 2) * spread + (random() - 0.5) * 0.3;
    grow(fx, fy, na, len * 0.76, w * 0.64, depth - 1, tree, steer);
  }
}

function treeL() {
  trunkPts.L = trunk(560, 130);
  grow(688, 660, radians(-96), 160, 26, 7, 'L', 0.30);
  grow(672, 706, radians(-152), 128, 16, 6, 'L', 0.13);
  grow(658, 752, radians(-68), 132, 15, 6, 'L', 0.30);
  grow(636, 822, radians(-38), 108, 11, 5, 'L', 0.22);
  grow(616, 900, radians(-158), 92, 9, 5, 'L', 0.11);
}

function treeR() {
  trunkPts.R = trunk(1040, -130);
  grow(912, 660, radians(-84), 160, 26, 7, 'R', 0.30);
  grow(928, 706, radians(-28), 128, 16, 6, 'R', 0.13);
  grow(942, 752, radians(-112), 132, 15, 6, 'R', 0.30);
  grow(964, 822, radians(-142), 108, 11, 5, 'R', 0.22);
  grow(984, 900, radians(-22), 92, 9, 5, 'R', 0.11);
}

// ---------- roots ----------
function mkPath(x0, y0, x1, y1, x2, y2, x3, y3, jitter, seed) {
  const n = 34, pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n, u = 1 - t;
    pts.push({
      x: u*u*u*x0 + 3*u*u*t*x1 + 3*u*t*t*x2 + t*t*t*x3,
      y: u*u*u*y0 + 3*u*u*t*y1 + 3*u*t*t*y2 + t*t*t*y3
    });
  }
  for (let i = 0; i <= n; i++) {
    pts[i].x += (noise(seed + i * 0.13, 3.3) - 0.5) * jitter;
    pts[i].y += (noise(5.5, seed + i * 0.11) - 0.5) * jitter * 0.7;
  }
  return pts;
}

function rootStroke(pts, w0, w1, col, al) {
  noStroke();
  fill(col[0], col[1], col[2], al);
  const n = pts.length;
  for (let i = 0; i < n - 1; i++) {
    const a = pts[i], b = pts[i + 1];
    const wA = lerp(w0, w1, i / (n - 1)), wB = lerp(w0, w1, (i + 1) / (n - 1));
    const ang = atan2(b.y - a.y, b.x - a.x);
    const px = Math.cos(ang + HALF_PI), py = Math.sin(ang + HALF_PI);
    quad(a.x + px * wA / 2, a.y + py * wA / 2,
         a.x - px * wA / 2, a.y - py * wA / 2,
         b.x - px * wB / 2, b.y - py * wB / 2,
         b.x + px * wB / 2, b.y + py * wB / 2);
    circle(a.x, a.y, wA);
    circle(b.x, b.y, wB);
  }
}

function hair(p, ang, len, w, col) {
  const bend = (random() - 0.5) * 0.9;
  const m = { x: p.x + Math.cos(ang + bend * 0.35) * len * 0.5, y: p.y + Math.sin(ang + bend * 0.35) * len * 0.5 };
  const e = { x: p.x + Math.cos(ang + bend) * len, y: p.y + Math.sin(ang + bend) * len };
  rootStroke([p, m, e], w, 1.1, col, 130);
}

function rootHairs(pts, col) {
  const idx = [4, 8, 12, 16, 20, 24, 28, 31];
  for (const i of idx) {
    if (i >= pts.length - 1) continue;
    const p = pts[i], q = pts[i + 1];
    const tang = atan2(q.y - p.y, q.x - p.x);
    const side = random() < 0.5 ? 1 : -1;
    hair(p, tang + side * random(0.45, 1.15), random(16, 64), random(2.5, 4.5), col);
    if (random() < 0.35) hair(p, tang - side * random(0.4, 0.9), random(50, 130), random(3.5, 5.5), col);
  }
}

const LR = [                               // left tree's roots [p0,c1,c2,p1,w]
  [[560,1172],[495,1310],[640,1560],[772,1700],30],
  [[560,1172],[592,1330],[700,1470],[788,1520],24],
  [[560,1172],[468,1385],[432,1600],[505,1830],26],
  [[560,1174],[622,1262],[736,1358],[795,1402],18],
  [[556,1174],[640,1240],[700,1292],[748,1316],14],
  [[562,1174],[518,1420],[558,1640],[668,1848],20],
  [[564,1176],[660,1202],[768,1240],[836,1252],11]
];

function braid() {                          // the graft: two roots, one weave
  const n = 80, y0 = 1524, y1 = 1832;
  for (let k = 0; k < 2; k++) {
    const pts = [];
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const ph = t * TWO_PI * 2.3 + k * PI;
      const r = 30 * (1 - t * 0.85);
      pts.push({ x: 800 + Math.cos(ph) * r, y: lerp(y0, y1, t) + Math.sin(ph) * r * 0.5 });
    }
    rootStroke(pts, 15, 4, k === 0 ? [118, 74, 58] : [100, 62, 70], 235);
  }
  rootStroke([{ x: 800, y: 1826 }, { x: 800, y: 1862 }, { x: 803, y: 1892 }], 9, 2, [124, 80, 64], 235);
}

function rootsAll() {
  const Lcol = [101, 62, 52], Rcol = [88, 58, 68];
  for (let i = 0; i < LR.length; i++) {
    const r = LR[i];
    const pts = mkPath(r[0][0], r[0][1], r[1][0], r[1][1], r[2][0], r[2][1], r[3][0], r[3][1], 20, 100 + i * 13);
    rootStroke(pts, r[4], 3, Lcol, 235);
    rootHairs(pts, Lcol);
    const m = v => [1600 - v[0], v[1]];
    const pts2 = mkPath(...m(r[0]), ...m(r[1]), ...m(r[2]), ...m(r[3]), 20, 400 + i * 13);
    rootStroke(pts2, r[4] * random(0.9, 1.06), 3, Rcol, 235);
    rootHairs(pts2, Rcol);
  }
  braid();
}

// ---------- ember ----------
function ember() {
  const ex = 800, ey = 1668;
  for (let d = 560; d > 36; d -= 8) {
    fill(255, 138, 74, map(d, 560, 36, 1.1, 7.5));
    circle(ex, ey, d);
  }
  for (let d = 190; d > 22; d -= 6) {
    fill(255, 190, 110, map(d, 190, 22, 2, 12));
    circle(ex, ey, d);
  }
  fill(255, 178, 102, 170); circle(ex, ey, 54);
  fill(255, 226, 168, 220); circle(ex, ey, 26);
  noFill(); stroke(255, 170, 90, 60); strokeWeight(2);
  circle(ex, ey, 130); circle(ex, ey, 210); circle(ex, ey, 304);
  noStroke();
  const sx = 800, sy = 1402;               // the first spark, where young roots touch
  for (let d = 150; d > 12; d -= 6) {
    fill(255, 160, 90, map(d, 150, 12, 1.5, 6));
    circle(sx, sy, d);
  }
  fill(255, 214, 150, 200); circle(sx, sy, 10);
}

function soilSparks() {
  for (let i = 0; i < 240; i++) {
    const x = random(430, 1170), y = random(1210, 1950);
    const d = dist(x, y, 800, 1668);
    const p = constrain(map(d, 0, 320, 0.75, 0.12), 0.12, 0.75);
    if (random() < p) {
      fill(255, 196, 120, random(20, 70));
      circle(x, y, random(0.8, 2.2));
    }
  }
}

// ---------- blossoms ----------
const LPAL = [[233,102,124],[243,133,111],[219,81,109],[238,168,146]];
const RPAL = [[233,158,185],[219,126,164],[243,190,200],[203,112,152]];
const GOLDS = [[243,197,108],[250,222,150]];

function pickBlossom(tree, x) {
  const d = Math.abs(x - 800);
  const goldP = constrain(map(d, 0, 300, 0.5, 0.08), 0.08, 0.5);
  if (random() < goldP) return GOLDS[floor(random(2))];
  let pal = tree === 'L' ? LPAL : RPAL;
  if (d < 170 && random() < 0.38) pal = (pal === LPAL ? RPAL : LPAL);
  return pal[floor(random(pal.length))];
}

function blossoms(front) {
  noStroke();
  for (const t of tips) {
    if (front ? t.back : !t.back) continue;
    const shade = front ? 1 : 0.55;
    if (front && random() < 0.5) {
      fill(140, 52, 74, 24);
      circle(t.x, t.y, t.spread * 3);
    }
    for (let i = 0; i < t.n; i++) {
      const a = random(TWO_PI), rr = random(t.spread);
      const x = t.x + Math.cos(a) * rr, y = t.y + Math.sin(a) * rr * 0.85;
      const c = pickBlossom(t.tree, x);
      const s = front ? random(6, 16) : random(4.5, 10);
      const al = front ? random(135, 225) : random(85, 155);
      fill(c[0] * shade, c[1] * shade, c[2] * shade, al);
      circle(x, y, s);
      if (front && random() < 0.38) {
        fill(255, 226, 205, random(28, 66));
        circle(x - s * 0.18, y - s * 0.18, s * 0.45);
      }
    }
  }
}

function crownSparks() {                   // gold gathers where the crowns merge
  for (let i = 0; i < 80; i++) {
    fill(255, 226, 152, random(110, 225));
    circle(random(620, 980), random(280, 540), random(1.2, 3));
  }
}

// ---------- trunk detail ----------
function bark(pts) {
  noFill(); stroke(13, 7, 16, 130); strokeWeight(2.4);
  for (const off of [-0.34, -0.12, 0.16, 0.38]) {
    beginShape();
    for (let i = 0; i < pts.length; i += 2) {
      const p = pts[i], q = pts[Math.min(i + 1, pts.length - 1)];
      const dx = q.x - p.x, dy = q.y - p.y;
      const m = Math.sqrt(dx * dx + dy * dy) || 1;
      const px = -dy / m, py = dx / m;
      const w = trunkW(i / (pts.length - 1));
      const wig = (noise(i * 0.3, off * 37) - 0.5) * 7;
      vertex(p.x + px * (w * off + wig), p.y + py * (w * off + wig));
    }
    endShape();
  }
  noStroke();
}

function rimLight(pts) {                   // each trunk lit on the side facing the other
  noStroke();
  for (let i = 2; i < pts.length - 2; i += 2) {
    const p = pts[i], q = pts[i + 1];
    const dx = q.x - p.x, dy = q.y - p.y;
    const m = Math.sqrt(dx * dx + dy * dy) || 1;
    let px = -dy / m, py = dx / m;
    if (px * (800 - p.x) + py * (1170 - p.y) < 0) { px = -px; py = -py; }
    const w = trunkW(i / (pts.length - 1));
    fill(236, 152, 96, 56);
    circle(p.x + px * (w / 2 - 3), p.y + py * (w / 2 - 3), 4);
  }
}

// ---------- petals, sparks, grass ----------
function petals() {
  for (let i = 0; i < 130; i++) {
    const x = random(330, 1270), y = random(690, 1120);
    noFill(); stroke(232, 150, 140, 22); strokeWeight(1.5);
    const sw = random(26, 70);
    bezier(x + sw, y - sw * 1.5, x + sw * 0.45, y - sw * 0.7,
           x + sw * 0.12, y - sw * 0.25, x, y);
    noStroke();
    const c = pickBlossom(random() < 0.5 ? 'L' : 'R', x);
    const s = random(7, 15);
    push(); translate(x, y); rotate(random(TWO_PI));
    fill(c[0], c[1], c[2], random(130, 215));
    ellipse(0, 0, s, s * 0.42);
    fill(255, 232, 214, 60);
    ellipse(-s * 0.16, -1, s * 0.5, s * 0.2);
    pop();
  }
  for (let i = 0; i < 30; i++) {           // settled on the ground
    const x = random(400, 1200), y = random(HOR - 26, HOR - 2);
    const c = pickBlossom(random() < 0.5 ? 'L' : 'R', x);
    const s = random(6, 11);
    push(); translate(x, y); rotate(random(-0.6, 0.6));
    fill(c[0], c[1], c[2], 150); ellipse(0, 0, s, s * 0.3);
    pop();
  }
  noStroke();
}

function fireflies() {
  noStroke();
  for (let i = 0; i < 9; i++) {
    const x = random(590, 1010), y = random(780, 1080);
    fill(255, 204, 124, 26); circle(x, y, 13);
    fill(255, 238, 178, 235); circle(x, y, 2.6);
  }
}

function grass() {
  noStroke();
  for (let i = 0; i < 460; i++) {
    const x = random(-12, W + 12);
    const h = 10 + random() * 34;
    const lean = random(-14, 14);
    if (Math.abs(x - 800) < 280 && random() < 0.7) fill(118, 50, 58, 235);
    else fill(24, 13, 30, 235);
    quad(x - 2.6, HOR + 6, x + 2.6, HOR + 6,
         x + lean + 1.2, HOR - h, x + lean - 1.2, HOR - h);
  }
  noFill(); stroke(255, 172, 96, 40); strokeWeight(3);
  beginShape();
  for (let x = 460; x <= 1140; x += 28) vertex(x, HOR + 2 - 3 * noise(x * 0.01, 21));
  endShape();
  noStroke();
}

// ---------- finish ----------
function vignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 1000, 500, 800, 1000, 1350);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(6,2,12,0.38)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function grain() {
  noStroke();
  for (let i = 0; i < 12000; i++) {
    const v = random() < 0.5 ? 0 : 255;
    fill(v, random(4, 12));
    circle(random(W), random(H), random(0.7, 1.7));
  }
}

// ---------- composition ----------
function draw() {
  background(9, 5, 15);
  sky();
  stars();
  moon();
  hills();
  horizonGlow();
  canopyMass();
  soil();

  segs = []; tips = [];
  treeL();
  treeR();

  rootsAll();
  ember();
  soilSparks();

  blossoms(false);                          // blossoms behind the branches
  drawSegs();                               // trunks and branches
  bark(trunkPts.L); bark(trunkPts.R);
  rimLight(trunkPts.L); rimLight(trunkPts.R);
  blossoms(true);                           // blossoms in front
  crownSparks();
  petals();
  fireflies();
  grass();
  vignette();
  grain();
}

/* Where Two Colors Turn Gold
   Two trees lean toward each other across a night field. Where their
   crowns meet the foliage turns gold, and in the arch their trunks
   form hangs one shared light. Roots braid below; petals meet between. */

const W = 1600;
const H = 2000;

let WARM, COOL, GOLD;
let LSPINE, RSPINE;
let segCount = 0;
const clusters = [];

const LCP = [
  { x: 556, y: 1800 }, { x: 560, y: 1520 }, { x: 584, y: 1210 }, { x: 622, y: 910 },
  { x: 660, y: 660 }, { x: 688, y: 505 }, { x: 698, y: 435 }
];
const RCP = [
  { x: 1044, y: 1800 }, { x: 1040, y: 1520 }, { x: 1016, y: 1210 }, { x: 978, y: 910 },
  { x: 940, y: 660 }, { x: 912, y: 505 }, { x: 902, y: 435 }
];

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  WARM = ['#6b2440', '#a23a52', '#c85a5e', '#e2896b', '#d99a52', '#efb08a'].map(h2r);
  COOL = ['#16404f', '#1f6272', '#2f89a0', '#5aa8b0', '#3f7585', '#9fd0d4'].map(h2r);
  GOLD = ['#8a5a20', '#c9962e', '#eab84e', '#f7d98a', '#fff0c2'].map(h2r);
  LSPINE = makeSpine(LCP, 0);
  RSPINE = makeSpine(RCP, 1);
  paint();
}

/* ---------- small helpers ---------- */

function h2r(h) {
  return [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
}
function sh(c, f) {
  return [constrain(c[0] * f, 0, 255), constrain(c[1] * f, 0, 255), constrain(c[2] * f, 0, 255)];
}
function li(c, f) {
  return [c[0] + (255 - c[0]) * f, c[1] + (255 - c[1]) * f, c[2] + (255 - c[2]) * f];
}
function lerpC(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}
function gauss() { return (random() + random() + random() - 1.5) * 2; }

function glow(cx, cy, r, c, a) {
  const g = drawingContext.createRadialGradient(cx, cy, 0, cx, cy, r);
  g.addColorStop(0, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')');
  g.addColorStop(0.5, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + (a * 0.4) + ')');
  g.addColorStop(1, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(cx - r, cy - r, r * 2, r * 2);
}

function groundY(x) { return 1690 + 62 * noise(x * 0.0018 + 9.7); }

function crownVals(x, y) {
  const dl = sqrt(sq((x - 560) / 345) + sq((y - 430) / 285));
  const dr = sqrt(sq((x - 1040) / 345) + sq((y - 430) / 285));
  return { dl: dl, dr: dr, inside: min(dl, dr) < 1 };
}

/* ---------- trunks ---------- */

function catmullPoint(cp, t) {
  const n = cp.length - 1;
  const f = constrain(t, 0, 1) * n;
  let i = floor(f);
  if (i >= n) i = n - 1;
  const u = f - i;
  const p0 = cp[max(i - 1, 0)], p1 = cp[i];
  const p2 = cp[min(i + 1, n)], p3 = cp[min(i + 2, n)];
  const u2 = u * u, u3 = u2 * u;
  return {
    x: 0.5 * (2 * p1.x + (-p0.x + p2.x) * u +
      (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * u2 +
      (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * u3),
    y: 0.5 * (2 * p1.y + (-p0.y + p2.y) * u +
      (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * u2 +
      (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * u3)
  };
}

function makeSpine(cp, seed) {
  const raw = [];
  for (let i = 0; i <= 400; i++) {
    const t = i / 400;
    const p = catmullPoint(cp, t);
    const wob = (noise(t * 5.5 + seed * 9.3) - 0.5) * 16 * (0.35 + 0.65 * t);
    raw.push({ x: p.x + wob, y: p.y + (noise(t * 5.5 + seed * 9.3 + 50) - 0.5) * 8 });
  }
  const out = [];
  for (let i = 0; i <= 400; i++) {
    const a = raw[max(0, i - 2)], b = raw[min(400, i + 2)];
    let tx = b.x - a.x, ty = b.y - a.y;
    const l = sqrt(tx * tx + ty * ty) || 1;
    out.push({ x: raw[i].x, y: raw[i].y, tx: tx / l, ty: ty / l, t: i / 400 });
  }
  return out;
}

function trunkW(t, tree) {
  let w = 14 + 52 * pow(1 - t, 1.6);
  if (t < 0.14) w *= 1 + 0.75 * pow(1 - t / 0.14, 1.8); // root flare
  w *= 0.9 + 0.28 * noise(t * 6 + tree * 17.3 + 3.3);
  return w;
}

function drawTrunk(spine, tree) {
  const inner = [], outer = [];
  for (let i = 0; i <= 400; i += 4) {
    const s = spine[i];
    const w = trunkW(s.t, tree) / 2;
    const nx = -s.ty, ny = s.tx;
    const sg = tree === 0 ? 1 : -1; // inner edge faces the partner
    inner.push({ x: s.x + nx * w * sg, y: s.y + ny * w * sg, t: s.t });
    outer.push({ x: s.x - nx * w * sg, y: s.y - ny * w * sg, t: s.t });
  }
  const top = spine[400], base = spine[0];
  const g = drawingContext.createLinearGradient(top.x, top.y, base.x, base.y);
  if (tree === 0) { g.addColorStop(0, '#4a2f3c'); g.addColorStop(1, '#150d12'); }
  else { g.addColorStop(0, '#2c3b45'); g.addColorStop(1, '#0a0f13'); }
  drawingContext.fillStyle = g;
  drawingContext.beginPath();
  drawingContext.moveTo(outer[0].x, outer[0].y);
  for (const p of outer) drawingContext.lineTo(p.x, p.y);
  for (let i = inner.length - 1; i >= 0; i--) drawingContext.lineTo(inner[i].x, inner[i].y);
  drawingContext.closePath();
  drawingContext.fill();

  // bark
  strokeCap(ROUND);
  for (let k = 0; k < 95; k++) {
    const t = random(0.03, 0.97);
    const s = spine[round(t * 400)];
    const w = trunkW(t, tree);
    const off = (random() - 0.5) * w * 0.8;
    const nx = -s.ty, ny = s.tx;
    const px = s.x + nx * off, py = s.y + ny * off;
    const len = random(14, 52);
    if (random() < 0.6) stroke(4, 2, 5, 65);
    else if (tree === 0) stroke(128, 76, 88, 50);
    else stroke(64, 106, 122, 50);
    strokeWeight(random(1.4, 3.2));
    line(px, py, px + s.tx * len, py + s.ty * len);
  }

  // the shared light kissing each trunk's inner edge
  for (let i = 1; i < inner.length; i++) {
    const a = inner[i - 1], b = inner[i];
    if (b.t < 0.06 || b.t > 0.98) continue;
    const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
    const d = dist(mx, my, 800, 1000);
    const f = exp(-(d * d) / (2 * 250 * 250));
    const al = 22 + 170 * f;
    stroke(255, 208, 140, al * 0.35);
    strokeWeight(7);
    line(a.x, a.y, b.x, b.y);
    stroke(255, 236, 195, al);
    strokeWeight(2.2);
    line(a.x, a.y, b.x, b.y);
  }
  // faint cool rim from the night sky on the outer edge
  for (let i = 1; i < outer.length; i++) {
    const a = outer[i - 1], b = outer[i];
    if (b.t < 0.25 || b.t > 0.95) continue;
    stroke(110, 145, 178, 26);
    strokeWeight(3);
    line(a.x, a.y, b.x, b.y);
  }
  noStroke();
}

/* ---------- branches ---------- */

function drawSeg(x, y, ex, ey, len, w, tree, tgt, depth) {
  const mx = (x + ex) / 2, my = (y + ey) / 2;
  let px = -(ey - y), py = ex - x;
  const pl = sqrt(px * px + py * py) || 1;
  px /= pl; py /= pl;
  const side = (tgt.x - mx) * px + (tgt.y - my) * py >= 0 ? 1 : -1;
  const k = 0.17 * len * side; // curve toward what it reaches for
  const cx = mx + px * k, cy = my + py * k;
  const STEPS = 5;
  const pts = [];
  for (let i = 0; i <= STEPS; i++) {
    const t = i / STEPS, u = 1 - t;
    const bx = u * u * x + 2 * u * t * cx + t * t * ex;
    const by = u * u * y + 2 * u * t * cy + t * t * ey;
    const dx = 2 * u * (cx - x) + 2 * t * (ex - cx);
    const dy = 2 * u * (cy - y) + 2 * t * (ey - cy);
    const dl = sqrt(dx * dx + dy * dy) || 1;
    const hw = lerp(w, w * 0.62, t) * 0.5;
    pts.push({ bx: bx, by: by, nx: -dy / dl, ny: dx / dl, hw: hw });
  }
  let c = tree === 0 ? [26, 16, 20] : [12, 19, 23];
  const dOrb = dist(mx, my, 800, 1000);
  if (dOrb < 360) c = lerpC(c, [74, 52, 30], (1 - dOrb / 360) * 0.55); // backlit near the light
  c = lerpC(c, tree === 0 ? [64, 32, 44] : [22, 54, 64], (depth / 8) * 0.35);
  noStroke();
  fill(c[0], c[1], c[2]);
  beginShape();
  for (const p of pts) vertex(p.bx - p.nx * p.hw, p.by - p.ny * p.hw);
  for (let i = pts.length - 1; i >= 0; i--) {
    const p = pts[i];
    vertex(p.bx + p.nx * p.hw, p.by + p.ny * p.hw);
  }
  endShape(CLOSE);
  circle(x, y, w * 0.92);
}

function grow(x, y, ang, len, w, depth, tree, tgt) {
  if (depth > 8 || len < 9 || w < 0.8 || segCount > 17000) return;
  segCount++;
  // young branches steer toward what they are reaching for
  const k = depth < 3 ? 0.3 : 0.1;
  const want = atan2(tgt.y - y, tgt.x - x);
  let d = want - ang;
  while (d > PI) d -= TWO_PI;
  while (d < -PI) d += TWO_PI;
  ang += constrain(d, -0.9, 0.9) * k;
  ang -= 0.05; // a slow reach upward
  const ex = x + cos(ang) * len;
  const ey = y + sin(ang) * len;
  drawSeg(x, y, ex, ey, len, w, tree, tgt, depth);
  if (depth >= 5) clusters.push({ x: ex, y: ey, ang: ang, depth: depth, tree: tree });
  const kids = depth === 0 ? 3 : random() < 0.18 ? 3 : 2;
  for (let i = 0; i < kids; i++) {
    let spread;
    if (kids === 3) spread = map(i, 0, 2, -0.5, 0.5) + random(-0.15, 0.15);
    else spread = (i === 0 ? -1 : 1) * random(0.18, 0.55);
    if (i === 0 && random() < 0.25) spread = random(-0.1, 0.1);
    grow(ex, ey, ang + spread, len * random(0.74, 0.85), w * 0.62, depth + 1, tree, tgt);
  }
}

function branches() {
  const prim = [
    { t: 1.00, a: -1.32, len: 185, w: 23, tgt: [790, 255] },   // crown spire
    { t: 0.90, a: -0.55, len: 245, w: 20, tgt: [1010, 530] },  // reaching across
    { t: 0.78, a: -0.20, len: 250, w: 16, tgt: [880, 665] },   // low crosser
    { t: 0.66, a: -2.70, len: 180, w: 14, tgt: [430, 520] },   // outward shoulder
    { t: 0.62, a: -0.50, len: 195, w: 13, tgt: [798, 1010] },  // toward the light
    { t: 0.46, a: -1.80, len: 170, w: 12, tgt: [470, 890] },   // outer arm
    { t: 0.32, a: -2.05, len: 145, w: 10, tgt: [420, 1160] }   // low arm
  ];
  for (const p of prim) {
    const sL = LSPINE[round(p.t * 400)];
    grow(sL.x, sL.y, p.a, p.len, p.w, 0, 0, { x: p.tgt[0], y: p.tgt[1] });
    const sR = RSPINE[round(p.t * 400)];
    grow(sR.x, sR.y, PI - p.a, p.len, p.w, 0, 1, { x: 1600 - p.tgt[0], y: p.tgt[1] });
  }
}

/* ---------- leaves ---------- */

function pickLeafColor(tree, x, y, mode) {
  let m = 1 - dist(x, y, 800, 415) / 340; // closeness to the meeting place
  m = constrain(m, 0, 1);
  m = m * m * (3 - 2 * m);
  let pal;
  if (random() < m * 0.8) pal = GOLD;
  else if (abs(x - 800) < 160 && random() < 0.5) pal = random() < 0.5 ? WARM : COOL;
  else pal = tree === 0 ? WARM : COOL;
  const col = pal[floor(random(pal.length))].slice();
  if (mode === 2) return li(col, 0.5);
  const cv = crownVals(x, y);
  let f = 0.62 + 0.38 * (1 - min(min(cv.dl, cv.dr), 1)); // darker at the rim
  if (mode === 1) f *= 0.5;
  return sh(col, f);
}

function leaves() {
  noStroke();
  // leaves clustered on every twig
  for (const c of clusters) {
    const n = c.depth >= 7 ? 2 : c.depth === 6 ? 3 : c.depth === 5 ? 4 : 6;
    const R = c.depth >= 7 ? 15 : c.depth === 6 ? 23 : c.depth === 5 ? 32 : 44;
    for (let i = 0; i < n; i++) {
      const lx = c.x + random(-R, R);
      const ly = c.y + random(-R * 0.75, R * 0.75);
      if (ly > 850 && abs(lx - 800) < 155 && random() < 0.8) continue; // keep the window open
      if (dist(lx, ly, 800, 1000) < 115 && random() < 0.8) continue;   // never veil the light
      const s = c.depth >= 7 ? random(3.5, 6) : c.depth === 6 ? random(4.5, 7.5) : random(6, 10.5);
      const col = pickLeafColor(c.tree, lx, ly, 0);
      fill(col[0], col[1], col[2], 240);
      push();
      translate(lx, ly);
      rotate(c.ang + random(-1.4, 1.4));
      ellipse(0, 0, s, s * random(0.5, 0.68));
      pop();
    }
  }
  // ambient foliage filling out both crowns
  let placed = 0, tries = 0;
  while (placed < 1700 && tries < 12000) {
    tries++;
    const left = random() < 0.5;
    const cx = left ? 560 : 1040;
    const a = random(TWO_PI), rr = sqrt(random());
    const x = cx + cos(a) * rr * 345;
    const y = 430 + sin(a) * rr * 285;
    if (y > 725) continue;
    if (y > 690 && abs(x - 800) < 200) continue;
    const cv = crownVals(x, y);
    const dens = noise(x * 0.0045 + 3, y * 0.0045 + 3);
    if (min(cv.dl, cv.dr) > 0.55 + 0.5 * dens) continue;
    placed++;
    const col = pickLeafColor(left ? 0 : 1, x, y, 0);
    fill(col[0], col[1], col[2], 190);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(5.5, 11.5), random(3.5, 7));
    pop();
  }
  // small bright leaves catching the light
  for (const c of clusters) {
    if (random() < 0.32) {
      const n = 1 + floor(random(2));
      for (let i = 0; i < n; i++) {
        const lx = c.x + random(-24, 24);
        const ly = c.y + random(-22, 12);
        if (ly > 850 && abs(lx - 800) < 155) continue;
        if (dist(lx, ly, 800, 1000) < 115) continue;
        const col = pickLeafColor(c.tree, lx, ly, 2);
        fill(col[0], col[1], col[2], 225);
        push();
        translate(lx, ly);
        rotate(random(TWO_PI));
        ellipse(0, 0, random(3, 6.5), random(1.8, 3.8));
        pop();
      }
    }
  }
  // where the crowns meet, the leaves turn to gold
  for (let i = 0; i < 70; i++) {
    const x = 800 + gauss() * 170;
    const y = 415 + gauss() * 120;
    const c = GOLD[floor(random(GOLD.length))];
    fill(c[0], c[1], c[2], 235);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    const s = random(6, 11);
    ellipse(0, 0, s, s * 0.6);
    pop();
  }
}

/* ---------- sky, ground, roots, light, atmosphere ---------- */

function stars() {
  noStroke();
  let placed = 0, tries = 0;
  while (placed < 380 && tries < 4000) {
    tries++;
    const x = random(W), y = random(1500);
    if (crownVals(x, y).inside) continue;
    placed++;
    const a = 25 + 175 * random() * random();
    const s = 0.8 + 2.0 * random() * random();
    const warm = random() < 0.25;
    fill(warm ? 255 : 208, warm ? 232 : 218, warm ? 205 : 250, a);
    circle(x, y, s);
  }
  let n = 0;
  tries = 0;
  while (n < 9 && tries < 2000) {
    tries++;
    const x = random(80, W - 80), y = random(80, 1250);
    if (crownVals(x, y).inside || dist(x, y, 800, 1000) < 380) continue;
    n++;
    const L = random(9, 22);
    glow(x, y, L * 2.4, [190, 205, 255], 0.28);
    stroke(225, 235, 255, 210);
    strokeWeight(1.4);
    line(x - L, y, x + L, y);
    line(x, y - L, x, y + L);
    noStroke();
    fill(240, 246, 255, 240);
    circle(x, y, 2.4);
  }
}

function deepCanopy() {
  noStroke();
  let placed = 0, tries = 0;
  while (placed < 2300 && tries < 16000) {
    tries++;
    const left = random() < 0.5;
    const cx = left ? 560 : 1040;
    const a = random(TWO_PI), rr = sqrt(random());
    const x = cx + cos(a) * rr * 345;
    const y = 430 + sin(a) * rr * 285;
    if (y > 730) continue;
    const cv = crownVals(x, y);
    const dens = noise(x * 0.0045, y * 0.0045);
    if (min(cv.dl, cv.dr) > 0.45 + 0.6 * dens) continue;
    placed++;
    const col = pickLeafColor(left ? 0 : 1, x, y, 1);
    fill(col[0], col[1], col[2], 135);
    circle(x, y, random(9, 18));
  }
}

function ground() {
  noStroke();
  const g = drawingContext.createLinearGradient(0, 1660, 0, H);
  g.addColorStop(0, '#141b26');
  g.addColorStop(1, '#05070c');
  drawingContext.fillStyle = g;
  drawingContext.beginPath();
  drawingContext.moveTo(-20, H + 20);
  for (let x = -20; x <= W + 20; x += 16) drawingContext.lineTo(x, groundY(x));
  drawingContext.lineTo(W + 20, H + 20);
  drawingContext.closePath();
  drawingContext.fill();
  // moonlit crest
  noFill();
  stroke(120, 160, 175, 45);
  strokeWeight(2);
  beginShape();
  for (let x = -20; x <= W + 20; x += 16) vertex(x, groundY(x) - 1);
  endShape();
  // sparse grass
  for (let i = 0; i < 1100; i++) {
    const x = random(W);
    const y = groundY(x) + random(6, 300);
    const len = random(5, 16);
    if (abs(x - 800) < 260 && random() < 0.5) stroke(96, 74, 52, random(25, 60));
    else stroke(46, 66, 84, random(25, 65));
    strokeWeight(1.2);
    const a = -HALF_PI + random(-0.4, 0.4);
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
  noStroke();
  glow(800, 1800, 460, [96, 74, 46], 0.16); // the light pooling between them
}

function fog() {
  for (let i = 0; i < 7; i++) {
    const x = 140 + i * 220 + random(-40, 40);
    glow(x, groundY(i * 220) + random(4, 40), random(220, 330), [150, 178, 200], 0.1);
  }
}

function groundPetals() {
  noStroke();
  for (let i = 0; i < 115; i++) {
    const r = random();
    let x, pal;
    if (r < 0.42) { x = random(470, 800); pal = WARM; }
    else if (r < 0.84) { x = random(800, 1120); pal = COOL; }
    else { x = random(725, 875); pal = GOLD; }
    const y = groundY(x) + random(15, 250);
    const c = pal[floor(random(pal.length))];
    fill(c[0], c[1], c[2], 60 + random(90));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
