function fishPoint(k, s) {
  const h = HEAD_ANG[k];
  const th = h - BODY_ARC * s;
  const wob = 30 * Math.sin(s * 8.2 + k * 2.4) * (0.15 + 0.85 * s);
  const curl = -58 * Math.pow(Math.max(0, 1 - s / 0.22), 1.7);
  const flare = 30 * Math.pow(Math.max(0, (s - 0.78) / 0.22), 2);
  const dr = wob + curl + flare;
  return {
    x: CX + (RXR + dr) * Math.cos(th),
    y: CY + (RYR + dr) * Math.sin(th)
