}

function fishFrame(k, s) {
  const s0 = constrain(s, 0, 1);
  const a = fishPoint(k, s0);
  const b = fishPoint(k, constrain(s0 - 0.01, 0, 1));
  const c = fishPoint(k, constrain(s0 + 0.01, 0, 1));
  let tx = c.x - b.x, ty = c.y - b.y;
  const m = Math.hypot(tx, ty) || 1;
  tx /= m; ty /= m;
  return { x: a.x, y: a.y, tx: tx, ty: ty, nx: -ty, ny: tx, w: bodyW(s0) * SIZE_K[k] };
