function lobePt(bx, by, a, len, wdt, side, phase, t) {
  const perp = a + HALF_PI;
  const wave = Math.sin(t * 4.4 + phase) * len * 0.10 * t;
  const cx = bx + Math.cos(a) * len * t + Math.cos(perp) * wave;
  const cy = by + Math.sin(a) * len * t + Math.sin(perp) * wave;
  const env = Math.sin(t * Math.PI);
  const wOff = wdt * (0.22 + 0.78 * env) * side;
  return [cx + Math.cos(perp) * wOff, cy + Math.sin(perp) * wOff];
}

function finRay(bx, by, a, len, col, alpha, wt, phase) {
  noFill();
  stroke(col[0], col[1], col[2], alpha);
  strokeWeight(wt);
  beginShape();
  const perp = a + HALF_PI;
  for (let i = 0; i <= 4; i++) {
    const t = i / 4;
    const wave = Math.sin(t * 4.4 + phase) * len * 0.10 * t;
    vertex(bx + Math.cos(a) * len * t + Math.cos(perp) * wave,
      by + Math.sin(a) * len * t + Math.sin(perp) * wave);
