    const f = fishFrame(k, sp.s);
    const ang = Math.atan2(f.ty, f.tx);
    for (const side of [-1, 1]) {
      const bx = f.x + f.nx * side * f.w * 0.55;
      const by = f.y + f.ny * side * f.w * 0.55;
      const a = ang + side * sp.spread;
      paintLobe(bx, by, a, sp.len * random(0.88, 1.12), sp.wdt, k * 1.9 + side * 2, finCols);
