        const ra = a + lerp(-0.3, 0.3, i / (sp.rays - 1));
        finRay(bx, by, ra, sp.len * 0.85 * random(0.8, 1), finCols[1], random(30, 55), 2, k + side * 2 + i);
      }
    }
  }
}

function paintRim(k) {
  const rc = k === 0 ? [168, 156, 132] : [122, 26, 16];
  for (let i = 0; i <= 110; i++) {
    const s = i / 110;
    const f = fishFrame(k, s);
    const ang = Math.atan2(f.ty, f.tx);
    for (const side of [-1, 1]) {
      dab(f.x + f.nx * side * f.w * 1.14, f.y + f.ny * side * f.w * 1.14, f.w * 0.3, ang, rc, 95);
    }
  }
}

