// ---------- sky ----------
function sky() {
  const stops = [
    [10, 11, 34, 0.0], [36, 26, 72, 0.26], [82, 40, 84, 0.52],
    [140, 62, 88, 0.73], [196, 96, 84, 0.9], [228, 150, 103, 1.0]
  ];
  const skyAt = (t) => {
    t = constrain(t, 0, 1);
    for (let i = 0; i < stops.length - 1; i++) {
      if (t <= stops[i + 1][3]) {
        const a = stops[i], b = stops[i + 1];
        const k = (t - a[3]) / (b[3] - a[3]);
        return [lerp(a[0], b[0], k), lerp(a[1], b[1], k), lerp(a[2], b[2], k)];
      }
    }
    const l = stops[stops.length - 1];
    return [l[0], l[1], l[2]];
  };
  noStroke();
  for (let y = 0; y < HORIZON; y += 4) {
    const c = skyAt(y / HORIZON);
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 5);
  }
  for (let i = 0; i < 3200; i++) { // painterly dabs
    const y = random(0, HORIZON - 6);
    const x = random(0, W);
    const c = skyAt(y / HORIZON);
    fill(c[0] + random(-16, 16), c[1] + random(-14, 12), c[2] + random(-12, 14), 34);
    push();
    translate(x, y);
    rotate(random(0, TAU));
    ellipse(0, 0, random(10, 30), random(3, 10));
    pop();
  }
  noFill();
  for (let i = 0; i < 12; i++) { // dusk streaks
    const y = HORIZON - random(40, 330);
    const c = skyAt(Math.min(1, (y + random(80, 200)) / HORIZON));
    stroke(c[0] + 12, c[1] + 8, c[2] + 6, random(26, 60));
    strokeWeight(random(6, 16));
    const x0 = random(-150, W * 0.45);
    const x1 = x0 + random(700, 1500);
    const my = y + random(-40, 30);
    bezier(x0, y, lerp(x0, x1, 0.3), my - 50, lerp(x0, x1, 0.7), my + 50, x1, y + random(-25, 25));
  }
}

