function taperedCurve(x0, y0, cx1, cy1, cx2, cy2, x1, y1, w0, w1, c) {
  noFill();
  const n = 40;
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    pts.push({
      x: bezierPoint(x0, cx1, cx2, x1, t),
      y: bezierPoint(y0, cy1, cy2, y1, t),
      w: lerp(w0, w1, t)
    });
  }
  for (let i = 0; i < n; i++) {
    stroke(c[0], c[1], c[2]);
    strokeWeight(pts[i + 1].w);
    line(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
  }
  return pts;
}

