  stroke(16, 12, 27);
  strokeWeight(w);
  line(x, y, x2, y2);
  // warm rim light on the side facing the glow
  let rim = lean * w * 0.38;
  stroke(255, 186, 116, constrain(20 + w * 2.2, 0, 90));
  strokeWeight(max(1, w * 0.28));
  line(x + rim, y, x2 + rim, y2);
  // children bending toward the center
  let n = random() < 0.35 ? 3 : 2;
  let target = -HALF_PI + lean * 0.8;
  for (let i = 0; i < n; i++) {
    let na = lerp(angle, target, 0.15) + random(-0.42, 0.42);
    if (depth <= 2) na += random(0, 0.55); // outer twigs droop
    branch(x2, y2, na, len * random(0.68, 0.82), w * 0.62, depth - 1, lean);
  }
}

function leafCluster(x, y) {
  let d = dist(x, y, GLOW_X, GLOW_Y);
  if (d < 200 && random() < 0.75) return; // keep the light itself visible
  let warm = constrain(map(d, 750, 260, 0, 1), 0, 1);
  for (let i = 0; i < 8; i++) {
    let a = random(TWO_PI);
    let r = random(4, 36);
    let lx = x + cos(a) * r;
    let ly = y + sin(a) * r * 0.72;
    let c = lerpColor(color(16, 32, 24), color(88, 104, 48), warm + random(-0.2, 0.2));
    if (random() < warm * 0.55) c = lerpColor(c, color(216, 148, 104), random(0.5));
    noStroke();
    fill(red(c), green(c), blue(c), random(150, 225));
    ellipse(lx, ly, random(9, 24), random(6, 16), a);
  }
}

function paintFireflies() {
  noStroke();
  for (let i = 0; i < 90; i++) {
    let x = lerp(random(width), 800, random(0.35, 0.75));
    let y = random(320, 1560);
    let s = random(1.4, 3.4);
    fill(255, 214, 140, 28);
    ellipse(x, y, s * 7, s * 7);
    fill(255, 226, 160, 70);
    ellipse(x, y, s * 3.2, s * 3.2);
    fill(255, 246, 214, 230);
    ellipse(x, y, s, s);
  }
  // drifting petals
  for (let i = 0; i < 26; i++) {
    let x = lerp(random(width), 800, random(0.2, 0.7));
    let y = random(300, 1500);
    let c = random() < 0.5 ? color(238, 164, 172) : color(255, 214, 150);
    fill(red(c), green(c), blue(c), random(120, 200));
    ellipse(x, y, random(6, 11), random(3, 5), random(TWO_PI));
  }
}

function paintForeground() {
  // grass
  for (let i = 0; i < 750; i++) {
    let x = random(width);
    let depthT = random();
    let yb = 1650 + pow(depthT, 0.8) * 350;
    let h = random(18, 60 + depthT * 50);
    let bend = random(-26, 26) + (x - 800) * 0.015;
    let nearLight = constrain(1 - abs(x - 800) / 420, 0, 1);
    let c = lerpColor(color(9, 22, 17), color(52, 72, 38), random(0.2, 1));
    if (random() < nearLight * 0.6) c = lerpColor(c, color(150, 130, 70), random(0.4));
    stroke(red(c), green(c), blue(c), 210);
    strokeWeight(random(1.4, 3.6));
    noFill();
    beginShape();
    vertex(x, yb);
    quadraticVertex(x + bend * 0.3, yb - h * 0.6, x + bend, yb - h);
    endShape();
  }
  // small flowers
  for (let i = 0; i < 70; i++) {
    let x = lerp(random(width), 800, random(0, 0.6));
    let y = 1720 + random(270);
    let stemH = random(14, 34);
    stroke(20, 40, 24, 160);
    strokeWeight(1.4);
    line(x, y, x + random(-4, 4), y - stemH);
    let c = random() < 0.4 ? color(232, 138, 160)
          : (random() < 0.5 ? color(255, 210, 122) : color(240, 240, 235));
    noStroke();
    fill(red(c), green(c), blue(c), 220);
    ellipse(x + random(-4, 4), y - stemH, random(4, 8), random(4, 8));
    fill(255, 240, 200, 200);
    ellipse(x + random(-4, 4), y - stemH, 2, 2);
  }
}

function paintVignette() {
  let g = drawingContext.createRadialGradient(800, 920, 500, 800, 1000, 1420);
  g.addColorStop(0, 'rgba(4, 5, 16, 0)');
  g.addColorStop(0.7, 'rgba(4, 5, 16, 0.12)');
  g.addColorStop(1, 'rgba(3, 4, 12, 0.6)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);
  let g2 = drawingContext.createLinearGradient(0, 0, 0, 420);
  g2.addColorStop(0, 'rgba(2, 3, 10, 0.45)');
  g2.addColorStop(1, 'rgba(2, 3, 10, 0)');
  drawingContext.fillStyle = g2;
  drawingContext.fillRect(0, 0, width, 420);
}

function paintGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (random() - 0.5) * 14;
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
  paint();
}

function glow(x, y, r, c) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, c);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TWO_PI);
  ctx.fill();
}

function ribbon(x0, y0, x1, y1, cA, cB, w0, w1, ph) {
  const ctx = drawingContext;
  const a = color(cA);
  const b = color(cB);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const steps = 170;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const nx = (noise(t * 3.2 + ph) - 0.5) * 460;
    const ny = (noise(t * 3.2 + ph + 9.1) - 0.5) * 360 + sin(t * PI) * -160;
    const x = lerp(x0, x1, t) + nx;
    const y = lerp(y0, y1, t) + ny;
    const rr = lerp(w0, w1, sin(t * PI)) * (0.65 + 0.7 * noise(t * 8 + ph));
    const c = lerpColor(a, b, t);
    ctx.fillStyle = `rgba(${int(red(c))},${int(green(c))},${int(blue(c))},0.14)`;
    ctx.beginPath();
    ctx.ellipse(x, y, rr, rr * 0.7, noise(t * 5 + ph) * PI, 0, TWO_PI);
    ctx.fill();
  }
  ctx.restore();
}

function paint() {
  const ctx = drawingContext;

  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0, '#070b1d');
  bg.addColorStop(0.45, '#141a3a');
  bg.addColorStop(0.75, '#3a1638');
  bg.addColorStop(1, '#12081a');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < 700; i++) {
    const x = random(width);
    const y = random(height);
    const a = noise(x * 0.003, y * 0.003) * TWO_PI;
    const len = random(12, 70);
    ctx.strokeStyle = `hsla(${random(220, 320)},70%,70%,0.05)`;
    ctx.lineWidth = random(0.5, 1.5);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + cos(a) * len, y + sin(a) * len);
    ctx.stroke();
  }

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 26; i++) {
    const x = random(width);
    const y = random(height * 0.85);
    const r = random(180, 650);
    const hue = random([210, 280, 330, 20]);
    glow(x, y, r, `hsla(${hue},80%,60%,${random(0.025, 0.07)})`);
  }
  ctx.restore();

  const pts = [];
  for (let i = 0; i < 110; i++) {
    pts.push({ x: random(width), y: random(height * 0.72), r: random(0.6, 2.2) });
  }
  strokeWeight(0.7);
  for (let i = 0; i < pts.length; i++) {
    for (let j = i + 1; j < pts.length; j++) {
      const d = dist(pts[i].x, pts[i].y, pts[j].x, pts[j].y);
      if (d < 170) {
        stroke(190, 210, 255, map(d, 0, 170, 26, 0));
        line(pts[i].x, pts[i].y, pts[j].x, pts[j].y);
      }
    }
  }
  noStroke();
  fill(220, 230, 255, 180);
  for (const p of pts) ellipse(p.x, p.y, p.r, p.r);

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glow(560, 1180, 620, 'rgba(80,180,255,0.34)');
  glow(1050, 820, 650, 'rgba(255,90,160,0.32)');
  glow(800, 1000, 430, 'rgba(255,205,120,0.42)');
  ctx.restore();

  ribbon(230, 1780, 1380, 260, '#67e8ff', '#ff7ab8', 8, 26, 1.7);
  ribbon(1370, 1780, 220, 260, '#ff9a6a', '#9be7ff', 26, 8, 4.2);

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  glow(800, 1000, 240, 'rgba(255,240,200,0.75)');
  glow(800, 1000, 90, 'rgba(255,255,230,0.9)');
  noFill();
  stroke(255, 220, 170, 40);
  strokeWeight(2);
  ellipse(800, 1000, 620, 620);
  stroke(150, 190, 255, 25);
  ellipse(800, 1000, 760, 760);
  ctx.restore();

  for (let i = 0; i < 7000; i++) {
    const x = random(width);
    const y = random(height);
    const s = random(0.6, 1.8);
    if (random() < 0.5) ctx.fillStyle = `rgba(255,255,255,${random(0.01, 0.05)})`;
    else ctx.fillStyle = `rgba(0,0,0,${random(0.02, 0.07)})`;
    ctx.fillRect(x, y, s, s);
  }

  ctx.save();
  ctx.globalCompositeOperation = 'source-over';
  const vg = ctx.createRadialGradient(width / 2, height / 2, height * 0.25, width / 2, height / 2, height * 0.75);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  // ---- night sky ----
  const cTop = color(15, 13, 38);
  const cMid = color(45, 35, 80);
  const cLow = color(72, 46, 92);
  noStroke();
  for (let y = 0; y < 2000; y += 4) {
    let c;
    if (y < 900) c = lerpColor(cTop, cMid, y / 900);
    else c = lerpColor(cMid, cLow, (y - 900) / 1100);
    fill(c);
    rect(0, y, 1600, 5);
  }

  // ---- stars ----
  for (let i = 0; i < 260; i++) {
    const x = random(1600);
    const y = random(0, 1250);
    const r = random(0.8, 2.8);
    const a = random(50, 190);
    noStroke();
    fill(255, 250, 235, a);
    circle(x, y, r * 2);
    if (r > 2.1) {
      fill(255, 245, 220, a * 0.16);
      circle(x, y, r * 7);
    }
  }

  // ---- ambient glow behind the heart ----
  let g = ctx.createRadialGradient(800, 560, 40, 800, 560, 800);
  g.addColorStop(0, 'rgba(255,214,130,0.50)');
  g.addColorStop(0.45, 'rgba(255,180,100,0.16)');
  g.addColorStop(1, 'rgba(255,170,90,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1600, 2000);

  // ---- ground ----
  for (let y = 1740; y < 2000; y += 4) {
    const t = (y - 1740) / 260;
    noStroke();
    fill(lerpColor(color(17, 23, 50), color(5, 6, 15), t));
    rect(0, y, 1600, 5);
  }

  // warm light pool on the ground
  ctx.save();
  ctx.translate(800, 1935);
  ctx.scale(1, 0.32);
  let g2 = ctx.createRadialGradient(0, 0, 10, 0, 0, 560);
  g2.addColorStop(0, 'rgba(255,205,120,0.30)');
  g2.addColorStop(1, 'rgba(255,205,120,0)');
  ctx.fillStyle = g2;
  ctx.beginPath();
  ctx.arc(0, 0, 560, 0, TWO_PI);
  ctx.fill();
  ctx.restore();

  // ---- roots intertwining ----
  stroke(8, 10, 24);
  strokeCap(ROUND);
  for (let i = 0; i < 4; i++) {
    strokeWeight(random(4, 9));
    bezier(170 + i * 22, 2000, 320 + random(-60, 60), 1925 + random(-40, 40),
      560 + random(-80, 80), 2005 + random(-30, 30), 800, 1985 + random(-15, 15));
    bezier(1430 - i * 22, 2000, 1280 + random(-60, 60), 1925 + random(-40, 40),
      1040 + random(-80, 80), 2005 + random(-30, 30), 800, 1985 + random(-15, 15));
  }

  // ---- trunks ----
  trunkCurve(sampleQuad([140, 2010], [190, 1450], [600, 820], 28), 150, 44, color(12, 15, 32));
  trunkCurve(sampleQuad([1460, 2010], [1410, 1450], [1000, 820], 28), 150, 44, color(12, 15, 32));
  // warm rim light on the inner, heart-facing sides
  trunkCurve(sampleQuad([162, 2010], [217, 1455], [624, 826], 28), 54, 16, color(255, 190, 110, 85));
  trunkCurve(sampleQuad([1438, 2010], [1383, 1455], [976, 826], 28), 54, 16, color(255, 190, 110, 85));
  // cool rim on the outer sides
  trunkCurve(sampleQuad([116, 2010], [163, 1445], [576, 814], 28), 38, 12, color(80, 100, 170, 65));
  trunkCurve(sampleQuad([1484, 2010], [1437, 1445], [1024, 814], 28), 38, 12, color(80, 100, 170, 65));

  // ---- limbs ----
  limb([600, 830], [520, 700], [430, 640], 46, 18);
  limb([600, 830], [560, 640], [560, 470], 40, 15);
  limb([600, 830], [645, 560], [700, 380], 34, 12);
  limb([600, 830], [480, 780], [330, 780], 36, 14);
  limb([700, 380], [745, 335], [800, 320], 16, 9);
  limb([1000, 830], [1080, 700], [1170, 640], 46, 18);
  limb([1000, 830], [1040, 640], [1040, 470], 40, 15);
  limb([1000, 830], [955, 560], [900, 380], 34, 12);
  limb([1000, 830], [1120, 780], [1270, 780], 36, 14);
  limb([900, 380], [855, 335], [800, 320], 16, 9);

  // ---- twigs ----
  twigs(430, 640, -PI / 2, 70, 8, 3);
  twigs(560, 470, -PI / 2 - 0.4, 65, 7, 3);
  twigs(700, 380, -PI / 2 - 0.2, 60, 6, 3);
  twigs(330, 780, -PI / 2 - 0.5, 60, 7, 3);
  twigs(1170, 640, -PI / 2, 70, 8, 3);
  twigs(1040, 470, -PI / 2 + 0.4, 65, 7, 3);
  twigs(900, 380, -PI / 2 + 0.2, 60, 6, 3);
  twigs(1270, 780, -PI / 2 + 0.5, 60, 7, 3);

  // ---- foliage arching into a heart shape ----
  leafCluster(430, 640, 1.15);
  leafCluster(560, 470, 1.0);
  leafCluster(700, 380, 0.9);
  leafCluster(800, 318, 0.85);
  leafCluster(900, 380, 0.9);
  leafCluster(1040, 470, 1.0);
  leafCluster(1170, 640, 1.15);
  leafCluster(330, 780, 1.3);
  leafCluster(1270, 780, 1.3);
  leafCluster(620, 300, 0.7);
  leafCluster(980, 300, 0.7);

  // ---- heart glow layers ----
  for (let i = 10; i >= 1; i--) {
    ctx.fillStyle = 'rgba(255,200,110,0.05)';
    heartPath(800, 560, 400 * (1 + i * 0.09));
    ctx.fill();
  }

  // ---- glowing heart core ----
  ctx.save();
  ctx.shadowColor = 'rgba(255,190,100,0.9)';
  ctx.shadowBlur = 70;
  let gh = ctx.createRadialGradient(800, 480, 30, 800, 560, 480);
  gh.addColorStop(0, '#fff7dd');
  gh.addColorStop(0.45, '#ffd27a');
  gh.addColorStop(1, '#ff9a5c');
  ctx.fillStyle = gh;
  heartPath(800, 560, 400);
  ctx.fill();
  ctx.restore();

  // inner highlight
  ctx.fillStyle = 'rgba(255,250,230,0.5)';
  heartPath(768, 478, 230);
  ctx.fill();

  // ---- light rays ----
  ctx.save();
  ctx.translate(800, 560);
  for (let k = 0; k < 9; k++) {
    ctx.save();
    ctx.rotate(k * (TWO_PI / 9) + 0.2);
    ctx.fillStyle = 'rgba(255,215,140,0.055)';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(1150, -30);
    ctx.lineTo(1150, 30);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();

  // ---- shaft of light falling toward the figures ----
  ctx.save();
  ctx.translate(800, 1300);
  ctx.scale(0.16, 1);
  let gs = ctx.createRadialGradient(0, 0, 20, 0, 0, 520);
  gs.addColorStop(0, 'rgba(255,210,130,0.16)');
  gs.addColorStop(1, 'rgba(255,210,130,0)');
  ctx.fillStyle = gs;
  ctx.beginPath();
  ctx.arc(0, 0, 520, 0, TWO_PI);
  ctx.fill();
  ctx.restore();

  // ---- two small figures beneath the heart ----
  noStroke();
  fill(0, 0, 0, 90);
  ellipse(800, 1940, 340, 44);
  ctx.save();
  ctx.shadowColor = 'rgba(255,205,120,0.95)';
  ctx.shadowBlur = 36;
  fill(9, 10, 22);
  ellipse(692, 1858, 155, 178);
  circle(742, 1750, 74);
  ellipse(908, 1858, 155, 178);
  circle(858, 1750, 74);
  ctx.restore();

  // ---- grass ----
  for (let i = 0; i < 300; i++) {
    const x = random(1600);
    const by = random(1750, 2000);
    const h = random(10, 46);
    const bend = random(-16, 16);
    stroke(random(24, 40), random(36, 60), random(80, 150), 140);
    strokeWeight(random(1.5, 3));
    line(x, by, x + bend, by - h);
  }

  // ---- fireflies ----
  for (let i = 0; i < 110; i++) {
    const ang = random(TWO_PI);
    const r = pow(random(1), 0.6) * 830;
    const x = 800 + cos(ang) * r * 1.05;
    const y = 560 + sin(ang) * r * 0.85 + 130;
    if (x < 4 || x > 1596 || y < 4 || y > 1996) continue;
    const s = random(2, 6.5);
    const a = random(90, 230);
    ctx.save();
    ctx.shadowColor = 'rgba(255,215,140,0.9)';
    ctx.shadowBlur = 12;
    ctx.fillStyle = 'rgba(255,' + floor(random(200, 255)) + ',130,' + (a / 255).toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(x, y, s, 0, TWO_PI);
    ctx.fill();
    ctx.restore();
  }

  // ---- painterly grain ----
  noStroke();
  for (let i = 0; i < 5000; i++) {
    if (random() < 0.5) fill(255, 4); else fill(0, 5);
    rect(random(1600), random(2000), 2, 2);
  }

  // ---- vignette ----
  const vg = ctx.createRadialGradient(800, 950, 480, 800, 1000, 1380);
  vg.addColorStop(0, 'rgba(4,4,12,0)');
  vg.addColorStop(1, 'rgba(4,4,12,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, 1600, 2000);
}

// ---------- helpers ----------

function sampleQuad(p0, c, p1, n) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n, u = 1 - t;
    pts.push([
      u * u * p0[0] + 2 * u * t * c[0] + t * t * p1[0],
      u * u * p0[1] + 2 * u * t * c[1] + t * t * p1[1]
    ]);
  }
  return pts;
}

function trunkCurve(pts, w0, w1, col) {
  noStroke();
  fill(col);
  for (let i = 0; i < pts.length - 1; i++) {
    const t = i / (pts.length - 1);
    const mx = (pts[i][0] + pts[i + 1][0]) / 2;
    const my = (pts[i][1] + pts[i + 1][1]) / 2;
    circle(mx, my, lerp(w0, w1, t));
  }
}

function limb(p0, c, p1, w0, w1) {
  trunkCurve(sampleQuad(p0, c, p1, 22), w0, w1, color(12, 15, 32));
}

function twigs(x, y, ang, len, w, depth) {
  if (depth <= 0 || len < 14) {
    noStroke();
    fill(22, 35, 63);
    circle(x, y, random(18, 36));
    return;
  }
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  stroke(12, 15, 32);
  strokeWeight(w);
  strokeCap(ROUND);
  line(x, y, x2, y2);
  const n = 2 + floor(random(2));
  for (let i = 0; i < n; i++) {
    twigs(x2, y2, ang + random(-1.0, 1.0), len * random(0.6, 0.78), w * 0.62, depth - 1);
  }
}

function leafCluster(cx, cy, s) {
  const cols = [color(20, 31, 56), color(24, 42, 71), color(16, 26, 48), color(29, 51, 85)];
  noStroke();
  for (let i = 0; i < 9; i++) {
    fill(random(cols));
    circle(cx + random(-55, 55) * s, cy + random(-42, 42) * s, random(26, 58) * s * 2);
  }
  // rim light facing the glowing heart
  const dx = 800 - cx, dy = 560 - cy;
  const d = sqrt(dx * dx + dy * dy) || 1;
  fill(74, 96, 156, 70);
  for (let i = 0; i < 4; i++) {
    const r = random(16, 34) * s;
    circle(cx + random(-30, 30) * s + (dx / d) * r * 0.9,
           cy + random(-24, 24) * s + (dy / d) * r * 0.9, r * 2);
  }
}

function heartPath(cx, cy, s) {
  const c = drawingContext;
  c.beginPath();
  c.moveTo(cx, cy + s * 0.3);
  c.bezierCurveTo(cx - s * 1.2, cy - s * 0.6, cx - s * 0.6, cy - s * 1.5, cx, cy - s * 0.7);
  c.bezierCurveTo(cx + s * 0.6, cy - s * 1.5, cx + s * 1.2, cy - s * 0.6, cx, cy + s * 0.3);
  c.closePath();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  strokeCap(ROUND);
