function skyCol(y) {
  const s = [
    [0,            [13, 8, 32]],
    [0.24 * height, [44, 19, 70]],
    [0.44 * height, [108, 41, 95]],
    [0.60 * height, [193, 82, 99]],
    [0.73 * height, [249, 138, 95]],
    [0.85 * height, [255, 197, 108]],
    [height,       [255, 216, 132]]
  ];
  for (let i = 0; i < s.length - 1; i++) {
    if (y >= s[i][0] && y <= s[i + 1][0]) {
      const t = (y - s[i][0]) / (s[i + 1][0] - s[i][0]);
      return [lerp(s[i][1][0], s[i + 1][1][0], t),
              lerp(s[i][1][1], s[i + 1][1][1], t),
              lerp(s[i][1][2], s[i + 1][1][2], t)];
    }
  }
  return s[s.length - 1][1];
}

function paintSky() {
  for (let y = 0; y < height; y++) {
    const c = skyCol(y);
    stroke(c[0], c[1], c[2]);
    line(0, y, width, y);
  }
}

function paintStars() {
  for (let i = 0; i < 190; i++) {
    const x = random(width);
    const y = random(0, 0.5 * height);
