    const w = random(280, 760);
    const h = w * random(0.07, 0.15);
    if (back) {
      fill(255, 186, 168, random(8, 16));
      ellipse(x, y, w, h);
      fill(255, 214, 180, random(6, 12));
      ellipse(x, y + h * 0.35, w * 0.92, h * 0.55);
    } else {
      fill(64, 28, 74, random(14, 24));
      ellipse(x, y, w, h);
      fill(255, 170, 130, random(5, 10));
      ellipse(x, y - h * 0.3, w * 0.85, h * 0.5);
