function bird(x, y, s, r, g, b, a) {
  push();
  translate(x, y);
  scale(s);
  stroke(r, g, b, a);
  strokeWeight(3.4);
  noFill();
  beginShape();
  vertex(-17, 0);
  quadraticVertex(-8.5, -10, 0, 0);
  quadraticVertex(8.5, -10, 17, 0);
  endShape();
  pop();
}

function ridgeA(x) { return 1150 + noise(x * 0.004, 5) * 120; }
function ridgeB(x) { return 1300 + noise(x * 0.005, 15) * 100; }
function ridgeC(x) {
  const d = x - 800;
  return 1545 + noise(x * 0.004, 25) * 40 - 60 * Math.exp(-(d * d) / (240 * 240));
}

function paintHills() {
  noStroke();
  fill(68, 31, 82);
  beginShape();
  vertex(0, ridgeA(0));
  for (let x = 0; x <= width; x += 40) vertex(x, ridgeA(x));
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  fill(45, 21, 59);
  beginShape();
  vertex(0, ridgeB(0));
  for (let x = 0; x <= width; x += 40) vertex(x, ridgeB(x));
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  fill(23, 10, 33);
  beginShape();
  vertex(0, ridgeC(0));
  for (let x = 0; x <= width; x += 40) vertex(x, ridgeC(x));
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  fill(255, 188, 118, 20);
  ellipse(800, 1545, 580, 110);
}

