function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
}

function draw() {
  noLoop();
  const W = width, H = height;
  colorMode(RGB, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  noStroke();
  fill(8, 6, 18);
  rect(0, 0, W, H);
  for (let y = 0; y < H; y += 4) {
    const t = y / H;
    const c = lerpColor(color(31, 18, 58), color(5, 4, 14), t);
    stroke(red(c), green(c), blue(c), 255);
    strokeWeight(4);
    line(0, y, W, y);
  }
  noStroke();
  for (let i = 0; i < 110; i++) {
    const x = random(W), y = random(H), r = random(90, 520);
    const cool = random() < 0.55;
    fill(cool ? color(38, 70, 150, 16) : color(120, 45, 110, 14));
    ellipse(x, y, r, r * random(0.35, 0.9));
  }

  const cx = W / 2, cy = H * 0.52;

  function pathPoint(t, left) {
    const seedA = left ? 0 : 40;
    const x0 = left ? -0.18 * W : 1.18 * W;
    const x1 = left ? 1.18 * W : -0.18 * W;
    let x = lerp(x0, x1, t);
    let y = lerp(1.14 * H, -0.14 * H, t);
    x += (noise(t * 5.2 + seedA) - 0.5) * W * 0.34;
    y += (noise(t * 7.1 + seedA + 9) - 0.5) * H * 0.16;
    x += sin(t * TWO_PI + (left ? 0 : PI)) * W * 0.11 * sin(t * PI);
    y += sin(t * PI * 3 + (left ? 0.7 : 2.1)) * H * 0.035 * sin(t * PI);
    return { x, y };
  }

  function ribbon(left, c1, c2) {
    const N = 110;
    const pts = [];
    for (let i = 0; i <= N; i++) pts.push(pathPoint(i / N, left));
    const layers = [
      { w: 190, a: 16 },
      { w: 130, a: 34 },
      { w: 76, a: 78 },
      { w: 34, a: 210 },
      { w: 12, a: 255 }
    ];
    noFill();
    for (const L of layers) {
      strokeWeight(L.w);
      for (let i = 0; i < N; i++) {
        const t = (i + 0.5) / N;
        const c = lerpColor(c1, c2, t);
        stroke(red(c), green(c), blue(c), L.a);
        line(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
      }
    }
  }

  blendMode(BLEND);
  ribbon(true, color(255, 72, 132), color(255, 196, 96));
  ribbon(false, color(126, 226, 255), color(122, 112, 255));

  blendMode(ADD);
  for (let i = 0; i < 70; i++) {
    const t = i / 70;
    const r = lerp(26, 560, t);
    const a = lerp(120, 3, t);
    fill(255, 190 + 60 * (1 - t), 110 + 90 * (1 - t), a);
    ellipse(cx, cy, r * 1.25, r);
  }
  noFill();
  for (let i = 0; i < 5; i++) {
    push();
    translate(cx, cy);
    rotate(i * 0.22 - 0.4);
    stroke(255, 226, 170, 70 - i * 10);
    strokeWeight(5 - i * 0.7);
    ellipse(0, 0, 300 + i * 70, 130 + i * 34);
    pop();
  }
  noStroke();
  fill(255, 246, 220, 235);
  circle(cx, cy, 96);
  fill(255, 255, 255, 255);
  circle(cx, cy, 40);

  for (let i = 0; i < 320; i++) {
    let x, y;
    if (random() < 0.55) {
      const p = pathPoint(random(), random() < 0.5);
      x = p.x + (random() - 0.5) * 190;
      y = p.y + (random() - 0.5) * 190;
    } else {
      x = random(W);
      y = random(H);
    }
    const d = dist(x, y, cx, cy);
    const a = constrain(map(d, 0, 950, 150, 12), 10, 170);
    const warm = random() < 0.5;
    fill(warm ? color(255, 205, 150, a) : color(170, 220, 255, a));
    circle(x, y, random(1.2, 4.2));
  }

  blendMode(BLEND);
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(cx, cy, H * 0.22, cx, cy, H * 0.86);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(2,2,8,0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  angleMode(RADIANS);
}

function draw() {
  background(17, 35, 42);

  // 深色纸面中的隐约光场。
  noStroke();
  for (let i = 100; i > 0; i--) {
    const t = i / 100;
    fill(112, 128, 111, 1.8);
    ellipse(805, 1030, 450 + 1010 * t, 580 + 1050 * t);
  }

  for (let i = 0; i < 26000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.003, y * 0.003);
    stroke(143, 162, 150, random(3, 13) * n);
    strokeWeight(random(0.5, 1.8));
    point(x, y);
  }

  // 两股不同的物质，分别弯向同一个空处。
  const left = makeRibbon([
    [690, 365, 305, 460, 255, 1135, 620, 1390],
    [620, 1390, 820, 1540, 1110, 1530, 1300, 1740]
  ], 181, 0);

  const right = makeRibbon([
    [965, 1590, 1350, 1370, 1325, 780, 1030, 575],
    [1030, 575, 825, 420, 510, 450, 295, 260]
  ], 156, 7);

  // 光不是实心的圆，而是被空处慢慢聚拢的颜色。
  noStroke();
  for (let i = 75; i > 0; i--) {
    const t = i / 75;
    fill(223, 181, 101, 1.1);
    ellipse(803, 1090, 135 + 500 * t, 180 + 690 * t);
  }

  drawThreads(left, right);

  paintRibbon(left, {
    dark: [94, 45, 39],
    middle: [183, 84, 59],
    light: [239, 164, 112]
  });

  paintRibbon(right, {
    dark: [65, 103, 102],
    middle: [143, 169, 152],
    light: [228, 223, 184]
  });

  // 一块尚未圆满的形体，被托住而非被包裹。
  drawSeed(793, 1090, 63, 94, -0.19,
           [193, 158, 97], [241, 218, 159], 3);

  drawSeed(874, 980, 19, 29, 0.42,
           [112, 142, 128], [198, 207, 167], 11);

  drawSeed(737, 886, 10, 16, -0.28,
           [186, 132, 78], [244, 205, 133], 18);

  // 细小的明处，没有组成星座，也不指向任何符号。
  noStroke();
  for (let i = 0; i < 105; i++) {
    const a = random(TWO_PI);
    const r = pow(random(), 0.72);
    const x = 802 + cos(a) * r * 225;
    const y = 1058 + sin(a) * r * 315;
    fill(237, 204, 140, random(18, 85));
    const s = random(0.8, 2.5);
    ellipse(x, y, s, s);
  }

  // 全画幅的颗粒使线、光与色块落回同一张纸上。
  strokeWeight(1);
  for (let i = 0; i < 56000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.53) {
      stroke(235, 221, 190, random(3, 12));
    } else {
      stroke(4, 17, 23, random(5, 20));
    }
    point(x, y);
  }
}

function makeRibbon(curves, breadth, phase) {
  const pts = [];
  const count = 400;

  for (let i = 0; i <= count; i++) {
    const t = i / count;
    const segment = t < 0.5 ? 0 : 1;
    const u = segment === 0 ? t * 2 : (t - 0.5) * 2;
    const c = curves[segment];

    const x = bezierPoint(c[0], c[2], c[4], c[6], u);
    const y = bezierPoint(c[1], c[3], c[5], c[7], u);
    const dx = bezierTangent(c[0], c[2], c[4], c[6], u);
    const dy = bezierTangent(c[1], c[3], c[5], c[7], u);
    const len = sqrt(dx * dx + dy * dy);

    const swell = pow(sin(PI * t), 0.67);
    const variation = 0.86 + 0.19 * sin(t * TWO_PI + phase);
    const roughness = (noise(t * 17, phase + 30) - 0.5) * 10;
    const w = 2 + breadth * swell * variation + roughness * swell;

    pts.push({
      x, y,
      nx: -dy / len,
      ny: dx / len,
      w,
      t,
      phase
    });
  }
  return pts;
}

function ribbonPoint(p, s) {
  return {
    x: p.x + p.nx * p.w * s,
    y: p.y + p.ny * p.w * s
  };
}

function attachment(ribbon, t) {
  const p = ribbon[floor(t * (ribbon.length - 1))];
  return ribbonPoint(p, -0.89);
}

function drawThreads(left, right) {
  noFill();

  for (let i = 0; i < 62; i++) {
    const u = i / 61;
    const a = attachment(left, 0.22 + u * 0.16);
    const b = attachment(right, 0.29 + u * 0.15);
    const low = max(a.y, b.y) + 205 + 56 * sin(PI * u);

    stroke(5, 20, 25, 34);
    strokeWeight(2.6);
    bezier(
      a.x, a.y + 5,
      a.x + 125, low + 5,
      b.x - 140, low + 5,
      b.x, b.y + 5
    );

    const bright = i % 9 === 0;
    stroke(
      bright ? 242 : 188,
      bright ? 211 : 164,
      bright ? 151 : 112,
      bright ? 125 : 53
    );
    strokeWeight(bright ? 1.45 : 0.72);
    bezier(
      a.x, a.y,
      a.x + 125, low,
      b.x - 140, low,
      b.x, b.y
    );
  }
}

function paintRibbon(ribbon, palette) {
  // 用相邻的薄色层塑造柔软、略带风化的厚度。
  noStroke();
  const strips = 110;

  for (let k = 0; k < strips; k++) {
    const s0 = -1 + 2 * k / strips;
    const s1 = -1 + 2 * (k + 1) / strips;
    const s = (s0 + s1) / 2;

    const crest = exp(-pow((s + 0.31) / 0.62, 2));
    let c = mixRGB(palette.dark, palette.middle, 0.35 + crest * 0.65);
    c = mixRGB(c, palette.light, crest * 0.53);

    fill(c[0], c[1], c[2]);
    beginShape();
    for (const p of ribbon) {
      const q = ribbonPoint(p, s0);
      vertex(q.x, q.y);
    }
    for (let j = ribbon.length - 1; j >= 0; j--) {
      const q = ribbonPoint(ribbon[j], s1);
      vertex(q.x, q.y);
    }
    endShape(CLOSE);
  }

  // 沿形体走向的纤维，不使用规则轮廓线。
  noFill();
  for (let k = 0; k < 185; k++) {
    const s = random(-0.99, 0.99);
    const start = floor(random(0, 90));
    const finish = floor(random(290, ribbon.length));
    const pale = random() < 0.64;

    if (pale) {
      stroke(...palette.light, random(8, 29));
    } else {
      stroke(...palette.dark, random(13, 38));
    }
    strokeWeight(random(0.45, 1.25));

    beginShape();
    for (let j = start; j < finish; j += 2) {
      const p = ribbon[j];
      const drift = (noise(j * 0.022, k * 0.11) - 0.5) * 0.035;
      const q = ribbonPoint(p, constrain(s + drift, -1, 1));
      vertex(q.x, q.y);
    }
    endShape();
  }

  // 细密色斑随曲面分布。
  noStroke();
  for (let i = 0; i < 14500; i++) {
    const p = ribbon[floor(random(4, ribbon.length - 4))];
    const s = random(-0.98, 0.98);
    const q = ribbonPoint(p, s);
    const c = random() < 0.6 ? palette.light : palette.dark;
    fill(c[0], c[1], c[2], random(8, 37));
    const d = random(0.6, 2.4);
    ellipse(q.x, q.y, d, d * random(0.6, 1.4));
  }

  // 面向空处的一线反光，断续而不封闭。
  noFill();
  stroke(...palette.light, 104);
  strokeWeight(1.15);
  beginShape();
  for (let j = 32; j < ribbon.length - 50; j++) {
    const q = ribbonPoint(ribbon[j], -0.985);
    vertex(q.x, q.y);
  }
  endShape();
}

function drawSeed(x, y, rx, ry, angle, dark, light, phase) {
  push();
  translate(x, y);
  rotate(angle);

  noStroke();
  fill(5, 22, 28, 34);
  ellipse(8, 14, rx * 2.15, ry * 2.1);

  // 不规则的外壳保留其自身的边界。
  for (let layer = 0; layer < 52; layer++) {
    const t = layer / 52;
    const scale = 1 - t * 0.96;
    const c = mixRGB(dark, light, pow(t, 0.65) * 0.88);
    fill(c[0], c[1], c[2]);

    beginShape();
    for (let j = 0; j < 100; j++) {
      const a = TWO_PI * j / 100;
      const irregular = 0.93
        + 0.065 * sin(3 * a + phase)
        + 0.035 * cos(5 * a - phase);
      vertex(
        cos(a) * rx * scale * irregular - t * rx * 0.24,
        sin(a) * ry * scale * irregular - t * ry * 0.20
      );
    }
    endShape(CLOSE);
  }

  // 一道细小的不完整处，不被掩饰。
  noFill();
  stroke(74, 81, 66, 105);
  strokeWeight(max(0.7, rx * 0.018));
  beginShape();
  vertex(rx * 0.13, -ry * 0.87);
  bezierVertex(
    -rx * 0.12, -ry * 0.47,
    rx * 0.32, -ry * 0.26,
    rx * 0.02, ry * 0.04
  );
  endShape();

  stroke(249, 227, 170, 145);
  strokeWeight(0.85);
  beginShape();
  vertex(rx * 0.10 - 2, -ry * 0.81);
  bezierVertex(
    -rx * 0.13 - 2, -ry * 0.47,
    rx * 0.27 - 2, -ry * 0.25,
    -2, ry * 0.02
  );
  endShape();

  pop();
}

function mixRGB(a, b, t) {
  return [
    lerp(a[0], b[0], t),
    lerp(a[1], b[1], t),
    lerp(a[2], b[2], t)
  ];
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  angleMode(RADIANS);
}

const INK = [18, 30, 40];
const GOLD = [224, 185, 119];

function rgba(c, a) {
  return `rgba(${c[0]},${c[1]},${c[2]},${a})`;
}

function blend(a, b, t) {
  return [
    lerp(a[0], b[0], t),
    lerp(a[1], b[1], t),
    lerp(a[2], b[2], t)
  ];
}

function glow(x, y, rx, ry, c, opacity) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(rx, ry);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
  g.addColorStop(0, rgba(c, opacity));
  g.addColorStop(0.5, rgba(c, opacity * 0.35));
  g.addColorStop(1, rgba(c, 0));
  ctx.fillStyle = g;
  ctx.fillRect(-1, -1, 2, 2);
  ctx.restore();
}

function silhouette(b, a) {
  return 0.92
    + 0.065 * sin(3 * a + b.phase)
    + 0.035 * sin(5 * a - b.phase)
    + 0.075 * (
      noise(3 + cos(a) * 1.7, 3 + sin(a) * 1.7, b.seed) - 0.5
    );
}

function shorePoint(b, a, s) {
  const r = silhouette(b, a);
  return {
    x: b.x + b.shiftX * (1 - s) + cos(a) * b.rx * s * r,
    y: b.y + b.shiftY * (1 - s) + sin(a) * b.ry * s * r
  };
}

function shore(b) {
  noStroke();

  // 不透明的色层：两种物质各自保留自己的肌理。
  for (let i = 0; i < 115; i++) {
    const t = i / 114;
    const s = 1 - t * 0.965;
    let c;
    if (t < 0.57) {
      c = blend(b.edge, b.middle, pow(t / 0.57, 0.75));
    } else {
      c = blend(b.middle, b.light, pow((t - 0.57) / 0.43, 1.4));
    }
    fill(...c);
    beginShape();
    for (let j = 0; j < 200; j++) {
      const a = TWO_PI * j / 200;
      const p = shorePoint(b, a, s);
      const rough = 0.65 * sin(j * 2.7 + i * 1.8);
      vertex(p.x + rough, p.y + rough);
    }
    endShape(CLOSE);
  }

  // 断续的等高线，像沉积，也像被时间留下的掌纹。
  noFill();
  for (let k = 0; k < 83; k++) {
    const s = 0.12 + k * 0.0105;
    const start = random(TWO_PI);
    const span = random(0.7, 4.9);
    const c = k % 4 === 0 ? b.light : b.edge;
    stroke(...c, random(20, 62));
    strokeWeight(random(0.45, 1.5));
    beginShape();
    for (let a = start; a <= start + span; a += 0.023) {
      const p = shorePoint(b, a, s);
      vertex(
        p.x + 1.5 * sin(a * 18 + k),
        p.y + 1.2 * cos(a * 13 - k)
      );
    }
    endShape();
  }

  // 颜料颗粒。
  noStroke();
  for (let i = 0; i < 14500; i++) {
    const a = random(TWO_PI);
    const s = sqrt(random()) * 0.985;
    const p = shorePoint(b, a, s);
    const pale = random() < 0.46;
    fill(...(pale ? b.light : b.edge), random(9, 42));
    const d = random(0.6, 2.7);
    ellipse(p.x, p.y, d, d * random(0.6, 1.8));
  }

  // 边缘不是一道封死的轮廓。
  noFill();
  for (let k = 0; k < 12; k++) {
    const a0 = random(TWO_PI);
    stroke(...b.light, random(20, 60));
    strokeWeight(random(0.5, 1.1));
    beginShape();
    for (let a = a0; a < a0 + random(0.15, 0.45); a += 0.016) {
      const p = shorePoint(b, a, random(0.991, 1.002));
      vertex(p.x, p.y);
    }
    endShape();
  }
}

function surroundingCurrent(front) {
  noFill();
  const count = front ? 14 : 39;

  for (let k = 0; k < count; k++) {
    const rx = front ? random(540, 650) : random(555, 690);
    const ry = rx * random(1.19, 1.29);
    const a0 = random(-2.9, -1.9);
    const span = random(3.7, 5.4);
    stroke(...GOLD, front ? random(12, 34) : random(7, 23));
    strokeWeight(random(0.5, 1.4));

    beginShape();
    for (let a = a0; a < a0 + span; a += 0.014) {
      const wave = 5 * sin(a * 3 + k * 0.12)
        + 3 * sin(a * 7 + k);
      const x = (rx + wave) * cos(a);
      const y = (ry + wave) * sin(a);
      const tilt = -0.09;
      vertex(
        800 + x * cos(tilt) - y * sin(tilt),
        1025 + x * sin(tilt) + y * cos(tilt)
      );
    }
    endShape();
  }
}

function silk(upper, count, faint) {
  noFill();

  for (let i = 0; i < count; i++) {
    const t = i / (count - 1);
    const spread = (t - 0.5) * 110;
    const x1 = 575 + random(-35, 45) + t * 48;
    const y1 = 1125 + spread + random(-12, 12);
    const x2 = 1055 + random(-40, 35) - t * 42;
    const y2 = 925 + spread * 0.7 + random(-12, 12);

    const c = blend([226, 149, 101], [185, 224, 198], t);
    stroke(...c, faint ? random(5, 13) : random(22, 64));
    strokeWeight(faint ? random(2, 5) : random(0.45, 1.2));

    const lift = upper ? -1 : 1;
    const depth = upper ? 310 : 345;
    bezier(
      x1, y1,
      680 + spread * 0.2,
      1050 + lift * depth + spread * 0.8,
      925 + spread * 0.22,
      980 + lift * depth + spread * 0.75,
      x2, y2
    );
  }
}

function grain() {
  loadPixels();
  let state = 1;
  for (let i = 0; i < pixels.length; i += 4) {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    const n = ((state >>> 24) / 255 - 0.5) * 7;
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

function draw() {
  background(...INK);

  glow(750, 1000, 980, 1200, [70, 87, 86], 0.48);
  glow(480, 1140, 640, 810, [126, 68, 48], 0.15);
  glow(1110, 850, 610, 790, [36, 112, 112], 0.15);
  glow(805, 1020, 280, 450, [218, 190, 127], 0.065);

  // 底材上近乎隐去的纤维。
  strokeWeight(0.6);
  for (let i = 0; i < 9500; i++) {
    const x = random(width);
    const y = random(height);
    stroke(155, 168, 159, random(2, 10));
    line(x, y, x + random(-3, 3), y + random(2, 13));
  }

  surroundingCurrent(false);

  // 光先落在底材上，再成为可辨认的丝线。
  silk(true, 34, true);
  silk(false, 34, true);

  const left = {
    x: 481, y: 1095,
    rx: 292, ry: 485,
    shiftX: 50, shiftY: 23,
    phase: 0.5, seed: 2,
    edge: [91, 47, 44],
    middle: [191, 99, 66],
    light: [237, 180, 125]
  };

  const right = {
    x: 1116, y: 944,
    rx: 290, ry: 511,
    shiftX: -50, shiftY: -10,
    phase: 2.4, seed: 8,
    edge: [28, 75, 79],
    middle: [65, 134, 126],
    light: [180, 207, 168]
  };

  shore(left);
  shore(right);

  silk(true, 79, false);
  silk(false, 89, false);

  // 少数较亮的线并不把中央填满。
  noFill();
  stroke(242, 211, 157, 112);
  strokeWeight(1.25);
  bezier(601, 1100, 677, 711, 932, 668, 1031, 900);
  stroke(226, 218, 175, 91);
  strokeWeight(0.9);
  bezier(617, 1159, 746, 1442, 1005, 1250, 1046, 953);

  surroundingCurrent(true);

  // 零星的金色沉积，密度随画面边缘自然消退。
  noStroke();
  for (let i = 0; i < 900; i++) {
    const a = random(TWO_PI);
    const r = random(0.83, 1.12);
    const x = 800 + 621 * r * cos(a);
    const y = 1025 + 790 * r * sin(a);
    if (random() < 0.63) continue;
    fill(...GOLD, random(12, 56));
    const d = random(0.6, 2.1);
    ellipse(x, y, d, d);
  }

  // 极轻的暗角，让边缘沉入纸面。
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(800, 1000);
  ctx.scale(800, 1000);
  const vignette = ctx.createRadialGradient(0, 0, 0.55, 0, 0, 1.4);
  vignette.addColorStop(0, "rgba(5,12,20,0)");
  vignette.addColorStop(1, "rgba(5,12,20,0.46)");
  ctx.fillStyle = vignette;
  ctx.fillRect(-1, -1, 2, 2);
  ctx.restore();

  grain();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function paint() {
  const c = drawingContext;

  // 纸底
  const ground = c.createLinearGradient(0, 0, 300, height);
  ground.addColorStop(0, "#e8e5da");
  ground.addColorStop(0.48, "#eee8d9");
  ground.addColorStop(1, "#c2c6bc");
  c.fillStyle = ground;
  c.fillRect(0, 0, width, height);

  glow(805, 880, 850, [
    [0, "rgba(255,251,227,0.95)"],
    [0.44, "rgba(255,246,218,0.50)"],
    [1, "rgba(255,246,218,0)"]
  ]);

  glow(190, 1390, 730, [
    [0, "rgba(49,83,96,0.15)"],
    [1, "rgba(49,83,96,0)"]
  ]);

  glow(1390, 1260, 670, [
    [0, "rgba(167,92,66,0.12)"],
    [1, "rgba(167,92,66,0)"]
  ]);

  // 纸纤维与颜料沉积
  for (let i = 0; i < 54000; i++) {
    const x = random(width);
    const y = random(height);
    const a = random(0.015, 0.055);
    c.fillStyle = `rgba(73,65,48,${a})`;
    c.fillRect(x, y, random(0.5, 1.7), random(0.5, 2.2));
  }

  const left = {
    outer: [
      [375, 290], [-100, 900], [140, 1770], [1035, 1690]
    ],
    inner: [
      [375, 290], [170, 850], [530, 1520], [1035, 1690]
    ],
    colors: ["#416d78", "#133b4c", "#527e82", "#a5b2a0"],
    fibers: [
      [193, 211, 189], [95, 149, 151],
      [17, 48, 65], [213, 199, 145]
    ]
  };

  const right = {
    outer: [
      [1365, 435], [1710, 1080], [1380, 1870], [595, 1640]
    ],
    inner: [
      [1365, 435], [1160, 930], [1220, 1450], [595, 1640]
    ],
    colors: ["#ce9c73", "#a95642", "#bf7654", "#e1c297"],
    fibers: [
      [246, 211, 157], [159, 66, 48],
      [207, 138, 94], [108, 75, 64]
    ]
  };

  // 轻薄的底层，不构成封闭轮廓
  c.save();
  c.lineWidth = 1.1;
  for (let i = 0; i < 24; i++) {
    const k = i / 23;
    c.strokeStyle = `rgba(122,132,119,${0.035 + k * 0.025})`;
    c.beginPath();
    c.moveTo(348 - 25 * k, 332 + 80 * k);
    c.bezierCurveTo(
      55 - 35 * k, 1100,
      430, 1870 + 35 * k,
      1120 + 70 * k, 1740
    );
    c.stroke();
  }
  c.restore();

  ribbon(left);
  ribbon(right);

  // 两种颜色之间的承托：细线仍然各自可辨
  c.save();
  c.lineCap = "round";
  for (let i = 0; i < 86; i++) {
    const u = i / 85;
    const a = ribbonPoint(left, 0.55 + 0.255 * u, 0.91);
    const b = ribbonPoint(right, 0.52 + 0.26 * u, 0.92);
    const sag = 125 + 55 * sin(PI * u);
    const warm = i % 4 !== 0;

    c.strokeStyle = warm
      ? `rgba(188,143,72,${random(0.13, 0.38)})`
      : `rgba(72,113,120,${random(0.13, 0.27)})`;
    c.lineWidth = random(0.65, 1.65);
    c.beginPath();
    c.moveTo(a.x, a.y);
    c.bezierCurveTo(
      a.x + (b.x - a.x) * 0.29, a.y + sag,
      b.x - (b.x - a.x) * 0.29, b.y + sag,
      b.x, b.y
    );
    c.stroke();
  }

  // 少量斜向纤维，让承托具有编织的密度
  for (let i = 0; i < 22; i++) {
    const u = i / 21;
    const a = ribbonPoint(left, 0.59 + 0.19 * u, 0.95);
    const b = ribbonPoint(right, 0.77 - 0.19 * u, 0.95);
    c.strokeStyle = "rgba(245,226,174,0.28)";
    c.lineWidth = random(0.6, 1.2);
    c.beginPath();
    c.moveTo(a.x, a.y);
    c.bezierCurveTo(
      a.x + 210, a.y + 115,
      b.x - 210, b.y + 110,
      b.x, b.y
    );
    c.stroke();
  }
  c.restore();

  // 边缘的光没有延伸成一道围墙
  edgeLight(left, 0.17, 0.88, "rgba(218,223,187,0.62)");
  edgeLight(right, 0.20, 0.87, "rgba(255,220,160,0.68)");

  glow(805, 1115, 270, [
    [0, "rgba(255,252,224,0.22)"],
    [1, "rgba(255,252,224,0)"]
  ]);

  // 悬浮的小片保留各自的颜色和方向
  const fragments = [
    [752, 1110, 11, -0.46, "#bb8b44"],
    [855, 1185, 8, 0.72, "#517b7d"],
    [935, 1083, 6, 0.28, "#b3664d"],
    [697, 1232, 7, -0.15, "#65868a"],
    [807, 1285, 5, 0.55, "#ca9e59"],
    [882, 989, 4, -0.70, "#d2b373"]
  ];

  for (const f of fragments) {
    fragment(...f);
  }

  // 零散微光，而非一个被占有的中心
  c.save();
  for (let i = 0; i < 160; i++) {
    const x = random(540, 1120);
    const y = random(770, 1390);
    const envelope = exp(
      -sq((x - 825) / 240) - sq((y - 1130) / 260)
    );
    if (random() > envelope * 0.58) continue;
    c.fillStyle = `rgba(180,142,71,${random(0.15, 0.5)})`;
    c.beginPath();
    c.arc(x, y, random(0.5, 1.6), 0, TWO_PI);
    c.fill();
  }
  c.restore();

  // 整张画统一的细颗粒
  for (let i = 0; i < 32000; i++) {
    const light = random() < 0.55;
    c.fillStyle = light
      ? "rgba(255,251,229,0.055)"
      : "rgba(30,40,42,0.035)";
    c.fillRect(random(width), random(height), 1, 1);
  }
}

function cubic(points, t) {
  const s = 1 - t;
  return {
    x: s * s * s * points[0][0]
      + 3 * s * s * t * points[1][0]
      + 3 * s * t * t * points[2][0]
      + t * t * t * points[3][0],
    y: s * s * s * points[0][1]
      + 3 * s * s * t * points[1][1]
      + 3 * s * t * t * points[2][1]
      + t * t * t * points[3][1]
  };
}

function ribbonPoint(r, t, s) {
  const a = cubic(r.outer, t);
  const b = cubic(r.inner, t);
  return {
    x: lerp(a.x, b.x, s),
    y: lerp(a.y, b.y, s)
  };
}

function ribbonPath(r) {
  const p = new Path2D();
  const a = r.outer;
  const b = r.inner;
  p.moveTo(a[0][0], a[0][1]);
  p.bezierCurveTo(
    a[1][0], a[1][1],
    a[2][0], a[2][1],
    a[3][0], a[3][1]
  );
  p.bezierCurveTo(
    b[2][0], b[2][1],
    b[1][0], b[1][1],
    b[0][0], b[0][1]
  );
  p.closePath();
  return p;
}

function ribbon(r) {
  const c = drawingContext;
  const path = ribbonPath(r);

  c.save();
  const g = c.createLinearGradient(200, 390, 1290, 1760);
  g.addColorStop(0, r.colors[0]);
  g.addColorStop(0.39, r.colors[1]);
  g.addColorStop(0.76, r.colors[2]);
  g.addColorStop(1, r.colors[3]);
  c.fillStyle = g;
  c.fill(path);
  c.clip(path);

  // 顺着形体生长的颜料丝
  for (let i = 0; i < 640; i++) {
    const s = (i + random(-0.5, 0.5)) / 640;
    const rgb = random(r.fibers);
    const alpha = random(0.12, 0.44);
    c.strokeStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`;
    c.lineWidth = random(0.45, 1.9);
    c.beginPath();

    for (let j = 0; j <= 170; j++) {
      const t = j / 170;
      const drift = (noise(s * 9, t * 5) - 0.5)
        * 0.025 * sin(PI * t);
      const p = ribbonPoint(r, t, s + drift);
      if (j === 0) c.moveTo(p.x, p.y);
      else c.lineTo(p.x, p.y);
    }
    c.stroke();
  }

  // 不连续的干笔，避免表面过分光滑
  for (let i = 0; i < 1450; i++) {
    const s = random();
    const t0 = random(0.04, 0.96);
    const t1 = min(0.985, t0 + random(0.003, 0.032));
    const rgb = random(r.fibers);
    c.strokeStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${random(0.08, 0.3)})`;
    c.lineWidth = random(0.4, 2.2);
    c.beginPath();
    for (let j = 0; j <= 8; j++) {
      const p = ribbonPoint(r, lerp(t0, t1, j / 8), s);
      if (j === 0) c.moveTo(p.x, p.y);
      else c.lineTo(p.x, p.y);
    }
    c.stroke();
  }

  for (let i = 0; i < 10000; i++) {
    const p = ribbonPoint(r, random(), random());
    c.fillStyle = random() < 0.5
      ? "rgba(255,240,204,0.10)"
      : "rgba(20,36,42,0.09)";
    c.fillRect(p.x, p.y, random(0.5, 1.8), random(0.5, 2));
  }

  c.restore();
}

function edgeLight(r, start, end, color) {
  const c = drawingContext;
  c.save();
  c.strokeStyle = color;
  c.lineWidth = 1.5;
  c.beginPath();
  for (let i = 0; i <= 150; i++) {
    const t = lerp(start, end, i / 150);
    const p = ribbonPoint(r, t, 0.992);
    if (i === 0) c.moveTo(p.x, p.y);
    else c.lineTo(p.x, p.y);
  }
  c.stroke();
  c.restore();
}

function glow(x, y, radius, stops) {
  const c = drawingContext;
  c.save();
  const g = c.createRadialGradient(x, y, 0, x, y, radius);
  for (const stop of stops) g.addColorStop(stop[0], stop[1]);
  c.fillStyle = g;
  c.fillRect(x - radius, y - radius, radius * 2, radius * 2);
  c.restore();
}

function fragment(x, y, size, angle, color) {
  const c = drawingContext;
  c.save();
  c.translate(x, y);
  c.rotate(angle);
  c.fillStyle = color;
  c.beginPath();
  c.moveTo(-size * 0.38, -size);
  c.bezierCurveTo(
    size * 0.68, -size * 0.5,
    size * 0.57, size * 0.52,
    size * 0.13, size
  );
  c.bezierCurveTo(
    -size * 0.6, size * 0.45,
    -size * 0.68, -size * 0.2,
    -size * 0.38, -size
  );
  c.fill();
