function halo(x, y, r, rgb, alpha) {
  const ctx = drawingContext;
  ctx.save();
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, `rgba(${rgb.join(",")},${alpha})`);
  g.addColorStop(0.42, `rgba(${rgb.join(",")},${alpha * 0.45})`);
  g.addColorStop(1, `rgba(${rgb.join(",")},0)`);
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
  ctx.restore();
}

function section(r, t, q) {
  const p = r.p;
  const x = bezierPoint(p[0], p[2], p[4], p[6], t);
  const y = bezierPoint(p[1], p[3], p[5], p[7], t);
  const dx = bezierTangent(p[0], p[2], p[4], p[6], t);
  const dy = bezierTangent(p[1], p[3], p[5], p[7], t);
  const len = sqrt(dx * dx + dy * dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;

  const taper = pow(max(0, sin(PI * t)), 0.64);
  const waviness = 0.86 + 0.23 * noise(r.id, t * 5);
  const w = (3 + r.w * taper) * waviness;
  const fray = (noise(r.id + 20, t * 31, q * 2 + 5) - 0.5)
             * 7 * abs(q);

  return {
    x: x + nx * (q * w + fray),
    y: y + ny * (q * w + fray),
    nx, ny, w
  };
}

function ribbon(r) {
  noStroke();
  fill(...r.base);
  beginShape();
  for (let i = 0; i <= 260; i++) {
    const a = section(r, i / 260, -1);
    vertex(a.x, a.y);
  }
  for (let i = 260; i >= 0; i--) {
    const a = section(r, i / 260, 1);
    vertex(a.x, a.y);
  }
  endShape(CLOSE);

  // 顺着流向排列的色丝。
  noFill();
  for (let j = 0; j < 510; j++) {
    const q = random(-1, 1);
    const inner = pow((q + 1) * 0.5, 1.6);
    let c = lerpColor(color(...r.dark), color(...r.light), inner);
    c = lerpColor(c, color(...r.base), random(0.08, 0.38));
    c.setAlpha(random(30, 135));
    stroke(c);
    strokeWeight(random(0.55, 2.9));

    const start = random(0, 0.075);
    const end = random(0.91, 1);
    beginShape();
    for (let i = 0; i <= 150; i++) {
