function halo(x, y, radius, stops) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
  for (const stop of stops) g.addColorStop(stop[0], stop[1]);
  ctx.save();
  ctx.fillStyle = g;
  ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
  ctx.restore();
}

function curvePoint(points, t) {
  let section = t < 0.5 ? 0 : 3;
  let u = t < 0.5 ? t * 2 : (t - 0.5) * 2;
  let a = points[section];
  let b = points[section + 1];
  let c = points[section + 2];
  let d = points[section + 3];
  return {
    x: bezierPoint(a[0], b[0], c[0], d[0], u),
    y: bezierPoint(a[1], b[1], c[1], d[1], u)
  };
}

function ribbon(outer, inner, stops, warm) {
  const ctx = drawingContext;
  const path = new Path2D();
  const steps = 240;

  for (let i = 0; i <= steps; i++) {
    let p = curvePoint(outer, i / steps);
    if (i === 0) path.moveTo(p.x, p.y);
    else path.lineTo(p.x, p.y);
  }
  for (let i = steps; i >= 0; i--) {
    let p = curvePoint(inner, i / steps);
    path.lineTo(p.x, p.y);
  }
  path.closePath();

  let g = warm
    ? ctx.createLinearGradient(1390, 1100, 1005, 1000)
    : ctx.createLinearGradient(245, 1000, 560, 1020);

  for (const stop of stops) g.addColorStop(stop[0], stop[1]);

  ctx.save();
  ctx.shadowColor = "rgba(8,27,30,0.24)";
  ctx.shadowBlur = 35;
  ctx.shadowOffsetY = 14;
  ctx.fillStyle = g;
  ctx.fill(path);
  ctx.restore();

  ctx.save();
  ctx.clip(path);

  // 顺着形体生长的干刷纹理。
  noFill();
  for (let j = 0; j < 210; j++) {
    let u = (j + random(-0.25, 0.25)) / 209;
    if (j % 4 === 0) {
      stroke(warm ? color(84, 40, 35, 31)
                  : color(18, 54, 65, 35));
    } else {
      stroke(warm ? color(255, 220, 164, random(15, 39))
                  : color(202, 220, 190, random(14, 37)));
    }
    strokeWeight(random(0.5, 1.65));
    beginShape();
    for (let i = 0; i <= 175; i++) {
      let t = i / 175;
      let a = curvePoint(outer, t);
      let b = curvePoint(inner, t);
      let drift = (noise(t * 11, j * 0.11) - 0.5) * 5;
      vertex(
        lerp(a.x, b.x, u) + drift,
        lerp(a.y, b.y, u) + drift * 0.4
      );
    }
    endShape();
  }

  noStroke();
  for (let i = 0; i < 11500; i++) {
    let t = random();
    let u = random();
    let a = curvePoint(outer, t);
    let b = curvePoint(inner, t);
    let x = lerp(a.x, b.x, u);
    let y = lerp(a.y, b.y, u);
    if (random() < 0.56) fill(255, 225, 173, random(8, 29));
    else fill(14, 36, 40, random(9, 27));
    ellipse(x, y, random(0.5, 2.7), random(1, 4.2));
  }

  ctx.restore();
}

