    const y = cy + sin(a) * ry * rr;
    fill(255, 210, 160, random(20, 90));
    circle(x, y, random(1, 3));
  }
  blendMode(BLEND);

  // ---- 颗粒质感 ----
  noStroke();
  for (let i = 0; i < 70000; i++) {
    fill(random() < 0.5 ? 0 : 255, random(4, 10));
    rect(random(width), random(height), 1.2, 1.2);
  }

  // 暗角
  noFill();
  for (let i = 0; i < 260; i++) {
    stroke(5, 4, 12, 3);
    strokeWeight(6);
    const m = i * 4;
    ellipse(width / 2, height / 2, width * 1.55 - m, height * 1.45 - m);
  }
}

const W = 1600, H = 2000;
const CX = 800, CY = 1100;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  // ---------- 背景 ----------
  let bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#0a0c1b');
  bg.addColorStop(0.55, '#15122b');
  bg.addColorStop(1, '#0c0a17');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // 远处的暖晕
  let halo = ctx.createRadialGradient(CX, CY, 0, CX, CY, 950);
  halo.addColorStop(0, 'rgba(255,170,110,0.32)');
  halo.addColorStop(0.25, 'rgba(200,90,115,0.17)');
  halo.addColorStop(0.6, 'rgba(80,60,125,0.07)');
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, W, H);

  // ---------- 涟漪：向外扩散的光 ----------
  noFill();
  let r = 110;
  let ri = 0;
  while (r < 1500) {
    let w = exp(-r / 430);
    let c = warmRGB(w);
    let a = 34 * exp(-r / 950);
    stroke(c[0], c[1], c[2], a);
    strokeWeight(1.4);
    beginShape();
    for (let i = 0; i <= 400; i++) {
      let th = (i / 400) * TAU;
      let rr = r + (noise(cos(th) * 1.2 + 5, sin(th) * 1.2 + 5, ri * 0.4) - 0.5) * r * 0.18;
      vertex(CX + cos(th) * rr, CY + sin(th) * rr);
    }
    endShape();
    r *= 1.16;
    ri++;
  }

  // ---------- 周围的场：被染暖的世界 ----------
  for (let i = 0; i < 7500; i++) {
    let x = random(W), y = random(H);
    let steps = floor(random(20, 75));
    strokeWeight(random(0.6, 1.9));
    for (let s = 0; s < steps; s++) {
      let a = noise(x * 0.0012, y * 0.0012) * TAU * 2;
      let dx = x - CX, dy = y - CY;
      let d = sqrt(dx * dx + dy * dy) + 0.001;
      let t = atan2(dy, dx) + HALF_PI;
      let inf = exp(-d / 520) * 0.85;
      let vx = cos(a) * (1 - inf) + cos(t) * inf - (dx / d) * inf * 0.15;
      let vy = sin(a) * (1 - inf) + sin(t) * inf - (dy / d) * inf * 0.15;
      let m = sqrt(vx * vx + vy * vy) + 0.0001;
      let nx = x + (vx / m) * 3;
      let ny = y + (vy / m) * 3;
      let w = warmth(x, y);
      let c = warmRGB(w);
      stroke(c[0], c[1], c[2], 16 + w * 70);
      line(x, y, nx, ny);
      x = nx; y = ny;
      if (x < -10 || x > W + 10 || y < -10 || y > H + 10) break;
    }
  }

  // ---------- 两股相互转向的流 ----------
  blendMode(ADD);
  stream(170, 250, [150, 185, 235], 160, 0);
  stream(1430, 1910, [225, 95, 125], 160, 1000);
  blendMode(BLEND);

  // ---------- 中心之光 ----------
  blendMode(ADD);
  let core = ctx.createRadialGradient(CX, CY, 0, CX, CY, 260);
  core.addColorStop(0, 'rgba(255,248,230,0.85)');
  core.addColorStop(0.18, 'rgba(255,215,160,0.45)');
  core.addColorStop(0.5, 'rgba(255,150,110,0.14)');
  core.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = core;
  ctx.fillRect(CX - 300, CY - 300, 600, 600);

  // 微尘
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = random(W), y = random(H);
    let w = warmth(x, y);
    let c = warmRGB(w);
    fill(c[0], c[1], c[2], 10 + w * 90);
    let s = random(0.8, 2.4) * (0.6 + w);
    circle(x, y, s);
  }

  // 最远处的火星：光抵达了不在其中的地方
  for (let i = 0; i < 46; i++) {
    let x, y, d;
    do {
      x = random(60, W - 60);
      y = random(60, H - 60);
      d = dist(x, y, CX, CY);
    } while (d < 650);
    let sz = random(3, 7);
    for (let k = 6; k >= 1; k--) {
      fill(255, 190, 130, 7 * (7 - k));
      circle(x, y, sz * k * 1.6);
    }
    fill(255, 240, 210, 200);
    circle(x, y, sz * 0.7);
  }
  blendMode(BLEND);

  // ---------- 暗角 ----------
  let vig = ctx.createRadialGradient(CX, CY - 100, 500, CX, CY - 100, 1400);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(1, 'rgba(4,3,10,0.6)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, W, H);

  // ---------- 颗粒 ----------
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = (random() - 0.5) * 14;
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g, 0, 255);
  }
  updatePixels();
}

// 一股流：从远处出发，向中心旋近，却在触碰前停下
function stream(sx, sy, col, n, seedOff) {
  const gold = [255, 195, 115];
  const cream = [255, 240, 215];
  for (let k = 0; k < n; k++) {
    let x = sx + randomGaussian() * 75;
    let y = sy + randomGaussian() * 75;
    let d0 = dist(x, y, CX, CY);
    let rStop = random(18, 75);
    let swirl = 0.9 + random(-0.12, 0.12);
    let inward = 0.55 + random(-0.08, 0.08);
    let step = 2.5;
    let wgt = random(0.7, 2.0);
    for (let s = 0; s < 3500; s++) {
      let dx = CX - x, dy = CY - y;
      let d = sqrt(dx * dx + dy * dy);
      if (d < rStop) break;
      let ux = dx / d, uy = dy / d;
      let px = -uy, py = ux;
      let vx = ux * inward + px * swirl;
      let vy = uy * inward + py * swirl;
      let na = (noise(x * 0.004, y * 0.004, (k + seedOff) * 0.012) - 0.5) * 1.1;
      let ca = cos(na), sa = sin(na);
      let rx = vx * ca - vy * sa;
      let ry = vx * sa + vy * ca;
      let m = sqrt(rx * rx + ry * ry);
      let nx = x + (rx / m) * step;
      let ny = y + (ry / m) * step;

      let t = constrain(1 - d / d0, 0, 1);
      let c;
      if (t < 0.7) c = mix(col, gold, pow(t / 0.7, 1.6));
      else c = mix(gold, cream, (t - 0.7) / 0.3);
      let a = 10 + pow(t, 1.5) * 26;
      stroke(c[0], c[1], c[2], a);
      strokeWeight(wgt * (1 - t * 0.4));
      line(x, y, nx, ny);
      x = nx; y = ny;
    }
  }
}

function warmth(x, y) {
  let d = dist(x, y, CX, CY);
  let w = exp(-d / 430);
  w += (noise(x * 0.003 + 50, y * 0.003 + 50) - 0.5) * 0.18;
  return constrain(w, 0, 1);
}

function warmRGB(w) {
  const cool = [70, 95, 150];
  const mid = [215, 105, 128];
  const warm = [255, 208, 145];
  if (w < 0.5) return mix(cool, mid, w * 2);
  return mix(mid, warm, (w - 0.5) * 2);
}

function mix(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const W = width, H = height;
  const cx = W / 2, cy = H / 2;

  // 背景：上方深靛，下方深暖，中间相接
  const topC = [8, 13, 34], midC = [16, 12, 22], botC = [32, 11, 10];
  for (let y = 0; y < H; y++) {
    let t = y / H, c;
    if (t < 0.5) c = mixArr(topC, midC, t / 0.5);
    else c = mixArr(midC, botC, (t - 0.5) / 0.5);
    stroke(c[0], c[1], c[2]);
    line(0, y, W, y);
  }

  // 交汇处的柔光
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(cx, cy, 0, cx, cy, 700);
  g.addColorStop(0, 'rgba(255,205,160,0.22)');
  g.addColorStop(0.4, 'rgba(200,120,140,0.08)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  const cool = [50, 110, 230];
  const warm = [235, 80, 45];
  const third = [255, 222, 170];

  blendMode(ADD);
  noFill();

  const N = 230;
  for (let kind = 0; kind < 2; kind++) {
    for (let i = 0; i < N; i++) {
      let x0 = random(-250, W + 250);
      let x1 = random(-250, W + 250);
      let off = randomGaussian(0, 35);
      let ph = kind * PI + random(-0.35, 0.35);
      let amp = random(30, 120);
      let sw = random(0.6, 2.2);
      let nOff = random(1000);
      let own = kind === 0 ? cool : warm;
      let other = kind === 0 ? warm : cool;

      strokeWeight(sw);
      let px = null, py = null;
      for (let y = -20; y <= H + 20; y += 5) {
        let t = y / H;
        let base = lerp(x0, x1, t) + (noise(nOff, y * 0.0016) - 0.5) * 360;
        let p = exp(-sq((y - cy) / 270));
        let braid = amp * sin(y * 0.02 + ph);
        let x = cx + off + (base - cx - off) * (1 - p * 0.94) + braid * p;

        // 颜色：在自己的一侧是本色；穿过交汇处后，带上对方的颜色
        let past = kind === 0 ? (y - cy) / (H / 2) : (cy - y) / (H / 2);
        let tint = constrain(past, 0, 1);
        tint = 0.38 * (1 - pow(1 - tint, 3));
        let c = mixArr(own, other, tint);
        c = mixArr(c, third, p * 0.85);
        let a = 30 + 70 * p;

        if (px !== null) {
          stroke(c[0], c[1], c[2], a);
          line(px, py, x, y);
        }
        px = x; py = y;
      }
    }
  }

  // 交汇处溢出的微光
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = cx + randomGaussian(0, 150);
    let y = cy + randomGaussian(0, 230);
    let d = dist(x, y, cx, cy);
    let s = random(1, 3.5);
    fill(255, 215, 165, map(d, 0, 500, 120, 10, true));
    circle(x, y, s);
  }

  blendMode(BLEND);

  // 暗角
  let v = ctx.createRadialGradient(cx, cy, 500, cx, cy, 1400);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, W, H);

  // 颗粒质感
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-9, 9);
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

function mixArr(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // ---- 背景：深夜般的渐变 ----
  const top = color(9, 11, 28);
  const bot = color(30, 16, 42);
  for (let y = 0; y < height; y++) {
    stroke(lerpColor(top, bot, y / height));
    line(0, y, width, y);
  }

  // 朦胧的云雾
  noStroke();
  for (let i = 0; i < 450; i++) {
    const x = random(width), y = random(height);
    const r = random(120, 450);
    const n = noise(x * 0.002, y * 0.002);
    fill(60 + n * 40, 50, 110 + n * 30, 3);
    ellipse(x, y, r, r * random(0.6, 1.2));
  }

  // ---- 生成那条线：从下方进入，向上方离开，盘绕但不闭合 ----
  const pts = [];
  let pos = createVector(width * 0.5 + random(-80, 80), height + 40);
  let dir = createVector(0, -1);
  const step = 4;
  for (let i = 0; i < 4000; i++) {
    pts.push(pos.copy());
    const a = (noise(i * 0.006) - 0.5) * 0.26;
    dir.rotate(a);
    dir.add(createVector((width * 0.5 - pos.x) * 0.00004, -0.011));
    dir.normalize();
    pos.add(p5.Vector.mult(dir, step));
    if (pos.y < -60) break;
  }

  // ---- 微小的存在 ----
  const motes = [];
  const R = 95;
  for (let i = 0; i < 2800; i++) {
    const x = random(width), y = random(height);
    const s = 1.2 + pow(random(), 2.2) * 4.5;
    let best = 1e12, bi = 0;
    for (let j = 0; j < pts.length; j += 2) {
      const dx = pts[j].x - x, dy = pts[j].y - y;
      const d2 = dx * dx + dy * dy;
      if (d2 < best) { best = d2; bi = j; }
    }
    motes.push({ x, y, s, d: sqrt(best), p: pts[bi] });
  }

  // 未被照见的：灰暗、冷
  noStroke();
  for (const m of motes) {
    if (m.d >= R) {
      fill(140, 150, 195, random(35, 100));
      circle(m.x, m.y, m.s);
    }
  }

  blendMode(ADD);

  // 线周围的温暖光晕
  noStroke();
  for (let i = 0; i < pts.length; i += 6) {
    const p = pts[i];
    fill(255, 120, 50, 2);
    circle(p.x, p.y, 220);
    fill(255, 150, 80, 3);
    circle(p.x, p.y, 110);
    fill(255, 180, 110, 4);
    circle(p.x, p.y, 50);
  }

  // 被照见者伸向那条线的细小光
  for (const m of motes) {
    if (m.d < R) {
      const t = 1 - m.d / R;
      stroke(255, 180, 120, 38 * t * t);
      strokeWeight(0.8);
      line(m.x, m.y, m.p.x, m.p.y);
    }
  }

  // 那条线本身：多层发光
  noFill();
  const layers = [
    [30, 255, 110, 50, 5],
    [16, 255, 140, 70, 10],
    [8, 255, 170, 100, 26],
    [3.5, 255, 205, 150, 80],
    [1.4, 255, 245, 225, 210]
  ];
  for (const L of layers) {
    strokeWeight(L[0]);
    stroke(L[1], L[2], L[3], L[4]);
    beginShape();
    for (const p of pts) vertex(p.x, p.y);
    endShape();
  }

  // 被照亮的存在
  noStroke();
  for (const m of motes) {
    if (m.d < R) {
      const t = pow(1 - m.d / R, 1.3);
      const k = noise(m.x * 0.004, m.y * 0.004);
      const r = 255;
      const g = lerp(110, 175, k);
      const b = lerp(125, 80, k);
      for (let j = 6; j >= 1; j--) {
        fill(r, g, b, 7 * t);
        circle(m.x, m.y, m.s * (1.5 + j * 3.2) * (0.5 + t));
      }
      fill(255, 235, 205, 255 * t);
      circle(m.x, m.y, m.s * (0.9 + t * 0.8));
    }
  }

  blendMode(BLEND);

  // 颗粒质感
  strokeWeight(1);
  for (let i = 0; i < 90000; i++) {
    if (random() < 0.5) stroke(255, random(3, 10));
    else stroke(0, random(6, 16));
    point(random(width), random(height));
  }

  // 暗角
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(width / 2, height / 2, 450, width / 2, height / 2, 1400);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

const W = 1600, H = 2000;
const CX = 800, CY = 920, R = 270;

function rimAt(a) {
  return R * (0.82 + 0.38 * noise(1.3 * cos(a) + 10, 1.3 * sin(a) + 10));
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();

  // 背景：深夜般的暖紫到暗红
  const top = color(14, 11, 30), bot = color(28, 13, 24);
  for (let y = 0; y < H; y++) {
    stroke(lerpColor(top, bot, y / H));
    line(0, y, W, y);
  }

  // 被环绕的那个形状：从不被触碰
  noStroke();
  fill(6, 5, 12);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.01) {
    const r = rimAt(a);
    vertex(CX + cos(a) * r, CY + sin(a) * r);
  }
  endShape(CLOSE);

  // 它自身微弱的内光
  blendMode(ADD);
  for (let s = 1; s > 0.04; s -= 0.02) {
    fill(55, 30, 22, 5);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.02) {
      const r = rimAt(a) * s * 0.97;
      vertex(CX + cos(a) * r, CY + sin(a) * r);
    }
    endShape(CLOSE);
  }

  // 一根线，一再回来
  noFill();
  strokeWeight(1.1);
  let x = CX + R + 60, y = CY, h = HALF_PI;
  const N = 220000;
  for (let i = 0; i < N; i++) {
    const dx = x - CX, dy = y - CY;
    const d = max(1, sqrt(dx * dx + dy * dy));
    const a = atan2(dy, dx);
    const rim = rimAt(a);
    const gap = d - rim;

    const e = noise(i * 0.00004 + 3);
    const T = rim + 6 + pow(e, 3) * 2600;

    const tang = a + HALF_PI;
    const tx = cos(tang), ty = sin(tang);
    const corr = constrain((T - d) * 0.008, -1.4, 1.4);
    const rx = dx / d * corr, ry = dy / d * corr;
    const na = noise(x * 0.0025, y * 0.0025, i * 0.00001) * TWO_PI * 2;
    const nx = cos(na) * 0.55, ny = sin(na) * 0.55;

    const desired = atan2(ty + ry + ny, tx + rx + nx);
    const diff = atan2(sin(desired - h), cos(desired - h));
    h += diff * 0.12;

    let x2 = x + cos(h) * 2.2;
    let y2 = y + sin(h) * 2.2;

    // 靠近，但从不闯入
    const dx2 = x2 - CX, dy2 = y2 - CY;
    const d2 = sqrt(dx2 * dx2 + dy2 * dy2);
    const a2 = atan2(dy2, dx2);
    const rim2 = rimAt(a2);
    if (d2 < rim2 + 2) {
      x2 = CX + cos(a2) * (rim2 + 2);
      y2 = CY + sin(a2) * (rim2 + 2);
    }

    const f = constrain(gap / 520, 0, 1);
    let cr = lerp(255, 70, f), cg = lerp(165, 92, f), cb = lerp(115, 195, f);
    if (gap < 40) {
      const k = 1 - gap / 40;
      cr = lerp(cr, 255, k);
      cg = lerp(cg, 228, k);
      cb = lerp(cb, 195, k);
    }
    stroke(cr, cg, cb, lerp(13, 6, f));
    line(x, y, x2, y2);

    x = x2;
    y = y2;
  }

  blendMode(BLEND);

  // 暗角
  const g = drawingContext.createRadialGradient(CX, CY, 350, CX, CY, 1500);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.65)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);

  // 颗粒质感
  strokeWeight(1);
  for (let i = 0; i < 90000; i++) {
    if (random() < 0.5) stroke(255, 235, 215, random(3, 10));
    else stroke(0, random(6, 16));
    point(random(W), random(H));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(7, 8, 16);

  // 定义两个生命核心的位置（双星系统）
  let f1 = createVector(620, 1120);
  let f2 = createVector(980, 880);
  let center = p5.Vector.add(f1, f2).mult(0.5);

  // 1. 绘制深空背景尘埃与星辰
  drawCosmicDust(center);

  // 开启发光叠加模式
  blendMode(ADD);

  // 2. 绘制底层的引力光晕
  drawBaseGlows(f1, f2, center);

  // 3. 绘制交织的力场轨迹（爱之共鸣）
  drawFieldLines(f1, f2, center);

  // 4. 绘制从交汇处升腾的璀璨粒子
  drawResonanceParticles(f1, f2, center);

  // 5. 绘制两个独立而明亮的灵魂核心
  drawCores(f1, f2);

  // 恢复默认混合模式，绘制暗角以增强纵深感
  blendMode(BLEND);
  drawVignette();
}

function drawCosmicDust(center) {
  noStroke();
  for (let i = 0; i < 12000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let d = dist(x, y, center.x, center.y);

    if (random() < n * 1.2) {
      let alpha = map(d, 0, 1400, 35, 5);
      if (random() > 0.5) {
        fill(30, 50, 90, alpha);
      } else {
        fill(80, 30, 60, alpha);
      }
      let s = random(1, 3.5);
      circle(x, y, s);
    }
  }

  // 零星的亮星
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height);
    fill(255, 255, 255, random(20, 120));
    circle(x, y, random(0.5, 2));
  }
}

function drawBaseGlows(f1, f2, center) {
  noStroke();
  // 核心1光晕（暖色：珊瑚红与洋红）
  for (let r = 900; r > 0; r -= 8) {
    let alpha = map(r, 900, 0, 0, 3.5);
    fill(200, 40, 80, alpha * 0.35);
    circle(f1.x, f1.y, r * 1.4);
  }

  // 核心2光晕（冷色：青蓝与深海蓝）
  for (let r = 900; r > 0; r -= 8) {
    let alpha = map(r, 900, 0, 0, 3.5);
    fill(30, 130, 210, alpha * 0.35);
    circle(f2.x, f2.y, r * 1.4);
  }

  // 交汇处光晕（金色共鸣）
  for (let r = 700; r > 0; r -= 6) {
    let alpha = map(r, 700, 0, 0, 4.5);
    fill(255, 190, 90, alpha * 0.4);
    circle(center.x, center.y, r * 1.1);
  }
}

function drawFieldLines(f1, f2, center) {
  noFill();
  let numLines = 4200;
  let steps = 160;
  let stepLen = 7;

  // 定义色彩
  let c1_inner = color(255, 90, 60);
  let c1_outer = color(150, 20, 80);
  let c2_inner = color(60, 230, 255);
  let c2_outer = color(20, 60, 170);
  let c_bridge = color(255, 235, 160);

  for (let i = 0; i < numLines; i++) {
    let p;
    let type = random();

    // 决定粒子的起点分布
    if (type < 0.42) {
      let ang = random(TWO_PI);
      let rad = Math.pow(random(), 0.7) * 550;
      p = createVector(f1.x + cos(ang) * rad, f1.y + sin(ang) * rad);
    } else if (type < 0.84) {
      let ang = random(TWO_PI);
      let rad = Math.pow(random(), 0.7) * 550;
      p = createVector(f2.x + cos(ang) * rad, f2.y + sin(ang) * rad);
    } else {
      p = createVector(random(width), random(height));
    }

    let baseWeight = random(0.4, 2.0);

    for (let s = 0; s < steps; s++) {
      let v1 = p5.Vector.sub(p, f1);
      let v2 = p5.Vector.sub(p, f2);
      let d1 = v1.mag();
      let d2 = v2.mag();

      // 避免深入核心中心产生奇点
      if (d1 < 12 || d2 < 12) break;

      // 切线向量（代表各自独立的旋转生命周期）
      let t1 = createVector(-v1.y, v1.x).normalize();
      let t2 = createVector(v2.y, -v2.x).normalize(); 

      // 引力向量（代表彼此吸引）
      let a1 = v1.copy().normalize().mult(-1);
      let a2 = v2.copy().normalize().mult(-1);

      // 距离权重计算
      let w1 = 14000 / (d1 * d1 + 3500);
      let w2 = 14000 / (d2 * d2 + 3500);

      let dir = createVector(0, 0);

      // 组合切线与向心力
      dir.add(t1.mult(w1 * 2.2));
      dir.add(t2.mult(w2 * 2.2));
      dir.add(a1.mult(w1 * 0.85));
      dir.add(a2.mult(w2 * 0.85));

      // 引入柏林噪声，赋予生命轨迹有机的流动感
      let nScale = 0.0022;
      let nAngle = noise(p.x * nScale, p.y * nScale, i * 0.0005) * TWO_PI * 3;
      let nVec = p5.Vector.fromAngle(nAngle).mult(0.45);
      dir.add(nVec);

      // 全局柔和旋涡，将散逸的能量收回画面中心
      let vc = p5.Vector.sub(p, center);
      let dc = vc.mag();
      let tc = createVector(-vc.y, vc.x).normalize().mult(0.15);
      let ac = vc.copy().normalize().mult(-0.08 * (dc / 1000));
      dir.add(tc).add(ac);

      dir.normalize().mult(stepLen);
      let nextP = p5.Vector.add(p, dir);

      // 计算色彩：根据距离两个核心的远近进行混合
      let ratio = d1 / (d1 + d2); // 0代表靠近f1，1代表靠近f2
      let col1 = lerpColor(c1_inner, c1_outer, constrain(d1 / 700, 0, 1));
      let col2 = lerpColor(c2_inner, c2_outer, constrain(d2 / 700, 0, 1));
      let baseCol = lerpColor(col1, col2, ratio);

      // 共鸣度：当同时靠近两个核心，且距离差距不大时，激发出金色光芒
      let resonance = exp(-abs(d1 - d2) * 0.009) * exp(-(d1 + d2 - 440) * 0.003);
      resonance = constrain(resonance, 0, 1);

      let finalCol = lerpColor(baseCol, c_bridge, Math.pow(resonance, 0.75) * 0.95);

      // 线条两端的平滑淡入淡出
      let stepAlpha = sin(map(s, 0, steps, 0, PI));
      let distAlpha = map(dc, 0, 1100, 1, 0.05, true);
      let alpha = stepAlpha * distAlpha * (14 + resonance * 38);

      stroke(red(finalCol), green(finalCol), blue(finalCol), alpha);
      strokeWeight(baseWeight * (1 + resonance * 1.4));
      line(p.x, p.y, nextP.x, nextP.y);

      p = nextP;
    }
  }
}

function drawResonanceParticles(f1, f2, center) {
  noStroke();
  for (let i = 0; i < 4000; i++) {
    // 围绕中心正态分布
    let ang = random(TWO_PI);
    let rad = abs(randomGaussian(0, 280));
    let p = createVector(center.x + cos(ang) * rad, center.y + sin(ang) * rad * 1.3);

    let d1 = p.dist(f1);
    let d2 = p.dist(f2);

    // 在两个核心交界的中轴区域产生更多光尘
    let balance = exp(-abs(d1 - d2) * 0.006);
    if (random() < balance) {
      let s = random(0.8, 3.8);
      let a = random(30, 190) * balance;

      if (random() < 0.65) {
        fill(255, 235, 180, a); // 暖金
      } else if (d1 < d2) {
        fill(255, 130, 150, a); // 柔粉
      } else {
        fill(150, 230, 255, a); // 冰蓝
      }
      circle(p.x, p.y, s);

      // 极少数特别明亮的星芒
      if (s > 3.2 && random() < 0.25) {
        fill(255, 255, 255, a * 0.4);
        circle(p.x, p.y, s * 3.5);
      }
    }
  }
}

function drawCores(f1, f2) {
  noStroke();
  // 核心 1：温暖、热烈的灵魂
  for (let r = 180; r > 0; r -= 2) {
    let t = map(r, 180, 0, 0, 1);
    let c = lerpColor(color(220, 30, 70), color(255, 250, 240), Math.pow(t, 1.8));
    fill(red(c), green(c), blue(c), map(r, 180, 0, 0, 28));
    circle(f1.x, f1.y, r);
  }

  // 核心 2：深邃、宁静的灵魂
  for (let r = 180; r > 0; r -= 2) {
    let t = map(r, 180, 0, 0, 1);
    let c = lerpColor(color(20, 120, 220), color(240, 250, 255), Math.pow(t, 1.8));
    fill(red(c), green(c), blue(c), map(r, 180, 0, 0, 28));
    circle(f2.x, f2.y, r);
  }
}

function drawVignette() {
  noFill();
  let maxR = dist(0, 0, width / 2, height / 2);
  for (let r = 850; r < maxR + 200; r += 4) {
    let alpha = map(r, 850, maxR + 100, 0, 160, true);
    stroke(4, 5, 10, alpha * 0.15);
    strokeWeight(6);
    circle(width / 2, height / 2, r * 2);
  }
}

let cA, cB, cCenter, cGold;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 定义色彩：温暖的绯红、深邃的青蓝、交融的柔粉与圣洁的金色
  cA = color(255, 65, 50);     // 实体A：炽热之红
  cB = color(20, 140, 255);    // 实体B：深邃之蓝
  cCenter = color(255, 220, 240); // 共振核心
  cGold = color(255, 190, 80); // 灵魂的辉光

  // 1. 绘制深空背景
  background(6, 7, 15);

  // 使用叠加模式表现光的交融
  blendMode(ADD);

  // 2. 绘制环境背景的微弱星云
  drawNebula();

  // 定义两个灵魂的引力核心与相遇中心
  let coreA = createVector(450, 750);
  let coreB = createVector(1150, 1250);
  let center = createVector(800, 1000);

  // 3. 绘制连接彼此的引力弦（命运的羁绊）
  drawTethers(coreA, coreB, center);

  // 4. 绘制双生流体的轨迹（自我的延伸与交融）
  drawFlowLines(coreA, coreB, center);

  // 5. 绘制本源核心与共振光晕
  drawCoreGlow(coreA.x, coreA.y, cA, 900);
  drawCoreGlow(coreB.x, coreB.y, cB, 900);

  // 相遇处的爆发与升华
  drawCoreGlow(center.x, center.y, cGold, 1400);
  drawCoreGlow(center.x, center.y, cCenter, 800);
  drawCoreGlow(center.x, center.y, color(255, 255, 255), 350);

  // 6. 绘制爱的余晖与星尘
  drawStardust(coreA, coreB, center);
}

// 绘制背景星云
function drawNebula() {
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let r = random(100, 400) * n;

    let col = lerpColor(cA, cB, noise(x * 0.0005, y * 0.0005));
    col.setAlpha(2);
    fill(col);
    circle(x, y, r);
  }
}

// 绘制连接两个核心的曲线弦
function drawTethers(coreA, coreB, center) {
  noFill();
  for (let i = 0; i < 280; i++) {
    let t = i / 280;
    strokeWeight(random(0.5, 2.5));

    // 控制点向中心坍缩又向外扩散，形成呼吸感的纺锤形与心形隐喻
    let spread = 1600;
    let cp1x = center.x + (noise(i * 0.05, 1) - 0.5) * spread;
    let cp1y = center.y + (noise(i * 0.05, 2) - 0.5) * spread;
    let cp2x = center.x + (noise(i * 0.05, 3) - 0.5) * spread;
    let cp2y = center.y + (noise(i * 0.05, 4) - 0.5) * spread;

    // 细分贝塞尔曲线以实现渐变色彩
    let steps = 80;
    let prevX = coreA.x;
    let prevY = coreA.y;

    for (let s = 1; s <= steps; s++) {
      let st = s / steps;
      let x = bezierPoint(coreA.x, cp1x, cp2x, coreB.x, st);
      let y = bezierPoint(coreA.y, cp1y, cp2y, coreB.y, st);

      // 颜色从红渐变到金白，再渐变到蓝
      let col;
      if (st < 0.5) {
        col = lerpColor(cA, cGold, st * 2);
      } else {
        col = lerpColor(cGold, cB, (st - 0.5) * 2);
      }

      // 越靠近中心越明亮
      let alpha = sin(st * PI) * 25;
      col.setAlpha(alpha);
      stroke(col);
      line(prevX, prevY, x, y);

      prevX = x;
      prevY = y;
    }
  }
}

// 绘制受双星引力场影响的生命轨迹
function drawFlowLines(coreA, coreB, center) {
  noFill();
  let numLines = 3200;

  for (let i = 0; i < numLines; i++) {
    let isEntityA = i % 2 === 0;
    let startCore = isEntityA ? coreA : coreB;
    let baseCol = isEntityA ? cA : cB;
    let otherCol = isEntityA ? cB : cA;

    // 从核心周围诞生，少数从宇宙边缘诞生
    let x, y;
    if (random() < 0.85) {
      let angle = random(TWO_PI);
      let dist = abs(randomGaussian(0, 220));
      x = startCore.x + cos(angle) * dist;
      y = startCore.y + sin(angle) * dist;
    } else {
      x = random(width);
      y = random(height);
    }

    let steps = int(random(100, 280));
    strokeWeight(random(0.6, 2.2));

    for (let s = 0; s < steps; s++) {
      let px = x;
      let py = y;

      // 计算与各个核心的距离
      let dA = dist(x, y, coreA.x, coreA.y);
      let dB = dist(x, y, coreB.x, coreB.y);
      let dC = dist(x, y, center.x, center.y);

      // 计算引力与漩涡角度
      let angleA = atan2(coreA.y - y, coreA.x - x);
      let angleB = atan2(coreB.y - y, coreB.x - x);
      let angleC = atan2(center.y - y, center.x - x);

      // 柏林噪声提供自然的生命律动
      let n = noise(x * 0.002, y * 0.002, s * 0.005) * TWO_PI * 2;

      // 力的合成：向中心旋转靠拢，同时保持向外的舒展
      let swirlAngle = angleC + HALF_PI * (isEntityA ? 0.85 : -0.85); 
      let pullAngle = isEntityA ? angleB : angleA; // 被对方吸引

      let finalAngle = swirlAngle;
      // 距离中心越近，旋转与交融越剧烈
      let centerInfluence = map(constrain(dC, 0, 1000), 0, 1000, 1, 0.2);

      let vx = cos(swirlAngle) * 1.5 + cos(pullAngle) * 0.8 + cos(n) * 1.2;
      let vy = sin(swirlAngle) * 1.5 + sin(pullAngle) * 0.8 + sin(n) * 1.2;

      // 归一化并赋予速度
      let vMag = sqrt(vx * vx + vy * vy);
      let speed = 3.5;
      x += (vx / vMag) * speed;
      y += (vy / vMag) * speed;

      // 色彩计算：靠近对方或中心时，色彩发生共情与转化
      let mixRatio = constrain(map(dC, 600, 50, 0, 1), 0, 1);
      let c = lerpColor(baseCol, cGold, mixRatio * 0.7);
      if (dC < 250) {
        c = lerpColor(c, cCenter, map(dC, 250, 0, 0, 0.8));
      }

      // 线条两头淡出
      let lifeAlpha = sin((s / steps) * PI);
      let proximityAlpha = map(constrain(dC, 0, 800), 0, 800, 35, 10);
      c.setAlpha(lifeAlpha * proximityAlpha);

      stroke(c);
      line(px, py, x, y);
    }
  }
}

// 绘制柔和的发光体
function drawCoreGlow(x, y, col, maxRad) {
  noStroke();
  let steps = 120;
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    // 使用指数衰减使光晕更自然
    let r = maxRad * pow(1 - t, 1.8);
    let alpha = map(t, 0, 1, 1.5, 8) * sin(t * PI);

    let c = color(red(col), green(col), blue(col), alpha);
    fill(c);
    circle(x, y, r);
  }
}

// 绘制迸发的星尘（爱的结晶与回响）
function drawStardust(coreA, coreB, center) {
  noStroke();
  for (let i = 0; i < 1800; i++) {
    // 粒子主要分布在中心周围及连接轴上
    let t = random();
    let baseX, baseY, spread;

    if (t < 0.6) {
      // 围绕中心
      baseX = center.x;
      baseY = center.y;
      spread = random(50, 700);
    } else if (t < 0.8) {
      // 围绕A
      baseX = coreA.x;
      baseY = coreA.y;
      spread = random(20, 400);
    } else {
      // 围绕B
      baseX = coreB.x;
      baseY = coreB.y;
      spread = random(20, 400);
    }

    let angle = random(TWO_PI);
    let r = abs(randomGaussian(0, spread * 0.5));
    let x = baseX + cos(angle) * r;
    let y = baseY + sin(angle) * r;

    // 根据位置决定星尘颜色
    let dC = dist(x, y, center.x, center.y);
    let col;
    if (dC < 300) {
      col = lerpColor(cGold, color(255), random(0.2, 0.9));
    } else {
      col = random() < 0.5 ? cA : cB;
      col = lerpColor(col, cGold, 0.4);
    }

    let sz = random(1, 5);
    // 极少数明亮的大星尘
    if (random() < 0.03) {
      sz = random(6, 14);
      col.setAlpha(40);
      fill(col);
      circle(x, y, sz * 2.5);
    }

    col.setAlpha(random(50, 200));
    fill(col);
    circle(x, y, sz);

    // 星尘中心高光
    fill(255, 255, 255, random(100, 220));
    circle(x, y, sz * 0.4);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 背景：深邃的宇宙虚空
  background(6, 8, 18);

  // 定义两个核心的位置（双星系统）
  let coreA = createVector(620, 1120); // 冷色核心（深海/静谧）
  let coreB = createVector(980, 880);  // 暖色核心（火焰/炽热）
  let center = p5.Vector.lerp(coreA, coreB, 0.5);

  // 1. 绘制背景星尘与虚空纹理
  drawVoidTexture(center);

  // 开启发光混合模式
  blendMode(ADD);

  // 2. 绘制两个核心的底层光晕
  drawCoreGlow(coreA, color(0, 120, 255), 900);
  drawCoreGlow(coreB, color(255, 70, 30), 900);
  // 交汇处的金色共鸣底层光晕
  drawCoreGlow(center, color(255, 190, 80), 700);

  // 3. 绘制引力流线（爱之丝线）
  let numParticles = 3800;
  let steps = 220;

  for (let i = 0; i < numParticles; i++) {
    let p = spawnParticle(coreA, coreB);
    let type = p.type;
    let pos = p.pos;

    for (let s = 0; s < steps; s++) {
      let dA = p5.Vector.dist(pos, coreA);
      let dB = p5.Vector.dist(pos, coreB);

      // 计算来自两个核心的引力与旋转力
      let v = getFieldVector(pos, coreA, coreB, dA, dB);
      pos.add(v);

      // 计算色彩混合比例
      let ratio = dA / (dA + dB + 0.001); // 0 靠近 A, 1 靠近 B
      // 计算共鸣度：当距离两者相当且足够近时，产生强烈的金色共鸣
      let harmony = pow(1 - abs(dA - dB) / (dA + dB + 0.001), 4.0);
      let proximity = constrain(1 - (dA + dB) / 1500, 0, 1);
      let goldFactor = harmony * proximity * 1.4;

      // 生命周期透明度（两端淡出）
      let lifeAlpha = sin(map(s, 0, steps, 0, PI));

      // 确定画笔颜色
      let col = getStreamColor(type, ratio, goldFactor, lifeAlpha);
      stroke(col);

      // 越靠近中心共鸣区，线条越细腻明亮
      let sw = map(proximity, 0, 1, 0.8, 2.2) * (1 + goldFactor * 0.8);
      strokeWeight(sw);

      point(pos.x, pos.y);

      // 如果过于靠近核心内部，则停止以保留核心形态
      if (dA < 15 || dB < 15) break;
    }
  }

  // 4. 绘制共鸣区的爆发星火（爱意的结晶）
  drawResonanceSparks(coreA, coreB, center);

  // 5. 绘制两个高光实体核心（保持独立的自我）
  drawMainCores(coreA, coreB);

  // 恢复默认混合模式并添加画布暗角
  blendMode(BLEND);
  drawVignette();
}

// 绘制背景纹理与遥远的星辰
function drawVoidTexture(center) {
  noStroke();
  for (let i = 0; i < 6000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, center.x, center.y);
    let n = noise(x * 0.003, y * 0.003);

    if (random() < 0.8) {
      // 微弱的背景星尘
      fill(150, 180, 255, random(5, 25) * n);
      circle(x, y, random(1, 2.5));
    } else {
      // 稍亮的孤星
      fill(255, 230, 200, random(30, 100));
      circle(x, y, random(1.5, 3.5));
    }
  }
}

// 绘制柔和的大范围光晕
function drawCoreGlow(pos, col, maxRad) {
  noStroke();
  let steps = 80;
  for (let i = 0; i < steps; i++) {
    let r = map(i, 0, steps, maxRad, 10);
    let alpha = map(i, 0, steps, 0.2, 4.0);
    fill(red(col), green(col), blue(col), alpha);
    circle(pos.x, pos.y, r);
  }
}

// 生成粒子初始位置与属性
function spawnParticle(coreA, coreB) {
  let rand = random();
  let pos;
  let type;

  if (rand < 0.42) {
    // 源自核心 A 的粒子
    let angle = random(TWO_PI);
    let r = randomGaussian(80, 120);
    pos = createVector(coreA.x + cos(angle) * r, coreA.y + sin(angle) * r);
    type = 0;
  } else if (rand < 0.84) {
    // 源自核心 B 的粒子
    let angle = random(TWO_PI);
    let r = randomGaussian(80, 120);
    pos = createVector(coreB.x + cos(angle) * r, coreB.y + sin(angle) * r);
    type = 1;
  } else {
    // 弥漫在宇宙空间中、被这段关系吸引的粒子
    pos = createVector(random(-200, width + 200), random(-200, height + 200));
    type = 2;
  }
  return { pos, type };
}

// 计算双星引力与漩涡矢量场
function getFieldVector(pos, coreA, coreB, dA, dB) {
  let dirA = p5.Vector.sub(coreA, pos).normalize();
  let dirB = p5.Vector.sub(coreB, pos).normalize();

  // 切线方向（制造环绕感，两星同向旋转形成太极/双螺旋态势）
  let tanA = createVector(-dirA.y, dirA.x);
  let tanB = createVector(-dirB.y, dirB.x);

  // 引力权重：距离越近影响越大
  let wA = 1200 / (pow(dA, 1.15) + 80);
  let wB = 1200 / (pow(dB, 1.15) + 80);

  let v = createVector(0, 0);

  // 叠加旋转力与向心力
  v.add(p5.Vector.mult(tanA, wA * 1.6));
  v.add(p5.Vector.mult(dirA, wA * 0.42));

  v.add(p5.Vector.mult(tanB, wB * 1.6));
  v.add(p5.Vector.mult(dirB, wB * 0.42));

  // 加入柏林噪声，赋予生命体的呼吸感与不规则美
  let n = noise(pos.x * 0.0025, pos.y * 0.0025) * TWO_PI * 2;
  let noiseVec = p5.Vector.fromAngle(n).mult(0.45);
  v.add(noiseVec);

  // 设定步长
  v.normalize().mult(3.2);
  return v;
}

// 计算流线色彩
function getStreamColor(type, ratio, goldFactor, lifeAlpha) {
  let cA, cB;
  if (type === 0) {
    // 灵魂 A 的本色：深海蓝与青色
    cA = color(0, 210, 255);
    cB = color(160, 70, 255); // 被 B 吸引后染上的紫罗兰色
  } else if (type === 1) {
    // 灵魂 B 的本色：炽热红与珊瑚橘
    cA = color(255, 160, 40); // 被 A 吸引后染上的琥珀色
    cB = color(255, 45, 95);
  } else {
    // 环境共鸣色
    cA = color(40, 150, 255);
    cB = color(255, 90, 50);
  }

  let baseCol = lerpColor(cA, cB, ratio);
  let goldCol = color(255, 240, 170); // 爱意共鸣的高光金白

  let finalCol = lerpColor(baseCol, goldCol, constrain(goldFactor, 0, 1));

  // 基础透明度
  let baseAlpha = (type === 2) ? 6 : 11;
  let alpha = baseAlpha * lifeAlpha * (1 + goldFactor * 1.5);

  return color(red(finalCol), green(finalCol), blue(finalCol), alpha);
}

// 绘制交汇处的星火与光斑
function drawResonanceSparks(coreA, coreB, center) {
  noStroke();
  for (let i = 0; i < 900; i++) {
    // 集中在两个核心之间的区域
    let t = random(0.1, 0.9);
    let basePos = p5.Vector.lerp(coreA, coreB, t);
    let spread = map(abs(t - 0.5), 0, 0.4, 180, 400);

    let angle = random(TWO_PI);
    let r = abs(randomGaussian(0, spread));
    let p = createVector(basePos.x + cos(angle) * r, basePos.y + sin(angle) * r);

    // 顺着引力场稍微偏移，使其融入流线
    let dA = p5.Vector.dist(p, coreA);
    let dB = p5.Vector.dist(p, coreB);
    let harmony = pow(1 - abs(dA - dB) / (dA + dB + 0.001), 3);

    if (random() < harmony + 0.15) {
      let sz = random(1.5, 5.5) * (0.5 + harmony);
      fill(255, 235, 180, random(30, 150) * harmony);
      circle(p.x, p.y, sz);

      // 极亮的小核心
      if (random() < 0.3) {
        fill(255, 255, 255, 200 * harmony);
        circle(p.x, p.y, sz * 0.4);
      }
    }
  }
}

// 绘制两个耀眼的独立核心
function drawMainCores(coreA, coreB) {
  noStroke();
  // 核心 A（冷冽而深情）
  for (let r = 120; r > 0; r -= 2) {
    let t = map(r, 120, 0, 0, 1);
    let c = lerpColor(color(0, 180, 255, 0), color(220, 250, 255, 45), pow(t, 2));
    fill(c);
    circle(coreA.x, coreA.y, r);
  }
  fill(255, 255, 255, 230);
  circle(coreA.x, coreA.y, 18);

  // 核心 B（炽热而温柔）
  for (let r = 120; r > 0; r -= 2) {
    let t = map(r, 120, 0, 0, 1);
    let c = lerpColor(color(255, 60, 20, 0), color(255, 240, 200, 45), pow(t, 2));
    fill(c);
    circle(coreB.x, coreB.y, r);
  }
  fill(255, 255, 255, 230);
  circle(coreB.x, coreB.y, 18);
}

// 绘制边缘暗角，使视觉聚焦于中心
function drawVignette() {
  noFill();
  let maxDist = dist(0, 0, width / 2, height / 2);
  for (let r = 1300; r < maxDist * 2.2; r += 8) {
    let alpha = map(r, 1300, maxDist * 2.2, 0, 180);
    stroke(4, 5, 12, alpha);
    strokeWeight(12);
    circle(width / 2, height / 2, r);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 深邃的宇宙基底
  background(7, 9, 19);

  // 使用叠加模式绘制发光体
  blendMode(ADD);

  // 2. 氛围底层光晕（象征两个灵魂的场域与交汇）
  drawGlow(450, 1250, 1300, color(220, 40, 80), 0.14);   // 暖红场域
  drawGlow(1150, 750, 1300, color(20, 110, 220), 0.14);  // 冷青场域
  drawGlow(800, 1000, 1500, color(160, 70, 190), 0.12);  // 共振紫场域
  drawGlow(800, 960, 850, color(255, 190, 90), 0.22);    // 核心纯金光晕
  drawGlow(800, 960, 350, color(255, 240, 220), 0.35);   // 奇点白光

  // 3. 爱的轨迹：无数独立的丝线在引力中弯曲、交织
  let numStrands = 2200;
  for (let i = 0; i < numStrands; i++) {
    let isEntityA = i < numStrands / 2;
    drawStrand(isEntityA);
  }

  // 4. 共振之环：在靠近的张力中诞生的纯粹几何与秩序
  drawResonanceRings(800, 960);

  // 5. 灵魂的余温：飘散在空间中的微光粒子
  drawEmbers(800, 960);

  // 6. 恢复正常混合模式，绘制边缘暗角以聚焦视线
  blendMode(BLEND);
  drawVignette();
}

// 绘制柔和的径向发光
function drawGlow(x, y, maxRad, col, intensity) {
  noStroke();
  let steps = 90;
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let r = lerp(maxRad, 10, t);
    // 越靠近中心，透明度按照正弦曲线平滑过渡
    let a = sin(t * PI) * 255 * intensity * (1 - t * 0.4);
    fill(red(col), green(col), blue(col), a / (steps * 0.18));
    circle(x, y, r);
  }
}

// 绘制单根能量丝线
function drawStrand(isA) {
  // 各自的核心起点
  let originX = isA ? 380 : 1220;
  let originY = isA ? 1320 : 680;
  // 爱的交汇中心
  let nexusX = 800;
  let nexusY = 960;

  // 在核心周围呈高斯分布生成起点
  let angle = random(TWO_PI);
  let radius = abs(randomGaussian()) * 220;
  let x = originX + cos(angle) * radius;
  let y = originY + sin(angle) * radius;

  // 基础色彩：A为暖色系（红/金），B为冷色系（青/蓝）
  let baseCol = isA ?
    lerpColor(color(255, 45, 95), color(255, 165, 40), random()) :
    lerpColor(color(0, 215, 255), color(50, 90, 255), random());

  // 交汇时的升华色彩（璀璨金白）
  let nexusCol = color(255, 235, 195);

  let steps = int(random(140, 280));
  let stepSize = 5.5;
  let swirlDir = isA ? 1 : -1;

  // 偶尔出现更为明亮的主干丝线
  let isHero = random() < 0.06;
  let weight = isHero ? random(1.8, 3.2) : random(0.5, 1.3);
  let baseAlpha = isHero ? random(35, 65) : random(10, 26);

  strokeWeight(weight);
  noFill();

  for (let s = 0; s < steps; s++) {
    let px = x;
    let py = y;

    // 柏林噪声带来的自然流动感
    let n = noise(x * 0.0022, y * 0.0022, s * 0.004);
    let noiseAngle = n * TWO_PI * 3.5;

    // 计算与交汇中心的关系
    let dx = nexusX - x;
    let dy = nexusY - y;
    let distToNexus = sqrt(dx * dx + dy * dy);
    let angleToNexus = atan2(dy, dx);

    // 环绕中心的切线角（形成拥抱般的旋涡）
    let swirlAngle = angleToNexus + (PI * 0.42 * swirlDir);

    // 距离中心越近，彼此的引力与环绕感越强；越远则越自由
    let pullStrength = constrain(map(distToNexus, 0, 1000, 0.85, 0.15), 0.15, 0.85);

    let vx = cos(noiseAngle) * (1 - pullStrength) + cos(swirlAngle) * pullStrength;
    let vy = sin(noiseAngle) * (1 - pullStrength) + sin(swirlAngle) * pullStrength;

    x += vx * stepSize;
    y += vy * stepSize;

    // 色彩随距离中心的远近而升华
    let colorMix = constrain(map(distToNexus, 550, 40, 0, 1), 0, 1);
    colorMix = pow(colorMix, 1.6);
    let currentCol = lerpColor(baseCol, nexusCol, colorMix);

    // 两端渐隐
    let lifeFade = sin(map(s, 0, steps, 0, PI));
    // 靠近中心时迸发更强的光芒
    let proximityBoost = map(colorMix, 0, 1, 1, 2.6);

    let finalAlpha = baseAlpha * lifeFade * proximityBoost;
    stroke(red(currentCol), green(currentCol), blue(currentCol), finalAlpha);

    line(px, py, x, y);
  }
}

// 绘制交汇处的神圣几何光环
function drawResonanceRings(cx, cy) {
  noFill();
  for (let i = 0; i < 45; i++) {
    let r = pow(random(), 1.4) * 680 + 25;
    let rot = random(TWO_PI);
    let arcLen = random(PI * 0.15, PI * 1.1);

    let col = lerpColor(color(255, 170, 90), color(190, 225, 255), random());
    let alpha = map(r, 25, 700, 45, 4) * random(0.5, 1.2);

    stroke(red(col), green(col), blue(col), alpha);
    strokeWeight(random(0.6, 2.2));

    push();
    translate(cx, cy);
    rotate(rot);
    // 略微压扁的椭圆，带来空间透视与环绕感
    let tilt = random(0.82, 1.0);
    arc(0, 0, r * 2, r * 2 * tilt, 0, arcLen);
    pop();
  }
}

// 绘制漫天星火般的微粒
function drawEmbers(cx, cy) {
  noStroke();
  for (let i = 0; i < 1600; i++) {
    // 粒子以交汇处为中心，向四周扩散
    let angle = random(TWO_PI);
    let dist = pow(random(), 1.7) * 1150;
    let x = cx + cos(angle) * dist + randomGaussian() * 40;
    let y = cy + sin(angle) * dist + randomGaussian() * 40;

    // 根据位置决定微粒的冷暖倾向
    let isWarmSide = (x * 0.8 - y * 0.6) < -100;
    let col;
    if (dist < 280) {
      col = color(255, 245, 220); // 核心金白
    } else if (isWarmSide) {
      col = lerpColor(color(255, 80, 110), color(255, 190, 90), random());
    } else {
      col = lerpColor(color(40, 190, 255), color(150, 120, 255), random());
    }

    let sz = pow(random(), 3) * 6.5 + 1;
    let a = map(dist, 0, 1150, 160, 15) * random(0.3, 1);

    // 微粒本体的柔和光晕
    fill(red(col), green(col), blue(col), a * 0.25);
    circle(x, y, sz * 3.2);

    // 微粒亮核
    fill(red(col), green(col), blue(col), a);
    circle(x, y, sz);
  }
}

// 绘制深邃的暗角，使光芒更内敛深沉
function drawVignette() {
  noFill();
  let cx = width / 2;
  let cy = height / 2;
  let maxR = dist(0, 0, cx, cy);

  for (let r = maxR * 0.65; r < maxR * 1.05; r += 3) {
    let a = map(r, maxR * 0.65, maxR, 0, 180);
    stroke(4, 6, 14, a * 0.08);
    strokeWeight(5);
    circle(cx, cy, r * 2);
  }
}

let c1, c2;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  c1 = createVector(600, 1180);
  c2 = createVector(1000, 820);

  drawBackground();
  drawAura();
  drawCosmicDust();
  drawFieldLines();
  drawCores();
  drawGoldenWeave();
  drawSparks();
}

function drawBackground() {
  noStroke();
  let maxDist = 2000;
  for (let r = maxDist; r > 0; r -= 8) {
    let inter = map(r, 0, maxDist, 0, 1);
    let col = lerpColor(color(24, 15, 38), color(4, 5, 12), pow(inter, 0.7));
    fill(col);
    circle(800, 1000, r * 2);
  }
}

function drawAura() {
  blendMode(ADD);
  noStroke();

  // Aura 1 (Cool Cyan/Blue)
  for (let r = 1000; r > 0; r -= 10) {
    let alpha = map(r, 0, 1000, 3, 0);
    fill(10, 120, 220, alpha);
    circle(c1.x, c1.y, r * 2);
  }

  // Aura 2 (Warm Magenta/Coral)
  for (let r = 1000; r > 0; r -= 10) {
    let alpha = map(r, 0, 1000, 3, 0);
    fill(240, 40, 100, alpha);
    circle(c2.x, c2.y, r * 2);
  }

  // Intersection Aura (Golden/Warm)
  for (let r = 800; r > 0; r -= 10) {
    let alpha = map(r, 0, 800, 2.5, 0);
    fill(255, 160, 60, alpha);
    circle(800, 1000, r * 2);
  }
}

function drawCosmicDust() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    if (random() < n) {
      let d = dist(x, y, 800, 1000);
      let alpha = map(d, 0, 1200, 120, 10) * random(0.2, 1);
      fill(200, 220, 255, alpha);
      circle(x, y, random(0.5, 2.5));
    }
  }
}

function getFlowVector(p, type) {
  let v1 = p5.Vector.sub(p, c1);
  let d1 = max(v1.mag(), 20);
  let v2 = p5.Vector.sub(p, c2);
  let d2 = max(v2.mag(), 20);

  let rot1 = createVector(-v1.y, v1.x).normalize();
  let rot2 = createVector(v2.y, -v2.x).normalize(); 

  let pull1 = v1.copy().normalize().mult(-1);
  let pull2 = v2.copy().normalize().mult(-1);

  let force = createVector(0, 0);

  let w1 = 1200 / pow(d1, 1.15);
  let w2 = 1200 / pow(d2, 1.15);

  if (type === 1) {
    force.add(rot1.mult(w1 * 1.4));
    force.add(pull2.mult(w2 * 2.0));
    force.add(rot2.mult(w2 * 0.8));
  } else {
    force.add(rot2.mult(w2 * 1.4));
    force.add(pull1.mult(w1 * 2.0));
    force.add(rot1.mult(w1 * 0.8));
  }

  let n = noise(p.x * 0.0018, p.y * 0.0018) * TWO_PI * 4;
  let noiseVec = p5.Vector.fromAngle(n).mult(0.7);
  force.add(noiseVec);

  let centerPull = p5.Vector.sub(createVector(800, 1000), p);
  let dc = centerPull.mag();
  if (dc > 500) {
    force.add(centerPull.normalize().mult(map(dc, 500, 1500, 0, 1.5)));
  }

  return force.normalize().mult(3);
}

function drawFieldLines() {
  blendMode(ADD);
  noFill();

  let numParticles = 3200;
  let steps = 260;

  for (let i = 0; i < numParticles; i++) {
    let type = (i % 2 === 0) ? 1 : 2;
    let origin = (type === 1) ? c1 : c2;

    let angle = random(TWO_PI);
    let r = sqrt(random()) * 550;
    if (random() < 0.35) r = random(10, 120);

    let p = createVector(origin.x + cos(angle) * r, origin.y + sin(angle) * r);

    let baseCol = (type === 1) ? color(0, 190, 255) : color(255, 45, 110);
    let altCol = (type === 1) ? color(60, 90, 255) : color(255, 130, 40);
    let myCol = lerpColor(baseCol, altCol, random());
    let goldCol = color(255, 225, 150);

    strokeWeight(random(0.4, 1.8));

    for (let s = 0; s < steps; s++) {
      let prev = p.copy();
      let vel = getFlowVector(p, type);
      p.add(vel);

      let d1 = p.dist(c1);
      let d2 = p.dist(c2);

      let proximity = map(d1 + d2, 480, 1300, 1, 0, true);
      proximity = pow(proximity, 1.8);

      let curCol = lerpColor(myCol, goldCol, proximity);

      let stepAlpha = sin(map(s, 0, steps, 0, PI));
      let a = stepAlpha * map(proximity, 0, 1, 14, 42);

      stroke(red(curCol), green(curCol), blue(curCol), a);
      line(prev.x, prev.y, p.x, p.y);

      if (d1 < 12 || d2 < 12) break;
    }
  }
}

function drawGoldenWeave() {
  blendMode(ADD);
  noFill();

  for (let i = 0; i < 650; i++) {
    let t = random();
    let base = p5.Vector.lerp(c1, c2, t);
    let spread = sin(t * PI) * 280 + 40;
    let p = p5.Vector.add(base, p5.Vector.random2D().mult(random(spread)));

    strokeWeight(random(0.6, 2.2));

    let steps = 140;
    for (let s = 0; s < steps; s++) {
      let prev = p.copy();

      let v1 = p5.Vector.sub(c1, p);
      let v2 = p5.Vector.sub(c2, p);
      let dir = p5.Vector.sub(v2.normalize(), v1.normalize()).normalize();

      if (i % 2 === 0) dir.mult(-1);

      let n = noise(p.x * 0.004, p.y * 0.004, i * 0.1) * TWO_PI * 2;
      dir.add(p5.Vector.fromAngle(n).mult(0.55));
      dir.normalize().mult(2.5);

      p.add(dir);

      let alpha = sin(map(s, 0, steps, 0, PI)) * 32;
      let col = lerpColor(color(255, 190, 90), color(255, 245, 210), sin(s / steps * PI));
      stroke(red(col), green(col), blue(col), alpha);
      line(prev.x, prev.y, p.x, p.y);

      if (p.dist(c1) < 15 || p.dist(c2) < 15) break;
    }
  }
}

function drawCores() {
  blendMode(ADD);
  noStroke();

  // Core 1
  for (let r = 250; r > 0; r -= 2) {
    let t = map(r, 0, 250, 1, 0);
    let col = lerpColor(color(0, 140, 255), color(220, 250, 255), pow(t, 2));
    fill(red(col), green(col), blue(col), pow(t, 1.8) * 18);
    circle(c1.x, c1.y, r * 2);
  }

  // Core 2
  for (let r = 250; r > 0; r -= 2) {
    let t = map(r, 0, 250, 1, 0);
    let col = lerpColor(color(255, 30, 100), color(255, 230, 240), pow(t, 2));
    fill(red(col), green(col), blue(col), pow(t, 1.8) * 18);
    circle(c2.x, c2.y, r * 2);
  }

  // Shared Heart Glow
  for (let r = 350; r > 0; r -= 4) {
    let t = map(r, 0, 350, 1, 0);
    fill(255, 210, 140, pow(t, 2) * 5);
    circle(800, 1000, r * 2);
  }
}

function drawSparks() {
  blendMode(ADD);
  noStroke();

  for (let i = 0; i < 1200; i++) {
    let t = random();
    let p = p5.Vector.lerp(c1, c2, t);
    let spread = (1 - abs(t - 0.5) * 1.6) * 450 + 80;
    p.add(p5.Vector.random2D().mult(pow(random(), 1.4) * spread));

    let d1 = p.dist(c1);
    let d2 = p.dist(c2);

    let col = color(255, 230, 180);
    if (d1 < d2 * 0.7) col = lerpColor(col, color(120, 220, 255), 0.6);
    if (d2 < d1 * 0.7) col = lerpColor(col, color(255, 140, 180), 0.6);

    let sz = random(1, 4.5);
    fill(red(col), green(col), blue(col), random(60, 220));
    circle(p.x, p.y, sz);

    if (random() < 0.12) {
      fill(red(col), green(col), blue(col), random(15, 45));
      circle(p.x, p.y, sz * random(3, 7));
    }

    if (random() < 0.015 && abs(t - 0.5) < 0.3) {
      stroke(255, 245, 220, random(80, 180));
      strokeWeight(0.8);
      let len = random(8, 22);
      line(p.x - len, p.y, p.x + len, p.y);
      line(p.x, p.y - len, p.x, p.y + len);
      noStroke();
    }
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  ellipseMode(CENTER);
  rectMode(CORNER);
  noLoop();
}

let Lx, Ly, Rx, Ry, Lix, Liy, Rix, Riy, Mx, My, tilt;

function draw() {
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255);

  Lx = 640;
  Ly = 880;
  Rx = 1040;
  Ry = 1160;
  Lix = 755;
  Liy = 955;
  Rix = 925;
  Riy = 1085;
  Mx = 840;
  My = 1020;
  tilt = Math.atan2(Ry - Ly, Rx - Lx);

  ground();
  nightPools();

  glow(Mx, My + 40, 820, 680, { r: 32, g: 12, b: 24 }, { r: 78, g: 34, b: 36 }, 30, tilt * 0.25, 1.45);
  glow(860, 1560, 500, 140, { r: 26, g: 10, b: 8 }, { r: 128, g: 58, b: 28 }, 24, 0, 2.2);

  glow(Lx, Ly, 400, 310, { r: 92, g: 20, b: 36 }, { r: 255, g: 148, b: 104 }, 74, tilt, 3.25);
  glow(Rx, Ry, 430, 330, { r: 40, g: 48, b: 104 }, { r: 255, g: 184, b: 118 }, 78, tilt, 3.15);

  dabs(Lx, Ly, 360, 36, 18, { r: 228, g: 86, b: 68 }, 240, 11);
  dabs(Rx, Ry, 380, -40, -12, { r: 236, g: 166, b: 96 }, 240, 10);
  dabs(Rx + 90, Ry + 24, 170, 0, 0, { r: 128, g: 146, b: 196 }, 36, 6);

  glow(Lix, Liy, 172, 132, { r: 255, g: 118, b: 88 }, { r: 255, g: 214, b: 176 }, 42, tilt, 4.1);
  glow(Rix, Riy, 180, 138, { r: 255, g: 158, b: 88 }, { r: 255, g: 222, b: 188 }, 42, tilt, 4.0);

  filaments(false);
  outerShade();
  bridge();

  glow(Mx, My, 108, 82, { r: 255, g: 188, b: 132 }, { r: 255, g: 252, b: 244 }, 34, tilt * 0.15, 5.2);

  filaments(true);
  impasto();
  sparks();
  motes();
  vignette();
  grain();
}

function ground() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.32) {
      let u = t / 0.32;
      r = lerp(9, 24, u);
      g = lerp(11, 13, u);
      b = lerp(24, 34, u);
    } else if (t < 0.52) {
      let u = (t - 0.32) / 0.2;
      r = lerp(24, 58, u);
      g = lerp(13, 22, u);
      b = lerp(34, 32, u);
    } else if (t < 0.76) {
      let u = (t - 0.52) / 0.24;
      r = lerp(58, 74, u);
      g = lerp(22, 30, u);
      b = lerp(32, 20, u);
    } else {
      let u = (t - 0.76) / 0.24;
      r = lerp(74, 20, u);
      g = lerp(30, 10, u);
      b = lerp(20, 9, u);
    }
    r += (noise(y * 0.012, 2) - 0.5) * 7;
    g += (noise(y * 0.012, 5) - 0.5) * 5;
    b += (noise(y * 0.012, 9) - 0.5) * 6;
    stroke(r, g, b);
    line(0, y, width, y);
  }
}

function nightPools() {
  noStroke();
  fill(5, 7, 16, 42);
  ellipse(280, 380, 980, 860);
  ellipse(1320, 340, 900, 800);
  ellipse(180, 1680, 1100, 860);
  ellipse(1420, 1760, 980, 820);
  fill(16, 7, 12, 28);
  ellipse(820, 1780, 1300, 520);
}

function glow(cx, cy, radx, rady, cOuter, cInner, layers, rot, layerAlpha) {
  push();
  translate(cx, cy);
  rotate(rot);
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let u = Math.pow(1 - t, 1.18);
    let wob = noise(i * 0.12, cx * 0.008, cy * 0.008);
    let jx = (wob - 0.5) * radx * 0.045;
    let jy = (noise(i * 0.12, 7) - 0.5) * rady * 0.045;
    fill(
      lerp(cOuter.r, cInner.r, u),
      lerp(cOuter.g, cInner.g, u),
      lerp(cOuter.b, cInner.b, u),
      layerAlpha
    );
    ellipse(jx, jy, radx * 2 * t, rady * 2 * t);
  }
  pop();
}

function dabs(cx, cy, rad, biasx, biasy, col, count, alphaMax) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let r = Math.pow(random(), 0.52) * rad;
    let x = cx + Math.cos(a) * r + biasx;
    let y = cy + Math.sin(a) * r * 0.9 + biasy;
    let n = noise(x * 0.007, y * 0.007, i * 0.02);
    let w = rad * (0.07 + 0.2 * n) * random(0.55, 1.15);
    let al = alphaMax * (1 - r / rad) * (0.35 + 0.65 * n);
    fill(
      constrain(col.r + random(-12, 12), 0, 255),
      constrain(col.g + random(-12, 12), 0, 255),
      constrain(col.b + random(-10, 10), 0, 255),
      al
    );
    ellipse(x, y, w, w * random(0.68, 1.12));
  }
}

function field(x, y) {
  let vx = 0.18;
  let vy = -0.32;
  let cs = [
    [Lx, Ly, 1.0, 250],
    [Rx, Ry, -1.0, 270],
    [Mx, My, 0.55, 130]
  ];
  for (let i = 0; i < cs.length; i++) {
    let dx = x - cs[i][0];
    let dy = y - cs[i][1];
    let d = Math.sqrt(dx * dx + dy * dy) + 0.001;
    let fall = Math.exp(-(d * d) / (2 * cs[i][3] * cs[i][3]));
    vx += cs[i][2] * (-dy / d) * fall * 7.6;
    vy += cs[i][2] * (dx / d) * fall * 7.6;
  }
  vx += (noise(x * 0.0021, y * 0.0021) - 0.5) * 1.35;
  vy += (noise(x * 0.0021, y * 0.0021, 3.7) - 0.5) * 1.35;
  return { x: vx, y: vy };
}

function influence(x, y) {
  let d1 = dist(x, y, Lx, Ly);
  let d2 = dist(x, y, Rx, Ry);
  return Math.exp(-(d1 * d1) / (2 * 310 * 310)) + Math.exp(-(d2 * d2) / (2 * 330 * 330));
}

function filaments(bright) {
  let n = bright ? 46 : 120;
  for (let i = 0; i < n; i++) {
    let x, y;
    let kind = i % 3;
    if (kind === 0) {
      let t = random();
      x = lerp(Lix, Rix, t) + random(-28, 28);
      y = lerp(Liy, Riy, t) + random(-26, 26);
    } else if (kind === 1) {
      let a = random(TWO_PI);
      let r = random(36, 270);
      x = Lx + Math.cos(a) * r;
      y = Ly + Math.sin(a) * r;
    } else {
      let a = random(TWO_PI);
      let r = random(36, 290);
      x = Rx + Math.cos(a) * r;
      y = Ry + Math.sin(a) * r;
    }
    let steps = bright ? 34 : 72;
    for (let s = 0; s < steps; s++) {
      let v = field(x, y);
      let sp = Math.sqrt(v.x * v.x + v.y * v.y) + 0.001;
      let step = bright ? 6 : 8;
      let nx = x + (v.x / sp) * step;
      let ny = y + (v.y / sp) * step;
      let inf = influence(x, y);
      if (inf < 0.045) break;
      let d1 = dist(x, y, Lx, Ly);
      let d2 = dist(x, y, Rx, Ry);
      let m = d1 / (d1 + d2);
      let cr = lerp(244, 198, m);
      let cg = lerp(126, 172, m);
      let cb = lerp(98, 214, m);
      if (bright) {
        cr = lerp(cr, 255, 0.42);
        cg = lerp(cg, 238, 0.4);
        cb = lerp(cb, 216, 0.28);
      }
      let edge = Math.sin((s / steps) * Math.PI);
      stroke(cr, cg, cb, (bright ? 20 : 11) * inf * edge);
      strokeWeight((bright ? 1.25 : 1.7) * (0.45 + noise(x * 0.012, y * 0.012)) * edge);
      line(x, y, nx, ny);
      x = nx;
      y = ny;
    }
  }
}

function outerShade() {
  noStroke();
  for (let i = 0; i < 16; i++) {
    fill(6, 4, 12, 8);
    ellipse(400 - i * 9, Ly - 10, 360, 540);
    ellipse(1310 + i * 9, Ry + 16, 380, 560);
  }
}

function bridge() {
  noStroke();
  for (let i = 0; i < 90; i++) {
    let t = random();
    let x = lerp(Lix, Rix, t) + random(-20, 20);
    let y = lerp(Liy, Riy, t) + random(-18, 18);
    let w = Math.sin(t * Math.PI);
    let cr = lerp(lerp(255, 255, t), 255, w * 0.86);
    let cg = lerp(lerp(150, 196, t), 246, w * 0.86);
    let cb = lerp(lerp(112, 146, t), 232, w * 0.82);
    fill(cr, cg, cb, 6 + 20 * w);
    ellipse(x, y, random(12, 40) * (0.7 + 0.5 * w), random(8, 30));
  }
}

function impasto() {
  noStroke();
  for (let i = 0; i < 36; i++) {
    let t = random(0.2, 0.8);
    let x = lerp(Lix, Rix, t) + random(-34, 34);
    let y = lerp(Liy, Riy, t) + random(-30, 30);
    push();
    translate(x, y);
    rotate(tilt + random(-0.5, 0.5));
    fill(255, random(196, 236), random(160, 200), random(6, 14));
    ellipse(0, 0, random(36, 120), random(5, 14));
    pop();
  }
}

function sparks() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 14; i++) {
    fill(255, 228, 198, 16);
    ellipse(Mx + randomGaussian() * 16, My + randomGaussian() * 11, random(6, 20), random(5, 16));
  }
  blendMode(BLEND);
}

function motes() {
  noStroke();
  for (let i = 0; i < 520; i++) {
    let x = Mx + randomGaussian() * 150;
    let y = My - Math.abs(randomGaussian()) * 480;
    let al = constrain(map(y, 160, My, 0, 46), 0, 46) * 0.42;
    fill(255, 208, 176, al);
    ellipse(x, y, random(1.1, 3.1), random(1.1, 3.1));
  }
  for (let i = 0; i < 380; i++) {
    let x = Mx + randomGaussian() * 230;
    let y = My + 70 + Math.abs(randomGaussian()) * 400;
    fill(255, random(128, 176), random(68, 108), random(7, 30));
    ellipse(x, y, random(1, 2.5), random(1, 2.5));
  }
  for (let i = 0; i < 700; i++) {
    let x = random(width);
    let y = random(height);
    let inf = influence(x, y);
    if (inf < 0.09) continue;
    fill(255, 198, 158, 6 + inf * 24);
    ellipse(x, y, random(0.8, 2.1), random(0.8, 2.1));
  }
}

function vignette() {
  noFill();
  for (let i = 0; i < 220; i++) {
    let a = map(i, 0, 220, 16, 0);
    stroke(5, 4, 10, a * 0.34);
    line(0, i, width, i);
  }
  for (let i = 0; i < 160; i++) {
    let a = map(i, 0, 160, 14, 0);
    stroke(5, 4, 10, a * 0.28);
    line(0, height - 1 - i, width, height - 1 - i);
  }
  for (let i = 0; i < 130; i++) {
    let a = map(i, 0, 130, 15, 0);
    stroke(5, 4, 10, a * 0.36);
    line(i, 0, i, height);
    line(width - 1 - i, 0, width - 1 - i, height);
  }
  noStroke();
  for (let k = 0; k < 7; k++) {
    fill(4, 3, 8, 9);
    ellipse(-40, -20, 980 + k * 30, 900 + k * 24);
    ellipse(width + 30, -10, 860, 820);
    ellipse(-20, height + 20, 1040, 760);
    ellipse(width + 20, height + 10, 980, 800);
  }
}

function grain() {
  for (let i = 0; i < 14000; i++) {
    stroke(255, random(4, 11));
    point(random(width), random(height));
  }
  for (let i = 0; i < 7000; i++) {
    stroke(0, random(4, 9));
    point(random(width), random(height));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255);
  noiseDetail(4, 0.5);
  paint();
}

function paint() {
  drawBackground();
  drawAir();
  let paths = buildPaths(440);
  drawHalos(paths);
  drawBetween(paths);
  drawDescent();
  drawRibbons(paths);
  drawBlooms();
  drawPool();
  drawEmbers();
  drawVignette();
  drawGrain();
}

function drawBackground() {
  background(6, 8, 20);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let n = noise(y * 0.004, 0.4);
    let r = lerp(6, 22, pow(t, 1.05)) + pow(t, 2.1) * 20 + (n - 0.5) * 5;
    let g = lerp(8, 13, t) + pow(t, 2.4) * 7 + (n - 0.5) * 3;
    let b = lerp(20, 24, t) + (n - 0.5) * 4;
    stroke(r, g, b);
    strokeWeight(1);
    line(0, y, width, y);
  }
}

function drawAir() {
  blendMode(BLEND);
  noStroke();
  for (let i = 10; i >= 1; i--) {
    let k = i / 6;
    fill(36, 18, 32, 4);
    ellipse(500, 980, 760 * k, 1280 * k);
    fill(14, 30, 40, 4);
    ellipse(1120, 1060, 720 * k, 1240 * k);
    fill(18, 14, 28, 3);
    ellipse(width * 0.5, height * 0.46, 1500 * k * 0.55, 1860 * k * 0.55);
  }
}

function buildPaths(n) {
  let rose = [];
  let gold = [];
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    rose.push(sample(t, 1));
    gold.push(sample(t, -1));
  }
  return { rose: rose, gold: gold, n: n };
}

function sample(t, side) {
  let y0 = lerp(250, 1765, t);
  let x0 = width * 0.5
    + sin(t * PI * 1.04) * 34
    + (noise(t * 0.72, 1.8) - 0.5) * 260
    + (noise(t * 3.4, 4.4) - 0.5) * 14;
  let y = y0 + (noise(t * 3.1, 7.2) - 0.5) * 10;

  let dt = 0.0028;
  let t2 = t + dt;
  let y02 = lerp(250, 1765, t2);
  let x02 = width * 0.5
    + sin(t2 * PI * 1.04) * 34
    + (noise(t2 * 0.72, 1.8) - 0.5) * 260
    + (noise(t2 * 3.4, 4.4) - 0.5) * 14;
  let y2 = y02 + (noise(t2 * 3.1, 7.2) - 0.5) * 10;
  let dx = x02 - x0;
  let dy = y2 - y;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let px = -dy / len;
  let py = dx / len;

  let phase = t * TWO_PI * 3;
  let env = 0.18 + 0.82 * sin(t * PI);
  let cross = pow(abs(cos(phase)), 8);
  let sep = env * 186 * (1 - cross * 0.22);
  let w = lerp(13, 74, pow(t, 0.62));
  w *= 0.8 + 0.26 * noise(t * 2.1, side * 5.4 + 2);
  w *= 1 + cross * 0.5;

  let off = sin(phase) * sep * side;
  let fadeIn = constrain(t / 0.05, 0, 1);
  let fadeOut = constrain((1.06 - t) / 0.2, 0, 1);
  return {
    cx: x0 + px * off,
    cy: y + py * off,
    px: px,
    py: py,
    w: w,
    z: side * cos(phase),
    t: t,
    cross: cross,
    fade: fadeIn * fadeOut,
    spineX: x0,
    spineY: y
  };
}

function drawHalos(paths) {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < paths.rose.length; i += 3) {
    let p = paths.rose[i];
    let q = paths.gold[i];
    fill(255, 118, 102, 1.7 * p.fade);
    ellipse(p.cx, p.cy, 460, 460);
    fill(255, 132, 112, 3.6 * p.fade);
    ellipse(p.cx, p.cy, 190, 190);
    fill(255, 196, 112, 1.7 * q.fade);
    ellipse(q.cx, q.cy, 450, 450);
    fill(255, 204, 124, 3.6 * q.fade);
    ellipse(q.cx, q.cy, 180, 180);
  }
}

function drawBetween(paths) {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < paths.rose.length; i += 4) {
    let a = paths.rose[i];
    let b = paths.gold[i];
    let gap = dist(a.cx, a.cy, b.cx, b.cy);
    let strength = constrain((gap - 36) / 200, 0, 1) * a.fade;
    fill(255, 214, 182, 4.2 * strength);
    ellipse((a.cx + b.cx) / 2, (a.cy + b.cy) / 2, gap * 0.72, 30);
  }
}

function drawDescent() {
  let p = sample(0.5, 1);
  blendMode(ADD);
  noStroke();
  let y0 = p.cy + 30;
  for (let y = y0; y < 1810; y += 5) {
    let u = (y - y0) / (1810 - y0);
    let x = p.cx + (noise(y * 0.007, 12) - 0.5) * 80 * u + sin(u * 7.5) * 14;
    fill(255, 178, 142, 2.6 * (1 - u * 0.25));
    ellipse(x, y, lerp(28, 210, pow(u, 0.85)), 12);
  }
}

function drawRibbons(paths) {
  blendMode(BLEND);
  for (let i = 0; i < paths.n; i++) {
    let a = paths.rose[i];
    let b = paths.gold[i];
    if (a.z <= b.z) {
      drawRibbonSegment(a, paths.rose[i + 1], 1);
      drawRibbonSegment(b, paths.gold[i + 1], -1);
    } else {
      drawRibbonSegment(b, paths.gold[i + 1], -1);
      drawRibbonSegment(a, paths.rose[i + 1], 1);
    }
  }
}

function palette(side, t, z) {
  let front = map(z, -1, 1, 0.5, 1);
  let n = noise(t * 1.5, side * 2.4);
  if (side > 0) {
    return {
      r: lerp(148, 208, front) + n * 16,
      g: lerp(46, 82, front) + n * 6,
      b: lerp(52, 78, front),
      hr: 255,
      hg: lerp(186, 220, front),
      hb: lerp(168, 196, front),
      sr: 52,
      sg: 18,
      sb: 26
    };
  }
  return {
    r: lerp(156, 222, front) + n * 10,
    g: lerp(112, 166, front) + n * 10,
    b: lerp(34, 58, front),
    hr: 255,
    hg: lerp(206, 234, front),
    hb: lerp(156, 188, front),
    sr: 48,
    sg: 30,
    sb: 14
  };
}

function drawRibbonSegment(a, b, side) {
  let z = (a.z + b.z) / 2;
  let t = (a.t + b.t) / 2;
  let fade = (a.fade + b.fade) / 2;
  let pal = palette(side, t, z);
  let breath = 0.86 + 0.14 * noise(t * 2.6, side * 8.0);
  let alpha = 172 * fade * map(z, -1, 1, 0.64, 1) * breath;
  band(a, b, 0, pal, alpha * 0.18, 1.5);
  band(a, b, 0.4, { r: pal.sr, g: pal.sg, b: pal.sb }, alpha * 0.16, 0.14, 6, 8);
  let offs = [-0.36, -0.14, 0.08, 0.3];
  for (let f = 0; f < offs.length; f++) {
    let n = noise(t * 3.2, f * 1.7, side);
    band(a, b, offs[f], {
      r: pal.r + (n - 0.5) * 22,
      g: pal.g + (n - 0.5) * 14,
      b: pal.b + (n - 0.5) * 10
    }, alpha * 0.7, 0.19);
  }
  band(a, b, -0.05, { r: pal.hr, g: pal.hg, b: pal.hb }, alpha * 0.4, 0.065, -8, -10);
}

function band(a, b, fOff, col, alpha, widthK, sx, sy) {
  if (alpha <= 0.2) return;
  if (sx === undefined) sx = 0;
  if (sy === undefined) sy = 0;
  let ax = a.cx + a.px * a.w * fOff + sx;
  let ay = a.cy + a.py * a.w * fOff + sy;
  let bx = b.cx + b.px * b.w * fOff + sx;
  let by = b.cy + b.py * b.w * fOff + sy;
  let wa = a.w * widthK;
  let wb = b.w * widthK;
  noStroke();
  fill(col.r, col.g, col.b, alpha);
  beginShape();
  vertex(ax + a.px * wa, ay + a.py * wa);
  vertex(ax - a.px * wa, ay - a.py * wa);
  vertex(bx - b.px * wb, by - b.py * wb);
  vertex(bx + b.px * wb, by + b.py * wb);
  endShape(CLOSE);
}

function drawBlooms() {
  blendMode(ADD);
  noStroke();
  let ts = [1 / 6, 2 / 6, 0.5, 4 / 6, 5 / 6];
  for (let i = 0; i < ts.length; i++) {
    let t = ts[i];
    let p = sample(t, 1);
    let emphasis = pow(sin(t * PI), 1.3);
    let d = lerp(150, 540, emphasis);
    let a = lerp(4.5, 10, emphasis);
    for (let k = 7; k >= 1; k--) {
      let u = k / 7;
      fill(255, 220, 196, a * pow(1 - u, 1.15));
      ellipse(p.cx, p.cy, d * u, d * u * 0.94);
    }
    fill(255, 248, 240, a * 1.35);
    ellipse(p.cx, p.cy, d * 0.07, d * 0.07);
  }
}

function drawPool() {
  let cx = width * 0.5 + 6;
  let cy = 1838;
  blendMode(BLEND);
  noStroke();
  fill(7, 4, 8, 55);
  ellipse(cx, cy + 28, 1040, 168);
  blendMode(ADD);
