function paintGround() {
  const g = drawingContext;
  const lg = g.createLinearGradient(0, 0, 80, height);
  lg.addColorStop(0, "#14090d");
  lg.addColorStop(0.38, "#2c161e");
  lg.addColorStop(0.55, "#412028");
  lg.addColorStop(0.78, "#241016");
  lg.addColorStop(1, "#0e0709");
  g.fillStyle = lg;
  g.fillRect(0, 0, width, height);

  const pool = g.createRadialGradient(mx, my, 40, mx, my, 980);
  pool.addColorStop(0, "rgba(150, 68, 58, 0.55)");
  pool.addColorStop(0.42, "rgba(90, 32, 40, 0.26)");
  pool.addColorStop(1, "rgba(0,0,0,0)");
  g.fillStyle = pool;
  g.fillRect(0, 0, width, height);

  const ha = g.createRadialGradient(ax, ay, 10, ax, ay, 640);
  ha.addColorStop(0, "rgba(180, 96, 42, 0.20)");
  ha.addColorStop(1, "rgba(0,0,0,0)");
  g.fillStyle = ha;
  g.fillRect(0, 0, width, height);

  const hb = g.createRadialGradient(bx, by, 10, bx, by, 700);
