function paintClouds() {
  noStroke();
  for (let i = 0; i < 20; i++) {
    const x = random(width);
    const y = random(height);
    const r = random(200, 540);
    const n = noise(x * 0.0016, y * 0.0016);
    fill(78 + n * 36, 32 + n * 16, 44, 7);
    ellipse(x, y, r, r * random(0.62, 0.9));
  }
}

function paintBloom(x, y, r, cr, cg, cb, aScale, seedOff, layers) {
  noStroke();
  for (let i = layers; i >= 1; i--) {
    const t = i / layers;
    const rad = r * (0.1 + 0.9 * t);
    const aVal = aScale * pow(1 - t, 2.05);
    const ox = x + (noise(t * 1.7, seedOff) - 0.5) * r * 0.028;
    const oy = y + (noise(seedOff, t * 1.7) - 0.5) * r * 0.028;
    fill(cr, cg, cb, aVal);
    beginShape();
    const steps = 56;
    for (let k = 0; k < steps; k++) {
      const ang = (k / steps) * TAU;
      const n = noise(cos(ang) * 0.55 + seedOff, sin(ang) * 0.55 + 4.0, t * 1.4);
      const rr = rad * (0.935 + n * 0.09);
      vertex(ox + cos(ang) * rr, oy + sin(ang) * rr * 1.045);
    }
    endShape(CLOSE);
  }
}

function paintStream(sx, sy, dir, baseR, baseG, baseB) {
  noFill();
  for (let i = 0; i < 640; i++) {
    const a0 = random(TAU);
    const rd = random(8, 72) * random();
    let x = sx + cos(a0) * rd;
    let y = sy + sin(a0) * rd;
    let px = x;
    let py = y;
    const cr = baseR + random(-10, 10);
    const cg = baseG + random(-16, 16);
    const cb = baseB + random(-10, 10);
    const w = random(0.45, 1.45);
    for (let s = 0; s < 34; s++) {
      const dx = x - mx;
      const dy = y - my;
      const d = sqrt(dx * dx + dy * dy) + 0.001;
      const ang = noise(x * 0.00135, y * 0.00135, dir * 1.7) * TAU;
      const tx = -dy / d;
      const ty = dx / d;
      const pull = constrain(1 - d / 520, 0, 1);
      x += cos(ang) * 6.5 + tx * dir * 2.2 - (dx / d) * pull * 1.4;
      y += sin(ang) * 6.5 + ty * dir * 2.2 - (dy / d) * pull * 1.4;
      const near = constrain(1 - d / 700, 0, 1);
      const fade = 1 - s / 34;
      stroke(cr, cg, cb, (7 + near * 14) * fade);
      strokeWeight(w * (0.75 + near * 0.85));
      line(px, py, x, y);
      px = x;
      py = y;
      if (d > 860 || x < -40 || x > width + 40 || y < -40 || y > height + 40) break;
    }
  }
}

function paintWeave() {
  noFill();
  for (let i = 0; i < 2800; i++) {
    const x = mx + (random() + random() + random() - 1.5) * 230;
    const y = my + (random() + random() + random() - 1.5) * 200;
    const ang = noise(x * 0.008, y * 0.008, i * 0.002) * TAU;
    const len = random(7, 26);
    if (i % 2 === 0) stroke(255, 186 + random(-12, 18), 108, random(12, 30));
    else stroke(255, 126 + random(-10, 16), 146, random(12, 30));
    strokeWeight(random(0.7, 2.3));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

function paintReach() {
  noFill();
  for (let i = 0; i < 48; i++) {
    const x1 = ax + random(-50, 50);
    const y1 = ay + random(-50, 50);
    const x2 = bx + random(-60, 60);
    const y2 = by + random(-60, 60);
    const u = random();
    let endT;
    if (u < 0.34) endT = random(0.42, 0.72);
    else if (u < 0.7) endT = random(0.88, 1.02);
    else endT = random(1.08, 1.32);
    const ex = lerp(x1, x2, endT);
    const ey = lerp(y1, y2, endT);
    const bend = random(-120, 120);
    const bend2 = random(-90, 90);
    const c1x = lerp(x1, ex, 0.33) + bend;
    const c1y = lerp(y1, ey, 0.33) + bend2 * 0.35;
    const c2x = lerp(x1, ex, 0.66) - bend * 0.45;
    const c2y = lerp(y1, ey, 0.66) + bend2;
    stroke(255, 214, 186, random(6, 18));
    strokeWeight(random(0.4, 1.25));
    bezier(x1, y1, c1x, c1y, c2x, c2y, ex, ey);
  }
}

function paintMotes() {
  for (let i = 0; i < 1500; i++) {
