let cx1 = 650;
let cy1 = 940;
let cx2 = 1000;
let cy2 = 1260;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  ground();
  upperAir();
  blendMode(ADD);
  climate();
  streams();
  gestures();
  leak(cx1, cy1, 360, 255, 156, 118);
  leak(cx2, cy2, 440, 255, 118, 86);
  nearBody();
  paintKnot(cx1, cy1, cx2, cy2, 250, 740, 0);
  paintKnot(cx2, cy2, cx1, cy1, 320, 880, 1);
  nucleus(cx1, cy1, cx2, cy2);
  nucleus(cx2, cy2, cx1, cy1);
  interval();
  brightThreads();
  sparks();
  blendMode(BLEND);
  ash(cx1, cy1, cx2, cy2, 230);
  ash(cx2, cy2, cx1, cy1, 290);
  vignette();
  grain();
}

function ground() {
  noFill();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r;
    let g;
    let b;
    if (t < 0.34) {
      let u = t / 0.34;
      r = lerp(11, 30, u);
      g = lerp(9, 15, u);
      b = lerp(20, 28, u);
    } else if (t < 0.64) {
      let u = (t - 0.34) / 0.3;
      let bell = Math.sin(u * Math.PI);
      r = lerp(30, 26, u) + bell * 40;
      g = lerp(15, 13, u) + bell * 12;
      b = lerp(28, 20, u) + bell * 6;
    } else {
      let u = (t - 0.64) / 0.36;
      r = lerp(42, 7, u);
      g = lerp(16, 5, u);
      b = lerp(22, 9, u);
    }
    let n = noise(y * 0.004) * 2.2;
    stroke(r + n, g + n * 0.4, b + n * 0.3);
    line(0, y, width, y);
  }
}

function upperAir() {
  noStroke();
  for (let i = 0; i < 18; i++) {
    fill(36, 32, 64, 3);
    ellipse(280 + i * 6, 240 + i * 4, 980, 760);
  }
  for (let i = 0; i < 26; i++) {
    fill(86, 34, 32, 3.5);
    ellipse(840, 1120, 980 + i * 18, 1180 + i * 16);
  }
}

function climate() {
  noStroke();
  for (let i = 12; i >= 1; i--) {
    let t = i / 12;
    fill(255, 112, 78, 2.1);
    ellipse(830, 1110, 1460 * t, 1620 * t);
  }
}

function field(x, y) {
  let dx1 = x - cx1;
  let dy1 = y - cy1;
  let d1 = Math.sqrt(dx1 * dx1 + dy1 * dy1) + 8;
  let dx2 = x - cx2;
  let dy2 = y - cy2;
  let d2 = Math.sqrt(dx2 * dx2 + dy2 * dy2) + 8;
  let s1 = 230 / (d1 * 0.22 + 52);
  let s2 = 270 / (d2 * 0.18 + 48);
  let vx = (-dy1 / d1) * s1 + (dy2 / d2) * s2;
  let vy = (dx1 / d1) * s1 + (-dx2 / d2) * s2;
  let mx = (cx1 + cx2) * 0.5;
  let my = (cy1 + cy2) * 0.5;
  let dmx = mx - x;
  let dmy = my - y;
  let dm = Math.sqrt(dmx * dmx + dmy * dmy) + 30;
  vx += (dmx / dm) * 0.5;
  vy += (dmy / dm) * 0.5;
  vy -= 0.2;
  let n1 = noise(x * 0.00115, y * 0.00115);
  let n2 = noise(x * 0.00115 + 18, y * 0.00115 + 9);
  vx += (n1 - 0.5) * 1.55;
  vy += (n2 - 0.5) * 1.55;
  return { x: vx, y: vy };
}

function presence(x, y) {
  let d1 = dist(x, y, cx1, cy1);
  let d2 = dist(x, y, cx2, cy2);
  let mx = (cx1 + cx2) * 0.5;
  let my = (cy1 + cy2) * 0.5;
  let dm = dist(x, y, mx, my);
  let near = Math.min(d1, d2, dm * 0.9);
  return constrain(map(near, 36, 980, 1, 0), 0, 1);
}

function stream(x, y, steps, len, cr, cg, cb, baseA, weight) {
  for (let i = 0; i < steps; i++) {
    let v = field(x, y);
    let m = Math.sqrt(v.x * v.x + v.y * v.y) + 0.0001;
    let nx = x + (v.x / m) * len;
    let ny = y + (v.y / m) * len;
    let t = i / steps;
    let env = Math.sin(t * Math.PI);
    let p = presence(x, y);
    let a = baseA * env * (0.2 + 0.8 * p);
    if (a > 0.35) {
      stroke(cr, cg, cb, a);
      strokeWeight(weight * (0.45 + env * 0.75));
      line(x, y, nx, ny);
    }
    x = nx;
    y = ny;
    if (x < -120 || x > 1720 || y < -120 || y > 2120) break;
  }
}

function streams() {
  for (let i = 0; i < 150; i++) {
    let ang = random(TAU);
    let rad = 70 + Math.pow(random(), 0.62) * 920;
    let x = 830 + Math.cos(ang) * rad * 0.92;
    let y = 1100 + Math.sin(ang) * rad * 1.02;
    if (y < 560 && random() < 0.7) continue;
    if (random() < 0.2) {
      stream(x, y, 52, 9, 176, 168, 214, 5.5, 0.7);
    } else {
      stream(x, y, 66, 8.5, 255, 172, 132, 9, 0.9);
    }
  }
}

function bundle(pts, cr, cg, cb, ca, weight, passes) {
  noFill();
  for (let p = 0; p < passes; p++) {
    let ox = random(-16, 16);
    let oy = random(-16, 16);
    stroke(cr, cg, cb, ca * random(0.35, 1));
    strokeWeight(weight * random(0.35, 1.05));
    beginShape();
    curveVertex(pts[0].x + ox, pts[0].y + oy);
    for (let i = 0; i < pts.length; i++) {
      let jx = (noise(p * 0.17, i * 0.31) - 0.5) * weight * 1.6;
      let jy = (noise(p * 0.17 + 4, i * 0.31) - 0.5) * weight * 1.6;
      curveVertex(pts[i].x + ox + jx, pts[i].y + oy + jy);
    }
    let last = pts[pts.length - 1];
    curveVertex(last.x + ox, last.y + oy);
    endShape();
  }
}

function gestures() {
  bundle(
    [
      { x: 790, y: 1880 },
      { x: 640, y: 1600 },
      { x: 710, y: 1360 },
      { x: 900, y: 1160 },
      { x: 770, y: 980 },
      { x: 910, y: 700 },
      { x: 820, y: 340 }
    ],
    255, 214, 186, 8, 6, 18
  );
  bundle(
    [
      { x: 1180, y: 360 },
      { x: 1040, y: 640 },
      { x: 860, y: 980 },
      { x: 1080, y: 1280 },
      { x: 1340, y: 1560 }
    ],
    186, 176, 220, 6, 2.2, 10
  );
}

function leak(cx, cy, radius, cr, cg, cb) {
  noStroke();
  for (let i = 0; i < 46; i++) {
    let ang = random(TAU);
    let n = noise(Math.cos(ang) + 2, Math.sin(ang) + 3, cx * 0.01);
    let rad = radius * (0.5 + n * 0.85);
    let x = cx + Math.cos(ang) * rad * 0.7;
    let y = cy + Math.sin(ang) * rad * 0.7;
    fill(cr, cg, cb, 3.2);
    ellipse(x, y, radius * random(0.22, 0.48), radius * random(0.16, 0.34));
  }
}

function nearBody() {
  for (let i = 0; i < 90; i++) {
    let right = random() > 0.46;
    let cx = right ? cx2 : cx1;
    let cy = right ? cy2 : cy1;
    let reach = right ? 300 : 230;
    let ang = random(TAU);
    let rad = 24 + Math.pow(random(), 0.8) * reach;
    let x = cx + Math.cos(ang) * rad;
    let y = cy + Math.sin(ang) * rad;
    if (right) stream(x, y, 16, 7, 255, 146, 108, 15, 1.45);
    else stream(x, y, 16, 7, 255, 196, 156, 16, 1.35);
  }
}

function paintKnot(cx, cy, ox, oy, radius, count, kind) {
  let dir = atan2(oy - cy, ox - cx);
  noStroke();
  for (let i = 0; i < count; i++) {
    let ang = random(TAU);
    let rad = Math.pow(random(), 1.48) * radius;
    let n1 = noise(i * 0.02, kind * 3);
    let x = cx + Math.cos(ang) * rad * (0.76 + n1 * 0.48);
    let y = cy + Math.sin(ang) * rad * (0.82 + noise(i * 0.02 + 4, kind * 3) * 0.38);
    let face = Math.cos(ang - dir);
    let depth = constrain(rad / radius, 0, 1);
    let facing = constrain(map(face, -1, 1, 0, 1), 0, 1);
    let hot = constrain((1 - depth * 0.7) * lerp(0.32, 1, facing), 0, 1);
    let r;
    let g;
    let b;
    if (kind < 0.5) {
      r = lerp(148, 255, hot);
      g = lerp(76, 222, Math.pow(hot, 1.08));
      b = lerp(62, 192, Math.pow(hot, 1.4));
    } else {
      r = lerp(124, 255, hot);
      g = lerp(38, 174, Math.pow(hot, 1.18));
      b = lerp(60, 138, Math.pow(hot, 1.28));
    }
    let a = (10 + 52 * Math.pow(1 - depth, 1.12)) * random(0.5, 1.05);
    fill(r, g, b, a);
    push();
    translate(x, y);
    rotate(ang + facing * 0.7);
    ellipse(0, 0, random(12, 46) * (1.05 - depth * 0.32), random(3, 12));
    pop();
  }
  for (let i = 0; i < count * 0.38; i++) {
    let ang = random(TAU);
    let rad = radius * random(0.72, 1.16);
    let x = cx + Math.cos(ang) * rad;
    let y = cy + Math.sin(ang) * rad;
    let face = Math.cos(ang - dir);
    let facing = constrain(map(face, -1, 1, 0, 1), 0, 1);
    let hot = 0.22 + facing * 0.5;
    let r = kind < 0.5 ? lerp(160, 255, hot) : lerp(138, 236, hot);
    let g = kind < 0.5 ? lerp(82, 186, hot) : lerp(48, 124, hot);
    let b = kind < 0.5 ? lerp(70, 154, hot) : lerp(58, 112, hot);
    fill(r, g, b, random(4, 13));
    push();
    translate(x, y);
    rotate(ang);
    ellipse(0, 0, random(16, 58), random(4, 13));
    pop();
  }
}

function nucleus(cx, cy, ox, oy) {
  let dir = atan2(oy - cy, ox - cx);
  let x = cx + Math.cos(dir) * 18;
  let y = cy + Math.sin(dir) * 14;
  noStroke();
  for (let i = 14; i >= 1; i--) {
    let t = i / 14;
    fill(255, 186, 148, (1 - t) * 7 + 1);
    ellipse(x, y, 118 * t + 10, 98 * t + 8);
  }
  for (let i = 8; i >= 1; i--) {
    let t = i / 8;
    fill(255, 248, 240, (1 - t) * 16);
    ellipse(x + random(-1.4, 1.4), y + random(-1.4, 1.4), 34 * t + 4, 28 * t + 3);
  }
}

function interval() {
  let mx = (cx1 + cx2) * 0.5;
  let my = (cy1 + cy2) * 0.5;
  noStroke();
  for (let i = 16; i >= 1; i--) {
    let t = i / 16;
    fill(255, 198, 166, (1 - t) * 3.1);
    ellipse(mx, my, 540 * t, 360 * t);
  }
  for (let k = 0; k < 110; k++) {
    let t = 0.3 + random() * 0.4;
    let x = lerp(cx1, cx2, t) + random(-34, 34);
    let y = lerp(cy1, cy2, t) + random(-28, 28);
    fill(255, 230, 208, random(5, 15));
    ellipse(x, y, random(3, 12), random(2, 7));
  }
}

function brightThreads() {
  for (let i = 0; i < 28; i++) {
    let t = random(0.28, 0.72);
    let x = lerp(cx1, cx2, t) + random(-48, 48);
    let y = lerp(cy1, cy2, t) + random(-42, 42);
    stream(x, y, 22, 6.5, 255, 236, 220, 15, 0.75);
  }
}

function sparks() {
  noStroke();
  for (let i = 0; i < 240; i++) {
    let ang = random(TAU);
    let rad = Math.pow(random(), 0.4) * 760;
    let x = 830 + Math.cos(ang) * rad * 0.82;
    let y = 1100 + Math.sin(ang) * rad * 0.96;
    let p = presence(x, y);
    if (p < 0.12 && random() > 0.25) continue;
    let cool = random() < 0.18;
    if (cool) fill(196, 188, 224, 6 + p * 22);
    else fill(255, 220, 188, 7 + p * 36);
    ellipse(x, y, random(1.1, 3.4), random(1.1, 3.4));
  }
}

function ash(cx, cy, ox, oy, radius) {
  let dir = atan2(oy - cy, ox - cx) + Math.PI;
  noStroke();
  for (let i = 0; i < 70; i++) {
    let ang = dir + random(-1.05, 1.05);
    let rad = random(0.12, 0.78) * radius;
    let x = cx + Math.cos(ang) * rad;
    let y = cy + Math.sin(ang) * rad;
    fill(14, 5, 10, random(7, 18));
    ellipse(x, y, random(14, 48), random(7, 20));
  }
}

function vignette() {
  noStroke();
  for (let i = 0; i < 240; i++) {
    fill(5, 3, 8, map(i, 0, 240, 8, 0));
    rect(0, i, width, 1);
    rect(0, height - 1 - i, width, 1);
    rect(i, 0, 1, height);
    rect(width - 1 - i, 0, 1, height);
  }
}

function grain() {
  strokeWeight(1);
  for (let i = 0; i < 64000; i++) {
    let x = random(width);
    let y = random(height);
    let v = noise(x * 0.014, y * 0.014);
    if (v > 0.52) stroke(255, 232, 214, random(3, 10));
    else stroke(6, 3, 8, random(4, 13));
    point(x, y);
  }
}

