function glow(x, y, r, cOuter, cInner, layers, aBase, aspect, ang) {
  if (aspect === undefined) aspect = 1;
  if (ang === undefined) ang = 0;
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let c = lerpColor(cInner, cOuter, t);
    let jx = (noise(i * 0.13, x * 0.002, 1.7) - 0.5) * r * 0.08;
    let jy = (noise(i * 0.13, y * 0.002, 8.2) - 0.5) * r * 0.08;
    let br = 1 + (noise(i * 0.09, 2.4) - 0.5) * 0.12;
    fill(red(c), green(c), blue(c), aBase);
    ellipse(jx, jy, r * 2 * t * br, r * 2 * t * br * aspect);
  }
  pop();
}

function paintNight() {
  noStroke();
  for (let i = 10; i >= 1; i--) {
    fill(26, 18, 36, 7);
    ellipse(420, 360, 1500 * i / 10, 1200 * i / 10);
  }
  for (let i = 10; i >= 1; i--) {
    fill(40, 20, 16, 8);
    ellipse(1180, 1680, 1700 * i / 10, 1300 * i / 10);
  }
  for (let i = 0; i < 1800; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.55) fill(52, 26, 28, random(3, 9));
    else if (n < 0.4) fill(16, 14, 28, random(3, 8));
    else fill(32, 16, 18, random(3, 8));
    ellipse(x, y, random(24, 90), random(18, 70));
  }
}

function satellites(cx, cy, n, r, cOut, cIn, spread, ang) {
  for (let i = 0; i < n; i++) {
    let a = random(TWO_PI);
    let d = pow(random(), 0.7) * spread;
    glow(
      cx + cos(a) * d,
      cy + sin(a) * d,
      r * random(0.55, 1.05),
      cOut,
      cIn,
      8,
      random(2.2, 4.2),
      random(0.65, 1.15),
      ang + random(-0.6, 0.6)
    );
  }
}

function plume(x0, y0, x1, y1, ang, isRose) {
  for (let s = 0; s <= 6; s++) {
    let t = s / 6;
    let x = lerp(x0, x1, t);
    let y = lerp(y0, y1, t);
    let r = lerp(isRose ? 220 : 248, 132, t);
    let cOut, cIn;
    if (isRose) {
      cOut = lerpColor(color(158, 56, 62), color(214, 120, 108), t);
      cIn = lerpColor(color(232, 124, 108), color(255, 206, 184), t);
    } else {
      cOut = lerpColor(color(170, 108, 44), color(214, 150, 96), t);
      cIn = lerpColor(color(236, 176, 110), color(255, 214, 176), t);
    }
    glow(x, y, r, cOut, cIn, 14, lerp(5.5, 3.2, t), lerp(0.7, 0.88, t), ang);
  }
}

function smear(cx, cy, sx, sy, n, palette) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = cx + randomGaussian() * sx;
    let y = cy + randomGaussian() * sy;
    let c = palette[floor(random(palette.length))];
    if (random() < 0.6) {
      c = lerpColor(c, palette[floor(random(palette.length))], random());
    }
    fill(red(c), green(c), blue(c), random(5, 14));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(46, 168), random(16, 54));
    pop();
  }
}

function dabField(cx, cy, sx, sy, n, palette, sMin, sMax, aMin, aMax) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = cx + randomGaussian() * sx;
    let y = cy + randomGaussian() * sy;
    let c = palette[floor(random(palette.length))];
    if (random() < 0.55) {
      c = lerpColor(c, palette[floor(random(palette.length))], random());
    }
    fill(red(c), green(c), blue(c), random(aMin, aMax));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    let s = random(sMin, sMax);
    ellipse(0, 0, s, s * random(0.45, 1));
    pop();
  }
}

function pigment(rose, gold, meet, ang) {
