    color(124, 72, 26),
    color(176, 112, 42),
    color(224, 162, 84),
    color(255, 204, 140),
    color(255, 226, 188)
  ];
  const sharedPalette = [
    color(255, 150, 124),
    color(255, 186, 140),
    color(255, 206, 170),
    color(255, 228, 208),
    color(240, 130, 110),
    color(255, 196, 120)
  ];

  smear(rose.x, rose.y, 180, 210, 26, rosePalette);
  smear(gold.x, gold.y, 210, 200, 28, goldPalette);
  smear(meet.x, meet.y, 150, 130, 20, sharedPalette);

  dabField(rose.x - 16, rose.y - 8, 200, 230, 680, rosePalette, 5, 26, 8, 32);
  dabField(rose.sx, rose.sy, 86, 96, 260, rosePalette, 4, 16, 14, 46);
  dabField(gold.x + 16, gold.y + 12, 220, 200, 740, goldPalette, 5, 28, 8, 30);
  dabField(gold.sx, gold.sy, 96, 90, 280, goldPalette, 4, 16, 14, 44);
  dabField(meet.x, meet.y, 140, 120, 480, sharedPalette, 4, 20, 10, 34);

  let ux = cos(ang);
  let uy = sin(ang);
  dabField(rose.sx - ux * 72, rose.sy - uy * 72, 48, 54, 70, [color(96, 28, 40), color(140, 48, 56)], 6, 20, 10, 26);
  dabField(gold.sx + ux * 78, gold.sy + uy * 78, 52, 48, 80, [color(110, 64, 22), color(160, 100, 40)], 6, 20, 10, 24);
}

function filament(x0, y0, x1, y1, amp, sw, col, seed) {
  noFill();
  stroke(red(col), green(col), blue(col), alpha(col));
  strokeWeight(sw);
  beginShape();
  let steps = 28;
  let dx = x1 - x0;
  let dy = y1 - y0;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let px = -dy / len;
  let py = dx / len;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let env = sin(PI * t);
    let wob = (noise(seed, t * 2.4) - 0.5) * 2 * amp * env;
    let x = lerp(x0, x1, t) + px * wob;
    let y = lerp(y0, y1, t) + py * wob;
    if (i === 0 || i === steps) curveVertex(x, y);
    curveVertex(x, y);
  }
  endShape();
}

function filaments(rose, gold) {
  const cols = [
    color(255, 196, 176, 22),
    color(255, 214, 170, 18),
    color(255, 176, 150, 16),
    color(255, 228, 210, 24),
    color(255, 186, 130, 15)
  ];
  for (let i = 0; i < 11; i++) {
    let t0 = random(0.12, 0.4);
    let t1 = random(0.6, 0.92);
    let sp = random(16, 72);
    let x0 = lerp(rose.x, gold.x, t0) + random(-sp, sp);
    let y0 = lerp(rose.y, gold.y, t0) + random(-sp, sp);
    let x1 = lerp(rose.x, gold.x, t1) + random(-sp, sp);
    let y1 = lerp(rose.y, gold.y, t1) + random(-sp, sp);
    let c = cols[floor(random(cols.length))];
    filament(x0, y0, x1, y1, random(14, 54), random(0.5, 2.2), c, i * 0.37);
    if (i % 3 === 0) {
      filament(x0, y0, x1, y1, random(18, 60), random(3.5, 7), color(red(c), green(c), blue(c), 7), i * 0.37 + 9);
    }
  }
}

function dustArc(cx, cy, r, aspect, rot, a0, a1, wob, sw, col, seed) {
  noFill();
  stroke(red(col), green(col), blue(col), alpha(col));
  strokeWeight(sw);
  beginShape();
  let steps = 36;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = lerp(a0, a1, t);
    let rr = r + (noise(seed, cos(a) * 1.3, sin(a) * 1.3) - 0.5) * 2 * wob;
    let lx = cos(a) * rr;
    let ly = sin(a) * rr * aspect;
    let x = cx + lx * cos(rot) - ly * sin(rot);
    let y = cy + lx * sin(rot) + ly * cos(rot);
    if (i === 0 || i === steps) curveVertex(x, y);
    curveVertex(x, y);
  }
  endShape();
}

function ripples(rose, gold, meet, ang) {
  dustArc(rose.sx, rose.sy, 168, 0.9, 0.2, 0.5, 2.5, 14, 1.3, color(255, 186, 168, 20), 2.1);
  dustArc(rose.sx, rose.sy, 230, 0.86, -0.4, 2.4, 4.7, 18, 1.0, color(255, 160, 140, 14), 3.4);
  dustArc(gold.sx, gold.sy, 182, 0.84, ang, 3.5, 5.7, 16, 1.4, color(255, 206, 160, 18), 4.2);
  dustArc(gold.sx, gold.sy, 254, 0.8, 0.5, 0.7, 2.9, 20, 1.1, color(255, 186, 130, 12), 5.5);
  dustArc(meet.x, meet.y, 360, 0.6, ang, 0.3, 2.2, 24, 1.4, color(255, 214, 190, 12), 6.6);
  dustArc(meet.x, meet.y, 448, 0.56, ang, 3.4, 5.5, 28, 1.1, color(255, 196, 170, 9), 7.7);
}

function motes(rose, gold, meet) {
  noStroke();
  for (let i = 0; i < 16; i++) {
    let x = meet.x + randomGaussian() * 300;
    let y = meet.y + randomGaussian() * 340;
    let c = random() < 0.5 ? color(255, 186, 160) : color(255, 210, 160);
    fill(red(c), green(c), blue(c), random(5, 11));
    ellipse(x, y, random(10, 32), random(10, 32));
  }

  for (let i = 0; i < 2400; i++) {
    let pick = random();
    let x, y, col;
    if (pick < 0.34) {
      x = rose.x + randomGaussian() * 220;
      y = rose.y + randomGaussian() * 240;
      col = random() < 0.5 ? color(255, 170, 146) : color(255, 206, 186);
    } else if (pick < 0.68) {
      x = gold.x + randomGaussian() * 240;
      y = gold.y + randomGaussian() * 220;
      col = random() < 0.5 ? color(255, 206, 150) : color(255, 220, 180);
    } else {
      let t = random();
      x = lerp(rose.x, gold.x, t) + randomGaussian() * 96;
      y = lerp(rose.y, gold.y, t) + randomGaussian() * 84;
      col = color(255, 220, 198);
    }
    fill(red(col), green(col), blue(col), random(10, 42));
    let s = random() < 0.88 ? random(1.1, 2.8) : random(2.8, 6);
    ellipse(x, y, s, s);
  }

  for (let i = 0; i < 170; i++) {
    let y = random(70, 740);
    let spread = map(y, 70, 740, 190, 52);
    let x = meet.x - 10 + randomGaussian() * spread;
    let a = map(y, 70, 740, 3, 24);
    stroke(255, random(180, 210), random(150, 180), a);
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + random(-1.4, 1.4), y + random(4, 13));
  }

  for (let i = 0; i < 140; i++) {
    let y = random(1480, 1930);
    let spread = map(y, 1480, 1930, 64, 200);
    let x = meet.x + 24 + randomGaussian() * spread;
    let a = map(y, 1480, 1930, 22, 3);
    stroke(255, random(170, 200), random(130, 165), a);
    strokeWeight(random(0.5, 1.6));
    line(x, y, x + random(-1.2, 1.2), y - random(3, 11));
  }
  noStroke();

  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let y = random(height);
    if (dist(x, y, meet.x, meet.y) < 480) continue;
    fill(186, 196, 214, random(5, 16));
    ellipse(x, y, random(1.1, 2.4), random(1.1, 2.4));
  }

  for (let i = 0; i < 28; i++) {
    let x = meet.x + randomGaussian() * 400;
    let y = meet.y + randomGaussian() * 460;
    let a = random(TWO_PI);
    let d = random(5, 13);
    fill(255, 186, 160, random(16, 44));
    ellipse(x, y, 2.2, 2.2);
    fill(255, 214, 170, random(16, 44));
    ellipse(x + cos(a) * d, y + sin(a) * d, 2.0, 2.0);
  }

  for (let i = 0; i < 70; i++) {
    fill(255, 242, 230, random(28, 72));
    ellipse(meet.x - 12 + randomGaussian() * 64, meet.y + 6 + randomGaussian() * 46, random(1.1, 2.6), random(1.1, 2.6));
  }
}

function grain() {
  strokeWeight(1);
  for (let i = 0; i < 18000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.52) stroke(255, 220, 200, random(2, 7));
    else stroke(8, 5, 8, random(3, 9));
    point(x, y);
  }
  noStroke();
}

function vignette() {
  loadPixels();
  let d = pixelDensity();
  let w = width * d;
  let h = height * d;
  for (let y = 0; y < h; y++) {
    let ny = (y / h - 0.5) * 2;
    for (let x = 0; x < w; x++) {
      let nx = (x / w - 0.5) * 2;
      let e = nx * nx * 0.62 + ny * ny * 0.78;
      let v = e - 0.4;
      if (v <= 0) continue;
      if (v > 1) v = 1;
      let s = v * v * 0.58;
      let k = 1 - s;
      let idx = 4 * (y * w + x);
      pixels[idx] *= k;
      pixels[idx + 1] *= k * (1 - s * 0.04);
      pixels[idx + 2] *= k * (1 - s * 0.16);
    }
  }
  updatePixels();
}

