function drawBackgroundGradient() {
  const ctx = drawingContext;
  const cx = width / 2;
  const cy = height / 2;
  const g = ctx.createRadialGradient(cx, cy, 20, cx, cy, 1500);
  g.addColorStop(0, 'rgba(58,34,88,0.55)');
  g.addColorStop(0.45, 'rgba(24,14,44,0.35)');
  g.addColorStop(1, 'rgba(6,4,12,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawHalos() {
  const ctx = drawingContext;

  const warm = ctx.createRadialGradient(610, 860, 20, 610, 860, 520);
  warm.addColorStop(0, 'rgba(255,95,120,0.18)');
  warm.addColorStop(1, 'rgba(255,95,120,0)');
  ctx.fillStyle = warm;
  ctx.fillRect(120, 280, 1080, 1040);

  const cool = ctx.createRadialGradient(990, 1140, 20, 990, 1140, 520);
  cool.addColorStop(0, 'rgba(80,150,255,0.16)');
  cool.addColorStop(1, 'rgba(80,150,255,0)');
  ctx.fillStyle = cool;
  ctx.fillRect(500, 700, 1080, 1040);
}

function drawCoreGlow() {
  const ctx = drawingContext;
  const cx = width / 2;
  const cy = height / 2;
  const g = ctx.createRadialGradient(cx, cy, 8, cx, cy, 450);
  g.addColorStop(0, 'rgba(255,248,225,0.95)');
  g.addColorStop(0.16, 'rgba(255,205,140,0.55)');
  g.addColorStop(0.42, 'rgba(230,110,160,0.22)');
  g.addColorStop(1, 'rgba(230,110,160,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function knotPoint(t, cx, cy, R, r, phase = 0, radialOffset = 0, yScale = 1.0) {
  const rr = R + (r + radialOffset) * cos(3 * t + phase);
  return {
    x: cx + rr * cos(2 * t),
    y: cy + rr * sin(2 * t) * yScale
  };
}

function drawKnot(cx, cy, R, r, phase, yScale = 1, wobble = 0.05) {
  const steps = 460;
  beginShape();
  for (let i = 0; i <= steps; i++) {
    const t = map(i, 0, steps, 0, TWO_PI);
    const p = knotPoint(t, cx, cy, R, r, phase, 0, yScale);
    const n1 = noise(t * 2.8, phase * 0.35);
    const n2 = noise(t * 3.1 + 10, phase * 0.28 + 5);
    const dx = (n1 - 0.5) * 210 * wobble;
    const dy = (n2 - 0.5) * 170 * wobble;
    vertex(p.x + dx, p.y + dy);
  }
  endShape(CLOSE);
}

function drawBraidedLove() {
