function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
}

function draw() {
  const W = width;
  const H = height;
  background(7, 6, 18);

  let ctx = drawingContext;
  let grad = ctx.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0, '#0a0614');
  grad.addColorStop(0.45, '#150b22');
  grad.addColorStop(0.75, '#0f0819');
  grad.addColorStop(1, '#05030c');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  strokeCap(ROUND);
  noFill();

  let A = createVector(W * 0.39, H * 0.36);
  let B = createVector(W * 0.63, H * 0.62);
  let C = p5.Vector.lerp(A, B, 0.5);

  drawGlow(C.x, C.y, 680, 'rgba(255,178,130,0.34)', 'rgba(8,5,18,0)');
  drawGlow(A.x, A.y, 300, 'rgba(255,130,80,0.30)', 'rgba(8,5,18,0)');
  drawGlow(B.x, B.y, 300, 'rgba(110,160,255,0.30)', 'rgba(8,5,18,0)');

  blendMode(ADD);

  push();
  translate(C.x, C.y);
  for (let i = 0; i < 30; i++) {
    let rx = random(300, 780);
    let ry = rx * random(0.38, 0.68);
    let rot = random(-PI / 3.2, PI / 3.2) + (i % 2 === 0 ? 0.18 : -0.18);
    let edgeAlpha = map(i, 0, 29, 45, 12);
    let c1 = color(255, 150 + i * 2, 90, edgeAlpha);
    let c2 = color(105, 155, 255, edgeAlpha);
    let c = lerpColor(c1, c2, random(0.3, 0.7));
    stroke(c);
    strokeWeight(random(0.8, 2.2));
    push();
    rotate(rot);
    ellipse(0, 0, rx * 2, ry * 2);
    pop();
  }
  pop();

  const SEG = 90;
  for (let i = 0; i < 68; i++) {
    let ang1 = random(TWO_PI);
    let ang2 = ang1 + random(-PI * 0.65, PI * 0.65);
    let rad1 = random(12, 100) * (i % 9 === 0 ? 1.4 : 1);
    let rad2 = random(12, 100) * (i % 9 === 0 ? 1.4 : 1);
    let start = createVector(A.x + cos(ang1) * rad1, A.y + sin(ang1) * rad1);
    let end = createVector(B.x + cos(ang2) * rad2, B.y + sin(ang2) * rad2);

    let dir = p5.Vector.sub(B, A);
    let perp = createVector(-dir.y, dir.x).normalize();
    let bulge = (random() - 0.45) * 950 * (0.55 + random() * 0.75);
    let c1 = p5.Vector.add(start, dir.copy().mult(0.18)).add(perp.copy().mult(bulge * 0.55));
    let c2 = p5.Vector.add(end, dir.copy().mult(-0.18)).add(perp.copy().mult(bulge * 0.72));

    let warm = color(255, 172, 90, 150);
    let cool = color(110, 165, 255, 150);
    let px = 0;
    let py = 0;
    for (let s = 0; s <= SEG; s++) {
      let t = s / SEG;
      let x = bezierPoint(start.x, c1.x, c2.x, end.x, t);
      let y = bezierPoint(start.y, c1.y, c2.y, end.y, t);
      let nx = noise(x * 0.0015, y * 0.0015, i * 0.31);
      let ny = noise(x * 0.0012 + 81, y * 0.0012 + 19, i * 0.67);
      x += (nx - 0.5) * 16;
      y += (ny - 0.5) * 16;
      stroke(lerpColor(warm, cool, t));
      strokeWeight(1.2 + 2.2 * sin(t * PI));
      if (s > 0) {
        line(px, py, x, y);
      }
      px = x;
      py = y;
    }
  }

  for (let i = 0; i < 36; i++) {
    let useA = i < 18;
    let cx = (useA ? A.x : B.x) + random(-35, 35);
    let cy = (useA ? A.y : B.y) + random(-35, 35);
    let a0 = random(TWO_PI);
    let a1 = a0 + random(2.2, 5.8) * (useA ? 1 : -1);
    let r0 = random(45, 130) * (useA ? 1.2 : 1.0);
    let r1 = random(50, 170) * (useA ? 0.9 : 1.2);
    let cBase = useA ? color(255, 140, 85, 100) : color(110, 160, 255, 100);
    let steps = 60;
    let px = 0;
    let py = 0;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let ang = lerp(a0, a1, t);
      let rad = lerp(r0, r1, t);
      let x = cx + cos(ang) * rad;
      let y = cy + sin(ang) * rad;
      stroke(cBase);
      strokeWeight(map(sin(t * PI), 0, 1, 0.4, 2.0));
      if (s > 0) {
        line(px, py, x, y);
      }
      px = x;
      py = y;
    }
  }

  drawGlow(C.x, C.y, 190, 'rgba(255,220,180,0.85)', 'rgba(255,120,150,0)');
  for (let r = 48; r > 3; r -= 2) {
    noStroke();
    fill(255, 222, 185, map(r, 3, 48, 220, 6));
    ellipse(C.x, C.y, r * 2);
  }

  for (let i = 0; i < 700; i++) {
    let x = random(W);
    let y = random(H);
    let d = dist(x, y, C.x, C.y);
    if (d > 70) {
      let alpha = constrain(map(d, 70, 900, 190, 8), 0, 190);
      let roll = random();
      if (roll < 0.72) {
        stroke(255, 220, 185, alpha);
      } else if (roll < 0.86) {
        stroke(255, 148, 130, alpha);
      } else {
        stroke(165, 185, 255, alpha);
      }
      strokeWeight(random(0.7, 2.4));
      point(x, y);
    }
  }

  for (let i = 0; i < 200; i++) {
    let ang = random(TWO_PI);
    let rad = random(90, 620);
    let sx = C.x + cos(ang) * rad;
    let sy = C.y + sin(ang) * rad;
    let len = random(12, 62) * map(rad, 90, 620, 0.7, 1.5);
    let dirAng = ang + random(-0.38, 0.38);
    let ex = sx + cos(dirAng) * len;
    let ey = sy + sin(dirAng) * len;
    stroke(255, 205, 165, random(10, 60));
    strokeWeight(random(0.5, 1.3));
    line(sx, sy, ex, ey);
  }

  blendMode(BLEND);
  noLoop();
}

function drawGlow(x, y, r, inner, outer) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, inner);
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

