function ribPoint(t, phase, off, kind) {
  let u = t * TWO_PI + phase;
  let ampX = kind === 0 ? 405 : 495;
  let ampY = kind === 0 ? 705 : 755;
  let cx2 = kind === 0 ? cx - 35 : cx + 45;
  let cy2 = kind === 0 ? cy - 10 : cy + 20;
  let x = cx2 + sin(u) * ampX;
  let y = cy2 + sin(u * 2) * ampY;
  let n1 = noise(t * 4.1 + kind * 31.7 + off * 1.3);
  let n2 = noise(t * 3.7 + kind * 47.3 + off * 0.9 + 101.3);
  x += (n1 - 0.5) * 190;
  y += (n2 - 0.5) * 190;
  return { x: x, y: y };
}

function drawRibbon(kind, phase, cA, cB) {
  blendMode(ADD);

  for (let k = 0; k < 10; k++) {
    let off = (k - 5) * 0.28;
    let col = lerpColor(cA, cB, k / 9);
    stroke(red(col), green(col), blue(col), random(2.5, 6.5));
    strokeWeight(random(14, 30));
    noFill();
    beginShape();
    for (let t = 0; t <= 1.001; t += 0.01) {
      let p = ribPoint(t, phase, off, kind);
      vertex(p.x, p.y);
    }
    endShape();
  }

  for (let k = 0; k < 5; k++) {
    let off = (k - 2) * 0.15;
    let col = lerpColor(cA, cB, 0.2 + k * 0.2);
    stroke(red(col), green(col), blue(col), random(16, 30));
    strokeWeight(random(2, 5));
    noFill();
    beginShape();
    for (let t = 0; t <= 1.001; t += 0.005) {
      let p = ribPoint(t, phase, off, kind);
      vertex(p.x, p.y);
    }
    endShape();
  }

  noStroke();
  for (let i = 0; i < 650; i++) {
    let t = random();
    let off = random(-1.8, 1.8);
    let p = ribPoint(t, phase, off, kind);
    let jx = (noise(i * 0.7, kind * 20.1) - 0.5) * 70;
    let jy = (noise(i * 0.7 + 40, kind * 20.1) - 0.5) * 70;
    p.x += jx;
    p.y += jy;
    let size = random(1.2, 7.5);
    let alpha = random(6, 26);
    let col = lerpColor(cA, cB, random());
    fill(red(col), green(col), blue(col), alpha);
    ellipse(p.x, p.y, size, size);
  }
}

function drawHalo() {
  blendMode(ADD);
  noFill();
  for (let r = 240; r < 680; r += 42) {
    stroke(255, 170, 140, random(4, 10));
    strokeWeight(random(1, 3));
    ellipse(cx, cy, r * 2, r * 1.55);
  }
}

function drawExchange() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 320; i++) {
    let ang = random(TWO_PI);
    let r = random(30, 390);
    let x = cx + cos(ang) * r;
    let y = cy + sin(ang) * r * 0.9;
    let side = cos(ang) >= 0;
    let col = side ? color(255, 185, 110, random(10, 35)) : color(255, 110, 145, random(10, 35));
    fill(col);
    let s = random(1, 5);
    ellipse(x, y, s, s);
  }
}

function drawCentralGlow() {
  blendMode(ADD);
  noStroke();
  let g = drawingContext.createRadialGradient(cx, cy, 20, cx, cy, 480);
  g.addColorStop(0, 'rgba(255,220,180,0.16)');
  g.addColorStop(0.22, 'rgba(255,150,120,0.09)');
  g.addColorStop(0.55, 'rgba(255,90,120,0.04)');
  g.addColorStop(1, 'rgba(255,60,100,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);

  for (let r = 120; r > 0; r -= 5) {
    fill(255, 230, 195, 4);
    ellipse(cx, cy, r * 2, r * 2);
  }
}

function drawVignette() {
  drawingContext.globalCompositeOperation = 'source-over';
  let v = drawingContext.createRadialGradient(cx, cy, 320, cx, cy, 1500);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(0.65, 'rgba(0,0,0,0.05)');
  v.addColorStop(1, 'rgba(0,0,0,0.75)');
  drawingContext.fillStyle = v;
  drawingContext.fillRect(0, 0, width, height);
}

const F1 = {x: 710, y: 760};
const F2 = {x: 890, y: 1240};

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255);
  pixelDensity(1);
  noLoop();
}

function draw() {
  drawBackground();
  drawGlows();
  drawLocalRings();
  drawSharedRings();
  drawBridges();
  drawParticles();
  drawCores();
  drawVignette();
}

function drawBackground() {
  const ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = 'source-over';
  const grad = ctx.createRadialGradient(width/2, height/2, 100, width/2, height/2, 1600);
  grad.addColorStop(0, '#1b112c');
  grad.addColorStop(0.45, '#120b20');
  grad.addColorStop(0.8, '#0a0713');
  grad.addColorStop(1, '#050308');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function radialGlow(x, y, r, rgb, alphaMax) {
  const ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
  grad.addColorStop(0, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alphaMax})`);
  grad.addColorStop(0.25, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alphaMax * 0.35})`);
  grad.addColorStop(0.6, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alphaMax * 0.1})`);
  grad.addColorStop(1, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);
  ctx.fillStyle = grad;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
  ctx.restore();
}

function drawGlows() {
  radialGlow(F1.x, F1.y, 540, [255, 195, 140], 0.28);
  radialGlow(F2.x, F2.y, 540, [255, 90, 140], 0.26);
  radialGlow(width/2, height/2, 900, [255, 160, 140], 0.18);
}

function ringPoint(cx, cy, rX, rY, angle, idx, amp) {
  const x0 = cx + cos(angle) * rX;
  const y0 = cy + sin(angle) * rY;
  const n = noise(cx * 0.01 + cos(angle) * 0.6 + idx * 0.05, cy * 0.01 + sin(angle) * 0.6 - idx * 0.04);
  const x = x0 + (n - 0.5) * amp;
  const y = y0 + (n - 0.5) * amp;
  return {x, y};
}

function drawLocalRings() {
  blendMode(ADD);
  noFill();
  const gold = color(255, 212, 150);
  const rose = color(255, 92, 138);
  for (let i = 0; i < 54; i++) {
    const focus = i % 2 === 0 ? F1 : F2;
    const radius = 30 + i * 6.5 + random(-6, 6);
    const col = i % 2 === 0 ? lerpColor(gold, rose, 0.25) : lerpColor(rose, gold, 0.25);
    const alpha = random(0.02, 0.06);
    const w = random(0.8, 2.4);
    const amp = random(16, 48);
    stroke(red(col), green(col), blue(col), alpha * 255);
    strokeWeight(w);
    beginShape();
    for (let a = 0; a <= TWO_PI; a += TWO_PI / 180) {
      const p = ringPoint(focus.x, focus.y, radius, radius, a, i, amp);
      vertex(p.x, p.y);
    }
    endShape(CLOSE);
  }
  blendMode(BLEND);
}

function drawSharedRings() {
  blendMode(ADD);
  noFill();
  const gold = color(255, 212, 150);
  const rose = color(255, 92, 138);
  for (let i = 0; i < 26; i++) {
    const rX = 390 + i * 11 + random(-10, 10);
    const rY = 500 + i * 16 + random(-12, 12);
    const col = lerpColor(gold, rose, i / 26);
    const alpha = random(0.018, 0.045);
    const w = random(0.6, 1.8);
    const amp = random(24, 70);
    stroke(red(col), green(col), blue(col), alpha * 255);
    strokeWeight(w);
    beginShape();
    for (let a = 0; a <= TWO_PI; a += TWO_PI / 220) {
      const p = ringPoint(width/2, height/2, rX, rY, a, i + 200, amp);
      vertex(p.x, p.y);
    }
    endShape(CLOSE);
  }
  blendMode(BLEND);
}

function drawBridges() {
  blendMode(ADD);
  noFill();
  const gold = color(255, 212, 150);
  const rose = color(255, 92, 138);
  const angleBase = atan2(F2.y - F1.y, F2.x - F1.x) + PI / 2;
  for (let i = 0; i < 26; i++) {
    const phase = random(TWO_PI);
    const sway = random(70, 200);
    const col = lerpColor(gold, rose, random());
    const alpha = random(0.025, 0.075);
    stroke(red(col), green(col), blue(col), alpha * 255);
    strokeWeight(random(0.8, 2.2));
    beginShape();
    for (let k = 0; k <= 80; k++) {
      const t = k / 80;
      const x0 = lerp(F1.x, F2.x, t);
      const y0 = lerp(F1.y, F2.y, t);
      const offset = sin(t * PI) * sway * sin(t * PI * 2 + phase);
      const px = x0 + cos(angleBase) * offset;
      const py = y0 + sin(angleBase) * offset;
      vertex(px, py);
    }
    endShape();
  }
  blendMode(BLEND);
}

function drawParticles() {
  blendMode(ADD);
  noStroke();
  const gold = color(255, 212, 150);
  const rose = color(255, 92, 138);
  for (let i = 0; i < 250; i++) {
    let x, y;
    const which = random();
    if (which < 0.33) {
      const angle = random(TWO_PI);
      const r = random(35, 420);
      x = F1.x + cos(angle) * r;
      y = F1.y + sin(angle) * r;
    } else if (which < 0.66) {
      const angle = random(TWO_PI);
      const r = random(35, 420);
      x = F2.x + cos(angle) * r;
      y = F2.y + sin(angle) * r;
    } else {
      const angle = random(TWO_PI);
      const rX = random(400, 760);
      const rY = random(520, 1010);
      x = width / 2 + cos(angle) * rX;
      y = height / 2 + sin(angle) * rY;
    }
    x += random(-30, 30);
    y += random(-30, 30);
    const m = noise(x * 0.004, y * 0.004);
    const col = lerpColor(gold, rose, m);
    const rad = random(1.0, 4.5);
    fill(red(col), green(col), blue(col), random(80, 240));
    ellipse(x, y, rad, rad);
    fill(red(col), green(col), blue(col), random(10, 35));
    ellipse(x, y, rad * 5.5, rad * 5.5);
  }
  blendMode(BLEND);
}

function drawCores() {
  blendMode(ADD);
  noStroke();
  const warmCore = color(255, 236, 205);
  const roseCore = color(255, 130, 150);
  fill(red(warmCore), green(warmCore), blue(warmCore), 230);
  ellipse(F1.x, F1.y, 46, 46);
  fill(red(roseCore), green(roseCore), blue(roseCore), 220);
  ellipse(F2.x, F2.y, 40, 40);
  fill(255, 170, 140, 60);
  ellipse(F1.x, F1.y, 130, 130);
  fill(255, 90, 140, 50);
  ellipse(F2.x, F2.y, 120, 120);
  blendMode(BLEND);
}

function drawVignette() {
  const ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = 'source-over';
  const grad = ctx.createRadialGradient(width/2, height/2, 450, width/2, height/2, 1500);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(0.7, 'rgba(0,0,0,0.08)');
  grad.addColorStop(1, 'rgba(0,0,0,0.5)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(8, 6, 18);
  drawBackgroundGradient();

  blendMode(ADD);

  let c1 = {x: 650, y: 880};
  let c2 = {x: 950, y: 1120};

  radialGlow(800, 1000, 900, color(80, 50, 140, 32));

  drawThreads(c1, c2, 55, 190);

  drawBlob(c1.x, c1.y, 330, color(255, 190, 130), color(255, 70, 110), 1700, 0.0);
  drawBlob(c2.x, c2.y, 300, color(190, 130, 255), color(225, 50, 155), 1700, 7.5);

  drawThreads(c1, c2, 22, 120);

  radialGlow(c1.x, c1.y, 260, color(255, 220, 190, 120));
  radialGlow(c2.x, c2.y, 240, color(210, 150, 255, 110));
  radialGlow((c1.x + c2.x) / 2, (c1.y + c2.y) / 2, 230, color(255, 160, 220, 45));

  noStroke();
  fill(255, 235, 210, 210);
  ellipse(c1.x, c1.y, 32, 32);

  fill(235, 210, 255, 210);
  ellipse(c2.x, c2.y, 28, 28);

  drawEmbers(1200);

  blendMode(BLEND);
}

function drawBackgroundGradient() {
  noStroke();
  for (let y = 0; y < height; y += 8) {
    let t = y / height;
    let r = lerp(8, 24, t);
    let g = lerp(6, 15, t);
    let b = lerp(18, 48, t);
    fill(r, g, b);
    rect(0, y, width, 8);
  }
}

function radialGlow(x, y, radius, col) {
  let ctx = drawingContext;
  let r = red(col);
  let g = green(col);
  let b = blue(col);
  let a = alpha(col) / 255;
  let grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
  grad.addColorStop(0, `rgba(${r},${g},${b},${a})`);
  grad.addColorStop(1, `rgba(${r},${g},${b},0)`);
  ctx.save();
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawThreads(c1, c2, count, spread) {
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < count; i++) {
    let midX = (c1.x + c2.x) / 2 + random(-spread, spread);
    let midY = (c1.y + c2.y) / 2 + random(-spread * 1.2, spread * 1.2);
    let col = color(
      255,
      170 + random(-25, 25),
      190 + random(-30, 30),
      4 + random(0, 10)
    );
    stroke(col);
    strokeWeight(random(0.4, 1.6));
    beginShape();
    let steps = 70;
    for (let j = 0; j <= steps; j++) {
      let t = j / steps;
      let x = bezierPoint(c1.x, midX, midX, c2.x, t);
      let y = bezierPoint(c1.y, midY, midY, c2.y, t);
      let wave = sin(t * Math.PI);
      let n = noise(t * 4 + i * 0.3, i * 0.07);
      x += (n - 0.5) * 46 * wave;
      y += (n - 0.5) * 46 * wave;
      vertex(x, y);
    }
    endShape();
  }
  noStroke();
}

function drawBlob(cx, cy, maxR, coreCol, edgeCol, n, offset) {
  noStroke();
  let cr = red(coreCol), cg = green(coreCol), cb = blue(coreCol);
  let er = red(edgeCol), eg = green(edgeCol), eb = blue(edgeCol);

  for (let i = 0; i < n; i++) {
    let angle = random(Math.PI * 2);
    let rr = Math.pow(random(1), 1.65) * maxR;
    let nx = Math.cos(angle) * 1.4;
    let ny = Math.sin(angle) * 1.4;
    let wob = (noise(nx + offset, ny, rr * 0.004) - 0.5) * 150;
    let x = cx + Math.cos(angle) * (rr + wob);
    let y = cy + Math.sin(angle) * (rr + wob) * 0.88;

    if (x < -60 || x > width + 60 || y < -60 || y > height + 60) continue;

    let t = constrain(rr / maxR, 0, 1);
    let r = lerp(cr, er, t);
    let g = lerp(cg, eg, t);
    let b = lerp(cb, eb, t);
    let a = 7 + (1 - t) * 22;
    let size = 0.6 + (1 - t) * 3.2;
    fill(r, g, b, a);
    ellipse(x, y, size, size);
  }
}

function drawEmbers(n) {
  noStroke();
  let centers = [
    {x: 650, y: 880},
    {x: 950, y: 1120},
    {x: 800, y: 1000}
  ];

  for (let i = 0; i < n; i++) {
    let c = random(centers);
    let angle = random(Math.PI * 2);
    let radius = random(50, 900);
    let x = c.x + Math.cos(angle) * radius;
    let y = c.y + Math.sin(angle) * radius;

    if (x < 0 || x > width || y < 0 || y > height) continue;

    let warmRoll = random(1);
    let r = warmRoll < 0.6 ? 255 : 210;
    let g = warmRoll < 0.6 ? random(190, 230) : random(130, 180);
    let b = warmRoll < 0.6 ? random(170, 210) : random(220, 255);
    let a = random(2, 10);
    let size = random(0.5, 2.4);
    fill(r, g, b, a);
    ellipse(x, y, size, size);
  }
}

// 之间 —— 爱是一束被两个独立者点亮的空隙
// p5.js 1.11 · 1600×2000 · 静态图像

let W = 1600, H = 2000;

const GOLD = [235, 183, 96], IVORY = [255, 240, 208], ROSE = [226, 112, 110],
      EMBER = [233, 122, 62], TEAL = [82, 150, 142], TEALHI = [152, 206, 190],
      MAD = [186, 68, 54], MADHI = [238, 142, 92];

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  paint();
}

function col(c, a) {
  return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a + ')';
}
function mix3(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}
function quad1(a, c, b, t) {
  let u = 1 - t;
  return u * u * a + 2 * u * t * c + t * t * b;
}

function paint() {
  background(14, 10, 20);
  baseWash();
  stars();
  ripples();
  crown();
  spineGlow();
  forms();
  blendMode(ADD);
  weave();
  heroes();
  fray();
  melt();
  embers();
  pool();
  blendMode(BLEND);
  embrace();
  vignette();
  grain();
}

// ---------- 背景：黑夜不是空的 ----------
function baseWash() {
  let c = drawingContext;
  let g = c.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.00, '#0e0a16');
  g.addColorStop(0.38, '#191021');
  g.addColorStop(0.68, '#221019');
  g.addColorStop(1.00, '#0b070f');
  c.fillStyle = g; c.fillRect(0, 0, W, H);

  radialField(800, 1070, 80, 980, [[0, 'rgba(128,58,34,0.50)'], [0.55, 'rgba(66,26,32,0.25)'], [1, 'rgba(0,0,0,0)']]);
  radialField(330, 420, 40, 760, [[0, 'rgba(24,52,58,0.35)'], [1, 'rgba(0,0,0,0)']]);
  radialField(1330, 1520, 40, 720, [[0, 'rgba(58,20,28,0.40)'], [1, 'rgba(0,0,0,0)']]);
  radialField(1280, 300, 30, 620, [[0, 'rgba(40,24,56,0.35)'], [1, 'rgba(0,0,0,0)']]);

  noStroke();
  for (let i = 0; i < 150; i++) {
    let x = noise(i * 0.71, 3.3) * W, y = noise(7.7, i * 0.63) * H;
    let r = 90 + noise(i * 1.3) * 260;
    let cs = [[34, 16, 40], [16, 34, 38], [46, 18, 26], [22, 14, 34]];
    let cc = cs[Math.floor(noise(i * 2.2) * cs.length)];
    fill(col(cc, 0.03 + noise(i) * 0.05));
    ellipse(x, y, r * 2, r * (1.4 + noise(i * 3.1) * 0.9));
  }
}
function radialField(x, y, r0, r1, stops) {
  let c = drawingContext, g = c.createRadialGradient(x, y, r0, x, y, r1);
  for (let s of stops) g.addColorStop(s[0], s[1]);
  c.fillStyle = g; c.fillRect(0, 0, W, H);
}
function stars() {
  noStroke();
  for (let i = 0; i < 80; i++) {
    let x = random(W), y = random(H * 0.42);
    let s = random(1, 2.6);
    fill(col(IVORY, random(0.04, 0.13)));
    ellipse(x, y, s, s);
  }
}

// ---------- 从中心向外荡开的涟漪 ----------
function ripples() {
  noFill();
  let cx = 800, cy = 1060;
  for (let k = 0; k < 24; k++) {
    let R = 300 + k * 46;
    let base = (k % 3 === 2) ? TEAL : GOLD;
    let alph = 0.10 * (1 - k / 26) + 0.015;
    for (let p = 0; p < 2; p++) {
      stroke(col(base, alph * (p ? 0.6 : 1)));
      strokeWeight((k < 6 ? 1.6 : 1.1) * (p ? 1.6 : 1));
      beginShape();
      let on = false;
      for (let a = 0; a <= TAU + 0.05; a += 0.035) {
        let gate = noise(k * 0.9 + p * 3 + Math.cos(a) * 1.2, Math.sin(a) * 1.2 + k * 0.4);
        if (gate > 0.36) {
          let rr = R + (noise(Math.cos(a) + k * 0.35, Math.sin(a) + k * 0.35) - 0.5) * 34 + random(-2, 2);
          vertex(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr * 1.06);
          on = true;
        } else if (on) { endShape(); beginShape(); on = false; }
      }
      endShape();
    }
  }
}
function crown() {
  noFill();
  for (let j = 0; j < 3; j++) {
    let R = 600 + j * 80;
    stroke(col(GOLD, 0.05 - j * 0.012));
    strokeWeight(1.4 + j * 0.4);
    beginShape();
    for (let a = PI * 1.08; a <= PI * 1.92; a += 0.03) {
      let rr = R + (noise(Math.cos(a) * 1.4 + j, Math.sin(a) * 1.4) - 0.5) * 40;
      vertex(800 + Math.cos(a) * rr, 1030 + Math.sin(a) * rr * 0.98);
    }
    endShape();
  }
}

// ---------- 空隙里的光柱（在两者背后亮起） ----------
function spineGlow() {
  blendMode(ADD);
  noStroke();
  for (let y = 880; y <= 1500; y += 26) {
    let t = (y - 880) / 620;
    let e = Math.pow(Math.sin(PI * t), 1.3);
    let wob = (noise(y * 0.01) - 0.5) * 26;
    fill(col(GOLD, 0.045 + 0.085 * e));
    ellipse(800 + wob, y, (26 + 92 * e) * 2, 44);
    if (e > 0.35) {
      fill(col(IVORY, 0.05 * e));
      ellipse(800 + wob, y, (8 + 30 * e) * 2, 26);
    }
  }
  blendMode(BLEND);
}

// ---------- 两个完整者：各自成形，向彼此倾斜 ----------
function forms() {
  drawForm(432, 1160, 330, 0.96, 1.16, 0.10, 1,
    { deep: [13, 32, 37], mid: [36, 80, 84], hi: [118, 178, 166], rim: [255, 236, 198], stain: MAD, seed: [4.2, 9.1] });
  drawForm(1168, 1178, 344, 0.97, 1.19, -0.10, -1,
    { deep: [45, 14, 18], mid: [120, 44, 38], hi: [224, 128, 84], rim: [255, 226, 170], stain: TEAL, seed: [8.8, 2.6] });
}
function blobR(th, R, so, flat, dir) {
  let n = noise(so[0] + Math.cos(th) * 0.85, so[1] + Math.sin(th) * 0.85);
  let r = R * (0.78 + 0.44 * n);
  let f = Math.max(0, dir * Math.cos(th));
  return r * (1 - flat * Math.pow(f, 2.4));
}
function drawForm(cx, cy, R, sx, sy, tilt, dir, P) {
  push();
  translate(cx, cy);
  rotate(tilt);
  // 体量
  noStroke();
  for (let i = 9; i >= 1; i--) {
    let t = i / 9;
    fill(col(mix3(P.deep, P.mid, (1 - t) * 0.85), 0.34));
    beginShape();
    for (let a = 0; a < TAU; a += 0.09) {
      let rr = blobR(a, R, P.seed, 0.16, dir) * lerp(0.55, 1.03, t) + (noise(a * 2 + i, i * 3.7) - 0.5) * 22;
      vertex(rr * Math.cos(a) * sx, rr * Math.sin(a) * sy);
    }
    endShape(CLOSE);
  }
  // 炭笔般的重复轮廓
  noFill();
  for (let s = 0; s < 46; s++) {
    stroke(col(mix3(P.mid, P.hi, noise(s * 1.7) * 0.8), 0.10 + noise(s * 2.3) * 0.16));
    strokeWeight(0.8 + noise(s * 3.1) * 1.7);
    beginShape();
    for (let a = 0; a < TAU; a += 0.085) {
      let rr = blobR(a, R, P.seed, 0.16, dir) * (0.965 + noise(s * 1.1, a * 1.3) * 0.075);
      vertex(rr * Math.cos(a) * sx, rr * Math.sin(a) * sy);
    }
    endShape(CLOSE);
  }
  // 边缘内的颗粒
  noStroke();
  for (let i = 0; i < 800; i++) {
    let a = random(TAU), f = 0.7 + random(0.34);
    let rr = blobR(a, R, P.seed, 0.16, dir) * f;
    fill(col(mix3(P.mid, P.hi, random()), random(0.04, 0.14)));
    let sz = random(1, 3);
    ellipse(rr * Math.cos(a) * sx, rr * Math.sin(a) * sy, sz, sz);
  }
  // 面向空隙的一侧：被对方的光照亮
  let a0 = dir > 0 ? -1.02 : PI - 1.02, a1 = dir > 0 ? 1.02 : PI + 1.02;
  for (let s = 0; s < 30; s++) {
    let st = lerp(a0, a1, random()), en = min(a1, st + random(0.18, 0.6));
    strokeWeight(random(1, 2.6));
    stroke(col(P.rim, random(0.16, 0.4)));
    beginShape();
    for (let a = st; a <= en; a += 0.05) {
      let rr = blobR(a, R, P.seed, 0.16, dir) * 1.004;
      vertex(rr * Math.cos(a) * sx, rr * Math.sin(a) * sy);
    }
    endShape();
  }
  blendMode(ADD);
  for (let s = 0; s < 12; s++) {
    let st = lerp(a0, a1, random()), en = min(a1, st + random(0.3, 0.8));
    strokeWeight(random(3, 6));
    stroke(col(GOLD, random(0.03, 0.07)));
    beginShape();
    for (let a = st; a <= en; a += 0.06) {
      let rr = blobR(a, R, P.seed, 0.16, dir) * 1.012;
      vertex(rr * Math.cos(a) * sx, rr * Math.sin(a) * sy);
    }
    endShape();
  }
  blendMode(BLEND);
  // 被对方的颜色染过
  for (let s = 0; s < 14; s++) {
    let st = lerp(a0, a1, random()), en = min(a1, st + random(0.15, 0.4));
    strokeWeight(random(1, 2));
    stroke(col(P.stain, random(0.06, 0.16)));
    beginShape();
    for (let a = st; a <= en; a += 0.06) {
      let rr = blobR(a, R, P.seed, 0.16, dir) * (0.93 + random(0.03));
      vertex(rr * Math.cos(a) * sx, rr * Math.sin(a) * sy);
    }
    endShape();
  }
  // 向下扎根
  for (let i = 0; i < 16; i++) {
    let a = lerp(PI * 0.3, PI * 0.7, random()) + (dir > 0 ? -0.3 : 0.3);
    let rr = blobR(a, R, P.seed, 0.16, dir);
    let x0 = rr * Math.cos(a) * sx, y0 = rr * Math.sin(a) * sy;
    strokeWeight(random(1, 2.4));
    stroke(col(mix3(P.deep, P.mid, 0.3), random(0.15, 0.4)));
    line(x0, y0, x0 + random(-8, 8), y0 + random(18, 70));
  }
  pop();
}

// ---------- 空隙的坐标 ----------
function edgeL(y) { return 700 + (1150 - y) * 0.10; }
function edgeR(y) { return 890 - (1150 - y) * 0.10; }

// ---------- 千万根细线：底层的织 ----------
function weave() {
  noFill();
  for (let i = 0; i < 1900; i++) {
    let y = 1120 + ((random() + random() + random()) / 3 - 0.5) * 2 * 560;
    y = constrain(y, 860, 1500);
    let x0 = edgeL(y) + random(-26, 10), x1 = edgeR(y) + random(-10, 26);
    let bend = (random() - 0.5) * (30 + (y > 1120 ? 40 : 80));
    let cxp = (x0 + x1) / 2 + random(-30, 30), cyp = y + bend;
    let sel = random(), cc, al;
    if (sel < 0.44) { cc = GOLD; al = random(0.035, 0.10); }
    else if (sel < 0.60) { cc = IVORY; al = random(0.03, 0.08); }
    else if (sel < 0.73) { cc = ROSE; al = random(0.03, 0.08); }
    else if (sel < 0.87) { cc = TEAL; al = random(0.03, 0.07); }
    else { cc = EMBER; al = random(0.03, 0.09); }
    stroke(col(cc, al));
    strokeWeight(random(0.5, 1.5));
    beginShape();
    for (let s = 0; s <= 16; s++) {
      let t = s / 16;
      let x = quad1(x0, cxp, x1, t) + (noise(i * 0.13, t * 2.2) - 0.5) * 16;
      let yy = quad1(y, cyp, y, t) + (noise(t * 2.2, i * 0.17) - 0.5) * 12;
      vertex(x, yy);
    }
    endShape();
  }
  // 两端仍带着各自的颜色
  for (let i = 0; i < 380; i++) {
    let y = constrain(1120 + ((random() + random()) / 2 - 0.5) * 2 * 540, 870, 1490);
    let x0 = edgeL(y) + random(-24, 6), xe = lerp(x0, 800, random(0.55, 0.95));
    stroke(col(TEAL, random(0.05, 0.12))); strokeWeight(random(0.6, 1.4));
    beginShape();
    for (let s = 0; s <= 8; s++) {
      let t = s / 8;
      vertex(lerp(x0, xe, t) + (noise(i, t) - 0.5) * 10, y + (noise(t, i) - 0.5) * 14 + sin(t * PI) * random(-14, 14));
    }
    endShape();
  }
  for (let i = 0; i < 380; i++) {
    let y = constrain(1120 + ((random() + random()) / 2 - 0.5) * 2 * 540, 870, 1490);
    let x0 = edgeR(y) + random(-6, 24), xe = lerp(x0, 800, random(0.55, 0.95));
    stroke(col(MAD, random(0.05, 0.12))); strokeWeight(random(0.6, 1.4));
    beginShape();
    for (let s = 0; s <= 8; s++) {
      let t = s / 8;
      vertex(lerp(x0, xe, t) + (noise(i + 40, t) - 0.5) * 10, y + (noise(t, i + 40) - 0.5) * 14 + sin(t * PI) * random(-14, 14));
    }
    endShape();
  }
}

// ---------- 少数被命名的线：从我的颜色，经过金色，到你的颜色 ----------
function heroes() {
  noFill();
  for (let i = 0; i < 240; i++) {
    let y = constrain(1120 + ((random() + random()) / 2 - 0.5) * 2 * 520, 880, 1480);
    let x0 = edgeL(y) + random(-16, 4), x1 = edgeR(y) + random(-4, 16);
    let bend = random([-1, 1]) * random(24, 150);
    let cxp = (x0 + x1) / 2 + random(-24, 24), cyp = y + bend;
    let steps = 26, pts = [];
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      pts.push([quad1(x0, cxp, x1, t) + (noise(i * 0.3, t * 3) - 0.5) * 10,
                quad1(y, cyp, y, t) + (noise(t * 3, i * 0.31) - 0.5) * 9]);
    }
    let w = random(0.9, 2.4), al = random(0.14, 0.34);
    let cA = mix3(TEAL, TEALHI, random() * 0.6), cB = mix3(MAD, MADHI, random() * 0.6), cM = mix3(GOLD, IVORY, random() * 0.5);
    for (let s = 0; s < steps; s++) {
      let t = (s + 0.5) / steps;
      stroke(col(t < 0.5 ? mix3(cA, cM, t * 2) : mix3(cM, cB, (t - 0.5) * 2), al));
      strokeWeight(w);
      line(pts[s][0], pts[s][1], pts[s + 1][0], pts[s + 1][1]);
    }
    noStroke();
    fill(col(IVORY, al * 0.9));
    ellipse(pts[0][0], pts[0][1], w * 2.6, w * 2.6);
    ellipse(pts[steps][0], pts[steps][1], w * 2.6, w * 2.6);
  }
}

// ---------- 也有些线没有抵达：断裂与重试 ----------
function fray() {
  for (let i = 0; i < 90; i++) {
    let left = random() < 0.5;
    let y = constrain(1120 + ((random() + random()) / 2 - 0.5) * 2 * 540, 880, 1480);
    let x = left ? edgeL(y) + random(-20, 0) : edgeR(y) + random(0, 20);
    let dirx = left ? 1 : -1;
    let len = random(40, 130), segs = 6;
    let dx = dirx * len / segs, dy = random(-22, 22) / segs;
    let cc = random() < 0.5 ? GOLD : (left ? TEALHI : MADHI);
    let px = x, py = y;
    for (let s = 0; s < segs; s++) {
      stroke(col(cc, 0.26 * (1 - s / segs) + 0.02));
      strokeWeight(random(0.7, 1.6));
      let nx = px + dx + (noise(i, s) - 0.5) * 8, ny = py + dy + (noise(s, i) - 0.5) * 8;
      line(px, py, nx, ny);
      px = nx; py = ny;
    }
    noStroke();
    fill(col(cc, 0.25));
    for (let d = 0; d < 3; d++) {
      px += dx * 0.8; py += random(-6, 6);
      ellipse(px, py, random(1, 2.4), random(1, 2.4));
    }
  }
}

function melt() {
  noStroke();
  fill(col(GOLD, 0.05)); ellipse(800, 1100, 520, 1150);
  fill(col(IVORY, 0.05)); ellipse(800, 1020, 300, 640);
  fill(col(ROSE, 0.03)); ellipse(800, 1260, 420, 520);
}

// ---------- 这光向上蒸腾 ----------
function embers() {
  noStroke();
  for (let i = 0; i < 330; i++) {
    let t = random();
    let y = lerp(1400, 150, Math.pow(t, 0.92));
    let spread = lerp(26, 240, t);
    let x = 800 + (noise(i * 0.71) - 0.5) * 2 * spread + Math.sin(y * 0.01 + i) * 10;
    let cc = t < 0.55 ? mix3(GOLD, ROSE, t / 0.55) : mix3(ROSE, [150, 196, 205], (t - 0.55) / 0.45);
    let a = lerp(0.5, 0.06, t), sz = lerp(4.6, 1.0, t);
    fill(col(cc, a * 0.22)); ellipse(x, y, sz * 4.4, sz * 4.4);
    fill(col(cc, a)); ellipse(x, y, sz, sz);
    if (t < 0.18 && random() < 0.4) {
      stroke(col(IVORY, a * 0.5)); strokeWeight(0.8);
      let L = sz * 3.4;
      line(x - L, y, x + L, y); line(x, y - L, x, y + L);
      noStroke();
    }
  }
  for (let i = 0; i < 46; i++) {
    let y = random(300, 1300), x = 800 + random([-1, 1]) * random(160, 540);
    let sz = random(1, 2.8);
    fill(col(GOLD, random(0.03, 0.10))); ellipse(x, y, sz * 3, sz * 3);
    fill(col(IVORY, random(0.05, 0.14))); ellipse(x, y, sz, sz);
  }
}

// ---------- 也向下扎根 ----------
function pool() {
  noStroke();
  fill(col(GOLD, 0.10)); ellipse(800, 1532, 340, 54);
  fill(col(GOLD, 0.16)); ellipse(800, 1532, 200, 32);
  fill(col(IVORY, 0.22)); ellipse(800, 1530, 96, 16);
  for (let i = 0; i < 7; i++) {
    let x = 800 + (i - 3) * random(20, 34), y = 1590 + random(0, 60);
    fill(col(GOLD, random(0.2, 0.4))); ellipse(x, y, 3, 3);
  }
}

// ---------- 环抱：围而不闭，顶部留给光 ----------
function embrace() {
  noFill();
  let cx = 800, cy = 1140;
  for (let j = 0; j < 3; j++) {
    let rx = 560 + j * 46, ry = 640 + j * 52, rot = (noise(j * 7) - 0.5) * 0.12;
    for (let p = 0; p < 5; p++) {
      stroke(col(mix3(GOLD, [120, 70, 40], noise(j, p) * 0.7), 0.10 + noise(j * 3, p) * 0.12));
      strokeWeight(1.1 + noise(j, p, 3) * 1.8);
      beginShape();
      for (let a = PI * 0.30; a <= PI * 1.70; a += 0.03) {
        let rr = 1 + (noise(Math.cos(a) * 1.1 + j + p * 0.4, Math.sin(a) * 1.1) - 0.5) * 0.05;
        let ca = Math.cos(a), sa = Math.sin(a);
        vertex(cx + (ca * rx * rr) * Math.cos(rot) - (sa * ry * rr) * Math.sin(rot),
               cy + (ca * rx * rr) * Math.sin(rot) + (sa * ry * rr) * Math.cos(rot));
      }
      endShape();
    }
  }
}

function vignette() {
  let c = drawingContext;
  let g = c.createRadialGradient(800, 1040, 620, 800, 1040, 1450);
  g.addColorStop(0, 'rgba(7,4,11,0)');
  g.addColorStop(1, 'rgba(7,4,11,0.55)');
  c.fillStyle = g; c.fillRect(0, 0, W, H);
  let t = c.createLinearGradient(0, 0, 0, 300);
  t.addColorStop(0, 'rgba(7,5,12,0.5)'); t.addColorStop(1, 'rgba(7,5,12,0)');
  c.fillStyle = t; c.fillRect(0, 0, W, 300);
  let b = c.createLinearGradient(0, H - 360, 0, H);
  b.addColorStop(0, 'rgba(6,4,9,0)'); b.addColorStop(1, 'rgba(6,4,9,0.6)');
  c.fillStyle = b; c.fillRect(0, H - 360, W, 360);
}

function grain() {
  noStroke();
  for (let i = 0; i < 13000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.58) fill(0, 0, 0, random(6, 22));
    else fill(255, 240, 220, random(5, 16));
    let s = random() < 0.85 ? 1 : 2;
    rect(x, y, s, s);
  }
  for (let i = 0; i < 120; i++) {
    let x = random(W), y = random(H), l = random(14, 60), a = random(TAU);
    strokeWeight(random(0.4, 0.9));
    stroke(255, 235, 210, random(3, 9));
    line(x, y, x + Math.cos(a) * l, y + Math.sin(a) * l);
  }
}

let W = 1600, H = 2000;

const GOLD = { halo:[255,168,80],  mid:[255,196,118], core:[255,231,185], inner:[255,249,236] };
const ROSE = { halo:[255,116,104], mid:[255,150,128], core:[255,206,182], inner:[255,242,233] };

const BG = [
  [0.00, 14, 19, 44],
  [0.30, 21, 28, 60],
  [0.55, 31, 31, 66],
  [0.78, 45, 35, 63],
  [1.00, 27, 23, 46]
];

function easeIO(t){ return t < 0.5 ? 2*t*t : 1 - pow(-2*t+2, 2)/2; }
function easeOut(t){ return 1 - pow(1-t, 3); }

function setup(){
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  background(10, 14, 32);

  paintBase();
  brushField();
  dust();
  originAuras();
  beams();

  // 远处还有别的线，也织着各自的光
  ghostBraid(252, 430,  0.34, -0.32, 14, 11);
  ghostBraid(1348, 1235, 0.40,  0.24, 12, 10);
  ghostBraid(300, 1585, 0.30, -0.14, 11, 9);

  bloomHalo();
  rings();

  const A = buildThread(-1); // 金
  const B = buildThread(1);  // 玫
  drawThread(A, GOLD);
  drawThread(B, ROSE);
  fibers(A, GOLD);
  fibers(B, ROSE);
  beads(A, GOLD);
  beads(B, ROSE);

  sparks();
  bloomCore();
  wisps();
  embers();

  vignette();
  grain();
}

/* ---------- 背景 ---------- */

function bgAt(y){
  const t = y / H;
  for(let i = 1; i < BG.length; i++){
    if(t <= BG[i][0]){
      const a = BG[i-1], b = BG[i];
      const u = (t - a[0]) / (b[0] - a[0]);
      return [ lerp(a[1],b[1],u), lerp(a[2],b[2],u), lerp(a[3],b[3],u) ];
    }
  }
  return [27,23,46];
}

function paintBase(){
  noStroke();
  for(let y = 0; y < H; y++){
    const c = bgAt(y);
    const n = (noise(y * 0.01) - 0.5) * 8;
    fill(c[0]+n, c[1]+n, c[2]+n);
    rect(0, y, W, 1.5);
  }
  glow(300, 300, 700,  [[0,'rgba(64,58,120,0.20)'],[1,'rgba(64,58,120,0)']], SCREEN);
  glow(1400, 700, 760, [[0,'rgba(40,66,110,0.18)'],[1,'rgba(40,66,110,0)']], SCREEN);
  glow(820, 1650, 900, [[0,'rgba(120,66,60,0.16)'],[1,'rgba(120,66,60,0)']], SCREEN);
}

function brushField(){
  noStroke();
  for(let i = 0; i < 5200; i++){
    const x = random(W), y = random(H);
    const ang = noise(x*0.0015, y*0.0015) * TWO_PI * 1.7;
    const L = random(24, 90), Wd = random(7, 24);
    const c = bgAt(y);
    let r = c[0] + random(-16,16);
    let g = c[1] + random(-16,16);
    let b = c[2] + random(-14,18);
    if(random() < 0.08){ r += 26; b += 18; }
    if(random() < 0.06){ g += 12; b += 20; }
    push();
    translate(x, y);
    rotate(ang);
    fill(r, g, b, random(6, 15));
    rect(-L/2, -Wd/2, L, Wd, Wd*0.5);
    pop();
  }
}

function dust(){
  blendMode(ADD);
  noStroke();
  for(let i = 0; i < 420; i++){
    const x = random(W), y = random(H * 0.92);
    if(dist(x, y, 845, 1030) < 320) continue;
    fill(150, 170, 225, random(10, 34));
    circle(x, y, random(0.8, 2.4));
  }
  blendMode(BLEND);
}

function originAuras(){
  glow(185, -30, 430,  [[0,'rgba(255,190,110,0.16)'],[1,'rgba(255,190,110,0)']]);
  glow(1418, -30, 430, [[0,'rgba(255,140,130,0.16)'],[1,'rgba(255,140,130,0)']]);
}

function beams(){
  beam(-50, 120, 0.79, 1350, 300, 0.045);
  beam(1650, 240, 2.37, 1400, 340, 0.035);
}

function beam(x, y, ang, len, wid, alpha){
  blendMode(ADD);
  const c = drawingContext;
  c.save();
  c.translate(x, y);
  c.rotate(ang);
  const g = c.createLinearGradient(0, 0, len, 0);
  g.addColorStop(0,    'rgba(255,210,150,0)');
  g.addColorStop(0.45, 'rgba(255,210,150,' + alpha + ')');
  g.addColorStop(1,    'rgba(255,210,150,0)');
  c.fillStyle = g;
  c.fillRect(0, -wid/2, len, wid);
  c.restore();
  blendMode(BLEND);
}

function glow(cx, cy, r, stops, mode){
  blendMode(mode || ADD);
  const c = drawingContext;
  const g = c.createRadialGradient(cx, cy, 0, cx, cy, r);
  for(const st of stops) g.addColorStop(st[0], st[1]);
  c.fillStyle = g;
  c.fillRect(cx - r, cy - r, r*2, r*2);
  blendMode(BLEND);
}

/* ---------- 远处的伴侣 ---------- */

function ghostBraid(cx, cy, sc, rot, aG, aR){
  push();
  translate(cx, cy);
  rotate(rot);
  scale(sc);
  blendMode(ADD);
  const TOT = TWO_PI * 2.2;
  let px = null, py = null, qx = null, qy = null;
  for(let i = 0; i <= 260; i++){
    const s = i / 260;
    const th = s * TOT;
    const amp = 95 * pow(sin(PI * s), 0.8) + 3;
    const y = lerp(-280, 280, s);
    const x = sin(th) * amp;
    const x2 = sin(th + PI) * amp;
    strokeWeight(4);
    if(px !== null){
      stroke(255, 205, 150, aG); line(px, py, x, y);
      stroke(255, 160, 150, aR); line(qx, qy, x2, y);
    }
    px = x; py = y; qx = x2; qy = y;
  }
  blendMode(BLEND);
  pop();
}

/* ---------- 两条线 ---------- */

function crPoint(cps, t){
  const n = cps.length - 1;
  const ft = constrain(t, 0, 1) * n;
  let i = Math.floor(ft);
  if(i >= n) i = n - 1;
  const lt = ft - i;
  const p0 = cps[Math.max(i-1,0)], p1 = cps[i], p2 = cps[i+1], p3 = cps[Math.min(i+2,n)];
  const t2 = lt*lt, t3 = t2*lt;
  const x = 0.5 * ((2*p1[0]) + (-p0[0]+p2[0])*lt + (2*p0[0]-5*p1[0]+4*p2[0]-p3[0])*t2 + (-p0[0]+3*p1[0]-3*p2[0]+p3[0])*t3);
  const y = 0.5 * ((2*p1[1]) + (-p0[1]+p2[1])*lt + (2*p0[1]-5*p1[1]+4*p2[1]-p3[1])*t2 + (-p0[1]+3*p1[1]-3*p2[1]+p3[1])*t3);
  return { x, y };
}

function buildThread(side){
  const pts = [];
  const cps = side < 0
    ? [[168,-90],[252,180],[348,408],[556,572],[742,634],[798,700]]
    : [[1432,-90],[1350,166],[1186,370],[986,560],[852,640],[802,700]];

  // 第一段：各自在暗处流浪
  const n1 = 560;
  for(let i = 0; i <= n1; i++){
    const t = i / n1;
    const p = crPoint(cps, t);
    const p2 = crPoint(cps, min(t + 0.012, 1));
    let dx = p2.x - p.x, dy = p2.y - p.y;
    const d = Math.hypot(dx, dy) || 1; dx /= d; dy /= d;
    const amp = lerp(62, 3, pow(t, 0.85));
    const off = (noise(side*37.3 + t*3.2, side*11.7 + 5) - 0.5) * 2 * amp;
    const m = lerp(0.45, 0.95, t) * (0.9 + 0.2 * noise(t*6 + side*3));
    pts.push({ x: p.x - dy*off, y: p.y + dx*off, m });
  }

  // 第二段：交缠，光在之间发生
  const n2 = 1150, TOT = TWO_PI * 2.7;
  for(let i = 1; i <= n2; i++){
    const s = i / n2;
    const th = s * TOT + (side > 0 ? PI : 0);
    const ampS = 185 * pow(sin(PI * s), 0.8) + 6;
    const x = 800 + 45 * sin(PI * s) + sin(th) * ampS + (noise(s*8.3, side*4.4 + 9) - 0.5) * 5;
    const y = 700 + 660 * easeIO(s) + (noise(s*6.1 + 20, side*2.7) - 0.5) * 5;
    const m = 0.95 + 0.55 * pow(sin(PI * s), 1.2);
    pts.push({ x, y, m });
  }

  // 第三段：并肩下行，仍不合并
  const n3 = 620;
  for(let i = 1; i <= n3; i++){
    const s2 = i / n3;
    const y = 1360 + 700 * pow(s2, 1.12);
    const breathe = 0.92 + 0.08 * sin(s2 * 6.5);
    const sep = lerp(12, 46, easeOut(min(1, s2 * 1.9))) * breathe;
    const cx = 800 + 26 * sin(s2 * PI * 1.15) + (noise(s2*4.2, side*6.3 + 31) - 0.5) * 12;
    const x = cx + side * sep / 2 + (noise(s2*9.8, side*17.9 + 3) - 0.5) * 6;
    const m = max(0, 1.12 * (1 - pow(s2, 1.5)));
    pts.push({ x, y, m });
  }
  return pts;
}

function drawThread(pts, pal){
  blendMode(ADD);
  pass(pts, 34,  pal.halo,  7);
  pass(pts, 16,  pal.halo,  13);
  pass(pts, 7,   pal.mid,   42);
  pass(pts, 3.4, pal.core,  130);
  pass(pts, 1.6, pal.inner, 210);
  blendMode(BLEND);
}

function pass(pts, w, col, baseA){
  strokeWeight(w);
  for(let i = 1; i < pts.length; i++){
    const m = pts[i].m * pts[i-1].m;
    if(m <= 0.01) continue;
    stroke(col[0], col[1], col[2], min(baseA * m, 255));
    line(pts[i-1].x, pts[i-1].y, pts[i].x, pts[i].y);
  }
}

function fibers(pts, pal){
  blendMode(ADD);
  for(let i = 10; i < pts.length - 12; i += 7){
    const p = pts[i];
    if(p.m < 0.15 || random() > 0.5 * p.m + 0.15) continue;
    const q = pts[i + 3];
    let ang = atan2(q.y - p.y, q.x - p.x) + HALF_PI * (random() < 0.5 ? 1 : -1);
    ang += random(-0.5, 0.5);
    const L = random(6, 20);
    stroke(pal.mid[0], pal.mid[1], pal.mid[2], random(14, 40) * p.m);
    strokeWeight(random(0.6, 1.4));
    line(p.x, p.y, p.x + cos(ang)*L, p.y + sin(ang)*L);
  }
  blendMode(BLEND);
}

function beads(pts, pal){
  blendMode(ADD);
  noStroke();
  const idxs = [146, 291, 426, 1897, 2052]; // 各自的旧结，与后来的新光
  for(const idx of idxs){
    const p = pts[idx];
    if(!p || p.m < 0.1) continue;
    fill(pal.core[0], pal.core[1], pal.core[2], 60 * p.m);
    circle(p.x, p.y, 11);
    fill(255, 250, 240, 110 * p.m);
    circle(p.x, p.y, 5.5);
  }
  blendMode(BLEND);
}

/* ---------- 结与光 ---------- */

function bloomHalo(){
  glow(845, 1030, 620, [[0,'rgba(255,196,130,0.30)'],[0.4,'rgba(255,150,110,0.12)'],[1,'rgba(255,120,90,0)']]);
  glow(845, 1030, 260, [[0,'rgba(255,230,190,0.36)'],[1,'rgba(255,200,150,0)']]);
}

function rings(){
  blendMode(ADD);
  noFill();
  strokeWeight(1.4);
  const rings = [[255, 26], [365, 17], [480, 11], [610, 7]];
  for(const r of rings){
    stroke(255, 214, 150, r[1]);
    const a0 = random(TWO_PI);
    arc(845 + random(-6,6), 1030 + random(-6,6),
        r[0]*2, r[0]*2*(0.96 + random(0.08)),
        a0, a0 + PI * random(1.1, 1.8));
  }
  blendMode(BLEND);
}

function sparks(){
  for(let k = 1; k <= 5; k++){
    const s = k / 5.4;
    const ampS = 185 * pow(sin(PI * s), 0.8) + 6;
    if(ampS < 34) continue;
    const x = 800 + 45 * sin(PI * s);
    const y = 700 + 660 * easeIO(s);
    const r = 8 + ampS * 0.05;
    glow(x, y, r*6, [[0,'rgba(255,240,214,0.5)'],[0.4,'rgba(255,205,160,0.16)'],[1,'rgba(255,180,140,0)']]);
    blendMode(ADD);
    noStroke();
    fill(255, 248, 234, 190);
    circle(x, y, r);
    stroke(255, 238, 206, 60);
    strokeWeight(1.1);
    line(x - r*3, y, x + r*3, y);
    line(x, y - r*3, x, y + r*3);
    blendMode(BLEND);
  }
}

function bloomCore(){
  glow(845, 1030, 150, [[0,'rgba(255,244,220,0.55)'],[0.5,'rgba(255,214,160,0.22)'],[1,'rgba(255,200,150,0)']]);
  blendMode(ADD);
  noStroke();
  fill(255, 236, 200, 60);  circle(845, 1030, 64);
  fill(255, 250, 238, 120); circle(845, 1030, 30);
  blendMode(BLEND);
}

function wisps(){
  blendMode(ADD);
  noFill();
  strokeWeight(1.1);
  wispLine(800, 940, -0.6);
  wispLine(905, 985, 0.7);
  blendMode(BLEND);
}

function wispLine(x0, y0, dir){
  let x = x0, y = y0, px = x, py = y;
  for(let i = 0; i < 70; i++){
    const a = -HALF_PI + dir * 0.5 + (noise(i * 0.12 + x0 * 0.01) - 0.5) * 1.6;
    x += cos(a) * 11;
    y += sin(a) * 11;
    stroke(255, 216, 168, 30 * (1 - i / 70));
    line(px, py, x, y);
    px = x; py = y;
  }
}

function embers(){
  blendMode(ADD);
  noStroke();
  for(let i = 0; i < 300; i++){
    let x, y;
    if(random() < 0.68){
      x = randomGaussian() * 230 + 845;
      y = randomGaussian() * 330 + 1030;
    } else {
      const s2 = random(0.05, 1);
      y = 1360 + 700 * pow(s2, 1.12);
      x = 800 + 26 * sin(s2 * PI * 1.15) + randomGaussian() * 46;
    }
    if(x < -20 || x > W + 20 || y < -20 || y > H + 20) continue;
    const big = random() < 0.12;
    const r = big ? random(3.5, 6) : random(1, 3.2);
    const a = big ? random(90, 160) : random(26, 80);
    const col = random() < 0.5 ? [255,214,160] : [255,176,150];
    fill(col[0], col[1], col[2], a * 0.35); circle(x, y, r * 3.4);
    fill(col[0], col[1], col[2], a);        circle(x, y, r);
  }
  stroke(255, 220, 170, 40);
  strokeWeight(1);
  for(let i = 0; i < 26; i++){
    const x = randomGaussian() * 250 + 845;
    const y = randomGaussian() * 300 + 1000;
    const L = random(8, 26);
    const an = -HALF_PI + random(-0.5, 0.5);
    line(x, y, x + cos(an)*L, y + sin(an)*L);
  }
  blendMode(BLEND);
}

/* ---------- 收边 ---------- */

function vignette(){
  const c = drawingContext;
  let g = c.createRadialGradient(845, 1000, 540, 845, 1000, 1450);
  g.addColorStop(0, 'rgba(6,8,20,0)');
  g.addColorStop(1, 'rgba(5,7,18,0.66)');
  c.fillStyle = g;
  c.fillRect(0, 0, W, H);

  g = c.createLinearGradient(0, 0, 0, 320);
  g.addColorStop(0, 'rgba(4,6,16,0.55)');
  g.addColorStop(1, 'rgba(4,6,16,0)');
  c.fillStyle = g;
  c.fillRect(0, 0, W, 320);

  g = c.createLinearGradient(0, H - 300, 0, H);
  g.addColorStop(0, 'rgba(4,5,14,0)');
  g.addColorStop(1, 'rgba(4,5,14,0.6)');
  c.fillStyle = g;
  c.fillRect(0, H - 300, W, 300);
}

function grain(){
  blendMode(BLEND);
  noStroke();
  for(let i = 0; i < 18000; i++){
    const x = random(W), y = random(H), s = random(0.8, 2.0);
    if(random() < 0.5) fill(8, 10, 24, random(5, 13));
    else fill(255, 238, 214, random(3, 9));
    rect(x, y, s, s);
  }
  stroke(255, 240, 220, 5);
  strokeWeight(0.7);
  for(let i = 0; i < 26; i++){
    const x = random(W), y = random(H);
    const an = random(TWO_PI), L = random(40, 160);
    line(x, y, x + cos(an)*L, y + sin(an)*L);
  }
  blendMode(BLEND);
}

let W = 1600, H = 2000;
let KX = 800, KY = 930;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 255);
  strokeCap(ROUND);
  noLoop();

  paintBackground();
  grain(12000, 8);
  aurora();
  fieldMarks();
  rings();
  originGlows();

  blendMode(ADD);
  threads();
  embers();
  coreGlow();
  blendMode(BLEND);

  vignette();
  grain(3200, 5);
}

function paintBackground() {
  noStroke();
  for (let y = 0; y < H; y += 4) {
    let t = y / H;
    let h = lerp(232, 250, t);
    let s = lerp(60, 46, t);
    let b = lerp(6.5, 10.5, t) + 2.2 * sin(t * PI);
    fill(h, s, b);
    rect(0, y, W, 4.5);
  }
}

function grain(n, aMax) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(W), y = random(H);
    let a = random(1.5, aMax);
    if (random() < 0.5) fill(222, 24, 82, a);
    else fill(242, 50, 6, a);
    let s2 = random(0.6, 1.9);
    rect(x, y, s2, s2);
  }
}

function aurora() {
  noStroke();
  for (let i = 0; i < 22; i++) {
    let x = random(W), y = random(H);
    let r = random(280, 640);
    let hh = random([226, 240, 258, 212]);
    let sq0 = random(0.7, 1.05);
    for (let k = 10; k > 0; k--) {
      let t = k / 10;
      fill(hh, 48, 18, 3.2 * (1 - t) + 0.3);
      ellipse(x, y, r * 2 * t, r * 2 * t * sq0);
    }
  }
}

function fieldMarks() {
  for (let i = 0; i < 15000; i++) {
    let x = random(W), y = random(H);
    let d = dist(x, y, KX, KY);
    if (d < 150) continue;
    if (abs(x - KX) < 230 && y < KY - 150 && random() < 0.6) continue;
    let m = noise(x * 0.0016 + 3, y * 0.0016);
    if (random() > m * 1.5 - 0.25) continue;
    let base = atan2(KY - y, KX - x);
    let curl = 0.85 * exp(-d / 310);
    let wob = (noise(x * 0.003 + 40, y * 0.003) - 0.5) * 1.5;
    let a = base + wob + curl;
    let len = map(constrain(d, 150, 1300), 1300, 150, 6, 20) * map(m, 0, 1, 0.6, 1.25);
    let al = map(constrain(d, 150, 1250), 1250, 150, 6, 19) * map(m, 0, 1, 0.55, 1.2);
    stroke(216 + random(-16, 12), 44, 64, al);
    strokeWeight(random(0.7, 1.3));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
}

function rings() {
  let rs = [255, 325, 405, 495, 600, 722];
  for (let k = 0; k < rs.length; k++) {
    let r0 = rs[k];
    let aBase = map(k, 0, rs.length - 1, 12, 6);
    for (let ang = 0; ang < TWO_PI; ang += 0.024) {
      if (noise(k * 9.3 + ang * 1.35) < 0.3) continue;
      let a1 = ang, a2 = ang + 0.026;
      let r1 = r0 + (noise(cos(a1) + k * 5 + 30, sin(a1) + k * 5) - 0.5) * 36;
      let r2 = r0 + (noise(cos(a2) + k * 5 + 30, sin(a2) + k * 5) - 0.5) * 36;
      stroke(40, 26, 90, aBase * (0.7 + 0.6 * noise(ang * 3.1 + k * 7)));
      strokeWeight(0.9);
      line(KX + cos(a1) * r1, KY + sin(a1) * r1 * 0.96,
           KX + cos(a2) * r2, KY + sin(a2) * r2 * 0.96);
    }
  }
}

function originGlows() {
  halo(40, 1700, 320, 212, 58, 60, 16, 16);
  halo(1570, 330, 300, 266, 52, 60, 15, 16);
}

function threads() {
  for (let i = 0; i < 150; i++) walk(208, 186, 1, false);
  for (let i = 0; i < 6; i++) walk(208, 186, 1, true);
  for (let i = 0; i < 150; i++) walk(268, 126, -1, false);
  for (let i = 0; i < 6; i++) walk(268, 126, -1, true);
}

function walk(cool, routeBase, sign, hero) {
  let x, y;
  if (sign === 1) {
    if (random() < 0.6) { x = -8; y = random(H * 0.5, H * 0.98); }
    else { y = H + 8; x = random(-20, W * 0.52); }
  } else {
    if (random() < 0.6) { x = W + 8; y = random(H * 0.03, H * 0.52); }
    else { y = -8; x = random(W * 0.45, W + 20); }
  }
  let route = routeBase + random(-9, 9);
  let d0 = dist(x, y, KX, KY);
  let vx = (KX - x) / d0 * 3 + random(-0.6, 0.6);
  let vy = (KY - y) / d0 * 3 + random(-0.6, 0.6);
  let released = false;
  let releaseR = random(86, 122);
  let riseBudget = 430;
  let weight = hero ? random(2.0, 2.6) : random(0.9, 1.5);
  let aBase = hero ? 22 : 13;
  let maxSteps = 640;

  for (let s = 0; s < maxSteps; s++) {
    let d = dist(x, y, KX, KY);
    if (!released && d < releaseR && random() < 0.010) released = true;
    if (!released && d < 62 && random() < 0.055) break;

    let tx, ty;
    if (!released) {
      let ux = (KX - x) / max(d, 0.001);
      let uy = (KY - y) / max(d, 0.001);
      let pull = constrain(map(d, 60, 900, 0.5, 1.15), 0.5, 1.15);
      let sw = sign * (2.4 * exp(-sq(d - 175) / (2 * 130 * 130)) + 0.55 * exp(-d / 420));
      let wob = (noise(x * 0.006 + 200, y * 0.006) - 0.5) * 1.35;
      let bx = ux * pull - uy * sw;
      let by = uy * pull + ux * sw;
      let ca = cos(wob), sa = sin(wob);
      tx = bx * ca - by * sa;
      ty = bx * sa + by * ca;
    } else {
      let sway = (noise(x * 0.004 + 900, y * 0.004) - 0.5) * 2.4;
      let axis = (KX + (noise(y * 0.002 + 55) - 0.5) * 300 - x) * 0.004;
      tx = sway + axis;
      ty = -2.2 - noise(x * 0.005 + 40, y * 0.005) * 1.1;
    }
    let m = Math.hypot(tx, ty);
    if (m > 0.0001) { tx /= m; ty /= m; }
    let spd = released ? 2.7 : map(constrain(d, 60, 900), 60, 900, 1.9, 3.1);
    vx = lerp(vx, tx * spd, 0.16);
    vy = lerp(vy, ty * spd, 0.16);
    let nx = x + vx, ny = y + vy;

    let wgt = pow(constrain(map(d, 500, 120, 0, 1), 0, 1), 1.5);
    let hue = (cool + route * wgt + 360) % 360;
    let sat = lerp(52, 86, wgt);
    let bri = lerp(46, 100, wgt);
    let al = aBase * (0.8 + 0.6 * wgt);
    if (d < 95) al *= map(d, 95, 26, 1, 0.5);
    if (released) al *= 0.8;

    stroke(hue, sat, bri, al);
    strokeWeight(weight * (1 + 0.5 * wgt));
    line(x, y, nx, ny);

    if (random() < (hero ? 0.045 : 0.012)) {
      noStroke();
      fill(hue, sat * 0.75, min(bri + 18, 100), al * 1.4);
      let bs = (hero ? 3.2 : 2.1) * (0.7 + wgt);
      ellipse((x + nx) / 2, (y + ny) / 2, bs, bs);
    }

    x = nx; y = ny;
    if (x < -70 || x > W + 70 || y < -50 || y > H + 70) break;
    if (released) { riseBudget--; if (riseBudget <= 0) break; }
  }
}

function embers() {
  for (let i = 0; i < 170; i++) {
    let x = KX + random(-155, 155);
    let y = KY - random(10, 150);
    let v = random(1.5, 2.9);
    let sway = random(0.6, 1.8);
    let hue = 28 + random(22);
    let sz = random(1.1, 3.3);
    let steps = 260;
    let px = x, py = y;
    let s = 0;
    for (; s < steps && y > -30; s++) {
      x += (noise(x * 0.008 + 300, y * 0.008) - 0.5) * sway * 2.4;
      y -= v * (0.8 + 0.4 * noise(s * 0.02 + i * 3.7));
      if (s % 8 === 0) {
        let lf = 1 - s / steps;
        stroke(hue, 55 * lf + 25, 96, 15 * lf + 1);
        strokeWeight(max(0.6, sz * (0.5 + lf) * 0.9));
        line(px, py, x, y);
        px = x; py = y;
      }
    }
    let lf = max(0, 1 - s / steps);
    noStroke();
    fill(hue, 50, 100, 26 * lf);
    ellipse(x, y, sz * 1.5, sz * 1.5);
  }
}

function coreGlow() {
  halo(KX, KY, 560, 226, 55, 62, 5, 22);
  halo(KX, KY, 430, 330, 42, 72, 6, 22);
  halo(KX, KY, 300, 38, 68, 86, 8, 22);
  halo(KX, KY, 150, 40, 58, 100, 11, 20);
  halo(KX, KY, 62, 46, 24, 100, 13, 16);
  halo(KX, 520, 300, 34, 55, 92, 5, 16);
}

function halo(x, y, r, h, s, b, aPeak, steps) {
  noStroke();
  for (let i = steps; i >= 1; i--) {
    let t = i / steps;
    fill(h, s, b, aPeak * pow(1 - t, 1.7));
    ellipse(x, y, r * 2 * t, r * 2 * t);
  }
}

function vignette() {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(W / 2, 960, 560, W / 2, 1040, 1560);
  g.addColorStop(0, 'rgba(6,8,18,0)');
  g.addColorStop(0.6, 'rgba(6,8,18,0.18)');
  g.addColorStop(1, 'rgba(3,4,10,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  const W = 1600, H = 2000;
  const CX = 800, CY = 880;
  const R = 430, D = 470;
  const cL = { x: CX - D / 2, y: CY };
  const cR = { x: CX + D / 2, y: CY };
  const ctx = drawingContext;
  strokeCap(ROUND);

  function rgba(c, a) {
    return 'rgba(' + red(c) + ',' + green(c) + ',' + blue(c) + ',' + a + ')';
  }
  function wash(x, y, r, c, a) {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, rgba(c, a));
    g.addColorStop(1, rgba(c, 0));
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  function angDiff(a, b) { // a - b，归一化到 [-PI, PI]
    let d = (a - b) % TWO_PI;
    if (d > PI) d -= TWO_PI;
    if (d < -PI) d += TWO_PI;
    return d;
  }

  // ── 夜空底 ──
  let bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#0e1528');
  bg.addColorStop(0.42, '#0a0f20');
  bg.addColorStop(0.75, '#070a16');
  bg.addColorStop(1, '#03050c');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  wash(320, 280, 780, color(30, 50, 100), 0.16);
  wash(1330, 360, 720, color(44, 44, 92), 0.13);
  wash(140, 1420, 640, color(16, 46, 58), 0.15);
  wash(1470, 1350, 640, color(22, 38, 66), 0.12);
  wash(800, 1120, 900, color(36, 26, 48), 0.16);
  wash(800, 880, 640, color(110, 64, 42), 0.10);
  wash(800, 1720, 560, color(84, 60, 38), 0.10);

  // ── 星尘 ──
  noStroke();
  for (let i = 0; i < 430; i++) {
    let x = random(W), y = random(H * 0.74);
    if (dist(x, y, CX, CY) < 500) continue;
    let tw = noise(x * 0.004, y * 0.004);
    let s = (0.7 + 1.8 * tw) * random(0.5, 1.3);
    if (random() < 0.74) fill(186, 202, 235, random(16, 66));
    else fill(235, 206, 160, random(12, 52));
    circle(x, y, s);
    if (random() < 0.1) { fill(230, 235, 255, 9); circle(x, y, s * 4.5); }
  }

  // ── 下方静水 ──
  let wg = ctx.createLinearGradient(0, 1340, 0, H);
  wg.addColorStop(0, 'rgba(3,6,13,0)');
  wg.addColorStop(0.22, 'rgba(3,6,13,0.5)');
  wg.addColorStop(1, 'rgba(1,2,6,0.9)');
  ctx.fillStyle = wg;
  ctx.fillRect(0, 1340, W, H - 1340);

  for (let i = 0; i < 60; i++) {
    let y = random(1376, 1400), x = random(W), len = random(30, 160);
    stroke(120, 140, 170, random(6, 16));
    strokeWeight(random(0.6, 1.4));
    line(x, y, x + len, y);
  }

  // 光柱：落入水中的光
  let pg = ctx.createLinearGradient(0, 1250, 0, 2000);
  pg.addColorStop(0, 'rgba(255,206,138,0.16)');
  pg.addColorStop(0.45, 'rgba(255,180,110,0.08)');
  pg.addColorStop(1, 'rgba(255,180,110,0)');
  ctx.fillStyle = pg;
  ctx.fillRect(640, 1250, 320, 750);

  for (let i = 0; i < 240; i++) {
    let y = 1396 + pow(random(), 1.5) * 596;
    let spread = map(y, 1396, 1992, 55, 230);
    let x = 800 + randomGaussian(0, spread * 0.62);
    let len = random(8, 66);
    let a = map(y, 1396, 1992, 26, 7) * random(0.45, 1);
    stroke(255, 196, 138, a);
    strokeWeight(random(0.7, 1.9));
    line(x - len / 2, y, x + len / 2, y);
  }
  for (let i = 0; i < 150; i++) {
    let y = random(1400, 1990), x = random(W), len = random(14, 90);
    stroke(110, 130, 165, random(5, 14));
    strokeWeight(random(0.5, 1.3));
    line(x, y, x + len, y);
  }

  // ── 呼吸的涟漪环 ──
  const breathR = [505, 590, 682, 780];
  for (let k = 0; k < breathR.length; k++) {
    let rr = breathR[k];
    let prev = null;
    for (let i = 0; i <= 900; i++) {
      let a = (i / 900) * TWO_PI;
      let gate = noise(cos(a) * 1.4 + k * 7 + 2, sin(a) * 1.4 + k * 3);
      if (gate < 0.28 + k * 0.07) { prev = null; continue; }
      let r2 = rr + (noise(i * 0.02 + k * 40) - 0.5) * 12;
      let x = CX + cos(a) * r2, y = CY + sin(a) * r2;
      if (prev) {
        let al = (16 - k * 3) * map(gate, 0.3, 1, 0.5, 1.2);
        stroke(216, 178, 126, al);
        strokeWeight(random(0.7, 1.5));
        line(prev.x, prev.y, x, y);
      }
      prev = { x: x, y: y };
    }
  }

  // ── 两个完整的圆（炭笔手感）──
  function charRing(c, warmAng, baseC, warmC, seed) {
    let prev = null;
    for (let i = 0; i <= 1250; i++) {
      let a = (i / 1250) * TWO_PI;
      let gate = noise(i * 0.02 + seed, seed * 3);
      if (gate < 0.045) { prev = null; continue; }
      let rr = R + random(-3.5, 3.5) + 10 * (noise(cos(a) + 8 + seed, sin(a) + 4 + seed) - 0.5);
      let x = c.x + cos(a) * rr, y = c.y + sin(a) * rr;
      if (prev) {
        stroke(red(baseC), green(baseC), blue(baseC), random(16, 44));
        strokeWeight(random(0.9, 2.8));
        line(prev.x, prev.y, x, y);
        if (abs(angDiff(a, warmAng)) < HALF_PI * 1.15 && random() < 0.8) {
          stroke(red(warmC), green(warmC), blue(warmC), random(9, 26));
          strokeWeight(random(0.8, 2.2));
          line(prev.x + random(-1.5, 1.5), prev.y + random(-1.5, 1.5),
               x + random(-1.5, 1.5), y + random(-1.5, 1.5));
        }
      }
      prev = { x: x, y: y };
    }
  }
  blendMode(ADD);
  for (let c of [cL, cR]) {
    let prev = null;
    for (let i = 0; i <= 500; i++) {
      let a = (i / 500) * TWO_PI;
      let x = c.x + cos(a) * R, y = c.y + sin(a) * R;
      if (prev) { stroke(190, 140, 90, 7); strokeWeight(13); line(prev.x, prev.y, x, y); }
      prev = { x: x, y: y };
    }
  }
  blendMode(BLEND);
  charRing(cL, 0, color(112, 128, 162), color(240, 192, 130), 11);
  charRing(cR, PI, color(104, 120, 158), color(238, 188, 128), 47);

  // ── 共有的形状（vesica）──
  function inVesica(x, y, m) {
    return dist(x, y, cL.x, cL.y) < R - m && dist(x, y, cR.x, cR.y) < R - m;
  }
  function almondEdge(c, o) {
    let prev = null;
    for (let i = 0; i <= 720; i++) {
      let a = (i / 720) * TWO_PI;
      let x = c.x + cos(a) * R, y = c.y + sin(a) * R;
      if (dist(x, y, o.x, o.y) < R - 2) {
        let j = random(-1.4, 1.4);
        let xj = x + cos(a) * j, yj = y + sin(a) * j;
        if (prev) {
          stroke(252, 208, 152, random(60, 130));
          strokeWeight(random(1.1, 2.3));
          line(prev.x, prev.y, xj, yj);
        }
        prev = { x: xj, y: yj };
      } else prev = null;
    }
  }
  almondEdge(cL, cR);
  almondEdge(cR, cL);

  for (let i = 0; i < 3000; i++) { // 厚重的暖色笔触
    let x = random(605, 995), y = random(522, 1238);
    if (!inVesica(x, y, 10)) continue;
    let spine = constrain(1 - abs(x - CX) / 195, 0, 1);
    let a = noise(x * 0.005, y * 0.005, 3) * TWO_PI * 2;
    let L = (4 + 20 * spine) * random(0.5, 1.3);
    let cc = lerpColor(color(150, 62, 58), color(255, 208, 148), pow(spine, 1.3));
    stroke(red(cc), green(cc), blue(cc), 8 + 18 * spine);
    strokeWeight(random(0.9, 2.6));
    line(x - cos(a) * L, y - sin(a) * L, x + cos(a) * L, y + sin(a) * L);
  }
  blendMode(ADD);
  for (let i = 0; i < 2400; i++) { // 发光的内层
    let x = random(610, 990), y = random(530, 1230);
    if (!inVesica(x, y, 14)) continue;
    let spine = constrain(1 - abs(x - CX) / 195, 0, 1);
    let a = noise(x * 0.006, y * 0.006, 9) * TWO_PI * 2;
    let L = (3 + 24 * spine) * random(0.4, 1.2);
    let cc = lerpColor(color(120, 46, 40), color(255, 220, 160), pow(spine, 1.15));
    stroke(red(cc), green(cc), blue(cc), 5 + 16 * spine);
    strokeWeight(random(0.7, 2.0));
    line(x - cos(a) * L, y - sin(a) * L, x + cos(a) * L, y + sin(a) * L);
  }
  for (let i = 0; i < 340; i++) { // 中缝的光
    let y = random(540, 1220);
    let x = CX + randomGaussian(0, 7 + 20 * abs(y - CY) / 360);
    if (!inVesica(x, y, 8)) continue;
    let a = HALF_PI + random(-0.35, 0.35), L = random(3, 14);
    stroke(255, 240, 205, random(24, 70));
    strokeWeight(random(0.8, 1.9));
    line(x - cos(a) * L, y - sin(a) * L, x + cos(a) * L, y + sin(a) * L);
  }
  blendMode(BLEND);

  // ── 中心的火种 ──
  wash(800, 880, 250, color(255, 168, 92), 0.30);
  wash(800, 880, 110, color(255, 222, 164), 0.38);
  blendMode(ADD);
  for (let i = 0; i < 260; i++) {
    let a = random(TWO_PI), r0 = random(2, 20);
    let L = random(8, 62) * (random() < 0.7 ? 0.6 : 1);
    let x0 = CX + cos(a) * r0, y0 = CY + sin(a) * r0;
    let t = random();
    let cc = lerpColor(color(255, 150, 84), color(255, 246, 224), t);
    stroke(red(cc), green(cc), blue(cc), 24 + 60 * t);
    strokeWeight(random(0.8, 2.2));
    line(x0, y0, x0 + cos(a) * L, y0 + sin(a) * L);
  }
  noStroke();
  for (let i = 0; i < 14; i++) {
    fill(255, 250, 235, random(30, 90));
    circle(CX + randomGaussian(0, 4), CY + randomGaussian(0, 4), random(3, 13));
  }
  blendMode(BLEND);

  // ── 金缮缝与远端的灯 ──
  function goldStitch(x, y, dir) {
    stroke(255, 216, 138, 210);
    strokeWeight(1.4);
    for (let k = -1; k <= 1; k++) {
      let tx = x + cos(dir) * k * 5, ty = y + sin(dir) * k * 5;
      let pa = dir + HALF_PI + random(-0.35, 0.35), hl = random(3.5, 6.5);
      line(tx - cos(pa) * hl, ty - sin(pa) * hl, tx + cos(pa) * hl, ty + sin(pa) * hl);
    }
    noStroke();
    fill(255, 224, 150, 230);
    circle(x, y, 5);
    blendMode(ADD);
    fill(255, 190, 110, 45);
    circle(x, y, 18);
    blendMode(BLEND);
  }
  function moteEnd(x, y, warm) {
    noStroke();
    if (warm) fill(255, 232, 185, 190); else fill(190, 208, 240, 170);
    circle(x, y, random(3.5, 6.5));
    blendMode(ADD);
    if (warm) fill(255, 200, 130, 50); else fill(160, 185, 235, 40);
    circle(x, y, random(14, 22));
    blendMode(BLEND);
  }
  function thread(ax, ay, dir0, steps, target, broken) {
    let x = ax, y = ay, dir = dir0;
    let breakAt = -1;
    if (broken === true) breakAt = int(random(steps * 0.28, steps * 0.66));
    else if (typeof broken === 'number') breakAt = broken;
    for (let s = 0; s < steps; s++) {
      if (target) {
        let want = atan2(target.y - y, target.x - x);
        dir += angDiff(want, dir) * 0.05;
        if (dist(x, y, target.x, target.y) < 16) { moteEnd(target.x, target.y, true); return; }
      }
      dir += (noise(x * 0.0035, y * 0.0035, 77) - 0.5) * 0.5 + random(-0.03, 0.03);
      let nx = x + cos(dir) * 4.6, ny = y + sin(dir) * 4.6;
      if (nx < 16 || nx > W - 16 || ny < 12 || ny > H - 12) break;
      if (s === breakAt) {
        goldStitch(x, y, dir);
        let side = random() < 0.5 ? 1 : -1;
        x += cos(dir) * 12 + cos(dir + HALF_PI) * 9 * side;
        y += sin(dir) * 12 + sin(dir + HALF_PI) * 9 * side;
        dir += random(-0.3, 0.3);
        continue;
      }
      let fade = 1, rem = steps - s;
      if (rem < 24) fade = rem / 24;
      stroke(226, 192, 130, 20 + 34 * fade);
      strokeWeight(1.05);
      line(x, y, nx, ny);
      x = nx; y = ny;
    }
    if (!target && random() < 0.6) moteEnd(x, y, dist(x, y, CX, CY) < 720);
  }

  for (let i = 0; i < 11; i++) {
    let a = PI * random(0.58, 1.42);
    thread(cL.x + cos(a) * (R + 3), cL.y + sin(a) * (R + 3),
           a + random(-0.2, 0.2), int(random(120, 240)), null, i === 2 || i === 7);
  }
  for (let i = 0; i < 11; i++) {
    let a = PI * random(-0.42, 0.42);
    thread(cR.x + cos(a) * (R + 3), cR.y + sin(a) * (R + 3),
           a + random(-0.2, 0.2), int(random(120, 240)), null, i === 3 || i === 8);
  }
  for (let i = 0; i < 4; i++) {
    let side = i < 2 ? cL : cR;
    let a = -HALF_PI + random(-0.5, 0.5) + (side === cL ? -0.25 : 0.25);
    thread(side.x + cos(a) * (R + 3), side.y + sin(a) * (R + 3),
           a, int(random(130, 210)), null, i === 1);
  }
  for (let i = 0; i < 4; i++) {
    let side = i < 2 ? cL : cR;
    let a = HALF_PI + random(-0.45, 0.45) + (side === cL ? 0.2 : -0.2);
    thread(side.x + cos(a) * (R + 3), side.y + sin(a) * (R + 3),
           a, int(random(110, 180)), null, i === 2);
  }
  // 两根远行的线：远方有人，仍被系着；光也垂进静水
  let fa = -0.62;
  thread(cR.x + cos(fa) * (R + 3), cR.y + sin(fa) * (R + 3),
         fa, 460, { x: 1470, y: 190 }, 60);
  let fa2 = PI * 0.82;
  thread(cL.x + cos(fa2) * (R + 3), cL.y + sin(fa2) * (R + 3),
         fa2, 380, { x: 190, y: 1620 }, 62);

  // ── 上升的火花 ──
  noStroke();
  for (let p = 0; p < 8; p++) {
    let x = CX + random(-90, 90), y = random(500, 640);
    let drift = random(-0.6, 0.6);
    let steps = int(random(45, 95));
    for (let s = 0; s < steps; s++) {
      y -= random(3.5, 7.5);
      x += drift + (noise(x * 0.012, y * 0.012) - 0.5) * 7;
      fill(255, 222, 172, map(s, 0, steps, 64, 0) * random(0.4, 1));
      circle(x, y, random(1, 2.9));
    }
  }
  for (let p = 0; p < 3; p++) {
    let x = CX + random(-26, 26), y = CY - random(10, 40);
    for (let s = 0; s < 40; s++) {
      y -= random(4, 8);
      x += (noise(x * 0.02, y * 0.02, 5) - 0.5) * 5;
      fill(255, 236, 190, map(s, 0, 40, 80, 0));
      circle(x, y, random(1, 2.4));
    }
  }

  // ── 漂浮的微光 ──
  for (let i = 0; i < 130; i++) {
    let x = random(W), y = random(H * 0.72);
    if (dist(x, y, CX, CY) < 430) continue;
    let warm = random() < 0.4;
    noStroke();
    if (warm) fill(255, 224, 170, random(30, 110));
    else fill(196, 210, 238, random(24, 90));
    circle(x, y, random(1.2, 3.4));
    if (warm && random() < 0.3) {
      blendMode(ADD); fill(255, 200, 130, 22); circle(x, y, 10); blendMode(BLEND);
    }
  }

  // ── 颗粒 ──
  noStroke();
  for (let i = 0; i < 30000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.56) fill(0, 0, 0, random(16, 40));
    else fill(214, 222, 238, random(7, 20));
    rect(x, y, 1, 1);
  }

  // ── 暗角 ──
  let vg = ctx.createRadialGradient(CX, CY, 320, CX, 940, 1280);
  vg.addColorStop(0, 'rgba(2,4,10,0)');
  vg.addColorStop(0.62, 'rgba(2,4,10,0.14)');
  vg.addColorStop(1, 'rgba(1,2,7,0.66)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);

  let bg2 = ctx.createLinearGradient(0, 1560, 0, H);
  bg2.addColorStop(0, 'rgba(0,0,0,0)');
  bg2.addColorStop(1, 'rgba(0,0,0,0.4)');
  ctx.fillStyle = bg2;
  ctx.fillRect(0, 1560, W, 440);
}

// 《第三束光》—— 爱本身：两簇火倾身相向，中间燃出第三个光，并向世界流淌出去
const W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  paint();
}

function paint() {
  background(8, 7, 15);
  blendMode(BLEND);
  bgGradient();
  nebula();
  ripples();
  unionAmbience();
  being(598, 878, 1, 250);          // 左边的火，向右倾身
  woundLight(638, 870, 250, -1);    // 它外侧的裂痕，也在透光
  being(1002, 866, -1, 250);        // 右边的火，向左倾身
  woundLight(962, 858, 250, 1);
  river();
  threads();
  unionCore();
  sparksField();
  grain();
  vignette();
}

/* ---------------- 工具 ---------------- */

function g(s) {                       // 近似高斯抖动
  return (random() + random() + random() - 1.5) * s;
}

function mixC(a, b, t) {
  t = constrain(t, 0, 1);
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}

function radialGlow(x, y, r, c, a) {  // 柔和径向辉光
  const ctx = drawingContext;
  const gd = ctx.createRadialGradient(x, y, 0, x, y, r);
  gd.addColorStop(0.0, `rgba(${c[0]},${c[1]},${c[2]},${a})`);
  gd.addColorStop(0.45, `rgba(${c[0]},${c[1]},${c[2]},${a * 0.4})`);
  gd.addColorStop(1.0, `rgba(${c[0]},${c[1]},${c[2]},0)`);
  ctx.fillStyle = gd;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function bez(p0, p1, p2, p3, t) {
  const u = 1 - t;
  return {
    x: u * u * u * p0.x + 3 * u * u * t * p1.x + 3 * u * t * t * p2.x + t * t * t * p3.x,
    y: u * u * u * p0.y + 3 * u * u * t * p1.y + 3 * u * t * t * p2.y + t * t * t * p3.y
  };
}

/* ---------------- 底层 ---------------- */

function bgGradient() {
  const ctx = drawingContext;
  const gd = ctx.createLinearGradient(0, 0, 0, H);
  gd.addColorStop(0.00, '#0a0d1f');
  gd.addColorStop(0.40, '#151027');
  gd.addColorStop(0.72, '#130c1d');
  gd.addColorStop(1.00, '#07050e');
  ctx.fillStyle = gd;
  ctx.fillRect(0, 0, W, H);
}

function nebula() {
  blendMode(ADD);
  radialGlow(300, 280, 720, [44, 58, 118], 0.10);
  radialGlow(1360, 400, 660, [92, 44, 106], 0.09);
  radialGlow(230, 1660, 640, [28, 78, 84], 0.08);
  radialGlow(1420, 1740, 620, [110, 56, 40], 0.07);
  radialGlow(800, 1500, 760, [70, 40, 90], 0.06);
}

function ripples() {                  // 从交汇处向外荡开的微光涟漪
  blendMode(BLEND);
  noFill();
  const rs = [470, 610, 760, 920, 1100, 1290];
  for (let i = 0; i < rs.length; i++) {
    const r = rs[i];
    const nSeg = 2 + (i % 2);
    for (let s2 = 0; s2 < nSeg; s2++) {
      const a0 = random(TWO_PI);
      stroke(255, 200, 140, 26 - i * 3.2);
      strokeWeight(Math.max(0.6, 1.6 - i * 0.16));
      arc(800, 880, r * 2, r * 2 * 1.08, a0, a0 + random(0.6, 1.9));
    }
  }
}

function unionAmbience() {
  blendMode(ADD);
  radialGlow(800, 880, 980, [255, 150, 72], 0.10);
  radialGlow(800, 880, 620, [255, 182, 100], 0.14);
  radialGlow(800, 1080, 720, [255, 140, 70], 0.08);
}

/* ---------------- 两簇火 ---------------- */

function being(cx, cy, facing, baseR) {
  const coreX = cx + facing * 40;     // 核心先向对方挪近一步
  const coreY = cy - 8;
  blendMode(ADD);
  radialGlow(coreX, coreY, baseR * 1.75, [255, 118, 58], 0.10);
  radialGlow(coreX, coreY, baseR * 1.15, [255, 162, 88], 0.22);
  radialGlow(coreX, coreY, baseR * 0.62, [255, 228, 176], 0.5);

  noFill();
  const fx = facing > 0 ? 0 : PI;     // 朝向对方的方向
  for (let i = 0; i < 780; i++) {
    const a = random(TWO_PI);
    const reach = 1 + 0.42 * Math.max(0, Math.cos(a - fx)); // 那一侧的笔触伸长
    const n = noise(Math.cos(a) + 2, Math.sin(a) + 2, facing * 7);
    const rr = baseR * (0.34 + 0.85 * n) * reach * random(0.86, 1.12);
    const t = constrain(rr / (baseR * 1.35), 0, 1);
    const c = t < 0.45
      ? mixC([255, 240, 206], [255, 188, 108], t / 0.45)
      : mixC([255, 188, 108], [226, 88, 58], (t - 0.45) / 0.55);
    stroke(c[0], c[1], c[2], random(14, 62));
    strokeWeight(random(1.0, 4.4));
    const j = random(-0.06, 0.06);
    arc(coreX, coreY, rr * 2 * (1 + j), rr * 2 * (1 - j), a, a + random(0.15, 1.05));
  }

  for (let i = 0; i < 90; i++) {      // 向上飘散的火舌
    const a = random(PI * 1.12, PI * 1.88);
    const r1 = baseR * random(0.5, 1.02);
    const r2 = r1 + random(18, 88);
    const aa = a + random(-0.16, 0.16);
    stroke(255, random(170, 220), random(110, 150), random(16, 44));
    strokeWeight(random(1, 2.6));
    line(coreX + Math.cos(a) * r1, coreY + Math.sin(a) * r1,
         coreX + Math.cos(aa) * r2, coreY + Math.sin(aa) * r2);
  }

  for (let i = 0; i < 150; i++) {     // 内核细密的亮笔
    const a = random(TWO_PI);
    const rr = baseR * random(0.08, 0.42);
    stroke(255, 242, 210, random(26, 78));
    strokeWeight(random(1, 3));
    arc(coreX, coreY, rr * 2, rr * 2 * random(0.88, 1.12), a, a + random(0.3, 1.4));
  }
}

function woundLight(coreX, coreY, baseR, side) { // 背对的那一侧：伤口也漏出光
  blendMode(ADD);
  const wx = coreX + side * baseR * 0.88;
  const wy = coreY + 26;
  radialGlow(wx, wy, 64, [255, 202, 140], 0.26);
  for (let i = 0; i < 26; i++) {
    const rr = baseR * random(0.52, 0.94);
    const a = (side < 0 ? PI : 0) + random(-0.24, 0.24);
    const px = coreX + Math.cos(a) * rr;
    const py = coreY + Math.sin(a) * rr + 22;
    const l = random(10, 32);
    stroke(255, 236, 200, random(38, 88));
    strokeWeight(random(1, 2.2));
    line(px, py, px + side * random(2, 10), py + l * random(0.5, 1.3));
  }
}

/* ---------------- 中间的光与下坠的河 ---------------- */

function river() {
  blendMode(ADD);
  const ph = random(1000);
  const xAt = y => 800 + (noise(y * 0.0012 + ph) - 0.5) * 250 + Math.sin(y * 0.0034 + ph) * 28;

  for (let i = 0; i < 2500; i++) {    // 光河：越往下越宽，越往边越暗
    const y = random(985, 2015);
    const prog = (y - 985) / (2015 - 985);
    const wHalf = lerp(24, 310, Math.pow(prog, 0.85));
    const xc = xAt(y);
    const x = xc + g(1) * wHalf * 0.5;
    const len = random(9, 46) * (0.6 + prog * 0.9);
    const slant = (xAt(y + 30) - xAt(y - 30)) / 60;
    const cen = constrain(Math.abs(x - xc) / wHalf, 0, 1);
    const hot = (1 - cen) * (1 - prog * 0.45);
    const c = mixC(mixC([255, 232, 182], [255, 168, 88], prog), [212, 92, 52], cen);
    stroke(c[0], c[1], c[2], random(12, 44) * (0.5 + hot));
    strokeWeight(random(1, 3.4));
    line(x, y, x + slant * len, y + len);
  }

  for (let i = 0; i < 180; i++) {     // 溅进远处黑暗里的余烬
    const y = random(1240, 1975);
    const side = random() < 0.5 ? -1 : 1;
    const x = constrain(xAt(y) + side * random(lerp(130, 430, (y - 1240) / 735), 620), 26, W - 26);
    const s = random(1.1, 3.0);
    noStroke();
    fill(255, 190, 122, random(40, 110));
    circle(x, y, s * 2);
    if (random() < 0.3) radialGlow(x, y, s * 9, [255, 180, 110], 0.26);
  }
}

function threads() {                  // 两簇火之间来回奔走的丝线
  blendMode(ADD);
  const L = { x: 640, y: 864 }, R = { x: 960, y: 860 };
  for (let i = 0; i < 72; i++) {
    const up = (i % 2 === 0) ? -1 : 1;
    const b = random(46, 208);
    const p0 = { x: L.x + g(16), y: L.y + g(28) };
    const p3 = { x: R.x + g(16), y: R.y + g(28) };
    const p1 = { x: lerp(L.x, R.x, 0.33) + g(28), y: L.y + up * b * random(0.55, 1) + g(18) };
    const p2 = { x: lerp(L.x, R.x, 0.67) + g(28), y: R.y + up * b * random(0.55, 1) + g(18) };
    const col = mixC([255, 212, 140], [255, 140, 98], random());
    const al = random(10, 32);
    const w = random(0.7, 1.9);
    const segs = 30;
    for (let s2 = 0; s2 < segs; s2++) {
      const t1 = s2 / segs, t2 = (s2 + 1) / segs;
      const q1 = bez(p0, p1, p2, p3, t1);
      const q2 = bez(p0, p1, p2, p3, t2);
      const mid = 1 - Math.abs((t1 + t2) / 2 - 0.5) * 2;
      stroke(col[0], col[1], col[2], al * (0.4 + 0.9 * mid));
      strokeWeight(w);
      line(q1.x, q1.y, q2.x, q2.y);
    }
    if (random() < 0.42) {
      const q = bez(p0, p1, p2, p3, random(0.3, 0.7));
      radialGlow(q.x, q.y, random(13, 28), [255, 210, 140], 0.3);
      noStroke();
      fill(255, 240, 206, 160);
      circle(q.x, q.y, random(3, 6));
    }
  }
}

function unionCore() {                // 第三束光：交汇处最亮的一粒心
  blendMode(ADD);
  radialGlow(800, 880, 430, [255, 172, 92], 0.30);
  radialGlow(800, 880, 250, [255, 216, 150], 0.5);
  radialGlow(800, 880, 120, [255, 246, 226], 0.85);

  const ctx = drawingContext;         // 中间竖立的梭形光焰
  ctx.save();
  ctx.translate(800, 858);
  ctx.scale(0.52, 1.38);
  const gd = ctx.createRadialGradient(0, 0, 0, 0, 0, 150);
  gd.addColorStop(0, 'rgba(255,248,230,0.55)');
  gd.addColorStop(0.5, 'rgba(255,192,112,0.22)');
  gd.addColorStop(1, 'rgba(255,160,80,0)');
  ctx.fillStyle = gd;
  ctx.fillRect(-150, -150, 300, 300);
  ctx.restore();

  noFill();
  for (let i = 0; i < 110; i++) {     // 自中间升起的光丝
    const x0 = 800 + g(26);
    const y0 = 902 - random(120);
    const h = random(30, 150);
    const sway = random(-18, 18);
    stroke(255, 226, 170, random(20, 62));
    strokeWeight(random(0.8, 2.4));
    beginShape();
    for (let k = 0; k <= 4; k++) {
      vertex(x0 + sway * (k / 4) + g(3), y0 - h * (k / 4));
    }
    endShape();
  }

  for (let i = 0; i < 70; i++) {      // 向下倾注，汇入光河
    const y0 = random(900, 1090);
    const x0 = 800 + g(13) * (1 + (y0 - 900) / 190);
    stroke(255, 222, 160, random(24, 68));
    strokeWeight(random(1, 3));
    line(x0, y0, x0 + g(6), y0 + random(16, 52));
  }
}

/* ---------------- 远处被点亮的微光 ---------------- */

function sparksField() {
  blendMode(ADD);
  for (let i = 0; i < 110; i++) {     // 上方松松的一道光拱
    const a = random(PI + 0.12, TWO_PI - 0.12);
    const x = 800 + Math.cos(a) * random(470, 660) + g(30);
    const y = 872 + Math.sin(a) * random(380, 560) + g(30);
    sparkDot(x, y);
  }
  let placed = 0, guard = 0;          // 散在暗处、正被照亮的微光
  while (placed < 300 && guard < 5000) {
    guard++;
    const x = random(40, 1560), y = random(60, 1960);
    if (dist(x, y, 800, 880) < 430) continue;
    sparkDot(x, y);
    placed++;
  }
}

function sparkDot(x, y) {
  const cool = random() < 0.12;
  const bright = random() < 0.16;
  const s = bright ? random(1.8, 3.2) : random(0.8, 2.2);
  if (bright) radialGlow(x, y, s * random(7, 11), cool ? [188, 208, 255] : [255, 190, 120], 0.22);
  noStroke();
  if (cool) fill(214, 224, 255, bright ? random(130, 200) : random(34, 110));
  else fill(255, 226, 172, bright ? random(130, 200) : random(34, 110));
  circle(x, y, s * 2);
}

