function fieldLines() {
  noFill();
  for (let k = 0; k < 17; k++) {
    const rx = 520 + k * 26;
    const ry = 680 + k * 22;
    stroke(105, 86, 73, 5.5);
    strokeWeight(0.75);
    beginShape();
    for (let j = 0; j <= 240; j++) {
      const a = TWO_PI * j / 240;
      const wobble = (noise(cos(a) * 1.7 + 20, sin(a) * 1.7 + 20, k * 0.07) - 0.5) * 34;
      vertex(
        800 + (rx + wobble) * cos(a),
        960 + (ry + wobble) * sin(a)
      );
    }
    endShape(CLOSE);
  }

  for (let i = 0; i < 500; i++) {
    const x = random(width);
    const y = random(height);
    stroke(115, 95, 75, random(2, 6));
    strokeWeight(0.7);
    line(x, y, x + random(10, 70), y + random(-2, 2));
  }
}

function paperGrain(n) {
  strokeWeight(1);
  for (let i = 0; i < n; i++) {
    if (random() < 0.55) {
      stroke(255, 250, 238, random(3, 10));
    } else {
      stroke(73, 57, 49, random(2, 7));
    }
    point(random(width), random(height));
  }
}

function paintField(shape, x0, x1, palette) {
  const ctx = drawingContext;
  ctx.save();
  ctx.clip(shape);

  for (let i = 0; i < 150; i++) {
    const x = random(x0, x1);
    const y = random(190, 1740);
    const len = random(100, 460);
    const bend = (noise(x * 0.003, y * 0.003) - 0.5) * 230 + random(-50, 50);
    const c = random(palette);
    stroke(red(c), green(c), blue(c), random(5, 15));
    strokeWeight(random(10, 58));
    noFill();
    bezier(
      x, y,
      x + bend * 0.15, y + len * 0.28,
      x + bend, y + len * 0.72,
      x + bend * 0.65, y + len
    );
  }

  noStroke();
  for (let i = 0; i < 430; i++) {
    const c = random(palette);
    fill(red(c), green(c), blue(c), random(3, 9));
    ellipse(
      random(x0, x1), random(180, 1780),
      random(20, 140), random(40, 250)
    );
  }

  for (let i = 0; i < 1450; i++) {
    const x = random(x0, x1);
    const y = random(190, 1770);
    const len = random(25, 230);
    const drift = (noise(x * 0.006, y * 0.004, 4) - 0.5) * 100;
    const c = random(palette);
    stroke(red(c), green(c), blue(c), random(8, 28));
    strokeWeight(random(0.4, 2.4));
    noFill();
    bezier(
      x, y,
      x + drift * 0.25, y + len * 0.3,
      x + drift, y + len * 0.7,
      x + drift * 0.7, y + len
    );
  }

  noStroke();
  for (let i = 0; i < 10500; i++) {
    const c = random(palette);
    fill(red(c), green(c), blue(c), random(4, 25));
    const r = random() < 0.06 ? random(2, 7) : random(0.5, 2.2);
    circle(random(x0, x1), random(180, 1780), r);
  }

  ctx.restore();
}

function cubicPoint(s, t) {
  const m = 1 - t;
  return {
    x: m*m*m*s[0][0] + 3*m*m*t*s[1][0] + 3*m*t*t*s[2][0] + t*t*t*s[3][0],
    y: m*m*m*s[0][1] + 3*m*m*t*s[1][1] + 3*m*t*t*s[2][1] + t*t*t*s[3][1]
  };
}

function edgePoint(segments, u) {
  u = constrain(u, 0, 1);
  if (u === 1) {
    const s = segments[segments.length - 1];
    return {x: s[3][0], y: s[3][1]};
  }
  const q = u * segments.length;
  const i = floor(q);
  return cubicPoint(segments[i], q - i);
}

function traceInner(segments, side, c) {
  noFill();
  for (let k = 10; k >= 0; k--) {
    const off = side * k * 6;
    stroke(
      red(c), green(c), blue(c),
      k === 0 ? 85 : 8 + (10 - k) * 2
    );
    strokeWeight(k === 0 ? 2.2 : 0.8 + k * 0.1);
    beginShape();
    vertex(segments[0][0][0] + off, segments[0][0][1]);
    for (let i = 0; i < segments.length; i++) {
      const s = segments[i];
      bezierVertex(
        s[1][0] + off, s[1][1],
        s[2][0] + off, s[2][1],
        s[3][0] + off, s[3][1]
      );
    }
    endShape();
  }
}

function memories(shape, segments, inward, c) {
  const ctx = drawingContext;
  ctx.save();
  ctx.clip(shape);
  noStroke();

  for (let i = 0; i < 950; i++) {
    const p = edgePoint(segments, random(0.05, 0.95));
    const d = 4 + pow(random(), 1.7) * 180;
    const x = p.x + inward * d + randomGaussian(0, 7);
    const y = p.y + randomGaussian(0, 18);
    const a = random(12, 55) * (1 - d / 240);
    fill(red(c), green(c), blue(c), a);

    if (random() < 0.12) {
      ellipse(x, y, random(2, 6), random(5, 15));
    } else {
      circle(x, y, random(0.8, 4.5));
    }
  }
  ctx.restore();
}

function edgeDust(segments, c1, c2) {
  noStroke();
  for (let i = 0; i < 1100; i++) {
    const p = edgePoint(segments, random(0.02, 0.98));
    const spread = randomGaussian(0, 23);
    const x = p.x + spread;
    const y = p.y + randomGaussian(0, 14);
    const c = lerpColor(c1, c2, random());
    const a = random(8, 44) * (1 - min(abs(spread) / 100, 0.8));
    fill(red(c), green(c), blue(c), a);
    const r = random() < 0.035 ? random(3, 7) : random(0.6, 3.2);
    circle(x, y, r);
  }
}

function filaments() {
  const warm = color(226, 143, 96);
  const cool = color(101, 166, 157);
  const gold = color(246, 216, 155);

  for (let i = 0; i < 13; i++) {
    const u = 0.08 + 0.79 * i / 12 + random(-0.016, 0.016);
    const a = edgePoint(innerL, u);
    const b = edgePoint(innerR, u + random(-0.026, 0.026));

    const c1 = [
      lerp(a.x, 800, random(0.45, 0.75)),
      a.y + random(-110, 110)
    ];
    const c2 = [
      lerp(b.x, 800, random(0.45, 0.75)),
      b.y + random(-110, 110)
    ];
    const segment = [[a.x,a.y], c1, c2, [b.x,b.y]];

    const start = i % 5 === 1 ? random(0.1, 0.25) : 0;
    const end = i % 5 === 3 ? random(0.72, 0.9) : 1;
    const baseAlpha = random(25, 58);
    strokeWeight(random(0.65, 1.45));

    for (let j = 0; j < 80; j++) {
      const q0 = j / 80;
      const q1 = (j + 1) / 80;
      const t0 = lerp(start, end, q0);
      const t1 = lerp(start, end, q1);
      const p0 = cubicPoint(segment, t0);
      const p1 = cubicPoint(segment, t1);
      const tm = (t0 + t1) * 0.5;

      let c = lerpColor(warm, cool, tm);
      c = lerpColor(c, gold, 0.48 * sin(PI * tm));
      const envelope = max(0, sin(PI * (q0 + q1) * 0.5));
      stroke(red(c), green(c), blue(c), baseAlpha * pow(envelope, 0.55));
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }
}

function sharedMotes() {
  const warm = color(190, 116, 75);
  const cool = color(54, 113, 116);
  const light = color(244, 209, 145);
  noStroke();

  for (let i = 0; i < 1650; i++) {
    const u = i < 500 ? random(0.28, 0.72) : random(0.03, 0.96);
    const a = edgePoint(innerL, u);
    const b = edgePoint(innerR, constrain(u + random(-0.012, 0.012), 0, 1));
    const t = random();

    const x = lerp(a.x, b.x, t) + randomGaussian(0, 5);
    const y = lerp(a.y, b.y, t) + randomGaussian(0, 12);

    let c = lerpColor(warm, cool, t);
    c = lerpColor(c, light, 0.38 * sin(PI * t));
    fill(red(c), green(c), blue(c), random(20, 95));

    const r = random() < 0.035 ? random(2.5, 5.5) : random(0.45, 1.9);
    circle(x, y, r * 2);
  }
}

const W = 1600;
const H = 2000;
let CORE, GOLD, CREAM;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  const ctx = drawingContext;
  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, "#070a1b");
  bg.addColorStop(0.46, "#15132d");
  bg.addColorStop(1, "#050713");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  for (let i = 0; i < 1500; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.003, y * 0.003);
    strokeWeight(random(0.45, 1.25));
    stroke(125, 145, 190, 3 + 18 * pow(n, 2));
    point(x, y);
  }

  const colA = color(235, 111, 124);
  const colB = color(82, 173, 197);
  GOLD = color(255, 194, 124);
  CREAM = color(255, 239, 207);
  CORE = { x: 810, y: 1000 };

  const A = {
    x: 500, y: 800, rx: 225, ry: 305,
    rot: -0.34, phase: 0.8, seed: 3.1, col: colA
  };
  const B = {
    x: 1115, y: 1200, rx: 250, ry: 330,
    rot: 0.26, phase: 2.2, seed: 8.7, col: colB
  };

  blendMode(ADD);
  glow(CORE.x, CORE.y, 820, [215, 93, 103], 0.026);
  glow(A.x, A.y, 440, [224, 74, 100], 0.035);
  glow(B.x, B.y, 470, [55, 140, 175], 0.038);
  blendMode(BLEND);

  const distant = [
    { x: 275, y: 375, rx: 82, ry: 108, rot: 0.3, phase: 1.4, seed: 14.2 },
    { x: 1370, y: 440, rx: 52, ry: 70, rot: -0.5, phase: 3.2, seed: 19.7 },
    { x: 265, y: 1640, rx: 66, ry: 91, rot: 0.8, phase: 0.2, seed: 24.1 },
    { x: 1345, y: 1725, rx: 88, ry: 66, rot: -0.2, phase: 4.4, seed: 31.6 }
  ];

  noFill();
  for (const s of distant) {
    for (let k = 0; k < 4; k++) {
      stroke(112, 135, 176, 5 + k * 2.2);
      strokeWeight(0.8);
      outline(s, 0.55 + k * 0.15);
    }
  }

  drawIsland(A, B);
  drawIsland(B, A);

  const rimA = rimPoints(A, B);
  const rimB = rimPoints(B, A);

  blendMode(ADD);
  for (let i = 0; i < 86; i++) {
    const p0 = rimA[floor(random(rimA.length))];
    const p3 = rimB[floor(random(rimB.length))];
    const dx = p3.x - p0.x;
    const dy = p3.y - p0.y;
    const len = sqrt(dx * dx + dy * dy);
    const bend = random(-0.18, 0.18) * len;

    let mx = (p0.x + p3.x) * 0.5 - dy / len * bend;
    let my = (p0.y + p3.y) * 0.5 + dx / len * bend;
    const pull = random(0, 0.16);
    mx = lerp(mx, CORE.x, pull);
    my = lerp(my, CORE.y, pull);

    const p1 = {
      x: lerp(p0.x, mx, 0.52) + random(-18, 18),
      y: lerp(p0.y, my, 0.52) + random(-18, 18)
    };
    const p2 = {
      x: lerp(p3.x, mx, 0.52) + random(-18, 18),
      y: lerp(p3.y, my, 0.52) + random(-18, 18)
    };

    const incomplete = random() < 0.34;
    const tEnd = incomplete ? random(0.38, 0.86) : 1;
    const bright = i < 7;
    const base = bright ? random(26, 42) : random(6, 15);
    const steps = 54;
    let px = p0.x;
    let py = p0.y;

    for (let j = 1; j <= steps; j++) {
      const u = j / steps;
      const t = u * tEnd;
      const x = cubic(p0.x, p1.x, p2.x, p3.x, t);
      const y = cubic(p0.y, p1.y, p2.y, p3.y, t);
      const cc = t < 0.52
        ? lerpColor(colA, GOLD, t / 0.52)
        : lerpColor(GOLD, colB, (t - 0.52) / 0.48);
      const fade = incomplete ? pow(1 - u, 0.55) : 1;
      const envelope = (0.32 + 0.68 * sin(PI * u)) * fade;

      strokeWeight(bright ? 5 : 2.6);
      stroke(red(cc), green(cc), blue(cc), base * 0.1 * envelope);
      line(px, py, x, y);

      strokeWeight(bright ? 1.35 : 0.72);
      stroke(red(cc), green(cc), blue(cc), base * envelope);
      line(px, py, x, y);
      px = x;
      py = y;
    }
  }

  glow(CORE.x, CORE.y, 620, [255, 112, 90], 0.035);
  glow(CORE.x, CORE.y, 340, [255, 180, 110], 0.075);
  glow(CORE.x, CORE.y, 150, [255, 218, 160], 0.1);
  glow(CORE.x, CORE.y, 48, [255, 244, 214], 0.14);

  push();
  translate(CORE.x, CORE.y);
  rotate(-0.22);
  noFill();
  for (let i = 0; i < 19; i++) {
    const r = random(48, 137);
    const start = random(TWO_PI);
    const span = random(0.12, 0.78);
    const cc = lerpColor(GOLD, CREAM, random());
    stroke(red(cc), green(cc), blue(cc), random(12, 39));
    strokeWeight(random(0.6, 1.5));
    arc(0, 0, r * 2, r * random(1.25, 1.8), start, start + span);
  }
  pop();

  for (let i = 0; i < 540; i++) {
    const a = random(TWO_PI);
    const r = pow(random(), 1.7) * 390;
    const x = CORE.x + cos(a) * r;
    const y = CORE.y + sin(a) * r * 0.82;
    const cc = lerpColor(GOLD, CREAM, random());
    strokeWeight(random(0.45, 1.9));
    stroke(red(cc), green(cc), blue(cc), (1 - r / 390) * random(6, 31));
    point(x, y);
  }

  scatterRimMotes(rimA, colA);
  scatterRimMotes(rimB, colB);
  blendMode(BLEND);

  for (let i = 0; i < 4300; i++) {
    const v = random(120, 220);
    strokeWeight(0.65);
    stroke(v, v * 0.94, v, random(2, 7));
    point(random(W), random(H));
  }

  const vignette = ctx.createRadialGradient(
    W / 2, H * 0.48, H * 0.18,
    W / 2, H * 0.5, H * 0.74
  );
  vignette.addColorStop(0, "rgba(2,3,12,0)");
  vignette.addColorStop(0.58, "rgba(2,3,12,0.02)");
  vignette.addColorStop(0.82, "rgba(2,3,12,0.22)");
  vignette.addColorStop(1, "rgba(1,2,8,0.64)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, W, H);
}

function islandPoint(s, a, sc) {
  const n = noise(
    s.seed + cos(a) * 1.35 + 4.2,
    s.seed * 0.7 + sin(a) * 1.35 + 1.7
  );
  const rr = 1
    + 0.105 * sin(3 * a + s.phase)
    + 0.055 * sin(5 * a - s.phase * 1.3)
    + (n - 0.5) * 0.18;
  const x = cos(a) * s.rx * rr * sc;
  const y = sin(a) * s.ry * rr * sc;
  return {
    x: s.x + x * cos(s.rot) - y * sin(s.rot),
    y: s.y + x * sin(s.rot) + y * cos(s.rot)
  };
}

function outline(s, sc) {
  beginShape();
  for (let i = 0; i < 160; i++) {
    const p = islandPoint(s, i / 160 * TWO_PI, sc);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);
}

function drawIsland(s, other) {
  noStroke();
  fill(red(s.col), green(s.col), blue(s.col), 6);
  outline(s, 0.99);
  noFill();

  for (let k = 0; k < 13; k++) {
    stroke(red(s.col), green(s.col), blue(s.col), 6 + k * 0.8);
    strokeWeight(0.85);
    outline(s, 0.14 + k * 0.055);
  }

  const N = 160;
  for (let k = 0; k < 6; k++) {
    const sc = 0.82 + k * 0.043;
    const base = 17 + k * 4;
    for (let i = 0; i < N; i++) {
      const p1 = islandPoint(s, i / N * TWO_PI, sc);
      const p2 = islandPoint(s, (i + 1) / N * TWO_PI, sc);
      const vx = (p1.x + p2.x) * 0.5 - s.x;
      const vy = (p1.y + p2.y) * 0.5 - s.y;
      const dx = other.x - s.x;
      const dy = other.y - s.y;
      const f = (vx * dx + vy * dy)
        / (sqrt(vx * vx + vy * vy) * sqrt(dx * dx + dy * dy));
      const openness = pow(max(0, f), 1.7);
      const gate = noise(s.seed * 4 + k * 3.7, i * 0.11);

      if (openness > 0.12 && gate < openness * 0.68) {
        if (random() < 0.08) {
          strokeWeight(1.25);
          stroke(red(s.col), green(s.col), blue(s.col), base * 0.65);
          point(p1.x, p1.y);
        }
        continue;
      }

      const alpha = base * (1 - openness * 0.78)
        * (0.72 + 0.28 * noise(i * 0.09, k + s.seed));
      stroke(red(s.col), green(s.col), blue(s.col), alpha);
      strokeWeight(0.9 + k * 0.09);
      line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  for (const sc of [0.06, 0.095, 0.13]) {
    stroke(red(s.col), green(s.col), blue(s.col), 19);
    strokeWeight(0.9);
    outline(s, sc);
  }
}

function rimPoints(s, other) {
  const points = [];
  const dx = other.x - s.x;
  const dy = other.y - s.y;
  const dl = sqrt(dx * dx + dy * dy);

  for (let i = 0; i < 160; i++) {
    const p = islandPoint(s, i / 160 * TWO_PI, 1.01);
    const vx = p.x - s.x;
    const vy = p.y - s.y;
    const f = (vx * dx + vy * dy) / (sqrt(vx * vx + vy * vy) * dl);
    if (f > 0.28) points.push(p);
  }
  return points;
}

function scatterRimMotes(rim, col) {
  for (let i = 0; i < 190; i++) {
    const p = rim[floor(random(rim.length))];
    const q = random(0.02, 0.2);
    const x = lerp(p.x, CORE.x, q) + random(-22, 22);
    const y = lerp(p.y, CORE.y, q) + random(-22, 22);
    const cc = lerpColor(col, GOLD, random(0.15, 0.8));
    strokeWeight(random(0.45, 1.7));
    stroke(red(cc), green(cc), blue(cc), random(7, 31));
    point(x, y);
  }
}

function cubic(a, b, c, d, t) {
  const u = 1 - t;
  return u * u * u * a
    + 3 * u * u * t * b
    + 3 * u * t * t * c
    + t * t * t * d;
}

function glow(x, y, r, rgb, alpha) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`);
  g.addColorStop(0.25, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha * 0.55})`);
  g.addColorStop(0.65, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha * 0.12})`);
  g.addColorStop(1, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

const W = 1600;
const H = 2000;

const A = { x: 590, y: 675 };
const B = { x: 1015, y: 1325 };
const M = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };
const DX = B.x - A.x;
const DY = B.y - A.y;
const LL = Math.hypot(DX, DY);
const U = { x: DX / LL, y: DY / LL };
const V = { x: -U.y, y: U.x };
const ROT = Math.atan2(U.y, U.x);

let warm, coral, gold, cool, sky, lilac, ivory, shared;

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  smooth();
  noLoop();

  warm = color(235, 105, 102);
  coral = color(244, 132, 116);
  gold = color(244, 188, 123);
  cool = color(102, 187, 193);
  sky = color(131, 177, 216);
  lilac = color(171, 145, 205);
  ivory = color(255, 230, 190);
  shared = color(203, 157, 180);

  paint();
}

function draw() {}

function paint() {
  drawGround();

  radialWash(M.x, M.y, 1120, color(59, 38, 83), 0.32);
  radialWash(A.x - 35, A.y, 630, coral, 0.20);
  radialWash(B.x + 30, B.y, 690, cool, 0.17);
  radialWash(M.x, M.y, 440, color(117, 76, 116), 0.075);

  blendMode(ADD);
  drawOuterField();
  drawBridge();

  drawCore(
    A,
    [coral, warm, gold, shared],
    305
  );
  drawCore(
    B,
    [cool, sky, lilac, shared],
    345
  );

  drawTravelingLight();
  blendMode(BLEND);

  radialWash(M.x, M.y, 270, ivory, 0.035);
  drawGrain();
  drawVignette();
}

function drawGround() {
  background(5, 7, 18);

  const ctx = drawingContext;
  ctx.save();
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, "#070817");
  g.addColorStop(0.42, "#111027");
  g.addColorStop(0.72, "#0b1023");
  g.addColorStop(1, "#050713");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

function rgba(c, a) {
  return (
    "rgba(" +
    Math.round(red(c)) + "," +
    Math.round(green(c)) + "," +
    Math.round(blue(c)) + "," +
    a + ")"
  );
}

function radialWash(x, y, r, c, a) {
  const ctx = drawingContext;
  ctx.save();
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, rgba(c, a));
  g.addColorStop(0.28, rgba(c, a * 0.58));
  g.addColorStop(0.68, rgba(c, a * 0.14));
  g.addColorStop(1, rgba(c, 0));
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
  ctx.restore();
}

function drawOuterField() {
  noFill();

  for (let i = 0; i < 68; i++) {
    const rx = random(510, 880);
    const ry = random(340, 680);
    const start = random(TWO_PI);
    const span = random(0.28, 1.32);
    const phase = random(TWO_PI);
    const steps = 42;

    if (i % 3 === 0) {
      stroke(142, 108, 153, random(3, 8));
    } else if (i % 3 === 1) {
      stroke(89, 117, 158, random(3, 8));
    } else {
      stroke(151, 119, 137, random(2.5, 7));
    }

    strokeWeight(random(0.4, 1.05));
    beginShape();

    for (let j = 0; j <= steps; j++) {
      const a = start + span * j / steps;
      const wobble = 1 + 0.025 * Math.sin(a * 3 + phase);
      const ex = Math.cos(a) * rx * wobble;
      const ey = Math.sin(a) * ry * wobble;
      const x = M.x + ex * Math.cos(ROT) - ey * Math.sin(ROT);
      const y = M.y + ex * Math.sin(ROT) + ey * Math.cos(ROT);
      vertex(x, y);
    }

    endShape();
  }
}

function fieldPoint(base, along, across) {
  return {
    x: base.x + U.x * along + V.x * across,
    y: base.y + U.y * along + V.y * across
  };
}

function makePath(q) {
  const p0 = fieldPoint(
    A,
    random(-135, 105),
    q * random(95, 160) + random(-52, 52)
  );

  const p3 = fieldPoint(
    B,
    random(-105, 135),
    q * random(110, 175) + random(-52, 52)
  );

  const bow = Math.sin(q * Math.PI) * random(45, 105) + random(-45, 45);

  const p1 = fieldPoint(
    A,
    LL * 0.32 + random(-55, 70),
    q * random(190, 300) + bow + random(-42, 42)
  );

  const p2 = fieldPoint(
    B,
    -LL * 0.32 + random(-70, 55),
    q * random(190, 300) + bow * 0.35 + random(-42, 42)
  );

  return {
    p0,
    p1,
    p2,
    p3,
    q,
    phase: random(1000),
    ca: lerpColor(warm, gold, random()),
    cb: lerpColor(cool, random() < 0.5 ? sky : lilac, random()),
    mid: shared
  };
}

function pathPoint(p, t) {
  const mt = 1 - t;
  const a = mt * mt * mt;
  const b = 3 * mt * mt * t;
  const c = 3 * mt * t * t;
  const d = t * t * t;

  let x = a * p.p0.x + b * p.p1.x + c * p.p2.x + d * p.p3.x;
  let y = a * p.p0.y + b * p.p1.y + c * p.p2.y + d * p.p3.y;

  const envelope = Math.sin(Math.PI * t);
  const nx = noise(p.phase, t * 2.8) - 0.5;
  const ny = noise(p.phase + 37, t * 2.8) - 0.5;

  x += nx * 40 * envelope;
  y += ny * 40 * envelope;

  return { x, y };
}

function pathColor(p, t) {
  if (t < 0.5) {
    return lerpColor(p.ca, p.mid, Math.pow(t * 2, 0.85));
  }
  return lerpColor(p.mid, p.cb, Math.pow((t - 0.5) * 2, 1.05));
}

function drawBridge() {
  const count = 780;
  const segments = 64;

  for (let i = 0; i < count; i++) {
    let q = (random() + random() + random() - 1.5) / 1.5;
    if (i % 8 === 0) q = random(-1, 1);

    const bright = random() < 0.075;
    const p = makePath(q);
    p.mid = lerpColor(
      shared,
      ivory,
      bright ? random(0.35, 0.75) : random(0, 0.18)
    );

    const baseAlpha = bright ? random(24, 50) : random(5, 16);
    const weight = bright ? random(0.8, 1.45) : random(0.35, 0.9);

    let previous = pathPoint(p, 0);

    for (let j = 1; j <= segments; j++) {
      const t = j / segments;
      const current = pathPoint(p, t);
      const c = pathColor(p, t);
      const envelope =
        0.30 + 0.70 * Math.pow(Math.sin(Math.PI * t), 0.6);

      stroke(
        red(c),
        green(c),
        blue(c),
        baseAlpha * envelope
      );
      strokeWeight(weight * (0.76 + 0.24 * Math.sin(Math.PI * t)));
      line(previous.x, previous.y, current.x, current.y);
      previous = current;
    }
  }
}

function drawCore(C, palette, count) {
  blendMode(BLEND);
  radialWash(C.x, C.y, 340, palette[0], 0.13);
  radialWash(C.x, C.y, 155, palette[1], 0.075);
  blendMode(ADD);
  noFill();

  for (let i = 0; i < count; i++) {
    const r = 25 + Math.pow(random(), 0.72) * 315;
    const rx = r * random(0.82, 1.16);
    const ry = r * random(0.48, 0.78);
    const rotation = ROT + random(-0.5, 0.5);
    const start = random(TWO_PI);

    let span = random(0.35, 2.5);
    if (random() < 0.1) span = random(2.8, 4.8);

    const phase = random(100);
    const cx = C.x + random(-22, 22);
    const cy = C.y + random(-22, 22);
    const col = palette[Math.floor(random(palette.length))];
    const bright = random() < 0.06;
    const alpha = bright
      ? random(30, 60)
      : random(6, 21) * (1.15 - r / 700);

    stroke(red(col), green(col), blue(col), alpha);
    strokeWeight(bright ? random(0.8, 1.5) : random(0.35, 0.95));

    const steps = Math.max(9, Math.floor(span * 25));
    beginShape();

    for (let j = 0; j <= steps; j++) {
      const a = start + span * j / steps;
      const wobble =
        1 +
        0.045 * Math.sin(a * 3 + phase) +
        0.05 * (noise(phase, a * 0.7) - 0.5);

      const ex = Math.cos(a) * rx * wobble;
      const ey = Math.sin(a) * ry * wobble;
      const x = cx + ex * Math.cos(rotation) - ey * Math.sin(rotation);
      const y = cy + ex * Math.sin(rotation) + ey * Math.cos(rotation);
      vertex(x, y);
    }

    endShape();
  }

  noStroke();
  for (let i = 0; i < 155; i++) {
    const r = Math.pow(random(), 1.85) * 130;
    const a = random(TWO_PI);
    const x = C.x + Math.cos(a) * r * 1.12;
    const y = C.y + Math.sin(a) * r * 0.82;
    const col = random() < 0.16
      ? ivory
      : palette[Math.floor(random(palette.length))];

    fill(red(col), green(col), blue(col), random(16, 72));
    const size = random() < 0.07 ? random(2, 3.1) : random(0.5, 1.75);
    circle(x, y, size);
  }
}

function drawTravelingLight() {
  noStroke();

  for (let i = 0; i < 460; i++) {
    const q = (random() + random() + random() - 1.5) / 1.5;
    const p = makePath(q);
    p.mid = lerpColor(shared, ivory, random(0.2, 0.75));

    const t = random(0.035, 0.965);
    const pos = pathPoint(p, t);
    const c = pathColor(p, t);
    const envelope = 0.35 + 0.65 * Math.sin(Math.PI * t);

    fill(
      red(c),
      green(c),
      blue(c),
      random(24, 96) * envelope
    );

    const size = random() < 0.045
      ? random(2.2, 3.5)
      : random(0.55, 1.8);

    circle(pos.x, pos.y, size);
  }

  for (let i = 0; i < 95; i++) {
    const a = random(TWO_PI);
    const r = random(300, 710);
    const ex = Math.cos(a) * r;
    const ey = Math.sin(a) * r * random(0.55, 0.82);
    const x = M.x + ex * Math.cos(ROT) - ey * Math.sin(ROT);
    const y = M.y + ex * Math.sin(ROT) + ey * Math.cos(ROT);
    const c = i % 2 === 0 ? shared : sky;

    fill(red(c), green(c), blue(c), random(8, 35));
    circle(x, y, random(0.5, 1.5));
  }
}

function drawGrain() {
  const ctx = drawingContext;
  ctx.save();

  for (let i = 0; i < 22000; i++) {
    const x = random(W);
    const y = random(H);
    const a = random(0.012, 0.04);

    ctx.fillStyle = random() < 0.52
      ? "rgba(235,222,230," + a + ")"
      : "rgba(0,0,10," + a * 1.4 + ")";

    const s = random(0.35, 1.25);
    ctx.fillRect(x, y, s, s);
  }

  ctx.restore();

  stroke(205, 190, 215, 3.5);
  strokeWeight(0.45);

  for (let i = 0; i < 850; i++) {
    const x = random(W);
    const y = random(H);
    const length = random(4, 24);
    const a = random(-0.22, 0.22) + HALF_PI;
    line(
      x,
      y,
      x + Math.cos(a) * length,
      y + Math.sin(a) * length
    );
  }
}

function drawVignette() {
  const ctx = drawingContext;
  ctx.save();

  const g = ctx.createRadialGradient(
    W * 0.5, H * 0.5, 430,
    W * 0.5, H * 0.5, 1280
  );

  g.addColorStop(0, "rgba(2,3,12,0)");
  g.addColorStop(0.58, "rgba(2,3,12,0.03)");
  g.addColorStop(0.82, "rgba(2,3,12,0.30)");
  g.addColorStop(1, "rgba(2,3,12,0.76)");

  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

const W = 1600;
const H = 2000;
let warm, cool, gold;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  angleMode(RADIANS);
  noLoop();
}

function draw() {
  warm = [
    color(164, 64, 54),
    color(199, 83, 62),
    color(221, 119, 86),
    color(137, 55, 65),
    color(215, 151, 94)
  ];
  cool = [
    color(27, 62, 74),
    color(38, 99, 110),
    color(70, 131, 137),
    color(53, 71, 100),
    color(105, 143, 137)
  ];
  gold = color(181, 137, 67);

  strokeCap(ROUND);
  strokeJoin(ROUND);
  paintGround();

  for (const side of [-1, 1]) {
    const palette = side < 0 ? warm : cool;
    for (let i = 0; i < 12; i++) {
      const q = (i + 0.5) / 12;
      const a = makeArc(side, q);
      const c = random(palette);
      noFill();
      stroke(red(c), green(c), blue(c), random(4, 9));
      strokeWeight(50 + 105 * q);
      traceArc(a);
    }
  }

  blendMode(MULTIPLY);
  for (const side of [-1, 1]) {
    const palette = side < 0 ? warm : cool;
    for (let i = 21; i >= 0; i--) {
      const q = pow((i + 0.5) / 22, 1.04);
      const a = makeArc(side, q);
      const c = lerpColor(random(palette), color(239, 229, 211), 0.08);
      const ribbonWidth = random(18, 52) * (0.55 + q);
      const alphaValue = random(10, 23) * (1 - 0.25 * q);
      paintRibbon(a, c, ribbonWidth, alphaValue);
    }
  }
  blendMode(BLEND);

  for (const side of [-1, 1]) {
    const palette = side < 0 ? warm : cool;
    for (let i = 139; i >= 0; i--) {
      const q = pow((i + random(0.12, 0.88)) / 140, 0.96);
      const a = makeArc(side, q);
      let c = random(palette);
      c = lerpColor(c, color(236, 226, 207), 0.08 + q * 0.18);
      if (random() < 0.035) c = gold;

      const alphaValue = random(28, 76) * (1 - 0.28 * q);
      noFill();
      stroke(red(c), green(c), blue(c), alphaValue);
      strokeWeight(random(0.65, 2.15) + (random() < 0.08 ? random(1, 3) : 0));

      if (random() < 0.32) {
        traceArc(a, 0, random(0, 0.055), random(0.945, 1));
      } else {
        traceArc(a);
      }
    }
  }

  for (const side of [-1, 1]) {
    const palette = side < 0 ? warm : cool;
    for (let k = 0; k < 8; k++) {
      const a = makeArc(side, random(0.025, 0.3));
      const c = k % 3 === 0 ? gold : lerpColor(random(palette), color(255, 244, 215), 0.3);
      noFill();
      stroke(red(c), green(c), blue(c), random(48, 92));
      strokeWeight(random(0.8, 2.2));
      const u0 = random(0.04, 0.7);
      traceArc(a, 0, u0, min(0.98, u0 + random(0.12, 0.28)));
    }
  }

  wash(800, 985, 435, color(255, 249, 228), 0.5);
  wash(812, 945, 205, color(255, 226, 154), 0.12);
  paintSharedLight();
  paintVignette();
  paintGrain();
}

function makeArc(side, q) {
  q = constrain(q, 0, 1);

  const innerRx = side < 0 ? 152 : 180;
  const innerRy = side < 0 ? 432 : 466;
  const outerRx = side < 0 ? 770 : 790;
  const outerRy = side < 0 ? 962 : 978;

  const rx = lerp(innerRx, outerRx, pow(q, 0.9))
    + random(-10, 10) * (0.35 + q);
  const ry = lerp(innerRy, outerRy, pow(q, 0.94))
    + random(-16, 16) * (0.35 + q);

  const cx = 800 + (side < 0 ? 14 : -16)
    + sin(q * 5.4 + (side < 0 ? 0.3 : 1.2)) * 24 * q
    + random(-5, 5);
  const cy = 1000 + (side < 0 ? 24 : -28)
    + random(-18, 18) * (0.4 + q);

  let a0, a1;
  if (side < 0) {
    a0 = HALF_PI + random(-0.16, 0.13) - q * 0.06;
    a1 = 3 * HALF_PI + random(-0.12, 0.18) + q * 0.08;
  } else {
    a0 = -HALF_PI + random(-0.15, 0.12) - q * 0.07;
    a1 = HALF_PI + random(-0.12, 0.16) + q * 0.05;
  }

  return {
    side,
    q,
    rx,
    ry,
    cx,
    cy,
    a0,
    a1,
    phase: random(0, 500),
    lean: random(-1, 1)
  };
}

function arcPoint(a, u, offset = 0) {
  const t = lerp(a.a0, a.a1, u);
  const cs = cos(t);
  const sn = sin(t);

  const n = noise(
    a.phase + cs * 0.8,
    a.phase * 0.13 + sn * 0.8,
    a.q * 1.9
  ) - 0.5;

  const n2 = noise(
    a.phase * 0.07 + u * 1.4,
    a.q * 4.2 + 7.3
  ) - 0.5;

  const swell = (12 + 58 * a.q) * n
    + (3 + 10 * a.q) * sin(t * 3 + a.phase);

  const rx = a.rx + offset + swell;
  const ry = a.ry + offset * 1.15 + swell * 1.25;

  let x = a.cx + rx * cs;
  let y = a.cy + ry * sn;

  x += (5 + 22 * a.q) * n2 + 13 * a.q * sin(2 * t + a.phase);
  y += 18 * a.q * sin(t * 2 + a.phase * 0.17) + 12 * n2;
  x += a.lean * sn * (8 + 18 * a.q);

  return { x, y };
}

function traceArc(a, offset = 0, u0 = 0, u1 = 1) {
  noFill();
  beginShape();
  for (let j = 0; j <= 156; j++) {
    const u = lerp(u0, u1, j / 156);
    const p = arcPoint(a, u, offset);
    vertex(p.x, p.y);
  }
  endShape();
}

function paintRibbon(a, c, ribbonWidth, alphaValue) {
  noStroke();
  fill(red(c), green(c), blue(c), alphaValue);

  beginShape();
  for (let j = 0; j <= 100; j++) {
    const p = arcPoint(a, j / 100, ribbonWidth * 0.5);
    vertex(p.x, p.y);
  }
  for (let j = 100; j >= 0; j--) {
    const p = arcPoint(a, j / 100, -ribbonWidth * 0.5);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);

  noFill();
  stroke(red(c), green(c), blue(c), min(46, alphaValue * 1.6));
  strokeWeight(0.8);
  traceArc(a);
}

function paintGround() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(780, 880, 40, 800, 1000, 1370);
  g.addColorStop(0, "#fffaf0");
  g.addColorStop(0.46, "#f4ecdd");
  g.addColorStop(1, "#ddd2c1");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  wash(390, 1050, 790, warm[1], 0.055);
  wash(1210, 920, 830, cool[1], 0.05);
  wash(770, 1580, 610, warm[4], 0.025);
  wash(800, 980, 520, color(255, 241, 199), 0.14);
}

function wash(x, y, r, c, alphaValue) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  const rgb = `${red(c)},${green(c)},${blue(c)}`;
  g.addColorStop(0, `rgba(${rgb},${alphaValue})`);
  g.addColorStop(0.45, `rgba(${rgb},${alphaValue * 0.44})`);
  g.addColorStop(1, `rgba(${rgb},0)`);
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function paintSharedLight() {
  for (let i = 0; i < 44; i++) {
    const u = (i + random(0.1, 0.9)) / 44;
    const y = lerp(1360, 640, u) + random(-20, 20);
    const x = 800
      + 44 * sin(u * TWO_PI * 1.15 - 0.8)
      + random(-22, 22);

    if (i % 10 === 0) wash(x, y, 34, gold, 0.1);

    const d = random(1.4, 4.8) * (0.8 + 0.5 * sin(PI * u));
    noStroke();
    fill(177, 128, 55, random(42, 112));
    circle(x, y, d);

    if (i % 7 === 0) {
      fill(255, 249, 221, 115);
      circle(x - 0.5, y - 0.5, d * 0.38);
    }
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 980, 710, 800, 1000, 1360);
  g.addColorStop(0, "rgba(54,43,37,0)");
  g.addColorStop(0.72, "rgba(54,43,37,0.025)");
  g.addColorStop(1, "rgba(54,43,37,0.14)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function paintGrain() {
  const ctx = drawingContext;

  for (let i = 0; i < 34000; i++) {
    const pale = random() < 0.56;
    ctx.fillStyle = pale
      ? "rgba(255,255,245,0.055)"
      : "rgba(60,45,35,0.035)";
    const s = random(0.35, 1.35);
    ctx.fillRect(random(W), random(H), s, s);
  }

  ctx.lineWidth = 0.6;
  for (let i = 0; i < 380; i++) {
    const x = random(W);
    const y = random(H);
    const length = random(3, 19);
    const angle = random(-0.25, 0.25) + (random() < 0.5 ? 0 : HALF_PI);
    ctx.strokeStyle = random() < 0.5
      ? "rgba(87,68,48,0.035)"
      : "rgba(255,250,235,0.06)";
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + cos(angle) * length, y + sin(angle) * length);
    ctx.stroke();
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);

  const ctx = drawingContext;
  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0, "rgb(7,10,15)");
  bg.addColorStop(0.55, "rgb(11,13,17)");
  bg.addColorStop(1, "rgb(15,12,14)");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  ambient(480, 1030, 720, "207,129,82", 0.040, 1.0, 1.25);
  ambient(1160, 1040, 720, "80,150,155", 0.042, 1.0, 1.25);
  ambient(seamX(1060), 1060, 540, "244,219,174", 0.075, 0.82, 1.65);

  const warm = [
    [222, 158, 78],
    [245, 207, 139],
    [204, 116, 102],
    [151, 94, 74],
    [183, 133, 91]
  ];
  const cool = [
    [88, 170, 165],
    [173, 214, 199],
    [133, 164, 205],
    [70, 105, 124],
    [105, 145, 151]
  ];

  makeSide(-1, warm);
  makeSide(1, cool);
  makeBridges();
  makeMotes();

  ctx.save();
  let vg = ctx.createRadialGradient(800, 980, 280, 800, 1000, 1280);
  vg.addColorStop(0, "rgba(2,3,6,0)");
  vg.addColorStop(0.68, "rgba(2,3,6,0.08)");
  vg.addColorStop(0.86, "rgba(2,3,6,0.28)");
  vg.addColorStop(1, "rgba(2,3,6,0.72)");
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  strokeWeight(1);
  for (let i = 0; i < 48000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.52) {
      stroke(255, 244, 224, random(2, 7));
    } else {
      stroke(0, 0, 0, random(3, 10));
    }
    point(x, y);
  }

  noLoop();
}

function seamX(y) {
  return 800 + 135 * sin(y * 0.00155 + 0.55) + 62 * sin(y * 0.0039 + 2.1);
}

function seamH(y) {
  const t = abs(y - 1060) / 1060;
  return 34 + 250 * pow(min(t, 1.2), 1.45);
}

function fadeAt(x, y) {
  const f = min(
    (x - 50) / 260,
    (1550 - x) / 260,
    (y - 50) / 300,
    (1950 - y) / 300,
    1
  );
  return constrain(f, 0, 1);
}

function ambient(x, y, r, rgb, alpha, sx, sy) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(sx, sy);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
  g.addColorStop(0, "rgba(" + rgb + "," + alpha + ")");
  g.addColorStop(0.48, "rgba(" + rgb + "," + alpha * 0.38 + ")");
  g.addColorStop(1, "rgba(" + rgb + ",0)");
  ctx.fillStyle = g;
  ctx.fillRect(-r, -r, r * 2, r * 2);
  ctx.restore();
}

function makeSide(side, palette) {
  const inward = side < 0 ? 1 : -1;
  const ivory = [248, 231, 196];

  for (let i = 0; i < 43000; i++) {
    const y = random(70, 1930);
    const c = seamX(y);
    const h = seamH(y);
    const edge = side < 0 ? c - h : c + h;

    let x;
    if (side < 0) {
      x = random(70, edge - 6);
    } else {
      x = random(edge + 6, 1530);
    }

    const d = abs(x - edge);
    const fade = fadeAt(x, y);
    const glow = exp(-d / 520);
    const accept = (0.16 + 0.84 * exp(-d / 560)) * pow(fade, 0.7);

    if (random() > accept) continue;

    let base = palette[floor(random(palette.length))];
    const mix = glow * 0.78;
    const r = lerp(base[0], ivory[0], mix);
    const g = lerp(base[1], ivory[1], mix);
    const b = lerp(base[2], ivory[2], mix);

    let alpha = (14 + 90 * glow) * random(0.5, 1.0) * (0.35 + 0.65 * fade);
    let weight = 0.65 + glow * 0.9 + random(0.4);
    let len = 22 + 95 * exp(-d / 560) + random(42);

    if (random() < 0.055) {
      len *= random(2.0, 3.4);
      alpha *= 0.55;
      weight *= 0.8;
    }

    const n = noise(
      x * 0.00135 + (side < 0 ? 0 : 11.7),
      y * 0.00135 + 4.2
    );
    let a = -HALF_PI + (n - 0.5) * 1.7;
    a += inward * (0.12 + 0.95 * exp(-d / 560));

    stroke(r, g, b, alpha);
    strokeWeight(weight);

    let px = x;
    let py = y;
    const steps = 4;
    const step = len / steps;

    for (let s = 0; s < steps; s++) {
      a += (noise(px * 0.004, py * 0.004 + 17.3) - 0.5) * 0.22;
      const nx = px + cos(a) * step;
      const ny = py + sin(a) * step;
      const boundary = side < 0
        ? seamX(ny) - seamH(ny) - 3
        : seamX(ny) + seamH(ny) + 3;

      if ((side < 0 && nx > boundary) || (side > 0 && nx < boundary)) break;
      line(px, py, nx, ny);
      px = nx;
      py = ny;
    }
  }
}

function makeBridges() {
  for (let i = 0; i < 104; i++) {
    let y0;
    if (random() < 0.65) {
      y0 = 1060 + randomGaussian() * 360;
    } else {
      y0 = random(240, 1760);
    }
    y0 = constrain(y0, 220, 1780);

    const y1 = y0 + random(-30, 30);
    const y2 = y0 + random(-110, 110);
    const x1 = seamX(y1) - seamH(y1) - random(4, 110);
    const x2 = seamX(y2) + seamH(y2) + random(4, 110);

    const dist = x2 - x1;
    const sag = 20 + dist * random(0.08, 0.22);
    const cx1 = lerp(x1, x2, 0.30);
    const cx2 = lerp(x1, x2, 0.70);
    const cy1 = y1 + sag;
    const cy2 = y2 + sag;

    const reached = random() < 0.68;
    const tEnd = reached ? 1 : random(0.38, 0.82);
    const important = random() < 0.10;
    const baseA = important ? random(62, 92) : random(18, 58);
    const tint = random();

    const r = lerp(241, 199, tint * 0.45);
    const g = lerp(222, 224, tint * 0.45);
    const b = lerp(190, 211, tint * 0.45);

    strokeWeight(important ? random(0.9, 1.25) : random(0.5, 1.0));

    let px = x1;
    let py = y1;
    const steps = 48;

    for (let j = 1; j <= steps; j++) {
      const t = tEnd * j / steps;
      const x = bezierPoint(x1, cx1, cx2, x2, t);
      const y = bezierPoint(y1, cy1, cy2, y2, t);
      const envelope = 0.38 + 0.62 * pow(sin(PI * t), 0.35);
      stroke(r, g, b, baseA * envelope);
      line(px, py, x, y);
      px = x;
      py = y;
    }

    if (!reached) {
      softDot(px, py, important ? 2.4 : 1.6, [247, 224, 181], 125);
    } else if (important) {
      softDot(x1, y1, 1.5, [245, 215, 169], 80);
      softDot(x2, y2, 1.5, [207, 231, 215], 80);
    }
  }
}

function makeMotes() {
  for (let i = 0; i < 330; i++) {
    let y;
    if (random() < 0.34) {
      y = 1060 + randomGaussian() * 320;
    } else {
      y = random(120, 1880);
    }
    if (y < 90 || y > 1910) continue;

    const c = seamX(y);
    const h = seamH(y);
    const x = c + randomGaussian() * h * 0.28;
    if (abs(x - c) > h * 0.66) continue;

    const near = exp(-abs(y - 1060) / 700);
    let r = random(0.7, 2.6);
    if (random() < 0.08) r = random(3.5, 5.3);

    const coolMote = random() < 0.18;
    const col = coolMote ? [215, 239, 229] : [255, 238, 205];
    const a = (60 + 135 * near) * random(0.55, 1);
    softDot(x, y, r, col, a);
  }

  softDot(seamX(1060), 1060, 4.2, [255, 235, 194], 185);
}

function softDot(x, y, r, col, a) {
  noStroke();
  fill(col[0], col[1], col[2], a * 0.022);
  circle(x, y, r * 11);
  fill(col[0], col[1], col[2], a * 0.045);
  circle(x, y, r * 6.4);
  fill(col[0], col[1], col[2], a * 0.11);
  circle(x, y, r * 3.3);
  fill(col[0], col[1], col[2], a);
  circle(x, y, r * 2);
}

// 《之间》—— 爱是两个存在之间多出来的那道光
// p5.js 1.11 · 1600×2000 · 静态一帧

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

// 暖的存在 / 冷的存在 / 它们之间的场
const A = { x: 560,  y: 900,  r: 292, seed: 3.7, wob: 0.12, freq: 0.5 };
const B = { x: 1080, y: 1060, r: 252, seed: 9.2, wob: 0.12, freq: 0.5 };
const M = { x: 820,  y: 980 };

function draw() {
  background(11, 7, 18);
  blendMode(ADD);

  // 深处的空间氛围
  radialGlow(M.x, M.y, 1000, color(34, 22, 50), 36);

  // 远近两层星尘
  starDust(120, 5, 16, 0.6, 1.3);
  starDust(44, 14, 42, 0.9, 1.8);

  // 暖的存在：外晕 → 心
  glowBlob(A, 380, color(64, 24, 44),     26, 26, 0.55);
  glowBlob(A, 330, color(196, 82, 88),    40, 24, 0.45);
  glowBlob(A, 300, color(242, 125, 92),   62, 22, 0.35);
  glowBlob(A, 210, color(255, 205, 165), 118, 18, 0.14);
  glowBlob(A, 120, color(255, 240, 224), 168, 14, 0.06);

  // 冷的存在：外晕 → 心
  glowBlob(B, 330, color(20, 52, 84),     24, 26, 0.55);
  glowBlob(B, 290, color(60, 120, 180),   38, 24, 0.45);
  glowBlob(B, 260, color(110, 170, 220),  60, 22, 0.35);
  glowBlob(B, 180, color(190, 230, 248), 115, 18, 0.14);
  glowBlob(B, 105, color(236, 250, 255), 165, 14, 0.06);

  // 形体内部：流动的丝与微尘（爱是活的）
  flowLines(A, color(255, 190, 150), 38, 9);
  flowLines(B, color(200, 235, 250), 36, 9);
  innerDust(A, color(255, 214, 180), 88, 110);
  innerDust(B, color(215, 240, 252), 82, 100);

  // 相向而流的光丝：给予与接受
  bondThreads();

  // 之间：无形体的场（正圆），全画最亮处
  radialGlow(M.x, M.y, 400, color(120, 84, 40),    51);
  radialGlow(M.x, M.y, 300, color(232, 180, 104),  87);
  radialGlow(M.x, M.y, 220, color(255, 222, 150), 140);
  radialGlow(M.x, M.y, 150, color(255, 242, 205), 217);
  radialGlow(M.x, M.y,  95, color(255, 252, 236), 255);

  // 之间发出的回响：不完整的环
  ripples();

  // 光尘：聚拢、升腾、沉降、沉入深处的倒影
  bondDust();
  risingDust();
  emberDust();
  reflection();

  // 收拢视线
  vignette();
}

// ---------- 径向光（正圆 = 场，没有边界） ----------
function radialGlow(x, y, r, c, aMax) {
  noStroke();
  let layers = 40;
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let rr = r * (0.14 + 0.86 * t);
    let a = aMax * pow(1 - t, 2.1);
    fill(c, a);
    ellipse(x, y, rr * 2, rr * 2);
  }
}

// ---------- 有机形体（有边界、会呼吸） ----------
function blobFactor(ang, seed, wob, freq) {
  let u = cos(ang) * freq + seed;
  let v = sin(ang) * freq + seed * 1.37;
  let n = 0.72 * noise(u, v) + 0.28 * noise(u * 2.7 + 41.3, v * 2.7 + 41.3);
  return 1 + wob * (n - 0.5) * 2; // 余弦/正弦输入保证形状闭合
}

function blobFill(o, R) {
  beginShape();
  let n = 140;
  for (let i = 0; i <= n; i++) {
    let ang = TWO_PI * i / n;
    let r = R * blobFactor(ang, o.seed, o.wob, o.freq);
    vertex(o.x + cos(ang) * r, o.y + sin(ang) * r);
  }
  endShape(CLOSE);
}

function blobPoint(o, ang) {
  let r = o.r * blobFactor(ang, o.seed, o.wob, o.freq);
  return { x: o.x + cos(ang) * r, y: o.y + sin(ang) * r };
}

function glowBlob(o, R, c, aMax, layers, rIn) {
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let rr = R * (rIn + (1 - rIn) * t);
    let a = aMax * pow(1 - t, 1.7);
    fill(c, a);
    blobFill(o, rr);
  }
}

// ---------- 星尘背景 ----------
function starDust(count, aMin, aMax, sMin, sMax) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let c = random() < 0.5 ? color(228, 222, 238) : color(238, 228, 218);
    fill(c, random(aMin, aMax));
    let s = random(sMin, sMax);
    ellipse(x, y, s, s);
  }
}

// ---------- 形体内部的流线 ----------
function flowLines(o, c, aBase, count) {
  noFill();
  strokeWeight(1.1);
  for (let i = 0; i < count; i++) {
    let a0 = random(TWO_PI);
    let a1 = a0 + PI + random(-0.9, 0.9);
    let r0 = o.r * random(0.3, 0.78);
    let r1 = o.r * random(0.3, 0.78);
    let p0x = o.x + cos(a0) * r0, p0y = o.y + sin(a0) * r0;
    let p1x = o.x + cos(a1) * r1, p1y = o.y + sin(a1) * r1;
    let mx = (p0x + p1x) / 2 + (noise(i * 3.3 + o.seed, o.seed) - 0.5) * o.r * 0.8;
    let my = (p0y + p1y) / 2 + (noise(o.seed, i * 2.9 + o.seed) - 0.5) * o.r * 0.8;
    stroke(c, aBase * random(0.35, 1.0));
    bezier(p0x, p0y,
           p0x + (mx - p0x) * 0.42, p0y + (my - p0y) * 0.42,
           p1x + (mx - p1x) * 0.42, p1y + (my - p1y) * 0.42,
           p1x, p1y);
  }
}

// ---------- 形体内部微尘 ----------
function innerDust(o, c, aMax, count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let rr = o.r * pow(random(), 0.62);
    let al = aMax * (1 - rr / o.r) * random(0.25, 1.0);
    fill(c, al);
    let s = random(0.8, 2.2);
    ellipse(o.x + cos(a) * rr, o.y + sin(a) * rr, s, s);
  }
}

// ---------- 两体之间的光丝 ----------
function bondThreads() {
  noFill();
  let dir = atan2(B.y - A.y, B.x - A.x);
  let nx = -sin(dir), ny = cos(dir);
  for (let i = 0; i < 24; i++) {
    let t = -0.9 + 1.8 * (i / 23) + random(-0.04, 0.04);
    let pA = blobPoint(A, dir + t * 0.62);
    let pB = blobPoint(B, dir + PI - t * 0.62);
    let bend = t * 78 + (noise(i * 5.7, 7.1) - 0.5) * 70;
    let c1x = pA.x + (M.x - pA.x) * 0.42 + nx * bend;
    let c1y = pA.y + (M.y - pA.y) * 0.42 + ny * bend;
    let c2x = pB.x + (M.x - pB.x) * 0.42 + nx * bend;
    let c2y = pB.y + (M.y - pB.y) * 0.42 + ny * bend;
    let c = (i % 2 === 0) ? color(255, 196, 150) : color(170, 214, 236);
    let a = 9 + 22 * pow(1 - abs(t), 1.6);
    if (i < 3) a += 14;
    stroke(c, a);
    strokeWeight(random(0.8, 1.5));
    bezier(pA.x, pA.y, c1x, c1y, c2x, c2y, pB.x, pB.y);
  }
  // 自之间升起的三缕
  for (let k = 0; k < 3; k++) {
    let sx = M.x + (k - 1) * 76 + random(-18, 18);
    let sy = M.y - 40 + random(-24, 24);
    let ex = M.x + (random() - 0.5) * 380;
    let ey = 150 + random(80);
    stroke(255, 238, 205, 9 + random(7));
    strokeWeight(1);
    bezier(sx, sy,
           sx + (random() - 0.5) * 200, sy - 280,
           ex + (random() - 0.5) * 200, ey + 240,
           ex, ey);
  }
}

// ---------- 之间的回响环 ----------
function ripples() {
  noFill();
  let radii = [42, 66, 110, 158, 212, 272];
  let baseA = [70, 92, 74, 56, 42, 28];
  for (let k = 0; k < radii.length; k++) {
    stroke(255, 233, 187, baseA[k]);
    strokeWeight(1.6 - k * 0.13);
    if (k === 0) {
      arc(M.x, M.y, radii[k] * 2, radii[k] * 2, 0, TWO_PI);
    } else {
      for (let s = 0; s < 2; s++) {
        let st = random(TWO_PI);
        let len = random(0.3, 0.6);
        arc(M.x, M.y, radii[k] * 2, radii[k] * 2, st, st + len * TWO_PI);
      }
    }
  }
}

// ---------- 之间聚集的光尘与微星 ----------
function bondDust() {
  noStroke();
  for (let i = 0; i < 620; i++) {
    let gx = (random() + random() + random() - 1.5) / 1.5;
    let gy = (random() + random() + random() - 1.5) / 1.5;
    let px = M.x + gx * 300;
    let py = M.y + gy * 260;
    let d2 = pow((px - M.x) / 300, 2) + pow((py - M.y) / 260, 2);
    let fall = exp(-d2 * 2.0);
    let a = fall * (5 + random() * 32);
    let c = random() < 0.7 ? color(255, 244, 214) : color(220, 236, 244);
    fill(c, a);
    let s = 0.8 + random() * 1.8 + fall * 1.3;
    ellipse(px, py, s, s);
  }
  strokeCap(ROUND);
  for (let i = 0; i < 26; i++) {
    let gx = (random() + random() + random() - 1.5) / 1.5 * 0.8;
    let gy = (random() + random() + random() - 1.5) / 1.5 * 0.8;
    let px = M.x + gx * 250;
    let py = M.y + gy * 220;
    let L = random(4, 13);
    let a = random(35, 105);
    stroke(255, 250, 232, a);
    strokeWeight(0.9);
    line(px - L, py, px + L, py);
    line(px, py - L * 0.7, px, py + L * 0.7);
    noStroke();
    fill(255, 252, 240, a);
    ellipse(px, py, 1.8, 1.8);
  }
}

// ---------- 向上升腾的光尘 ----------
function risingDust() {
  noStroke();
  for (let i = 0; i < 240; i++) {
    let gx = (random() + random() + random() - 1.5) / 1.5;
    let h = pow(random(), 0.72);
    let py = 930 - h * 690;
    let px = M.x + gx * (150 + h * 150);
    let a = (1 - h * 0.55) * random(3, 18);
    let c = random() < 0.55 ? color(245, 228, 196) : color(206, 228, 238);
    fill(c, a);
    let s = random(0.7, 1.9);
    ellipse(px, py, s, s);
  }
}

// ---------- 向下沉降的余烬 ----------
function emberDust() {
  noStroke();
  for (let i = 0; i < 210; i++) {
    let d = pow(random(), 1.35);
    let py = 1360 + d * 570;
    let gx = (random() + random() + random() - 1.5) / 1.5;
    let px = M.x + gx * (95 + d * 340);
    let a = (1 - d * 0.75) * random(3, 20);
    let c = random() < 0.75 ? color(255, 158, 98) : color(255, 214, 160);
    fill(c, a);
    let s = random(0.7, 2.1);
    ellipse(px, py, s, s);
  }
}

// ---------- 深处水面上的一点倒影 ----------
function reflection() {
  noStroke();
  for (let i = 16; i >= 1; i--) {
    let t = i / 16;
    let w = 34 + 300 * t;
    let a = 13 * pow(1 - t, 2.2);
    fill(255, 236, 196, a);
    ellipse(M.x, 1798, w, w * 0.2);
  }
  strokeCap(ROUND);
  for (let k = 0; k < 4; k++) {
    let y = 1774 + k * 16 + random(-3, 3);
    let half = 95 - k * 15 + random(25);
    stroke(255, 230, 180, 15 - k * 3);
    strokeWeight(1);
    line(M.x - half, y, M.x + half, y);
  }
}

// ---------- 暗角 ----------
function vignette() {
  blendMode(BLEND);
  let ctx = drawingContext;
  ctx.save();
  let g = ctx.createRadialGradient(800, 990, 430, 800, 990, 1500);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.7, 'rgba(4,3,10,0.14)');
  g.addColorStop(1, 'rgba(4,3,10,0.5)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

// 之间有光 —— 两个存在相遇时，世界多出来的那一部分

let cA, cB, RA, RB;
let polyA, polyB;
let ovC;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(6, 8, 14);

  // ---------- 两个存在的几何 ----------
  cA = { x: 540, y: 720 };   RA = 345;
  cB = { x: 1060, y: 1320 }; RB = 365;
  const towardB = atan2(cB.y - cA.y, cB.x - cA.x);
  const towardA = atan2(cA.y - cB.y, cA.x - cB.x);
  polyA = makeBlob(cA, RA, 3.7, towardB, 0.42);
  polyB = makeBlob(cB, RB, 11.9, towardA, 0.42);
  ovC = findOverlap();

  // ---------- 深处的夜 ----------
  noStroke();
  for (let y = 0; y < height; y += 10) {
    const t = y / height;
    fill(lerp(9, 24, t), lerp(12, 13, t), lerp(22, 10, t));
    rect(0, y, width, 10.5);
  }
  for (let i = 0; i < 820; i++) {
    fill(215, 224, 244, random(6, 52));
    circle(random(width), random(height), random(0.7, 1.9));
  }
  for (let i = 0; i < 16; i++) {
    const sx = random(width), sy = random(height);
    for (let k = 0; k < 4; k++) {
      fill(236, 240, 252, 24 - k * 6);
      circle(sx, sy, 3 + k * 4.5);
    }
  }

  // 相遇将发生的地方，夜色先暖了一点
  blendMode(ADD);
  for (let k = 0; k < 26; k++) {
    fill(255, 198, 142, 2);
    circle(ovC.x, ovC.y, lerp(1760, 470, k / 25));
  }

  // ---------- 两个存在的身体 ----------
  blendMode(BLEND);
  drawLayers(polyA, cA, [58, 14, 28], [255, 132, 84]);
  drawLayers(polyB, cB, [10, 34, 56], [84, 216, 208]);

  // 各自的内心之光
  blendMode(ADD);
  heartGlow(cA, 290, [255, 118, 66], [255, 196, 132]);
  heartGlow(cB, 310, [58, 198, 198], [168, 242, 236]);

  // ---------- 各自的粒子（相遇区除外） ----------
  scatter(cA, RA, polyA, polyB, 5.0, [255, 176, 122], [232, 96, 72], [128, 26, 46], 11500);
  scatter(cB, RB, polyB, polyA, 9.0, [150, 236, 228], [56, 150, 176], [14, 44, 78], 11500);

  // ---------- 相遇：第三种颜色 ----------
  goldParticles();
  coreGlow();

  // ---------- 伸向彼此 ----------
  tendrils(polyA, cA, 8.1, [255, 158, 104], 26);
  tendrils(polyB, cB, 4.4, [126, 224, 216], 26);

  // ---------- 溢出的微光 ----------
  embers();

  // ---------- 暗角与颗粒 ----------
  blendMode(BLEND);
  postProcess();
}

// 有机形状：噪声轮廓，朝向对方的一侧伸展，背侧收拢
function makeBlob(c, R, off, toward, stretch) {
  const pts = [];
  const N = 260;
  for (let i = 0; i < N; i++) {
    const a = (i / N) * TAU;
    const u = cos(a), v = sin(a);
    const n1 = noise(u * 1.1 + off, v * 1.1 + off * 1.7);
    const n2 = noise(u * 2.7 + off * 2.3, v * 2.7 - off * 0.9);
    let r = R * (0.66 + 0.52 * n1 + 0.20 * n2);
    const to = pow(max(cos(angDiff(a, toward)), 0), 1.6);
    r *= 1 + stretch * to * (0.8 + 0.5 * noise(u * 1.8 + off * 3.1, v * 1.8 - off));
    const away = pow(max(cos(angDiff(a, toward + PI)), 0), 2);
    r *= 1 - 0.14 * away;
    pts.push([c.x + u * r, c.y + v * r]);
  }
  return pts;
}

function angDiff(a, b) {
  let d = (a - b) % TAU;
  if (d > PI) d -= TAU;
  else if (d < -PI) d += TAU;
  return d;
}

function inPoly(pts, x, y) {
  let inside = false;
  const n = pts.length;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const yi = pts[i][1], yj = pts[j][1];
    if ((yi > y) !== (yj > y)) {
      const xi = pts[i][0], xj = pts[j][0];
      if (x < (xj - xi) * (y - yi) / (yj - yi) + xi) inside = !inside;
    }
  }
  return inside;
}

// 重叠区（“之间”）的质心与半径
function findOverlap() {
  const x0 = max(cA.x - RA * 1.5, cB.x - RB * 1.5);
  const x1 = min(cA.x + RA * 1.5, cB.x + RB * 1.5);
  const y0 = max(cA.y - RA * 1.5, cB.y - RB * 1.5);
  const y1 = min(cA.y + RA * 1.5, cB.y + RB * 1.5);
  const pts = [];
  for (let i = 0; i < 9000 && pts.length < 6000; i++) {
    const x = random(x0, x1), y = random(y0, y1);
    if (inPoly(polyA, x, y) && inPoly(polyB, x, y)) pts.push([x, y]);
  }
  if (pts.length < 40) {
    return { x: (cA.x + cB.x) / 2, y: (cA.y + cB.y) / 2, r: 140 };
  }
  let sx = 0, sy = 0;
  for (const p of pts) { sx += p[0]; sy += p[1]; }
  const cx = sx / pts.length, cy = sy / pts.length;
  let m = 0;
  for (const p of pts) m += dist(p[0], p[1], cx, cy);
  return { x: cx, y: cy, r: constrain((m / pts.length) * 1.5, 90, 300) };
}

// 柔和的体积底：由外向内逐层提亮
function drawLayers(pts, c, out, inn) {
  const n = 36;
  noStroke();
  for (let k = 0; k < n; k++) {
    const t = k / (n - 1);
    const s = lerp(1.16, 0.06, t);
    const e = pow(t, 1.4);
    fill(lerp(out[0], inn[0], e), lerp(out[1], inn[1], e), lerp(out[2], inn[2], e), 5);
    beginShape();
    for (let i = 0; i < pts.length; i++) {
      vertex(c.x + (pts[i][0] - c.x) * s, c.y + (pts[i][1] - c.y) * s);
    }
    endShape(CLOSE);
  }
}

// 每个存在自身的一点微光
function heartGlow(c, rMax, col, core) {
  noStroke();
  for (let k = 0; k < 34; k++) {
    const t = k / 33;
    fill(lerp(col[0], core[0], t), lerp(col[1], core[1], t), lerp(col[2], core[2], t),
         lerp(2, 15, t * t));
    circle(c.x, c.y, lerp(rMax * 2, 30, pow(t, 1.5)));
  }
}

// 各自的粒子云，带噪声团絮纹理；排除相遇区
function scatter(c, R, poly, other, off, inner, mid, outer, n) {
  noStroke();
  const span = R * 1.45;
  for (let i = 0; i < n; i++) {
    let x = 0, y = 0, ok = false;
    for (let t = 0; t < 60; t++) {
      x = c.x + random(-span, span);
      y = c.y + random(-span, span);
      if (inPoly(poly, x, y) && !inPoly(other, x, y)) { ok = true; break; }
    }
    if (!ok) continue;
    const tex = noise(x * 0.0035 + off, y * 0.0035 + off * 0.6);
    if (random() > 0.3 + tex * 0.9) continue;
    const t = constrain(dist(x, y, c.x, c.y) / (R * 1.2), 0, 1);
    let r, g, b;
    if (t < 0.45) {
      const k = t / 0.45;
      r = lerp(inner[0], mid[0], k);
      g = lerp(inner[1], mid[1], k);
      b = lerp(inner[2], mid[2], k);
    } else {
      const k = (t - 0.45) / 0.55;
      r = lerp(mid[0], outer[0], k);
      g = lerp(mid[1], outer[1], k);
      b = lerp(mid[2], outer[2], k);
    }
    fill(r, g, b, 9 + 25 * pow(1 - t, 1.6));
    circle(x, y, 3.5 + 7 * (1 - t) + random(0, 3));
  }
}

// 金色：只在两者重叠处存在，属于“之间”
function goldParticles() {
  noStroke();
  const x0 = max(cA.x - RA * 1.5, cB.x - RB * 1.5);
  const x1 = min(cA.x + RA * 1.5, cB.x + RB * 1.5);
  const y0 = max(cA.y - RA * 1.5, cB.y - RB * 1.5);
  const y1 = min(cA.y + RA * 1.5, cB.y + RB * 1.5);
  const target = 9000;
  let n = 0;
  for (let i = 0; i < 30000 && n < target * 0.65; i++) {
    const x = random(x0, x1), y = random(y0, y1);
    if (!inPoly(polyA, x, y) || !inPoly(polyB, x, y)) continue;
    const tex = noise(x * 0.0035 + 13.0, y * 0.0035 + 13.0);
    if (random() > 0.3 + tex * 0.9) continue;
    n++;
    paintGold(x, y);
  }
  while (n < target) {
    const a = random(TAU);
    const rr = ovC.r * 1.3 * pow(random(), 0.6);
    n++;
    paintGold(ovC.x + cos(a) * rr, ovC.y + sin(a) * rr);
  }
}

function paintGold(x, y) {
  const t = constrain(dist(x, y, ovC.x, ovC.y) / (ovC.r * 1.25), 0, 1);
  fill(255, lerp(248, 196, t), lerp(224, 110, t), 4 + 13 * pow(1 - t, 1.6));
  circle(x, y, 3.5 + 9 * pow(1 - t, 1.2) + random(0, 3.5));
}

// 相遇之处的光核
function coreGlow() {
  noStroke();
  for (let k = 0; k < 46; k++) {
    const t = k / 45;
    fill(255, lerp(214, 250, t), lerp(140, 235, t), lerp(3, 24, t * t));
    circle(ovC.x, ovC.y, lerp(ovC.r * 5.2, 28, pow(t, 1.5)));
  }
  for (let k = 0; k < 20; k++) {
    const t = k / 19;
    fill(255, 253, 244, lerp(4, 30, t * t));
    circle(ovC.x, ovC.y, lerp(ovC.r * 1.6, 10, pow(t, 1.2)));
  }
}

// 丝线：从边界朝对方生长，在光里渐渐消融
function tendrils(poly, c, off, col, n) {
  strokeCap(ROUND);
  const dCT = dist(c.x, c.y, ovC.x, ovC.y);
  for (let i = 0; i < n; i++) {
    let p = poly[floor(random(poly.length))];
    for (let t2 = 0; t2 < 7; t2++) {
      if (dist(p[0], p[1], ovC.x, ovC.y) <= dCT) break;
      p = poly[floor(random(poly.length))];
    }
    const tx = ovC.x + random(-200, 200);
    const ty = ovC.y + random(-180, 180);
    let x = p[0], y = p[1];
    let heading = atan2(ty - y, tx - x) + random(-0.3, 0.3);
    const steps = floor(random(12, 30));
    const stepLen = random(9, 15);
    for (let s = 0; s < steps; s++) {
      const k = s / steps;
      heading += (noise(x * 0.005 + off, y * 0.005 + off * 2) - 0.5) * 0.6 + random(-0.08, 0.08);
      heading += angDiff(atan2(ty - y, tx - x), heading) * 0.07;
      const nx = x + cos(heading) * stepLen;
      const ny = y + sin(heading) * stepLen;
      stroke(col[0], col[1], col[2], 8 + 115 * (1 - k));
      strokeWeight(lerp(2.6, 0.25, k));
      line(x, y, nx, ny);
      x = nx; y = ny;
      if (dist(x, y, tx, ty) < 16) break;
    }
  }
  noStroke();
}

// 从相遇处升起、飘散的微光
function embers() {
  noStroke();
  for (let i = 0; i < 160; i++) {
    let stR;
    if (random() < 0.6) stR = random(8, ovC.r * 1.1);
    else stR = random(ovC.r, 620);
    const baseAng = random(TAU);
    let x = ovC.x + cos(baseAng) * stR;
    let y = ovC.y + sin(baseAng) * stR;
    let ang;
    const r0 = random();
    if (r0 < 0.55) ang = -HALF_PI + random(-1.0, 1.0);
    else if (r0 < 0.82) ang = random(TAU);
    else ang = HALF_PI + random(-0.6, 0.6);
    const segs = floor(random(3, 8));
    const segLen = random(12, 32);
    for (let s = 0; s < segs; s++) {
      ang += random(-0.16, 0.16);
      x += cos(ang) * segLen;
      y += sin(ang) * segLen;
      const k = s / segs;
      fill(255, 228, 170, 8 + 92 * (1 - k));
      circle(x, y, lerp(3.2, 0.8, k));
    }
  }
}

// 暗角与胶片颗粒（逐像素）
function postProcess() {
  loadPixels();
  const cx = width / 2, cy = height / 2;
  const gtab = new Float32Array(8192);
  for (let i = 0; i < 8192; i++) gtab[i] = random();
  const d = pixels;
  for (let y = 0; y < height; y++) {
    const dy = y - cy;
    for (let x = 0; x < width; x++) {
      const dx = x - cx;
      const dd = Math.sqrt(dx * dx + dy * dy);
      let f = (dd - 640) / 560;
      f = f < 0 ? 0 : (f > 1 ? 1 : f);
      const v = 1 - f * f * 0.55;
      const i = (y * width + x) * 4;
      const g = (gtab[(i >> 2) & 8191] - 0.5) * 14;
      d[i]     = d[i]     * v + g;
      d[i + 1] = d[i + 1] * v + g;
      d[i + 2] = d[i + 2] * v + g;
    }
  }
  updatePixels();
}

// 《之间》——爱本身
// 两个完整的存在，自愿跨越界线向彼此奔赴；
// 光诞生于“之间”，升腾，又落下成为尘埃。

let A, B, M;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  // 左侧：温热的存在；右侧：清冷的存在。平等，但从不相同。
  A = { x: 560,  y: 950,  r: 255,
        deep: [150, 22, 18],  mid: [255, 82, 58],
        bright: [255, 158, 106], white: [255, 228, 196] };
  B = { x: 1040, y: 1010, r: 235,
        deep: [10, 70, 108],  mid: [55, 186, 255],
        bright: [136, 238, 232], white: [212, 244, 255] };
  M = { x: 800, y: 980 }; // “之间”
}

function draw() {
  background(9, 5, 10);
  blendMode(ADD);

  // ---- 远空的暗云与微尘 ----
  for (let i = 0; i < 10; i++) {
    const x = random(width);
    const y = random(height * 0.8);
    const r = 320 + random(520);
    const warm = random() < 0.55;
    softOrb(x, y, r, warm ? [58, 22, 20] : [12, 32, 52], 0.032);
  }
  noStroke();
  for (let i = 0; i < 240; i++) {
    fill(255, 242, 228, 6 + random(14));
    circle(random(width), random(height), 0.6 + random(0.9));
  }

  // ---- 两个存在的大光晕 ----
  softOrb(A.x, A.y, 730, A.deep, 0.09);
  softOrb(A.x, A.y, 410, A.mid, 0.09);
  softOrb(B.x, B.y, 690, B.deep, 0.09);
  softOrb(B.x, B.y, 380, B.mid, 0.09);

  // ---- 界线：不吞噬，但可以跨越 ----
  boundaryRing(A);
  boundaryRing(B);

  // ---- 身体：全向伸展的自身 ----
  bodyStrands(A);
  bodyStrands(B);

  // ---- 奔赴：伸向“之间”的长丝 ----
  reachStrands(A, B);
  reachStrands(B, A);

  // ---- 核心：自我仍在 ----
  coreFuzz(A);
  coreFuzz(B);
  softOrb(A.x, A.y, 150, A.mid, 0.3);
  softOrb(A.x, A.y, 70, A.bright, 0.55);
  softOrb(A.x, A.y, 26, A.white, 0.9);
  softOrb(B.x, B.y, 140, B.mid, 0.3);
  softOrb(B.x, B.y, 64, B.bright, 0.55);
  softOrb(B.x, B.y, 24, B.white, 0.9);

  // ---- “之间”的光 ----
  ellipseOrb(M.x, M.y, 330, [255, 228, 196], 0.17, 1.35, 0.9);
  ellipseOrb(M.x, M.y, 195, [255, 240, 214], 0.34, 1.15, 0.95);
  ellipseOrb(M.x, M.y, 105, [255, 250, 236], 0.55, 1, 1);
  ellipseOrb(M.x, M.y, 44, [255, 255, 250], 0.95, 1, 1);

  sparks();
  crossStars();

  // ---- 升腾 ----
  ellipseOrb(M.x, M.y - 300, 700, [255, 240, 214], 0.07, 0.17, 1);
  ellipseOrb(M.x, M.y - 250, 560, [255, 246, 226], 0.08, 0.09, 1);

  // ---- 落下：尘埃 ----
  fallingDust();

  // ---- 大地余晖 ----
  ellipseOrb(800, 1952, 560, [255, 228, 188], 0.10, 1.5, 0.1);
  ellipseOrb(800, 1958, 300, [255, 244, 220], 0.12, 1.9, 0.08);

  // ---- 暗角 ----
  blendMode(BLEND);
  const ctx = drawingContext;
  const vg = ctx.createRadialGradient(800, 1000, 520, 800, 1000, 1330);
  vg.addColorStop(0, 'rgba(4,2,6,0)');
  vg.addColorStop(0.55, 'rgba(4,2,6,0.08)');
  vg.addColorStop(1, 'rgba(4,2,6,0.6)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

// ---------- 工具 ----------

function gauss() { // 确定性的近似正态（仅依赖 random()）
  return (random() + random() + random() +
          random() + random() + random() - 3) * 1.414;
}

function rgba(c, a) {
  const al = constrain(a, 0, 1);
  return 'rgba(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ',' + al + ')';
}

function ellipseOrb(x, y, r, c, a, sx, sy) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(sx, sy);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
  g.addColorStop(0, rgba(c, a));
  g.addColorStop(0.35, rgba(c, a * 0.5));
  g.addColorStop(0.7, rgba(c, a * 0.16));
  g.addColorStop(1, rgba(c, 0));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function softOrb(x, y, r, c, a) { ellipseOrb(x, y, r, c, a, 1, 1); }

// 一缕光丝：从根到梢渐亮，抵达时消融于光
function strand(x0, y0, x1, y1, cRoot, cTip, w, a, bend) {
  const ctx = drawingContext;
  const dx = x1 - x0, dy = y1 - y0;
  const L = Math.max(1, Math.hypot(dx, dy));
  const nx = -dy / L, ny = dx / L;
  const phase = random(0, 1000);
  const amp = (0.12 + random() * 0.32) * L * bend;
  const g = ctx.createLinearGradient(x0, y0, x1, y1);
  g.addColorStop(0, rgba(cRoot, a * 0.55));
  g.addColorStop(0.45, rgba(cRoot, a));
  g.addColorStop(0.8, rgba(cTip, a * 0.85));
  g.addColorStop(1, rgba(cTip, 0));
  ctx.strokeStyle = g;
  ctx.lineWidth = w;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  const n = 52;
  for (let i = 1; i <= n; i++) {
    const t = i / n;
    const env = Math.sin(Math.PI * t);
    const bx = x0 + dx * t;
    const by = y0 + dy * t;
    const o1 = (noise(bx * 0.0014, by * 0.0014, phase) - 0.5) * 2;
    const o2 = (noise(phase * 0.37, bx * 0.005, by * 0.005) - 0.5) * 2;
    const off = (o1 * amp + o2 * amp * 0.3) * env;
    ctx.lineTo(bx + nx * off, by + ny * off);
  }
  ctx.stroke();
}

// ---------- 组成部分 ----------

// 界线：一圈断续的、微微起伏的细环
function boundaryRing(C) {
  const ctx = drawingContext;
  const ph = random(1000);
  ctx.lineCap = 'round';
  ctx.lineWidth = 1;
  const n = 240;
  const seg = (Math.PI * 2) / n;
  for (let i = 0; i < n; i++) {
    if (random() < 0.18) continue;
    const a0 = i * seg;
    const a1 = a0 + seg * 1.7;
    ctx.strokeStyle = rgba(C.bright, 0.08 + random() * 0.14);
    ctx.beginPath();
    for (let s = 0; s <= 4; s++) {
      const aa = lerp(a0, a1, s / 4);
      const rr = C.r + (noise(Math.cos(aa) * 0.8 + 1.7,
                              Math.sin(aa) * 0.8 + 1.7, ph) - 0.5) * 72;
      const x = C.x + Math.cos(aa) * rr;
      const y = C.y + Math.sin(aa) * rr;
      if (s === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

// 身体：从核心向四方生长的暗丝，略偏向对方
function bodyStrands(C) {
  const toM = Math.atan2(M.y - C.y, M.x - C.x);
  for (let i = 0; i < 720; i++) {
    let ang;
    if (random() < 0.62) ang = toM + random(-1.9, 1.9);
    else ang = random(Math.PI * 2);
    const r0 = random(C.r * 0.32);
    const x0 = C.x + Math.cos(ang) * r0;
    const y0 = C.y + Math.sin(ang) * r0;
    let len = 40 + Math.abs(gauss()) * 190;
    if (len > 500) len = 500;
    const x1 = x0 + Math.cos(ang) * len;
    const y1 = y0 + Math.sin(ang) * len;
    strand(x0, y0, x1, y1, C.deep, C.mid,
           0.6 + random() * 1.5, 0.03 + random() * 0.07, 0.7);
  }
}

// 奔赴：千万缕自身伸向“之间”
function reachStrands(C, O) {
  for (let i = 0; i < 1150; i++) {
    const ang = random(Math.PI * 2);
    const rr = C.r * 0.6 * Math.sqrt(random());
    const x0 = C.x + Math.cos(ang) * rr;
    const y0 = C.y + Math.sin(ang) * rr;
    const wide = i >= 520;
    const x1 = M.x + gauss() * (wide ? 210 : 115);
    const y1 = M.y + gauss() * (wide ? 150 : 80);
    strand(x0, y0, x1, y1, C.mid, C.bright,
           0.6 + random() * random() * 2.1, 0.028 + random() * 0.085, 0.55);
  }
  // 少数几缕走得更远：轻轻伸入对方的世界
  for (let i = 0; i < 70; i++) {
    const f = 0.52 + random() * 0.24;
    const ang = random(Math.PI * 2);
    const rr = C.r * 0.45 * Math.sqrt(random());
    const x0 = C.x + Math.cos(ang) * rr;
    const y0 = C.y + Math.sin(ang) * rr;
    const x1 = lerp(C.x, O.x, f) + gauss() * 55;
    const y1 = lerp(C.y, O.y, f) + gauss() * 45;
    strand(x0, y0, x1, y1, C.bright, C.white,
           0.5 + random() * 1.1, 0.02 + random() * 0.05, 0.5);
  }
}

// 核心周围的绒光，像心跳
function coreFuzz(C) {
  for (let i = 0; i < 240; i++) {
    const ang = random(Math.PI * 2);
    const r0 = random(C.r * 0.45);
    const len = 8 + random(56);
    const x0 = C.x + Math.cos(ang) * r0;
    const y0 = C.y + Math.sin(ang) * r0;
    const a2 = ang + random(-0.3, 0.3);
    strand(x0, y0, x0 + Math.cos(a2) * len, y0 + Math.sin(a2) * len,
           C.bright, C.white, 0.8 + random() * 0.8,
           0.10 + random() * 0.2, 0.2);
  }
}

// “之间”迸出的星屑
function sparks() {
  noStroke();
  for (let i = 0; i < 120; i++) {
    const x = M.x + gauss() * 135;
    const y = M.y + gauss() * 95;
    let c = [255, 246, 228];
    const u = random();
    if (u < 0.24) c = [255, 152, 118];
    else if (u < 0.48) c = [148, 234, 255];
    fill(c[0], c[1], c[2], 130 + random(110));
    circle(x, y, 0.8 + random() * 1.9);
  }
}

function crossStars() {
  for (let i = 0; i < 22; i++) {
    const x = M.x + gauss() * 150;
    const y = M.y + gauss() * 110;
    const L = 5 + random() * 14;
    stroke(255, 248, 235, 55 + random(85));
    strokeWeight(0.8);
    line(x - L, y, x + L, y);
    line(x, y - L, x, y + L);
    noStroke();
    fill(255, 252, 244, 190);
    circle(x, y, 1.6);
  }
}

// 光落下，化作尘埃，飘散向大地
function fallingDust() {
  noStroke();
  for (let i = 0; i < 160; i++) {
    const t = Math.pow(random(), 0.85);
    const y = lerp(M.y + 170, 1905, t);
    const spread = 60 + t * 500;
    const x = M.x + gauss() * spread * 0.55;
    const s = (0.9 + random() * 2.4) * (1 - 0.3 * t);
    const a = (190 - t * 110) * (0.5 + random() * 0.5);
    let c = [255, 240, 206];
    const u = random();
    if (u < 0.16) c = [255, 198, 128];
    else if (u < 0.28) c = [255, 150, 118];
    else if (u < 0.40) c = [150, 226, 250];
    fill(c[0], c[1], c[2], a);
    circle(x, y, s);
    if (random() < 0.32) {
      stroke(c[0], c[1], c[2], 16);
      strokeWeight(0.7);
      const tl = 8 + random(26);
      line(x, y, x + random(-7, 7), y - tl);
      noStroke();
    }
  }
}

// 《之间》——爱本身：两个光体之间生长、编织、扎根、升腾的关系
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  // 结构：两个光体 A、B，以及它们"之间"的核心 C
  const A = { x: 560, y: 660 };
  const B = { x: 1040, y: 1020 };
  const C = { x: 800, y: 840 };

  drawBackgroundTexture();   // 深空底色
  drawDustFar(C);            // 远处被牵引的光尘
  drawRoots(C);              // 向下扎根的须
  drawLightBody(A, 0);       // 金色光体
  drawLightBody(B, 1);       // 珊瑚光体
  drawStrands(A, C, [234, 176, 96]);  // 从A长向核心的千万条线
  drawStrands(B, C, [222, 116, 120]); // 从B长向核心的千万条线
  drawWeave(C);              // 核心处的交织
  drawRising(C);             // 向上升腾的呼吸
  drawCoreGlow(C);           // 核心之光
  drawOrbitArcs(C);          // 环抱一切的弧
  drawDustNear(C);           // 近处的星尘
  drawGrain();               // 颗粒
  drawVignette();            // 暗角
}

// ---------- 背景：带噪声的深空 ----------
function drawBackgroundTexture() {
  background(17, 13, 26);
  noStroke();
  for (let i = 0; i < 2600; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.0016, y * 0.0016);
    fill(12 + n * 16, 9 + n * 12, 24 + n * 30, random(7, 18));
    ellipse(x, y, random(30, 90), random(30, 90));
  }
  // 底部：温暖的沉积，暗示泥土
  for (let i = 0; i < 900; i++) {
    fill(44, 27, 24, random(4, 10));
    ellipse(random(width), random(1450, height), random(40, 130), random(30, 90));
  }
}

// ---------- 两个光体 ----------
function drawLightBody(P, which) {
  noStroke();
  const outer = which === 0 ? [58, 40, 18] : [56, 20, 26];
  const core  = which === 0 ? [255, 232, 196] : [255, 213, 205];
  const midC  = which === 0 ? [186, 124, 54] : [170, 72, 80];
  const R = 280;

  // 有机光晕：多层半透明椭圆，带轻微偏移，像呼吸
  for (let i = 58; i >= 1; i--) {
    const t = i / 58;
    const rr = R * Math.pow(t, 1.4);
    const mix = Math.pow(1 - t, 1.35);
    fill(
      lerp(outer[0], core[0], mix),
      lerp(outer[1], core[1], mix),
      lerp(outer[2], core[2], mix),
      4 + (1 - t) * 14
    );
    ellipse(P.x + random(-4, 4), P.y + random(-4, 4), rr * 2, rr * 2);
  }
  // 亮芯
  for (let i = 12; i >= 1; i--) {
    const t = i / 12;
    const rr = 56 * Math.pow(t, 1.1);
    fill(core[0], core[1], core[2], 10 + (1 - t) * 36);
    ellipse(P.x + random(-3, 3), P.y + random(-3, 3), rr * 2, rr * 2);
  }
  fill(core[0], core[1], core[2], 205);
  ellipse(P.x, P.y, 34, 34);
  // 涟漪弧
  noFill();
  for (let k = 0; k < 3; k++) {
    stroke(midC[0], midC[1], midC[2], random(15, 30));
    strokeWeight(random(0.8, 1.4));
    const rr = R * random(0.45, 0.8);
    const st = random(TWO_PI);
    arc(P.x, P.y, rr * 2, rr * 2, st, st + random(1.4, 3.2));
  }
  noStroke();
}

// ---------- 从光体长向核心的线 ----------
function drawStrands(S, C, colLine) {
  const warm = [255, 240, 214];
  const baseAng = Math.atan2(C.y - S.y, C.x - S.x);
  for (let i = 0; i < 210; i++) {
    const a = baseAng + random(-0.9, 0.9);
    const r0 = random(70, 180);
    const sx = S.x + Math.cos(a) * r0;
    const sy = S.y + Math.sin(a) * r0;
    const ea = random(TWO_PI);
    const er = random(28, 140);
    const ex = C.x + Math.cos(ea) * er;
    const ey = C.y + Math.sin(ea) * er * 0.9;

    const dx = ex - sx, dy = ey - sy;
    const len = Math.max(1, Math.hypot(dx, dy));
    const nx = -dy / len, ny = dx / len;
    const nz1 = (noise(i * 0.21, 3.7) - 0.5) * 2;
    const nz2 = (noise(i * 0.21, 9.1) - 0.5) * 2;
    const amp = random(25, 95);

    const m1x = sx + dx * 0.34 + nx * nz1 * amp;
    const m1y = sy + dy * 0.34 + ny * nz1 * amp;
    const m2x = sx + dx * 0.68 - nx * nz2 * amp * 0.65;
    const m2y = sy + dy * 0.68 - ny * nz2 * amp * 0.65;

    const near = 1 - er / 145; // 越接近核心越亮
    stroke(
      lerp(colLine[0], warm[0], near * 0.85),
      lerp(colLine[1], warm[1], near * 0.85),
      lerp(colLine[2], warm[2], near * 0.85),
      random(22, 55) + near * 32
    );
    strokeWeight(random(0.5, 1.25));
    noFill();
    beginShape();
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    curveVertex(m1x, m1y);
    curveVertex(m2x, m2y);
    curveVertex(ex, ey);
    curveVertex(ex, ey);
    endShape();
  }
}

// ---------- 核心：细线交织成的发亮之核 ----------
function drawWeave(C) {
  noFill();
  for (let i = 0; i < 150; i++) {
    const a = random(TWO_PI);
    const r = random(18, 128);
    const px = C.x + Math.cos(a) * r;
    const py = C.y + Math.sin(a) * r * 0.9;
    const dirA = random(-0.95, 0.95);
    const L = random(45, 140);
    const x2 = px + Math.cos(dirA) * L * random(0.5, 1);
    const y2 = py + Math.sin(dirA) * L * 0.35;
    const cx = (px + x2) / 2 + random(-35, 35);
    const cy = (py + y2) / 2 + random(-30, 30);
    stroke(255, 241, 216, random(30, 85) * (1 - r / 160) + 15);
    strokeWeight(random(0.45, 1.05));
    beginShape();
    curveVertex(px, py);
    curveVertex(px, py);
    curveVertex(cx, cy);
    curveVertex(x2, y2);
    curveVertex(x2, y2);
    endShape();
  }
  // 隐约的轮廓弧
  for (let k = 0; k < 4; k++) {
    stroke(255, 236, 200, random(12, 26));
    strokeWeight(0.8);
    const rr = 60 + k * 28 + random(-8, 8);
    const st = random(TWO_PI);
    arc(C.x, C.y, rr * 2, rr * 1.82, st, st + random(2.6, 4.4));
  }
}

// ---------- 升腾：向上的呼吸 ----------
function drawRising(C) {
  noFill();
  for (let i = 0; i < 48; i++) {
    const a = -HALF_PI + random(-0.55, 0.55);
    const r0 = random(40, 120);
    const sx = C.x + Math.cos(a) * r0;
    const sy = C.y + Math.sin(a) * r0 * 0.92;
    const ex = sx + random(-190, 190);
    const ey = sy - random(240, 700);
    const mx = (sx + ex) / 2 + random(-80, 80);
    const my = (sy + ey) / 2 + random(-50, 50);
    stroke(255, 243, 222, random(8, 24));
    strokeWeight(random(0.45, 0.85));
    beginShape();
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    curveVertex(mx, my);
    curveVertex(ex, ey);
    curveVertex(ex, ey);
    endShape();
  }
}

// ---------- 根：向下穿过黑暗 ----------
function drawRoots(C) {
  noFill();
  // 主根
  for (let i = 0; i < 95; i++) {
    const a = HALF_PI + random(-0.8, 0.8);
    const r0 = random(100, 185);
    const sx = C.x + Math.cos(a) * r0;
    const sy = C.y + Math.sin(a) * r0 * 0.9;
    const ex = C.x + random(-390, 390);
    const ey = random(1560, 1975);
    const dx = ex - sx, dy = ey - sy;
    const len = Math.max(1, Math.hypot(dx, dy));
    const nx = -dy / len, ny = dx / len;
    const amp = random(30, 120);
    const m1x = sx + dx * 0.33 + nx * random(-amp, amp);
    const m1y = sy + dy * 0.33 + ny * random(-amp, amp);
    const m2x = sx + dx * 0.66 + nx * random(-amp, amp);
    const m2y = sy + dy * 0.66 + ny * random(-amp, amp);
    stroke(66, 54, 88, random(38, 85));
    strokeWeight(random(0.6, 1.5));
    beginShape();
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    curveVertex(m1x, m1y);
    curveVertex(m2x, m2y);
    curveVertex(ex, ey);
    curveVertex(ex, ey);
    endShape();
  }
  // 细根
  for (let i = 0; i < 60; i++) {
    const a = HALF_PI + random(-1.0, 1.0);
    const r0 = random(60, 170);
    const sx = C.x + Math.cos(a) * r0;
    const sy = C.y + Math.sin(a) * r0 * 0.9;
    const ex = C.x + random(-340, 340);
    const ey = random(1380, 1850);
    const mx = (sx + ex) / 2 + random(-90, 90);
    const my = (sy + ey) / 2 + random(-60, 60);
    stroke(58, 47, 78, random(22, 50));
    strokeWeight(random(0.35, 0.8));
    beginShape();
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    curveVertex(mx, my);
    curveVertex(ex, ey);
    curveVertex(ex, ey);
    endShape();
  }
  // 深处的种子：根尖的微光
  noStroke();
  for (let i = 0; i < 24; i++) {
    const x = C.x + random(-380, 380);
    const y = random(1480, 1950);
    const bright = i < 7;
    fill(216, 168, 100, 10);
    ellipse(x, y, 26, 26);
    fill(226, 180, 110, bright ? 90 : 45);
    ellipse(x, y, bright ? 4.5 : 3, bright ? 4.5 : 3);
    if (bright) {
      stroke(228, 186, 118, 55);
      strokeWeight(0.7);
      line(x - 8, y, x + 8, y);
      line(x, y - 8, x, y + 8);
      noStroke();
    }
  }
}

// ---------- 核心之光 ----------
function drawCoreGlow(C) {
  noStroke();
  const R = 340;
  for (let i = 64; i >= 1; i--) {
    const t = i / 64;
    const rr = R * Math.pow(t, 1.45);
    const mix = Math.pow(1 - t, 1.5);
    fill(
      lerp(196, 255, mix),
      lerp(148, 244, mix),
      lerp(92, 224, mix),
      4 + mix * 12
    );
    ellipse(C.x + random(-4, 4), C.y + random(-4, 4), rr * 2, rr * 1.85);
  }
  for (let i = 14; i >= 1; i--) {
    const t = i / 14;
    const rr = 46 * Math.pow(t, 1.2);
    fill(255, 246, 228, 14 + (1 - t) * 42);
    ellipse(C.x, C.y, rr * 2, rr * 1.8);
  }
  fill(255, 250, 238, 190);
  ellipse(C.x, C.y, 22, 19);
}

// ---------- 环抱：极淡的大弧，把一切围进"之间" ----------
function drawOrbitArcs(C) {
  noFill();
  for (let k = 0; k < 4; k++) {
    const rr = 430 + k * 210 + random(-30, 30);
    const segs = Math.floor(random(2, 5));
    for (let s = 0; s < segs; s++) {
      const st = random(TWO_PI);
      stroke(232, 190, 130, random(8, 16));
      strokeWeight(0.9 + k * 0.15);
      arc(C.x, C.y, rr * 2, rr * 1.9, st, st + random(0.9, 2.6));
    }
  }
}

// ---------- 光尘 ----------
function drawDustFar(C) {
  noStroke();
  for (let i = 0; i < 300; i++) {
    const x = random(width);
    const y = random(height);
    const d = Math.hypot(x - C.x, y - C.y);
    const p = 0.1 + 0.8 * Math.pow(Math.max(0, 1 - d / 1500), 1.6);
    if (random() > p) continue;
    const s = random(0.6, 2.4);
    const c = random() < 0.62 ? [255, 244, 224] : [238, 202, 150];
    fill(c[0], c[1], c[2], random(25, 105));
    ellipse(x, y, s, s);
  }
}

function drawDustNear(C) {
  noStroke();
  for (let i = 0; i < 120; i++) {
    const a = random(TWO_PI);
    const r = random(170, 560);
    const x = C.x + Math.cos(a) * r;
    const y = C.y + Math.sin(a) * r * 0.9;
    const s = random(0.8, 3);
    fill(255, 246, 228, random(45, 140));
    ellipse(x, y, s, s);
    if (random() < 0.12) {
      stroke(255, 246, 228, random(40, 85));
      strokeWeight(0.7);
      const L = random(6, 15);
      line(x - L, y, x + L, y);
      line(x, y - L, x, y + L);
      noStroke();
    }
  }
}

// ---------- 颗粒与暗角 ----------
function drawGrain() {
  noStroke();
  for (let i = 0; i < 11000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.5) fill(255, 246, 230, random(3, 9));
    else fill(6, 4, 12, random(4, 12));
    rect(x, y, 1.2, 1.2);
  }
}

function drawVignette() {
  noFill();
  stroke(8, 6, 14, 5);
  strokeWeight(3);
  for (let i = 0; i < 90; i++) {
    rect(i * 2.2, i * 2.2, width - i * 4.4, height - i * 4.4);
  }
}

// 《之间》 —— 爱，是两个孤独之间的光
// p5.js 1.11 · 静态

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  drawBackground();
  drawFarDust();
  drawAmbientGlow();

  // 两个孤独：琥珀（左下）与玫瑰（右上），内核朝向彼此
  softOrb(532, 985, 262, color(255, 246, 220), color(238, 152, 66), 3.0, { x: 0.857, y: -0.516 });
  softOrb(1025, 688, 213, color(255, 233, 228), color(224, 96, 112), 7.0, { x: -0.857, y: 0.516 });

  drawConnectionArcs();
  drawSpark();
  drawAscent();
  drawEmbraceArc();
  drawFallingLight();
  drawRisingDust();
  drawGrain();
  drawVignette();
}

/* ---------- 背景：夜的垂直呼吸 ---------- */
function drawBackground() {
  noStroke();
  const stops = [
    [0.0,  color(18, 16, 34)],
    [0.42, color(31, 22, 41)],
    [0.72, color(15, 11, 23)],
    [1.0,  color(7, 5, 13)]
  ];
  for (let y = 0; y < 2000; y++) {
    const t = y / 1999;
    let c = stops[stops.length - 1][1];
    for (let i = 0; i < stops.length - 1; i++) {
      if (t >= stops[i][0] && t <= stops[i + 1][0]) {
        const f = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
        c = lerpColor(stops[i][1], stops[i + 1][1], f);
        break;
      }
    }
    fill(c);
    rect(0, y, 1600, 1);
  }
}

/* ---------- 远处的星尘：别处也有无数场相遇 ---------- */
function drawFarDust() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 220; i++) {
    const t = random();
    const mt = 1 - t;
    let x = mt * mt * 150 + 2 * mt * t * 800 + t * t * 1450;
    let y = mt * mt * 320 + 2 * mt * t * 130 + t * t * 300;
    y += (noise(t * 3 + 40, 2) - 0.5) * 90;
    x += (random() - 0.5) * 40;
    const a = 4 + random() * 9;
    const c = random() < 0.8 ? [205, 210, 240] : [255, 220, 180];
    fill(c[0], c[1], c[2], a);
    circle(x, y, 1 + random() * 1.3);
  }
}

/* ---------- 中心暖雾与顶部冷雾 ---------- */
function drawAmbientGlow() {
  blendMode(ADD);
  noStroke();
  softGlow(778, 836, 900, color(115, 45, 72), 9);
  softGlow(778, 836, 600, color(145, 62, 82), 12);
  softGlow(778, 836, 400, color(165, 78, 92), 14);
  softGlow(800, 150, 760, color(45, 42, 92), 10);
}

/* ---------- 柔光工具：三层递进 ---------- */
function softGlow(x, y, r, c, a) {
  fill(red(c), green(c), blue(c), a * 0.35);
  circle(x, y, r * 2);
  fill(red(c), green(c), blue(c), a * 0.75);
  circle(x, y, r * 1.3);
  fill(red(c), green(c), blue(c), a);
  circle(x, y, r * 0.72);
}

/* ---------- 光球：边缘呼吸，内核朝向他者，受光面朝向他者 ---------- */
function softOrb(cx, cy, R, core, edge, seed, toward) {
  blendMode(ADD);
  noStroke();

  // 外晕
  softGlow(cx, cy, R * 2.1, edge, 10);
  softGlow(cx, cy, R * 1.55, edge, 14);
  softGlow(cx, cy, R * 1.2, edge, 20);

  // 主体：由暗缘到亮心的径向渐变
  const layers = 46;
  for (let i = 0; i <= layers; i++) {
    const t = i / layers;
    const r = R * 1.02 * (1 - t);
    const a = lerp(2, 22, pow(t, 2));
    const c = lerpColor(edge, core, pow(t, 1.35));
    fill(red(c), green(c), blue(c), a);
    circle(cx, cy, r * 2);
  }

  // 有机的呼吸边缘
  const N = 90;
  for (let i = 0; i < N; i++) {
    const ang = (i / N) * TWO_PI;
    const nv = noise(cos(ang) * 0.9 + seed, sin(ang) * 0.9 + seed * 2);
    const rr = R * (0.9 + nv * 0.22);
    const x = cx + cos(ang) * rr;
    const y = cy + sin(ang) * rr;
    const c = lerpColor(edge, core, 0.35 + nv * 0.4);
    fill(red(c), green(c), blue(c), 14 + nv * 22);
    circle(x, y, 7 + nv * 9);
    fill(red(c), green(c), blue(c), 30 + nv * 30);
    circle(x, y, 2.5 + nv * 3);
  }

  // 受光侧：朝向他者的一弧亮带
  const baseAng = atan2(toward.y, toward.x);
  for (let i = 0; i < 26; i++) {
    const ang = baseAng + (random() - 0.5) * 1.4;
    const rr = R * (0.66 + random() * 0.22);
    const x = cx + cos(ang) * rr;
    const y = cy + sin(ang) * rr;
    fill(red(core), green(core), blue(core), 16 + random() * 26);
    circle(x, y, 8 + random() * 14);
  }

  // 内核：悄悄偏向对方
  const kx = cx + toward.x * R * 0.17;
  const ky = cy + toward.y * R * 0.17;
  softGlow(kx, ky, R * 0.34, core, 40);
  fill(red(core), green(core), blue(core), 70);
  circle(kx, ky, R * 0.30);
  fill(red(core), green(core), blue(core), 150);
  circle(kx, ky, R * 0.15);
  fill(255, 252, 245, 230);
  circle(kx, ky, R * 0.06);
}

/* ---------- 之间的连桥：细弧汇入同一颗星 ---------- */
function drawConnectionArcs() {
  blendMode(ADD);
  noFill();
  strokeCap(ROUND);
  const ax = 756, ay = 850, bx = 843, by = 798;
  const nx = 0.516, ny = 0.857;
  for (let k = -1; k <= 1; k++) {
    const x1 = ax + nx * k * 26, y1 = ay + ny * k * 26;
    const x2 = bx + nx * k * 26, y2 = by + ny * k * 26;
    const mx = (x1 + x2) / 2 - nx * k * 30;
    const my = (y1 + y2) / 2 - ny * k * 30;
    stroke(255, 234, 196, k === 0 ? 34 : 18);
    strokeWeight(k === 0 ? 1.4 : 1.0);
    bezier(x1, y1, mx, my, mx, my, x2, y2);
  }
}

/* ---------- 间隙的火花：全画最亮处 ---------- */
function drawSpark() {
  blendMode(ADD);
  const x = 800, y = 824;
  noStroke();
  softGlow(x, y, 150, color(255, 214, 150), 16);
  softGlow(x, y, 78, color(255, 232, 186), 34);
  fill(255, 240, 200, 130); circle(x, y, 26);
  fill(255, 248, 228, 220); circle(x, y, 11);
  fill(255, 253, 246, 255); circle(x, y, 5);

  // 两个接触点微微发亮
  contactGlow(756, 850);
  contactGlow(843, 798);

  // 含蓄的星芒
  noFill();
  stroke(255, 246, 220, 70);
  strokeWeight(1);
  line(x - 42, y, x + 42, y);
  line(x, y - 42, x, y + 42);
  stroke(255, 246, 220, 40);
  line(x - 26, y - 26, x + 26, y + 26);
  line(x - 26, y + 26, x + 26, y - 26);

  // 溅出的火星
  noStroke();
  for (let i = 0; i < 7; i++) {
    const a = random(TWO_PI);
    const d = 26 + random() * 70;
    fill(255, 236, 200, 25 + random() * 45);
    circle(x + cos(a) * d, y + sin(a) * d, 1.5 + random() * 2);
  }
}
function contactGlow(x, y) {
  fill(255, 238, 205, 60); circle(x, y, 16);
  fill(255, 246, 228, 110); circle(x, y, 7);
}

/* ---------- 一缕升腾：光也向上 ---------- */
function drawAscent() {
  blendMode(ADD);
  noFill();
  let px = 790, py = 812;
  for (let s = 1; s <= 60; s++) {
    const t = s / 60;
    const x = 790 + (noise(t * 2.0 + 50, 9) - 0.5) * 2 * 45 * t;
    const y = lerp(812, 220, t);
    stroke(215, 220, 248, 16 * (1 - t));
    strokeWeight(lerp(1.6, 0.25, t));
    line(px, py, x, y);
    px = x; py = y;
  }
}

/* ---------- 拥抱的轨道：下弧明亮如怀抱，上弧淡如呼吸 ---------- */
function drawEmbraceArc() {
  blendMode(ADD);
  noStroke();
  const cx = 778, cy = 836, rx = 600, ry = 520, rot = -0.14;
  const orbA = { x: 532, y: 985, r: 278 };
  const orbB = { x: 1025, y: 688, r: 226 };

  for (let i = 0; i < 340; i++) {
    const a = random(TWO_PI);
    const rad = 1 + (random() - 0.5) * 0.07;
    const ex = cos(a) * rx * rad;
    const ey = sin(a) * ry * rad;
    const x = cx + ex * cos(rot) - ey * sin(rot);
    const y = cy + ex * sin(rot) + ey * cos(rot);
    if (dist(x, y, orbA.x, orbA.y) < orbA.r || dist(x, y, orbB.x, orbB.y) < orbB.r) continue;
    const downness = (sin(a) + 1) / 2;
    const al = lerp(6, 55, pow(downness, 1.8)) * random(0.35, 1.0);
    fill(255, 216, 155, al);
    circle(x, y, 1 + random() * 1.6);
  }
  for (let i = 0; i < 30; i++) {
    const a = random(TWO_PI);
    const downness = (sin(a) + 1) / 2;
    if (downness < 0.35) continue;
    const ex = cos(a) * rx, ey = sin(a) * ry;
    const x = cx + ex * cos(rot) - ey * sin(rot);
    const y = cy + ex * sin(rot) + ey * cos(rot);
    if (dist(x, y, orbA.x, orbA.y) < orbA.r || dist(x, y, orbB.x, orbB.y) < orbB.r) continue;
    const s = 2.5 + random() * 3;
    fill(255, 226, 170, 18);  circle(x, y, s * 3);
    fill(255, 238, 200, 60 + random() * 50); circle(x, y, s);
  }
}

/* ---------- 倾泻的光：给予 ---------- */
const strands = [
  { sx: 800, sy: 838, ex: 745, ey: 1725, amp: 60, al: 95 },
  { sx: 803, sy: 838, ex: 890, ey: 1655, amp: 75, al: 80 },
  { sx: 798, sy: 850, ex: 800, ey: 1790, amp: 95, al: 70 },
  { sx: 806, sy: 845, ex: 655, ey: 1545, amp: 48, al: 45 },
  { sx: 799, sy: 840, ex: 955, ey: 1585, amp: 44, al: 38 },
  { sx: 801, sy: 838, ex: 760, ey: 1400, amp: 30, al: 30 }
];
function strandPoint(st, t, idx) {
  const x = lerp(st.sx, st.ex, t) +
    (noise(t * 2.4 + idx * 13.7, idx * 5.1) - 0.5) * 2 * st.amp * pow(t, 0.75);
  const y = lerp(st.sy, st.ey, t);
  return { x, y };
}
function drawFallingLight() {
  blendMode(ADD);
  for (let i = 0; i < strands.length; i++) {
    const st = strands[i];
    noFill();
    let prev = strandPoint(st, 0, i);
    for (let s = 1; s <= 90; s++) {
      const t = s / 90;
      const p = strandPoint(st, t, i);
      stroke(255, 228, 168, st.al * (1 - pow(t, 1.15)));
      strokeWeight(lerp(3.2, 0.35, t));
      line(prev.x, prev.y, p.x, p.y);
      prev = p;
    }
    for (let k = 0; k < 14; k++) {
      const t = random(0.05, 0.95);
      const p = strandPoint(st, t, i);
      const sz = 1.2 + random() * 2.4;
      const al = (30 + random() * 55) * (1 - t * 0.55);
      noStroke();
      fill(255, 235, 195, al * 0.35); circle(p.x, p.y, sz * 3.4);
      fill(255, 242, 215, al);        circle(p.x, p.y, sz);
    }
  }
}

/* ---------- 升起的微尘：回应 ---------- */
function drawRisingDust() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 380; i++) {
    let x;
    if (random() < 0.42) x = 500 + random() * 600;
    else x = 80 + random() * 1440;
    const yr = pow(random(), 1.65);
    const y = 1985 - yr * 730;
    const s = 0.8 + random() * 2.3;
    const al = (8 + 50 * yr) * random(0.4, 1.0);
    const c = dustColor();
    fill(c[0], c[1], c[2], al);
    circle(x, y, s);
  }
  for (let i = 0; i < 24; i++) {
    const x = 350 + random() * 900;
    const y = 1380 + random() * 560;
    const s = 2 + random() * 3.5;
    const c = random() < 0.7 ? [255, 218, 160] : [255, 168, 156];
    fill(c[0], c[1], c[2], 14);  circle(x, y, s * 4);
    fill(c[0], c[1], c[2], 45);  circle(x, y, s * 2);
    fill(min(c[0] + 20, 255), min(c[1] + 20, 255), min(c[2] + 15, 255), 110);
    circle(x, y, s);
  }
}
function dustColor() {
  const r = random();
  if (r < 0.72) return [255, 240, 218];
  if (r < 0.90) return [255, 214, 158];
  return [255, 170, 158];
}

/* ---------- 存在之尘：统一的颗粒质感 ---------- */
function drawGrain() {
  noStroke();
  blendMode(BLEND);
  for (let i = 0; i < 5000; i++) {
    fill(10, 8, 16, 6 + random() * 26);
    circle(random() * 1600, random() * 2000, 1.3);
  }
  blendMode(ADD);
  for (let i = 0; i < 4200; i++) {
    fill(255, 236, 212, 4 + random() * 22);
    circle(random() * 1600, random() * 2000, 1);
  }
}

/* ---------- 暗角：让目光回到中心 ---------- */
function drawVignette() {
  blendMode(BLEND);
  noFill();
  const cx = 800, cy = 950;
  for (let r = 700; r <= 1480; r += 4) {
    stroke(6, 4, 11, map(r, 700, 1480, 0, 52));
    strokeWeight(5.6);
    circle(cx, cy, r * 2);
  }
  noStroke();
}

function draw() {}

const A = { x: 470, y: 660 };
const B = { x: 1150, y: 1400 };
let cA, cB, cMid;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  cA = color(255, 176, 128);   // warm rose-gold
  cB = color(150, 175, 255);   // cool periwinkle
  cMid = lerpColor(cA, cB, 0.5);
  noLoop();
  drawScene();
}

function softGlow(x, y, r, c, maxA) {
  noStroke();
  const steps = 36;
  for (let i = steps; i >= 1; i--) {
    const rr = r * i / steps;
    const a = maxA * pow(1 - i / steps, 2);
    fill(red(c), green(c), blue(c), a);
    circle(x, y, rr * 2);
  }
}

function softGlowAdd(x, y, r, c, maxA) {
  push();
  blendMode(ADD);
  noStroke();
  const steps = 40;
  for (let i = steps; i >= 1; i--) {
    const rr = r * i / steps;
    const a = maxA * pow(1 - i / steps, 2.2);
    fill(red(c), green(c), blue(c), a);
    circle(x, y, rr * 2);
  }
  pop();
}

function drawRibbon(dAB) {
  const steps = 300;
  const nx = -(B.y - A.y) / dAB;
  const ny = (B.x - A.x) / dAB;
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = lerp(A.x, B.x, t);
    const y = lerp(A.y, B.y, t);
    const off = (noise(t * 3.2, 0.7) - 0.5) * 2.4 * dAB * 0.07 * sin(t * PI)
              + (noise(t * 8, 4.1) - 0.5) * dAB * 0.045 * sin(t * PI);
    pts.push({ x: x + nx * off, y: y + ny * off, t: t });
  }
  push();
  blendMode(ADD);
  noFill();
  for (let layer = 0; layer < 6; layer++) {
    stroke(red(cMid), green(cMid), blue(cMid), 6 + layer * 2.5);
    strokeWeight(58 - layer * 9);
    beginShape();
    for (const p of pts) vertex(p.x, p.y);
    endShape();
  }
  stroke(255, 238, 224, 55);
  strokeWeight(7);
  beginShape();
  for (const p of pts) vertex(p.x, p.y);
  endShape();
  stroke(255, 252, 246, 90);
  strokeWeight(2.4);
  beginShape();
  for (const p of pts) vertex(p.x, p.y);
  endShape();
  noStroke();
  for (let i = 0; i < 460; i++) {
    const t = random(1);
    const p = pts[floor(t * steps)];
    const off = (noise(t * 11, 2.2) - 0.5) * 130 * sin(t * PI);
    const px = p.x + nx * off;
    const py = p.y + ny * off;
    const c = lerpColor(cA, cB, constrain(t + (noise(t * 20, 8) - 0.5) * 0.5, 0, 1));
    const s = random(1, 4.6) * (0.55 + 0.45 * sin(t * PI));
    const a = random(60, 210);
    fill(red(c), green(c), blue(c), a);
    circle(px, py, s);
    if (random() < 0.09) softGlowAdd(px, py, s * 7, c, a * 0.55);
  }
  pop();
}

function drawSoul(P, c, coreR) {
  push();
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 7; i++) {
    const rr = coreR * (2 + i * 0.75);
    stroke(red(c), green(c), blue(c), 22 - i * 2.6);
    strokeWeight(random(0.7, 1.8));
    push();
    translate(P.x, P.y);
    rotate(i * 0.35 + random(-0.15, 0.15));
    const st = random(TWO_PI), len = random(PI * 0.5, PI * 1.8);
    arc(0, 0, rr * 2, rr * 2 * random(0.85, 1), st, st + len);
    pop();
  }
  noStroke();
  for (let i = 0; i < 130; i++) {
    const ang = noise(i * 0.11, P.x * 0.01) * TWO_PI * 2.4;
    const rr = coreR * (1.8 + noise(i * 0.07, P.y * 0.01) * 3.4);
    const px = P.x + cos(ang) * rr;
    const py = P.y + sin(ang) * rr * 0.9;
    const s = random(0.8, 3.2);
    const a = random(35, 150);
    fill(red(c), green(c), blue(c), a);
    circle(px, py, s);
    if (random() < 0.08) softGlowAdd(px, py, s * 8, c, a * 0.5);
  }
  pop();
}

function drawScene() {
  background(7, 9, 20);

  push();
  for (let i = 0; i < 80; i++) {
    const x = random(width), y = random(height);
    const r = random(120, 380);
    const c = random() < 0.55 ? color(26, 30, 64) : color(56, 36, 74);
    softGlow(x, y, r, c, random(14, 30));
  }
  pop();

  push();
  blendMode(ADD);
  for (let i = 0; i < 650; i++) {
    stroke(random(180, 255), random(190, 255), 255, random(25, 130));
    strokeWeight(random(0.6, 2.4));
    point(random(width), random(height));
  }
  pop();

  const mx = (A.x + B.x) / 2, my = (A.y + B.y) / 2;
  const dAB = dist(A.x, A.y, B.x, B.y);
  const ang = atan2(B.y - A.y, B.x - A.x);

  push();
  blendMode(ADD);
  noFill();
  translate(mx, my);
  rotate(ang);
  for (let i = 0; i < 4; i++) {
    stroke(red(cMid), green(cMid), blue(cMid), 10 - i * 2);
    strokeWeight(random(0.8, 1.6));
    const st = random(TWO_PI), len = random(PI * 0.5, PI * 1.4);
    arc(0, 0, dAB * 1.9, dAB * 1.35, st, st + len);
  }
  pop();

  softGlowAdd(mx, my, 520, color(232, 158, 214), 26);
  softGlowAdd(mx, my, 240, cMid, 55);

  drawRibbon(dAB);

  drawSoul(A, cA, 30);
  drawSoul(B, cB, 25);

  push();
  blendMode(ADD);
  softGlowAdd(A.x, A.y, 300, cA, 70);
  softGlowAdd(A.x, A.y, 110, cA, 150);
  softGlowAdd(B.x, B.y, 260, cB, 70);
  softGlowAdd(B.x, B.y, 95, cB, 150);
  noStroke();
  fill(255, 246, 238, 235);
  circle(A.x, A.y, 26);
  fill(250, 246, 255, 235);
  circle(B.x, B.y, 22);
  pop();

  push();
  blendMode(ADD);
  for (let i = 0; i < 160; i++) {
    const t = random(0.3, 0.7);
    const x = lerp(A.x, B.x, t) + (noise(i * 0.13, 1) - 0.5) * 560;
    const y = lerp(A.y, B.y, t) + (noise(i * 0.13, 9) - 0.5) * 560;
    const c = lerpColor(cA, cB, constrain(t + (noise(i) - 0.5) * 0.4, 0, 1));
    stroke(red(c), green(c), blue(c), random(50, 190));
    strokeWeight(random(0.8, 3));
    point(x, y);
  }
  pop();

  push();
  noFill();
  for (let i = 0; i < 70; i++) {
    stroke(0, 0, 5, i * 1.1);
    strokeWeight(2);
    rect(-i * 26, -i * 33, width + i * 52, height + i * 66, i * 18);
  }
  pop();

  push();
  for (let i = 0; i < 3500; i++) {
    if (random() < 0.5) stroke(255, 255, 255, random(2, 9));
    else stroke(0, 0, 0, random(3, 10));
    strokeWeight(1);
    point(random(width), random(height));
  }
  pop();
}

