}

function draw() {
  const ctx = drawingContext;

  // deep-space background
  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0.0, '#05060f');
  bg.addColorStop(0.5, '#0b0a1e');
  bg.addColorStop(1.0, '#150a1a');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  // distant stars
  noStroke();
  for (let i = 0; i < 380; i++) {
    const x = random(width);
    const y = random(height);
    const r = random(0.6, 2.4);
    const a = random(25, 120);
    if (random() < 0.28) fill(255, 224, 190, a);
    else fill(185, 205, 255, a);
    circle(x, y, r * 2);
  }

  // paths of the two lights
  const pathA = makePath(1580, 420, 0.0);
  const pathB = makePath(420, 1580, 37.0);

  // the meeting point
  const center = findMeeting(pathA, pathB);

  blendMode(ADD);

  // halos at the four ends — the two sources of light
  halo(60, 1560, 560, '255,190,110');
  halo(width - 60, 440, 560, '255,190,110');
  halo(60, 440, 560, '255,125,165');
  halo(width - 60, 1580, 560, '255,125,165');

  // the two ribbons of light
  ribbon(pathA, color(255, 183, 94));
  ribbon(pathB, color(255, 122, 162));

  // drifting motes along each ribbon
  motes(pathA, color(255, 200, 130));
  motes(pathB, color(255, 150, 185));

  // the bloom where they meet
  bloom(center.x, center.y, 680, '255,238,205', 0.9);
  bloom(center.x, center.y, 240, '255,252,244', 1.0);

  // soft ripples radiating from the meeting
  noFill();
  push();
  translate(center.x, center.y);
  rotate(-0.12);
  for (let i = 1; i <= 5; i++) {
    stroke(255, 214, 180, 12);
    strokeWeight(2.2);
    ellipse(0, 0, i * 250, i * 300);
  }
  pop();

  // free-floating sparks around the center
  for (let i = 0; i < 90; i++) {
    const ang = random(TWO_PI);
    const d = random(40, 520) * (0.4 + 0.6 * noise(i * 0.1));
    const x = center.x + cos(ang) * d * 1.15;
    const y = center.y + sin(ang) * d * 0.9;
    fill(255, 226, 190, random(30, 170));
    circle(x, y, random(1.5, 5));
  }

  // vignette
  blendMode(BLEND);
  const vg = ctx.createRadialGradient(width / 2, height / 2, height * 0.32, width / 2, height / 2, height * 0.78);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(3,3,14,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

function makePath(y0, y1, nOff) {
  const pts = [];
  const N = 200;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const x = lerp(-90, width + 90, t);
    const y = lerp(y0, y1, t) + (noise(t * 3.4 + nOff) - 0.5) * 560;
    pts.push({ x: x, y: y, t: t });
  }
  return pts;
}

function findMeeting(a, b) {
  let cx = width / 2, cy = height / 2, best = 1e9;
  for (let i = 0; i < a.length; i++) {
    const j = Math.round(a[i].t * (b.length - 1));
    const d = abs(a[i].y - b[j].y);
    if (d < best) {
      best = d;
      cx = a[i].x;
      cy = (a[i].y + b[j].y) / 2;
    }
  }
  return { x: cx, y: cy };
}

function halo(x, y, r, rgb) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + rgb + ',0.5)');
  g.addColorStop(0.5, 'rgba(' + rgb + ',0.16)');
  g.addColorStop(1, 'rgba(' + rgb + ',0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function ribbon(pts, col) {
  noStroke();
  const cr = red(col), cg = green(col), cb = blue(col);
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    const swell = sin(PI * p.t);
    const w = 16 + 40 * swell + noise(p.t * 6 + 7) * 14;
    fill(cr, cg, cb, 12);
    circle(p.x, p.y, w * 3.4);
    fill(cr, cg, cb, 26);
    circle(p.x, p.y, w * 2.0);
    fill(cr, cg, cb, 60);
    circle(p.x, p.y, w * 1.1);
    fill(255, 246, 228, 200);
    circle(p.x, p.y, w * 0.42);
  }
  noFill();
  stroke(255, 250, 238, 210);
  strokeWeight(2.6);
  strokeCap(ROUND);
  beginShape();
  for (let i = 0; i < pts.length; i++) vertex(pts[i].x, pts[i].y);
  endShape();
}

function motes(pts, col) {
  noStroke();
  const cr = red(col), cg = green(col), cb = blue(col);
  for (let i = 0; i < 150; i++) {
    const p = pts[floor(random(pts.length))];
    const x = p.x + random(-30, 30);
    const y = p.y + (noise(p.t * 9 + i * 0.05) - 0.5) * 90 + random(-10, 10);
    fill(cr, cg, cb, random(50, 210));
    circle(x, y, random(2, 9));
  }
}

function bloom(x, y, r, rgb, strength) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + rgb + ',' + (0.85 * strength) + ')');
  g.addColorStop(0.3, 'rgba(' + rgb + ',' + (0.35 * strength) + ')');
  g.addColorStop(0.65, 'rgba(' + rgb + ',' + (0.10 * strength) + ')');
  g.addColorStop(1, 'rgba(' + rgb + ',0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  const W = 1600, H = 2000;
  const ctx = drawingContext;

  // ---- palette & geometry ----
  const lineWarm = [255, 176, 92];    // amber
  const lineCool = [255, 158, 205];   // rose
  const A = { x: 470, y: 1450 };      // warm light, lower left
  const B = { x: 1140, y: 560 };      // rose light, upper right
  const M = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };

  const dx = B.x - A.x, dy = B.y - A.y;
  const len = Math.hypot(dx, dy);
  const U = { x: dx / len, y: dy / len };
  const P = { x: -U.y, y: U.x };

  function glow(x, y, r, stops) {
    const rg = ctx.createRadialGradient(x, y, 0, x, y, r);
    for (let k = 0; k < stops.length; k++) rg.addColorStop(stops[k][0], stops[k][1]);
    ctx.fillStyle = rg;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  // ---- 1. night background ----
  ctx.globalCompositeOperation = 'source-over';
  const bg = ctx.createLinearGradient(0, 0, W * 0.25, H);
  bg.addColorStop(0, '#06050e');
  bg.addColorStop(0.5, '#0c0918');
  bg.addColorStop(1, '#160f23');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // ---- 2. faint nebulae + distant dust (additive) ----
  ctx.globalCompositeOperation = 'lighter';
  const nebs = [
    ['110,70,190', 520], ['40,60,130', 680], ['170,60,95', 440],
    ['28,80,120', 600], ['90,40,140', 500], ['150,90,60', 380]
  ];
  for (let i = 0; i < nebs.length; i++) {
    glow(random(W), random(H * 0.15, H * 0.95), nebs[i][1],
      [[0, 'rgba(' + nebs[i][0] + ',0.10)'], [1, 'rgba(' + nebs[i][0] + ',0)']]);
  }
  for (let i = 0; i < 900; i++) {
    const c = random() < 0.5 ? '255,240,220' : '205,195,255';
    ctx.fillStyle = 'rgba(' + c + ',' + random(0.04, 0.15).toFixed(3) + ')';
    ctx.fillRect(random(W), random(H), random(0.6, 1.8), random(0.6, 1.8));
  }

  // ---- 3. the two lights' halos ----
  glow(A.x, A.y, 660, [
    [0.0, 'rgba(255,232,190,0.85)'],
    [0.22, 'rgba(255,180,95,0.38)'],
    [0.55, 'rgba(255,120,60,0.10)'],
    [1.0, 'rgba(255,100,50,0)']
  ]);
  glow(B.x, B.y, 660, [
    [0.0, 'rgba(255,225,238,0.85)'],
    [0.22, 'rgba(255,150,200,0.38)'],
    [0.55, 'rgba(150,140,255,0.10)'],
    [1.0, 'rgba(140,130,255,0)']
  ]);
  // the overlap: brighter than either light alone
  glow(M.x, M.y, 780, [
    [0.0, 'rgba(255,242,228,0.50)'],
    [0.35, 'rgba(255,208,190,0.22)'],
    [0.7, 'rgba(255,170,160,0.07)'],
    [1.0, 'rgba(255,160,160,0)']
  ]);

  // ---- 4. luminous ribbons between the two lights ----
  const NC = 84;
  const SEG = 130;
  const p0 = { x: 0, y: 0 }, p1 = { x: 0, y: 0 };

  function curvePoint(i, t, out) {
    const s = map(i, 0, NC - 1, -1, 1);
    const s3 = s * s * s;
    const amp = s3 * 300 + s * 60 + (noise(i * 0.37 + 0.5) - 0.5) * 70;
    const bow = Math.sin(Math.PI * t) * amp;
    const wob = (noise(i * 1.7 + 9.1, t * 5.0) - 0.5) * 52 * Math.sin(Math.PI * t);
    const wob2 = (noise(i * 2.3 + 4.7, t * 7.0 + 3.0) - 0.5) * 34 * Math.sin(Math.PI * t);
    out.x = A.x + U.x * (len * t) + P.x * (bow + wob) + U.x * wob2;
    out.y = A.y + U.y * (len * t) + P.y * (bow + wob) + U.y * wob2;
  }

  for (let i = 0; i < NC; i++) {
    const s = map(i, 0, NC - 1, -1, 1);
    for (let j = 0; j < SEG; j++) {
      const t0 = 0.03 + 0.94 * (j / SEG);
      const t1 = 0.03 + 0.94 * ((j + 1) / SEG);
      curvePoint(i, t0, p0);
      curvePoint(i, t1, p1);
      const t = (t0 + t1) / 2;
      const mid = Math.sin(Math.PI * t);
      const rC = lerp(lineWarm[0], lineCool[0], t);
      const gC = lerp(lineWarm[1], lineCool[1], t);
      const bC = lerp(lineWarm[2], lineCool[2], t);
      stroke(rC, gC, bC, (12 + 34 * mid) * (1 - Math.abs(s) * 0.35));
      strokeWeight(0.7 + 2.6 * mid * (1.15 - Math.abs(s) * 0.5) * (0.6 + 0.4 * noise(i * 0.11)));
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // ---- 5. hot heart of the overlap ----
  glow(M.x, M.y, 300, [
    [0.0, 'rgba(255,252,244,0.95)'],
    [0.3, 'rgba(255,236,214,0.55)'],
    [0.7, 'rgba(255,200,170,0.18)'],
    [1.0, 'rgba(255,190,160,0)']
  ]);

  // ---- 6. the two cores ----
  glow(A.x, A.y, 170, [
    [0.0, 'rgba(255,255,246,1)'],
    [0.25, 'rgba(255,226,170,0.85)'],
    [0.6, 'rgba(255,170,80,0.35)'],
    [1.0, 'rgba(255,150,70,0)']
  ]);
  glow(B.x, B.y, 150, [
    [0.0, 'rgba(255,252,250,1)'],
    [0.25, 'rgba(255,214,232,0.85)'],
    [0.6, 'rgba(240,150,205,0.35)'],
    [1.0, 'rgba(190,150,255,0)']
  ]);

  // ---- 7. faint ripples ----
  noFill();
  for (let k = 0; k < 4; k++) {
    stroke(255, 190, 110, 16 - k * 3.5);
    strokeWeight(1.1);
    circle(A.x, A.y, 190 + k * 100);
    stroke(255, 170, 215, 16 - k * 3.5);
    circle(B.x, B.y, 170 + k * 100);
  }

  // ---- 8. sparks riding the ribbons ----
  noStroke();
  for (let i = 0; i < 2600; i++) {
    const ci = Math.floor(random(NC));
    const t = random(0.02, 0.98);
    curvePoint(ci, t, p0);
    const mid = Math.sin(Math.PI * t);
    const jx = (noise(i * 0.9, 1.0) - 0.5) * 70 * mid;
    const jy = (noise(i * 0.9, 2.0) - 0.5) * 70 * mid;
    const rC = lerp(lineWarm[0], lineCool[0], t) + random(-14, 14);
    const gC = lerp(lineWarm[1], lineCool[1], t) + random(-14, 14);
    const bC = lerp(lineWarm[2], lineCool[2], t) + random(-14, 14);
    const sz = random(0.7, 2.6) * (0.35 + 0.65 * mid) + (random() < 0.04 ? random(1.5, 3.5) : 0);
    const a = random(50, 210) * (0.25 + 0.75 * mid);
    fill(constrain(rC, 0, 255), constrain(gC, 0, 255), constrain(bC, 0, 255), constrain(a, 0, 255));
    circle(p0.x + jx, p0.y + jy, sz);
  }

  // sparks in the very heart of the overlap
  for (let i = 0; i < 150; i++) {
    const ang = random(Math.PI * 2);
    const rr = Math.pow(random(), 0.6) * 200;
    fill(255, 248, 236, random(120, 255));
    circle(M.x + Math.cos(ang) * rr, M.y + Math.sin(ang) * rr * 0.85, random(0.8, 2.6));
  }

  // ambient drifting dust
  for (let i = 0; i < 700; i++) {
    const c = random() < 0.5 ? '255,235,215' : '215,200,255';
    ctx.fillStyle = 'rgba(' + c + ',' + random(0.05, 0.17).toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(random(W), random(H), random(0.5, 1.6), 0, Math.PI * 2);
    ctx.fill();
  }

  // soft bokeh along the band
  for (let i = 0; i < 34; i++) {
    const t = random(0.15, 0.85);
    const x = lerp(A.x, B.x, t) + (noise(i * 3.3, 0) - 0.5) * 280;
    const y = lerp(A.y, B.y, t) + (noise(i * 3.3, 5) - 0.5) * 280;
    const c = random() < 0.5 ? '255,190,120' : '255,170,215';
    ctx.fillStyle = 'rgba(' + c + ',' + random(0.03, 0.08).toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(x, y, random(8, 26), 0, Math.PI * 2);
    ctx.fill();
  }

  // ---- 9. film grain ----
  ctx.globalCompositeOperation = 'source-over';
  for (let i = 0; i < 10000; i++) {
    if (random() < 0.5) ctx.fillStyle = 'rgba(255,255,255,' + random(0.015, 0.06).toFixed(3) + ')';
    else ctx.fillStyle = 'rgba(0,0,6,' + random(0.02, 0.08).toFixed(3) + ')';
    ctx.fillRect(random(W), random(H), random(1, 2.4), random(1, 2.4));
  }

  // ---- 10. vignette ----
  const vg = ctx.createRadialGradient(W / 2, H * 0.48, H * 0.30, W / 2, H * 0.5, H * 0.78);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(3,2,9,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // ---- deep night gradient ----
  const cTop = color(12, 16, 42);
  const cMid = color(27, 20, 55);
  const cBot = color(54, 26, 45);
  noStroke();
  for (let y = 0; y < height; y += 3) {
    const t = y / height;
    const c = t < 0.55 ? lerpColor(cTop, cMid, t / 0.55) : lerpColor(cMid, cBot, (t - 0.55) / 0.45);
    fill(c);
    rect(0, y, width, 3);
  }
  // soft nebula clouds
  for (let i = 0; i < 7; i++) {
    fill(random() < 0.5 ? 70 : 100, 40, random() < 0.5 ? 90 : 70, random(5, 10));
    ellipse(random(width), random(height * 0.7), random(300, 700), random(150, 350));
  }
  // mottled texture
  for (let i = 0; i < 1500; i++) {
    const warm = random() < 0.4;
    fill(warm ? 96 + random(40) : 60 + random(40), warm ? 46 : 52, warm ? 68 : 96, random(3, 9));
    rect(random(width), random(height), random(2, 7), random(2, 7));
  }
  drawStars();

  blendMode(ADD);
  drawRipples();
  drawThreads();
  drawFilaments();
  drawBloom();
  blendMode(BLEND);
  drawHill();
  blendMode(ADD);
  drawCores();
  blendMode(BLEND);
  drawPetals();
  drawVignette();
  drawGrain();
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    const x = random(width), y = random(height * 0.9);
    const warm = random() < 0.3;
    const s = random(1, 3.2);
    const a = random(40, 150);
    fill(warm ? 255 : 205, warm ? 224 : 215, warm ? 190 : 255, a);
    circle(x, y, s);
    if (random() < 0.06) {
      fill(255, 230, 200, 18);
      circle(x, y, s * 5);
    }
  }
}

function drawRipples() {
  noFill();
  for (const [cx, cy] of [[430, 1560], [1170, 1560]]) {
    for (let i = 1; i <= 15; i++) {
      const r = i * 58;
      const a = map(r, 58, 870, 22, 2, true);
      stroke(255, 178, 150, a);
      strokeWeight(1.4);
      ellipse(cx, cy, r * 2, r * 1.9);
    }
  }
}

function drawThreads() {
  const A = [430, 1560], B = [1170, 1560];
  for (let k = 0; k < 6; k++) {
    const lift = 180 + k * 90 + random(40);
    const pts = [];
    const seg = 40;
    for (let i = 0; i <= seg; i++) {
      const t = i / seg;
      const x = lerp(A[0], B[0], t);
      const y = lerp(A[1], B[1], t) - sin(t * PI) * lift + (noise(t * 5, k * 7) - 0.5) * 30;
      pts.push([x, y]);
    }
    stroke(255, 180, 120, 7);
    strokeWeight(6);
    noFill();
    beginShape();
    for (const p of pts) vertex(p[0], p[1]);
    endShape();
    for (let i = 0; i < pts.length - 1; i++) {
      const t = i / (pts.length - 1);
      stroke(255, 214, 150, sin(t * PI) * 60);
      strokeWeight(1.6);
      line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    }
  }
}

function strandPath(bx, by, side, seedOff) {
  const pts = [];
  let x = bx, y = by;
  let ang = -HALF_PI + random(-1.0, 1.0) + (side === 0 ? 0.35 : -0.35);
  const att = random(0.02, 0.06);
  const steps = 80 + floor(random(50));
  const cx = 800, cy = 620;
  for (let i = 0; i < steps; i++) {
    pts.push([x, y]);
    ang += (noise(x * 0.0015, y * 0.0015, seedOff) - 0.5) * 0.55;
    let diff = atan2(cy - y, cx - x) - ang;
    while (diff > PI) diff -= TWO_PI;
    while (diff < -PI) diff += TWO_PI;
    ang += diff * att;
    let d2 = -HALF_PI - ang;
    while (d2 > PI) d2 -= TWO_PI;
    while (d2 < -PI) d2 += TWO_PI;
    ang += d2 * 0.025;
    const len = 11 + noise(i * 0.12 + seedOff, x * 0.001) * 15;
    x += cos(ang) * len;
    y += sin(ang) * len;
    if (y < 120 || x < 50 || x > 1550 || y > 1900) break;
  }
  pts.push([x, y]);
  return pts;
}

function drawFilaments() {
  const bases = [[430, 1560, 0], [1170, 1560, 1]];
  for (const [bx, by, side] of bases) {
    for (let s = 0; s < 62; s++) {
      const pts = strandPath(bx, by, side, s * 13.7);
      stroke(255, 168, 108, 8);
      strokeWeight(7);
      noFill();
      beginShape();
      for (const p of pts) vertex(p[0], p[1]);
      endShape();
      for (let i = 0; i < pts.length - 1; i++) {
        const t = i / (pts.length - 1);
        const c = lerpColor(color(255, 208, 138), color(255, 132, 168), t);
        stroke(red(c), green(c), blue(c), lerp(120, 26, t));
        strokeWeight(lerp(2.6, 1.1, t));
        line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
      }
      const tip = pts[pts.length - 1];
      const r = random(2, 4.5);
      noStroke();
      fill(255, 226, 180, 40);
      circle(tip[0], tip[1], r * 4);
      fill(255, 236, 200, 200);
      circle(tip[0], tip[1], r);
    }
  }
}

function drawBloom() {
  const cx = 800, cy = 640;
  noStroke();
  for (const [r, a] of [[380, 10], [300, 14], [220, 20]]) {
    fill(255, 190, 160, a);
    circle(cx, cy, r * 2);
  }
  noFill();
  stroke(255, 210, 170, 14);
  strokeWeight(1.2);
  circle(cx, cy, 560);
  const ga = PI * (3 - sqrt(5));
  for (let i = 0; i < 180; i++) {
    const r = 13 * sqrt(i);
    if (r > 265) break;
    const a = i * ga + 0.4;
    const x = cx + cos(a) * r;
    const y = cy + sin(a) * r * 0.94;
    const t = r / 265;
    const c = lerpColor(color(255, 244, 214), color(255, 118, 158), t);
    fill(red(c), green(c), blue(c), lerp(170, 46, t));
    circle(x, y, lerp(7.5, 2.2, t));
  }
}

function drawHill() {
  noStroke();
  fill(9, 7, 18);
  beginShape();
  vertex(0, height);
  vertex(0, 1700);
  for (let x = 0; x <= width; x += 40) {
    vertex(x, 1690 - noise(x * 0.003) * 70 - (x > 300 && x < 1300 ? 26 : 0));
  }
  vertex(width, height);
  endShape(CLOSE);
  noFill();
  stroke(255, 150, 120, 14);
  strokeWeight(2);
  beginShape();
  for (let x = 0; x <= width; x += 40) {
    vertex(x, 1690 - noise(x * 0.003) * 70 - (x > 300 && x < 1300 ? 26 : 0));
  }
  endShape();
}

function drawCores() {
  noStroke();
  for (const [cx, cy] of [[430, 1560], [1170, 1560]]) {
    for (let i = 22; i >= 1; i--) {
      const t = 1 - i / 22;
      const c = lerpColor(color(255, 116, 138), color(255, 246, 226), t);
      fill(red(c), green(c), blue(c), lerp(4, 70, t));
      circle(cx, cy, i * 52);
    }
    fill(255, 210, 170, 16);
    ellipse(cx, cy, 380, 60);
    fill(255, 250, 235, 235);
    circle(cx, cy, 34);
    fill(255, 255, 255, 255);
    circle(cx, cy, 14);
  }
}

function drawPetals() {
  noStroke();
  for (let i = 0; i < 30; i++) {
    const x = random(480, 1120);
    const y = random(430, 1350);
    const s = random(6, 18);
    const warm = random() < 0.5;
    push();
    translate(x, y);
    rotate(random(TWO_PI) + noise(x * 0.01, y * 0.01) * 2);
    fill(255, warm ? 186 : 150, warm ? 196 : 170, random(35, 85));
    ellipse(0, 0, s, s * 0.45);
    pop();
  }
}

function drawVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(width / 2, height * 0.46, height * 0.28, width / 2, height * 0.5, height * 0.78);
  g.addColorStop(0, 'rgba(4,4,12,0)');
  g.addColorStop(1, 'rgba(4,4,12,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawGrain() {
  noStroke();
  for (let i = 0; i < 2600; i++) {
    if (random() < 0.5) fill(255, 255, 255, random(2, 6));
    else fill(0, 0, 8, random(2, 6));
    rect(random(width), random(height), random(1, 2.5), random(1, 2.5));
  }
}

const W = 1600, H = 2000;
const GOLD = [255, 196, 120], ROSE = [255, 140, 160], CREAM = [255, 236, 205],
      VIOLET = [150, 140, 255], COOL = [140, 170, 255];

function rgba(c, a) { return `rgba(${c[0]},${c[1]},${c[2]},${a})`; }

function rglow(x, y, r, stops, squash) {
  const ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  if (squash && squash !== 1) { ctx.translate(x, y); ctx.scale(1, squash); ctx.translate(-x, -y); }
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y, r, 0, TWO_PI); ctx.fill();
  ctx.restore();
}

function strand(x1, y1, x2, y2, bow, wd, rgb, a) {
  const c1x = lerp(x1, x2, 0.3) + random(-bow, bow),
        c1y = lerp(y1, y2, 0.3) + random(-bow, bow),
        c2x = lerp(x1, x2, 0.7) + random(-bow, bow),
        c2y = lerp(y1, y2, 0.7) + random(-bow, bow);
  noFill(); strokeCap(ROUND);
  stroke(rgb[0], rgb[1], rgb[2], a * 0.28); strokeWeight(wd * 4);
  bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);
  stroke(rgb[0], rgb[1], rgb[2], a); strokeWeight(wd);
  bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);
}

function ring(cx, cy, r, squash, rgb, a, wob, wd) {
  noFill();
  stroke(rgb[0], rgb[1], rgb[2], a); strokeWeight(wd);
  beginShape();
  const n = 160;
  for (let i = 0; i <= n; i++) {
    const t = i / n * TWO_PI;
    const rr = r + noise(cos(t) * 2.3 + 5, sin(t) * 2.3 + 5, r * 0.013) * wob;
    vertex(cx + cos(t) * rr, cy + sin(t) * rr * squash);
  }
  endShape(CLOSE);
}

function mote(x, y, s, rgb, a) {
  rglow(x, y, s * 4, [[0, rgba(rgb, a)], [1, rgba(rgb, 0)]]);
  noStroke(); fill(255, 255, 255, Math.min(1, a * 1.4));
  circle(x, y, Math.max(0.6, s * 0.9));
}

function reflect(cx, halfW, rgb, a0) {
  const ctx = drawingContext;
  const hy = H * 0.80;
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  for (let y = hy; y < H; y += 5) {
    const t = (y - hy) / (H - hy);
    const a = a0 * (1 - t) * (1 - t);
    if (a < 0.004) break;
    const off = noise(y * 0.008, cx * 0.001) * 36;
    ctx.globalAlpha = a;
    ctx.fillStyle = `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;
    ctx.fillRect(cx - halfW + off, y, halfW * 2, 5);
  }
  ctx.restore();
}

function grass(side) {
  noFill(); strokeCap(ROUND);
  for (let i = 0; i < 11; i++) {
    const x0 = side === 0 ? random(-20, W * 0.30) : random(W * 0.70, W + 20);
    const hgt = random(120, 400);
    const lean = (side === 0 ? 1 : -1) * random(40, 220);
    const wd = random(3, 9);
    const x1 = x0 + lean, y1 = H - hgt;
    stroke(10, 7, 18, 255); strokeWeight(wd);
    bezier(x0, H, x0 + lean * 0.15, H - hgt * 0.45, x1 - lean * 0.35, H - hgt * 0.75, x1, y1);
    if (random() < 0.5) {
      noStroke(); fill(12, 9, 20);
      push(); translate(x1, y1); rotate(lean * 0.004);
      ellipse(0, -hgt * 0.05, wd * 1.6, hgt * 0.09);
      pop();
    }
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();
}

function draw() {
  const ctx = drawingContext;
  const lx = W * 0.40, ly = H * 0.40, rx = W * 0.60, ry = H * 0.40;
  const mx = W * 0.50, my = H * 0.435;
  const hy = H * 0.80;

  // deep sky
  let g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#0a0d26');
  g.addColorStop(0.35, '#141034');
  g.addColorStop(0.62, '#241233');
  g.addColorStop(1, '#0b0716');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);

  // cool nebulae
  const nebs = [
    [W*0.15, H*0.10, 430, [90,110,220], 0.10],
    [W*0.85, H*0.14, 390, [170,90,200], 0.085],
    [W*0.78, H*0.33, 310, [80,140,220], 0.07],
    [W*0.24, H*0.28, 350, [120,80,200], 0.07],
    [W*0.50, H*0.05, 520, [60,70,160], 0.08]
  ];
  for (const n of nebs) rglow(n[0], n[1], n[2], [[0, rgba(n[3], n[4])], [1, rgba(n[3], 0)]]);

  // great ambient warmth
  rglow(mx, my, H * 0.55, [[0, rgba([255,160,90], 0.30)], [0.5, rgba([210,100,90], 0.12)], [1, rgba([210,100,90], 0)]]);

  // still water
  let wg = ctx.createLinearGradient(0, hy, 0, H);
  wg.addColorStop(0, '#150d24'); wg.addColorStop(1, '#050410');
  ctx.fillStyle = wg; ctx.fillRect(0, hy, W, H - hy);
  ctx.strokeStyle = rgba(CREAM, 0.10); ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(0, hy); ctx.lineTo(W, hy); ctx.stroke();

  // ripples where the light meets
  for (let i = 0; i < 9; i++) {
    const r = 190 + i * 78;
    ring(mx, my, r, 0.94, (i % 2 ? GOLD : CREAM), Math.max(0.03, 0.10 - i * 0.009), 60 + i * 22, 1.1);
  }

  // threads between the two lights
  for (let i = 0; i < 26; i++) {
    const a1 = random(TWO_PI), a2 = random(TWO_PI);
    const p1x = lx + cos(a1) * random(60, 240), p1y = ly + sin(a1) * random(60, 240);
    const p2x = rx + cos(a2) * random(60, 240), p2y = ry + sin(a2) * random(60, 240);
    strand(p1x, p1y, p2x, p2y, random(120, 520), random(0.8, 2.6),
           [GOLD, ROSE, CREAM][floor(random(3))], random(0.10, 0.30));
  }
  for (let i = 0; i < 10; i++) {
    strand(lx + random(-150, 60), ly + random(-280, -60),
           rx + random(-60, 150), ry + random(-280, -60),
           random(60, 200), random(0.8, 2), (i % 3 ? CREAM : VIOLET), random(0.08, 0.20));
  }
  for (let i = 0; i < 6; i++) {
    strand(lx + random(-200, 200), ly + random(-120, 120),
           rx + random(-200, 200), ry + random(-120, 120),
           random(200, 600), random(0.7, 1.6), VIOLET, random(0.05, 0.12));
  }
  for (let i = 0; i < 6; i++) {
    strand(lx + random(-60, 60), ly + random(80, 160),
           lx + random(-140, 140), hy + random(-30, 60),
           random(60, 160), random(0.7, 1.6), GOLD, random(0.06, 0.14));
    strand(rx + random(-60, 60), ry + random(80, 160),
           rx + random(-140, 140), hy + random(-30, 60),
           random(60, 160), random(0.7, 1.6), ROSE, random(0.06, 0.14));
  }

  // reflections on the water
  reflect(lx, 26, GOLD, 0.30);
  reflect(rx, 26, ROSE, 0.30);
  reflect(mx, 95, [255, 190, 130], 0.38);
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 46; i++) {
    const y = hy + random(H - hy);
    const cxs = [lx, rx, mx][i % 3] + random(-170, 170);
    const w = random(40, 260);
    ctx.strokeStyle = rgba([255, 190, 140], random(0.02, 0.07));
    ctx.lineWidth = random(1, 2.5);
    ctx.beginPath();
    ctx.moveTo(cxs - w / 2, y);
    ctx.lineTo(cxs + w / 2, y + random(-4, 4));
    ctx.stroke();
  }
  ctx.restore();

  // the two lights
  rglow(lx, ly, 300, [[0, 'rgba(255,240,215,0.95)'], [0.18, 'rgba(255,205,135,0.65)'], [0.5, 'rgba(255,150,80,0.22)'], [1, rgba([255,140,80], 0)]]);
  rglow(rx, ry, 300, [[0, 'rgba(255,232,228,0.95)'], [0.18, 'rgba(255,170,170,0.60)'], [0.5, 'rgba(255,110,130,0.20)'], [1, rgba([255,100,130], 0)]]);
  rglow(lx, ly, 95, [[0, 'rgba(255,255,245,0.9)'], [1, rgba([255,230,180], 0)]]);
  rglow(rx, ry, 95, [[0, 'rgba(255,255,250,0.9)'], [1, rgba([255,200,200], 0)]]);
  // where they meet
  rglow(mx, my + 10, 360, [[0, 'rgba(255,248,230,0.85)'], [0.35, 'rgba(255,215,155,0.40)'], [1, rgba([255,180,120], 0)]]);
  rglow(mx, my + 10, 130, [[0, 'rgba(255,255,252,0.95)'], [1, rgba([255,240,210], 0)]]);

  // drifting sparks
  for (let i = 0; i < 170; i++) {
    const src = random(3); let x, y;
    if (src < 1) { x = lx + randomGaussian() * 150; y = ly + randomGaussian() * 150; }
    else if (src < 2) { x = rx + randomGaussian() * 150; y = ry + randomGaussian() * 150; }
    else { x = mx + randomGaussian() * 230; y = my + randomGaussian() * 200; }
    mote(x, y, random(1.2, 3.6), [GOLD, ROSE, CREAM][floor(random(3))], random(0.25, 0.8));
  }
  for (let i = 0; i < 90; i++) {
    const cool = random() < 0.4;
    const c = cool ? [COOL, VIOLET, [220, 230, 255]][floor(random(3))] : [GOLD, CREAM][floor(random(2))];
    mote(random(W), random(H * 0.85), random(0.8, 2.6), c, random(0.12, 0.5));
  }
  for (let i = 0; i < 40; i++) {
    const t = random(1);
    const x = mx + randomGaussian() * 120 * (0.4 + t);
    const y = my - random(60, 620) * (0.3 + t * 0.7);
    if (y > 20) mote(x, y, random(1, 2.8), CREAM, random(0.15, 0.6) * (1 - t * 0.5));
  }
  for (let i = 0; i < 10; i++) {
    rglow(random(W), random(H * 0.7), random(30, 90),
          [[0, rgba([255, 220, 180], random(0.03, 0.07))], [1, rgba([255, 220, 180], 0)]]);
  }

  // grass silhouettes
  grass(0); grass(1);

  // vignette
  const vg = ctx.createRadialGradient(W/2, H*0.44, H*0.28, W/2, H*0.5, H*0.78);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(3,2,10,0.62)');
  ctx.fillStyle = vg; ctx.fillRect(0, 0, W, H);

  // canvas grain
  const gr = createGraphics(400, 500);
  gr.loadPixels();
  for (let i = 0; i < gr.pixels.length; i += 4) {
    const v = 128 + random(-46, 46);
    gr.pixels[i] = v; gr.pixels[i+1] = v; gr.pixels[i+2] = v; gr.pixels[i+3] = 255;
  }
  gr.updatePixels();
  ctx.save();
  ctx.globalAlpha = 0.05;
  ctx.globalCompositeOperation = 'overlay';
  ctx.drawImage(gr.canvas, 0, 0, W, H);
  ctx.restore();
}

// p5.js 1.11
// 无外部资源；画面不使用任何文字。
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  angleMode(RADIANS);

  backgroundWash();
  aureole();
  distantGarden();
  water();

  bird(false);
  bird(true);

  nest();
  foreground();
  paperGrain();
}

function backgroundWash() {
  const top = color('#102d37');
  const bottom = color('#254c50');

  for (let y = 0; y < height; y++) {
    stroke(lerpColor(top, bottom, y / height));
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 3200; i++) {
    let x = random(width);
    let y = random(height);
    fill(111, 157, 145, random(1, 5));
    ellipse(x, y, random(15, 90), random(12, 70));
  }
}

function aureole() {
  noStroke();

  // 层叠的薄色，留下柔软而不完全均匀的光晕。
  for (let r = 650; r > 555; r -= 3) {
    fill(202, 162, 95, 1.5);
    circle(800, 805, r * 2);
  }
  fill('#77715a');
  circle(800, 805, 1110);

  for (let r = 550; r > 0; r -= 5) {
    fill(213, 171, 105, 1.35);
    circle(800, 805, r * 2);
  }

  for (let i = 0; i < 14500; i++) {
    let a = random(TWO_PI);
    let r = sqrt(random()) * 550;
    let x = 800 + cos(a) * r;
    let y = 805 + sin(a) * r;
    let n = noise(x * 0.006, y * 0.006);
    fill(239, 208, 146, 5 + n * 19);
    circle(x, y, random(0.8, 3.4));
  }

  noFill();
  stroke(219, 187, 123, 90);
  strokeWeight(1.4);
  arc(800, 805, 1140, 1140, -2.86, -0.35);
  stroke(219, 187, 123, 42);
  arc(800, 805, 1163, 1163, -2.48, -0.75);

  noStroke();
  for (let i = 0; i < 100; i++) {
    let x = random(230, 1370);
    let y = random(210, 1160);
    if (dist(x, y, 800, 805) > 560) {
      fill(225, 195, 130, random(35, 130));
      circle(x, y, random(1.2, 3.2));
    }
  }
}

function distantGarden() {
  for (let side of [-1, 1]) {
    push();
    translate(800, 0);
    scale(side, 1);

    for (let j = 0; j < 10; j++) {
      let x = 510 + j * 22;
      let y = 1450 + random(-60, 100);
      let h = random(320, 700);
      let lean = random(-100, 25);

      noFill();
      stroke(104, 139, 123, 42);
      strokeWeight(random(1.4, 3));
      bezier(x, y, x - 20, y - h * 0.45,
             x + lean, y - h * 0.7, x + lean, y - h);

      for (let k = 1; k < 7; k++) {
        let t = k / 8;
        let lx = x + lean * t;
        let ly = y - h * t;
        push();
        translate(lx, ly);
        rotate(-0.7 + (k % 2) * 1.4);
        noStroke();
        fill(105, 142, 123, 28);
        ellipse(0, -26, 13, 65);
        pop();
      }
    }
    pop();
  }
}

function water() {
  noStroke();
  for (let y = 1370; y < 2000; y += 3) {
    fill(11, 44, 52, map(y, 1370, 2000, 0, 95));
    rect(0, y, width, 3);
  }

  for (let i = 0; i < 1000; i++) {
    let y = random(1440, 1930);
    let spread = map(y, 1440, 1930, 100, 360);
    let x = 800 + randomGaussian() * spread;
    let warm = abs(x - 800) < spread * 0.7;
    stroke(warm ? color(206, 168, 100, random(7, 28))
                : color(108, 163, 158, random(6, 22)));
    strokeWeight(random(0.6, 2.3));
    let w = random(5, 48);
    line(x - w, y, x + w, y);
  }
}

function bird(mirrored) {
  push();
  if (mirrored) {
    translate(1600, 0);
    scale(-1, 1);
  }

  const body = mirrored ? '#a5c6c0' : '#e5c9ac';
  const light = mirrored ? '#d6e5d7' : '#f4dfbd';
  const shadow = mirrored ? '#578f92' : '#b88873';
  const featherDark = mirrored ? '#78a7a6' : '#ceaa8e';
  const vein = mirrored ? color(40, 89, 94, 65)
                        : color(128, 83, 63, 62);

  // 肩膀与长颈：一条连续的剪影。
  noStroke();
  fill(body);
  beginShape();
  vertex(590, 1195);
  bezierVertex(565, 1100, 463, 940, 450, 807);
  bezierVertex(428, 669, 468, 541, 567, 510);
  bezierVertex(653, 485, 726, 526, 747, 580);
  bezierVertex(762, 607, 758, 632, 740, 646);
  bezierVertex(718, 666, 686, 654, 675, 631);
  bezierVertex(649, 593, 601, 595, 577, 638);
  bezierVertex(536, 709, 572, 825, 639, 914);
  bezierVertex(720, 1020, 747, 1140, 694, 1240);
  bezierVertex(657, 1265, 620, 1244, 590, 1195);
  endShape(CLOSE);

  // 颈部内侧的色带。
  fill(shadow);
  beginShape();
  vertex(692, 1207);
  bezierVertex(732, 1108, 673, 1008, 617, 920);
  bezierVertex(543, 806, 529, 696, 568, 635);
  bezierVertex(597, 590, 646, 576, 679, 615);
  bezierVertex(638, 556, 574, 585, 549, 631);
  bezierVertex(506, 712, 534, 845, 594, 944);
  bezierVertex(652, 1048, 672, 1140, 654, 1221);
  endShape(CLOSE);

  noFill();
  stroke(light);
  strokeWeight(5);
  bezier(481, 823, 450, 669, 501, 548, 588, 535);

  // 躯干与向上收拢的尾羽。
  noStroke();
  fill(body);
  beginShape();
  vertex(211, 1112);
  bezierVertex(332, 1191, 431, 1110, 539, 1078);
  bezierVertex(659, 1039, 779, 1165, 729, 1314);
  bezierVertex(688, 1452, 463, 1472, 335, 1350);
  bezierVertex(272, 1294, 237, 1201, 211, 1112);
  endShape(CLOSE);

  // 一片片铺叠的羽毛，不使用纹理图片。
  for (let i = 0; i < 24; i++) {
    let t = i / 23;
    let tx = 235 + 345 * t;
    let ty = 1150 + 258 * sin(t * HALF_PI);
    let rx = 594 + 36 * t;
    let ry = 1134 + 63 * t;
    let c = lerpColor(color(light), color(featherDark), t * 0.65);
    feather(rx, ry, tx, ty, 23 + 13 * sin(PI * t), c, vein);
  }

  // 肩上的短绒羽。
  for (let row = 0; row < 6; row++) {
    for (let j = 0; j < 9; j++) {
      let x = 477 + j * 20 + row * 9;
      let y = 1131 + row * 22 - 17 * sin(j / 8 * PI);
      noFill();
      stroke(mirrored ? color(232, 241, 220, 92)
                      : color(255, 237, 208, 115));
      strokeWeight(2.2);
      bezier(x - 10, y, x - 5, y + 15,
             x + 9, y + 17, x + 17, y + 6);
    }
  }

  // 深色喙在画面中线轻轻相接。
  noStroke();
  fill(mirrored ? '#294e54' : '#775349');
  beginShape();
  vertex(741, 616);
  bezierVertex(759, 626, 783, 645, 800, 665);
  bezierVertex(774, 662, 751, 652, 735, 641);
  endShape(CLOSE);
  stroke(mirrored ? '#adc6b4' : '#d7b28b');
  strokeWeight(1.4);
  line(747, 636, 794, 662);

  // 微垂的眼，避免拟人化的夸张表情。
  noFill();
  stroke('#254044');
  strokeWeight(4);
  bezier(690, 594, 698, 601, 707, 602, 715, 596);
  stroke(light);
  strokeWeight(2);
  bezier(686, 582, 695, 578, 707, 580, 714, 586);

  // 羽颈上的细碎干笔。
  for (let i = 0; i < 100; i++) {
    let t = random();
    let x = bezierPoint(477, 465, 510, 581, t);
    let y = bezierPoint(806, 677, 558, 536, t);
    stroke(mirrored ? color(236, 241, 221, 35)
                    : color(255, 241, 216, 40));
    strokeWeight(random(0.6, 1.6));
    line(x + random(3, 22), y, x + random(3, 22), y + random(3, 9));
  }
  pop();
}

function feather(rx, ry, tx, ty, w, c, vein) {
  let dx = tx - rx;
  let dy = ty - ry;
  let d = sqrt(dx * dx + dy * dy);
  let px = -dy / d;
  let py = dx / d;

  fill(c);
  stroke(vein);
  strokeWeight(0.8);
  beginShape();
  vertex(rx, ry);
  bezierVertex(
    rx + dx * 0.3 + px * w, ry + dy * 0.3 + py * w,
    tx + px * w * 0.5, ty + py * w * 0.5,
    tx, ty
  );
  bezierVertex(
    tx - px * w * 0.42, ty - py * w * 0.42,
    rx + dx * 0.4 - px * w * 0.7,
    ry + dy * 0.4 - py * w * 0.7,
    rx, ry
  );
  endShape(CLOSE);

  noFill();
  stroke(vein);
  strokeWeight(0.8);
  bezier(rx, ry, rx + dx * 0.35, ry + dy * 0.35,
         tx - dx * 0.18 + px * 3,
