        let y = lerp(by, ey, t);
        let dir = j % 2 ? -1 : 1;
        fill(j % 3 ? '#20484a' : '#315957');
        noStroke();
        beginShape();
        vertex(x, y);
        bezierVertex(x + dir * 50, y - 4,
                     x + dir * 75, y - 63, x + dir * 83, y - 94);
        bezierVertex(x + dir * 26, y - 80,
                     x + dir * 12, y - 33, x, y);
        endShape(CLOSE);
      }
    }
