function paperGrain() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let i = 4 * (y * width + x);
      let g = random(-4.5, 4.5);
      let edge = pow(
        max(abs(x - 800) / 800, abs(y - 1000) / 1000), 6
      ) * 9;
      pixels[i] = constrain(pixels[i] + g - edge, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + g - edge, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + g - edge, 0, 255);
    }
  }
  updatePixels();
}

