// p5.js 1.11
// 全部图形由程序绘制，无外部资源。
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

const C = {
  night: "#192e3b",
  blue: "#41616a",
  mint: "#91a69a",
  coral: "#cb795f",
  peach: "#e9b18a",
  gold: "#d5ab63",
  cream: "#f4dfaf",
  soil: "#563e3e"
};

function bez(p, t) {
  const u = 1 - t;
  return createVector(
    u*u*u*p[0] + 3*u*u*t*p[2] + 3*u*t*t*p[4] + t*t*t*p[6],
    u*u*u*p[1] + 3*u*u*t*p[3] + 3*u*t*t*p[5] + t*t*t*p[7]
  );
}

function tangent(p, t) {
  const u = 1 - t;
  return createVector(
    3*u*u*(p[2]-p[0]) + 6*u*t*(p[4]-p[2]) + 3*t*t*(p[6]-p[4]),
    3*u*u*(p[3]-p[1]) + 6*u*t*(p[5]-p[3]) + 3*t*t*(p[7]-p[5])
  ).normalize();
}

function curveLine(p, col, weight) {
  noFill();
  stroke(col);
  strokeWeight(weight);
  bezier(...p);
}

function leaf(x, y, angle, len, wide, col, vein = true) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  fill(col);
  beginShape();
  vertex(0, 0);
  bezierVertex(len*.24, -wide*.66, len*.73, -wide*.53, len, 0);
  bezierVertex(len*.68, wide*.47, len*.23, wide*.58, 0, 0);
  endShape(CLOSE);
  if (vein) {
    stroke(244, 223, 175, 65);
    strokeWeight(0.8);
    noFill();
    bezier(0, 0, len*.3, -wide*.07, len*.65, wide*.03, len*.88, 0);
  }
  pop();
}

function shelterPath() {
  const p = new Path2D();
  p.moveTo(407, 1475);
  p.bezierCurveTo(294, 1112, 440, 682, 800, 466);
  p.bezierCurveTo(1160, 682, 1306, 1112, 1193, 1475);
  p.closePath();
  return p;
}

function draw() {
  background(C.night);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  const ctx = drawingContext;
  const shelter = shelterPath();

  // 夜色的柔和层次。
  noStroke();
  for (let i = 0; i < 100; i++) {
    fill(79, 103, 105, 1.8);
    ellipse(800, 760, 1490-i*8, 1620-i*9);
  }

  // 远方的星点与细雨，避开树木围起的空间。
  for (let i = 0; i < 170; i++) {
    const x = random(70, 1530), y = random(65, 1350);
    if (!ctx.isPointInPath(shelter, x, y)) {
      noStroke();
      fill(224, 215, 175, random(35, 120));
      circle(x, y, random(1.4, 4));
    }
  }

  for (let i = 0; i < 390; i++) {
    const x = random(-70, 1600), y = random(70, 1450);
    const len = random(16, 53);
    if (!ctx.isPointInPath(shelter, x, y) &&
        !ctx.isPointInPath(shelter, x+len*.42, y+len)) {
      stroke(157, 183, 182, random(12, 43));
      strokeWeight(random(.7, 1.6));
      line(x, y, x+len*.42, y+len);
    }
  }

  // 树下不是一盏灯，而是一整片被保护的暖色。
  ctx.save();
  ctx.clip(shelter);
  const g = ctx.createLinearGradient(0, 440, 0, 1500);
  g.addColorStop(0, "#607875");
  g.addColorStop(.48, "#b5b38a");
  g.addColorStop(1, "#efcf8f");
  ctx.fillStyle = g;
  ctx.fillRect(220, 420, 1160, 1100);

  noStroke();
  for (let i = 0; i < 80; i++) {
    fill(255, 227, 160, 2.4);
    ellipse(800, 1300, 850-i*8, 1060-i*10);
  }

  // 轻微的颜料沉积。
  for (let i = 0; i < 6500; i++) {
    const x = random(300, 1300), y = random(450, 1500);
    fill(255, 236, 187, random(3, 12));
    ellipse(x, y, random(2, 9), random(1, 4));
  }
  ctx.restore();

  // 远景草坡。
  noStroke();
  fill("#687c70");
  beginShape();
  vertex(0, 1450);
  bezierVertex(270, 1355, 410, 1405, 650, 1440);
  bezierVertex(980, 1335, 1330, 1370, 1600, 1455);
  vertex(1600, 1640);
  vertex(0, 1640);
  endShape(CLOSE);

  // 地面剖面。
  fill(C.soil);
  beginShape();
  vertex(0, 1503);
  bezierVertex(330, 1540, 530, 1450, 800, 1457);
  bezierVertex(1110, 1464, 1330, 1545, 1600, 1490);
  vertex(1600, 2000);
  vertex(0, 2000);
  endShape(CLOSE);

  // 土壤中的薄层。
  for (let k = 0; k < 22; k++) {
    const y = 1540+k*22;
    noFill();
    stroke(196, 135, 104, 15);
    strokeWeight(random(1, 2.5));
    beginShape();
    for (let x = -20; x <= 1620; x += 35) {
      vertex(x, y + 17*sin(x*.006+k*.6) + 12*noise(x*.004, k));
    }
    endShape();
  }

  drawRoots();

  // 树脚旁的草与落叶。
  for (let i = 0; i < 100; i++) {
    const x = random(120, 1480);
    const y = 1478 + 23*sin(x*.006);
    if (abs(x-800) < 105) continue;
    stroke(random([C.blue, C.mint, "#9c9977"]));
    strokeWeight(random(1, 2.4));
    const h = random(8, 36);
    line(x, y, x+random(-12, 12), y-h);
  }

  const left = [424,1480, 293,1110, 469,680, 792,470];
  const right = [1176,1480, 1307,1110, 1131,680, 808,470];

  tree(left, C.coral, C.peach, true);
  tree(right, C.mint, C.cream, false);

  // 两梢相遇处，一小段金色的新枝。
  curveLine([758,497, 785,464, 823,448, 843,415], C.gold, 3);
  leaf(808, 457, -1.75, 42, 19, C.cream);
  leaf(825, 440, -.48, 36, 17, C.gold);

  // 幼芽周围低低的光。
  noStroke();
  for (let i = 0; i < 35; i++) {
    fill(245, 209, 137, 3);
    ellipse(800, 1462, 300-i*7, 70-i*1.5);
  }

  // 唯一的新生植物。
  curveLine([800,1463, 787,1410, 817,1357, 800,1301], "#536e59", 6);
  curveLine([801,1397, 780,1385, 761,1377, 747,1355], "#536e59", 3);
  leaf(797, 1393, -2.63, 91, 39, "#81936b");
  leaf(803, 1365, -.63, 89, 36, "#a4ae73");
  leaf(800, 1314, -1.87, 52, 23, C.cream);

  noStroke();
  fill(C.gold);
  ellipse(800, 1464, 17, 8);

  // 暖空气中缓慢浮动的微粒。
  for (let i = 0; i < 46; i++) {
    const x = random(580, 1020), y = random(1000, 1430);
    noStroke();
    fill(255, 235, 179, random(50, 155));
    circle(x, y, random(1.5, 4));
  }

  // 满版纸张颗粒：保留安静、略粗粝的印刷质感。
  noStroke();
  for (let i = 0; i < 65000; i++) {
    const x = random(width), y = random(height);
    if (random() < .5) fill(255, 236, 198, random(4, 14));
    else fill(20, 27, 34, random(4, 13));
    ellipse(x, y, random(.6, 2.5), random(.6, 2.3));
  }
}

function tree(p, trunkCol, lightCol, isLeft) {
  const palette = isLeft
    ? [C.coral, C.peach, C.gold, "#a65f51", "#ba9470"]
    : [C.mint, "#648783", C.gold, "#bac4a2", "#486d73"];

  // 每根枝条沿主干生长；叶片的朝向跟随枝条。
  for (let j = 0; j < 27; j++) {
    const t = .24 + j*.026;
    const q = bez(p, t);
    const d = tangent(p, t);
    const n = createVector(-d.y, d.x);
    const side = j%2 === 0 ? -1 : 1;
    const extent = random(105, 210) * (1-.24*t);
    const end = p5.Vector.add(q,
      p5.Vector.add(p5.Vector.mult(n, side*extent),
                    p5.Vector.mult(d, random(75, 150))));
    const branch = [
      q.x, q.y,
      q.x+d.x*70, q.y+d.y*70,
      end.x-d.x*45, end.y-d.y*45,
      end.x, end.y
    ];

    curveLine(branch, trunkCol, map(t, .24, .95, 8, 2.5));

    const count = floor(random(8, 13));
    for (let k = 1; k <= count; k++) {
      const u = k/(count+1);
      const a = bez(branch, u);
      const v = tangent(branch, u);
      const s = k%2 ? -1 : 1;
      const angle = atan2(v.y, v.x) + s*random(.55, 1.15);
      const len = random(30, 61) * (.8+.2*sin(u*PI));
      const stem = random(6, 15);
      const lx = a.x+cos(angle)*stem;
      const ly = a.y+sin(angle)*stem;

      stroke(trunkCol);
      strokeWeight(1.2);
      line(a.x, a.y, lx, ly);
      leaf(lx, ly, angle, len, len*random(.35, .53), random(palette));
    }
    const v = tangent(branch, 1);
    leaf(end.x, end.y, atan2(v.y,v.x), random(32, 51), 19, random(palette));
  }

  // 渐细的主干轮廓。
  noStroke();
  fill(trunkCol);
  beginShape();
  for (let i = 0; i <= 100; i++) {
    const t = i/100, q = bez(p,t), d = tangent(p,t);
    const w = 44*pow(1-t, .85)+3;
    vertex(q.x-d.y*w, q.y+d.x*w);
  }
  for (let i = 100; i >= 0; i--) {
    const t = i/100, q = bez(p,t), d = tangent(p,t);
    const w = 44*pow(1-t, .85)+3;
    vertex(q.x+d.y*w, q.y-d.x*w);
  }
  endShape(CLOSE);

  // 木纹用断续曲线，而非硬边描线。
  for (let k = 0; k < 7; k++) {
    const start = random(.015, .22);
    const stop = random(.65, .96);
    const offset = map(k, 0, 6, -.72, .72);
    const ink = color(lightCol);
    ink.setAlpha(random(40, 110));
    stroke(ink);
    strokeWeight(random(.8, 2.1));
    noFill();
    beginShape();
    for (let t = start; t <= stop; t += .012) {
      const q = bez(p,t), d = tangent(p,t);
      const w = (44*pow(1-t,.85)+3)*offset
              + 2*sin(t*25+k);
      vertex(q.x-d.y*w, q.y+d.x*w);
    }
    endShape();
  }
}

function drawRoots() {
  const roots = [
    [424,1474, 450,1645, 1000,1928, 1260,1750],
    [1176,1474, 1140,1650, 600,1940, 333,1770],
    [425,1482, 415,1630, 245,1705, 173,1840],
    [1175,1482, 1200,1642, 1390,1690, 1450,1850],
    [423,1480, 580,1570, 690,1685, 822,1860],
    [1177,1480, 1020,1570, 908,1700, 773,1885]
  ];

  roots.forEach((p, index) => {
    const col = index%2 === 0 ? C.coral : C.mint;

    // 从粗到细的根。
    for (let i = 0; i < 95; i++) {
      const t = i/95;
      const a = bez(p,t), b = bez(p,(i+1)/95);
      stroke(col);
      strokeWeight(22*pow(1-t,1.5)+1);
      line(a.x,a.y,b.x,b.y);
    }

    // 纤细支根留出大片土壤的负空间。
    for (let j = 0; j < 9; j++) {
      const t = .22+j*.075;
      const q = bez(p,t), d = tangent(p,t);
      const s = j%2 ? -1 : 1;
      const dx = random(40, 110)*s;
      const dy = random(48, 115);
      const twig = [
        q.x,q.y,
        q.x+d.x*35,q.y+32,
        q.x+dx*.65,q.y+dy,
        q.x+dx,q.y+dy
      ];
      const ink = color(col);
      ink.setAlpha(150);
      curveLine(twig, ink, random(1,2.5));
      const tip = bez(twig,.65);
      curveLine([
        tip.x,tip.y,
        tip.x+dx*.15,tip.y+12,
        tip.x+dx*.1,tip.y+34,
        tip.x+dx*.05,tip.y+48
      ], ink, .9);
    }
  });

  noStroke();
  for (let i = 0; i < 350; i++) {
    fill(212, 164, 119, random(15, 65));
    const x = random(80,1520), y = random(1550,1940);
    ellipse(x,y,random(1,4),random(1,3));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

let hx = 1080, hb, wallH = 190;

function groundY(x) {
  return 1330 - noise(x * 0.002, 50) * 40;
}

function draw() {
  hb = groundY(hx);
  drawSky();
  drawStars();
  drawHills();
  drawGround();
  drawHouse();
  drawSpill();
  let tFig = 0.62;
  drawFootprints(tFig);
  drawFigure(tFig);
  drawSmoke();
  drawSnow();
  drawVignette();
}

function drawSky() {
  for (let y = 0; y < 1400; y++) {
    let t = y / 1400;
    let c = lerpColor(color(6, 9, 28), color(52, 66, 110), pow(t, 1.6));
    stroke(c);
    line(0, y, width, y);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 320; i++) {
    let x = random(width);
    let y = random(950) * random(0.4, 1);
    fill(255, 250, 235, random(40, 200));
    circle(x, y, random(1, 3.2));
  }
  blendMode(ADD);
  for (let i = 0; i < 14; i++) {
    let x = random(width), y = random(700);
    for (let r = 14; r > 0; r -= 2) {
      fill(180, 200, 255, 6);
      circle(x, y, r);
    }
    fill(255, 255, 255, 200);
    circle(x, y, 2.5);
  }
  blendMode(BLEND);
}

function pine(x, y, h, col) {
  noStroke();
  fill(col);
  rect(x - h * 0.025, y - h * 0.15, h * 0.05, h * 0.18);
  for (let k = 0; k < 5; k++) {
    let yy = y - h + k * h * 0.17;
    let ww = h * 0.07 * (k + 1);
    triangle(x, yy - h * 0.1, x - ww, yy + h * 0.22, x + ww, yy + h * 0.22);
  }
}

function drawHills() {
  let layers = [
    { base: 1100, amp: 110, col: [34, 46, 84], sc: 0.0016, tree: [24, 32, 62] },
    { base: 1180, amp: 80, col: [50, 63, 104], sc: 0.0024, tree: [32, 42, 76] },
    { base: 1260, amp: 50, col: [68, 82, 124], sc: 0.003, tree: [40, 50, 86] }
  ];
  for (let i = 0; i < layers.length; i++) {
    let L = layers[i];
    noStroke();
    fill(L.col[0], L.col[1], L.col[2]);
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 8) {
      vertex(x, L.base - noise(x * L.sc, i * 10) * L.amp);
    }
    vertex(width, height);
    endShape(CLOSE);
    let n = 30 + i * 10;
    for (let k = 0; k < n; k++) {
      let x = random(width);
      let y = L.base - noise(x * L.sc, i * 10) * L.amp + 4;
      let h = random(30, 70) * (1 + i * 0.4);
      pine(x, y, h, color(L.tree[0], L.tree[1], L.tree[2]));
    }
  }
}

function drawGround() {
  let ctx = drawingContext;
  noStroke();
  fill(0);
  let g = ctx.createLinearGradient(0, 1280, 0, 2000);
  g.addColorStop(0, 'rgb(78,92,136)');
  g.addColorStop(1, 'rgb(128,142,188)');
  ctx.fillStyle = g;
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 8) vertex(x, groundY(x));
  vertex(width, height);
  endShape(CLOSE);

  // drifts
  for (let i = 0; i < 9; i++) {
    let y = 1400 + i * 70;
    fill(150, 165, 210, 14);
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 10) {
      vertex(x, y + (noise(x * 0.002, i * 3 + 100) - 0.5) * 120);
    }
    vertex(width, height);
    endShape(CLOSE);
  }
  // sparkle
  for (let i = 0; i < 2500; i++) {
    let x = random(width), y = random(1340, 2000);
    fill(220, 230, 255, random(20, 90));
    circle(x, y, random(0.8, 2.2));
  }
  // foreground pines beside the house
  pine(hx - 300, groundY(hx - 300) + 10, 330, color(18, 22, 40));
  pine(hx - 380, groundY(hx - 380) + 14, 230, color(22, 26, 46));
  pine(hx + 290, groundY(hx + 290) + 10, 260, color(20, 24, 42));
}

function drawHouse() {
  let left = hx - 150, w = 300;
  let top = hb - wallH;
  noStroke();
