  rect(wx, wy, ww, wh);
  fill(30, 30, 46);
  rect(wx + ww / 2 - 3, wy, 6, wh);
  rect(wx, wy + wh / 2 - 3, ww, 6);
  fill(170, 184, 222);
  rect(wx - 8, wy + wh, ww + 16, 8, 3);

