function drawSpill() {
  let ctx = drawingContext;
  noStroke();
  fill(0);
  blendMode(ADD);
  // warm pool on snow
  ctx.save();
  ctx.translate(hx - 30, hb + 50);
  ctx.scale(1, 0.32);
  let g = ctx.createRadialGradient(0, 0, 10, 0, 0, 620);
  g.addColorStop(0, 'rgba(255,170,90,0.42)');
  g.addColorStop(0.5, 'rgba(180,100,50,0.14)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(-700, -700, 1400, 1400);
  ctx.restore();
  // light from the open door, reaching toward the path
  let dx = hx + 40;
  let lg = ctx.createLinearGradient(dx, hb, dx - 300, hb + 520);
  lg.addColorStop(0, 'rgba(255,190,110,0.5)');
  lg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = lg;
  beginShape();
  vertex(dx, hb);
  vertex(dx + 26, hb);
  vertex(dx - 120, hb + 560);
  vertex(dx - 520, hb + 560);
  endShape(CLOSE);
  blendMode(BLEND);
}

function pathPt(t) {
  let P = [[330, 2060], [120, 1720], [880, 1600], [hx + 76, hb + 4]];
  let x = bezierPoint(P[0][0], P[1][0], P[2][0], P[3][0], t);
  let y = bezierPoint(P[0][1], P[1][1], P[2][1], P[3][1], t);
  let tx = bezierTangent(P[0][0], P[1][0], P[2][0], P[3][0], t);
  let ty = bezierTangent(P[0][1], P[1][1], P[2][1], P[3][1], t);
  return { x: x, y: y, a: atan2(ty, tx) };
}

function scaleAt(y) {
  return constrain(map(y, hb, 2000, 0.12, 1.05), 0.1, 1.2);
}

function drawFootprints(tEnd) {
  let N = 3000, acc = 0, side = 1;
  let prev = pathPt(0);
  noStroke();
  for (let i = 1; i <= N; i++) {
    let t = (i / N) * tEnd;
    let p = pathPt(t);
    acc += dist(p.x, p.y, prev.x, prev.y);
    prev = p;
    let s = scaleAt(p.y);
    if (acc >= 58 * s) {
      acc = 0;
      side *= -1;
      let ox = cos(p.a + HALF_PI) * 13 * s * side;
      let oy = sin(p.a + HALF_PI) * 13 * s * side * 0.6;
      let d = dist(p.x, p.y, hx, hb + 100);
      let warm = constrain(map(d, 700, 250, 0, 1), 0, 1);
      push();
      translate(p.x + ox, p.y + oy);
      rotate(p.a);
      scale(1, 0.55);
      fill(160, 175, 220, 60);
      ellipse(2 * s, 3 * s, 34 * s, 16 * s);
      let c = lerpColor(color(44, 52, 96, 200), color(120, 80, 70, 200), warm);
      fill(c);
      ellipse(0, 0, 32 * s, 14 * s);
      pop();
    }
  }
}

function drawFigure(t) {
  let p = pathPt(t);
  let s = scaleAt(p.y) * 1.05;
  let x = p.x, y = p.y;
  noStroke();
  // shadow
  fill(30, 36, 70, 110);
  ellipse(x - 40 * s, y + 6 * s, 130 * s, 22 * s);
  // legs
  fill(18, 18, 30);
  quad(x - 18 * s, y - 90 * s, x - 2 * s, y - 90 * s, x - 6 * s, y, x - 20 * s, y);
  quad(x + 2 * s, y - 90 * s, x + 18 * s, y - 90 * s, x + 22 * s, y - 2 * s, x + 8 * s, y - 2 * s);
  // coat
  fill(22, 22, 36);
  beginShape();
  vertex(x - 26 * s, y - 220 * s);
  vertex(x + 26 * s, y - 220 * s);
  vertex(x + 40 * s, y - 70 * s);
  vertex(x - 40 * s, y - 70 * s);
  endShape(CLOSE);
  // warm rim light on the side facing home
  fill(255, 170, 90, 120);
  quad(x + 22 * s, y - 218 * s, x + 27 * s, y - 218 * s, x + 41 * s, y - 72 * s, x + 35 * s, y - 72 * s);
  // head
  fill(22, 22, 36);
  circle(x, y - 248 * s, 46 * s);
  fill(255, 170, 90, 110);
  arc(x, y - 248 * s, 46 * s, 46 * s, -HALF_PI, HALF_PI);
  // red scarf
  fill(178, 38, 52);
  rect(x - 26 * s, y - 228 * s, 52 * s, 16 * s, 6 * s);
  beginShape();
  vertex(x - 22 * s, y - 214 * s);
  vertex(x - 8 * s, y - 214 * s);
  vertex(x - 30 * s, y - 160 * s);
  vertex(x - 44 * s, y - 166 * s);
  endShape(CLOSE);
}

function drawSmoke() {
  let cx = hx + 79, cy = hb - wallH - 178;
  noStroke();
  for (let i = 0; i < 90; i++) {
    let k = i / 90;
    let x = cx + (noise(i * 0.04, 200) - 0.5) * 220 * k + k * 120;
    let y = cy - i * 6;
    fill(170, 180, 215, 10 * (1 - k) + 2);
    circle(x, y, 20 + k * 110);
  }
}

function drawSnow() {
  noStroke();
  for (let i = 0; i < 1500; i++) {
    let x = random(width), y = random(height);
    let r = pow(random(), 3) * 8 + 1.2;
    fill(235, 240, 255, random(80, 210));
    circle(x, y, r);
  }
  // snow caught in the window light
  blendMode(ADD);
  for (let i = 0; i < 160; i++) {
    let a = random(TWO_PI), d = random(20, 260);
    let x = hx - 68 + cos(a) * d, y = hb - wallH + 87 + sin(a) * d;
    fill(255, 200, 130, map(d, 20, 260, 160, 20));
    circle(x, y, random(1.5, 4));
  }
  blendMode(BLEND);
}

function drawVignette() {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(900, 1250, 500, 800, 1100, 1450);
  g.addColorStop(0, 'rgba(0,0,10,0)');
  g.addColorStop(1, 'rgba(0,0,12,0.6)');
  noStroke();
  fill(0);
  ctx.fillStyle = g;
  rect(0, 0, width, height);
}

let P = [
  [52, 72, 110], [34, 46, 78], [196, 150, 72], [168, 84, 56],
  [128, 146, 112], [226, 212, 184], [196, 128, 120], [96, 110, 120],
  [210, 176, 90], [120, 84, 60]
];
let rects = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function split(x, y, w, h, d) {
  if (d >= 6 || (d >= 2 && random() < 0.22) || (w < 240 && h < 240)) {
    rects.push({ x, y, w, h });
    return;
  }
  let vert = w > h;
  if (random() < 0.2) vert = !vert;
  if (vert && w < 240) vert = false;
  if (!vert && h < 240) vert = true;
  let t = random(0.3, 0.7);
  if (vert) {
    let a = w * t;
    split(x, y, a, h, d + 1);
    split(x + a, y, w - a, h, d + 1);
  } else {
    let a = h * t;
    split(x, y, w, a, d + 1);
    split(x, y + a, w, h - a, d + 1);
  }
}

function drawPatch(p) {
  let g = 3;
  let x0 = p.x + g, y0 = p.y + g, w = p.w - 2 * g, h = p.h - 2 * g;
  let c = random(P);
  let c2 = random() < 0.5 ? [236, 224, 198] : [c[0] * 0.6, c[1] * 0.6, c[2] * 0.6];
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.rect(x0, y0, w, h);
  drawingContext.clip();
  noStroke();
  fill(c[0], c[1], c[2]);
  rect(x0, y0, w, h);
  let type = floor(random(5));
  if (type == 1) {
    let sp = random(18, 46);
    let diag = random() < 0.4;
    stroke(c2[0], c2[1], c2[2], 150);
    strokeWeight(sp * random(0.2, 0.45));
    strokeCap(SQUARE);
    for (let s = -h; s < w + h; s += sp) {
      if (diag) line(x0 + s, y0, x0 + s + h, y0 + h);
      else line(x0 + s, y0, x0 + s, y0 + h);
    }
  } else if (type == 2) {
    let sp = random(28, 50);
    noStroke();
    fill(c2[0], c2[1], c2[2], 170);
    let row = 0;
    for (let yy = y0; yy < y0 + h + sp; yy += sp * 0.87) {
      let off = (row % 2) * sp / 2;
      for (let xx = x0 - sp; xx < x0 + w + sp; xx += sp) {
        circle(xx + off, yy, sp * 0.3);
      }
      row++;
    }
  } else if (type == 3) {
    let sp = random(30, 60);
    noStroke();
    fill(c2[0], c2[1], c2[2], 70);
    for (let s = 0; s < w; s += sp) rect(x0 + s, y0, sp / 2, h);
    for (let s = 0; s < h; s += sp) rect(x0, y0 + s, w, sp / 2);
  } else if (type == 4) {
    let cnt = (w * h) / 9000;
    noStroke();
    for (let i = 0; i < cnt; i++) {
      let cx = random(x0, x0 + w), cy = random(y0, y0 + h);
      fill(c2[0], c2[1], c2[2], 190);
      let rot = random(TAU);
      for (let k = 0; k < 5; k++) {
        circle(cx + cos(rot + k * TAU / 5) * 7, cy + sin(rot + k * TAU / 5) * 7, 9);
      }
      fill(230, 190, 90, 220);
      circle(cx, cy, 5);
    }
  }
  // weave texture
  strokeWeight(1);
  let n = (w * h) / 120;
  for (let i = 0; i < n; i++) {
    let x = random(x0, x0 + w), y = random(y0, y0 + h);
    if (random() < 0.5) stroke(255, 255, 255, 18);
    else stroke(0, 0, 0, 22);
    if (random() < 0.5) line(x, y, x + random(4, 10), y);
    else line(x, y, x, y + random(4, 10));
  }
  // wear and fading
  noStroke();
  for (let k = 0; k < 3; k++) {
    let ex = random(x0, x0 + w), ey = random(y0, y0 + h);
    let ew = random(100, 400), eh = random(80, 300);
    for (let j = 0; j < 6; j++) {
      fill(255, 245, 225, 8);
      ellipse(ex, ey, ew * (1 - j * 0.14), eh * (1 - j * 0.14));
    }
  }
  drawingContext.restore();
  noFill();
  stroke(0, 70);
  strokeWeight(4);
  rect(x0 + 2, y0 + 2, w - 4, h - 4);
  stroke(255, 30);
  strokeWeight(1);
  rect(x0 + 6, y0 + 6, w - 12, h - 12);
}

function dashLine(x1, y1, x2, y2) {
  let len = dist(x1, y1, x2, y2);
  let dx = (x2 - x1) / len, dy = (y2 - y1) / len;
  for (let s = 8; s < len - 14; s += 24) {
    let j1 = random(-1.2, 1.2), j2 = random(-1.2, 1.2);
    let ax = x1 + dx * s - dy * j1, ay = y1 + dy * s + dx * j1;
    let bx = x1 + dx * (s + 12) - dy * j2, by = y1 + dy * (s + 12) + dx * j2;
    stroke(0, 60);
    line(ax + 1.5, ay + 2, bx + 1.5, by + 2);
    stroke(232, 220, 190, 220);
    line(ax, ay, bx, by);
  }
}

function seams(p) {
  strokeWeight(3);
  strokeCap(ROUND);
  let i = 13;
  let x0 = p.x + i, y0 = p.y + i, x1 = p.x + p.w - i, y1 = p.y + p.h - i;
  dashLine(x0, y0, x1, y0);
  dashLine(x1, y0, x1, y1);
  dashLine(x1, y1, x0, y1);
  dashLine(x0, y1, x0, y0);
}

function drawTearHole(t) {
  let n = 24;
  let dx = cos(t.a), dy = sin(t.a);
  let px = -dy, py = dx;
  let top = [], bot = [];
  for (let i = 0; i <= n; i++) {
    let u = i / n;
    let al = (u - 0.5) * t.L;
    let hw = sin(PI * u) * random(5, 13) + 0.5;
    let cx = t.x + dx * al + px * random(-2, 2);
    let cy = t.y + dy * al + py * random(-2, 2);
    top.push([cx + px * hw, cy + py * hw]);
    bot.push([cx - px * hw * random(0.6, 1.1), cy - py * hw * random(0.6, 1.1)]);
  }
  noStroke();
  fill(0, 60);
  beginShape();
  for (let q of top) vertex(q[0] + 3, q[1] + 3);
  for (let i = bot.length - 1; i >= 0; i--) vertex(bot[i][0] + 3, bot[i][1] + 3);
  endShape(CLOSE);
  fill(24, 17, 14);
  beginShape();
  for (let q of top) vertex(q[0], q[1]);
  for (let i = bot.length - 1; i >= 0; i--) vertex(bot[i][0], bot[i][1]);
  endShape(CLOSE);
  // frayed fibers
  strokeWeight(1.2);
  for (let k = 0; k < 40; k++) {
    let arr = random() < 0.5 ? top : bot;
    let q = random(arr);
    stroke(225, 210, 180, 150);
    line(q[0], q[1], q[0] + random(-6, 6), q[1] + random(-6, 6));
  }
}

function crossStitch(t) {
  let dx = cos(t.a), dy = sin(t.a);
  let px = -dy, py = dx;
  let n = floor(t.L / 24);
  strokeCap(ROUND);
  for (let i = 0; i <= n; i++) {
    let al = (i / n - 0.5) * t.L * 0.88;
    let cx = t.x + dx * al, cy = t.y + dy * al;
    let s = random(20, 27);
    let tilt = (i % 2 == 0 ? 1 : -1) * random(4, 8);
    let ax = cx + px * s - dx * tilt, ay = cy + py * s - dy * tilt;
    let bx = cx - px * s + dx * tilt, by = cy - py * s + dy * tilt;
    noStroke();
    fill(20, 12, 10, 160);
    circle(ax, ay, 6);
    circle(bx, by, 6);
    stroke(0, 80);
    strokeWeight(7);
    line(ax + 3, ay + 4, bx + 3, by + 4);
    stroke(178, 30, 40);
    strokeWeight(6.5);
    line(ax, ay, bx, by);
    stroke(235, 110, 110, 160);
    strokeWeight(1.8);
    line(ax - px * 1.5, ay - py * 1.5, bx - px * 1.5, by - py * 1.5);
  }
}

function catmull(pts, steps) {
  let out = [];
  let p = [pts[0]].concat(pts, [pts[pts.length - 1]]);
  for (let i = 1; i < p.length - 2; i++) {
    for (let s = 0; s < steps; s++) {
      let t = s / steps, t2 = t * t, t3 = t2 * t;
      let f = (a, b, c, d) =>
        0.5 * (2 * b + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t2 + (-a + 3 * b - 3 * c + d) * t3);
      out.push([
        f(p[i - 1][0], p[i][0], p[i + 1][0], p[i + 2][0]),
        f(p[i - 1][1], p[i][1], p[i + 1][1], p[i + 2][1])
      ]);
    }
  }
  out.push(pts[pts.length - 1]);
  return out;
}

function draw() {
  background(30, 24, 20);
  split(60, 60, 1480, 1880, 0);
  for (let p of rects) drawPatch(p);
  for (let p of rects) seams(p);

  let base = [[420, 330], [1150, 560], [500, 880], [1120, 1180], [430, 1450], [1000, 1680]];
  let tears = base.map((b) => ({
    x: b[0] + random(-30, 30),
    y: b[1] + random(-25, 25),
    a: random(-0.9, 0.9) + (random() < 0.5 ? 0 : PI / 2),
    L: random(110, 190)
  }));
  for (let t of tears) drawTearHole(t);

  // running stitch connecting every mend
  let start = [200, 170];
  let pts = [start].concat(tears.map((t) => [t.x, t.y]));
  let path = catmull(pts, 60);
  for (let i = 0; i < path.length; i++) {
    path[i][0] += (noise(i * 0.02) - 0.5) * 40;
    path[i][1] += (noise(i * 0.02 + 50) - 0.5) * 40;
  }
  let acc = 0;
  strokeCap(ROUND);
  let segs = [];
  for (let i = 1; i < path.length; i++) {
    let a = path[i - 1], b = path[i];
    let d = dist(a[0], a[1], b[0], b[1]);
    acc += d;
    let near = false;
    for (let t of tears) if (dist(b[0], b[1], t.x, t.y) < t.L / 2 + 18) near = true;
    if (acc % 42 < 27 && !near) segs.push([a, b]);
  }
  stroke(0, 80);
  strokeWeight(7);
  for (let s of segs) line(s[0][0] + 3, s[0][1] + 4, s[1][0] + 3, s[1][1] + 4);
  stroke(178, 30, 40);
  strokeWeight(6);
  for (let s of segs) line(s[0][0], s[0][1], s[1][0], s[1][1]);
  stroke(235, 110, 110, 140);
  strokeWeight(1.6);
  for (let s of segs) line(s[0][0] - 1, s[0][1] - 1.5, s[1][0] - 1, s[1][1] - 1.5);

  // knot at start
  noStroke();
  fill(0, 90);
  circle(start[0] + 3, start[1] + 4, 18);
  fill(160, 24, 34);
  circle(start[0], start[1], 16);
  fill(235, 120, 120, 150);
  circle(start[0] - 3, start[1] - 3, 5);

  for (let t of tears) crossStitch(t);

  // slack thread to the needle
  let lt = tears[tears.length - 1];
  let E = [1230, 1790];
  let ang = 0.5;
  noFill();
  stroke(0, 70);
  strokeWeight(7);
  bezier(lt.x + 4, lt.y + 6, 1030, 1920, 1170, 1920, E[0] + 4, E[1] + 6);
  stroke(178, 30, 40);
  strokeWeight(6);
  bezier(lt.x, lt.y, 1020, 1910, 1170, 1910, E[0], E[1]);
  stroke(235, 110, 110, 140);
  strokeWeight(1.6);
  bezier(lt.x - 1, lt.y - 2, 1020, 1908, 1170, 1908, E[0] - 1, E[1] - 2);

  // needle
  push();
  translate(E[0], E[1]);
  rotate(ang);
  translate(22, 0);
  noStroke();
  fill(0, 80);
  beginShape();
  vertex(-36 + 5, -4 + 7); vertex(200 + 5, -3.5 + 7); vertex(250 + 5, 7);
  vertex(200 + 5, 3.5 + 7); vertex(-36 + 5, 4 + 7);
  endShape(CLOSE);
  fill(178, 184, 190);
  beginShape();
  vertex(-36, -4); vertex(200, -3.5); vertex(250, 0); vertex(200, 3.5); vertex(-36, 4);
  endShape(CLOSE);
  ellipse(-36, 0, 9, 8);
  stroke(250, 250, 255, 210);
  strokeWeight(1.5);
  line(-30, -1.6, 215, -1);
  noStroke();
  fill(35, 30, 30);
  ellipse(-22, 0, 18, 3.2);
  pop();

  // thread tail through the eye
  noFill();
  stroke(0, 60);
  strokeWeight(6);
  bezier(E[0] + 3, E[1] + 5, E[0] - 30, E[1] - 30, E[0] - 70, E[1] - 10, E[0] - 85, E[1] + 30);
  stroke(178, 30, 40);
  strokeWeight(5);
  bezier(E[0], E[1], E[0] - 30, E[1] - 34, E[0] - 72, E[1] - 14, E[0] - 88, E[1] + 26);

  // light, grain, vignette
  noiseDetail(2, 0.5);
  loadPixels();
  let cx = 800, cy = 1000, md = dist(0, 0, cx, cy);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let i = 4 * (y * width + x);
      let nn = noise(x * 0.003, y * 0.003);
      let d = dist(x, y, cx, cy) / md;
      let lw = 1 - dist(x, y, 350, 250) / 2600;
      let f = (1 - 0.5 * d * d) * (0.86 + 0.28 * nn) * (0.8 + 0.35 * lw);
      let gr = random(-9, 9);
      pixels[i] = constrain(pixels[i] * f * 1.06 + gr, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * f + gr, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * f * 0.9 + gr, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

const H = 1100; // 地平线
const F = 420;  // 透视系数
const CX = 800;

function draw() {
  const ctx = drawingContext;

  // —— 天空 ——
  let g = ctx.createLinearGradient(0, 0, 0, H + 20);
  g.addColorStop(0, '#070a24');
  g.addColorStop(0.55, '#171d47');
  g.addColorStop(0.85, '#3a3a68');
  g.addColorStop(1, '#5b5478');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, H + 20);

  // 星星
  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(width), y = pow(random(), 1.6) * 950;
    let s = random() < 0.95 ? random(0.8, 2) : random(2.5, 3.6);
    fill(230, 235, 255, random(60, 200) * map(y, 0, 950, 1, 0.3));
    circle(x, y, s);
  }

  // —— 远山 ——
  drawHills(1010, 70, 0.0025, color(38, 40, 78), 0);
  drawHills(1055, 50, 0.004, color(30, 32, 64), 50);
  // 远处的松树
  for (let i = 0; i < 70; i++) {
    let x = random(width);
    if (x > 820 && x < 1200) continue;
    let base = 1060 + noise(x * 0.004 + 50) * 50 - 20 + random(10, 40);
    let h = random(18, 45);
    fill(22, 24, 50);
    triangle(x - h * 0.28, base, x + h * 0.28, base, x, base - h);
  }

  // —— 雪地 ——
  g = ctx.createLinearGradient(0, H, 0, height);
  g.addColorStop(0, '#4b5277');
  g.addColorStop(0.3, '#626b93');
  g.addColorStop(1, '#8b95b8');
  ctx.fillStyle = g;
  noStroke();
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 10) {
    vertex(x, H + noise(x * 0.003, 9) * 18 - 9);
  }
  vertex(width, height);
  endShape(CLOSE);

  // 雪堆的柔和阴影
  for (let i = 0; i < 40; i++) {
    let y = random(H + 40, height);
    let d = (y - H) / (height - H);
    fill(40, 46, 82, 18);
    ellipse(random(width), y, random(300, 900) * d + 100, random(30, 120) * d + 10);
  }
  for (let i = 0; i < 30; i++) {
    let y = random(H + 40, height);
    let d = (y - H) / (height - H);
    fill(190, 200, 235, 12);
    ellipse(random(width), y, random(300, 900) * d + 100, random(20, 80) * d + 10);
  }

  // 雪的颗粒质感
  for (let i = 0; i < 26000; i++) {
    let x = random(width), y = random(H, height);
    let n = noise(x * 0.01, y * 0.01);
    stroke(n > 0.5 ? color(200, 210, 240, 40) : color(40, 45, 80, 35));
    strokeWeight(random(0.6, 1.8));
    point(x, y);
  }
  noStroke();

  // —— 窗光洒在雪地上 ——
  blendMode(ADD);
  ctx.save();
  ctx.translate(1060, 1160);
  ctx.scale(1, 0.22);
  g = ctx.createRadialGradient(0, 0, 0, 0, 0, 750);
  g.addColorStop(0, 'rgba(255,170,90,0.42)');
  g.addColorStop(0.35, 'rgba(220,120,60,0.16)');
  g.addColorStop(1, 'rgba(120,60,30,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, 750, 0, TWO_PI);
  ctx.fill();
  ctx.restore();
  // 从窗口投下的光斑
  ctx.save();
  g = ctx.createLinearGradient(0, 1130, 0, 1260);
  g.addColorStop(0, 'rgba(255,190,110,0.35)');
  g.addColorStop(1, 'rgba(255,150,80,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(1040, 1134);
  ctx.lineTo(1092, 1134);
  ctx.lineTo(1170, 1260);
  ctx.lineTo(1030, 1260);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
  blendMode(BLEND);

  // —— 脚印 ——
  drawFootprints();

  // —— 光秃的树 ——
  stroke(18, 18, 38);
  branch(790, 1132, -HALF_PI, 70, 9, 6);
  noStroke();

  // —— 小屋 ——
  drawHouse();

  // —— 炊烟 ——
  for (let i = 0; i < 260; i++) {
    let t = i / 260;
    let x = 1092 + (noise(t * 3, 4) - 0.5) * 160 * t - t * 120;
    let y = 945 - t * 520;
    fill(150, 150, 185, 9 * (1 - t));
    circle(x, y, 20 + t * 110);
  }

  // —— 窗光晕 ——
  blendMode(ADD);
  radial(1065, 1062, 380, 'rgba(255,150,70,0.30)', 'rgba(255,120,50,0)');
  radial(1065, 1062, 120, 'rgba(255,200,120,0.45)', 'rgba(255,150,70,0)');
  blendMode(BLEND);

  // —— 飘雪 ——
  for (let i = 0; i < 900; i++) {
    let y = random(height);
    let x = random(width);
    let near = random();
    let s = near < 0.9 ? random(1.5, 4) : random(6, 12);
    let a = near < 0.9 ? random(80, 180) : random(40, 90);
    fill(235, 238, 255, a);
    circle(x, y, s);
    if (s > 6) {
      fill(235, 238, 255, a * 0.3);
      circle(x, y, s * 1.8);
    }
  }

  // —— 暗角 ——
  ctx.save();
  g = ctx.createRadialGradient(width / 2, 1150, 300, width / 2, 1150, 1400);
  g.addColorStop(0, 'rgba(5,6,20,0)');
  g.addColorStop(1, 'rgba(5,6,20,0.65)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function drawHills(base, amp, sc, c, off) {
  fill(c);
  noStroke();
  beginShape();
  vertex(0, H + 30);
  for (let x = 0; x <= width; x += 8) {
    vertex(x, base - noise(x * sc + off) * amp * 2 + amp);
  }
  vertex(width, H + 30);
  endShape(CLOSE);
}

function radial(x, y, r, c0, c1) {
  const ctx = drawingContext;
  ctx.save();
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, c0);
  g.addColorStop(1, c1);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TWO_PI);
  ctx.fill();
  ctx.restore();
}

function drawFootprints() {
  noStroke();
  let i = 0;
  for (let z = 0.47; z < 11.4; z += 0.12) {
    i++;
    let u = (z - 0.47) / 11.53;
    let X = lerp(-0.22, 4.86, u) + sin(z * 0.55) * 0.9 * sin(PI * u);
    let side = (i % 2 === 0) ? -1 : 1;
    let Xs = X + side * 0.085 + (noise(i * 0.7) - 0.5) * 0.03;
    let sx = CX + Xs * F / z;
    let sy = H + F / z;
    let w = 24 / z;
    let h = w * lerp(1.6, 0.9, u);
    let a = lerp(190, 70, pow(u, 0.6));
    let ang = side * 0.08 + (noise(i * 1.3) - 0.5) * 0.1;

    push();
    translate(sx, sy);
    rotate(ang);
    // 被翻起的雪边，略亮
    fill(185, 195, 230, a * 0.5);
    ellipse(0, -h * 0.18 + h * 0.08, w * 1.1, h * 0.75);
    ellipse(0, h * 0.33 + h * 0.06, w * 0.95, h * 0.55);
    // 凹陷的阴影
    fill(36, 42, 78, a);
    ellipse(0, -h * 0.18, w, h * 0.7);
    ellipse(0, h * 0.33, w * 0.82, h * 0.48);
    // 靠近小屋的脚印染上暖光
    if (u > 0.75) {
      fill(255, 160, 90, (u - 0.75) * 4 * 35);
      ellipse(0, -h * 0.18, w, h * 0.7);
      ellipse(0, h * 0.33, w * 0.82, h * 0.48);
    }
    pop();
  }
}

function branch(x, y, ang, len, depth, wgt) {
  if (depth === 0 || len < 3) return;
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  strokeWeight(wgt);
  line(x, y, x2, y2);
  let n = depth > 6 ? 2 : (random() < 0.5 ? 2 : 3);
