function drawHills() {
  const ctx = drawingContext;
  let layers = [
    { base: 1010, amp: 160, sc: 0.0016, col: 'rgb(34,40,72)' },
    { base: 1070, amp: 110, sc: 0.0022, col: 'rgb(46,54,90)' },
    { base: 1130, amp: 70, sc: 0.003, col: 'rgb(58,68,106)' }
  ];
  for (let i = 0; i < layers.length; i++) {
    let L = layers[i];
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(0, height);
    for (let x = 0; x <= width; x += 4) {
      ctx.lineTo(x, L.base + (noise(x * L.sc, i * 10) - 0.5) * L.amp);
    }
    ctx.lineTo(width, height);
    ctx.closePath();
    ctx.fillStyle = L.col;
    ctx.fill();
    ctx.restore();
    // pines on hills
    let n = i === 0 ? 14 : i === 1 ? 10 : 7;
    for (let k = 0; k < n; k++) {
      let x = random(width);
      if (abs(x - HX) < 260 && i > 0) continue;
      let y = L.base + (noise(x * L.sc, i * 10) - 0.5) * L.amp + 6;
      let h = random(40, 90) * (0.6 + i * 0.35);
      drawPine(x, y, h, color(20 + i * 8, 24 + i * 9, 46 + i * 12));
    }
  }
}

function drawPine(x, y, h, c) {
  noStroke();
  fill(c);
  let tiers = 4;
  for (let t = 0; t < tiers; t++) {
    let ty = y - (h * t) / tiers * 0.8;
    let w = h * 0.38 * (1 - t / (tiers + 1));
    triangle(x - w, ty, x + w, ty, x, ty - h * 0.45);
  }
  fill(red(c) + 60, green(c) + 65, blue(c) + 70, 120);
  let w = h * 0.12;
  triangle(x - w, y - h * 0.62, x + w, y - h * 0.62, x, y - h * 0.82);
}

function drawGround() {
  const ctx = drawingContext;
  ctx.save();
