  ctx.moveTo(0, height);
  for (let x = 0; x <= width; x += 4) ctx.lineTo(x, gY(x));
  ctx.lineTo(width, height);
  ctx.closePath();
  let g = ctx.createLinearGradient(0, 1150, 0, 2000);
  g.addColorStop(0, 'rgb(78,90,130)');
  g.addColorStop(0.5, 'rgb(112,126,166)');
  g.addColorStop(1, 'rgb(150,164,200)');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.restore();
}

