function drawFootprints() {
  let pts = [
    [520, 2150], [470, 2040], [640, 1820], [440, 1590],
    [700, 1420], [960, 1290], [HX + 30, BY + 30], [HX + 48, BY + 6], [HX + 48, BY + 6]
  ];
  let samples = [];
  for (let i = 0; i < pts.length - 3; i++) {
    for (let s = 0; s < 1; s += 0.004) {
      let x = curvePoint(pts[i][0], pts[i + 1][0], pts[i + 2][0], pts[i + 3][0], s);
      let y = curvePoint(pts[i][1], pts[i + 1][1], pts[i + 2][1], pts[i + 3][1], s);
      samples.push([x, y]);
    }
  }
  let acc = 0;
  let side = 1;
  noStroke();
  for (let i = 1; i < samples.length - 1; i++) {
    let [x0, y0] = samples[i - 1];
    let [x1, y1] = samples[i];
    acc += dist(x0, y0, x1, y1);
    let sc = constrain(map(y1, BY, 2000, 0.07, 1), 0.07, 1.1);
    let stride = 75 * sc;
    if (acc >= stride && y1 < 2010) {
      acc = 0;
      let ang = atan2(y1 - y0, x1 - x0);
      let px = x1 + cos(ang + HALF_PI) * side * 14 * sc;
      let py = y1 + sin(ang + HALF_PI) * side * 14 * sc;
      let warm = constrain(map(dist(px, py, HX, BY), 0, 450, 1, 0), 0, 1);
      push();
      translate(px, py);
      rotate(ang + random(-0.12, 0.12));
      // highlight rim
      fill(lerpColor(color(205, 215, 240, 90), color(255, 215, 160, 120), warm));
      ellipse(-2 * sc, -3 * sc, 40 * sc, 19 * sc);
      // depression
      fill(lerpColor(color(50, 60, 102, 170), color(120, 80, 70, 150), warm));
      ellipse(4 * sc, 0, 26 * sc, 13 * sc);
      ellipse(-12 * sc, 0, 14 * sc, 11 * sc);
      pop();
      side *= -1;
    }
  }
}

function drawSnowfall() {
