}

function drawSky() {
  let c1 = color(16, 20, 50), c2 = color(92, 60, 110), c3 = color(238, 160, 110);
  for (let y = 0; y < GY + 40; y++) {
    let t = y / GY;
    let c = t < 0.6 ? lerpColor(c1, c2, t / 0.6) : lerpColor(c2, c3, constrain((t - 0.6) / 0.4, 0, 1));
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = random(width), y = random(GY * 0.6);
    let b = random();
    fill(255, 245, 225, 40 + 190 * b * (1 - y / (GY * 0.6)));
    circle(x, y, random(1, 3.2));
  }
  blendMode(ADD);
  for (let r = 700; r > 0; r -= 10) {
    fill(255, 140, 70, 2);
    ellipse(800, GY, r * 2.2, r * 0.9);
  }
  blendMode(BLEND);
}

function drawHills() {
  noStroke();
  for (let layer = 0; layer < 2; layer++) {
    fill(layer == 0 ? color(78, 54, 92) : color(48, 36, 66));
    beginShape();
    vertex(0, GY + 5);
    for (let x = 0; x <= width; x += 10) {
      let h = noise(x * 0.002 + layer * 10, layer * 5) * (layer == 0 ? 170 : 100);
      vertex(x, GY - h + (layer == 0 ? 20 : 35));
    }
    vertex(width, GY + 5);
    endShape(CLOSE);
  }
}

function drawSoil() {
  noStroke();
  for (let y = GY; y < height; y += 2) {
    let t = (y - GY) / (height - GY);
    fill(lerpColor(color(58, 36, 26), color(18, 11, 9), t));
    rect(0, y, width, 2);
  }
  noFill();
  for (let k = 0; k < 7; k++) {
    let by = GY + 100 + k * 170 + random(-30, 30);
    stroke(0, 0, 0, 30);
    strokeWeight(random(15, 45));
    beginShape();
    for (let x = -20; x <= width + 20; x += 20) {
      vertex(x, by + (noise(x * 0.003, k * 3) - 0.5) * 80);
    }
    endShape();
  }
  noStroke();
  for (let i = 0; i < 12000; i++) {
    let y = random(GY, height);
    let l = random(0.5, 1.6);
    fill(70 * l, 46 * l, 32 * l, random(40, 120));
    ellipse(random(width), y, random(1, 4), random(1, 3));
  }
  for (let i = 0; i < 70; i++) {
    let g = random(55, 85);
    fill(g, g * 0.82, g * 0.7, 200);
    ellipse(random(width), random(GY + 40, height), random(8, 30), random(6, 20));
  }
}

function root(x, y, ang, len, w, tx, ty, steer, depth, col) {
  let steps = floor(len / 6);
  strokeCap(ROUND);
  for (let i = 0; i < steps; i++) {
    let target = atan2(ty - y, tx - x);
    let d = target - ang;
    while (d > PI) d -= TWO_PI;
    while (d < -PI) d += TWO_PI;
    ang += d * steer + (noise(x * 0.01, y * 0.01, depth * 7) - 0.5) * 0.25;
    let nx = x + cos(ang) * 6, ny = y + sin(ang) * 6;
    if (ny < GY + 6) { ny = GY + 6; ang = abs(ang); }
    if (ny > height + 10 || nx < -20 || nx > width + 20) return;
    let ww = w * (1 - i / steps) + 0.6;
    stroke(red(col) * 0.8, green(col) * 0.8, blue(col) * 0.8, 210);
    strokeWeight(ww);
    line(x, y, nx, ny);
    if (depth < 4 && ww > 1.2 && random() < 0.035) {
      root(nx, ny, ang + random([-1, 1]) * random(0.4, 1.1),
        len * random(0.3, 0.55) * (1 - i / steps + 0.3), ww * 0.6,
        nx + random(-300, 300), ny + random(100, 400), 0.02, depth + 1, col);
    }
    x = nx; y = ny;
  }
}

function drawBraid(colA, colB) {
  const N = 500;
  let A = [], B = [], K = [];
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let ax = bezierPoint(480, 500, 1100, 1150, t);
    let ay = bezierPoint(840, 1300, 1500, 1850, t);
    let bx = bezierPoint(1120, 1100, 500, 450, t);
    let by = bezierPoint(840, 1300, 1500, 1850, t);
    let k = exp(-pow((t - 0.5) / 0.15, 2));
    let mx = (ax + bx) / 2, my = (ay + by) / 2;
    ax = lerp(ax, mx, k); ay = lerp(ay, my, k);
    bx = lerp(bx, mx, k); by = lerp(by, my, k);
    let off = 24 * k * sin(t * TWO_PI * 9);
    A.push([ax + off, ay]);
    B.push([bx - off, by]);
    K.push(k);
  }

  // fine root hairs sprouting from the braided roots
  for (let i = 20; i < N; i += 8) {
    if (K[i] < 0.2 && random() < 0.5) {
      let p = random() < 0.5 ? A[i] : B[i];
      let c = p === A[i] ? colA : colB;
      root(p[0], p[1], random(TWO_PI), random(80, 220), random(2, 4),
        p[0] + random(-200, 200), p[1] + random(50, 250), 0.02, 2, c);
    }
  }

  strokeCap(ROUND);
  for (let i = 0; i < N; i++) {
    let t = i / N;
    let w = lerp(24, 4, t);
    let order = cos(t * TWO_PI * 9) > 0 ? [[B, colB], [A, colA]] : [[A, colA], [B, colB]];
    for (const [P, c] of order) {
      let p = P[i], q = P[i + 1];
      stroke(red(c) * 0.35, green(c) * 0.3, blue(c) * 0.3);
      strokeWeight(w + 4);
      line(p[0], p[1], q[0], q[1]);
      stroke(c);
      strokeWeight(w);
      line(p[0], p[1], q[0], q[1]);
      stroke(min(255, red(c) + 50), min(255, green(c) + 45), min(255, blue(c) + 35), 180);
      strokeWeight(w * 0.3);
      line(p[0] - w * 0.2, p[1], q[0] - w * 0.2, q[1]);
    }
  }

  // warmth where they hold each other
  blendMode(ADD);
  noStroke();
  for (let i = 0; i <= N; i += 3) {
    if (K[i] > 0.25) {
      let p = A[i];
      fill(255, 150, 70, 5 * K[i]);
      circle(p[0], p[1], 220 * K[i]);
      fill(255, 190, 110, 8 * K[i]);
      circle(p[0], p[1], 70 * K[i]);
    }
  }
  for (let i = 0; i < 120; i++) {
    let j = floor(random(N * 0.33, N * 0.67));
    let p = A[j];
    fill(255, 210, 140, random(40, 120) * K[j]);
    circle(p[0] + random(-60, 60), p[1] + random(-40, 40), random(1.5, 4));
  }
  blendMode(BLEND);
}

function drawSurface() {
  stroke(255, 180, 120, 90);
  strokeWeight(2);
  line(0, GY + 1, width, GY + 1);
  strokeWeight(1.5);
  for (let i = 0; i < 1600; i++) {
    let x = random(width);
    let h = random(4, 18) * (0.5 + noise(x * 0.01));
    stroke(30, 24, 30, 220);
    line(x, GY + 3, x + random(-4, 4), GY + 3 - h);
  }
}

function branch(x, y, ang, len, w, d) {
  let x2 = x + cos(ang) * len, y2 = y + sin(ang) * len;
  stroke(22, 16, 26);
  strokeWeight(w);
  line(x, y, x2, y2);
  if (d > 0) {
    let n = d > 6 ? 2 : (random() < 0.5 ? 2 : 3);
    for (let i = 0; i < n; i++) {
      branch(x2, y2,
        ang + random(-0.4, 0.4) + (i - (n - 1) / 2) * 0.42,
        len * random(0.68, 0.8), w * 0.68, d - 1);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 深邃夜空背景
  background(6, 5, 14);

  // 2. 绘制背景星云与环境微光
  blendMode(ADD);
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(80, 400);
    let distToCenter = dist(x, y, 800, 1000);
    if (distToCenter < 900) {
      let c = lerpColor(color(15, 25, 65, 2), color(65, 15, 35, 2), noise(x * 0.002, y * 0.002));
      noStroke();
      fill(c);
      circle(x, y, r);
    }
  }

  // 漫天繁星
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.5);
    let a = random(20, 150);
    if (random() < 0.1) s *= 2;
    fill(255, 245, 235, a);
    circle(x, y, s);
  }

  // 3. 计算双螺旋主轴轨迹（两个灵魂的靠近与缠绕）
  let spineA = [];
  let spineB = [];
  let steps = 1200;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;

    // 纵向位置：使用S型缓动，让画面中心（拥抱处）的点更密集
    let easeT = t < 0.5 ? 2 * t * t : 1 - pow(-2 * t + 2, 2) / 2;
    let y = lerp(1950, 150, easeT);

    // 旋转角度：越靠近中心旋转越紧密
    let angle = t * TWO_PI * 2.2 + sin(t * PI) * 1.5;

    // 彼此的距离半径：从底部遥远，到中心紧贴，再到顶部交融上升
    let radius;
    if (t < 0.55) {
      let normT = t / 0.55;
      radius = lerp(650, 25, pow(normT, 0.7));
    } else {
      let normT = (t - 0.55) / 0.45;
      radius = lerp(25, 160, pow(normT, 1.5));
    }

    // 整体中心线的自然摆动
    let centerX = 800 + sin(t * PI * 1.5 - 0.5) * 120 * sin(t * PI);
    let centerY = y + cos(t * PI * 3) * 30 * sin(t * PI);

    let ax = centerX + cos(angle) * radius;
    let ay = centerY + sin(angle) * radius * 0.35; // 压扁Y轴形成三维透视感

    let bx = centerX + cos(angle + PI) * radius;
    let by = centerY + sin(angle + PI) * radius * 0.35;

    spineA.push(createVector(ax, ay));
    spineB.push(createVector(bx, by));
  }

  // 4. 绘制两个灵魂之间的引力丝线（羁绊）
  strokeWeight(0.6);
  for (let i = 0; i < steps; i += 2) {
    let pA = spineA[i];
    let pB = spineB[i];
    let d = pA.dist(pB);

    if (d < 500) {
      let alpha = map(d, 0, 500, 70, 0);
      let cA = color(255, 90, 60, alpha);
      let cB = color(50, 190, 255, alpha);
      let cMid = color(255, 220, 150, alpha * 1.5);

      let n1 = noise(i * 0.05, 1) * 150 - 75;
      let n2 = noise(i * 0.05, 2) * 150 - 75;

      noFill();
      // 绘制连接彼此的柔和曲线
      for(let k = 0; k < 3; k++) {
        let amt = k / 2;
        stroke(lerpColor(lerpColor(cA, cB, amt), cMid, 0.5));
        bezier(
          pA.x, pA.y,
          lerp(pA.x, pB.x, 0.3) + n1, lerp(pA.y, pB.y, 0.3) - n2,
          lerp(pA.x, pB.x, 0.7) - n1, lerp(pA.y, pB.y, 0.7) + n2,
          pB.x, pB.y
        );
      }
    }
  }

  // 5. 绘制灵魂的丝绸轨迹（成千上万条微光曲线）
  let numStrands = 1600;

  const drawStrand = (spine, isWarm, seedOffset) => {
    for (let s = 0; s < numStrands; s++) {
      let offsetAngle = random(TWO_PI);
      let baseSpread = abs(randomGaussian(0, 55));
      let noiseFreq = random(0.008, 0.025);
      let phase = random(1000);

      let c1, c2, cCore;
      if (isWarm) {
        c1 = color(210, 20, 60);    // 深红
        c2 = color(255, 120, 30);   // 暖橙
        cCore = color(255, 230, 160); // 金白
      } else {
        c1 = color(20, 50, 180);    // 深蓝
        c2 = color(0, 210, 230);    // 青色
        cCore = color(200, 245, 255); // 冰白
      }

      let baseCol = lerpColor(c1, c2, random());
      let proximityToCenter = constrain(1 - baseSpread / 120, 0, 1);
      let finalCol = lerpColor(baseCol, cCore, pow(proximityToCenter, 2));

      // 距离核心越近越亮，边缘如薄纱般透明
      let alpha = map(baseSpread, 0, 150, 35, 2, true);
      finalCol.setAlpha(alpha);

      stroke(finalCol);
      strokeWeight(random(0.4, 1.8));
      noFill();

      // 将长轨迹分段绘制，创造流动的呼吸感
      let segLength = floor(random(80, 250));
      let startIdx = floor(random(0, steps - segLength));

      beginShape();
      for (let i = startIdx; i < startIdx + segLength; i += 4) {
        let t = i / steps;
        let p = spine[i];

        // 在中心交汇处（t约0.55）丝线收紧并剧烈共鸣
        let pinch = map(abs(t - 0.55), 0, 0.5, 0.35, 1.3);
        let currentSpread = baseSpread * pinch;

        let n = noise(i * noiseFreq, s * 0.1 + seedOffset);
        let a = offsetAngle + (n - 0.5) * 5 + t * 8;
        let r = currentSpread * (0.4 + 0.8 * noise(i * 0.02, phase));

        let vx = p.x + cos(a) * r;
        let vy = p.y + sin(a) * r;
        curveVertex(vx, vy);
      }
      endShape();
    }
  };

  drawStrand(spineA, true, 0);
  drawStrand(spineB, false, 5000);

  // 6. 绘制交汇核心的耀眼光芒与进发的火花（爱的结晶与升华）
  for (let i = 0; i < steps; i++) {
    let pA = spineA[i];
    let pB = spineB[i];
    let d = pA.dist(pB);

    // 当两个灵魂足够靠近时，产生强烈的金光
    if (d < 180) {
      let mid = p5.Vector.lerp(pA, pB, 0.5);
      let intensity = pow(map(d, 0, 180, 1, 0), 2);

      noStroke();
      // 核心柔光
      fill(255, 210, 140, intensity * 6);
      circle(mid.x, mid.y, random(50, 220) * intensity);

      fill(255, 245, 220, intensity * 12);
      circle(mid.x, mid.y, random(10, 60) * intensity);

      // 迸发的爱情火花/光尘
      let sparkCount = floor(intensity * 8);
      for (let k = 0; k < sparkCount; k++) {
        let ang = random(TWO_PI);
        let distR = abs(randomGaussian(0, 160 * intensity));
        let sx = mid.x + cos(ang) * distR;
        let sy = mid.y + sin(ang) * distR;

        let sparkSize = random(1, 4.5);
        let sparkAlpha = map(distR, 0, 300, 220, 0, true) * intensity;

        if (random() < 0.5) {
          fill(255, 230, 180, sparkAlpha); // 金色光尘
        } else if (random() < 0.5) {
          fill(255, 140, 120, sparkAlpha); // 暖粉光尘
        } else {
          fill(140, 230, 255, sparkAlpha); // 冰蓝光尘
        }
        circle(sx, sy, sparkSize);
      }
    }
  }

  // 7. 中心主拥抱点的神圣光晕（视觉焦点）
  let nexusA = spineA[floor(steps * 0.55)];
  let nexusB = spineB[floor(steps * 0.55)];
  let nexus = p5.Vector.lerp(nexusA, nexusB, 0.5);

  noStroke();
  for (let r = 800; r > 0; r -= 8) {
    let normR = r / 800;
    let a = pow(1 - normR, 3.5) * 4.5;
    let c = lerpColor(color(255, 240, 200), color(255, 100, 150), normR);
    c.setAlpha(a);
    fill(c);
    circle(nexus.x, nexus.y, r);
  }

  // 放射状的细腻光丝（象征爱意扩散到宇宙）
  for (let i = 0; i < 350; i++) {
    let ang = random(TWO_PI);
    let len = random(40, 550) * pow(random(), 1.5);
    strokeWeight(random(0.3, 1.2));
    stroke(255, 235, 205, random(5, 30));

    let x1 = nexus.x + cos(ang) * random(5, 30);
    let y1 = nexus.y + sin(ang) * random(5, 30);
    let x2 = nexus.x + cos(ang) * len;
    let y2 = nexus.y + sin(ang) * len;
    line(x1, y1, x2, y2);
  }

  // 8. 画面边缘暗角处理，让视线更聚焦于中心的光芒
  blendMode(BLEND);
  noFill();
  for (let r = 1800; r < 2700; r += 4) {
    let a = map(r, 1800, 2700, 0, 180);
    stroke(4, 3, 10, a);
    strokeWeight(6);
    circle(800, 1000, r);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 绘制深邃的背景与星辰
  drawBackground();

  // 2. 开启加法混合模式，绘制光的交织
  blendMode(ADD);

  // 3. 绘制底层的灵魂引力场（柔和的薄雾与微光）
  drawBackgroundAura();

  // 4. 绘制两条交织的生命轨迹（代表两个独立的个体）
  // 左侧起源：温暖的琥珀与珊瑚红
  // 右侧起源：深邃的青色与星辰蓝
  drawIntertwiningPaths();

  // 5. 绘制中心交汇处的共生之光与升华的余韵
  drawConvergenceCore();

  // 6. 恢复混合模式，添加画布暗角以凝聚视线
  blendMode(BLEND);
  drawVignette();
}

function drawBackground() {
  background(5, 6, 12);

  // 绘制背景中微弱的星尘
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, width * 0.5, height * 0.45);

    // 越靠近中心，星辰越密集
    if (random(1500) > d * 0.7) {
      let s = random(0.5, 2.5);
      let a = random(20, 120);
      if (random() < 0.1) {
        fill(255, 220, 180, a * 1.5); // 暖星
      } else if (random() < 0.2) {
        fill(180, 220, 255, a * 1.5); // 冷星
      } else {
        fill(255, 255, 255, a);
      }
      circle(x, y, s);
    }
  }
}

function drawBackgroundAura() {
  noStroke();
  let cx = width * 0.5;
  let cy = height * 0.45;

  // 中心交汇的巨大柔光
  for (let r = 1200; r > 50; r -= 25) {
    let inter = map(r, 50, 1200, 1, 0);
    fill(30 * inter, 15 * inter, 45 * inter, 4);
    circle(cx, cy, r * 1.2);
  }

  // 暖色引力源光晕
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    let x = lerp(width * 0.2, cx, t) + sin(t * PI * 2) * 200 * (1 - t);
    let y = lerp(height * 0.9, cy, t);
    fill(40, 10, 15, 6);
    circle(x, y, random(300, 700) * (1 - t * 0.5));
  }

  // 冷色引力源光晕
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    let x = lerp(width * 0.8, cx, t) - sin(t * PI * 2) * 200 * (1 - t);
    let y = lerp(height * 0.9, cy, t);
    fill(10, 25, 45, 6);
    circle(x, y, random(300, 700) * (1 - t * 0.5));
  }
}

function drawIntertwiningPaths() {
  let numStrands = 1800; // 每一方的丝线数量
  let steps = 260;       // 每根丝线的步数

  let cx = width * 0.5;
  let cy = height * 0.45;

  // 交织绘制，使冷暖丝线在空间中自然穿插
  for (let i = 0; i < numStrands; i++) {
    let progress = i / numStrands;

    // 绘制暖色丝线 (Entity A)
    drawSingleStrand(true, progress, steps, cx, cy);

    // 绘制冷色丝线 (Entity B)
    drawSingleStrand(false, progress, steps, cx, cy);
  }
}

function drawSingleStrand(isWarm, progress, steps, cx, cy) {
  noFill();

  // 起点设置：底部两侧
  let startX = isWarm ? random(width * 0.05, width * 0.4) : random(width * 0.6, width * 0.95);
  let startY = random(height * 0.85, height * 1.05);

  // 为每根丝线分配独特的噪声偏移和螺旋属性
  let noiseOffset = random(10000);
  let spiralFreq = random(1.2, 2.2) * PI;
  let spiralAmp = random(150, 450);
  let phase = isWarm ? 0 : PI; // 两个个体相位相反，形成双螺旋环绕

  // 越靠后绘制的丝线越亮、越细、越靠近核心
  let coreAffinity = pow(progress, 1.5); 
  strokeWeight(lerp(2.5, 0.6, coreAffinity));

  beginShape();
  for (let s = 0; s <= steps; s++) {
    let t = s / steps;

    // 基础上升路径：从底部向中心汇聚，然后向上升华
    let baseY = lerp(startY, height * 0.08, pow(t, 0.85));

    // 随着上升，螺旋半径在中心(t=0.65左右)收缩到最小，随后再次舒展如花朵
    let pinch = abs(t - 0.65);
    let radiusFactor = constrain(pow(pinch * 1.8, 1.2), 0.02, 1.0);
    // 核心丝线收缩得更紧
    radiusFactor *= lerp(1.0, 0.3, coreAffinity);

    let angle = t * spiralFreq + phase + (noise(noiseOffset, t * 2) - 0.5) * 2;
    let spiralOffset = cos(angle) * spiralAmp * radiusFactor;

    let baseX = lerp(startX, cx, sin(t * PI * 0.5));
    let x = baseX + spiralOffset;
    let y = baseY + sin(angle) * spiralAmp * 0.3 * radiusFactor;

    // 加入流体柏林噪声，赋予丝线有机生命感
    let nScale = 0.0025;
    let nAngle = noise(x * nScale, y * nScale, t * 1.5) * TWO_PI * 3;
    let nForce = lerp(80, 15, coreAffinity) * sin(t * PI);

    x += cos(nAngle) * nForce;
    y += sin(nAngle) * nForce;

    // 中心引力场的强力牵引
    let dToCenter = dist(x, y, cx, cy);
    if (dToCenter < 500) {
      let pull = pow(map(dToCenter, 0, 500, 1, 0), 2) * 0.4;
      x = lerp(x, cx, pull);
      y = lerp(y, cy, pull);
    }

    vertex(x, y);
  }

  // 计算颜色：根据个体属性与核心亲和度渐变
  let alpha = lerp(4, 18, coreAffinity);
  if (isWarm) {
    // 从深红、珊瑚橙到耀眼的金白
    let r = lerp(220, 255, coreAffinity);
    let g = lerp(40, 210, pow(coreAffinity, 1.2));
    let b = lerp(60, 170, pow(coreAffinity, 2.0));
    stroke(r, g, b, alpha);
  } else {
    // 从深蓝、青绿到璀璨的冰蓝白
    let r = lerp(20, 190, pow(coreAffinity, 2.0));
    let g = lerp(100, 230, pow(coreAffinity, 1.2));
    let b = lerp(220, 255, coreAffinity);
    stroke(r, g, b, alpha);
  }

  endShape();
}

function drawConvergenceCore() {
  let cx = width * 0.5;
  let cy = height * 0.45;

  // 1. 绘制核心交汇处的缠绕光环（如同两个灵魂的拥抱）
  noFill();
  for (let i = 0; i < 600; i++) {
    let r = random(10, 320) * pow(random(), 1.5);
    let angleStart = random(TWO_PI);
    let angleLen = random(PI * 0.2, PI * 1.2);

    strokeWeight(random(0.5, 2.0));

    // 色彩在冷暖与纯白之间交融
    let colType = random();
    if (colType < 0.4) {
      stroke(255, 180, 120, random(5, 25)); // 暖金
    } else if (colType < 0.8) {
      stroke(120, 210, 255, random(5, 25)); // 冰蓝
    } else {
      stroke(255, 240, 255, random(10, 35)); // 纯白偏紫（融合色）
    }

    // 略微倾斜的椭圆轨道，增强立体感
    push();
    translate(cx, cy);
    rotate(sin(i) * 0.4);
    beginShape();
    for (let a = angleStart; a < angleStart + angleLen; a += 0.1) {
      let nr = r + (noise(cos(a) * 2, sin(a) * 2, i * 0.1) - 0.5) * 40;
      let x = cos(a) * nr;
      let y = sin(a) * nr * 0.85;
      vertex(x, y);
    }
    endShape();
    pop();
  }

  // 2. 绘制核心爆发的璀璨光晕
  noStroke();
  for (let r = 400; r > 0; r -= 4) {
    let t = map(r, 0, 400, 1, 0);
    let alpha = pow(t, 3) * 12;
    fill(255, 235, 220, alpha);
    circle(cx, cy, r);
  }

  // 极亮的核心点
  fill(255, 255, 255, 200);
  circle(cx, cy, 12);
  fill(255, 255, 255, 80);
  circle(cx, cy, 45);

  // 3. 迸发的爱意微粒（向四周及上方飘散的光点）
  for (let i = 0; i < 1500; i++) {
    let angle = random(TWO_PI);
    // 距离分布：越靠近中心越密集，同时向上方延伸
    let distPow = pow(random(), 2.2);
    let d = distPow * 900;

    let x = cx + cos(angle) * d * 0.8;
    let y = cy + sin(angle) * d - pow(distPow, 1.5) * 300; // 向上漂浮的趋势

    // 加入噪声扰动
    x += (noise(i, x * 0.005) - 0.5) * 150;
    y += (noise(i, y * 0.005) - 0.5) * 150;

    let s = map(distPow, 0, 1, random(2, 6), random(0.5, 2));
    let a = map(distPow, 0, 1, random(100, 255), random(10, 50));

    if (random() < 0.45) {
      fill(255, random(140, 220), random(100, 180), a); // 暖光尘
    } else if (random() < 0.9) {
      fill(random(100, 180), random(180, 240), 255, a); // 冷光尘
    } else {
      fill(255, 255, 255, a * 1.2); // 纯白星火
    }

    circle(x, y, s);

    // 为部分大光点添加柔和光晕
    if (s > 3.5 && random() < 0.3) {
      fill(255, 230, 210, a * 0.2);
      circle(x, y, s * 4);
    }
  }
}

function drawVignette() {
  // 使用多层半透明圆环构建自然的暗角，使画面更具沉浸感
  noFill();
  let cx = width * 0.5;
  let cy = height * 0.5;
  let maxR = dist(0, 0, cx, cy);

  for (let r = maxR * 0.65; r <= maxR * 1.1; r += 8) {
    let alpha = map(r, maxR * 0.65, maxR * 1.05, 0, 180);
    alpha = constrain(alpha, 0, 180);
    stroke(3, 4, 8, alpha * 0.15);
    strokeWeight(12);
    circle(cx, cy, r * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 深邃的宇宙背景
  background(7, 9, 19);

  // 2. 绘制背景星群与微尘
  drawStarfield();

  // 3. 开启发光混合模式
  blendMode(ADD);

  // 中心交汇点
  let cx = width * 0.5;
  let cy = height * 0.48;

  // 4. 底层氛围光晕
  drawAmbientGlow(cx, cy);

  // 5. 绘制两股交织的灵魂轨迹（冷色与暖色）
  drawStreams(cx, cy);

  // 6. 绘制中心共舞的光轨与金色尘埃
  drawResonance(cx, cy);

  // 7. 绘制两颗核心星辰
  drawCores(cx, cy);

  // 8. 恢复混合模式，添加暗角与质感画框
  blendMode(BLEND);
  drawVignette();
}

function drawStarfield() {
  noStroke();
  for (let i = 0; i < 6000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    if (random() < n * 1.2) {
      let sz = pow(random(), 4) * 3.5 + 0.5;
      let alpha = random(30, 180) * n;
      if (random() < 0.3) {
        fill(255, 220, 200, alpha);
      } else if (random() < 0.6) {
        fill(180, 220, 255, alpha);
      } else {
        fill(255, 255, 255, alpha);
      }
      circle(x, y, sz);
    }
  }
}

function drawAmbientGlow(cx, cy) {
  noStroke();
  // 中心金色与紫罗兰的融合光晕
  for (let r = 1200; r > 0; r -= 15) {
    let inter = map(r, 0, 1200, 1, 0);
    let alpha = pow(inter, 3.5) * 4;
    fill(160, 80, 130, alpha);
    circle(cx, cy, r * 1.3);
  }

  // 暖色源头余晖（左下）
  for (let r = 900; r > 0; r -= 20) {
    let inter = map(r, 0, 900, 1, 0);
    fill(200, 50, 70, pow(inter, 3) * 2.5);
    circle(width * 0.25, height * 0.75, r);
  }

  // 冷色源头余晖（右上）
  for (let r = 900; r > 0; r -= 20) {
    let inter = map(r, 0, 900, 1, 0);
    fill(30, 110, 180, pow(inter, 3) * 2.5);
    circle(width * 0.75, height * 0.25, r);
  }
}

function drawStreams(cx, cy) {
  noFill();
  let numLines = 2200;
  let steps = 420;
  let dt = 3.2;

  for (let i = 0; i < numLines; i++) {
    let isWarm = i % 2 === 0;
    let x, y;

    // 设定两条星流的发源区域
    if (isWarm) {
      x = random(-200, width * 0.65);
      y = random(height * 0.65, height + 200);
    } else {
      x = random(width * 0.35, width + 200);
      y = random(-200, height * 0.35);
    }

    let sw = random(0.4, 2.0);
    strokeWeight(sw);

    let baseAlpha = random(4, 14);
    if (random() < 0.05) {
      // 少数明亮的主干流线
      baseAlpha = random(20, 45);
      strokeWeight(sw * 1.3);
    }

    // 色彩变化微调
    let colorShift = random(-25, 25);

    for (let s = 0; s < steps; s++) {
      let dx = cx - x;
      let dy = cy - y;
      let d = sqrt(dx * dx + dy * dy);

      // 朝向中心的引力角度
      let angleToCenter = atan2(dy, dx);

      // 靠近中心时，引力转化为旋转切线力（拥抱的姿态）
      let swirlFactor = exp(-d / 650);
      let pullAngle = angleToCenter + swirlFactor * (PI * 0.49);

      // 柏林噪声带来的自然流动感
      let n = noise(x * 0.0012, y * 0.0012, (isWarm ? 0 : 50));
      let noiseAngle = n * TWO_PI * 2.5;

      // 远距离受噪声主导，近距离受引力与旋转主导
      let finalAngle = pullAngle + sin(noiseAngle) * (0.85 - swirlFactor * 0.5);

      let nx = x + cos(finalAngle) * dt;
      let ny = y + sin(finalAngle) * dt;

      // 计算与中心的接近度，决定色彩如何升华
      let proximity = constrain(map(d, 750, 40, 0, 1), 0, 1);
      proximity = pow(proximity, 1.6);

      // 轨迹首尾淡入淡出
      let stepFade = sin(map(s, 0, steps, 0, PI));
      let currentAlpha = baseAlpha * stepFade * (1 + proximity * 1.8);

      let r, g, b;
      if (isWarm) {
        // 暖色流：深红/珊瑚色 -> 璀璨金白
        r = lerp(235 + colorShift, 255, proximity);
        g = lerp(55 + colorShift * 0.5, 235, proximity);
        b = lerp(90, 190, proximity);
      } else {
        // 冷色流：深海蓝/青色 -> 璀璨金白
        r = lerp(25, 255, proximity);
        g = lerp(155 + colorShift * 0.5, 240, proximity);
        b = lerp(235 + colorShift, 210, proximity);
      }

      stroke(r, g, b, currentAlpha);
      line(x, y, nx, ny);

      x = nx;
      y = ny;

      // 抵达核心极近处时化作光芒消散
      if (d < 22 && random() < 0.15) break;
    }
  }
}

function drawResonance(cx, cy) {
  // 绘制中心纠缠的金色丝线（双星共舞的轨道）
  noFill();
  for (let i = 0; i < 350; i++) {
    let rStart = random(20, 480);
    let a = random(TWO_PI);
    let len = random(40, 160);

    let isGold = random() < 0.6;
    if (isGold) {
      stroke(255, 225, 160, random(8, 28));
    } else if (random() < 0.5) {
      stroke(255, 140, 170, random(8, 22));
    } else {
      stroke(140, 220, 255, random(8, 22));
    }
    strokeWeight(random(0.4, 1.6));

    beginShape();
    for (let s = 0; s < len; s++) {
      let n = noise(cos(a) * 1.5, sin(a) * 1.5, rStart * 0.008);
      let r = rStart + sin(s * 0.08) * 35 * n;
      // 椭圆形倾斜旋转，增加动态立体感
      let px = cx + cos(a) * r;
      let py = cy + sin(a) * r * 0.85;
      // 围绕中心旋转一圈的角度修正
      let rotAngle = -PI * 0.15;
      let rx = cx + (px - cx) * cos(rotAngle) - (py - cy) * sin(rotAngle);
      let ry = cy + (px - cx) * sin(rotAngle) + (py - cy) * cos(rotAngle);

      vertex(rx, ry);
      a += 0.025;
      rStart *= 0.997;
    }
    endShape();
  }

  // 迸发的爱之微粒（星尘）
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let ang = random(TWO_PI);
    let dist = pow(random(), 2.2) * 750;
    let x = cx + cos(ang) * dist;
    let y = cy + sin(ang) * dist;

    let sz = map(dist, 0, 750, 4.5, 0.8) * random(0.4, 1.6);
    let a = map(dist, 0, 750, 180, 10) * random(0.5, 1);

    let cChoice = random();
    if (cChoice < 0.45) {
      fill(255, 235, 180, a); // 金色
    } else if (cChoice < 0.75) {
      fill(255, 150, 170, a); // 绯红
    } else {
      fill(150, 225, 255, a); // 冰蓝
    }
    circle(x, y, sz);
  }
}

function drawCores(cx, cy) {
  // 两个灵魂的发光核心，彼此独立又紧密相依
  let c1x = cx - 42;
  let c1y = cy + 32;
  let c2x = cx + 42;
  let c2y = cy - 32;

  noStroke();
  // 暖色灵魂核
  for (let r = 260; r > 0; r -= 3) {
    let inter = map(r, 0, 260, 1, 0);
    fill(255, 170, 130, pow(inter, 2.8) * 14);
    circle(c1x, c1y, r);
  }
  fill(255, 250, 240, 220);
  circle(c1x, c1y, 14);

  // 冷色灵魂核
  for (let r = 260; r > 0; r -= 3) {
    let inter = map(r, 0, 260, 1, 0);
    fill(130, 210, 255, pow(inter, 2.8) * 14);
    circle(c2x, c2y, r);
  }
  fill(240, 250, 255, 220);
  circle(c2x, c2y, 14);

  // 两核之间共振产生的纯白桥梁光辉
  for (let r = 220; r > 0; r -= 4) {
    let inter = map(r, 0, 220, 1, 0);
    fill(255, 245, 225, pow(inter, 2.2) * 16);
    circle(cx, cy, r);
  }
}

function drawVignette() {
  noFill();
  // 四周暗角，让视线聚焦于中心的相遇
  for (let i = 0; i < 180; i++) {
    let alpha = map(i, 0, 180, 120, 0);
    stroke(4, 6, 14, alpha);
    strokeWeight(3);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 深邃夜空背景与径向引力场
  background(6, 7, 18);

  let cx = width * 0.5;
  let cy = height * 0.46; // 黄金分割偏上作为爱与交汇的中心

  noStroke();
  for (let r = 2000; r > 0; r -= 8) {
    let inter = map(r, 0, 2000, 1, 0);
    let c = lerpColor(color(6, 7, 18, 0), color(40, 15, 45, 5), pow(inter, 1.5));
    fill(c);
    circle(cx, cy, r * 2);
  }

  // 2. 远景星尘（孤独宇宙的底色）
  for (let i = 0; i < 3500; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, cx, cy);
    let alpha = map(d, 0, 1400, 200, 25);
    fill(255, 245, 235, random(alpha * 0.2, alpha));
    let s = random(0.5, 2.8);
    circle(x, y, s);
  }

  // 启用色彩叠加模式，让光芒相互交融
  blendMode(ADD);

  // 定义两个灵魂的色彩体系：暖金珊瑚色 与 幽兰青碧色
  let warmColors = [
    color(255, 50, 80, 14),
    color(255, 110, 50, 14),
    color(255, 190, 90, 14),
    color(255, 220, 170, 18)
  ];

  let coolColors = [
    color(30, 90, 255, 14),
    color(0, 190, 230, 14),
    color(110, 60, 240, 14),
    color(180, 230, 255, 18)
  ];

  // 3. 绘制双螺旋流体轨迹（靠近与环绕）
  let numStrands = 1300;

  // 灵魂 A：从左下角升起
  drawSoulStream(cx, cy, -width * 0.1, height * 1.05, warmColors, 0, numStrands);

  // 灵魂 B：从右上角降落
  drawSoulStream(cx, cy, width * 1.1, -height * 0.05, coolColors, PI, numStrands);

  // 4. 绘制中心交汇的共鸣（心形引力谐振线）
  drawResonance(cx, cy);

  // 5. 绘制迸发的爱之微光与星火
  drawEmbers(cx, cy, warmColors, coolColors);

  // 6. 中心灵魂奇点的极致辉光
  for (let r = 500; r > 0; r -= 4) {
    let t = map(r, 0, 500, 1, 0);
    let alpha = pow(t, 3.2) * 10;
    fill(255, 235, 220, alpha);
    noStroke();
    circle(cx, cy, r * 2);
  }

  // 7. 恢复默认混合模式，添加油画般的质感颗粒与暗角
  blendMode(BLEND);
  applyVignetteAndGrain();
}

function drawSoulStream(cx, cy, startX, startY, palette, phaseOffset, count) {
  noFill();

  for (let i = 0; i < count; i++) {
    let c = random(palette);
    stroke(c);
    strokeWeight(random(0.6, 2.6));

    // 在起点周围形成散落的星云根系
    let sx = startX + randomGaussian(0, 220);
    let sy = startY + randomGaussian(0, 220);

    let steps = 320;
    let rotSpeed = random(2.2, 3.8) * PI;
    let streamNoiseOffset = random(1000);

    beginShape();
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let easeT = 1 - pow(1 - t, 2.4); // 越靠近中心越紧密

      // 基础线性靠拢
      let baseX = lerp(sx, cx, easeT);
      let baseY = lerp(sy, cy, easeT);

      // 螺旋环绕运动
      let distToCenter = dist(baseX, baseY, cx, cy);
      let angle = t * rotSpeed + phaseOffset + (i * 0.002);
      let spiralRadius = distToCenter * 0.55 * sin(t * PI);

      let spiralX = baseX + cos(angle) * spiralRadius;
      let spiralY = baseY + sin(angle) * spiralRadius;

      // 柏林噪声扰动，赋予生命般的气韵与流淌感
      let nScale = 0.0022;
      let nAngle = noise(spiralX * nScale, spiralY * nScale, streamNoiseOffset * 0.01 + t * 1.5) * TWO_PI * 4;
      let nForce = (1 - pow(t, 0.8)) * 180 + 18; 

      let finalX = spiralX + cos(nAngle) * nForce;
      let finalY = spiralY + sin(nAngle) * nForce;

      // 在终点处形成微小的双星互绕环
      if (t > 0.82) {
        let endT = map(t, 0.82, 1, 0, 1);
        let coreOrbit = 55 * (1 - endT * 0.4);
        let coreAngle = endT * TWO_PI * 1.5 + phaseOffset + (i * 0.05);
        finalX = lerp(finalX, cx + cos(coreAngle) * coreOrbit, endT * 0.6);
        finalY = lerp(finalY, cy + sin(coreAngle) * coreOrbit, endT * 0.6);
      }

      vertex(finalX, finalY);
    }
    endShape();
  }
}

function drawResonance(cx, cy) {
  // 在交汇中心绘制隐秘而神圣的共鸣波纹（抽象的心与无限符号的结合）
  noFill();
  for (let i = 0; i < 240; i++) {
    let t = i / 240;
    let scaleVal = map(pow(t, 1.4), 0, 1, 8, 420);

    let c1 = color(255, 160, 200, 12 * (1 - t));
    let c2 = color(160, 220, 255, 12 * (1 - t));
    stroke(lerpColor(c1, c2, sin(t * PI * 6) * 0.5 + 0.5));
    strokeWeight(random(0.5, 1.8));

    let rot = (1 - t) * PI * 0.6 + random(-0.04, 0.04);

    push();
    translate(cx, cy + 30 * t);
    rotate(rot);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.04) {
      let n = noise(cos(a) * 1.5 + i * 0.08, sin(a) * 1.5 + i * 0.08);
      let rMod = 1 + (n - 0.5) * 0.45;

      // 参数化心形谐振方程，融入柔和的流线变形
      let x = 16 * pow(sin(a), 3);
      let y = -(13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a));

      vertex(x * (scaleVal / 16) * rMod, y * (scaleVal / 16) * rMod);
    }
    endShape(CLOSE);
    pop();
  }
}

function drawEmbers(cx, cy, warmPalette, coolPalette) {
  noStroke();
  for (let i = 0; i < 4500; i++) {
    let angle = random(TWO_PI);
    // 运用幂函数让粒子集中在中心，又向四周优雅地消散
    let r = pow(random(1), 2.2) * 1100;
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 1.15; // 纵向略微拉伸以契合画布比例

    let n = noise(x * 0.004, y * 0.004);
    if (n > 0.35) {
      let isWarm = (sin(angle * 2 + r * 0.006) + random(-0.4, 0.4)) > 0;
      let baseCol = isWarm ? random(warmPalette) : random(coolPalette);

      let alpha = map(r, 0, 1100, 220, 10) * pow(n, 1.5);
      fill(red(baseCol), green(baseCol), blue(baseCol), alpha);

      let s = map(r, 0, 1100, 4.5, 0.8) * random(0.4, 1.8);
      circle(x, y, s);

      // 极少数明亮的灵魂火花
      if (random(1) < 0.04 && r < 550) {
        fill(255, 250, 245, alpha * 1.2);
        circle(x, y, s * 0.5);

        // 十字星芒微光
        stroke(255, 250, 245, alpha * 0.4);
        strokeWeight(0.7);
        let flareLen = s * random(2.5, 5);
        line(x - flareLen, y, x + flareLen, y);
        line(x, y - flareLen, x, y + flareLen);
        noStroke();
      }
    }
  }
}

function applyVignetteAndGrain() {
  let cx = width * 0.5;
  let cy = height * 0.46;

  // 边缘暗角，聚焦视线
  noFill();
  for (let r = 900; r < 1500; r += 4) {
    let alpha = map(r, 900, 1500, 0, 12);
    stroke(4, 5, 14, alpha);
    strokeWeight(6);
    circle(cx, cy, r * 2);
  }

  // 细腻的画布纹理颗粒（点彩层）
  noStroke();
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    if (random(1) < 0.5) {
      fill(255, 250, 240, random(2, 6));
    } else {
      fill(5, 6, 15, random(4, 10));
    }
    rect(x, y, 1.5, 1.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 绘制深邃的宇宙背景与柔和星云
  background(7, 8, 18);
  drawNebula();

  // 2. 绘制背景星尘
  drawStars(2500);

  // 3. 定义两个灵魂的核心位置（双星系统）
  let centerA = createVector(660, 1020);
  let centerB = createVector(940, 980);
  let midCenter = p5.Vector.lerp(centerA, centerB, 0.5);

  // 4. 绘制两个核心的光晕
  drawCoreGlow(centerA.x, centerA.y, color(255, 80, 40), 750);
  drawCoreGlow(centerB.x, centerB.y, color(20, 180, 255), 750);
  drawCoreGlow(midCenter.x, midCenter.y, color(255, 190, 230), 1100);

  // 5. 绘制交织的生命轨迹（流线系统）
  blendMode(ADD);

  // 灵魂A的轨迹：温暖、炽热（红金、珊瑚粉、琥珀色）
  let paletteA = [
    color(255, 50, 30, 14),
    color(255, 120, 40, 14),
    color(255, 190, 80, 16),
    color(255, 100, 140, 12)
  ];

  // 灵魂B的轨迹：沉静、深邃（青色、蔚蓝、紫罗兰）
  let paletteB = [
    color(20, 130, 255, 14),
    color(40, 220, 240, 14),
    color(110, 80, 255, 12),
    color(180, 240, 255, 16)
  ];

  // 交融的轨迹：爱之共鸣（香槟金、柔粉、纯白）
  let paletteMix = [
    color(255, 220, 180, 20),
    color(255, 160, 210, 18),
    color(255, 255, 255, 24)
  ];

  // 生成流线
  drawFlowSystem(centerA, centerB, paletteA, 'A', 2200);
  drawFlowSystem(centerA, centerB, paletteB, 'B', 2200);
  drawFlowSystem(centerA, centerB, paletteMix, 'MIX', 1400);

  // 6. 绘制连接彼此的光丝（心弦）
  drawConnectingThreads(centerA, centerB, 350);

  // 7. 绘制核心高光与迸发的微尘
  drawEmbers(midCenter, 900);
  drawCoreHighlight(centerA.x, centerA.y, color(255, 200, 150));
  drawCoreHighlight(centerB.x, centerB.y, color(180, 240, 255));
  drawCoreHighlight(midCenter.x, midCenter.y, color(255, 245, 250), 1.5);

  // 8. 画面边缘暗角与质感叠加
  blendMode(BLEND);
  drawVignette();
}

// 获取自定义物理/情感流场中的受力方向
function getFieldVelocity(x, y, cA, cB, type) {
  let p = createVector(x, y);
  let dA = p5.Vector.sub(cA, p);
  let dB = p5.Vector.sub(cB, p);
  let distA = constrain(dA.mag(), 40, 2000);
  let distB = constrain(dB.mag(), 40, 2000);

  dA.normalize();
  dB.normalize();

  // 旋转切线向量
  let tangentA = createVector(-dA.y, dA.x);
  let tangentB = createVector(dB.y, -dB.x); // 反向旋转以在中心形成交汇流

  // 柏林噪声带来的自然流动感
  let n = noise(x * 0.0018, y * 0.0018) * TWO_PI * 2.5;
  let noiseVec = p5.Vector.fromAngle(n);

  let v = createVector(0, 0);

  // 根据离两个核心的距离计算引力与旋转权重
  let pullA = 180 / pow(distA, 0.75);
  let pullB = 180 / pow(distB, 0.75);

  if (type === 'A') {
    v.add(p5.Vector.mult(tangentA, 1.8 * pullA));
    v.add(p5.Vector.mult(tangentB, 1.2 * pullB));
    v.add(p5.Vector.mult(dB, 0.9 * pullB)); // 被B吸引
    v.add(p5.Vector.mult(dA, 0.3 * pullA));
  } else if (type === 'B') {
    v.add(p5.Vector.mult(tangentB, 1.8 * pullB));
    v.add(p5.Vector.mult(tangentA, 1.2 * pullA));
    v.add(p5.Vector.mult(dA, 0.9 * pullA)); // 被A吸引
    v.add(p5.Vector.mult(dB, 0.3 * pullB));
  } else {
    // 混合流：围绕双星外部形成S形与心形环绕包络
    let mid = p5.Vector.lerp(cA, cB, 0.5);
    let dM = p5.Vector.sub(mid, p);
    let distM = constrain(dM.mag(), 50, 2000);
    dM.normalize();
    let tangentM = createVector(-dM.y, dM.x);

    v.add(p5.Vector.mult(tangentA, 1.4 * pullA));
    v.add(p5.Vector.mult(tangentB, 1.4 * pullB));
    v.add(p5.Vector.mult(tangentM, 1.2));
    v.add(p5.Vector.mult(dM, 60 / pow(distM, 0.6)));
  }

  // 加入噪声扰动，越往外围噪声影响越大
  let centerDist = dist(x, y, width / 2, height / 2);
  let noiseWeight = map(centerDist, 0, 1000, 0.4, 2.2);
  v.add(p5.Vector.mult(noiseVec, noiseWeight));

  // 整体向上的轻微升腾感
  v.y -= 0.25;

  v.normalize();
  return v;
}

function drawFlowSystem(cA, cB, palette, type, count) {
  noFill();
  for (let i = 0; i < count; i++) {
    let x, y;
    // 根据类型决定粒子的诞生区域
    if (type === 'A') {
      let ang = random(TWO_PI);
      let r = abs(randomGaussian(0, 380));
      x = cA.x + cos(ang) * r - random(0, 150);
      y = cA.y + sin(ang) * r + random(-200, 300);
    } else if (type === 'B') {
      let ang = random(TWO_PI);
      let r = abs(randomGaussian(0, 380));
      x = cB.x + cos(ang) * r + random(0, 150);
      y = cB.y + sin(ang) * r + random(-300, 200);
    } else {
      let ang = random(TWO_PI);
      let r = abs(randomGaussian(0, 260));
      let mid = p5.Vector.lerp(cA, cB, random(0.2, 0.8));
      x = mid.x + cos(ang) * r;
      y = mid.y + sin(ang) * r;
    }

    let col = random(palette);
    stroke(col);
    strokeWeight(random(0.6, 2.4));

    let steps = int(random(120, 380));
    let stepSize = random(2.5, 4.5);

    beginShape();
    for (let s = 0; s < steps; s++) {
      vertex(x, y);
      let v = getFieldVelocity(x, y, cA, cB, type);
      x += v.x * stepSize;
      y += v.y * stepSize;

      // 边界提前终止
      if (x < -100 || x > width + 100 || y < -100 || y > height + 100) break;
    }
    endShape();
  }
}

// 绘制两个灵魂之间直接纠缠的金色与彩色丝线
function drawConnectingThreads(cA, cB, count) {
  noFill();
  for (let i = 0; i < count; i++) {
    let t = random(1);
    let spread = randomGaussian(0, 180);

    let startAngle = random(TWO_PI);
    let startR = random(10, 160);
    let sx = cA.x + cos(startAngle) * startR;
    let sy = cA.y + sin(startAngle) * startR;

    let endAngle = random(TWO_PI);
    let endR = random(10, 160);
    let ex = cB.x + cos(endAngle) * endR;
    let ey = cB.y + sin(endAngle) * endR;

    // 控制点偏移，形成优雅的弧线
    let mid = p5.Vector.lerp(cA, cB, 0.5);
    let angleToB = atan2(cB.y - cA.y, cB.x - cA.x);
    let perpAngle = angleToB + HALF_PI;

    let cx1 = lerp(sx, ex, 0.33) + cos(perpAngle) * spread + (noise(i * 0.1) - 0.5) * 200;
    let cy1 = lerp(sy, ey, 0.33) + sin(perpAngle) * spread + (noise(i * 0.1 + 10) - 0.5) * 200;
    let cx2 = lerp(sx, ex, 0.66) - cos(perpAngle) * spread * 0.8 + (noise(i * 0.1 + 20) - 0.5) * 200;
    let cy2 = lerp(sy, ey, 0.66) - sin(perpAngle) * spread * 0.8 + (noise(i * 0.1 + 30) - 0.5) * 200;

    let c1 = color(255, 140, 80, 22);
    let c2 = color(80, 220, 255, 22);
    let strokeCol = lerpColor(c1, c2, t);

    stroke(strokeCol);
    strokeWeight(random(0.5, 1.8));
    bezier(sx, sy, cx1, cy1, cx2, cy2, ex, ey);
  }
}

