function drawEmbers(center, count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let ang = random(TWO_PI);
    // 越靠近中心越密集
    let r = pow(random(1), 1.8) * 750;
    let x = center.x + cos(ang) * r;
    let y = center.y + sin(ang) * r;

    // 根据流场方向轻微拉伸成星芒或光点
    let size = map(r, 0, 750, random(2, 6), random(0.8, 2.5));
    let alpha = map(r, 0, 750, random(120, 230), random(10, 60));

    if (random() < 0.4) {
      fill(255, 230, 170, alpha);
    } else if (random() < 0.7) {
      fill(255, 160, 200, alpha);
    } else {
      fill(160, 240, 255, alpha);
    }

    circle(x, y, size);
    // 给大颗粒加一点光晕
    if (size > 3.8) {
      fill(255, 255, 255, alpha * 0.3);
      circle(x, y, size * 2.8);
    }
  }
}

