function radialStops(x, y, r, stops) {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (let i = 0; i < stops.length; i++) g.addColorStop(stops[i][0], stops[i][1]);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
}

function paintedRibbon(pts, ws, core, fringe) {
  ribbon(pts, ws, fringe, 26, 1.16, 220);
  ribbon(pts, ws, core, 80, 1.0, 300);
}

function ribbon(pts, ws, col, a, scl, steps) {
  noStroke();
  fill(col[0], col[1], col[2], a);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = polyAt(pts, t);
    let w = spanAt(ws, t) * scl;
    let j = (noise(t * 1.3, col[0] * 0.02) - 0.5) * 5;
    ellipse(p.x + j, p.y, w, w * 0.9);
  }
}

function polyAt(pts, t) {
  let n = pts.length - 1;
  let x = constrain(t, 0, 1) * n;
  let i = min(floor(x), n - 1);
  let u = x - i;
  u = u * u * (3 - 2 * u);
  return {
    x: lerp(pts[i][0], pts[i + 1][0], u),
    y: lerp(pts[i][1], pts[i + 1][1], u)
  };
}

function spanAt(ws, t) {
  let n = ws.length - 1;
  let x = constrain(t, 0, 1) * n;
  let i = min(floor(x), n - 1);
  let u = x - i;
  u = u * u * (3 - 2 * u);
  return lerp(ws[i], ws[i + 1], u);
}

function offsetEdge(pts, ws, side) {
  let edge = [];
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = polyAt(pts, t);
    let q = polyAt(pts, min(t + 0.02, 1));
    let dx = q.x - p.x;
    let dy = q.y - p.y;
    let len = mag(dx, dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    let w = spanAt(ws, t) * 0.48;
    edge.push([p.x + nx * w * side, p.y + ny * w * side]);
  }
  return edge;
}

function rimAlong(pts, ws, side, col, alpha) {
  glowStroke(offsetEdge(pts, ws, side), col, alpha);
}

function glowStroke(pts, col, a) {
  noFill();
  stroke(col[0], col[1], col[2], a * 0.28);
  strokeWeight(15);
  drawCurve(pts);
  stroke(col[0], col[1], col[2], a * 0.75);
  strokeWeight(3.2);
  drawCurve(pts);
}

function drawCurve(pts) {
  beginShape();
  curveVertex(pts[0][0], pts[0][1]);
  for (let i = 0; i < pts.length; i++) curveVertex(pts[i][0], pts[i][1]);
  curveVertex(pts[pts.length - 1][0], pts[pts.length - 1][1]);
  endShape();
}

function petal(x, y, s, rot, c) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(c[0], c[1], c[2], c[3]);
  ellipse(0, -s * 0.12, s * 0.4, s);
  fill(c[0], c[1], c[2], c[3] * 0.7);
  ellipse(s * 0.16, s * 0.04, s * 0.28, s * 0.66);
  pop();
}

function blossom(x, y, s, col) {
  push();
  translate(x, y);
  noStroke();
  fill(col[0], col[1], col[2], col[3]);
  for (let k = 0; k < 5; k++) {
    rotate(TWO_PI / 5);
    ellipse(0, s * 0.34, s * 0.4, s * 0.6);
  }
  fill(255, 220, 180, col[3]);
  ellipse(0, 0, s * 0.26, s * 0.26);
  pop();
}

function ember(x, y, s) {
  noStroke();
  fill(255, 186, 140, 7);
  ellipse(x, y, s * 6.5, s * 6.5);
  fill(255, 220, 190, 16);
  ellipse(x, y, s * 2.2, s * 2.2);
  fill(255, 246, 232, 36);
  ellipse(x, y, s, s);
}

