function skyAt(t) {
  if (t < 0.30) return lerpColor(color(7, 6, 14), color(24, 18, 44), t / 0.30);
  if (t < 0.50) return lerpColor(color(24, 18, 44), color(102, 52, 82), (t - 0.30) / 0.20);
  if (t < 0.60) return lerpColor(color(102, 52, 82), color(206, 112, 82), (t - 0.50) / 0.10);
  if (t < 0.68) return lerpColor(color(206, 112, 82), color(236, 188, 132), (t - 0.60) / 0.08);
  if (t < 0.78) return lerpColor(color(236, 188, 132), color(58, 32, 30), (t - 0.68) / 0.10);
  return lerpColor(color(58, 32, 30), color(8, 6, 8), (t - 0.78) / 0.22);
}

function drawSky() {
  strokeWeight(2);
  for (let y = 0; y < height; y++) {
    let c = skyAt(y / height);
    let n = noise(y * 0.01, 0.4);
    stroke(
      red(c) + (n - 0.5) * 12,
      green(c) + (n - 0.5) * 6,
      blue(c) + (n - 0.5) * 8
    );
    line(0, y, width, y);
  }
}

function softDisc(x, y, rx, ry, col, layers, maxA, minA) {
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let a = lerp(minA, maxA, 1 - t);
    fill(red(col), green(col), blue(col), a);
    ellipse(x, y, rx * 2 * t, ry * 2 * t);
