function ridge(yBase, amp, col, seed) {
  noStroke();
  fill(col);
  beginShape();
  vertex(0, 1760);
  for (let x = 0; x <= width; x += 8) {
    let n = noise(x * 0.0015 + seed, seed);
    let n2 = noise(x * 0.0065 + seed, seed + 2);
    let dip = exp(-pow((x - 815) / 280, 2)) * amp * 0.62;
    let y = yBase - n * amp - n2 * amp * 0.24 + dip;
    vertex(x, y);
  }
  vertex(width, 1760);
  endShape(CLOSE);
}

