function drawPerson(cfg) {
  let base = cfg.base;

  noStroke();
  fill(0, 36);
  beginShape();
  for (let i = 0; i < cfg.coat.length; i++) {
    vertex(cfg.coat[i][0] + 16, cfg.coat[i][1] + 20);
  }
  endShape(CLOSE);

  fill(base[0], base[1], base[2], 255);
  beginShape();
  for (let i = 0; i < cfg.coat.length; i++) {
    vertex(cfg.coat[i][0], cfg.coat[i][1]);
  }
  endShape(CLOSE);

  feather(cfg.coat, base);
  paintColumn(cfg.spine, cfg.widths, color(base[0] + 12, base[1] + 18, base[2] + 14), 32);
  paintColumn(cfg.fold, cfg.foldW, color(base[0] * 0.4, base[1] * 0.35, base[2] * 0.35), 14);

  noStroke();
  fill(base[0] + 8, base[1] + 10, base[2] + 8, 255);
  ellipse(cfg.neck[0], cfg.neck[1], 38, 56);

  paintColumn(cfg.arm, cfg.armW, color(base[0] + 16, base[1] + 20, base[2] + 16), 22);

  noStroke();
  fill(196, 140, 116, 220);
  ellipse(cfg.hand[0], cfg.hand[1], 18, 14);
  fill(255, 214, 182, 150);
  ellipse(cfg.hand[0] + cfg.dir * 2, cfg.hand[1] - 2, 8, 6);

  fill(base[0] * 0.3, base[1] * 0.3, base[2] * 0.35, 250);
  ellipse(cfg.head[0] - cfg.dir * 10, cfg.head[1] + 6, cfg.hw * 0.95, cfg.hh * 0.92);

  stroke(base[0] * 0.28 + 8, base[1] * 0.22 + 6, base[2] * 0.22 + 6, 120);
  strokeWeight(1.5);
  noFill();
  for (let i = 0; i < cfg.tassels; i++) {
    bezier(
      cfg.head[0] - cfg.dir * 4,
      cfg.head[1] + 20,
      cfg.head[0] - cfg.dir * (50 + i * 8),
      cfg.head[1] + 120,
      cfg.head[0] - cfg.dir * (80 + i * 6),
      cfg.head[1] + 240,
      cfg.head[0] - cfg.dir * (100 + i * 10),
      cfg.head[1] + 360 + i * 18
    );
  }

  push();
  translate(cfg.head[0], cfg.head[1]);
  rotate(cfg.rot);
  noStroke();
  fill(base[0] + 6, base[1] + 8, base[2] + 6, 255);
  ellipse(0, 0, cfg.hw, cfg.hh);
  fill(base[0] + 22, base[1] + 28, base[2] + 18, 255);
  ellipse(cfg.dir * cfg.hw * 0.14, 6, cfg.hw * 0.6, cfg.hh * 0.7);
  fill(cfg.cheek[0], cfg.cheek[1], cfg.cheek[2], 78);
  ellipse(cfg.dir * cfg.hw * 0.2, 8, 30, 40);
  fill(base[0] * 0.45, base[1] * 0.45, base[2] * 0.45, 230);
  ellipse(cfg.dir * cfg.hw * 0.4, 1, 15, 24);
  fill(0, 28);
  ellipse(cfg.dir * cfg.hw * 0.16, -8, 22, 8);
  pop();

  warmEdge(cfg.inner);
  coolEdge(cfg.outer);
}

function feather(pts, base) {
  noStroke();
  for (let i = 0; i < pts.length; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    for (let s = 0; s <= 8; s++) {
      let t = s / 8;
      let x = lerp(a[0], b[0], t) + random(-5, 5);
      let y = lerp(a[1], b[1], t) + random(-5, 5);
      fill(base[0] + random(-8, 12), base[1] + random(-8, 12), base[2] + random(-8, 8), 50);
      ellipse(x, y, random(12, 30), random(10, 24));
    }
  }
}

function paintColumn(spine, widths, baseCol, vary) {
  noStroke();
  for (let i = 0; i < spine.length - 1; i++) {
    for (let s = 0; s <= 8; s++) {
      let t = s / 8;
      let x = lerp(spine[i][0], spine[i + 1][0], t);
      let y = lerp(spine[i][1], spine[i + 1][1], t);
      let w = lerp(widths[i], widths[i + 1], t);
      let n = noise(x * 0.008, y * 0.008, i);
      for (let k = 0; k < 3; k++) {
        let j = n + k * 0.17;
        fill(
          red(baseCol) + (j - 0.5) * vary,
          green(baseCol) + (noise(j, y * 0.01) - 0.5) * vary,
          blue(baseCol) + (noise(x * 0.01, j) - 0.5) * vary * 0.7,
          36
        );
        ellipse(
          x + random(-w * 0.12, w * 0.12),
          y + random(-5, 5),
          w * random(0.9, 1.2),
          random(40, 78)
        );
      }
    }
  }
}

