function rgba(r, g, b, a) {
  return "rgba(" + r + "," + g + "," + b + "," + a + ")";
}

function clamp255(v) {
  return v < 0 ? 0 : v > 255 ? 255 : v;
}

function quadPoint(x1, y1, cx, cy, x2, y2, t) {
  const u = 1 - t;
  return {
    x: u * u * x1 + 2 * u * t * cx + t * t * x2,
    y: u * u * y1 + 2 * u * t * cy + t * t * y2
  };
}

function smoothBlob(x, y, rx, ry, rot, hx, hy, stops) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.scale(rx, ry);
  const g = ctx.createRadialGradient(hx, hy, 0.04, 0, 0, 1);
  for (let i = 0; i < stops.length; i++) {
    g.addColorStop(stops[i][0], stops[i][1]);
  }
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, 1, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function disc(x, y, rad, fillStyle, strokeStyle, sw) {
  const ctx = drawingContext;
  ctx.beginPath();
  ctx.arc(x, y, rad, 0, Math.PI * 2);
  if (fillStyle) {
    ctx.fillStyle = fillStyle;
    ctx.fill();
  }
  if (strokeStyle) {
    ctx.lineWidth = sw;
    ctx.strokeStyle = strokeStyle;
    ctx.stroke();
  }
}

function organicCurve(x1, y1, cx, cy, x2, y2, w, r, g, b, a, seed) {
  const ctx = drawingContext;
  const pts = [];
  for (let i = 0; i <= 28; i++) {
    const t = i / 28;
    const p = quadPoint(x1, y1, cx, cy, x2, y2, t);
    const ox = (noise(seed, t * 1.7) - 0.5) * 16;
    const oy = (noise(seed + 4, t * 1.7) - 0.5) * 12;
    pts.push([p.x + ox, p.y + oy]);
  }
  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  for (let k = 7; k >= 1; k--) {
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
    const t = k / 7;
    ctx.strokeStyle = rgba(r, g, b, a * (0.1 + 0.55 * (1 - t)));
    ctx.lineWidth = w * t;
    ctx.stroke();
  }
  ctx.restore();
}

function paint() {
  const ctx = drawingContext;
  ctx.globalCompositeOperation = "source-over";
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  background(9, 7, 15);
  sky();
  atmosphere();
  stars();
  haloRings();
  cloak();
  sharedRobe();
  hairBack();
  bodies();
  fabric();
  embrace();
  lightColumn();
  handsAndInnerLight();
  heads();
  frontStrands();
  dustRing();
  gapLight();
  silk();
