    [0, rgba(96, 38, 42, 0.36)],
    [0.55, rgba(48, 20, 32, 0.12)],
    [1, rgba(48, 20, 32, 0)]
  ]);
  smoothBlob(801, 764, 440, 360, 0, 0, 0, [
    [0, rgba(190, 108, 80, 0.3)],
    [0.5, rgba(120, 48, 52, 0.1)],
    [1, rgba(120, 48, 52, 0)]
  ]);
  const ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  smoothBlob(801, 764, 320, 250, 0, 0, 0, [
    [0, rgba(255, 186, 140, 0.38)],
    [1, rgba(255, 186, 140, 0)]
  ]);
  ctx.restore();
  for (let i = 0; i < 26; i++) {
