function haloRings() {
  const ctx = drawingContext;
  const radii = [206, 304, 424, 560];
  const alphas = [0.3, 0.18, 0.11, 0.06];
  for (let r = 0; r < radii.length; r++) {
    ctx.beginPath();
    const steps = 96;
    for (let i = 0; i <= steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      const n = noise(Math.cos(a) * 0.8 + r, Math.sin(a) * 0.8, 3);
      const rr = radii[r] + (n - 0.5) * (14 + r * 7);
      const x = 801 + Math.cos(a) * rr;
      const y = 764 + Math.sin(a) * rr * 0.9;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.strokeStyle = rgba(224, 176, 132, alphas[r]);
    ctx.lineWidth = r === 0 ? 2.1 : 1.25;
    ctx.stroke();
  }
}

function cloak() {
  for (let i = 0; i < 540; i++) {
    let x;
    let y;
    if (random() < 0.7) {
      const a = random(Math.PI * 2);
      const j = random(0.8, 1.1);
      x = 820 + Math.cos(a) * 430 * j;
      y = 1320 + Math.sin(a) * 500 * j;
    } else {
      x = random(400, 1240);
      y = random(980, 1780);
    }
    const nx = (x - 820) / 500;
    const ny = (y - 1320) / 560;
    if (nx * nx + ny * ny > 1) continue;
    if (dist(x, y, 730, 742) < 188) continue;
    if (dist(x, y, 872, 786) < 180) continue;
    if (y < 900) continue;
    const rad = random() < 0.13 ? random(18, 31) : random(5, 14);
    const roll = random();
    let fill;
    if (roll < 0.12) fill = rgba(34, 20, 38, 0.82);
    else if (roll < 0.3) fill = rgba(168, 78, 88, 0.76);
    else if (roll < 0.5) fill = rgba(226, 198, 156, 0.82);
    else fill = rgba(176, 122, 56, 0.8);
    disc(x, y, rad, fill, rgba(42, 24, 16, 0.52), 1.1);
    if (rad > 9) {
      disc(x - rad * 0.28, y - rad * 0.3, Math.max(1.2, rad * 0.16), rgba(255, 236, 210, 0.52), null, 0);
    }
    if (rad > 16 && random() < 0.45) {
      disc(x, y, rad * 0.52, null, rgba(255, 224, 176, 0.32), 0.8);
    }
  }
}

