function flower(x, y, s, pr, pg, pb, cr, cg, cb) {
  const ctx = drawingContext;
  const petals = 7;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(random(Math.PI * 2));
  for (let i = 0; i < petals; i++) {
    ctx.rotate((Math.PI * 2) / petals);
    ctx.beginPath();
    ctx.ellipse(s * 0.34, 0, s * 0.32, s * 0.145, 0, 0, Math.PI * 2);
    ctx.fillStyle = rgba(pr, pg, pb, 0.82);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(s * 0.2, 0, s * 0.15, s * 0.075, 0, 0, Math.PI * 2);
    ctx.fillStyle = rgba(Math.min(255, pr + 28), Math.min(255, pg + 22), Math.min(255, pb + 14), 0.5);
    ctx.fill();
  }
  ctx.restore();
  disc(x, y, s * 0.12, rgba(cr, cg, cb, 0.96), null, 0);
  disc(x - s * 0.03, y - s * 0.032, s * 0.042, rgba(255, 248, 236, 0.9), null, 0);
}

