function robeW(t) {
  if (t < 0.12) return lerp(30, 72, t / 0.12);
  if (t < 0.32) return lerp(72, 104, (t - 0.12) / 0.2);
  if (t < 0.5) return lerp(104, 88, (t - 0.32) / 0.18);
  if (t < 0.72) return lerp(88, 168, (t - 0.5) / 0.22);
  return lerp(168, 286, (t - 0.72) / 0.28);
}

function drawSky() {
  for (let y = 0; y < 2000; y += 3) {
    let t = y / 2000;
    let c;
    if (t < 0.36) {
      c = lerpColor(color(7, 6, 20), color(34, 22, 62), t / 0.36);
    } else if (t < 0.58) {
      c = lerpColor(color(34, 22, 62), color(96, 44, 66), (t - 0.36) / 0.22);
    } else if (t < 0.78) {
      c = lerpColor(color(96, 44, 66), color(52, 28, 40), (t - 0.58) / 0.2);
    } else {
      c = lerpColor(color(52, 28, 40), color(18, 10, 16), (t - 0.78) / 0.22);
    }
    let n = noise(y * 0.004, 1.3);
    stroke(
      constrain(red(c) + (n - 0.5) * 12, 0, 255),
      constrain(green(c) + (n - 0.5) * 8, 0, 255),
      constrain(blue(c) + (n - 0.5) * 14, 0, 255),
      255
    );
    strokeWeight(4);
    line(0, y, 1600, y);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 80; i++) {
    let x = random(30, 1570);
