function sampleSpline(anchors, n) {
  let ext = [];
  ext.push(anchors[0]);
  for (let i = 0; i < anchors.length; i++) ext.push(anchors[i]);
  ext.push(anchors[anchors.length - 1]);
  let pts = [];
  let segs = anchors.length - 1;
  for (let i = 0; i < n; i++) {
    let f = n === 1 ? 0 : (i / (n - 1)) * segs;
    let seg = min(floor(f), segs - 1);
    let t = f - seg;
    let p0 = ext[seg];
    let p1 = ext[seg + 1];
    let p2 = ext[seg + 2];
    let p3 = ext[seg + 3];
    pts.push({
      x: curvePoint(p0[0], p1[0], p2[0], p3[0], t),
      y: curvePoint(p0[1], p1[1], p2[1], p3[1], t)
    });
  }
  return pts;
}

function offsetPts(pts, dx, dy) {
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    out.push({ x: pts[i].x + dx, y: pts[i].y + dy });
  }
  return out;
}

function fillRibbon(pts, widthAt, col, a) {
  let left = [];
  let right = [];
  for (let i = 0; i < pts.length; i++) {
    let t = i / (pts.length - 1);
    let w = widthAt(t);
    let i1 = min(i + 1, pts.length - 1);
    let i0 = max(i - 1, 0);
    let dx = pts[i1].x - pts[i0].x;
    let dy = pts[i1].y - pts[i0].y;
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    let j = noise(i * 0.12, 2.4) - 0.5;
    left.push({
      x: pts[i].x + nx * w * 0.5 + j * 7,
      y: pts[i].y + ny * w * 0.5
    });
    right.push({
      x: pts[i].x - nx * w * 0.5 - j * 7,
      y: pts[i].y - ny * w * 0.5
    });
  }
  noStroke();
  fill(red(col), green(col), blue(col), a);
  beginShape();
  for (let i = 0; i < left.length; i++) vertex(left[i].x, left[i].y);
  for (let i = right.length - 1; i >= 0; i--) vertex(right[i].x, right[i].y);
  endShape(CLOSE);
}

function brushAlong(pts, widthAt, c0, c1) {
  let layers = [
    { scale: 1, alpha: 14, strands: 6 },
    { scale: 0.5, alpha: 24, strands: 4 },
    { scale: 0.2, alpha: 34, strands: 2 }
  ];
  for (let L = 0; L < layers.length; L++) {
    let layer = layers[L];
    for (let i = 0; i < pts.length - 1; i++) {
      let t = i / (pts.length - 1);
      let w = widthAt(t) * layer.scale;
      let col = lerpColor(c0, c1, t);
      let dx = pts[i + 1].x - pts[i].x;
      let dy = pts[i + 1].y - pts[i].y;
      let len = sqrt(dx * dx + dy * dy) || 1;
      let nx = -dy / len;
      let ny = dx / len;
      for (let s = 0; s < layer.strands; s++) {
        let u = layer.strands === 1 ? 0 : s / (layer.strands - 1) - 0.5;
        let n = noise(i * 0.16, s * 0.41, L * 2.2);
        let off = u * w + (n - 0.5) * w * 0.22;
        let edge = max(0.18, 1 - abs(u) * 1.15);
        stroke(red(col), green(col), blue(col), layer.alpha * edge);
        strokeWeight(max(1.1, w * 0.17));
        line(
          pts[i].x + nx * off,
          pts[i].y + ny * off,
          pts[i + 1].x + nx * off,
          pts[i + 1].y + ny * off
        );
      }
    }
  }
}

function rimLight(pts, widthAt, col, side) {
  for (let i = 0; i < pts.length - 1; i++) {
    let t = i / (pts.length - 1);
    if (t > 0.9) continue;
    let w = widthAt(t);
    let dx = pts[i + 1].x - pts[i].x;
    let dy = pts[i + 1].y - pts[i].y;
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    let off = side * w * 0.46;
    let a = 18 + (1 - t) * 36;
    stroke(red(col), green(col), blue(col), a * 0.35);
    strokeWeight(8);
    line(pts[i].x + nx * off, pts[i].y + ny * off, pts[i + 1].x + nx * off, pts[i + 1].y + ny * off);
    stroke(red(col), green(col), blue(col), a);
    strokeWeight(2);
    line(pts[i].x + nx * off, pts[i].y + ny * off, pts[i + 1].x + nx * off, pts[i + 1].y + ny * off);
  }
}

