}

function paintSky() {
  noFill();
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let r = lerp(8, 14, t);
    let g = lerp(9, 10, t);
    let b = lerp(22, 16, t);
    let warm = exp(-pow((y - 1100) / 500, 2));
    r += 34 * warm;
    g += 12 * warm;
    b += 8 * warm;
    let dusk = exp(-pow((y - 1540) / 240, 2));
    r += 16 * dusk;
    g += 7 * dusk;
    let n = (noise(y * 0.008, 1.7) - 0.5) * 5;
    stroke(r + n, g + n * 0.35, b + n * 0.25);
    strokeWeight(2);
    line(0, y, width, y);
  }
}

function paintAtmosphere() {
  blendMode(ADD);
  wash(780, 900, 560, 480, 255, 146, 88, 78, 18);
  wash(610, 980, 240, 320, 255, 110, 96, 28, 10);
  wash(1040, 940, 260, 340, 255, 168, 78, 28, 10);
  noStroke();
  for (let i = 0; i <= 100; i++) {
    let t = i / 100;
    let x = lerp(390, 1230, t);
    let y = lerp(1060, 1036, t) - sin(t * PI) * 530;
    fill(255, 176, 128, 1.5 + 7 * sin(t * PI));
    ellipse(x, y + (noise(t * 2.2, 4) - 0.5) * 16, 100, 34);
  }
  blendMode(BLEND);
  noStroke();
  fill(58, 28, 34, 12);
  ellipse(800, 1180, 460, 280);
  fill(36, 22, 32, 10);
  ellipse(800, 980, 320, 240);
}

function paintGround() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 28; i++) {
    fill(18, 11, 13, 9);
    ellipse(800, 1610 + i * 2.4, 1760 - i * 12, 90);
  }
  for (let i = 0; i < 16; i++) {
    fill(130, 62, 40, 5);
    ellipse(800, 1596, 460 - i * 10, 40);
  }
  strokeCap(ROUND);
  for (let i = 0; i < 1600; i++) {
    let x = random(width);
    let y = random(1490, 1720);
    let lit = exp(-pow((x - 800) / 300, 2));
    stroke(
      lerp(26, 146, lit * 0.5) + random(-5, 5),
      lerp(24, 74, lit * 0.28) + random(-5, 5),
      lerp(20, 38, lit * 0.15),
      random(28, 78)
    );
    strokeWeight(random(0.7, 1.5));
    let h = random(8, 34) * (y < 1630 ? 1 : 0.35);
    line(x, y, x + random(-6, 6), y - h);
  }
}

function paintFigures() {
  blendMode(BLEND);
  figureMass(-1);
  figureMass(1);
  figureRobes(-1, false);
  figureRobes(1, false);
  figureHairNeckHead(-1);
  figureHairNeckHead(1);
  figureSleeve(-1);
  figureSleeve(1);
  blendMode(ADD);
  figureRobes(-1, true);
  figureRobes(1, true);
  figureSleeveLight(-1);
