function figureRobes(side, highlight) {
  for (let i = 0; i < 40; i++) {
    let s = i / 39;
    let yTop = side < 0 ? 988 : 962;
    let x1 = lerp(800 + side * 286, 800 + side * 136, s) + random(-4, 4);
    let y1 = yTop + s * 28 + random(-3, 3);
    let x2 = lerp(800 + side * 438, 800 + side * 150, s) + random(-7, 7);
    let y2 = lerp(1518, 1636, pow(s, 0.8)) + random(-12, 16);
    let cx = lerp(x1, x2, 0.46) - side * lerp(42, 6, s);
    let cy = lerp(y1, y2, 0.4) + random(-8, 8);
    let w = lerp(36, 15, s);
    if (!highlight) {
      let cr = side < 0 ? lerp(40, 124, s) : lerp(46, 138, s);
      let cg = side < 0 ? lerp(16, 38, s) : lerp(22, 66, s);
      let cb = side < 0 ? lerp(30, 46, s) : lerp(16, 28, s);
      ribbon(x1, y1, cx, cy, x2, y2, cr, cg, cb, 22, w, 32);
    } else {
      ribbon(
        x1, y1, cx, cy, x2, y2,
        255,
        side < 0 ? lerp(78, 146, s) : lerp(138, 196, s),
        side < 0 ? lerp(68, 104, s) : lerp(48, 82, s),
        lerp(1.6, 7.5, s),
        w * 0.5,
        24
      );
    }
  }
}

