      random(11, 20),
      random(6, 13),
      18
    );
  }

  let palette = [
    [232, 104, 112],
    [255, 214, 196],
    [240, 164, 86],
    [188, 54, 72],
    [255, 236, 220],
    [214, 86, 78],
    [255, 186, 150]
  ];
  for (let i = 0; i < 96; i++) {
    let a = -HALF_PI + (random() - 0.5) * random(0.15, 1.55);
    let rad = 14 + pow(random(), 0.62) * 132;
    let col = palette[floor(random(palette.length))];
    petal(
      800 + cos(a) * rad * 0.76,
      1092 + sin(a) * rad,
      a + HALF_PI + random(-0.28, 0.28),
      random(24, 70),
      random(7, 16),
      col[0], col[1], col[2],
      random(64, 132)
    );
  }
  for (let i = 0; i < 26; i++) {
