  blendMode(ADD);
  wash(800, 1158, 78, 52, 255, 224, 196, 120, 10);
  wash(800, 1068, 130, 160, 255, 168, 136, 34, 10);
  blendMode(BLEND);
  noStroke();
  fill(255, 228, 206, 46);
  ellipse(800, 1158, 24, 16);
  fill(255, 240, 226, 200);
  ellipse(800, 1158, 7, 5);

  for (let i = 0; i < 20; i++) {
    let col = palette[floor(random(palette.length))];
    petal(
      800 + random(-130, 130),
      random(1190, 1690),
      random(-1.1, 1.1),
