    strokeWeight(2);
    line(0, y, width, y);
  }
  stroke(255, 188, 154, 30);
  strokeWeight(1.3);
  noFill();
  beginShape();
  for (let x = 340; x <= 1260; x += 10) {
    vertex(x, 1602 + (noise(x * 0.012, 9) - 0.5) * 10);
  }
  endShape();

  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 38; i++) {
    let y = 1636 + i * 8.5;
    let fade = map(i, 0, 38, 13, 0);
    let wob = (noise(i * 0.18, 5.5) - 0.5) * 40;
    fill(255, 142, 112, fade);
    ellipse(800 + wob, y, 210 - i * 3.2, 7);
    fill(255, 108, 122, fade * 0.5);
    ellipse(600 + wob * 0.35, y + 3, 78, 5);
    fill(255, 182, 92, fade * 0.5);
    ellipse(1048 - wob * 0.3, y + 2, 84, 5);
  }
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 12; i++) {
    fill(200, 96, 88, random(10, 26));
