  }
}

function paintFinish() {
  blendMode(BLEND);
  strokeCap(ROUND);
  for (let i = 0; i < 220; i++) {
    let x = random(width);
    if (abs(x - 800) < 150 && random() < 0.65) continue;
    let y = random(1564, 1668);
    stroke(18, 14, 12, random(36, 86));
    strokeWeight(random(0.8, 1.6));
    line(x, y, x + random(-8, 8), y - random(18, 72));
  }

  blendMode(ADD);
