  for (let i = 0; i < 130; i++) {
    let x = 800 + (random() - 0.5) * 420 * random();
    let y = 1120 + (random() - 0.58) * 480 * random();
    fill(255, random(168, 230), random(136, 200), random(7, 20));
    ellipse(x, y, random(1.3, 3.4), random(1.3, 3.4));
  }

  blendMode(BLEND);
