    line(0, height - 1 - i, width, height - 1 - i);
    line(i, 0, i, height);
    line(width - 1 - i, 0, width - 1 - i, height);
  }
}

function ribbon(x1, y1, cx, cy, x2, y2, r, g, b, a, w, steps) {
  let px = x1;
  let py = y1;
  noStroke();
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let u = 1 - t;
    let x = u * u * x1 + 2 * u * t * cx + t * t * x2;
    let y = u * u * y1 + 2 * u * t * cy + t * t * y2;
    let dx = x - px;
    let dy = y - py;
    let n = noise(x * 0.011, y * 0.011, t * 1.8);
    let wob = (n - 0.5) * w * 0.42;
    let taper = 0.38 + 0.62 * sin(t * PI);
    let span = max(3, sqrt(dx * dx + dy * dy) * 1.75);
    push();
    translate(x + wob, y + wob * 0.28);
    rotate(atan2(dy, dx));
    fill(r, g, b, a * (0.62 + 0.38 * taper));
    ellipse(0, 0, span, max(2, w * taper));
    pop();
    px = x;
    py = y;
  }
}

function petal(x, y, rot, len, wid, r, g, b, a) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(r * 0.7, g * 0.6, b * 0.6, a * 0.5);
  beginShape();
  vertex(0, 2);
  bezierVertex(wid, -len * 0.22, wid * 0.48, -len * 0.82, 0, -len);
  bezierVertex(-wid * 0.48, -len * 0.82, -wid, -len * 0.22, 0, 2);
  endShape(CLOSE);
  fill(r, g, b, a);
  beginShape();
  vertex(0, 0);
  bezierVertex(wid * 0.7, -len * 0.28, wid * 0.34, -len * 0.8, 0, -len * 0.94);
  bezierVertex(-wid * 0.34, -len * 0.8, -wid * 0.7, -len * 0.28, 0, 0);
  endShape(CLOSE);
  fill(255, 244, 232, a * 0.26);
  beginShape();
  vertex(0, -len * 0.18);
  bezierVertex(wid * 0.2, -len * 0.4, wid * 0.1, -len * 0.68, 0, -len * 0.76);
  bezierVertex(-wid * 0.1, -len * 0.68, -wid * 0.2, -len * 0.4, 0, -len * 0.18);
  endShape(CLOSE);
  pop();
}

function wash(x, y, rx, ry, r, g, b, a, layers) {
  noStroke();
  for (let i = layers; i >= 1; i--) {
    fill(r, g, b, (a / layers) * (0.35 + 0.65 * (1 - i / layers)));
    ellipse(x, y, (rx * 2 * i) / layers, (ry * 2 * i) / layers);
  }
}

