}

function drawBezierFlow(x1, y1, c1x, c1y, c2x, c2y, x2, y2, col1, col2, n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let t = random(1);
    let x = bezierPoint(x1, c1x, c2x, x2, t);
    let y = bezierPoint(y1, c1y, c2y, y2, t);
    x += random(-38, 38);
    y += random(-38, 38);

    let c = lerpColor(col1, col2, t);
    let alpha = random(20, 130);
    fill(red(c), green(c), blue(c), alpha);
    let d = random(2, 9);
    ellipse(x, y, d, d);

    if (random() > 0.68) {
      let t2 = min(1, t + 0.008);
      let xb = bezierPoint(x1, c1x, c2x, x2, t2);
      let yb = bezierPoint(y1, c1y, c2y, y2, t2);
      let dx = xb - x;
      let dy = yb - y;
      let len = sqrt(dx * dx + dy * dy) + 0.001;
      dx /= len;
      dy /= len;
      stroke(red(c), green(c), blue(c), alpha);
      strokeWeight(random(0.5, 2.6));
      line(x, y, x + dx * random(5, 20), y + dy * random(5, 20));
      noStroke();
    }
  }
}

function drawHeartParticles() {
  noStroke();
  let cx = 800;
  let cy = 1000;
  let S = 22;

  for (let i = 0; i < 3000; i++) {
    let t = random(TWO_PI);
    let rr = pow(random(1), 1.6) * 0.85 + 0.05;
    let hx = 16 * pow(sin(t), 3);
    let hy = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
    let nx = (noise(i * 0.01, t * 6) - 0.5) * 75;
    let ny = (noise(t * 6, i * 0.01) - 0.5) * 75;
    let x = cx + hx * S * rr + nx;
    let y = cy + hy * S * rr + ny;

    let col = lerpColor(color(160, 25, 55), color(255, 120, 80), constrain(map(rr, 0.05, 0.9, 0, 1), 0, 1));
    let alpha = random(10, 70);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(x, y, random(2, 8), random(2, 8));
  }

  for (let i = 0; i < 2200; i++) {
    let t = random(TWO_PI);
    let rr = 0.94 + random(-0.04, 0.12);
    let hx = 16 * pow(sin(t), 3);
    let hy = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
    let nx = (noise(i * 0.02, t * 4) - 0.5) * 45;
    let ny = (noise(t * 4, i * 0.02) - 0.5) * 45;
    let x = cx + hx * S * rr + nx;
    let y = cy + hy * S * rr + ny;

    let col = lerpColor(color(255, 90, 70), color(255, 230, 160), constrain(map(rr, 0.9, 1.06, 0, 1), 0, 1));
    let alpha = random(30, 130);
    fill(red(col), green(col), blue(col), alpha);
    let d = random(1.5, 5);
    ellipse(x, y, d, d);

    if (random() > 0.7) {
      fill(255, 230, 180, alpha * 0.45);
      ellipse(x - random(-2, 2), y - random(-2, 2), d * 3.2, d * 3.2);
    }
  }

  for (let i = 0; i < 700; i++) {
    let t = random(TWO_PI);
    let rr = 1.08 + random(0.05, 0.5);
    let hx = 16 * pow(sin(t), 3);
    let hy = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
    let x = cx + hx * S * rr + random(-60, 60);
    let y = cy + hy * S * rr + random(-60, 60);
    let col = color(255, 140, 110);
    let alpha = random(8, 45);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(x, y, random(1, 4), random(1, 4));
  }
}

function drawHeartOutline() {
  let cx = 800;
  let cy = 1000;
  let S = 22;
  let steps = 900;

  for (let i = 0; i < steps; i++) {
    let t = map(i, 0, steps, 0, TWO_PI);
    let hx = 16 * pow(sin(t), 3);
    let hy = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
    let x = cx + hx * S;
    let y = cy + hy * S;

    let dt = 0.01;
    let t2 = t + dt;
    let hx2 = 16 * pow(sin(t2), 3);
    let hy2 = -(13 * cos(t2) - 5 * cos(2 * t2) - 2 * cos(3 * t2) - cos(4 * t2));
    let dx = (hx2 - hx) * S;
    let dy = (hy2 - hy) * S;
    let len = sqrt(dx * dx + dy * dy) + 0.001;
    dx /= len;
    dy /= len;

    stroke(255, 200, 110, random(100, 255));
    strokeWeight(random(0.7, 3.2));
    line(x, y, x + dx * random(5, 18), y + dy * random(5, 18));
  }
  noStroke();
}

function drawHeartCoreGlow() {
