}

function drawRadialGlow(x, y, r, rr, gg, bb, aMax) {
  let ctx = drawingContext;
  let grad = ctx.createRadialGradient(x, y, 0, x, y, r);
  grad.addColorStop(0, `rgba(${rr},${gg},${bb},${aMax})`);
  grad.addColorStop(0.4, `rgba(${Math.floor(rr * 0.8)},${Math.floor(gg * 0.6)},${Math.floor(bb * 0.6)},${aMax * 0.5})`);
  grad.addColorStop(1, `rgba(${rr},${gg},${bb},0)`);
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
}

