function radialGlow(x, y, maxR, hue, sat, bri, alpha) {
  const c = color(hue, sat, bri);
  const r = red(c);
  const g = green(c);
  const b = blue(c);
  const ctx = drawingContext;
  const grad = ctx.createRadialGradient(x, y, 0, x, y, maxR);
  grad.addColorStop(0, `rgba(${r},${g},${b},${alpha})`);
  grad.addColorStop(0.4, `rgba(${r},${g},${b},${alpha * 0.45})`);
  grad.addColorStop(1, `rgba(${r},${g},${b},0)`);
  ctx.fillStyle = grad;
  ctx.fillRect(x - maxR, y - maxR, maxR * 2, maxR * 2);
}

