function heartPoint(t, sc, cx, cy) {
  const hx = 16 * pow(sin(t), 3);
  const hy = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t);
  return { x: cx + sc * hx, y: cy - sc * hy };
}

function drawRibbons() {
  drawRibbon(PI, TWO_PI, 330);
  drawRibbon(0, PI, 46);
}

function drawRibbon(t0, t1, hue) {
  const sc = 45;
  const cx = 800;
  const cy = 950;
  const steps = 360;

  for (let pass = 1; pass <= 9; pass++) {
    const w = 110 - pass * 10;
    if (w <= 0) continue;
    noFill();
    stroke(hue, 80, 100, 0.022);
    strokeWeight(w);
    strokeCap(ROUND);
    beginShape();
    for (let i = 0; i <= steps; i++) {
      const t = lerp(t0, t1, i / steps);
      const p = heartPoint(t, sc, cx, cy);
      vertex(p.x, p.y);
    }
    endShape();
  }

  noFill();
  stroke(hue, 70, 100, 0.08);
  strokeWeight(24);
  strokeCap(ROUND);
  beginShape();
  for (let i = 0; i <= steps; i++) {
    const t = lerp(t0, t1, i / steps);
    const p = heartPoint(t, sc, cx, cy);
    vertex(p.x, p.y);
  }
  endShape();

  noFill();
  stroke(hue, 55, 100, 0.75);
  strokeWeight(4.5);
  beginShape();
  for (let i = 0; i <= steps; i++) {
    const t = lerp(t0, t1, i / steps);
    const p = heartPoint(t, sc, cx, cy);
    vertex(p.x, p.y);
  }
  endShape();
}

function drawHeartParticles() {
  noStroke();
  const sc = 45;
  const cx = 800;
  const cy = 950;

  for (let i = 0; i < 8500; i++) {
    const t = random(TWO_PI);
    const p = heartPoint(t, sc, cx, cy);
    const tight = i < 3000;
    const angle = random(TWO_PI);
    const n = noise(i * 0.01, t * 3);
    const jitter = tight ? 2 + n * 16 : (0.5 + n) * 45;
    const x = p.x + cos(angle) * jitter;
    const y = p.y + sin(angle) * jitter;

    const side = sin(t) >= 0;
    const hue = side ? 46 : 330;
    const topDist = min(abs(t), abs(t - TWO_PI));
    const botDist = abs(t - PI);
    const joinAmount = max(exp(-topDist * 8), exp(-botDist * 8));
    const sat = 80 * (1 - joinAmount) + 8 * joinAmount;

    const alpha = tight ? random(0.06, 0.15) : random(0.015, 0.045);
    const radius = tight ? random(1.5, 5.5) : random(2, 12) + 7 * joinAmount;
    fill(hue, sat, 100, alpha);
    ellipse(x, y, radius, radius);
  }
}

