let W=1600;
let H=2000;
let baseHeart=[];
let tangents=[];
let normals=[];
let fibers=[];

function setup(){
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W,H);
  colorMode(HSB,360,100,100,1);
  noLoop();
  buildHeart();
  buildFibers();
}

function buildHeart(){
  let steps=400;
  for(let i=0;i<steps;i++){
    let t=TWO_PI*i/steps;
    let x=16*Math.pow(Math.sin(t),3);
    let y=13*Math.cos(t)-5*Math.cos(2*t)-2*Math.cos(3*t)-Math.cos(4*t);
    let s=43;
    baseHeart.push(createVector(W/2+x*s,H/2-y*s+30));
  }
  for(let i=0;i<baseHeart.length;i++){
    let prev=baseHeart[(i-1+baseHeart.length)%baseHeart.length];
    let next=baseHeart[(i+1)%baseHeart.length];
    let dx=next.x-prev.x;
    let dy=next.y-prev.y;
    let len=Math.sqrt(dx*dx+dy*dy);
    let tx=dx/len;
    let ty=dy/len;
    tangents.push(createVector(tx,ty));
    normals.push(createVector(-ty,tx));
  }
}

function buildFibers(){
  let count=300;
  for(let f=0;f<count;f++){
    let roll=random();
    let hue;
    if(roll<0.45){
      hue=random(320,360);
    }else if(roll<0.75){
      hue=random(18,55);
    }else{
      hue=random(260,310);
    }
    fibers.push({
      freqA:random(0.4,2.8),
      freqB:random(0.4,2.8),
      phase:random(TWO_PI),
      amp:random(6,48),
      hue:hue,
      sat:random(60,100),
      bright:random(75,100),
      alpha:random(0.05,0.16),
      weight:random(0.4,1.5)
    });
  }
}

function draw(){
  background(236,42,14);
  blendMode(ADD);

  drawGlow(W/2,H/2-80,540,268,0.045);
  drawGlow(W/2-340,H/2-480,280,330,0.05);
  drawGlow(W/2+340,H/2-480,280,22,0.05);
  drawGlow(W/2,H*0.72,340,350,0.04);

  noStroke();
  fill(350,75,100,0.05);
  beginShape();
  for(let p of baseHeart){
    vertex(p.x,p.y);
  }
  endShape(CLOSE);

  drawFibers();
  drawHeartOutline();
  drawOrbitingDust();
  drawCoreGlow();
  drawVignette();
}

function drawGlow(x,y,r,hue,a){
  let layers=26;
  for(let i=0;i<layers;i++){
    let k=i/layers;
    let rr=r*(1-k*k*0.75);
    let alpha=a*(1-k);
    noStroke();
    fill(hue,70,95,alpha);
    ellipse(x,y,rr*2,rr*2);
  }
}

function drawFibers(){
  noFill();
  for(let f of fibers){
    stroke(f.hue,f.sat,f.bright,f.alpha);
    strokeWeight(f.weight);
    beginShape();
    for(let i=0;i<baseHeart.length;i+=2){
      let p=baseHeart[i];
      let n=normals[i];
      let t=i/baseHeart.length*TWO_PI;
      let wave=Math.sin(f.freqA*t+f.phase)*0.62+Math.sin(f.freqB*t+f.phase*1.8)*0.38;
      let envelope=0.72+0.28*Math.sin(t/2+f.phase);
      let nz=noise(p.x*0.003,p.y*0.003,f.phase);
      let off=f.amp*(wave+(nz-0.5)*0.5)*envelope;
      let x=p.x+n.x*off;
      let y=p.y+n.y*off;
      curveVertex(x,y);
    }
    endShape(CLOSE);
  }
}

function drawHeartOutline(){
  noFill();
  stroke(40,60,100,0.14);
  strokeWeight(1.8);
  beginShape();
  for(let i=0;i<baseHeart.length;i+=2){
    curveVertex(baseHeart[i].x,baseHeart[i].y);
  }
  endShape(CLOSE);
}

function drawOrbitingDust(){
  noStroke();
  for(let i=0;i<1100;i++){
    let idx=Math.floor(random(baseHeart.length));
    let p=baseHeart[idx];
    let n=normals[idx];
    let angle=random(TWO_PI);
    let rad=Math.pow(random(),0.6)*random(20,130);
    let x=p.x+n.x*Math.cos(angle)*rad+random(-14,14);
    let y=p.y+n.y*Math.sin(angle)*rad+random(-14,14);
    let hue;
    if(rad<60){
      hue=random(18,55);
    }else{
      hue=random(320,360);
    }
    let size=random(0.6,4.5);
    fill(hue,random(60,100),100,random(0.08,0.35));
    ellipse(x,y,size,size);
  }
}

function drawCoreGlow(){
  noStroke();
  for(let i=0;i<baseHeart.length;i+=4){
    let p=baseHeart[i];
    fill(45,80,100,0.05);
    ellipse(p.x,p.y,28,28);
  }
}

function drawVignette(){
  blendMode(BLEND);
  let ctx=drawingContext;
  let g=ctx.createRadialGradient(W/2,H/2,400,W/2,H/2,1300);
  g.addColorStop(0,'rgba(8,8,18,0)');
  g.addColorStop(1,'rgba(8,8,18,0.65)');
  ctx.fillStyle=g;
  ctx.fillRect(0,0,W,H);
}

