    stroke(hue, 60, 78, alpha);
    strokeWeight(0.7);
    bezier(540, 1050, 370, 270 + off, 1230, 270 + off, 1060, 1030);
    bezier(540, 1050, 370, 1650 + off, 1230, 1650 + off, 1060, 1030);
