function drawHeartThreads() {
  noFill();
  for (let k = 0; k < 110; k++) {
    let sc = 14 + k * 0.21;
    let hue = map(k, 0, 110, 28, 350);
    let sat = map(k, 0, 110, 80, 55);
    let bri = map(k, 0, 110, 100, 58);
    let alpha = map(k, 0, 110, 0.14, 0.018);

    stroke(hue, sat, bri, alpha);
    strokeWeight(map(k, 0, 110, 0.35, 1.5));

    beginShape();
    for (let i = 0; i <= 260; i++) {
      let t = map(i, 0, 260, 0, TWO_PI);
      let hx = 16 * Math.pow(sin(t), 3);
      let hy = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
      let n = noise(hx * 0.018 + k * 0.055, hy * 0.018 - k * 0.045, 2.9);
      let rr = sc * (0.9 + 0.20 * n);

      let x = 800 + hx * rr + (n - 0.5) * 18;
      let y = 1020 + (hy - 6) * rr + (n - 0.5) * 18;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

