function paintBackground() {
  noStroke();
  let top = color(18, 12, 44);
  let mid = color(82, 17, 58);
  let low = color(148, 42, 46);

  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let c;
    if (t < 0.52) {
      c = lerpColor(top, mid, t / 0.52);
    } else {
      c = lerpColor(mid, low, (t - 0.52) / 0.48);
    }
    fill(c);
    rect(0, y, width, 2.5);
  }

  for (let i = 0; i < 56; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(180, 760);
    let c = random() < 0.62 ? color(9, 4, 20, random(3, 8)) : color(150, 30, 52, random(2, 6));
    fill(c);
    ellipse(x, y, r * random(0.68, 1.35), r);
