function drawBezierRibbon(pts, colA, colB, count, wMin, wMax, aMin, aMax, spread, wiggle) {
  noFill();
  for (let i = 0; i < count; i++) {
    let c = lerpColor(colA, colB, random());
    stroke(red(c), green(c), blue(c), random(aMin, aMax));
    strokeWeight(random(wMin, wMax));

    let ox = [];
    let oy = [];
    for (let k = 0; k < 4; k++) {
      ox.push(random(-spread, spread));
      oy.push(random(-spread, spread));
    }

    beginShape();
    for (let u = 0; u <= 1.0001; u += 0.016) {
      let x = bezierPoint(pts[0].x + ox[0], pts[1].x + ox[1], pts[2].x + ox[2], pts[3].x + ox[3], u);
      let y = bezierPoint(pts[0].y + oy[0], pts[1].y + oy[1], pts[2].y + oy[2], pts[3].y + oy[3], u);
      x += (noise(i * 0.73, u * wiggle) - 0.5) * spread * 0.32;
      y += (noise(i * 0.29 + 31, u * wiggle + 57) - 0.5) * spread * 0.32;
      vertex(x, y);
    }
    endShape();
  }
}

