function heartX(t, s) {
  return 16 * pow(sin(t), 3) * s;
}

function heartY(t, s) {
  return -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t)) * s;
}

function drawHeartShadow() {
  noStroke();
  fill(22, 5, 16, 48);
  beginShape();
  for (let t = 0; t <= TWO_PI + 0.02; t += 0.02) {
    vertex(800 + heartX(t, 33.5), 930 + heartY(t, 33.5));
  }
  endShape(CLOSE);
}

function softGlow(x, y, r, c, maxAlpha, layers) {
  noStroke();
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let rr = r * (0.16 + 0.84 * t);
    let a = maxAlpha * (1 - t) * (1 - t);
    fill(red(c), green(c), blue(c), a);
    ellipse(x, y, rr, rr * random(0.94, 1.06));
  }
}

function drawHeartGlow() {
  blendMode(ADD);
  softGlow(800, 930, 1180, color(255, 76, 58), 8, 22);
  softGlow(800, 905, 640, color(255, 138, 76), 12, 20);
  softGlow(800, 880, 330, color(255, 208, 132), 14, 18);
  blendMode(BLEND);
}

function drawHeartContours() {
  let cx = 800;
  let cy = 930;
  let baseS = 35;
  noFill();

  for (let layer = 0; layer < 52; layer++) {
    let s = baseS + random(-4, 6);
    let cA = color(255, 64, 82);
    let cB = color(255, 178, 96);
    let c = lerpColor(cA, cB, noise(layer * 0.17));
    stroke(red(c), green(c), blue(c), random(12, 34));
    strokeWeight(random(0.8, 3.8));

    beginShape();
    for (let t = 0; t <= TWO_PI + 0.025; t += 0.02) {
      let jx = (noise(layer * 0.23, t * 1.25) - 0.5) * 26;
      let jy = (noise(layer * 0.39 + 70, t * 1.25) - 0.5) * 26;
      vertex(cx + heartX(t, s) + jx, cy + heartY(t, s) + jy);
    }
    endShape();
  }
}

function drawHeartCore() {
  let cx = 800;
  let cy = 930;
  blendMode(ADD);
