  for (let s = 5; s <= 33; s += 2) {
    for (let t = 0; t < TWO_PI; t += 0.045) {
      let n = noise(s * 0.21, t * 2.8);
      if (n > 0.32) {
        let x = cx + heartX(t, s) + random(-5, 5);
        let y = cy + heartY(t, s) + random(-5, 5);
        let c = lerpColor(color(255, 72, 70), color(255, 214, 145), noise(t * 1.7, s * 0.05));
        fill(red(c), green(c), blue(c), random(2, 7));
        ellipse(x, y, random(4, 20), random(4, 20));
      }
    }
  }

  for (let t = 0; t < TWO_PI; t += 0.012) {
    let x = cx + heartX(t, 35);
    let y = cy + heartY(t, 35);
    let c = lerpColor(color(255, 120, 78), color(255, 230, 175), noise(t * 3.3));
    fill(red(c), green(c), blue(c), random(4, 10));
    ellipse(x + random(-3, 3), y + random(-3, 3), random(2, 9), random(2, 9));
