  const cool = { x: 1005, y: 950, r: 330 };
  const meet = { x: (warm.x + cool.x) / 2 + 8, y: (warm.y + cool.y) / 2 + 6 };

  drawBackground(horizon);
  drawWaterBase(horizon);
  drawAurora(horizon);
  drawHaloRings(warm, cool, horizon);
  drawWeavingThreads(warm, cool, meet, horizon);
  drawLights(warm, cool, meet);
  drawReflections(warm, cool, meet, horizon);
  drawBloom(meet);
  drawFireflies(horizon, meet);
  drawVignette();
