function drawBackground(horizon) {
  let c0 = color(249, 84, 7);
  let c1 = color(276, 66, 13);
  let c2 = color(324, 58, 17);
  let c3 = color(16, 72, 15);
  for (let y = 0; y <= horizon; y++) {
    let t = y / horizon;
    let c;
    if (t < 0.42) c = lerpColor(c0, c1, t / 0.42);
    else if (t < 0.78) c = lerpColor(c1, c2, (t - 0.42) / 0.36);
    else c = lerpColor(c2, c3, (t - 0.78) / 0.22);
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();
}

function drawWaterBase(horizon) {
  let c0 = color(226, 78, 10);
  let c1 = color(250, 82, 7);
  let c2 = color(258, 88, 4);
  for (let y = horizon; y <= height; y++) {
    let t = (y - horizon) / (height - horizon);
    let c;
    if (t < 0.35) c = lerpColor(c0, c1, t / 0.35);
    else c = lerpColor(c1, c2, (t - 0.35) / 0.65);
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();

  blendMode(SCREEN);
  for (let y = horizon + 5; y < height; y += 5) {
    let n = noise(y * 0.015, 3.7);
    let a = map(y, horizon, height, 4.2, 1.2) * (0.35 + n);
    stroke(204 + n * 72, 52, 26 + n * 18, a);
    strokeWeight(0.6 + n * 1.1);
    let bend = (noise(y * 0.06, 11.1) - 0.5) * 14;
    let x0 = noise(y * 0.02, 7.7) * 260;
    let x1 = width - noise(y * 0.02, 17.3) * 260;
    line(x0, y + bend, x1, y - bend * 0.6);
  }
  blendMode(BLEND);
}

