  blendMode(SCREEN);
  noFill();
  ringSet(warm.x, warm.y, 200, 430, 8, 48, 92);
  ringSet(cool.x, cool.y, 190, 410, 175, 225, 90);
  ctx.restore();
  blendMode(BLEND);
}

function ringSet(cx, cy, rMin, rMax, h0, h1, bri) {
  for (let i = 0; i < 58; i++) {
    let r = random(rMin, rMax);
    let start = random(TWO_PI);
    let span = random(PI / 5, PI * 1.4);
    let h = lerp(h0, h1, random());
    stroke(h, random(45, 72), bri, random(2.2, 5.5));
    strokeWeight(random(0.5, 2.2));
    arc(cx, cy, r * 2, r * 2, start, start + span);
  }
}

function drawWeavingThreads(warm, cool, meet, horizon) {
  const ctx = drawingContext;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, width, horizon + 30);
  ctx.clip();
  blendMode(SCREEN);
  noFill();
  for (let i = 0; i < 165; i++) {
    let kind = i % 3;
    let ax, ay, bx, by;
    if (kind === 0) {
      ax = warm.x; ay = warm.y; bx = cool.x; by = cool.y;
    } else if (kind === 1) {
      ax = warm.x; ay = warm.y; bx = meet.x; by = meet.y;
    } else {
      ax = cool.x; ay = cool.y; bx = meet.x; by = meet.y;
    }

    let amp = random(24, 250);
    let phase = random(TWO_PI);
    let offX = random(-140, 140);
    let offY = random(-220, 220);
    let hue;
    if (kind === 0) hue = lerp(16, 194, random());
    else if (kind === 1) hue = random(8, 46);
    else hue = random(168, 216);

    stroke(hue, random(48, 78), 96, random(2.0, 5.2));
    strokeWeight(random(0.5, 1.9));
    beginShape();
    for (let u = 0; u <= 1.0001; u += 0.025) {
      let envelope = sin(u * PI);
      let x = lerp(ax, bx, u) + offX * envelope + sin(u * TWO_PI * 1.35 + phase) * amp * envelope;
      let y = lerp(ay, by, u) + offY * envelope + cos(u * TWO_PI * 0.85 + phase) * amp * 0.42 * envelope + (noise(u * 4 + i * 0.013) - 0.5) * 68;
      vertex(x, y);
    }
    endShape();
  }
  ctx.restore();
  blendMode(BLEND);
}

