function drawReflections(warm, cool, meet, horizon) {
  const ctx = drawingContext;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, horizon, width, height - horizon);
  ctx.clip();

  let squash = 0.62;
  let warmY = horizon + (horizon - warm.y) * squash;
  let coolY = horizon + (horizon - cool.y) * squash;
  let meetY = horizon + (horizon - meet.y) * squash;

  glowEllipse(warm.x, warmY, 380, 580, [
    [0, color(15, 90, 90, 10)],
    [0.5, color(8, 90, 80, 5)],
    [1, color(8, 90, 80, 0)]
  ], 'screen');

  glowEllipse(cool.x, coolY, 330, 520, [
    [0, color(190, 90, 90, 9)],
    [0.5, color(210, 90, 80, 4.5)],
    [1, color(210, 90, 80, 0)]
  ], 'screen');

  glowEllipse(meet.x, meetY, 260, 430, [
    [0, color(44, 90, 100, 8)],
    [0.55, color(38, 90, 95, 4)],
    [1, color(38, 90, 95, 0)]
  ], 'screen');

  blendMode(SCREEN);
  for (let i = 0; i < 170; i++) {
    let kind = i % 3;
    let baseX, hue;
    if (kind === 0) {
      baseX = warm.x; hue = random(10, 36);
    } else if (kind === 1) {
      baseX = cool.x; hue = random(172, 214);
    } else {
      baseX = meet.x; hue = random(38, 52);
    }
    let x = constrain(randGaussian(baseX, 85), -30, width + 30);
    let y0 = horizon + random(6, 540);
    if (y0 >= height - 12) continue;
    let len = random(22, 250);
    let sway = random(-18, 18);
    stroke(hue, random(55, 82), 95, random(1.6, 4.6));
    strokeWeight(random(0.5, 2.0));
    line(x, y0, x + sway, min(height, y0 + len));
  }
  ctx.restore();
  blendMode(BLEND);
}

function drawBloom(meet) {
  push();
  translate(meet.x, meet.y);
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 235; i++) {
    let ang = i * 0.315 + random(-0.05, 0.05);
    let rad = pow(i, 0.62) * 13.8;
    let x = cos(ang) * rad * 0.82;
    let y = sin(ang) * rad * 1.08;
    let sz = map(i, 0, 235, 96, 7) * random(0.75, 1.25);
    let h = lerp(14, 54, noise(i * 0.021)) + random(-6, 6);
    fill(h, 62 + noise(i * 0.033) * 32, 100, random(1.7, 4.0));
    push();
    translate(x, y);
    rotate(ang + HALF_PI + random(-0.12, 0.12));
    ellipse(0, 0, sz * 0.34, sz);
    pop();
  }
  for (let i = 0; i < 42; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 0.65) * 72;
    let s = random(1.4, 5.2);
    fill(47, 42, 100, random(9, 22));
    ellipse(cos(a) * r, sin(a) * r * 1.12, s, s);
  }
  pop();
  blendMode(BLEND);
}

function drawFireflies(horizon, meet) {
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = constrain(randGaussian(meet.x, 380), -60, width + 60);
    let y = constrain(randGaussian(meet.y - 30, 350), -60, height + 40);
    if (random() < 0.32) {
      y = constrain(randGaussian(horizon + 180, 220), horizon, height + 20);
    }
    let below = y > horizon;
    let r = random();
    let h;
    if (r < 0.45) h = random(12, 42);
    else if (r < 0.88) h = random(170, 218);
    else h = 48;
    let s = random(1.2, 6.8);
    let a = below ? random(1.0, 4.2) : random(2.5, 12.0);
    fill(h, 60, 100, a * 0.26);
    ellipse(x, y, s * 4.8, s * 4.8);
    fill(h, 24, 100, a);
    ellipse(x, y, s, s);
    if (random() < 0.28) {
      stroke(h, 28, 100, a * 0.22);
      strokeWeight(0.55);
      let len = s * random(2.0, 5.0);
      line(x - len, y, x + len, y);
      line(x, y - len, x, y + len);
      noStroke();
    }
  }
  blendMode(BLEND);
}

function drawVignette() {
  glowEllipse(width * 0.5, height * 0.46, width * 0.92, height * 0.82, [
    [0, color(0, 0, 100, 100)],
    [0.66, color(0, 0, 100, 100)],
    [1, color(260, 82, 10, 52)]
  ], 'multiply');
}

function drawGrain() {
  blendMode(BLEND);
  strokeWeight(1);
  for (let i = 0; i < 9500; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.52) stroke(0, 0, 0, random(1.0, 2.8));
    else stroke(0, 0, 100, random(0.8, 2.2));
    point(x, y);
  }
  noStroke();
}

function glowEllipse(x, y, rx, ry, stops, mode) {
  const ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = mode || 'screen';
  ctx.translate(x, y);
  ctx.scale(rx / 100, ry / 100);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 100);
  for (let i = 0; i < stops.length; i++) {
    g.addColorStop(stops[i][0], stops[i][1].toString());
  }
  ctx.fillStyle = g;
  ctx.fillRect(-100, -100, 200, 200);
  ctx.restore();
}

function randGaussian(mean, sd) {
  let u = 1 - random();
  let v = random();
  return mean + sd * sqrt(-2 * log(u)) * cos(TWO_PI * v);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 1);
  background(230, 72, 5);
  noLoop();

  paintBase();
  paintBrushTexture();
  drawAuras();
  drawRibbons();
  drawHeartCore();
  drawSparks();
  drawVignette();
  drawFrame();
}

function paintBase() {
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let h, s, b;
    if (t < 0.44) {
      let u = t / 0.44;
      h = hueLerp(226, 272, u);
      s = lerp(74, 60, u);
      b = lerp(6, 10, u);
    } else if (t < 0.78) {
      let u = (t - 0.44) / 0.34;
      h = hueLerp(272, 346, u);
      s = lerp(60, 62, u);
      b = lerp(10, 14, u);
    } else {
      let u = (t - 0.78) / 0.22;
      h = hueLerp(346, 18, u);
      s = lerp(62, 70, u);
      b = lerp(14, 11, u);
    }
    let n = noise(y * 0.005, 3.7);
    h = (h + (n - 0.5) * 18 + 360) % 360;
    s = constrain(s + (n - 0.5) * 10, 0, 100);
    b = constrain(b + (n - 0.5) * 5, 0, 100);
    fill(h, s, b);
    rect(0, y, width, 2);
  }
}

function paintBrushTexture() {
  push();
  for (let i = 0; i < 2600; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0022, y * 0.0022);
    let ang = n * TWO_PI * 2.2;
    let len = random(16, 130);
    let dx = cos(ang) * len;
    let dy = sin(ang) * len * 0.34;
    let h = hueLerp(226, 350, y / height);
    h = (h + random(-20, 20) + 360) % 360;
    stroke(h, random(22, 58), random(16, 64), random(0.014, 0.05));
    strokeWeight(random(0.6, 2.3));
    line(x - dx * 0.5, y - dy * 0.5, x + dx * 0.5, y + dy * 0.5);
  }
  pop();
}

function drawAuras() {
  push();
  blendMode(ADD);
  glow(width * 0.50, height * 0.38, 650, 345, 68, 96, 0.028, 30);
  glow(width * 0.26, height * 0.23, 430, 262, 55, 76, 0.022, 22);
  glow(width * 0.76, height * 0.58, 480, 24, 68, 86, 0.020, 22);
  glow(width * 0.50, height * 0.90, 540, 16, 72, 82, 0.018, 26);
  pop();
}

function drawRibbons() {
  let phaseA = -0.35;
  let phaseB = 2.65;
  push();
  blendMode(ADD);
  drawRibbonGlow(phaseA, 348);
  drawRibbonGlow(phaseB, 38);

  drawRibbon(phaseA, 348, 80, 97, 0.042, 30, 94, 1.0, 3.5);
  drawRibbon(phaseB, 38, 84, 97, 0.038, 30, 94, 1.0, 3.5);

  drawRibbon(phaseA, 354, 46, 100, 0.075, 10, 20, 0.7, 1.8);
  drawRibbon(phaseB, 44, 42, 100, 0.068, 10, 20, 0.7, 1.8);
  pop();
}

function drawRibbonGlow(phase, h) {
  for (let t = 0.02; t < 1.0; t += 0.045) {
    let p = ribbonPoint(t, phase, 0);
    let r = 115 * (0.32 + 0.68 * sin(t * PI));
    glow(p[0], p[1], r, h, 72, 100, 0.013, 12);
  }
}

function drawRibbon(phase, baseHue, baseSat, baseBri, baseAlpha, strands, spread, wMin, wMax) {
  noFill();
  let steps = 235;
  for (let j = 0; j < strands; j++) {
    let offset = (j / (strands - 1) - 0.5) * spread;
    let h = (baseHue + random(-16, 16) + 360) % 360;
    let s = constrain(baseSat + random(-14, 10), 12, 100);
    let b = constrain(baseBri + random(-8, 6), 25, 100);
    let a = baseAlpha * random(0.38, 1.22);
    stroke(h, s, b, a);
    strokeWeight(random(wMin, wMax));
    beginShape();
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let p = ribbonPoint(t, phase, offset);
      vertex(p[0], p[1]);
    }
    endShape();
  }
}

function ribbonPoint(t, phase, offset) {
  let shrink = pow(max(0, 1 - t), 0.78);
  let twist = phase + t * 7.45;
  let sep = width * 0.205 * shrink;
  let lift = sep * 0.18 * sin(twist + 0.8);
  let y = height * (0.055 + 0.895 * t) + lift + (noise(t * 5.2 + phase * 0.13 + offset * 0.011) - 0.5) * 30;
  let n = noise(t * 3.15 + phase * 0.23 + offset * 0.017) - 0.5;
  let off = offset * (0.12 + 0.88 * shrink);
  let x = width / 2 + sep * cos(twist) + off + n * 58 * (0.22 + 0.78 * shrink);
  return [x, y];
}

function drawHeartCore() {
  let cx = width * 0.5;
  let cy = height * 0.385;
  let s = 245;
  push();
  blendMode(ADD);
  noStroke();
  glow(cx, cy, s * 2.25, 345, 70, 100, 0.026, 28);
  glow(cx, cy, s * 1.05, 36, 55, 100, 0.038, 20);
  for (let i = 0; i < 20; i++) {
    let ss = s * (1 + i * 0.062);
    let h = (345 + i * 2.3) % 360;
    let a = map(i, 0, 19, 0.058, 0.008);
    fill(h, constrain(78 - i * 2, 18, 100), 100, a);
    heartShape(cx, cy, ss);
  }
  glow(cx, cy, 74, 42, 30, 100, 0.060, 18);
  pop();
}

function heartShape(cx, cy, s) {
  beginShape();
  vertex(cx, cy + s * 0.62);
  bezierVertex(cx - s * 0.78, cy + s * 0.06, cx - s * 0.62, cy - s * 0.62, cx, cy - s * 0.28);
  bezierVertex(cx + s * 0.62, cy - s * 0.62, cx + s * 0.78, cy + s * 0.06, cx, cy + s * 0.62);
  endShape(CLOSE);
}

function drawSparks() {
  push();
  blendMode(ADD);
  noStroke();
  let phaseA = -0.35;
  let phaseB = 2.65;
  for (let i = 0; i < 560; i++) {
    let t = random();
    let phase = random() < 0.5 ? phaseA : phaseB;
    let offset = random(-64, 64);
    let p = ribbonPoint(t, phase, offset);
    let r = random(1.1, 6.2);
    let h = random() < 0.62 ? (random(330, 372) % 360) : random(28, 52);
    fill(h, random(28, 80), 100, random(0.05, 0.20));
    ellipse(p[0] + random(-18, 18), p[1] + random(-18, 18), r, r);
  }
  for (let i = 0; i < 380; i++) {
    let x = width * 0.5 + randomGaussian() * width * 0.20;
    let y = height * 0.39 + randomGaussian() * height * 0.16;
    let r = random(0.8, 3.4);
    let h = random() < 0.72 ? 348 : 42;
    fill(h, random(20, 68), 100, random(0.03, 0.11));
    ellipse(x, y, r, r);
  }
  for (let i = 0; i < 85; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(9, 38);
    let h = random() < 0.52 ? 268 : 348;
    fill(h, 48, 100, random(0.007, 0.028));
    ellipse(x, y, r, r);
  }
  pop();
}

function glow(x, y, radius, h, s, b, alpha, layers) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < layers; i++) {
    let t = i / max(1, layers - 1);
    let r = radius * (1 - t * 0.88);
    let a = alpha * (1 - t) * (1 - t);
    fill(h, s, b, a);
    ellipse(x, y, r * 2, r * 2);
  }
  pop();
}

function drawVignette() {
  const ctx = drawingContext;
  ctx.save();
  let g = ctx.createRadialGradient(width * 0.5, height * 0.40, height * 0.14, width * 0.5, height * 0.50, height * 0.80);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.60, 'rgba(10,6,18,0.10)');
  g.addColorStop(1, 'rgba(4,2,8,0.72)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  let g2 = ctx.createLinearGradient(0, 0, 0, height);
  g2.addColorStop(0, 'rgba(3,4,10,0.36)');
  g2.addColorStop(0.22, 'rgba(0,0,0,0)');
  g2.addColorStop(0.78, 'rgba(0,0,0,0)');
  g2.addColorStop(1, 'rgba(8,3,6,0.44)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function drawFrame() {
  push();
  noFill();
  strokeWeight(2.4);
  stroke(40, 42, 88, 0.18);
  rect(52, 52, width - 104, height - 104);
  strokeWeight(1);
  stroke(350, 46, 92, 0.10);
  rect(74, 74, width - 148, height - 148);
  pop();
}

function hueLerp(a, b, t) {
  let d = (b - a + 540) % 360 - 180;
  return (a + d * t + 360) % 360;
}

let heartCX, heartCY, heartScale;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 100);
  heartCX = width * 0.5;
  heartCY = height * 0.42;
  heartScale = 40;
  noLoop();
  paint();
}

function draw() {}

function paint() {
  drawBackground();
  drawGrain();
  drawCentralGlow();
  drawHeartFill();
  drawHeartBrush();
  drawHeartSparks();
  drawFloatingSeeds();
  drawVignette();
}

function drawBackground() {
  let ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = "source-over";
  let g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0.00, color(231, 75, 13, 100).toString());
  g.addColorStop(0.36, color(256, 60, 18, 100).toString());
  g.addColorStop(0.68, color(324, 52, 26, 100).toString());
  g.addColorStop(0.86, color(351, 58, 34, 100).toString());
  g.addColorStop(1.00, color(19, 72, 36, 100).toString());
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function drawGrain() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 4800; i++) {
    let x = random(width);
    let y = random(height);
    let cool = y < height * 0.56;
    let hue = cool ? random(212, 262) : random(14, 46);
    fill(hue, random(18, 65), random(16, 78), random(0.5, 3.0));
    circle(x, y, random(0.6, 2.4));
  }
}

function drawCentralGlow() {
  let ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  let g = ctx.createRadialGradient(heartCX, heartCY, 0, heartCX, heartCY, 980);
  g.addColorStop(0.00, color(22, 95, 100, 22).toString());
  g.addColorStop(0.32, color(345, 85, 92, 12).toString());
  g.addColorStop(0.68, color(275, 60, 45, 5).toString());
  g.addColorStop(1.00, color(0, 0, 0, 0).toString());
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function drawHeartFill() {
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 32; i++) {
    let f = i / 31;
    let s = heartScale * (1.16 - f * 0.58);
    let hue = (330 + f * 80) % 360;
    fill(hue, lerp(85, 45, f), lerp(45, 100, f), 2.0);
    beginShape();
    for (let t = 0; t <= TWO_PI; t += 0.018) {
      let p = heartPoint(t, s);
      let wob = (noise(cos(t) * 0.42 + i * 0.13 + 7, sin(t) * 0.42 + 13) - 0.5) * 24 * (1 - f * 0.55);
      vertex(p.x + wob, p.y + wob * 0.65);
    }
    endShape(CLOSE);
  }
  blendMode(BLEND);
}

function drawHeartBrush() {
  blendMode(SCREEN);
  strokeCap(ROUND);

  for (let i = 0; i < 11500; i++) {
    let t = random(TWO_PI);
    let p = heartPoint(t, heartScale);
    let f = heartFrame(t);
    let off = randomGaussian(0, 22) + (noise(cos(t) * 0.55 + 31, sin(t) * 0.55 + 67, i * 0.0003) - 0.5) * 100;
    off = constrain(off, -190, 190);
    let x = p.x + f.nx * off;
    let y = p.y + f.ny * off;
    let ang = atan2(f.ty, f.tx) + random(-0.24, 0.24) + (noise(t * 1.7 + 5, i * 0.0006) - 0.5) * 0.9;
    let proximity = constrain(1 - abs(off) / 210, 0.12, 1);
    let len = random(9, 68) * proximity;
    strokeWeight(random(0.5, 3.6) * proximity + 0.16);
    let side = constrain(map(p.x, heartCX - 540, heartCX + 540, 0, 1), 0, 1);
    let hue = (337 + side * 68 + random(-11, 11)) % 360;
    let sat = random(56, 96);
    if (random() < 0.09) sat = random(8, 32);
    stroke(hue, sat, random(80, 100), random(2, 11) * (0.35 + proximity * 0.85));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  for (let i = 0; i < 2600; i++) {
    let t = random(TWO_PI);
    let p = heartPoint(t, heartScale);
    let f = heartFrame(t);
    let off = randomGaussian(0, 7) + (noise(cos(t) * 0.7 + 71, sin(t) * 0.7 + 97, i * 0.0004) - 0.5) * 22;
    off = constrain(off, -55, 55);
    let x = p.x + f.nx * off;
    let y = p.y + f.ny * off;
    let ang = atan2(f.ty, f.tx) + random(-0.12, 0.12);
    let len = random(16, 95);
    strokeWeight(random(0.6, 2.4));
    let side = constrain(map(p.x, heartCX - 540, heartCX + 540, 0, 1), 0, 1);
    let hue = (339 + side * 64 + random(-7, 7)) % 360;
    let sat = random(18, 72);
    if (random() < 0.22) sat = random(4, 18);
    stroke(hue, sat, random(90, 100), random(6, 20));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  blendMode(BLEND);
}

function drawHeartSparks() {
  blendMode(SCREEN);
  noStroke();

  for (let i = 0; i < 3300; i++) {
    let t = random(TWO_PI);
    let p = heartPoint(t, heartScale);
    let f = heartFrame(t);
    let off = randomGaussian(0, 58) + (noise(cos(t) * 0.8 + 11, sin(t) * 0.8 + 29, i * 0.0002) - 0.5) * 140;
    off = constrain(off, -230, 230);
    let x = p.x + f.nx * off + random(-4, 4);
    let y = p.y + f.ny * off + random(-4, 4);
    let side = constrain(map(p.x, heartCX - 540, heartCX + 540, 0, 1), 0, 1);
    let hue = (335 + side * 70 + random(-12, 12)) % 360;
    let sat = random(45, 95);
    if (random() < 0.14) sat = random(5, 25);
    let alpha = random(2, 16);
    let sz = random(0.8, 5.2);
    if (random() < 0.025) {
      sz = random(7, 16);
      alpha *= 0.45;
    }
    fill(hue, sat, random(85, 100), alpha);
    circle(x, y, sz);
  }

  for (let i = 0; i < 950; i++) {
    let t = random(TWO_PI);
    let p = heartPoint(t, heartScale);
    let f = heartFrame(t);
    let off = constrain(randomGaussian(0, 8), -30, 30);
    let x = p.x + f.nx * off;
    let y = p.y + f.ny * off;
    let side = constrain(map(p.x, heartCX - 540, heartCX + 540, 0, 1), 0, 1);
    let hue = (340 + side * 60) % 360;
    fill(hue, random(5, 25), 100, random(8, 22));
    circle(x, y, random(0.8, 3.0));
  }

  blendMode(BLEND);
}

function drawFloatingSeeds() {
  blendMode(SCREEN);
  noStroke();

  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, heartCX, heartCY);
    if (d < 560 && random() < 0.55) continue;

    let lower = y > height * 0.60;
    let hue = lower ? random(16, 46) : random(280, 345);
    let sat = random(30, 88);
    if (random() < 0.12) sat = random(5, 25);
    let alpha = random(1.5, 9);
    let sz = random(0.8, 3.8);
    if (random() < 0.035) {
      sz = random(6, 18);
      alpha = random(1.5, 4);
    }
    fill(hue, sat, random(68, 100), alpha);
    circle(x, y, sz);
  }

  for (let i = 0; i < 42; i++) {
    let x = random(width);
    let y = random(height);
    let hue = random() < 0.55 ? random(18, 44) : random(320, 352);
    fill(hue, random(25, 65), 100, random(1.2, 3.4));
    circle(x, y, random(20, 120));
    if (random() < 0.5) {
      fill(hue, random(15, 35), 100, random(2, 5));
      circle(x, y, random(6, 20));
    }
  }

  blendMode(BLEND);
}

function drawVignette() {
  blendMode(BLEND);
  let ctx = drawingContext;

  ctx.save();
  ctx.globalCompositeOperation = "source-over";
  let g = ctx.createRadialGradient(heartCX, heartCY, 360, heartCX, height * 0.50, 1450);
  g.addColorStop(0.00, color(0, 0, 0, 0).toString());
  g.addColorStop(0.55, color(255, 70, 8, 10).toString());
  g.addColorStop(1.00, color(250, 85, 4, 58).toString());
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  let top = ctx.createLinearGradient(0, 0, 0, 420);
  top.addColorStop(0.00, color(240, 80, 4, 34).toString());
  top.addColorStop(1.00, color(0, 0, 0, 0).toString());
  ctx.fillStyle = top;
  ctx.fillRect(0, 0, width, 420);
  ctx.restore();

  ctx.save();
  ctx.globalCompositeOperation = "screen";
  let b = ctx.createLinearGradient(0, height * 0.82, 0, height);
  b.addColorStop(0.00, color(20, 80, 80, 0).toString());
  b.addColorStop(1.00, color(20, 85, 90, 9).toString());
  ctx.fillStyle = b;
  ctx.fillRect(0, height * 0.82, width, height * 0.18);
  ctx.restore();
}

function heartPoint(t, s) {
  if (s === undefined) s = heartScale;
  let st = sin(t);
  let x = 16 * st * st * st;
  let y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t);
  return {
    x: heartCX + x * s,
    y: heartCY - y * s
  };
}

function heartFrame(t) {
  let dt = 0.002;
  let a = heartPoint(t - dt, heartScale);
  let b = heartPoint(t + dt, heartScale);
  let tx = b.x - a.x;
  let ty = b.y - a.y;
  let len = sqrt(tx * tx + ty * ty);
  if (len < 0.0001) {
    return { tx: 1, ty: 0, nx: 0, ny: -1 };
  }
  tx /= len;
  ty /= len;
  return {
    tx: tx,
    ty: ty,
    nx: -ty,
    ny: tx
  };
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  paintBackground();
  paintBrushTexture();
  paintAtmosphere();
  drawRibbons();
  drawHeart();
  drawSparks();
  drawVignette();
}

function rgba(c, a) {
  return 'rgba(' + Math.round(red(c)) + ',' + Math.round(green(c)) + ',' + Math.round(blue(c)) + ',' + a + ')';
}

function clamp255(v) {
  return Math.max(0, Math.min(255, v));
}

function paintBackground() {
  let c0 = color(14, 9, 30);
  let c1 = color(42, 20, 62);
  let c2 = color(96, 32, 66);
  let c3 = color(214, 104, 72);
  noFill();
  strokeWeight(1);

  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c;
    if (t < 0.34) {
      c = lerpColor(c0, c1, t / 0.34);
    } else if (t < 0.68) {
      c = lerpColor(c1, c2, (t - 0.34) / 0.34);
    } else {
      c = lerpColor(c2, c3, (t - 0.68) / 0.32);
    }

    let n = (noise(y * 0.008) - 0.5) * 12;
    stroke(
      clamp255(red(c) + n),
      clamp255(green(c) + n * 0.65),
      clamp255(blue(c) + n * 0.35),
      255
    );
    line(0, y, width, y);
  }
}

function paintBrushTexture() {
  blendMode(BLEND);
  noStroke();

  for (let i = 0; i < 210; i++) {
    let x = random(width);
    let y = random(height);
    let t = y / height;

    let base = lerpColor(color(58, 64, 150), color(255, 112, 82), t);
    let light = color(255, 232, 200);
    let c = lerpColor(base, light, noise(x * 0.0022, y * 0.0022) * 0.4);

    fill(red(c), green(c), blue(c), random(3, 9));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(100, 420), random(26, 120));
    pop();
  }
}

function radialGlow(x, y, r, c, a) {
  let ctx = drawingContext;
  ctx.save();

  let grad = ctx.createRadialGradient(x, y, 0, x, y, r);
  grad.addColorStop(0, rgba(c, a));
  grad.addColorStop(0.45, rgba(c, a * 0.42));
  grad.addColorStop(1, rgba(c, 0));

  ctx.fillStyle = grad;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
  ctx.restore();
}

function paintAtmosphere() {
  blendMode(ADD);
  radialGlow(420, 360, 560, color(80, 110, 235), 0.09);
  radialGlow(1230, 520, 590, color(235, 95, 140), 0.09);
  radialGlow(800, 840, 820, color(255, 150, 120), 0.12);
  radialGlow(820, 1480, 920, color(255, 120, 85), 0.08);
  blendMode(BLEND);
}

function offsetPoint(p, layer, i, amt) {
  let nx = (noise(layer * 0.31 + i * 3.73, 17.11) - 0.5) * 2;
  let ny = (noise(layer * 0.31 + i * 3.73, 91.37) - 0.5) * 2;
  return createVector(p.x + nx * amt, p.y + ny * amt);
}

function drawFlow(pts, c1, c2, maxW, baseAlpha) {
  noFill();
  curveTightness(-0.06);

  for (let layer = 0; layer < 28; layer++) {
    let t = layer / 27;
    let col = lerpColor(c1, c2, t);
    let w = maxW * pow(1 - t, 1.35) + 0.8;
    let a = baseAlpha * (1 - t * 0.62);

    stroke(red(col), green(col), blue(col), a);
    strokeWeight(w);

    let p = [];
    for (let i = 0; i < pts.length; i++) {
      p.push(offsetPoint(pts[i], layer, i, 14 + layer * 1.45));
    }

    beginShape();
    curveVertex(p[0].x, p[0].y);
    for (let i = 0; i < p.length; i++) {
      curveVertex(p[i].x, p[i].y);
    }
    curveVertex(p[p.length - 1].x, p[p.length - 1].y);
    endShape();
  }
}

function drawRibbons() {
  let cool = [
    createVector(150, 210),
    createVector(520, 420),
    createVector(905, 700),
    createVector(575, 1045),
    createVector(880, 1430),
    createVector(520, 1880)
  ];

  let warm = [
    createVector(1450, 250),
    createVector(1065, 480),
    createVector(705, 780),
    createVector(1015, 1135),
    createVector(745, 1530),
    createVector(1095, 1910)
  ];

  blendMode(ADD);
  drawFlow(cool, color(105, 155, 255), color(205, 125, 255), 34, 16);
  drawFlow(warm, color(255, 105, 120), color(255, 195, 120), 36, 16);
  blendMode(BLEND);
}

function heartPoints(cx, cy, s, seed) {
  let pts = [];
  let steps = 190;

  for (let i = 0; i <= steps; i++) {
    let th = map(i, 0, steps, 0, TWO_PI);
    let hx = 16 * pow(sin(th), 3);
    let hy = 13 * cos(th) - 5 * cos(2 * th) - 2 * cos(3 * th) - cos(4 * th);

    let px = hx * s / 16;
    let py = -hy * s / 16;

    let n1 = noise(seed * 0.17 + cos(th) * 0.72 + 3.1, seed * 0.13 + sin(th) * 0.72 + 7.7) - 0.5;
    let n2 = noise(seed * 0.21 + cos(th) * 0.72 + 11.9, seed * 0.11 + sin(th) * 0.72 + 5.2) - 0.5;

    pts.push(createVector(cx + px + n1 * s * 0.035, cy + py + n2 * s * 0.035));
  }

  return pts;
}

function drawHeart() {
  blendMode(ADD);

  radialGlow(800, 800, 430, color(255, 180, 155), 0.18);
  radialGlow(800, 825, 290, color(255, 235, 205), 0.20);

  noFill();

  for (let i = 0; i < 30; i++) {
    let t = i / 29;
    let size = 255 + t * 150;
    let col = lerpColor(color(255, 115, 145), color(255, 205, 130), t);
    let a = 20 * (1 - t) + 3;
    let w = lerp(6.5, 1.1, t);

    stroke(red(col), green(col), blue(col), a);
    strokeWeight(w);

    let pts = heartPoints(800, 795, size, i);
    beginShape();
    for (let k = 0; k < pts.length; k++) {
      vertex(pts[k].x, pts[k].y);
    }
    endShape(CLOSE);
  }

  for (let i = 0; i < 6; i++) {
    let size = 235 - i * 6;
    let a = 18 - i * 2;

    stroke(255, 242, 225, a);
    strokeWeight(1.5 + i * 0.2);

    let pts = heartPoints(800, 795, size, 80 + i);
    beginShape();
    for (let k = 0; k < pts.length; k++) {
      vertex(pts[k].x, pts[k].y);
    }
    endShape(CLOSE);
  }

  blendMode(BLEND);
}

function drawSparks() {
  blendMode(ADD);
  noStroke();

  let palette = [
    color(255, 215, 170),
    color(255, 150, 160),
    color(150, 185, 255),
    color(255, 245, 235),
    color(255, 120, 110)
  ];

  for (let i = 0; i < 300; i++) {
    let x, y;
    let region = random();

    if (region < 0.52) {
      let ang = random(TWO_PI);
      let r = pow(random(), 0.62) * 590;
      x = 800 + cos(ang) * r * 1.12;
      y = 800 + sin(ang) * r * 0.92;
    } else if (region < 0.80) {
      x = random(150, 1450);
      y = random(1080, 1940);
    } else {
      x = random(90, 1510);
      y = random(90, 880);
    }

    let c = palette[floor(random(palette.length))];
    let s = random(1.2, 5.8);
    let a = random(14, 72);

    fill(red(c), green(c), blue(c), a);
    circle(x, y, s);

    if (random() < 0.07) {
      stroke(red(c), green(c), blue(c), a * 0.5);
      strokeWeight(1);
      line(x - s * 2.8, y, x + s * 2.8, y);
      line(x, y - s * 2.8, x, y + s * 2.8);
      noStroke();
    }
  }

  blendMode(BLEND);
}

function drawVignette() {
  let ctx = drawingContext;
  ctx.save();

  let lg = ctx.createLinearGradient(0, 0, 0, height);
  lg.addColorStop(0, 'rgba(7,5,18,0.32)');
  lg.addColorStop(0.18, 'rgba(7,5,18,0)');
  lg.addColorStop(0.82, 'rgba(14,4,8,0)');
  lg.addColorStop(1, 'rgba(18,4,6,0.26)');
  ctx.fillStyle = lg;
  ctx.fillRect(0, 0, width, height);

  let rg = ctx.createRadialGradient(800, 960, 460, 800, 960, 1280);
  rg.addColorStop(0, 'rgba(0,0,0,0)');
  rg.addColorStop(1, 'rgba(6,3,12,0.36)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, width, height);

  ctx.restore();
}

