function drawRootSide(side, c) {
  push();
  if (side < 0) {
    translate(width, 0);
    scale(-1, 1);
  }

  noFill();
  for (let i = 0; i < 9; i++) {
    const sx = 270 + i * 43;
    const sy = 1548 + random(-12, 18);
    stroke(withAlpha(c, 92 - i * 5));
    strokeWeight(max(1.2, 5.4 - i * 0.42));
    bezier(
      sx, sy,
      sx + 35, 1635 + i * 5,
      500 + i * 18, 1660 + i * 18,
      620 + i * 20, 1760 + i * 20
    );
  }

  for (let i = 0; i < 5; i++) {
    const sx = 280 + i * 42;
    stroke(withAlpha(c, 48));
    strokeWeight(2.2);
    bezier(
      sx, 1555,
      sx - 30, 1650,
      210 - i * 22, 1710 + i * 25,
      95 + i * 16, 1850 + i * 18
    );
  }

  rootBranch(390, 1555, 116, 1.14, 6, c);
  rootBranch(315, 1560, 96, 1.88, 5, c);
  rootBranch(490, 1560, 92, 0.91, 5, c);

  pop();
}

function rootBranch(x, y, len, ang, depth, c) {
  if (depth <= 0 || y > 1985 || x < 20 || x > 1580) return;

  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len * 0.78;

  noFill();
  stroke(withAlpha(c, 25 + depth * 11));
  strokeWeight(max(0.65, depth * 0.72));
  bezier(
    x, y,
    x + cos(ang - 0.18) * len * 0.32,
    y + sin(ang - 0.18) * len * 0.26,
    x + cos(ang + 0.14) * len * 0.72,
    y + sin(ang + 0.14) * len * 0.56,
    x2, y2
  );

  rootBranch(
    x2,
    y2,
    len * random(0.64, 0.76),
    ang + random(-0.28, 0.28),
    depth - 1,
    c
  );

  if (depth > 2) {
    rootBranch(
      x2,
      y2,
      len * random(0.42, 0.57),
      ang + random(-0.72, 0.72),
      depth - 2,
      c
    );
  }
}

