  fill(base);
  bodyShape();

  fill(withAlpha(highlight, 23));
  beginShape();
  vertex(282, 1550);
  bezierVertex(282, 1280, 340, 1000, 470, 790);
  bezierVertex(500, 735, 525, 700, 548, 680);
  bezierVertex(500, 920, 475, 1240, 535, 1550);
  endShape(CLOSE);

  noFill();
  for (let i = 0; i <= 16; i++) {
    const t = i / 16;
    stroke(withAlpha(highlight, 38 + 20 * (1 - t)));
    strokeWeight(i % 4 === 0 ? 2.7 : 1.5);
    beginShape();
    vertex(265 + t * 345, 1565);
    bezierVertex(
      270 + t * 250, 1350,
      305 + t * 240, 1040,
