  rotate(0.18);

  fill(4, 10, 18, 60);
  ellipse(12, 15, 282, 322);

  fill(base);
  ellipse(0, 0, 280, 320);

  for (let i = 0; i < 18; i++) {
    const t = i / 17;
    fill(withAlpha(highlight, 3 + t * 2));
    ellipse(
      -15 + 25 * t,
      -10 + 5 * t,
      270 - 90 * t,
      310 - 100 * t
    );
  }

  noFill();
  stroke(withAlpha(highlight, 112));
  strokeWeight(3);
  arc(0, 0, 245, 285, -1.18, 1.12);
  stroke(withAlpha(highlight, 48));
  strokeWeight(1.4);
  arc(-4, 2, 213, 253, -1.12, 1.05);
