  armShape();

  noFill();
  stroke(withAlpha(highlight, 94));
  strokeWeight(2.2);
  bezier(500, 830, 565, 900, 625, 1040, 762, 1105);

  push();
  translate(764, 1110);
  rotate(0.24);
  noStroke();
  fill(armColor);
  ellipse(0, 0, 86, 43);
  pop();

  pop();
}

