function finishSurface() {
  for (let i = 0; i < 42000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.006, y * 0.006);

    if (random() < 0.52) {
      stroke(255, 239, 213, random(2, 8) * (0.5 + n));
    } else {
      stroke(0, 0, 0, random(2, 7) * (0.6 + n));
    }
    strokeWeight(random(0.45, 1.45));
    point(x, y);
  }

  for (let i = 0; i < 1200; i++) {
    const x = random(width);
    const y = random(height);
    stroke(248, 224, 190, random(2, 6));
