  for (let i = 0; i < 44; i++) {
    stroke(3, 8, 16, 1.8);
    strokeWeight(22);
    rect(
      i * 2.5,
      i * 2.5,
      width - i * 5,
      height - i * 5,
      70
    );
  }
}

let tipsL = [];
let tipsR = [];
let rootsL = [];
let rootsR = [];
let flowerWarm = [];
let flowerCool = [];
let crownRose;

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(1600, 2000);
  pixelDensity(1);

  flowerWarm = [
    color(244, 166, 112),
    color(239, 116, 111),
    color(255, 204, 151),
    color(222, 133, 150)
  ];
  flowerCool = [
    color(118, 205, 202),
    color(139, 181, 218),
    color(177, 153, 211),
    color(164, 224, 205)
  ];
  crownRose = color(255, 177, 157);

  paintSky();
  paintStars();

  softGlow(800, 310, 310, color(255, 202, 170), 52, 1.1);
  noStroke();
  fill(255, 237, 211, 225);
  circle(800, 310, 116);
  fill(255, 248, 226, 115);
  circle(782, 292, 72);

  softGlow(800, 1770, 400, color(238, 157, 100), 55, 1.25);

  growBranch(540, 1460, 150, HALF_PI - 0.04, 8, 1, true, 14);
  growBranch(1060, 1460, 150, HALF_PI + 0.04, 8, -1, true, 14);
  weaveRoots();

  paintHorizon();
  softGlow(800, 865, 465, color(225, 104, 119), 55, 0.85);

  growBranch(540, 1462, 245, -HALF_PI + 0.05, 8, 1, false, 18);
  growBranch(1060, 1462, 245, -HALF_PI - 0.05, 8, -1, false, 18);
  weaveCrown();

  paintPollen();
  paintGrain();
  paintVignette();

  noLoop();
}

function paintSky() {
  const top = color(10, 14, 34);
  const middle = color(31, 27, 58);
  const dusk = color(94, 52, 74);
  const soilTop = color(31, 23, 38);
  const bottom = color(9, 11, 24);

  for (let y = 0; y < height; y++) {
    let c;
    if (y < 1460) {
      const t = y / 1460;
      if (t < 0.62) {
        c = lerpColor(top, middle, t / 0.62);
      } else {
        c = lerpColor(middle, dusk, (t - 0.62) / 0.38);
      }
    } else {
      c = lerpColor(soilTop, bottom, (y - 1460) / 540);
    }
    stroke(c);
    line(0, y, width, y);
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 230; i++) {
    const x = random(width);
    const y = random(40, 1320);
    const fade = 1 - y / 1460;
    const s = random(0.6, 2.3);
    fill(255, 229, 211, random(18, 95) * fade);
    circle(x, y, s);
  }
}

function softGlow(x, y, r, c, steps, strength) {
  noStroke();
  for (let i = 0; i < steps; i++) {
    const t = i / (steps - 1);
    const rr = r * (1 - t * 0.94);
    fill(red(c), green(c), blue(c), strength * (0.25 + t * 0.75));
    circle(x, y, rr * 2);
  }
}

function growBranch(x, y, len, ang, depth, side, isRoot, w) {
  const n = noise(x * 0.004, y * 0.004, depth * 0.13) - 0.5;

  if (isRoot) {
    ang += -side * 0.035 + n * 0.16;
    if (y + sin(ang) * len > 1992) len *= 0.55;
  } else {
    ang += side * 0.035 + n * 0.12;
  }

  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  const bend = random(-0.22, 0.22) * len;
  const cx = (x + x2) * 0.5 + cos(ang + HALF_PI) * bend;
  const cy = (y + y2) * 0.5 + sin(ang + HALF_PI) * bend;

  const near = constrain(1 - abs(x2 - 800) / 620, 0, 1);
  let base;
  if (isRoot) {
    base = side === 1 ? color(186, 112, 80) : color(70, 137, 145);
  } else {
    base = side === 1 ? color(210, 133, 100) : color(92, 155, 167);
  }
  const cc = lerpColor(
    base,
    color(236, 173, 124),
    near * (isRoot ? 0.55 : 0.35)
  );

  noFill();
  stroke(red(cc), green(cc), blue(cc), isRoot ? 10 : 13);
  strokeWeight(w * 3.4 + 0.8);
  bezier(x, y, cx, cy, cx, cy, x2, y2);

  stroke(red(cc), green(cc), blue(cc), isRoot ? 88 : 145);
  strokeWeight(max(0.45, w));
  bezier(x, y, cx, cy, cx, cy, x2, y2);

  if (isRoot) {
    const node = { x: x2, y: y2 };
    if (side === 1) rootsL.push(node);
    else rootsR.push(node);
  }

  if (depth <= 0 || len < 7) {
    if (!isRoot) {
      const tip = { x: x2, y: y2 };
      if (side === 1) tipsL.push(tip);
      else tipsR.push(tip);
      blossom(x2, y2, side);
    }
    return;
  }

  const branches = depth > 3 && random() < 0.12 ? 3 : 2;

  for (let i = 0; i < branches; i++) {
    const dir = branches === 2 ? (i === 0 ? -1 : 1) : i - 1;
    let na = ang + dir * random(0.18, 0.48) + random(-0.09, 0.09);
    let nl = len * random(
      isRoot ? 0.66 : 0.68,
      isRoot ? 0.77 : 0.79
    );

    if (depth <= 6 && depth >= 3 && i === 0 && random() < 0.22) {
      na = isRoot
        ? HALF_PI - side * random(0.35, 0.75)
        : -HALF_PI + side * random(0.35, 0.72);
      nl *= 1.06;
    }

    growBranch(
      x2,
      y2,
      nl,
      na,
      depth - 1,
      side,
      isRoot,
      max(0.35, w * random(0.62, 0.72))
    );
  }
}

function blossom(x, y, side) {
  const near = constrain(1 - abs(x - 800) / 480, 0, 1);
  const base = side === 1 ? random(flowerWarm) : random(flowerCool);
  const c = lerpColor(base, crownRose, near * 0.8);
  const petals = 3 + floor(random(4));

  noStroke();
  for (let i = 0; i < petals; i++) {
    const px = x + random(-10, 10);
    const py = y + random(-10, 10);
    const s = random(3.5, 8.5) * (1 + near * 0.35);

    push();
    translate(px, py);
    rotate(random(TWO_PI));
    fill(red(c), green(c), blue(c), random(85, 175));
    ellipse(0, 0, s * 1.9, s);
    pop();
  }

  if (random() < 0.38) {
    fill(255, 232, 190, random(90, 180));
    circle(x, y, random(1.2, 3.2));
  }
}

function weaveCrown() {
  let made = 0;
  let attempts = 0;

  while (made < 120 && attempts < 3000) {
    attempts++;
    const a = random(tipsL);
    const b = random(tipsR);
    if (!a || !b) continue;
    if (a.y > 1240 || b.y > 1240) continue;
    if (b.x < a.x + 20) continue;

    const d = dist(a.x, a.y, b.x, b.y);
    if (d < 80 || d > 620) continue;

    const lift = random(30, 140) + d * 0.12;
    const c1x = lerp(a.x, b.x, 0.32);
    const c2x = lerp(a.x, b.x, 0.68);
    const c1y = a.y - lift;
    const c2y = b.y - lift;

    noFill();
    stroke(255, 196, 145, random(22, 70));
    strokeWeight(random(0.45, 1.25));
    bezier(a.x, a.y, c1x, c1y, c2x, c2y, b.x, b.y);

    if (random() < 0.7) {
      const t = random(0.35, 0.65);
      const px = bezierPoint(a.x, c1x, c2x, b.x, t);
      const py = bezierPoint(a.y, c1y, c2y, b.y, t);
      noStroke();
      fill(255, 184, 157, random(80, 170));
      circle(px, py, random(2, 6));
    }
    made++;
  }
}

function weaveRoots() {
  let made = 0;
  let attempts = 0;

  while (made < 190 && attempts < 5000) {
    attempts++;
    const a = random(rootsL);
    const b = random(rootsR);
    if (!a || !b) continue;
    if (a.y < 1490 || b.y < 1490 || b.x < a.x) continue;

    const d = dist(a.x, a.y, b.x, b.y);
    if (d < 40 || d > 560) continue;

    const sag = random(20, 110);
    const c1x = lerp(a.x, b.x, 0.3);
    const c2x = lerp(a.x, b.x, 0.7);
    const c1y = a.y + sag;
    const c2y = b.y + sag;

    noFill();
    stroke(244, 178, 112, random(20, 72));
    strokeWeight(random(0.4, 1.3));
    bezier(a.x, a.y, c1x, c1y, c2x, c2y, b.x, b.y);

    if (random() < 0.32) {
      const px = bezierPoint(a.x, c1x, c2x, b.x, 0.5);
      const py = bezierPoint(a.y, c1y, c2y, b.y, 0.5);
      noStroke();
      fill(255, 198, 127, random(45, 120));
      circle(px, py, random(1.5, 4.5));
    }
    made++;
  }
}

