function buildFigures() {
  const segments = [
    [515, 1370, 485, 1190, 520, 1030],
    [535, 955, 565, 875, 620, 815],
    [610, 770, 580, 720, 575, 655],
    [555, 520, 625, 435, 720, 440],
    [775, 443, 805, 485, 795, 545],
    [792, 580, 770, 607, 778, 632],
    [783, 650, 804, 665, 800, 681],
    [797, 695, 778, 695, 781, 710],
    [797, 721, 793, 737, 778, 739],
    [785, 767, 760, 787, 728, 785],
    [712, 817, 715, 848, 735, 884],
    [758, 950, 803, 1010, 807, 1115],
    [822, 1280, 775, 1420, 716, 1530],
    [675, 1575, 610, 1560, 575, 1510]
  ];

  leftPoly = [];
  let p = [575, 1510];

  for (const s of segments) {
    for (let j = 1; j <= 28; j++) {
      leftPoly.push(cubicPoint(p, s, j / 28));
    }
    p = [s[4], s[5]];
  }

  rightPoly = leftPoly.map(q => [1600 - q[0], q[1] + 35]);
}

function cubicPoint(p0, s, t) {
  const u = 1 - t;
  return [
    u * u * u * p0[0] +
      3 * u * u * t * s[0] +
      3 * u * t * t * s[2] +
      t * t * t * s[4],
    u * u * u * p0[1] +
      3 * u * u * t * s[1] +
      3 * u * t * t * s[3] +
      t * t * t * s[5]
  ];
}

function drawPoly(poly) {
  beginShape();
  for (const p of poly) vertex(p[0], p[1]);
  endShape(CLOSE);
}

function insidePoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0];
    const yi = poly[i][1];
    const xj = poly[j][0];
    const yj = poly[j][1];
    const crosses =
      (yi > y) !== (yj > y) &&
      x < ((xj - xi) * (y - yi)) / (yj - yi) + xi;
    if (crosses) inside = !inside;
  }
  return inside;
}

function paintRoots() {
  glow(800, 1650, 460, [76, 126, 117], 0.08);

  for (let side = 0; side < 2; side++) {
