      if (golden) {
        stroke(222, 181, 112, random(24, 56));
      } else if (mirrored) {
        stroke(193, 105, 111, random(16, 48));
      } else {
        stroke(80, 151, 148, random(17, 50));
      }

      strokeWeight(golden ? random(0.8, 1.7) : random(0.45, 1.25));
      noFill();
      bezier(
        sx,
        sy,
        sx + random(-190, 190),
        random(1600, 1720),
        ex + random(-250, 250),
        random(1660, 1840),
        ex,
        ey
      );

      if (i % 6 === 0) {
        noStroke();
        fill(
          golden ? 229 : mirrored ? 184 : 100,
          golden ? 193 : mirrored ? 125 : 161,
          golden ? 132 : mirrored ? 125 : 151,
          random(20, 55)
        );
        circle(ex, ey, random(1.5, 4.5));
      }
    }
  }

  for (let i = 0; i < 24; i++) {
    const offset = (i - 12) * 3.1;
    stroke(218, 178, 112, random(12, 34));
    strokeWeight(random(0.45, 1.15));
    noFill();
    bezier(
      640 + offset,
      1500,
      560 + offset * 2,
      1650,
      1030 - offset * 2,
      1730,
      790 + offset * 0.4,
      1940
    );
  }
}

