function paintFigure(poly, base, accent, rim) {
  for (let k = 0; k < 9; k++) {
    push();
    translate(random(-2.5, 2.5), random(-2.5, 2.5));
    noFill();
    stroke(accent[0], accent[1], accent[2], 7);
    strokeWeight(17 - k * 1.5);
    drawPoly(poly);
    pop();
  }

  noStroke();
  fill(base[0], base[1], base[2], 238);
  drawPoly(poly);

  let minX = width;
  let maxX = 0;
  let minY = height;
  let maxY = 0;
  for (const p of poly) {
    minX = min(minX, p[0]);
    maxX = max(maxX, p[0]);
    minY = min(minY, p[1]);
    maxY = max(maxY, p[1]);
  }

  let placed = 0;
  let attempts = 0;
  while (placed < 4700 && attempts < 40000) {
    attempts++;
    const x = random(minX, maxX);
    const y = random(minY, maxY);
    if (!insidePoly(x, y, poly)) continue;

    const n = noise(x * 0.004, y * 0.004);
    const mixAmt = random(0.08, 0.8) * (0.5 + n * 0.5);
    const r = lerp(base[0], accent[0], mixAmt);
    const g = lerp(base[1], accent[1], mixAmt);
    const b = lerp(base[2], accent[2], mixAmt);
    const ang = -HALF_PI + (n - 0.5) * 1.5;
    const len = random(2, 10);

    stroke(r, g, b, random(18, 68));
    strokeWeight(random(0.45, 1.45));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    placed++;
  }

  placed = 0;
  attempts = 0;
  while (placed < 260 && attempts < 7000) {
    attempts++;
    const x = random(minX, maxX);
    const y = random(minY, maxY);
    if (!insidePoly(x, y, poly)) continue;

    noStroke();
    fill(rim[0], rim[1], rim[2], random(15, 65));
    circle(x, y, random(0.8, 2.8));
    placed++;
  }

  noFill();
  stroke(accent[0], accent[1], accent[2], 65);
  strokeWeight(3.2);
  drawPoly(poly);
  stroke(rim[0], rim[1], rim[2], 72);
  strokeWeight(1.15);
  drawPoly(poly);
}

