function ribbon(p0, c1, c2, p3, col) {
  noFill();
  stroke(col[0], col[1], col[2], 10);
  strokeWeight(72);
  bezier(
    p0[0], p0[1],
    c1[0], c1[1],
    c2[0], c2[1],
    p3[0], p3[1]
  );

  for (let i = 0; i < 58; i++) {
    const off = map(i, 0, 57, -34, 34) + random(-2, 2);
    const golden = i % 13 === 0;
    stroke(
      golden ? 237 : col[0],
      golden ? 202 : col[1],
      golden ? 151 : col[2],
      golden ? random(30, 62) : random(18, 55)
    );
    strokeWeight(random(0.55, 1.65));
    bezier(
      p0[0],
      p0[1] + off * 0.22,
      c1[0],
      c1[1] + off,
      c2[0],
      c2[1] + off,
      p3[0],
      p3[1] + off * 0.22
    );
  }
}

