function growRoot(x, y, len, ang, w, depth, c) {
  if (
    depth <= 0 ||
    len < 10 ||
    y > 1995 ||
    x < -30 ||
    x > width + 30
  ) {
    return;
  }

  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  let bend = random(-0.25, 0.25) * len;
  let nx = -sin(ang);
  let ny = cos(ang);

  stroke(red(c), green(c), blue(c), map(depth, 0, 5, 65, 155));
  strokeWeight(max(0.7, w));
  noFill();
  bezier(
    x, y,
    x + cos(ang) * len * 0.35 + nx * bend,
    y + sin(ang) * len * 0.35 + ny * bend,
    x + cos(ang) * len * 0.75 - nx * bend * 0.35,
    y + sin(ang) * len * 0.75 - ny * bend * 0.35,
    x2, y2
  );

  let a1 = constrain(ang + random(-0.28, 0.28), 0.42, 2.72);
  growRoot(
    x2, y2,
    len * random(0.61, 0.75),
    a1,
    w * 0.64,
    depth - 1,
    c
  );

  if (random() < 0.9) {
    let sign = random() < 0.5 ? -1 : 1;
    let a2 = constrain(
      ang + sign * random(0.38, 0.72),
      0.42,
      2.72
    );
    growRoot(
      x2, y2,
      len * random(0.48, 0.66),
      a2,
      w * 0.53,
      depth - 1,
      c
    );
  }
}

