function addBarkMarks(side) {
  let p0, p1, p2, p3, c;

  if (side < 0) {
    p0 = [480, 1470];
    p1 = [425, 1200];
    p2 = [665, 1030];
    p3 = [620, 720];
    c = leftLight;
  } else {
    p0 = [1120, 1470];
    p1 = [1175, 1200];
    p2 = [935, 1030];
    p3 = [980, 720];
    c = rightLight;
  }

  for (let i = 0; i < 72; i++) {
    let t = random(0.04, 0.96);
    let x = bezierPoint(p0[0], p1[0], p2[0], p3[0], t);
    let y = bezierPoint(p0[1], p1[1], p2[1], p3[1], t);
    let trunkWidth = lerp(145, 38, t);
    let offset = random(-trunkWidth * 0.28, trunkWidth * 0.28);

    stroke(red(c), green(c), blue(c), random(25, 65));
    strokeWeight(random(1, 3));
    line(
      x + offset,
      y,
      x + offset + random(-4, 4),
      y - random(8, 27)
    );
  }
}

function growBranch(x, y, len, ang, w, depth, side) {
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  let bend = random(-0.18, 0.18) * len;
  let nx = -sin(ang);
  let ny = cos(ang);

  let c1x = x + cos(ang) * len * 0.32 + nx * bend;
  let c1y = y + sin(ang) * len * 0.32 + ny * bend;
  let c2x = x + cos(ang) * len * 0.73 - nx * bend * 0.35;
  let c2y = y + sin(ang) * len * 0.73 - ny * bend * 0.35;

  let bark = side < 0 ? leftBark : rightBark;
  let light = side < 0 ? leftLight : rightLight;

  noFill();
  stroke(red(bark), green(bark), blue(bark), 245);
  strokeWeight(max(0.65, w));
  bezier(x, y, c1x, c1y, c2x, c2y, x2, y2);

  if (w > 9) {
    stroke(red(light), green(light), blue(light), 55);
    strokeWeight(max(0.5, w * 0.16));
    bezier(x, y, c1x, c1y, c2x, c2y, x2, y2);
  }

  if (depth <= 0 || len < 10) {
    leafCluster(x2, y2, ang, side, 0);
    return;
  }

  if (depth === 1) {
    leafCluster(x2, y2, ang, side, 2);
  }

  let n = noise(x * 0.002, y * 0.002, depth * 0.07) - 0.5;
  let nextAngle = ang + n * 0.25 + random(-0.13, 0.13);

  growBranch(
    x2, y2,
    len * random(0.68, 0.77),
    nextAngle,
    w * 0.69,
    depth - 1,
    side
  );

  let sign = random() < 0.5 ? -1 : 1;
  let splitAngle = ang + sign * random(0.48, 0.88);

  growBranch(
    x2, y2,
    len * random(0.56, 0.69),
    splitAngle,
    w * 0.58,
    depth - 1,
    side
  );
}

function leafCluster(x, y, ang, side, amount) {
  let count = amount > 0 ? amount : floor(random(3, 7));

  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let d = random(4, 34);
    let px = x + cos(a) * d;
    let py = y + sin(a) * d;

    let meeting = px > 660 && px < 940 && py < 1080;
    let useGold = meeting ? random() < 0.58 : random() < 0.025;

    let palette;
    if (useGold) {
      palette = goldLeaves;
    } else {
      palette = side < 0 ? leftLeaves : rightLeaves;
    }

    let base = palette[floor(random(palette.length))];
    let c = color(
      red(base),
      green(base),
      blue(base),
      random(175, 238)
    );

    drawLeaf(
      px,
      py,
      random(13, 27),
      ang + random(-1.5, 1.5),
      c
    );
  }
}

function drawLeaf(x, y, s, a, c) {
  push();
  translate(x, y);
  rotate(a);
  noStroke();
  fill(c);
  beginShape();
  vertex(-s * 0.55, 0);
  bezierVertex(
    -s * 0.15, -s * 0.42,
    s * 0.45, -s * 0.32,
    s * 0.65, 0
  );
  bezierVertex(
    s * 0.25, s * 0.38,
    -s * 0.25, s * 0.35,
    -s * 0.55, 0
  );
  endShape(CLOSE);
  pop();
}

