function taperedBezier(
  x0, y0, x1, y1, x2, y2, x3, y3,
  c, w0, w1, a = 255
) {
  let px = x0;
  let py = y0;

  for (let i = 1; i <= 72; i++) {
    let t = i / 72;
    let x = bezierPoint(x0, x1, x2, x3, t);
    let y = bezierPoint(y0, y1, y2, y3, t);

    stroke(red(c), green(c), blue(c), a);
    strokeWeight(lerp(w0, w1, t));
    line(px, py, x, y);

    px = x;
    py = y;
  }
}

