function samplePath(segments, steps) {
  const pts = [];

  for (let s = 0; s < segments.length; s++) {
    const g = segments[s];

    for (let k = 0; k < steps; k++) {
      const t = k / steps;
      const x = cubicValue(g[0], g[2], g[4], g[6], t);
      const y = cubicValue(g[1], g[3], g[5], g[7], t);
      const dx = cubicDerivative(g[0], g[2], g[4], g[6], t);
      const dy = cubicDerivative(g[1], g[3], g[5], g[7], t);
      const m = max(0.0001, sqrt(dx * dx + dy * dy));

      pts.push({
        x, y,
        nx: -dy / m,
        ny: dx / m,
        u: (s + t) / segments.length
      });
    }
  }

  const g = segments[segments.length - 1];
  const dx = g[6] - g[4];
  const dy = g[7] - g[5];
  const m = max(0.0001, sqrt(dx * dx + dy * dy));
  pts.push({
    x: g[6],
    y: g[7],
    nx: -dy / m,
    ny: dx / m,
    u: 1
  });

  return pts;
}

function cubicValue(a, b, c, d, t) {
  const mt = 1 - t;
  return mt * mt * mt * a +
    3 * mt * mt * t * b +
    3 * mt * t * t * c +
    t * t * t * d;
}

function cubicDerivative(a, b, c, d, t) {
  const mt = 1 - t;
  return 3 * mt * mt * (b - a) +
    6 * mt * t * (c - b) +
    3 * t * t * (d - c);
}

function ribbonWidth(u, phase) {
  const envelope = pow(max(0, sin(PI * u)), 0.64);
  const breathing = 0.93 + 0.09 * sin(u * PI * 3 + phase);
  const taper = 1 - 0.22 * smooth01((u - 0.66) / 0.34);
  return (8 + 218 * envelope * breathing) * taper;
}

function smooth01(v) {
  v = constrain(v, 0, 1);
  return v * v * (3 - 2 * v);
}

function traceRibbon(pts, phase, qA, qB, dx = 0, dy = 0, rough = 0) {
  beginShape();

  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    const w = ribbonWidth(p.u, phase);
    const jitter = (noise(phase * 10 + p.u * 9, qA * 13 + 4) - 0.5) * rough;
    const off = qA * w + jitter;
    vertex(p.x + p.nx * off + dx, p.y + p.ny * off + dy);
  }

  for (let i = pts.length - 1; i >= 0; i--) {
    const p = pts[i];
    const w = ribbonWidth(p.u, phase);
    const jitter = (noise(phase * 10 + p.u * 9, qB * 13 + 17) - 0.5) * rough;
    const off = qB * w + jitter;
    vertex(p.x + p.nx * off + dx, p.y + p.ny * off + dy);
  }

  endShape(CLOSE);
}

function paintRibbon(pts, phase, pal, innerSide) {
  noStroke();

  for (let k = 4; k >= 0; k--) {
    fill(4, 7, 20, 10);
    traceRibbon(pts, phase, -0.55, 0.55, 12 + k * 3, 18 + k * 4, 5);
  }

  fill(5, 8, 22, 70);
  traceRibbon(pts, phase, -0.54, 0.54, 12, 18, 4);

  fill(pal.base);
  traceRibbon(pts, phase, -0.53, 0.53, 0, 0, 3.5);

  const outerA = innerSide === 1 ? -0.51 : 0.12;
  const outerB = innerSide === 1 ? -0.12 : 0.51;
  const innerA = innerSide === 1 ? 0.08 : -0.50;
  const innerB = innerSide === 1 ? 0.50 : -0.08;

  fillA(pal.dark, 52);
  traceRibbon(pts, phase, outerA, outerB, 0, 0, 2);

  fillA(pal.light, 34);
  traceRibbon(pts, phase, innerA, innerB, 0, 0, 2);

  for (let j = 0; j < 58; j++) {
    const q = map(j, 0, 57, -0.485, 0.485);

    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i];
      const b = pts[i + 1];
      const wa = ribbonWidth(a.u, phase);
      const wb = ribbonWidth(b.u, phase);
      const ja = (noise(a.u * 14 + phase, q * 21 + 8) - 0.5) * 3.2;
      const jb = (noise(b.u * 14 + phase, q * 21 + 8) - 0.5) * 3.2;
      const oa = q * wa + ja;
      const ob = q * wb + jb;
      const c = ribbonInk(pal, q, a.u, innerSide);

      stroke(red(c), green(c), blue(c), 58);
      strokeWeight(5.4);
      line(
        a.x + a.nx * oa,
        a.y + a.ny * oa,
        b.x + b.nx * ob,
        b.y + b.ny * ob
      );
    }
  }

  for (let k = 0; k < 6; k++) {
    drawRim(
      pts,
      phase,
      innerSide * (0.10 + k * 0.065),
      pal.light,
      25,
      1.1
    );
  }

  drawRim(pts, phase, -innerSide * 0.50, pal.dark, 95, 2.2);
  drawRim(pts, phase, innerSide * 0.495, pal.rim, 115, 2.4);
}

function ribbonInk(pal, q, u, innerSide) {
  const lit = constrain(q * innerSide + 0.5, 0, 1);
  let c = lerpColor(pal.dark, pal.light, pow(lit, 0.75));
  c = lerpColor(pal.base, c, 0.62);
  const tide = 0.5 + 0.5 * sin(u * 8 + lit * 2);
  return lerpColor(c, pal.light, 0.07 * tide);
}

function drawRim(pts, phase, q, col, alpha, weight) {
  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i];
    const b = pts[i + 1];
    const oa = q * ribbonWidth(a.u, phase);
    const ob = q * ribbonWidth(b.u, phase);
    const fade = pow(max(0, sin(PI * a.u)), 0.3);

    strokeA(col, alpha * fade);
    strokeWeight(weight);
    line(
      a.x + a.nx * oa,
      a.y + a.ny * oa,
      b.x + b.nx * ob,
      b.y + b.ny * ob
    );
  }
}

function paintReach() {
  noFill();

  for (let j = 0; j < 3; j++) {
    stroke(240, 194, 130, 32 - j * 6);
    strokeWeight(1.2);
    bezier(
      515 + j * 4, 1220 - j * 8,
      620, 1185 - j * 12,
      665, 1110,
      718, 1080 + j * 12
    );
    bezier(
      1085 - j * 4, 1220 - j * 8,
      980, 1185 - j * 12,
      935, 1110,
      882, 1080 + j * 12
    );
  }
}

function paintSharedLight() {
  noStroke();

  for (let r = 360; r > 24; r -= 8) {
    const a = map(r, 360, 24, 0.15, 2.4);
    fill(248, 178, 100, a);
    ellipse(800, 1050, r * 1.12, r * 1.22);
  }

  push();
  translate(800, 1050);
  rotate(-0.18);
  noFill();
  stroke(242, 196, 126, 52);
  strokeWeight(1.5);
  arc(0, 0, 340, 390, 0.15, 2.25);
  arc(0, 0, 390, 450, 3.15, 5.45);
  pop();

