/* ---------- 天空 ---------- */
function sky() {
  noStroke();
  for (let y = 0; y <= HORIZON + 8; y += 4) {
    const t = min(y / HORIZON, 1);
    const c = ramp(t);
    fill(c[0], c[1], c[2]);
    rect(0, y - 2, W, 5);
  }
}
function ramp(t) {
  for (let i = 1; i < SKY.length; i++) {
    if (t <= SKY[i][0]) {
      const a = SKY[i - 1], b = SKY[i];
      const k = (t - a[0]) / (b[0] - a[0]);
      return [
        lerp(a[1][0], b[1][0], k),
        lerp(a[1][1], b[1][1], k),
        lerp(a[1][2], b[1][2], k),
      ];
    }
  }
  return SKY[SKY.length - 1][1];
}

