/* ---------- 双干缠绕 ---------- */
function trunkPoint(side, t) {
  const d = 480 * pow(1 - t, 1.6) + 26;          // 两干中轴间距
  const R = 36 + 120 * pow(sin(PI * t), 0.75);   // 舞动的幅度
  const w = 15.7 * t;                            // 约 2.5 个周期
  let sway = R * sin(w);
  const inward = (side < 0 && sway > 0) || (side > 0 && sway < 0);
  if (!inward) sway *= 0.78;                     // 向内相拥时摆幅更大
  const x = 800 + side * d / 2 - side * sway + side * 34 * (noise(t * 5.2 + side * 7.7) - 0.5);
  const y = lerp(1748, 776, t);
  const r = lerp(27, 5.5, pow(t, 0.75)) * (0.85 + 0.3 * noise(t * 6.5 + side * 3.1));
  return { x: x, y: y, r: r };
}
function trunkColor(side, t) {
  const a = side < 0 ? [43, 25, 35] : [52, 28, 34];
  const b = side < 0 ? [108, 50, 72] : [118, 55, 70];
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}
function trunks() {
  noStroke();
  for (const side of [-1, 1]) {
    for (let i = 0; i <= 300; i++) {
      const t = i / 300;
      const p = trunkPoint(side, t);
      const c = trunkColor(side, t);
      fill(c[0], c[1], c[2]);
      circle(p.x, p.y, p.r * 2);
      if (side < 0 && i % 6 === 0) {  // 受月一侧的微光
        fill(118, 66, 84, 46);
        circle(p.x - p.r * 0.42, p.y, p.r * 1.05);
      }
    }
  }
  // 顶端融合为一
  for (let i = 0; i <= 26; i++) {
    const t = i / 26;
    const y = lerp(778, 700, t);
    const x = 800 + 7 * noise(t * 3.3);
    fill(112, 52, 73);
    circle(x, y, lerp(7.5, 3.2, t) * 2);
  }
  roots();
}
function roots() {
  noFill();
  stroke(43, 25, 35);
  strokeCap(ROUND);
  strokeWeight(17); bezier(562, 1750, 515, 1754, 462, 1764, 414, 1782);
  strokeWeight(11); bezier(560, 1754, 534, 1762, 512, 1778, 496, 1794);
  strokeWeight(15); bezier(556, 1752, 600, 1758, 652, 1768, 700, 1786);
  strokeWeight(17); bezier(1038, 1750, 1085, 1754, 1138, 1764, 1186, 1782);
  strokeWeight(11); bezier(1040, 1754, 1066, 1762, 1088, 1778, 1104, 1794);
  strokeWeight(15); bezier(1044, 1752, 1000, 1758, 948, 1768, 900, 1786);
  noStroke();
}

