function flowerColor(x, y) {
  const lt = constrain(1 - dist(x, y, 460, 330) / 1050, 0, 1); // 靠月一侧更亮
  const w = random();
  let r, g, b;
  if (w < 0.40)      { r = 243; g = 174; b = 192; }
  else if (w < 0.70) { r = 249; g = 207; b = 218; }
  else if (w < 0.90) { r = 252; g = 235; b = 238; }
  else               { r = 226; g = 118; b = 152; }
  return [lerp(r, 255, lt * 0.5), lerp(g, 245, lt * 0.5), lerp(b, 224, lt * 0.5)];
}
function bloom(x, y, s) {
  noStroke();
  const n = floor(12 + random(12));
  for (let i = 0; i < n; i++) {
    const a = random(TWO_PI);
    const dd = sqrt(random(1)) * 30 * s;
    const fx = x + cos(a) * dd;
    const fy = y + sin(a) * dd * 0.82;
    const r = (3.4 + random(4)) * s;
    const c = flowerColor(fx, fy);
    fill(c[0], c[1], c[2], 190 + random(65));
    circle(fx, fy, r * 2);
    if (r > 4.6 && random() < 0.55) {
