}
function branch(x, y, ang, len, wid, depth) {
  const bend = (noise(x * 0.012, y * 0.012) - 0.5) * 0.6;
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  const mx = (x + x2) / 2 + cos(ang + HALF_PI) * len * bend;
  const my = (y + y2) / 2 + sin(ang + HALF_PI) * len * bend;
  noFill();
  stroke(56, 30, 46, 210);
  strokeWeight(wid);
  bezier(x, y, mx, my, mx, my, x2, y2);
  if (depth <= 0) {
    bloom(x2, y2, 0.7 + random(0.7));
    return;
  }
  const n = random() < 0.34 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    const spread = 0.5 + random(0.38);
    const a = ang + (i - (n - 1) / 2) * spread + (random() - 0.5) * 0.22;
    branch(x2, y2, a, len * (0.68 + random(0.14)), wid * 0.62, depth - 1);
  }
}
function branchSystem() {
  const start = [
    [-2.72, 210], [-2.34, 225], [-1.95, 235], [-1.58, 240],
    [-1.22, 238], [-0.86, 232], [-0.52, 222], [-0.18, 205],
