// 《根在深处相遇》 —— 夜色中两棵彼此倾向的树，根系在土壤深处汇成一团光
let W = 1600, H = 2000;
let horizonY = 1250;
let gLev = [];       // 地面起伏
let rootSegs = [];   // 根系线段
let flowers = [];    // 满树光花
let CORE_X = 800, CORE_Y = 1625;
let skyA, skyB, skyC, soilTop, soilDeep;

// 花的调色板（暖橙金为主，点缀珊瑚）
const FLOW = [
  [255, 192, 122, 40],
  [255, 154,  94, 25],
  [255, 224, 174, 15],
  [255, 141, 122, 12],
  [255, 143, 156,  8]
];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  strokeCap(ROUND);

  skyA = color(6, 10, 24);
  skyB = color(19, 31, 58);
  skyC = color(44, 56, 84);
  soilTop = color(56, 40, 27);
  soilDeep = color(10, 6, 4);

  for (let x = 0; x <= W; x += 8) {
    gLev.push(horizonY - 22 + noise(x * 0.0028 + 7.7) * 44);
  }

  paint();
}

function gY(x) {
  let i = floor(constrain(x, 0, W) / 8);
  return gLev[i];
}

function paint() {
  drawSky();
  drawStars();
  drawMoon();
  drawArch();
  drawSoil();
  drawStrata();
  growRoots();
  drawCoreGlow();
  renderRoots();
  drawRings();
  drawSurface();
  flowers = [];
  drawTree(470, gY(470) - 2, 1);
  drawTree(1130, gY(1130) - 2, -1);
  renderFlowers();
  drawMotes();
  drawBirds();
  vignette();
}

// ---------- 柔光 ----------
function softGlow(x, y, r, c, a, layers) {
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let al = a * pow(1 - t, 2.0);
    fill(red(c), green(c), blue(c), al);
    circle(x, y, 2 * r * t);
  }
}

// ---------- 天空 ----------
function drawSky() {
  noStroke();
  for (let y = 0; y <= 1280; y += 4) {
    let t = y / 1280;
