// ---------- 根系 ----------
function angDiff(a, b) {
  let d = a - b;
  while (d > PI) d -= TWO_PI;
  while (d < -PI) d += TWO_PI;
  return d;
}

function growRoots() {
  rootSegs = [];
  let lx = 470, rx = 1130;
  let ly = gY(lx) + 6, ry = gY(rx) + 6;
  rootBranch(lx, ly, HALF_PI - 0.30, 112, 0, 7);
  rootBranch(lx, ly, HALF_PI - 0.85,  80, 0, 6);
  rootBranch(lx, ly, HALF_PI + 0.20,  86, 0, 6);
  rootBranch(rx, ry, HALF_PI + 0.30, 112, 0, 7);
  rootBranch(rx, ry, HALF_PI + 0.85,  80, 0, 6);
  rootBranch(rx, ry, HALF_PI - 0.20,  86, 0, 6);
}

function rootBranch(x, y, ang, len, depth, maxDepth) {
  if (depth >= maxDepth || len < 4) return;
  // 所有根都被深处那团光轻轻牵引
  let ta = atan2(CORE_Y - y, CORE_X - x);
  ang += angDiff(ta, ang) * 0.09;
  let dev = constrain(angDiff(ang, HALF_PI), -1.25, 1.25);
  ang = HALF_PI + dev;
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  rootSegs.push({ x1: x, y1: y, x2: x2, y2: y2, w: map(depth, 0, 7, 13, 0.9), d: depth });
  let n = depth < 2 ? 3 : (random() < 0.3 ? 3 : 2);
  for (let i = 0; i < n; i++) {
    let dir = i === 0 ? -1 : (i === 1 ? 1 : (random() < 0.5 ? -1 : 1));
    let spread = random(0.22, 0.55);
    let na = ang + dir * spread + random(-0.12, 0.12);
    rootBranch(x2, y2, na, len * random(0.74, 0.86), depth + 1, maxDepth);
  }
}

function drawCoreGlow() {
  blendMode(ADD);
  softGlow(CORE_X, CORE_Y, 320, color(255, 168, 92), 60, 40);
  softGlow(CORE_X, CORE_Y, 150, color(255, 214, 150), 85, 28);
  blendMode(BLEND);
}

function renderRoots() {
  blendMode(ADD);
  for (let s of rootSegs) {
    stroke(255, 186, 120, 11);
    strokeWeight(s.w * 3.4);
    line(s.x1, s.y1, s.x2, s.y2);
  }
  for (let s of rootSegs) {
    let a = map(s.d, 0, 7, 220, 75);
    stroke(240, 212, 168, a);
    strokeWeight(s.w);
    line(s.x1, s.y1, s.x2, s.y2);
  }
  blendMode(BLEND);
}

// 深处那两枚相扣的环
function drawRings() {
  ring(782, 1618, 62, 46, -0.55, color(255, 214, 158), 225);
  ring(820, 1632, 62, 46,  0.55, color(255, 156, 126), 225);
  blendMode(ADD);
  softGlow(CORE_X, CORE_Y, 58, color(255, 244, 214), 130, 16);
  blendMode(BLEND);
}

function ring(x, y, rx, ry, rot, c, a) {
  push();
  translate(x, y);
  rotate(rot);
  noFill();
  blendMode(ADD);
  stroke(red(c), green(c), blue(c), 42);
  strokeWeight(10);
  ellipse(0, 0, rx * 2, ry * 2);
  blendMode(BLEND);
  stroke(red(c), green(c), blue(c), a);
  strokeWeight(3.6);
  ellipse(0, 0, rx * 2, ry * 2);
  pop();
}

// ---------- 地表 ----------
function drawSurface() {
  noFill();
  stroke(214, 200, 176, 40);
  strokeWeight(1.8);
  beginShape();
  for (let i = 0; i < gLev.length; i++) vertex(i * 8, gLev[i]);
  endShape();
  stroke(255, 236, 200, 55); // 月亮一侧的地表更亮
  beginShape();
  for (let x = 980; x <= W; x += 8) vertex(x, gY(x));
  endShape();
  // 草
  noFill();
  for (let i = 0; i < 130; i++) {
    let x = random(15, W - 15);
    let y = gY(x) + random(0, 7);
    let h = random(14, 48);
    let bend = random(-12, 12);
    stroke(8, 13, 22, 230);
    strokeWeight(random(1.4, 2.6));
    beginShape();
    vertex(x, y);
    quadraticVertex(x + bend * 0.6, y - h * 0.55, x + bend, y - h);
    endShape();
  }
  // 地面附近的萤光
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 14; i++) {
    let x = random(120, W - 120);
    let y = random(1140, 1235);
    softGlow(x, y, random(9, 20), color(255, 210, 150), 160, 14);
    fill(255, 240, 205, 220);
    circle(x, y, 3);
  }
  blendMode(BLEND);
}

// ---------- 树 ----------
function drawTree(bx, by, lean) {
  blendMode(ADD);
  softGlow(bx + lean * 70, by - 350, 470, color(255, 148, 82), 26, 36);
  softGlow(bx + lean * 70, by - 350, 235, color(255, 186, 116), 20, 22);
  blendMode(BLEND);
  noFill();
  stroke(24, 33, 52);
  branch(bx, by, -HALF_PI + lean * 0.13, 150, 0, 10, lean, bx - 390, bx + 390);
}

function branch(x, y, ang, len, depth, maxDepth, lean, minX, maxX) {
  // 保持向上生长的姿态
  let dev = constrain(angDiff(ang, -HALF_PI), -1.72, 1.72);
  ang = -HALF_PI + dev;
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  // 软性拉回各自的领域，把中缝留给彼此
  if (x2 < minX) ang += 0.3;
  else if (x2 > maxX) ang -= 0.3;
  x2 = x + cos(ang) * len;
  y2 = y + sin(ang) * len;
  strokeWeight(map(depth, 0, maxDepth, 34, 1.1));
  line(x, y, x2, y2);
  if (depth >= 6 && random() < 0.45) flowers.push(makeFlower(x2, y2, depth));
  if (depth >= maxDepth) {
    flowers.push(makeFlower(x2, y2, depth));
    if (random() < 0.6) flowers.push(makeFlower(x2 + random(-18, 18), y2 + random(-18, 18), depth));
    return;
  }
  let n = depth < 3 ? 2 : (random() < 0.22 ? 3 : 2);
  let decay = depth < 4 ? 0.85 : 0.80;
  for (let i = 0; i < n; i++) {
    let dir = i === 0 ? -1 : (i === 1 ? 1 : (random() < 0.5 ? -1 : 1));
    let spread = random(0.16, 0.42) + depth * 0.012;
    let na = ang + dir * spread + random(-0.09, 0.09) + lean * 0.028;
    branch(x2, y2, na, len * decay * random(0.94, 1.04), depth + 1, maxDepth, lean, minX, maxX);
  }
}

function makeFlower(x, y, depth) {
  let t = random(100);
  let c;
  if (t < 40) c = FLOW[0];
  else if (t < 65) c = FLOW[1];
  else if (t < 80) c = FLOW[2];
  else if (t < 92) c = FLOW[3];
  else c = FLOW[4];
  let r = random(3.5, 12) * (depth >= 10 ? 1.1 : 0.8);
  return { x: x + random(-12, 12), y: y + random(-12, 12), r: r, c: c, a: random(110, 215) };
}

function renderFlowers() {
  blendMode(ADD);
  noStroke();
  for (let f of flowers) {
    let c = f.c;
    fill(c[0], c[1], c[2], f.a * 0.16);
    circle(f.x, f.y, f.r * 3.6);
    fill(c[0], c[1], c[2], f.a);
    circle(f.x, f.y, f.r);
  }
  blendMode(BLEND);
}

// ---------- 两树之间交换的光 ----------
function drawMotes() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 44; i++) {
    let fromLeft = random() < 0.5;
    let x, y;
    if (fromLeft) { x = random(640, 860); y = random(470, 1120); }
    else { x = random(740, 960); y = random(470, 1120); }
    let dir = fromLeft ? 1 : -1;
    for (let j = 7; j >= 1; j--) {
      let px = x - dir * j * 6;
      let py = y - j * 2.4;
      fill(255, 202, 140, 120 * (1 - j / 8));
      circle(px, py, 7.5 - j * 0.7);
    }
    fill(255, 234, 190, 210);
    circle(x, y, 4.6);
  }
  for (let i = 0; i < 34; i++) {
    fill(255, 220, 170, random(25, 80));
    circle(random(640, 960), random(430, 1180), random(1.5, 3.5));
  }
  blendMode(BLEND);
}

// ---------- 相向而飞的两只鸟 ----------
function drawBirds() {
  blendMode(ADD);
  softGlow(800, 520, 170, color(255, 220, 170), 16, 20);
  blendMode(BLEND);
  bird(695, 530, 56, 1, 0.55);
  bird(908, 500, 48, -1, 0.28);
}

function bird(x, y, s, dir, lift) {
  noFill();
  blendMode(ADD);
  stroke(255, 226, 180, 55);
  strokeWeight(9);
  wings(x, y, s, dir, lift);
  blendMode(BLEND);
  stroke(246, 232, 202, 235);
  strokeWeight(3);
  wings(x, y, s, dir, lift);
}

function wings(x, y, s, dir, lift) {
  noFill();
  beginShape();
  vertex(x - dir * s * 0.55, y + lift * s * 0.30);
  quadraticVertex(x - dir * s * 0.25, y - s * 0.10, x, y - s * 0.02);
  endShape();
  beginShape();
  vertex(x + dir * s * 0.55, y - lift * s * 0.34);
  quadraticVertex(x + dir * s * 0.25, y - s * 0.22, x, y - s * 0.02);
  endShape();
}

// ---------- 暗角 ----------
function vignette() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 42; i++) {
    fill(4, 6, 14, 4);
    rect(0, i * 3, W, 3.2);
    rect(0, H - (i + 1) * 3, W, 3.2);
    rect(i * 3, 0, 3.2, H);
    rect(W - (i + 1) * 3, 0, 3.2, H);
  }
}

// 相触之前：地上将触未触，地下早已相拥。

