/* ---------- 天空 ---------- */

function skyColor(f) {
  f = constrain(f, 0, 1);
  for (let i = 1; i < SKY_STOPS.length; i++) {
    if (f <= SKY_STOPS[i][0]) {
      const a = SKY_STOPS[i - 1], b = SKY_STOPS[i];
      const t = (f - a[0]) / (b[0] - a[0]);
      return lerpColor(color(a[1]), color(b[1]), t);
    }
  }
  return color(SKY_STOPS[SKY_STOPS.length - 1][1]);
}

function drawSky() {
  noStroke();
  for (let y = 0; y <= HORIZON + 60; y += 6) {
    fill(skyColor(y / HORIZON));
    rect(0, y, 1600, 6.5);
  }
}

function drawClouds() {
