  const spots = [[1150, 150], [980, 320], [240, 420], [1420, 260], [520, 120], [660, 240]];
  for (const s of spots) fourStar(s[0], s[1], random(6, 11), 230);
}

function fourStar(x, y, r, a) {
  stroke(255, 250, 235, a);
  strokeWeight(1.4);
  line(x - r, y, x + r, y);
  line(x, y - r, x, y + r);
}

function drawBirds() {
  stroke(16, 22, 38, 220);
