/* ---------- 大地与地下 ---------- */

function soilColor(f) {
  if (f < 0.05) return lerpColor(color('#8a4e33'), color('#2e1c27'), f / 0.05);
  const t = (f - 0.05) / 0.95;
  return lerpColor(color('#2e1c27'), color('#0a070f'), Math.pow(t, 0.75));
}

function drawSoil() {
  noStroke();
