  for (let i = 0; i < 55; i++) {
    const x = random(1600), y = random(1240, 1960);
    if (random() < 0.5) fill(18, 12, 18, 200); else fill(64, 44, 40, 110);
    ellipse(x, y, random(6, 26), random(4, 12));
