/* ---------- 根系 ---------- */

function root(x, y, ang, len, depth, w, bias, wood, glow) {
  const x2 = x + Math.cos(ang) * len;
  const y2 = y + Math.sin(ang) * len;
  stroke(wood[0], wood[1], wood[2], 235);
  strokeWeight(w);
  line(x, y, x2, y2);
  const a = 34 + depth * 16;
  stroke(glow[0], glow[1], glow[2], a * 0.25);
  strokeWeight(Math.max(1, w * 0.9));
  line(x, y, x2, y2);
  stroke(glow[0], glow[1], glow[2], a);
  strokeWeight(Math.max(0.8, w * 0.32));
  line(x, y, x2, y2);
  if (depth <= 0) return;
  const n = random() < 0.75 ? 2 : 3;
  for (let i = 0; i < n; i++) {
    const t = (i / (n - 1)) * 2 - 1;
    let na = ang + bias + t * 0.5 + random(-0.25, 0.25);
    na = constrain(na, 0.12, Math.PI - 0.12);
    root(x2, y2, na, len * (0.72 + random(0.14)), depth - 1, Math.max(1, w * 0.62), bias, wood, glow);
  }
}

function drawRootSystems() {
  const RW = [30, 14, 13], GW = [28, 20, 12];
  root(478, 1176, 1.22, 96, 7, 13, -0.12, RW, RED_GLOW);
  root(478, 1176, 1.55, 105, 6, 9, -0.05, RW, RED_GLOW);
  root(478, 1176, 1.02, 82, 5, 8, -0.10, RW, RED_GLOW);
  root(1122, 1176, Math.PI - 1.22, 96, 7, 13, 0.12, GW, GOLD_GLOW);
  root(1122, 1176, Math.PI - 1.55, 105, 6, 9, 0.05, GW, GOLD_GLOW);
  root(1122, 1176, Math.PI - 1.02, 82, 5, 8, 0.10, GW, GOLD_GLOW);
}

/* ---------- 地下的双螺旋与心火 ---------- */

function glowDot(x, y, c, m) {
  fill(c[0], c[1], c[2], 13 * m);
  circle(x, y, 24);
  fill(c[0], c[1], c[2], 190 * m);
  circle(x, y, 6.5);
}

function drawSpiral() {
  blendMode(ADD);
  noStroke();
  for (let t = 0; t <= 1.0001; t += 0.004) {
    let edge = 1;
    if (t < 0.04) edge = t / 0.04;
    if (t > 0.95) edge = Math.max(0, (1 - t) / 0.05);
    const ph = t * TWO_PI * 2.6;
    const yy = 1870 - t * 430;
    const s = Math.sin(ph);
    glowDot(800 + s * 64, yy, RED_GLOW, edge);
    glowDot(800 - s * 64, yy, GOLD_GLOW, edge);
  }
  for (let k = 0; k <= 5; k++) {
    const t = k / 5.2;
    const yy = 1870 - t * 430;
    fill(255, 244, 226, 80); circle(800, yy, 22);
    fill(255, 250, 240, 220); circle(800, yy, 6.5);
  }
  blendMode(BLEND);
}

function lightArc(x0, y0, cx, cy, x1, y1, c) {
  for (let t = 0; t <= 1.0001; t += 0.055) {
    const u = 1 - t;
    const x = u * u * x0 + 2 * u * t * cx + t * t * x1;
    const y = u * u * y0 + 2 * u * t * cy + t * t * y1;
    fill(c[0], c[1], c[2], 12 + (1 - t) * 140);
    circle(x, y, 6.5 * (1 - t) + 1.5);
  }
}

function drawLightArcs() {
  blendMode(ADD);
  noStroke();
  lightArc(798, 1452, 700, 1490, 630, 1500, RED_GLOW);
  lightArc(802, 1452, 900, 1490, 970, 1500, GOLD_GLOW);
  blendMode(BLEND);
}

function drawHeartfire() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 34; i++) {
    const f = i / 34;
    fill(255, 132, 74, 2.2 + f * 6.5);
    circle(800, 1672, 430 * (1 - f) + 20);
  }
  blendMode(BLEND);
}

function drawAxisThread() {
  blendMode(ADD);
  strokeCap(ROUND);
  stroke(255, 220, 170, 9); strokeWeight(4);
  line(800, 720, 800, 1395);
  stroke(255, 235, 200, 15); strokeWeight(1.5);
  line(800, 720, 800, 1395);
  blendMode(BLEND);
}

/* ---------- 树 ---------- */

function leafCluster(x, y, r, pal) {
  noStroke();
  for (let i = 0; i < 8; i++) {
    const a = random(TWO_PI), d = random(r);
    const px = x + Math.cos(a) * d;
    const py = y + Math.sin(a) * d * 0.82 + r * 0.28;
    fill(pal[0]);
    circle(px, py, random(r * 0.75, r * 1.3));
  }
  for (let i = 0; i < 9; i++) {
    const a = random(TWO_PI), d = random(r);
    const px = x + Math.cos(a) * d;
    const py = y + Math.sin(a) * d * 0.82 - r * 0.10;
    const t = constrain(1 - Math.abs(px - 800) / 430, 0, 1);
    let idx = Math.floor(random() * pal.length + t * 2.2);
    idx = constrain(idx, 0, pal.length - 1);
    fill(pal[idx]);
    circle(px, py, random(r * 0.6, r * 1.2));
  }
}

function branch(x, y, ang, len, depth, w, bias, pal, wood) {
  const x2 = x + Math.cos(ang) * len;
  const y2 = y - Math.sin(ang) * len;
  stroke(wood);
  strokeWeight(w);
  strokeCap(ROUND);
  line(x, y, x2, y2);
  if (depth <= 0) {
    leafCluster(x2, y2, random(30, 46), pal);
    return;
  }
  if (depth >= 7) {
    const na = ang + bias * 0.55 + random(-0.06, 0.06);
    branch(x2, y2, na, len * 0.88, depth - 1, w * 0.78, bias, pal, wood);
    if (random() < 0.7) {
      const side = random() < 0.5 ? -1 : 1;
      branch(x2, y2, ang + side * 0.6 + random(-0.12, 0.12), len * 0.45, depth - 4, Math.max(2.5, w * 0.28), bias, pal, wood);
    }
    return;
  }
  const n = random() < 0.8 ? 2 : 3;
  for (let i = 0; i < n; i++) {
    const t = (i / (n - 1)) * 2 - 1;
    const na = ang + bias + t * 0.46 + random(-0.18, 0.18);
    branch(x2, y2, na, len * (0.70 + random(0.12)), depth - 1, Math.max(1.4, w * 0.65), bias, pal, wood);
  }
  if (depth <= 2) leafCluster(x2, y2, random(15, 26) + (2 - depth) * 5, pal);
}

function drawTrees() {
  stroke(RED_WOOD); strokeWeight(13); strokeCap(ROUND);
  line(478, 1168, 446, 1188);
  line(478, 1168, 513, 1186);
  branch(478, 1176, HALF_PI - 0.12, 185, 8, 30, -0.03, RED_PAL, RED_WOOD);

  stroke(GOLD_WOOD); strokeWeight(13);
  line(1122, 1168, 1154, 1188);
  line(1122, 1168, 1087, 1186);
  branch(1122, 1176, HALF_PI + 0.12, 185, 8, 30, 0.03, GOLD_PAL, GOLD_WOOD);
}

function reach(x0, y0, cx, cy, x1, y1, w, wood, pal) {
  noFill();
  stroke(wood);
  strokeWeight(w);
  strokeCap(ROUND);
  bezier(x0, y0, cx, cy, (cx + x1) / 2, (cy + y1) / 2, x1, y1);
  leafCluster(x1, y1, 26, pal);
}

function drawReachBranches() {
  reach(655, 660, 705, 640, 750, 622, 6.5, RED_WOOD, RED_PAL);
  reach(632, 470, 676, 455, 735, 472, 5, RED_WOOD, RED_PAL);
  reach(945, 655, 895, 635, 850, 618, 6.5, GOLD_WOOD, GOLD_PAL);
  reach(968, 462, 924, 448, 865, 465, 5, GOLD_WOOD, GOLD_PAL);
}

/* ---------- 落叶与光 ---------- */

function leaf(x, y, ang, c, s, a, wdx, wdy) {
  push();
  translate(x, y);
  rotate(ang);
  if (wdx !== 0 || wdy !== 0) {
    for (let k = 2; k >= 1; k--) {
      translate(-wdx * 14, -wdy * 14);
      fill(c[0], c[1], c[2], a * 0.18 / k);
      ellipse(0, 0, 24 * s, 11 * s);
    }
  }
  fill(c[0], c[1], c[2], a);
  ellipse(0, 0, 24 * s, 11 * s);
  stroke(c[0] * 0.6, c[1] * 0.6, c[2] * 0.6, a);
  strokeWeight(1.2);
  line(12 * s, 0, 17 * s, -2 * s);
  pop();
}

function drawFallingLeaves() {
  for (let i = 0; i < 46; i++) {
    const x0 = random(560, 900), y0 = random(520, 1060);
    const dx = random(50, 430), dy = random(-180, 60);
    leaf(x0 + dx, y0 + dy, random(-0.7, 0.15), random(RED_LEAF), random(0.7, 1.25), 235, 0.9, -0.32);
  }
  for (let i = 0; i < 46; i++) {
    const x0 = random(700, 1040), y0 = random(520, 1060);
    const dx = random(-430, -50), dy = random(-180, 60);
    leaf(x0 + dx, y0 + dy, random(-0.15, 0.7), random(GOLD_LEAF), random(0.7, 1.25), 235, -0.9, -0.30);
  }
}

