// 《同根》 —— 1600 × 2000 静态画作
// 地上：黎明，两树相望；地下：根系缠绕成一颗发光的心，与太阳上下呼应

const W = 1600, H = 2000;
const HORIZON = 1200;        // 地平线
const CX = 800;              // 中轴：太阳与心同轴呼应
const HY = 1710, HS = 12;    // 地下心形的中心与缩放

const LEFT_PAL  = [[236,168,64],[219,110,48],[198,72,58],[244,197,84],[168,58,50]];   // 左树·金焰
const RIGHT_PAL = [[219,82,108],[187,60,92],[233,118,130],[243,168,182],[152,44,74]]; // 右树·绯红

let branchCols = [];

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  strokeCap(ROUND);
  for (let d = 0; d <= 8; d++) {
    branchCols[d] = lerpColor(color(24, 12, 20), color(64, 30, 42), d / 8);
  }
  paint();
}

function paint() {
  drawSky();          // 天空渐变
  drawStars();        // 晨星
  drawGlow();         // 地平线上的光（太阳）
  drawMountains();    // 远山剪影
  drawClouds();       // 云带
  drawBirds();        // 飞鸟

  drawGround();       // 树基土丘与石头（在树后）
  const spotsL = growTree(560, HORIZON - 2, -HALF_PI + 0.10, -1);
  const spotsR = growTree(1040, HORIZON - 2, -HALF_PI - 0.10, 1);
  drawAllLeaves(spotsL.concat(spotsR));   // 树冠

  drawSoil();         // 土壤剖面
  drawRoots();        // 自由根系
  drawLeaderRoots();  // 连向心脏的主根
  drawHeartGlow();    // 心底光
  drawWovenHeart();   // 双根编织的心 + 光须
  drawHeartMotes();   // 心周光尘

  drawGrass();        // 草
  drawGroundPetals(); // 地上落瓣
  drawAirPetals();    // 空中飘瓣
  drawSoilGrain();    // 土壤颗粒
  drawFilmGrain();    // 全局颗粒
  drawVignette();     // 暗角
}

/* ---------------- 天空 ---------------- */

function drawSky() {
  const stops = [
    [0.00, 11, 13, 40],
    [0.28, 28, 33, 80],
    [0.52, 72, 50, 100],
    [0.72, 142, 84, 92],
    [0.88, 220, 138, 88],
    [1.00, 255, 196, 124]
  ];
  strokeWeight(1);
  for (let y = 0; y < HORIZON; y++) {
    const t = y / HORIZON;
    let c = stops[stops.length - 1];
    for (let i = 0; i < stops.length - 1; i++) {
      if (t <= stops[i + 1][0]) {
        const a = stops[i], b = stops[i + 1];
        const k = (t - a[0]) / (b[0] - a[0]);
        c = [0, lerp(a[1], b[1], k), lerp(a[2], b[2], k), lerp(a[3], b[3], k)];
        break;
      }
    }
    stroke(c[1], c[2], c[3]);
    line(0, y, W, y);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 175; i++) {
    const x = random(W);
    const y = pow(random(), 1.5) * 760;      // 上密下疏
    const sz = random(0.7, 2.5);
    fill(255, 242, 224, random(90, 200));
    ellipse(x, y, sz, sz);
    if (random() < 0.055) {                  // 少数亮星带光芒
      push();
      translate(x, y);
      rotate(random(TWO_PI));                // 旋转的光芒，避免规整
      stroke(255, 235, 205, 150);
      strokeWeight(1);
      line(-sz * 3.6, 0, sz * 4.2, 0);
      line(0, -sz * 3.2, 0, sz * 3.6);
      pop();
    }
  }
}

function drawGlow() {
  push();
  blendMode(ADD);
  noStroke();
  const gx = CX, gy = HORIZON + 4;
  for (let i = 0; i < 20; i++) {             // 大范围曦光
    const r = 640 - i * 24;
    fill(255, 186, 120, 3 + i * 0.55);
    ellipse(gx, gy, r * 2, r * 1.28);
  }
  for (let i = 0; i < 10; i++) {             // 光核（半掩于地平线）
    const r = 96 - i * 8.5;
    fill(255, 238, 200, 16);
    ellipse(gx, gy - 26, r * 2, r * 2);
  }
  blendMode(BLEND);
  pop();
}

function drawMountains() {
  noStroke();
  mountainLayer(0.0015, 120, 0.35, color(84, 55, 108));   // 远山
  mountainLayer(0.0028, 78, 4.7, color(46, 26, 58));      // 近山
}

function mountainLayer(f, amp, off, col) {
  fill(col);
  beginShape();
  vertex(-4, HORIZON + 2);
  for (let x = 0; x <= W; x += 16) {
    // 中央（日出处）山势低伏，让光露出
    const dip = 0.35 + 0.65 * abs(x - CX) / CX;
    vertex(x, HORIZON - noise(x * f, off) * amp * dip);
  }
  vertex(W + 4, HORIZON + 2);
  endShape(CLOSE);
}

function drawClouds() {
  noStroke();
  const bands = [[300, 55], [480, 65], [660, 75], [880, 85], [1055, 60]];
  for (const [cy, spread] of bands) {
    for (let i = 0; i < 34; i++) {
      const x = random(-80, W + 80);
      const y = cy + random(-spread, spread);
      const t = y / HORIZON;
      const c = lerpColor(color(92, 82, 132), color(255, 186, 128), pow(t, 1.4));
      fill(c, 14 + t * 26 + random(12));
      ellipse(x, y, random(70, 210), random(9, 24));
    }
  }
}

/* ---------------- 飞鸟 ---------------- */

function drawBirds() {
  const flock = [[-95, 28, 0.62], [-42, -6, 0.5], [4, 8, 0.72], [58, -30, 0.55], [112, 16, 0.46]];
  for (const [ox, oy, s] of flock) {
    drawBird(CX + 60 + ox, 360 + oy, s, -1, random(-0.75, 0.75));
  }
  drawBird(295, 690, 0.40, 1, random(-0.6, 0.6));
  drawBird(345, 722, 0.34, 1, random(-0.6, 0.6));
  drawBird(1180, 560, 0.38, -1, random(-0.6, 0.6));
}

function drawBird(x, y, s, dir, flap) {
  push();
  translate(x, y);
  scale(s * dir, s);
  fill(15, 8, 20);
  noStroke();
  ellipse(0, 0, 13, 4.6);        // 身体
  ellipse(6.5, -0.5, 4.4, 3.6);  // 头
  wing(-1, 0, flap);
  wing(-1, 0, PI - flap);
  pop();
}

function wing(x, y, a) {
  const L = 15;
  beginShape();
  vertex(x, y);
  quadraticVertex(x + cos(a) * L * 0.45, y + sin(a) * L * 0.45 - 5,
                  x + cos(a) * L, y + sin(a) * L);
  quadraticVertex(x + cos(a) * L * 0.55, y + sin(a) * L * 0.55 + 4, x, y + 1.5);
  endShape(CLOSE);
}

/* ---------------- 地面与树 ---------------- */

function drawGround() {
  noStroke();
  fill(22, 11, 18);                          // 树基土丘
  ellipse(560, HORIZON + 5, 250, 34);
  ellipse(1040, HORIZON + 5, 250, 34);
  for (let i = 0; i < 7; i++) {              // 石头
    const x = random(160, W - 160);
    if (abs(x - 560) < 130 || abs(x - 1040) < 130) continue;
    const rw = random(38, 95), rh = rw * random(0.24, 0.38);
    fill(20, 10, 17);
    ellipse(x, HORIZON - rh * 0.25, rw, rh);
    noFill();
    stroke(255, 175, 120, 55);
    strokeWeight(1.6);
    arc(x, HORIZON - rh * 0.25, rw * 0.92, rh * 0.92, PI + 0.25, TWO_PI - 0.25);
    noStroke();
  }
}

function growTree(bx, by, baseA, side) {
  const spots = [];
  branch(bx, by, baseA, 235, 52, 0, side, spots);
  return spots;
}

function branch(x, y, angle, len, w, depth, side, spots) {
  if (depth > 8 || len < 13) { addSpot(x, y, side, spots, 1); return; }
  if (depth >= 5 && random() < 0.26) { addSpot(x, y, side, spots, 1.15); return; }

  const bias = -side * 0.055;                                   // 枝条向中心伸展
  const sway = (noise(x * 0.0022, y * 0.0022, depth * 1.3) - 0.5) * 0.55;
  const a = angle + bias + sway * 0.35;
  const nx = cos(a + HALF_PI), ny = sin(a + HALF_PI);
  const k = (noise(x * 0.004 + 40, y * 0.004) - 0.5) * len * 0.24;
  const x2 = x + cos(a) * len;
  const y2 = y + sin(a) * len;
  const mx = x + cos(a) * len * 0.55 + nx * k;
  const my = y + sin(a) * len * 0.55 + ny * k;

  stroke(branchCols[depth]);
  strokeWeight(w);
  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(mx, my, x2, y2);
  endShape();

  if (depth >= 3 && random() < 0.16) addSpot(mx, my, side, spots, 0.85);

  const n = depth < 2 ? 2 : (random() < 0.26 ? 3 : 2);
  for (let i = 0; i < n; i++) {
    const dir = i === 0 ? -1 : (i === n - 1 ? 1 : 0);
    branch(x2, y2, a + dir * random(0.28, 0.62),
           len * random(0.68, 0.79), w * 0.62, depth + 1, side, spots);
  }
  if (depth >= 2 && depth <= 5 && random() < 0.22) {            // 中途小枝
    branch(mx, my, a + (random() < 0.5 ? -1 : 1) * random(0.5, 0.95),
           len * 0.55, w * 0.5, depth + 2, side, spots);
  }
}

function addSpot(x, y, side, spots, sc) {
  const xc = side < 0 ? random(4, 20) : -random(4, 20);        // 树冠向中心聚拢
  spots.push([x + xc, y + random(-8, 12), sc * random(0.8, 1.25)]);
}

function leafColor(t) {
  const a = LEFT_PAL[floor(random(LEFT_PAL.length))];
  const b = RIGHT_PAL[floor(random(RIGHT_PAL.length))];
  const k = constrain(t + random(-0.25, 0.25), 0, 1);
  return [lerp(a[0], b[0], k), lerp(a[1], b[1], k), lerp(a[2], b[2], k)];
}

function drawAllLeaves(spots) {
  for (const s of spots) drawLeafCluster(s[0], s[1], s[2]);
}

function drawLeafCluster(px, py, sc) {
  const t = constrain((px - 600) / 420, 0, 1);    // 金→绯的过渡带
  const R = 44 * sc;
  const base = leafColor(t);
  noStroke();
  fill(base[0], base[1], base[2], 34);            // 柔光底团
  ellipse(px, py, R * 2.3, R * 2.05);
  const n = floor(26 * sc) + 10;
  for (let i = 0; i < n; i++) {
    const ang = random(TWO_PI);
    const rr = pow(random(), 0.55) * R;
    const x = px + cos(ang) * rr * 1.2;
    const y = py + sin(ang) * rr;
    const c = leafColor(t);
    const dL = dist(x, y, CX, HORIZON);
    const lit = constrain(1 - dL / 900, 0, 1) * 0.55 + (random() < 0.18 ? 0.35 : 0);
    fill(lerp(c[0], 255, lit), lerp(c[1], 214, lit), lerp(c[2], 170, lit), 225);
    const sz = random(2.6, 6.5);
    ellipse(x, y, sz, sz * 0.92);
  }
}

/* ---------------- 土壤剖面 ---------------- */

function drawSoil() {
  for (let y = HORIZON; y < H; y++) {              // 纵向渐深
    const t = (y - HORIZON) / (H - HORIZON);
    stroke(lerpColor(color(58, 30, 46), color(16, 7, 17), pow(t, 0.85)));
    strokeWeight(1);
    line(0, y, W, y);
  }
  for (let y = HORIZON; y < HORIZON + 26; y++) {    // 表层切面受光带
    const t = (y - HORIZON) / 26;
    stroke(lerpColor(color(122, 70, 62), color(58, 30, 46), t));
    line(0, y, W, y);
  }
  noStroke();
  fill(255, 216, 150, 110);                         // 地平线亮边
  rect(0, HORIZON - 2, W, 2);

  noFill();                                         // 沉积层理
  let y = HORIZON + 40;
  while (y < H - 10) {
    stroke(232, 150, 122, 8 + noise(y * 0.02) * 10);
    strokeWeight(random(1.2, 4.5));
    beginShape();
    for (let x = 0; x <= W; x += 36) {
      vertex(x, y + (noise(x * 0.0035, y * 0.012) - 0.5) * 22);
    }
    endShape();
    y += random(16, 36);
  }
  noStroke();                                       // 埋石
  for (let i = 0; i < 30; i++) {
    const x = random(70, W - 70), yy = random(HORIZON + 60, H - 50);
    if (dist(x, yy, CX, HY) < 340) continue;
    const rw = random(9, 40);
    fill(10, 5, 12, 210);
    ellipse(x, yy, rw, rw * random(0.4, 0.68));
  }
}

/* ---------------- 根系与心 ---------------- */

function heart(t) {
  const x = 16 * pow(sin(t), 3);
  const y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t);
  return [CX + x * HS, HY - y * HS];
}

function rootCol(x, y) {
  const prox = constrain(1 - dist(x, y, CX, HY) / 500, 0, 1);
  return lerpColor(color(56, 30, 44), color(212, 96, 128), pow(prox, 2));
}

function root(x, y, angle, len, w, depth, side) {
  if (depth > 7 || len < 9 || w < 0.8) return;
  let a = angle + side * 0.09 + (noise(x * 0.002, y * 0.002, 3.7) - 0.5) * 0.6;
  if (y > 1480) {                                   // 深处被心吸引
    const da = atan2(HY - 8 - y, CX - x);
    a = a * 0.85 + da * 0.15;
  }
  const nx = cos(a + HALF_PI), ny = sin(a + HALF_PI);
  const k = (noise(y * 0.01, x * 0.002) - 0.5) * len * 0.2;
  const x2 = x + cos(a) * len;
  const y2 = y + sin(a) * len;
  const mx = x + cos(a) * len * 0.55 + nx * k;
  const my = y + sin(a) * len * 0.55 + ny * k;

  stroke(rootCol(x, y));
  strokeWeight(w);
  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(mx, my, x2, y2);
  endShape();

  const n = depth < 2 ? 2 : (random() < 0.3 ? 3 : 2);
  for (let i = 0; i < n; i++) {
    const dir = i === 0 ? -1 : (i === n - 1 ? 1 : 0);
    root(x2, y2, a + dir * random(0.3, 0.65),
         len * random(0.7, 0.82), w * 0.68, depth + 1, side);
  }
}

function drawRoots() {
  for (const [bx, side] of [[560, -1], [1040, 1]]) {
    for (let i = 0; i < 5; i++) {
      const a = HALF_PI + (i - 2) * 0.42 + random(-0.1, 0.1) + side * 0.12;
      root(bx + (i - 2) * 14, HORIZON + 4, a, 100 + random(50), 13, 0, side);
    }
  }
}

function leaderRoot(x0, y0, cx, cy, x1, y1, w0) {
  const STEPS = 26;
  let px = x0, py = y0;
  for (let i = 1; i <= STEPS; i++) {
    const t = i / STEPS, mt = 1 - t;
    const x = mt * mt * x0 + 2 * mt * t * cx + t * t * x1;
    const y = mt * mt * y0 + 2 * mt * t * cy + t * t * y1;
    const prox = constrain((y - 1400) / 200, 0, 1);
    const col = lerpColor(color(58, 31, 44), color(255, 120, 150), pow(prox, 1.6));
    if (prox > 0.05) {                              // 末端发光
      stroke(255, 110, 150, 55 * prox);
      strokeWeight(w0 * 1.9);
      line(px, py, x, y);
    }
    stroke(col);
    strokeWeight(lerp(w0, 6, t));
    line(px, py, x, y);
    px = x; py = y;
  }
  noStroke();                                       // 融入心脏的亮结
  fill(255, 160, 185, 190);
  ellipse(x1, y1, 9, 9);
}

function drawLeaderRoots() {
  const aL = heart(-0.55), aR = heart(0.55);
  const bL = heart(-2.35), bR = heart(2.35);
  leaderRoot(560, HORIZON + 4, 606, 1470, aL[0], aL[1], 19);
  leaderRoot(1040, HORIZON + 4, 994, 1470, aR[0], aR[1], 19);
  leaderRoot(548, HORIZON + 6, 618, 1625, bL[0], bL[1], 10);
  leaderRoot(1052, HORIZON + 6, 982, 1625, bR[0], bR[1], 10);
}

function drawHeartGlow() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 22; i++) {
    const r = 300 - i * 12;
    fill(255, 118, 158, 2.5 + i * 0.55);
    ellipse(CX, HY + 18, r * 2, r * 1.85);
  }
  for (let i = 0; i < 12; i++) {
    fill(255, 205, 220, 9);
    ellipse(CX, HY + 18, 150 - i * 11, 140 - i * 10);
  }
  blendMode(BLEND);
  pop();
}

function drawWovenHeart() {
  const N = 110;
  const pts = [];
  for (let i = 0; i <= N; i++) {
    const t = map(i, 0, N, 0, TWO_PI);
    const p = heart(t), q = heart(t + 0.012);
    const dx = q[0] - p[0], dy = q[1] - p[1];
    const L = sqrt(dx * dx + dy * dy) || 1;
    pts.push([p[0], p[1], -dy / L, dx / L]);
  }
  const OFF = 7.5;
  const P = (i, s) => [pts[i][0] + pts[i][2] * OFF * s, pts[i][1] + pts[i][3] * OFF * s];

  for (let i = 0; i < N; i++) {                     // 双线交替穿插 = 编织
    const a1 = P(i, 1), a2 = P(i + 1, 1);
    const b1 = P(i, -1), b2 = P(i + 1, -1);
    const first = (i % 2 === 0);
    weaveSeg(first ? a1 : b1, first ? a2 : b2, 0);
    weaveSeg(first ? b1 : a1, first ? b2 : a2, 1);
  }

  for (let i = 0; i < 30; i++) {                    // 心向外发微光须
    const t = random(TWO_PI);
    const p = heart(t), q = heart(t + 0.01);
    const dx = q[0] - p[0], dy = q[1] - p[1];
    const L = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / L, ny = dx / L;
    if ((p[0] - CX) * nx + (p[1] - HY) * ny < 0) { nx = -nx; ny = -ny; }
    const len = random(30, 95);
    const bend = random(-0.5, 0.5);
    const ex = p[0] + nx * len - ny * len * bend * 0.5;
    const ey = p[1] + ny * len + nx * len * bend * 0.5;
    noFill();
    stroke(255, 140, 175, 85);
    strokeWeight(1.5);
    beginShape();
    vertex(p[0], p[1]);
    quadraticVertex(p[0] + nx * len * 0.5 - ny * len * bend * 0.3,
                    p[1] + ny * len * 0.5 + nx * len * bend * 0.3, ex, ey);
    endShape();
    noStroke();                                     // 须端光尘
    fill(255, 157, 187, 140);
    ellipse(ex, ey, 2.6, 2.6);
  }
}

function weaveSeg(p1, p2, which) {
  stroke(255, 105, 150, 46);                        // 光晕层
  strokeWeight(13);
  line(p1[0], p1[1], p2[0], p2[1]);
  stroke(which === 0 ? color(255, 150, 178) : color(255, 214, 226));
  strokeWeight(4.6);
  line(p1[0], p1[1], p2[0], p2[1]);
}

function drawHeartMotes() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 70; i++) {
    const a = random(TWO_PI);
    const r = 40 + pow(random(), 0.7) * 260;
    fill(255, 170, 200, random(20, 80));
    ellipse(CX + cos(a) * r * 1.1, HY + sin(a) * r * 0.8,
            random(1, 3), random(1, 3));
  }
  blendMode(BLEND);
  pop();
}

