// 《地下的月亮》
// 天上：两棵冬夜之树彼此倾身，枝条在月下交织，横枝上依偎着两只小鸟；
// 地下：剖开大地，两树的根系穿过黑暗的泥土，在深处缠绕成一团温暖的光——
// 像另一轮被埋进土里的月亮。

let HEART_X = 800;
let HEART_Y = 1655;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(6, 10, 28);
  drawSky();
  drawStars();
  drawMoon();
  drawTrees();
  drawThreads();
  drawFireflies();
  drawGround();
  drawUnderground();
  drawVignette();
  drawGrain();
}

// ---------- 天空 ----------
function drawSky() {
  let g = drawingContext.createLinearGradient(0, 0, 0, 1150);
  g.addColorStop(0, '#05081c');
  g.addColorStop(0.5, '#141f45');
  g.addColorStop(0.82, '#2c2547');
  g.addColorStop(1, '#4b3457');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, 1600, 1150);
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(1600);
    let y = random(1000);
    if (dist(x, y, 800, 372) < 230) continue;
    let a = map(y, 0, 1000, 220, 40) * random(0.25, 1);
    fill(215, 224, 255, a);
    circle(x, y, random(0.6, 2.1));
  }
  for (let i = 0; i < 9; i++) {
    let x = random(80, 1520);
    let y = random(60, 800);
    if (dist(x, y, 800, 372) < 260) continue;
    glow(x, y, 16, '220,228,255', 0.5);
    fill(240, 245, 255, 230);
    circle(x, y, 2.2);
  }
}

function drawMoon() {
  glow(800, 372, 430, '205,196,190', 0.14);
  glow(800, 372, 240, '232,222,200', 0.3);
  noStroke();
  fill(242, 234, 210);
  circle(800, 372, 198);
  glow(800, 372, 104, '255,250,232', 0.5);
  // 月面淡淡的斑
  fill(214, 205, 180, 42);
  circle(770, 346, 42);
  circle(842, 396, 28);
  circle(824, 330, 15);
  circle(764, 404, 20);
  circle(800, 366, 24);
}

// ---------- 树 ----------
function drawTrees() {
  strokeCap(ROUND);
  strokeJoin(ROUND);
  stroke(4, 6, 14);
  branchSeg(520, 1160, -HALF_PI + 0.14, 245, 0, 26);   // 左树，向右倾身
  branchSeg(1080, 1160, -HALF_PI - 0.14, 245, 0, 26);  // 右树，向左倾身

  // 两冠交握处的一根横枝
  noFill();
  stroke(4, 6, 14);
  strokeWeight(8);
  bezier(690, 896, 760, 886, 840, 888, 905, 898);
  strokeWeight(5);
  bezier(700, 880, 770, 870, 830, 872, 895, 882);

  // 横枝上依偎的两只小鸟
  bird(762, 888, 1);
  bird(800, 888, -1);
}

function branchSeg(x, y, angle, len, depth, w) {
  // 粗枝向中心聚拢，细梢自由散开
  let b = (800 - x) * (depth < 7 ? 0.0005 : 0.00018);
  angle += b;
  angle += (noise(x * 0.004, y * 0.004, depth * 0.61) - 0.5) * 0.45;
  angle = constrain(angle, -PI + 0.24, -0.18);
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  if (y2 < 160 || x2 < 20 || x2 > 1580) return;
  stroke(4, 6, 14);
  strokeWeight(w);
  line(x, y, x2, y2);
  if (depth >= 10 || len < 8) return;
  let n = depth < 2 ? 3 : (random() < 0.8 ? 2 : 3);
  for (let i = 0; i < n; i++) {
    let off = n === 3
      ? (i - 1) * (0.45 + random(0.32))
      : (i === 0 ? -1 : 1) * (0.3 + random(0.42));
    branchSeg(x2, y2, angle + off, len * (0.66 + random(0.13)), depth + 1, max(w * 0.72, 1.5));
  }
}

function bird(x, y, dir) {
  push();
  translate(x, y);
  scale(dir, 1);
  noStroke();
  fill(3, 5, 12);
  triangle(-12, -14, -34, -8, -14, -20);   // 尾
  ellipse(0, -15, 34, 22);                 // 身
  circle(15, -28, 17);                     // 头
  triangle(23, -30, 32, -27, 23, -24);     // 喙
  stroke(200, 205, 225, 90);               // 翅上的一线月光
  strokeWeight(2);
  noFill();
  arc(-2, -18, 20, 12, -2.6, -0.6);
  pop();
}

// 两树之间挂着微光的细丝
function drawThreads() {
  thread(455, 690, 700, 765, 1125, 635);
  thread(540, 565, 790, 640, 1085, 500);
  thread(610, 1010, 800, 1060, 1000, 980);
}

function thread(x1, y1, cx, cy, x2, y2) {
  noFill();
  stroke(255, 240, 214, 60);
  strokeWeight(1.2);
  bezier(x1, y1, cx, cy, cx, cy, x2, y2);
  let mx = (x1 + 6 * cx + x2) / 8;
  let my = (y1 + 6 * cy + y2) / 8;
  glow(mx, my, 13, '255,220,160', 0.4);
  noStroke();
  fill(255, 232, 180, 200);
  circle(mx, my, 2.6);
}

// 树冠间浮动的暖光
function drawFireflies() {
  for (let i = 0; i < 68; i++) {
    let a = random(TWO_PI);
    let rr = pow(random(1), 0.62);
    let x = 800 + cos(a) * rr * 470;
    let y = 620 + sin(a) * rr * 330;
    let s = random(1.3, 3.4);
    glow(x, y, 10 + s * 5, '255,205,120', random(0.22, 0.42));
    noStroke();
    fill(255, 224, 156, random(140, 220));
    circle(x, y, s);
  }
}

// ---------- 雪地 ----------
function drawGround() {
  let g = drawingContext.createLinearGradient(0, 1146, 0, 1196);
  g.addColorStop(0, '#b7c2da');
  g.addColorStop(0.45, '#8d99b6');
  g.addColorStop(1, '#525e7c');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 1146, 1600, 50);
  // 雪脊亮线
  noStroke();
  for (let x = 0; x < 1600; x += 8) {
    let h = 2 + noise(x * 0.01, 90) * 3;
    fill(235, 240, 252, 150);
    rect(x, 1146, 8, h);
  }
  // 树影
  fill(22, 28, 44, 105);
  ellipse(520, 1168, 250, 22);
  ellipse(1080, 1168, 250, 22);
  // 月光洒在雪上
  glow(800, 1152, 540, '185,200,238', 0.2);
  // 雪粒
  noStroke();
  for (let i = 0; i < 50; i++) {
    fill(240, 244, 255, random(25, 90));
    circle(random(1600), random(1148, 1190), random(1, 2.4));
  }
}

// ---------- 地下 ----------
function drawUnderground() {
  // 土壤
  let g = drawingContext.createLinearGradient(0, 1190, 0, 2000);
  g.addColorStop(0, '#261d2b');
  g.addColorStop(0.22, '#181009');
  g.addColorStop(0.6, '#0c0705');
  g.addColorStop(1, '#050302');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 1190, 1600, 810);
  // 雪-土分界的投影线
  stroke(15, 12, 20, 130);
  strokeWeight(3);
  line(0, 1191, 1600, 1191);

  // 沉积层
  noFill();
  for (let k = 0; k < 5; k++) {
    let y0 = 1250 + k * 150 + random(50);
    stroke(64, 44, 34, 34);
    strokeWeight(2);
    beginShape();
    for (let x = 0; x <= 1600; x += 50) {
      vertex(x, y0 + (noise(x * 0.0028, k * 4.7) - 0.5) * 46);
    }
    endShape();
  }

  // 土壤颗粒（离光核越近越暖）
  noStroke();
  for (let i = 0; i < 1000; i++) {
    let x = random(1600);
    let y = random(1192, 1996);
    let s = random(0.8, 3.6);
    let warm = constrain(1 - dist(x, y, HEART_X, HEART_Y) / 430, 0, 1);
    let c = lerpColor(color(44, 28, 22), color(196, 128, 74), pow(warm, 1.8) * 0.85);
    fill(red(c), green(c), blue(c), random(35, 100));
    circle(x, y, s);
  }
  // 石头
  for (let i = 0; i < 55; i++) {
    let x = random(1600);
    let y = random(1210, 1980);
    if (dist(x, y, HEART_X, HEART_Y) < 300) continue;
    let w = random(7, 20);
    let h = w * random(0.55, 0.85);
    noStroke();
    fill(30, 20, 16, 200);
    ellipse(x, y, w, h);
    fill(70, 50, 40, 90);
    ellipse(x - w * 0.15, y - h * 0.2, w * 0.55, h * 0.5);
  }

  // 暖光透进土壤
  glow(HEART_X, HEART_Y, 480, '255,158,78', 0.3);
  glow(HEART_X, HEART_Y, 300, '255,190,110', 0.42);

  // 两棵树的根，向深处那团光生长
  strokeCap(ROUND);
  rootSeg(520, 1172, 1.15, 148, 0, 15);
  rootSeg(1080, 1172, PI - 1.15, 148, 0, 15);

  // 根须绕光缠成的结
  noFill();
  strokeWeight(12); stroke(148, 90, 56, 230);
  arc(HEART_X, HEART_Y, 384, 236, 0.35, 3.35);
  strokeWeight(9); stroke(198, 124, 72, 220);
  arc(HEART_X, HEART_Y, 316, 186, -0.7, 2.3);
  strokeWeight(6); stroke(226, 152, 94, 210);
  arc(HEART_X, HEART_Y, 258, 152, 2.7, 5.8);
  strokeWeight(2.5); stroke(255, 208, 140, 190);
  arc(HEART_X, HEART_Y, 312, 184, -0.55, 2.0);

  // 光尘
  for (let i = 0; i < 70; i++) {
    let a = random(TWO_PI);
    let rr = 40 + pow(random(1), 0.7) * 300;
    let x = HEART_X + cos(a) * rr;
    let y = HEART_Y + sin(a) * rr * 0.82;
    let b = 220 * constrain(1 - rr / 340, 0.1, 1);
    noStroke();
    fill(255, 214, 146, b);
    circle(x, y, random(1, 2.6));
  }

  // 心核——地下的月亮
  glow(HEART_X, HEART_Y, 130, '255,228,168', 0.9);
  noStroke();
  fill(255, 236, 188);
  circle(HEART_X, HEART_Y, 30);
  fill(255, 252, 240);
  circle(HEART_X, HEART_Y, 14);
}

function rootSeg(x, y, angle, len, depth, w) {
  // 深处的根被光吸引，向光核蜿蜒
  let t = atan2(HEART_Y - y, HEART_X - x);
  angle = angLerp(angle, t, depth < 6 ? 0.11 : 0.045);
  angle += (noise(x * 0.003, y * 0.003, 41.3 + depth * 1.7) - 0.5) * 0.5;
  angle = constrain(angle, 0.2, PI - 0.2);
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  if (y2 > 1985 || x2 < 15 || x2 > 1585) return;
  let mx = (x + x2) / 2;
  let my = (y + y2) / 2;
  let warm = constrain(1 - dist(mx, my, HEART_X, HEART_Y) / 480, 0, 1);
  if (warm > 0.06) { // 近光处根须透出暖光
    stroke(255, 160, 86, 30 + 120 * warm);
    strokeWeight(w + 6);
    line(x, y, x2, y2);
  }
  let c = lerpColor(color(54, 34, 25), color(216, 136, 76), pow(warm, 1.5));
  stroke(c);
  strokeWeight(w);
  line(x, y, x2, y2);
  if (depth >= 8 || len < 7) return;
  let n = depth < 2 ? 3 : (random() < 0.75 ? 2 : 3);
  for (let i = 0; i < n; i++) {
    let off = n === 3
      ? (i - 1) * (0.42 + random(0.34))
      : (i === 0 ? -1 : 1) * (0.26 + random(0.42));
    rootSeg(x2, y2, angle + off, len * (0.68 + random(0.12)), depth + 1, max(w * 0.7, 1.4));
  }
}

