function lerpStops(t, stops) {
  for (let i = 0; i < stops.length - 1; i++) {
    const t0 = stops[i][0], c0 = stops[i][1];
    const t1 = stops[i + 1][0], c1 = stops[i + 1][1];
    if (t >= t0 && t <= t1) {
      const f = (t - t0) / (t1 - t0);
      return color(lerp(c0[0], c1[0], f), lerp(c0[1], c1[1], f), lerp(c0[2], c1[2], f));
    }
  }
  const c = stops[stops.length - 1][1];
  return color(c[0], c[1], c[2]);
}

function heartShape(x, y, s) {
  beginShape();
  vertex(x, y + s * 0.9);
  bezierVertex(x - s * 1.15, y + s * 0.05, x - s * 0.55, y - s * 0.9, x, y - s * 0.22);
  bezierVertex(x + s * 0.55, y - s * 0.9, x + s * 1.15, y + s * 0.05, x, y + s * 0.9);
  endShape(CLOSE);
}

