const W = 1600, H = 2000, HOR = 1260;

const LEAF_WARM = ['#ff8787', '#ffa94d', '#ffd43b', '#e64980', '#f783ac', '#ffc9c9', '#f76707'];
const LEAF_COOL = ['#748ffc', '#9775fa', '#63e6be'];

function setup() {
