  drawStars();
  drawGlow();
  drawSuns();
  drawWaterBase();

  // 镜像倒影（重新播种，保证与岸上景物完全一致）
  c.save();
  c.beginPath();
  c.rect(0, HOR, W, H - HOR);
  c.clip();
  c.translate(0, 2 * HOR);
