    ellipse(888 + (noise(i * 0.7, 9) - 0.5) * spread, y, random(26, 90) * (0.4 + t * 1.2), random(3, 8));
  }
  for (let i = 0; i < 130; i++) {
    const y = HOR + random(H - HOR);
    const x = random(-40, W);
