function drawTrees() {
  noFill();
  stroke(15, 9, 28);
  strokeCap(ROUND);
  strokeWeight(54);
  line(298, HOR + 40, 382, 1080);
  strokeWeight(34);
  line(382, 1080, 472, 918);
  strokeWeight(54);
  line(1302, HOR + 40, 1218, 1080);
  strokeWeight(34);
  line(1218, 1080, 1128, 918);
  branch(472, 918, -HALF_PI + 0.45, 155, 8, 1);
  branch(1128, 918, -HALF_PI - 0.45, 155, 8, -1);
}

function branch(x, y, ang, len, depth, side) {
  if (depth === 0 || len < 6) {
    drawLeaf(x, y);
    return;
  }
  const nx = x + cos(ang) * len;
  const ny = y + sin(ang) * len;
  const cx = (x + nx) / 2 + (noise(x * 0.02, y * 0.02, depth * 13.7) - 0.5) * len * 0.9;
  const cy = (y + ny) / 2 + (noise(x * 0.02 + 40, y * 0.02, depth * 7.3) - 0.5) * len * 0.6;
  stroke(15, 9, 28);
  strokeWeight(map(depth, 1, 8, 1.4, 13));
  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(cx, cy, nx, ny);
  endShape();
  if (depth <= 3 && random() < 0.55) drawLeaf(x + random(-10, 10), y + random(-10, 10));
  const n = depth > 6 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let a = ang + map(i, 0, n - 1, -1, 1) * random(0.32, 0.72) + (noise(depth * 31.7 + i, x * 0.05, y * 0.05) - 0.5) * 0.55;
    a = lerp(a, -HALF_PI + side * 0.28, 0.22);
    branch(nx, ny, a, len * random(0.66, 0.8), depth - 1, side);
  }
}

function drawLeaf(x, y) {
  const pal = random() < 0.16 ? LEAF_COOL : LEAF_WARM;
  const c = color(random(pal));
  c.setAlpha(random(150, 245));
  noStroke();
  fill(c);
  push();
  translate(x, y);
  rotate(random(TWO_PI));
  ellipse(0, 0, random(7, 17), random(4, 10));
  pop();
}

function drawBridges() {
  strokeCap(ROUND);
  for (let i = 0; i < 8; i++) {
    const y0 = random(420, 780);
    const x0 = random(540, 740);
    const x1 = W - x0 + random(-50, 50);
    const y1 = y0 + random(-70, 70);
    const cx1 = x0 + random(80, 180), cy1 = y0 - random(30, 150);
    const cx2 = x1 - random(80, 180), cy2 = y1 - random(30, 150);
    noFill();
    stroke(15, 9, 28);
    strokeWeight(random(2, 5));
    bezier(x0, y0, cx1, cy1, cx2, cy2, x1, y1);
    for (let t = 0.12; t < 0.95; t += random(0.12, 0.22)) {
      if (random() < 0.75) {
        const p = bezierPoint(x0, y0, cx1, cy1, cx2, cy2, x1, y1, t);
        drawLeaf(p.x + random(-6, 6), p.y + random(-6, 6));
      }
    }
  }
}

function heartXY(t, cx, cy, s) {
  const x = 16 * pow(sin(t), 3);
  const y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t);
  return [cx + x * s, cy - y * s];
}

function drawBirds() {
  noFill();
  const N = 54;
  for (let i = 0; i < N; i++) {
    const t = (i / N) * TWO_PI + random(-0.06, 0.06);
    const p = heartXY(t, W / 2, 830, 21);
    drawBird(p[0] + random(-26, 26), p[1] + random(-26, 26), random(6, 13), random() < 0.5 ? 1 : -1);
  }
  for (let i = 0; i < 16; i++) {
    drawBird(random(W * 0.08, W * 0.92), random(120, 480), random(4, 9), random() < 0.5 ? 1 : -1);
  }
}

function drawBird(x, y, s, dir) {
  stroke(26, 14, 40, 220);
  strokeWeight(max(1.2, s * 0.22));
  strokeCap(ROUND);
  const w = dir * s * 0.55;
  beginShape();
  vertex(x - s, y);
  quadraticVertex(x - s * 0.45, y + w, x, y);
  endShape();
  beginShape();
  vertex(x + s, y);
  quadraticVertex(x + s * 0.45, y + w, x, y);
  endShape();
}

function drawPetals() {
  noStroke();
  for (let i = 0; i < 70; i++) {
    const c = color(random(LEAF_WARM));
    c.setAlpha(random(80, 200));
    fill(c);
    push();
    translate(random(W * 0.15, W * 0.85), random(300, HOR - 40));
    rotate(noise(i * 0.3, i * 0.7) * TWO_PI);
    ellipse(0, 0, random(4, 9), random(2.5, 5));
    pop();
  }
}

function drawFireflies() {
  noStroke();
  for (let i = 0; i < 60; i++) {
    const x = random(W * 0.1, W * 0.9);
    const y = random(350, HOR - 60);
    const r = random(2, 5);
    fill(255, 230, 160, 26);
    circle(x, y, r * 7);
    fill(255, 240, 190, 220);
    circle(x, y, r * 2);
  }
}

function drawReeds() {
  strokeCap(ROUND);
  for (let side = 0; side < 2; side++) {
    for (let i = 0; i < 13; i++) {
      const x0 = side === 0 ? random(-30, 300) : random(W - 300, W + 30);
      const h = random(170, 430);
      const tipX = x0 + random(-80, 80);
      const tipY = H - h;
      noFill();
      stroke(9, 6, 20);
      strokeWeight(random(3, 8));
      beginShape();
      vertex(x0, H + 10);
      quadraticVertex(x0 + random(-35, 35), H - h * 0.55, tipX, tipY);
      endShape();
      if (random() < 0.45) {
        noStroke();
        fill(12, 8, 24);
        ellipse(tipX, tipY - 16, random(10, 15), random(28, 40));
        fill(60, 40, 30, 160);
        ellipse(tipX, tipY - 34, 5, 10);
      }
    }
  }
}

function drawVignette() {
  const c = drawingContext;
  const g = c.createRadialGradient(W / 2, H * 0.42, H * 0.25, W / 2, H * 0.5, H * 0.85);
  g.addColorStop(0, 'rgba(8, 6, 20, 0)');
  g.addColorStop(1, 'rgba(8, 6, 20, 0.55)');
  c.fillStyle = g;
  c.fillRect(0, 0, W, H);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function heartPath(s) {
  const p = new Path2D();
  p.moveTo(0, 0.34 * s);
  p.bezierCurveTo(-1.18 * s, -0.12 * s, -0.62 * s, -1.08 * s, 0, -0.5 * s);
  p.bezierCurveTo(0.62 * s, -1.08 * s, 1.18 * s, -0.12 * s, 0, 0.34 * s);
  p.closePath();
  return p;
}

function drawHill(baseY, amp, col, seedOff, freq) {
  fill(col);
  noStroke();
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 14) {
    const y = baseY
      + (noise(x * freq + seedOff, 0.7) - 0.5) * 2 * amp
      + (noise(x * freq * 2.3 + seedOff * 2.0, 3.1) - 0.5) * amp * 0.5;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);
}

function draw() {
  const ctx = drawingContext;
  const W = width, H = height;
  const CX = W / 2, CY = 930, S = 430;

  // background gradient
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.0, '#101030');
  g.addColorStop(0.45, '#241b4d');
  g.addColorStop(0.75, '#3d2350');
  g.addColorStop(1.0, '#55284e');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // stars
  for (let i = 0; i < 150; i++) {
    const x = random(W), y = random(0, H * 0.62), r = random(0.6, 2.4);
    const a = random(0.15, 0.85), t = random();
    ctx.fillStyle = t < 0.5 ? `rgba(255,255,255,${a})`
      : t < 0.75 ? `rgba(190,225,255,${a})` : `rgba(255,215,235,${a})`;
    ctx.beginPath(); ctx.arc(x, y, r, 0, TWO_PI); ctx.fill();
  }
  for (let i = 0; i < 8; i++) {
    const x = random(W), y = random(0, H * 0.5);
    ctx.save();
    ctx.shadowColor = 'rgba(255,255,255,0.9)';
    ctx.shadowBlur = 18;
    ctx.fillStyle = 'rgba(255,255,255,0.95)';
    ctx.beginPath(); ctx.arc(x, y, random(1.8, 3), 0, TWO_PI); ctx.fill();
    ctx.restore();
  }

  // ambient glow behind the heart
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const rg = ctx.createRadialGradient(CX, CY - 40, 60, CX, CY - 40, 950);
  rg.addColorStop(0, 'rgba(255,190,150,0.30)');
  rg.addColorStop(0.5, 'rgba(190,150,255,0.16)');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();

  // light rays
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  ctx.translate(CX, CY - 40);
  for (let i = 0; i < 14; i++) {
    ctx.save();
    ctx.rotate(i * (TWO_PI / 14) + 0.13);
    const lg = ctx.createLinearGradient(0, 0, 1500, 0);
    lg.addColorStop(0, 'rgba(255,225,190,0.10)');
    lg.addColorStop(1, 'rgba(255,225,190,0)');
    ctx.fillStyle = lg;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(1500, -26); ctx.lineTo(1500, 26);
    ctx.closePath(); ctx.fill();
    ctx.restore();
  }
  ctx.restore();

  // halo rings
  ctx.save();
  ctx.strokeStyle = 'rgba(255,240,220,0.14)';
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.ellipse(CX, CY - 40, 600, 560, 0, 0, TWO_PI); ctx.stroke();
  ctx.strokeStyle = 'rgba(200,190,255,0.10)';
  ctx.beginPath(); ctx.ellipse(CX, CY - 40, 705, 665, 0, 0, TWO_PI); ctx.stroke();
  ctx.restore();

  // hills
  drawHill(1560, 110, '#2a1d47', 7.3, 0.0016);
  drawHill(1730, 90, '#150f2e', 11.1, 0.0021);

  // distant lights on the hills
  for (let i = 0; i < 26; i++) {
    const x = random(W), y = random(1560, 1900);
    ctx.save();
    ctx.shadowColor = 'rgba(255,200,140,0.9)';
    ctx.shadowBlur = 10;
    ctx.fillStyle = `rgba(255,205,150,${random(0.25, 0.7)})`;
    ctx.beginPath(); ctx.arc(x, y, random(1, 2.6), 0, TWO_PI); ctx.fill();
    ctx.restore();
  }

  // heart: warm left half
  const hp = heartPath(S);
  ctx.save();
  ctx.translate(CX, CY);
  ctx.beginPath(); ctx.rect(-W, -H, W, 2 * H); ctx.clip();
  ctx.shadowColor = 'rgba(255,120,140,0.85)';
  ctx.shadowBlur = 90;
  const gw = ctx.createLinearGradient(0, -S * 1.1, 0, S * 0.5);
  gw.addColorStop(0, '#ffe6b8');
  gw.addColorStop(0.45, '#ffb27d');
  gw.addColorStop(1, '#ff5e7e');
  ctx.fillStyle = gw;
  ctx.fill(hp);
  ctx.restore();

  // heart: cool right half
  ctx.save();
  ctx.translate(CX, CY);
  ctx.beginPath(); ctx.rect(0, -H, W, 2 * H); ctx.clip();
  ctx.shadowColor = 'rgba(130,140,255,0.85)';
  ctx.shadowBlur = 90;
  const gc = ctx.createLinearGradient(0, -S * 1.1, 0, S * 0.5);
  gc.addColorStop(0, '#d6f4ff');
  gc.addColorStop(0.45, '#9fb8ff');
  gc.addColorStop(1, '#7a5cf0');
  ctx.fillStyle = gc;
  ctx.fill(hp);
  ctx.restore();

  // inner shading and center glow, clipped to the heart
  ctx.save();
  ctx.translate(CX, CY);
  ctx.clip(hp);
  const ov = ctx.createLinearGradient(0, -S * 1.1, 0, S * 0.45);
  ov.addColorStop(0, 'rgba(255,255,255,0.35)');
  ov.addColorStop(0.5, 'rgba(255,255,255,0)');
  ov.addColorStop(1, 'rgba(40,10,60,0.35)');
  ctx.fillStyle = ov;
  ctx.fillRect(-S * 1.3, -S * 1.3, S * 2.6, S * 2.6);
  ctx.globalCompositeOperation = 'screen';
  const cg = ctx.createRadialGradient(0, -S * 0.35, 10, 0, -S * 0.35, S * 0.95);
  cg.addColorStop(0, 'rgba(255,255,255,0.55)');
  cg.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = cg;
  ctx.fillRect(-S * 1.3, -S * 1.3, S * 2.6, S * 2.6);
  ctx.restore();

  // glowing outline
  ctx.save();
  ctx.translate(CX, CY);
  ctx.shadowColor = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 25;
  ctx.strokeStyle = 'rgba(255,255,255,0.5)';
  ctx.lineWidth = 4;
  ctx.stroke(hp);
  ctx.restore();

  // seam of light where the two halves meet
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const sg = ctx.createLinearGradient(CX - 90, 0, CX + 90, 0);
  sg.addColorStop(0, 'rgba(255,244,214,0)');
  sg.addColorStop(0.5, 'rgba(255,244,214,0.55)');
  sg.addColorStop(1, 'rgba(255,244,214,0)');
  ctx.fillStyle = sg;
  ctx.fillRect(CX - 90, CY - S * 1.15, 180, S * 1.6);
  const sg2 = ctx.createLinearGradient(CX - 14, 0, CX + 14, 0);
  sg2.addColorStop(0, 'rgba(255,255,255,0)');
  sg2.addColorStop(0.5, 'rgba(255,255,255,0.85)');
  sg2.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = sg2;
  ctx.fillRect(CX - 14, CY - S * 1.05, 28, S * 1.45);
  ctx.restore();

  // orbiting particles
  for (let i = 0; i < 110; i++) {
    const a = random(TWO_PI);
    const rx = random(480, 770), ry = rx * random(0.72, 1.0);
    const px = CX + cos(a) * rx, py = CY - 40 + sin(a) * ry;
    const warm = random() < 0.5;
    const col = warm
      ? `rgba(255,${floor(random(170, 220))},${floor(random(140, 190))}`
      : `rgba(${floor(random(150, 190))},${floor(random(180, 230))},255`;
    const al = random(0.25, 0.85), r = random(1.2, 4.2);
    const glow = random() < 0.18;
    ctx.save();
    if (glow) { ctx.shadowColor = col + `,${al})`; ctx.shadowBlur = 14; }
    ctx.fillStyle = col + `,${al})`;
    ctx.beginPath(); ctx.arc(px, py, r, 0, TWO_PI); ctx.fill();
    ctx.restore();
  }

  // rising sparks
  for (let i = 0; i < 90; i++) {
    const x = CX + random(-540, 540) + sin(random(TWO_PI)) * 16;
    const y = random(CY - S * 1.2, CY + S * 0.7);
    const warm = random() < 0.5;
    const al = random(0.15, 0.6);
    ctx.fillStyle = warm ? `rgba(255,210,170,${al})` : `rgba(190,215,255,${al})`;
    ctx.beginPath(); ctx.arc(x, y, random(0.8, 2.6), 0, TWO_PI); ctx.fill();
  }

  // floating tiny hearts
  for (let i = 0; i < 14; i++) {
    const x = random(W * 0.1, W * 0.9), y = random(H * 0.12, H * 0.78);
    const s = random(7, 22), rot = random(-0.6, 0.6);
    const warm = random() < 0.5;
    ctx.save();
    ctx.translate(x, y); ctx.rotate(rot);
    ctx.globalAlpha = random(0.35, 0.8);
    ctx.fillStyle = warm ? '#ffb3c1' : '#a8c8ff';
    if (random() < 0.4) { ctx.shadowColor = ctx.fillStyle; ctx.shadowBlur = 12; }
    ctx.fill(heartPath(s));
    ctx.restore();
  }

  // painterly grain
  for (let i = 0; i < 2600; i++) {
    const x = random(W), y = random(H);
    ctx.fillStyle = random() < 0.5
      ? `rgba(255,255,255,${random(0.01, 0.05)})`
      : `rgba(0,0,0,${random(0.02, 0.06)})`;
    ctx.fillRect(x, y, random(1, 2.2), random(1, 2.2));
  }

  // vignette
  const vg = ctx.createRadialGradient(CX, CY - 100, 600, CX, CY - 100, 1300);
  vg.addColorStop(0, 'rgba(8,6,24,0)');
  vg.addColorStop(1, 'rgba(8,6,24,0.6)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  drawSky();
  drawStars();
  drawShootingStar();
  drawHeartMoon();
  drawHills();
  drawGrass();
  drawCoupleGlow();
  drawCouple();
  drawRisingHearts();
  drawFireflies();
  vignette();
}

function drawSky() {
  let ctx = drawingContext;
  let g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#060818');
  g.addColorStop(0.45, '#191238');
  g.addColorStop(0.75, '#3a2154');
  g.addColorStop(1, '#5e3057');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 340; i++) {
    let x = random(width);
    let y = random(height * 0.7);
    let r = random(0.6, 2.3);
    let a = random(90, 255);
    fill(255, 248, 230, a);
    circle(x, y, r * 2);
    if (r > 1.7) {
      stroke(255, 248, 230, a * 0.45);
      strokeWeight(1);
      line(x - r * 3.2, y, x + r * 3.2, y);
      line(x, y - r * 3.2, x, y + r * 3.2);
      noStroke();
    }
  }
}

function drawShootingStar() {
  let ctx = drawingContext;
  let g = ctx.createLinearGradient(1180, 140, 1500, 310);
  g.addColorStop(0, 'rgba(255,255,255,0)');
  g.addColorStop(0.65, 'rgba(255,250,235,0.55)');
  g.addColorStop(1, 'rgba(255,255,255,0.95)');
  ctx.strokeStyle = g;
  ctx.lineWidth = 3;
  ctx.lineCap = 'ROUND';
  ctx.beginPath();
  ctx.moveTo(1180, 140);
  ctx.lineTo(1500, 310);
  ctx.stroke();
  let rg = ctx.createRadialGradient(1500, 310, 0, 1500, 310, 30);
  rg.addColorStop(0, 'rgba(255,255,255,0.95)');
  rg.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = rg;
  ctx.beginPath();
  ctx.arc(1500, 310, 60, 0, TWO_PI);
  ctx.fill();
}

function heartPath(cx, cy, s) {
  beginShape();
  let n = 140;
  for (let i = 0; i <= n; i++) {
    let t = (i / n) * TWO_PI;
    let x = 16 * pow(sin(t), 3);
    let y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t);
    vertex(cx + x * s, cy - y * s);
  }
  endShape(CLOSE);
}

function drawHeartMoon() {
  let cx = width / 2;
  let cy = 620;
  let s = 15;
  let ctx = drawingContext;
  noStroke();
  let halo = ctx.createRadialGradient(cx, cy, 30, cx, cy, 640);
  halo.addColorStop(0, 'rgba(255,175,195,0.5)');
  halo.addColorStop(0.45, 'rgba(255,130,170,0.2)');
  halo.addColorStop(1, 'rgba(255,130,170,0)');
  ctx.fillStyle = halo;
  ctx.beginPath();
  ctx.arc(cx, cy, 1280, 0, TWO_PI);
  ctx.fill();

  let layers = [
    [1.28, 255, 110, 150, 36],
    [1.14, 255, 140, 175, 65],
    [1.02, 255, 180, 200, 170],
    [0.94, 255, 214, 214, 235],
    [0.86, 255, 242, 228, 255]
  ];
  for (let i = 0; i < layers.length; i++) {
    let L = layers[i];
    fill(L[1], L[2], L[3], L[4]);
    heartPath(cx, cy, s * L[0]);
  }
  fill(255, 255, 255, 90);
  ellipse(cx - s * 5.5, cy - s * 6, s * 6, s * 3.4, -0.5);
}

function hillY(x, base, amp, zoff) {
  return base + noise(x * 0.0016, zoff) * amp - amp / 2;
}

function drawHills() {
  noStroke();
  fill('#2b1d4e');
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 12) vertex(x, hillY(x, 1450, 100, 1.2));
  vertex(width, height);
  endShape(CLOSE);

  fill('#1d1440');
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 12) vertex(x, hillY(x, 1540, 130, 7.9));
  vertex(width, height);
  endShape(CLOSE);

  fill('#0f0a20');
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 12) vertex(x, hillY(x, 1630, 150, 3.7));
  vertex(width, height);
  endShape(CLOSE);
}

function drawGrass() {
  stroke('#070410');
  strokeWeight(5);
  strokeCap(ROUND);
  noFill();
  for (let i = 0; i < 46; i++) {
    let x = random(width);
    let baseY = height - random(0, 26);
    let hgt = random(36, 120);
    let bend = random(-46, 46);
    beginShape();
    vertex(x, baseY);
    quadraticVertex(x + bend * 0.3, baseY - hgt * 0.62, x + bend, baseY - hgt);
    endShape();
  }
  noStroke();
}

function coupleGeom() {
  let x1 = 695, x2 = 905;
  let y1 = hillY(x1, 1630, 150, 3.7);
  let y2 = hillY(x2, 1630, 150, 3.7);
  let hx = (x1 + x2) / 2;
  let hy = (y1 + y2) / 2 - 96;
  return { x1: x1, x2: x2, y1: y1, y2: y2, hx: hx, hy: hy };
}

function drawCoupleGlow() {
  let g = coupleGeom();
  let ctx = drawingContext;
  let my = (g.y1 + g.y2) / 2 - 110;
  let rg = ctx.createRadialGradient(g.hx, my, 20, g.hx, my, 430);
  rg.addColorStop(0, 'rgba(255,150,180,0.22)');
  rg.addColorStop(1, 'rgba(255,150,180,0)');
  ctx.fillStyle = rg;
  ctx.beginPath();
  ctx.arc(g.hx, my, 860, 0, TWO_PI);
  ctx.fill();
}

function drawFigure(x, feetY, h, lean, handX, handY) {
  let c = color(7, 5, 14);
  let headX = x + lean * 17;
  let headY = feetY - h;
  noStroke();
  fill(c);
  beginShape();
  vertex(x - 20, feetY);
  bezierVertex(x - 34, feetY - h * 0.5, x - 26, feetY - h * 0.82, x - 15, feetY - h * 0.9);
  bezierVertex(x - 9, feetY - h * 0.98, x + 9, feetY - h * 0.98, x + 15, feetY - h * 0.9);
  bezierVertex(x + 26, feetY - h * 0.82, x + 34, feetY - h * 0.5, x + 20, feetY);
  endShape(CLOSE);
  circle(headX, headY, 46);

  stroke(c);
  strokeWeight(11);
  strokeCap(ROUND);
  noFill();
  let shX = x + lean * 5;
  let shY = feetY - h * 0.85;
  beginShape();
  vertex(shX + lean * 9, shY);
  quadraticVertex((shX + handX) / 2 + lean * 6, shY + 20, handX, handY);
  endShape();
  beginShape();
  vertex(shX - lean * 9, shY);
  quadraticVertex(shX - lean * 18, shY + 34, x - lean * 5, feetY - h * 0.42);
  endShape();
  noStroke();
}

function drawCouple() {
  let g = coupleGeom();
  let c = color(7, 5, 14);
  drawFigure(g.x1, g.y1, 182, 1, g.hx, g.hy);
  drawFigure(g.x2, g.y2, 158, -1, g.hx, g.hy);

  let ctx = drawingContext;
  let rg = ctx.createRadialGradient(g.hx, g.hy, 2, g.hx, g.hy, 70);
  rg.addColorStop(0, 'rgba(255,185,205,0.85)');
  rg.addColorStop(1, 'rgba(255,185,205,0)');
  ctx.fillStyle = rg;
  ctx.beginPath();
  ctx.arc(g.hx, g.hy, 140, 0, TWO_PI);
  ctx.fill();
  noStroke();
  fill(c);
  circle(g.hx, g.hy, 17);
}

function drawRisingHearts() {
  let g = coupleGeom();
  noStroke();
  for (let i = 0; i < 30; i++) {
    let t = i / 29;
    let y = lerp(g.hy - 30, 900, t) + random(-12, 12);
    let sway = sin(t * PI) * 110 + (noise(i * 0.55) - 0.5) * 90;
    let x = g.hx + sway + random(-8, 8);
    let s = lerp(2.0, 6.5, t) * random(0.7, 1.25);
    let a = lerp(240, 30, t) * random(0.55, 1);
    fill(255, 165, 190, a);
    heartPath(x, y, s);
  }
}

function drawFireflies() {
  let ctx = drawingContext;
  noStroke();
  for (let i = 0; i < 42; i++) {
    let x = random(width);
    let y = random(height * 0.42, height * 0.96);
    let r = random(1.4, 3.6);
    let a = random(100, 230);
    let rg = ctx.createRadialGradient(x, y, 0, x, y, r * 7);
    rg.addColorStop(0, 'rgba(255,222,140,' + (a / 255 * 0.75).toFixed(3) + ')');
    rg.addColorStop(1, 'rgba(255,222,140,0)');
    ctx.fillStyle = rg;
    ctx.beginPath();
    ctx.arc(x, y, r * 14, 0, TWO_PI);
    ctx.fill();
    fill(255, 238, 175, a);
    circle(x, y, r * 2);
  }
}

function vignette() {
  let ctx = drawingContext;
  let rg = ctx.createRadialGradient(width / 2, height / 2, height * 0.35, width / 2, height / 2, height * 0.75);
  rg.addColorStop(0, 'rgba(0,0,0,0)');
  rg.addColorStop(1, 'rgba(5,3,15,0.55)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, width, height);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  backgroundGradient();
  drawStars();
  drawMoonGlow();
  drawHeartGlow();
  drawHeartParticles();
  drawRisingStream();
  drawPetals();
  drawBirds();
  drawHand(false);
  drawHand(true);
  drawOrb();
  drawSparks();
  drawVignette();
}

function backgroundGradient() {
  const stops = [
    [0.00, color(16, 11, 38)],
    [0.32, color(52, 30, 82)],
    [0.55, color(122, 58, 108)],
    [0.78, color(205, 108, 138)],
    [1.00, color(246, 183, 143)]
  ];
  for (let y = 0; y < height; y++) {
    const t = y / height;
    let c = stops[stops.length - 1][1];
    for (let i = 0; i < stops.length - 1; i++) {
      if (t >= stops[i][0] && t <= stops[i + 1][0]) {
        const f = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
        c = lerpColor(stops[i][1], stops[i + 1][1], f);
        break;
      }
    }
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    const x = random(width);
    const y = random(0, 1150);
    const fade = 1 - y / 1300;
    const a = random(50, 230) * fade;
    const r = random(0.8, 2.6);
    if (random() < 0.06) {
      fill(255, 240, 255, a * 0.25);
      circle(x, y, r * 7);
    }
    fill(255, 240, 255, a);
    circle(x, y, r * 2);
  }
}

function drawMoonGlow() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 660, 0, 800, 660, 560);
  g.addColorStop(0, 'rgba(255, 216, 190, 0.32)');
  g.addColorStop(0.5, 'rgba(255, 190, 180, 0.12)');
  g.addColorStop(1, 'rgba(255, 180, 180, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(800, 660, 560, 0, TWO_PI);
  ctx.fill();
}

function heartXY(t, s, cx, cy) {
  const x = 16 * pow(sin(t), 3);
  const y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t);
  return [cx + x * s, cy - y * s];
}

function drawHeartGlow() {
  noFill();
  const passes = [[26, 10], [12, 22], [4, 60]];
  for (const p of passes) {
    stroke(255, 170, 185, p[1]);
    strokeWeight(p[0]);
    beginShape();
    for (let i = 0; i <= 120; i++) {
      const pt = heartXY((i / 120) * TWO_PI, 17, 800, 680);
      curveVertex(pt[0], pt[1]);
    }
    endShape();
  }
  noStroke();
}

function drawHeartParticles() {
  const palette = [[255, 110, 150], [255, 205, 130], [255, 245, 230], [255, 160, 175], [255, 140, 190]];
  noStroke();
  for (let i = 0; i < 170; i++) {
    const t = (i / 170) * TWO_PI + random(-0.03, 0.03);
    const s = 15 * random(0.9, 1.1);
    const pt = heartXY(t, s, 800, 680);
    const x = pt[0] + random(-7, 7);
    const y = pt[1] + random(-7, 7);
    const c = palette[floor(random(palette.length))];
    const r = random(1.6, 4.6);
    fill(c[0], c[1], c[2], random(30, 70));
    circle(x, y, r * 5);
    fill(c[0], c[1], c[2], random(150, 255));
    circle(x, y, r * 2);
  }
  for (let i = 0; i < 70; i++) {
    const t = random(TWO_PI);
    const s = 8 * random(0.85, 1.15);
    const pt = heartXY(t, s, 800, 680);
    fill(255, 240, 220, random(120, 230));
    circle(pt[0] + random(-4, 4), pt[1] + random(-4, 4), random(1.2, 3));
  }
}

function drawRisingStream() {
  noStroke();
  for (let i = 0; i < 80; i++) {
    const t = i / 80;
    const y = lerp(1105, 860, t) + random(-14, 14);
    const wob = (noise(i * 0.12, 3.7) - 0.5) * 260 * (1 - t * 0.4);
    const x = 800 + wob + random(-10, 10);
    const r = lerp(5.5, 1.2, t) * random(0.5, 1.3);
    const a = lerp(220, 30, t);
    const c = random() < 0.6 ? [255, 210, 150] : [255, 150, 180];
    fill(c[0], c[1], c[2], a * 0.25);
    circle(x, y, r * 3.2);
    fill(c[0], c[1], c[2], a);
    circle(x, y, r);
  }
}

function drawPetals() {
  noStroke();
  for (let i = 0; i < 24; i++) {
    const s = random(7, 18);
    push();
    translate(random(150, 1450), random(300, 1300));
    rotate(random(TWO_PI));
    fill(255, random(140, 190), random(160, 200), random(50, 130));
    ellipse(0, 0, s, s * 0.55);
    pop();
  }
}

function drawBirds() {
  stroke(20, 12, 40, 200);
  strokeWeight(4);
  strokeCap(ROUND);
  noFill();
  bird(430, 380, 1);
  bird(1150, 300, 0.8);
  bird(1240, 420, 0.6);
  noStroke();
}

function bird(x, y, s) {
  push();
  translate(x, y);
  scale(s);
  arc(-14, 0, 28, 28, PI, TWO_PI);
  arc(14, 0, 28, 28, PI, TWO_PI);
  pop();
}

function handPath() {
  beginShape();
  curveVertex(-900, 200);
  curveVertex(-900, 200);
  curveVertex(-900, -10);
  curveVertex(-740, -45);
  curveVertex(-560, -75);
  curveVertex(-430, -93);
  curveVertex(-300, -100);
  curveVertex(-180, -96);
  curveVertex(-80, -88);
  curveVertex(-18, -72);
  curveVertex(6, -52);
  curveVertex(-2, -28);
  curveVertex(-32, -18);
  curveVertex(-115, -8);
  curveVertex(-195, 0);
  curveVertex(-238, 26);
  curveVertex(-282, 76);
  curveVertex(-306, 103);
  curveVertex(-273, 119);
  curveVertex(-224, 81);
  curveVertex(-335, 101);
  curveVertex(-500, 130);
  curveVertex(-720, 165);
  curveVertex(-900, 200);
  curveVertex(-900, 200);
  endShape(CLOSE);
}

function drawHand(mirror) {
  push();
  if (mirror) {
    translate(800, 1198);
    scale(-1, 1);
  } else {
    translate(800, 1152);
  }
  rotate(-0.15);
  push();
  translate(12, -8);
  fill(255, 185, 135, 65);
  handPath();
  pop();
  fill(14, 9, 30);
  handPath();
  stroke(6, 4, 16, 160);
  strokeWeight(3.2);
  line(-168, -88, -30, -63);
  line(-162, -70, -26, -45);
  line(-156, -52, -28, -27);
  noStroke();
  pop();
}

function drawOrb() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 1120, 0, 800, 1120, 320);
  g.addColorStop(0, 'rgba(255, 252, 240, 0.95)');
  g.addColorStop(0.12, 'rgba(255, 226, 175, 0.6)');
  g.addColorStop(0.4, 'rgba(255, 175, 160, 0.22)');
  g.addColorStop(1, 'rgba(255, 160, 160, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(800, 1120, 320, 0, TWO_PI);
  ctx.fill();
  noStroke();
  fill(255, 250, 235, 230);
  circle(800, 1120, 26);
  fill(255, 255, 255, 255);
  circle(800, 1120, 12);
}

function drawSparks() {
  noStroke();
  for (let i = 0; i < 50; i++) {
    const a = random(TWO_PI);
    const r = random(15, 150);
    const x = 800 + cos(a) * r;
    const y = 1120 + sin(a) * r * 0.85;
    const c = random() < 0.5 ? [255, 220, 160] : [255, 170, 190];
    const al = random(70, 240);
    fill(c[0], c[1], c[2], al * 0.25);
    circle(x, y, random(6, 16));
    fill(c[0], c[1], c[2], al);
    circle(x, y, random(1.2, 3.6));
  }
  stroke(255, 240, 210, 200);
  strokeWeight(1.6);
  for (let i = 0; i < 8; i++) {
    const a = random(TWO_PI);
    const r = random(20, 110);
    const x = 800 + cos(a) * r;
    const y = 1120 + sin(a) * r;
    const l = random(6, 14);
    line(x - l, y, x + l, y);
    line(x, y - l, x, y + l);
  }
  noStroke();
}

function drawVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 980, 350, 800, 1000, 1350);
  g.addColorStop(0, 'rgba(8, 5, 22, 0)');
  g.addColorStop(1, 'rgba(8, 5, 22, 0.52)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

// p5.js 1.11 — image fixe, sans ressources externes.

function setup() {
