  fond();
  lumiere();

  // Traces antérieures : la peinture garde mémoire des gestes.
  ruban([
    [1030, 265, 525, 210, 235, 665, 385, 1020],
    [385, 1020, 520, 1390, 310, 1650, 920, 1800]
  ], 180, [
    [36, 63, 66], [55, 76, 73], [81, 91, 79]
  ], 11, 0.52);

  ruban([
    [575, 300, 1100, 190, 1430, 650, 1230, 1065],
    [1230, 1065, 1080, 1350, 1370, 1640, 680, 1825]
  ], 165, [
    [76, 48, 47], [107, 61, 49], [133, 81, 58]
  ], 23, 0.48);

  // Deux matières distinctes, deux façons de faire place.
  ruban([
    [1005, 290, 590, 240, 330, 560, 440, 930],
    [440, 930, 500, 1310, 355, 1575, 890, 1745]
  ], 258, [
    [31, 76, 81],
    [46, 111, 111],
    [83, 143, 135],
    [137, 169, 148],
    [188, 188, 153]
  ], 41, 1);

  ruban([
    [620, 340, 1070, 235, 1370, 670, 1155, 1010],
    [1155, 1010, 1025, 1260, 1260, 1555, 715, 1760]
  ], 242, [
    [105, 48, 45],
    [151, 65, 49],
    [182, 88, 59],
    [207, 123, 79],
    [222, 164, 111]
  ], 73, 1);

  // Un peu de la couleur de l'autre demeure sur chaque rive.
  ruban([
    [1100, 532, 1200, 720, 1190, 820, 1105, 984]
  ], 38, [
    [80, 125, 118], [131, 153, 127], [173, 166, 131]
  ], 91, 0.68);

  ruban([
    [480, 1145, 450, 1350, 510, 1550, 697, 1630]
  ], 34, [
    [147, 95, 64], [185, 133, 85], [203, 163, 109]
  ], 109, 0.72);

  liens();
  eclats();
