}

function fond() {
  noStroke();

  // Sous-couche irrégulière, à la manière de lavis absorbés.
  for (let i = 0; i < 16000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0019, y * 0.0019);
    let d = dist(x, y, 800, 1010) / 1200;
    if (n > 0.52) {
      fill(118, 102, 72, random(2, 8) * (1.1 - 0.4 * d));
    } else {
      fill(9, 24, 35, random(3, 10));
    }
    let s = random(12, 85);
    ellipse(x, y, s, s * random(0.35, 1.5));
  }

  // Fibres visibles avant les couches opaques.
  for (let i = 0; i < 19000; i++) {
    let x = random(width);
    let y = random(height);
    stroke(167, 157, 127, random(3, 13));
    strokeWeight(random(0.4, 1.1));
    line(x, y, x + random(-1, 1), y + random(2, 9));
  }

  noFill();
  for (let i = 0; i < 85; i++) {
    stroke(8, 19, 28, 1.6);
    strokeWeight(3);
    rect(i * 2, i * 2, width - i * 4, height - i * 4);
  }
}

function lumiere() {
  noStroke();

  // Une réserve lumineuse, ni soleil ni objet possédé.
  for (let k = 0; k < 100; k++) {
    let r = map(k, 0, 99, 1.42, 0.025);
    let t = k / 99;
    fill(
      lerp(170, 249, t),
      lerp(135, 231, t),
      lerp(78, 184, t),
      lerp(5, 22, t)
    );

    beginShape();
    for (let j = 0; j < 160; j++) {
      let a = TWO_PI * j / 160;
      let wobble = 1 + 0.055 * sin(3 * a + 1.2)
        + 0.035 * sin(7 * a - 0.4);
      let x = 805 + sin(a) * 282 * r * wobble;
      let y = 1005 + cos(a) * 511 * r * wobble;
      x += 37 * cos(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  for (let i = 0; i < 15000; i++) {
    let x = random(380, 1240);
    let y = random(330, 1680);
    let q = sq((x - 805) / 300) + sq((y - 1005) / 530);
    if (q < 1.25 && random() < pow(max(0, 1 - q / 1.25), 0.6)) {
      if (random() < 0.62) fill(250, 230, 180, random(5, 23));
      else fill(132, 101, 59, random(4, 15));
      let s = random(0.7, 4);
      ellipse(x, y, s, s * random(0.4, 1.8));
    }
  }
}

function pointChemin(segments, t) {
  let z = constrain(t, 0, 0.999999) * segments.length;
  let index = floor(z);
  let u = z - index;
  let s = segments[index];

  let x = bezierPoint(s[0], s[2], s[4], s[6], u);
  let y = bezierPoint(s[1], s[3], s[5], s[7], u);
  let dx = bezierTangent(s[0], s[2], s[4], s[6], u);
  let dy = bezierTangent(s[1], s[3], s[5], s[7], u);
  let m = sqrt(dx * dx + dy * dy) || 1;

  return { x, y, nx: -dy / m, ny: dx / m };
}

function epaisseur(t, largeur, identite) {
  return largeur
    * pow(max(0, sin(PI * t)), 0.48)
    * (0.83 + 0.22 * noise(t * 5, identite));
}

function teinte(palette, t) {
  let z = constrain(t, 0, 0.99999) * (palette.length - 1);
  let i = floor(z);
  let f = z - i;
  return [
    lerp(palette[i][0], palette[i + 1][0], f),
    lerp(palette[i][1], palette[i + 1][1], f),
    lerp(palette[i][2], palette[i + 1][2], f)
  ];
}

function ruban(segments, largeur, palette, identite, opacite) {
  let count = 245;
  let points = [];
  for (let j = 0; j <= count; j++) {
    let t = j / count;
    let p = pointChemin(segments, t);
    p.w = epaisseur(t, largeur, identite);
    points.push(p);
  }

  // Corps de peinture, contour volontairement imparfait.
  let base = palette[1];
  noStroke();
  fill(base[0], base[1], base[2], 225 * opacite);
  beginShape();
  for (let j = 0; j <= count; j++) {
    let p = points[j];
    let d = p.w * (0.5 + 0.035 * noise(j * 0.14, identite));
    vertex(p.x + p.nx * d, p.y + p.ny * d);
  }
  for (let j = count; j >= 0; j--) {
    let p = points[j];
    let d = p.w * (0.5 + 0.045 * noise(j * 0.12, identite + 4));
    vertex(p.x - p.nx * d, p.y - p.ny * d);
  }
  endShape(CLOSE);

  // Chaque filament suit le geste, mais pas exactement son voisin.
  noFill();
  for (let i = 0; i < 260; i++) {
    let v = random(-0.52, 0.52);
    let valeur = constrain(
      0.47 + v * 0.60 + random(-0.30, 0.30), 0, 1
    );
    let c = teinte(palette, valeur);
    stroke(c[0], c[1], c[2], random(55, 145) * opacite);
    strokeWeight(random(0.65, 3.7));

    let start = floor(random(0, 14));
    let stop = count - floor(random(0, 17));
    beginShape();
    for (let j = start; j <= stop; j++) {
      let p = points[j];
      let drift = (noise(j * 0.037, i * 0.12, identite) - 0.5) * 14;
      let d = p.w * v + drift;
      vertex(p.x + p.nx * d, p.y + p.ny * d);
    }
    endShape();
  }

  // Dépôts et petits manques du pinceau sec.
  noStroke();
  for (let i = 0; i < 5100; i++) {
    let t = random(0.02, 0.98);
    let p = pointChemin(segments, t);
    let w = epaisseur(t, largeur, identite);
    let v = random(-0.51, 0.51);
    let c = teinte(palette, random());
    fill(c[0], c[1], c[2], random(15, 80) * opacite);
    let s = random(0.8, 4.2);
    ellipse(p.x + p.nx * w * v, p.y + p.ny * w * v,
      s, s * random(0.5, 2.3));
  }
}

function liens() {
  noFill();

  // Un faisceau souple traverse l'espace sans le saturer.
  for (let i = 0; i < 19; i++) {
    let y = 1070 + i * 5.2 + random(-4, 4);
    let x1 = 500 + random(-23, 25);
    let x2 = 1110 + random(-22, 24);
    let sag = 92 + 25 * sin(i * 0.27);

    stroke(65, 53, 37, 28);
    strokeWeight(4.5);
    bezier(x1, y + 3, 700, y + sag + 3,
      920, y + sag - 20, x2, y - 37);

    let c = i % 4 === 0
      ? [242, 216, 159]
      : [192 + random(25), 153 + random(24), 94 + random(23)];
    stroke(c[0], c[1], c[2], random(100, 190));
    strokeWeight(random(0.8, 2.2));
    bezier(x1, y, 700, y + sag,
      920, y + sag - 23, x2, y - 40);
  }

  // Des prolongements libres, plutôt qu'un nœud fermé.
  for (let i = 0; i < 11; i++) {
    stroke(189, 157, 103, random(25, 75));
    strokeWeight(random(0.7, 1.8));
    bezier(
      795 + i * 6, 1700 + random(-15, 15),
      845 + i * 4, 1780,
      715 - i * 7, 1815,
      680 - i * 11, 1870 + random(-14, 14)
    );
  }
}

function eclats() {
  noStroke();

  // Quelques poussières d'or : la lumière déborde son abri.
  for (let i = 0; i < 680; i++) {
    let a = random(TWO_PI);
    let r = random(0.85, 1.32);
    let x = 805 + cos(a) * 352 * r;
    let y = 1020 + sin(a) * 680 * r;
    if (noise(x * 0.008, y * 0.008) > 0.49) {
      fill(224, 186, 119, random(25, 105));
      let s = random(0.6, 3.1);
      ellipse(x, y, s, s * random(0.5, 1.6));
    }
  }

  // Une seule petite présence claire dans l'ouverture.
  for (let i = 0; i < 170; i++) {
    let x = randomGaussian(790, 14);
    let y = randomGaussian(940, 26);
    fill(255, 242, 203, random(8, 33));
    ellipse(x, y, random(1, 4), random(1, 5));
  }
}

function grain() {
  loadPixels();
  let state = 17431;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      state = (Math.imul(state, 1664525) + 1013904223) | 0;
      let n = ((state >>> 24) / 255 - 0.5) * 7;
      let fibre = (x % 3 === 0 ? 0.7 : -0.35)
        + (y % 4 === 0 ? 0.45 : -0.15);
      let k = 4 * (y * width + x);
      pixels[k] += n + fibre;
      pixels[k + 1] += n + fibre;
      pixels[k + 2] += n + fibre;
    }
  }
  updatePixels();
}

// p5.js 1.11 — image fixe, sans ressources externes.

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(19, 29, 42);
  atmosphere();

  glow(795, 920, 1150, 1600, [172, 100, 56], 1.8);
  glow(800, 885, 900, 1360, [235, 179, 101], 2.7);
  glow(795, 855, 660, 1060, [255, 233, 184], 3.4);

  dust(16000, 0, 0, width, height, 0.8);

  // Strates lointaines : les gestes ont commencé avant la rencontre.
  currents();

  pigment(
    leftHalo,
    "#874c3e",
    ["#bc7450", "#ddab70", "#593e46", "#da8456"],
    [165, 270, 1010, 1450],
    1200
  );

  pigment(
    rightHalo,
    "#765039",
    ["#b5794e", "#e3b577", "#583b39", "#d29159"],
    [520, 285, 940, 1420],
    1100
  );

  pigment(
    leftBody,
    "#244e60",
    ["#103342", "#326c79", "#4c8a8c", "#19334c", "#86a39a"],
    [190, 285, 970, 1400],
    2200
  );

  pigment(
    rightBody,
    "#a55a43",
    ["#693c40", "#c57955", "#e4a774", "#894342", "#f1c58d"],
    [520, 300, 910, 1390],
    2300
  );

  bodyGrain(leftBody, [150, 195, 184], 17000);
  bodyGrain(rightBody, [255, 199, 143], 17000);

  veins();
  wovenLight();

  // Un pli bleu passe devant la terre rouge, sans l'effacer.
  pigment(
    lowerFold,
    "#32616a",
    ["#173e50", "#54857e", "#79978a", "#b9b090", "#245464"],
    [370, 1370, 780, 330],
    850
  );

  bodyGrain(lowerFold, [194, 204, 170], 7500);
  lowerFilaments();
  pollen();

  // Grain final : une surface peinte, non un aplat numérique.
  dust(52000, 0, 0, width, height, 0.55);
  edgePatina();
}

function atmosphere() {
  noFill();
  for (let y = 0; y < height; y++) {
    const t = y / height;
    const warmth = exp(-sq((t - 0.79) / 0.27));
    const n = noise(y * 0.005);
    stroke(
      18 + 21 * warmth + n * 5,
      28 + 6 * warmth + n * 5,
      41 + 2 * warmth + n * 5
    );
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 7000; i++) {
    const x = random(width);
    const y = random(height);
    const warm = y > 1300;
    fill(warm ? 156 : 91, warm ? 91 : 112, warm ? 61 : 127, random(2, 9));
    ellipse(x, y, random(5, 75), random(3, 30));
  }
}

function glow(x, y, w, h, rgb, alpha) {
  noStroke();
  for (let i = 100; i > 0; i--) {
    const s = i / 100;
    fill(rgb[0], rgb[1], rgb[2], alpha);
    ellipse(x, y, w * s, h * s);
  }
}

