function clipShape(path) {
  const c = drawingContext;
  c.beginPath();
  path(c);
  c.clip();
}

function pigment(path, base, palette, box, count) {
  const c = drawingContext;
  c.save();
  c.beginPath();
  path(c);
  c.fillStyle = base;
  c.fill();
  c.clip();

  noStroke();
  for (let i = 0; i < count; i++) {
    const x = random(box[0], box[0] + box[2]);
    const y = random(box[1], box[1] + box[3]);
    const col = color(random(palette));
    col.setAlpha(random(8, 35));
    fill(col);

    const a = noise(x * 0.002, y * 0.002) * 4.5 - 2.25;
    push();
    translate(x, y);
    rotate(a);
    ellipse(0, 0, random(20, 150), random(4, 35));
    pop();
  }

  // Marques de brosse longues, avec des soies séparées.
  noFill();
  for (let i = 0; i < count / 3; i++) {
    const x = random(box[0], box[0] + box[2]);
    const y = random(box[1], box[1] + box[3]);
    const a = noise(x * 0.0017, y * 0.0017) * TWO_PI;
    const len = random(20, 145);
    const dx = cos(a) * len;
    const dy = sin(a) * len;
    const col = color(random(palette));
    col.setAlpha(random(12, 45));
    stroke(col);
    strokeWeight(random(0.6, 2));

    for (let j = 0; j < 4; j++) {
      const q = j * 2.1;
      bezier(
        x + q, y,
        x + dx * 0.25 + q, y + dy * 0.2,
        x + dx * 0.7 + q - 8, y + dy * 0.8,
        x + dx + q, y + dy
      );
    }
  }
  c.restore();
}

function bodyGrain(path, rgb, count) {
  const c = drawingContext;
  c.save();
  clipShape(path);
  noStroke();
  for (let i = 0; i < count; i++) {
    const x = random(160, 1440);
    const y = random(270, 1720);
    const n = noise(x * 0.018, y * 0.018);
    fill(rgb[0], rgb[1], rgb[2], random(5, 29) * n);
    rect(x, y, random(0.5, 2.3), random(1, 5));
  }
  c.restore();
}

