function wovenLight() {
  noFill();

  for (let i = 0; i < 100; i++) {
    const t = i / 99;
    const x1 = 468 + 77 * t + random(-9, 9);
    const y1 = 875 + 375 * t + random(-18, 18);
    const x2 = 1139 - 80 * t + random(-9, 9);
    const y2 = 850 + 380 * t + random(-18, 18);
    const sag = 1195 + 320 * t;

    stroke(225, 170, 92, 10);
    strokeWeight(random(5, 10));
    bezier(x1, y1, 580, sag, 963, sag + 75, x2, y2);

    stroke(249, 217, 153, random(27, 88));
    strokeWeight(random(0.5, 1.7));
    bezier(x1, y1, 580, sag, 963, sag + 75, x2, y2);

    // Dépôts discontinus de lumière sur les fibres.
    noStroke();
    for (let k = 0; k < 19; k++) {
      const u = random();
      const x = bezierPoint(x1, 580, 963, x2, u);
      const y = bezierPoint(y1, sag, sag + 75, y2, u);
      fill(255, 232, 175, random(25, 100));
      ellipse(x, y, random(1, 3), random(1, 4));
    }
    noFill();
  }

  // Quelques liens obliques : la trame reste irrégulière et ouverte.
  for (let i = 0; i < 27; i++) {
    const t = i / 26;
    stroke(236, 199, 132, random(18, 47));
    strokeWeight(random(0.4, 1.2));
    bezier(
      473 + t * 30, 1040 + t * 140,
      700, 1290 + t * 110,
      877, 1050 + t * 160,
      1123 - t * 30, 1040 + t * 185
    );
  }
}

