function pollen() {
  noStroke();

  for (let i = 0; i < 1150; i++) {
    const x = randomGaussian(800, 195);
    const y = randomGaussian(1340, 170);
    if (x < 480 || x > 1140 || y < 1010 || y > 1680) continue;

    const r = random(0.7, 3.3);
    fill(245, 202, 124, random(18, 100));
    ellipse(x, y, r, r * random(0.6, 1.9));
  }

  // Dans la clairière centrale, presque rien.
  for (let i = 0; i < 115; i++) {
    const x = randomGaussian(792, 100);
    const y = randomGaussian(858, 145);
    fill(255, 241, 198, random(18, 75));
    ellipse(x, y, random(0.8, 2.4), random(1, 3.5));
  }

  // Petites écailles de pigment métallique, toutes différentes.
  for (let i = 0; i < 62; i++) {
    const side = random() < 0.5;
    const y = random(720, 1290);
    const x = side
      ? 455 + 0.00028 * sq(y - 780) + random(-12, 12)
      : 1141 - 0.00024 * sq(y - 790) + random(-12, 12);
    const r = random(2, 7);

    fill(239, 190, 107, random(65, 170));
    beginShape();
    vertex(x - r, y);
    vertex(x + r * 0.2, y - r * 1.6);
    vertex(x + r * 0.8, y - r * 0.3);
    vertex(x + r * 0.4, y + r);
    vertex(x - r * 0.7, y + r * 0.5);
    endShape(CLOSE);
  }
}

function dust(count, x0, y0, w, h, strength) {
  noStroke();
  for (let i = 0; i < count; i++) {
    const x = random(x0, x0 + w);
    const y = random(y0, y0 + h);
    if (random() < 0.55) {
      fill(241, 219, 176, random(4, 22) * strength);
    } else {
      fill(6, 18, 28, random(5, 26) * strength);
    }
    rect(x, y, random(0.6, 1.8), random(0.7, 3.2));
  }
}

function edgePatina() {
  noFill();
  rectMode(CORNER);
  for (let i = 0; i < 75; i++) {
    stroke(8, 17, 27, 1.8);
    strokeWeight(2);
    rect(i, i, width - 2 * i, height - 2 * i);
  }

  // Trame discrète de la toile.
  strokeWeight(0.5);
  for (let x = 1; x < width; x += 5) {
    stroke(230, 220, 191, 2.5);
    line(x, 0, x, height);
  }
  for (let y = 2; y < height; y += 6) {
    stroke(7, 15, 25, 3.5);
    line(0, y, width, y);
  }
}

// p5.js 1.11 — image fixe, sans ressources externes.
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background("#172d38");
  atmosphere();
  openSpace();

  const left = makeRibbon([
    [704, 427],
    [370, 428], [300, 875], [460, 1210],
    [565, 1485], [861, 1685], [1117, 1415]
  ], 205, 11);

  const right = makeRibbon([
    [1015, 465],
    [1298, 626], [1311, 1010], [1110, 1260],
    [937, 1486], [665, 1653], [481, 1425]
  ], 222, 32);

  const root = makeRibbon([
    [352, 1160],
    [368, 1500], [697, 1760], [991, 1560],
    [1183, 1430], [1190, 1238], [1274, 1135]
  ], 80, 57);

  // Des continuités discrètes, derrière les grandes matières.
  distantThreads();

  paintRibbon(root, [
    "#586252", "#91866a", "#b9a077", "#44594f"
  ]);

  paintRibbon(left, [
    "#245759", "#3a7470", "#76a294",
    "#a7b8a0", "#426e68", "#c0b896"
  ]);

  paintRibbon(right, [
    "#813e3b", "#ae5546", "#d67d59",
    "#e4a77b", "#b8664e", "#edbb8b"
  ]);

  // Un pli transversal passe au-dessus, sans refermer l'ensemble.
  const crossing = makeRibbon([
    [441, 1349],
    [584, 1350], [729, 1596], [938, 1481],
    [1080, 1404], [1149, 1287], [1159, 1190]
  ], 67, 83);

  paintRibbon(crossing, [
    "#a87543", "#c49a5b", "#e6c88a",
    "#f1dca8", "#a8804e"
  ]);

  fineEdges(left, "#d9cfaa", [-0.76, 0.72]);
  fineEdges(right, "#efc69b", [-0.71, 0.79]);
  fineEdges(crossing, "#f7e5b8", [-0.55, 0.48]);

  stitches(left, 0.55, "#d0b57a");
  stitches(right, 0.39, "#edc28a");

  smallPresences();
  surfaceGrain();
}

function atmosphere() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 1600, 2000);
  g.addColorStop(0, "#172a36");
  g.addColorStop(0.47, "#344044");
  g.addColorStop(1, "#162f36");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // Frottis irréguliers : le fond reste une matière.
  noStroke();
  for (let i = 0; i < 12500; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.0027, y * 0.0027);
    if (n > 0.52) fill(137, 113, 82, random(3, 12));
    else fill(16, 37, 47, random(5, 18));

    ellipse(x, y, random(4, 29), random(2, 11));
  }

  for (let i = 0; i < 1700; i++) {
    const x = random(width);
    const y = random(height);
    stroke(172, 160, 131, random(3, 13));
    strokeWeight(random(0.4, 1.7));
    line(x, y, x + random(-4, 7), y + random(7, 38));
  }

  ctx.save();
  ctx.translate(805, 965);
  ctx.scale(1, 1.3);
  const glow = ctx.createRadialGradient(0, 0, 30, 0, 0, 700);
  glow.addColorStop(0, "rgba(219,178,110,0.48)");
  glow.addColorStop(0.52, "rgba(165,134,85,0.20)");
  glow.addColorStop(1, "rgba(165,134,85,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(-760, -760, 1520, 1520);
  ctx.restore();
}

function openSpace() {
  // Une réserve lumineuse, ni personnage ni objet.
  noStroke();
  const outer = color("#766e51");
  const inner = color("#eee0b2");

  for (let k = 0; k < 145; k++) {
    const t = k / 144;
    const r = lerp(1.16, 0.14, t);
    const c = lerpColor(outer, inner, pow(t, 0.58));
    c.setAlpha(38);
    fill(c);

    beginShape();
    for (let j = 0; j < 180; j++) {
      const a = TWO_PI * j / 180;
      const irregular = 1
        + 0.055 * sin(a * 3 + 0.6)
        + 0.035 * sin(a * 5 - 1.2)
        + 0.055 * (noise(cos(a) + 4, sin(a) + 7) - 0.5);
      const x = 805 + cos(a) * 369 * r * irregular;
      const y = 933 + sin(a) * 505 * r * irregular;
      vertex(x + 31 * sin(a), y);
    }
    endShape(CLOSE);
  }

  // De très petites touches empêchent la lumière d'être lisse.
  for (let i = 0; i < 5200; i++) {
    const x = random(495, 1110);
    const y = random(510, 1370);
    const d = sq((x - 805) / 300) + sq((y - 935) / 420);
    if (d < 1) {
      fill(255, 238, 191, random(2, 10) * (1 - d));
      ellipse(x, y, random(1, 8), random(1, 4));
    }
  }
}

function makeRibbon(points, breadth, seed) {
  const result = [];
  const count = (points.length - 1) / 3;
  const steps = 270;

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const segment = min(count - 1, floor(t * count));
    const u = t * count - segment;
    const p = points.slice(segment * 3, segment * 3 + 4);
    const x = bezierPoint(p[0][0], p[1][0], p[2][0], p[3][0], u);
    const y = bezierPoint(p[0][1], p[1][1], p[2][1], p[3][1], u);
    const dx = bezierTangent(p[0][0], p[1][0], p[2][0], p[3][0], u);
    const dy = bezierTangent(p[0][1], p[1][1], p[2][1], p[3][1], u);
    const length = sqrt(dx * dx + dy * dy) || 1;
    const taper = 0.065 + 0.935 * pow(sin(PI * t), 0.48);
    const w = breadth * taper * (0.80 + 0.37 * noise(t * 5, seed));
    result.push({ x, y, nx: -dy / length, ny: dx / length, w, t });
  }
  return result;
}

function ribbonPoint(p, u, seed = 0) {
  const rough = (noise(p.t * 41, u * 3 + 12, seed) - 0.5) * 5;
  return {
    x: p.x + p.nx * (p.w * u * 0.5 + rough),
    y: p.y + p.ny * (p.w * u * 0.5 + rough)
  };
}

function paintRibbon(path, palette) {
  const ctx = drawingContext;
  ctx.save();
  ctx.shadowColor = "rgba(10,23,26,0.36)";
  ctx.shadowBlur = 27;
  ctx.shadowOffsetY = 12;

  noStroke();
  fill(palette[0]);
  beginShape();
  for (const p of path) {
    const q = ribbonPoint(p, -1);
    vertex(q.x, q.y);
  }
  for (let i = path.length - 1; i >= 0; i--) {
    const q = ribbonPoint(path[i], 1);
    vertex(q.x, q.y);
  }
  endShape(CLOSE);
  ctx.restore();

  // Fibres longitudinales, pigment transparent et brosse sèche.
  noFill();
  for (let j = 0; j < 185; j++) {
    const u = map(j, 0, 184, -0.99, 0.99);
    const c = color(random(palette));
    c.setAlpha(random(75, 190));
    stroke(c);
    strokeWeight(random(0.65, 2.8));
    const start = floor(random(0, 18));
    const stop = path.length - floor(random(0, 20));

    beginShape();
    for (let i = start; i < stop; i++) {
      const p = path[i];
      const drift = 0.023 * sin(p.t * 24 + j * 0.27);
      const q = ribbonPoint(p, u + drift, 6);
      vertex(q.x, q.y);
    }
    endShape();
  }

  for (let k = 0; k < 1800; k++) {
    const p = random(path);
    const q = ribbonPoint(p, random(-0.97, 0.97), 15);
    const c = color(random(palette));
    c.setAlpha(random(20, 85));
    stroke(c);
    strokeWeight(random(0.5, 2));
    const len = random(1, 10);
    line(q.x, q.y, q.x - p.ny * len, q.y + p.nx * len);
  }
}

function fineEdges(path, ink, offsets) {
  noFill();
  const c = color(ink);
  c.setAlpha(120);
  stroke(c);
  strokeWeight(1.3);

  for (const u of offsets) {
    beginShape();
    for (let i = 9; i < path.length - 13; i++) {
      const q = ribbonPoint(path[i], u, 3);
      vertex(q.x, q.y);
    }
    endShape();
  }
}

function stitches(path, position, ink) {
  // Quelques reprises visibles : non une blessure effacée,
  // mais une matière qui a été patiemment tenue.
  const center = floor(position * (path.length - 1));
  for (let j = -3; j <= 3; j++) {
    const p = path[center + j * 2];
    const c = color(ink);
    c.setAlpha(155);
    stroke(c);
    strokeWeight(random(1.2, 2.2));
    noFill();
    beginShape();
    for (let k = 0; k <= 12; k++) {
      const u = lerp(-0.52, 0.34, k / 12);
      const q = ribbonPoint(p, u, j + 12);
      vertex(q.x + random(-1.5, 1.5), q.y + random(-1.5, 1.5));
    }
    endShape();
  }
}

function distantThreads() {
  noFill();
  for (let i = 0; i < 26; i++) {
    const d = i - 13;
    stroke(187, 161, 109, random(15, 52));
    strokeWeight(random(0.6, 1.5));
    bezier(
      686 + d * 2, 432 + d,
      385 + d * 8, 186 - d * 3,
      197 + d * 4, 1437,
      553 + d * 4, 1597
    );
  }

  for (let i = 0; i < 18; i++) {
    const d = i - 9;
    stroke(197, 163, 113, random(16, 46));
    strokeWeight(random(0.5, 1.3));
    bezier(
      1008 + d, 467,
      1480 + d * 3, 798,
      1355 + d * 7, 1674,
      894 + d * 3, 1730
    );
  }
}

function smallPresences() {
  const positions = [
    [352, 775, 10], [1280, 1070, 8],
    [624, 1682, 13], [966, 1710, 7],
    [470, 488, 6], [1178, 606, 5],
    [386, 1295, 8]
  ];

  noStroke();
  for (const [x, y, r] of positions) {
    for (let j = 5; j >= 1; j--) {
      fill(225, 185, 110, 7);
      ellipse(x, y, r * j * 2, r * j * 2);
    }

    fill("#c7a46b");
    ellipse(x, y, r * 1.3, r * 2);
    fill("#f0d6a0");
    ellipse(x - r * 0.18, y - r * 0.3, r * 0.5, r * 0.8);
  }

  for (let i = 0; i < 160; i++) {
    const a = random(TWO_PI);
    const x = 808 + cos(a) * random(480, 630);
    const y = 998 + sin(a) * random(650, 790);
    fill(208, 179, 125, random(12, 65));
    ellipse(x, y, random(0.7, 2.8), random(0.8, 3.4));
  }
}

function surfaceGrain() {
  // Grain final déposé sur toute la surface peinte.
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const g = random(-5.5, 5.5);
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g * 0.85, 0, 255);
  }
  updatePixels();
}

// p5.js 1.11 — image fixe, sans ressources externes.

const W = 1600;
const H = 2000;

const bleu = {
  path: [
    [[1025, 408], [660, 215], [201, 590], [392, 1110]],
    [[392, 1110], [509, 1480], [842, 1710], [1185, 1470]]
  ],
