  width: 168,
  phase: 0.4
};

const terre = {
  path: [
    [[554, 572], [742, 303], [1225, 367], [1272, 860]],
    [[1272, 860], [1327, 1242], [1077, 1586], [722, 1573]]
  ],
  dark: [103, 43, 37],
  light: [228, 151, 111],
  width: 158,
  phase: 2.1
};

function setup() {
