  background(28, 36, 40);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  fond();
  poussiereDuFond();

  ombre(bleu);
  ombre(terre);

  ruban(bleu);
  ruban(terre);

  // Quelques traces de lumière demeurent dans la matière.
  cicatrice(bleu, 0.21, 0.48, 0.40);
  cicatrice(bleu, 0.58, 0.76, -0.24);
  cicatrice(terre, 0.17, 0.37, -0.32);
  cicatrice(terre, 0.55, 0.80, 0.28);

