}

function fond() {
  loadPixels();

  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const dx = (x - 827) / 620;
      const dy = (y - 958) / 820;
      const r = dx * dx + dy * dy;
      const halo = Math.exp(-1.85 * r);
      const chaleur = Math.exp(
        -sq((x - 1040) / 780) - sq((y - 1230) / 1050)
      );
      const n = random(-3.6, 3.6);
      const i = 4 * (x + y * W);

      pixels[i]     = 25 + 218 * halo + 12 * chaleur + n;
      pixels[i + 1] = 35 + 190 * halo + 5 * chaleur + n;
      pixels[i + 2] = 42 + 142 * halo - 3 * chaleur + n;
      pixels[i + 3] = 255;
    }
  }
  updatePixels();
}

function poussiereDuFond() {
  noStroke();

  for (let i = 0; i < 20000; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.003, y * 0.003);
    const chaud = random() < 0.47;

    if (chaud) fill(202, 167, 119, random(2, 11));
    else fill(25, 49, 58, random(3, 13));

    push();
    translate(x, y);
    rotate(-0.35 + n * 0.8);
    ellipse(0, 0, random(3, 35), random(1, 7));
    pop();
  }

  // Marques presque effacées, sous les couches de peinture.
  noFill();
  for (let k = 0; k < 80; k++) {
    const y = random(150, 1850);
    const x = random(130, 1450);
    stroke(193, 178, 140, random(3, 12));
    strokeWeight(random(0.5, 2));
    bezier(
      x, y,
      x + random(-80, 80), y - 30,
      x + random(-80, 80), y + 70,
      x + random(-50, 50), y + random(90, 260)
    );
  }
}

function centre(forme, t) {
  t = constrain(t, 0, 1);
  const index = t < 0.5 ? 0 : 1;
  const u = index === 0 ? t * 2 : (t - 0.5) * 2;
  const p = forme.path[index];

  return {
    x: bezierPoint(p[0][0], p[1][0], p[2][0], p[3][0], u),
    y: bezierPoint(p[0][1], p[1][1], p[2][1], p[3][1], u)
  };
}

function pointRuban(forme, t, v) {
  t = constrain(t, 0, 1);
  const p = centre(forme, t);
  const a = centre(forme, max(0, t - 0.0004));
  const b = centre(forme, min(1, t + 0.0004));

  let dx = b.x - a.x;
  let dy = b.y - a.y;
  const longueur = Math.hypot(dx, dy) || 1;
  dx /= longueur;
  dy /= longueur;

  const souffle = 0.84 + 0.16 * sin(t * TWO_PI + forme.phase);
  const largeur = 5 + forme.width *
    pow(max(0, sin(PI * t)), 0.64) * souffle;
  const irregularite = (
    noise(t * 41, forme.phase * 11) - 0.5
  ) * 8 * pow(abs(v), 3);

  return {
    x: p.x - dy * (largeur * v + irregularite),
    y: p.y + dx * (largeur * v + irregularite)
  };
}

function ombre(forme) {
  noFill();

  for (let couche = 13; couche >= 1; couche--) {
    stroke(9, 24, 30, 3);
    strokeWeight(10 + couche * 3);

    for (let v = -0.8; v <= 0.81; v += 0.2) {
      beginShape();
      for (let t = 0; t <= 1.001; t += 0.008) {
        const p = pointRuban(forme, t, v);
        vertex(p.x + 12, p.y + 22);
      }
      endShape();
    }
  }
}

function pigment(forme, t, v, variation) {
  const relief = pow(max(0, 1 - abs(v)), 0.5);
  const lumiere = 0.20 + 0.49 * relief
    + 0.14 * sin(8 * t + forme.phase)
    + variation;
  const f = constrain(lumiere, 0, 1);

  return [
    lerp(forme.dark[0], forme.light[0], f),
    lerp(forme.dark[1], forme.light[1], f),
    lerp(forme.dark[2], forme.light[2], f)
  ];
}

function ruban(forme) {
  noStroke();

  // Sous-couche faite de petits pans, plutôt que d'un aplat lisse.
  const N = 310;
  const M = 26;

  for (let i = 0; i < N; i++) {
    const t = i / N;
    const tt = (i + 1) / N;

    for (let j = 0; j < M; j++) {
      const v = map(j, 0, M, -1, 1);
      const vv = map(j + 1, 0, M, -1, 1);
      const c = pigment(forme, t, (v + vv) / 2, random(-0.045, 0.045));
      fill(c[0], c[1], c[2]);

      const a = pointRuban(forme, t, v);
      const b = pointRuban(forme, tt, v);
      const d = pointRuban(forme, tt, vv);
      const e = pointRuban(forme, t, vv);
      quad(a.x, a.y, b.x, b.y, d.x, d.y, e.x, e.y);
    }
  }

  // Brossage longitudinal : fibres, reprises, empâtements.
  noFill();
  for (let i = 0; i < 22500; i++) {
    const t = random(0.004, 0.996);
    const v = random(-0.995, 0.995);
    const c = pigment(forme, t, v, random(-0.22, 0.25));
    const longueur = random(0.0015, 0.016);
    const derive = random(-0.018, 0.018);

    stroke(c[0], c[1], c[2], random(30, 125));
    strokeWeight(random(0.5, 3.8));

    beginShape();
    for (let k = 0; k <= 4; k++) {
      const p = pointRuban(
        forme,
        min(1, t + longueur * k / 4),
        constrain(v + derive * k / 4, -1, 1)
      );
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Des bords incomplets laissent respirer la silhouette.
  for (let i = 0; i < 1900; i++) {
    const t = random(0.035, 0.97);
    const v = random() < 0.5 ? random(-1.025, -0.94) : random(0.94, 1.025);
    const a = pointRuban(forme, t, v);
    const b = pointRuban(forme, min(1, t + random(0.001, 0.006)), v);

    stroke(forme.light[0], forme.light[1], forme.light[2], random(10, 58));
    strokeWeight(random(0.5, 2.2));
    line(a.x, a.y, b.x, b.y);
  }
}

function cicatrice(forme, debut, fin, cote) {
  const points = [];

  for (let i = 0; i <= 90; i++) {
    const u = i / 90;
    const t = lerp(debut, fin, u);
    const v = cote + 0.12 * sin(u * 11)
      + 0.075 * (noise(u * 23, debut * 20) - 0.5);
    points.push(pointRuban(forme, t, v));
  }

  noFill();
  for (let couche = 0; couche < 3; couche++) {
    if (couche === 0) {
      stroke(44, 33, 27, 135);
      strokeWeight(5);
    } else if (couche === 1) {
      stroke(191, 140, 68, 190);
      strokeWeight(2.1);
    } else {
      stroke(246, 213, 143, 195);
      strokeWeight(0.65);
    }

    beginShape();
    for (const p of points) vertex(p.x, p.y);
    endShape();
  }

  for (let i = 12; i < points.length - 10; i += 17) {
    const p = points[i];
    stroke(220, 179, 106, 120);
    strokeWeight(0.8);
    line(p.x, p.y, p.x + random(-14, 14), p.y + random(8, 23));
  }
}

function filPeint(points, intensite) {
  noFill();

  for (let passe = 0; passe < 4; passe++) {
    const teintes = [
      [70, 48, 31, 35],
      [175, 125, 57, 125],
      [237, 201, 130, 205],
      [255, 234, 178, 160]
    ];
    const c = teintes[passe];
    stroke(c[0], c[1], c[2], c[3] * intensite);
    strokeWeight([7, 3, 1.3, 0.55][passe]);

    beginShape();
    vertex(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i += 3) {
      bezierVertex(
        points[i][0], points[i][1],
        points[i + 1][0], points[i + 1][1],
        points[i + 2][0], points[i + 2][1]
      );
    }
    endShape();
  }
}

function fils() {
  // Le lien traverse l'espace, mais ne le clôt pas.
  filPeint([
    [453, 1074],
    [576, 1130], [596, 1369], [825, 1381],
    [1009, 1391], [1118, 1233], [1171, 1118]
  ], 0.90);

  filPeint([
    [461, 1091],
    [597, 1152], [615, 1398], [823, 1400],
    [1008, 1404], [1117, 1255], [1180, 1136]
  ], 0.42);

  filPeint([
    [706, 446],
    [813, 508], [993, 509], [1124, 635]
  ], 0.55);
}

function eclats() {
  noStroke();

  // Un peu de matière dorée, jamais un centre possédé.
  for (let i = 0; i < 240; i++) {
    const x = randomGaussian(833, 180);
    const y = randomGaussian(1328, 80);
    if (x < 510 || x > 1175 || y < 1130 || y > 1470) continue;

    fill(247, 213, 151, random(25, 145));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(0.7, 4.5), random(0.5, 2));
    pop();
  }

  for (let i = 0; i < 55; i++) {
    const x = randomGaussian(868, 120);
    const y = randomGaussian(815, 180);
    fill(255, 240, 202, random(12, 65));
    circle(x, y, random(0.7, 2));
  }
}

function glacisEtGrain() {
  loadPixels();

  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = 4 * (x + y * W);
      const bord = min(x, W - 1 - x, y, H - 1 - y);
      const patine = 1 - 0.14 * exp(-bord / 34);
      const trame = ((x % 3 === 0) ? -0.8 : 0.3)
        + ((y % 4 === 0) ? -0.65 : 0.2);
      const grain = random(-2.9, 2.9) + trame;

      pixels[i]     = constrain(pixels[i] * patine + grain, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * patine + grain, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * patine + grain, 0, 255);
    }
  }

  updatePixels();
}

