}

function draw() {
  background("#142c37");

  wash(730, 950, 1120, 1350, [
    [0, "rgba(60,91,93,0.75)"],
    [0.65, "rgba(27,53,65,0.3)"],
    [1, "rgba(8,21,34,0)"]
  ]);

  // Sous-couches : traces larges, presque effacées.
  noFill();
  for (let i = 0; i < 180; i++) {
    const x = random(-150, 1750);
    const y = random(-200, 2200);
    stroke(random() < 0.5 ? color(99, 111, 101, 9)
                          : color(5, 21, 37, 15));
    strokeWeight(random(12, 80));
    bezier(x, y, x - 120, y + 100,
           x + 120, y + 220, x + 35, y + random(240, 500));
  }

  noStroke();
  for (let i = 0; i < 24000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.005, y * 0.005);
    fill(139, 155, 139, random(2, 13) * n);
    ellipse(x, y, random(0.6, 3.7), random(1, 6));
  }

  // Une clarté qui existe avant les formes qui la soutiennent.
  wash(805, 1005, 630, 830, [
    [0, "rgba(235,190,104,0.76)"],
    [0.43, "rgba(196,145,75,0.50)"],
    [0.76, "rgba(144,98,54,0.17)"],
    [1, "rgba(144,98,54,0)"]
  ]);

  luminousField();

  const warm = makeRibbon([
    [1080, 390, 890, 270, 520, 410, 407, 740],
    [407, 740, 250, 1150, 500, 1500, 870, 1545],
    [870, 1545, 1010, 1560, 1120, 1500, 1190, 1370]
  ], 180, 13);

  const cool = makeRibbon([
    [510, 1580, 865, 1770, 1260, 1490, 1265, 1110],
    [1265, 1110, 1310, 750, 1110, 465, 820, 460],
    [820, 460, 665, 450, 560, 560, 547, 715]
  ], 158, 71);

  ribbonShadow(warm);
  ribbonShadow(cool);

  paintRibbon(warm, [
    "#f3c68a", "#d88958", "#b94e39", "#813d36", "#453b39"
  ], 13);

  paintRibbon(cool, [
    "#c1d2bd", "#6faaa3", "#397e87", "#285361", "#243b4b"
  ], 71);

  // Des attaches irrégulières : elles entourent sans quadriller.
  noFill();
  for (let i = 0; i < 32; i++) {
    const t = i / 31;
    const a = ribbonPoint(warm, 0.24 + t * 0.16, -0.88);
    const b = ribbonPoint(cool, 0.18 + t * 0.16, -0.87);
    stroke(235, 196, 127, random(13, 52));
    strokeWeight(random(0.45, 1.5));
    bezier(a.x, a.y,
           520 + t * 35, 1340 + t * 110,
           1030 + t * 70, 1490 - t * 25,
           b.x, b.y);
  }

  for (let i = 0; i < 23; i++) {
    const t = i / 22;
    const a = ribbonPoint(warm, 0.15 + t * 0.13, -0.92);
    const b = ribbonPoint(cool, 0.64 + t * 0.15, -0.92);
    stroke(243, 217, 162, random(12, 44));
    strokeWeight(random(0.5, 1.25));
    bezier(a.x, a.y,
           620 - t * 40, 595 + t * 35,
           1050 - t * 60, 565 + t * 70,
           b.x, b.y);
  }

  // Quelques dépôts de matière, non des points de lumière.
  noStroke();
  for (let i = 0; i < 1600; i++) {
    const a = random(TWO_PI);
    const r = random(0.78, 1.15);
    const x = 813 + cos(a) * 315 * r;
    const y = 1000 + sin(a) * 455 * r;
    fill(238, 209, 150, random(5, 30));
    ellipse(x, y, random(0.6, 3), random(1.2, 4));
  }

  // Une dernière lumière reste discontinue sur les crêtes.
  edgeLight(warm, color(255, 220, 163), 19);
  edgeLight(cool, color(208, 230, 207), 83);

  grain();
}

function wash(x, y, rx, ry, stops) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(rx, ry);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.fillRect(-1, -1, 2, 2);
  ctx.restore();
}

function luminousField() {
  noStroke();

  // Les couches translucides gardent un bord irrégulier et respirant.
  for (let k = 0; k < 90; k++) {
    const s = lerp(1.15, 0.14, k / 89);
    const t = k / 89;
    fill(lerp(219, 255, t),
         lerp(176, 244, t),
         lerp(108, 211, t), 10);

    beginShape();
    for (let j = 0; j < 180; j++) {
      const a = TWO_PI * j / 180;
      const rough = 1 + 0.065 *
        (noise(4 + cos(a) * 1.5, 4 + sin(a) * 1.5) - 0.5);
      const x = 810 + s * (
        cos(a) * 307 * rough + 44 * sin(a) + 21 * sin(2 * a)
      );
      const y = 1005 + s * sin(a) * 443 * rough;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  wash(785, 947, 255, 360, [
    [0, "rgba(255,248,220,0.40)"],
    [0.5, "rgba(255,239,192,0.13)"],
    [1, "rgba(255,239,192,0)"]
  ]);
}

function makeRibbon(segments, breadth, seed) {
  const points = [];
  const steps = 125;

  for (let s = 0; s < segments.length; s++) {
    const b = segments[s];
    for (let j = 0; j <= steps; j++) {
      if (s > 0 && j === 0) continue;
      const t = j / steps;
      const x = bezierPoint(b[0], b[2], b[4], b[6], t);
      const y = bezierPoint(b[1], b[3], b[5], b[7], t);
      const dx = bezierTangent(b[0], b[2], b[4], b[6], t);
      const dy = bezierTangent(b[1], b[3], b[5], b[7], t);
      const length = Math.hypot(dx, dy) || 1;
      const u = (s + t) / segments.length;
      const taper = pow(max(0, sin(PI * u)), 0.48);
      const w = 3 + breadth * taper *
        (0.85 + 0.23 * noise(seed, u * 5));
      points.push({ x, y, nx: -dy / length, ny: dx / length, w });
    }
  }
  return points;
}

function offsetPoint(p, u, i, seed) {
  const abrasion = (noise(seed + u * 3, i * 0.045) - 0.5) * 10;
  const d = p.w * u + abrasion;
  return { x: p.x + p.nx * d, y: p.y + p.ny * d };
}

function ribbonPoint(points, t, u) {
  const p = points[round(constrain(t, 0, 1) * (points.length - 1))];
  return { x: p.x + p.nx * p.w * u, y: p.y + p.ny * p.w * u };
}

function ribbonShadow(points) {
  noFill();
  for (let k = 8; k >= 1; k--) {
    stroke(5, 22, 30, 6);
    strokeWeight(k * 7);
    beginShape();
    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      vertex(p.x + p.nx * p.w + 12, p.y + p.ny * p.w + 20);
    }
    endShape();
  }
}

function paletteAt(palette, t) {
  const v = constrain(t, 0, 1) * (palette.length - 1);
  const i = min(floor(v), palette.length - 2);
  return lerpColor(palette[i], palette[i + 1], v - i);
}

function paintRibbon(points, hexes, seed) {
  const palette = hexes.map(h => color(h));

  noStroke();
  fill(palette[2]);
  beginShape();
  for (let i = 0; i < points.length; i++) {
    const p = offsetPoint(points[i], -1, i, seed);
    vertex(p.x, p.y);
  }
  for (let i = points.length - 1; i >= 0; i--) {
    const p = offsetPoint(points[i], 1, i, seed);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);

  // Poils de brosse : variations longitudinales du pigment.
  noFill();
  for (let j = 0; j < 340; j++) {
    const u = map(j, 0, 339, -1, 1);
    const c = paletteAt(palette,
      constrain((u + 1) / 2 + random(-0.07, 0.07), 0, 1));
    c.setAlpha(random(80, 190));
    stroke(c);
    strokeWeight(random(0.8, 2.8));

    beginShape();
    for (let i = 0; i < points.length; i++) {
      const p = offsetPoint(points[i], u, i, seed);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Frottis, réserves et petites ruptures de la couche picturale.
  for (let j = 0; j < 6500; j++) {
    const i = floor(random(points.length));
    const u = random(-0.98, 0.98);
    const p = offsetPoint(points[i], u, i, seed);
    const base = points[i];
    const c = paletteAt(palette,
      constrain((u + 1) / 2 + random(-0.22, 0.22), 0, 1));
    c.setAlpha(random(15, 75));
    stroke(c);
    strokeWeight(random(0.5, 2.3));
    const len = random(2, 15);
    line(p.x, p.y,
         p.x + base.ny * len,
         p.y - base.nx * len);
  }

  for (let j = 0; j < 110; j++) {
    const start = floor(random(points.length - 25));
    const end = min(points.length - 1, start + floor(random(8, 65)));
    const u = random(-0.9, 0.9);
    stroke(18, 39, 44, random(12, 35));
    strokeWeight(random(0.5, 1.4));
    beginShape();
    for (let i = start; i <= end; i++) {
      const p = offsetPoint(points[i], u, i, seed);
      vertex(p.x, p.y);
    }
    endShape();
  }
}

function edgeLight(points, c, seed) {
  noFill();
  for (let j = 0; j < 70; j++) {
    const start = floor(random(15, points.length - 30));
    const end = min(points.length - 1, start + floor(random(4, 28)));
    const u = random(-0.97, -0.68);
    c.setAlpha(random(18, 65));
    stroke(c);
    strokeWeight(random(0.5, 1.6));
    beginShape();
    for (let i = start; i <= end; i++) {
      const p = offsetPoint(points[i], u, i, seed);
      vertex(p.x, p.y);
    }
    endShape();
  }
}

function grain() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = 4 * (y * width + x);
      const weave = (x % 3 === 0 ? -0.8 : 0.35) +
                    (y % 4 === 0 ? -0.7 : 0.2);
      const g = random(-3.8, 3.8) + weave;
      pixels[i]     = constrain(pixels[i]     + g, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + g * 0.85, 0, 255);
    }
  }
  updatePixels();
}

// La lumière d'entre — p5.js 1.11
const W = 1600, H = 2000;
const GLOW_Y = 1080;
let FL, FR;

const KT = [0, 0.03, 0.08, 0.14, 0.2, 0.32, 0.6, 1.0];
const KW = [0, 0.30, 0.42, 0.36, 0.29, 0.88, 1.0, 0.94];

const STOPS = [
  [0.00, [8, 6, 14],   [14, 10, 24]],
  [0.45, [12, 8, 18],  [30, 18, 34]],
  [0.68, [16, 10, 20], [78, 32, 40]],
  [0.84, [22, 12, 20], [170, 78, 46]],
  [0.94, [30, 16, 22], [238, 150, 82]],
  [1.00, [36, 20, 24], [255, 222, 170]]
];

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;
  paintSky(ctx);
  paintGlow(ctx);
  paintGround(ctx);
  FL = makeFigure(590, 640, 1700, 158, 55, 0);
  FR = makeFigure(1010, 655, 1700, 154, -55, 100);
  paintFigure(ctx, FL, true);
  paintFigure(ctx, FR, false);
  brushPass();
  paintStars();
  paintRims(FL, true);
  paintRims(FR, false);
  paintSeam(ctx);
  paintMotes();
  vignette(ctx);
  grain();
}

// ---------- fond ----------
function paintSky(ctx) {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#0a0b22');
  g.addColorStop(0.45, '#1b1640');
  g.addColorStop(0.75, '#2d1a3a');
  g.addColorStop(1, '#1a0f1a');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function paintGlow(ctx) {
  ctx.save();
  ctx.translate(800, GLOW_Y);
  ctx.scale(0.75, 1.35);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 600);
  g.addColorStop(0, 'rgba(255,226,170,0.95)');
  g.addColorStop(0.12, 'rgba(255,190,110,0.75)');
  g.addColorStop(0.35, 'rgba(220,110,70,0.35)');
  g.addColorStop(0.7, 'rgba(120,50,80,0.12)');
  g.addColorStop(1, 'rgba(40,20,60,0)');
  ctx.fillStyle = g;
  ctx.fillRect(-1100, -1100, 2200, 2200);
  ctx.restore();
}

function paintGround(ctx) {
  const g = ctx.createLinearGradient(0, 1680, 0, H);
  g.addColorStop(0, '#1c0f17');
  g.addColorStop(1, '#0b0609');
  ctx.fillStyle = g;
  ctx.fillRect(0, 1690, W, H - 1690);

  // flaque de lumière au sol
  ctx.save();
  ctx.translate(800, 1715);
  ctx.scale(1, 0.18);
  const p = ctx.createRadialGradient(0, 0, 0, 0, 0, 700);
  p.addColorStop(0, 'rgba(255,190,120,0.65)');
  p.addColorStop(0.4, 'rgba(200,100,70,0.25)');
  p.addColorStop(1, 'rgba(80,30,40,0)');
  ctx.fillStyle = p;
  ctx.fillRect(-900, -900, 1800, 1800);
  ctx.restore();

  // ombres projetées vers l'extérieur
  ctx.fillStyle = 'rgba(5,3,8,0.55)';
  ctx.beginPath();
  ctx.moveTo(440, 1695); ctx.lineTo(770, 1695);
  ctx.lineTo(0, 1890); ctx.lineTo(0, 1760);
  ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(1160, 1695); ctx.lineTo(830, 1695);
  ctx.lineTo(W, 1890); ctx.lineTo(W, 1760);
  ctx.closePath(); ctx.fill();
}

// ---------- figures ----------
function profile(t) {
  for (let i = 0; i < KT.length - 1; i++) {
    if (t <= KT[i + 1]) {
      let u = (t - KT[i]) / (KT[i + 1] - KT[i]);
      u = (i === 0) ? Math.sqrt(u) : u * u * (3 - 2 * u);
      return lerp(KW[i], KW[i + 1], u);
    }
  }
  return KW[KW.length - 1];
}

function makeFigure(cx, top, bottom, w, lean, seed) {
  const N = 160, left = [], right = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const y = lerp(top, bottom, t);
    const off = lean * Math.pow(1 - t, 1.3);
    const hw = w * profile(t);
    const damp = Math.min(1, t * 10);
    const wl = (noise(seed, t * 5) - 0.5) * w * 0.14 * damp;
    const wr = (noise(seed + 33, t * 5) - 0.5) * w * 0.14 * damp;
    left.push([cx + off - hw + wl, y]);
    right.push([cx + off + hw + wr, y]);
  }
  return { left, right };
}

function tracePath(ctx, F) {
  ctx.beginPath();
  ctx.moveTo(F.left[0][0], F.left[0][1]);
  for (let i = 1; i < F.left.length; i++) ctx.lineTo(F.left[i][0], F.left[i][1]);
  for (let i = F.right.length - 1; i >= 0; i--) ctx.lineTo(F.right[i][0], F.right[i][1]);
  ctx.closePath();
}

function mixCol(a, b, t) {
  const r = Math.round(a[0] + (b[0] - a[0]) * t);
  const g = Math.round(a[1] + (b[1] - a[1]) * t);
  const bl = Math.round(a[2] + (b[2] - a[2]) * t);
  return 'rgb(' + r + ',' + g + ',' + bl + ')';
}

function paintFigure(ctx, F, litRight) {
  ctx.save();
  tracePath(ctx, F);
  ctx.clip();
  for (let i = 0; i < F.left.length - 1; i++) {
    const y0 = F.left[i][1], y1 = F.left[i + 1][1];
    const xl = F.left[i][0], xr = F.right[i][0];
    const outer = litRight ? xl : xr;
    let inner = litRight ? xr : xl;
    if (Math.abs(inner - outer) < 1) inner = outer + (litRight ? 1 : -1);
    const g = ctx.createLinearGradient(outer, 0, inner, 0);
    const k = Math.exp(-sq((y0 - GLOW_Y) / 620));
    for (const s of STOPS) g.addColorStop(s[0], mixCol(s[1], s[2], 0.25 + 0.75 * k));
    ctx.fillStyle = g;
    ctx.fillRect(Math.min(xl, xr) - 30, y0 - 1, Math.abs(xr - xl) + 60, y1 - y0 + 2);
  }
  const vg = ctx.createLinearGradient(0, 1450, 0, 1705);
  vg.addColorStop(0, 'rgba(10,6,12,0)');
  vg.addColorStop(1, 'rgba(10,6,12,0.85)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 1450, W, 260);
  ctx.restore();
}

// ---------- matière picturale ----------
function brushPass() {
  loadPixels();
  const px = pixels;
  for (let n = 0; n < 110000; n++) {
    const x = random(W), y = random(H);
    const idx = 4 * (Math.floor(y) * W + Math.floor(x));
    const nz = noise(x * 0.003, y * 0.003);
    const r = px[idx] + (nz - 0.5) * 28 + random(-8, 8);
    const g = px[idx + 1] + random(-6, 6);
    const b = px[idx + 2] + (0.5 - nz) * 20 + random(-8, 8);
    let a = noise(x * 0.0015 + 50, y * 0.0015) * TWO_PI * 1.5;
    if (Math.abs(x - 800) < 120 && y > 600 && y < 1700) a = HALF_PI + random(-0.2, 0.2);
    const len = random(10, 34);
    const dx = Math.cos(a) * len / 2, dy = Math.sin(a) * len / 2;
    stroke(r, g, b, 150);
    strokeWeight(random(2, 5.5));
    line(x - dx, y - dy, x + dx, y + dy);
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 140; i++) {
    const x = random(W), y = random(20, 560);
    fill(230, 225, 255, random(40, 150));
    circle(x, y, random(1, 2.6));
  }
}

function paintRims(F, litRight) {
  const innerPts = litRight ? F.right : F.left;
  const outerPts = litRight ? F.left : F.right;
  blendMode(ADD);
  for (let i = 2; i < innerPts.length - 1; i++) {
    const p = innerPts[i], q = innerPts[i + 1];
    const k = Math.exp(-sq((p[1] - GLOW_Y) / 620)) * constrain((1650 - p[1]) / 300, 0, 1);
    stroke(255, 200, 130, 18 * k);
    strokeWeight(16);
    line(p[0], p[1], q[0], q[1]);
    stroke(255, 225, 165, 110 * k);
    strokeWeight(3);
    line(p[0], p[1], q[0], q[1]);
  }
  blendMode(BLEND);
  for (let i = 2; i < outerPts.length - 1; i++) {
    const p = outerPts[i], q = outerPts[i + 1];
    const f = constrain((1650 - p[1]) / 400, 0, 1);
    stroke(110, 120, 200, 40 * f);
    strokeWeight(2);
    line(p[0], p[1], q[0], q[1]);
  }
}

function paintSeam(ctx) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.save();
  ctx.translate(800, 1150);
  ctx.scale(0.09, 1);
  let g = ctx.createRadialGradient(0, 0, 0, 0, 0, 650);
  g.addColorStop(0, 'rgba(255,235,200,0.55)');
  g.addColorStop(0.4, 'rgba(255,190,120,0.18)');
  g.addColorStop(1, 'rgba(255,150,90,0)');
  ctx.fillStyle = g;
  ctx.fillRect(-700, -700, 1400, 1400);
  ctx.restore();
  ctx.translate(800, GLOW_Y);
  ctx.scale(0.35, 1.1);
  g = ctx.createRadialGradient(0, 0, 0, 0, 0, 500);
  g.addColorStop(0, 'rgba(255,200,140,0.18)');
  g.addColorStop(1, 'rgba(255,150,90,0)');
  ctx.fillStyle = g;
  ctx.fillRect(-600, -600, 1200, 1200);
  ctx.restore();
}

function paintMotes() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 340; i++) {
    const y = 1680 - Math.pow(random(), 1.6) * 1250;
    const spread = 18 + Math.max(0, 900 - y) * 0.12;
    const x = 800 + randomGaussian() * spread;
    const h = constrain(map(y, 1680, 430, 1, 0.15), 0.1, 1);
    const s = random(1.2, 4.5);
    fill(255, 200, 130, 26 * h);
    circle(x, y, s * 5);
    fill(255, 230, 180, 160 * h);
    circle(x, y, s);
  }
  blendMode(BLEND);
}

function vignette(ctx) {
  const g = ctx.createRadialGradient(800, 1050, 500, 800, 1050, 1350);
  g.addColorStop(0, 'rgba(5,3,10,0)');
  g.addColorStop(1, 'rgba(5,3,10,0.7)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function grain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const n = random(-9, 9);
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();
}

// La troisième couleur
let A, B;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function rel(f, x, y) {
  let dx = x - f.x, dy = y - f.y;
  let th = atan2(dy, dx);
  let n = noise(f.off + cos(th) * 0.9 + 1, f.off + sin(th) * 0.9 + 1);
  let r = f.R * (0.82 + 0.36 * n);
  return sqrt(dx * dx + dy * dy) / r;
}

function pick(pal) {
  return pal[floor(random(pal.length))];
}

function mix(c1, c2, t) {
  return [lerp(c1[0], c2[0], t), lerp(c1[1], c2[1], t), lerp(c1[2], c2[2], t)];
}

function draw() {
  let ctx = drawingContext;

  // Fond : obscurité chaude
  let g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#1b1424');
  g.addColorStop(0.5, '#22161d');
  g.addColorStop(1, '#100b12');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // Texture de pinceau dans le fond
  let darkPal = [[40, 26, 44], [52, 30, 38], [24, 18, 30], [60, 40, 46], [30, 24, 40]];
  for (let i = 0; i < 30000; i++) {
    let x = random(width), y = random(height);
    let a = noise(x * 0.0015, y * 0.0015) * TWO_PI * 2;
    let len = random(20, 70);
    let c = pick(darkPal);
    stroke(c[0], c[1], c[2], random(18, 40));
    strokeWeight(random(1, 4));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }

  // Les deux présences
  A = { x: 640, y: 860, R: 430, off: 10 };
  B = { x: 980, y: 1200, R: 410, off: 50 };

  let palA = [[196, 64, 58], [214, 98, 72], [170, 48, 60], [226, 130, 96], [150, 40, 52]];
  let palB = [[40, 64, 140], [58, 92, 170], [30, 48, 110], [80, 110, 180], [36, 40, 96]];
  let goldOuter = [[240, 180, 110], [250, 200, 130], [230, 160, 100]];
  let goldInner = [[255, 250, 232], [255, 240, 205], [250, 232, 196]];

  let axis = atan2(B.y - A.y, B.x - A.x);

  for (let i = 0; i < 150000; i++) {
    let x = random(120, 1480), y = random(320, 1740);
    let ra = rel(A, x, y), rb = rel(B, x, y);
    let fz = random(-0.06, 0.06);
    let ia = ra + fz < 1, ib = rb + fz < 1;
    if (!ia && !ib) continue;

    let col, a, e, alpha;
    let nz = noise(x * 0.004, y * 0.004);

    if (ia && ib) {
      e = min(1 - ra, 1 - rb);
      let t = constrain(e * 4, 0, 1);
      col = mix(pick(goldOuter), pick(goldInner), t);
      a = axis + (nz - 0.5) * 1.4 + random(-0.2, 0.2);
      alpha = 70;
    } else if (ia) {
      e = 1 - ra;
      col = pick(palA);
      a = atan2(y - A.y, x - A.x) + HALF_PI + (nz - 0.5) * 1.2;
      alpha = 60;
    } else {
      e = 1 - rb;
      col = pick(palB);
      a = atan2(y - B.y, x - B.x) - HALF_PI + (nz - 0.5) * 1.2;
      alpha = 60;
    }

    alpha *= constrain(e * 6, 0.15, 1);
    let len = random(12, 42);
    stroke(col[0] + random(-10, 10), col[1] + random(-10, 10), col[2] + random(-10, 10), alpha);
    strokeWeight(random(2, 7));
    let mx = x + cos(a) * len * 0.5, my = y + sin(a) * len * 0.5;
    let a2 = a + random(-0.25, 0.25);
    line(x, y, mx, my);
    line(mx, my, mx + cos(a2) * len * 0.5, my + sin(a2) * len * 0.5);
  }

  // Trouver le cœur de la rencontre
  let best = 1e9, lx = 800, ly = 1030;
  for (let x = 400; x < 1200; x += 8) {
    for (let y = 700; y < 1400; y += 8) {
      let m = max(rel(A, x, y), rel(B, x, y));
      if (m < best) { best = m; lx = x; ly = y; }
    }
  }

  // Lueur
  blendMode(ADD);
  let gl = ctx.createRadialGradient(lx, ly, 0, lx, ly, 340);
  gl.addColorStop(0, 'rgba(255,220,160,0.28)');
  gl.addColorStop(0.5, 'rgba(255,180,110,0.10)');
  gl.addColorStop(1, 'rgba(255,160,100,0)');
  ctx.fillStyle = gl;
  ctx.fillRect(0, 0, width, height);

  // La lumière qui déborde dans le monde
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let ang = random(TWO_PI);
    let d = 120 + pow(random(), 2.2) * 950;
    let px = lx + cos(ang) * d + random(-20, 20);
    let py = ly + sin(ang) * d * 1.15 + random(-20, 20);
    let fade = 1 - d / 1100;
    fill(255, 210 + random(-20, 30), 150 + random(-30, 60), 90 * fade + 10);
    let s = random(1, 4) * (0.5 + fade);
    ellipse(px, py, s, s);
  }
  blendMode(BLEND);

  // Vignette
  let v = ctx.createRadialGradient(width / 2, height / 2, 500, width / 2, height / 2, 1350);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(1, 'rgba(0,0,0,0.6)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, width, height);

  // Grain
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-8, 8);
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();
}

// Faire place — p5.js 1.11
const L = { x: 790, y: 1180 }; // position de la lueur

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

// Épaisseur de la forme qui abrite, le long de sa courbe
function thickness(t) {
  let s = sin(PI * constrain(t * 1.05 - 0.02, 0, 1));
  return 40 + 230 * pow(max(s, 0), 0.8);
}

// t ∈ [0,1] le long de la courbe ; u ∈ [-1,1] à travers (−1 = face intérieure)
function arcPoint(t, u) {
  let a = lerp(PI + 0.55, -1.25, t);
  let r = 470;
  r -= 210 * smoothstep(0.62, 1.0, t);        // l'extrémité droite se penche au-dessus
  r += 40 * (1 - smoothstep(0.0, 0.25, t));   // la gauche s'évase légèrement
  let th = thickness(t);
  let rr = r + u * th * 0.5 + (noise(t * 3.0, u * 2.0 + 10) - 0.5) * 40;
  return { x: L.x + cos(a) * rr, y: L.y + 60 + sin(a) * rr * 1.12 };
}

function shelterColor(p, u) {
  let d = dist(p.x, p.y, L.x, L.y);
  let lit = exp(-d / 260);
  let facing = map(u, -1, 1, 1.0, 0.12);
  let k = constrain(lit * facing * 2.3, 0, 1);
  // de l'ombre extérieure vers le cramoisi intérieur
  let m = constrain((1 - u) / 2, 0, 1) * 0.8 + random(-0.08, 0.08);
  let r0 = lerp(46, 150, m), g0 = lerp(12, 30, m), b0 = lerp(24, 40, m);
  // puis vers l'or, là où la lumière touche
  let k2 = k * k;
  let r = lerp(r0, 255, k);
  let g = lerp(g0, 120, k) + 80 * k2;
  let b = lerp(b0, 70, k) + 60 * k2;
  return [r, g, b, 175];
}

function draw() {
  const ctx = drawingContext;
  blendMode(BLEND);

  // --- Nuit de fond ---
  let g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, 'rgb(11,13,30)');
  g.addColorStop(0.5, 'rgb(28,16,30)');
  g.addColorStop(1, 'rgb(19,9,11)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // Touches de pinceau dans la nuit
  strokeCap(ROUND);
  for (let i = 0; i < 6000; i++) {
    let x = random(width), y = random(height);
    let ang = noise(x * 0.0015, y * 0.0015) * PI - PI / 2.2;
    let len = random(30, 140);
    let m = y / height;
    stroke(lerp(28, 62, m) + random(-6, 6), lerp(28, 22, m), lerp(62, 40, m) + random(-6, 6), 16);
    strokeWeight(random(2, 9));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // --- La forme qui fait place ---
  let us = [];
  for (let s = 0; s < 760; s++) us.push(random(-1, 1));
  us.sort((a, b) => b - a); // l'extérieur d'abord, la face éclairée en dernier

  for (let s = 0; s < us.length; s++) {
    let u = us[s];
    let t0 = max(random(-0.15, 0.55), 0);
    let t1 = min(t0 + random(0.25, 0.9), 1);
    let w = random(2, 10);
    let prev = null;
    for (let t = t0; t <= t1; t += 0.004) {
      let uu = constrain(u + (noise(s * 0.31, t * 4) - 0.5) * 0.16, -1.05, 1.05);
      let p = arcPoint(t, uu);
      if (prev) {
        let taper = pow(sin(PI * (t - t0) / max(t1 - t0, 0.001)), 0.5);
        let c = shelterColor(p, uu);
        stroke(c[0], c[1], c[2], c[3]);
        strokeWeight(max(0.5, w * taper));
        line(prev.x, prev.y, p.x, p.y);
      }
      prev = p;
    }
  }

  // Liseré de lumière sur le bord intérieur
  blendMode(ADD);
  for (let s = 0; s < 120; s++) {
    let u = random(-1.02, -0.8);
    let prev = null;
    for (let t = 0.05; t <= 1.0; t += 0.005) {
      let p = arcPoint(t, u);
      if (prev) {
        let d = dist(p.x, p.y, L.x, L.y);
        let a = 40 * exp(-d / 230);
        stroke(255, 170, 90, a);
        strokeWeight(random(1, 4));
        line(prev.x, prev.y, p.x, p.y);
      }
      prev = p;
    }
  }

  // --- Halo de la lueur ---
  let rg = ctx.createRadialGradient(L.x, L.y, 0, L.x, L.y, 900);
  rg.addColorStop(0, 'rgba(255,235,190,0.95)');
  rg.addColorStop(0.03, 'rgba(255,205,130,0.55)');
  rg.addColorStop(0.12, 'rgba(235,130,70,0.22)');
  rg.addColorStop(0.35, 'rgba(140,50,40,0.10)');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, width, height);

  // --- Le cœur de la lueur : une petite flamme ---
  noStroke();
  for (let layer = 6; layer >= 0; layer--) {
    let sc = 1 + layer * 0.55;
    fill(255, lerp(240, 150, layer / 6), lerp(210, 80, layer / 6), layer === 0 ? 255 : 26);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let sa = sin(a);
      let rx = 15 * sc, ry = 20 * sc;
      let x = L.x + cos(a) * rx * (sa < 0 ? 1 - 0.55 * pow(-sa, 2) : 1);
      let y = L.y + sa * ry - (sa < 0 ? pow(-sa, 3) * 26 * sc : 0);
      x += (noise(a * 2, layer) - 0.5) * 4 * sc;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // --- Poussières de lumière qui s'élèvent par l'ouverture ---
  for (let i = 0; i < 140; i++) {
    let h = pow(random(), 1.4);
    let y = L.y - 40 - h * 820;
    let spread = 30 + h * 260;
    let x = L.x + (noise(i * 0.7, h * 2) - 0.5) * 2 * spread + 30 * h;
    let a = 120 * (1 - h) + 10;
    fill(255, 195, 120, a);
    circle(x, y, random(1.5, 5));
    fill(255, 160, 90, a * 0.15);
    circle(x, y, random(10, 20));
  }

  // --- Grain ---
  blendMode(BLEND);
  strokeWeight(1);
  for (let i = 0; i < 45000; i++) {
    let v = random(255);
    stroke(v, v, v, 10);
    point(random(width), random(height));
  }

  // --- Vignette ---
  let vg = ctx.createRadialGradient(800, 1120, 450, 800, 1120, 1450);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(4,2,6,0.65)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

// Ce qui pousse entre — p5.js 1.11
const W = 1600, H = 2000;
const GROUND = 1480;
let COOL, WARM, COOL_L, WARM_L, GOLD, INK;
let trunks = [];

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  COOL = color(46, 74, 156);
  COOL_L = color(120, 156, 222);
  WARM = color(186, 62, 44);
  WARM_L = color(244, 150, 92);
  GOLD = color(255, 206, 130);
  INK = color(14, 10, 24);
  trunks = [
    [createVector(430, GROUND + 20), createVector(370, 1060), createVector(560, 700), createVector(840, 520)],
    [createVector(1180, GROUND + 20), createVector(1250, 1010), createVector(1050, 720), createVector(760, 545)]
  ];
}

function draw() {
  strokeCap(ROUND);
  paintSky();
  paintEarth();
  paintRoots();
  paintGlow(1000, 1.6);
  paintTrunks();
  paintCanopy();
  paintGarden();
  paintGlow(620, 0.7);
  paintSeeds();
  finishing();
}

// ---------- helpers ----------
function groundY(x) {
  return GROUND + (noise(x * 0.004, 50) - 0.5) * 50;
}
function bezPt(P, t) {
  return createVector(
    bezierPoint(P[0].x, P[1].x, P[2].x, P[3].x, t),
    bezierPoint(P[0].y, P[1].y, P[2].y, P[3].y, t)
  );
}
function bezTan(P, t) {
  return createVector(
    bezierTangent(P[0].x, P[1].x, P[2].x, P[3].x, t),
    bezierTangent(P[0].y, P[1].y, P[2].y, P[3].y, t)
  );
}
function trunkW(t) {
  return lerp(120, 34, t) + 90 * pow(1 - t, 8);
}
function trunkEdge(P, t, o) {
  let p = bezPt(P, t), tg = bezTan(P, t);
  tg.normalize();
  let nx = -tg.y, ny = tg.x;
  let w = trunkW(t) * 0.5 * (1 + (noise(t * 6, o * 2 + 5) - 0.5) * 0.25);
  return createVector(p.x + nx * o * w, p.y + ny * o * w);
}
// each one takes a little of the other's colour where they meet
function mixOther(c, x, y, s) {
  let other = s == 0 ? lerpColor(WARM, WARM_L, 0.4) : lerpColor(COOL, COOL_L, 0.4);
  let m = 0.38 * exp(-sq((x - 800) / 200));
  return lerpColor(c, other, m);
}
function brushLine(x1, y1, x2, y2, w, c, al) {
  for (let j = 0; j < 3; j++) {
    stroke(red(c) + random(-10, 10), green(c) + random(-10, 10), blue(c) + random(-10, 10), al);
    strokeWeight(max(1, w * random(0.55, 1)));
    let jx = random(-w * 0.18, w * 0.18), jy = random(-w * 0.18, w * 0.18);
    line(x1 + jx, y1 + jy, x2 + jx, y2 + jy);
  }
}

// ---------- sky ----------
function skyCol(y) {
  let t = constrain(y / GROUND, 0, 1);
  let c1 = color(16, 18, 46), c2 = color(58, 40, 86), c3 = color(150, 78, 82);
  return t < 0.6 ? lerpColor(c1, c2, t / 0.6) : lerpColor(c2, c3, (t - 0.6) / 0.4);
}
function paintSky() {
  for (let y = 0; y < H; y++) {
    stroke(skyCol(y));
    line(0, y, W, y);
  }
  for (let i = 0; i < 14000; i++) {
    let x = random(-50, W + 50), y = random(-50, GROUND + 40);
    let a = noise(x * 0.002, y * 0.002) * TWO_PI * 1.5;
    let len = random(20, 70);
    let c = skyCol(y + random(-120, 120));
    let v = random(-14, 14);
    stroke(red(c) + v, green(c) + v, blue(c) + v * 1.4, 40);
    strokeWeight(random(2, 7));
    line(x, y, x + cos(a) * len, y + sin(a) * len * 0.5);
  }
  noStroke();
  for (let i = 0; i < 90; i++) {
    fill(255, 240, 220, random(40, 140));
    circle(random(W), random(0, 700), random(1.5, 3.5));
  }
}

// ---------- earth ----------
function paintEarth() {
  noStroke();
  fill(52, 32, 32);
  beginShape();
  for (let x = 0; x <= W; x += 10) vertex(x, groundY(x));
  vertex(W, H);
  vertex(0, H);
  endShape(CLOSE);
  for (let y = GROUND + 30; y < H; y++) {
    stroke(10, 6, 12, map(y, GROUND + 30, H, 0, 200));
    line(0, y, W, y);
  }
  for (let i = 0; i < 5000; i++) {
    let x = random(W);
    let y = random(groundY(x) + 5, H);
    let v = random(-12, 12);
    let d = map(y, GROUND, H, 1, 0.4);
    stroke((60 + v) * d, (38 + v) * d, (36 + v) * d, 70);
    strokeWeight(random(2, 6));
    let len = random(15, 60);
    line(x, y, x + len, y + random(-4, 4));
  }
}

// ---------- branching (canopy and roots) ----------
function branchCol(x, y, s, w, root) {
  let base = s == 0 ? COOL : WARM, lite = s == 0 ? COOL_L : WARM_L;
  let c;
  if (root) c = lerpColor(base, INK, 0.55);
  else c = lerpColor(lerpColor(base, INK, 0.35), lite, constrain(map(w, 25, 2, 0.1, 0.8), 0, 1));
  return mixOther(c, x, y, s);
}
function branch(x, y, a, len, w, depth, s, root) {
  let steps = 7;
  let px = x, py = y;
  let target = root ? (s == 0 ? 0.8 : PI - 0.8) : -HALF_PI;
  for (let i = 0; i < steps; i++) {
    a += (noise(px * 0.008, py * 0.008, s * 7 + (root ? 20 : 0)) - 0.5) * 0.5;
    a += (target - a) * 0.035;
    let nx = px + cos(a) * len / steps, ny = py + sin(a) * len / steps;
    if (root && ny < groundY(nx) + 20) {
      a = lerp(a, HALF_PI, 0.6);
      ny = groundY(nx) + 20;
    }
    let ww = w * (1 - (i / steps) * 0.3);
    brushLine(px, py, nx, ny, ww, branchCol(px, py, s, ww, root), root ? 120 : 170);
    px = nx; py = ny;
  }
  if (depth <= 0 || w < 1.6) {
    if (!root) blossom(px, py, s);
    return;
  }
  let n = random() < 0.55 ? 2 : 3;
  for (let k = 0; k < n; k++) {
    branch(px, py, a + random(-0.75, 0.75), len * random(0.6, 0.78), w * 0.64, depth - 1, s, root);
  }
}
function blossom(x, y, s) {
  noStroke();
  let pal = [color(244, 170, 190), color(255, 214, 140), color(250, 236, 220),
             s == 0 ? COOL_L : WARM_L, color(190, 140, 220)];
  for (let i = 0; i < 6; i++) {
    let c = mixOther(random(pal), x, y, s);
    fill(red(c), green(c), blue(c), random(110, 200));
    ellipse(x + random(-14, 14), y + random(-14, 14), random(5, 14), random(4, 11));
  }
}

// ---------- roots: hidden, interlaced ----------
function paintRoots() {
  for (let s = 0; s < 2; s++) {
    let bx = trunks[s][0].x, by = groundY(bx) + 10;
    for (let k = 0; k < 7; k++) {
      let a = s == 0 ? random(0.2, 2.4) : random(0.75, 2.95);
      branch(bx + random(-50, 50), by + random(0, 20), a, random(140, 220), random(14, 26), 5, s, true);
    }
  }
}

// ---------- light born between them ----------
function paintGlow(maxR, al) {
  blendMode(ADD);
  noStroke();
  for (let r = maxR; r > 10; r -= 8) {
    let t = r / 1000;
    fill(lerp(255, 180, t), lerp(190, 80, t), lerp(120, 70, t), al);
    ellipse(800, 1230, r * 1.15, r * 1.3);
  }
  blendMode(BLEND);
}

// ---------- trunks, woven strand by strand ----------
function paintTrunks() {
  for (let k = 0; k < 160; k++) {
    for (let s = 0; s < 2; s++) {
      let P = trunks[s];
      let base = s == 0 ? COOL : WARM, lite = s == 0 ? COOL_L : WARM_L;
      let dark = lerpColor(base, INK, 0.6);
      let o = random(-1, 1);
      let inner = s == 0 ? o : -o;
      let wt = random(3, 9);
      for (let t = 0; t < 1; t += 0.008) {
        let p1 = trunkEdge(P, t, o), p2 = trunkEdge(P, t + 0.008, o);
        let lit = constrain(map(inner, -1, 1, 0, 1) + (noise(p1.x * 0.02, p1.y * 0.02) - 0.5) * 0.6, 0, 1);
        let c = lerpColor(dark, lite, pow(lit, 1.4));
        if (lit > 0.85) c = lerpColor(c, GOLD, (lit - 0.85) * 3);
        c = mixOther(c, p1.x, p1.y, s);
        stroke(red(c), green(c), blue(c), 120);
        strokeWeight(wt * lerp(1, 0.5, t));
        line(p1.x, p1.y, p2.x, p2.y);
      }
    }
  }
}

// ---------- shared canopy ----------
function paintCanopy() {
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let x = 800 + randomGaussian() * 360, y = 470 + randomGaussian() * 200;
    let s = x < 800 ? 0 : 1;
    if (random() < 0.25) s = 1 - s;
    let c = mixOther(s == 0 ? COOL_L : WARM_L, x, y, s);
    fill(red(c), green(c), blue(c), 14);
    ellipse(x, y, random(30, 110), random(20, 70));
  }
  let ts = [0.5, 0.62, 0.72, 0.8, 0.87, 0.93];
  for (let s = 0; s < 2; s++) {
    let P = trunks[s];
    for (let i = 0; i < ts.length; i++) {
      let t = ts[i];
      let p = bezPt(P, t), tg = bezTan(P, t);
      let a = atan2(tg.y, tg.x);
      let outwardSign = s == 0 ? -1 : 1;
      let dir = (i < 2 || i % 2 == 0) ? outwardSign : -outwardSign;
      branch(p.x, p.y, a + dir * random(0.45, 0.85), random(150, 200) * (1.1 - t * 0.3),
             trunkW(t) * 0.32, 5, s, false);
    }
    let pe = bezPt(P, 1), te = bezTan(P, 1);
    branch(pe.x, pe.y, atan2(te.y, te.x), 190, trunkW(1) * 0.8, 6, s, false);
  }
}

// ---------- what grows underneath ----------
function paintGarden() {
  for (let i = 0; i < 2600; i++) {
    let x = random(W), gy = groundY(x);
    let near = exp(-sq((x - 800) / 350));
    let h = random(8, 40) * (1 + 1.2 * exp(-sq((x - 800) / 300)));
    let lean = random(-0.4, 0.4);
    let c = lerpColor(color(30, 40, 36), color(150, 150, 80), near * random(0.3, 1));
    stroke(red(c), green(c), blue(c), 150);
    strokeWeight(random(1, 2.5));
    line(x, gy + random(0, 10), x + lean * h, gy - h);
  }
  let pal = [color(150, 96, 196), color(70, 168, 160), color(250, 204, 96), color(236, 118, 140),
             color(252, 238, 214), color(110, 140, 230), color(232, 110, 70)];
  for (let i = 0; i < 170; i++) {
    let x = 800 + randomGaussian() * 190;
    if (x < 440 || x > 1160) continue;
    let gy = groundY(x) + random(0, 14);
    let h = random(30, 150) * exp(-sq((x - 800) / 400));
    let tx = x + random(-0.25, 0.25) * h, ty = gy - h;
    stroke(60, 90, 60, 200);
    strokeWeight(2);
    noFill();
    bezier(x, gy, x, gy - h * 0.5, tx, ty + h * 0.3, tx, ty);
    let c = random(pal);
    let r = random(7, 18);
    noStroke();
    fill(red(c), green(c), blue(c), 40);
    circle(tx, ty, r * 3);
    let off = random(TWO_PI);
    for (let p = 0; p < 5; p++) {
      let a = off + p * TWO_PI / 5;
      fill(red(c), green(c), blue(c), 200);
      ellipse(tx + cos(a) * r * 0.45, ty + sin(a) * r * 0.45, r * 0.7, r * 0.7);
    }
    fill(255, 236, 180, 230);
    circle(tx, ty, r * 0.35);
  }
}

// ---------- rising seeds of light ----------
function paintSeeds() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = 800 + randomGaussian() * 230;
    let y = 1250 - abs(randomGaussian()) * 450;
    let r = random(2, 6);
    fill(255, 220, 150, 30);
    circle(x, y, r * 5);
    fill(255, 240, 200, 200);
    circle(x, y, r);
  }
}

// ---------- grain and vignette ----------
function finishing() {
  for (let i = 0; i < 40000; i++) {
    stroke(random() < 0.5 ? 0 : 255, 10);
    strokeWeight(random(1, 2));
    point(random(W), random(H));
  }
  let g = drawingContext.createRadialGradient(800, 1100, 400, 800, 1100, 1300);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(8,4,12,0.65)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

const W = 1600, H = 2000, HOR = 1450;
const GW = 800, GH = 1000;
const ROSE = [242, 84, 108];
const GOLD = [255, 188, 92];
let A, B, reg, colBuf;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  A = makeForm(520, HOR + 60, 1010, 230, 0.09, 3.1, 1, [24, 14, 36], ROSE);
  B = makeForm(1090, HOR + 70, 930, 215, -0.09, 7.7, -1, [16, 16, 40], GOLD);
}

function draw() {
  renderBase();
  paintStrokes();
  drawStars();
  drawMotes();
  drawBlossoms();
  finish();
}

// ---------- utilitaires ----------
function sstep(a, b, x) {
  const t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function makeForm(cx, base, h, w, lean, sd, dir, body, col) {
  const f = { cx, base, h, w, lean, sd, dir, body, col,
    cen: new Float32Array(H), hw: new Float32Array(H) };
  for (let y = 0; y < H; y++) {
    const t = (base - y) / h;
    f.cen[y] = cx + lean * h * constrain(t, 0, 1) + 22 * (noise(sd + 10, y * 0.0015) - 0.5);
    if (t < 0 || t > 1) { f.hw[y] = -1; continue; }
    let p = sqrt(max(0, 1 - pow(t, 2.2))) * (1 - 0.18 * t);
    p *= 0.88 + 0.12 * sqrt(min(1, t / 0.05));
    const n = 1 + 0.12 * (noise(sd, y * 0.003) - 0.5) + 0.04 * (noise(sd + 5, y * 0.02) - 0.5);
    f.hw[y] = w * p * n;
  }
  f.lights = [];
  const ts = [0.16, 0.4, 0.64], ws = [0.8, 1.0, 0.75];
  for (let k = 0; k < 3; k++) {
    const y = floor(base - ts[k] * h);
    f.lights.push({ x: f.cen[y] + dir * (f.hw[y] + 16), y: y, w: ws[k] });
  }
  return f;
}

function inForm(f, x, y) {
  const yi = floor(y);
  if (yi < 0 || yi >= H) return false;
  const hw = f.hw[yi];
  if (hw <= 0) return false;
  return abs(x - f.cen[yi]) < hw;
}

function groundLine(x) {
  return HOR + 12 * (noise(x * 0.003, 77) - 0.5);
}

function region(x, y) {
  if (inForm(A, x, y)) return 1;
  if (inForm(B, x, y)) return 2;
  if (y < groundLine(x)) return 3;
  return 4;
}

function illum(L, x, y, fall) {
  let s = 0;
  const f2 = fall * fall;
  for (const l of L) {
    const dx = x - l.x, dy = y - l.y;
    s += l.w / (1 + (dx * dx + dy * dy) / f2);
  }
  return s;
}

// ---------- couleurs ----------
function bodyColor(f, o, x, y) {
  const yi = floor(y);
  const e = ((x - f.cen[yi]) / f.hw[yi]) * f.dir; // 1 = face tournée vers l'autre
  const t = constrain((f.base - y) / f.h, 0, 1);
  const lit = illum(o.lights, x, y, 240);
  const face = pow(constrain((e + 0.45) / 1.45, 0, 1), 1.7);
  const L = 1 - exp(-lit * face * 1.15);
  const n1 = noise(x * 0.005, y * 0.004, f.sd);
  const n2 = noise(x * 0.025, y * 0.01, f.sd + 2);
  const k = 0.7 + 0.6 * n1;
  const rim = pow(constrain(-e, 0, 1), 6) * 0.6;
  const top = pow(t, 5) * 0.5 * (0.5 + 0.5 * constrain(-e + 0.5, 0, 1));
  const warm = 0.85 + 0.3 * n2;
  const hot = pow(L, 3);
  const foot = 0.6 + 0.4 * sstep(0, 0.06, t);
  const cool = [34, 30, 70];
  const glow = [80, 68, 52];
  const c = [];
  for (let q = 0; q < 3; q++) {
    c[q] = (f.body[q] * k + o.col[q] * L * warm + cool[q] * (rim + top) + glow[q] * hot) * foot;
  }
  return c;
}

function skyColor(x, y) {
  const tt = pow(constrain(y / HOR, 0, 1), 1.6);
  const nn = noise(x * 0.0018, y * 0.0026, 20);
  const nn2 = noise(x * 0.006, y * 0.004, 30);
  let r = lerp(7, 40, tt) * (0.8 + 0.45 * nn);
  let g = lerp(8, 18, tt) * (0.8 + 0.45 * nn);
  let b = lerp(24, 48, tt) * (0.85 + 0.4 * nn);
  const la = illum(A.lights, x, y, 200), lb = illum(B.lights, x, y, 200);
  const mist = 0.75 + 0.5 * nn2;
  const ga = (1 - exp(-la * 0.55)) * mist, gb = (1 - exp(-lb * 0.55)) * mist;
  r += ROSE[0] * ga * 0.55 + GOLD[0] * gb * 0.55;
  g += ROSE[1] * ga * 0.55 + GOLD[1] * gb * 0.55;
  b += ROSE[2] * ga * 0.55 + GOLD[2] * gb * 0.55;
  const core = 1 - exp(-la * lb * 0.6);
  r += 70 * core; g += 52 * core; b += 34 * core;
  const dx = x - 812, dy = (y - 1150) * 0.8;
  const halo = 1 / (1 + (dx * dx + dy * dy) / (520 * 520));
  r += 38 * halo; g += 18 * halo; b += 22 * halo;
  return [r, g, b];
}

function shadowOf(f, x, y) {
  const u = (f.cx + f.dir * 0.3 * f.w - x) * f.dir;
  let s = 0;
  if (u > 0) {
    const yc = f.base - 4 - u * 0.09;
    const hh = 16 + u * 0.05;
    s = (1 - sstep(hh * 0.5, hh, abs(y - yc))) * exp(-u / 900);
  }
  const dx = (x - f.cx) / (f.w * 1.15), dy = (y - f.base) / 22;
  const contact = exp(-(dx * dx + dy * dy));
  return max(s, contact);
}

function groundLight(x, y) {
  let pa = 0, pb = 0;
  const f2 = 280 * 280;
  for (const l of A.lights) {
    const dx = x - l.x, dy = (y - A.base) * 2.4;
    pa += l.w / (1 + (dx * dx + dy * dy) / f2);
  }
  for (const l of B.lights) {
    const dx = x - l.x, dy = (y - B.base) * 2.4;
    pb += l.w / (1 + (dx * dx + dy * dy) / f2);
  }
  const sh = 1 - 0.85 * max(shadowOf(A, x, y), shadowOf(B, x, y));
  return [(1 - exp(-pa * 0.7)) * sh, (1 - exp(-pb * 0.7)) * sh];
}

function groundColor(x, y) {
  const g = pow(constrain((y - HOR) / (H - HOR), 0, 1), 0.7);
  const streak = noise(x * 0.0025, y * 0.025, 40);
  const fine = noise(x * 0.02, y * 0.05, 41);
  const m = 0.65 + 0.55 * streak + 0.15 * (fine - 0.5);
  let r = lerp(34, 9, g) * m, gg = lerp(20, 7, g) * m, b = lerp(32, 14, g) * m;
  const gl = groundLight(x, y);
  const k = 0.6 * (0.8 + 0.4 * streak);
  r += (ROSE[0] * gl[0] + GOLD[0] * gl[1]) * k;
  gg += (ROSE[1] * gl[0] + GOLD[1] * gl[1]) * k;
  b += (ROSE[2] * gl[0] + GOLD[2] * gl[1]) * k;
  return [r, gg, b];
}

// ---------- rendu de base ----------
function renderBase() {
  reg = new Uint8Array(GW * GH);
  colBuf = new Float32Array(GW * GH * 3);
  const img = createImage(GW, GH);
  img.loadPixels();
  for (let j = 0; j < GH; j++) {
    const y = j * 2 + 1;
    for (let i = 0; i < GW; i++) {
      const x = i * 2 + 1;
      const r = region(x, y);
      let c;
      if (r === 1) c = bodyColor(A, B, x, y);
      else if (r === 2) c = bodyColor(B, A, x, y);
      else if (r === 3) c = skyColor(x, y);
      else c = groundColor(x, y);
      const k = j * GW + i;
      reg[k] = r;
      for (let q = 0; q < 3; q++) {
        const v = constrain(c[q], 0, 255);
        colBuf[k * 3 + q] = v;
        img.pixels[k * 4 + q] = v;
      }
      img.pixels[k * 4 + 3] = 255;
    }
  }
  img.updatePixels();
  image(img, 0, 0, W, H);
}

function sampleAt(x, y) {
  const i = constrain(floor(x / 2), 0, GW - 1);
  const j = constrain(floor(y / 2), 0, GH - 1);
  const k = j * GW + i;
  return { r: reg[k], c: [colBuf[k * 3], colBuf[k * 3 + 1], colBuf[k * 3 + 2]] };
}

// ---------- touches de peinture ----------
function paintStrokes() {
  strokeCap(ROUND);
  const passes = [
    { n: 42000, wmin: 4, wmax: 9, lmin: 14, lmax: 40 },
    { n: 50000, wmin: 1.8, wmax: 4.5, lmin: 6, lmax: 20 }
  ];
  for (const p of passes) {
    for (let k = 0; k < p.n; k++) {
      const x = random(W), y = random(H);
      const s = sampleAt(x, y);
      const r = s.r;
      let ang;
      if (r === 1 || r === 2) {
        ang = HALF_PI + (noise(x * 0.004, y * 0.004, 9) - 0.5) * 0.5;
      } else if (r === 3) {
        const base = (noise(x * 0.0015, y * 0.0015, 11) - 0.5) * 1.6;
        const gp = exp(-pow((x - 812) / 150, 2));
        const up = -HALF_PI + (noise(x * 0.01, y * 0.004, 12) - 0.5) * 0.6;
        ang = lerp(base, up, gp);
      } else {
        ang = (noise(x * 0.003, y * 0.01, 13) - 0.5) * 0.25;
      }
      let len = random(p.lmin, p.lmax);
      if (r === 4) len *= 0.7 + (y - HOR) / (H - HOR);
      let ok = false;
      for (let tries = 0; tries < 2; tries++) {
        const dx = cos(ang) * len * 0.5, dy = sin(ang) * len * 0.5;
        if (sampleAt(x + dx, y + dy).r === r && sampleAt(x - dx, y - dy).r === r) { ok = true; break; }
        len *= 0.5;
      }
      if (!ok) continue;
      const j = random(-1, 1) * 9;
      const c = s.c;
      stroke(
        constrain(c[0] + j + random(-4, 4), 0, 255),
        constrain(c[1] + j + random(-4, 4), 0, 255),
        constrain(c[2] + j + random(-4, 4), 0, 255),
        random(110, 190)
      );
      strokeWeight(random(p.wmin, p.wmax));
      const dx = cos(ang) * len * 0.5, dy = sin(ang) * len * 0.5;
      line(x - dx, y - dy, x + dx, y + dy);
    }
  }
}

// ---------- étoiles ----------
function drawStars() {
  noStroke();
  for (let k = 0; k < 160; k++) {
    const x = random(W), y = random(0, 950);
    if (inForm(A, x, y) || inForm(B, x, y)) continue;
    if (abs(x - 812) < 220 && y > 350) continue;
    const s = random(1, 2.6);
    fill(230, 225, 255, random(40, 150));
    circle(x, y, s);
  }
}

// ---------- poussières de lumière dans l'écart ----------
function drawMotes() {
  blendMode(ADD);
  noStroke();
  for (let k = 0; k < 340; k++) {
    const y = random(1) < 0.8 ? random(520, 1480) : random(220, 520);
    const sd = 45 + max(0, 700 - y) * 0.35;
    const x = 812 + randomGaussian() * sd;
    if (inForm(A, x, y) || inForm(B, x, y)) continue;
    const t = constrain((x - 700) / 225, 0, 1);
    const c = [lerp(ROSE[0], GOLD[0], t), lerp(ROSE[1], GOLD[1], t), lerp(ROSE[2], GOLD[2], t)];
    const s = random(1.5, 5);
    fill(c[0], c[1], c[2], 10); circle(x, y, s * 7);
    fill(c[0], c[1], c[2], 35); circle(x, y, s * 2.6);
    fill(255, 238, 215, 150); circle(x, y, s * 0.8);
  }
  blendMode(BLEND);
}

// ---------- ce qui pousse dans la lumière ----------
function drawBlossoms() {
  const pal = [ROSE, GOLD, [255, 232, 205]];
  for (let k = 0; k < 240; k++) {
    const x = 812 + randomGaussian() * 200;
    const y = HOR + 15 + abs(randomGaussian()) * 170;
    if (y > H - 20) continue;
    if (inForm(A, x, y) || inForm(B, x, y)) continue;
    const gl = groundLight(x, y);
    const lvl = max(gl[0], gl[1]);
    if (lvl < 0.15) continue;
    const sc = map(y, HOR, H, 0.6, 1.8);
    const hx = x + random(-3, 3) * sc, hy = y - random(8, 20) * sc;
    stroke(28, 38, 30, 210);
    strokeWeight(1.2 * sc);
    line(x, y, hx, hy);
    noStroke();
    const pc = pal[floor(random(3))];
    const b = 0.35 + 0.9 * lvl;
    fill(min(255, pc[0] * b), min(255, pc[1] * b), min(255, pc[2] * b), 230);
    const rot = random(TWO_PI);
    for (let p = 0; p < 5; p++) {
      const a = rot + (p * TWO_PI) / 5;
      circle(hx + cos(a) * 1.8 * sc, hy + sin(a) * 1.8 * sc * 0.8, 2.6 * sc);
    }
    fill(255, 240, 210, 230);
    circle(hx, hy, 1.4 * sc);
  }
}

// ---------- vignette et grain ----------
function finish() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 4;
      const dx = (x - W * 0.5) / (W * 0.62), dy = (y - H * 0.5) / (H * 0.6);
      const v = 1 - 0.5 * pow(min(1, dx * dx + dy * dy), 1.4);
      const g = (random() - 0.5) * 10;
      pixels[i] = pixels[i] * v + g;
      pixels[i + 1] = pixels[i + 1] * v + g;
      pixels[i + 2] = pixels[i + 2] * v + g;
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  drawBackground();

  let foci = getFoci();

  // 1. Deep Atmospheric Glow
  drawAmbientGlow(foci);

  // 2. The Great Streams of Being (Thousands of flowing threads)
  drawLoveStreams(foci);

  // 3. The Sacred Intersection (Golden synthesis at the center)
  drawCoreUnion(foci);

  // 4. Stardust & Tenderness (Floating embers and quiet constellations)
  drawFloatingParticles(foci);

  // 5. Painterly Canvas Texture
  applyCanvasTexture();
}

function getFoci() {
  let list = [];
  let steps = 40;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let y = lerp(150, 1850, t);

    // Two paths that approach, embrace at the center, and expand into the heights
    let proximity = exp(-pow((y - 1050) / 380, 2));
    let separation = lerp(520, 45, proximity);

    // Gentle organic twist around the central axis
    let twist = sin(t * PI * 2.2 - 0.6) * 140 * (1 - proximity * 0.4);
    let centerShift = (noise(t * 2.5) - 0.5) * 160;

    let xA = 800 + centerShift - separation * 0.5 + twist;
    let xB = 800 + centerShift + separation * 0.5 - twist;

    list.push({
      y: y,
      xA: xA,
      xB: xB,
      cx: (xA + xB) * 0.5,
      prox: proximity,
      t: t
    });
  }
  return list;
}

function drawBackground() {
  // Deep cosmic indigo-violet void
  background(9, 7, 16);

  noStroke();
  for (let i = 0; i < 3500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let r = random(80, 350);

    if (n > 0.45) {
      fill(24, 14, 34, 4);
    } else {
      fill(10, 18, 28, 4);
    }
    circle(x, y, r);
  }
}

function drawAmbientGlow(foci) {
  blendMode(ADD);
  noStroke();

  for (let f of foci) {
    // Entity A: Warmth, incarnate crimson & terracotta
    for (let i = 0; i < 15; i++) {
      let rad = random(150, 600);
      fill(180, 35, 55, 1.5);
      circle(f.xA + randomGaussian(0, 60), f.y + randomGaussian(0, 60), rad);
    }

    // Entity B: Depth, infinite cerulean & teal
    for (let i = 0; i < 15; i++) {
      let rad = random(150, 600);
      fill(20, 110, 160, 1.5);
      circle(f.xB + randomGaussian(0, 60), f.y + randomGaussian(0, 60), rad);
    }

    // The Synthesis: Golden amber light where they draw near
    if (f.prox > 0.25) {
      let count = floor(f.prox * 35);
      for (let i = 0; i < count; i++) {
        let rad = random(100, 550) * f.prox;
        fill(230, 140, 50, 2.0 * f.prox);
        circle(f.cx + randomGaussian(0, 50), f.y + randomGaussian(0, 50), rad);
      }
    }
  }
  blendMode(BLEND);
}

function getFieldVector(x, y, foci, soulType) {
  // Find nearest vertical segment
  let idx = constrain(floor(map(y, 150, 1850, 0, foci.length - 1)), 0, foci.length - 1);
  let f = foci[idx];

  // Organic base turbulence
  let n1 = noise(x * 0.002, y * 0.002);
  let n2 = noise(x * 0.007 + 100, y * 0.007 + 100);
  let baseAngle = -HALF_PI + (n1 - 0.5) * PI * 1.1 + (n2 - 0.5) * 0.5;
  let vx = cos(baseAngle);
  let vy = sin(baseAngle) - 0.4; // Natural upward aspiration

  // Pull toward own trajectory and the beloved's trajectory
  let ownX = (soulType === 0) ? f.xA : f.xB;
  let otherX = (soulType === 0) ? f.xB : f.xA;

  // As proximity increases, the pull toward the shared center dominates
  let targetX = lerp(ownX, f.cx, pow(f.prox, 0.7));
  let distToTarget = targetX - x;

  // Gentle harmonic pull
  vx += distToTarget * 0.0035;

  // Swirl in the embrace zone
  let dCenter = dist(x, y, 800, 1020);
  if (dCenter < 550) {
    let swirlStrength = pow(map(dCenter, 0, 550, 1, 0), 1.5);
    let angleToCenter = atan2(y - 1020, x - 800);
    // Rotational dance + inward gravity
    let orbitAngle = angleToCenter + HALF_PI * 0.78;
    vx = lerp(vx, cos(orbitAngle), swirlStrength * 0.55);
    vy = lerp(vy, sin(orbitAngle) - 0.25, swirlStrength * 0.55);
  }

  let mag = sqrt(vx * vx + vy * vy) || 1;
  return { vx: vx / mag, vy: vy / mag, f: f };
}

function drawLoveStreams(foci) {
  let numParticles = 22000;

  let cCrimson = color(235, 50, 70);
  let cRose = color(255, 130, 155);
  let cCerulean = color(25, 165, 215);
  let cCyan = color(120, 235, 250);
  let cGold = color(255, 205, 95);
  let cWhite = color(255, 250, 240);

  noFill();

  for (let i = 0; i < numParticles; i++) {
    // Switch to additive blending for the final luminous layers
    if (i === floor(numParticles * 0.65)) {
      blendMode(ADD);
    }
    let isAdd = i >= floor(numParticles * 0.65);

    let soul = (i % 2 === 0) ? 0 : 1; // 0: Warm Soul, 1: Cool Soul

    // Spawn along the height, biased toward the lower/middle regions to flow upward
    let startT = pow(random(), 1.15);
    let fIdx = floor(startT * (foci.length - 1));
    let fStart = foci[fIdx];

    let originX = (soul === 0) ? fStart.xA : fStart.xB;
    let spread = lerp(240, 85, fStart.prox);
    let x = originX + randomGaussian(0, spread);
    let y = fStart.y + randomGaussian(0, 40);

    let steps = floor(random(35, 110));
    let stepSize = random(3.5, 6.5);

    // Individual color nuance
    let baseCol;
    if (soul === 0) {
      baseCol = lerpColor(cCrimson, cRose, random(0.85));
    } else {
      baseCol = lerpColor(cCerulean, cCyan, random(0.85));
    }

    // Measure how close this thread is to the union
    let dUnion = dist(x, y, fStart.cx, fStart.y);
    let unionFactor = constrain(map(dUnion, 320, 0, 0, 1), 0, 1) * fStart.prox;

    let finalCol = lerpColor(baseCol, cGold, pow(unionFactor, 0.75));
    if (unionFactor > 0.65) {
      finalCol = lerpColor(finalCol, cWhite, map(unionFactor, 0.65, 1, 0, 0.75));
    }

    let alpha = isAdd ? random(4, 14) : random(12, 32);
    stroke(red(finalCol), green(finalCol), blue(finalCol), alpha);
    strokeWeight(random(0.6, 2.6));

    beginShape();
    for (let s = 0; s < steps; s++) {
      vertex(x, y);
      let v = getFieldVector(x, y, foci, soul);
      x += v.vx * stepSize;
      y += v.vy * stepSize;

      if (x < 40 || x > width - 40 || y < 40 || y > height - 40) break;
    }
    endShape();
  }

  blendMode(BLEND);
}

function drawCoreUnion(foci) {
  blendMode(ADD);

  // 1. Filaments of connection bridging the two souls
  for (let i = 0; i < 1600; i++) {
    let f = random(foci);
    if (random() < f.prox * 1.15) {
      let y1 = f.y + randomGaussian(0, 35);
      let y2 = f.y + randomGaussian(0, 35);
      let x1 = f.xA + randomGaussian(0, 45);
      let x2 = f.xB + randomGaussian(0, 45);

      let cx1 = lerp(x1, x2, 0.3) + randomGaussian(0, 60);
      let cy1 = lerp(y1, y2, 0.3) - random(30, 140);
      let cx2 = lerp(x1, x2, 0.7) + randomGaussian(0, 60);
      let cy2 = lerp(y1, y2, 0.7) + random(30, 140);

      let alpha = f.prox * random(4, 16);
      if (random() < 0.5) {
        stroke(255, 190, 110, alpha);
      } else {
        stroke(255, 130, 160, alpha);
      }
      strokeWeight(random(0.5, 1.8));
      noFill();
      bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
    }
  }

  // 2. The Heart of the Embrace (Radiant center at y ~ 1020)
  noStroke();
  let heartX = 800;
  let heartY = 1020;
  for (let i = 0; i < 450; i++) {
    let angle = random(TWO_PI);
    let distR = abs(randomGaussian(0, 130));
    let px = heartX + cos(angle) * distR * 0.85;
    let py = heartY + sin(angle) * distR * 1.35;
    let rad = map(distR, 0, 350, 160, 20, true) * random(0.6, 1.4);

    fill(255, 225, 170, random(1.5, 4.5));
    circle(px, py, rad);
  }

  blendMode(BLEND);
}

function drawFloatingParticles(foci) {
  blendMode(ADD);
  noStroke();

  // Delicate sparks and constellations born from the encounter
  for (let i = 0; i < 2400; i++) {
    let f = random(foci);
    let spread = lerp(450, 180, f.prox);
    let x = f.cx + randomGaussian(0, spread);
    let y = f.y + randomGaussian(0, 50);

    let dToCenter = abs(x - f.cx);
    let isCore = dToCenter < 140 && f.prox > 0.5;

    let r = random(1.2, 4.5);
    if (random() < 0.04) r = random(5, 11); // Occasional bright star

    if (isCore) {
      fill(255, 240, 200, random(50, 180));
    } else if (x < f.cx) {
      fill(255, 110, 130, random(30, 120));
    } else {
      fill(110, 220, 255, random(30, 120));
    }

    circle(x, y, r);

    // Soft halo around larger sparks
    if (r > 4.0) {
      fill(255, 215, 160, 18);
      circle(x, y, r * 4.5);
      fill(255, 240, 220, 8);
      circle(x, y, r * 9.0);
    }
  }

  blendMode(BLEND);
}

function applyCanvasTexture() {
  // Subtle organic grain to give the warmth of oil/pastel on fine tooth paper
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Fine canvas weave + random pigment grain
      let weave = (sin(x * 0.9) + cos(y * 0.9)) * 1.8;
      let grain = (random() - 0.5) * 14 + weave;

      // Gentle vignette at the extreme edges
      let dx = (x - 800) / 800;
      let dy = (y - 1000) / 1000;
      let vig = constrain(1.0 - pow(dx * dx + dy * dy, 1.6) * 0.28, 0, 1);

      pixels[idx]     = constrain(pixels[idx] * vig + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * vig + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * vig + grain, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(8, 10, 18);

  // 1. Fond atmosphérique (Nébuleuse de l'existence)
  drawBackgroundNebula();

  // Configuration des centres de gravité des deux entités
  let centerA = createVector(width * 0.35, height * 0.65); // Entité A (Cyan/Bleu)
  let centerB = createVector(width * 0.65, height * 0.35); // Entité B (Magenta/Corail)
  let nexus = createVector(width * 0.5, height * 0.5);     // Le point de rencontre

  // 2. Halo lumineux au point de rencontre (L'émergence de l'amour)
  drawNexusGlow(nexus);

  // 3. Les courants de vie (Filaments génératifs)
  let numStrands = 3200;

  blendMode(ADD);
  for (let i = 0; i < numStrands; i++) {
    let isEntityA = i % 2 === 0;
    drawStrand(isEntityA, centerA, centerB, nexus);
  }

  // 4. Poussière d'étoiles et étincelles d'harmonie (Éclats d'or)
  drawSparks(nexus);

  // 5. Texture de toile / Grain photographique doux
  blendMode(OVERLAY);
  drawCanvasTexture();
}

function drawBackgroundNebula() {
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(200, 800);

    // Couleurs très sombres pour la profondeur
    let n = noise(x * 0.002, y * 0.002);
    if (n < 0.45) {
      fill(12, 20, 40, 6);
    } else if (n > 0.55) {
      fill(40, 12, 25, 6);
    } else {
      fill(25, 18, 35, 8);
    }
    circle(x, y, r);
  }
}

function drawNexusGlow(nexus) {
  blendMode(ADD);
  noStroke();

  // Grand halo doux
  for (let r = 1200; r > 0; r -= 15) {
    let inter = map(r, 0, 1200, 1, 0);
    let c = lerpColor(color(40, 10, 30, 0), color(255, 180, 100, 3), pow(inter, 2));
    fill(c);
    circle(nexus.x, nexus.y, r);
  }

  // Coeur incandescent
  for (let r = 400; r > 0; r -= 5) {
    let inter = map(r, 0, 400, 1, 0);
    fill(255, 220, 180, inter * 4);
    circle(nexus.x, nexus.y, r);
  }
}

function drawStrand(isA, centerA, centerB, nexus) {
  let pos = createVector();
  let origin = isA ? centerA : centerB;
  let other = isA ? centerB : centerA;

  // Distribution autour des centres respectifs, s'étirant vers les bords
  let angle = random(TWO_PI);
  let distFromCenter = randomGaussian(0, 350);
  pos.x = origin.x + cos(angle) * distFromCenter;
  pos.y = origin.y + sin(angle) * distFromCenter;

  // Certains fils partent des confins de la toile
  if (random() < 0.3) {
    pos.x = isA ? random(-100, width * 0.6) : random(width * 0.4, width + 100);
    pos.y = isA ? random(height * 0.4, height + 100) : random(-100, height * 0.6);
  }

  // Palettes de couleurs
  let baseColor;
  if (isA) {
    // Palette Froide : Bleu abysse, Cyan, Turquoise
    let c1 = color(10, 80, 180);
    let c2 = color(0, 210, 255);
    let c3 = color(80, 50, 220);
    baseColor = random() < 0.6 ? lerpColor(c1, c2, random()) : c3;
  } else {
    // Palette Chaude : Magenta, Cramoisi, Corail, Ambre
    let c1 = color(200, 20, 90);
    let c2 = color(255, 100, 60);
    let c3 = color(160, 10, 120);
    baseColor = random() < 0.6 ? lerpColor(c1, c2, random()) : c3;
  }

  let goldColor = color(255, 235, 170);

  let steps = int(random(150, 450));
  let stepSize = random(2, 4);
  let weight = random(0.5, 2.5);
  strokeWeight(weight);
  noFill();

  let prevPos = pos.copy();

  for (let s = 0; s < steps; s++) {
    // 1. Force du champ de bruit de Perlin (le chaos individuel)
    let nScale = 0.0025;
    let nAngle = noise(pos.x * nScale, pos.y * nScale, (isA ? 0 : 100)) * TWO_PI * 3;
    let force = p5.Vector.fromAngle(nAngle);
    force.mult(0.8);

    // 2. Force d'attraction vers le Nexus (L'Amour)
    let toNexus = p5.Vector.sub(nexus, pos);
    let dNexus = toNexus.mag();
    toNexus.normalize();

    // L'attraction est plus forte à moyenne distance, créant un vortex au centre
    let attractionStrength = map(constrain(dNexus, 50, 900), 50, 900, 0.2, 1.2);
    toNexus.mult(attractionStrength);

    // 3. Force de rotation (la danse autour du centre)
    let swirl = createVector(-toNexus.y, toNexus.x);
    let swirlStrength = map(constrain(dNexus, 0, 700), 0, 700, 1.8, 0.1);
    // Les deux entités tournent dans le même sens au centre (harmonie), mais s'approchent de manière opposée
    swirl.mult(swirlStrength);

    // 4. Légère attraction vers l'Autre
    let toOther = p5.Vector.sub(other, pos);
    toOther.normalize();
    toOther.mult(0.25);

    // Combinaison des forces
    let velocity = createVector(0, 0);
    velocity.add(force);
    velocity.add(toNexus);
    velocity.add(swirl);
    velocity.add(toOther);
    velocity.normalize();
    velocity.mult(stepSize);

    pos.add(velocity);

    // Calcul de la couleur en fonction de la proximité du Nexus et de la progression
    let proximityToLove = map(constrain(dNexus, 40, 500), 40, 500, 1, 0);
    proximityToLove = pow(proximityToLove, 1.5); // Courbe non-linéaire pour un coeur plus brillant

    let currentColor = lerpColor(baseColor, goldColor, proximityToLove);

    // Alpha basé sur le cycle de vie du fil (fondu en entrée et en sortie)
    let lifeRatio = s / steps;
    let alphaFade = sin(lifeRatio * PI); 
    let baseAlpha = map(proximityToLove, 0, 1, 12, 35);

    currentColor.setAlpha(baseAlpha * alphaFade);

    stroke(currentColor);
    line(prevPos.x, prevPos.y, pos.x, pos.y);

    prevPos.set(pos);
  }
}

function drawSparks(nexus) {
  noStroke();
  for (let i = 0; i < 1800; i++) {
    // Distribution concentrée autour du nexus et le long de la diagonale de rencontre
    let angle = random(TWO_PI);
    let r = abs(randomGaussian(0, 350));

    // Déformation elliptique pour suivre le flux de l'étreinte
    let x = nexus.x + cos(angle) * r;
    let y = nexus.y + sin(angle) * r;

    // Rotation des particules pour s'aligner avec la diagonale
    let d = dist(x, y, nexus.x, nexus.y);

    let sparkSize = random(0.8, 3.5);
    let alpha = map(constrain(d, 0, 600), 0, 600, 180, 10);

    if (random() < 0.7) {
      fill(255, 240, 200, alpha); // Or blanc
    } else if (random() < 0.5) {
      fill(100, 220, 255, alpha * 0.8); // Éclat cyan
    } else {
      fill(255, 120, 150, alpha * 0.8); // Éclat rose
    }

    circle(x, y, sparkSize);

    // Quelques étoiles plus grandes et brillantes au coeur
    if (d < 250 && random() < 0.03) {
      fill(255, 250, 240, 40);
      circle(x, y, sparkSize * 4);
      fill(255, 255, 255, 200);
      circle(x, y, sparkSize * 0.8);
    }
  }
}

function drawCanvasTexture() {
  // Ajoute une subtile texture organique pour donner un aspect peint/matériel
  noFill();
  strokeWeight(1);
  for (let i = 0; i < 25000; i++) {
    let x = random(width);
    let y = random(height);
    let l = random(5, 20);
    let a = random(TWO_PI);

    if (random() < 0.5) {
      stroke(255, 255, 255, 4);
    } else {
      stroke(0, 0, 0, 8);
    }
    line(x, y, x + cos(a) * l, y + sin(a) * l);
  }

  // Vignette douce pour refermer l'intimité du cadre
  blendMode(MULTIPLY);
  noStroke();
  for (let r = width * 0.8; r < width * 1.5; r += 20) {
    fill(10, 8, 15, 8);
    beginShape();
    vertex(0, 0);
    vertex(width, 0);
    vertex(width, height);
    vertex(0, height);
    beginContour();
    for (let a = TWO_PI; a > 0; a -= 0.1) {
      let vx = width / 2 + cos(a) * (r * 0.8);
      let vy = height / 2 + sin(a) * r;
      vertex(vx, vy);
    }
    endContour();
    endShape(CLOSE);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Définition des centres d'existence
  let pA = createVector(540, 1220); // L'essence d'eau et de nuit (Indigo / Cyan)
  let pB = createVector(1060, 780); // L'essence de feu et d'aurore (Cramoisi / Or)
  let pC = p5.Vector.add(pA, pB).mult(0.5); // Le lieu de la rencontre

  // 1. Fond cosmique profond
  background(7, 8, 16);

  // 2. Nébuleuses de fond (Atmosphère picturale)
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);

    let dA = dist(x, y, pA.x, pA.y);
    let dB = dist(x, y, pB.x, pB.y);
    let dC = dist(x, y, pC.x, pC.y);

    let r = 10, g = 15, b = 35, a = n * 4;

    if (dA < 850) {
      let f = pow(1 - dA / 850, 2);
      r += 15 * f;
      g += 85 * f;
      b += 160 * f;
      a += 5 * f;
    }
    if (dB < 850) {
      let f = pow(1 - dB / 850, 2);
      r += 180 * f;
      g += 45 * f;
      b += 65 * f;
      a += 5 * f;
    }
    if (dC < 650) {
      let f = pow(1 - dC / 650, 2.5);
      r += 220 * f;
      g += 170 * f;
      b += 110 * f;
      a += 6 * f;
    }

    fill(r, g, b, a);
    let rad = random(80, 320) * n;
    circle(x, y, rad);
  }

  // 3. Courants de conscience (Flots organiques qui cherchent l'autre)
  let numStreams = 7000;
  for (let i = 0; i < numStreams; i++) {
    let isA = random() < 0.5;
    let origin = isA ? pA : pB;
    let target = isA ? pB : pA;

    let angle = random(TWO_PI);
    let distFromOrigin = randomGaussian(0, 240);
    let pos = createVector(
      origin.x + cos(angle) * distFromOrigin,
      origin.y + sin(angle) * distFromOrigin
    );

    let cStart = isA ? color(15, 130, 210) : color(220, 40, 75);
    let cMid   = isA ? color(90, 210, 255) : color(255, 145, 60);
    let cLove  = color(255, 240, 215); 

    let maxSteps = int(random(90, 240));
    let stepSize = 3.5;

    noFill();
    strokeWeight(random(0.6, 2.4));

    let prevPos = pos.copy();

    for (let s = 0; s < maxSteps; s++) {
      let nAngle = noise(pos.x * 0.0025, pos.y * 0.0025, i * 0.0005) * TWO_PI * 3;
      let vNoise = p5.Vector.fromAngle(nAngle);

      // Gravité amoureuse vers l'autre
      let vTarget = p5.Vector.sub(target, pos);
      let dToTarget = vTarget.mag();
      vTarget.normalize();

      // Mouvement orbital doux autour du point de rencontre
      let vCenter = p5.Vector.sub(pC, pos);
      let dToCenter = vCenter.mag();
      let vSwirl = createVector(-vCenter.y, vCenter.x).normalize();
      if (!isA) vSwirl.mult(-1);

      let vel = createVector(0, 0);
      vel.add(vNoise.mult(1.3));
      vel.add(vTarget.mult(1.5));
      vel.add(vSwirl.mult(map(dToCenter, 0, 900, 1.8, 0.2, true)));
      vel.normalize().mult(stepSize);

      pos.add(vel);

      // Mutation de la couleur en approchant de l'autre et du centre
      let progress = s / maxSteps;
      let proximityToCenter = 1 - constrain(dToCenter / 480, 0, 1);

      let col = lerpColor(cStart, cMid, progress);
      col = lerpColor(col, cLove, pow(proximityToCenter, 1.6));

      let alpha = sin(progress * PI) * map(proximityToCenter, 0, 1, 16, 48);
      col.setAlpha(alpha);

      stroke(col);
      line(prevPos.x, prevPos.y, pos.x, pos.y);
      prevPos.set(pos);

      if (dToTarget < 35) break;
    }
  }

  // 4. Les Fils d'Or du Lien (Résonance directe entre les deux âmes)
  for (let i = 0; i < 1600; i++) {
    let spread = 320;
    let a1 = random(TWO_PI);
    let r1 = abs(randomGaussian(0, spread * 0.45));
    let x1 = pA.x + cos(a1) * r1;
    let y1 = pA.y + sin(a1) * r1;

    let a2 = random(TWO_PI);
    let r2 = abs(randomGaussian(0, spread * 0.45));
    let x2 = pB.x + cos(a2) * r2;
    let y2 = pB.y + sin(a2) * r2;

    let pull = random(-450, 450);
    let angleC = atan2(pB.y - pA.y, pB.x - pA.x) + HALF_PI;
    let cx1 = lerp(x1, pC.x, 0.5) + cos(angleC) * pull + random(-90, 90);
    let cy1 = lerp(y1, pC.y, 0.5) + sin(angleC) * pull + random(-90, 90);
    let cx2 = lerp(x2, pC.x, 0.5) - cos(angleC) * pull * 0.6 + random(-90, 90);
    let cy2 = lerp(y2, pC.y, 0.5) - sin(angleC) * pull * 0.6 + random(-90, 90);

    noFill();
    let c = lerpColor(color(255, 170, 80), color(200, 235, 255), random());
    c.setAlpha(random(5, 20));
    stroke(c);
    strokeWeight(random(0.4, 1.6));
    bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
  }

  // 5. Anneaux d'harmonie (Ondes de choc de la rencontre)
  for (let i = 0; i < 400; i++) {
    let rad = random(30, 800);
    let aStart = random(TWO_PI);
    let aEnd = aStart + random(PI * 0.15, PI * 0.8);

    let c = lerpColor(color(255, 200, 140), color(140, 210, 255), random());
    c.setAlpha(map(rad, 30, 800, 28, 2));
    stroke(c);
    strokeWeight(random(0.5, 2.2));
    noFill();

    push();
    translate(pC.x + random(-15, 15), pC.y + random(-15, 15));
    rotate(random(TWO_PI));
    scale(random(0.85, 1.15), random(0.85, 1.15));
    arc(0, 0, rad * 2, rad * 2, aStart, aEnd);
    pop();
  }

  // 6. Éclosion lumineuse et poussière d'étoiles (Empathie et transcendance)
  noStroke();
  for (let r = 550; r > 0; r -= 5) {
    let inter = map(r, 550, 0, 0, 1);
    let c = lerpColor(color(255, 130, 70, 0), color(255, 248, 235, 8), pow(inter, 1.5));
    fill(c);
    circle(pC.x, pC.y, r * 1.7);
  }

  // Présence des deux noyaux (Ils restent distincts, illuminés de l'intérieur)
  for (let r = 280; r > 0; r -= 4) {
    fill(40, 190, 255, map(r, 280, 0, 0, 6));
    circle(pA.x, pA.y, r);

    fill(255, 70, 95, map(r, 280, 0, 0, 6));
    circle(pB.x, pB.y, r);
  }

  // 7. Particules d'étincelles (La joie)
  for (let i = 0; i < 3500; i++) {
    let angle = random(TWO_PI);
    let d = abs(randomGaussian(0, 380));
    let x = pC.x + cos(angle) * d;
    let y = pC.y + sin(angle) * d;

    if (random() < 0.35) {
      let source = random() < 0.5 ? pA : pB;
      d = abs(randomGaussian(0, 220));
      x = source.x + cos(angle) * d;
      y = source.y + sin(angle) * d;
    }

    let s = random(0.8, 4.2);
    if (random() < 0.04) s = random(4.5, 9); 

    let c = color(255, random(215, 255), random(190, 255), random(40, 210));
    fill(c);
    circle(x, y, s);
  }

  // 8. Grain de toile (Finition matérielle)
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 120000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.5) {
      fill(255, 250, 240, random(2, 6));
    } else {
      fill(5, 5, 12, random(3, 8));
    }
    rect(x, y, 1.5, 1.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 1. Fond : L'immensité silencieuse avant la rencontre
  background(8, 10, 22);

  drawBackgroundNebula();

  // Définir les centres des deux entités (les deux solitudes)
  let c1 = createVector(620, 1080); // Entité chaude (Ancrage, passion, terre)
  let c2 = createVector(980, 920);  // Entité froide (Éther, souffle, ciel)
  let mid = p5.Vector.add(c1, c2).mult(0.5); // Le lieu de l'Amour

  // 2. Rayonnements sous-jacents (Auras)
  blendMode(ADD);
  drawAura(c1.x, c1.y, 900, color(180, 30, 60, 4));
  drawAura(c2.x, c2.y, 900, color(20, 120, 160, 4));
  drawAura(mid.x, mid.y, 1100, color(220, 140, 40, 5));

  // 3. Les courants de vie (Flux de particules qui s'entrelacent)
  let numStrands = 3500;
  for (let i = 0; i < numStrands; i++) {
    let isEntity1 = random() < 0.5;
    drawLoveStrand(isEntity1, c1, c2, mid);
  }

  // 4. Les filaments d'or (La transcendance née de l'union)
  for (let i = 0; i < 900; i++) {
    drawGoldenBridge(c1, c2, mid);
  }

  // 5. Les Noyaux (Préservation de l'essence individuelle de chacun)
  drawCore(c1.x, c1.y, color(255, 80, 100), color(255, 200, 180));
  drawCore(c2.x, c2.y, color(60, 200, 255), color(200, 245, 255));

  // L'étincelle centrale (Le "Nous")
  drawSpark(mid.x, mid.y);

  // 6. Poussière d'étoiles / Émanations (Ce que l'amour irradie vers le monde)
  drawEmanations(mid);

  // 7. Texture de toile / Grain pictural
  blendMode(OVERLAY);
  applyCanvasTexture();
}

function drawBackgroundNebula() {
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(200, 800);
    let n = noise(x * 0.002, y * 0.002);
    if (n > 0.4) {
      fill(15 + n * 20, 12 + n * 10, 35 + n * 30, 6);
      circle(x, y, r);
    }
  }
}

function drawAura(x, y, maxR, col) {
  noStroke();
  fill(col);
  for (let r = maxR; r > 0; r -= 15) {
    circle(x, y, r + random(-10, 10));
  }
}

function drawLoveStrand(isEntity1, c1, c2, mid) {
  // Départ autour de l'une des entités
  let origin = isEntity1 ? c1 : c2;
  let target = isEntity1 ? c2 : c1;

  let angle = random(TWO_PI);
  let distOrigin = randomGaussian(0, 180);
  let pos = createVector(
    origin.x + cos(angle) * distOrigin,
    origin.y + sin(angle) * distOrigin
  );

  let steps = int(random(150, 400));
  let stepSize = random(2, 4.5);

  // Couleurs de base
  let baseCol1 = color(230, random(20, 70), random(60, 110)); // Cramoisi / Rose
  let baseCol2 = color(random(20, 60), random(150, 210), 230); // Cyan / Bleu profond
  let goldCol = color(255, 215, 120); // Or lumineux

  let myBaseCol = isEntity1 ? baseCol1 : baseCol2;
  let otherBaseCol = isEntity1 ? baseCol2 : baseCol1;

  noFill();
  strokeWeight(random(0.5, 2.2));

  for (let s = 0; s < steps; s++) {
    let prevPos = pos.copy();

    // Vecteurs de force
    let toC1 = p5.Vector.sub(c1, pos);
    let toC2 = p5.Vector.sub(c2, pos);
    let toMid = p5.Vector.sub(mid, pos);

    let d1 = toC1.mag();
    let d2 = toC2.mag();
    let dMid = toMid.mag();

    // Force de rotation autour de sa propre origine
    let swirl1 = createVector(-toC1.y, toC1.x).normalize();
    // Force de rotation autour de l'autre (dans le sens harmonieux)
    let swirl2 = createVector(toC2.y, -toC2.x).normalize();

    // Attraction mutuelle
    let pullToOther = (isEntity1 ? toC2 : toC1).copy().normalize();
    let pullToCenter = toMid.copy().normalize();

    // Champ de bruit organique
    let n = noise(pos.x * 0.0025, pos.y * 0.0025, s * 0.005);
    let noiseVec = p5.Vector.fromAngle(n * TWO_PI * 2.5);

    // Combinaison des forces pour créer la danse
    let force = createVector(0, 0);
    force.add(swirl1.mult(1.2 / (1 + d1 * 0.002)));
    force.add(swirl2.mult(1.2 / (1 + d2 * 0.002)));
    force.add(pullToOther.mult(0.7));
    force.add(pullToCenter.mult(0.4 * sin(s * 0.02)));
    force.add(noiseVec.mult(0.9));

    force.normalize().mult(stepSize);
    pos.add(force);

    // Calcul de la couleur en fonction de la proximité avec l'autre et le centre
    let proximityToMid = constrain(map(dMid, 450, 0, 0, 1), 0, 1);
    let proximityToOther = constrain(map(isEntity1 ? d2 : d1, 600, 50, 0, 1), 0, 1);

    // Transition vers la couleur de l'autre (empathie) puis vers l'or (transcendance)
    let currentCol = lerpColor(myBaseCol, otherBaseCol, proximityToOther * 0.6);
    currentCol = lerpColor(currentCol, goldCol, pow(proximityToMid, 1.5) * 0.85);

    // Alpha doux aux extrémités de la trajectoire
    let lifeRatio = sin(map(s, 0, steps, 0, PI));
    let alphaVal = lifeRatio * map(proximityToMid, 0, 1, 12, 35);

    stroke(red(currentCol), green(currentCol), blue(currentCol), alphaVal);
    line(prevPos.x, prevPos.y, pos.x, pos.y);
  }
}

function drawGoldenBridge(c1, c2, mid) {
  // Ces lignes naissent directement dans l'espace "entre-deux"
  let t = random(0.1, 0.9);
  let startPt = p5.Vector.lerp(c1, c2, t);
  startPt.add(p5.Vector.random2D().mult(random(10, 220)));

  let pos = startPt.copy();
  let steps = int(random(60, 180));

  strokeWeight(random(0.4, 1.5));

  for (let s = 0; s < steps; s++) {
    let prev = pos.copy();

    let angle = noise(pos.x * 0.004, pos.y * 0.004) * TWO_PI * 2;
    let dir = p5.Vector.fromAngle(angle);

    // Légère attraction vers l'axe reliant c1 et c2
    let toMid = p5.Vector.sub(mid, pos).normalize().mult(0.6);
    dir.add(toMid).normalize().mult(2.5);

    pos.add(dir);

    let dMid = dist(pos.x, pos.y, mid.x, mid.y);
    let glow = constrain(map(dMid, 400, 0, 0, 1), 0, 1);
    let alphaVal = sin(map(s, 0, steps, 0, PI)) * (15 + glow * 40);

    stroke(255, random(200, 240), random(140, 200), alphaVal);
    line(prev.x, prev.y, pos.x, pos.y);
  }
}

function drawCore(x, y, outerCol, innerCol) {
  noStroke();
  // Halo du noyau
  for (let r = 250; r > 0; r -= 5) {
    let inter = map(r, 250, 0, 0, 1);
    let c = lerpColor(outerCol, innerCol, pow(inter, 2));
    fill(red(c), green(c), blue(c), map(r, 250, 0, 1, 15));

    // Forme légèrement organique
    beginShape();
    for (let a = 0; a < TWO_PI; a += PI / 16) {
      let nr = r * (0.9 + 0.2 * noise(x + cos(a) * 2, y + sin(a) * 2, r * 0.01));
      vertex(x + cos(a) * nr, y + sin(a) * nr);
    }
    endShape(CLOSE);
  }
}

function drawSpark(x, y) {
  // Le point de fusion lumineux où les deux regards/âmes se touchent
  noStroke();
  for (let r = 350; r > 0; r -= 4) {
    let alpha = map(r, 350, 0, 0.5, 8);
    fill(255, 235, 200, alpha);
    circle(x + random(-2, 2), y + random(-2, 2), r);
  }
}

function drawEmanations(mid) {
  // Petites braises de lumière qui s'élèvent et se répandent
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let angle = random(TWO_PI);
    // Distribution plus dense près du centre, s'étirant vers le haut et le bas
    let dist = pow(random(1), 1.8) * 1100;
    let x = mid.x + cos(angle) * dist * 0.8;
    let y = mid.y + sin(angle) * dist * 1.1;

    let sz = random(1, 5);
    let alpha = map(dist, 0, 1100, 180, 10) * random(0.3, 1);

    if (random() < 0.7) {
      fill(255, random(180, 230), random(120, 180), alpha);
    } else if (x < mid.x) {
      fill(255, 100, 130, alpha);
    } else {
      fill(100, 220, 255, alpha);
    }

    circle(x, y, sz);
    if (sz > 3.5) {
      fill(255, 255, 255, alpha * 0.5);
      circle(x, y, sz * 2.5);
    }
  }
}

function applyCanvasTexture() {
  // Ajoute une subtile texture de grain pictural
  noStroke();
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.5) {
      fill(255, 250, 240, random(3, 8));
    } else {
      fill(0, 5, 15, random(3, 8));
    }
    rect(x, y, random(1, 3), random(1, 3));
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Définition des centres des deux présences et de leur point de rencontre
  let f1 = createVector(520, 1120); // Présence d'ombre et d'eau (Indigo/Cyan)
  let f2 = createVector(1080, 880); // Présence de braise et de sang (Cramoisi/Corail)
  let mid = p5.Vector.lerp(f1, f2, 0.5); // Le berceau de lumière

  // 1. Fond cosmique profond
  background(7, 8, 16);

  // 2. Nébuleuses de fond (Atmosphère émotionnelle)
  noStroke();
  for (let i = 0; i < 3500; i++) {
    let x = random(-200, width + 200);
    let y = random(-200, height + 200);
    let n = noise(x * 0.0012, y * 0.0012);
    let d1 = dist(x, y, f1.x, f1.y);
    let d2 = dist(x, y, f2.x, f2.y);
    let dMid = dist(x, y, mid.x, mid.y);

    let r = 12, g = 14, b = 28, a = 12;
    if (d1 < 800) {
      r = lerp(r, 20, 1 - d1 / 800);
      g = lerp(g, 75, 1 - d1 / 800);
      b = lerp(b, 140, 1 - d1 / 800);
    }
    if (d2 < 800) {
      r = lerp(r, 150, 1 - d2 / 800);
      g = lerp(g, 25, 1 - d2 / 800);
      b = lerp(b, 65, 1 - d2 / 800);
    }
    if (dMid < 500) {
      r = lerp(r, 220, 1 - dMid / 500);
      g = lerp(g, 150, 1 - dMid / 500);
      b = lerp(b, 70, 1 - dMid / 500);
    }

    fill(r, g, b, a * n);
    let rad = random(80, 350) * n;
    circle(x, y, rad);
  }

  // 3. Champ de flux : Les courants de vie qui traversent l'espace
  blendMode(ADD);
  for (let i = 0; i < 4500; i++) {
    let p = createVector(random(width), random(height));
    let col;
    let d1 = p.dist(f1);
    let d2 = p.dist(f2);

    // Attribution des couleurs selon la proximité des âmes
    if (d1 < d2 * 0.85) {
      col = color(25, random(90, 160), random(180, 240), 5);
    } else if (d2 < d1 * 0.85) {
      col = color(random(190, 250), random(35, 90), random(65, 120), 5);
    } else {
      col = color(255, random(170, 220), random(100, 160), 7);
    }

    stroke(col);
    strokeWeight(random(0.5, 2.2));
    noFill();

    beginShape();
    for (let s = 0; s < 70; s++) {
      vertex(p.x, p.y);

      // Angle dicté par le bruit de Perlin + attraction vers le centre
      let nAngle = noise(p.x * 0.002, p.y * 0.002) * TWO_PI * 2.5;
      let vToMid = p5.Vector.sub(mid, p);
      let distMid = vToMid.mag();
      vToMid.normalize();

      // Tourbillon doux autour du centre d'amour
      let swirl = createVector(-vToMid.y, vToMid.x).mult(1.5);
      let flow = p5.Vector.fromAngle(nAngle);

      let force = p5.Vector.lerp(flow, swirl, constrain(1 - distMid / 900, 0, 0.75));
      force.add(vToMid.mult(0.4));
      force.normalize().mult(5);

      p.add(force);
    }
    endShape();
  }

  // 4. L'Étreinte : Les fils de connexion directe entre les deux êtres
  for (let i = 0; i < 1600; i++) {
    let t = random(1);
    let angle1 = random(TWO_PI);
    let r1 = pow(random(1), 2) * 280;
    let start = createVector(f1.x + cos(angle1) * r1, f1.y + sin(angle1) * r1);

    let angle2 = random(TWO_PI);
    let r2 = pow(random(1), 2) * 280;
    let end = createVector(f2.x + cos(angle2) * r2, f2.y + sin(angle2) * r2);

    // Points de contrôle qui s'ouvrent comme des bras ou un cœur abstrait
    let spread = random(-550, 550);
    let cp1 = createVector(
      lerp(start.x, end.x, 0.3) + spread * 0.8 + (noise(i * 0.1) - 0.5) * 350,
      lerp(start.y, end.y, 0.3) - spread * 0.6 + (noise(i * 0.1 + 50) - 0.5) * 350
    );
    let cp2 = createVector(
      lerp(start.x, end.x, 0.7) - spread * 0.6 + (noise(i * 0.1 + 100) - 0.5) * 350,
      lerp(start.y, end.y, 0.7) + spread * 0.8 + (noise(i * 0.1 + 150) - 0.5) * 350
    );

    // Dessin de la courbe en segments pour un dégradé de couleur fluide
    let steps = 50;
    strokeWeight(random(0.4, 2.5));
    for (let s = 0; s < steps; s++) {
      let st1 = s / steps;
      let st2 = (s + 1) / steps;

      let x1 = bezierPoint(start.x, cp1.x, cp2.x, end.x, st1);
      let y1 = bezierPoint(start.y, cp1.y, cp2.y, end.y, st1);
      let x2 = bezierPoint(start.x, cp1.x, cp2.x, end.x, st2);
      let y2 = bezierPoint(start.y, cp1.y, cp2.y, end.y, st2);

      // Transition : Cyan -> Or Incandescent -> Cramoisi
      let c;
      if (st1 < 0.5) {
        c = lerpColor(color(30, 170, 255, 10), color(255, 225, 140, 22), st1 * 2);
      } else {
        c = lerpColor(color(255, 225, 140, 22), color(255, 50, 100, 10), (st1 - 0.5) * 2);
      }
      stroke(c);
      line(x1, y1, x2, y2);
    }
  }

  // 5. Incarnation des deux âmes (Texturation picturale et organique)
  blendMode(BLEND);
  drawBeing(f1.x, f1.y, color(12, 35, 85), color(50, 190, 245), f2);
  drawBeing(f2.x, f2.y, color(105, 15, 45), color(255, 85, 110), f1);

  // 6. La Résonance : La lumière qui naît dans l'écart
  blendMode(ADD);
  for (let i = 0; i < 900; i++) {
    let ang = random(TWO_PI);
    let distFromCenter = pow(random(1), 2.5) * 450;
    // Forme elliptique orientée le long de la frontière entre les deux êtres
    let x = mid.x + cos(ang) * distFromCenter * 0.7 - sin(ang) * distFromCenter * 0.4;
    let y = mid.y + sin(ang) * distFromCenter * 1.1 + cos(ang) * distFromCenter * 0.4;

    let sz = random(5, 90) * (1 - distFromCenter / 500);
    noStroke();
    fill(255, random(180, 240), random(110, 190), random(3, 12));
    circle(x, y, sz);
  }

  // Filaments d'or pur au cœur de la rencontre
  for (let i = 0; i < 350; i++) {
    let p = createVector(mid.x + random(-180, 180), mid.y + random(-220, 220));
    stroke(255, 240, 190, random(15, 45));
    strokeWeight(random(0.5, 1.8));
    noFill();
    beginShape();
    for (let s = 0; s < 35; s++) {
      vertex(p.x, p.y);
      let a = noise(p.x * 0.008, p.y * 0.008) * TWO_PI * 2;
      p.x += cos(a) * 4;
      p.y += sin(a) * 4;
    }
    endShape();
  }

  // Poussière d'étoiles / Braises d'émotion qui s'élèvent
  for (let i = 0; i < 1200; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, mid.x, mid.y);
    if (random(1) > pow(d / 1100, 0.6)) {
      noStroke();
      let alpha = random(40, 200) * (1 - d / 1200);
      fill(255, random(210, 250), random(160, 230), alpha);
      let r = random(1, 4.5);
      circle(x, y, r);
      if (r > 3.2) {
        fill(255, 220, 170, alpha * 0.25);
        circle(x, y, r * 4);
      }
    }
  }

  // 7. Grain de toile et patine finale
  blendMode(OVERLAY);
  noStroke();
  for (let i = 0; i < 35000; i++) {
    let x = random(width);
    let y = random(height);
    if (random(1) > 0.5) {
      fill(255, 250, 240, 4);
    } else {
      fill(0, 5, 15, 6);
    }
    rect(x, y, random(1, 3), random(1, 3));
  }
}

// Fonction pour peindre chaque présence avec une vulnérabilité tournée vers l'autre
function drawBeing(cx, cy, deepCol, brightCol, otherPos) {
  let center = createVector(cx, cy);
  let toOther = p5.Vector.sub(otherPos, center).normalize();

  // Couches d'impasto organique
  for (let i = 0; i < 4000; i++) {
    let r = pow(random(1), 1.6) * 340;
    let a = random(TWO_PI);
    let dir = createVector(cos(a), sin(a));

    // Déformation de l'âme qui s'étire vers l'autre
    let pull = max(0, dir.dot(toOther));
    r += pow(pull, 2) * 140 * random(0.4, 1.2);

    let x = cx + dir.x * r;
    let y = cy + dir.y * r;

    let n = noise(x * 0.008, y * 0.008);
    let c = lerpColor(deepCol, brightCol, constrain(1 - r / 380 + (n - 0.5) * 0.4, 0, 1));

    // Auras dorées sur la rive qui fait face à l'autre
    if (pull > 0.45 && r > 120) {
      c = lerpColor(c, color(255, 215, 135), (pull - 0.45) * 1.4);
    }

    c.setAlpha(random(12, 45));
    noStroke();
    fill(c);

    push();
    translate(x, y);
    // Orientation des coups de pinceau en courbe autour du noyau et vers l'autre
    let strokeAngle = a + HALF_PI + n * 1.5;
    if (pull > 0.3) {
      strokeAngle = lerp(strokeAngle, toOther.heading(), pull * 0.7);
    }
    rotate(strokeAngle);
    let w = random(12, 65) * (1 - r / 520);
    let h = random(3, 18) * (1 - r / 520);
    ellipse(0, 0, w, h);
    pop();
  }

  // Noyau intérieur lumineux (Le soi profond qui reste intact)
  blendMode(ADD);
  for (let i = 0; i < 300; i++) {
    let r = pow(random(1), 2) * 110;
    let a = random(TWO_PI);
    let c = lerpColor(brightCol, color(255, 245, 225), 1 - r / 110);
    c.setAlpha(random(8, 25));
    fill(c);
    noStroke();
    circle(cx + cos(a) * r, cy + sin(a) * r, random(10, 55));
  }
  blendMode(BLEND);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  angleMode(RADIANS);
  ellipseMode(CENTER);
