function dab(x, y, w, h, rot, r, g, b, a) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(r, g, b, a);
  ellipse(0, 0, w, h);
  pop();
}

function glow(x, y, w, h, r, g, b, a) {
  noStroke();
  const n = 8;
  for (let i = n; i >= 1; i--) {
    const t = i / n;
    const fall = Math.pow(1 - t, 2);
    fill(r, g, b, Math.min(255, a * (0.2 + 0.8 * fall)));
    ellipse(x, y, Math.max(1, w * t), Math.max(1, h * t));
  }
}

function paintAtmosphere() {
  for (let i = 0; i < 36; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.0015, y * 0.0015);
    const rr = lerp(28, 68, n);
    const gg = lerp(10, 32, n * n);
    const bb = lerp(16, 30, 1 - n);
    const s = random(300, 1000);
    glow(x, y, s, s * random(0.72, 1.3), rr, gg, bb, 13);
  }
  glow(800, 980, 1100, 1280, 96, 38, 30, 15);
  glow(770, 880, 700, 860, 148, 68, 36, 11);
  glow(180, 150, 1000, 800, 16, 20, 46, 13);
  glow(1460, 130, 920, 760, 14, 18, 42, 11);
  glow(800, 1980, 2100, 920, 8, 4, 7, 24);
}

function paintPools() {
  glow(450, 1740, 360, 210, 124, 36, 42, 14);
  glow(430, 1790, 170, 96, 186, 62, 52, 12);
  glow(1180, 1765, 380, 220, 146, 82, 32, 13);
  glow(1210, 1810, 160, 86, 206, 132, 52, 11);
}

function riverPoint(side, t) {
  const y0 = side === 0 ? 1870 : 1895;
  const y1 = side === 0 ? 340 : 305;
  let y = lerp(y0, y1, t);
  y += (noise(12 + side, t * 1.6) - 0.5) * 26;
  const pull = Math.exp(-Math.pow((t - 0.62) / 0.28, 2));
  let x;
  if (side === 0) {
    const spine = lerp(410, 548, t);
    x = lerp(spine, 648, pull * 0.92);
    x += (noise(1.2, t * 1.25) - 0.5) * 64;
  } else {
    const spine = lerp(1210, 1060, t);
    x = lerp(spine, 928, pull * 0.9);
    x += (noise(2.6, t * 1.25) - 0.5) * 64;
  }
  return { x, y, pull };
}

function riverColor(side, t, across, pull) {
  let r, g, b;
  if (side === 0) {
    r = lerp(102, 198, t);
    g = lerp(30, 82, t);
    b = lerp(44, 74, t);
    if (across > 0.12) {
      const f = constrain((across - 0.12) / 0.38, 0, 1);
      r = lerp(r, 248, f * (0.3 + pull * 0.55));
      g = lerp(g, 156, f * (0.22 + pull * 0.5));
      b = lerp(b, 118, f * 0.28);
    }
    if (across < -0.22) {
      const f = constrain((-across - 0.22) / 0.28, 0, 1);
      r *= lerp(1, 0.62, f);
      g *= lerp(1, 0.6, f);
      b *= lerp(1, 0.68, f);
    }
  } else {
    r = lerp(124, 220, t);
    g = lerp(64, 148, t);
    b = lerp(26, 58, t);
    if (across < -0.12) {
      const f = constrain((-across - 0.12) / 0.38, 0, 1);
      r = lerp(r, 255, f * (0.28 + pull * 0.5));
      g = lerp(g, 198, f * (0.28 + pull * 0.48));
      b = lerp(b, 132, f * 0.32);
    }
    if (across > 0.22) {
      const f = constrain((across - 0.22) / 0.28, 0, 1);
      r *= lerp(1, 0.7, f);
      g *= lerp(1, 0.68, f);
      b *= lerp(1, 0.62, f);
    }
    if (across > 0.18 && noise(t * 3.3, 11) > 0.72) {
      r = lerp(r, 62, 0.5);
      g = lerp(g, 112, 0.55);
      b = lerp(b, 96, 0.5);
    }
  }
  r = lerp(r, 255, pull * 0.12);
  g = lerp(g, 214, pull * 0.1);
  b = lerp(b, 170, pull * 0.06);
  return {
    r: constrain(r, 0, 255),
    g: constrain(g, 0, 255),
    b: constrain(b, 0, 255)
  };
}

function paintRiverHalo(side) {
  for (let i = 0; i <= 7; i++) {
    const t = 0.12 + (i / 7) * 0.72;
    const p = riverPoint(side, t);
    if (side === 0) glow(p.x, p.y, 310, 220, 164, 48, 54, 7);
    else glow(p.x, p.y, 310, 220, 176, 104, 42, 7);
  }
}

function paintRiver(side) {
  const steps = 480;
  let prev = riverPoint(side, 0);
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const p = riverPoint(side, t);
    const ang = Math.atan2(p.y - prev.y, p.x - prev.x);
    let fade = 1;
    if (t < 0.05) fade = t / 0.05;
    if (t > 0.84) fade *= (1 - t) / 0.16;
    const thick = lerp(88, 16, t) * (0.85 + 0.38 * p.pull) * (0.7 + 0.45 * noise(side * 4, t * 2.5));
    const strands = 8;
    for (let s = 0; s < strands; s++) {
      const across = s / (strands - 1) - 0.5;
      const ox = Math.cos(ang + HALF_PI) * across * thick;
      const oy = Math.sin(ang + HALF_PI) * across * thick * 0.42;
      const j = (noise(side + 1, t * 5, s * 0.4) - 0.5) * 8;
      const c = riverColor(side, t, across, p.pull);
      const edge = Math.abs(across) * 2;
      const a = fade * (10 + (1 - edge) * 18 + p.pull * 16);
      const len = thick * (0.42 + noise(t * 3, s) * 0.58);
      dab(
        p.x + ox + j,
        p.y + oy,
        len,
        2.1 + (1 - edge) * 4.6,
        ang + (noise(s, t) - 0.5) * 0.45,
        c.r, c.g, c.b, a
      );
    }
    if (i % 5 === 0) {
      const c = riverColor(side, t, side === 0 ? 0.28 : -0.28, p.pull);
      glow(p.x, p.y, thick * 1.7, thick, c.r, c.g, c.b, 5 * fade);
    }
    prev = p;
  }
}

function paintPassage(amount) {
  glow(800, 910, 460, 560, 255, 196, 148, amount);
  glow(724, 960, 250, 330, 206, 74, 68, amount * 0.65);
  glow(878, 948, 240, 310, 228, 158, 58, amount * 0.6);
  glow(796, 868, 168, 210, 255, 238, 216, amount * 1.05);
}

function paintFilaments(side) {
  for (let k = 0; k < 5; k++) {
    const dir = side === 0 ? 1 : -1;
    let x = side === 0 ? 650 : 950;
    let y = 836 + k * 52 + (noise(k, side * 2) - 0.5) * 16;
    for (let i = 0; i < 34; i++) {
      const t = i / 33;
      x += dir * (6.2 + noise(k, t, side) * 2.4);
      y += (noise(k, t, side + 4) - 0.5) * 6.5;
      const a = Math.sin(t * Math.PI) * 24;
      if (side === 0) dab(x, y, 16, 2.3, (noise(k, t, 6) - 0.5) * 0.5, 214, 98, 90, a);
      else dab(x, y, 16, 2.3, (noise(k, t, 6) - 0.5) * 0.5, 232, 172, 78, a);
    }
  }
}

function paintArch() {
  const cx = 792;
  const cy = 928;
  const rx = 156;
  const ry = 286;
  const start = -HALF_PI + 0.92;
  const end = -HALF_PI + TWO_PI - 0.92;
  for (let i = 0; i < 220; i++) {
    const u = i / 219;
    const ang = lerp(start, end, u);
    const wob = (noise(i * 0.07, 6) - 0.5) * 20;
    const flick = 0.45 + noise(i * 0.16, 2) * 0.55;
    const x = cx + Math.cos(ang) * (rx + wob);
    const y = cy + Math.sin(ang) * (ry + wob * 0.75);
    const xIn = cx + Math.cos(ang) * (rx * 0.7 + wob * 0.4);
    const yIn = cy + Math.sin(ang) * (ry * 0.7 + wob * 0.3);
    dab(x, y, 24 * flick, 6.5, ang + HALF_PI, 255, 208, 164, 26 * flick);
    dab(xIn, yIn, 12 * flick, 3.4, ang + HALF_PI, 255, 244, 228, 34 * flick);
  }
}

function paintSpill() {
  for (let i = 0; i < 72; i++) {
    const t = i / 71;
    const y = lerp(900, 8, Math.pow(t, 0.85));
    const x = 804 + Math.sin(t * 2.1) * 28 + (noise(t * 1.35, 8) - 0.5) * lerp(24, 170, t);
    const w = lerp(210, 42, t) * (0.78 + noise(t * 2, 3) * 0.4);
    glow(x, y, w, lerp(86, 32, t), 255, lerp(214, 168, t), lerp(162, 108, t), 9 * (1 - t * 0.5));
  }
  glow(640, 300, 180, 460, 176, 72, 64, 5);
  glow(990, 250, 160, 420, 196, 142, 64, 5);
}

function paintFarLights() {
  glow(336, 248, 64, 64, 188, 68, 58, 16);
  glow(1190, 156, 46, 46, 220, 158, 68, 15);
  glow(724, 86, 26, 26, 255, 230, 202, 18);
  glow(990, 328, 34, 34, 198, 88, 68, 11);
  glow(548, 132, 20, 20, 228, 176, 96, 13);
}

function paintSparks() {
  blendMode(ADD);
  for (let i = 0; i < 90; i++) {
    const y = lerp(880, 12, Math.pow(noise(i * 0.13, 2), 0.72));
    const spread = lerp(70, 540, constrain((880 - y) / 880, 0, 1));
    const x = 800 + (noise(i * 0.17, 5) - 0.5) * spread * 1.7;
    const s = 4 + noise(i * 0.3, 1) * 13;
    if (noise(i, 9) > 0.52) glow(x, y, s * 3.2, s * 3.2, 255, 136, 108, 17);
    else glow(x, y, s * 3.2, s * 3.2, 255, 198, 118, 15);
    if (noise(i, 4) > 0.4) {
      stroke(255, 236, 210, 150);
      strokeWeight(1.25);
      point(x, y);
    }
  }
  for (let i = 0; i < 36; i++) {
    const x = random(width);
    const y = random(height * 0.7, height);
    const s = random(3, 8);
    glow(x, y, s * 2.4, s * 2.4, 255, random(140, 205), 88, 11);
  }
  blendMode(BLEND);
  noStroke();
}

function paintVignette() {
  glow(-80, -60, 1500, 1100, 6, 3, 6, 36);
  glow(width + 80, -40, 1400, 1000, 6, 3, 6, 34);
  glow(width / 2, -180, 1900, 640, 8, 4, 8, 30);
  glow(-160, height + 40, 1700, 860, 5, 2, 4, 40);
  glow(width + 160, height + 40, 1700, 860, 5, 2, 4, 40);
  glow(width / 2, height + 160, 2100, 720, 6, 3, 5, 36);
  glow(-220, height * 0.55, 640, 2000, 6, 3, 6, 28);
  glow(width + 220, height * 0.55, 640, 2000, 6, 3, 6, 28);
}

function paintGrain() {
  strokeWeight(1);
  for (let i = 0; i < 7000; i++) {
    const x = random(width);
    const y = random(height);
    if (i % 3 === 0) stroke(18, 7, 11, random(8, 20));
    else stroke(255, 226, 196, random(3, 11));
    point(x, y);
  }
  noStroke();
}

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  colorMode(RGB, 255);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  noiseDetail(4, 0.5);
  const ctx = drawingContext;
  ctx.globalCompositeOperation = "source-over";
  ctx.globalAlpha = 1;
  paintGround(ctx);
  paintChamber(ctx);
  paintVessel(ctx, 0);
  paintVessel(ctx, 1);
  paintInterval(ctx);
  paintArch(ctx);
  paintSeeds(ctx);
  paintRise(ctx);
  paintPool(ctx);
  paintMotes(ctx);
  paintVignette(ctx);
  grain();
}

function rgba(r, g, b, a) {
  return "rgba(" + (r | 0) + "," + (g | 0) + "," + (b | 0) + "," + a + ")";
}

function soft(ctx, x, y, r, R, G, B, a) {
  if (r <= 0.5 || a <= 0.003) return;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, rgba(R, G, B, a));
  g.addColorStop(1, rgba(R, G, B, 0));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
}

function brush(ctx, x, y, len, ang, w, R, G, B, a) {
  ctx.strokeStyle = rgba(R, G, B, a);
  ctx.lineWidth = w;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + Math.cos(ang) * len, y + Math.sin(ang) * len);
  ctx.stroke();
}

function radiusAt(t) {
  const chest = Math.exp(-((t - 0.5) * (t - 0.5)) / (2 * 0.22 * 0.22)) * 108;
  const shoulder = Math.exp(-((t - 0.21) * (t - 0.21)) / (2 * 0.07 * 0.07)) * 14;
  return 26 + chest + shoulder;
}

function presence(t, side) {
  const y = (side === 0 ? 620 : 646) + t * 760;
  const bow = Math.sin(Math.PI * t);
  const x = side === 0 ? 620 + 28 * bow : 980 - 26 * bow;
  const r = radiusAt(t) * (side === 0 ? 1 : 0.94);
  return { x: x, y: y, r: r, bow: bow };
}

function paintGround(ctx) {
  ctx.fillStyle = "#1a0e0c";
  ctx.fillRect(0, 0, W, H);

  const warm = ctx.createLinearGradient(0, 0, 1200, 0);
  warm.addColorStop(0, "rgba(78, 30, 22, 0.34)");
  warm.addColorStop(1, "rgba(78, 30, 22, 0)");
  ctx.fillStyle = warm;
  ctx.fillRect(0, 0, 1200, H);

  const cool = ctx.createLinearGradient(W, 0, 420, 0);
  cool.addColorStop(0, "rgba(12, 28, 38, 0.40)");
  cool.addColorStop(1, "rgba(12, 28, 38, 0)");
  ctx.fillStyle = cool;
  ctx.fillRect(420, 0, W - 420, H);

  const top = ctx.createLinearGradient(0, 0, 0, 780);
  top.addColorStop(0, "rgba(5, 7, 14, 0.84)");
  top.addColorStop(1, "rgba(5, 7, 14, 0)");
  ctx.fillStyle = top;
  ctx.fillRect(0, 0, W, 780);

  const bot = ctx.createLinearGradient(0, 1360, 0, H);
  bot.addColorStop(0, "rgba(10, 5, 4, 0)");
  bot.addColorStop(1, "rgba(8, 4, 3, 0.72)");
  ctx.fillStyle = bot;
  ctx.fillRect(0, 1360, W, H - 1360);

  soft(ctx, 800, 260, 420, 16, 30, 54, 0.18);
  soft(ctx, 760, 230, 160, 36, 54, 82, 0.06);

  for (let i = 0; i < 90; i++) {
    const x = noise(i * 0.17, 1) * W;
    const y = noise(i * 0.17, 2) * H;
    const coolN = noise(i * 0.2, 3);
    const R = coolN > 0.55 ? 18 + coolN * 20 : 46 + coolN * 30;
    const G = coolN > 0.55 ? 26 : 20;
    const B = coolN > 0.55 ? 38 : 18;
    soft(ctx, x, y, 70 + noise(i, 4) * 80, R, G, B, 0.035);
  }

  for (let i = 0; i < 36; i++) {
    const x = noise(i * 0.3, 6) * 460;
    const y = noise(i * 0.3, 7) * H;
    const h = 180 + noise(i, 8) * 520;
    ctx.fillStyle = rgba(32, 14, 16, 0.035);
    ctx.fillRect(x, y, 8 + noise(i, 9) * 18, h);
  }
  for (let i = 0; i < 36; i++) {
    const x = 1140 + noise(i * 0.3, 10) * 420;
    const y = noise(i * 0.3, 11) * H;
    const h = 180 + noise(i, 12) * 520;
    ctx.fillStyle = rgba(10, 22, 30, 0.04);
    ctx.fillRect(x, y, 8 + noise(i, 13) * 16, h);
  }
}

function paintChamber(ctx) {
  soft(ctx, 800, 1040, 560, 72, 28, 26, 0.2);
  soft(ctx, 760, 980, 340, 110, 48, 36, 0.1);
  soft(ctx, 860, 1100, 300, 40, 48, 52, 0.06);
  soft(ctx, 800, 1010, 420, 140, 62, 44, 0.1);
}

function vesselPath(side) {
  const ctx = drawingContext;
  const steps = 90;
  const left = [];
  const right = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const p = presence(t, side);
    const amp = p.r * 0.07;
    const wob = (noise(t * 2.6, 20 + side) - 0.5) * 2 * amp;
    const wob2 = (noise(t * 2.6, 24 + side) - 0.5) * 2 * amp;
    left.push([p.x - p.r + wob, p.y]);
    right.push([p.x + p.r + wob2, p.y]);
  }
  ctx.beginPath();
  ctx.moveTo(left[0][0], left[0][1]);
  for (let i = 1; i < left.length; i++) ctx.lineTo(left[i][0], left[i][1]);
  const lb = left[steps];
  const rb = right[steps];
  ctx.quadraticCurveTo((lb[0] + rb[0]) / 2, lb[1] + 30, rb[0], rb[1]);
  for (let i = steps - 1; i >= 0; i--) ctx.lineTo(right[i][0], right[i][1]);
  const lt = left[0];
  const rt = right[0];
  ctx.quadraticCurveTo((lt[0] + rt[0]) / 2, lt[1] - 28, lt[0], lt[1]);
  ctx.closePath();
}

function paintVessel(ctx, side) {
  vesselPath(side);
  ctx.save();
  ctx.shadowColor = side === 0 ? "rgba(130, 42, 40, 0.65)" : "rgba(150, 96, 40, 0.55)";
  ctx.shadowBlur = 42;
  const fillG = ctx.createLinearGradient(0, 560, 0, 1460);
  if (side === 0) {
    fillG.addColorStop(0, "rgba(80, 24, 30, 0)");
    fillG.addColorStop(0.28, "rgba(124, 38, 46, 0.62)");
    fillG.addColorStop(0.55, "rgba(146, 52, 50, 0.70)");
    fillG.addColorStop(0.8, "rgba(96, 32, 34, 0.28)");
    fillG.addColorStop(1, "rgba(40, 14, 14, 0)");
  } else {
    fillG.addColorStop(0, "rgba(70, 40, 18, 0)");
    fillG.addColorStop(0.3, "rgba(138, 78, 36, 0.60)");
    fillG.addColorStop(0.58, "rgba(156, 96, 46, 0.66)");
    fillG.addColorStop(0.82, "rgba(90, 48, 26, 0.26)");
    fillG.addColorStop(1, "rgba(30, 16, 10, 0)");
  }
  ctx.fillStyle = fillG;
  ctx.fill();
  ctx.restore();

  ctx.save();
  vesselPath(side);
  ctx.clip();
  const layers = side === 0
    ? [[120, 36, 44], [176, 72, 58], [214, 132, 92]]
    : [[150, 86, 42], [196, 124, 68], [176, 72, 68]];
  for (let k = 0; k < layers.length; k++) {
    const col = layers[k];
    for (let i = 0; i < 22; i++) {
      const t = 0.14 + (i / 21) * 0.72;
      const p = presence(t, side);
      const ox = (noise(t * 4.2, 40 + k + side * 5) - 0.5) * p.r * 0.8;
      soft(ctx, p.x + ox, p.y, p.r * (0.42 + k * 0.12), col[0], col[1], col[2], 0.055);
    }
  }
  for (let i = 0; i < 16; i++) {
    const t = 0.3 + (i / 15) * 0.4;
    const p = presence(t, side);
    const inward = side === 0 ? 1 : -1;
    const col = side === 0 ? [232, 176, 120] : [196, 86, 78];
    soft(ctx, p.x + inward * p.r * 0.42, p.y, p.r * 0.38, col[0], col[1], col[2], 0.05);
  }
  ctx.restore();

  for (let i = 0; i <= 28; i++) {
    const t = i / 28;
    const p = presence(t, side);
    const outward = side === 0 ? -1 : 1;
    soft(ctx, p.x, p.y, p.r * 1.55, side === 0 ? 120 : 150, side === 0 ? 48 : 90, side === 0 ? 40 : 48, 0.035);
    soft(ctx, p.x + outward * p.r * 0.92, p.y, 22, side === 0 ? 24 : 20, side === 0 ? 46 : 62, side === 0 ? 58 : 64, 0.055);
  }

  const mid = presence(0.5, side);
  soft(ctx, mid.x, mid.y, mid.r * 0.72, side === 0 ? 190 : 200, side === 0 ? 82 : 118, side === 0 ? 58 : 68, 0.08);

  for (let i = 0; i < 180; i++) {
    const t = 0.08 + noise(i * 0.15, 60 + side) * 0.84;
    const p = presence(t, side);
    const ox = (noise(i * 0.21, 70 + side) - 0.5) * p.r * 1.5;
    const oy = (noise(i * 0.19, 80 + side) - 0.5) * 16;
    const ang = -Math.PI / 2 + (noise(i * 0.27, 90 + side) - 0.5) * 0.9;
    const inward = side === 0 ? 1 : -1;
    const onInner = ox * inward > 0;
    let R;
    let G;
    let B;
    if (side === 0) {
      R = onInner ? 230 : 150;
      G = onInner ? 150 : 60;
      B = onInner ? 110 : 55;
    } else {
      R = onInner ? 200 : 170;
      G = onInner ? 90 : 110;
      B = onInner ? 75 : 60;
    }
    brush(
      ctx,
      p.x + ox,
      p.y + oy,
      14 + noise(i, 100 + side) * 28,
      ang,
      1 + noise(i, 110) * 1.6,
      R,
      G,
      B,
      0.07 + noise(i, 120) * 0.08
    );
  }
}

function paintInterval(ctx) {
  for (let y = 760; y <= 1320; y += 8) {
    const n = noise(y * 0.012, 9);
    const x = 801 + (n - 0.5) * 12;
    soft(ctx, x, y, 30, 22, 24, 40, 0.055);
  }
  for (let y = 780; y <= 1300; y += 7) {
    const n = noise(y * 0.01, 11);
    const x = 801 + Math.sin(y * 0.018) * 5;
    soft(ctx, x - 16, y, 20, 200, 100, 80, 0.04);
    soft(ctx, x + 16, y, 20, 190, 150, 90, 0.04);
    soft(ctx, x, y, 12, 255, 232, 210, 0.055 + n * 0.03);
  }
  for (let y = 690; y <= 1480; y += 5) {
    const n = noise(y * 0.02, 13);
    if (n < 0.22) continue;
    if (Math.abs(y - 1190) < 18 && n < 0.55) continue;
    const x = 801 + (noise(y * 0.03, 14) - 0.5) * 18 + Math.sin(y * 0.04) * 3;
    soft(ctx, x, y, 4 + n * 7, 255, 228, 196, 0.045 + n * 0.04);
  }
  soft(ctx, 801, 1010, 78, 255, 214, 180, 0.1);
  soft(ctx, 801, 1010, 28, 255, 242, 228, 0.2);
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  soft(ctx, 801, 1010, 10, 255, 248, 240, 0.35);
  ctx.restore();
}

function paintArch(ctx) {
  for (let i = 0; i <= 40; i++) {
    const t = i / 40;
    const x = 620 + (980 - 620) * t;
    const y = 640 - Math.sin(Math.PI * t) * 168 + (noise(t * 3, 30) - 0.5) * 14;
    if (noise(t * 5, 31) < 0.15) continue;
    soft(ctx, x, y, 16 + Math.sin(Math.PI * t) * 14, 236, 196, 150, 0.015 + Math.sin(Math.PI * t) * 0.04);
  }
}

function paintSeeds(ctx) {
  const L = presence(0.46, 0);
