function paintPool(ctx) {
  const shore = ctx.createLinearGradient(0, 1420, 0, 1540);
  shore.addColorStop(0, "rgba(8, 4, 6, 0)");
  shore.addColorStop(0.5, "rgba(8, 4, 6, 0.35)");
  shore.addColorStop(1, "rgba(8, 4, 6, 0)");
  ctx.fillStyle = shore;
  ctx.fillRect(0, 1420, W, 120);

  soft(ctx, 800, 1688, 640, 62, 28, 18, 0.28);
  soft(ctx, 660, 1660, 240, 130, 64, 40, 0.1);
  soft(ctx, 960, 1695, 220, 110, 70, 46, 0.09);
  soft(ctx, 801, 1704, 200, 186, 112, 68, 0.12);
  soft(ctx, 801, 1708, 24, 220, 180, 140, 0.12);

  function drip(x0, y0, len, R, G, B) {
    let x = x0;
    for (let s = 0; s < len; s += 4) {
      const y = y0 + s;
      x += (noise(x0 * 0.02, s * 0.08) - 0.5) * 2.4;
      const k = 1 - s / len;
      if (noise(s * 0.05, x0) < 0.18) continue;
      soft(ctx, x, y, 2.2 + k * 5, R, G, B, 0.07 * k);
    }
  }
  const lf = presence(0.9, 0);
  const rf = presence(0.9, 1);
  drip(lf.x + 6, lf.y + 10, 200, 180, 90, 60);
  drip(rf.x - 4, rf.y + 8, 220, 170, 100, 55);
  drip(801, 1340, 280, 220, 160, 110);

  for (let i = 0; i < 140; i++) {
    const x = 380 + noise(i * 0.23, 50) * 840;
    const y = 1560 + noise(i * 0.23, 51) * 250;
    const ang = (noise(i * 0.4, 52) - 0.5) * 0.5;
    brush(ctx, x, y, 30 + noise(i, 53) * 110, ang, 1 + noise(i, 54) * 2.2, 190, 120, 75, 0.045 + noise(i, 55) * 0.05);
  }
}

function paintMotes(ctx) {
  for (let i = 0; i < 64; i++) {
    const x = 180 + noise(i * 0.31, 60) * 1240;
    const y = 120 + noise(i * 0.31, 61) * 1700;
    ctx.fillStyle = rgba(255, 214, 170, 0.12 + noise(i, 63) * 0.4);
    ctx.beginPath();
    ctx.arc(x, y, 0.8 + noise(i, 62) * 2.2, 0, Math.PI * 2);
