function paintVignette(ctx) {
  const g = ctx.createRadialGradient(800, 1020, 260, 800, 1080, 1280);
  g.addColorStop(0, "rgba(0,0,0,0)");
  g.addColorStop(0.5, "rgba(0,0,0,0)");
  g.addColorStop(1, "rgba(0,0,0,0.60)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  const varnish = ctx.createRadialGradient(780, 1000, 80, 800, 1040, 880);
  varnish.addColorStop(0, "rgba(140, 72, 28, 0.06)");
  varnish.addColorStop(1, "rgba(40, 16, 8, 0)");
  ctx.fillStyle = varnish;
  ctx.fillRect(0, 0, W, H);
}

function clamp(v) {
  return v < 0 ? 0 : v > 255 ? 255 : v;
}

function grain() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 4;
      const n = random() - 0.5;
      const weave = (x + y) % 5 === 0 ? -2.5 : 1.2;
      const v = n * 11 + weave;
      const dx = (x - 800) / 800;
      const dy = (y - 1040) / 1040;
      const d = Math.sqrt(dx * dx + dy * dy);
      const warm = (1 - Math.min(d, 1)) * 5;
      pixels[i] = clamp(pixels[i] * 0.95 + 7 + v + warm) | 0;
      pixels[i + 1] = clamp(pixels[i + 1] * 0.95 + 4 + v * 0.92 + warm * 0.55) | 0;
      pixels[i + 2] = clamp(pixels[i + 2] * 0.95 + 3 + v * 0.82) | 0;
    }
  }
  updatePixels();
}

