function dryGround() {
  strokeCap(SQUARE);
  for (let i = 0; i < 3800; i++) {
    let y = random(height);
    let x = random(-30, width);
    let warmth = y / height;
    let n = noise(x * 0.0015, y * 0.0022);
    stroke(
      20 + warmth * 34 + n * 14,
      12 + warmth * 14 + n * 6,
      24 + (1 - warmth) * 16,
      random(5, 12)
    );
    strokeWeight(random(0.4, 1.7));
    line(x, y, x + random(28, 170), y + (noise(y * 0.012, 3) - 0.5) * 5);
  }
}

function underGestures() {
  let tones = [
    color(62, 28, 34),
    color(34, 20, 44),
    color(74, 36, 30),
    color(20, 28, 44),
    color(48, 22, 36)
  ];
  for (let i = 0; i < 13; i++) {
    wipe(
      random(180, 1420),
      random(460, 1620),
      random(36, 100),
      random(200, 580),
      random(-0.45, 0.45),
      tones[floor(random(tones.length))],
      random(4, 9)
    );
  }
}

function wipe(x, y, w, h, ang, c, a) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(red(c), green(c), blue(c), a);
  rect(-w / 2, -h / 2, w, h, min(w, h) * 0.45);
  pop();
}

function aura(x, y, dw, dh, col, layers, aMax) {
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let j = 8 + (1 - t) * 6;
    fill(red(col), green(col), blue(col), aMax * pow(1.05 - t, 2));
    ellipse(
      x + random(-j, j),
      y + random(-j, j),
      dw * t * random(0.97, 1.03),
      dh * t * random(0.97, 1.03)
    );
  }
}

function presence(p) {
  strokeCap(ROUND);
  for (let i = 0; i < p.n; i++) {
    let t = (random() + random() + random()) / 3;
    let env;
    if (p.shape === "opening") {
      env = 0.6 + 0.4 * sin(t * PI);
    } else {
      env = lerp(0.52, 0.98, pow(t, 0.8));
      env *= 0.88 + 0.12 * sin(t * PI);
    }
    let u = random() + random() - 1;
    let y = p.cy + (t - 0.5) * p.h;
    let x = p.cx + u * p.w * 0.5 * env + p.lean * (0.5 - t) * p.h * 0.16;
    x += (noise(p.ox, t * 2.4, i * 0.002) - 0.5) * p.scatter;
    y += (noise(t * 1.8, p.ox) - 0.5) * p.scatter * 0.4;

    if (p.porous && noise(x * 0.0045, y * 0.0045) < 0.3) continue;

    let inner = u * p.inward;
    let n = noise(i * 0.02, t * 3.0, p.ox);
    let light = constrain(0.12 + env * 0.38 + max(0, inner) * 0.5 + (n - 0.5) * 0.3, 0, 1);
    let col = pick(p.cols, light);
    let sw = lerp(p.w0, p.w1, random()) * lerp(1.2, 0.55, light);
    let a = lerp(p.a0, p.a1, light) * random(0.7, 1);
    let rr = red(col);
    let gg = green(col);
    let bb = blue(col);

    if (random() < p.dab) {
      noStroke();
      fill(rr, gg, bb, a);
      ellipse(x, y, sw * random(2.1, 5.0), sw * random(1.3, 3.4));
    } else {
      let len = lerp(p.len0, p.len1, random()) * (0.4 + env);
      let ang = -HALF_PI + p.lean * 0.5 + random(-p.jitter, p.jitter);
      stroke(rr, gg, bb, a);
      strokeWeight(max(0.4, sw * 0.42));
      line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    }

    if (p.inward !== 0 && inner < -0.5 && random() < 0.28) {
      stroke(14, 7, 12, random(8, 20));
      strokeWeight(random(0.5, 1.5));
      let ang2 = -HALF_PI + p.lean * 0.35 + random(-0.25, 0.25);
      let d = random(8, 20);
      line(x, y, x + cos(ang2) * d, y + sin(ang2) * d);
    }
  }
}

function pick(cols, t) {
  t = constrain(t, 0, 1);
  let x = t * (cols.length - 1);
  let i = floor(x);
  if (i >= cols.length - 1) return cols[cols.length - 1];
  return lerpColor(cols[i], cols[i + 1], x - i);
}

