function spinePoint(pts, t, seed) {
  let n = pts.length - 1;
  let tt = constrain(t, 0, 1);
  let ft = tt * n;
  let i = min(floor(ft), n - 1);
  let u = ft - i;
  u = u * u * (3 - 2 * u);
  let x = lerp(pts[i].x, pts[i + 1].x, u);
  let y = lerp(pts[i].y, pts[i + 1].y, u);
  let meet = exp(-pow((tt - 0.52) * 6.2, 2));
  let amp = lerp(118, 28, meet);
  let nx = (noise(seed, tt * 2.6) - 0.5) * 2 * amp;
  let ny = (noise(seed + 4.4, tt * 2.6) - 0.5) * 2 * amp * 0.62;
  nx += (noise(seed + 10, tt * 8.5) - 0.5) * 26;
  ny += (noise(seed + 12, tt * 8.5) - 0.5) * 18;
  return { x: x + nx, y: y + ny };
}

function spineTangent(pts, t, seed) {
  let a = spinePoint(pts, max(0, t - 0.01), seed);
  let b = spinePoint(pts, min(1, t + 0.01), seed);
  return atan2(b.y - a.y, b.x - a.x);
}

function leftColor(t, n) {
  let r, g, b;
  if (t < 0.4) {
    let u = t / 0.4;
    r = lerp(116, 198, u);
    g = lerp(30, 66, u);
    b = lerp(52, 74, u);
  } else if (t < 0.68) {
    let u = (t - 0.4) / 0.28;
    r = lerp(198, 226, u);
    g = lerp(66, 122, u);
    b = lerp(74, 98, u);
  } else {
    let u = (t - 0.68) / 0.32;
    r = lerp(226, 156, u);
    g = lerp(122, 88, u);
    b = lerp(98, 62, u);
  }
  r += (n - 0.5) * 26;
  g += (n - 0.5) * 16;
  b += (n - 0.5) * 12;
  return {
    r: constrain(r, 0, 255),
    g: constrain(g, 0, 255),
    b: constrain(b, 0, 255)
  };
}

function rightColor(t, n) {
  let r, g, b;
  if (t < 0.4) {
    let u = t / 0.4;
    r = lerp(138, 216, u);
    g = lerp(76, 152, u);
    b = lerp(30, 56, u);
  } else if (t < 0.68) {
    let u = (t - 0.4) / 0.28;
    r = lerp(216, 234, u);
    g = lerp(152, 150, u);
    b = lerp(56, 102, u);
  } else {
    let u = (t - 0.68) / 0.32;
    r = lerp(234, 150, u);
    g = lerp(150, 90, u);
    b = lerp(102, 54, u);
  }
  r += (n - 0.5) * 22;
  g += (n - 0.5) * 18;
  b += (n - 0.5) * 14;
  return {
    r: constrain(r, 0, 255),
    g: constrain(g, 0, 255),
    b: constrain(b, 0, 255)
  };
}

function paintGround() {
  for (let y = 0; y < height; y += 3) {
    let ty = y / height;
    let r, g, b;
    if (ty < 0.4) {
      let u = ty / 0.4;
      u = u * u * (3 - 2 * u);
      r = lerp(12, 44, u);
      g = lerp(6, 16, u);
      b = lerp(26, 52, u);
    } else if (ty < 0.7) {
      let u = (ty - 0.4) / 0.3;
      u = u * u * (3 - 2 * u);
      r = lerp(44, 62, u);
      g = lerp(16, 24, u);
      b = lerp(52, 50, u);
    } else {
      let u = (ty - 0.7) / 0.3;
      u = u * u * (3 - 2 * u);
      r = lerp(62, 22, u);
      g = lerp(24, 9, u);
      b = lerp(50, 16, u);
    }
    for (let x = 0; x < width; x += 32) {
      let n = noise(x * 0.0016, y * 0.0022);
      let cx = 1 - abs(x - width * 0.48) / (width * 0.55);
      let warm = constrain(cx, 0, 1) * 12;
      stroke(r + n * 14 + warm, g + n * 6 + warm * 0.25, b + n * 10, 255);
      strokeWeight(4);
      line(x, y, x + 34, y);
    }
  }
  noStroke();
}

