function paintCurrent(pts, seed, colFn, count, sizeMul, alphaBase) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let t = i / (count - 1);
    t = constrain(t + (random() - 0.5) * 0.02, 0, 1);
    let p = spinePoint(pts, t, seed);
    let ang = spineTangent(pts, t, seed);
    let env = 0.18 + 0.82 * sin(t * PI);
    let meet = exp(-pow((t - 0.52) * 4.6, 2));
    let spread = (64 + noise(t * 2.2, seed + 2) * 130) * env * (1 + meet * 0.9);
    let g = (random() + random() + random() - 1.5) / 1.5;
    let across = g * spread * 0.92;
    let along = (random() - 0.5) * 46;
    let x = p.x + cos(ang + HALF_PI) * across + cos(ang) * along;
    let y = p.y + sin(ang + HALF_PI) * across + sin(ang) * along;
    let n = noise(i * 0.02, seed + 1.4);
    let c = colFn(t, n);
    let w = (16 + n * 34) * sizeMul * (0.55 + env);
    let h = w * (0.38 + random() * 0.55);
    let a = alphaBase * (0.4 + n * 0.75) * (0.45 + env * 0.55);
    if (abs(g) > 0.72) {
      c = {
        r: c.r * 0.78,
        g: c.g * 0.7,
        b: c.b * 0.82
      };
      a *= 0.8;
    }
    if (i % 19 === 0) {
      w *= 2.3;
      h *= 1.8;
      a *= 0.42;
    }
    push();
    translate(x, y);
    rotate(ang + (random() - 0.5) * 0.85);
    fill(c.r, c.g, c.b, a);
    ellipse(0, 0, w, h);
    pop();
  }
}

function paintOuterVeins() {
