function paintInnerEdge(pts, seed, otherPts, otherSeed, colFn, count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let t = random(0.08, 0.92);
    if (random() < 0.55) t = random(0.3, 0.7);
    let p = spinePoint(pts, t, seed);
    let o = spinePoint(otherPts, t, otherSeed);
    let angTo = atan2(o.y - p.y, o.x - p.x);
    let flow = spineTangent(pts, t, seed);
    let env = 0.3 + 0.7 * sin(t * PI);
    let d = 16 + random() * (36 + 80 * env);
    let x = p.x + cos(angTo) * d + (random() - 0.5) * 24;
    let y = p.y + sin(angTo) * d + (random() - 0.5) * 24;
    let c = colFn(t, random());
    push();
    translate(x, y);
    rotate(flow + (random() - 0.5) * 0.4);
    fill(
      constrain(c.r + 46, 0, 255),
      constrain(c.g + 30, 0, 255),
      constrain(c.b + 18, 0, 255),
      18 + random() * 26
    );
    ellipse(0, 0, 8 + random() * 20, 4 + random() * 9);
    pop();
  }
}

function paintStrokes(pts, seed, colFn, n) {
  noFill();
  for (let i = 0; i < n; i++) {
    let t = random(0.05, 0.94);
    if (random() < 0.4) t = random(0.36, 0.66);
    let p = spinePoint(pts, t, seed);
    let ang = spineTangent(pts, t, seed) + (random() - 0.5) * 0.45;
    let env = 0.3 + 0.7 * sin(t * PI);
    let across = (random() - 0.5) * 210 * env;
    let x = p.x + cos(ang + HALF_PI) * across;
    let y = p.y + sin(ang + HALF_PI) * across;
    let len = 24 + random() * 120;
    let c = colFn(t, random());
    stroke(c.r, c.g, c.b, 14 + random() * 30);
    strokeWeight(0.8 + random() * 3.2);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    let mx = (x + x2) / 2 + cos(ang + HALF_PI) * (random() - 0.5) * 22;
    let my = (y + y2) / 2 + sin(ang + HALF_PI) * (random() - 0.5) * 22;
    beginShape();
    curveVertex(x, y);
    curveVertex(x, y);
    curveVertex(mx, my);
    curveVertex(x2, y2);
    curveVertex(x2, y2);
    endShape();
  }
  noStroke();
}

function paintApproaches() {
  noFill();
  for (let i = 0; i < 16; i++) {
    let t = random(0.16, 0.4);
    let a = spinePoint(leftPts, t, 1.7);
    let b = spinePoint(rightPts, t, 8.2);
    let gap = 0.16 + random() * 0.18;
    let lift = -16 - random() * 48;
    stroke(224, 164, 136, 12 + random() * 16);
    strokeWeight(0.6 + random() * 1.3);
    let x1 = lerp(a.x, b.x, 0.04);
    let y1 = lerp(a.y, b.y, 0.04);
    let x2 = lerp(a.x, b.x, 0.5 - gap);
    let y2 = lerp(a.y, b.y, 0.5 - gap);
    beginShape();
    curveVertex(x1, y1);
    curveVertex(x1, y1);
    curveVertex(lerp(x1, x2, 0.5), lerp(y1, y2, 0.5) + lift);
    curveVertex(x2, y2);
    curveVertex(x2, y2);
    endShape();
    let x3 = lerp(a.x, b.x, 0.5 + gap);
    let y3 = lerp(a.y, b.y, 0.5 + gap);
    let x4 = lerp(a.x, b.x, 0.96);
    let y4 = lerp(a.y, b.y, 0.96);
    beginShape();
    curveVertex(x3, y3);
    curveVertex(x3, y3);
    curveVertex(lerp(x3, x4, 0.5), lerp(y3, y4, 0.5) + lift * 0.55);
    curveVertex(x4, y4);
    curveVertex(x4, y4);
    endShape();
  }
  noStroke();
}

function paintMeeting() {
  noStroke();
  let clusters = [
    { x: 742, y: 1148, s: 250 },
    { x: 858, y: 1236, s: 210 },
    { x: 796, y: 1194, s: 170 },
    { x: 708, y: 1272, s: 130 },
    { x: 900, y: 1128, s: 120 }
  ];
  for (let k = 0; k < clusters.length; k++) {
    let cl = clusters[k];
    for (let i = 0; i < 520; i++) {
      let ang = random(TWO_PI);
      let rad = pow(random(), 0.55) * cl.s;
      let x = cl.x + cos(ang) * rad * 1.2;
      let y = cl.y + sin(ang) * rad * 0.78;
      let near = constrain(1 - rad / cl.s, 0, 1);
      let roll = random();
      let r, g, b;
      if (roll < 0.28) {
        r = 234;
        g = 188;
        b = 206;
      } else if (roll < 0.52) {
        r = 250;
        g = 222;
        b = 190;
      } else {
        r = 240;
        g = 172;
        b = 128;
      }
      r = constrain(lerp(r - 18, r + 8, near) + random(-12, 12), 0, 255);
      g = constrain(lerp(g - 22, g + 6, near) + random(-10, 10), 0, 255);
      b = constrain(lerp(b - 16, b + 10, near) + random(-10, 10), 0, 255);
      let w = lerp(36, 8, near) + random(8);
      fill(r, g, b, lerp(6, 18, near));
      ellipse(x, y, w, w * random(0.5, 0.9));
    }
  }
  for (let i = 0; i < 80; i++) {
    fill(236, 186, 168, 5);
    ellipse(790 + random(-160, 180), 1188 + random(-70, 80), random(80, 220), random(18, 36));
  }
}

function paintHalo() {
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 7; i++) {
    fill(110, 62, 36, 10);
    ellipse(792 + random(-18, 18), 1188 + random(-14, 14), random(280, 640), random(200, 460));
  }
  for (let i = 0; i < 4; i++) {
    fill(150, 96, 64, 12);
    ellipse(786 + random(-8, 8), 1176 + random(-8, 8), random(80, 200), random(60, 140));
  }
  blendMode(BLEND);
}

function paintInnerFold() {
  noStroke();
  let ang = 0.55;
  for (let i = 0; i < 340; i++) {
    let along = (random() - 0.5) * 200;
    let across = (random() + random() - 1) * 42;
    let x = 812 + cos(ang) * along + cos(ang + HALF_PI) * across;
    let y = 1232 + sin(ang) * along + sin(ang + HALF_PI) * across;
    fill(68, 30, 76, 8);
    ellipse(x, y, 28 + random() * 54, 14 + random() * 22);
  }
}

function paintDescending() {
  for (let i = 0; i < 34; i++) {
    let rose = random() < 0.5;
    let x = rose ? 640 + random() * 160 : 820 + random() * 170;
    let y = 1300 + random() * 70;
    if (rose) stroke(196, 108, 96, 10 + random() * 14);
    else stroke(206, 156, 86, 10 + random() * 14);
    strokeWeight(0.5 + random() * 1.5);
    noFill();
    for (let k = 0; k < 7; k++) {
      if (random() < 0.28) {
        y += 28 + random() * 24;
        continue;
      }
      let ny = y + 22 + random() * 48;
      let nx = x + (noise(i * 0.4, k * 0.3) - 0.5) * 28;
      line(x, y, nx, ny);
      x = nx;
      y = ny;
    }
  }
  noStroke();
}

function paintSown() {
  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(140, 1480);
    let y = random(1520, 1960);
    let n = noise(x * 0.005, y * 0.005);
    if (n < 0.46) continue;
    let edge = constrain(min(x - 100, 1500 - x, y - 1500, 1970 - y) / 180, 0, 1);
    let rose = noise(x * 0.01, y * 0.01) > 0.5;
    if (rose) fill(176, 86, 72, (8 + n * 16) * edge);
    else fill(168, 118, 62, (8 + n * 16) * edge);
    ellipse(x, y, 3 + n * 12, 2 + n * 7);
  }
}

function paintEmbers() {
  noStroke();
  for (let i = 0; i < 100; i++) {
    let x = 660 + (noise(i * 0.17, 50) - 0.5) * 420;
    let y = 1100 + (noise(i * 0.17, 51) - 0.5) * 300;
    fill(255, 236, 216, random(28, 78));
    ellipse(x, y, random(1.4, 4.6), random(1.4, 4.6));
  }
  for (let i = 0; i < 36; i++) {
    let t = random(0.14, 0.86);
    let p = random() < 0.5 ? spinePoint(leftPts, t, 1.7) : spinePoint(rightPts, t, 8.2);
    fill(255, 226, 198, random(22, 60));
    ellipse(p.x + random(-24, 24), p.y + random(-18, 18), random(1.3, 3.2), random(1.3, 3.2));
  }
  for (let i = 0; i < 40; i++) {
    let x = random(180, 1420);
    let y = random(60, 620);
    if (noise(x * 0.008, y * 0.008) < 0.5) continue;
    fill(255, 214, 186, random(16, 42));
    ellipse(x, y, random(1.1, 2.8), random(1.1, 2.8));
  }
}

function paintVignette() {
  noStroke();
  for (let i = 0; i < 48; i++) {
    let a = map(i, 0, 48, 26, 0);
    fill(8, 3, 14, a);
    rect(0, i * 5, width, 7);
    rect(0, height - (i + 1) * 7, width, 8);
    rect(i * 4, 0, 6, height);
    rect(width - (i + 1) * 4, 0, 6, height);
  }
}

function paintGrain() {
  noStroke();
  for (let i = 0; i < 7000; i++) {
    let x = random(width);
    let y = random(height);
    let warm = random();
    if (warm < 0.5) fill(255, 230, 210, random(4, 10));
    else fill(18, 8, 16, random(4, 11));
    rect(x, y, random(1, 2.1), random(1, 2.1));
  }
}

// p5.js 1.11 — still painting, 1600×2000
let hearths;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  noiseDetail(3, 0.5);
  initHearths();
  paintGround();
  paintFloor();
  paintVeils();
  paintHearths();
  paintFlows();
  paintGestures();
  reclaimNight();
  paintAlizarin();
  paintBreath();
  paintThreads();
  paintRims();
  paintCores();
  paintSky();
  paintEmbers();
  paintTooth();
  paintVignette();
}

function initHearths() {
  hearths = [
    {x: 1100, y: 1320, s: 310, cr: 255, cg: 186, cb: 128, er: 124, eg: 44, eb: 28, a: 1.0},
    {x: 520, y: 1060, s: 270, cr: 240, cg: 164, cb: 158, er: 108, eg: 36, eb: 66, a: 1.0},
    {x: 880, y: 640, s: 180, cr: 255, cg: 226, cb: 196, er: 184, eg: 116, eb: 92, a: 0.9},
    {x: 300, y: 400, s: 110, cr: 210, cg: 196, cb: 214, er: 92, eg: 76, eb: 118, a: 0.5},
    {x: 420, y: 1630, s: 200, cr: 146, cg: 44, cb: 38, er: 40, eg: 12, eb: 16, a: 0.72}
  ];
}

function fieldColor(x, y) {
  let r = 14, g = 7, b = 16, w = 0;
  for (let i = 0; i < hearths.length; i++) {
    let h = hearths[i];
    let d = dist(x, y, h.x, h.y);
    let inf = exp(-(d * d) / (2 * h.s * h.s * 1.2)) * h.a;
    w += inf;
    r += h.cr * inf * 0.6;
    g += h.cg * inf * 0.52;
    b += h.cb * inf * 0.48;
  }
  let corridor = exp(-pow((x - 810) / 190, 2)) * exp(-pow((y - 1160) / 460, 2));
  r += 230 * corridor * 0.26;
  g += 190 * corridor * 0.18;
  b += 150 * corridor * 0.09;
  w += corridor * 0.4;
  return {
    r: constrain(r, 0, 255),
    g: constrain(g, 0, 255),
    b: constrain(b, 0, 255),
    w: w
  };
}

function gauss(sd) {
  return constrain(randomGaussian(0, sd), -2.6 * sd, 2.6 * sd);
}

function dab(x, y, w, h, rot, r, g, b, a) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255), constrain(a, 0, 255));
  ellipse(0, 0, abs(w), abs(h));
  pop();
}

function softWash(x, y, rad, r, g, b, a) {
  noStroke();
  for (let i = 20; i >= 1; i--) {
    fill(r, g, b, a);
    ellipse(x, y, rad * 2 * (i / 20), rad * 2.12 * (i / 20));
  }
}

function flowAngle(x, y) {
  let n = noise(x * 0.00115, y * 0.00115);
  let a = n * TAU * 1.65;
  let tang = atan2(y - 1160, x - 810) + HALF_PI;
  return lerp(a, tang, 0.2) - 0.08;
}

function paintGround() {
  background(8, 4, 10);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let n = noise(0.4, y * 0.0028);
    let band = exp(-pow((t - 0.46) / 0.36, 2));
    let r = 8 + band * 26 + n * 6;
    let g = 4 + band * 9 + n * 3;
    let b = 12 + band * 16 + n * 5;
    stroke(r, g, b);
    strokeWeight(1);
    line(0, y, width, y);
  }
  for (let i = 0; i < 3200; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0035, y * 0.0035);
    stroke(16 + n * 22, 6 + n * 8, 14 + n * 12, random(5, 13));
    strokeWeight(random(0.6, 1.7));
    line(x, y, x + random(14, 64), y + random(-1.4, 1.4));
  }
}

function paintFloor() {
  for (let i = 0; i < 160; i++) {
    let y = random(1520, 1920);
    let x = random(60, 1540);
    stroke(48, 18, 14, random(5, 12));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + random(28, 130), y + random(-2, 2));
  }
}

function paintVeils() {
  softWash(240, 380, 560, 28, 32, 58, 2.1);
  softWash(1320, 280, 620, 70, 32, 28, 1.6);
  softWash(810, 1160, 520, 150, 64, 40, 1.8);
  softWash(1100, 1340, 480, 120, 42, 24, 1.7);
  softWash(520, 1060, 440, 100, 32, 48, 1.7);
  softWash(300, 400, 240, 90, 80, 120, 1.5);
  softWash(800, 1920, 980, 10, 4, 8, 3.2);
  softWash(1080, 1580, 360, 64, 24, 14, 1.4);
}

function paintHearth(h, shadows, bodies) {
  noStroke();
  for (let i = 16; i >= 1; i--) {
    let t = i / 16;
    fill(h.er, h.eg, h.eb, 2.8 * h.a);
    ellipse(h.x, h.y + 8, h.s * 3.1 * t, h.s * 3.3 * t);
  }
  for (let i = 0; i < shadows; i++) {
    let ang = random(TAU);
    let rad = abs(gauss(h.s * 0.5));
    let x = h.x + cos(ang) * rad + h.s * 0.05;
    let y = h.y + sin(ang) * rad + h.s * 0.07;
    let edge = constrain(rad / h.s, 0, 1);
    let rot = noise(x * 0.0014, y * 0.0014) * TAU;
    dab(x, y, random(12, 36), random(4, 13), rot,
        h.er * 0.32, h.eg * 0.28, h.eb * 0.3,
        random(10, 26) * h.a * (1.05 - edge * 0.4));
  }
  for (let i = 0; i < bodies; i++) {
    let ang = random(TAU);
    let rad = abs(gauss(h.s * 0.4));
    let x = h.x + cos(ang) * rad;
    let y = h.y + sin(ang) * rad;
    let edge = constrain(rad / (h.s * 0.95), 0, 1);
    let r = lerp(h.cr, h.er, edge) + random(-10, 10);
    let g = lerp(h.cg, h.eg, edge) + random(-8, 8);
    let b = lerp(h.cb, h.eb, edge) + random(-8, 8);
    let rot = flowAngle(x, y) + random(-0.4, 0.4);
    dab(x, y, random(8, 26), random(3, 10), rot,
        r, g, b, random(12, 30) * h.a * lerp(1, 0.45, edge));
  }
}

function paintHearths() {
  paintHearth(hearths[4], 200, 380);
  paintHearth(hearths[3], 90, 200);
  paintHearth(hearths[2], 200, 460);
  paintHearth(hearths[1], 340, 780);
  paintHearth(hearths[0], 400, 900);
}

function samplePoint() {
  let roll = random();
  if (roll < 0.56) {
    let h = hearths[floor(random(hearths.length))];
    let ang = random(TAU);
    let rad = abs(gauss(h.s * 0.62));
    return {x: h.x + cos(ang) * rad, y: h.y + sin(ang) * rad};
  } else if (roll < 0.8) {
    return {x: 810 + gauss(170), y: 1160 + gauss(360)};
  }
  return {x: random(width), y: random(height)};
}

function paintFlows() {
  noFill();
  for (let i = 0; i < 3400; i++) {
    let p = samplePoint();
    let x = p.x;
    let y = p.y;
    let fc = fieldColor(x, y);
    let len = floor(random(8, 24));
    stroke(fc.r + random(-8, 8), fc.g + random(-6, 6), fc.b + random(-6, 6),
           constrain(5 + fc.w * 9, 3, 20));
    strokeWeight(random(0.5, 2.1));
    beginShape();
    for (let k = 0; k < len; k++) {
      vertex(x, y);
      let a = flowAngle(x, y);
      x += cos(a) * 2.5;
      y += sin(a) * 2.5;
    }
    endShape();
  }
}

function paintGestures() {
  noFill();
  for (let i = 0; i < 110; i++) {
    let x = random(80, 1520);
    let y = random(160, 1860);
    let fc = fieldColor(x, y);
    if (fc.w < 0.1 && random() < 0.72) continue;
    stroke(fc.r, fc.g, fc.b, 3.5 + min(fc.w, 1.3) * 6);
    strokeWeight(random(1.4, 5.5));
    beginShape();
    for (let k = 0; k < 20; k++) {
      vertex(x, y);
      let a = flowAngle(x, y) + random(-0.12, 0.12);
      x += cos(a) * random(5, 9);
      y += sin(a) * random(5, 9);
    }
    endShape();
  }
}

function reclaimNight() {
  for (let i = 0; i < 2200; i++) {
    let x = random(width);
    let y = random(height);
    let fc = fieldColor(x, y);
    if (fc.w > 0.4) continue;
    let rot = noise(x * 0.002, y * 0.002) * TAU;
    dab(x, y, random(12, 40), random(4, 14), rot,
        8 + random(10), 4, 12 + random(8), random(8, 20));
  }
}

function paintAlizarin() {
  for (let s = 0; s < 3; s++) {
    let idx = s === 2 ? 4 : s;
    let h = hearths[idx];
    let n = idx === 4 ? 36 : 54;
    for (let i = 0; i < n; i++) {
      let ang = random(TAU);
      let rad = abs(gauss(h.s * 0.32));
      dab(h.x + cos(ang) * rad, h.y + sin(ang) * rad,
          random(6, 18), random(2.5, 7), random(TAU),
          128, 22, 30, random(7, 16) * h.a);
    }
  }
}

function paintBreath() {
  noStroke();
  for (let i = 20; i >= 1; i--) {
    fill(255, 206, 164, 2.3);
    ellipse(808, 1160, 70 + 200 * (i / 20), 80 + 760 * (i / 20));
  }
  for (let i = 0; i < 640; i++) {
    let y = random(540, 1600);
    let t = constrain((y - 540) / 1060, 0, 1);
    let spread = 26 + sin(t * PI) * 50;
    let x = 806 + sin(t * 2.3) * 20 + gauss(spread * 0.5);
    let fade = sin(t * PI);
    stroke(255, 216, 184, random(4, 12) * fade);
    strokeWeight(random(0.45, 1.5));
    line(x, y, x + random(-2.5, 2.5), y - random(14, 58));
  }
}

function strand(x1, y1, x2, y2, reach, weight, cr, cg, cb, baseA) {
  let steps = 46;
  let limit = floor(steps * reach);
  if (limit < 2) return;
  let px = x1;
  let py = y1;
  for (let i = 1; i <= limit; i++) {
    let u = i / steps;
    let x = lerp(x1, x2, u);
    let y = lerp(y1, y2, u);
    x += (noise(u * 2.8, x1 * 0.013, y1 * 0.01) - 0.5) * 64;
    y += (noise(u * 2.8, x2 * 0.011, 6.5) - 0.5) * 40 + sin(u * PI) * -18;
    let fade = sin((i / limit) * PI);
    stroke(cr, cg, cb, baseA * fade * 0.32);
    strokeWeight(weight * 3.4);
    line(px, py, x, y);
    stroke(cr, cg, cb, baseA * fade);
    strokeWeight(weight * random(0.75, 1.2));
    line(px, py, x, y);
    px = x;
    py = y;
  }
}

function paintThreads() {
  let pairs = [
    [0, 1, 0.94, 228, 170, 132],
    [1, 2, 0.9, 236, 198, 172],
    [2, 3, 0.56, 206, 188, 204],
    [4, 0, 0.86, 168, 86, 58],
    [4, 1, 0.68, 146, 64, 62]
  ];
  for (let p = 0; p < pairs.length; p++) {
    let a = hearths[pairs[p][0]];
    let b = hearths[pairs[p][1]];
    let strands = 4 + floor(random(3));
    for (let s = 0; s < strands; s++) {
      let reach = pairs[p][2] * random(0.78, 1);
      if (p === 2) reach = pairs[p][2] * random(0.42, 0.8);
      strand(
        a.x + gauss(16), a.y + gauss(16),
        b.x + gauss(16), b.y + gauss(16),
        reach, random(0.35, 1.05),
        pairs[p][3] + random(-8, 8),
        pairs[p][4] + random(-8, 8),
        pairs[p][5] + random(-8, 8),
        random(9, 20)
      );
    }
  }
  let far = hearths[3];
  let gold = hearths[2];
  for (let s = 0; s < 3; s++) {
    strand(far.x + gauss(6), far.y + gauss(6), gold.x, gold.y,
           random(0.16, 0.3), 0.55, 198, 188, 208, 13);
  }
}

function paintRims() {
  for (let n = 0; n < 4; n++) {
    let h = hearths[n];
    let count = n === 3 ? 40 : 150;
    let dir = atan2(1180 - h.y, 808 - h.x);
    for (let i = 0; i < count; i++) {
      let ang = dir + random(-1.0, 1.0);
      let rad = h.s * random(0.22, 0.8);
      dab(h.x + cos(ang) * rad, h.y + sin(ang) * rad,
          random(7, 18), random(2.4, 6.5), ang + HALF_PI,
          255, 222, 196, random(7, 18) * h.a);
    }
  }
}

function paintCores() {
  for (let n = 0; n < hearths.length; n++) {
    let h = hearths[n];
    let count = floor(28 * h.a) + 8;
    for (let i = 0; i < count; i++) {
      let x = h.x + gauss(h.s * 0.12) - h.s * 0.03;
      let y = h.y + gauss(h.s * 0.1) - h.s * 0.04;
      dab(x, y, random(3, 9), random(1.6, 4), random(TAU),
          255, 242, 228, random(28, 64) * h.a);
    }
  }
  for (let i = 0; i < 70; i++) {
    dab(808 + gauss(34), 1170 + gauss(62),
        random(4, 13), random(2, 5.5), random(TAU),
        255, 234, 210, random(16, 40));
  }
  for (let i = 0; i < 14; i++) {
    dab(800 + gauss(12), 1148 + gauss(18),
        random(2, 4.5), random(1.4, 2.8), random(TAU),
        255, 250, 244, random(46, 86));
  }
}

function paintSky() {
  noStroke();
  for (let i = 0; i < 64; i++) {
    fill(186, 198, 214, random(6, 24));
    ellipse(random(width), random(30, 500), random(1, 2.3), random(1, 2.3));
  }
}

function paintEmbers() {
  blendMode(ADD);
  for (let i = 0; i < 170; i++) {
    let x, y;
    if (random() < 0.62) {
      x = 812 + gauss(150);
      y = 1140 + gauss(260);
    } else {
      let h = hearths[floor(random(3))];
      x = h.x + gauss(h.s * 0.32);
      y = h.y + gauss(h.s * 0.32);
    }
    let rad = random(1.1, 3.4);
    noStroke();
    fill(255, 190, 140, random(4, 12));
    ellipse(x, y, rad * 6.5, rad * 6.5);
    fill(255, 236, 220, random(24, 62));
    ellipse(x, y, rad, rad * random(0.7, 1.15));
  }
  blendMode(BLEND);
}

function paintTooth() {
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() > 0.5) stroke(255, 226, 208, random(2, 6));
    else stroke(12, 4, 8, random(3, 9));
    strokeWeight(random(0.3, 1.05));
    let a = noise(x * 0.007, y * 0.007) * TAU;
    let len = random(3, 15);
    line(x, y, x + cos(a) * len, y + sin(a) * len * 0.55);
  }
}

function paintVignette() {
  noFill();
  for (let i = 0; i < 280; i++) {
    let a = pow(1 - i / 280, 1.7) * 34;
    stroke(5, 2, 8, a);
    strokeWeight(4);
    line(0, i, width, i);
    line(0, height - 1 - i, width, height - 1 - i);
  }
  for (let i = 0; i < 210; i++) {
    let a = pow(1 - i / 210, 1.55) * 30;
    stroke(5, 2, 8, a);
    strokeWeight(4);
    line(i, 0, i, height);
    line(width - 1 - i, 0, width - 1 - i, height);
  }
  noStroke();
  for (let i = 8; i >= 1; i--) {
    fill(4, 1, 6, 5);
    ellipse(0, 0, 700 * (i / 8), 700 * (i / 8));
    ellipse(width, 0, 640 * (i / 8), 640 * (i / 8));
    ellipse(0, height, 820 * (i / 8), 820 * (i / 8));
    ellipse(width, height, 860 * (i / 8), 860 * (i / 8));
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  noiseDetail(4, 0.5);

  paintBackground();

  let warmColors = [color('#ffd9b0'), color('#ffb083'), color('#f76e72'), color('#b8324a')];
  let coolColors = [color('#d9ceff'), color('#a8b7ff'), color('#6d6bc0'), color('#3a2e80')];

  let warmPath = buildPath(400, 1900, 1200, 300, 0.6);
  let coolPath = buildPath(1200, 1900, 400, 300, 4.0);

  drawPathCloud(warmPath, warmColors, 500, 150, 45, BLEND);
  drawPathCore(warmPath, warmColors, 350, 70, 75);
  drawPathLine(warmPath, warmColors, 2, 55);

  drawPathCloud(coolPath, coolColors, 500, 150, 45, BLEND);
  drawPathCore(coolPath, coolColors, 350, 70, 75);
  drawPathLine(coolPath, coolColors, 2, 55);

  drawCentralGlow();

  let warmSparkColors = [color('#ffd9b0'), color('#ff8a7a'), color('#ff4f5e')];
  let coolSparkColors = [color('#d9ceff'), color('#9ea8ff'), color('#5f6bb0')];

  drawSparks(warmPath, warmSparkColors, 400, 125, [0.5, 3]);
  drawSparks(coolPath, coolSparkColors, 400, 125, [0.5, 3]);
  drawCenterSparks();
}

function paintBackground() {
  let bgGrad = drawingContext.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, '#0f060d');
  bgGrad.addColorStop(0.45, '#1d0c15');
  bgGrad.addColorStop(1, '#080510');
  drawingContext.fillStyle = bgGrad;
  drawingContext.fillRect(0, 0, width, height);

  let rg = drawingContext.createRadialGradient(width / 2, height * 0.53, 0, width / 2, height * 0.53, 1200);
  rg.addColorStop(0, '#471628');
  rg.addColorStop(0.35, '#2b101d');
  rg.addColorStop(1, '#0d060e');
  drawingContext.globalAlpha = 0.45;
  drawingContext.fillStyle = rg;
  drawingContext.fillRect(0, 0, width, height);
  drawingContext.globalAlpha = 1;

  noStroke();
  for (let i = 0; i < 2200; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(10, 32);
    fill(255, 220, 200, a);
    let s = random(0.4, 2.0);
    ellipse(x, y, s, s);
  }
}

function buildPath(x1, y1, x2, y2, offset) {
  let pts = [];
  let steps = 700;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let baseX = lerp(x1, x2, t);
    let baseY = lerp(y1, y2, t);
    let nx = (noise(t * 2.2 + offset) - 0.5) * 160;
    let ny = (noise(t * 1.9 + offset * 2.7) - 0.5) * 160;
    let sx = sin(t * TWO_PI * 1.2 + offset) * 70;
    let cy = cos(t * TWO_PI * 0.8 + offset * 1.1) * 80;
    pts.push({ x: baseX + nx + sx, y: baseY + ny + cy, t: t });
  }
  return pts;
}

function randomPoint(points) {
  let idx = Math.floor(random(0, points.length)) % points.length;
  return points[idx];
}

function colorFromPalette(palette, t) {
  let idx = t * (palette.length - 1);
  let i = Math.min(Math.floor(idx), palette.length - 2);
  let j = i + 1;
  let amt = idx - i;
  return lerpColor(palette[i], palette[j], amt);
}

function drawPathCloud(points, palette, count, maxR, alphaBase, mode) {
  push();
  blendMode(mode);
  noStroke();
  for (let i = 0; i < count; i++) {
    let p = randomPoint(points);
    let t = p.t;
    let ox = random(-maxR, maxR) * 0.45;
    let oy = random(-maxR, maxR) * 0.55;
    let r = random(maxR * 0.35, maxR);
    let col = colorFromPalette(palette, t);
    let alpha = alphaBase * random(0.10, 0.40);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(p.x + ox, p.y + oy, r, r);
  }
  pop();
}

function drawPathCore(points, palette, count, maxR, alphaBase) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < count; i++) {
    let p = randomPoint(points);
    let t = p.t;
    let ox = random(-20, 20);
    let oy = random(-20, 20);
    let r = random(maxR * 0.2, maxR * 0.55);
    let col = colorFromPalette(palette, t);
    let alpha = alphaBase * random(0.18, 0.55);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(p.x + ox, p.y + oy, r, r);
  }
  pop();
}

function drawPathLine(points, palette, weight, alpha) {
  push();
  noFill();
  for (let i = 0; i < points.length - 1; i++) {
    let col = colorFromPalette(palette, points[i].t);
    stroke(red(col), green(col), blue(col), alpha);
    strokeWeight(weight);
    line(points[i].x, points[i].y, points[i + 1].x, points[i + 1].y);
  }
  pop();
}

function drawCentralGlow() {
  push();
  blendMode(ADD);
  softGlow(width / 2, height * 0.53, 700, color(150, 110, 255), 5);
  softGlow(width / 2, height * 0.53, 500, color(255, 160, 120), 7);
  softGlow(width / 2, height * 0.53, 300, color(255, 220, 190), 11);
  softGlow(width / 2, height * 0.53, 130, color(255, 255, 245), 15);
  pop();
}

function softGlow(x, y, radius, c, maxAlpha) {
  noStroke();
  let r0 = red(c);
  let g0 = green(c);
  let b0 = blue(c);
  let step = max(6, radius / 80);
  for (let r = radius; r > 0; r -= step) {
    let amt = r / radius;
    let alpha = maxAlpha * (1 - amt) * 0.7;
    fill(r0, g0, b0, alpha);
    ellipse(x, y, r * 2, r * 2);
  }
}

function drawSparks(points, palette, count, maxDist, sizeRange) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < count; i++) {
    let p = randomPoint(points);
    let t = p.t;
    let angle = random(TWO_PI);
    let dist = random(0, maxDist);
    let x = p.x + cos(angle) * dist;
    let y = p.y + sin(angle) * dist * 0.7;
    let r = random(sizeRange[0], sizeRange[1]);
    let col = colorFromPalette(palette, t);
    let alpha = random(30, 120);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(x, y, r, r);
  }
  pop();
}

function drawCenterSparks() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 280; i++) {
    let angle = random(TWO_PI);
    let dist = pow(random(1), 0.6) * 220;
    let x = width / 2 + cos(angle) * dist;
    let y = height * 0.53 + sin(angle) * dist * 0.8;
    let r = random(0.4, 2.4);
    let c = color(255, random(190, 255), random(215, 255), random(30, 110));
    fill(red(c), green(c), blue(c), alpha(c));
    ellipse(x, y, r, r);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(0);

  // Radial gradient background
  let ctx = drawingContext;
  let bgGrad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, max(width, height)*0.7);
  bgGrad.addColorStop(0, color(255, 240, 230));
  bgGrad.addColorStop(0.5, color(200, 100, 120));
  bgGrad.addColorStop(1, color(30, 10, 20));
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Generate two intertwining paths
  let pathA = generatePath(300, 400, 800, 1000, 400, 0, 0, 180, 80);
  let pathB = generatePath(1300, 1600, 800, 1000, 400, 5, PI, 180, 80);

  // Draw streams with additive blending for luminous effect
  blendMode(ADD);
  drawStream(pathA, color(255, 90, 70), color(255, 200, 180), 25);
  drawStream(pathB, color(200, 70, 140), color(255, 180, 220), 25);

  // Central glow where the two streams merge
  let glow = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, 350);
  glow.addColorStop(0, color(255, 255, 240, 180));
  glow.addColorStop(1, color(255, 255, 240, 0));
  ctx.fillStyle = glow;
  ctx.fillRect(width/2-350, height/2-350, 700, 700);

  // Small particles around the streams
  drawParticles();

  blendMode(BLEND);
}

function generatePath(x1, y1, x2, y2, n, noiseOff, twist, spread, noiseAmp) {
  let points = [];
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx*dx + dy*dy);
  let perpX = -dy / len, perpY = dx / len;

  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let baseX = lerp(x1, x2, t);
    let baseY = lerp(y1, y2, t);
    let envelope = sin(t * PI);

    // Deterministic sinusoidal twist around the direct line
    let wobble = sin(t * TAU * 2 + twist) * spread * envelope;

    // Organic noise perturbation
    let perpNoise = (noise(t * 3 + noiseOff, 0) - 0.5) * noiseAmp * envelope;

    let offset = wobble + perpNoise;
    let x = baseX + perpX * offset;
    let y = baseY + perpY * offset;
    points.push({x, y});
  }
  return points;
}

function drawStream(points, colStart, colEnd, alphaBase) {
  for (let i = 0; i < points.length; i++) {
    let t = i / (points.length - 1);
    let p = points[i];

    // Thicker in the middle, thinner at ends
    let radius = 40 * sin(t * PI) + 8;

    // Interpolate color
    let c = lerpColor(colStart, colEnd, t);

    // Multiple overlapping ellipses for soft brush-like texture
    for (let j = 0; j < 3; j++) {
      let offX = (random() - 0.5) * radius * 0.8;
      let offY = (random() - 0.5) * radius * 0.8;
      let r = radius * (0.7 + random() * 0.6);
      fill(red(c), green(c), blue(c), alphaBase * random(0.8, 1.2));
      noStroke();
      ellipse(p.x + offX, p.y + offY, r, r);
    }
  }
}

function drawParticles() {
  // Scatter small glowing specks near the paths
  for (let i = 0; i < 600; i++) {
    let angle = random(TWO_PI);
    let dist = random(50, 700);
    let x = width/2 + cos(angle) * dist;
    let y = height/2 + sin(angle) * dist * 0.8;

    let size = random(2, 7);
    let alpha = random(20, 120);
    fill(255, 240, 220, alpha);
    ellipse(x, y, size, size);
  }

  // Additional particles concentrated near center
  for (let i = 0; i < 200; i++) {
    let x = width/2 + random(-250, 250);
    let y = height/2 + random(-250, 250);
    let size = random(1, 5);
    fill(255, 255, 250, random(40, 160));
    ellipse(x, y, size, size);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 1);
  noLoop();

  drawBackground();
  radialGlow(520, 1020, 700, 'rgba(255, 110, 60, 0.10)');
  radialGlow(1080, 980, 700, 'rgba(70, 140, 255, 0.10)');
  radialGlow(800, 1000, 500, 'rgba(255, 230, 210, 0.08)');

  drawStreamlines();
  drawCentralBloom();
  drawDust();
  drawVignette();
}

function draw() {}

function drawBackground() {
  drawingContext.globalCompositeOperation = 'source-over';
  let ctx = drawingContext;
  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0, '#0e0c16');
  bg.addColorStop(0.35, '#1a1016');
  bg.addColorStop(0.65, '#101018');
  bg.addColorStop(1, '#0a0810');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);
}

function radialGlow(x, y, r, col) {
  drawingContext.globalCompositeOperation = 'source-over';
  let grad = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  grad.addColorStop(0, col);
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = grad;
  drawingContext.beginPath();
  drawingContext.arc(x, y, r, 0, Math.PI * 2);
  drawingContext.fill();
}

function getFieldDirection(x, y, seed) {
  let ax = 520, ay = 1000, bx = 1080, by = 1000;
  let dxA = x - ax, dyA = y - ay;
  let dA = Math.sqrt(dxA * dxA + dyA * dyA) + 0.2;
  let dxB = x - bx, dyB = y - by;
  let dB = Math.sqrt(dxB * dxB + dyB * dyB) + 0.2;

  let ex = dxB / (dB * dB * dB) - dxA / (dA * dA * dA);
  let ey = dyB / (dB * dB * dB) - dyA / (dA * dA * dA);
  let mag = Math.sqrt(ex * ex + ey * ey);
  if (mag > 0.0001) {
    ex = ex / mag;
    ey = ey / mag;
  }

  let cx = x - 800, cy = y - 1000;
  let dc = Math.sqrt(cx * cx + cy * cy) + 1;
  let swirlAmp = 0.32 * Math.sin(dc * 0.0095 + seed * 2.7);
  let px = -cy / dc;
  let py = cx / dc;
  let sx = px * swirlAmp;
  let sy = py * swirlAmp;

  let nx = (noise(x * 0.0018, y * 0.0018, seed * 0.25) - 0.5) * 0.55;
  let ny = (noise(x * 0.0018 + 100, y * 0.0018 + 100, seed * 0.25) - 0.5) * 0.55;

  let outX = ex + sx + nx;
  let outY = ey + sy + ny;
  let outMag = Math.sqrt(outX * outX + outY * outY) || 1;
  return { x: outX / outMag, y: outY / outMag };
}

function positionColor(x) {
  let t = Math.min(1, Math.max(0, (x - 480) / (1120 - 480)));
  let r, g, b;
  if (t < 0.5) {
    let k = t * 2;
    r = 255;
    g = 70 + (225 - 70) * k;
    b = 50 + (205 - 50) * k;
  } else {
    let k = (t - 0.5) * 2;
    r = 255 + (80 - 255) * k;
    g = 225 + (145 - 225) * k;
    b = 205 + (255 - 205) * k;
  }
  return [r, g, b];
}

function drawStreamlines() {
  push();
  blendMode(ADD);
  noFill();
  strokeCap(ROUND);
  let total = 150;
  for (let s = 0; s < total; s++) {
    let fromRight = (s % 2 === 0);
    let angle;
    if (fromRight) {
      angle = Math.PI + random(-0.9, 0.9);
    } else {
      angle = random(-0.9, 0.9);
    }
    let radius = random(10, 130);
    let cx = fromRight ? 1080 : 520;
    let cy = 1000;
    let x = cx + radius * Math.cos(angle);
    let y = cy + radius * Math.sin(angle);
    let reversed = !fromRight;
    let steps = Math.floor(random(220, 420));
    let stepSize = random(2.2, 4.0);
    let alpha = random(0.05, 0.12);
    let prevX = x;
    let prevY = y;
    let seed = s * 0.37;
    strokeWeight(random(1.0, 2.2));

    for (let i = 0; i < steps; i++) {
      let dir = getFieldDirection(x, y, seed + i * 0.02);
      let dx = dir.x;
      let dy = dir.y;
      if (reversed) {
        dx = -dx;
        dy = -dy;
      }
      x += dx * stepSize;
      y += dy * stepSize;

      let t = i / steps;
      let col = positionColor(x);
      stroke(col[0], col[1], col[2], alpha * (1 - t * 0.4));
      line(prevX, prevY, x, y);
      prevX = x;
      prevY = y;

      let targetX = fromRight ? 520 : 1080;
      let targetY = 1000;
      if (Math.hypot(x - targetX, y - targetY) < 22) break;
      if (x < -80 || x > width + 80 || y < -80 || y > height + 80) break;
    }
  }
  pop();
}

function drawCentralBloom() {
  push();
  blendMode(ADD);
  noStroke();
  for (let r = 10; r < 240; r += 18) {
    let alpha = 0.12 * (1 - r / 240);
    fill(255, 235, 215, alpha);
    ellipse(800, 1000, r * 2, r * 2);
  }
  pop();
}

function drawDust() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(0, width);
    let y = random(0, height);
    let d = Math.hypot(x - 800, y - 1000);
    let alpha = Math.max(0, 0.07 * (1 - d / 900)) * random(0.5, 1);
    if (alpha <= 0.002) continue;
    let col = positionColor(x);
    fill(col[0], col[1], col[2], alpha);
    let s = random(0.8, 3.0);
    ellipse(x, y, s, s);
  }
  pop();
}

function drawVignette() {
  drawingContext.globalCompositeOperation = 'source-over';
  let grad = drawingContext.createRadialGradient(800, 1000, 300, 800, 1000, 1500);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(0.7, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,0.38)');
  drawingContext.fillStyle = grad;
  drawingContext.fillRect(0, 0, width, height);
}

let leftPts = [];
let rightPts = [];

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  leftPts = computeStreamPoints(true);
  rightPts = computeStreamPoints(false);
}

function draw() {
  strokeCap(ROUND);
  strokeJoin(ROUND);

  drawBackground();
  drawSweepingVeils();
  drawNebula();

  drawStreams();

  drawTendrils();
  drawCore();
  drawDust();
  drawVignette();
}

function drawBackground() {
  let g = drawingContext.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#0b060f');
  g.addColorStop(0.5, '#21101e');
  g.addColorStop(1, '#06040b');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);
}

function drawSweepingVeils() {
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 8; i++) {
    let t = i / 7;
    let w = lerp(90, 12, t);
    let a = lerp(3, 18, t);
    stroke(130 + i * 4, 18, 52, a);
    strokeWeight(w);
    bezier(
      300 - i * 18, 2000 - i * 10,
      470, 1520,
      530, 1150,
      800, 760 - i * 12
    );
    stroke(175, 105, 25, a);
    bezier(
      1300 + i * 18, 2000 - i * 10,
      1130, 1520,
      1070, 1150,
      800, 760 - i * 12
    );
  }
  blendMode(BLEND);
}

function drawNebula() {
  blendMode(ADD);
  drawSoftGlow(500, 650, 650, 65, 25, 55, 14);
  drawSoftGlow(1120, 1150, 620, 85, 32, 45, 12);
  drawSoftGlow(800, 480, 520, 115, 45, 65, 10);
  drawSoftGlow(650, 1500, 480, 40, 18, 45, 10);
  drawSoftGlow(1080, 1500, 480, 80, 28, 40, 10);
  blendMode(BLEND);
}

function drawSoftGlow(x, y, maxR, r, g, b, maxA) {
  noStroke();
  for (let rad = maxR; rad > 0; rad -= 15) {
    let a = map(rad, maxR, 0, 0, maxA);
    fill(r, g, b, a);
    circle(x, y, rad);
  }
}

function computeStreamPoints(left) {
  let pts = [];
  let cx = 800;
  let cy = 930;
  let N = 850;
  let startAngle = left ? 0.75 * PI : 0.25 * PI;
  let direction = left ? -1 : 1;
  let turns = 4.8;
  let maxRadius = 720;

  for (let i = 0; i < N; i++) {
    let t = i / (N - 1);
    let angle = startAngle + direction * t * turns * TWO_PI;
    let radius = maxRadius * (1 - t * t * 0.75);
    let n = noise(t * 5 + (left ? 0 : 100), left ? 0 : 100);
    let rr = radius * (1 + (n - 0.5) * 0.22);
    let aa = angle + (n - 0.5) * 0.35;
    pts.push({
      x: cx + cos(aa) * rr,
      y: cy + sin(aa) * rr * 0.88,
      t: t
    });
  }
  return pts;
}

function drawStreams() {
  blendMode(ADD);
  drawStream(leftPts, true, true);
  drawStream(rightPts, false, true);
  blendMode(BLEND);
  drawStream(leftPts, true, false);
  drawStream(rightPts, false, false);
}

function drawStream(pts, left, glowPass) {
  noFill();
  for (let i = 0; i < pts.length - 1; i++) {
    let t = pts[i].t;
    let col = getStreamColor(t, left);
    let w, a;
    if (glowPass) {
      w = map(t, 0, 1, 75, 5);
      a = map(t, 0, 1, 55, 5);
    } else {
      w = map(t, 0, 1, 32, 1.5);
      a = map(t, 0, 1, 200, 45);
    }
    col.setAlpha(a);
    stroke(col);
    strokeWeight(w);
    line(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
  }
}

function getStreamColor(t, left) {
  let c1, c2, c3;
  if (left) {
    c1 = color(116, 6, 38);
    c2 = color(215, 28, 68);
    c3 = color(255, 224, 178);
  } else {
    c1 = color(160, 86, 14);
    c2 = color(242, 160, 44);
    c3 = color(255, 238, 202);
  }
  if (t < 0.5) {
    return lerpColor(c1, c2, t * 2);
  } else {
    return lerpColor(c2, c3, (t - 0.5) * 2);
  }
}

function drawTendrils() {
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 36; i++) {
    let startX = 800 + random(-250, 250);
    let startY = random(430, 820);
    let ang = random(-0.9 * PI, -0.1 * PI);
    let len = random(250, 650);
    let cp1x = startX + cos(ang) * len * 0.4 + random(-70, 70);
    let cp1y = startY + sin(ang) * len * 0.4 + random(-70, 70);
    let cp2x = startX + cos(ang + 0.3) * len * 0.7 + random(-60, 60);
    let cp2y = startY + sin(ang + 0.3) * len * 0.7 + random(-60, 60);
    let endX = startX + cos(ang + random(-0.4, 0.4)) * len;
    let endY = startY + sin(ang + random(-0.4, 0.4)) * len;
    let r = random(255);
    let g = random(170, 230);
    let b = random(140, 190);
    stroke(r, g, b, random(8, 45));
    strokeWeight(random(0.8, 2.8));
    bezier(startX, startY, cp1x, cp1y, cp2x, cp2y, endX, endY);
  }
  blendMode(BLEND);
}

function drawCore() {
  blendMode(ADD);
  drawSoftGlow(800, 930, 280, 255, 225, 190, 40);
  drawSoftGlow(800, 930, 130, 255, 245, 220, 90);
  drawSoftGlow(800, 930, 55, 255, 255, 255, 170);
  blendMode(BLEND);
}

function drawDust() {
  blendMode(ADD);
  noStroke();
  let palette = [
    [255, 210, 170],
    [255, 180, 120],
    [255, 140, 130],
    [255, 220, 200],
    [255, 190, 160]
  ];
  for (let i = 0; i < 1800; i++) {
    let t = random(0, 0.96);
    let side = random() < 0.5 ? -1 : 1;
    let angle = (side < 0 ? 0.75 * PI : 0.25 * PI) + side * t * 4.8 * TWO_PI;
    let radius = 720 * (1 - t * t * 0.75) + random(-28, 28);
    let x = 800 + cos(angle + random(-0.12, 0.12)) * radius;
    let y = 930 + sin(angle + random(-0.12, 0.12)) * radius * 0.88;
    let c = palette[floor(random(0, palette.length))];
    let a = random(10, 100);
    fill(c[0], c[1], c[2], a);
    circle(x, y, random(0.8, 3.2));
  }
  blendMode(BLEND);
}

function drawVignette() {
  let g = drawingContext.createRadialGradient(800, 930, 220, 800, 930, 1500);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.58)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noiseDetail(4, 0.5);
  colorMode(RGB, 255);
  noLoop();
}

function draw() {
  drawLove();
}

function drawLove() {
  // fond dégradé vertical
  for (let y = 0; y < height; y += 4) {
    let inter = y / height;
    let c = lerpColor(color(6, 6, 22), color(30, 20, 55), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // halo central
  blendMode(ADD);
  noStroke();
  for (let r = 520; r > 0; r -= 5) {
    let alpha = map(r, 0, 520, 55, 0);
    fill(255, 180, 100, alpha);
    ellipse(width / 2, height / 2, r * 2, r * 2);
  }
  blendMode(BLEND);

  // masse chaude
  blendMode(ADD);
  for (let i = 0; i < 180; i++) {
    let angle = random(TWO_PI);
    let dist = randomGaussian(0, 1) * 130;
    let x = 520 + cos(angle) * dist;
    let y = 1380 + sin(angle) * dist * 0.9;
    let r = random(70, 170);
    let alpha = random(8, 22);
    fill(255, random(90, 130), 40, alpha);
    ellipse(x, y, r, r);
  }

  // masse froide
  for (let i = 0; i < 180; i++) {
    let angle = random(TWO_PI);
    let dist = randomGaussian(0, 1) * 120;
    let x = 1080 + cos(angle) * dist;
    let y = 620 + sin(angle) * dist * 0.9;
    let r = random(60, 160);
    let alpha = random(10, 25);
    fill(70, random(130, 180), 255, alpha);
    ellipse(x, y, r, r);
  }
  blendMode(BLEND);

  // fils
  blendMode(ADD);
  let warm = color(255, 140, 70);
  let cool = color(70, 180, 255);
  noFill();
  for (let i = 0; i < 420; i++) {
    let t = i / 419;
    let angle1 = random(TWO_PI);
    let r1 = random(80, 220);
    let x1 = 520 + cos(angle1) * r1;
    let y1 = 1380 + sin(angle1) * r1 * 0.9;
    let angle2 = random(TWO_PI);
    let r2 = random(70, 200);
    let x2 = 1080 + cos(angle2) * r2;
    let y2 = 620 + sin(angle2) * r2 * 0.9;

    let n1x = noise(i * 0.04, 2) * 280 - 140;
    let n1y = noise(i * 0.04, 3) * 280 - 140;
    let n2x = noise(i * 0.04, 5) * 280 - 140;
    let n2y = noise(i * 0.04, 7) * 280 - 140;

    let cpx1 = lerp(x1, x2, 0.25) + n1x;
    let cpy1 = lerp(y1, y2, 0.25) + n1y;
    let cpx2 = lerp(x1, x2, 0.75) + n2x;
    let cpy2 = lerp(y1, y2, 0.75) + n2y;

    let col = lerpColor(warm, cool, t);
    col.setAlpha(random(6, 35));
    stroke(col);
    strokeWeight(random(0.3, 1.6));
    bezier(x1, y1, cpx1, cpy1, cpx2, cpy2, x2, y2);
  }
  blendMode(BLEND);

  // noyau central
  blendMode(ADD);
  for (let i = 0; i < 260; i++) {
    let angle = random(TWO_PI);
    let rad = random(0, 95);
    let x = width / 2 + cos(angle) * rad;
    let y = height / 2 + sin(angle) * rad * 0.8;
    let sz = random(1, 6);
    let alpha = random(30, 130);
    fill(255, 240, 200, alpha);
    noStroke();
    ellipse(x, y, sz, sz);
  }
  for (let r = 90; r > 0; r -= 3) {
    let alpha = map(r, 0, 90, 110, 5);
    fill(255, 250, 240, alpha);
    ellipse(width / 2, height / 2, r * 2, r * 2);
  }
  blendMode(BLEND);

  // grands arcs d'étreinte
  blendMode(ADD);
  noFill();
  for (let k = 0; k < 24; k++) {
    let off = k * 4;
    stroke(255, 160, 80, 7);
    strokeWeight(14 + off * 0.4);
    bezier(280, 1900, 520, 1250 + off, 900, 820 + off, 1320, 350);
  }
  for (let k = 0; k < 24; k++) {
    let off = k * 4;
    stroke(80, 180, 255, 7);
    strokeWeight(14 + off * 0.4);
    bezier(1320, 1700, 1000, 1100 + off, 600, 950 + off, 360, 450);
  }
  blendMode(BLEND);
}

const W = 1600, H = 2000;
const CX = 800, CY = 820;

const COOL_FAR = [51, 71, 126];
const COOL_MID = [143, 167, 217];
const WARM_FAR = [142, 58, 78];
const WARM_MID = [224, 136, 79];
const GOLD = [244, 189, 106];
const WHITE = [255, 242, 216];

function mix(a, b, t) {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  ];
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  backgroundBase();
  nebula();
  vortexArcs();
  const rec = flowStreams();
  threads(rec);
  groundAndKintsugi();
  risingSeam();
  hearth();
  embers();
  stars();
  vignette();
  grain();
}

function gradientColor(stops, t) {
  for (let i = 0; i < stops.length - 1; i++) {
    const t0 = stops[i][0], c0 = stops[i][1];
    const t1 = stops[i + 1][0], c1 = stops[i + 1][1];
    if (t >= t0 && t <= t1) return lerpColor(c0, c1, (t - t0) / (t1 - t0));
  }
  return stops[stops.length - 1][1];
}

function backgroundBase() {
  const stops = [
    [0.00, color('#04060d')],
    [0.18, color('#0a1126')],
    [0.42, color('#141d40')],
    [0.60, color('#181631')],
    [0.80, color('#140d1c')],
    [1.00, color('#060409')]
  ];
  noStroke();
  for (let y = 0; y <= H; y += 2) {
    const t = y / H;
    const c = gradientColor(stops, t);
    const n = noise(t * 5 + 3) - 0.5;
    fill(red(c) + n * 10, green(c) + n * 8, blue(c) + n * 14);
    rect(0, y - 1, W, 2.6);
  }
}

function nebula() {
  push();
  blendMode(ADD);
  noStroke();
  const cols = [[48, 62, 120], [84, 52, 96], [34, 78, 96], [110, 58, 66]];
  for (let i = 0; i < 240; i++) {
    const c = cols[floor(random(cols.length))];
    fill(c[0], c[1], c[2], random(3, 9));
    ellipse(random(W), random(H * 0.9), random(60, 260), random(40, 180));
  }
  for (let i = 0; i < 26; i++) {
    const r = 560 - i * 20;
    fill(150, 92, 54, 2.2);
    ellipse(CX + random(-8, 8), CY + random(-8, 8), r * 2, r * 2 * random(0.94, 1.02));
  }
  pop();
}

function vortexArcs() {
  noFill();
  for (let k = 0; k < 7; k++) {
    const r = 360 + k * 118 + random(-20, 20);
    const a0 = random(TWO_PI);
    const span = random(PI * 0.5, PI * 1.4);
    const warm = random() < 0.4;
    stroke(warm ? 232 : 120, warm ? 180 : 140, warm ? 106 : 200, warm ? 14 : 12);
    strokeWeight(random(0.8, 1.8));
    beginShape();
    for (let a = 0; a <= span; a += 0.06) {
      const rr = r + (noise(cos(a0 + a) * 2 + k * 7 + 10, sin(a0 + a) * 2 + 10) - 0.5) * 46;
      vertex(CX + cos(a0 + a) * rr, CY + sin(a0 + a) * rr);
    }
    endShape();
  }
}

function streamCol(kind, r) {
  const far = kind === 0 ? COOL_FAR : WARM_FAR;
  const mid = kind === 0 ? COOL_MID : WARM_MID;
  const t1 = constrain(map(r, 1050, 320, 0, 1), 0, 1);
  const warmth = pow(constrain(map(r, 660, 130, 0, 1), 0, 1), 1.6);
  const c = mix(mix(far, mid, t1), GOLD, warmth * 0.92);
  const a = 26 + 46 * warmth + random(-6, 10);
  return [c[0], c[1], c[2], a];
}

function flowStreams() {
  const rec = [];
  const defs = [
    { n: 140, kind: 0, spawn: () => createVector(random(-90, 540), random(1500, 2180)) },
    { n: 140, kind: 1, spawn: () => createVector(random(1150, 1780), random(960, 1980)) }
  ];
  blendMode(BLEND);
  noFill();

  for (const d of defs) {
    for (let i = 0; i < d.n; i++) {
      const p = d.spawn();
      const baseW = random(0.7, 2.0);
      let steps = 0, seg = 0;
      let r = dist(p.x, p.y, CX, CY);
      let c = streamCol(d.kind, r);
      stroke(c[0], c[1], c[2], c[3]);
      strokeWeight(baseW);
      beginShape();
      vertex(p.x, p.y);
      while (steps < 760) {
        const dx = CX - p.x, dy = CY - p.y;
        r = sqrt(dx * dx + dy * dy);
        if (r < 74) break;
        const ang = atan2(dy, dx);
        const swirl = constrain(map(r, 60, 900, 1.5, 0.5), 0.5, 1.5);
        const na = noise(p.x * 0.0015 + 50, p.y * 0.0015 + 50) * TWO_PI * 2;
        let vx = cos(ang) + cos(ang + HALF_PI) * swirl + cos(na) * 0.4;
        let vy = sin(ang) + sin(ang + HALF_PI) * swirl + sin(na) * 0.4;
        const m = sqrt(vx * vx + vy * vy) || 1;
        const sp = 2.4 + noise(p.x * 0.004 + 90, p.y * 0.004 + 90) * 1.6;
        p.x += (vx / m) * sp;
        p.y += (vy / m) * sp;
        vertex(p.x, p.y);
        if (steps % 40 === 0) rec.push({ x: p.x, y: p.y, kind: d.kind, r: r });
        steps++;
        seg++;
        if (seg >= 11) {
          endShape();
          c = streamCol(d.kind, r);
          stroke(c[0], c[1], c[2], c[3]);
          strokeWeight(baseW * (0.75 + map(r, 900, 100, 0.55, 1.25, true)));
          beginShape();
          vertex(p.x, p.y);
          seg = 0;
        }
      }
      endShape();
    }
  }
  return rec;
}

function threads(rec) {
  const A = rec.filter(q => q.kind === 0 && q.r > 240 && q.r < 780);
  const B = rec.filter(q => q.kind === 1 && q.r > 240 && q.r < 780);
  blendMode(BLEND);
  noFill();
  let drawn = 0, tries = 0;
  while (drawn < 46 && tries < 900 && A.length && B.length) {
    tries++;
    const a = A[floor(random(A.length))];
    const b = B[floor(random(B.length))];
    const d = dist(a.x, a.y, b.x, b.y);
    if (d < 80 || d > 380) continue;
    const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2 + d * random(0.08, 0.24);
    const al = random(18, 44);
    stroke(246, 206, 128, al);
    strokeWeight(random(0.5, 1.25));
    bezier(a.x, a.y, mx + random(-20, 20), my, mx + random(-20, 20), my, b.x, b.y);
    noStroke();
    fill(255, 224, 160, al + 26);
    circle(a.x, a.y, random(2, 3.6));
    circle(b.x, b.y, random(2, 3.6));
    drawn++;
  }
}

function groundAndKintsugi() {
  blendMode(BLEND);
  noStroke();
  for (let y = 1500; y < H; y += 3) {
    const t = map(y, 1500, H, 0, 1);
    fill(8, 6, 12, 30 + 200 * pow(t, 1.5));
    rect(0, y - 1.5, W, 3.4);
  }
  blendMode(ADD);
  for (let i = 0; i < 30; i++) {
    const rx = 560 - i * 17, ry = 190 - i * 5.6;
    fill(214, 140, 70, 2.4);
    ellipse(CX, 1545, rx * 2, ry * 2);
  }
  blendMode(BLEND);

  for (let c = 0; c < 17; c++) {
    let x = random(50, W - 50);
    let y = H + random(10, 120);
    const pts = [];
    const maxRise = random(140, 430);
    let risen = 0;
    while (risen < maxRise && y > 1522) {
      pts.push({ x: x, y: y });
      const dy = random(2.5, 6.5);
      y -= dy; risen += dy;
      x += randomGaussian() * 3.2 + (noise(x * 0.012 + 15, y * 0.012 + 15) - 0.5) * 14;
    }
    if (pts.length < 4) continue;
    noFill();
    stroke(3, 2, 6, 200);
    strokeWeight(random(2.6, 4.6));
    beginShape(); for (const q of pts) vertex(q.x, q.y); endShape();
    stroke(235, 190, 100, 235);
    strokeWeight(random(0.9, 1.7));
    beginShape(); for (const q of pts) vertex(q.x + 0.6, q.y); endShape();
    blendMode(ADD);
    stroke(235, 190, 100, 30);
    strokeWeight(4.5);
    beginShape(); for (const q of pts) vertex(q.x, q.y); endShape();
    blendMode(BLEND);
    noStroke();
    fill(255, 226, 150, 220);
    const nb = floor(random(1, 4));
    for (let b = 0; b < nb; b++) {
      const q = pts[floor(random(pts.length))];
      circle(q.x, q.y, random(2.2, 4.4));
    }
  }
}

function risingSeam() {
  blendMode(BLEND);
  noFill();
  const pts = [];
  let x = CX + random(-30, 30), y = 1552;
  while (y > 1005) {
    pts.push({ x: x, y: y });
    y -= random(6, 11);
    x += (noise(y * 0.01 + 60) - 0.5) * 12;
  }
  stroke(240, 198, 112, 130);
  strokeWeight(1.3);
  beginShape(); for (const q of pts) vertex(q.x, q.y); endShape();
  blendMode(ADD);
  stroke(240, 198, 112, 26);
  strokeWeight(4);
  beginShape(); for (const q of pts) vertex(q.x, q.y); endShape();
  blendMode(BLEND);
  noStroke();
  fill(255, 232, 170, 200);
  for (let i = 0; i < 5; i++) {
    const q = pts[floor(random(pts.length))];
    circle(q.x, q.y, random(2.5, 4));
  }
}

function hearth() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 30; i++) {
    const r = 500 - i * 15;
    fill(216, 132, 66, 0.8 + i * 0.28);
    ellipse(CX + random(-4, 4), CY + random(-4, 4), r * 2, r * 2 * random(0.96, 1.03));
  }
  for (let i = 0; i < 22; i++) {
    const r = 300 - i * 12;
    fill(244, 189, 106, 2.2 + i * 0.35);
    ellipse(CX, CY, r * 2, r * 2);
  }
  noFill();
  for (let i = 0; i < 1050; i++) {
    const th = random(TWO_PI);
    const r0 = pow(random(), 0.65) * 250 + 30;
    const L = random(26, 150) * (1 + (280 - r0) / 300);
    const curl = random(0.25, 0.85) * (random() < 0.5 ? -1 : 1);
    const c = mix(GOLD, WHITE, pow(random(), 2));
    stroke(c[0], c[1], c[2], random(16, 60));
    strokeWeight(random(0.6, 2.1));
    beginShape();
    let a = th, rr = r0;
    for (let s = 0; s < 7; s++) {
      vertex(CX + cos(a) * rr, CY + sin(a) * rr);
      a += curl * 0.12;
      rr += L / 7;
    }
    endShape();
  }
  seedGlow(742, 788, [172, 200, 244], 62);
  seedGlow(868, 862, [255, 168, 112], 66);
  noStroke();
  for (let i = 0; i < 14; i++) {
    const r = 66 - i * 4;
    fill(255, 244, 220, 5 + i * 1.2);
    ellipse(806, 826, r * 2, r * 2);
  }
  fill(255, 250, 236, 90);
  ellipse(806, 826, 26, 26);
  pop();

  blendMode(BLEND);
  noFill();
  for (let k = 0; k < 5; k++) {
    const R = 320 + k * 150;
    stroke(244, 200, 120, 16 - k * 2);
    strokeWeight(1);
    beginShape();
    for (let a = 0; a <= TWO_PI + 0.02; a += 0.05) {
      const rr = R + (noise(cos(a) * 1.4 + k * 13 + 20, sin(a) * 1.4 + 20) - 0.5) * 34;
      vertex(CX + cos(a) * rr, CY + sin(a) * rr);
    }
    endShape(CLOSE);
  }
}

function seedGlow(x, y, rim, rad) {
  noFill();
  for (let i = 0; i < 60; i++) {
    const a = random(TWO_PI);
    const rr = rad + random(-6, 8);
    stroke(rim[0], rim[1], rim[2], random(14, 40));
    strokeWeight(random(0.8, 2));
    arc(x, y, rr * 2, rr * 2, a, a + random(0.2, 0.7));
  }
  noStroke();
  for (let i = 0; i < 16; i++) {
    const r = rad * (1 - i / 17);
    fill(255, 232, 190, 4 + i);
    ellipse(x, y, r * 2, r * 2);
  }
}

function emberColor(t) {
  if (t < 0.35) return mix([255, 238, 196], [244, 178, 106], t / 0.35);
  if (t < 0.70) return mix([244, 178, 106], [210, 106, 122], (t - 0.35) / 0.35);
  return mix([210, 106, 122], [116, 128, 180], (t - 0.70) / 0.30);
}

function embers() {
  push();
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 240; i++) {
    let x = CX + randomGaussian() * 80;
    let y = CY + randomGaussian() * 60 - 10;
    const life = 50 + random(140);
    const drift = random(-0.9, 0.9);
    const vy = random(1.6, 3.8);
    const w = random(0.7, 1.9);
    let px = x, py = y, seg = 0;
    for (let s = 0; s < life; s++) {
      const t = s / life;
      x += drift + (noise(x * 0.006 + 30, y * 0.006 + 30) - 0.5) * 3.4;
      y -= vy * (1 - t * 0.4);
      if (seg === 0) { px = x; py = y; seg = 1; continue; }
      const c = emberColor(t);
      stroke(c[0], c[1], c[2], (1 - t) * 46 + 4);
      strokeWeight(w * (1 - t * 0.6));
      line(px, py, x, y);
      px = x; py = y;
      if (y < -20) break;
    }
    if (random() < 0.3) {
      noStroke();
      fill(255, 240, 205, 60);
      circle(x, y, random(1.6, 3.4));
      noFill();
    }
  }
  pop();
}

function stars() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 230; i++) {
    const x = random(W);
    const y = pow(random(), 1.6) * H * 0.8;
    const warm = random() < 0.25;
    const al = random(14, 60);
    fill(warm ? 255 : 205, warm ? 226 : 216, warm ? 168 : 244, al);
    circle(x, y, random(0.8, 2.6));
  }
  for (let i = 0; i < 12; i++) {
    const x = random(W), y = random(H * 0.55);
    const al = random(40, 80);
    fill(235, 240, 255, al);
    circle(x, y, random(2.2, 3.6));
    stroke(235, 240, 255, al * 0.6);
    strokeWeight(0.7);
    const L = random(5, 12);
    line(x - L, y, x + L, y);
    line(x, y - L, x, y + L);
    noStroke();
  }
  pop();
}

function vignette() {
  blendMode(BLEND);
  noStroke();
  for (let y = 0; y < 300; y += 3) {
    fill(4, 5, 11, 130 * pow(1 - y / 300, 1.6));
    rect(0, y - 1.5, W, 3.4);
  }
  for (let x = 0; x < 240; x += 3) {
    const a = 110 * pow(1 - x / 240, 1.7);
    fill(4, 5, 11, a);
    rect(x - 1.5, 0, 3.4, H);
    rect(W - x - 1.5, 0, 3.4, H);
  }
  for (let y = 0; y < 240; y += 3) {
    fill(3, 2, 7, 120 * pow(1 - y / 240, 1.6));
    rect(0, H - y - 1.5, W, 3.4);
  }
}

function grain() {
  blendMode(BLEND);
  for (let i = 0; i < 3400; i++) {
    const light = random() < 0.5;
    stroke(light ? 255 : 0, light ? 255 : 0, light ? 255 : 0, random(4, 13));
    strokeWeight(random(0.6, 1.6));
    point(random(W), random(H));
  }
  blendMode(ADD);
  for (let i = 0; i < 700; i++) {
    const a = random(TWO_PI), r = pow(random(), 0.8) * 520;
    stroke(244, 200, 120, random(6, 18));
    strokeWeight(random(0.6, 1.4));
    point(CX + cos(a) * r, CY + sin(a) * r);
  }
  blendMode(BLEND);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 1);
  pixelDensity(1);
  noLoop();

  paintGround();

  const A = { x: width * 0.37, y: height * 0.33 };
  const B = { x: width * 0.62, y: height * 0.66 };
  const C = { x: (A.x + B.x) * 0.5, y: (A.y + B.y) * 0.5 };

  colorFields(A, B, C);
  rings(A, 208, 76, 92, 540, 96);
  rings(B, 12, 82, 94, 580, 104);
  rings(C, 46, 88, 100, 400, 84);
  filaments(A, B);
  woundsAndRepair(A, B);
  centralBloom(C);
  vignette();
}

function paintGround() {
  noStroke();
  for (let y = 0; y <= height; y += 2) {
    let t = y / height;
    let n = noise(t * 4.7, 12.3);
    let h = lerp(240, 340, pow(t, 1.28)) + (n - 0.5) * 26;
    let s = lerp(70, 88, t);
    let b = lerp(8, 19, t) + n * 7;
    fill((h + 360) % 360, s, b, 1);
    rect(0, y, width, 2.5);
  }

  for (let i = 0; i < 5200; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0032, y * 0.0032);
    let h = lerp(232, 348, y / height) + (n - 0.5) * 30;
    fill((h + 360) % 360, 62, n > 0.52 ? 26 : 8, 0.026);
    ellipse(x, y, random(2, 26), random(2, 26));
  }
}

function colorFields(A, B, C) {
  noStroke();
  blendMode(ADD);
  for (let i = 0; i < 34; i++) {
    let r = map(i, 0, 33, 640, 90);
    fill((210 + random(-8, 8) + 360) % 360, 76, 72, 0.012);
    ellipse(A.x + random(-26, 26), A.y + random(-26, 26), r * 2, r * 2);
    fill((14 + random(-8, 8) + 360) % 360, 80, 74, 0.011);
    ellipse(B.x + random(-28, 28), B.y + random(-28, 28), r * 2.08, r * 2.08);
    fill((46 + random(-6, 6) + 360) % 360, 84, 80, 0.008);
    ellipse(C.x + random(-20, 20), C.y + random(-20, 20), r * 1.5, r * 1.5);
  }
  blendMode(BLEND);
}

function rings(p, baseHue, s, b, maxR, count) {
  noFill();
  for (let i = 0; i < count; i++) {
    let t = i / (count - 1);
    let rBase = lerp(maxR * 0.12, maxR, t);
    let alpha = lerp(0.15, 0.015, t);
    let h = (baseHue + random(-10, 10) + 360) % 360;
    stroke(h, s, b, alpha);
    strokeWeight(random(0.4, 2.2));
    beginShape();
    for (let a = 0; a <= TWO_PI + 0.05; a += 0.065) {
      let nx = cos(a) * 0.82 + 5.2;
      let ny = sin(a) * 0.82 + 9.7;
      let n = noise(p.x * 0.0008 + nx + i * 0.016, p.y * 0.0008 + ny + i * 0.021);
      let r = rBase * (0.68 + 0.62 * n);
      vertex(p.x + cos(a) * r, p.y + sin(a) * r);
    }
    endShape();
  }
}

function filaments(A, B) {
  noFill();
  blendMode(ADD);
  let d = dist(A.x, A.y, B.x, B.y);
  let nx = -(B.y - A.y) / d;
  let ny = (B.x - A.x) / d;

  for (let i = 0; i < 380; i++) {
    let pick = random();
    let h;
    if (pick < 0.18) h = 46;
    else if (pick < 0.58) h = 206;
    else h = 10;

    let x1 = A.x + cos(random(TWO_PI)) * random(0, 260);
    let y1 = A.y + sin(random(TWO_PI)) * random(0, 260);
    let x2 = B.x + cos(random(TWO_PI)) * random(0, 285);
    let y2 = B.y + sin(random(TWO_PI)) * random(0, 285);

    let bend1 = random(-430, 430) * noise(i * 0.021, 3.4);
    let bend2 = random(-430, 430) * noise(i * 0.021, 8.9);

    let c1x = lerp(x1, x2, 0.30) + nx * bend1 + random(-70, 70);
    let c1y = lerp(y1, y2, 0.30) + ny * bend1 + random(-70, 70);
    let c2x = lerp(x1, x2, 0.70) + nx * bend2 + random(-70, 70);
    let c2y = lerp(y1, y2, 0.70) + ny * bend2 + random(-70, 70);

    stroke((h + random(-12, 12) + 360) % 360, random(48, 96), random(62, 100), random(0.012, 0.058));
    strokeWeight(random(0.35, 2.7));
    bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);
  }
  blendMode(BLEND);
}

function woundsAndRepair(A, B) {
  noStroke();
  for (let i = 0; i < 260; i++) {
    let t = random();
    let x = lerp(A.x, B.x, t) + random(-420, 420);
    let y = lerp(A.y, B.y, t) + random(-420, 420);
    let darkHue = random() < 0.5 ? 248 : 336;
    fill(darkHue, random(50, 72), random(4, 12), random(0.04, 0.15));
    ellipse(x, y, random(4, 62), random(4, 62));
  }

  blendMode(ADD);
  for (let i = 0; i < 680; i++) {
    let t = random();
    let x = lerp(A.x, B.x, t) + random(-340, 340);
    let y = lerp(A.y, B.y, t) + random(-340, 340);
    let gold = random() < 0.72;
    let h = gold ? 46 + random(-6, 8) : 200 + random(-20, 30);
    fill((h + 360) % 360, random(38, 92), 100, random(0.03, gold ? 0.18 : 0.08));
    let r = random(1, gold ? 7 : 4);
    ellipse(x, y, r, r);
  }
  blendMode(BLEND);
}

function centralBloom(C) {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 64; i++) {
    let r = map(i, 0, 63, 560, 10);
    let h = lerp(42, 54, noise(i * 0.11));
    fill(h, 76, 100, 0.008);
    ellipse(C.x + random(-12, 12), C.y + random(-12, 12), r, r * 1.18);
  }
  for (let i = 0; i < 190; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 1.6) * 300;
    fill(48, 70, 100, random(0.02, 0.12));
    ellipse(C.x + cos(a) * r, C.y + sin(a) * r * 1.12, random(1, 4.5), random(1, 4.5));
  }
  blendMode(BLEND);
}

function vignette() {
  noStroke();
  for (let x = 0; x < 230; x += 5) {
    let a = map(x, 0, 230, 0.12, 0);
    fill(252, 82, 4, a);
    rect(x, 0, 5, height);
    rect(width - x - 5, 0, 5, height);
  }
  for (let y = 0; y < 320; y += 5) {
    let a = map(y, 0, 320, 0.16, 0);
    fill(250, 84, 4, a);
    rect(0, y, width, 5);
    rect(0, height - y - 5, width, 5);
  }
}

// LA TRESSE ARDENTE — peinture générative fixe, 1600 × 2000, p5.js 1.11

const W = 1600, H = 2000;
const CX = 800, CY = 760;
const Y0 = 2160;

const PAL_A = [[88, 18, 30], [182, 54, 38], [235, 152, 62]];
const PAL_B = [[112, 26, 56], [200, 86, 94], [242, 198, 160]];
const GOLD = [224, 172, 96];
const IVORY = [247, 236, 216];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  strokeCap(ROUND);

  // 1 — le sol : nuit prune, souffles chauds et froids
  background(26, 16, 24);
  softGlow(W / 2, 1650, 950, [96, 32, 44], 9);
  softGlow(260, 460, 760, [36, 54, 62], 6);
  softGlow(1360, 300, 700, [32, 48, 56], 5);
  softGlow(W / 2, 1150, 560, [70, 24, 36], 5);
  softGlow(W / 2, H + 60, 760, [116, 44, 40], 8);

  veils();       // sous-peinture : courants du champ
  embrace();     // deux grands bras qui enveloppent
  farRings();    // respiration concentrique lointaine

  // lueur sous la tresse
  for (let i = 0; i < 5; i++) {
    let t = 0.16 + i * 0.2;
    let s = spine(t);
    softGlow(s.x, s.y, 300, [122, 44, 42], 4.5);
  }

  // 2 — les deux courants tressés
  paintStrand(0, PAL_A);
  paintStrand(PI, PAL_B);

  // vrilles semées partout, racines vers le bas
  for (let i = 0; i < 46; i++) {
    let k = i % 2 === 0 ? 0 : PI;
    tendril(random(0.08, 0.92), k, k === 0 ? PAL_A : PAL_B, false);
  }
  for (let i = 0; i < 14; i++) {
    let k = i % 2 === 0 ? 0 : PI;
    tendril(random(0.0, 0.12), k, k === 0 ? PAL_A : PAL_B, true);
  }

  crossingNodes(); // nœuds lumineux des croisements

  // 3 — l'étreinte devient lumière
  blendMode(ADD);
  softGlow(CX, CY, 430, [110, 52, 30], 6);
  blendMode(BLEND);

  bloomRings();
  rays();

  blendMode(ADD);
  softGlow(CX, CY, 130, [216, 158, 88], 15);
  softGlow(CX, CY, 62, [236, 202, 142], 20);
  blendMode(BLEND);

  drips();   // l'or patient qui coule
  sparks();  // étincelles et pétales

  // cœur
  noStroke();
  fill(255, 249, 234, 96);
  ellipse(CX, CY, 50, 50);
  fill(250, 240, 219, 232);
  ellipse(CX, CY, 26, 26);

  grain();
  vignette();
}

// ---------- outils ----------

function softGlow(x, y, maxR, col, peak, rings) {
  rings = rings || 24;
  noStroke();
  for (let i = rings; i >= 1; i--) {
    let t = i / rings;
    fill(col[0], col[1], col[2], peak * pow(1 - t, 1.7));
    ellipse(x, y, maxR * 2 * t, maxR * 2 * t);
  }
}

function dash(x1, y1, x2, y2, w, col, a) {
  stroke(col[0], col[1], col[2], a);
  strokeWeight(w);
  line(x1, y1, x2, y2);
}

function mix(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}
function triLerp(pal, t) {
  if (t < 0.5) return mix(pal[0], pal[1], t * 2);
  return mix(pal[1], pal[2], (t - 0.5) * 2);
}
function darker(c, f) { return [c[0] * f, c[1] * f, c[2] * f]; }

// ---------- géométrie de la tresse ----------

function spine(t) {
  let sway = sin(t * 3.4 + 0.5) * 120 * pow(1 - t, 1.1);
  return { x: CX + sway, y: Y0 + (CY - Y0) * t };
}
function phase(t) { return TWO_PI * (0.5 * t + 1.8 * t * t); }
function braidR(t) { return 30 + 260 * pow(1 - t, 1.35); }

function strandPoint(t, k) {
  let s = spine(t);
  let ph = phase(t) + k;
  let r = braidR(t);
  let jx = (noise(t * 9.1, k * 0.5 + 2) - 0.5) * 10;
  let jy = (noise(t * 7.3, k * 0.5 + 41) - 0.5) * 10;
  return {
    x: s.x + r * cos(ph) + jx,
    y: s.y + r * sin(ph) * 0.34 + jy,
    depth: sin(ph)
  };
}

function paintStrand(k, pal) {
  const N = 560;
  for (let pass = 0; pass < 2; pass++) {
    let prev = null;
    for (let i = 0; i <= N; i++) {
      let t = i / N;
      let p = strandPoint(t, k);
      let front = p.depth >= 0;
      if ((pass === 1) === front) {
        if (prev) {
          let w = 8.5 + 15.5 * (0.5 + 0.5 * p.depth);
          w *= 0.7 + 0.55 * sin(PI * min(t * 1.12, 1));
          if (t > 0.96) w *= map(t, 0.96, 1, 1, 0.55);
          let col = triLerp(pal, pow(t, 0.9));
          let a;
          if (front) {
            a = 235;
          } else {
            col = darker(col, 0.55);
            a = 150;
          }
          dash(prev.x, prev.y, p.x, p.y, max(w, 1.2), col, a);
          if (front && p.depth > 0.35 && ((i * 7 + (k === 0 ? 1 : 2)) % 3 === 0)) {
            dash(prev.x + 1.5, prev.y - 2, p.x + 1.5, p.y - 2,
              w * 0.3, mix(col, IVORY, 0.55), 115);
          }
        }
        prev = p;
      } else {
        prev = null;
      }
    }
  }
}

function crossingNodes() {
  let prev = cos(phase(0));
  for (let i = 1; i <= 420; i++) {
    let t = i / 420;
    let v = cos(phase(t));
    if ((prev < 0 && v >= 0) || (prev >= 0 && v < 0)) {
      let s = spine(t);
      softGlow(s.x, s.y, 46, [238, 190, 112], 15);
      noStroke();
      fill(250, 241, 220, 215);
      ellipse(s.x, s.y, 9, 9);
      noFill();
      stroke(232, 182, 102, 110);
      strokeWeight(1.2);
      ellipse(s.x, s.y, 27, 27);
    }
    prev = v;
  }
}

function tendril(t0, k, pal, isRoot) {
  let p = strandPoint(t0, k);
  let x = p.x, y = p.y;
  let steps = isRoot ? 90 + int(random(90)) : 45 + int(random(85));
  let col = mix(triLerp(pal, pow(t0, 0.9)), GOLD, isRoot ? 0.25 : 0.4);
  let w = isRoot ? random(0.7, 1.5) : random(1.2, 2.6);
  let aBase = isRoot ? 42 : 55;
  let so = random(1000);
  for (let s = 0; s < steps; s++) {
    let ang = noise(x * 0.0038 + so, y * 0.0038) * TWO_PI * 2.1;
    let nx = x + cos(ang) * 3.6;
    let ny = y + sin(ang) * 3.6 + (isRoot ? 2.3 : 0);
    dash(x, y, nx, ny, w, col, aBase * (1 - s / steps) + 6);
    x = nx; y = ny;
    w *= 0.994;
  }
  if (!isRoot && random() < 0.55) {
    noStroke();
    let bud = random() < 0.6 ? GOLD : [236, 148, 138];
    fill(bud[0], bud[1], bud[2], 95);
    ellipse(x, y, random(3, 5), random(3, 5));
  }
}

// ---------- champ et gestes ----------

function veils() {
  for (let i = 0; i < 26; i++) {
    let x = random(W), y = random(H);
    let col = random() < 0.5 ? [118, 42, 54] : [58, 78, 88];
    let a = random(8, 17);
    let wgt = random(0.8, 2.3);
    let sc = random(0.0012, 0.0026);
    for (let s = 0; s < 130; s++) {
      let ang = noise(x * sc, y * sc, i * 0.37) * TWO_PI * 2.2;
      let nx = x + cos(ang) * 7;
      let ny = y + sin(ang) * 7;
      dash(x, y, nx, ny, wgt, col, a);
      x = nx; y = ny;
      if (x < -60 || x > W + 60 || y < -60 || y > H + 60) break;
    }
  }
}

function embrace() {
  arcRing(2050, 1420, 1413, 3.16, 4.10, GOLD, 26, 2.2, 11);
  arcRing(-450, 1420, 1413, -0.96, -0.02, GOLD, 26, 2.2, 29);
}

function arcRing(cx, cy, R, a0, a1, col, al, wgt, so) {
  noFill();
  stroke(col[0], col[1], col[2], al);
  strokeWeight(wgt);
  beginShape();
  for (let ang = a0; ang <= a1; ang += 0.015) {
    let wob = (noise(so + ang * 2.3, so * 1.7) - 0.5) * 0.03;
    let rr = R * (1 + wob);
    vertex(cx + rr * cos(ang), cy + rr * sin(ang));
  }
  endShape();
}

function farRings() {
  brokenRing(CX, CY, 810, GOLD, 14, 1.3, 3.1, 0.42);
  brokenRing(CX, CY, 1010, GOLD, 11, 1.1, 5.7, 0.46);
  brokenRing(CX, CY, 1260, [150, 130, 110], 9, 1.0, 8.9, 0.5);
}

function bloomRings() {
  brokenRing(CX - 140, CY, 300, GOLD, 26, 1.4, 13.7, 0.34);
  brokenRing(CX + 140, CY, 300, GOLD, 26, 1.4, 17.3, 0.34);
  brokenRing(CX, CY, 150, GOLD, 62, 2.4, 21.1, 0.30);
  brokenRing(CX, CY, 205, GOLD, 52, 2.0, 23.7, 0.32);
  brokenRing(CX, CY, 285, GOLD, 42, 1.8, 29.3, 0.34);
  brokenRing(CX, CY, 380, GOLD, 32, 1.5, 31.9, 0.38);
  brokenRing(CX, CY, 500, GOLD, 24, 1.2, 37.1, 0.42);
}

function brokenRing(x, y, R, col, al, wgt, so, gap) {
  noFill();
  stroke(col[0], col[1], col[2], al);
  strokeWeight(wgt);
  beginShape();
  let has = false;
  for (let ang = 0; ang <= TWO_PI + 0.02; ang += 0.02) {
    let on = noise(so * 3.7 + ang * 1.9, so) > gap;
    if (on) {
      let wob = (noise(so + cos(ang) * 1.4 + 3, so + sin(ang) * 1.4 + 7) - 0.5) * 0.06;
      let rr = R * (1 + wob);
      vertex(x + rr * cos(ang), y + rr * sin(ang));
      has = true;
    } else if (has) {
      endShape();
      beginShape();
      has = false;
    }
  }
  endShape();
}

function rays() {
  for (let i = 0; i < 150; i++) {
    let ang = random(TWO_PI);
    let L = 46 + pow(random(), 2.2) * 430;
    let r0 = random();
    let col = r0 < 0.48 ? [238, 196, 120] : (r0 < 0.82 ? [247, 232, 206] : [228, 132, 118]);
    let al = random(24, 92);
    let wgt = random(1.0, 3.1);
    let p0x = CX + cos(ang) * 24, p0y = CY + sin(ang) * 24;
    let p1x = CX + cos(ang) * L, p1y = CY + sin(ang) * L;
    let bend = (random() - 0.5) * 0.42 * L;
    let cxp = CX + cos(ang) * L * 0.55 - sin(ang) * bend;
    let cyp = CY + sin(ang) * L * 0.55 + cos(ang) * bend;
    let mx = 0.25 * p0x + 0.5 * cxp + 0.25 * p1x;
    let my = 0.25 * p0y + 0.5 * cyp + 0.25 * p1y;
    dash(p0x, p0y, mx, my, wgt, col, al);
    dash(mx, my, p1x, p1y, wgt * 0.45, col, al * 0.8);
  }
}

function drips() {
  for (let i = 0; i < 7; i++) {
    let x = CX + (random() - 0.5) * 220;
    let yStart = CY + 24 + random(70);
    let len = 260 + random(680);
    let col = random() < 0.6 ? [238, 205, 140] : IVORY;
    let al = random(46, 92);
    let wgt = random(0.8, 1.8);
    let so = random(1000);
    let cx0 = x;
    for (let yy = yStart; yy < yStart + len; yy += 7) {
      let xx = cx0 + (noise(so + yy * 0.02) - 0.5) * 6;
      dash(cx0, yy, xx, yy + 7, wgt, col, al * (1 - (yy - yStart) / len));
      cx0 = xx;
    }
    noStroke();
    fill(col[0], col[1], col[2], al * 0.85);
    ellipse(cx0, yStart + len, 4.5, 6.5);
  }
}

function sparks() {
  noStroke();
  for (let i = 0; i < 780; i++) {
    let x, y;
    if (random() < 0.6) {
      let ang = random(TWO_PI);
      let d = pow(random(), 1.7) * 640;
      x = CX + cos(ang) * d * 1.15;
      y = CY + sin(ang) * d * 1.3;
    } else {
      x = random(W);
      y = random(H);
    }
    let r0 = random();
    let col = r0 < 0.72 ? IVORY : (r0 < 0.94 ? GOLD : [122, 168, 158]);
    let a = random(26, 120);
    let s = random(1.2, 3.6);
    fill(col[0], col[1], col[2], a);
    ellipse(x, y, s, s);
    if (random() < 0.05) {
      stroke(col[0], col[1], col[2], a * 0.55);
      strokeWeight(0.8);
      let g = random(5, 15);
      line(x - g, y, x + g, y);
      line(x, y - g, x, y + g);
      noStroke();
    }
    if (random() < 0.02) {
      fill(col[0], col[1], col[2], a * 0.5);
      ellipse(x + random(-30, 30), y + random(-20, 40), random(7, 16), random(4, 9));
    }
  }
}

function grain() {
  noStroke();
  for (let i = 0; i < 16000; i++) {
    let x = random(W), y = random(H);
    let al = random(5, 16);
    if (random() < 0.6) fill(10, 6, 12, al);
    else fill(243, 231, 210, al);
    let s = random() < 0.85 ? 1.4 : 2.6;
    rect(x, y, s, s);
  }
}

function vignette() {
  softGlow(0, 0, 1150, [12, 6, 12], 8);
  softGlow(W, 0, 1150, [12, 6, 12], 8);
  softGlow(0, H, 1250, [12, 6, 12], 9);
  softGlow(W, H, 1250, [12, 6, 12], 9);
  softGlow(W / 2, -260, 1000, [12, 6, 12], 5);
  softGlow(-160, H / 2, 820, [12, 6, 12], 5);
  softGlow(W + 160, H / 2, 820, [12, 6, 12], 5);
}

let W = 1600, H = 2000;
let CX = 800, CY = 930;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
  paint();
}

function paint() {
  ground();
  arrivalThreads();
  roots();
  glowBase();
  weave();
  halo();
  core();
  sparks();
  grain();
  vignette();
}

function ground() {
  background(336, 58, 8);
  for (let i = 0; i < 2400; i++) {
    let x = random(W), y = random(H);
    let n = noise(x * 0.0011, y * 0.0011);
    let n2 = noise(x * 0.004 + 40, y * 0.004);
    let warm = constrain(map(y, 0, H, 0.9, 0.1) + (n - 0.5) * 0.8, 0, 1);
    let h = lerp(338, 18, warm);
    let s = lerp(45, 72, n2);
    let b = lerp(5, 21, n);
    stroke(h, s, b, random(3, 7));
    strokeWeight(random(6, 22));
    let a = noise(x * 0.002 + 90, y * 0.002) * TWO_PI * 2;
    let L = random(24, 90);
    line(x, y, x + cos(a) * L, y + sin(a) * L * 0.35);
  }
}

function arrivalThreads() {
  for (let i = 0; i < 96; i++) {
    let a0 = random(TWO_PI);
    let r0 = random(950, 1550);
    let turns = random(0.8, 2.2) * (random() < 0.5 ? -1 : 1);
    let cool = random() < 0.22;
    let hueBase = cool ? random(192, 214) : random(338, 372);
    let steps = 150;
    let px = 0, py = 0;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let ease = t * t * (3 - 2 * t);
      let wob = (noise(i * 3.7, t * 3) - 0.5) * 110 * (1 - ease);
      let r = lerp(r0, 150, ease) + wob;
      let a = a0 + turns * ease * TWO_PI * 0.5;
      let x = CX + cos(a) * r * 0.92;
      let y = CY + sin(a) * r * 1.1;
      if (s > 0) {
        stroke(hueBase % 360, lerp(28, 72, t), lerp(16, 60, t), lerp(1.2, 14, ease));
        strokeWeight(lerp(0.8, 2.6, ease));
        line(px, py, x, y);
      }
      px = x; py = y;
    }
  }
}

function roots() {
  for (let i = 0; i < 14; i++) {
    let x0 = CX + random(-170, 170);
    let y0 = CY + random(130, 230);
    let drift = random(-1, 1);
    let px = x0, py = y0;
    let steps = 80;
    for (let s = 1; s <= steps; s++) {
      let t = s / steps;
      let x = x0 + drift * 130 * t + (noise(i * 9.1, t * 2) - 0.5) * 260 * t;
      let y = lerp(y0, H + 60, pow(t, 0.85));
      stroke(344 + random(-6, 6), 52, lerp(26, 9, t), lerp(26, 5, t));
      strokeWeight(lerp(6.5, 0.8, t));
      line(px, py, x, y);
      px = x; py = y;
      if (random() < 0.06) {
        noStroke();
        fill(26, 85, 72, 18);
        ellipse(x, y, random(3, 7));
      }
    }
  }
}

function glowBase() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 24; i++) {
    let t = i / 23;
    let r = lerp(640, 130, t);
    fill(lerp(345, 30, t), 75, 50, 1.7);
    ellipse(CX + random(-8, 8), CY + random(-8, 8), r * 2, r * 2.1);
  }
  blendMode(BLEND);
}

function weave() {
  let R = 235;
  let loops = TWO_PI * 2.4;
  let steps = 320;
  let strands = [];
  let hues = [349, 36, 9, 353];
  for (let j = 0; j < 26; j++) {
    strands.push({
      f1: 2.0 + (j * 0.618) % 2.4,
      f2: 1.6 + (j * 0.414) % 2.1,
      f3: 2.2 + (j * 0.726) % 1.9,
      p1: random(TWO_PI),
      p2: random(TWO_PI),
      p3: random(TWO_PI),
      hue: hues[j % 4]
    });
  }
  blendMode(ADD);
  for (let sd of strands) {
    let px = 0, py = 0;
    for (let s = 0; s <= steps; s++) {
      let t = (s / steps) * loops;
      let p = knotPoint(sd, t, R);
      let nz = (p.z / R + 1) / 2;
      if (s > 0) {
        stroke(sd.hue, 82, 68, lerp(1.0, 4.5, nz));
        strokeWeight(lerp(3, 9, nz));
        line(px, py, p.x, p.y);
      }
      px = p.x; py = p.y;
    }
  }
  blendMode(BLEND);
  for (let sd of strands) {
    let px = 0, py = 0;
    for (let s = 0; s <= steps; s++) {
      let t = (s / steps) * loops;
      let p = knotPoint(sd, t, R);
      let nz = (p.z / R + 1) / 2;
      if (s > 0) {
        stroke(sd.hue, lerp(70, 55, nz), lerp(30, 90, nz), lerp(16, 62, nz));
        strokeWeight(lerp(0.9, 3.1, nz));
        line(px, py, p.x, p.y);
      }
      px = p.x; py = p.y;
    }
  }
}

function knotPoint(sd, t, R) {
  let x = Math.sin(sd.f1 * t + sd.p1) * R;
  let y = Math.sin(sd.f2 * t + sd.p2) * R;
  let z = Math.sin(sd.f3 * t + sd.p3) * R;
  let rx = -0.5, rz = 0.3;
  let y2 = y * Math.cos(rx) - z * Math.sin(rx);
  let z2 = y * Math.sin(rx) + z * Math.cos(rx);
  let x3 = x * Math.cos(rz) - y2 * Math.sin(rz);
  let y3 = x * Math.sin(rz) + y2 * Math.cos(rz);
  let sc = 1 + (z2 / R) * 0.12;
  return { x: CX + x3 * sc, y: CY + y3 * sc * 1.06, z: z2 };
}

function halo() {
  blendMode(ADD);
  noFill();
  push();
  translate(CX, CY);
  rotate(-0.16);
  for (let i = 0; i < 170; i++) {
    let a = random(TWO_PI);
    let w = random(0.02, 0.1);
    let rr = random(0.97, 1.05);
    stroke(32 + random(-12, 10), 65, 82, random(2.5, 8));
    strokeWeight(random(1.4, 3.4));
    arc(0, 0, 960 * rr, 1150 * rr, a, a + w);
  }
  pop();
  blendMode(BLEND);
}

function core() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 30; i++) {
    let t = i / 29;
    let r = lerp(170, 22, t);
    fill(lerp(16, 44, t), lerp(88, 50, t), lerp(55, 100, t), 4.5);
    ellipse(CX + (noise(i * 0.5) - 0.5) * 14, CY + (noise(i * 0.5 + 40) - 0.5) * 14, r * 2);
  }
  for (let i = 0; i < 10; i++) {
    fill(46, 30, 100, 7);
    ellipse(CX + random(-14, 14), CY + random(-14, 14), random(4, 16));
  }
  blendMode(BLEND);
}

function sparks() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 240; i++) {
    let t = random();
    let spread = lerp(70, 340, pow(t, 1.15));
    let x = CX + (noise(i * 0.37) - 0.5) * 2 * spread;
    let y = lerp(CY - 190, 70, pow(t, 0.95));
    let fade = sin(t * PI);
    let sz = lerp(1.6, 6.5, noise(i * 0.91)) * (0.35 + 0.65 * fade);
    fill(30, 70, 92, 4.5 * fade);
    ellipse(x, y, sz * 4.6);
    fill(43, 45, 100, 24 * fade);
    ellipse(x, y, sz);
  }
  for (let i = 0; i < 90; i++) {
    let a = random(TWO_PI);
    let d = random(280, 590);
    let x = CX + cos(a) * d;
    let y = CY + sin(a) * d * 1.12;
    let s = random(1.4, 3.8);
    fill(12, 60, 85, 6);
    ellipse(x, y, s * 3.4);
    fill(38, 48, 96, 14);
    ellipse(x, y, s);
  }
  blendMode(BLEND);
}

function grain() {
  noStroke();
  for (let i = 0; i < 15000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.5) fill(40, 35, 85, random(1.5, 4));
    else fill(265, 45, 10, random(1.5, 4));
    rect(x, y, random(1, 2.6), random(1, 2.6));
  }
}

function vignette() {
  noFill();
  for (let k = 0; k < 320; k += 6) {
    let a = map(k, 0, 320, 5, 0.2);
    stroke(337, 62, 5, a);
    strokeWeight(7);
    rect(k, k, W - 2 * k, H - 2 * k);
  }
  noStroke();
  let corners = [[0, 0], [W, 0], [0, H], [W, H]];
  for (let c of corners) {
    for (let i = 0; i < 18; i++) {
      fill(338, 60, 5, 1.8);
      ellipse(c[0], c[1], 940 - i * 40, 940 - i * 40);
    }
  }
}

let W = 1600;
let H = 2000;
let A, B, M;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  colorMode(HSB, 360, 100, 100, 100);
  pixelDensity(1);
  noLoop();

  A = { x: 540, y: 680 };
  B = { x: 1110, y: 1360 };
  M = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };

  paint();
}

function paint() {
  backgroundField();
  undercurrents();
  presences();
  threads();
  repairVeins();
  sparks();
  brushGrain();
  finalGlazes();
  vignette();
}

function wrapHue(h) {
  return ((h % 360) + 360) % 360;
}

function glow(x, y, r, h, s, b, a, steps) {
  noStroke();
  h = wrapHue(h);
  for (let i = steps; i >= 1; i--) {
    let t = i / steps;
    let rr = r * t;
    let alpha = a * (1 - t) + a * 0.08;
    fill(h, s, b, alpha);
    ellipse(x, y, rr * 2, rr * 2);
  }
}

function backgroundField() {
  noStroke();
  let c1 = color(262, 86, 7);
  let c2 = color(335, 80, 13);
  let c3 = color(16, 88, 22);

  for (let y = 0; y < H; y += 4) {
    let t = y / H;
    let c;
    if (t < 0.44) c = lerpColor(c1, c2, t / 0.44);
    else c = lerpColor(c2, c3, (t - 0.44) / 0.56);
    fill(c);
    rect(0, y, W, 4);
  }

  blendMode(MULTIPLY);
  for (let i = 0; i < 130; i++) {
    let x = random(W);
    let y = random(H);
    let r = random(120, 560);
    let n = noise(x * 0.0008, y * 0.0008, i * 0.013);
    fill(wrapHue(276 + n * 46), 72, 9 + n * 9, 3.5);
    ellipse(x, y, r * 2, r * 1.28);
  }
  blendMode(BLEND);
}

function undercurrents() {
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 24; i++) {
    let x = random(-220, W + 220);
    let y = random(-220, H + 220);
    let r = random(180, 640);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    scale(random(0.6, 1.7), random(0.35, 0.95));
    fill(wrapHue(random(248, 320)), 74, 11, 4.5);
    ellipse(0, 0, r * 2, r * 2);
    pop();
  }

  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 20; i++) {
    let t = i / 19;
    let x = lerp(-120, W + 120, t) + random(-140, 140);
    let y = lerp(H * 0.08, H * 0.92, t) + random(-180, 180);
    fill(wrapHue(14 + i * 2.2), 82, 27, 3.0);
    ellipse(x, y, random(260, 760), random(110, 380));
  }
  blendMode(BLEND);
}

function presences() {
  blendMode(SCREEN);

  glow(A.x, A.y, 640, 344, 84, 68, 10, 30);
  glow(B.x, B.y, 700, 18, 88, 64, 9, 32);
  glow(M.x, M.y, 430, 40, 90, 74, 6, 26);

  noStroke();
  for (let i = 0; i < 44; i++) {
    let p = i < 22 ? A : B;
    let baseH = i < 22 ? 338 : 18;
    let ang = random(TWO_PI);
    let d = random(60, i < 22 ? 420 : 480);
    let x = p.x + cos(ang) * d;
    let y = p.y + sin(ang) * d * random(0.72, 1.28);
    let n = noise(x * 0.0018, y * 0.0018, i * 0.04);
    fill(wrapHue(baseH + n * 28), 64 + n * 26, 38 + n * 38, 2.4 + n * 4.0);
    ellipse(x, y, random(50, 250), random(36, 190));
  }

  noFill();
  for (let i = 0; i < 8; i++) {
    let r = 120 + i * 64 + random(-18, 18);
    stroke(wrapHue(343 + i * 3), 70, 88, 5);
    strokeWeight(random(1.0, 3.6));
    arc(A.x, A.y, r * 2, r * 2, random(TWO_PI), random(TWO_PI) + random(PI * 0.35, PI * 1.35));
  }

  for (let i = 0; i < 8; i++) {
    let r = 140 + i * 70 + random(-20, 20);
    stroke(wrapHue(15 + i * 3), 74, 86, 5);
    strokeWeight(random(1.0, 3.8));
    arc(B.x, B.y, r * 2, r * 2, random(TWO_PI), random(TWO_PI) + random(PI * 0.35, PI * 1.35));
  }

  blendMode(BLEND);
}

function threads() {
  blendMode(SCREEN);
  noFill();

  for (let i = 0; i < 95; i++) {
    let t = i / 94;
    let sa = random(TWO_PI);
    let ea = random(TWO_PI);

    let sx = A.x + cos(sa) * random(20, 210);
    let sy = A.y + sin(sa) * random(20, 210) * random(0.78, 1.3);
    let ex = B.x + cos(ea) * random(30, 240);
    let ey = B.y + sin(ea) * random(30, 240) * random(0.78, 1.3);

    let mx1 = lerp(sx, ex, 0.3) + random(-235, 235);
    let my1 = lerp(sy, ey, 0.3) + random(-235, 235);
    let mx2 = lerp(sx, ex, 0.7) + random(-235, 235);
    let my2 = lerp(sy, ey, 0.7) + random(-235, 235);

    stroke(wrapHue(336 + t * 80), 54 + t * 32, 90, random(3, 9));
    strokeWeight(random(0.4, 2.2));
    bezier(sx, sy, mx1, my1, mx2, my2, ex, ey);
  }

  for (let i = 0; i < 46; i++) {
    let ang = random(TWO_PI);
    let r1 = random(18, 220);
    let r2 = random(18, 220);
    let x1 = M.x + cos(ang) * r1;
    let y1 = M.y + sin(ang) * r1 * 0.86;
    let x2 = M.x + cos(ang + random(PI * 0.3, PI * 1.2)) * r2;
    let y2 = M.y + sin(ang + random(PI * 0.3, PI * 1.2)) * r2 * 0.86;

    stroke(wrapHue(36 + random(-8, 14)), 64, 96, random(3.5, 8));
    strokeWeight(random(0.4, 1.7));
    line(x1, y1, x2, y2);
  }

  blendMode(BLEND);
}

function repairVeins() {
  blendMode(SCREEN);
  crackLine(W * 0.34, H * 0.96, W * 0.30, H * 0.16, 46, 47);
  crackLine(W * 0.74, H * 0.98, W * 0.63, H * 0.30, 38, 43);
  crackLine(W * 0.52, H * 0.88, M.x, M.y, 26, 50);
  blendMode(BLEND);
}

function crackLine(x0, y0, x1, y1, seg, h) {
  let pts = [];
  for (let i = 0; i <= seg; i++) {
    let t = i / seg;
    let bend = sin(t * PI);
    let x = lerp(x0, x1, t) + random(-72, 72) * bend;
    let y = lerp(y0, y1, t) + random(-26, 26) * bend;
    pts.push({ x: x, y: y });
  }

  noFill();

  stroke(wrapHue(262), 82, 7, 16);
  strokeWeight(10);
  beginShape();
  for (let i = 0; i < pts.length; i++) vertex(pts[i].x, pts[i].y);
  endShape();

  stroke(wrapHue(h), 88, 58, 7);
  strokeWeight(14);
  beginShape();
  for (let i = 0; i < pts.length; i++) vertex(pts[i].x, pts[i].y);
  endShape();

  stroke(wrapHue(h), 96, 94, 20);
  strokeWeight(3.2);
  beginShape();
  for (let i = 0; i < pts.length; i++) vertex(pts[i].x, pts[i].y);
  endShape();

  stroke(wrapHue(52), 100, 100, 32);
  strokeWeight(1.0);
  beginShape();
  for (let i = 0; i < pts.length; i++) vertex(pts[i].x, pts[i].y);
  endShape();

  for (let i = 2; i < pts.length - 2; i += 3) {
    if (random() < 0.62) {
      glow(pts[i].x, pts[i].y, random(8, 26), h, 92, 96, 3, 6);
    }
  }
}

function sparks() {
  blendMode(SCREEN);
  noStroke();

  let foci = [
    A, B, M,
    { x: W * 0.34, y: H * 0.56 },
    { x: W * 0.64, y: H * 0.64 }
  ];
  let palette = [344, 20, 44, 54, 288];

  for (let i = 0; i < 620; i++) {
    let f = foci[floor(random(foci.length))];
    let a = random(TWO_PI);
    let d = random() * random() * 540;
    let x = f.x + cos(a) * d;
    let y = f.y + sin(a) * d * random(0.68, 1.32);
    let h = palette[floor(random(palette.length))];

    fill(wrapHue(h), 72, 96, random(2, 9));
    let s = random(1.2, 4.8);
    ellipse(x, y, s, s);

    if (random() < 0.045) {
      glow(x, y, random(8, 22), h, 85, 95, 2.5, 5);
    }
  }

  blendMode(BLEND);
}

function brushGrain() {
  blendMode(SCREEN);
  for (let i = 0; i < 1100; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.004, y * 0.004, 30);
    let a = n * TWO_PI * 2;
    let l = random(5, 46);
    stroke(wrapHue(36 + n * 30), 38, 88, 2.2);
    strokeWeight(random(0.4, 1.6));
    line(x, y, x + cos(a) * l, y + sin(a) * l);
  }

  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 2200; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.006, y * 0.006, 80);
    if (n > 0.55) fill(45, 30, 88, 1.3);
    else fill(262, 70, 7, 1.7);
    ellipse(x, y, random(0.8, 2.6), random(0.8, 2.6));
  }
  blendMode(BLEND);
}

function finalGlazes() {
  blendMode(SCREEN);
  glow(M.x, M.y, 950, 32, 74, 64, 2.5, 24);
  glow(W * 0.5, H * 0.14, 760, 282, 60, 56, 1.8, 18);

  blendMode(MULTIPLY);
  glow(W * 0.08, H * 0.94, 900, 262, 85, 8, 6, 18);
  glow(W * 0.95, H * 0.30, 860, 342, 80, 8, 5, 18);
  blendMode(BLEND);
}

function vignette() {
  let ctx = drawingContext;
  ctx.save();

  let g = ctx.createRadialGradient(W * 0.52, H * 0.46, H * 0.10, W * 0.50, H * 0.50, H * 0.90);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.70, 'rgba(8,4,12,0.10)');
  g.addColorStop(1, 'rgba(4,2,9,0.56)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  let g2 = ctx.createLinearGradient(0, H * 0.60, 0, H);
  g2.addColorStop(0, 'rgba(12,4,9,0)');
  g2.addColorStop(1, 'rgba(12,5,8,0.32)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, W, H);

  ctx.restore();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  background(15, 15, 26);

  ground();
  undercurrents();

  radialWash(420, 850, 760, color(174, 57, 67), 0.18);
  radialWash(1180, 1110, 760, color(32, 125, 133), 0.17);
  radialWash(800, 1000, 540, color(231, 175, 107), 0.07);

  paintBody(400, 900, 350, 550, 0.8, 0.04, -0.10, true);
  paintBody(1200, 1090, 350, 540, 2.4, -0.04, 0.11, false);

  weave();
  openPaths();
  pigment();
  surface();
}

function ground() {
  let top = color(26, 14, 33);
  let bottom = color(6, 27, 37);

  for (let y = 0; y < height; y += 4) {
    let c = lerpColor(top, bottom, y / height);
    let n = noise(y * 0.004, 3.7) * 5;
    stroke(red(c) + n, green(c) + n * 0.65, blue(c) + n);
    strokeWeight(5);
    line(0, y, width, y);
  }

  noFill();
  for (let i = 0; i < 90; i++) {
    let x = random(-260, 1500);
    let y = random(180, 1840);
    let reach = random(180, 720);

    if (i % 2 === 0) {
      stroke(177, 72, 76, random(3, 10));
    } else {
      stroke(52, 132, 137, random(3, 10));
    }

    strokeWeight(random(8, 58));
    bezier(
      x, y,
      x + reach * 0.25, y + random(-240, 240),
      x + reach * 0.7, y + random(-280, 280),
      x + reach, y + random(-180, 180)
    );
  }
}

function undercurrents() {
  noFill();

  for (let i = 0; i < 46; i++) {
    let warm = i % 2 === 0;
    let x = random(100, 1500);
    let y = random(350, 1660);
    let span = random(240, 700);

    if (warm) {
      stroke(218, 117, 91, random(4, 13));
    } else {
      stroke(104, 174, 158, random(4, 13));
    }

    strokeWeight(random(0.7, 2.4));
    bezier(
      x - span * 0.5, y + random(-80, 80),
      x - span * 0.1, y - random(120, 360),
      x + span * 0.2, y + random(120, 360),
      x + span * 0.5, y + random(-80, 80)
    );
  }
}

function radialWash(x, y, r, c, a) {
  let ctx = drawingContext;
  let rgb = `${red(c)},${green(c)},${blue(c)}`;
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);

  g.addColorStop(0, `rgba(${rgb},${a})`);
  g.addColorStop(0.42, `rgba(${rgb},${a * 0.48})`);
  g.addColorStop(1, `rgba(${rgb},0)`);

  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function blobPoints(cx, cy, rx, ry, phase, skew, tilt) {
  let pts = [];

  for (let i = 0; i < 240; i++) {
    let a = TWO_PI * i / 240;
    let n = noise(
      phase + 4 + cos(a) * 1.6,
      phase + 7 + sin(a) * 1.6
    );

    let r = 0.96
      + 0.07 * sin(3 * a + phase)
      + 0.045 * sin(5 * a - phase)
      + 0.12 * (n - 0.5);

    let xx = rx * cos(a) * r;
    let yy = ry * sin(a) * r;
    xx += skew * yy;

    let x = cx + xx * cos(tilt) - yy * sin(tilt);
    let y = cy + xx * sin(tilt) + yy * cos(tilt);
    y += 20 * sin(2 * a + phase);

    pts.push({ x, y });
  }

  return pts;
}

function paintBody(cx, cy, rx, ry, phase, skew, tilt, warm) {
  let pts = blobPoints(cx, cy, rx, ry, phase, skew, tilt);
  let ctx = drawingContext;

  ctx.save();
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);

  for (let i = 1; i < pts.length; i++) {
    ctx.lineTo(pts[i].x, pts[i].y);
  }

  ctx.closePath();
  ctx.clip();

  let fx = cx + (warm ? 110 : -110);
  let fy = cy + (warm ? -35 : 35);
  let g = ctx.createRadialGradient(fx, fy, 12, cx, cy, ry * 1.22);

  if (warm) {
    g.addColorStop(0, "#f2c47f");
    g.addColorStop(0.22, "#d66b59");
    g.addColorStop(0.52, "#913347");
    g.addColorStop(0.78, "#501d3c");
    g.addColorStop(1, "#24152e");
  } else {
    g.addColorStop(0, "#a8d4b5");
    g.addColorStop(0.22, "#4ca89d");
    g.addColorStop(0.50, "#227382");
    g.addColorStop(0.78, "#173d62");
    g.addColorStop(1, "#111b35");
  }

  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  let shade = ctx.createLinearGradient(
    cx - rx, cy - ry,
    cx + rx, cy + ry
  );
  shade.addColorStop(0, "rgba(255,240,215,0.07)");
  shade.addColorStop(0.45, "rgba(255,255,255,0)");
  shade.addColorStop(1, "rgba(0,5,20,0.24)");
  ctx.fillStyle = shade;
  ctx.fillRect(0, 0, width, height);

  let pal = warm ? [
    color(244, 187, 112),
    color(228, 118, 82),
    color(176, 60, 67),
    color(111, 35, 59),
    color(250, 210, 148),
    color(75, 25, 49)
  ] : [
    color(160, 211, 180),
    color(83, 166, 157),
    color(36, 119, 132),
    color(27, 69, 102),
    color(194, 220, 187),
    color(18, 36, 65)
  ];

  noFill();

  for (let i = 0; i < 100; i++) {
    let x = random(cx - rx * 1.2, cx + rx * 1.2);
    let y = random(cy - ry, cy + ry);
    let c = random(pal);
    let direction = warm ? -1 : 1;

    stroke(red(c), green(c), blue(c), random(4, 13));
    strokeWeight(random(18, 68));

    bezier(
      x, y,
      x + random(-160, 160), y + direction * random(50, 160),
      x + random(-180, 180), y + direction * random(170, 330),
      x + random(-150, 150), y + direction * random(300, 480)
    );
  }

  for (let i = 0; i < 760; i++) {
    let x = random(cx - rx * 1.3, cx + rx * 1.3);
    let y = random(cy - ry * 1.18, cy + ry * 1.18);
    let c = random(pal);
    let broad = i % 13 === 0;
    let alpha = broad ? random(5, 14) : random(10, 42);
    let steps = floor(random(12, 23));
    let speed = random(5, 10);

    stroke(red(c), green(c), blue(c), alpha);
    strokeWeight(broad ? random(8, 20) : random(0.7, 5.5));

    beginShape();

    for (let j = 0; j < steps; j++) {
      vertex(x, y);

      let angle = atan2(y - cy, x - cx)
        + (warm ? 1.05 : -1.05)
        + 1.5 * (noise(x * 0.003 + phase, y * 0.003) - 0.5);

      x += cos(angle) * speed;
      y += sin(angle) * speed;
    }

    endShape();
  }

  for (let i = 0; i < 190; i++) {
    let x = random(cx - rx, cx + rx);
    let y = random(cy - ry, cy + ry);
    let c = random(pal);

    stroke(red(c), green(c), blue(c), random(10, 34));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(-22, 22), y + random(8, 58));
  }

  ctx.restore();

  let rim = warm ? color(244, 165, 105) : color(133, 197, 177);
  let weights = [24, 10, 2];
  let alphas = [5, 9, 24];

  noFill();
  for (let k = 0; k < 3; k++) {
    stroke(red(rim), green(rim), blue(rim), alphas[k]);
    strokeWeight(weights[k]);
    beginShape();
    for (let p of pts) {
      vertex(p.x, p.y);
    }
    endShape(CLOSE);
  }
}

function weave() {
  radialWash(805, 1000, 480, color(238, 186, 116), 0.13);

  noFill();

  for (let i = 0; i < 11; i++) {
    let y = random(610, 1390);
    let warm = i % 2 === 0;

    if (warm) {
      stroke(237, 155, 105, 8);
    } else {
      stroke(132, 197, 172, 8);
    }

    strokeWeight(random(18, 48));
    bezier(
      random(650, 760), y,
      random(710, 920), y + random(-280, 280),
      random(720, 940), y + random(-280, 280),
      random(870, 1010), y + random(-170, 170)
    );
  }

  for (let i = 0; i < 124; i++) {
    let u = i / 123;
    let y0 = 560 + u * 850 + random(-85, 85);
    let y3 = 690 + u * 810 + random(-85, 85);
    let x0 = 730 + 52 * sin(u * PI * 1.4) + random(-34, 34);
    let x3 = 875 + 45 * cos(u * PI * 1.2) + random(-34, 34);

    let x1 = random(745, 945);
    let y1 = y0 + random(-260, 260);
    let x2 = random(700, 950);
    let y2 = y3 + random(-260, 260);

    let ca, cb;

    if (i % 4 === 0) {
      ca = color(244, 188, 112);
      cb = color(196, 211, 158);
    } else {
      ca = color(226, 108, 84);
      cb = color(85, 167, 158);
    }

    if (i % 9 === 0) {
      ca = color(247, 220, 165);
    }

    let start = i % 7 === 0 ? random(0.03, 0.19) : 0;
    let end = i % 6 === 0 ? random(0.68, 0.92) : 1;
    let alpha = random(28, 96);
    let weight = i % 13 === 0 ? random(2.2, 3.4) : random(0.55, 1.8);
    let steps = 46;

    for (let j = 0; j < steps; j++) {
      if (random() < 0.025) continue;

      let t0 = start + (end - start) * j / steps;
      let t1 = start + (end - start) * (j + 1) / steps;
      let tm = (t0 + t1) * 0.5;

      let ax = bezierPoint(x0, x1, x2, x3, t0);
      let ay = bezierPoint(y0, y1, y2, y3, t0);
      let bx = bezierPoint(x0, x1, x2, x3, t1);
      let by = bezierPoint(y0, y1, y2, y3, t1);

      let c = lerpColor(ca, cb, tm);
      let fade = 0.4 + 0.6 * sin(PI * tm);

      stroke(red(c), green(c), blue(c), alpha * fade);
      strokeWeight(weight * (0.65 + 0.5 * sin(PI * tm)));
      line(ax, ay, bx, by);
    }
  }

  radialWash(805, 1005, 390, color(238, 190, 124), 0.055);
}

function openPath(cx, cy, rx, ry, rot, a0, span, c, alpha, weight) {
  noFill();
  stroke(red(c), green(c), blue(c), alpha);
  strokeWeight(weight);
  beginShape();

  for (let i = 0; i <= 90; i++) {
    let a = a0 + span * i / 90;
    let xx = rx * cos(a);
    let yy = ry * sin(a);
    let x = cx + xx * cos(rot) - yy * sin(rot);
    let y = cy + xx * sin(rot) + yy * cos(rot);
    vertex(x, y);
  }

  endShape();
}

