function paint() {
  const top = color(13, 17, 33);
  const bottom = color(39, 21, 35);

  for (let y = 0; y < height; y += 3) {
    const t = y / height;
    let c = lerpColor(top, bottom, t);
    c = lerpColor(c, color(34, 36, 51), noise(y * 0.002, 8) * 0.16);
    stroke(c);
    strokeWeight(3);
    line(0, y, width, y);
  }

  for (let i = 0; i < 12000; i++) {
    const x = random(width);
    const y = random(height);
    const pale = random() < 0.52;
    stroke(
      pale ? 225 : 3,
      pale ? 211 : 5,
      pale ? 194 : 15,
      random(2, 8)
    );
    strokeWeight(random(0.4, 1.3));
    line(x, y, x + random(-1.5, 1.5), y + random(2, 13));
  }

  noStroke();
  halo(320, 970, 760, 1160, color(119, 42, 65), 120, 0.8);
  halo(1320, 930, 730, 1120, color(22, 91, 111), 120, 0.8);
  halo(820, 1000, 355, 610, color(225, 170, 111), 150, 0.9);

  for (const side of [-1, 1]) {
    noFill();
    for (let i = 0; i < 48; i++) {
      const q = random(0.02, 1);
      const c = pigment(side, q, random());
      stroke(red(c), green(c), blue(c), 8 + q * 9);
      strokeWeight(random(28, 108));
      traceField(side, q, 0, 1, 76);
    }

    noStroke();
    for (let i = 0; i < 112; i++) {
      const q0 = i / 112;
      const q1 = Math.min(1.025, (i + 1.35) / 112);
      const qm = (q0 + q1) * 0.5;
      const c = pigment(side, qm, 0.45);
      fill(red(c), green(c), blue(c), 43 + 24 * qm + random(-7, 7));

      beginShape();
      for (let j = 0; j <= 90; j++) {
        const p = fieldPoint(side, q0, j / 90);
        vertex(p.x, p.y);
      }
      for (let j = 90; j >= 0; j--) {
        const p = fieldPoint(side, q1, j / 90);
        vertex(p.x, p.y);
      }
      endShape(CLOSE);
    }

    noFill();
    for (let i = 0; i < 255; i++) {
      const q = 1 - Math.pow(random(), 1.75) * 0.98;
      let c = pigment(side, q, random());
      c = lerpColor(c, color(244, 220, 178), Math.pow(q, 6) * 0.43);
      stroke(red(c), green(c), blue(c), 11 + 33 * q + random(0, 12));
      strokeWeight(random() < 0.06 ? random(5, 11) : random(0.6, 3.1));

      let t0 = 0;
      let t1 = 1;
      if (random() < 0.22) {
        t0 = random(0, 0.4);
        t1 = random(0.65, 1);
      }
      traceField(side, q, t0, t1, 76);
    }

    for (let i = 0; i < 34; i++) {
      const q = random(0.955, 1.015);
      const c = side < 0
        ? color(246, 186, 131)
        : color(172, 220, 193);
      stroke(red(c), green(c), blue(c), random(24, 67));
      strokeWeight(random(0.55, 1.8));
      traceField(side, q, random(0, 0.05), random(0.95, 1), 90);
    }

    for (let i = 0; i < 850; i++) {
      const q = random();
      const t = random(0.02, 0.97);
      const a = fieldPoint(side, q, t);
      const b = fieldPoint(
        side,
        q + random(-0.004, 0.004),
        t + random(0.003, 0.017)
      );
      const c = pigment(side, q, t);
      stroke(red(c), green(c), blue(c), random(8, 37));
      strokeWeight(random(0.45, 2.2));
      line(a.x, a.y, b.x, b.y);
    }
  }

  blendMode(SCREEN);
  halo(830, 1015, 235, 350, color(224, 174, 120), 90, 0.48);

  noFill();
  for (let i = 0; i < 46; i++) {
    const t = random(0.31, 0.69);
    const a = fieldPoint(-1, random(0.93, 1.01), t);
    const d = fieldPoint(
      1,
      random(0.93, 1.01),
      t + random(-0.025, 0.025)
    );
    const bow = random(-150, 150);
    const b = {
      x: lerp(a.x, d.x, 0.33),
      y: a.y + bow
    };
    const c = {
      x: lerp(a.x, d.x, 0.67),
      y: d.y - bow * 0.62
    };

    let u0 = random() < 0.45 ? random(0, 0.16) : 0;
    let u1 = random() < 0.45 ? random(0.74, 1) : 1;
    if (u1 <= u0) u1 = 1;

    const tint = lerpColor(
      color(244, 184, 133),
      color(177, 222, 198),
      random()
    );
    stroke(red(tint), green(tint), blue(tint), random(12, 39));
    strokeWeight(random(0.55, 1.8));

    beginShape();
    for (let j = 0; j <= 56; j++) {
      const u = lerp(u0, u1, j / 56);
      const p = cubicPoint(a, b, c, d, u);
      vertex(p.x, p.y);
    }
    endShape();
  }

  noStroke();
  for (let i = 0; i < 360; i++) {
    const side = random() < 0.5 ? -1 : 1;
    const t = random(0.1, 0.9);
    const p = fieldPoint(side, random(0.85, 1.02), t);
    const drift = Math.pow(random(), 2) * 155;
    const x = p.x - side * drift + randomGaussian(0, 8);
    const y = p.y + randomGaussian(0, 24);
    const c = random() < 0.35
      ? color(244, 213, 158)
      : side < 0
        ? color(237, 143, 111)
        : color(135, 207, 190);
    const r = random(0.7, 3.8);

    fill(red(c), green(c), blue(c), random(20, 105));
    ellipse(x, y, r * 2, r * 2);

    if (random() < 0.1) {
      fill(red(c), green(c), blue(c), 9);
      ellipse(x, y, r * 7, r * 7);
    }
  }

  for (let i = 0; i < 58; i++) {
    const x = 830 + randomGaussian(0, 72);
    const y = 1010 + randomGaussian(0, 205);
    fill(245, 216, 165, random(12, 52));
    const r = random(0.6, 2.3);
    ellipse(x, y, r * 2, r * 2);
  }

  blendMode(BLEND);
  noFill();
  for (let i = 0; i < 82; i++) {
    const d = i * 2.55;
    stroke(6, 8, 18, 1.9);
    strokeWeight(5.5);
    rect(d, d, width - 2 * d, height - 2 * d);
  }

  for (let i = 0; i < 9500; i++) {
    const x = random(width);
    const y = random(height);
    const pale = random() < 0.55;
    stroke(
      pale ? 241 : 0,
      pale ? 222 : 0,
      pale ? 192 : 0,
      random(2, 9)
    );
    strokeWeight(random(0.35, 1.15));
    line(x, y, x + random(-1.4, 1.4), y + random(0.5, 4));
  }
}

function fieldPoint(side, q, t) {
  const approach = Math.exp(-Math.pow((t - 0.51) / 0.19, 2));
  const spine =
    390 +
    140 * Math.sin(Math.PI * (1.25 * t - 0.15)) +
    180 * approach;
  const spread = 430 + 80 * Math.sin(Math.PI * t);
  const offset = (q - 0.88) * spread;
  const seedOffset = side < 0 ? 0 : 31.7;
  const grain =
    (noise(q * 3.2 + seedOffset, t * 4.5) - 0.5) * 54;

  let x =
    spine +
    offset +
    18 * Math.sin(t * 10 + q * 6) +
    grain;
  let y =
    -140 +
    2280 * t +
    24 * Math.sin(q * 5.2 + t * 4.5);

  if (side > 0) {
    x =
      width -
      x +
      72 * Math.sin(Math.PI * t) -
      34 * Math.sin(TWO_PI * t + q * 2);
    y += 46 * Math.sin(q * 3.1 + t * 3.7) + 38 * (t - 0.5);
  }

  return { x, y };
}

function pigment(side, q, t) {
  q = constrain(q, 0, 1);
  let c;

  if (side < 0) {
    const deep = color(40, 25, 55);
    const middle = color(128, 43, 67);
    const near = color(220, 100, 78);
    const edge = color(244, 177, 119);

    if (q < 0.52) {
      c = lerpColor(deep, middle, q / 0.52);
    } else if (q < 0.86) {
      c = lerpColor(middle, near, (q - 0.52) / 0.34);
    } else {
      c = lerpColor(near, edge, (q - 0.86) / 0.14);
    }
  } else {
    const deep = color(17, 34, 61);
    const middle = color(24, 80, 105);
    const near = color(43, 143, 143);
    const edge = color(151, 202, 177);

    if (q < 0.52) {
      c = lerpColor(deep, middle, q / 0.52);
    } else if (q < 0.86) {
      c = lerpColor(middle, near, (q - 0.52) / 0.34);
    } else {
      c = lerpColor(near, edge, (q - 0.86) / 0.14);
    }
  }

  const n = noise(q * 5 + t * 2, side < 0 ? 3 : 17);
  if (n > 0.52) {
    c = lerpColor(c, color(242, 215, 178), (n - 0.52) * 0.18);
  } else {
    c = lerpColor(c, color(10, 14, 28), (0.52 - n) * 0.2);
  }
  return c;
}

function traceField(side, q, t0, t1, steps) {
  beginShape();
  for (let i = 0; i <= steps; i++) {
    const p = fieldPoint(side, q, lerp(t0, t1, i / steps));
    vertex(p.x, p.y);
  }
  endShape();
}

function halo(x, y, rx, ry, c, steps, alpha) {
  noStroke();
  for (let i = steps; i >= 1; i--) {
    const r = i / steps;
    fill(red(c), green(c), blue(c), alpha);
    ellipse(x, y, rx * 2 * r, ry * 2 * r);
  }
}

function cubicPoint(a, b, c, d, u) {
  const v = 1 - u;
  return {
    x:
      v * v * v * a.x +
      3 * v * v * u * b.x +
      3 * v * u * u * c.x +
      u * u * u * d.x,
    y:
      v * v * v * a.y +
      3 * v * v * u * b.y +
      3 * v * u * u * c.y +
      u * u * u * d.y
  };
}

