function paintGround() {
  const top = color(240, 232, 215);
  const bottom = color(211, 196, 172);

  strokeWeight(4);
  for (let y = 0; y < height; y += 3) {
    const t = pow(y / height, 1.15);
    stroke(lerpColor(top, bottom, t));
    line(0, y, width, y + 3);
  }

  radialWash(80, 1080, 760, [
    [0, "rgba(42,82,85,0.10)"],
    [1, "rgba(42,82,85,0)"]
  ]);
  radialWash(1530, 930, 760, [
    [0, "rgba(157,74,54,0.09)"],
    [1, "rgba(157,74,54,0)"]
  ]);
  radialWash(770, 120, 630, [
    [0, "rgba(255,252,239,0.50)"],
    [1, "rgba(255,252,239,0)"]
  ]);

  noStroke();
  for (let i = 0; i < 55; i++) {
    fill(108, 87, 66, random(2, 6));
    ellipse(
      random(width),
      random(height),
      random(90, 520),
      random(70, 430)
    );
  }

  for (let i = 0; i < 11000; i++) {
    const x = random(width);
    const y = random(height);
    const len = random(2, 22);
    if (random() < 0.52) {
      stroke(255, 250, 236, random(3, 10));
    } else {
      stroke(76, 61, 48, random(2, 7));
    }
    strokeWeight(random(0.35, 1.15));
    if (random() < 0.78) {
      line(x, y, x + len, y + random(-0.7, 0.7));
    } else {
      line(x, y, x + random(-0.5, 0.5), y + len);
    }
  }
}

function coolPath() {
  const p = new Path2D();
  p.moveTo(250, 1840);
  p.bezierCurveTo(110, 1640, 100, 1390, 170, 1160);
  p.bezierCurveTo(240, 930, 300, 770, 430, 610);
  p.bezierCurveTo(540, 480, 650, 330, 770, 340);
  p.bezierCurveTo(860, 350, 820, 480, 760, 610);
  p.bezierCurveTo(690, 760, 745, 900, 690, 1060);
  p.bezierCurveTo(640, 1210, 730, 1330, 650, 1490);
  p.bezierCurveTo(600, 1610, 700, 1740, 610, 1860);
  p.bezierCurveTo(480, 1910, 360, 1900, 250, 1840);
  p.closePath();
  return p;
}

function warmPath() {
  const p = new Path2D();
  p.moveTo(950, 1850);
  p.bezierCurveTo(870, 1680, 1000, 1550, 930, 1380);
  p.bezierCurveTo(860, 1210, 960, 1100, 900, 940);
  p.bezierCurveTo(850, 780, 950, 680, 900, 540);
  p.bezierCurveTo(875, 460, 835, 390, 900, 350);
  p.bezierCurveTo(1060, 300, 1210, 470, 1310, 650);
  p.bezierCurveTo(1440, 870, 1500, 1090, 1430, 1300);
  p.bezierCurveTo(1360, 1510, 1500, 1680, 1360, 1850);
  p.bezierCurveTo(1210, 1930, 1080, 1910, 950, 1850);
  p.closePath();
  return p;
}

function paintBody(path, box, baseStops, palette, side) {
  const ctx = drawingContext;
  ctx.save();

  const base = ctx.createLinearGradient(
    0, box.y, 0, box.y + box.h
  );
  for (const s of baseStops) base.addColorStop(s[0], s[1]);
  ctx.fillStyle = base;
  ctx.fill(path);
  ctx.clip(path);

  for (let i = 0; i < 520; i++) {
    const x = random(box.x, box.x + box.w);
    const y = random(box.y, box.y + box.h);
    const c = color(pickPigment(palette, x, y, side));
    c.setAlpha(random(5, 23));

    push();
    translate(x, y);
    rotate(random(-0.42, 0.42));
    noStroke();
    fill(c);
    ellipse(0, 0, random(55, 285), random(35, 250));
    pop();
  }

  for (let i = 0; i < 230; i++) {
    const x = random(box.x, box.x + box.w);
    const y = random(box.y, box.y + box.h);
    const len = random(110, 490);
    const drift = (side === 0 ? 1 : -1) * random(25, 145);
    const c = color(pickPigment(palette, x, y, side));
    c.setAlpha(random(10, 43));

    noFill();
    stroke(c);
    strokeWeight(random(2, 19));
    bezier(
      x, y,
      x + drift * 0.15, y - len * 0.30,
      x - drift * 0.65, y - len * 0.68,
      x + drift, y - len
    );
  }

  for (let i = 0; i < 7600; i++) {
    const x = random(box.x, box.x + box.w);
    const y = random(box.y, box.y + box.h);
    const n = noise(x * 0.003, y * 0.003, side * 5.7);
    const len = random(4, 58) * (0.55 + n);
    const lean = side === 0 ? 0.28 : -0.28;
    const a = -HALF_PI + lean
      + 0.32 * sin(y * 0.004 + side)
      + random(-0.30, 0.30);
    const c = color(pickPigment(palette, x, y, side));
    c.setAlpha(random(12, 57));

    stroke(c);
    strokeWeight(random(0.55, 4.6));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }

  const innerLight = ctx.createRadialGradient(
    825, 545, 10, 825, 545, 790
  );
  innerLight.addColorStop(0, "rgba(255,229,166,0.22)");
  innerLight.addColorStop(0.42, "rgba(238,208,147,0.07)");
  innerLight.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = innerLight;
  ctx.fillRect(box.x, box.y, box.w, box.h);

  ctx.restore();
}

function pickPigment(palette, x, y, side) {
  const n = noise(x * 0.0022, y * 0.0022, side * 7.3) * 0.72
    + random() * 0.28;
  return palette[min(palette.length - 1, floor(n * palette.length))];
}

function bleed(path, rgb) {
  const ctx = drawingContext;
  ctx.save();
  for (let i = 0; i < 7; i++) {
    ctx.save();
    ctx.translate(random(-5, 5), random(-5, 5));
    ctx.strokeStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0.018)`;
    ctx.lineWidth = 26 + i * 11;
    ctx.stroke(path);
    ctx.restore();
  }
  ctx.restore();
}

function edge(path, rgb) {
  const ctx = drawingContext;
  ctx.save();
  for (let i = 0; i < 6; i++) {
    ctx.save();
    ctx.translate(random(-2.4, 2.4), random(-2.4, 2.4));
    ctx.lineWidth = max(0.7, 15 - i * 2.5);
    ctx.strokeStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.022 + i * 0.009})`;
    ctx.stroke(path);
    ctx.restore();
  }
  ctx.restore();
}

function gapAt(y) {
  const t = constrain((y - 380) / 1400, 0, 1);
  return {
    l: 790 - 165 * t + 22 * sin(y * 0.006),
    r: 880 + 125 * t + 24 * sin(y * 0.005 + 1.3)
  };
}

function exchange() {
  for (let i = 0; i < 260; i++) {
    const y = random(410, 1640);
    const g = gapAt(y);
    const left = random() < 0.5;
    const depth = random(3, 64);
    const x = left ? g.l - depth : g.r + depth;

    push();
    translate(x, y);
    rotate(random(-0.35, 0.35));
    noStroke();
    if (left) {
      fill(215, 119, 79, random(20, 88));
    } else {
      fill(69, 130, 130, random(20, 88));
    }
    ellipse(0, 0, random(1.2, 7), random(4, 24));
    pop();
  }

  for (let i = 0; i < 90; i++) {
    const y = random(400, 1510);
    const g = gapAt(y);
    const left = random() < 0.5;
    const x = left ? g.l - random(0, 15) : g.r + random(0, 15);
    stroke(239, 204, 135, random(18, 65));
    strokeWeight(random(0.5, 1.8));
    line(x, y, x + random(-3, 3), y - random(5, 23));
  }
}

function offerings() {
  for (let i = 0; i < 74; i++) {
    const y = random(405, 1510);
    const g = gapAt(y);
    const distance = g.r - g.l;
    const left = random() < 0.5;
    const reach = distance * random(0.18, 0.59);
    const rise = random(-95, 95);
    let p0, p1, p2, p3;

    if (left) {
      p0 = { x: g.l - random(5, 35), y };
      p3 = { x: g.l + reach, y: y + rise };
      p1 = {
        x: g.l + reach * 0.12,
        y: y - random(15, 75)
      };
      p2 = {
        x: g.l + reach * 0.72,
        y: y + rise + random(-55, 55)
      };
    } else {
      p0 = { x: g.r + random(5, 35), y };
      p3 = { x: g.r - reach, y: y + rise };
      p1 = {
        x: g.r - reach * 0.12,
        y: y - random(15, 75)
      };
      p2 = {
        x: g.r - reach * 0.72,
        y: y + rise + random(-55, 55)
      };
    }

    const rgb = random() < 0.76
      ? [211, 166, 84]
      : [255, 239, 190];
    fadeCurve(
      p0, p1, p2, p3, rgb,
      random(35, 105),
      random(0.45, 1.55)
    );
  }

  for (let i = 0; i < 620; i++) {
    const y = 390 + pow(random(), 1.55) * 1240;
    const g = gapAt(y);
    const distance = g.r - g.l;
    if (distance < 30) continue;

    const x = random(g.l + 5, g.r - 5);
    const middle = (g.l + g.r) * 0.5;
    const centrality = 1 - abs(x - middle) / (distance * 0.5);
    if (random() > 0.25 + centrality * 0.75) continue;

    const fade = map(y, 390, 1630, 1, 0.22);
    const rr = random(0.55, 2.8);

    noStroke();
    if (random() < 0.055) {
      fill(255, 232, 164, 13 * fade);
      ellipse(x, y, rr * 9, rr * 9);
    }
    fill(
      random() < 0.25 ? 255 : 218,
      random() < 0.25 ? 241 : 174,
      random() < 0.25 ? 197 : 88,
      random(25, 145) * fade
    );
    ellipse(x, y, rr * 2, rr * random(1.4, 3));
  }

  for (let i = 0; i < 80; i++) {
    const y = random(220, 450);
    const spread = map(y, 220, 450, 125, 52);
    const x = 825 + random(-spread, spread);
    const rr = random(0.5, 2.1);
    noStroke();
    fill(202, 158, 80, random(15, 75));
    ellipse(x, y, rr * 2, rr * 2);
  }
}

function fadeCurve(p0, p1, p2, p3, rgb, alpha, weight) {
  let previous = p0;

  for (let j = 1; j <= 36; j++) {
    const t = j / 36;
    const u = 1 - t;
    const q = {
      x: u * u * u * p0.x
        + 3 * u * u * t * p1.x
        + 3 * u * t * t * p2.x
        + t * t * t * p3.x,
      y: u * u * u * p0.y
        + 3 * u * u * t * p1.y
        + 3 * u * t * t * p2.y
        + t * t * t * p3.y
    };
    const envelope = pow(sin(PI * t), 0.75);

    stroke(
      rgb[0], rgb[1], rgb[2],
      alpha * envelope
    );
    strokeWeight(weight * (0.55 + 0.45 * envelope));
    line(previous.x, previous.y, q.x, q.y);
    previous = q;
  }
}

function radialWash(x, y, r, stops) {
  const ctx = drawingContext;
  ctx.save();
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
  ctx.restore();
}

function patina() {
  for (let i = 0; i < 17000; i++) {
    const x = random(width);
    const y = random(height);
    const pale = random() < 0.56;

    if (pale) {
      stroke(255, 247, 225, random(2, 9));
    } else {
      stroke(47, 39, 34, random(2, 8));
    }

    strokeWeight(random(0.35, 1.1));
    const len = random(1, 8);
    line(x, y, x + len, y + random(-0.55, 0.55));
  }

  for (let i = 0; i < 950; i++) {
    const x = random(width);
    const y = random(height);
    stroke(239, 224, 194, random(2, 7));
    strokeWeight(random(0.4, 1));
    line(x, y, x + random(-1, 1), y + random(8, 65));
  }

  const ctx = drawingContext;
  ctx.save();
  const vignette = ctx.createRadialGradient(
    800, 900, 380, 800, 900, 1320
  );
  vignette.addColorStop(0, "rgba(47,35,30,0)");
  vignette.addColorStop(0.62, "rgba(47,35,30,0.015)");
  vignette.addColorStop(1, "rgba(47,35,30,0.20)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);

  paintGround();
  veil(-1);
  veil(1);
  luminousInterval();
  crossings();
  driftingPigment();
  vignette();
  surfaceGrain();
}

function paintGround() {
  const top = color(22, 13, 29);
  const middle = color(13, 17, 32);
  const bottom = color(7, 20, 28);

  for (let y = 0; y < height; y += 4) {
    const t = y / (height - 1);
    const c = t < 0.55
      ? lerpColor(top, middle, t / 0.55)
      : lerpColor(middle, bottom, (t - 0.55) / 0.45);
    noStroke();
    fill(c);
    rect(0, y, width, 5);
  }

  blendMode(SCREEN);
  const stains = [
    color(93, 29, 57),
    color(30, 57, 82),
    color(92, 52, 61),
    color(26, 67, 70)
  ];

  for (let i = 0; i < 26; i++) {
    glow(
      random(-160, width + 160),
      random(-100, height + 100),
      random(180, 480),
      random(240, 660),
      stains[i % stains.length],
      random(0.35, 1.1),
      32
    );
  }

  blendMode(BLEND);
  const dryColors = [
    color(101, 58, 80),
    color(39, 67, 85),
    color(159, 107, 92)
  ];

  for (let i = 0; i < 1700; i++) {
    const x = random(width);
    const y = random(height);
    const c = random(dryColors);
    stroke(red(c), green(c), blue(c), random(2, 7));
    strokeWeight(random(0.5, 4));
    line(
      x,
      y,
      x + random(-8, 8),
      y + random(8, 65)
    );
  }
}

function glow(x, y, rx, ry, c, a, steps) {
  noStroke();
  for (let i = steps; i > 0; i--) {
    const t = i / steps;
    const alpha = a * (0.06 + 0.94 * pow(1 - t, 1.5));
    fill(red(c), green(c), blue(c), alpha);
    ellipse(x, y, 2 * rx * t, 2 * ry * t);
  }
}

function contour(cx, cy, rx, ry, phase, s, rough, bend) {
  const n = 96;
  const tilt = bend * 0.045;

  beginShape();
  for (let j = -2; j < n + 2; j++) {
    const k = (j + n) % n;
    const a = k / n * TWO_PI;
    const w = 1 + rough * (
      0.045 * sin(3 * a + phase) +
      0.027 * sin(5 * a - phase * 0.6) +
      0.018 * cos(2 * a + phase * 0.4)
    );

    let xx = rx * s * cos(a) * w;
    const yy = ry * s * sin(a) * (
      1 + rough * 0.028 * sin(4 * a - phase)
    );

    xx -= bend * 82 * (yy / (ry * s));

    const x = xx * cos(tilt) - yy * sin(tilt);
    const y = xx * sin(tilt) + yy * cos(tilt);
    curveVertex(cx + x, cy + y);
  }
  endShape(CLOSE);
}

function veil(side) {
  const left = side < 0;
  const cx = left ? 490 : 1110;
  const cy = left ? 990 : 1030;
  const rx = left ? 525 : 500;
  const ry = left ? 825 : 790;
  const bend = left ? 1 : -1;
  const phase = left ? 0.7 : 2.4;

  const outer = left ? color(86, 20, 54) : color(15, 35, 72);
  const inner = left ? color(221, 76, 79) : color(61, 121, 151);
  const light = left ? color(255, 167, 123) : color(155, 190, 187);
  const deep = left ? color(102, 29, 65) : color(28, 48, 99);

  blendMode(SCREEN);

  for (let i = 0; i < 60; i++) {
    const t = i / 59;
    const c = lerpColor(outer, inner, pow(t, 0.72));
    noStroke();
    fill(red(c), green(c), blue(c), 2.5 + 3.8 * t);
    contour(
      cx + bend * 38 * t,
      cy + (left ? -1 : 1) * 30 * sin(t * PI),
      rx,
      ry,
      phase + t * 0.7,
      1.04 - 0.55 * t,
      1,
      bend
    );
  }

  glow(
    cx + bend * 40,
    cy,
    rx * 0.66,
    ry * 0.82,
    inner,
    1.7,
    46
  );

  for (let i = 0; i < 42; i++) {
    const t = i / 41;
    const c = lerpColor(inner, light, random(0, 0.55));
    noFill();
    stroke(
      red(c),
      green(c),
      blue(c),
      random(4, 17) * (0.55 + 0.45 * t)
    );
    strokeWeight(random(0.45, 1.4));
    contour(
      cx + bend * random(-18, 18),
      cy + random(-20, 20),
      rx,
      ry,
      phase + random(-0.16, 0.16),
      0.30 + 0.72 * t,
      1.15,
      bend
    );
  }

  presenceGrain(
    cx, cy, rx, ry, bend, phase,
    deep, inner, light
  );
}

function presenceGrain(cx, cy, rx, ry, bend, phase, deep, inner, light) {
  for (let i = 0; i < 7000; i++) {
    const x = random(cx - rx * 1.12, cx + rx * 1.12);
    const y = random(cy - ry * 1.08, cy + ry * 1.08);
    const v = (y - cy) / ry;
    const u = (x - cx + bend * 82 * v) / rx;
    const r = sqrt(u * u + v * v);
    const a = atan2(v, u);
    const edge = 1 +
      0.045 * sin(3 * a + phase) +
      0.027 * sin(5 * a - phase * 0.6) +
      0.018 * cos(2 * a + phase * 0.4);

    if (r > edge * 1.01) continue;

    const n = noise(x * 0.0025, y * 0.0025, bend + 3);
    const c = n > 0.52
      ? lerpColor(inner, light, constrain((n - 0.52) * 1.6, 0, 1))
      : lerpColor(deep, inner, constrain(n * 1.9, 0, 1));

    const flow = HALF_PI +
      0.32 * u +
      0.18 * sin(v * 4 + bend) +
      random(-0.25, 0.25);
    const len = random(4, 32) * (1.15 - 0.25 * r);

    stroke(
      red(c),
      green(c),
      blue(c),
      random(4, 18) * (0.65 + 0.55 * (1 - r))
    );
    strokeWeight(random(0.35, 2.1));
    line(
      x,
      y,
      x + cos(flow) * len,
      y + sin(flow) * len
    );
  }
}

function luminousInterval() {
  blendMode(SCREEN);

  glow(805, 1010, 390, 720, color(150, 64, 75), 1.8, 52);
  glow(805, 1000, 270, 610, color(233, 139, 94), 3.0, 58);
  glow(805, 1000, 128, 465, color(255, 214, 154), 3.8, 56);
  glow(805, 1000, 48, 260, color(255, 235, 196), 2.4, 40);

  const threads = [
    color(255, 208, 156),
    color(240, 151, 129),
    color(177, 192, 190),
    color(255, 229, 187)
  ];

  for (let i = 0; i < 72; i++) {
    let q = i / 71 * 2 - 1;
    q += random(-0.012, 0.012);

    const y0 = 345 + 170 * abs(q) + random(-45, 45);
    const y3 = 1665 - 155 * abs(q) + random(-45, 45);
    const x0 = 805 + q * 105 + random(-12, 12);
    const x3 = 805 - q * 80 + random(-12, 12);
    const c = random(threads);

    noFill();
    stroke(red(c), green(c), blue(c), random(3, 13));
    strokeWeight(random(0.45, 1.5));
    bezier(
      x0,
      y0,
      805 + q * 270,
      690 + random(-40, 40),
      805 - q * 230,
      1320 + random(-40, 40),
      x3,
      y3
    );
  }
}

function crossings() {
  blendMode(SCREEN);
  const palette = [
    color(255, 188, 139),
    color(244, 128, 119),
    color(161, 189, 192),
    color(255, 223, 177)
  ];

  for (let i = 0; i < 150; i++) {
    const u = random(-1, 1);
    const yA = 1000 + u * 570 + random(-85, 85);
    const yB = 1010 + u * 500 + random(-105, 105);
    const xA = random(390, 625);
    const xB = random(975, 1210);
    const lift = random(-170, 170);
    const cx1 = random(635, 755);
    const cx2 = random(845, 965);
    const cy1 = yA + lift;
    const cy2 = yB - lift;
    const c = random(palette);

    noFill();
    stroke(red(c), green(c), blue(c), random(5, 24));
    strokeWeight(random(0.4, 1.55));
    bezier(xA, yA, cx1, cy1, cx2, cy2, xB, yB);

    if (i % 11 === 0) {
      const t0 = random(0.18, 0.72);
      const t1 = min(t0 + random(0.05, 0.16), 0.96);
      stroke(red(c), green(c), blue(c), random(35, 75));
      strokeWeight(random(0.65, 1.25));
      beginShape();
      for (let j = 0; j <= 12; j++) {
        const t = lerp(t0, t1, j / 12);
        vertex(
          bezierPoint(xA, cx1, cx2, xB, t),
          bezierPoint(yA, cy1, cy2, yB, t)
        );
      }
      endShape();
    }
  }
}

function driftingPigment() {
  blendMode(SCREEN);
  const palette = [
    color(255, 202, 151),
    color(235, 126, 119),
    color(151, 184, 190)
  ];

  for (let i = 0; i < 220; i++) {
    const x = randomGaussian(805, 390);
    const y = randomGaussian(1000, 570);
    if (x < 30 || x > width - 30 || y < 30 || y > height - 30) continue;

    const c = random(palette);
    if (i % 7 === 0) {
      glow(
        x,
        y,
        random(6, 18),
        random(6, 18),
        c,
        0.8,
        10
      );
    }

    noStroke();
    fill(red(c), green(c), blue(c), random(18, 95));
    const d = random(0.7, 2.8);
    ellipse(x, y, d, d);
  }

  blendMode(BLEND);
}

function vignette() {
  blendMode(BLEND);
  const ctx = drawingContext;
  ctx.save();
  const g = ctx.createRadialGradient(
    width * 0.5, height * 0.48, 220,
    width * 0.5, height * 0.5, 1260
  );
  g.addColorStop(0, "rgba(4,5,13,0)");
  g.addColorStop(0.52, "rgba(4,5,13,0)");
  g.addColorStop(0.82, "rgba(4,5,13,0.16)");
  g.addColorStop(1, "rgba(4,5,13,0.68)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function surfaceGrain() {
  blendMode(BLEND);

  for (let i = 0; i < 42000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.46) {
