function paintGround() {
  background(16, 17, 30);

  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, "rgb(15,22,38)");
  g.addColorStop(0.46, "rgb(35,23,40)");
  g.addColorStop(1, "rgb(14,15,28)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function wash(x, y, rx, ry, stops, mode) {
  blendMode(mode === undefined ? BLEND : mode);

  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(rx, ry);

  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
  for (const stop of stops) {
    g.addColorStop(stop[0], stop[1]);
  }

  ctx.fillStyle = g;
  ctx.fillRect(-1, -1, 2, 2);
  ctx.restore();

  blendMode(BLEND);
}

function groundFibres() {
  noFill();

  for (let i = 0; i < 190; i++) {
    const x = random(-400, 1350);
    const y = random(-100, 2100);

    if (random() < 0.5) {
      stroke(207, 137, 119, random(2, 6));
    } else {
      stroke(125, 165, 174, random(2, 6));
    }

    strokeWeight(random(5, 28));
    bezier(
      x, y,
      x + random(180, 620), y + random(-230, 230),
      x + random(400, 900), y + random(-230, 230),
      x + random(650, 1200), y + random(-160, 160)
    );
  }
}

function cubicPoint(p, t) {
  const u = 1 - t;
  return [
    u * u * u * p[0][0] +
      3 * u * u * t * p[1][0] +
      3 * u * t * t * p[2][0] +
      t * t * t * p[3][0],
    u * u * u * p[0][1] +
      3 * u * u * t * p[1][1] +
      3 * u * t * t * p[2][1] +
      t * t * t * p[3][1]
  ];
}

function frameAt(p, t) {
  const q = cubicPoint(p, t);
  const u = 1 - t;

  const dx =
    3 * u * u * (p[1][0] - p[0][0]) +
    6 * u * t * (p[2][0] - p[1][0]) +
    3 * t * t * (p[3][0] - p[2][0]);

  const dy =
    3 * u * u * (p[1][1] - p[0][1]) +
    6 * u * t * (p[2][1] - p[1][1]) +
    3 * t * t * (p[3][1] - p[2][1]);

  const m = sqrt(dx * dx + dy * dy) || 1;

  return {
    x: q[0],
    y: q[1],
    nx: -dy / m,
    ny: dx / m
  };
}

function envelope(t) {
  return pow(max(0, sin(PI * (0.08 + 0.92 * t))), 0.52);
}

function ribbon(path, spread, rgb, alpha, phase) {
  const left = [];
  const right = [];

  for (let i = 0; i <= 110; i++) {
    const t = i / 110;
    const f = frameAt(path, t);
    const e = spread * envelope(t);

    const irregular =
      1 +
      0.045 * sin(t * 17 + phase) +
      0.025 * sin(t * 41 + phase * 2);

    const a = e * irregular * (1 + 0.05 * sin(t * 29 + phase));
    const b = e * irregular * (1 + 0.06 * cos(t * 23 + phase));

    left.push([f.x + f.nx * a, f.y + f.ny * a]);
    right.push([f.x - f.nx * b, f.y - f.ny * b]);
  }

  noStroke();
  fill(rgb[0], rgb[1], rgb[2], alpha);
  beginShape();

  for (const p of left) {
    vertex(p[0], p[1]);
  }

  for (let i = right.length - 1; i >= 0; i--) {
    vertex(right[i][0], right[i][1]);
  }

  endShape(CLOSE);
}

function paintCurrent(path, spread, palette, count, seed) {
  ribbon(path, spread * 1.18, palette[0], 30, seed);
  ribbon(path, spread, palette[0], 216, seed + 1);
  ribbon(path, spread * 0.81, palette[1], 112, seed + 2);
  ribbon(path, spread * 0.54, palette[2], 44, seed + 3);

  noFill();

  for (let i = 0; i < count; i++) {
    const side = random(-1, 1);
    const centrality = 1 - abs(side);
    const widthScale = random(0.9, 1.065);

    const tone = floor(constrain(
      centrality * (palette.length - 1) + random(-1.5, 1.5),
      0,
      palette.length - 1
    ));

    const rgb = palette[tone];
    const broad = random() < 0.09;

    stroke(
      rgb[0],
      rgb[1],
      rgb[2],
      broad ? random(4, 11) : random(10, 35)
    );

    strokeWeight(broad ? random(16, 34) : random(2.2, 11));

    beginShape();

    for (let j = 0; j <= 84; j++) {
      const t = j / 84;
      const f = frameAt(path, t);
      const e = envelope(t);

      const drift =
        (noise(seed + i * 0.017 + t * 2.8, t * 1.7 + seed) - 0.5) *
        spread *
        0.13 *
        e;

      const off = side * spread * e * widthScale + drift;
      vertex(f.x + f.nx * off, f.y + f.ny * off);
    }

    endShape();
  }
}

function currentPigment(path, spread, palette, amount) {
  noStroke();

  for (let i = 0; i < amount; i++) {
    const t = random(0.015, 0.995);
    const f = frameAt(path, t);
    const e = envelope(t);
    const side = random(-1.08, 1.08);
    const off = side * spread * e;

    const x = f.x + f.nx * off + random(-3, 3);
    const y = f.y + f.ny * off + random(-3, 3);
    const rgb = palette[floor(random(palette.length))];
    const r = random() < 0.95 ? random(0.5, 2.4) : random(3, 7);

    fill(rgb[0], rgb[1], rgb[2], random(15, 76));
    ellipse(x, y, r, r * random(0.55, 1.5));
  }
}

function softCurve(a, b, c, d, rgb, alpha, weight) {
  const path = [a, b, c, d];
  const steps = 64;

  for (let j = 0; j < steps; j++) {
    const t0 = j / steps;
    const t1 = (j + 1) / steps;
    const p = cubicPoint(path, t0);
    const q = cubicPoint(path, t1);
    const fade = pow(max(0, sin(PI * (0.03 + 0.94 * t0))), 0.6);

    stroke(rgb[0], rgb[1], rgb[2], alpha * fade);
    strokeWeight(weight * (0.35 + 0.65 * fade));
    line(p[0], p[1], q[0], q[1]);
  }
}

function reach(a, b, c, d, palette, count) {
  for (let i = 0; i < count; i++) {
    const s = (i / (count - 1) - 0.5) * 2;
    const rgb = palette[2 + floor(random(4))];

    const p0 = [
      a[0] + s * 20 + random(-8, 8),
      a[1] + s * 56 + random(-10, 10)
    ];

    const p1 = [
      b[0] + s * 38 + random(-24, 24),
      b[1] + s * 88 + random(-25, 25)
    ];

    const p2 = [
      c[0] + s * 62 + random(-25, 25),
      c[1] + s * 92 + random(-25, 25)
    ];

    const p3 = [
      d[0] + s * 40 + random(-12, 12),
      d[1] + s * 116 + random(-14, 14)
    ];

    softCurve(
      p0, p1, p2, p3,
      rgb,
      random(5, 23),
      random(0.45, 2.1)
    );
  }
}

function gestures(path, spread, palette, amount) {
  for (let i = 0; i < amount; i++) {
    const t = random(0.64, 0.97);
    const f = frameAt(path, t);
    const e = envelope(t);
    const lateral = random(-0.85, 0.85);
    const off = spread * e * lateral * 0.82;

    const a = [
      f.x + f.nx * off,
      f.y + f.ny * off
    ];

    const angle = random(TWO_PI);
    const radius = random(30, 185);
    const d = [
      800 + cos(angle) * radius * 0.72,
      1000 + sin(angle) * radius
    ];

    const bend = random(-95, 95);
    const b = [
      lerp(a[0], d[0], 0.38) + bend,
      lerp(a[1], d[1], 0.38) + random(-70, 70)
    ];

    const c = [
      lerp(a[0], d[0], 0.74) - bend * 0.3,
      lerp(a[1], d[1], 0.74) + random(-45, 45)
    ];

    const rgb = palette[3 + floor(random(3))];

    softCurve(
      a, b, c, d,
      rgb,
      random(8, 35),
      random(0.45, 1.45)
    );
  }
}

function centralPigment() {
  const pigments = [
    [244, 207, 151],
    [197, 207, 177],
    [231, 157, 119],
    [255, 235, 190]
  ];

  noStroke();

  for (let i = 0; i < 540; i++) {
    const angle = random(TWO_PI);
    const r = pow(random(), 1.7) * 500;
    const x = 800 + cos(angle) * r * 0.76;
    const y = 1000 + sin(angle) * r;
    const rgb = pigments[floor(random(pigments.length))];
    const fade = 1 - r / 520;
    const size = random(0.5, 2.8);

    fill(rgb[0], rgb[1], rgb[2], random(8, 54) * fade);
    ellipse(x, y, size, size * random(0.6, 1.4));
  }
}

function grain() {
  for (let i = 0; i < 40000; i++) {
    const x = random(width);
    const y = random(height);

    if (random() < 0.52) {
      stroke(240, 228, 209, random(2, 7));
    } else {
      stroke(0, 0, 0, random(3, 9));
    }

    strokeWeight(random(0.4, 1.15));
    point(x, y);
  }

  for (let i = 0; i < 1800; i++) {
    const x = random(width);
    const y = random(height);
    stroke(232, 217, 201, random(2, 5));
    strokeWeight(0.6);
    line(x, y, x + random(1, 5), y + random(-0.4, 0.4));
  }
}

// L'Entre-Deux — deux courants, une étreinte, une flamme qui n'appartient à aucun des deux.

const W = 1600, H = 2000;
const CX = 800;
const Y_BAS = 1940, Y_HAUT = 165;
const COEUR_X = 800, COEUR_Y = 640;
const TOURS = 2.75;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
  peindre();
}

function peindre() {
  fondNocturne();
  courant(false);          // le courant chaud, enraciné en bas à gauche
  courant(true);           // le courant froid, enraciné en bas à droite
  etincellesDeContact();   // là où les deux se touchent, la lumière jaillit
  pontsDeTendresse();      // les gestes qui traversent l'espace pour rejoindre l'autre
  coeurIncandescent();     // la flamme nourrie par l'étreinte
  souffleLumineux();       // ce qu'elle exhale vers le haut
  poussieres();            // la joie dispersée
  grain();                 // matière de toile
  vignette();              // la nuit se referme aux bords
}

/* ---------- géométrie des courants ---------- */

function ampOsc(t) {
  return 40 + 130 * Math.sin(Math.PI * t);
}

function yDe(t) {
  const tt = t <= 0 ? 0 : Math.pow(t, 0.96);
  return lerp(Y_BAS, Y_HAUT, tt);
}

function xCourant(t, froid, dphase, dside, ampMul) {
  const tc = constrain(t, 0, 1);
  const ecart = 60 + 320 * Math.pow(Math.abs(1 - 2 * tc), 1.6) + dside * 60;
  const osc = ampOsc(t) * ampMul * Math.cos(TWO_PI * TOURS * t + dphase);
  return CX + (froid ? 1 : -1) * (ecart + osc);
}

/* ---------- palettes ---------- */

function coulPal(stops, t) {
  const n = stops.length - 1;
  const f = constrain(t, 0, 1) * n;
  const i = Math.min(Math.floor(f), n - 1);
  const k = f - i;
  return [lerp(stops[i][0], stops[i + 1][0], k),
          lerp(stops[i][1], stops[i + 1][1], k),
          lerp(stops[i][2], stops[i + 1][2], k)];
}

function paletteChaud(t) {  // braise sombre -> vermillon -> ambre
  return coulPal([[14, 88, 36], [18, 90, 58], [27, 84, 76], [34, 72, 92]], t);
}

function paletteFroid(t) {  // abîme -> bleu profond -> turquoise
  return coulPal([[226, 82, 40], [214, 76, 56], [197, 66, 70], [175, 58, 86]], t);
}

/* ---------- fond ---------- */

function fondNocturne() {
  background(227, 62, 9);
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 240; i++) {           // nappes d'encre, à peine perceptibles
    const x = 160 + noise(i * 0.12, 3.1) * (W - 320);
    const y = 100 + noise(7.7, i * 0.12) * (H - 200);
    const r = 50 + 120 * noise(i * 0.61, 40.4);
    fill(228, 55, 24, 3);
    circle(x, y, r * 2);
  }
  pop();
  blendMode(BLEND);
}

/* ---------- les deux courants ---------- */

function courant(froid) {
  // présence continue : le fleuve de couleur
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 360; i++) {
    const t = random();
    const x = xCourant(t, froid, random(-0.4, 0.4), random(-1, 1), random(0.5, 1.1));
    const y = yDe(t) + random(-45, 45);
    const c = froid ? paletteFroid(t) : paletteChaud(t);
    fill(c[0], c[1], c[2], 4);
    circle(x, y, random(50, 130));
  }
  pop();
  blendMode(BLEND);

  // chevelure : des centaines de brins montent, s'enlacent
  push();
  blendMode(ADD);
  noFill();
  const N = 430, STEPS = 128, TRONCONS = 4;
  for (let k = 0; k < N; k++) {
    const gros = k < 26;
    const sw = gros ? random(2.4, 4.6) : random(0.6, 2.1);
    const alpha = gros ? random(7, 12) : random(15, 30);
    const dphase = random(-0.55, 0.55);
    const dside = random(-1, 1);
    const ampMul = random(0.45, 1.2);
    const wob = random(0.5, 1.5);
    const hueJit = random(-9, 9);
    const t0 = random(-0.05, 0.02);
    const t1 = random(0.97, 1.06);

    const pts = [];
    for (let j = 0; j <= STEPS; j++) {
      const t = lerp(t0, t1, j / STEPS);
      const x0 = xCourant(t, froid, dphase, dside, ampMul);
      const y0 = yDe(t);
      const viv = 0.35 + 0.65 * Math.abs(1 - 2 * constrain(t, 0, 1));
      const n1 = noise(k * 0.131, t * 3.2, 31.7) - 0.5;
      const n2 = noise(k * 0.131 + 77.3, t * 3.2, 88.1) - 0.5;
      pts.push([x0 + n1 * 130 * wob * viv, y0 + n2 * 95 * wob * viv]);
    }

    strokeWeight(sw);
    for (let m = 0; m < TRONCONS; m++) {
      const tc = (m + 0.5) / TRONCONS;
      const c = froid ? paletteFroid(tc) : paletteChaud(tc);
      stroke(c[0] + hueJit, c[1], c[2], alpha);
      beginShape();
      for (let j = m * (STEPS / TRONCONS); j <= (m + 1) * (STEPS / TRONCONS); j++) {
        vertex(pts[j][0], pts[j][1]);
      }
      endShape();
    }
  }
  pop();
  blendMode(BLEND);
}

/* ---------- étincelles aux points de contact ---------- */

function etincellesDeContact() {
  const zones = [];
  for (let t = 0.2; t <= 0.82; t += 0.003) {
    const d = xCourant(t, true, 0, 0, 1) - xCourant(t, false, 0, 0, 1);
    if (Math.abs(d) < 120) zones.push(t);
  }
  const choisis = [];
  for (const t of zones) {
    if (choisis.length === 0 || t - choisis[choisis.length - 1] > 0.055) {
      choisis.push(t);
    }
  }
  push();
  blendMode(ADD);
  for (const t of choisis) {
    const cx = CX + random(-16, 16);
    const cy = yDe(t) + random(-16, 16);
    const n = Math.floor(random(38, 68));
    for (let i = 0; i < n; i++) {
      const ang = random(TWO_PI);
      const len = random(14, 95);
      if (random() < 0.45) stroke(350, 22, 100, random(10, 26));
      else stroke(46, 25, 100, random(10, 30));
      strokeWeight(random(0.6, 1.9));
      line(cx, cy, cx + Math.cos(ang) * len, cy + Math.sin(ang) * len * 0.85);
    }
  }
  pop();
  blendMode(BLEND);
}

/* ---------- ponts de tendresse ---------- */

function pontsDeTendresse() {
  push();
  blendMode(ADD);
  noFill();
  for (let k = 0; k < 110; k++) {
    const t = random(0.18, 0.8);
    const x1 = xCourant(t, false, random(-0.35, 0.35), random(-0.7, 0.7), 1);
    const x2 = xCourant(t, true, random(-0.35, 0.35), random(-0.7, 0.7), 1);
    const dx = x2 - x1;
    if (Math.abs(dx) < 80 || Math.abs(dx) > 850) continue;
    const y = yDe(t) + random(-40, 40);
    const fleche = random(60, 160) * (random() < 0.7 ? -1 : 1);
    const mx = (x1 + x2) / 2;
    const my = y + fleche;
    const cA = paletteChaud(t), cB = paletteFroid(t);
    const a = random(8, 16);
    strokeWeight(random(0.7, 1.7));
    const segs = 26;
    let px = x1, py = y;
    for (let s = 1; s <= segs; s++) {
      const u = s / segs, iu = 1 - u;
      const bx = iu * iu * x1 + 2 * iu * u * mx + u * u * x2;
      const by = iu * iu * y + 2 * iu * u * my + u * u * y;
      const h = lerp(cA[0], cB[0], u);
      const sat = lerp(cA[1], cB[1], u) * (0.35 + 0.65 * Math.abs(2 * u - 1));
      const bri = lerp(cA[2], cB[2], u);
      stroke(h, sat, bri, a);
      line(px, py, bx, by);
      px = bx; py = by;
    }
  }
  pop();
  blendMode(BLEND);
}

/* ---------- la flamme centrale ---------- */

function coeurIncandescent() {
  push();
  blendMode(ADD);
  noFill();
  strokeWeight(5.5);
  const R = 330;
  for (let r = 8; r < R; r += 5) {          // anneaux : une nuée née du contact
    const u = r / R;
    const profil = Math.exp(-u * u * 6.5);
    for (let m = 0; m < 3; m++) {
      push();
      translate(COEUR_X + random(-10, 10) * u, COEUR_Y + random(-13, 13) * u);
      scale(1, 1.32);
      stroke(lerp(46, 40, u), lerp(10, 58, u), lerp(100, 78, u), 1.5 + 15 * profil / 3);
      circle(0, 0, r * 2);
      pop();
    }
  }
  noStroke();                                // le point d'incandescence
  for (let i = 0; i < 70; i++) {
    const a = random(TWO_PI);
    const r = Math.abs(randomGaussian(0, 15));
    fill(46, 8, 100, 8);
    circle(COEUR_X + Math.cos(a) * r, COEUR_Y + Math.sin(a) * r * 1.25, random(4, 14));
  }
  pop();
  blendMode(BLEND);
}

/* ---------- le souffle de la flamme ---------- */

function souffleLumineux() {
  push();
  blendMode(ADD);
  noFill();
  for (let k = 0; k < 130; k++) {
    let x = COEUR_X + randomGaussian(0, 55);
    let y = COEUR_Y + randomGaussian(0, 38);
    const monte = random() < 0.75;           // la plupart s'élèvent, quelques-uns retombent en grâce
    const len = random(150, 560);
    const pas = len / 42;
    const drape = random(-1, 1);
    stroke(random(42, 50), random(10, 35), 100, random(6, 15));
    strokeWeight(random(0.6, 2));
    beginShape();
    for (let s = 0; s <= 42; s++) {
      vertex(x, y);
      const nv = noise(k * 0.23, s * 0.09, 5.5) - 0.5;
      if (monte) {
        y -= pas;
        x += nv * 26 + drape * 2;
        if (y < 75) break;
      } else {
        y += pas * 0.8;
        x += nv * 30 + Math.sign(x - COEUR_X) * 2.2;
        if (y > H - 70) break;
      }
    }
    endShape();
  }
  pop();
  blendMode(BLEND);
}

/* ---------- poussières de lumière ---------- */

function poussieres() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 620; i++) {            // autour de la flamme
    const a = random(TWO_PI);
    const r = Math.abs(randomGaussian(0, 320));
    const x = COEUR_X + Math.cos(a) * r * 1.25;
    const y = COEUR_Y + Math.sin(a) * r * 1.45 - 40;
    const u = random();
    let c;
    if (u < 0.60) c = [46, 38, 100];
    else if (u < 0.85) c = [48, 8, 100];
    else if (u < 0.95) c = [176, 45, 92];
    else c = [22, 78, 96];
    const d = Math.sqrt((x - COEUR_X) * (x - COEUR_X) + (y - COEUR_Y) * (y - COEUR_Y));
    const proche = constrain(1 - d / 750, 0.15, 1);
    fill(c[0], c[1], c[2], random(7, 34) * proche);
    circle(x, y, random(1, 3.4));
  }
  for (let i = 0; i < 360; i++) {            // le long des courants
    const froid = random() < 0.5;
    const t = random();
    const x = xCourant(t, froid, random(-0.5, 0.5), random(-1, 1), random(0.5, 1.15));
    const y = yDe(t) + random(-55, 55);
    const c = froid ? [188, 50, 92] : [26, 80, 96];
    fill(c[0], c[1], c[2], random(6, 26));
    circle(x, y, random(1, 2.8));
  }
  pop();
  blendMode(BLEND);
}

/* ---------- matière et nuit ---------- */

function grain() {
  push();
  noStroke();
  for (let i = 0; i < 26000; i++) {
    const b = random() < 0.5 ? 45 : 96;
    fill(0, 0, b, 6);
    rect(random(W), random(H), 1.4, 1.4);
  }
  pop();
}

function vignette() {
  const g = createGraphics(W, H);
  g.pixelDensity(1);
  g.loadPixels();
  const cx = CX, cy = 850;
  const dMax = Math.hypot(800, 1150);
  const d0 = 0.58 * dMax;
  for (let y = 0; y < H; y++) {
    const dy = y - cy;
    const row = y * W;
    for (let x = 0; x < W; x++) {
      const dx = x - cx;
      const d = Math.sqrt(dx * dx + dy * dy);
      let a = 0;
      if (d > d0) {
        const k = Math.min((d - d0) / (dMax - d0), 1);
        a = 200 * Math.pow(k, 1.7);
      }
      const idx = 4 * (row + x);
      g.pixels[idx] = 20;
      g.pixels[idx + 1] = 28;
      g.pixels[idx + 2] = 60;
      g.pixels[idx + 3] = a;
    }
  }
  g.updatePixels();
  push();
  blendMode(MULTIPLY);
  image(g, 0, 0);
  pop();
  blendMode(BLEND);
}

// L'Entre-Deux — 1600 × 2000
// Deux courants, l'un de feu et l'autre d'eau, montent des profondeurs,
// s'enlacent sans se fondre ; leur rencontre fait naître une lumière
// qui n'appartient à aucun des deux — puis cette lumière s'élève.

const W = 1600, H = 2000;
const CX = 800, CY = 690; // le cœur de la rencontre

const FIRE = [
  [0.00, [92, 24, 10]],
  [0.40, [188, 60, 16]],
  [0.74, [250, 138, 48]],
  [1.00, [255, 206, 108]],
];
const WATER = [
  [0.00, [9, 42, 50]],
  [0.40, [13, 100, 95]],
  [0.74, [44, 188, 158]],
  [1.00, [168, 238, 212]],
];
const WHITE_FIRE  = [255, 244, 220];
const WHITE_WATER = [232, 255, 243];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  night();      // la nuit profonde
  dust();       // poussières lointaines
  heartGlow();  // l'irradiation de la rencontre
  blendingMode(ADD);
  streams(-1);  // le courant de feu
  streams(1);   // le courant d'eau
  plume();      // la clarté qui s'élève
  seeds();      // l'entre-deux habité
  blendingMode(BLEND);
  matter();     // grain de toile, voile, vignette
}

/* ---------- le fond nocturne ---------- */

function night() {
  const ctx = drawingContext;
  ctx.save();
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.00, 'rgb(5, 8, 15)');
  g.addColorStop(0.42, 'rgb(9, 11, 20)');
  g.addColorStop(0.78, 'rgb(14, 12, 20)');
  g.addColorStop(1.00, 'rgb(23, 16, 23)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

function dust() {
  noStroke();
  let placed = 0, guard = 0;
  while (placed < 150 && guard < 4000) {
    guard++;
    const x = random(W), y = random(H * 0.85);
    if (dist(x, y, CX, CY) < 760) continue;
    placed++;
    const rare = random() < 0.1;
    fill(202, 216, 236, rare ? random(28, 52) : random(7, 26));
    circle(x, y, random(0.7, 1.9));
  }
}

/* ---------- le cœur de la rencontre ---------- */

function heartGlow() {
  halo(CX - 34, CY + 30, 620, [
    [0, 'rgba(255,166,72,0.14)'],
    [0.45, 'rgba(198,86,38,0.06)'],
    [1, 'rgba(0,0,0,0)'],
  ]);
  halo(CX + 34, CY - 26, 620, [
    [0, 'rgba(84,214,186,0.13)'],
    [0.45, 'rgba(28,124,116,0.055)'],
    [1, 'rgba(0,0,0,0)'],
  ]);
  halo(CX, CY, 860, [
    [0, 'rgba(255,234,198,0.13)'],
    [0.30, 'rgba(232,202,160,0.07)'],
    [0.65, 'rgba(120,110,118,0.028)'],
    [1, 'rgba(0,0,0,0)'],
  ]);
  halo(CX, CY, 200, [
    [0, 'rgba(255,252,240,0.85)'],
    [0.30, 'rgba(255,238,188,0.36)'],
    [0.62, 'rgba(255,214,132,0.11)'],
    [1, 'rgba(0,0,0,0)'],
  ]);
}

function halo(x, y, r, stops) {
  const ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

/* ---------- les deux courants ---------- */

function streams(side) {
  const fire = side < 0;
  const bx0 = fire ? 424 : 1176;
  const N = 195;
  for (let i = 0; i < N; i++) {
    // naissance sous le bord inférieur, dans la profondeur
    const a = random(PI);
    const bx = bx0 + Math.cos(a) * 205 * (0.55 + random(0.75));
    const by = 2018 + Math.sin(a) * 105 * random(0.4, 1.2);
    // but : un point de l'anneau où tout s'enlace
    const thT = fire ? radians(random(100, 215)) : radians(random(-35, 80));
    const rT = 250 * (0.78 + random(0.38));
    const tx = CX + Math.cos(thT) * rT;
    const ty = CY + Math.sin(thT) * rT;
    // évasement de la jupe vers l'extérieur
    const cxx = bx + side * 285 * (0.55 + random(0.75));
    const cyy = lerp(by, ty, 0.42 + random(0.2)) + random(-90, 90);

    const ph1 = random(1000), ph2 = random(1000);
    const amp = 26 + random(74);
    const w0 = 0.9 + random(2.1);
    const a0 = 0.030 + random(0.052);
    const uOff = random(-0.05, 0.05);

    // --- la montée
    const STEPS = 108;
    let px = bx, py = by;
    for (let s = 1; s <= STEPS; s++) {
      const t = s / STEPS;
      let x = q1(bx, cxx, tx, t);
      let y = q1(by, cyy, ty, t);
      const env = Math.sin(Math.PI * t);
      x += (noise(t * 2.3 + ph1, i * 0.13) - 0.5) * 2 * amp * env;
      y += (noise(t * 2.3 + ph2, i * 0.13 + 57) - 0.5) * 1.6 * amp * env;
      const gl = glowAt(x, y);
      const col = streamColor(fire, constrain(t + uOff, 0, 1), gl);
      const al = a0 * lerp(0.62, 1.25, t) * (1 + gl * 0.45);
      const w = w0 * (0.55 + 0.85 * env);
      seg(px, py, x, y, col, al, w);
      px = x; py = y;
    }

    // --- l'enlacement : chacun enveloppe l'autre, en sens opposé,
    //     puis se dissout dans la lumière en approchant le noyau
    const dir = fire ? 1 : -1;
    const thTot = radians(200 + random(190));
    const SP = 56;
    for (let s2 = 1; s2 <= SP; s2++) {
      const t2 = s2 / SP;
      const th = thT + dir * thTot * t2;
      const rr = lerp(rT, 55, Math.pow(t2, 0.8));
      const wob = Math.sin(Math.PI * t2) * 30;
      const x = CX + Math.cos(th) * rr + (noise(t2 * 3.1 + ph1, 31.7) - 0.5) * 2 * wob;
      const y = CY + Math.sin(th) * rr + (noise(t2 * 3.1 + ph2, 71.3) - 0.5) * 2 * wob;
      const gl = glowAt(x, y);
      const col = lerpRGB(streamColor(fire, 1, gl * 0.6),
                          fire ? WHITE_FIRE : WHITE_WATER,
                          Math.min(1, t2 * 1.4));
      const al = a0 * Math.pow(1 - t2, 1.15) * 1.7;
      seg(px, py, x, y, col, al, w0 * 0.8);
      px = x; py = y;
    }
  }
}

/* ---------- la clarté qui s'élève ---------- */

function plume() {
  // colonne de clarté au-dessus du cœur, qui se résorbe en montant
  for (let y = CY - 30; y > 140; y -= 27) {
    const s = (CY - y) / (CY - 140);
    const r = 105 + 155 * Math.sin(Math.PI * Math.pow(s, 0.9)) * (1 - 0.45 * s);
    const al = 0.004 + 0.015 * Math.pow(1 - s, 1.3);
    const col = lerpRGB([255, 240, 204], [150, 174, 220], Math.pow(s, 1.5));
    halo(colX(y), y, r, [
      [0, rgbaStr(col, al)],
      [1, 'rgba(0,0,0,0)'],
    ]);
  }
  // filaments d'évaporation
  for (let i = 0; i < 110; i++) {
    const th = radians(175 + random(190));
    const r0 = 55 + random(155);
    let x = CX + Math.cos(th) * r0;
    let y = CY + Math.sin(th) * r0 * 0.75;
    const L = 330 + random(620);
    const w = 0.7 + random(1.2);
    const a0 = 0.013 + random(0.03);
    const ph = random(500);
    const STEPS = 52;
    let px = x, py = y;
    for (let s = 1; s <= STEPS; s++) {
      const t = s / STEPS;
      y -= L / STEPS;
      x += (noise(t * 2.6 + ph, i * 0.31) - 0.5) * 3.6;
      x += (colX(y) - x) * 0.012; // la flamme se resserre en montant
      const col = lerpRGB([255, 242, 208], [170, 192, 228], Math.pow(t, 1.6));
      const al = a0 * Math.pow(1 - t, 1.25);
      seg(px, py, x, y, col, al, w);
      px = x; py = y;
    }
  }
  // étincelles emportées vers le haut
  for (let i = 0; i < 120; i++) {
    const s = Math.pow(random(), 1.35);
    const y = lerp(CY + 30, 190, s);
    const spread = 70 + (CY - y) * 0.3;
    const x = colX(y) + (random() + random() - 1) * spread;
    const col = random() < 0.28 ? [176, 244, 224] : [255, 238, 198];
    const sz = (0.8 + random(2.3)) * (1 - 0.3 * s);
    noStroke();
    fill(col[0], col[1], col[2], random(24, 88));
    circle(x, y, sz);
    fill(col[0], col[1], col[2], 12);
    circle(x, y, sz * 5);
  }
}

/* ---------- l'entre-deux habité ---------- */

function seeds() {
  // semences déposées dans la nuit entre les deux courants
  for (let i = 0; i < 30; i++) {
    const y = random(1060, 1770);
    const p = (2010 - y) / 1240;
    const half = 170 - 65 * p;
    const x = CX + (random() + random() + random() - 1.5) * 1.33 * half;
    const col = random() < 0.5 ? [255, 214, 150] : [160, 236, 214];
    noStroke();
    fill(col[0], col[1], col[2], random(14, 40));
    circle(x, y, random(0.8, 2.4));
    fill(col[0], col[1], col[2], 8);
    circle(x, y, random(4, 9));
  }
  // passeurs : quelques filaments traversent d'un courant vers l'autre
  // et se teintent de l'autre en chemin
  for (let i = 0; i < 12; i++) {
    const p = 0.3 + random(0.5);
    const y = lerp(2010, 790, p);
    const edge = 618 + 90 * Math.pow(p, 1.3);
    const x1 = edge + random(-25, 25);
    const x2 = W - edge + random(-25, 25);
    const cxm = CX + random(-40, 40);
    const cym = y + 75 + random(60);
    const w = 0.9 + random(0.5);
    const STEPS = 26;
    let px = x1, py = y;
    for (let s = 1; s <= STEPS; s++) {
      const t = s / STEPS;
      const x = q1(x1, cxm, x2, t);
      const yy = q1(y, cym, y, t);
      const col = lerpRGB([255, 150, 62], [70, 198, 168], t);
      const al = 0.05 * Math.pow(Math.sin(Math.PI * t), 0.35);
      seg(px, py, x, yy, col, al, w);
      px = x; py = yy;
    }
  }
}

/* ---------- matière de la toile ---------- */

function matter() {
  noStroke();
  for (let i = 0; i < 22000; i++) {   // grain clair
    const v = random(50, 210);
    fill(v, v, v + random(12), random(7, 13));
    circle(random(W), random(H), random(1, 2.6));
  }
  for (let i = 0; i < 8000; i++) {    // grain sombre
    fill(0, 0, 0, random(9, 20));
    circle(random(W), random(H), random(1, 3));
  }
  fill(13, 15, 24, 12);               // voile unificateur
  rect(0, 0, W, H);
  const ctx = drawingContext;         // vignette
  ctx.save();
  const g = ctx.createRadialGradient(800, 950, 650, 800, 970, 1500);
  g.addColorStop(0.0, 'rgba(0,0,0,0)');
  g.addColorStop(0.55, 'rgba(3,3,9,0.05)');
  g.addColorStop(0.8, 'rgba(2,2,7,0.15)');
  g.addColorStop(1.0, 'rgba(0,0,6,0.32)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

/* ---------- outils ---------- */

function seg(x1, y1, x2, y2, col, al, w) {
  strokeWeight(w);
  stroke(col[0], col[1], col[2], al * 255);
  line(x1, y1, x2, y2);
}

function q1(a, c, b, t) { // Bézier quadratique
  const u = 1 - t;
  return u * u * a + 2 * u * t * c + t * t * b;
}

function colX(y) { // axe légèrement ondulé de la colonne de clarté
  return CX + Math.sin(y * 0.004 + 1.2) * 26;
}

function glowAt(x, y) { // proximité lumineuse du cœur
  const d = Math.sqrt((x - CX) * (x - CX) + (y - CY) * (y - CY));
  if (d >= 560) return 0;
  const g = 1 - d / 560;
  return g * g;
}

function streamColor(fire, u, gl) {
  const base = ramp(fire ? FIRE : WATER, u);
  return lerpRGB(base, fire ? WHITE_FIRE : WHITE_WATER, Math.min(1, gl * 0.8));
}

function lerpRGB(c1, c2, t) {
  return [lerp(c1[0], c2[0], t), lerp(c1[1], c2[1], t), lerp(c1[2], c2[2], t)];
}

function ramp(stops, u) {
  if (u <= stops[0][0]) return stops[0][1];
  for (let i = 1; i < stops.length; i++) {
    if (u <= stops[i][0]) {
      const a = stops[i - 1], b = stops[i];
      return lerpRGB(a[1], b[1], (u - a[0]) / (b[0] - a[0]));
    }
  }
  return stops[stops.length - 1][1];
}

function rgbaStr(col, a) {
  return 'rgba(' + (col[0] | 0) + ',' + (col[1] | 0) + ',' + (col[2] | 0) + ',' + a + ')';
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  const W = 1600;
  const H = 2000;
  const CX = 800;      // axe de la toile
  const CY = 1330;     // cœur de la fusion
  const WATER = 1518;  // ligne d'eau

  noStroke();

  /* ============ LE CIEL ============ */
  for (let y = 0; y < H; y++) {
    const c = lerpColor(color(3, 5, 12), color(8, 13, 26), y / (H - 1));
    fill(c);
    rect(0, y, W, 1);
  }

  blendMode(ADD);
  // poussière stellaire
  for (let i = 0; i < 900; i++) {
    fill(190, 208, 255, random(3, 14));
    ellipse(random(W), H * pow(random(), 2.2), random(0.8, 2.1), random(0.8, 2.1));
  }
  // étoiles
  for (let i = 0; i < 110; i++) {
    const y = H * pow(random(), 2.6);
    const x = random(W);
    const s = random(1.2, 3.0);
    const warm = random() < 0.32;
    const cr = warm ? 255 : 214;
    const cg = warm ? 226 : 230;
    const cb = warm ? 182 : 255;
    fill(cr, cg, cb, random(8, 20));
    ellipse(x, y, s * 5.5, s * 5.5);
    fill(cr, cg, cb, random(50, 120));
    ellipse(x, y, s, s);
  }

  /* ============ LES DEUX COURANTS ============ */
  const N = 700;
  const wOf = t => lerp(150, 44, pow(t, 0.85));

  function streamPath(side, ph, ampBase, ampGrow, nzs) {
    const pts = [];
    const xEnd = CX + side * 62;
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const conv = pow(1 - t, 1.25);
      let x = CX + side * 390 * conv;
      x = lerp(x, xEnd, pow(t, 3));
      const amp = ampBase + ampGrow * pow(t, 1.9);
      const damp = t > 0.96 ? pow((1 - t) / 0.04, 0.55) : 1;
      const osc = sin(TWO_PI * 2.35 * t + ph) * amp * damp;
      const nz = (noise(t * 5.3 + nzs, side * 2.7 + 11.1) - 0.5) * 2 * (40 + 130 * t) * damp;
      pts.push({ x: x + osc + nz, y: lerp(-70, CY + 14, t), t: t });
    }
    return pts;
  }

  function paintStream(pts, pal, ember) {
    // voiles superposés : masse sombre, chair, fil incandescent
    const passes = [
      { f: 1.00, col: pal.deep,   A: 26, off: 0.30 },
      { f: 0.82, col: pal.deep,   A: 22, off: 0.28 },
      { f: 0.62, col: pal.mid,    A: 24, off: 0.34 },
      { f: 0.46, col: pal.mid,    A: 28, off: 0.24 },
      { f: 0.34, col: pal.bright, A: 34, off: 0.20 },
      { f: 0.24, col: pal.bright, A: 40, off: 0.16 },
      { f: 0.16, col: pal.bright, A: 48, off: 0.13 },
      { f: 0.10, col: pal.core,   A: 55, off: 0.09 },
      { f: 0.06, col: pal.core,   A: 60, off: 0.06 },
    ];
    blendMode(ADD);
    noStroke();
    for (let k = 0; k < passes.length; k++) {
      const P = passes[k];
      let i = 0;
      while (i < pts.length - 1) {
        let acc = 0;
        let j = i;
        while (j < pts.length - 1 && acc < max(2.5, (wOf(pts[j].t) / 2) * P.f)) {
          acc += dist(pts[j].x, pts[j].y, pts[j + 1].x, pts[j + 1].y);
          j++;
        }
        const tj = pts[j].t;
        const rj = (wOf(tj) / 2) * P.f;
        const a = constrain((P.A * acc) / (2 * rj), 1, 255);
        const amp = wOf(tj) * P.off;
        const ox = (noise(tj * 3.3 + k * 19.1, k * 4.3) - 0.5) * 2 * amp;
        const oy = (noise(tj * 2.9 + k * 7.7, 60 + k * 6.1) - 0.5) * 2 * amp * 0.35;
        fill(P.col[0], P.col[1], P.col[2], a);
        ellipse(pts[j].x + ox, pts[j].y + oy, rj * 2, rj * 2);
        i = j;
      }
    }
    // coups de pinceau le long du courant
    for (let e = 0; e < 110; e++) {
      const i = floor(random(15, pts.length - 42));
      const t = pts[i].t;
      const ang = atan2(pts[i + 6].y - pts[i].y, pts[i + 6].x - pts[i].x);
      const off = (random() - 0.5) * wOf(t) * 0.8;
      push();
      translate(pts[i].x + cos(ang + HALF_PI) * off, pts[i].y + sin(ang + HALF_PI) * off);
      rotate(ang);
      blendMode(ADD);
      const cc = random() < 0.5 ? pal.mid : pal.bright;
      fill(cc[0], cc[1], cc[2], random(8, 22));
      ellipse(0, 0, random(24, 85), random(5, 15));
      pop();
    }
    // braises
    blendMode(ADD);
    noStroke();
    for (let e = 0; e < 520; e++) {
      const i = floor(random(0, pts.length - 1));
      const t = pts[i].t;
      const r = wOf(t) / 2;
      const off = (random() + random() - 1) * r * 0.95;
      const ang = atan2(pts[i + 1].y - pts[i].y, pts[i + 1].x - pts[i].x);
      const x = pts[i].x + cos(ang + HALF_PI) * off;
      const y = pts[i].y + sin(ang + HALF_PI) * off;
      const s = random(0.8, 3.0);
      fill(ember[0], ember[1], ember[2], random(18, 95) * (1 - 0.4 * t));
      ellipse(x, y, s, s);
      if (random() < 0.12) {
        fill(ember[0], ember[1], ember[2], 10);
        ellipse(x, y, s * 5, s * 5);
      }
    }
  }

  const GOLD = {
    deep: [112, 48, 10], mid: [205, 112, 30],
    bright: [255, 192, 84], core: [255, 238, 186]
  };
  const TEAL = {
    deep: [6, 54, 66], mid: [16, 128, 138],
    bright: [92, 224, 210], core: [214, 255, 246]
  };

  const goldPath = streamPath(-1, 0.0, 70, 330, 7.3);
  const tealPath = streamPath(1, 0.9, 64, 300, 41.7);
  paintStream(tealPath, TEAL, [190, 255, 240]);
  paintStream(goldPath, GOLD, [255, 214, 130]);

  /* ============ ONDES ÉMISES ============ */
  blendMode(ADD);
  noFill();
  const rings = [[265, 20], [380, 13], [510, 8], [660, 5]];
  for (const [R, aa] of rings) {
    stroke(172, 202, 232, aa);
    strokeWeight(2);
    beginShape();
    for (let i = 0; i <= 130; i++) {
      const th = (i / 130) * TWO_PI;
      const rr = R + (noise(cos(th) * 0.8 + 5, sin(th) * 0.8 + 5) - 0.5) * 26;
      vertex(CX + cos(th) * rr, CY + sin(th) * rr);
    }
    endShape(CLOSE);
  }

  /* ============ LE SOUFFLE ASCENDANT ============ */
  blendMode(ADD);
  noFill();
  for (let v = 0; v < 6; v++) {
    const id = v * 3.17 + 2.4;
    const yTop = 170 + v * 36 + random(40);
    const sway = 20 + random(45);
    let px = CX + random(-22, 22);
    let py = CY - 30;
    for (let s2 = 1; s2 <= 120; s2++) {
      const s = s2 / 120;
      const y = lerp(CY - 30, yTop, s);
      const spread = 40 + 300 * s;
      const x = CX + (noise(id + s * 2.6, id * 0.7) - 0.5) * 2 * spread
              + sin(s * 2.7 + id) * sway;
      const c = lerpColor(color(255, 226, 170), color(150, 195, 255), s);
      strokeWeight(lerp(6.5, 1.2, s));
      stroke(red(c), green(c), blue(c), lerp(30, 3, s));
      line(px, py, x, y);
      px = x;
      py = y;
    }
  }

  /* ============ LA FUSION ============ */
  function glow(cx, cy, R, col, L0) {
    blendMode(ADD);
    noStroke();
    const dr = 4;
    for (let r = R; r > 0; r -= dr) {
      const a = (2 * L0 * dr * (1 - r / R)) / R;
      fill(col[0], col[1], col[2], constrain(a, 1, 255));
      ellipse(cx, cy, r * 2, r * 2);
    }
  }
  // deux lumières qui se recouvrent sans s'effacer
  glow(CX - 62, CY, 210, [255, 150, 40], 62);
  glow(CX + 62, CY, 210, [40, 210, 190], 62);
  glow(CX, CY, 130, [255, 244, 214], 120);
  glow(CX, CY, 46, [255, 255, 250], 200);

  // la mandorle : trace nette de l'entre-deux
  const Rg = 210;
  const dxG = 62;
  const dyI = sqrt(Rg * Rg - dxG * dxG);
  const aLow = atan2(dyI, dxG);
  blendMode(ADD);
  noFill();
  stroke(255, 250, 235, 34);
  strokeWeight(2.4);
  arc(CX - dxG, CY, Rg * 2, Rg * 2, aLow, TWO_PI - aLow, OPEN);
  arc(CX + dxG, CY, Rg * 2, Rg * 2, aLow - PI, PI - aLow, OPEN);

  /* ============ LA GERBE ============ */
  const spineX = u => CX + sin(u * 3.4 + 0.8) * 55 + (noise(u * 2.2, 4.4) - 0.5) * 90;
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 950; i++) {
    const u = random();
    if (random() < 0.75 * u) continue;
    const y = lerp(CY - 20, 130, u);
    const x = spineX(u) + ((random() + random() + random() - 1.5) / 1.5) * (46 + 240 * u);
    const s = (0.9 + random() * 2.4) * (1 - 0.35 * u);
    const c = lerpColor(color(255, 236, 185), color(150, 196, 255), u);
    fill(red(c), green(c), blue(c), (1 - 0.6 * u) * random(25, 95));
    ellipse(x, y, s, s);
  }
  // traînées ascendantes
  for (let i = 0; i < 90; i++) {
    const u = random();
    if (random() < 0.7 * u) continue;
    const y = lerp(CY - 60, 220, u);
    const x = spineX(u) + (random() + random() - 1) * (40 + 200 * u);
    const c = lerpColor(color(255, 236, 185), color(150, 196, 255), u);
    stroke(red(c), green(c), blue(c), (1 - 0.6 * u) * random(15, 45));
    strokeWeight(1.4);
    line(x, y, x + random(-3, 3), y - random(9, 34) * (1 - 0.3 * u));
  }
  // braises majeures
  noStroke();
  for (let i = 0; i < 26; i++) {
    const u = pow(random(), 1.6);
    const y = lerp(CY - 30, 260, u);
    const x = spineX(u) + (random() + random() - 1) * (60 + 160 * u);
    fill(255, 244, 210, 12);
    ellipse(x, y, 22, 22);
    fill(255, 248, 225, 40);
    ellipse(x, y, 9, 9);
    fill(255, 252, 240, 110);
    ellipse(x, y, 4, 4);
  }

  /* ============ LES CENDRES ============ */
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 55; i++) {
    const y = lerp(CY + 70, WATER - 8, random());
    const fade = 1 - (y - CY) / (WATER - CY);
    const x = CX + (random() + random() - 1) * 65 + sin(y * 0.02 + i) * 16;
    fill(235, 150, 60, 12 + 45 * fade * fade);
    ellipse(x, y, random(1, 2.6), random(1, 2.6));
  }

  /* ============ L'EAU ET LE REFLET ============ */
  blendMode(BLEND);
  noStroke();
  fill(5, 8, 18, 170);
  rect(0, WATER, W, H - WATER);
  fill(3, 5, 12, 120);
  rect(0, WATER + 240, W, H - WATER - 240);
  stroke(140, 175, 210, 20);
  strokeWeight(1);
  line(0, WATER, W, WATER);

  blendMode(ADD);
  noStroke();
  // tache du reflet
  for (let r = 70; r > 0; r -= 5) {
    const a = (2 * 55 * 5 * (1 - r / 70)) / 70;
    fill(225, 208, 175, constrain(a, 1, 255));
    ellipse(CX, WATER + 36, r * 2, r * 1.2);
  }
  // colonne du reflet, tremblante
  for (let y = WATER + 10; y < 1875; y += 6) {
    const v = (y - WATER) / (1875 - WATER);
    const wob = (noise(y * 0.012, 77) - 0.5) * 2 * (10 + 26 * v);
    const wdt = lerp(46, 10, pow(v, 0.8)) * (0.7 + 0.6 * noise(y * 0.03, 12));
    const c = lerpColor(color(255, 210, 130), color(120, 220, 210), v);
    fill(red(c), green(c), blue(c), constrain(26 * (1 - v) * (1 - v), 1, 255));
    ellipse(CX + wob, y, wdt, 6.5);
  }
  // rides
  for (let i = 0; i < 34; i++) {
    const y = lerp(WATER + 14, H - 20, random());
    const cxr = CX + ((random() + random() + random() - 1.5) / 1.5) * 260;
    const len = random(50, 300) * (1 - 0.4 * (y - WATER) / (H - WATER));
    const c = abs(cxr - CX) < 90 ? color(255, 214, 150) : color(150, 185, 220);
    stroke(red(c), green(c), blue(c), random(4, 12));
    strokeWeight(random(0.8, 1.8));
    line(cxr - len / 2, y, cxr + len / 2, y);
  }

  /* ============ MATIÈRE ============ */
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 24000; i++) {
    if (random() < 0.5) fill(0, 0, 0, random(2, 6));
    else fill(255, 255, 255, random(1, 4));
    ellipse(random(W), random(H), random(0.7, 1.5), random(0.7, 1.5));
  }
  // vignette
  for (let i = 0; i < 70; i += 2) {
    fill(0, 0, 0, (1 - i / 70) * 1.6);
    rect(i, 0, 2, H);
    rect(W - i - 2, 0, 2, H);
    rect(0, H - i - 2, W, 2);
  }
}

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  sky();
  ground();
  flames();
  union();
  dawn();
  dawnVeins();
  threads();
  heart();
  particles();
  vignette();
  grain();
}

// ---------- ciel ----------
function sky() {
  noStroke();
  const cTop = color(6, 8, 15);
  const cMid = color(26, 28, 48);
  const cLow = color(20, 15, 28);
  for (let y = 0; y < H; y += 4) {
    let c;
    if (y < 1200) c = lerpColor(cTop, cMid, y / 1200);
    else c = lerpColor(cMid, cLow, (y - 1200) / (H - 1200));
    fill(c);
    rect(0, y, W, 4);
  }
  // nappes de vapeur (profondeur du fond)
  for (let i = 0; i < 340; i++) {
    const x = noise(i * 0.137, 7.71) * W;
    const y = 140 + noise(i * 0.113, 3.37) * (H - 280);
    const r = 180 + noise(i * 0.071, 9.13) * 430;
    const col = random() < 0.62 ? color(30, 38, 70) : color(44, 32, 68);
    fill(col, 6);
    ellipse(x, y, r, r * 0.72);
  }
}

// ---------- terre ----------
function groundTop(x) {
  return 1620 + noise(x * 0.0042, 5.23) * 130 - 40;
}

function ground() {
  noStroke();
  for (let y = 1650; y < H; y += 4) {
    const t = (y - 1650) / (H - 1650);
    fill(lerpColor(color(56, 36, 24), color(13, 8, 7), t));
    rect(0, y, W, 4);
  }
  // bord irrégulier
  for (let x = -60; x < W + 60; x += 5) {
    const gy = groundTop(x);
    fill(lerpColor(color(64, 42, 27), color(50, 32, 20), noise(x * 0.01, 8.83)));
    rect(x, gy, 5, 1662 - gy);
  }
  // matière
  const palette = [color(72, 48, 28), color(46, 30, 18), color(94, 62, 33), color(28, 18, 11), color(58, 40, 34)];
  for (let i = 0; i < 2400; i++) {
    const x = random(W);
    const gy = groundTop(x);
    const y = gy + 8 + pow(random(), 1.4) * (H - gy - 12);
    fill(random(palette), random(12, 34));
    const s = random(6, 34);
    ellipse(x, y, s, s * random(0.35, 0.7));
  }
  // liseré éclairé par ce qui brûle au-dessus
  for (let x = 0; x <= W; x += 4) {
    const gy = groundTop(x);
    const glow = pow(1 - abs(x - 800) / 800, 1.6);
    const c = lerpColor(color(198, 130, 54), color(140, 88, 44), noise(x * 0.02, 4.41));
    fill(c, 24 + 62 * glow);
    ellipse(x, gy, 8, 4.5);
  }
  // racines d'or
  root(560, groundTop(560) + 8, HALF_PI, 170, 4);
  root(1010, groundTop(1010) + 8, HALF_PI, 170, 4);
  root(800, groundTop(800) + 26, HALF_PI, 130, 3);
}

function root(x, y, ang, len, depth) {
  if (depth <= 0) return;
  noFill();
  stroke(172, 122, 56, 30 + depth * 7);
  strokeWeight(0.9 + depth * 0.8);
  beginShape();
  vertex(x, y);
  let px = x, py = y, a = ang;
  const steps = 7;
  const seg = len / steps;
  for (let i = 0; i < steps; i++) {
    a += (noise(px * 0.012, py * 0.012, depth * 3.7) - 0.5) * 0.6;
    a = constrain(a, QUARTER_PI * 0.55, PI - QUARTER_PI * 0.55);
    px += cos(a) * seg;
    py += sin(a) * seg * 0.8;
    vertex(px, py);
  }
  endShape();
  const branches = random() < 0.72 ? 2 : 1;
  for (let b = 0; b < branches; b++) {
    const dev = (b === 0 ? -1 : 1) * random(0.35, 0.85);
    root(px, py, a + dev, len * 0.68, depth - 1);
  }
}

// ---------- les deux flammes ----------
function flames() {
  flameColumn(560, 775, color(88, 10, 40), color(206, 48, 90), color(216, 92, 124), -1);
  flameColumn(1040, 825, color(126, 64, 12), color(226, 158, 60), color(240, 200, 96), 1);
}

function flameColumn(x0, x1, cDeep, cMid, cTip, side) {
  const yBot = 1730, yTop = 950;
  noStroke();
  for (let pass = 0; pass < 4; pass++) {
    for (let y = yBot; y > yTop; y -= 6) {
      const t = map(y, yBot, yTop, 0, 1);
      const wob = (noise(y * 0.006 + pass * 13.7, side * 3.13) - 0.5) * 110 * t;
      const cx = lerp(x0, x1, pow(t, 0.92)) + wob + sin(t * 6.2 + pass * 1.7) * 10;
      const w = lerp(240, 105, t) * (0.75 + noise(y * 0.004, pass * 7.7 + side * 11.1) * 0.55);
      let c;
      if (t < 0.75) c = lerpColor(cDeep, cMid, t / 0.75);
      else c = lerpColor(cMid, cTip, (t - 0.75) / 0.25);
      fill(c, 20);
      ellipse(cx, y, w, 30);
    }
  }
  // coups de pinceau
  for (let b = 0; b < 240; b++) {
    const t = pow(random(), 0.85);
    const y = lerp(yBot, yTop, t);
    const base = lerp(x0, x1, pow(t, 0.92));
    const w = lerp(240, 105, t) * 0.62;
    const x = base + (random() * 2 - 1) * w;
    const len = random(16, 64) * (1.2 - t * 0.5);
    let c;
    if (t < 0.7) c = lerpColor(cDeep, cMid, t / 0.7);
    else c = lerpColor(cMid, cTip, (t - 0.7) / 0.3);
    stroke(c, random(16, 44));
    strokeWeight(random(2, 6.5));
    line(x, y + len, x + (noise(x * 0.01, y * 0.01) - 0.5) * 16, y - len);
  }
  noStroke();
}

// ---------- la braise du contact ----------
function union() {
  noStroke();
  for (let i = 0; i < 80; i++) {
    const a = random(TWO_PI);
    const r = pow(random(), 0.6) * 95;
    const x = 800 + cos(a) * r * 1.15;
    const y = 938 + sin(a) * r * 0.55;
    fill(color(176, 64, 32), random(14, 36));
    ellipse(x, y, random(14, 60), random(10, 32));
  }
  for (let i = 0; i < 26; i++) {
    const x = 800 + (random() * 2 - 1) * 80;
    const y = 905 - random() * 170;
    fill(color(198, 86, 36), random(10, 24));
    ellipse(x, y, random(10, 30), random(20, 55));
  }
}

// ---------- la lumière née de la rencontre ----------
function dawn() {
  noStroke();
  blob(800, 620, 400, 380, 0.3, 40.0, color(214, 174, 112), 13);
  blob(800, 650, 335, 400, 0.28, 47.0, color(226, 190, 130), 15);
  for (let i = 0; i < 30; i++) {
    const t = i / 29;
    const cy = lerp(1010, 430, t);
    const rx = lerp(200, 425, pow(t, 1.12)) * (0.82 + noise(i * 0.31, 21.7) * 0.36);
    const c = lerpColor(color(238, 206, 150), color(250, 240, 218), noise(i * 0.23, 8.8));
    blob(800 + (noise(i * 0.41, 31.3) - 0.5) * 80, cy, rx, rx * lerp(1.12, 0.85, t), 0.34, i * 0.83 + 3, c, 23);
  }
  for (let i = 0; i < 16; i++) {
    const t = i / 15;
    const cy = lerp(950, 560, t);
    const rx = lerp(120, 250, t) * (0.85 + noise(i * 0.4, 55.5) * 0.3);
    blob(800 + (noise(i * 0.37, 61.1) - 0.5) * 60, cy, rx, rx * 1.05, 0.3, i * 0.7 + 70, color(252, 245, 228), 25);
  }
  // teintes de chair : la lumière garde en elle ceux qui l'ont faite
  for (let i = 0; i < 10; i++) {
    const x = 800 + (random() * 2 - 1) * 160;
    const y = lerp(1000, 800, random());
    blob(x, y, random(40, 110), random(50, 120), 0.3, random(100, 160), color(234, 182, 160), random(10, 22));
  }
  // ombres mordant les bords (modelé)
  for (let i = 0; i < 12; i++) {
    const side = random() < 0.5 ? -1 : 1;
    const t = random(0.3, 1);
    const cy = lerp(830, 400, t);
    const lim = lerp(200, 420, t);
    blob(800 + side * (lim + random(10, 90)), cy, random(50, 130), random(60, 150), 0.35, random(200, 260), color(16, 18, 34), random(12, 28));
  }
}

// veines pourpre et or dans la lumière
function dawnVeins() {
  noFill();
  for (let v = 0; v < 16; v++) {
    const gold = random() < 0.5;
    stroke(gold ? color(216, 154, 68) : color(198, 68, 88), random(28, 58));
    strokeWeight(random(1.5, 4));
    beginShape();
    let x = 800 + (random() * 2 - 1) * 190;
    const y0 = 1000, y1 = 460;
    for (let y = y0; y > y1; y -= 16) {
      const t = map(y, y0, y1, 0, 1);
      const lim = lerp(175, 390, pow(t, 1.1));
      x += (noise(y * 0.007 + v * 17.3, v * 2.31) - 0.48) * 26;
      x = lerp(x, 800, 0.02);
      x = constrain(x, 800 - lim, 800 + lim);
      vertex(x, y);
    }
    endShape();
  }
  noStroke();
}

// ---------- fils : la circulation terre-lumière ----------
function threads() {
  noFill();
  stroke(234, 210, 164, 40);
  strokeWeight(1.6);
  shakyBezier(300, groundTop(300) + 10, 200, 1300, 660, 950, 615, 465);
  shakyBezier(1300, groundTop(1300) + 10, 1400, 1300, 940, 950, 985, 465);
  stroke(238, 216, 172, 28);
  strokeWeight(1.2);
  for (let i = 0; i < 3; i++) {
    const x0 = 800 + (i - 1) * 55;
    shakyBezier(x0, 1700, x0 + 80, 1380, 805 - i * 35, 1100, 800 + (i - 1) * 45, 385);
  }
  noStroke();
}

function shakyBezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2) {
  for (let k = 0; k < 3; k++) {
    const jx = () => (random() * 2 - 1) * 1.8;
    bezier(x1 + jx(), y1 + jx() * 0.6, cx1 + jx() * 2, cy1 + jx(), cx2 + jx() * 2, cy2 + jx(), x2 + jx(), y2 + jx() * 0.6);
  }
}

// ---------- le cœur incandescent ----------
function heart() {
  blendMode(ADD);
  noStroke();
  fill(255, 226, 170, 5);
  ellipse(800, 860, 1000, 1150);
  fill(255, 228, 176, 6);
  ellipse(800, 880, 660, 760);
  fill(255, 232, 190, 8);
  ellipse(800, 905, 380, 440);
  fill(255, 240, 214, 26);
  ellipse(800, 922, 250, 175);
  fill(255, 244, 222, 42);
  ellipse(800, 922, 155, 112);
  fill(255, 248, 232, 64);
  ellipse(800, 922, 90, 66);
  fill(255, 252, 240, 115);
  ellipse(800, 922, 44, 34);
  blendMode(BLEND);
}

// ---------- étincelles qui débordent ----------
function particles() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 900; i++) {
    const t = pow(random(), 0.85);
    const y = 930 - t * 880;
    const spread = lerp(50, 560, pow(t, 1.3));
    const x = 800 + (random() + random() + random() - 1.5) * (spread / 1.5);
    const r = lerp(4.6, 1.1, t) * random(0.6, 1.3);
    const a = lerp(78, 14, t) * random(0.5, 1);
    const pick = random();
    if (pick < 0.66) fill(242, 198, 122, a);
    else if (pick < 0.88) fill(255, 246, 228, a);
    else fill(238, 168, 150, a);
    ellipse(x, y, r * 2, r * 2);
  }
  // rares étincelles en croix
  for (let i = 0; i < 16; i++) {
    const t = random(0.05, 0.95);
    const y = 930 - t * 850;
    const spread = lerp(50, 560, pow(t, 1.3));
    const x = 800 + (random() * 2 - 1) * spread * 0.8;
    const s = random(7, 20) * (1 - t * 0.5);
    stroke(255, 248, 226, 55);
    strokeWeight(1.2);
    line(x - s, y, x + s, y);
    line(x, y - s * 1.3, x, y + s * 1.3);
    noStroke();
  }
  blendMode(BLEND);
}

// ---------- finitions ----------
function vignette() {
  noStroke();
  const col = color(2, 3, 8);
  for (let k = 0; k < 30; k++) {
    const a = 26 * pow(1 - k / 30, 2);
    fill(col, a);
    rect(0, k * 3, W, 3);
    rect(0, H - 3 - k * 3, W, 3);
    rect(k * 3, 0, 3, H);
    rect(W - 3 - k * 3, 0, 3, H);
  }
}

function grain() {
  noStroke();
  for (let i = 0; i < 52000; i++) {
    const x = random(W);
    const y = random(H);
    if (random() < 0.5) fill(255, 242, 226, random(3, 9));
    else fill(0, 0, 6, random(4, 12));
    rect(x, y, 1.3, 1.3);
  }
}

// forme organique (bord perturbé par le bruit)
function blob(cx, cy, rx, ry, amp, seed, col, a) {
  noStroke();
  fill(col, a);
  beginShape();
  const n = 72;
  for (let i = 0; i <= n; i++) {
    const t = TWO_PI * i / n;
    const q = noise(cos(t) * 0.9 + seed, sin(t) * 0.9 + seed * 1.7, seed) - 0.5;
    const f = 1 + amp * q * 2;
    vertex(cx + cos(t) * rx * f, cy + sin(t) * ry * f);
  }
  endShape(CLOSE);
}

// « Ce qui naît entre deux » — p5.js 1.11, image fixe 1600 x 2000
// Deux courants (feu / nuit bleue) montent d'une racine commune,
// se tressent sans se fondre, et font naître la lumière à chaque rencontre.

const W = 1600;
const H = 2000;

const EX = 800;            // étreinte — x
const EY = 430;            // étreinte — y
const RY = 1860;           // racine commune — y
const TWIST = 3 * Math.PI; // trois croisements

const WARM_DEEP  = '#4a0d18';
const WARM_DARKS = ['#3a0a14', '#2c0710'];
const WARM_MIDS  = ['#6b1020', '#8f1a24', '#b2302a', '#d94f2b'];
const WARM_HILI  = ['#f08a5a', '#f6b078', '#ffd9a0'];
const COOL_DEEP  = '#0d1c3f';
const COOL_DARKS = ['#091530', '#071028'];
const COOL_MIDS  = ['#12264f', '#1f4d7a', '#2a7f9e', '#4fb3b8'];
const COOL_HILI  = ['#9fdede', '#c8f0ee', '#eafffa'];

const PATH_N = 240;
let warmPts = [];
let coolPts = [];

const COLCACHE = {};

function col(h) {
  let c = COLCACHE[h];
  if (!c) {
    c = [unhex(h.substring(1, 3)), unhex(h.substring(3, 5)), unhex(h.substring(5, 7))];
    COLCACHE[h] = c;
  }
  return c;
}
function cf(h, a) { const c = col(h); fill(c[0], c[1], c[2], a); }
function cs(h, a) { const c = col(h); stroke(c[0], c[1], c[2], a); }
function gauss() { return (random() + random() + random() + random() - 2) * 1.15; }

// ---------- géométrie de la tresse ----------

function amp(t) {
  const s = Math.max(0, Math.sin(Math.PI * t));
  return 430 * Math.pow(s, 0.75);
}
function warpX(t, side) {
  return (noise(t * 2.6 + side * 13.7, side * 3.1) - 0.5) * 150 * Math.sin(Math.PI * t);
}
function warpY(t, side) {
  return (noise(t * 2.2 + side * 5.3, side * 9.4) - 0.5) * 60 * Math.sin(Math.PI * t);
}
function pt(side, t) {
  return {
    x: EX + side * amp(t) * Math.cos(TWIST * t) + warpX(t, side),
    y: RY - t * (RY - EY) + warpY(t, side)
  };
}
function tangent(side, t) {
  const e = 0.004;
  const a = pt(side, Math.max(0, t - e));
  const b = pt(side, Math.min(1, t + e));
  const dx = b.x - a.x, dy = b.y - a.y;
  const L = Math.hypot(dx, dy) || 1;
  return { x: dx / L, y: dy / L };
}
function hw(side, t) {
  const s = Math.max(0, Math.sin(Math.PI * t));
  return 55 + 80 * Math.pow(s, 0.5) + 35 * noise(t * 4.0 + side * 21.3, 4.2);
}

// ---------- setup / draw ----------

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
}

function draw() {
  noLoop();
  paint();
}

function paint() {
  background(6, 7, 16);
  bgGradient();
  atmosphere();
  stars();
  buildPaths();
  ground();
  roots();
  underpaint();
  darkTexture();
  blendMode(ADD);
  innerGlow();
  luminousStrokes();
  filaments();
  ribbonSparkles();
  crossingGlows();
  crown();
  rings();
  lightColumn();
  risingSparks();
  blendMode(BLEND);
  dustMotes();
  vignette();
  grain();
}

// ---------- passes ----------

function buildPaths() {
  warmPts = [];
  coolPts = [];
  for (let i = 0; i <= PATH_N; i++) {
    const t = i / PATH_N;
    warmPts.push(pt(1, t));
    coolPts.push(pt(-1, t));
  }
}

function softCircle(x, y, r, h, a) {
  noStroke();
  const L = 9;
  for (let i = L; i >= 1; i--) {
    const rr = r * i / L;
    cf(h, a / L);
    ellipse(x, y, rr * 2, rr * 2);
  }
}

function bgGradient() {
  noStroke();
  for (let y = 0; y < H; y += 2) {
    const k = y / H;
    fill(lerp(6, 24, k), lerp(7, 13, k), lerp(18, 16, k));
    rect(0, y, W, 2);
  }
}

function atmosphere() {
  softCircle(340, 1520, 680, '#200e1c', 110);
  softCircle(1260, 1520, 680, '#0e1636', 110);
  softCircle(800, 1000, 720, '#150f26', 70);
  softCircle(800, 1850, 520, '#1d0f12', 90);
  softCircle(800, 380, 430, '#1b1226', 55);
}

function stars() {
  noStroke();
  for (let i = 0; i < 420; i++) {
    const x = random(W), y = random(H);
    if (Math.hypot(x - EX, y - EY) < 250) continue;
    const s = random(0.5, 2.1);
    const a = random(10, 55) * (0.4 + 0.6 * noise(x * 0.006, y * 0.006));
    if (random() < 0.75) cf('#cdd8ef', a); else cf('#ffe6c0', a);
    ellipse(x, y, s, s);
  }
}

function ground() {
  noStroke();
  const cols = ['#150b0d', '#1a0e10', '#0f0a12', '#1c1012'];
  for (let y = 1775; y < H; y += 5) {
    const n = noise(y * 0.012, 50.0);
    cf(cols[Math.floor(n * cols.length) % cols.length], 75);
    rect(0, y, W, 6);
  }
  for (let i = 0; i < 480; i++) {
    const x = random(W), y = random(1785, H);
    const len = random(15, 90);
    strokeWeight(random(1, 3));
    cs(random() < 0.6 ? '#2b1712' : '#141020', random(12, 40));
    line(x, y, x + len, y + random(-4, 4));
  }
  noStroke();
}

function roots() {
  blendMode(BLEND);
  noFill();
  for (let i = 0; i < 18; i++) {
    let x = EX + random(-40, 40);
    let y = RY - random(0, 25);
    let ang = HALF_PI + random(-1.15, 1.15);
    cs(random() < 0.55 ? '#43101c' : '#101c38', random(28, 62));
    strokeWeight(random(1, 3.2));
    beginShape();
    vertex(x, y);
    for (let s = 0; s < 16; s++) {
      ang += (noise(i * 3.7 + 1.3, s * 0.33) - 0.5) * 0.95;
      const step = 13 + random(15);
      x += Math.cos(ang) * step;
      y += Math.sin(ang) * step * 1.1;
      vertex(x, y);
    }
    endShape();
  }
  // braise cachée au plus profond de la racine
  blendMode(ADD);
  softCircle(EX, 1950, 130, '#7a2434', 80);
  softCircle(EX, 1950, 42, '#c05568', 70);
  blendMode(BLEND);
}

function underpaint() {
  blendMode(BLEND);
  for (let i = 0; i < warmPts.length; i += 2) {
    const t = i / PATH_N;
    softCircle(warmPts[i].x, warmPts[i].y, hw(1, t) * 2.4, WARM_DEEP, 85);
  }
  for (let i = 0; i < coolPts.length; i += 2) {
    const t = i / PATH_N;
    softCircle(coolPts[i].x, coolPts[i].y, hw(-1, t) * 2.4, COOL_DEEP, 85);
  }
}

function innerGlow() {
  for (let i = 0; i < warmPts.length; i += 3) {
    const t = i / PATH_N;
    softCircle(warmPts[i].x, warmPts[i].y, hw(1, t) * 1.15, '#7a1a26', 30);
  }
  for (let i = 0; i < coolPts.length; i += 3) {
    const t = i / PATH_N;
    softCircle(coolPts[i].x, coolPts[i].y, hw(-1, t) * 1.15, '#1a345e', 30);
  }
}

function darkTexture() {
  blendMode(BLEND);
  strokePass(1, 1400, WARM_DARKS, 14, 38);
  strokePass(-1, 1400, COOL_DARKS, 14, 38);
}

function luminousStrokes() {
  blendMode(ADD);
  strokePass(1, 1800, WARM_MIDS, 20, 52);
  strokePass(-1, 1800, COOL_MIDS, 20, 52);
}

function strokePass(side, n, cols, aMin, aMax) {
  for (let i = 0; i < n; i++) {
    const t = random(0.02, 0.98);
    const p = pt(side, t);
    const tg = tangent(side, t);
    const w = hw(side, t);
    const off = gauss() * w * 0.8;
    const px = p.x - tg.y * off;
    const py = p.y + tg.x * off;
    const edge = Math.min(1, Math.abs(off) / (w * 0.75));
    const ci = Math.min(cols.length - 1, Math.floor((1 - edge) * cols.length));
    const len = random(6, 24);
    const a = random(aMin, aMax) * (1 - 0.5 * edge);
    cs(cols[ci], a);
    strokeWeight(random(1, 3.5));
    line(px - tg.x * len + gauss() * 2, py - tg.y * len + gauss() * 2,
         px + tg.x * len + gauss() * 2, py + tg.y * len + gauss() * 2);
  }
}

function filaments() {
  blendMode(ADD);
  noFill();
  const FS = [-1, -0.7, -0.4, -0.15, 0.15, 0.4, 0.7, 1];
  const sides = [1, -1];
  for (let s = 0; s < 2; s++) {
    const side = sides[s];
    const mids = side === 1 ? WARM_MIDS : COOL_MIDS;
    const hi = side === 1 ? '#ffc890' : '#d8f4f2';
    for (let f = 0; f < FS.length; f++) {
      const k = FS[f];
      const bright = Math.abs(k) < 0.45;
      const c = bright ? hi : mids[Math.min(3, Math.floor(Math.abs(k) * 4))];
      cs(c, bright ? random(26, 40) : random(14, 28));
      strokeWeight(bright ? random(1.2, 2.2) : random(0.7, 1.5));
      beginShape();
      for (let i = 0; i <= 140; i++) {
        const t = i / 140;
        const p = pt(side, t);
        const tg = tangent(side, t);
        const w = hw(side, t);
        const wob = (noise(t * 5.5 + f * 8.1, side * 6.6) - 0.5) * w * 0.5;
        const off = k * w * 0.62 + wob;
        vertex(p.x - tg.y * off, p.y + tg.x * off);
      }
      endShape();
    }
  }
}

function ribbonSparkles() {
  blendMode(ADD);
  const sides = [1, -1];
  for (let s = 0; s < 2; s++) {
    const side = sides[s];
    const cols = side === 1 ? WARM_HILI : COOL_HILI;
    for (let i = 0; i < 500; i++) {
      const t = random(0.02, 0.985);
      const p = pt(side, t);
      const tg = tangent(side, t);
      const w = hw(side, t);
      const off = gauss() * w * 0.45;
      const px = p.x - tg.y * off;
      const py = p.y + tg.x * off;
      const len = random(2.5, 9);
      cs(cols[Math.floor(random(cols.length))], random(16, 44));
      strokeWeight(random(0.8, 2));
      line(px - tg.x * len, py - tg.y * len, px + tg.x * len, py + tg.y * len);
    }
  }
}

function crossingGlows() {
  // lumière née à chaque rencontre
  blendMode(ADD);
  const ts = [1 / 6, 1 / 2, 5 / 6];
  for (let i = 0; i < 3; i++) {
    const t = ts[i];
    const a = pt(1, t), b = pt(-1, t);
    const mx = (a.x + b.x) * 0.5, my = (a.y + b.y) * 0.5;
    const r = 90 + i * 55;
    softCircle(mx, my, r * 1.9, '#7ac0d8', 34);
    softCircle(mx, my, r * 1.35, '#e86a8c', 52);
    softCircle(mx, my, r * 0.8, '#ffb87a', 85);
    softCircle(mx, my, r * 0.38, '#fff0d6', 95);
  }
  softCircle(EX, RY - 20, 85, '#e8a05a', 50);
  softCircle(EX, RY - 20, 30, '#ffe2b0', 60);
}

function crown() {
  // le soleil de l'étreinte finale : or, rose, violet, cyan — les deux en un
  blendMode(ADD);
  softCircle(EX, EY, 640, '#2c2050', 70);
  softCircle(EX, EY, 520, '#4a3878', 80);
  softCircle(EX, EY, 410, '#7a55a8', 75);
  softCircle(EX, EY, 320, '#b070b8', 75);
  softCircle(EX, EY, 245, '#e8829b', 85);
  softCircle(EX, EY, 185, '#f6b078', 95);
  softCircle(EX, EY, 130, '#ffd9a0', 110);
  softCircle(EX, EY, 78, '#fff2d4', 130);
  softCircle(EX, EY, 38, '#fffbef', 165);
}

function rings() {
  // résonances
  blendMode(ADD);
  noFill();
  strokeWeight(2);   cs('#ffd9a0', 20);
  arc(EX, EY, 600, 556, -HALF_PI + 0.25, -HALF_PI + 0.25 + TWO_PI * 0.86);
  strokeWeight(1.6); cs('#d8a8d8', 15);
  arc(EX, EY, 860, 796, HALF_PI * 0.4, HALF_PI * 0.4 + TWO_PI * 0.78);
  strokeWeight(1.2); cs('#a8cce0', 12);
  arc(EX, EY, 1120, 1030, PI + 0.6, PI + 0.6 + TWO_PI * 0.7);
  noStroke();
}

function lightColumn() {
  blendMode(ADD);
  for (let i = 0; i < 26; i++) {
    const y = EY - 14 - i * (EY / 26);
    const r = 130 * (1 - i / 30) + 25;
    softCircle(EX, y, r, '#ffe6bc', 5.5);
  }
}

function risingSparks() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 260; i++) {
    const th = random(-0.45, 0.45) * PI;
    const d = 40 + 900 * Math.pow(random(), 1.35);
    let x = EX + Math.sin(th) * d * (0.55 + d / 1500);
    let y = EY - Math.cos(th) * d * 0.94;
    x += (noise(i * 7.3, 2.2) - 0.5) * 60;
    y += (noise(i * 3.1, 8.8) - 0.5) * 50;
    if (y < 12) continue;
    const fade = Math.max(0.1, 1 - d / 1150);
    const s = random(0.8, 3.4) * (0.5 + fade);
    const a = random(28, 85) * fade;
    const cr = random();
    const c = cr < 0.62 ? '#ffe2b0' : (cr < 0.82 ? '#f2b4c4' : '#b0e4e4');
    if (random() < 0.22 && fade > 0.3) softCircle(x, y, s * 4.5, c, 26);
    cf(c, a);
    ellipse(x, y, s * 2, s * 2);
  }
}

function distToPts(pts, x, y) {
  let m = 1e9;
  for (let i = 0; i < pts.length; i++) {
    const dx = pts[i].x - x, dy = pts[i].y - y;
    const d = Math.sqrt(dx * dx + dy * dy);
    if (d < m) m = d;
  }
  return m;
}

function dustMotes() {
  // la poussière du monde penche vers les deux courants
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 900; i++) {
    const x = random(W), y = random(H);
    const dW = distToPts(warmPts, x, y);
    const dC = distToPts(coolPts, x, y);
    const d = Math.min(dW, dC);
    if (d < 320) {
      const warm = dW < dC;
      const a = 90 * Math.pow(1 - d / 320, 1.6) + 6;
      const s = random(0.7, 2.4);
      if (d < 150) blendMode(ADD);
      cf(warm ? '#f2a678' : '#a4d8dc', a);
      ellipse(x, y, s * 2, s * 2);
      blendMode(BLEND);
    } else {
      cf('#8890b2', random(6, 20));
      const s = random(0.5, 1.5);
      ellipse(x, y, s * 2, s * 2);
    }
  }
}

function vignette() {
  blendMode(BLEND);
  softCircle(-220, -260, 760, '#040409', 150);
  softCircle(W + 220, -260, 760, '#040409', 150);
  softCircle(-220, H + 260, 760, '#040409', 150);
  softCircle(W + 220, H + 260, 760, '#040409', 150);
  softCircle(-340, H / 2, 640, '#040409', 90);
  softCircle(W + 340, H / 2, 640, '#040409', 90);
  softCircle(EX, H + 420, 1000, '#040409', 110);
}

function grain() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 80000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) fill(255, random(3, 8));
    else fill(0, random(4, 10));
    rect(x, y, 1.3, 1.3);
  }
}

const W = 1600;
const H = 2000;
const CX = 800;
const CY = 940;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();
}

function draw() {
  paintBackground();
  softGlow(560, 770, 860, color(255, 118, 105), 15, 22);
  softGlow(1075, 1150, 860, color(106, 100, 255), 15, 22);
  ripples();
  blendMode(ADD);
  drawBlob(612, 852, 432, color(255, 99, 128), 1.7, 0.94, 7);
  drawBlob(1002, 1062, 402, color(128, 110, 255), 4.2, 0.96, 7);
  threads();
  coreGlow();
  particles();
  blendMode(BLEND);
  petals();
  grain();
  vignette();
}

function paintBackground() {
  const top = color(13, 10, 30);
  const mid = color(66, 21, 54);
  const bot = color(15, 8, 24);
  noStroke();
  for (let y = 0; y < H; y += 3) {
    const t = y / H;
    const c = t < 0.5 ? lerpColor(top, mid, t * 2) : lerpColor(mid, bot, (t - 0.5) * 2);
    fill(c);
    rect(0, y, W, 3);
  }
}

function softGlow(x, y, r, c, maxA, step) {
  blendMode(ADD);
  noStroke();
  for (let d = r; d > 0; d -= step) {
    fill(red(c), green(c), blue(c), map(d, 0, r, maxA, 0));
    ellipse(x, y, d * 2, d * 2 * 1.04);
  }
  blendMode(BLEND);
}

function ripples() {
  noFill();
  for (let i = 1; i <= 12; i++) {
    const base = 130 + i * 82;
    stroke(255, 208, 165, map(i, 1, 12, 42, 4));
    strokeWeight(1.1 + (12 - i) * 0.16);
    beginShape();
    for (let a = 0; a <= TWO_PI + 0.05; a += 0.06) {
      const r = base + 30 * noise(cos(a) * 3 + i * 0.71, sin(a) * 3 + i * 0.37);
      vertex(CX + cos(a) * r, CY + sin(a) * r * 1.12);
    }
    endShape(CLOSE);
  }
}

function blobShape(x, y, baseR, off, squash) {
  beginShape();
  for (let a = 0; a <= TWO_PI + 0.04; a += 0.045) {
    const n = noise(cos(a) * 2.2 + off * 13.7, sin(a) * 2.2 + off * 7.9);
    const r = baseR * (0.70 + 0.58 * n);
    vertex(x + cos(a) * r, y + sin(a) * r * squash);
  }
  endShape(CLOSE);
}

function drawBlob(x, y, baseR, c, off, squash, layers) {
  noStroke();
  for (let k = layers; k >= 0; k--) {
    fill(red(c), green(c), blue(c), 9 + (layers - k) * 7.5);
    blobShape(x, y, baseR * (1 + k * 0.085), off, squash);
  }
}

function threads() {
  noFill();
  for (let i = 0; i < 54; i++) {
    const ang = random(TWO_PI);
    const r = random(620, 1520);
    const sx = constrain(CX + cos(ang) * r, 30, W - 30);
    const sy = constrain(CY + sin(ang) * r * 1.15, 30, H - 30);
    const ex = CX + random(-240, 240);
    const ey = CY + random(-240, 240);
    const c1x = lerp(sx, ex, 0.35) + random(-340, 340);
    const c1y = lerp(sy, ey, 0.35) + random(-400, 400);
    const c2x = lerp(sx, ex, 0.7) + random(-260, 260);
    const c2y = lerp(sy, ey, 0.7) + random(-320, 320);
    const c = lerpColor(color(255, 216, 152), color(255, 148, 178), random());
    stroke(red(c), green(c), blue(c), random(24, 78));
    strokeWeight(random(0.6, 2.3));
    bezier(sx, sy, c1x, c1y, c2x, c2y, ex, ey);
  }
}

function coreGlow() {
  noStroke();
  for (let d = 430; d > 0; d -= 13) {
    fill(255, 210, 145, map(d, 0, 430, 78, 0));
    ellipse(CX, CY, d * 2, d * 2 * 1.06);
  }
  for (let d = 150; d > 0; d -= 7) {
    fill(255, 242, 222, map(d, 0, 150, 130, 0));
    ellipse(CX, CY, d * 2, d * 2 * 1.05);
  }
}

function particles() {
  noStroke();
  for (let i = 0; i < 160; i++) {
    const ang = random(TWO_PI);
    const r = pow(random(), 0.62) * 1180;
    const x = CX + cos(ang) * r;
    const y = CY + sin(ang) * r * 1.08;
    if (x < 8 || x > W - 8 || y < 8 || y > H - 8) continue;
    const s = random(1.2, 4.4);
    const c = lerpColor(color(255, 228, 185), color(255, 158, 190), random());
    fill(red(c), green(c), blue(c), 13);
    ellipse(x, y, s * 7, s * 7);
    fill(red(c), green(c), blue(c), 42);
    ellipse(x, y, s * 3.4, s * 3.4);
    fill(255, 246, 236, 215);
    ellipse(x, y, s * 1.35, s * 1.35);
  }
}

function petals() {
  noStroke();
  for (let i = 0; i < 70; i++) {
    push();
    translate(random(W), random(H));
    rotate(random(TWO_PI));
    fill(random() < 0.5 ? color(255, 150, 170, 46) : color(255, 215, 160, 42));
    ellipse(0, 0, random(6, 15), random(3, 7));
    pop();
  }
}

function grain() {
  strokeWeight(1);
  for (let i = 0; i < 22000; i++) {
    const g = random(255);
    stroke(g, g, g, random(3, 9));
    point(random(W), random(H));
  }
}

function vignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(CX, CY, H * 0.26, CX, CY, H * 0.74);
  g.addColorStop(0, 'rgba(4, 2, 10, 0)');
  g.addColorStop(1, 'rgba(4, 2, 10, 0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

let cDeep, cRed, cCoral, cGold, cPale;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  cDeep  = color(122, 16, 46);
  cRed   = color(214, 48, 72);
  cCoral = color(255, 122, 82);
  cGold  = color(255, 205, 120);
  cPale  = color(255, 244, 224);
}

function draw() {
  const ctx = drawingContext;

  // --- fond : dégradé vertical profond ---
  let g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0.0, '#0e0817');
  g.addColorStop(0.45, '#1a0c1d');
  g.addColorStop(0.8, '#241019');
  g.addColorStop(1.0, '#1c0d16');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // --- halo chaud voilé au centre ---
  let halo = ctx.createRadialGradient(width / 2, 930, 80, width / 2, 930, 1150);
  halo.addColorStop(0, 'rgba(96, 34, 46, 0.50)');
  halo.addColorStop(0.55, 'rgba(70, 24, 40, 0.22)');
  halo.addColorStop(1, 'rgba(70, 24, 40, 0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, width, height);

  // --- marbrures de peinture ---
  noStroke();
  for (let i = 0; i < 420; i++) {
    let x = random(width), y = random(height);
    let n = noise(x * 0.0016, y * 0.0016);
    let r = 60 + n * 190;
    if (n > 0.55) fill(255, 120, 90, 5 + n * 9);
    else fill(20, 8, 26, 6 + n * 10);
    ellipse(x, y, r * 2, r * 1.4);
  }

  // --- deux lobes translucides qui se chevauchent ---
  softDisc(628, 860, 430, 'rgba(255, 118, 84, 0.15)', 'rgba(255, 118, 84, 0)');
  softDisc(972, 860, 430, 'rgba(232, 62, 108, 0.15)', 'rgba(232, 62, 108, 0)');

  // --- lumière additive ---
  blendMode(ADD);
  softDisc(800, 930, 560, 'rgba(255, 132, 70, 0.10)', 'rgba(255, 132, 70, 0)');
  softDisc(800, 930, 330, 'rgba(255, 176, 104, 0.20)', 'rgba(255, 176, 104, 0)');
  softDisc(800, 930, 170, 'rgba(255, 216, 152, 0.38)', 'rgba(255, 216, 152, 0)');
  softDisc(800, 930, 80,  'rgba(255, 242, 208, 0.75)', 'rgba(255, 242, 208, 0)');
  softDisc(800, 930, 30,  'rgba(255, 255, 248, 0.95)', 'rgba(255, 255, 248, 0)');

  // --- les deux courants qui se cherchent ---
  paintStream(150, 1930, 40, 1290, 430, 620, 788, 905, 0.0, 2600);
  paintStream(1450, 1930, 1560, 1290, 1170, 620, 812, 905, 7.3, 2600);

  // --- gerbe d'étincelles au-dessus de la jonction ---
  for (let i = 0; i < 380; i++) {
    let x0 = 800 + (noise(i * 0.37) - 0.5) * 420;
    let y0 = 960 + (noise(i * 0.91 + 40) - 0.5) * 220;
    let up = noise(i * 0.53 + 90) * 760;
    let x = x0 + (noise(i * 1.31 + 7) - 0.5) * 190;
    let y = y0 - up;
    let a = map(up, 0, 760, 0.55, 0);
    let s = 1 + noise(i * 2.7) * 2.8;
    let col = lerpColor(cGold, cPale, noise(i * 0.77));
    noStroke();
    fill(red(col), green(col), blue(col), a * 255);
    ellipse(x, y, s, s);
  }

  // --- anneaux dorés ondoyants ---
  for (let k = 0; k < 6; k++) {
    let r0 = 330 + k * 64;
    noFill();
    stroke(255, 205, 130, 14 + k * 4);
    strokeWeight(1.2 + k * 0.35);
    beginShape();
    for (let a = 0; a <= TWO_PI + 0.05; a += 0.045) {
      let rr = r0 + (noise(cos(a) * 1.6 + k * 9, sin(a) * 1.6 + k * 3) - 0.5) * 30;
      vertex(800 + cos(a) * rr, 930 + sin(a) * rr * 1.06);
    }
    endShape(CLOSE);
  }

  // --- poussière dorée ---
  for (let i = 0; i < 750; i++) {
    let x = random(width), y = random(height);
    let d = dist(x, y, 800, 930);
    let a = map(d, 0, 1300, 0.16, 0.02, true);
    noStroke();
    fill(255, 224, 170, a * 255);
    ellipse(x, y, random(1, 2.4), random(1, 2.4));
  }
  blendMode(BLEND);

  // --- grain de toile ---
  for (let i = 0; i < 11000; i++) {
    let x = random(width), y = random(height);
    if (random() < 0.5) fill(0, 0, 0, random(4, 12));
    else fill(255, 240, 220, random(3, 9));
    noStroke();
    rect(x, y, 1.2, 1.2);
  }

  // --- vignettage ---
  let v = ctx.createRadialGradient(800, 980, 480, 800, 980, 1420);
  v.addColorStop(0, 'rgba(6, 3, 10, 0)');
  v.addColorStop(0.7, 'rgba(6, 3, 10, 0.28)');
  v.addColorStop(1, 'rgba(5, 2, 9, 0.82)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, width, height);
}

function softDisc(cx, cy, r, cIn, cOut) {
  const ctx = drawingContext;
  let gr = ctx.createRadialGradient(cx, cy, r * 0.04, cx, cy, r);
  gr.addColorStop(0, cIn);
  gr.addColorStop(1, cOut);
  ctx.fillStyle = gr;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, TWO_PI);
  ctx.fill();
}

function streamColor(t) {
  if (t < 0.33) return lerpColor(cDeep, cRed, t / 0.33);
  if (t < 0.66) return lerpColor(cRed, cCoral, (t - 0.33) / 0.33);
  return lerpColor(cCoral, cGold, (t - 0.66) / 0.34);
}

function paintStream(ax, ay, bx, by, cx, cy, dx, dy, seedOff, n) {
  for (let i = 0; i < n; i++) {
    let t = pow(i / (n - 1), 0.9);
    let px = bezierPoint(ax, bx, cx, dx, t);
    let py = bezierPoint(ay, by, cy, dy, t);
    let tx = bezierTangent(ax, bx, cx, dx, t);
    let ty = bezierTangent(ay, by, cy, dy, t);
    let tl = sqrt(tx * tx + ty * ty) || 1;
    tx /= tl; ty /= tl;
    let nx = -ty, ny = tx;
    let spread = 1.15 - t * 0.8;
    let off = ((noise(t * 4 + seedOff) - 0.5) * 240 + (noise(t * 11 + seedOff * 2.7) - 0.5) * 90) * spread;
    let x = px + nx * off;
    let y = py + ny * off;
    let col = streamColor(t);
    let jit = noise(i * 0.13 + seedOff * 5);
    let a = (0.05 + jit * 0.16) * (0.35 + t * 0.65);
    let len = 5 + jit * 14;
    let w = 1 + jit * 3.4;
    stroke(red(col), green(col), blue(col), a * 255);
    strokeWeight(w);
    strokeCap(ROUND);
    line(x, y, x + tx * len, y + ty * len);
    if (i % 7 === 0) {
      noStroke();
      fill(red(col), green(col), blue(col), a * 0.9 * 255);
      ellipse(x, y, w * 1.6, w * 1.6);
    }
  }
  // touches larges et douces le long du courant
  for (let i = 0; i < 130; i++) {
    let t = random();
    let px = bezierPoint(ax, bx, cx, dx, t);
    let py = bezierPoint(ay, by, cy, dy, t);
    let tx = bezierTangent(ax, bx, cx, dx, t);
    let ty = bezierTangent(ay, by, cy, dy, t);
    let tl = sqrt(tx * tx + ty * ty) || 1;
    let off = (noise(t * 5 + seedOff * 3) - 0.5) * 200 * (1.15 - t * 0.8);
    let x = px + (-ty / tl) * off;
    let y = py + (tx / tl) * off;
    let col = streamColor(t);
    noStroke();
    fill(red(col), green(col), blue(col), random(8, 20));
    ellipse(x, y, random(14, 42), random(10, 30));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // fond : nuit profonde virant au bordeaux
  blendMode(BLEND);
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let n = noise(y * 0.0016, 7.3) - 0.5;
    let c = lerpColor(color(9, 7, 20), color(34, 12, 22), constrain(t + n * 0.35, 0, 1));
    fill(c);
    rect(0, y, width, 2);
  }

  // halos lointains
  glow(500, 940, 760, color(110, 18, 58), 20);
  glow(1100, 880, 740, color(150, 62, 18), 20);

  // les deux présences
  presence(500, 940, 560, color(196, 30, 84), color(255, 120, 150));
  presence(1100, 880, 505, color(235, 110, 40), color(255, 205, 130));
  strokes(500, 940, 540, color(255, 170, 190));
  strokes(1100, 880, 485, color(255, 220, 160));

  // bloom de chaque présence
  glow(500, 940, 300, color(255, 150, 170), 42);
  glow(1100, 880, 300, color(255, 210, 150), 42);

  // filaments qui relient
  filaments();

  // la lumière née de la rencontre
  glow(800, 910, 520, color(255, 232, 196), 95);
  glow(800, 910, 240, color(255, 246, 226), 120);

  // anneaux d'émanation
  noFill();
  for (let i = 0; i < 6; i++) {
    let r = 250 + i * 78 + noise(i * 3.7, 2.2) * 34;
    stroke(255, 224, 186, max(4, 30 - i * 4));
    strokeWeight(1.5 + noise(i * 1.3) * 3);
    ellipse(800, 910, r * 2, r * 1.92);
  }

  // braises qui montent
  embers();

  // grain de toile
  grain();

  // vignettage
  vignette();
}

function presence(cx, cy, maxR, outer, inner) {
  blendMode(BLEND);
  noStroke();
  for (let r = maxR; r > 0; r -= 2.5) {
    let t = 1 - r / maxR;
    let col = lerpColor(outer, inner, t);
    let a = map(r, maxR, 0, 6, 46) * (0.55 + 0.9 * noise(r * 0.045, cx * 0.001));
    let ox = (noise(r * 0.03, cy * 0.001) - 0.5) * 34;
    let oy = (noise(r * 0.027 + 40, cx * 0.001) - 0.5) * 34;
    fill(red(col), green(col), blue(col), a);
    beginShape();
    let steps = 64;
    for (let i = 0; i <= steps; i++) {
      let ang = (i / steps) * TWO_PI;
      let wob = noise(cos(ang) * 1.7 + cx * 0.0015 + r * 0.012,
                      sin(ang) * 1.7 + cy * 0.0015 - r * 0.012);
      let rr = r * (0.76 + 0.36 * wob);
      vertex(cx + ox + cos(ang) * rr, cy + oy + sin(ang) * rr * 0.97);
    }
    endShape(CLOSE);
  }
}

function glow(cx, cy, maxR, col, maxA) {
  blendMode(ADD);
  noStroke();
  for (let r = maxR; r > 0; r -= 5) {
    let a = map(r, maxR, 0, 0, maxA) * (0.75 + 0.5 * noise(r * 0.02, cx * 0.002));
    fill(red(col), green(col), blue(col), a);
    circle(cx + (noise(r * 0.014, 3.1) - 0.5) * 22,
           cy + (noise(r * 0.018, 8.7) - 0.5) * 22, r * 2);
  }
  blendMode(BLEND);
}

function strokes(cx, cy, maxR, col) {
  blendMode(BLEND);
  noFill();
  for (let i = 0; i < 850; i++) {
    let ang = random(TWO_PI);
    let r = maxR * sqrt(random()) * 0.98;
    let x = cx + cos(ang) * r;
    let y = cy + sin(ang) * r * 0.97;
    let len = random(10, 42);
    stroke(red(col), green(col), blue(col), random(8, 34));
    strokeWeight(random(1, 3.2));
    let ta = ang + PI / 2 + random(-0.5, 0.5);
    line(x, y, x + cos(ta) * len, y + sin(ta) * len);
  }
}

function filaments() {
  blendMode(BLEND);
  noFill();
  for (let i = 0; i < 46; i++) {
    let x0 = random(340, 780);
    let y0 = 910 + randomGaussian() * 170;
    let x1 = random(820, 1260);
    let y1 = 910 + randomGaussian() * 170;
    let col = lerpColor(color(255, 150, 175), color(255, 222, 150), random());
    stroke(red(col), green(col), blue(col), random(45, 115));
    strokeWeight(random(0.8, 2.6));
    thread(x0, y0, x1, y1, i * 0.61);
  }
  for (let i = 0; i < 110; i++) {
    let x0 = random(width * 0.1, width * 0.62);
    let y0 = random(height * 0.28, height * 0.74);
    let x1 = random(width * 0.38, width * 0.9);
    let y1 = random(height * 0.26, height * 0.72);
    let col = lerpColor(color(255, 120, 150), color(255, 200, 130), random());
    stroke(red(col), green(col), blue(col), random(10, 42));
    strokeWeight(random(0.5, 1.8));
    thread(x0, y0, x1, y1, i * 0.37 + 11);
  }
}

function thread(x0, y0, x1, y1, seed) {
  beginShape();
  let steps = 32;
  for (let s = 0; s <= steps; s++) {
    let t = s / steps;
    let x = lerp(x0, x1, t);
    let y = lerp(y0, y1, t) + (noise(x * 0.0035, y * 0.0035, seed) - 0.5) * 200 * sin(PI * t);
    vertex(x, y);
  }
  endShape();
}

function embers() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 520; i++) {
    let x = 800 + randomGaussian() * 340;
    let y = 910 + randomGaussian() * 400 - random(0, 320);
    let d = dist(x, y, 800, 910);
    let a = map(d, 50, 950, 170, 5, true);
    let col = lerpColor(color(255, 242, 214), color(255, 130, 150), random());
    let s = random(1, 4.5);
    fill(red(col), green(col), blue(col), a * 0.22);
    circle(x, y, s * 3.2);
    fill(red(col), green(col), blue(col), a);
    circle(x, y, s);
  }
  blendMode(BLEND);
}

function grain() {
  blendMode(BLEND);
  strokeWeight(1);
  for (let i = 0; i < 26000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.5) stroke(255, 240, 230, random(2, 7));
    else stroke(2, 2, 8, random(2, 9));
    point(x, y);
  }
}

function vignette() {
  blendMode(BLEND);
  noStroke();
  for (let r = 1780; r > 760; r -= 6) {
    let a = map(r, 1780, 760, 0, 135);
    fill(4, 2, 9, a);
    circle(width / 2, height / 2, r * 2);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  const cx = 800, cy = 960, S = 42;

  // fond : dégradé profond
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(16, 4, 11), color(72, 15, 33), pow(t, 1.25));
    stroke(c);
    strokeWeight(1);
    line(0, y, width, y);
  }
  noStroke();

  // halos flottants
  blendMode(ADD);
  const haloCols = [color(255,150,140), color(255,190,120), color(215,80,110), color(255,120,140)];
  for (let i = 0; i < 16; i++) {
    let c = random(haloCols);
    c.setAlpha(random(5, 16));
    fill(c);
    circle(random(width), random(height), random(240, 860));
  }
  blendMode(BLEND);

  // grandes traînées diagonales en arrière-plan
  trail(-100, 300, 500, 900, 1100, 1400, 1750, 1700, color(120, 20, 50), 7, 0.9);
  trail(1700, 1700, 1200, 1200, 500, 700, -100, 200, color(90, 25, 60), 7, 0.8);

  // cœur lumineux en couches superposées
  for (let l = 0; l < 12; l++) {
    let f = l / 12;
    let col = lerpColor(color(110, 8, 32), color(240, 75, 105), f);
    col.setAlpha(9 + (1 - f) * 9);
    fill(col);
    heartShape(cx, cy, S * (1.12 - f * 0.17));
  }

  // deux rubans entrelacés qui tracent le cœur
  ribbon(cx, cy, S * 1.04, color(198, 28, 68), color(255, 192, 96), 0.0, 10, 0.17);
  ribbon(cx, cy, S * 0.95, color(255, 112, 142), color(255, 242, 222), PI, 10, 0.14);

  // noyau incandescent au point de rencontre
  blendMode(ADD);
  for (let r = 460; r > 0; r -= 13) {
    let t = r / 460;
    let c = lerpColor(color(255, 252, 240), color(255, 138, 88), t);
    c.setAlpha(4 + (1 - t) * 16);
    fill(c);
    circle(cx, cy, r * 2);
  }
  fill(255, 244, 214, 190);
  circle(cx, cy, 110);
  fill(255, 255, 248, 235);
  circle(cx, cy, 42);
  blendMode(BLEND);

  // étincelles
  const sparkCols = [color(255,214,150), color(255,152,162), color(255,242,214), color(232,92,122), color(255,186,110)];
  blendMode(ADD);
  for (let i = 0; i < 380; i++) {
    let a = random(TWO_PI);
    let rr = pow(random(1), 0.55) * 820;
    let x = cx + cos(a) * rr * 1.12;
    let y = cy - sin(a) * rr * 0.92;
    if (x < 0 || x > width || y < 0 || y > height) continue;
    let s = random(1.5, 6.5);
    let c = random(sparkCols);
    c.setAlpha(random(30, 130));
    fill(c);
    circle(x, y, s * 3.2);
    c.setAlpha(random(130, 240));
    circle(x, y, s);
  }
  blendMode(BLEND);

  // grain de peinture
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (noise(i * 0.00013, i * 0.00007) - 0.5) * 15;
    pixels[i]     = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();

  // vignettage
  let ctx = drawingContext;
  let vg = ctx.createRadialGradient(cx, cy, 480, cx, cy, 1280);
  vg.addColorStop(0, 'rgba(8,2,6,0)');
  vg.addColorStop(1, 'rgba(8,2,6,0.88)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

function heartXY(a, cx, cy, s) {
  let x = 16 * pow(sin(a), 3);
  let y = 13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a);
  return [cx + x * s, cy - y * s];
}

function heartShape(cx, cy, s) {
  beginShape();
  for (let i = 0; i <= 180; i++) {
    let p = heartXY((i / 180) * TWO_PI, cx, cy, s);
    vertex(p[0], p[1]);
  }
  endShape(CLOSE);
}

function ribbon(cx, cy, s, colA, colB, phase, layers, wobAmp) {
  noFill();
  let steps = 260;
  for (let l = 0; l < layers; l++) {
    let f = l / layers;
    let col = lerpColor(colA, colB, f);
    col.setAlpha(7 + (1 - f) * 10);
    stroke(col);
    strokeWeight(60 - l * 5.2 + noise(l * 9.31 + phase) * 18);
    beginShape();
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = t * TWO_PI + phase;
      let w = 1 + (noise(t * 7 + l * 13.7 + phase * 3.1) - 0.5) * wobAmp * (0.4 + f);
      let p = heartXY(a, cx, cy, s * w);
      vertex(p[0], p[1]);
    }
    endShape(CLOSE);
  }
}

function trail(x0, y0, x1, y1, x2, y2, x3, y3, col, layers, wob) {
  noFill();
  for (let l = 0; l < layers; l++) {
    let f = l / layers;
    let c = lerpColor(col, color(255, 120, 130), f * 0.4);
    c.setAlpha(6 + (1 - f) * 7);
    stroke(c);
    strokeWeight(70 - l * 8 + noise(l * 5.7) * 20);
    beginShape();
    for (let i = 0; i <= 80; i++) {
      let t = i / 80;
      let x = bezierPoint(x0, x1, x2, x3, t) + (noise(t * 4 + l * 11) - 0.5) * 90 * wob;
      let y = bezierPoint(y0, y1, y2, y3, t) + (noise(t * 4 + l * 23 + 50) - 0.5) * 90 * wob;
      vertex(x, y);
    }
    endShape();
  }
}

const W = 1600, H = 2000;
const CX = W / 2, CY = H / 2;

let warmCols, coolCols, bloomCols;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();

  warmCols  = ['#ffd166', '#ffb347', '#ff8c42', '#ff6b4a', '#ff2e63', '#c9184a'].map(h => color(h));
  coolCols  = ['#80ffdb', '#4cc9f0', '#4895ef', '#4361ee', '#7b2cbf', '#b5179e'].map(h => color(h));
  bloomCols = ['#fff7e6', '#ffe8d6', '#ffd6e0', '#ffc2d1', '#e0aaff'].map(h => color(h));

  paint();
}

function pick(arr) { return arr[floor(random(arr.length))]; }

function colorAt(x, y) {
  let u = (x / W + (1 - y / H)) / 2;                 // 0 = bas-gauche (chaud), 1 = haut-droite (froid)
  u += (noise(x * 0.0018, y * 0.0018, 7.3) - 0.5) * 0.55;
  u = constrain(u, 0, 1);
  let col = lerpColor(pick(warmCols), pick(coolCols), u);
  let d = dist(x, y, CX, CY) / (W * 0.5);             // proximité du point de rencontre
  if (d < 1) col = lerpColor(col, pick(bloomCols), (1 - d) * (1 - d) * 0.85);
  return col;
}

function softBlob(x, y, r, col, a) {
  let g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + floor(red(col)) + ',' + floor(green(col)) + ',' + floor(blue(col)) + ',' + a + ')');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(x - r, y - r, r * 2, r * 2);
}

function flowStrokes(n, maxSteps, wMin, wMax, alpha) {
  noFill();
  for (let i = 0; i < n; i++) {
    let x = random(W), y = random(H);
    let c = colorAt(x, y);
    let steps = floor(random(4, maxSteps));
    stroke(red(c), green(c), blue(c), random(alpha * 0.35, alpha));
    strokeWeight(random(wMin, wMax));
    beginShape();
    for (let s = 0; s < steps; s++) {
      vertex(x, y);
      let a = noise(x * 0.0016, y * 0.0016, 3.7) * TWO_PI * 2.4;
      x += cos(a) * random(5, 13);
      y += sin(a) * random(5, 13);
    }
    endShape();
  }
}

function dabs(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(W), y = random(H);
    let c = colorAt(x, y);
    let w = random(2, 9);
    fill(red(c), green(c), blue(c), random(25, 80));
    ellipse(x, y, w, w * random(0.5, 1), random(PI));
  }
}

function glowStrokes(n, maxSteps, wMin, wMax, alpha) {
  noFill();
  for (let i = 0; i < n; i++) {
    let x = constrain(CX + (random() + random() - 1) * W * 0.45, 0, W);
    let y = constrain(CY + (random() + random() - 1) * H * 0.45, 0, H);
    let c = lerpColor(colorAt(x, y), color(255, 250, 238), random(0.25, 0.75));
    let steps = floor(random(3, maxSteps));
    stroke(red(c), green(c), blue(c), random(alpha * 0.5, alpha));
    strokeWeight(random(wMin, wMax));
    beginShape();
    for (let s = 0; s < steps; s++) {
      vertex(x, y);
      let a = noise(x * 0.002, y * 0.002, 11.1) * TWO_PI * 2.2;
      x += cos(a) * random(4, 10);
      y += sin(a) * random(4, 10);
    }
    endShape();
  }
}

function ribbon(x1, y1, x2, y2, col, wBase, aScale) {
  noFill();
  for (let i = 0; i < 30; i++) {
    let t = i / 30;
    stroke(red(col), green(col), blue(col), random(4, 14) * aScale);
    strokeWeight(wBase * (1 - t * 0.85) + 1);
    bezier(
      x1 + random(-50, 50), y1 + random(-50, 50),
      lerp(x1, x2, 0.33) + random(-140, 140), lerp(y1, y2, 0.33) + random(-140, 140),
      lerp(x1, x2, 0.66) + random(-140, 140), lerp(y1, y2, 0.66) + random(-140, 140),
      x2 + random(-60, 60), y2 + random(-60, 60)
    );
  }
}

function bloom(x, y, r) {
  let g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0.00, 'rgba(255,246,230,0.85)');
  g.addColorStop(0.12, 'rgba(255,214,170,0.55)');
  g.addColorStop(0.30, 'rgba(255,150,170,0.30)');
  g.addColorStop(0.55, 'rgba(190,110,255,0.16)');
  g.addColorStop(0.80, 'rgba(90,60,200,0.06)');
  g.addColorStop(1.00, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(x - r, y - r, r * 2, r * 2);

  let g2 = drawingContext.createRadialGradient(x, y, 0, x, y, r * 0.28);
  g2.addColorStop(0, 'rgba(255,255,255,0.95)');
  g2.addColorStop(0.4, 'rgba(255,240,220,0.5)');
  g2.addColorStop(1, 'rgba(255,220,180,0)');
  drawingContext.fillStyle = g2;
  drawingContext.fillRect(x - r * 0.28, y - r * 0.28, r * 0.56, r * 0.56);
}

function motes(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x, y;
    if (random() < 0.62) {
      x = CX + (random() + random() + random() - 1.5) * W * 0.6;
      y = CY + (random() + random() + random() - 1.5) * H * 0.6;
    } else {
      x = random(W); y = random(H);
    }
    x = constrain(x, 0, W); y = constrain(y, 0, H);
    let c = colorAt(x, y);
    let s = random(1, 5.5);
    fill(red(c), green(c), blue(c), 30);
    ellipse(x, y, s * 4.5, s * 4.5);
    fill(255, 250, 240, random(110, 230));
    ellipse(x, y, s, s);
  }
}

function vignette() {
  let g = drawingContext.createRadialGradient(CX, CY, H * 0.35, CX, CY, H * 0.85);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(4,0,12,0.6)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function grain(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let v = random(255);
    fill(v, v, v, random(4, 10));
    rect(random(W), random(H), 1.5, 1.5);
  }
}

function paint() {
  background(11, 6, 28);

  // halos profonds : les deux présences avant la rencontre
  softBlob(W * 0.12, H * 0.92, 950, color(160, 40, 80), 0.35);
  softBlob(W * 0.90, H * 0.06, 950, color(40, 70, 190), 0.35);
  softBlob(CX, CY, 800, color(90, 30, 120), 0.28);
  softBlob(W * 0.5, H * 0.55, 500, color(255, 120, 90), 0.10);

  // nébuleuse de touches
  noStroke();
  for (let i = 0; i < 500; i++) {
    let c = random() < 0.5 ? pick(warmCols) : pick(coolCols);
    fill(red(c), green(c), blue(c), random(3, 9));
    ellipse(random(W), random(H), random(20, 140), random(20, 140));
  }

  // grands balayages courbes
  noFill();
  for (let i = 0; i < 40; i++) {
    let c = pick(warmCols.concat(coolCols));
    stroke(red(c), green(c), blue(c), random(6, 18));
    strokeWeight(random(0.6, 2));
    bezier(random(-200, W * 0.4), random(H),
           W * random(0.3, 0.7), random(H),
           W * random(0.6, 1.2), random(H),
           random(W * 0.8, W + 200), random(H));
  }

  // peinture : champs de traits
  flowStrokes(2400, 14, 1, 4.5, 90);
  flowStrokes(900, 22, 2, 7, 60);
  dabs(1600);

  // rubans lumineux convergeant vers le centre
  blendMode(ADD);
  ribbon(W * 0.06, H * 0.97, CX, CY, color(255, 110, 80), 90, 0.5);
  ribbon(W * 0.94, H * 0.03, CX, CY, color(90, 140, 255), 90, 0.5);
  ribbon(W * 0.02, H * 0.55, CX, CY, color(255, 190, 90), 50, 0.35);
  ribbon(W * 0.98, H * 0.45, CX, CY, color(150, 80, 255), 50, 0.35);

  glowStrokes(700, 16, 2, 6, 70);

  // la rencontre : floraison centrale
  bloom(CX, CY, 620);

  // anneaux d'énergie
  noFill();
  for (let i = 0; i < 26; i++) {
    let r = random(120, 640);
    let c = pick(warmCols.concat(coolCols, bloomCols));
    stroke(red(c), green(c), blue(c), random(12, 45));
    strokeWeight(random(0.8, 2.6));
    push();
    translate(CX + random(-40, 40), CY + random(-40, 40));
    rotate(random(PI));
    ellipse(0, 0, r * 2 * random(0.9, 1.1), r * 2 * random(0.8, 1.2));
    pop();
  }

  // poussières de lumière
  motes(240);

  blendMode(BLEND);
  vignette();
  grain(7000);
}

