function pigment(path, base, light, count) {
  const c = drawingContext;
  c.save();
  c.beginPath();
  path(c);
  c.fillStyle = base;
  c.fill();
  c.clip();

  noStroke();
  for (let i = 0; i < count; i++) {
    const x = random(100, 1500);
    const y = random(210, 2010);
    const n = noise(x * 0.006, y * 0.004);
    if (i % 4 === 0) {
      fill(17, 35, 40, random(3, 16));
    } else {
      fill(light[0], light[1], light[2], random(5, 23) * n);
    }
    ellipse(x, y, random(2, 17), random(5, 39));
  }

  for (let i = 0; i < count / 35; i++) {
    const x = random(100, 1500), y = random(210, 2010);
    stroke(light[0], light[1], light[2], random(5, 16));
    strokeWeight(random(0.7, 2.5));
    line(x, y, x + random(-9, 9), y + random(15, 90));
  }
  c.restore();
}

function brushCurve(p, rgb, weight, passes) {
  noFill();
  for (let i = 0; i < passes; i++) {
    stroke(rgb[0], rgb[1], rgb[2], random(12, 36));
    strokeWeight(weight * random(0.45, 1.25));
    const dx = random(-2.5, 2.5), dy = random(-2, 2);
    bezier(
      p[0] + dx, p[1] + dy,
      p[2] + dx, p[3] + dy,
      p[4] + dx, p[5] + dy,
      p[6] + dx, p[7] + dy
    );
  }
}

function garmentMarks(mirrored) {
  push();
  if (mirrored) {
    translate(1600, 0);
    scale(-1, 1);
  }
  const rgb = mirrored ? [111, 163, 160] : [226, 137, 86];
  for (let i = 0; i < 55; i++) {
    const x = random(235, 540);
    const y = random(1170, 1900);
    brushCurve(
      [x, y, x - 25, y + 70, x - 35, y + 140, x - 20, y + 200],
      rgb, random(2, 11), 2
    );
  }
  brushCurve(
    [292, 1740, 304, 1475, 337, 1200, 484, 1056],
    rgb, 20, 8
  );
  pop();
}

const W = 1600, H = 2000;
const WIN = { x: 1050, y: 1090, w: 90, h: 80 };
const GLOW = { x: 1095, y: 1130 };

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function skyCol(y) {
  const t = constrain(y / 1150, 0, 1);
  return lerpColor(color(9, 14, 42), color(44, 58, 104), pow(t, 1.4));
}

function groundCol(y) {
  const t = constrain((y - 1100) / 900, 0, 1);
  return lerpColor(color(108, 124, 166), color(170, 184, 214), t);
}

function draw() {
  // --- Ciel ---
  for (let y = 0; y < 1300; y++) {
    stroke(skyCol(y));
    line(0, y, W, y);
  }
  for (let i = 0; i < 9000; i++) {
    const x = random(W), y = random(0, 1200);
    const c = skyCol(y);
    const v = random(-10, 12);
    stroke(red(c) + v, green(c) + v, blue(c) + v * 1.5, 55);
    strokeWeight(random(2, 6));
    const a = (noise(x * 0.002, y * 0.002) - 0.5) * 0.8;
    const l = random(20, 70);
    line(x, y, x + cos(a) * l, y + sin(a) * l);
  }
  // Étoiles
  noStroke();
  for (let i = 0; i < 260; i++) {
    const x = random(W), y = random(0, 950);
    const s = random(1, 3.2);
    fill(230, 235, 255, random(60, 200) * (1 - y / 1100));
    ellipse(x, y, s, s);
  }

  // --- Colline lointaine / forêt ---
  fill(32, 42, 78);
  beginShape();
  vertex(0, 1400);
  for (let x = 0; x <= W; x += 10) {
    vertex(x, 1060 + noise(x * 0.002) * 80);
  }
  vertex(W, 1400);
  endShape(CLOSE);
  // petits sapins
  for (let i = 0; i < 140; i++) {
    const x = random(W);
    const base = 1060 + noise(x * 0.002) * 80 + 8;
    const h = random(25, 70);
    fill(20, 28, 58, 230);
    triangle(x - h * 0.22, base, x + h * 0.22, base, x, base - h);
  }

  // --- Champ de neige ---
  for (let y = 1100; y < H; y++) {
    stroke(groundCol(y));
    line(0, y, W, y);
  }
  // bord du champ irrégulier : recouvre le bas de la forêt
  noStroke();
  fill(groundCol(1150));
  beginShape();
  vertex(0, 1260);
  for (let x = 0; x <= W; x += 10) {
    vertex(x, 1150 + noise(x * 0.0015 + 10) * 50);
  }
  vertex(W, 1260);
  endShape(CLOSE);
  for (let i = 0; i < 9000; i++) {
    const x = random(W), y = random(1170, H);
    const c = groundCol(y);
    const v = random(-12, 16);
    stroke(red(c) + v, green(c) + v, blue(c) + v, 60);
    strokeWeight(random(2, 7) * map(y, 1170, H, 0.5, 1.4));
    const a = (noise(x * 0.003, y * 0.003, 5) - 0.5) * 0.35;
    const l = random(30, 110) * map(y, 1170, H, 0.4, 1.3);
    line(x, y, x + cos(a) * l, y + sin(a) * l);
  }
  // ombres douces des congères
  for (let i = 0; i < 40; i++) {
    const x = random(W), y = random(1300, H);
    noStroke();
    fill(80, 96, 140, 25);
    ellipse(x, y, random(200, 600), random(20, 60));
  }

  // --- Maison ---
  noStroke();
  // ombre au sol
  fill(70, 85, 128, 90);
  ellipse(1040, 1255, 460, 40);
  // murs
  fill(26, 32, 58);
  rect(860, 1010, 340, 240);
  // cheminée
  fill(24, 30, 54);
  rect(1120, 880, 40, 90);
  fill(190, 202, 228);
  rect(1116, 872, 48, 12, 4);
  // fumée
  for (let i = 0; i < 60; i++) {
    const t = i / 60;
    const sx = 1140 + sin(t * 5) * 30 + t * 120;
    const sy = 860 - t * 320;
    fill(120, 135, 175, 18 * (1 - t));
    ellipse(sx, sy, 30 + t * 90, 25 + t * 70);
  }
  // toit enneigé
  fill(18, 22, 42);
  rect(845, 1008, 370, 14);
  fill(178, 192, 224);
  triangle(822, 1014, 1238, 1014, 1030, 842);
  fill(205, 215, 238, 160);
  triangle(870, 1006, 1030, 862, 1000, 1006);
  // porte
  fill(16, 20, 38);
  rect(900, 1130, 62, 120, 3, 3, 0, 0);
  fill(255, 175, 90, 60);
  rect(960, 1134, 3, 114);

  // --- Halo de la lampe ---
  noStroke();
  for (let i = 0; i < 70; i++) {
    const d = map(i, 0, 70, 1000, 60);
    fill(255, 172, 85, 2.6);
    ellipse(GLOW.x, GLOW.y, d, d * 0.95);
  }
  // lumière déversée sur la neige
  for (let i = 0; i < 14; i++) {
    const k = i / 14;
    fill(255, 180, 100, 9);
    quad(WIN.x + 5, 1250, WIN.x + WIN.w - 5, 1250,
         1290 - k * 120, 1460 - k * 120, 960 + k * 90, 1460 - k * 120);
  }
  // fenêtre
  fill(255, 196, 110);
  rect(WIN.x, WIN.y, WIN.w, WIN.h);
  fill(255, 230, 170, 200);
  ellipse(GLOW.x - 10, GLOW.y + 5, 50, 40);
  stroke(30, 26, 40);
  strokeWeight(6);
  line(WIN.x + WIN.w / 2, WIN.y, WIN.x + WIN.w / 2, WIN.y + WIN.h);
  line(WIN.x, WIN.y + WIN.h / 2, WIN.x + WIN.w, WIN.y + WIN.h / 2);
  noFill();
  strokeWeight(8);
  stroke(20, 22, 40);
  rect(WIN.x, WIN.y, WIN.w, WIN.h);
  // neige sur le rebord
  noStroke();
  fill(215, 222, 240);
  rect(WIN.x - 8, WIN.y + WIN.h + 2, WIN.w + 16, 8, 4);

  // --- Empreintes de pas ---
  const P = [[360, 2060], [160, 1720], [1150, 1520], [935, 1256]];
  let acc = 0, side = 1;
  let px = bezierPoint(P[0][0], P[1][0], P[2][0], P[3][0], 0);
  let py = bezierPoint(P[0][1], P[1][1], P[2][1], P[3][1], 0);
  for (let i = 1; i <= 3000; i++) {
    const t = i / 3000;
    const x = bezierPoint(P[0][0], P[1][0], P[2][0], P[3][0], t);
    const y = bezierPoint(P[0][1], P[1][1], P[2][1], P[3][1], t);
    acc += dist(px, py, x, y);
    px = x; py = y;
    const s = map(y, 1256, 2000, 0.22, 1.45);
    if (acc >= 62 * s && t < 0.985) {
      acc = 0;
      const tx = bezierTangent(P[0][0], P[1][0], P[2][0], P[3][0], t);
      const ty = bezierTangent(P[0][1], P[1][1], P[2][1], P[3][1], t);
      const a = atan2(ty, tx);
      const ox = cos(a + HALF_PI) * 14 * s * side;
      const oy = sin(a + HALF_PI) * 14 * s * side * 0.6;
      const warm = constrain(map(dist(x, y, 1100, 1350), 0, 320, 1, 0), 0, 1);
      push();
      translate(x + ox, y + oy);
      rotate(a);
      scale(1, 0.55 + 0.45 * map(y, 1256, 2000, 0, 1));
      noStroke();
      const sh = lerpColor(color(70, 84, 128), color(150, 110, 90), warm * 0.6);
      fill(red(sh), green(sh), blue(sh), 200);
      ellipse(0, 0, 36 * s, 16 * s);
      ellipse(-22 * s, 0, 16 * s, 12 * s);
      const hl = lerpColor(color(220, 230, 246), color(255, 220, 170), warm);
      fill(red(hl), green(hl), blue(hl), 130);
      ellipse(2 * s, 5 * s, 30 * s, 5 * s);
      pop();
      side *= -1;
    }
  }

  // --- Grand arbre nu ---
  stroke(16, 20, 38);
  branch(230, 1560, 260, -HALF_PI + 0.05, 46, 11);
  // racines dans la neige
  noStroke();
  fill(150, 164, 200, 160);
  ellipse(230, 1565, 240, 36);
  fill(60, 74, 118, 90);
  ellipse(300, 1580, 380, 30);

  // --- Neige qui tombe ---
  noStroke();
  for (let i = 0; i < 1800; i++) {
    const x = random(W), y = random(H);
    const s = random(1.5, 7) * (random() < 0.06 ? 2.2 : 1);
    const warm = constrain(map(dist(x, y, GLOW.x, GLOW.y), 0, 420, 1, 0), 0, 1);
    const c = lerpColor(color(225, 232, 250), color(255, 210, 150), warm);
    fill(red(c), green(c), blue(c), random(70, 200));
    ellipse(x, y, s, s);
  }

  // --- Vignette ---
  noFill();
  for (let i = 0; i < 80; i++) {
    stroke(4, 6, 20, i * 0.55);
    strokeWeight(30);
    ellipse(W / 2, H / 2 - 50, 1500 + i * 26, 1900 + i * 26);
  }

  // --- Grain ---
  noStroke();
  for (let i = 0; i < 25000; i++) {
    fill(random() < 0.5 ? 0 : 255, random(6, 14));
    rect(random(W), random(H), 2, 2);
  }
}

function branch(x, y, len, ang, w, depth) {
  if (depth <= 0 || len < 6) return;
  // segment légèrement courbé
  const bend = random(-0.15, 0.15);
  const mx = x + cos(ang + bend) * len * 0.5;
  const my = y + sin(ang + bend) * len * 0.5;
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  stroke(16, 20, 38);
  strokeWeight(w);
  noFill();
  line(x, y, mx, my);
  strokeWeight(w * 0.85);
  line(mx, my, x2, y2);
  // neige posée sur le dessus des branches
  if (depth < 9 && abs(cos(ang)) > 0.25) {
    stroke(190, 202, 230, 150);
    strokeWeight(max(1, w * 0.3));
    line(x, y - w * 0.4, mx, my - w * 0.4);
    line(mx, my - w * 0.4, x2, y2 - w * 0.4);
  }
  const n = random() < 0.2 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    const spread = map(depth, 11, 1, 0.35, 0.7);
    const na = ang + random(-spread, spread) + (i - (n - 1) / 2) * 0.3;
    branch(x2, y2, len * random(0.66, 0.8), na, w * 0.66, depth - 1);
  }
}

const W = 1600, H = 2000, HY = 880;
let segs = [];
const CENTER = { x: 800, y: 1440 };

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();
}

function angDiff(a, b) {
  return atan2(sin(a - b), cos(a - b));
}

function skyCol(y) {
  const stops = [
    [0.0, color(20, 26, 51)],
    [0.55, color(61, 63, 107)],
    [0.85, color(176, 122, 134)],
    [1.0, color(240, 185, 143)]
  ];
  let t = constrain(y / HY, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    if (t <= stops[i + 1][0]) {
      let k = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      return lerpColor(stops[i][1], stops[i + 1][1], k);
    }
  }
  return stops[stops.length - 1][1];
}

function soilCol(y) {
  let t = constrain((y - HY) / (H - HY), 0, 1);
  return lerpColor(color(78, 55, 40), color(20, 14, 11), pow(t, 0.8));
}

function draw() {
  // ---- Sky ----
  for (let y = 0; y < HY; y++) {
    stroke(skyCol(y));
    line(0, y, W, y);
  }
  // painterly sky strokes
  for (let i = 0; i < 9000; i++) {
    let x = random(W), y = random(HY);
    let n = noise(x * 0.002, y * 0.006);
    let c = skyCol(y + (n - 0.5) * 140);
    c.setAlpha(90);
    stroke(c);
    strokeWeight(random(2, 7));
    let L = random(15, 50);
    let a = (noise(x * 0.001, y * 0.001) - 0.5) * 0.4;
    line(x, y, x + cos(a) * L, y + sin(a) * L);
    if (n > 0.64 && y > HY * 0.3) {
      stroke(245, 195, 175, 35);
      line(x, y, x + cos(a) * L, y + sin(a) * L);
    }
  }

  // ---- Distant hills ----
  noStroke();
  fill(72, 56, 86, 220);
  beginShape();
  vertex(0, HY);
  for (let x = 0; x <= W; x += 10) vertex(x, HY - 30 - noise(x * 0.003) * 90);
  vertex(W, HY);
  endShape(CLOSE);
  fill(46, 36, 50);
  beginShape();
  vertex(0, HY);
  for (let x = 0; x <= W; x += 10) vertex(x, HY - 10 - noise(x * 0.006, 50) * 40);
  vertex(W, HY);
  endShape(CLOSE);

  // ---- Soil ----
  for (let y = HY; y < H; y++) {
    stroke(soilCol(y));
    line(0, y, W, y);
  }
  for (let i = 0; i < 16000; i++) {
    let x = random(W), y = random(HY, H);
    let c = soilCol(y + (noise(x * 0.003, y * 0.01) - 0.5) * 90);
    let j = random(-12, 12);
    stroke(red(c) + j, green(c) + j * 0.8, blue(c) + j * 0.6, 110);
    strokeWeight(random(2, 6));
    let L = random(8, 30);
    let a = (noise(x * 0.002, y * 0.002, 9) - 0.5) * 0.6;
    line(x, y, x + cos(a) * L, y + sin(a) * L);
  }
  // stones
  for (let i = 0; i < 80; i++) {
    let x = random(W), y = random(HY + 60, H - 20);
    let s = random(8, 42);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    let g = random(60, 95);
    fill(g, g * 0.88, g * 0.78, 200);
    ellipse(0, 0, s * random(1.2, 1.8), s);
    fill(255, 230, 200, 25);
    ellipse(-s * 0.2, -s * 0.15, s * 0.7, s * 0.4);
    pop();
  }

  // ---- Underground glow ----
  noStroke();
  for (let r = 760; r > 0; r -= 5) {
    fill(255, 185, 105, 1.6);
    ellipse(CENTER.x, CENTER.y, r * 1.5, r);
  }

  // ---- Roots ----
  makeRoots(470, { x: 920, y: 1430 }, 1);
  makeRoots(1130, { x: 680, y: 1450 }, -1);

  strokeCap(ROUND);
  for (let s of segs) {
    stroke(14, 9, 7, 150);
    strokeWeight(s.w + 4);
    line(s.x1, s.y1, s.x2, s.y2);
  }
  for (let s of segs) {
    stroke(s.r, s.g, s.b);
    strokeWeight(s.w);
    line(s.x1, s.y1, s.x2, s.y2);
  }
  blendMode(ADD);
  for (let s of segs) {
    if (s.t > 0.05) {
      stroke(255, 160, 70, 22 * s.t);
      strokeWeight(s.w * 4 + 6);
      line(s.x1, s.y1, s.x2, s.y2);
    }
  }
  blendMode(BLEND);

  // ---- Trees ----
  strokeCap(ROUND);
  branch(470, HY + 6, -HALF_PI - 0.07, 175, 44, 9, -1);
  branch(1130, HY + 6, -HALF_PI + 0.07, 175, 44, 9, 1);

  // ---- Ground line & grass ----
  noStroke();
  fill(30, 22, 20);
  rect(0, HY - 3, W, 12);
  strokeWeight(2);
  for (let x = 0; x < W; x += 3) {
    stroke(38 + random(-8, 8), 34 + random(-8, 8), 28, 220);
    line(x, HY + 5, x + random(-5, 5), HY - random(4, 20));
  }

  // ---- Grain & vignette ----
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let idx = 4 * (y * W + x);
      let vx = (x - W / 2) / (W / 2), vy = (y - H / 2) / (H / 2);
      let v = 1 - 0.22 * (vx * vx + vy * vy);
      let g = random(-9, 9);
      pixels[idx] = pixels[idx] * v + g;
      pixels[idx + 1] = pixels[idx + 1] * v + g;
      pixels[idx + 2] = pixels[idx + 2] * v + g;
    }
  }
  updatePixels();
}

function makeRoots(x0, target, side) {
  let n = 8;
  for (let k = 0; k < n; k++) {
    let ang = map(k, 0, n - 1, 0.2, PI - 0.2) + random(-0.1, 0.1);
    let toward = cos(ang) * side > 0.05;
    let sx = x0 + cos(ang) * 18, sy = HY + 12;
    if (toward) {
      growRoot(sx, sy, ang, random(750, 950), 24, 4, target, 0.035);
    } else {
      let tg = { x: x0 + cos(ang) * 450, y: H + 300 };
      growRoot(sx, sy, ang, random(380, 620), 20, 3, tg, 0.012);
    }
  }
}

function growRoot(x, y, ang, len, thick, depth, target, steer) {
  let step = 6;
  let steps = floor(len / step);
  let px = x, py = y;
  for (let i = 0; i < steps; i++) {
    let t = constrain(1 - dist(px, py, CENTER.x, CENTER.y) / 560, 0, 1);
    let n = noise(px * 0.005, py * 0.005, depth * 7.3);
    ang += (n - 0.5) * (0.35 + 0.9 * t);
    let ta = atan2(target.y - py, target.x - px);
    ang += angDiff(ta, ang) * steer * (1 - 0.6 * t);
    if (py < HY + 30) ang += angDiff(HALF_PI, ang) * 0.3;
    if (px < 60 || px > W - 60) ang += angDiff(atan2(CENTER.y - py, CENTER.x - px), ang) * 0.2;
    let nx = px + cos(ang) * step, ny = py + sin(ang) * step;
    if (ny > H - 30) break;
    let w = thick * (1 - 0.65 * i / steps);
    let r = lerp(140, 255, t), g = lerp(102, 216, t), b = lerp(70, 150, t);
    segs.push({ x1: px, y1: py, x2: nx, y2: ny, w: w, r: r, g: g, b: b, t: t });
    px = nx; py = ny;
    if (depth > 0 && w > 1.4 && random() < 0.035) {
      let na = ang + (random() < 0.5 ? -1 : 1) * random(0.4, 0.9);
      growRoot(px, py, na, len * random(0.4, 0.65), w * 0.7, depth - 1, target, steer * 0.8);
    }
  }
}

function branch(x, y, ang, len, w, depth, side) {
  let steps = 8;
  let px = x, py = y;
  let a = ang;
  for (let i = 0; i < steps; i++) {
    a = ang + (noise(px * 0.01, py * 0.01, depth) - 0.5) * 0.35;
    let nx = px + cos(a) * len / steps, ny = py + sin(a) * len / steps;
    stroke(36, 26, 34);
    strokeWeight(lerp(w, w * 0.72, i / steps));
    line(px, py, nx, ny);
    px = nx; py = ny;
  }
  if (depth > 0) {
    let cnt = depth > 6 ? 2 : (random() < 0.3 ? 3 : 2);
    for (let j = 0; j < cnt; j++) {
      let na = a + (j - (cnt - 1) / 2) * random(0.35, 0.58) + random(-0.1, 0.1);
      na += angDiff(-HALF_PI, na) * 0.08;
      na += side * 0.035;
      branch(px, py, na, len * random(0.68, 0.79), w * 0.67, depth - 1, side);
    }
  } else if (random() < 0.4) {
    noStroke();
    fill(232, 150, 140, 130);
    circle(px, py, random(4, 8));
  }
}

