// ---------- BOIS ----------
function drawWood() {
  background(120, 78, 45);
  const plankW = 400;
  for (let p = 0; p < 4; p++) {
    const x0 = p * plankW;
    const tone = random(-14, 14);
    noStroke();
    fill(132 + tone, 86 + tone * 0.7, 50 + tone * 0.5);
    rect(x0, 0, plankW, height);
    for (let i = 0; i < 260; i++) {
      const gx = x0 + random(plankW);
      const off = random(1000);
      const c = random() < 0.55
        ? color(88, 52, 28, random(10, 35))
        : color(178, 122, 74, random(8, 25));
      stroke(c);
      strokeWeight(random(1, 4));
      noFill();
      beginShape();
      for (let y = -20; y <= height + 20; y += 20) {
        const dx = (noise(off, y * 0.0015) - 0.5) * 90 + sin(y * 0.004 + off) * 10;
        vertex(constrain(gx + dx, x0 + 3, x0 + plankW - 3), y);
      }
      endShape();
    }
    stroke(42, 24, 13, 210);
    strokeWeight(5);
    line(x0, 0, x0, height);
    stroke(165, 112, 70, 60);
    strokeWeight(2);
    line(x0 + 4, 0, x0 + 4, height);
  }
}

function drawKnots() {
  const knots = [[300, 380], [1340, 1720], [930, 1880]];
  noFill();
  for (const k of knots) {
    for (let r = 4; r < 60; r += 4) {
      stroke(70, 40, 20, 60 - r * 0.6);
      strokeWeight(2);
      beginShape();
      for (let a = 0; a <= TWO_PI + 0.1; a += 0.15) {
        const n = noise(k[0] * 0.01 + cos(a), k[1] * 0.01 + sin(a)) * 8;
        vertex(k[0] + cos(a) * (r + n) * 0.7, k[1] + sin(a) * (r + n) * 1.8);
      }
      endShape();
    }
  }
}

// ---------- ANNEAUX DE CAFÉ ----------
function stainRing(cx, cy, r, a) {
  if (random() < 0.3) {
    noStroke();
    fill(95, 55, 25, a * 0.25);
    circle(cx, cy, r * 2);
  }
  noFill();
  const start = random(TWO_PI);
  const span = random(PI * 1.2, TWO_PI);
  const seed = random(1000);
  for (let pass = 0; pass < 2; pass++) {
    stroke(68, 36, 15, a * (pass ? 0.55 : 1));
    strokeWeight(pass ? random(3, 6) : random(1, 2.5));
    beginShape();
    for (let t = 0; t <= span; t += 0.03) {
      const ang = start + t;
      const rr = r + (noise(seed + cos(ang), seed + sin(ang)) - 0.5) * 10;
      vertex(cx + cos(ang) * rr, cy + sin(ang) * rr);
    }
    endShape();
  }
}

function drawRings() {
  const A = createVector(640, 1150);
  const B = createVector(980, 920);
  for (let i = 0; i < 240; i++) {
    stainRing(A.x + randomGaussian() * 38, A.y + randomGaussian() * 38, random(110, 128), random(8, 22));
    stainRing(B.x + randomGaussian() * 38, B.y + randomGaussian() * 38, random(110, 128), random(8, 22));
  }
  for (let i = 0; i < 80; i++) {
    const t = random(0.2, 0.8);
    stainRing(
      lerp(A.x, B.x, t) + randomGaussian() * 30,
      lerp(A.y, B.y, t) + randomGaussian() * 30,
      random(110, 128), random(6, 16)
    );
  }
}

// ---------- LUMIÈRE DE FENÊTRE ----------
function qp(u, v) {
  const top = p5.Vector.lerp(P0, P1, u);
  const bot = p5.Vector.lerp(P3, P2, u);
  return p5.Vector.lerp(top, bot, v);
}

function drawLight() {
  P0 = createVector(-150, 420);
  P1 = createVector(950, 180);
  P2 = createVector(1600, 1250);
  P3 = createVector(380, 1650);
  const panes = [[0, 0.48], [0.52, 1]];
  blendMode(ADD);
  noStroke();
  for (const pu of panes) {
    for (const pv of panes) {
      for (let k = 0; k < 13; k++) {
        const e = k * 0.005;
        fill(255, 185, 105, 7);
        const a = qp(pu[0] + e, pv[0] + e);
        const b = qp(pu[1] - e, pv[0] + e);
        const c = qp(pu[1] - e, pv[1] - e);
        const d = qp(pu[0] + e, pv[1] - e);
        quad(a.x, a.y, b.x, b.y, c.x, c.y, d.x, d.y);
      }
    }
  }
  blendMode(BLEND);
}

// ---------- MIETTES ----------
function drawCrumbs() {
  noStroke();
  for (let i = 0; i < 28; i++) {
    const x = random(650, 1050) + randomGaussian() * 60;
    const y = random(950, 1150) + randomGaussian() * 60;
    const s = random(3, 9);
    fill(40, 20, 15, 70);
    ellipse(x + 3, y + 4, s, s * 0.8);
    fill(215, 172, 112);
    ellipse(x, y, s, s * random(0.6, 1));
  }
}

// ---------- TASSES ----------
function handlePath(R) {
  beginShape();
  vertex(R - 12, -34);
  bezierVertex(R + 75, -42, R + 75, 42, R - 12, 34);
  endShape();
}

function clipCircle(x, y, r) {
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.arc(x, y, r, 0, TWO_PI);
  drawingContext.clip();
}

function drawCup(x, y, R, o) {
  noStroke();
  for (let k = 0; k < 16; k++) {
    fill(30, 15, 25, 9);
    circle(x + 40 + k * 2.5, y + 50 + k * 3, R * 2 + 30 - k * 4);
  }
  push();
  translate(x + 55, y + 65);
  rotate(o.ha);
  noFill();
  stroke(30, 15, 25, 55);
  strokeWeight(30);
  handlePath(R);
  pop();

  push();
  translate(x, y);
  rotate(o.ha);
  noFill();
  stroke(o.bodyDark);
  strokeWeight(34);
  handlePath(R);
  stroke(o.body);
  strokeWeight(24);
  handlePath(R);
  stroke(255, 255, 255, 70);
  strokeWeight(5);
  translate(-3, -4);
  handlePath(R);
  pop();

  noStroke();
  fill(o.bodyDark);
  circle(x, y, R * 2 + 6);
  fill(o.body);
  circle(x, y, R * 2);

  clipCircle(x, y, R);
  for (let k = 0; k < 11; k++) {
    fill(255, 245, 220, 8);
    circle(x - R * 0.35, y - R * 0.4, R * 2 - k * 14);
  }
  for (let k = 0; k < 10; k++) {
    fill(40, 18, 18, 11);
    circle(x + R * 0.65, y + R * 0.75, R * 1.6 - k * 10);
  }
  drawingContext.restore();

  if (o.band) {
    noFill();
    stroke(o.band);
    strokeWeight(10);
    circle(x, y, R * 2 - 22);
  }

  noStroke();
  fill(o.inner);
  circle(x, y, R * 1.72);
  clipCircle(x, y, R * 0.86);
  for (let k = 0; k < 8; k++) {
    fill(40, 20, 15, 12);
    circle(x - R * 0.35, y - R * 0.4, R * 1.5 - k * 10);
  }
  drawingContext.restore();

  fill(o.liquid);
  circle(x + 4, y + 5, R * 1.42);
  noFill();
  stroke(red(o.foam), green(o.foam), blue(o.foam), 110);
  strokeWeight(3);
  circle(x + 2, y + 3, R * 1.56);

  clipCircle(x + 4, y + 5, R * 0.71);
  if (o.milk) {
    noFill();
    stroke(232, 198, 160, 90);
    strokeWeight(6);
    beginShape();
    for (let t = 0; t < TWO_PI * 2.2; t += 0.08) {
      const rr = t * R * 0.045;
      vertex(x + 10 + cos(t) * rr, y + 8 + sin(t) * rr);
    }
    endShape();
  } else {
    noFill();
    stroke(red(o.foam), green(o.foam), blue(o.foam), 160);
    strokeWeight(7);
    circle(x + 4, y + 5, R * 1.38);
  }
  noStroke();
  fill(255, 238, 205, 95);
  const rx = x - R * 0.28, ry = y - R * 0.25, s = 20, g = 4;
  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      const ax = rx + i * (s + g) + j * 5;
      const ay = ry + j * (s + g) - i * 4;
      quad(ax, ay, ax + s, ay - 4, ax + s + 5, ay + s - 4, ax + 5, ay + s);
    }
  }
  drawingContext.restore();

  noFill();
  stroke(255, 250, 235, 150);
  strokeWeight(4);
  arc(x, y, R * 2 - 6, R * 2 - 6, PI * 0.95, PI * 1.6);
}

// ---------- TEXTURE PICTURALE ----------
function painterly() {
  loadPixels();
  const snap = pixels.slice();
  for (let i = 0; i < 50000; i++) {
    const x = random(width), y = random(height);
    const idx = 4 * (floor(y) * width + floor(x));
    stroke(snap[idx], snap[idx + 1], snap[idx + 2], 70);
    strokeWeight(random(1.5, 3.5));
    const ang = noise(x * 0.003, y * 0.003) * TWO_PI * 2;
    const len = random(4, 12);
    line(x - cos(ang) * len / 2, y - sin(ang) * len / 2,
         x + cos(ang) * len / 2, y + sin(ang) * len / 2);
  }
}

function grain() {
  strokeWeight(1);
  for (let i = 0; i < 40000; i++) {
    stroke(random() < 0.5 ? 0 : 255, 12);
    point(random(width), random(height));
  }
}

function vignette() {
  const g = drawingContext.createRadialGradient(
    width / 2, height * 0.48, 300, width / 2, height / 2, 1350
  );
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(15,5,10,0.6)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);
}

const W = 1600, H = 2000;
const CX = 800, RIMY = 1000, R = 420, RHH = 100, BH = 360, FOOTR = 170, FOOTEH = 36;
const FOOTY = RIMY + BH;
let LX, LY, LZ, HX, HY, HZ;
let cracks = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  let l = Math.hypot(-0.55, -0.5, 0.67);
  LX = -0.55 / l; LY = -0.5 / l; LZ = 0.67 / l;
  let hx = LX, hy = LY, hz = LZ + 1;
  let hl = Math.hypot(hx, hy, hz);
  HX = hx / hl; HY = hy / hl; HZ = hz / hl;
}

function draw() {
  paintWall();
  paintTable();
  paintLight();
  paintShadow();
  paintBowl();
  paintLip();
  paintGold();
  finish();
}

function rAt(t) {
  t = constrain(t, 0, 1);
  return FOOTR + (R - FOOTR) * Math.sqrt(1 - t * t);
}

function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function paintWall() {
  for (let y = 0; y <= 1252; y++) {
    let k = y / 1250;
    stroke(lerp(40, 62, k), lerp(27, 40, k), lerp(27, 32, k));
    line(0, y, W, y);
  }
  for (let i = 0; i < 9000; i++) {
    let x = random(W), y = random(-50, 1240);
    let n = noise(x * 0.002, y * 0.002);
    let r = lerp(28, 95, n), g = lerp(19, 58, n), b = lerp(24, 38, n);
    stroke(r, g, b, random(8, 22));
    strokeWeight(random(6, 40));
    let a = noise(x * 0.001 + 5, y * 0.001) * TWO_PI * 2;
    let len = random(20, 90);
    line(x, y, x + cos(a) * len, min(1245, y + sin(a) * len));
  }
}

function paintTable() {
  for (let y = 1250; y <= H; y++) {
    let k = (y - 1250) / 750;
    stroke(lerp(78, 26, k), lerp(48, 16, k), lerp(32, 14, k));
    line(0, y, W, y);
  }
  noFill();
  for (let i = 0; i < 500; i++) {
    let y0 = random(1255, 1900);
    let n = random();
    stroke(lerp(30, 120, n), lerp(18, 75, n), lerp(12, 45, n), random(18, 40));
    strokeWeight(random(1, 4));
    beginShape();
    for (let x = -20; x <= W + 20; x += 20) {
      vertex(x, y0 + (noise(x * 0.003, y0 * 0.01) - 0.5) * 30 * (y0 - 1250) / 750);
    }
    endShape();
  }
  stroke(140, 95, 60, 120);
  strokeWeight(2);
  line(0, 1250, W, 1250);
  noStroke();
  fill(18, 11, 10);
  rect(0, 1900, W, 100);
  stroke(110, 70, 45, 90);
  strokeWeight(2);
  line(0, 1900, W, 1900);
}

function paintLight() {
  noStroke();
  for (let r = 1600; r > 20; r -= 8) {
    fill(255, 175, 105, 1.2);
    circle(250, 200, r);
  }
  for (let k = 0; k < 25; k++) {
    fill(255, 210, 160, 2.5);
    let j = random(-50, 50);
    quad(80 + j, -50, 560 + j, -50, 1250 + j, 1500, 380 + j, 1500);
  }
  for (let k = 0; k < 30; k++) {
    fill(255, 190, 130, 3);
    ellipse(560, 1440, 900 - k * 25, 220 - k * 6);
  }
}

function paintShadow() {
  noStroke();
  for (let k = 0; k < 40; k++) {
    fill(10, 6, 6, 7);
    ellipse(CX + 140 + k * 4, FOOTY + 30, FOOTR * 2 + 380 - k * 8, 90 - k * 1.5);
  }
  for (let k = 0; k < 15; k++) {
    fill(5, 3, 3, 18);
    ellipse(CX + 10, FOOTY + 6, FOOTR * 2 + 40 - k * 3, FOOTEH * 2 + 14 - k);
  }
}

function paintBowl() {
  loadPixels();
  let y0 = RIMY - RHH - 2, y1 = FOOTY + FOOTEH + 2;
  for (let y = y0; y <= y1; y++) {
    for (let x = CX - R - 3; x <= CX + R + 3; x++) {
      let dx = x - CX, dy = y - RIMY;
      let e = (dx * dx) / (R * R) + (dy * dy) / (RHH * RHH);
      let interior = false, exterior = false, cov = 0;
      if (e <= 1.05) {
        let d = (1 - Math.sqrt(e)) * RHH;
        if (dy < 0) { cov = constrain(d + 0.5, 0, 1); if (cov > 0) interior = true; }
        else if (e <= 1) { interior = true; cov = 1; }
      }
      if (!interior && dy >= 0) {
        let t = dy / BH;
        if (t <= 1) {
          let r = rAt(t);
          cov = constrain(r - Math.abs(dx) + 0.5, 0, 1);
        } else {
          let ef = dx * dx / (FOOTR * FOOTR) + ((y - FOOTY) * (y - FOOTY)) / (FOOTEH * FOOTEH);
          cov = constrain((1 - Math.sqrt(ef)) * FOOTEH + 0.5, 0, 1);
        }
        if (cov > 0) exterior = true;
      }
      if (!interior && !exterior) continue;

      let cr, cg, cb;
      if (interior) {
        let u = dx / R, w = dy / RHH;
        let lit = smoothstep(-0.35, 0.55, u - 0.35 * w + 0.1);
        lit = constrain(lit + 0.1 * (-w), 0, 1);
        let m = (noise(x * 0.012, y * 0.03) - 0.5) * 24;
        cr = lerp(16, 112, lit) + m;
        cg = lerp(24, 142, lit) + m;
        cb = lerp(32, 140, lit) + m;
      } else {
        let t = Math.min(dy / BH, 1);
        let r = t < 1 ? rAt(t) : FOOTR;
        let nx = constrain(dx / Math.max(r, 1), -1, 1);
        let nz = Math.sqrt(Math.max(0, 1 - nx * nx));
        let sy = 0.15 + t * 1.1;
        let nl = Math.hypot(nx, sy, nz);
        let Nx = nx / nl, Ny = sy / nl, Nz = nz / nl;
        let lam = Math.max(0, Nx * LX + Ny * LY + Nz * LZ);
        let v = constrain(lam * 1.3 + 0.06, 0, 1);
        if (v < 0.5) {
          let k = v * 2;
          cr = lerp(22, 64, k); cg = lerp(34, 100, k); cb = lerp(44, 112, k);
        } else {
          let k = (v - 0.5) * 2;
          cr = lerp(64, 172, k); cg = lerp(100, 198, k); cb = lerp(112, 190, k);
        }
        let nh = Math.max(0, Nx * HX + Ny * HY + Nz * HZ);
        let spec = Math.pow(nh, 50) * 200 + Math.pow(nh, 8) * 25;
        let bounce = Math.max(0, t - 0.45) / 0.55 * Math.max(0, nx * 0.6 + 0.4) * 0.6;
        let m = (noise(x * 0.008, y * 0.008) - 0.5) * 36;
        let drip = (noise(x * 0.06, y * 0.004) - 0.5) * 16 * (1 - t);
        cr += spec + 70 * bounce + m + drip;
        cg += spec + 38 * bounce + m + drip;
        cb += spec + 14 * bounce + m * 0.8 + drip;
        if (y > FOOTY - 10) {
          let f = smoothstep(FOOTY - 10, FOOTY - 2, y);
          let cm = (noise(x * 0.05, y * 0.05) - 0.5) * 30;
          let s = 0.25 + 0.85 * lam;
          cr = lerp(cr, 130 * s + cm, f);
          cg = lerp(cg, 92 * s + cm, f);
          cb = lerp(cb, 64 * s + cm, f);
        }
      }
      let idx = 4 * (y * W + x);
      pixels[idx] = pixels[idx] * (1 - cov) + constrain(cr, 0, 255) * cov;
      pixels[idx + 1] = pixels[idx + 1] * (1 - cov) + constrain(cg, 0, 255) * cov;
      pixels[idx + 2] = pixels[idx + 2] * (1 - cov) + constrain(cb, 0, 255) * cov;
    }
  }
  updatePixels();
}

function paintLip() {
  noFill();
  stroke(15, 22, 28, 120);
  strokeWeight(3);
  ellipse(CX, RIMY, 2 * R - 16, 2 * RHH - 12);
  stroke(120, 150, 148);
  strokeWeight(9);
  ellipse(CX, RIMY, 2 * R, 2 * RHH);
  stroke(205, 222, 210, 210);
  strokeWeight(3);
  arc(CX, RIMY - 1, 2 * R, 2 * RHH, PI * 0.6, PI * 1.35);
  stroke(60, 85, 92, 160);
  strokeWeight(3);
  arc(CX, RIMY + 1, 2 * R, 2 * RHH, -PI * 0.3, PI * 0.35);
}

function P(u, t) {
  let r = rAt(t);
  let off = lerp(RHH, FOOTEH, t) * Math.sqrt(Math.max(0, 1 - u * u));
  return { x: CX + u * r, y: RIMY + t * BH + off, u: u, t: t };
}

function lamAt(u, t) {
  let nx = u, nz = Math.sqrt(Math.max(0, 1 - u * u)), sy = 0.15 + t * 1.1;
  let len = Math.hypot(nx, sy, nz);
  return Math.max(0, (nx * LX + sy * LY + nz * LZ) / len);
}

function grow(u, t, du, depth, steps, ns) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    pts.push(P(u, t));
    t += 0.007;
    u += du + (noise(ns, i * 0.15) - 0.5) * 0.025;
    if (random() < 0.07) du = random(-0.012, 0.012);
    u = constrain(u, -0.8, 0.8);
    if (t > 0.9) break;
    if (depth < 2 && i > 5 && random() < 0.035) {
      grow(u, t, random([-1, 1]) * random(0.004, 0.012), depth + 1, floor(random(10, 35)), ns + random(10, 100));
    }
  }
  cracks.push({ pts: pts, depth: depth });
}

function interiorCrack(u, len, ns) {
  let p = P(u, 0);
  let pts = [];
  let x = p.x, y = p.y;
  for (let i = 0; i < len; i++) {
    pts.push({ x: x, y: y, u: 0.3, t: 0 });
    y -= 2.2;
    x += (noise(ns, i * 0.2) - 0.5) * 4;
  }
  cracks.push({ pts: pts, depth: 1 });
}

function paintGold() {
  grow(-0.38, 0, 0.003, 0, 130, 1);
  grow(0.08, 0, -0.004, 0, 60, 7);
  grow(0.46, 0.1, 0.004, 0, 50, 13);
  interiorCrack(-0.38, 22, 21);
  interiorCrack(0.08, 16, 29);

  strokeJoin(ROUND);
  strokeCap(ROUND);
  noFill();
  for (let c of cracks) {
    let sc = c.depth == 0 ? 1 : (c.depth == 1 ? 0.7 : 0.5);
    stroke(255, 180, 80, 14); strokeWeight(22 * sc); drawPath(c.pts, 0, 0);
    stroke(255, 190, 90, 22); strokeWeight(11 * sc); drawPath(c.pts, 0, 0);
  }
  for (let c of cracks) {
    let sc = c.depth == 0 ? 1 : (c.depth == 1 ? 0.7 : 0.5);
    stroke(110, 70, 22); strokeWeight(6.5 * sc); drawPath(c.pts, 0, 0);
    for (let i = 1; i < c.pts.length; i++) {
      let a = c.pts[i - 1], b = c.pts[i];
      let s = constrain(lamAt(a.u, a.t) * 1.4, 0, 1);
      stroke(165 + 75 * s, 115 + 70 * s, 38 + 55 * s);
      strokeWeight(4 * sc);
      line(a.x, a.y, b.x, b.y);
    }
    for (let i = 1; i < c.pts.length; i++) {
      let a = c.pts[i - 1], b = c.pts[i];
      let s = constrain(lamAt(a.u, a.t) * 1.4, 0, 1);
      stroke(255, 242, 200, 50 + 190 * s);
      strokeWeight(1.6 * sc);
      line(a.x - 1, a.y - 1, b.x - 1, b.y - 1);
    }
  }

  // éclat manquant remplacé par l'or
  let pts = [P(0.34, 0), P(0.53, 0), P(0.51, 0.045), P(0.46, 0.1), P(0.41, 0.06), P(0.37, 0.03)];
  pts[0].y -= 6; pts[1].y -= 6;
  noStroke();
  fill(255, 185, 90, 30);
  beginShape(); for (let p of pts) vertex(p.x, p.y); endShape(CLOSE);
  fill(140, 92, 30);
  beginShape(); for (let p of pts) vertex(p.x, p.y); endShape(CLOSE);
  let mx = 0, my = 0;
  for (let p of pts) { mx += p.x; my += p.y; }
  mx /= pts.length; my /= pts.length;
  fill(222, 172, 82);
  beginShape(); for (let p of pts) vertex(lerp(mx, p.x, 0.82) - 2, lerp(my, p.y, 0.82) - 2); endShape(CLOSE);
  fill(250, 225, 150, 170);
  beginShape(); for (let p of pts) vertex(lerp(mx, p.x, 0.4) - 4, lerp(my, p.y, 0.4) - 4); endShape(CLOSE);
  stroke(255, 245, 210, 220);
  strokeWeight(2);
  line(pts[0].x, pts[0].y, pts[1].x, pts[1].y);
}

function drawPath(pts, ox, oy) {
  beginShape();
  for (let p of pts) vertex(p.x + ox, p.y + oy);
  endShape();
}

function finish() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let idx = 4 * (y * W + x);
      let dx = (x - W * 0.48) / (W * 0.75), dy = (y - H * 0.5) / (H * 0.7);
      let d = Math.sqrt(dx * dx + dy * dy);
      let vf = 1 - 0.5 * Math.pow(Math.min(d, 1.3), 2.2);
      let s = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453;
      let g = (s - Math.floor(s) - 0.5) * 14;
      pixels[idx] = constrain(pixels[idx] * vf + g, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * vf + g, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * vf + g, 0, 255);
    }
  }
  updatePixels();
}

let base, cx;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function hillY(x) {
  return 1230 + (noise(x * 0.0015, 7.3) - 0.5) * 160 - 60 * Math.exp(-sq((x - 1060) / 420));
}

function snowCol(y) {
  let t = constrain((y - 1150) / 850, 0, 1);
  return lerpColor(color(92, 106, 152), color(170, 182, 218), pow(t, 0.8));
}

function draw() {
  cx = 1060;
  base = hillY(cx) + 12;
  paintSky();
  paintStars();
  paintFarHills();
  paintSnowField();
  paintSmoke();
  paintHouse();
  paintGlow();
  paintWindow();
  paintDoor();
  paintDrift();
  paintSpill();
  paintFootprints();
  paintTree();
  paintFallingSnow();
  paintGrain();
  paintVignette();
}

function paintSky() {
  noStroke();
  for (let y = 0; y < 1400; y += 4) {
    let t = y / 1400;
    fill(lerpColor(color(8, 12, 38), color(42, 52, 96), pow(t, 1.6)));
    rect(0, y, width, 4);
  }
  for (let i = 0; i < 9000; i++) {
    let x = random(width), y = random(1400);
    let t = y / 1400;
    let c = lerpColor(color(10, 14, 42), color(55, 66, 112), pow(t, 1.6));
    let a = noise(x * 0.003, y * 0.003) * TWO_PI * 1.5;
