function paintSpill() {
  blendMode(ADD);
  noStroke();
  let P = (u, v) => {
    let tx = lerp(cx - 150, cx - 30, u), bx = lerp(cx - 230, cx + 10, u);
    return [lerp(tx, bx, v), lerp(base + 40, base + 240, v)];
  };
