    fill(255, 160, 70, 2.2);
    ellipse(cx - 100, base + 140, r * 1.2, r * 0.55);
  }
  let panes = [[0, 0.46, 0, 0.46], [0.54, 1, 0, 0.46], [0, 0.46, 0.54, 1], [0.54, 1, 0.54, 1]];
  for (let p of panes) {
    for (let e = 0.07; e >= 0; e -= 0.01) {
      fill(255, 175, 85, e === 0 ? 34 : 7);
      let a = P(p[0] - e, p[2] - e), b = P(p[1] + e, p[2] - e);
      let c = P(p[1] + e, p[3] + e), d = P(p[0] - e, p[3] + e);
      quad(a[0], a[1], b[0], b[1], c[0], c[1], d[0], d[1]);
    }
  }
  for (let i = 0; i < 24; i++) {
    fill(255, 180, 90, 4);
    triangle(cx + 104, base, cx + 112, base, cx + 175 + i * 2, base + 200 - i * 3);
