function paintFootprints() {
  let p0 = [300, 2060], p1 = [760, 1820], p2 = [1330, 1560], p3 = [cx + 75, base + 8];
  let n = 46;
  noStroke();
  for (let i = 1; i < n; i++) {
    let t = pow(i / n, 0.7);
    let x = bezierPoint(p0[0], p1[0], p2[0], p3[0], t);
    let y = bezierPoint(p0[1], p1[1], p2[1], p3[1], t);
    let tx = bezierTangent(p0[0], p1[0], p2[0], p3[0], t);
    let ty = bezierTangent(p0[1], p1[1], p2[1], p3[1], t);
    let ang = atan2(ty, tx);
    let s = map(y, base, 2000, 0.22, 1.25);
    let side = i % 2 === 0 ? 1 : -1;
    let ox = -sin(ang) * side * 14 * s, oy = cos(ang) * side * 14 * s * 0.6;
    push();
    translate(x + ox, y + oy);
    rotate(ang);
    fill(70, 82, 135, 150);
    ellipse(0, 0, 34 * s, 15 * s);
    fill(52, 62, 115, 120);
    ellipse(-2 * s, 1 * s, 22 * s, 8 * s);
    fill(200, 210, 240, 90);
    ellipse(3 * s, -5 * s, 30 * s, 4 * s);
    pop();
  }
}

function branch(x, y, len, ang, w, depth) {
  if (depth === 0 || len < 6) return;
  let x2 = x + cos(ang) * len, y2 = y + sin(ang) * len;
  let mx = (x + x2) / 2 + random(-len * 0.08, len * 0.08);
  let my = (y + y2) / 2 + random(-len * 0.08, len * 0.08);
  stroke(16, 18, 34);
  strokeWeight(w);
  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(mx, my, x2, y2);
  endShape();
  if (depth < 7 && random() < 0.55 && abs(sin(ang)) < 0.85) {
    stroke(190, 200, 232, 200);
    strokeWeight(max(1, w * 0.35));
    line(x, y - w * 0.45, x2, y2 - w * 0.45);
  }
  let k = floor(random(2, 4));
  for (let i = 0; i < k; i++) {
    let na = ang + random(-0.6, 0.6) + (i - (k - 1) / 2) * 0.35;
    na = lerp(na, -HALF_PI, 0.1);
    branch(x2, y2, len * random(0.62, 0.8), na, w * 0.68, depth - 1);
  }
}

