function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 12, 24);

  let cx = width * 0.5;
  let cy = height * 0.46;

  // 1. Fond texturé : Nébuleuse sombre et profonde
  noStroke();
  for (let i = 0; i < 3500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let d = dist(x, y, cx, cy);

    let r = map(n, 0, 1, 8, 35);
    let g = map(n, 0, 1, 10, 25);
    let b = map(n, 0, 1, 20, 55);
    let a = map(d, 0, 1200, 18, 4);

    fill(r, g, b, a);
    let rad = random(40, 250);
    circle(x, y, rad);
  }

  // 2. Halo d'attraction au cœur de la rencontre
  blendMode(ADD);
  for (let r = 1100; r > 0; r -= 8) {
    let inter = map(r, 0, 1100, 1, 0);
    let c1 = color(255, 160, 70, 2.2 * inter);
    let c2 = color(120, 30, 140, 1.2 * (1 - inter));
    fill(lerpColor(c2, c1, inter));
    circle(cx, cy, r * 1.4);
  }

  // 3. Courants d'air et d'eau : Le champ de force partagé
  blendMode(SCREEN);
  for (let i = 0; i < 1800; i++) {
    let startX = random(width);
    let startY = random(height);
    let x = startX;
    let y = startY;

    let distCenter = dist(x, y, cx, cy);
    let isGold = random() < map(distCenter, 0, 700, 0.6, 0.05);

    beginShape();
    noFill();
    for (let step = 0; step < 60; step++) {
      let d = dist(x, y, cx, cy);
      let angleToCenter = atan2(cy - y, cx - x);
      let vortexAngle = angleToCenter + HALF_PI * 0.85;
      let noiseAngle = (noise(x * 0.002, y * 0.002) - 0.5) * TWO_PI * 2;

      let blendFactor = constrain(map(d, 0, 900, 0.8, 0.1), 0.1, 0.8);
      let finalAngle = lerpAngle(noiseAngle, vortexAngle, blendFactor);

      let alpha = sin(map(step, 0, 60, 0, PI)) * map(d, 0, 1000, 35, 8);

      if (isGold) {
        stroke(255, 215, 140, alpha * 1.2);
        strokeWeight(1.5);
      } else if (startX < width * 0.5) {
        stroke(230, 80, 90, alpha);
        strokeWeight(2);
      } else {
        stroke(60, 160, 220, alpha);
        strokeWeight(2);
      }

      vertex(x, y);
      x += cos(finalAngle) * 6;
      y += sin(finalAngle) * 6;
    }
    endShape();
  }

  // 4. La danse des deux âmes (Rubans de peinture)
  blendMode(BLEND);
  let numStrands = 550;
  let maxSteps = 320;

  let strandsA = [];
  let strandsB = [];

  for (let i = 0; i < numStrands; i++) {
    strandsA.push({
      x: random(width * 0.05, width * 0.45),
      y: height + random(50, 400),
      seed: random(10000),
      w: random(2, 14),
      cVar: random(-25, 25),
      speed: random(4.5, 6.5)
    });
    strandsB.push({
      x: random(width * 0.55, width * 0.95),
      y: height + random(50, 400),
      seed: random(10000),
      w: random(2, 14),
      cVar: random(-25, 25),
      speed: random(4.5, 6.5)
    });
  }

  // Dessin étape par étape pour un entrelacement naturel (z-ordering)
  for (let step = 0; step < maxSteps; step++) {
    let t = step / maxSteps;

    // Ascension vers le point de rencontre, puis élévation
    let spineY = lerp(height + 150, -150, pow(t, 0.88));

    // L'amplitude de l'orbite se resserre au cœur (t ~ 0.55)
    let env = sin(t * PI);
    let pinch = 1 - 0.65 * exp(-pow((t - 0.52) / 0.18, 2));
    let amp = 480 * env * pinch;

    let freq = t * TWO_PI * 1.65;
    let cosF = cos(freq);
    let sinF = sin(freq); // Détermine qui passe devant l'autre

    let spineAx = cx - cosF * amp;
    let spineAy = spineY + sinF * 50 * env;

    let spineBx = cx + cosF * amp;
    let spineBy = spineY - sinF * 50 * env;

    if (sinF > 0) {
      updateAndDrawStrands(strandsB, spineBx, spineBy, spineAx, spineAy, t, false);
      updateAndDrawStrands(strandsA, spineAx, spineAy, spineBx, spineBy, t, true);
    } else {
      updateAndDrawStrands(strandsA, spineAx, spineAy, spineBx, spineBy, t, true);
      updateAndDrawStrands(strandsB, spineBx, spineBy, spineAx, spineAy, t, false);
    }
  }

  // 5. Poussière d'or et étincelles d'émotion (Finition)
  blendMode(ADD);
  for (let i = 0; i < 900; i++) {
    let angle = random(TWO_PI);
    let r = pow(random(), 1.8) * 650;
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 1.3;

    let s = random(1, 5);
    let a = map(r, 0, 650, 180, 10);

    fill(255, 230, 170, a);
    noStroke();
    circle(x, y, s);

    if (random() < 0.08) {
      fill(255, 200, 140, a * 0.3);
      circle(x, y, s * 6);
    }
  }

  // Grain subtil sur toute la toile pour l'aspect pictural
  blendMode(OVERLAY);
  noStroke();
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    fill(random() > 0.5 ? 255 : 0, 6);
    rect(x, y, 2, 2);
  }
}

function updateAndDrawStrands(strands, targetX, targetY, otherX, otherY, t, isWarm) {
  for (let i = 0; i < strands.length; i++) {
    let s = strands[i];
    let px = s.x;
    let py = s.y;

    let n1 = noise(s.seed * 0.1, t * 3.5);
    let n2 = noise(s.seed * 0.1 + 200, t * 3.5);

    // Dispersion organique autour de l'épine dorsale
    let spread = map(sin(t * PI), 0, 1, 220, 95);
    if (t > 0.4 && t < 0.65) spread *= 0.75; // Étreinte plus serrée au centre

    let offsetAngle = n1 * TWO_PI * 2;
    let offsetRad = (n2 - 0.2) * spread;

    let tx = targetX + cos(offsetAngle) * offsetRad;
    let ty = targetY + sin(offsetAngle) * offsetRad * 0.6;

    let angle = atan2(ty - s.y, tx - s.x);
    angle += (noise(s.x * 0.004, s.y * 0.004, t * 2) - 0.5) * 1.4;

    s.x += cos(angle) * s.speed;
    s.y += sin(angle) * s.speed;

    // Calcul de la proximité avec l'autre entité pour la fusion des couleurs
    let dToOther = dist(s.x, s.y, otherX, otherY);
    let proximity = constrain(map(dToOther, 30, 380, 1, 0), 0, 1);
    proximity = pow(proximity, 1.5);

    let baseC, midC, highC;
    if (isWarm) {
      // Palette Chaude : Carmin, Corail, Or
      baseC = color(190 + s.cVar, 35, 65);
      midC = color(245 + s.cVar, 105, 65);
      highC = color(255, 235, 165);
    } else {
      // Palette Froide : Indigo, Turquoise, Perle
      baseC = color(25, 75 + s.cVar, 145);
      midC = color(45, 185 + s.cVar, 205);
      highC = color(220, 245, 255);
    }

    let col = lerpColor(baseC, midC, noise(s.seed, t * 5));
    col = lerpColor(col, highC, proximity * 0.9);

    let alpha = map(sin(t * PI), 0, 1, 15, 190);
    col.setAlpha(alpha);

    let currentW = s.w * sin(t * PI) * (1 + proximity * 0.6);

    // Coup de pinceau principal
    stroke(col);
    strokeWeight(currentW);
    line(px, py, s.x, s.y);

    // Rebord lumineux (effet d'empâtement / impasto)
    if (currentW > 5 && step % 2 === 0) {
      let highlight = lerpColor(col, color(255, 250, 240, alpha * 0.6), 0.5);
      stroke(highlight);
      strokeWeight(currentW * 0.25);
      line(px - 1.5, py - 1.5, s.x - 1.5, s.y - 1.5);
    }

    // Éclats lumineux nés du contact
    if (proximity > 0.65 && random() < 0.04) {
      noStroke();
      fill(255, 245, 200, alpha * 0.7);
      circle(s.x + random(-12, 12), s.y + random(-12, 12), random(1.5, 4.5));
    }
  }
}

function lerpAngle(a, b, t) {
  let diff = b - a;
  while (diff < -PI) diff += TWO_PI;
  while (diff > PI) diff -= TWO_PI;
  return a + diff * t;
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  background(8, 7, 16);

  // 1. Fond cosmique et texturé (Nébuleuse sombre)
  noStroke();
  for (let i = 0; i < 6000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0012, y * 0.0012);
    let r = map(n, 0, 1, 8, 45);
    let g = map(n, 0, 1, 6, 20);
    let b = map(n, 0, 1, 18, 60);
    fill(r, g, b, 18);
    let s = random(40, 200);
    ellipse(x, y, s, s);
  }

  // Poussière d'étoiles lointaines
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(15, 100);
    fill(255, 240, 220, a);
    let s = random(0.5, 2.5);
    ellipse(x, y, s, s);
  }

  // 2. Définition des colonnes vertébrales des deux amants (Courbes de Bézier)
  // Amant A (Chaleur : Rouge, Corail, Or)
  let spineA = [
    {x: 200, y: 2100},
    {x: 1350, y: 1450},
    {x: 250, y: 950},
    {x: 780, y: 580}
  ];

  // Amant B (Profondeur : Bleu nuit, Cyan, Argent)
  let spineB = [
    {x: 1400, y: 2100},
    {x: 250, y: 1450},
    {x: 1350, y: 950},
    {x: 820, y: 580}
  ];

  // Halo central de l'union
  blendMode(ADD);
  for (let r = 900; r > 0; r -= 15) {
    let alpha = map(r, 0, 900, 8, 0);
    fill(60, 25, 45, alpha);
    ellipse(800, 850, r * 1.4, r * 1.8);
  }

  // 3. Dessin des courants d'âmes entrelacés
  let numStrands = 1100;
  let steps = 260;

  // Pré-calcul des paramètres des fils pour un mélange harmonieux
  let strandsA = [];
  let strandsB = [];

  for (let i = 0; i < numStrands; i++) {
    strandsA.push(createStrandParams(i, true));
    strandsB.push(createStrandParams(i, false));
  }

  // Dessin étape par étape (de bas en haut) pour superposer les deux entités naturellement
  for (let s = 0; s < steps; s++) {
    let t1 = s / steps;
    let t2 = (s + 1) / steps;

    // Courant A
    for (let i = 0; i < numStrands; i++) {
      drawStrandSegment(strandsA[i], spineA, spineB, t1, t2, s, true);
    }
    // Courant B
    for (let i = 0; i < numStrands; i++) {
      drawStrandSegment(strandsB[i], spineB, spineA, t1, t2, s, false);
    }
  }

  // 4. Émanations d'énergie (Particules d'amour et de lumière aux intersections)
  for (let s = 0; s < 500; s++) {
    let t = random(0.15, 1.0);
    let pA = getSpinePoint(spineA, t);
    let pB = getSpinePoint(spineB, t);
    let d = dist(pA.x, pA.y, pB.x, pB.y);

    if (d < 450) {
      let midX = lerp(pA.x, pB.x, random(0.2, 0.8));
      let midY = lerp(pA.y, pB.y, random(0.2, 0.8));
      drawLoveSpark(midX, midY, d);
    }
  }

  // 5. Les "Têtes" / Centres spirituels (Le Baiser Cosmique)
  drawGlowCore(775, 580, color(255, 90, 50), color(255, 230, 180), 280);
  drawGlowCore(825, 580, color(30, 140, 255), color(200, 240, 255), 280);

  // Fusion lumineuse au point de contact
  drawGlowCore(800, 580, color(255, 200, 140), color(255, 255, 255), 420);

  // 6. Anneaux d'harmonie (Ondes de choc douces autour de l'union)
  noFill();
  for (let i = 0; i < 120; i++) {
    let r = random(80, 750);
    let a1 = random(TWO_PI);
    let a2 = a1 + random(PI * 0.2, PI * 0.8);
    strokeWeight(random(0.5, 2.5));
    let c = lerpColor(color(255, 140, 90, 25), color(100, 200, 255, 25), random(1));
    stroke(c);
    arc(800 + random(-20, 20), 650 + random(-20, 20), r, r * random(0.85, 1.15), a1, a2);
  }

  // 7.Finition : Grain de toile et vignettage
  blendMode(BLEND);
  applyVignetteAndGrain();
}

function createStrandParams(index, isWarm) {
  let angle = random(TWO_PI);
  let radius = pow(random(1), 1.4) * 320;
  let noiseOffset = random(10000);
  let weight = random(0.6, 3.8);

  let c1, c2, c3;
  if (isWarm) {
    c1 = color(180, 15, 45);   // Cramoisi profond
    c2 = color(255, 85, 30);   // Orange ardent
    c3 = color(255, 210, 110); // Or lumineux
  } else {
    c1 = color(15, 35, 130);   // Indigo profond
    c2 = color(0, 150, 215);   // Cyan riche
    c3 = color(170, 235, 255); // Bleu glacé
  }

  let mix = random(1);
  let baseCol = mix < 0.5 ? lerpColor(c1, c2, mix * 2) : lerpColor(c2, c3, (mix - 0.5) * 2);

  return {
    angle: angle,
    radius: radius,
    noiseOffset: noiseOffset,
    weight: weight,
    baseCol: baseCol
  };
}

function getSpinePoint(spine, t) {
  let x = bezierPoint(spine[0].x, spine[1].x, spine[2].x, spine[3].x, t);
  let y = bezierPoint(spine[0].y, spine[1].y, spine[2].y, spine[3].y, t);
  return {x: x, y: y};
}

function getFinalStrandPos(params, mySpine, otherSpine, t) {
  let p = getSpinePoint(mySpine, t);
  let pOther = getSpinePoint(otherSpine, t);

  // Le rayon se resserre vers le sommet (le baiser)
  let spread = map(sin(t * PI), 0, 1, 0.7, 1.25);
  if (t > 0.75) {
    spread = map(t, 0.75, 1.0, spread, 0.12);
  }

  // Mouvement hélicoïdal et turbulence de Perlin
  let currentAngle = params.angle + t * 5.0;
  let nX = (noise(params.noiseOffset, t * 3.5) - 0.5) * 260;
  let nY = (noise(params.noiseOffset + 500, t * 3.5) - 0.5) * 260;

  let x = p.x + cos(currentAngle) * params.radius * spread + nX * spread;
  let y = p.y + sin(currentAngle) * params.radius * spread * 0.6 + nY * spread;

  // Attraction gravitationnelle vers l'autre amant lorsqu'ils sont proches
  let d = dist(p.x, p.y, pOther.x, pOther.y);
  let pull = constrain(map(d, 700, 0, 0, 0.45), 0, 0.45);

  x = lerp(x, pOther.x, pull * pow(t, 1.5));
  y = lerp(y, pOther.y, pull * pow(t, 1.5));

  return {x: x, y: y, dSpines: d};
}

function drawStrandSegment(params, mySpine, otherSpine, t1, t2, stepIndex, isWarm) {
  let pos1 = getFinalStrandPos(params, mySpine, otherSpine, t1);
  let pos2 = getFinalStrandPos(params, mySpine, otherSpine, t2);

  // Transformation de la couleur à l'approche de l'autre (Naissance de la lumière)
  let proximity = constrain(map(pos1.dSpines, 550, 40, 0, 1), 0, 1);
  let gold = color(255, 235, 190);
  let finalCol = lerpColor(params.baseCol, gold, pow(proximity, 1.8) * 0.85);

  // Modulation de l'opacité (effet de coup de pinceau fluide)
  let alphaNoise = noise(params.noiseOffset + stepIndex * 0.08);
  let baseAlpha = map(sin(t1 * PI), 0, 1, 5, 38);
  if (t1 > 0.85) baseAlpha = map(t1, 0.85, 1.0, 38, 60);

  let alpha = baseAlpha * map(alphaNoise, 0, 1, 0.3, 1.5);

  finalCol.setAlpha(alpha);
  stroke(finalCol);
  strokeWeight(params.weight * map(sin(t1 * PI), 0, 1, 0.6, 1.4));

  line(pos1.x, pos1.y, pos2.x, pos2.y);
}

function drawLoveSpark(x, y, distSpines) {
  let intensity = map(distSpines, 450, 0, 0.2, 1);
  let angle = noise(x * 0.004, y * 0.004) * TWO_PI * 2;
  let len = random(20, 120) * intensity;

  let c = lerpColor(color(255, 100, 150), color(255, 240, 180), random(1));

  noFill();
  strokeWeight(random(0.5, 2.2));

  beginShape();
  let cx = x;
  let cy = y;
  for (let i = 0; i < 15; i++) {
    let a = map(sin((i / 14) * PI), 0, 1, 0, 50 * intensity);
    c.setAlpha(a);
    stroke(c);
    vertex(cx, cy);
    let stepAngle = angle + (noise(cx * 0.01, cy * 0.01) - 0.5) * 1.5;
    cx += cos(stepAngle) * (len / 15);
    cy += sin(stepAngle) * (len / 15) - 1.5; // Légère élévation
  }
  endShape();

  // Pétale ou éclat de lumière
  if (random(1) < 0.35) {
    noStroke();
    c.setAlpha(random(30, 90) * intensity);
    fill(c);
    let s = random(2, 7) * intensity;
    ellipse(x, y, s, s);
  }
}

function drawGlowCore(x, y, colOuter, colInner, maxRad) {
  noStroke();
  for (let r = maxRad; r > 0; r -= 4) {
    let t = map(r, maxRad, 0, 0, 1);
    let c = lerpColor(colOuter, colInner, pow(t, 1.5));
    c.setAlpha(map(pow(t, 2), 0, 1, 0, 14));
    fill(c);
    ellipse(x + random(-2, 2), y + random(-2, 2), r, r);
  }
}

function applyVignetteAndGrain() {
  // Vignettage doux pour encadrer l'intimité
  noFill();
  for (let r = 1800; r < 2600; r += 8) {
    let a = map(r, 1800, 2600, 0, 120);
    stroke(5, 4, 10, a);
    strokeWeight(12);
    ellipse(width / 2, height / 2, r * 0.85, r * 1.05);
  }

  // Texture de toile subtile via manipulation directe des pixels
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = random(-10, 10);
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();
}

let paletteWarm, paletteCool, paletteGold;

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  colorMode(HSB, 360, 100, 100, 1.0);

  // Warmth: Deep crimsons, corals, blush, soft amber
  paletteWarm = [
    color(350, 85, 45),
    color(355, 80, 65),
    color(8, 75, 85),
    color(18, 65, 95),
    color(340, 50, 90),
    color(25, 80, 90)
  ];

  // Depth: Prussian blue, indigo, teal, soft cyan, twilight violet
  paletteCool = [
    color(230, 85, 35),
    color(215, 80, 55),
    color(200, 75, 75),
    color(190, 55, 90),
    color(250, 65, 45),
    color(175, 70, 80)
  ];

  // Resonance: Gold, champagne, pure light
  paletteGold = [
    color(40, 85, 95),
    color(45, 70, 100),
    color(35, 90, 85),
    color(50, 40, 100),
    color(30, 60, 100)
  ];

  drawPainting();
}

function drawPainting() {
  // 1. Deep Atmospheric Background
  background(235, 75, 8);
  drawAmbientGlow();
  drawBackgroundWash();

  // 2. Distant Tendrils (Out of focus, wide brush)
  drawFlowLayer(1200, 14, 0.25, 160, false);

  // 3. Core Currents (The two entities rising and intertwining)
  drawFlowLayer(4500, 5, 0.55, 220, false);

  // 4. Fine Silk Threads (Sharp details and golden resonance at the intersection)
  drawFlowLayer(5500, 1.8, 0.85, 280, true);

  // 5. The Heart / Nexus (Intense light where they embrace)
  drawCoreRadiance();

  // 6. Luminous Spores & Sparks (Moments of tenderness drifting outward)
  drawEmbers();

  // 7. Canvas Texture & Glaze
  applyCanvasTexture();
}

function drawAmbientGlow() {
  noStroke();
  let cx = width * 0.5;
  let cy = height * 0.45;

  for (let r = 1800; r > 0; r -= 15) {
    let inter = map(r, 0, 1800, 1, 0);
    let h = lerp(240, 350, pow(inter, 1.5));
    let s = lerp(70, 50, inter);
    let b = lerp(8, 45, pow(inter, 2));
    fill(h, s, b, 0.03);
    ellipse(cx, cy, r * 1.2, r * 1.5);
  }
}

function drawBackgroundWash() {
  noStroke();
  for (let i = 0; i < 3500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);

    let dToCenter = dist(x, y, width * 0.5, height * 0.45);
    let centerFactor = constrain(map(dToCenter, 0, 900, 1, 0), 0, 1);

    let h = lerp(230, 340, n);
    let s = lerp(60, 40, centerFactor);
    let b = lerp(10, 35, centerFactor * n);

    fill(h, s, b, 0.04);

    push();
    translate(x, y);
    rotate(n * TWO_PI * 2);
    ellipse(0, 0, random(80, 300), random(40, 150));
    pop();
  }
}

function getSoulCenters(y) {
  let t = map(y, height * 1.1, -height * 0.1, 0, 1);

  // Envelope shapes the embrace: wide at bottom, intertwined in middle, unified at top
  let envelope = sin(constrain(t, 0, 1) * PI);
  let spread = 480 * pow(1 - t, 1.3) + 140 * envelope;

  // Rising spiral phase
  let freq = 2.6 * PI;
  let phase = pow(t, 1.15) * freq - 0.4;

  let centerX = width * 0.5 + (noise(t * 2, 10) - 0.5) * 180 * envelope;

  let ax = centerX - cos(phase) * spread;
  let bx = centerX + cos(phase) * spread;

  // Depth ordering (which one is in front)
  let az = sin(phase);
  let bz = -sin(phase);

  return { ax, bx, az, bz, centerX, spread, t };
}

function getFlowAngle(x, y) {
  let centers = getSoulCenters(y);

  // Numerical derivative to follow the exact spine of the curves
  let deltaY = 10;
  let nextCenters = getSoulCenters(y - deltaY);

  let dAx = nextCenters.ax - centers.ax;
  let dBx = nextCenters.bx - centers.bx;

  let angleA = atan2(-deltaY, dAx);
  let angleB = atan2(-deltaY, dBx);

  let dA = abs(x - centers.ax);
  let dB = abs(x - centers.bx);

  // Blend the two directional fields smoothly
  let weightA = 1 / (pow(dA, 1.5) + 1);
  let weightB = 1 / (pow(dB, 1.5) + 1);

  let vx = cos(angleA) * weightA + cos(angleB) * weightB;
  let vy = sin(angleA) * weightA + sin(angleB) * weightB;
  let spineAngle = atan2(vy, vx);

  // Add organic turbulence
  let n1 = noise(x * 0.002, y * 0.002);
  let n2 = noise(x * 0.008, y * 0.008);
  let turb = map(n1 * 0.7 + n2 * 0.3, 0, 1, -PI * 0.65, PI * 0.65);

  // At the core of the embrace, create swirling eddies
  let dCenter = dist(x, y, width * 0.5, height * 0.45);
  let swirlFactor = constrain(map(dCenter, 0, 500, 1, 0), 0, 1);
  let angleToCenter = atan2(y - height * 0.45, x - width * 0.5);
  let swirlAngle = angleToCenter + HALF_PI;

  // Combine forces
  let finalVx = cos(spineAngle) * 0.65 + cos(spineAngle + turb) * 0.35;
  let finalVy = sin(spineAngle) * 0.65 + sin(spineAngle + turb) * 0.35;

  if (swirlFactor > 0) {
    let swirlStrength = pow(swirlFactor, 2) * 0.45;
    finalVx = lerp(finalVx, cos(swirlAngle), swirlStrength);
    finalVy = lerp(finalVy, sin(swirlAngle), swirlStrength);
  }

  return atan2(finalVy, finalVx);
}

function drawFlowLayer(numPaths, baseWeight, baseAlpha, maxSteps, isDetailLayer) {
  noFill();

  for (let i = 0; i < numPaths; i++) {
    // Biased sampling towards the vertical stream and the central nexus
    let y = random(height * 0.02, height * 0.98);
    let centers = getSoulCenters(y);

    // Decide whether this particle belongs to Soul A (Warm), Soul B (Cool), or the Nexus
    let soulType = random() < 0.5 ? 'A' : 'B';

    // Gaussian-like spread around the chosen spine
    let offset = (random() + random() + random() - 1.5) * (isDetailLayer ? 280 : 500);
    let x = (soulType === 'A' ? centers.ax : centers.bx) + offset;

    if (x < -100 || x > width + 100) continue;

    // Pick base color
    let baseCol;
    if (soulType === 'A') {
      baseCol = random(paletteWarm);
    } else {
      baseCol = random(paletteCool);
    }
    let goldCol = random(paletteGold);

    let steps = floor(random(maxSteps * 0.4, maxSteps));
    let stepSize = isDetailLayer ? 3.5 : 5.5;

    // Modulate stroke weight
    let w = baseWeight * random(0.5, 1.6);
    strokeWeight(w);

    let px = x;
    let py = y;

    for (let s = 0; s < steps; s++) {
      let cInfo = getSoulCenters(py);
      let dA = abs(px - cInfo.ax);
      let dB = abs(px - cInfo.bx);

      // Measure of how deeply the two currents are overlapping at this exact point
      let proximityToBoth = (dA + dB);
      let resonance = constrain(map(proximityToBoth, 60, 420, 1, 0), 0, 1);
      resonance = pow(resonance, 1.8);

      // Boost resonance near the heart of the painting
      let dHeart = dist(px, py, width * 0.5, height * 0.43);
      let heartBoost = constrain(map(dHeart, 0, 450, 0.5, 0), 0, 0.5);
      resonance = constrain(resonance + heartBoost, 0, 1);

      // Blend base color with gold based on resonance
      let c = lerpColor(baseCol, goldCol, resonance);

      // Fade in and out along the stroke for tapered brush feel
      let stepProgress = s / steps;
      let taper = sin(stepProgress * PI);

      // Distance falloff from the main arteries so edges dissolve into background
      let minDist = min(dA, dB);
      let edgeFade = constrain(map(minDist, 0, 550, 1, 0.05), 0.05, 1);

      let alpha = baseAlpha * taper * edgeFade * (0.4 + resonance * 0.6);

      stroke(hue(c), saturation(c), brightness(c), alpha);

      let angle = getFlowAngle(px, py);
      let nx = px + cos(angle) * stepSize;
      let ny = py + sin(angle) * stepSize;

      line(px, py, nx, ny);

      // Occasional painterly dab / impasto texture on detail layer
      if (isDetailLayer && resonance > 0.6 && random() < 0.06) {
        noStroke();
        fill(hue(c), saturation(c) * 0.7, 100, alpha * 0.8);
        ellipse(nx + random(-3, 3), ny + random(-3, 3), w * 2.2, w * 1.2);
      }

      px = nx;
      py = ny;

      if (px < -100 || px > width + 100 || py < -100 || py > height + 100) break;
    }
  }
}

function drawCoreRadiance() {
  // Where the two streams cross most intimately, create soft, luminous glazes
  let crossings = [
    { x: width * 0.5, y: height * 0.62, r: 380, intensity: 0.7 },
    { x: width * 0.5, y: height * 0.35, r: 480, intensity: 1.0 },
    { x: width * 0.5, y: height * 0.16, r: 300, intensity: 0.6 }
  ];

  noStroke();
  for (let cr of crossings) {
    // Golden-rose atmospheric bloom
    for (let i = 0; i < 120; i++) {
      let angle = random(TWO_PI);
      let distFromCenter = abs(randomGaussian()) * (cr.r * 0.4);
      let x = cr.x + cos(angle) * distFromCenter;
      let y = cr.y + sin(angle) * distFromCenter;

      let size = map(distFromCenter, 0, cr.r, 180, 30) * random(0.6, 1.4);
      let h = random([35, 42, 48, 15, 350]);
      let s = map(distFromCenter, 0, cr.r, 20, 75);
      let b = 100;
      let a = map(distFromCenter, 0, cr.r, 0.04, 0.005) * cr.intensity;

      fill(h, s, b, a);
      push();
      translate(x, y);
      rotate(getFlowAngle(x, y));
      ellipse(0, 0, size * 1.8, size * 0.7);
      pop();
    }
  }

  // Intertwining ribbons of pure light at the main heart (y ~ 0.35)
  noFill();
  for (let i = 0; i < 450; i++) {
    let px = width * 0.5 + randomGaussian() * 110;
    let py = height * 0.38 + randomGaussian() * 140;

    strokeWeight(random(0.8, 2.5));
    let steps = floor(random(40, 120));

    for (let s = 0; s < steps; s++) {
      let taper = sin((s / steps) * PI);
      stroke(45, random(10, 45), 100, taper * 0.45);

      let angle = getFlowAngle(px, py) + sin(s * 0.15) * 0.25;
      let nx = px + cos(angle) * 3;
      let ny = py + sin(angle) * 3;

      line(px, py, nx, ny);
      px = nx;
      py = ny;
    }
  }
}

function drawEmbers() {
  noStroke();
  // Floating sparks of connection
  for (let i = 0; i < 1800; i++) {
    let t = random();
    let y = height * (0.05 + 0.9 * t);
    let cInfo = getSoulCenters(y);

    let spread = randomGaussian() * 260;
    let x = cInfo.centerX + spread;

    let dCenter = abs(x - cInfo.centerX);
    let prob = map(dCenter, 0, 500, 1, 0.1);
    if (random() > prob) continue;

    let col;
    if (dCenter < 140) {
      col = random(paletteGold);
    } else if (x < cInfo.centerX) {
      col = random() < 0.7 ? random(paletteWarm) : random(paletteCool);
    } else {
      col = random() < 0.7 ? random(paletteCool) : random(paletteWarm);
    }

    let r = random(1.5, 6.5);
    if (random() < 0.08) r = random(7, 14); // Occasional larger bokeh/droplet

    // Soft glow around larger embers
    if (r > 5) {
      fill(hue(col), saturation(col) * 0.8, 100, 0.12);
      ellipse(x, y, r * 3.5, r * 3.5);
      fill(hue(col), saturation(col) * 0.5, 100, 0.25);
      ellipse(x, y, r * 1.8, r * 1.8);
    }

    fill(hue(col), saturation(col) * 0.4, 100, random(0.4, 0.9));
    push();
    translate(x, y);
    rotate(getFlowAngle(x, y));
    ellipse(0, 0, r * 1.4, r * 0.9);
    pop();
  }
}

function applyCanvasTexture() {
  // Subtle woven linen feel and fine pigment grain
  loadPixels();
  let d = pixelDensity();
  let totalPixels = 4 * (width * d) * (height * d);

  for (let x = 0; x < width; x++) {
    // Vertical thread modulation
    let threadX = sin(x * 0.9) * 3;
    for (let y = 0; y < height; y++) {
      let threadY = sin(y * 0.9) * 3;
      let grain = (random() - 0.5) * 14 + (threadX + threadY);

      // Vignette darkening at the corners
      let distCorner = dist(x, y, width * 0.5, height * 0.48);
      let vig = map(distCorner, 600, 1300, 0, -22, true);

      let delta = grain + vig;

      let idx = 4 * (y * width + x);
      pixels[idx] = constrain(pixels[idx] + delta, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + delta, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + delta, 0, 255);
    }
  }
  updatePixels();
}

let particles = [];

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  drawBackground();

  // Centres des deux entités (Amants)
  let centerA = createVector(620, 1080);
  let centerB = createVector(980, 920);
  let midPoint = p5.Vector.lerp(centerA, centerB, 0.5);

  // Halo de connexion initiale en arrière-plan
  drawAura(centerA, color(345, 80, 70, 3), 900);
  drawAura(centerB, color(195, 80, 70, 3), 900);
  drawAura(midPoint, color(40, 90, 100, 5), 700);

  // Initialisation des courants d'âmes (particules)
  let numParticles = 5500;
  for (let i = 0; i < numParticles; i++) {
    let type = (i % 2 === 0) ? 'A' : 'B';
    let origin = (type === 'A') ? centerA : centerB;

    // Distribution en spirale/organique autour des centres
    let angle = random(TWO_PI);
    let dist = pow(random(1), 0.7) * 550;
    let x = origin.x + cos(angle) * dist;
    let y = origin.y + sin(angle) * dist;

    particles.push(new SoulThread(x, y, type, centerA, centerB));
  }

  // Simulation de la danse et du tissage (en plusieurs étapes pour entrelacer les couches)
  let steps = 160;
  for (let s = 0; s < steps; s++) {
    for (let i = 0; i < particles.length; i++) {
      particles[i].update(s, steps);
      particles[i].display(s, steps);
    }
  }

  // Éclats de lumière pure aux points de fusion intense
  drawSparks(midPoint);

  // Texture de toile peinte et grain final
  applyCanvasTexture();
}

function drawBackground() {
  background(250, 55, 8); // Nuit profonde

  // Nuages de fond picturaux
  noStroke();
  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);

    let dToCenter = dist(x, y, width / 2, height / 2);
    let normDist = constrain(dToCenter / 1200, 0, 1);

    let h = lerp(280, 220, n);
    let s = lerp(40, 70, normDist);
    let b = lerp(22, 4, normDist) * (0.5 + 0.5 * n);

    fill(h, s, b, random(2, 6));
    let r = random(80, 300);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, r, r * random(0.5, 1.5));
    pop();
  }
}

function drawAura(pos, col, maxRadius) {
  noStroke();
  fill(col);
  for (let i = 0; i < 60; i++) {
    let r = map(i, 0, 60, maxRadius, 20);
    let xOff = randomGaussian(0, r * 0.05);
    let yOff = randomGaussian(0, r * 0.05);
    ellipse(pos.x + xOff, pos.y + yOff, r, r);
  }
}

class SoulThread {
  constructor(x, y, type, cA, cB) {
    this.pos = createVector(x, y);
    this.prevPos = this.pos.copy();
    this.type = type;
    this.cA = cA;
    this.cB = cB;
    this.mid = p5.Vector.lerp(cA, cB, 0.5);
    this.vel = createVector(0, 0);

    // Variété dans les teintes de base
    if (this.type === 'A') {
      // Palette chaude : Cramoisi, Corail, Rose tendre, Or cuivré
      this.baseHue = random([335, 350, 10, 25]);
      this.baseSat = random(65, 95);
    } else {
      // Palette froide/sereine : Turquoise, Bleu nuit, Violet, Cyan lumineux
      this.baseHue = random([185, 205, 230, 265]);
      this.baseSat = random(55, 90);
    }

    this.baseBri = random(60, 95);
    this.strokeW = random(0.8, 4.5);
    this.speed = random(1.8, 3.8);
    this.noiseOffset = random(1000);
  }

  update(step, maxSteps) {
    this.prevPos = this.pos.copy();

    // Champ de bruit de Perlin pour le mouvement organique fluide
    let nScale = 0.0022;
    let n = noise(this.pos.x * nScale, this.pos.y * nScale, this.noiseOffset * 0.01);
    let flowDir = p5.Vector.fromAngle(n * TWO_PI * 3.5);

    // Vecteurs vers les centres et le point de fusion
    let toMid = p5.Vector.sub(this.mid, this.pos);
    let dMid = toMid.mag();
    toMid.normalize();

    // Force orbitale (tourbillon amoureux autour du centre commun)
    let swirl = createVector(-toMid.y, toMid.x);
    // Inverser légèrement le tourbillon très loin pour créer une composition en S (Yin-Yang abstrait)
    if (dMid > 600) {
      swirl.mult(map(dMid, 600, 1200, 1, -0.5));
    }

    // Force d'attraction vers l'autre entité
    let targetCenter = (this.type === 'A') ? this.cB : this.cA;
    let toOther = p5.Vector.sub(targetCenter, this.pos);
    toOther.normalize();

    // Combinaison des forces : l'amour guide le chaos
    let force = createVector(0, 0);
    force.add(p5.Vector.mult(flowDir, 1.3));
    force.add(p5.Vector.mult(swirl, 1.8));

    // Attraction gravitationnelle douce qui empêche la dispersion totale
    let pullStrength = map(constrain(dMid, 0, 900), 0, 900, 0.1, 1.6);
    force.add(p5.Vector.mult(toMid, pullStrength));
    force.add(p5.Vector.mult(toOther, 0.45));

    force.normalize();
    force.mult(this.speed);

    this.pos.add(force);
  }

  display(step, maxSteps) {
    let dA = p5.Vector.dist(this.pos, this.cA);
    let dB = p5.Vector.dist(this.pos, this.cB);
    let dMid = p5.Vector.dist(this.pos, this.mid);

    // Calcul de l'harmonie (proximité de la rencontre entre les deux forces)
    let harmony = exp(-dMid / 280); 
    let intimacy = exp(-abs(dA - dB) / 150) * exp(-dMid / 500);
    let fusion = constrain(harmony * 0.7 + intimacy * 0.6, 0, 1);

    // Évolution de la couleur vers l'or incandescent et le blanc pur au point de rencontre
    let h = this.baseHue;
    let goldHue = 42; 

    // Interpolation circulaire de la teinte vers l'or
    let diff = goldHue - h;
    if (diff > 180) diff -= 360;
    if (diff < -180) diff += 360;
    h = (h + diff * pow(fusion, 1.2) + 360) % 360;

    let s = lerp(this.baseSat, 25, pow(fusion, 2.5));
    let b = lerp(this.baseBri, 100, pow(fusion, 0.8));

    // Fondu doux au début et à la fin de la trace
    let lifeRatio = sin(map(step, 0, maxSteps, 0, PI));
    let alpha = lifeRatio * lerp(6, 22, fusion);

    strokeWeight(this.strokeW * lifeRatio * lerp(1, 1.8, fusion));
    stroke(h, s, b, alpha);
    line(this.prevPos.x, this.prevPos.y, this.pos.x, this.pos.y);

    // Touches de pinceau (empâtement / impasto) occasionnelles
    if (random(1) < 0.015 * (1 + fusion * 2)) {
      noStroke();
      fill(h, s * 0.9, min(100, b * 1.1), alpha * 2.2);
      push();
      translate(this.pos.x, this.pos.y);
      rotate(atan2(this.pos.y - this.prevPos.y, this.pos.x - this.prevPos.x));
      let bristleSize = this.strokeW * random(2, 5);
      ellipse(0, 0, bristleSize * 2.2, bristleSize * 0.7);
      pop();
    }
  }
}

function drawSparks(mid) {
  // Poussière d'étoiles et lumière d'éclosion au cœur de l'étreinte
  for (let i = 0; i < 900; i++) {
    let angle = random(TWO_PI);
    // Concentration au centre avec quelques éclats lointains
    let r = abs(randomGaussian(0, 220));

    // Déformation le long de l'axe de la danse (diagonale)
    let x = mid.x + cos(angle) * r;
    let y = mid.y + sin(angle) * r;

    let d = dist(x, y, mid.x, mid.y);
    let intensity = exp(-d / 200);

    noStroke();
    // Halo de l'éclat
    fill(random(30, 55), random(40, 80), 100, random(5, 20) * intensity);
    let sz = random(2, 14) * (0.4 + intensity);
    ellipse(x, y, sz, sz);

    // Cœur blanc brillant
    if (random(1) < 0.4) {
      fill(45, 15, 100, random(30, 70) * intensity);
      ellipse(x, y, sz * 0.35, sz * 0.35);
    }
  }

  // Filaments d'or fin reliant directement les deux cœurs
  noFill();
  for (let i = 0; i < 45; i++) {
    stroke(random(35, 50), random(20, 60), 100, random(8, 25));
    strokeWeight(random(0.5, 1.8));

    beginShape();
    let p = createVector(620 + randomGaussian(0, 60), 1080 + randomGaussian(0, 60));
    let target = createVector(980 + randomGaussian(0, 60), 920 + randomGaussian(0, 60));

    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(p.x, target.x, t);
      let y = lerp(p.y, target.y, t);
      let wave = sin(t * PI) * 180;
      let n = (noise(x * 0.005, y * 0.005, i) - 0.5) * wave;
      // Décalage perpendiculaire
      vertex(x + n, y - n);
    }
    endShape();
  }
}

function applyCanvasTexture() {
  // Crée un grain pictural subtil sur toute l'œuvre
  loadPixels();
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      let idx = (x + y * width) * 4;

      // Trame subtile de toile de lin
      let weave = (sin(x * 1.5) + sin(y * 1.5)) * 1.5;
      // Grain organique
      let grain = random(-6, 6);
      let mod = weave + grain;

      pixels[idx] = constrain(pixels[idx] + mod, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + mod, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + mod, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Fond : dégradé nocturne profond
  let bgTop = color(10, 12, 28);
  let bgBottom = color(28, 12, 24);
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(bgTop, bgBottom, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // 2. Texture de toile subtile en arrière-plan
  noStroke();
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    fill(255, 245, 235, n * 6);
    circle(x, y, random(1, 3.5));
  }

  // 3. Halo central : la chaleur de la rencontre
  blendMode(ADD);
  for (let r = 1300; r > 0; r -= 8) {
    let inter = map(r, 0, 1300, 1, 0);
    let c = lerpColor(color(45, 10, 35, 0), color(255, 110, 60, 4), pow(inter, 2.2));
    fill(c);
    // Légèrement décentré vers le haut pour l'élégance de la composition
    ellipse(width * 0.5, height * 0.48, r * 1.1, r * 1.4);
  }

  // 4. Définition des palettes pour les deux entités
  let paletteA = [
    color(255, 80, 50),   // Rouge vermillon
    color(255, 150, 30),  // Orange ardent
    color(255, 215, 90),  // Or lumineux
    color(240, 60, 90),   // Rose carmin
    color(255, 240, 190)  // Blanc chaud
  ];

  let paletteB = [
    color(20, 110, 230),  // Bleu outremer
    color(0, 190, 210),   // Cyan profond
    color(90, 50, 200),   // Violet indigo
    color(60, 235, 200),  // Turquoise lumineux
    color(190, 225, 255)  // Blanc givré
  ];

  // 5. Génération des flux (les deux amants)
  let numStreams = 3200;

  for (let i = 0; i < numStreams; i++) {
    let isA = (i % 2 === 0);

    // Points de départ : A en bas à gauche, B en bas à droite et haut
    let startX = isA ? random(-100, width * 0.65) : random(width * 0.35, width + 100);
    let startY = isA ? random(height * 0.65, height + 150) : random(height * 0.55, height + 150);

    // Quelques courants partent du haut pour fermer la composition
    if (random() < 0.25) {
      startX = isA ? random(-100, width * 0.4) : random(width * 0.6, width + 100);
      startY = random(-100, height * 0.5);
    }

    let x = startX;
    let y = startY;
    let baseCol = random(isA ? paletteA : paletteB);
    let maxSteps = int(random(120, 350));
    let thickness = random(0.8, 4.5);
    let alphaScale = random(8, 22);

    // Centre d'attraction (le cœur de l'étreinte)
    let centerX = width * 0.5;
    let centerY = height * 0.46;

    for (let step = 0; step < maxSteps; step++) {
      let n = noise(x * 0.0018, y * 0.0018, i * 0.0005);
      let angle = n * TWO_PI * 2.5;

      // Vecteur vers le centre
      let dx = x - centerX;
      let dy = y - centerY;
      let distToCenter = sqrt(dx * dx + dy * dy);

      // Force centripète et rotation (le tourbillon de l'étreinte)
      let angleToCenter = atan2(dy, dx);
      let vortexAngle = angleToCenter + PI * 0.62; // Spiraler vers l'intérieur

      // Plus on est proche du centre, plus la danse est serrée
      let pull = map(constrain(distToCenter, 0, 1000), 0, 1000, 0.75, 0.15);

      // Mélange du mouvement naturel (bruit) et de l'attraction amoureuse (vortex)
      let vx = cos(angle) * (1 - pull) + cos(vortexAngle) * pull;
      let vy = sin(angle) * (1 - pull) + sin(vortexAngle) * pull - 0.35; // Élévation globale

      x += vx * 3.5;
      y += vy * 3.5;

      // Calcul de la fusion des couleurs au centre
      let proximity = map(constrain(distToCenter, 40, 550), 40, 550, 1, 0);
      proximity = pow(proximity, 1.8);

      // Quand les deux forces se touchent, elles deviennent incandescentes (or rosé/blanc)
      let fusionColor = color(255, 225, 210);
      let currentCol = lerpColor(baseCol, fusionColor, proximity * 0.75);

      // Courbe d'opacité douce (apparition et disparition progressives)
      let stepAlpha = sin(map(step, 0, maxSteps, 0, PI)) * alphaScale;

      // Coup de pinceau
      stroke(red(currentCol), green(currentCol), blue(currentCol), stepAlpha);
      strokeWeight(thickness * (1 + proximity * 0.8));
      point(x, y);

      // Éclats d'étincelles / poussière d'or à la frontière de la rencontre
      if (proximity > 0.55 && random() < 0.015) {
        noStroke();
        fill(255, 245, 220, stepAlpha * 2.5);
        let sparkSize = random(1.5, 5);
        circle(x + random(-15, 15), y + random(-15, 15), sparkSize);
      }
    }
  }

  // 6. Courbes d'harmonie (fils d'or qui lient les deux âmes)
  noFill();
  for (let i = 0; i < 65; i++) {
    let t = i / 65;
    let alpha = sin(t * PI) * 35;
    stroke(255, 220, 180, alpha);
    strokeWeight(random(0.5, 1.8));

    beginShape();
    let cx = width * 0.5 + random(-250, 250);
    let cy = height * 0.46 + random(-350, 350);
    let rad = random(80, 450);
    let startA = random(TWO_PI);
    let endA = startA + random(PI * 0.4, PI * 1.4);

    for (let a = startA; a < endA; a += 0.05) {
      let r = rad + (noise(a * 1.5, i * 0.2) - 0.5) * 140;
      let px = cx + cos(a) * r;
      let py = cy + sin(a) * r * 1.3; // Étirement vertical
      curveVertex(px, py);
    }
    endShape();
  }

  // 7. Retour au mode normal pour les ombres et la vignette (profondeur picturale)
  blendMode(BLEND);

  // Quelques touches de matière sombre pour sculpter la lumière (clair-obscur)
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let distToCenter = dist(x, y, width * 0.5, height * 0.46);
    if (distToCenter > 380) {
      let angle = noise(x * 0.002, y * 0.002) * TWO_PI * 2;
      stroke(12, 10, 22, random(15, 40));
      strokeWeight(random(4, 18));
      let len = random(30, 120);
      line(x, y, x + cos(angle) * len, y + sin(angle) * len);
    }
  }

  // 8. Grain final sur toute la toile pour unifier la peinture
  noStroke();
  for (let i = 0; i < 60000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.5) {
      fill(255, 250, 240, random(2, 6));
    } else {
      fill(10, 5, 15, random(3, 8));
    }
    circle(x, y, random(0.5, 2));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  ellipseMode(CENTER);
  rectMode(CORNER);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  sky();
  skyTexture();
  atmosphere();
  sharedGround();
  aureole();
  drift(18, 21);
  figures();
  arms();
  lights();
  drift(26, 41);
  grain();
  vignette();
  lastSparks();
}

function wrapH(h) {
  return (h % 360 + 360) % 360;
}

function P(x, y) {
  return { x: x, y: y };
}

function cubic(p0, p1, p2, p3, n) {
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    let u = 1 - t;
    let uu = u * u;
    let tt = t * t;
    pts.push({
      x: uu * u * p0.x + 3 * uu * t * p1.x + 3 * u * tt * p2.x + tt * t * p3.x,
      y: uu * u * p0.y + 3 * uu * t * p1.y + 3 * u * tt * p2.y + tt * t * p3.y
    });
  }
  return pts;
}

function chain(parts) {
  let pts = [];
  for (let p = 0; p < parts.length; p++) {
    let start = p === 0 ? 0 : 1;
    for (let i = start; i < parts[p].length; i++) pts.push(parts[p][i]);
  }
  return pts;
}

function tremble(pts, amt, seed) {
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let n1 = noise(seed, i * 0.15);
    let n2 = noise(seed + 3, i * 0.15);
    out.push({
      x: pts[i].x + (n1 - 0.5) * amt,
      y: pts[i].y + (n2 - 0.5) * amt
    });
  }
  return out;
}

function bloom(x, y, rx, ry, h, s, b, a, layers) {
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let alpha = a * pow(1.02 - t, 1.35);
    fill(
      wrapH(h),
      constrain(s * lerp(0.5, 1, 1 - t), 0, 100),
      constrain(b, 0, 100),
      constrain(alpha, 0, 100)
    );
    ellipse(x, y, rx * 2 * t, ry * 2 * t);
  }
}

function cloud(cx, cy, rx, ry, rot, count, hue, sat, bri, alpha, seed) {
  push();
  translate(cx, cy);
  rotate(rot);
  noStroke();
  for (let i = 0; i < count; i++) {
    let n = noise(seed, i * 0.013);
    let n2 = noise(seed + 2, i * 0.021);
    let ang = random(TWO_PI);
    let rad = pow(random(), 0.5);
    let x = cos(ang) * rx * rad * lerp(0.85, 1.15, n);
    let y = sin(ang) * ry * rad * lerp(0.85, 1.15, n2);
    let w = lerp(rx * 0.42, 6, rad) * lerp(0.35, 1, random());
    fill(
      wrapH(hue + (n - 0.5) * 20),
      constrain(sat + (n2 - 0.5) * 14, 0, 100),
      constrain(bri + (1 - rad) * 14 + (n - 0.5) * 12, 0, 100),
      constrain(alpha * lerp(0.4, 1, 1 - rad) * lerp(0.55, 1, n2), 0, 100)
    );
    ellipse(x, y, max(1, w), max(1, w * lerp(0.55, 1, n2)));
  }
  pop();
}

function ribbon(pts, c0, c1, thick, alpha, wob, seed) {
  if (pts.length < 2) return;
  noStroke();
  for (let i = 0; i < pts.length; i++) {
    let t = i / (pts.length - 1);
    let env = lerp(1, 0.28, t);
    env *= 0.55 + 0.45 * sin(PI * min(t * 1.05, 1));
    let p0 = pts[max(0, i - 1)];
    let p1 = pts[min(pts.length - 1, i + 1)];
    let ang = atan2(p1.y - p0.y, p1.x - p0.x);
    let dx = p1.x - p0.x;
    let dy = p1.y - p0.y;
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    for (let d = 0; d < 6; d++) {
      let n = noise(seed, i * 0.07, d * 0.31);
      let n2 = noise(seed + 5, d * 0.17, i * 0.04);
      let side = (n - 0.5) * thick * env * wob;
      let x = pts[i].x + nx * side;
      let y = pts[i].y + ny * side;
      let w = thick * env * lerp(0.35, 1.1, n2);
      push();
      translate(x, y);
      rotate(ang + (n2 - 0.5) * 0.8);
      fill(
        wrapH(lerp(c0.h, c1.h, t) + (n - 0.5) * 14),
        constrain(lerp(c0.s, c1.s, t) + (n2 - 0.5) * 8, 0, 100),
        constrain(lerp(c0.b, c1.b, t) + (n - 0.45) * 16, 0, 100),
        constrain(alpha * lerp(0.45, 1, n2), 0, 100)
      );
      ellipse(0, 0, max(1, w), max(1, w * lerp(0.45, 0.85, n)));
      pop();
    }
  }
}

function sky() {
  background(228, 42, 7);
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let u = pow(t, 0.72);
    let h = lerp(228, 16, u);
    h = lerp(h, 318, sin(PI * t) * 0.22);
    h += (noise(y * 0.004, 0.3) - 0.5) * 6;
    let s = lerp(44, 36, t) + sin(PI * t) * 7;
    let b = lerp(7, 32, pow(t, 0.85));
    if (t > 0.9) b = lerp(b, 14, (t - 0.9) / 0.1);
    stroke(wrapH(h), constrain(s, 0, 100), constrain(b, 0, 100), 100);
    strokeWeight(2);
    line(0, y, width, y);
  }
}

function skyTexture() {
  strokeCap(ROUND);
  for (let i = 0; i < 2200; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0016, y * 0.0016);
    let ang = n * TWO_PI;
    let len = lerp(16, 64, noise(x * 0.01, y * 0.01));
    let yn = y / height;
    let h = lerp(226, 18, pow(yn, 0.8)) + (n - 0.5) * 12;
    let b = lerp(12, 34, pow(yn, 0.75)) + (n - 0.5) * 6;
    stroke(wrapH(h), 28, constrain(b, 0, 100), lerp(2.5, 7, n));
    strokeWeight(lerp(1, 2.2, noise(i * 0.02, 2)));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len * 0.55);
  }
}

