function drift(n, seed) {
  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let y = lerp(1820, 360, pow(t, 0.82));
    let spread = lerp(46, 440, t);
    let x = 850 + (noise(seed, i * 0.23) - 0.5) * spread;
    let s = lerp(13, 3.5, t) * lerp(0.65, 1.25, noise(seed + 1, i * 0.1));
    let h = lerp(16, 42, noise(seed + 2, i * 0.07));
    if (noise(seed + 3, i) > 0.84) h = 304;
    push();
    translate(x, y);
    rotate(noise(seed + 4, i) * TWO_PI);
    noStroke();
    fill(
      wrapH(h),
      38,
      lerp(58, 96, t),
      constrain(lerp(7, 18, 1 - t) * lerp(0.55, 1, noise(seed + 5, i)), 0, 100)
    );
    ellipse(0, 0, s, s * lerp(0.35, 0.68, noise(seed + 6, i)));
    pop();
  }
}

