function corps(pathFn, c0, c1) {
  noStroke();
  let shared = color(234, 140, 108);
  for (let p = 0; p < 8; p++) {
    let spread = (p - 3.5) * 15;
    for (let i = 0; i < 156; i++) {
      let t = i / 155;
      let pt = pathFn(t);
      let qt = pathFn(constrain(t + 0.012, 0, 1));
      let ang = atan2(qt.y - pt.y, qt.x - pt.x);
      let nx = -sin(ang);
      let ny = cos(ang);
      let n = noise(p * 0.37, t * 1.55, 3.4);
      let near = exp(-pow((t - 0.73) / 0.16, 2));
      let fade = ss(0.02, 0.11, t) * (1 - ss(0.9, 1, t));
      let local = lerpColor(c0, c1, constrain(t * 0.82 + (n - 0.5) * 0.22, 0, 1));
      let col = lerpColor(local, shared, near * 0.3);
      let rr = 46 * (0.5 + n * 0.7) * (0.34 + 0.7 * sin(t * PI));
      let x = pt.x + nx * (spread + (n - 0.5) * 18);
      let y = pt.y + ny * spread * 0.28;
      push();
      translate(x, y);
      rotate(ang);
      fill(red(col), green(col), blue(col), (12 + 8 * n) * fade);
      ellipse(0, 0, rr * 1.55, rr * 0.96);
      pop();
    }
  }
}

function noyau(pathFn, c) {
  noStroke();
