    let fade = ss(0.05, 0.14, t) * (1 - ss(0.88, 1, t));
    fill(red(c), green(c), blue(c), 16 * fade);
    ellipse(pt.x + (n - 0.5) * 14, pt.y + (noise(t * 3, 1.2) - 0.5) * 10, 34 + n * 22, 26 + n * 8);
  }
}

function trait(pathFn, c, strands, weight, alpha) {
  noFill();
  for (let s = 0; s < strands; s++) {
    let spread = strands === 1 ? 0 : (s / (strands - 1) - 0.5) * 40;
    let phase = s * 2.17 + 3;
    for (let i = 0; i < 86; i++) {
      let t0 = i / 86;
      let t1 = (i + 1) / 86;
      let p = pathFn(t0);
      let q = pathFn(t1);
      let ang = atan2(q.y - p.y, q.x - p.x);
      let nx = -sin(ang);
      let ny = cos(ang);
      let j = (noise(phase, t0 * 2.3) - 0.5) * 20;
      let fade = ss(0.03, 0.12, t0) * (1 - ss(0.9, 1, t0));
      let w = weight * (0.55 + noise(phase, t0 * 3.1) * 0.8);
      stroke(red(c), green(c), blue(c), alpha * fade * (0.62 + noise(phase + 4, t0 * 5) * 0.5));
      strokeWeight(w);
      line(
        p.x + nx * spread + j,
        p.y + ny * spread * 0.4,
        q.x + nx * spread + j * 0.85,
        q.y + ny * spread * 0.4
      );
    }
  }
}

