function decaler(pathFn, dx, dy) {
  return function (t) {
    let p = pathFn(t);
    let wob = noise(dx * 0.02, t * 1.45, dy * 0.03 + 2);
    return {
      x: p.x + dx + (wob - 0.5) * 16,
      y: p.y + dy + (noise(t * 1.7, dx * 0.01) - 0.5) * 10
    };
  };
}

function courantIncarnat(t) {
  let y = lerp(1860, 330, t);
  let x = lerp(270, 590, t);
  x += sin(t * PI * 1.25) * 96;
  x += sin(t * PI * 3.1 + 0.5) * 26;
  x += (noise(t * 1.35, 2.2) - 0.5) * 64;
  let near = exp(-pow((t - 0.72) / 0.18, 2));
  x = lerp(x, 748, near * 0.92);
  return { x: x, y: y };
}

function courantDore(t) {
  let y = lerp(1910, 400, t);
  let x = lerp(1350, 1040, t);
  x -= sin(t * PI * 1.15 + 0.25) * 108;
  x -= sin(t * PI * 2.65 + 1.1) * 24;
  x += (noise(t * 1.28, 6.5) - 0.5) * 60;
  let near = exp(-pow((t - 0.745) / 0.17, 2));
  x = lerp(x, 918, near * 0.92);
  return { x: x, y: y };
}

function ss(a, b, t) {
  let x = constrain((t - a) / (b - a), 0, 1);
  return x * x * (3 - 2 * x);
}

// p5.js 1.11 — still painting, 1600 × 2000, no external assets

