function lipPoint(fig) {
  return worldPoint(fig.x, fig.y, fig.tilt, fig.facing, 112, 52);
}

function midpoint(p, q) {
  return { x: (p.x + q.x) / 2, y: (p.y + q.y) / 2 };
}

function worldPoint(cx, cy, tilt, facing, lx, ly) {
  const x = lx * facing;
  const y = ly;
  const co = cos(tilt);
  const sn = sin(tilt);
  return { x: cx + x * co - y * sn, y: cy + x * sn + y * co };
}

function dab(x, y, len, wid, ang, c, a) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(red(c), green(c), blue(c), constrain(a, 0, 255));
  ellipse(0, 0, abs(len), abs(wid));
  pop();
}

function wash(x, y, rx, ry, c, a, n) {
  for (let i = 0; i < n; i++) {
    const ang = random(TWO_PI);
    const rr = random(0.12, 1);
    dab(
      x + cos(ang) * rx * rr * 0.48,
      y + sin(ang) * ry * rr * 0.48,
      rx * random(0.22, 0.62),
      ry * random(0.12, 0.4),
      random(TWO_PI),
      c,
      a * random(0.35, 1)
    );
  }
}

function lightAt(x, y, kiss) {
  return constrain(1.08 - dist(x, y, kiss.x, kiss.y) / 820, 0.08, 1);
}

function skinTone(person, light) {
  let shadow, mid, lit, blush;
  if (person === 0) {
    shadow = color(108, 58, 70);
    mid = color(206, 132, 108);
    lit = color(255, 216, 188);
    blush = color(206, 84, 92);
  } else {
    shadow = color(96, 58, 72);
    mid = color(184, 118, 112);
    lit = color(242, 196, 174);
    blush = color(188, 76, 98);
  }
  let c = light < 0.45
    ? lerpColor(shadow, mid, light / 0.45)
    : lerpColor(mid, lit, (light - 0.45) / 0.55);
  if (random() < 0.07) c = lerpColor(c, color(78, 96, 112), 0.42);
  if (random() < 0.06) c = lerpColor(c, blush, 0.5);
  if (light > 0.72 && random() < 0.1) c = lerpColor(c, color(255, 236, 214), 0.55);
  return c;
}

function shadeFrom(base, light) {
  const r = red(base);
  const g = green(base);
  const b = blue(base);
  const shadow = color(r * 0.26 + 10, g * 0.28 + 12, b * 0.4 + 20);
  const lit = color(
    min(255, r * 1.04 + 30),
    min(255, g * 0.92 + 14),
    min(255, b * 0.72 + 8)
  );
  return lerpColor(shadow, lit, constrain(light, 0, 1));
}

function underTube(pts, w0, w1, c) {
  stroke(red(c), green(c), blue(c));
  noFill();
  for (let s = 0; s < pts.length - 1; s++) {
    const t = s / max(1, pts.length - 2);
    strokeWeight(lerp(w0, w1, t));
    line(pts[s].x, pts[s].y, pts[s + 1].x, pts[s + 1].y);
  }
  noStroke();
}

function ribbon(pts, w0, w1, base, passes, lx, ly) {
  for (let p = 0; p < passes; p++) {
    for (let s = 0; s < pts.length - 1; s++) {
      const d = dist(pts[s].x, pts[s].y, pts[s + 1].x, pts[s + 1].y);
      const steps = max(4, floor(d / 14));
      const ang = atan2(pts[s + 1].y - pts[s].y, pts[s + 1].x - pts[s].x);
      for (let i = 0; i < steps; i++) {
        const u = i / steps;
        const t = (s + u) / (pts.length - 1);
        const x = lerp(pts[s].x, pts[s + 1].x, u);
        const y = lerp(pts[s].y, pts[s + 1].y, u);
        const w = lerp(w0, w1, t);
        const nx = -sin(ang);
        const ny = cos(ang);
        const off = (noise(x * 0.012, y * 0.012, p) - 0.5) * w * 0.85;
        let light = lightAt(x, y, { x: lx, y: ly });
        light += map(off, -w, w, -0.08, 0.1);
        light += (noise(p, t * 2) - 0.5) * 0.12;
        let col = shadeFrom(base, light);
        if (random() < 0.05) col = lerpColor(col, color(42, 74, 70), 0.4);
        dab(
          x + nx * off,
          y + ny * off,
          w * random(0.7, 1.5),
          w * random(0.16, 0.38),
          ang + random(-0.25, 0.25),
          col,
          random(22, 48)
        );
      }
    }
  }
}

function ribbonSkin(pts, w0, w1, person, passes, kiss) {
  for (let p = 0; p < passes; p++) {
    for (let s = 0; s < pts.length - 1; s++) {
      const d = dist(pts[s].x, pts[s].y, pts[s + 1].x, pts[s + 1].y);
      const steps = max(4, floor(d / 12));
      const ang = atan2(pts[s + 1].y - pts[s].y, pts[s + 1].x - pts[s].x);
      for (let i = 0; i < steps; i++) {
        const u = i / steps;
        const t = (s + u) / (pts.length - 1);
        const x = lerp(pts[s].x, pts[s + 1].x, u);
        const y = lerp(pts[s].y, pts[s + 1].y, u);
        const w = lerp(w0, w1, t);
        const nx = -sin(ang);
        const ny = cos(ang);
        const off = (noise(y * 0.01, x * 0.01, p + 3) - 0.5) * w * 0.8;
        const light = constrain(lightAt(x + nx * off, y + ny * off, kiss) + random(-0.05, 0.08), 0.06, 1);
        dab(
          x + nx * off,
          y + ny * off,
          w * random(0.75, 1.45),
          w * random(0.2, 0.42),
          ang + random(-0.3, 0.3),
          skinTone(person, light),
          random(26, 54)
        );
      }
    }
  }
}

function paintRoom() {
  background(16, 14, 24);
  noStroke();
  for (let y = 0; y < height; y += 2) {
    const t = y / height;
    let c = lerpColor(color(20, 22, 34), color(34, 22, 30), t);
    if (y > 1700) c = lerpColor(c, color(12, 10, 16), (y - 1700) / 300);
    fill(c);
    rect(0, y, width, 3);
  }
  for (let i = 0; i < 2400; i++) {
    const x = random(width);
    const y = random(height * 0.9);
    const n = noise(x * 0.0025, y * 0.0025);
    let c = lerpColor(color(26, 32, 48), color(54, 38, 44), n);
    if (x > 600 && x < 1060 && y > 640 && y < 1320) {
      c = lerpColor(c, color(96, 58, 60), 0.38);
    }
    if (x < 260) c = lerpColor(c, color(36, 44, 58), 0.35);
    dab(x, y, random(8, 20), random(30, 100), random(-0.1, 0.1), c, random(10, 22));
  }
  for (let i = 0; i < 500; i++) {
    const x = random(width);
    const y = random(1760, 1990);
    dab(x, y, random(20, 54), random(4, 9), random(-0.04, 0.04), color(18, 14, 22), random(14, 28));
  }
  wash(820, 1888, 420, 70, color(120, 64, 48), 4, 24);
}

function paintWindow() {
  for (let i = 0; i < 820; i++) {
    const x = lerp(random(430, 1120), 740, 0.4);
    const y = random(36, 780);
    const fall = constrain(1 - dist(x, y, 740, 390) / 540, 0, 1);
    if (fall < 0.04) continue;
    const c = lerpColor(color(108, 124, 142), color(186, 202, 214), fall);
    dab(x, y, random(7, 16), random(28, 120), random(-0.07, 0.07), c, 6 + fall * 14);
  }
}

function paintCurtain(x0, x1, y0, y1) {
  for (let i = 0; i < 380; i++) {
    const x = random(x0, x1);
    const y = random(y0, y1);
    const fold = 0.5 + 0.5 * sin((x - x0) * 0.045 + noise(y * 0.01) * 1.4);
    const c = lerpColor(color(24, 30, 42), color(64, 58, 68), fold);
    dab(x, y, random(10, 24), random(36, 130), random(-0.06, 0.06), c, random(16, 34));
  }
}

function paintDivan() {
  wash(800, 1620, 980, 220, color(32, 18, 26), 18, 50);
  for (let i = 0; i < 420; i++) {
    const x = random(260, 1360);
    const y = random(1506, 1760);
    const top = constrain(1 - (y - 1506) / 80, 0, 1);
    const c = lerpColor(color(28, 16, 24), color(72, 48, 52), top * 0.7);
    dab(x, y, random(24, 60), random(6, 12), random(-0.05, 0.05), c, random(16, 34));
  }
  for (let i = 0; i < 80; i++) {
    const t = i / 79;
    dab(
      lerp(300, 1320, t) + random(-3, 3),
      lerp(1508, 1542, t) + random(-2, 2),
      random(16, 36),
      random(4, 7),
      -0.02,
      color(118, 86, 78),
      random(18, 36)
    );
  }
}

function paintHairMass(x, y, w, h, rot, c) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(c);
  ellipse(0, 0, w, h);
  pop();
  for (let i = 0; i < 180; i++) {
    const ang = random(TWO_PI);
    const rr = random(0.2, 1);
    dab(
      x + cos(ang) * w * 0.42 * rr,
      y + sin(ang) * h * 0.42 * rr,
      random(18, 40),
      random(8, 16),
      rot + random(-0.4, 0.4),
      lerpColor(c, color(70, 36, 28), random(0.2)),
      random(20, 40)
    );
  }
}

function paintShoulder(x, y, person, light) {
  for (let i = 0; i < 70; i++) {
    dab(
      x + random(-36, 36),
      y + random(-22, 26),
      random(18, 36),
      random(10, 18),
      random(-0.4, 0.4),
      skinTone(person, light * random(0.75, 1)),
      random(30, 55)
    );
  }
}

function paintCloth(kiss) {
  wash(830, 1588, 820, 300, color(48, 20, 40), 14, 70);
  const folds = [
    [{ x: 630, y: 1310 }, { x: 548, y: 1504 }, { x: 470, y: 1696 }],
    [{ x: 708, y: 1336 }, { x: 676, y: 1536 }, { x: 620, y: 1736 }],
    [{ x: 824, y: 1352 }, { x: 800, y: 1552 }, { x: 764, y: 1752 }],
    [{ x: 948, y: 1332 }, { x: 992, y: 1532 }, { x: 1068, y: 1728 }],
    [{ x: 1056, y: 1308 }, { x: 1148, y: 1500 }, { x: 1236, y: 1688 }]
  ];
  const cols = [
    color(96, 28, 48),
    color(46, 30, 78),
    color(82, 30, 56),
    color(38, 34, 84),
    color(90, 32, 54)
  ];
  for (let i = 0; i < folds.length; i++) {
    underTube(folds[i], 130, 168, cols[i]);
    ribbon(folds[i], 120, 156, cols[i], 3, kiss.x, kiss.y);
  }
  for (let i = 0; i < 36; i++) {
    const t = i / 35;
    dab(
      lerp(700, 860, t) + random(-4, 4),
      lerp(1470, 1688, t),
      random(12, 26),
      random(3, 6),
      1.2,
      color(232, 196, 120),
      random(28, 60)
    );
  }
}

function paintHead(fig) {
  push();
  translate(fig.x, fig.y);
  rotate(fig.tilt);
  scale(fig.facing, 1);

  noStroke();
  fill(fig.skin === 0 ? color(154, 96, 84) : color(140, 90, 86));
  ellipse(-28, 6, 214, 272);
  fill(fig.skin === 0 ? color(140, 86, 76) : color(128, 80, 78));
  ellipse(-6, 132, 74, 96);

  for (let i = 0; i < 720; i++) {
    const lx = random(-136, 132);
    const ly = random(-146, 158);
    const ex = (lx + 28) / 107;
    const ey = (ly - 6) / 136;
    const inSkull = ex * ex + ey * ey <= 1.06;
    const inNose = lx > 36 && lx < 142 && ly > -16 && ly < 72 && abs(ly - 16) < 26 + (142 - lx) * 0.12;
    const inChin = ly > 78 && ly < 162 && abs(lx - 8) < 52;
    if (!inSkull && !inNose && !inChin) continue;
    const light = constrain(0.16 + (lx + 24) / 150 - ly / 900, 0.06, 1);
    const ang = noise(lx * 0.02, ly * 0.02) * 1.1 - 0.15;
    dab(lx, ly, random(20, 48), random(7, 15), ang, skinTone(fig.skin, light), random(30, 58));
  }

  dab(-96, 8, 36, 90, 0.15, color(36, 44, 64), 22);
  dab(8, 108, 54, 18, 0.1, color(78, 40, 48), 36);

  fill(fig.skin === 0 ? color(168, 104, 92) : color(154, 96, 90));
  ellipse(-124, 10, 34, 58);
  fill(90, 48, 56, 90);
  ellipse(-124, 12, 14, 28);
  dab(-124, 40, 7, 7, 0, fig.skin === 0 ? color(220, 176, 92) : color(186, 196, 206), 170);

  dab(30, -24, 40, 16, 0.08, color(110, 62, 70), 32);
  for (let i = 0; i < 16; i++) {
    const t = i / 15;
    const x = lerp(10, 58, t);
    const y = -15 + sin(t * PI) * 6;
    dab(x, y, 8, 2.4, -0.25 + t * 0.2, color(58, 30, 36), 130);
  }
  for (let i = 0; i < 7; i++) {
    dab(14 + i * 2.2, -18 - i * 1.3, 6, 1.6, -1.1, color(42, 24, 28), 110);
  }
  dab(52, -12, 4, 3, 0.2, color(255, 220, 206), 120);

  for (let i = 0; i < 9; i++) {
    dab(8 + i * 5.2, -43 + i * 0.35, 11, 3.2, -0.08, color(62, 32, 32), 75);
  }

  for (let i = 0; i < 12; i++) {
    const t = i / 11;
    dab(lerp(48, 126, t), lerp(-10, 14, t), 12, 4, 0.28, color(255, 224, 204), 36 + t * 50);
  }
  dab(114, 30, 18, 8, 0.35, color(104, 52, 60), 60);
  dab(118, 26, 6, 4, 0.4, color(64, 28, 36), 120);
  dab(78, 6, 16, 10, 0.3, color(96, 50, 58), 28);

  for (let i = 0; i < 22; i++) {
    dab(100 + random(-9, 11), 46 + random(-3, 3), random(10, 18), random(4, 7), random(-0.2, 0.25), color(168, 58, 70), random(80, 140));
  }
  for (let i = 0; i < 26; i++) {
    dab(104 + random(-9, 11), 59 + random(-3, 4), random(12, 20), random(5, 8), 0.12, color(186, 78, 84), random(90, 150));
  }
  for (let i = 0; i < 8; i++) {
    dab(94 + i * 3.2, 52, 5, 1.7, 0.12, color(84, 28, 40), 110);
  }
  dab(100, 72, 22, 6, 0.1, color(86, 38, 48), 40);
  dab(110, 57, 8, 3, 0.2, color(255, 214, 200), 150);
  dab(72, 28, 28, 16, 0.2, color(196, 82, 90), 28);

  const profile = [
    { x: 22, y: -80 },
    { x: 52, y: -42 },
    { x: 90, y: -8 },
    { x: 126, y: 14 },
    { x: 118, y: 40 },
    { x: 108, y: 54 },
    { x: 72, y: 98 },
    { x: 40, y: 126 }
  ];
  for (let i = 0; i < profile.length - 1; i++) {
    for (let k = 0; k < 4; k++) {
      const t = k / 4;
      const x = lerp(profile[i].x, profile[i + 1].x, t);
      const y = lerp(profile[i].y, profile[i + 1].y, t);
      const ang = atan2(profile[i + 1].y - profile[i].y, profile[i + 1].x - profile[i].x);
      dab(x, y, 10, 3.2, ang, color(255, 228, 208), 64);
    }
  }

  for (let i = 0; i < 16; i++) {
    dab(76 + random(-10, 8), 22 + random(-8, 8), random(8, 16), random(4, 7), random(-0.2, 0.3), color(255, 236, 220), random(40, 80));
  }

  pop();
}

function hairStrand(x1, y1, cx, cy, x2, y2, c, w, coolRim) {
  for (let i = 0; i <= 22; i++) {
    const t = i / 22;
    const x = bezierPoint(x1, cx, cx, x2, t);
    const y = bezierPoint(y1, cy, cy, y2, t);
    const xn = bezierPoint(x1, cx, cx, x2, min(1, t + 0.03));
    const yn = bezierPoint(y1, cy, cy, y2, min(1, t + 0.03));
    const ang = atan2(yn - y, xn - x);
    dab(x, y, w * random(1.1, 2.2), w * random(0.28, 0.5), ang + random(-0.15, 0.15), c, random(28, 64));
    if (coolRim && t < 0.45 && random() < 0.35) {
      dab(x, y, w * 0.8, w * 0.22, ang, color(198, 214, 224), 36);
    }
    if (!coolRim && random() < 0.2) {
      dab(x, y, w * 0.7, w * 0.2, ang, color(176, 92, 54), 30);
    }
  }
}

function paintHairFront(A, B) {
  const topA = worldPoint(A.x, A.y, A.tilt, A.facing, -16, -132);
  const topB = worldPoint(B.x, B.y, B.tilt, B.facing, -8, -128);
  const sideA = worldPoint(A.x, A.y, A.tilt, A.facing, -118, 8);
  const sideB = worldPoint(B.x, B.y, B.tilt, B.facing, -116, 16);

  hairStrand(topA.x, topA.y, 560, 760, 490, 1120, color(62, 24, 20), 7, false);
  hairStrand(topA.x + 10, topA.y + 8, 600, 800, 528, 1210, color(48, 18, 16), 8, false);
  hairStrand(sideA.x, sideA.y, 540, 980, 500, 1288, color(78, 32, 24), 5, false);
  hairStrand(topA.x + 24, topA.y, 690, 690, 640, 760, color(92, 40, 28), 4, true);

  hairStrand(topB.x, topB.y, 1088, 780, 1172, 1188, color(18, 14, 20), 8, true);
  hairStrand(topB.x - 8, topB.y + 6, 1128, 860, 1204, 1320, color(14, 12, 18), 7, true);
  hairStrand(sideB.x, sideB.y, 1160, 1020, 1210, 1404, color(22, 18, 26), 5, true);
  hairStrand(1148, 1120, 1168, 1160, 1202, 1264, color(20, 16, 24), 3.5, true);
  hairStrand(1124, 1168, 1160, 1210, 1194, 1288, color(28, 20, 26), 3, false);

  for (let i = 0; i < 40; i++) {
    dab(topA.x + random(-30, 40), topA.y + random(-10, 24), random(10, 22), random(3, 6), random(-0.6, 0.2), color(186, 206, 216), 28);
    dab(topB.x + random(-20, 36), topB.y + random(-8, 20), random(10, 20), random(3, 6), random(-0.2, 0.5), color(196, 214, 222), 30);
  }
}

function paintHand(x, y, rot, person, lit) {
  wash(x + 8, y + 14, 70, 36, color(16, 8, 18), 12, 10);
  push();
  translate(x, y);
  rotate(rot);
  for (let i = 0; i < 90; i++) {
    dab(random(-26, 30), random(-18, 24), random(16, 30), random(10, 16), random(-0.3, 0.3), skinTone(person, lit * random(0.72, 1)), random(36, 70));
  }
  for (let f = 0; f < 4; f++) {
    const fx = -18 + f * 12;
    for (let k = 0; k < 10; k++) {
      const t = k / 9;
      dab(fx + random(-1.5, 1.5), -16 - t * 78, 12, 9, 0.04, skinTone(person, lit * (1 - t * 0.12)), 64);
    }
    if (f < 3) dab(fx + 6, -58, 3.5, 36, 0.04, color(72, 36, 44), 32);
  }
  for (let k = 0; k < 10; k++) {
    const t = k / 9;
    dab(-26 - t * 10, 8 + t * 36, 13, 9, -0.7, skinTone(person, lit), 64);
  }
  dab(2, -12, 16, 6, 0.15, color(255, 230, 210), 80);
  pop();
}

