function paintVein(pts) {
  for (let s = 0; s < pts.length - 1; s++) {
    for (let i = 0; i < 12; i++) {
      if (random() < 0.28) continue;
      const u = i / 12;
      const x = lerp(pts[s].x, pts[s + 1].x, u) + random(-7, 7);
      const y = lerp(pts[s].y, pts[s + 1].y, u) + random(-4, 4);
      const ang = atan2(pts[s + 1].y - pts[s].y, pts[s + 1].x - pts[s].x);
      dab(x, y, random(10, 26), random(3, 6.5), ang + random(-0.45, 0.45), color(255, 208, 142), random(28, 68));
      if (random() < 0.3) dab(x, y, 7, 3, ang, color(255, 244, 224), 76);
    }
  }
}

