    const a = rot + i * TWO_PI / 6 + random(-0.08, 0.08);
    for (let k = 0; k < 5; k++) {
      const t = k / 4;
      const px = x + cos(a) * s * 0.34 * t;
      const py = y + sin(a) * s * 0.34 * t;
      dab(px, py, s * random(0.42, 0.62), s * random(0.18, 0.28), a, lerpColor(color(255, 214, 206), petal, t), random(28, 52));
    }
  }
  dab(x, y, s * 0.26, s * 0.26, 0, color(206, 150, 64), 70);
}

