function skyColor(t) {
  const stops = [
    [0.0, 18, 26, 62],
    [0.14, 34, 42, 92],
    [0.28, 62, 54, 112],
    [0.42, 104, 72, 116],
    [0.54, 150, 90, 110],
    [0.64, 190, 112, 106],
    [0.73, 226, 158, 124],
    [0.82, 170, 98, 84],
    [0.92, 88, 50, 44],
    [1.0, 48, 28, 26]
  ];
  let i = 0;
  while (i < stops.length - 2 && t > stops[i + 1][0]) i++;
  const a = stops[i];
  const b = stops[i + 1];
  const u = constrain((t - a[0]) / (b[0] - a[0]), 0, 1);
  return [lerp(a[1], b[1], u), lerp(a[2], b[2], u), lerp(a[3], b[3], u)];
}

function drawSky() {
  for (let y = 0; y < 2000; y++) {
    const c = skyColor(y / 1999);
    stroke(c[0], c[1], c[2]);
    strokeWeight(1.6);
    line(0, y, 1600, y);
  }
}

function drawStars() {
  for (let i = 0; i < 140; i++) {
    const x = random(30, 1570);
    const y = random(16, 860);
    if (dist(x, y, 1272, 268) < 120) continue;
    if (noise(x * 0.012, y * 0.012) < 0.42) continue;
    const fade = constrain((780 - y) / 620, 0, 1);
    const s = random(0.7, 2.5);
    const a = random(70, 200) * fade;
    noStroke();
    fill(255, 244, 226, a);
    ellipse(x, y, s, s);
    if (s > 2) {
      stroke(255, 244, 226, a * 0.4);
      strokeWeight(0.5);
      line(x - s * 2.6, y, x + s * 2.6, y);
      line(x, y - s * 2.6, x, y + s * 2.6);
    }
  }
}

