function distantRidge(x) {
  const center = Math.exp(-pow((x - 830) / 460, 2));
  const n = noise(x * 0.0022, 3.3) * 56 + noise(x * 0.008, 6) * 16;
  return 1478 + center * 70 - n * 0.4;
}

function drawHills() {
  noStroke();
