  beginShape();
  vertex(0, 1720);
  for (let x = 0; x <= 1600; x += 10) vertex(x, distantRidge(x));
  vertex(1600, 1720);
  endShape(CLOSE);
  fill(86, 74, 108, 70);
  beginShape();
  vertex(0, 1700);
  for (let x = 0; x <= 1600; x += 10) {
    vertex(x, distantRidge(x) + 30 + noise(x * 0.01, 9) * 12);
