function groundY(x) {
  const knoll = 22 * Math.exp(-pow((x - 840) / 340, 2));
  const roll = noise(x * 0.0024, 8.2) * 26 + noise(x * 0.009, 2.4) * 7;
  return 1556 - knoll - roll * 0.35;
}

function drawGround() {
  noStroke();
  fill(54, 32, 26);
  beginShape();
  vertex(0, 2000);
  vertex(0, groundY(0));
  for (let x = 0; x <= 1600; x += 8) vertex(x, groundY(x));
  vertex(1600, groundY(1600));
  vertex(1600, 2000);
  endShape(CLOSE);
  for (let i = 0; i < 1700; i++) {
    const x = random(1600);
    const gy = groundY(x);
    const y = random(gy - 2, 1996);
    const warm = glowAmt(x, y, 840, gy + 10, 420);
    fill(
      44 + warm * 78 + random(-8, 8),
      26 + warm * 30 + random(-6, 6),
      18 + random(8),
      random(26, 62)
    );
    ellipse(x, y, random(12, 42), random(6, 16));
  }
}

function quadPoint(x0, y0, cx, cy, x1, y1, t) {
  const u = 1 - t;
  return [
    u * u * x0 + 2 * u * t * cx + t * t * x1,
    u * u * y0 + 2 * u * t * cy + t * t * y1
  ];
}

function wood(x0, y0, cx, cy, x1, y1, w0, w1, lightDir, seed, shade) {
  noStroke();
  for (let i = 0; i < 40; i++) {
    const t = i / 39;
    const p = quadPoint(x0, y0, cx, cy, x1, y1, t);
    const w = lerp(w0, w1, t) * (0.86 + noise(seed, t * 4.2) * 0.3);
    const x = p[0] + (noise(seed + 2, t * 5) - 0.5) * w * 0.16;
    const y = p[1] + (noise(seed + 4, t * 3) - 0.5) * 2.5;
    fill(22 * shade, 12 * shade, 10, 50);
    ellipse(x + 2, y + 2, w, w * 0.45);
    fill(78 * shade, 46 * shade, 32 * shade, 155);
    ellipse(x, y, w * 0.76, w * 0.36);
    fill(36 * shade, 24 * shade, 28, 60);
    ellipse(x - lightDir * w * 0.15, y, w * 0.26, w * 0.18);
    fill(170 * shade, 112 * shade, 74 * shade, 38);
    ellipse(x + lightDir * w * 0.13, y - 1, w * 0.15, w * 0.12);
  }
  for (let k = 0; k < 26; k++) {
    const t = random(0.05, 0.92);
    const p = quadPoint(x0, y0, cx, cy, x1, y1, t);
    const w = lerp(w0, w1, t);
    const ox = random(-w * 0.2, w * 0.2);
    stroke(36 * shade, 18, 12, random(30, 95));
    strokeWeight(random(0.5, 1.5));
    const len = random(5, Math.max(8, w * 0.7));
    line(p[0] + ox, p[1] - len * 0.1, p[0] + ox + random(-2, 2), p[1] + len);
  }
}

