function glowAmt(x, y, cx, cy, rad) {
  const k = constrain(1 - dist(x, y, cx, cy) / rad, 0, 1);
  return k * k;
}

function leafRGBA(x, y, front) {
  const moon = glowAmt(x, y, 1272, 268, 780);
  const hearth = glowAmt(x, y, 820, 1360, 640);
  const n = noise(x * 0.011, y * 0.011);
  let r = 26 + n * 24 + hearth * 100 + moon * 28;
  let g = 58 + n * 30 + hearth * 36 + moon * 34;
  let b = 42 + n * 12 + moon * 22 - hearth * 10;
  if (!front) {
    r *= 0.72;
    g *= 0.75;
    b *= 0.78;
  }
  if (random() < 0.035 + hearth * 0.1) {
    r = 156 + random(48);
    g = 118 + random(36);
    b = 42 + random(24);
  } else if (random() < 0.012) {
    r = 128 + random(40);
    g = 32 + random(16);
    b = 40 + random(12);
  }
  const a = (front ? 168 : 128) + random(62);
  return [
    constrain(r, 0, 255),
    constrain(g, 0, 255),
    constrain(b, 0, 255),
    constrain(a, 0, 230)
  ];
}

function clearingAmount(x, y) {
  const nx = (x - 820) / 230;
  const ny = (y - 1290) / 320;
  const e = Math.sqrt(nx * nx + ny * ny);
  if (e > 1.15) return 0;
  if (e < 0.82) return 1;
  return (1.15 - e) / 0.33;
}

function spray(cx, cy, rx, ry, n, seed, front) {
  noStroke();
  for (let i = 0; i < n; i++) {
    const a = random(TWO_PI);
    const rad = pow(random(), 0.48);
    const x = cx + cos(a) * rx * rad;
    const y = cy + sin(a) * ry * rad;
    if (rad > 0.62 && noise(x * 0.006 + seed, y * 0.006) < 0.48) continue;
    if (random() < clearingAmount(x, y)) continue;
    const lc = leafRGBA(x, y, front);
    const rim = constrain((cy - y) / ry, 0, 1);
    if (rim > 0.45) {
      const k = (rim - 0.45) * 0.85;
      lc[0] = lerp(lc[0], 176, k);
      lc[1] = lerp(lc[1], 168, k);
      lc[2] = lerp(lc[2], 132, k);
    }
    const s = random(front ? 8 : 12, front ? 24 : 34) * (1.12 - rad * 0.28);
    fill(lc[0], lc[1], lc[2], lc[3]);
    if (random() < 0.24) {
      push();
      translate(x, y);
      rotate(noise(x * 0.02, y * 0.02 + seed) * TWO_PI);
      ellipse(0, 0, s * 1.7, s * 0.4);
      pop();
    } else {
      ellipse(x, y, s, s * random(0.48, 0.86));
    }
  }
}

function drawFoliage() {
  const crowns = [
    [430, 860, 300, 220, 1000, 1],
    [680, 720, 250, 180, 820, 2],
    [830, 640, 220, 160, 740, 3],
    [1000, 730, 240, 180, 820, 4],
    [1180, 880, 290, 210, 1000, 5],
    [300, 980, 180, 140, 360, 6],
    [1340, 1000, 170, 130, 320, 7],
    [560, 1000, 150, 110, 280, 8],
    [1080, 1020, 160, 120, 280, 9]
  ];
  for (let i = 0; i < crowns.length; i++) {
    const c = crowns[i];
    spray(c[0], c[1], c[2], c[3], c[4], c[5], false);
  }
  for (let i = 0; i < crowns.length; i++) {
    const c = crowns[i];
    spray(c[0], c[1] + 6, c[2] * 0.92, c[3] * 0.9, floor(c[4] * 0.55), c[5] + 20, true);
  }
}

function twig(x0, y0, x1, y1) {
  stroke(42, 28, 20, 175);
  strokeWeight(random(0.8, 1.5));
  noFill();
  bezier(
    x0, y0,
    lerp(x0, x1, 0.35) + random(-12, 12), lerp(y0, y1, 0.35),
    lerp(x0, x1, 0.7) + random(-10, 10), lerp(y0, y1, 0.75),
    x1, y1
  );
  noStroke();
  fill(214, 152, 152, 185);
  ellipse(x1, y1, random(3, 5.2), random(4, 6.4));
}

function drawTwigs() {
  const tips = [
    [600, 760, 520, 540],
    [680, 700, 650, 500],
    [760, 660, 770, 478],
    [840, 650, 880, 492],
    [940, 690, 1010, 524],
