// p5.js v1.11
const W = 1600;
const H = 2000;

let ribbonA, ribbonB;

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 100);
  randomSeed(1);
  noiseSeed(1);

  ribbonA = makeRibbonPath(-1, 340);
  ribbonB = makeRibbonPath(1, 340);

  noLoop();
}

function draw() {
  drawBackground();

  blendMode(ADD);
  drawNebula(48);
  blendMode(BLEND);

  // dark body of the two silk ribbons
  drawRibbonShape(ribbonA, color(52, 8, 32, 78), 1.6);
  drawRibbonShape(ribbonB, color(8, 18, 52, 78), 1.6);

  blendMode(ADD);
  drawRibbonGlow(ribbonA, color(255, 90, 120, 7), 130);
  drawRibbonGlow(ribbonB, color(90, 150, 255, 7), 130);

  drawRibbonShape(ribbonA, color(255, 82, 108, 20), 1.35);
  drawRibbonShape(ribbonB, color(68, 140, 255, 20), 1.35);

  drawRibbonShape(ribbonA, color(255, 160, 120, 24), 0.9);
  drawRibbonShape(ribbonB, color(150, 230, 255, 24), 0.9);

  drawRibbonShape(ribbonA, color(255, 225, 190, 15), 0.5);
  drawRibbonShape(ribbonB, color(220, 245, 255, 15), 0.5);

  drawRibbonCore(ribbonA, color(255, 210, 170, 42));
  drawRibbonCore(ribbonB, color(190, 230, 255, 42));

  drawUnionGlow();
  drawSparks(650);

  blendMode(BLEND);
  drawVignette();
}

function drawBackground() {
  const ctx = drawingContext;
  const grad = ctx.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0, '#080515');
  grad.addColorStop(0.52, '#1b0e2c');
  grad.addColorStop(1, '#2a0e22');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
}

function drawVignette() {
  const ctx = drawingContext;
  const grad = ctx.createRadialGradient(W/2, H*0.42, 160, W/2, H*0.42, 1750);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,0.52)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
}

function drawNebula(count) {
  const palette = [
    color(255, 80, 120, 12),
    color(90, 140, 255, 12),
    color(190, 80, 255, 12),
    color(255, 170, 90, 12)
  ];

  for (let i = 0; i < count; i++) {
    const x = random() * W;
    const y = random() * H;
    const r = random(160, 400);
    ctxGlow(x, y, r, random(palette));
  }
}

function makeRibbonPath(side, N) {
  const pts = [];
  const x0 = 800, y0 = 2200;
  const x1 = 1020, y1 = 1550;
  const x2 = 580, y2 = 750;
  const x3 = 800, y3 = 350;

  const phase = side === -1 ? 0 : PI;

  for (let i = 0; i < N; i++) {
    const t = i / (N - 1);
    const bx = bezierPoint(x0, x1, x2, x3, t);
    const by = bezierPoint(y0, y1, y2, y3, t);
    const tx = bezierTangent(x0, x1, x2, x3, t);
    const ty = bezierTangent(y0, y1, y2, y3, t);
    const len = Math.hypot(tx, ty) || 1;
    const nx = -ty / len;
    const ny = tx / len;

    const env = sin(t * PI);
    const wave = sin(t * PI * 6 + phase) * env * 200;
    const nudge = (noise(t * 3.4 + side * 20, 4.8) - 0.5) * env * 80;
    const offset = wave + nudge;

    pts.push({
      x: bx + nx * offset,
      y: by + ny * offset,
      nx,
      ny
    });
  }
  return pts;
}

function drawRibbonShape(pts, col, widthScale) {
  const N = pts.length;
  const left = [];
  const right = [];

  for (let i = 0; i < N; i++) {
    const t = i / (N - 1);
    const env = sin(t * PI);
    const w = (140 * pow(env, 0.66) + 18) * widthScale;
    const p = pts[i];
    left.push({ x: p.x + p.nx * w, y: p.y + p.ny * w });
    right.push({ x: p.x - p.nx * w, y: p.y - p.ny * w });
  }

  noStroke();
  fill(col);
  beginShape();
  for (let i = 0; i < N; i++) vertex(left[i].x, left[i].y);
  for (let i = N - 1; i >= 0; i--) vertex(right[i].x, right[i].y);
  endShape(CLOSE);
}

function drawRibbonCore(pts, col) {
  noFill();
  stroke(col);
  strokeWeight(3.5);
  strokeJoin(ROUND);
  strokeCap(ROUND);
  beginShape();
  curveVertex(pts[0].x, pts[0].y);
  for (let i = 0; i < pts.length; i++) {
    curveVertex(pts[i].x, pts[i].y);
  }
  curveVertex(pts[pts.length - 1].x, pts[pts.length - 1].y);
  endShape();
}

function drawRibbonGlow(pts, col, radius) {
  for (let i = 0; i < pts.length; i += 12) {
    ctxGlow(pts[i].x, pts[i].y, radius, col);
  }
}

function drawUnionGlow() {
  const cx = 800, cy = 350;
  ctxGlow(cx, cy, 480, color(255, 150, 140, 12));
  ctxGlow(cx, cy, 300, color(255, 210, 180, 20));
  ctxGlow(cx, cy, 150, color(255, 255, 255, 28));

  noFill();
  strokeWeight(2.5);
  stroke(255, 190, 160, 18);
  ellipse(cx, cy, 310, 440);
  stroke(255, 220, 200, 14);
  ellipse(cx, cy, 410, 560);
  stroke(255, 150, 180, 12);
  ellipse(cx, cy, 530, 700);
}

function drawSparks(count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    const angle = random(TWO_PI);
    const radius = pow(random(), 2.2) * 680;
    const x = 800 + cos(angle) * radius;
    const y = 350 + sin(angle) * radius * 0.85;
    if (x < 0 || x > W || y < 0 || y > H) continue;

    const size = random(1.5, 6);
    const choice = random();
    let col;
    if (choice < 0.45) col = color(255, 190, 160, random(10, 32));
    else if (choice < 0.75) col = color(150, 220, 255, random(10, 32));
    else col = color(220, 180, 255, random(10, 32));

    fill(col);
    ellipse(x, y, size, size);

    if (random() < 0.14) {
      ctxGlow(x, y, random(15, 50), color(red(col), green(col), blue(col), random(3, 10)));
    }
  }
}

function ctxGlow(x, y, r, col) {
  const ctx = drawingContext;
  const rr = Math.round(red(col));
  const gg = Math.round(green(col));
  const bb = Math.round(blue(col));
  const aa = alpha(col) / 100;

  const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
  grad.addColorStop(0, `rgba(${rr},${gg},${bb},${aa})`);
  grad.addColorStop(1, `rgba(${rr},${gg},${bb},0)`);
  ctx.fillStyle = grad;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255);
  noLoop();
  strokeCap(ROUND);
