function drawGradient() {
  noStroke();
  let top = color(10, 8, 26);
  let mid = color(38, 20, 60);
  let bot = color(10, 8, 26);
  for (let y = 0; y < height; y += 4) {
    let t = y / height;
    let col;
    if (t < 0.5) col = lerpColor(top, mid, t * 2);
    else col = lerpColor(mid, bot, (t - 0.5) * 2);
    fill(red(col), green(col), blue(col), 255);
    rect(0, y, width, 4);
  }
}

function drawPatches() {
  blendMode(BLEND);
  for (let i = 0; i < 90; i++) {
    let x = random(width);
    let y = random(height);
