}

function drawBrushstrokes() {
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 180; i++) {
    let x1 = random(width);
    let y1 = random(height);
    let angle = random(TWO_PI);
    let len = random(60, 240);
    let x2 = x1 + cos(angle) * len;
    let y2 = y1 + sin(angle) * len;
    let col = random([
      color(210, 190, 230, 18),
      color(255, 200, 180, 14),
      color(180, 160, 220, 16),
      color(255, 220, 200, 10)
    ]);
    stroke(red(col), green(col), blue(col), alpha(col));
    strokeWeight(random(18, 55));
    line(x1, y1, x2, y2);
  }
}

function drawStreams() {
  blendMode(ADD);
  drawOneStream(0);
  drawOneStream(1);
}

function drawOneStream(side) {
  const count = 85;
  const steps = 160;
  const c1 = side === 0 ? color(200, 45, 80) : color(90, 30, 150);
  const c2 = side === 0 ? color(255, 215, 165) : color(170, 220, 255);
  noFill();
  for (let j = 0; j < count; j++) {
    let phase = side * PI + j * 0.08;
    let baseOffset = side === 0 ? -380 : 380;
    let thickness = random(0.5, 1.8);
    let pAlpha = random(22, 60);
    let px = 0;
    let py = 0;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = lerp(height * 0.94, height * 0.34, t);
      let envelope = (1 - t) * (0.75 + 0.25 * sin(PI * t));
      let twist = sin(t * PI * 6 + phase + noise(t * 2.0 + side * 12 + j) * 2.0) * 170;
      let noiseX = (noise(t * 1.6 + j * 0.08 + side * 20) - 0.5) * 200;
      let x = width / 2 + (baseOffset + twist + noiseX) * envelope;

      let alphaMul = sin(t * PI);
      let col = lerpColor(c1, c2, t);
      let alpha = pAlpha * alphaMul * 0.8;

      if (i > 0) {
        stroke(red(col), green(col), blue(col), alpha);
        strokeWeight(thickness * (0.4 + 0.8 * alphaMul));
        line(px, py, x, y);
      }
      px = x;
      py = y;
    }
  }
}

function drawPlume() {
  blendMode(ADD);
  const count = 60;
  const steps = 120;
  const startY = height * 0.34;
  const endY = height * 0.12;
  noFill();
  for (let j = 0; j < count; j++) {
    let phase = j * 0.12;
    let thickness = random(0.6, 1.4);
    let alpha = random(20, 50);
    let px = width / 2 + random(-8, 8);
    let py = startY + random(-5, 5);
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = lerp(startY, endY, t);
      let spread = sin(t * PI * 1.5 + phase) * 35 * t;
      let n = (noise(t * 2.0 + j * 0.1) - 0.5) * 50 * t;
      let x = width / 2 + spread + n;
      let alphaMul = sin(t * PI);
      let col = lerpColor(color(255, 190, 160), color(255, 240, 220), t);
      stroke(red(col), green(col), blue(col), alpha * alphaMul * 0.7);
      strokeWeight(thickness * (0.4 + 0.6 * alphaMul));
      if (i > 0) line(px, py, x, y);
      px = x;
      py = y;
    }
  }
}

function drawCentralGlow() {
  blendMode(ADD);
  let cx = width / 2;
  let cy = height * 0.34;
