function drawRibbon(points, colStart, colEnd, wMin, wMax, offsetAmp, zOff, passes, alpha, glowMult) {
  noFill();
  let steps = 400;
  for (let pass = 0; pass < passes; pass++) {
    let prev = null;
    let z = zOff + pass * 8.3;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let p = catmullRom(points, t);
      let n1 = noise(p.x * 0.003, p.y * 0.003, z);
      let n2 = noise(p.x * 0.0015, p.y * 0.0015, z + 40);
      let offX = (n1 - 0.5) * offsetAmp;
      let offY = (n2 - 0.5) * offsetAmp;
      let x = p.x + offX;
      let y = p.y + offY;
      if (prev) {
        let col = lerpColor(colStart, colEnd, t);
        let taper = sin(PI * t);
        let w = (wMin + (wMax - wMin) * taper) * glowMult;
        stroke(red(col), green(col), blue(col), alpha * taper);
        strokeWeight(w);
        line(prev.x, prev.y, x, y);
      }
      prev = createVector(x, y);
    }
  }
}

function catmullRom(points, t) {
  let n = points.length - 1;
  let tt = t * n;
  let i = Math.floor(tt);
  let f = tt - i;
  if (i >= n) {
    i = n - 1;
    f = 1;
  }
  i = Math.max(0, i);
  let p0 = points[Math.max(0, i - 1)];
  let p1 = points[i];
  let p2 = points[i + 1];
  let p3 = points[Math.min(n, i + 2)];
  let x = 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * f + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * f * f + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * f * f * f);
  let y = 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * f + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * f * f + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * f * f * f);
  return createVector(x, y);
}

