function glowOrb(cx, cy, maxR, innerColor, outerColor, comp) {
  const ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = comp || 'source-over';
  const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, maxR);
  g.addColorStop(0, `rgba(${red(innerColor)},${green(innerColor)},${blue(innerColor)},${alpha(innerColor) / 255})`);
  g.addColorStop(0.55, `rgba(${red(innerColor)},${green(innerColor)},${blue(innerColor)},${alpha(innerColor) * 0.45 / 255})`);
  g.addColorStop(1, `rgba(${red(outerColor)},${green(outerColor)},${blue(outerColor)},0)`);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, maxR, 0, TWO_PI);
  ctx.fill();
  ctx.restore();
}

