function pathA(t) {
  let angle = t * PI * 9.5 + 0.7 * sin(t * PI * 4);
  let env = pow(sin(t * PI), 0.8);
  let x = width / 2 + 400 * env * sin(angle);
  let y = 170 + t * 1660 + 28 * sin(t * PI * 6);
  x += (noise(t * 4 + 10, 100) - 0.5) * 18;
  y += (noise(t * 4 + 200, 300) - 0.5) * 18;
  return { x, y };
}

function pathB(t) {
  let angle = t * PI * 8.8 + 0.5 * cos(t * PI * 3);
  let env = pow(sin(t * PI), 0.8);
  let x = width / 2 + 360 * env * cos(angle);
  let y = 170 + t * 1660 - 24 * sin(t * PI * 5);
  x += (noise(t * 4 + 400, 500) - 0.5) * 18;
  y += (noise(t * 4 + 600, 700) - 0.5) * 18;
  return { x, y };
}

function pathA2(t) {
  let angle = t * PI * 12 + 1.2 * sin(t * PI * 5);
  let env = pow(sin(t * PI), 0.85);
  let x = width / 2 + 440 * env * sin(angle);
  let y = 180 + t * 1640;
  return { x, y };
}

function pathB2(t) {
  let angle = t * PI * 11 + 0.9 * cos(t * PI * 4);
  let env = pow(sin(t * PI), 0.85);
  let x = width / 2 + 400 * env * cos(angle);
  let y = 180 + t * 1640;
  return { x, y };
}

function drawRibbon(pathFn, baseColor, radius, alpha, steps, nsx, nsy) {
  noStroke();

  blendMode(BLEND);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = pathFn(t);
    let env = pow(sin(t * PI), 0.8);
    let n1 = noise(i * 0.035 + nsx, 300 + nsy);
    let r = radius * (0.4 + 0.6 * env) * (0.75 + 0.55 * n1);
    let a = alpha * (0.55 + 0.45 * noise(i * 0.03 + nsx, 420 + nsy));
    fill(red(baseColor), green(baseColor), blue(baseColor), a);
    ellipse(p.x, p.y, r * 2, r * 2);
  }

  blendMode(ADD);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = pathFn(t);
    let env = pow(sin(t * PI), 0.8);
    let n2 = noise(i * 0.05 + 120 + nsx, 800 + nsy);
    let r = radius * 0.48 * (0.4 + 0.6 * env) * (0.6 + 0.5 * n2);
    let a = alpha * 0.30 * (0.5 + 0.6 * n2);
    let rcol = min(255, red(baseColor) + 70);
    let gcol = min(255, green(baseColor) + 70);
    let bcol = min(255, blue(baseColor) + 70);
    fill(rcol, gcol, bcol, a);
    ellipse(p.x, p.y, r * 2, r * 2);
  }
  blendMode(BLEND);
}

function drawSparkles(count) {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < count; i++) {
    let angle = random(TWO_PI);
    let rr = random(50, 720);
    let x = width / 2 + cos(angle) * rr;
    let y = height / 2 + sin(angle) * rr * 1.35;
