function bezPt(a, b, c, d, t) {
  let u = 1 - t;
  return u * u * u * a + 3 * u * u * t * b + 3 * u * t * t * c + t * t * t * d;
}

function bezTan(a, b, c, d, t) {
  let u = 1 - t;
  return 3 * u * u * (b - a) + 6 * u * t * (c - b) + 3 * t * t * (d - c);
}

function ribbon(x1, y1, cx1, cy1, cx2, cy2, x2, y2, h, s, b, a, w, wob, seedOff) {
  let steps = 160;
  let px = bezPt(x1, cx1, cx2, x2, 0);
  let py = bezPt(y1, cy1, cy2, y2, 0);
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let x = bezPt(x1, cx1, cx2, x2, t);
    let y = bezPt(y1, cy1, cy2, y2, t);
    let tx = bezTan(x1, cx1, cx2, x2, t);
    let ty = bezTan(y1, cy1, cy2, y2, t);
    let ang = atan2(ty, tx) + HALF_PI;
    let n = noise(x * 0.004 + seedOff * 0.1, y * 0.004 + seedOff * 0.1, seedOff) - 0.5;
    x += cos(ang) * n * wob;
    y += sin(ang) * n * wob;
    let taper = sin(t * PI);
    let ww = w * (0.15 + 0.85 * taper) * (0.6 + 0.4 * noise(t * 2 + seedOff));
    stroke(h, s, b, a);
    strokeWeight(ww);
    strokeCap(ROUND);
    line(px, py, x, y);
    px = x;
    py = y;
  }
}

