    let y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t);
    let nn = 1;
    if (wobble > 0) {
      nn = 1 + (noise(t * 1.5 + seedOff, size * 0.1) - 0.5) * wobble * 0.18;
    }
    vertex(cx + x * size * nn, cy - y * size * nn);
  }
  endShape(CLOSE);
}

