  pop();

  softForm(width * 0.37, height * 0.47, 335, 64, 88, -0.16, 1280, 620, 12.3);
  softForm(width * 0.63, height * 0.49, 33, 72, 94, 0.18, 1360, 680, 78.9);

  for (let i = 0; i < 34; i++) {
    let baseY = height * 0.10 + i * 54;
    let hue = i % 2 === 0 ? 337 : 36;
    stroke(hue, 68, 96, 7);
    strokeWeight(1.4 + noise(i * 0.42) * 6.2);
    noFill();
    beginShape();
    for (let x = -90; x <= width + 90; x += 36) {
      let y = baseY + (noise(x * 0.0011 + i * 0.19, i * 0.61) - 0.5) * 470 + sin(x * 0.0038 + i) * 36;
      curveVertex(x, y);
    }
    endShape();
  }
  noStroke();

  for (let i = 0; i < 64; i++) {
    let t = i / 64;
    let x = width * 0.5 + (noise(i * 0.14 + 140) - 0.5) * 130;
    let y = height * 0.45 + (noise(i * 0.12 + 210) - 0.5) * 180;
    let d = 380 - t * 300;
    fill(24 + t * 12, 58, 100, 2.7);
    ellipse(x, y, d, d * 1.16);
  }

  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0023, y * 0.0023);
    let near = dist(x, y, width * 0.5, height * 0.45) < 820;
    if (n > 0.57 && near) {
      fill(36 + n * 16, 55, 100, random(4, 16));
      ellipse(x, y, random(0.8, 3.8), random(0.8, 3.8));
    }
  }

  let ctx = drawingContext;
  let g = ctx.createRadialGradient(width * 0.5, height * 0.46, height * 0.16, width * 0.5, height * 0.5, height * 0.86);
  g.addColorStop(0, 'hsla(26, 85%, 62%, 0)');
  g.addColorStop(0.62, 'hsla(343, 78%, 8%, 0.10)');
  g.addColorStop(1, 'hsla(342, 85%, 4%, 0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function softForm(x, y, hue, saturation, brightness, angle, len, wid, seedShift) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  for (let i = 0; i <= 96; i++) {
    let t = i / 96;
    let px = (noise(i * 0.076 + seedShift) - 0.5) * wid * 0.62;
    let py = map(t, 0, 1, -len * 0.52, len * 0.52);
    let envelope = sin(PI * t);
    let w = wid * (0.18 + 0.82 * envelope);
    let h = w * 1.42;
    let hueShift = (noise(i * 0.121 + seedShift * 0.5 + 22) - 0.5) * 26;
    fill((hue + hueShift + 360) % 360, saturation, brightness, 2.5);
    ellipse(px, py, w, h);
  }
  pop();
}

let PAL, cA, cB, HC;
const W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  cA = { x: 545, y: 882 };
  cB = { x: 1082, y: 1126 };
  HC = { x: 806, y: 1004 };

  PAL = [
    [0.00, color(22, 7, 18)],
    [0.16, color(56, 10, 37)],
    [0.34, color(122, 15, 53)],
    [0.52, color(204, 43, 85)],
    [0.68, color(255, 108, 92)],
    [0.84, color(255, 182, 96)],
    [1.00, color(255, 241, 216)]
  ];

  const ctx = drawingContext;

  baseGround(ctx);
  grain(ctx, 2600, 1.6);
  glows(ctx);
  flowFieldPaint(ctx);
  halos(ctx);
  petals(ctx);
  whispers(ctx);
  heart(ctx);
  embers(ctx);
  grain(ctx, 1400, 0.9);
  vignette(ctx);
}

function pal(t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < PAL.length - 1; i++) {
    if (t <= PAL[i + 1][0]) {
      const k = (t - PAL[i][0]) / (PAL[i + 1][0] - PAL[i][0]);
      return lerpColor(PAL[i][1], PAL[i + 1][1], k);
    }
  }
  return PAL[PAL.length - 1][1].copy();
}

function baseGround(ctx) {
  const g = ctx.createLinearGradient(0, 0, W * 0.4, H);
  g.addColorStop(0, 'rgba(15,4,13,1)');
  g.addColorStop(0.42, 'rgba(45,9,30,1)');
  g.addColorStop(0.78, 'rgba(33,6,25,1)');
  g.addColorStop(1, 'rgba(19,4,16,1)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function grain(ctx, n, sc) {
  for (let i = 0; i < n; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) ctx.fillStyle = 'rgba(255,232,208,' + ((0.01 + random() * 0.025) * sc) + ')';
    else ctx.fillStyle = 'rgba(8,2,9,' + ((0.02 + random() * 0.05) * sc) + ')';
    const r = 0.6 + random() * 1.7;
    ctx.fillRect(x, y, r, r);
  }
}

function softGlow(ctx, x, y, r, c) {
  ctx.save();
  ctx.filter = 'blur(' + int(r * 0.3) + 'px)';
  ctx.fillStyle = c.toString();
  ctx.beginPath();
  ctx.ellipse(x, y, r * 0.62, r * 0.56, 0, 0, TWO_PI);
  ctx.fill();
  ctx.restore();
}

function glows(ctx) {
  softGlow(ctx, cA.x, cA.y, 460, color(255, 96, 122, 58));
  softGlow(ctx, cB.x, cB.y, 490, color(255, 122, 88, 58));
  softGlow(ctx, HC.x, HC.y, 400, color(255, 190, 108, 62));
  softGlow(ctx, 140, 1830, 430, color(22, 58, 66, 44));
  softGlow(ctx, 1500, 150, 400, color(26, 48, 62, 40));
  softGlow(ctx, cA.x, cA.y, 150, color(38, 6, 26, 96));
  softGlow(ctx, cB.x, cB.y, 160, color(38, 6, 26, 96));
}

function fieldAngle(x, y) {
  const base = noise(x * 0.0012, y * 0.0012) * TWO_PI * 2.2;
  let vx = cos(base) * 0.32, vy = sin(base) * 0.32;
  const cs = [cA, cB];
  const dirs = [1, -1];
  for (let i = 0; i < 2; i++) {
    const dx = x - cs[i].x, dy = y - cs[i].y;
    const d = sqrt(dx * dx + dy * dy) + 0.001;
    const w = Math.exp(-d / 540) * 1.05;
    vx += (-dy / d) * dirs[i] * w;
    vy += (dx / d) * dirs[i] * w;
  }
  const hx = HC.x - x, hy = HC.y - y;
  const hd = sqrt(hx * hx + hy * hy) + 0.001;
  const hw = Math.exp(-hd / 340) * 0.85;
  vx += (hx / hd) * hw;
  vy += (hy / hd) * hw;
  return atan2(vy, vx);
}

function tone(x, y) {
  const dA = dist(x, y, cA.x, cA.y);
  const dB = dist(x, y, cB.x, cB.y);
  const dH = dist(x, y, HC.x, HC.y);
  const g = Math.max(Math.exp(-dA / 450), Math.exp(-dB / 480), Math.exp(-dH / 400));
  const n = noise(x * 0.0022 + 40, y * 0.0022 + 40);
  return constrain(0.14 + g * 0.74 + (n - 0.5) * 0.34, 0.02, 1);
}

function flowFieldPaint(ctx) {
  ctx.save();
  ctx.lineCap = 'round';
  const N = 1900;
  for (let i = 0; i < N; i++) {
    let x, y;
    if (random() < 0.62) {
      const c = random() < 0.5 ? cA : cB;
      const a = random(TWO_PI);
      const rr = 100 + pow(random(), 0.65) * 560;
      x = c.x + cos(a) * rr;
      y = c.y + sin(a) * rr;
    } else {
      x = random(W);
      y = random(H);
    }
    const steps = 18 + int(random() * 22);
    const w0 = 0.8 + random() * 4.4;
    for (let s = 0; s < steps; s++) {
      const a = fieldAngle(x, y);
      const nx = x + cos(a) * 7.5;
      const ny = y + sin(a) * 7.5;
      if (nx < -30 || nx > W + 30 || ny < -30 || ny > H + 30) break;
      const c = pal(tone(nx, ny));
      c.setAlpha(16 + 42 * noise(nx * 0.008 + 90, ny * 0.008));
      ctx.strokeStyle = c.toString();
      ctx.lineWidth = w0 * (1 - (s / steps) * 0.6);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(nx, ny);
      ctx.stroke();
      x = nx;
      y = ny;
    }
  }
  ctx.restore();
}

function halos(ctx) {
  ctx.save();
  ctx.lineCap = 'round';
  const list = [[cA, 300], [cB, 330]];
  for (const pair of list) {
    const c = pair[0], r0 = pair[1];
    for (let p = 0; p < 3; p++) {
      const a0 = random(TWO_PI);
      const span = PI * (0.6 + random() * 1.2);
      const col = pal(0.86);
      col.setAlpha(26 + random() * 22);
      ctx.strokeStyle = col.toString();
      ctx.lineWidth = 1.1 + random() * 1.3;
      ctx.beginPath();
      ctx.arc(c.x, c.y, r0 + p * 12 + random() * 6, a0, a0 + span);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function petals(ctx) {
  ctx.save();
  ctx.lineCap = 'round';
  for (let i = 0; i < 70; i++) {
    const x = random(W), y = random(H);
    const r = 5 + random() * 15;
    const a0 = random(TWO_PI);
    const col = pal(0.45 + random() * 0.35);
    col.setAlpha(20 + random() * 30);
    ctx.strokeStyle = col.toString();
    ctx.lineWidth = 1.4 + random() * 2.4;
    ctx.beginPath();
    ctx.arc(x, y, r, a0, a0 + 1.3 + random() * 1.5);
    ctx.stroke();
  }
  ctx.restore();
}

function whispers(ctx) {
  ctx.save();
  ctx.lineCap = 'round';
  const dx = cB.x - cA.x, dy = cB.y - cA.y;
  const L = sqrt(dx * dx + dy * dy);
  const px = -dy / L, py = dx / L;
  for (let k = 0; k < 16; k++) {
    const amp = (60 + random() * 150) * (random() < 0.5 ? -1 : 1);
    const fr = 1 + int(random() * 2);
    const ph = random(TWO_PI);
    const col = pal(0.84 + random() * 0.16);
    col.setAlpha(13 + random() * 15);
    ctx.strokeStyle = col.toString();
    ctx.lineWidth = 0.8 + random() * 1.3;
    ctx.beginPath();
    for (let s = 0; s <= 1.0001; s += 0.02) {
      const taper = sin(PI * s);
      let o = sin(s * PI * fr + ph) * amp * taper;
      o += (noise(k * 0.93, s * 3.1) - 0.5) * 70 * taper;
      const x = lerp(cA.x, cB.x, s) + px * o;
      const y = lerp(cA.y, cB.y, s) + py * o;
      if (s === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  ctx.restore();
}

function heartPath(ctx, p, jr0) {
  const s = 24;
  const span = TWO_PI * (0.55 + random() * 0.45);
  const start = random(TWO_PI);
  ctx.beginPath();
  let first = true;
  for (let t = 0; t <= span + 0.0001; t += 0.034) {
    const u = start + t;
    const su = sin(u);
    const hx = 16 * su * su * su * s;
    const hy = -(13 * cos(u) - 5 * cos(2 * u) - 2 * cos(3 * u) - cos(4 * u)) * s;
    const len = sqrt(hx * hx + hy * hy) || 1;
    const jr = (noise(p * 0.37, u * 0.85) - 0.5) * 2 * jr0;
    const px = hx + (hx / len) * jr;
    const py = hy + (hy / len) * jr;
    if (first) { ctx.moveTo(px, py); first = false; }
    else ctx.lineTo(px, py);
  }
  ctx.stroke();
}

function heart(ctx) {
  softGlow(ctx, HC.x, HC.y - 30, 330, color(255, 178, 96, 88));
  ctx.save();
  ctx.translate(HC.x, HC.y);
  ctx.rotate(-0.06);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.globalCompositeOperation = 'lighter';
  for (let p = 0; p < 6; p++) {
    ctx.strokeStyle = 'rgba(255,200,128,' + (0.05 + random() * 0.045) + ')';
    ctx.lineWidth = 9 + random() * 9;
    heartPath(ctx, p + 400, 26);
  }
  ctx.globalCompositeOperation = 'source-over';
  for (let p = 0; p < 120; p++) {
    const warm = random() < 0.78;
    const col = warm ? pal(0.7 + random() * 0.3) : pal(0.34 + random() * 0.18);
    col.setAlpha(18 + random() * 26);
    ctx.strokeStyle = col.toString();
    ctx.lineWidth = 0.9 + random() * 1.9;
    heartPath(ctx, p, 4 + 24 * noise(p * 0.11));
  }
  ctx.restore();
}

function embers(ctx) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 230; i++) {
    const r0 = random();
    let x, y;
    if (r0 < 0.5) {
      x = HC.x + randomGaussian() * 230;
      y = HC.y + randomGaussian() * 280 - random(40, 380);
    } else if (r0 < 0.82) {
      const c = random() < 0.5 ? cA : cB;
      x = c.x + randomGaussian() * 250;
      y = c.y + randomGaussian() * 280;
    } else {
      x = random(W);
      y = random(H * 0.12, H * 0.92);
    }
    const r = 1.2 + random() * 4.2;
    const col = pal(0.72 + random() * 0.28);
    for (let h = 3; h >= 1; h--) {
      col.setAlpha(h === 1 ? 95 : 30 / h);
      ctx.fillStyle = col.toString();
      ctx.beginPath();
      ctx.arc(x, y, r * h * 0.9, 0, TWO_PI);
      ctx.fill();
    }
  }
  ctx.restore();
}

function vignette(ctx) {
  let g = ctx.createRadialGradient(800, 980, 640, 800, 1000, 1520);
  g.addColorStop(0, 'rgba(9,2,9,0)');
  g.addColorStop(1, 'rgba(8,2,9,0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  const g2 = ctx.createLinearGradient(0, 0, 0, H);
  g2.addColorStop(0, 'rgba(12,3,12,0.42)');
  g2.addColorStop(0.16, 'rgba(12,3,12,0)');
  g2.addColorStop(0.86, 'rgba(12,3,12,0)');
  g2.addColorStop(1, 'rgba(13,3,11,0.5)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, W, H);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 1);
  pixelDensity(1);
  noLoop();

  background(349, 70, 7);

  noStroke();
  for (let i = 0; i < 2300; i++) {
    let x = random(width);
    let y = random(height);
    let n1 = noise(x * 0.0011, y * 0.0011);
    let n2 = noise(x * 0.0022 + 31.7, y * 0.0022 + 11.3);
    let h = lerp(340, 28, n1);
    if (h > 360) h -= 360;
    let s = lerp(58, 88, n2);
    let b = lerp(5, 22, n1 * 0.7 + n2 * 0.3);
    fill(h, s, b, 0.03);
    let rx = random(40, 220) * (0.5 + n1);
    ellipse(x, y, rx, rx * random(0.65, 1.55));
  }

  for (let y = 0; y <= height; y += 5) {
    let t = y / height;
    let n = noise(t * 2.7 + 17.7);
    let h = lerp(344, 20, n);
    let b = 6 + 16 * sin(t * PI) + 8 * n;
    fill(h, 74, constrain(b, 4, 32), 0.035);
    noStroke();
    rect(0, y, width, 5);
  }

  push();
  translate(width * 0.5, height * 0.46);
  noStroke();
  for (let i = 0; i < 620; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 1.6) * min(width, height) * 0.36;
    let x = cos(a) * r * 1.12;
    let y = sin(a) * r * 1.42;
    let n = noise(x * 0.004 + 41, y * 0.004 + 77);
    let h = lerp(348, 40, n);
    h = (h + 360) % 360;
    fill(h, 78, 68 + 25 * n, 0.022);
    let d = random(24, 170) * (1.0 - r / (min(width, height) * 0.42));
    ellipse(x, y, d, d * random(0.8, 1.3));
  }
  pop();

  let N = 280;
  let ax = [], ay = [], bx = [], by = [];
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let y = height * (0.12 + 0.74 * t);
    let envelope = 0.30 + 0.70 * sin(t * PI);
    let xA = width * 0.5 + sin(t * TWO_PI * 1.18 + 0.45) * width * 0.215 * envelope;
    let xB = width * 0.5 + sin(t * TWO_PI * 1.18 + 0.45 + PI) * width * 0.215 * envelope;
    xA += (noise(t * 2.8, 4.2) - 0.5) * 68;
    xB += (noise(t * 2.8, 18.4) - 0.5) * 68;
    y += (noise(t * 3.6, 55.1) - 0.5) * 42;
    ax.push(xA);
    ay.push(y);
    bx.push(xB);
    by.push(y + (noise(t * 5.1, 9.3) - 0.5) * 22);
  }

  drawRibbon(ax, ay, N, 0);
  drawRibbon(bx, by, N, 1);

  noFill();
  for (let i = 6; i <= N - 6; i += 7) {
    let n = noise(i * 0.043, 91.3);
    let h = (26 + 26 * n) % 360;
    stroke(h, 72, 84, 0.05 + 0.05 * n);
    strokeWeight(0.7 + 2.4 * n);
    let midX = (ax[i] + bx[i]) * 0.5 + (noise(i * 0.11, 12.5) - 0.5) * 260;
    let midY = (ay[i] + by[i]) * 0.5 + (noise(i * 0.13, 71.9) - 0.5) * 180;
    bezier(ax[i], ay[i], midX - 80, midY - 40, midX + 80, midY + 40, bx[i], by[i]);
  }

  noStroke();
  for (let i = 0; i <= N; i += 2) {
    let t = i / N;
    let glow = sin(t * PI);
    let size = 12 + 42 * glow;
    fill(352, 88, 84, 0.05 + 0.07 * glow);
    ellipse(ax[i], ay[i], size, size * 1.25);
    fill(30, 82, 88, 0.05 + 0.07 * glow);
    ellipse(bx[i], by[i], size, size * 1.25);
  }

  let m = floor(N * 0.52);
  let cx = (ax[m] + bx[m]) * 0.5;
  let cy = (ay[m] + by[m]) * 0.5;
  blendMode(ADD);
  for (let i = 0; i < 540; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 2.1) * 320;
    let x = cx + cos(a) * r * 1.15;
    let y = cy + sin(a) * r * 1.55;
    let n = noise(x * 0.006, y * 0.006, 4.4);
    let h = (335 + 65 * n) % 360;
    fill(h, 75, 88, 0.018 + 0.032 * n);
    let d = 3 + 52 * (1 - r / 320) * random(0.4, 1.2);
    ellipse(x, y, d, d);
  }
  blendMode(BLEND);

  blendMode(ADD);
  for (let i = 0; i < 1800; i++) {
    let x = width * 0.5 + randomGaussian() * width * 0.17;
    let y = height * 0.47 + randomGaussian() * height * 0.16;
    if (x < 0 || x > width || y < 0 || y > height) continue;
    let n = noise(x * 0.006, y * 0.006, 18.8);
    let h = (38 + 26 * n) % 360;
    fill(h, 56, 96, 0.02 + 0.06 * n);
    let d = random(0.8, 3.2);
    ellipse(x, y, d, d);
  }
  blendMode(BLEND);

  noStroke();
  for (let i = 0; i < 2600; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.004, y * 0.004, 6.2);
    if (n > 0.56) {
      fill((345 + 40 * n) % 360, 42, 90, 0.016);
      let d = random(0.6, 2.0);
      ellipse(x, y, d, d);
    }
  }

  let ctx = drawingContext;
  ctx.save();
  let g1 = ctx.createRadialGradient(width * 0.5, height * 0.46, height * 0.12, width * 0.5, height * 0.50, height * 0.84);
  g1.addColorStop(0, 'rgba(0,0,0,0)');
  g1.addColorStop(0.62, 'rgba(8,2,7,0.10)');
  g1.addColorStop(1, 'rgba(5,1,6,0.62)');
  ctx.fillStyle = g1;
  ctx.fillRect(0, 0, width, height);

  let g2 = ctx.createLinearGradient(0, 0, 0, height);
  g2.addColorStop(0, 'rgba(16,3,10,0.30)');
  g2.addColorStop(0.22, 'rgba(0,0,0,0)');
  g2.addColorStop(0.78, 'rgba(0,0,0,0)');
  g2.addColorStop(1, 'rgba(14,2,9,0.38)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function drawRibbon(px, py, N, which) {
  noStroke();
  for (let pass = 0; pass < 3; pass++) {
    let step = (pass === 0 ? 3 : 2);
    for (let i = 0; i <= N; i += step) {
      let t = i / N;
      let envelope = sin(t * PI);
      let n = noise(i * 0.016 + which * 7.3, pass * 3.1);
      let baseSize;
      let alpha;
      if (pass === 0) {
        baseSize = 170;
        alpha = 0.018;
      } else if (pass === 1) {
        baseSize = 82;
        alpha = 0.030;
      } else {
        baseSize = 34;
        alpha = 0.052;
      }
      let d = baseSize * (0.35 + 0.85 * envelope) * (0.72 + 0.55 * n);
      let h, s, b;
      if (which === 0) {
        h = (345 + 18 * n) % 360;
        s = 86;
        b = 48 + 36 * envelope;
      } else {
        h = (14 + 26 * n) % 360;
        s = 78;
        b = 52 + 38 * envelope;
      }
      fill(h, s, b, alpha);
      ellipse(px[i], py[i], d, d * (1.15 + 0.3 * noise(i * 0.05, which)));
    }
  }
}

var W = 1600, H = 2000;

var warmFig = { hx:545, hy:560, hr:140, bx:700, by:1880, cx:720, cy:1180, wTop:115, wBot:300 };
var coolFig = { hx:1055, hy:500, hr:130, bx:900, by:1880, cx:880, cy:1140, wTop:105, wBot:290 };

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  paintBackground();
  paintHalo();
  paintFigure(warmFig, 1);
  paintFigure(coolFig, -1);
  paintOverlap();
  paintThread();
  paintEmbers();
  paintVignette();
  paintGrain();
}

/* ---------- geometry ---------- */

function qpoint(f, t) {
  var u = 1 - t;
  return {
    x: u*u*f.hx + 2*u*t*f.cx + t*t*f.bx,
    y: u*u*f.hy + 2*u*t*f.cy + t*t*f.by
  };
}

function qradius(f, t) {
  var r = f.wTop + (f.wBot - f.wTop) * pow(t, 1.25);
  r *= 1 - 0.35 * exp(-sq((t - 0.045) / 0.05));
  r *= 1 + 0.10 * (noise(t * 4.0 + f.hx * 0.01, f.hy * 0.01) - 0.5);
  return r;
}

function insideFig(f, x, y) {
  if (dist(x, y, f.hx, f.hy) < f.hr) return true;
  if (y < f.hy - f.hr || y > f.by) return false;
  var best = -1, bd = 1e9;
  for (var i = 0; i <= 26; i++) {
    var t = i / 26, p = qpoint(f, t);
    var d = abs(p.y - y);
    if (d < bd) { bd = d; best = t; }
  }
  if (bd > 70) return false;
  var p2 = qpoint(f, best);
  return dist(x, y, p2.x, p2.y) < qradius(f, best);
}

function spineAngle(f, x, y) {
  var best = 0.05, bd = 1e9;
  for (var i = 0; i <= 16; i++) {
    var t = i / 16, p = qpoint(f, t);
    var d = dist(x, y, p.x, p.y);
    if (d < bd) { bd = d; best = t; }
  }
  var p1 = qpoint(f, max(0, best - 0.04)), p2 = qpoint(f, min(1, best + 0.04));
  var a = atan2(p2.y - p1.y, p2.x - p1.x) + HALF_PI;
  if (a > HALF_PI) a -= PI;
  if (a < -HALF_PI) a += PI;
  return a;
}

/* ---------- brush ---------- */

function brush(x, y, ang, len, wdt, h, s, b, al) {
  h = (h % 360 + 360) % 360;
  noFill();
  stroke(h, constrain(s, 0, 100), constrain(b, 0, 100), constrain(al, 0, 100));
  strokeWeight(wdt);
  beginShape();
  var n = 6;
  for (var i = 0; i <= n; i++) {
    var t = i / n;
    var wob = (noise(x * 0.004 + t * 2.3, y * 0.004 - t * 1.1) - 0.5) * len * 0.4;
    vertex(x + cos(ang) * len * t + cos(ang + HALF_PI) * wob,
           y + sin(ang) * len * t + sin(ang + HALF_PI) * wob);
  }
  endShape();
}

/* ---------- background ---------- */

function paintBackground() {
  var ctx = drawingContext;
  var g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, 'hsl(295,42%,9%)');
  g.addColorStop(0.45, 'hsl(288,40%,11%)');
  g.addColorStop(1, 'hsl(270,45%,6%)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  var g2 = ctx.createRadialGradient(800, 620, 40, 800, 620, 860);
  g2.addColorStop(0, 'hsla(18,80%,42%,0.28)');
  g2.addColorStop(0.55, 'hsla(320,60%,28%,0.12)');
  g2.addColorStop(1, 'hsla(320,60%,20%,0)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, W, H);

  noFill();
  for (var i = 0; i < 420; i++) {
    var x = random(W), y = random(H);
    var a = HALF_PI + (noise(x * 0.0012, y * 0.0012) - 0.5) * 1.3;
    var l = random(90, 300);
    brush(x, y, a, l, random(18, 60),
          262 + random(-16, 30), random(26, 44), random(6, 15), random(3, 8));
  }
}

function paintHalo() {
  var ctx = drawingContext;
  var g = ctx.createRadialGradient(800, 530, 10, 800, 530, 460);
  g.addColorStop(0, 'hsla(33,95%,64%,0.50)');
  g.addColorStop(0.3, 'hsla(26,90%,55%,0.25)');
  g.addColorStop(0.62, 'hsla(322,70%,45%,0.10)');
  g.addColorStop(1, 'hsla(322,70%,40%,0)');
  ctx.fillStyle = g;
  ctx.fillRect(320, 90, 960, 880);

  noFill();
  for (var i = 0; i < 26; i++) {
    var r = random(130, 430);
    stroke(random(26, 44), 70, 82, random(1.5, 4));
    strokeWeight(random(1, 3.4));
    ellipse(800 + random(-26, 26), 530 + random(-24, 24), r * 2, r * 1.9);
  }

  noStroke();
  for (var j = 0; j < 150; j++) {
    var t = random(1);
    var x = 800 + random(-1, 1) * pow(random(1), 1.4) * (60 + t * 240);
    var y = lerp(470, 1300, t) + random(-30, 30);
    fill(random(30, 46), 85, 96, random(3, 8) * (1 - t * 0.55));
    circle(x, y, random(1.4, 4.2));
  }
}

/* ---------- figures ---------- */

function paintFigure(f, dir) {
  var warm = dir > 0;
  var pal = warm
    ? [[14,86,84],[7,80,62],[30,92,94],[352,72,46],[18,90,96]]
    : [[195,58,74],[210,66,52],[228,52,42],[172,44,80],[200,70,88]];
  var placed = 0, tries = 0, x, y;

  while (placed < 1250 && tries < 14000) {
    tries++;
    var inHead = random() < 0.28;
    if (inHead) {
      var a = random(TWO_PI), rr = f.hr * sqrt(random(1));
      x = f.hx + cos(a) * rr; y = f.hy + sin(a) * rr;
    } else {
      x = random(f.bx - f.wBot - 70, f.bx + f.wBot + 70);
      y = random(f.hy + f.hr * 0.3, f.by);
    }
    if (!insideFig(f, x, y)) continue;
    placed++;

    var ang;
    if (inHead) {
      ang = atan2(y - f.hy, x - f.hx) + HALF_PI + random(-0.4, 0.4);
    } else {
      ang = spineAngle(f, x, y) + (noise(x * 0.003, y * 0.003) - 0.5) * 1.3;
    }
    var len = random(16, inHead ? 44 : 72);
    var wdt = inHead ? random(2.5, 7) : random(3.5, 13);
    var c = random(pal);
    var hue = c[0] + random(-9, 9);
    var sat = c[1] + random(-8, 6);
    var bri = c[2] + (noise(x * 0.006, y * 0.006) - 0.5) * 22;
    var gap = abs(x - 800);
    bri += 14 * exp(-gap * gap / (2 * 280 * 280));
    var alp = random(9, 26);
    brush(x, y, ang, len, wdt, hue, sat, bri, alp);
  }

  noFill();
  for (var i = 0; i < 3; i++) {
    stroke(warm ? color(22, 80, 92, 22) : color(190, 60, 90, 20));
    strokeWeight(2.4);
    ellipse(f.hx + random(-6, 6), f.hy + random(-6, 6), f.hr * 2 + random(6, 26));
  }
}

function paintOverlap() {
  var x, y;
  for (x = 560; x <= 1060; x += 13) {
    for (y = 430; y <= 1870; y += 13) {
      if (!insideFig(warmFig, x, y) || !insideFig(coolFig, x, y)) continue;
      if (random() > 0.34) continue;
      var lens = exp(-sq((x - 800) / 230)) * exp(-sq((y - 1080) / 640));
      if (random() > 0.18 + 0.8 * lens) continue;
      var ang = spineAngle(warmFig, x, y) * 0.5 + spineAngle(coolFig, x, y) * 0.5
              + (noise(x * 0.004, y * 0.004) - 0.5) * 1.6;
      var f = (x - 560) / 500;
      var hue = lerp(348, 278, f) + random(-10, 10);
      var bri = 62 + 26 * lens + random(-8, 10);
      var alp = 10 + 16 * lens + random(0, 6);
      brush(x + random(-4, 4), y + random(-4, 4), ang, random(16, 58), random(3, 10),
            hue, random(55, 80), bri, alp);
    }
  }
}

/* ---------- golden thread ---------- */

function paintThread() {
  var A = { x:580, y:1160 }, B = { x:1035, y:1130 };
  var LC = { x:750, y:1080 }, R = 82;

  function base(t) {
    var x = lerp(A.x, B.x, t), y = lerp(A.y, B.y, t);
    y += (noise(t * 3.1, 7.7) - 0.5) * 120 * (0.3 + 0.7 * sin(t * PI));
    y += sin(t * PI) * 26;
    x += (noise(t * 2.3, 2.9) - 0.5) * 70;
    return { x: x, y: y };
  }

  var prePts = [], corePts = [], i, t, k, p;
  for (i = 0; i <= 46; i++) { t = 0.46 * i / 46; p = base(t); prePts.push(p); corePts.push(p); }
  var S = base(0.46), aS = atan2(LC.y - S.y, LC.x - S.x);
  for (k = 0; k <= 26; k++) {
    var a = aS + TWO_PI * k / 26;
    corePts.push({ x: LC.x + cos(a) * R, y: LC.y + sin(a) * R });
  }
  for (i = 0; i <= 58; i++) { t = 0.46 + 0.54 * i / 58; p = base(t); corePts.push(p); }
  for (i = prePts.length - 2; i >= 0; i--) prePts.push(prePts[i]);

  function pass(pts, w, h, s, b, al) {
    noFill(); stroke(h, s, b, al); strokeWeight(w);
    beginShape();
    curveVertex(pts[0].x, pts[0].y);
    for (var i = 0; i < pts.length; i++) curveVertex(pts[i].x, pts[i].y);
    curveVertex(pts[pts.length - 1].x, pts[pts.length - 1].y);
    endShape();
  }

  pass(prePts, 18, 38, 85, 90, 6);
  pass(corePts, 16, 38, 85, 90, 6);
  pass(corePts, 7, 40, 88, 94, 16);
  pass(corePts, 2.4, 45, 62, 100, 62);
}

/* ---------- embers, vignette, grain ---------- */

function paintEmbers() {
  noStroke();
  for (var i = 0; i < 170; i++) {
    var x = random(W), y = random(H);
    var near = dist(x, y, 800, 900) < 700;
    if (!near && random() < 0.45) continue;
    var gold = random() < 0.7;
    var h = gold ? random(28, 46) : random(330, 350);
    var r = random(2, gold ? 7 : 9);
    fill(h, 80, 96, 5); circle(x, y, r * 3.2);
    fill(h, 85, 98, random(25, 60)); circle(x, y, r);
    if (random() < 0.4) {
      stroke(h, 70, 95, 12); strokeWeight(1);
      line(x, y, x + random(-6, 6), y - random(14, 46));
      noStroke();
    }
  }
}

function paintVignette() {
  var ctx = drawingContext, g;
  g = ctx.createLinearGradient(0, 0, 0, 440);
  g.addColorStop(0, 'rgba(7,3,9,0.72)'); g.addColorStop(1, 'rgba(7,3,9,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, 440);
  g = ctx.createLinearGradient(0, H, 0, H - 480);
  g.addColorStop(0, 'rgba(6,2,8,0.8)'); g.addColorStop(1, 'rgba(6,2,8,0)');
  ctx.fillStyle = g; ctx.fillRect(0, H - 480, W, 480);
  g = ctx.createLinearGradient(0, 0, 320, 0);
  g.addColorStop(0, 'rgba(7,3,9,0.62)'); g.addColorStop(1, 'rgba(7,3,9,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 320, H);
  g = ctx.createLinearGradient(W, 0, W - 320, 0);
  g.addColorStop(0, 'rgba(7,3,9,0.62)'); g.addColorStop(1, 'rgba(7,3,9,0)');
  ctx.fillStyle = g; ctx.fillRect(W - 320, 0, 320, H);
  g = ctx.createRadialGradient(800, 940, 520, 800, 940, 1520);
  g.addColorStop(0, 'rgba(5,2,7,0)'); g.addColorStop(1, 'rgba(5,2,7,0.5)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
}

function paintGrain() {
  noStroke();
  for (var i = 0; i < 3800; i++) {
    var x = random(W), y = random(H);
    var d = random(1, 2.4);
    if (random() < 0.55) fill(45, 25, 90, random(1.5, 4));
    else fill(275, 50, 5, random(2, 5));
    rect(x, y, d, d);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  const ctx = drawingContext;
  const W = width;
  const H = height;
  const cx = W * 0.5;
  const cy = H * 0.5;

  noStroke();
  let bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#0d0511');
  bg.addColorStop(0.28, '#220a20');
  bg.addColorStop(0.56, '#471024');
  bg.addColorStop(0.82, '#310b1b');
  bg.addColorStop(1, '#12050d');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  for (let i = 0; i < 90; i++) {
    let x = random(W);
    let y = random(H);
    let r = random(80, 420);
    let n = noise(x * 0.0015, y * 0.0015, i * 0.02);
    let c;
    if (n < 0.35) c = 'rgba(118,32,64,0.045)';
    else if (n < 0.65) c = 'rgba(158,64,36,0.038)';
    else c = 'rgba(64,34,96,0.042)';
    let g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, c);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }

  function glow(x, y, r, inner, outer, mode) {
    ctx.save();
    ctx.globalCompositeOperation = mode;
    let g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, inner);
    g.addColorStop(1, outer);
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
    ctx.restore();
  }

  glow(cx, cy, 1150, 'rgba(255,170,110,0.14)', 'rgba(255,170,110,0)', 'lighter');
  glow(cx - 220, cy - 70, 700, 'rgba(255,62,88,0.30)', 'rgba(255,62,88,0)', 'lighter');
  glow(cx + 220, cy + 70, 700, 'rgba(56,140,255,0.24)', 'rgba(56,140,255,0)', 'lighter');
  glow(cx, cy, 460, 'rgba(255,230,170,0.34)', 'rgba(255,230,170,0)', 'lighter');
  glow(cx, cy - 760, 520, 'rgba(255,120,80,0.10)', 'rgba(255,120,80,0)', 'lighter');
  glow(cx, cy + 760, 560, 'rgba(255,80,120,0.09)', 'rgba(255,80,120,0)', 'lighter');

  blendMode(ADD);
  for (let i = 0; i < 22; i++) {
    let x = random(W);
    let y = random(H);
    let w = random(120, 520);
    let h = random(300, 900);
    let a0 = random(TWO_PI);
    let span = random(0.5, 2.6);
    noFill();
    stroke(255, 180, 130, 7);
    strokeWeight(random(18, 70));
    arc(x, y, w, h, a0, a0 + span, OPEN);
  }
  blendMode(BLEND);

  function presence(xBase, yTop, yBottom, col, shift) {
    for (let s = 0; s < 26; s++) {
      noFill();
      stroke(col[0], col[1], col[2], 9 + s * 0.4);
      strokeWeight(1.1 + s * 0.06);
      beginShape();
      for (let t = 0; t <= 1.0001; t += 0.02) {
        let y = lerp(yTop, yBottom, t);
        let n1 = noise(xBase * 0.002 + t * 1.4, s * 0.055, shift);
        let n2 = noise(xBase * 0.0012 + t * 0.7, s * 0.03, shift + 30);
        let x = xBase + sin(t * PI * 2.2 + shift + s * 0.12) * (70 + n1 * 260) + (n2 - 0.5) * 210;
        curveVertex(x, y);
      }
      endShape();
    }
  }

  blendMode(ADD);
  presence(cx - 235, H * 0.16, H * 0.86, [255, 82, 92], 0.0);
  presence(cx + 235, H * 0.18, H * 0.88, [86, 150, 255], 3.7);
  presence(cx, H * 0.12, H * 0.90, [255, 214, 150], 7.2);
  blendMode(BLEND);

  noFill();
  for (let i = 0; i < 32; i++) {
    let t = i / 31;
    let r1 = 310 + t * 80 + noise(i * 0.18) * 22;
    let r2 = 310 + (1 - t) * 80 + noise(i * 0.21 + 20) * 22;
    stroke(255, 205, 145, 12);
    strokeWeight(1.2);
    ellipse(cx - 220, cy - 70, r1 * 2, r1 * 1.72);
    stroke(170, 205, 255, 10);
    ellipse(cx + 220, cy + 70, r2 * 2, r2 * 1.72);
  }

  blendMode(ADD);
  for (let i = 0; i < 90; i++) {
    let a = random(TWO_PI);
    let rr = random(20, 390);
    let x = cx + cos(a) * rr * 1.15 + (noise(i * 0.03) - 0.5) * 140;
    let y = cy + sin(a) * rr * 0.82 + (noise(i * 0.04, 5) - 0.5) * 140;
    let d = random(2, 14);
    noStroke();
    fill(255, 235, 190, random(16, 52));
    ellipse(x, y, d, d);
  }

  for (let i = 0; i < 150; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.004, y * 0.004);
    if (n > 0.46) {
      noStroke();
      fill(255, 220, 180, random(6, 24));
      ellipse(x, y, random(1, 4), random(1, 4));
    }
  }
  blendMode(BLEND);

  noFill();
  stroke(255, 214, 160, 26);
  strokeWeight(1.5);
  beginShape();
  for (let t = 0; t <= 1.0001; t += 0.01) {
    let x = cx + sin(t * PI * 5 + 0.7) * (40 + noise(t * 2.0) * 220);
    let y = lerp(H * 0.08, H * 0.93, t);
    curveVertex(x, y);
  }
  endShape();

  stroke(255, 120, 130, 18);
  beginShape();
  for (let t = 0; t <= 1.0001; t += 0.01) {
    let x = cx + cos(t * PI * 4 + 2.1) * (60 + noise(t * 1.6 + 10) * 260);
    let y = lerp(H * 0.10, H * 0.95, t);
    curveVertex(x, y);
  }
  endShape();

  let vg = ctx.createRadialGradient(cx, cy, 620, cx, cy, 1500);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(6,2,8,0.66)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);

  noFill();
  stroke(255, 205, 150, 30);
  strokeWeight(2);
  rect(48, 48, W - 96, H - 96);
  stroke(255, 205, 150, 12);
  strokeWeight(1);
  rect(66, 66, W - 132, H - 132);
}

function draw() {}

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();
}

function draw() {
  const warm = [
    [218, 89, 73],
    [238, 132, 91],
    [173, 58, 64],
    [111, 40, 60],
    [244, 166, 116],
    [197, 74, 68]
  ];
  const cool = [
    [41, 113, 122],
    [59, 143, 139],
    [78, 125, 157],
    [112, 177, 158],
    [23, 52, 77],
    [46, 91, 116]
  ];

  ground();
  auras();

  const left = makePath([
    [[315, 1845], [500, 1580], [195, 1370], [390, 1090]],
    [[390, 1090], [625, 835], [215, 680], [465, 405]],
    [[465, 405], [580, 235], [760, 295], [690, 525]]
  ]);

  const right = makePath([
    [[1285, 1845], [1090, 1580], [1410, 1360], [1200, 1090]],
    [[1200, 1090], [970, 835], [1395, 690], [1140, 410]],
    [[1140, 410], [1030, 235], [835, 305], [905, 530]]
  ]);

  strokeJoin(ROUND);
  strokeCap(ROUND);

  paintRibbon(left, 178, warm, [137, 48, 55], 1, [245, 167, 113]);
  paintRibbon(right, 178, cool, [28, 76, 90], -1, [145, 203, 174]);

  roots(left, 178, warm);
  roots(right, 178, cool);
  detachedPigment(left, 178, warm);
  detachedPigment(right, 178, cool);

  meetingSpace(left, right);
  patina();
}

function ground() {
  noFill();
  for (let y = 0; y < H; y += 4) {
    const t = y / H;
    const wave = sin(t * PI * 2.4) * 3;
    stroke(
      lerp(18, 43, t) + wave,
      lerp(20, 27, t) + wave * 0.35,
      lerp(34, 39, t) + wave * 0.65
    );
    strokeWeight(4.3);
    line(0, y, W, y);
  }

  noStroke();
  for (let i = 0; i < 430; i++) {
    let c;
    const q = random();
    if (q < 0.42) c = [108, 55, 72];
    else if (q < 0.84) c = [40, 68, 91];
    else c = [139, 104, 77];

    fill(c[0], c[1], c[2], random(2, 7));
    const r = random(70, 310);
    ellipse(
      random(-80, W + 80),
      random(-80, H + 80),
      r * random(1.1, 2.8),
      r * random(0.35, 1.05)
    );
  }
}

function auras() {
  noStroke();
  for (let i = 58; i > 0; i--) {
    const t = i / 58;
    fill(167, 63, 64, 1.35);
    ellipse(490, 1030, 150 + 1030 * t, 220 + 1480 * t);

    fill(42, 116, 126, 1.35);
    ellipse(1110, 1030, 150 + 1030 * t, 220 + 1480 * t);

    fill(201, 151, 88, 0.65);
    ellipse(800, 930, 60 + 570 * t, 100 + 1210 * t);
  }
}

function makePath(segments) {
  const pts = [];
  for (const s of segments) {
    for (let j = 0; j < 72; j++) {
      const t = j / 72;
      pts.push({
        x: cubic(s[0][0], s[1][0], s[2][0], s[3][0], t),
        y: cubic(s[0][1], s[1][1], s[2][1], s[3][1], t)
      });
    }
  }
  const last = segments[segments.length - 1][3];
  pts.push({ x: last[0], y: last[1] });
  return pts;
}

function cubic(a, b, c, d, t) {
  const u = 1 - t;
  return u * u * u * a +
    3 * u * u * t * b +
    3 * u * t * t * c +
    t * t * t * d;
}

function normalAt(pts, i) {
  const a = pts[max(0, i - 1)];
  const b = pts[min(pts.length - 1, i + 1)];
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len = max(0.0001, sqrt(dx * dx + dy * dy));
  return { x: -dy / len, y: dx / len };
}

function ribbonWidth(t, base) {
  const swelling = pow(max(0, sin(PI * t)), 0.58);
  return base * (0.34 + 0.66 * swelling) *
    (0.94 + 0.12 * noise(t * 5, base * 0.01));
}

function ribbonShape(pts, base, extra, c) {
  fill(c);
  noStroke();
  beginShape();

  for (let i = 0; i < pts.length; i++) {
    const t = i / (pts.length - 1);
    const n = normalAt(pts, i);
    const w = ribbonWidth(t, base) + extra + 2.5 * sin(i * 1.91);
    vertex(pts[i].x + n.x * w, pts[i].y + n.y * w);
  }

  for (let i = pts.length - 1; i >= 0; i--) {
    const t = i / (pts.length - 1);
    const n = normalAt(pts, i);
    const w = ribbonWidth(t, base) + extra + 2.5 * sin(i * 1.91);
    vertex(pts[i].x - n.x * w, pts[i].y - n.y * w);
  }

  endShape(CLOSE);
}

function traceOffset(pts, base, offset, start, end, phase) {
  const i0 = floor(start * (pts.length - 1));
  const i1 = floor(end * (pts.length - 1));

  beginShape();
  for (let i = i0; i <= i1; i++) {
    const t = i / (pts.length - 1);
    const n = normalAt(pts, i);
    const d = offset * ribbonWidth(t, base) + sin(t * 18 + phase) * 2.8;
    vertex(pts[i].x + n.x * d, pts[i].y + n.y * d);
  }
  endShape();
}

function paintRibbon(pts, base, palette, baseColor, innerSign, innerLight) {
  ribbonShape(
    pts,
    base,
    26,
    color(baseColor[0], baseColor[1], baseColor[2], 25)
  );
  ribbonShape(
    pts,
    base,
    10,
    color(baseColor[0], baseColor[1], baseColor[2], 65)
  );
  ribbonShape(
    pts,
    base,
    0,
    color(baseColor[0], baseColor[1], baseColor[2], 255)
  );

  noFill();

  for (let j = 0; j < 95; j++) {
    const c = pick(palette);
    const start = random(0, 0.88);
    const end = min(1, start + random(0.08, 0.52));
    stroke(c[0], c[1], c[2], random(5, 17));
    strokeWeight(random(12, 55));
    traceOffset(
      pts,
      base,
      random(-0.84, 0.84),
      start,
      end,
      random(TWO_PI)
    );
  }

  for (let j = 0; j < 270; j++) {
    const c = pick(palette);
    const start = random(0, 0.96);
    const end = min(1, start + random(0.025, 0.32));
    stroke(c[0], c[1], c[2], random(12, 43));
    strokeWeight(random(0.7, 7));
    traceOffset(
      pts,
      base,
      random(-0.94, 0.94),
      start,
      end,
      random(TWO_PI)
    );
  }

  for (let j = 0; j < 28; j++) {
    const start = random(0.01, 0.79);
    const end = min(0.995, start + random(0.08, 0.31));
    stroke(
      innerLight[0],
      innerLight[1],
      innerLight[2],
      random(12, 45)
    );
    strokeWeight(random(1, 8));
    traceOffset(
      pts,
      base,
      innerSign * random(0.73, 0.96),
      start,
      end,
      random(TWO_PI)
    );
  }

  for (let j = 0; j < 180; j++) {
    const i = floor(random(3, pts.length - 3));
    const t = i / (pts.length - 1);
    const n = normalAt(pts, i);
    const w = ribbonWidth(t, base);
    const a = random(-0.96, 0.72);
    const b = min(0.99, a + random(0.05, 0.32));
    const c = pick(palette);

    stroke(c[0], c[1], c[2], random(10, 35));
    strokeWeight(random(0.5, 2.5));
    line(
      pts[i].x + n.x * w * a,
      pts[i].y + n.y * w * a,
      pts[i].x + n.x * w * b,
      pts[i].y + n.y * w * b
    );
  }
}

function roots(pts, base, palette) {
  const origin = pts[0];
  noFill();

  for (let i = 0; i < 30; i++) {
    const c = pick(palette);
    const x = origin.x + random(-65, 65);
    const y = origin.y + random(-35, 18);
    const endX = x + random(-100, 100);
    const endY = random(1880, 2005);

    stroke(c[0], c[1], c[2], random(10, 42));
    strokeWeight(random(0.6, 4.2));
    bezier(
      x, y,
      x + random(-55, 55), y + random(35, 100),
      endX + random(-45, 45), endY - random(25, 90),
      endX, endY
    );
  }
}

function detachedPigment(pts, base, palette) {
  noStroke();

  for (let j = 0; j < 145; j++) {
    const i = floor(random(2, pts.length - 2));
    const t = i / (pts.length - 1);
    const n = normalAt(pts, i);
    const side = random() < 0.5 ? -1 : 1;
    const d = side * ribbonWidth(t, base) * random(1.04, 1.72);
    const x = pts[i].x + n.x * d + random(-12, 12);
    const y = pts[i].y + n.y * d + random(-12, 12);
    const c = pick(palette);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(c[0], c[1], c[2], random(12, 68));
    ellipse(0, 0, random(1, 7), random(3, 18));
    pop();
  }
}

function edgePoint(pts, base, t, sign, fraction) {
  const i = floor(constrain(t, 0, 1) * (pts.length - 1));
  const n = normalAt(pts, i);
  const d = sign * ribbonWidth(t, base) * fraction;
  return {
    x: pts[i].x + n.x * d,
    y: pts[i].y + n.y * d
  };
}

function meetingSpace(left, right) {
  blendMode(ADD);
  noStroke();

  for (let i = 52; i > 0; i--) {
    const t = i / 52;
    fill(194, 137, 75, 0.8);
    ellipse(800, 930, 35 + 470 * t, 70 + 1090 * t);
  }

  for (let i = 34; i > 0; i--) {
    const t = i / 34;
    fill(238, 200, 137, 0.8);
    ellipse(800, 930, 20 + 165 * t, 50 + 590 * t);
  }

  blendMode(BLEND);
  noFill();

  for (let i = 0; i < 8; i++) {
    const at = 0.31 + i * 0.034 + random(-0.008, 0.008);
    const bt = at + random(-0.045, 0.045);
    const a = edgePoint(left, 178, at, 1, 0.88);
    const b = edgePoint(right, 178, bt, -1, 0.88);

    const c1x = lerp(a.x, 800, random(0.45, 0.8));
    const c1y = a.y + random(-150, 90);
    const c2x = lerp(b.x, 800, random(0.45, 0.8));
    const c2y = b.y + random(-90, 150);

    stroke(222, 164, 84, 6);
    strokeWeight(14);
    bezier(a.x, a.y, c1x, c1y, c2x, c2y, b.x, b.y);

    stroke(231, 184, 105, 28);
    strokeWeight(4);
    bezier(a.x, a.y, c1x, c1y, c2x, c2y, b.x, b.y);

    stroke(246, 215, 151, 145);
    strokeWeight(random(0.65, 1.35));
    bezier(a.x, a.y, c1x, c1y, c2x, c2y, b.x, b.y);
  }

  stroke(232, 185, 106, 5);
  strokeWeight(12);
  bezier(690, 1330, 940, 1190, 640, 1030, 830, 900);
  bezier(830, 900, 1010, 780, 700, 650, 875, 510);

  stroke(244, 211, 145, 82);
  strokeWeight(1.15);
  bezier(690, 1330, 940, 1190, 640, 1030, 830, 900);
  bezier(830, 900, 1010, 780, 700, 650, 875, 510);

  noStroke();
  for (let i = 0; i < 165; i++) {
    const x = 800 + randomGaussian() * 140;
    const y = 930 + randomGaussian() * 350;
    const r = random(0.7, 4.2);
    const pale = random() < 0.28;

    if (pale) fill(250, 227, 178, random(35, 125));
    else fill(222, 167, 87, random(25, 105));

    ellipse(x, y, r, r * random(0.7, 1.8));
  }
}

function patina() {
  blendMode(BLEND);

  for (let i = 0; i < 23000; i++) {
    const x = random(W);
    const y = random(H);

    if (random() < 0.55) {
      stroke(238, 220, 190, random(2, 9));
    } else {
      stroke(0, 0, 10, random(3, 12));
    }

    strokeWeight(random(0.4, 1.4));
    point(x, y);
  }

  for (let i = 0; i < 1500; i++) {
    const x = random(W);
    const y = random(H);
    stroke(235, 218, 188, random(2, 6));
    strokeWeight(random(0.35, 0.8));
    line(x, y, x + random(4, 30), y + random(-0.8, 0.8));
  }

  for (let i = 0; i < 900; i++) {
    const x = random(W);
    const y = random(H);
    stroke(4, 7, 15, random(2, 6));
    strokeWeight(random(0.35, 0.8));
    line(x, y, x + random(-0.8, 0.8), y + random(5, 27));
  }

  noFill();
  for (let i = 0; i < 90; i++) {
    stroke(5, 7, 15, 1.8);
    strokeWeight(3);
    const d = i * 1.6;
    rect(d, d, W - 2 * d, H - 2 * d);
