function buildPath(segments, steps) {
  let raw = [];

  for (let s = 0; s < segments.length; s++) {
    let a = segments[s];
    for (let j = 0; j < steps; j++) {
      let t = j / steps;
      raw.push(createVector(
        cubic(a[0], a[2], a[4], a[6], t),
        cubic(a[1], a[3], a[5], a[7], t)
      ));
    }
  }

  let z = segments[segments.length - 1];
  raw.push(createVector(z[6], z[7]));

  let result = [];
  for (let i = 0; i < raw.length; i++) {
    let before = raw[max(0, i - 1)];
    let after = raw[min(raw.length - 1, i + 1)];
    let tangent = p5.Vector.sub(after, before).normalize();
    result.push({
      p: raw[i],
      n: createVector(-tangent.y, tangent.x),
      t: i / (raw.length - 1)
    });
  }
  return result;
}

function cubic(a, b, c, d, t) {
  let u = 1 - t;
  return u * u * u * a +
    3 * u * u * t * b +
    3 * u * t * t * c +
    t * t * t * d;
}

function currentWidth(t, phase) {
  return (155 + 215 * pow(max(0, sin(PI * t)), 0.65)) *
    (1 - 0.2 * t) *
    (1 + 0.045 * sin(17 * t + phase));
}

function ribbon(info, phase, scale) {
  beginShape();
  for (let i = 0; i < info.length; i++) {
    let a = info[i];
    let w = currentWidth(a.t, phase) * scale * 0.5;
    vertex(a.p.x + a.n.x * w, a.p.y + a.n.y * w);
  }
  for (let i = info.length - 1; i >= 0; i--) {
    let a = info[i];
    let w = currentWidth(a.t, phase) * scale * 0.5;
    vertex(a.p.x - a.n.x * w, a.p.y - a.n.y * w);
  }
  endShape(CLOSE);
}

function strandPoint(info, i, q, phase) {
  let a = info[i];
  let w = currentWidth(a.t, phase);
  let offset = q * w * 0.47 +
    sin(a.t * 16 + phase + q * 3) * 8 +
    (noise(i * 0.018 + phase * 3, q * 7 + 40) - 0.5) * 16;
  return [
    a.p.x + a.n.x * offset,
    a.p.y + a.n.y * offset
  ];
}

function ink(pal) {
  let r = random();
  if (r < 0.22) {
    return lerpColor(pal.deep, pal.middle, random(0.15, 0.85));
  }
  if (r < 0.8) {
    return lerpColor(pal.middle, pal.light, random(0.1, 0.9));
  }
  return lerpColor(pal.light, pal.pale, random(0.15, 0.85));
}

function setStroke(c, a) {
  stroke(red(c), green(c), blue(c), a);
}

function paintCurrent(info, pal, phase) {
  strokeCap(ROUND);
  strokeJoin(ROUND);

  noStroke();
  fill(red(pal.deep), green(pal.deep), blue(pal.deep), 115);
  ribbon(info, phase, 1.2);

  fill(pal.base);
  ribbon(info, phase, 1);

  fill(red(pal.middle), green(pal.middle), blue(pal.middle), 45);
  ribbon(info, phase, 0.8);

  for (let layer = 0; layer < 2; layer++) {
    let count = layer === 0 ? 22 : 118;

    for (let s = 0; s < count; s++) {
      let q = random(-1, 1);
      let c = ink(pal);
      let alpha = layer === 0 ? random(14, 36) : random(42, 145);
      if (abs(q) > 0.82) alpha *= 0.72;

      setStroke(c, alpha);
      strokeWeight(layer === 0 ? random(12, 34) : random(1.1, 5.6));
      noFill();

      let i0 = 0;
      let i1 = info.length - 1;
      if (layer === 1 && random() < 0.4) {
        i0 = floor(random(0, info.length - 45));
        i1 = min(info.length - 1, i0 + floor(random(35, 180)));
      }

      beginShape();
      for (let i = i0; i <= i1; i++) {
        let p = strandPoint(info, i, q, phase);
        vertex(p[0], p[1]);
      }
      endShape();
    }
  }

  for (let side of [-1, 1]) {
    setStroke(pal.pale, 48);
    strokeWeight(2);
    noFill();
    beginShape();
    for (let i = 0; i < info.length; i++) {
      let p = strandPoint(info, i, side * 0.96, phase);
      vertex(p[0], p[1]);
    }
    endShape();
  }

  for (let k = 0; k < 100; k++) {
    let i = floor(random(3, info.length - 4));
    let q = random(-0.9, 0.9);
    let p = strandPoint(info, i, q, phase);
    let a = info[i];
    let len = random(12, 70);
    setStroke(ink(pal), random(35, 115));
    strokeWeight(random(1.5, 7));
    line(
      p[0], p[1],
      p[0] + a.n.y * len,
      p[1] - a.n.x * len
    );
  }

  for (let k = 0; k < 560; k++) {
    let i = floor(random(2, info.length - 2));
    let a = info[i];
    let side = random() < 0.5 ? -1 : 1;
    let w = currentWidth(a.t, phase);
    let off = side * w * random(0.47, 0.6);
    let x = a.p.x + a.n.x * off;
    let y = a.p.y + a.n.y * off;
    let len = random(4, 34);

    setStroke(ink(pal), random(18, 78));
    strokeWeight(random(0.6, 2.8));
    line(x, y, x + a.n.y * len, y - a.n.x * len);
  }
}

function paintInterlace(info, pal, phase) {
  let i0 = floor((info.length - 1) * 0.502);
  let i1 = floor((info.length - 1) * 0.575);

  noStroke();
  fill(pal.base);
  beginShape();

  for (let i = i0; i <= i1; i++) {
    let a = info[i];
    let u = (i - i0) / (i1 - i0);
    let taper = pow(max(0, sin(PI * u)), 0.22);
    let w = currentWidth(a.t, phase) * taper * 0.5;
    vertex(a.p.x + a.n.x * w, a.p.y + a.n.y * w);
  }

  for (let i = i1; i >= i0; i--) {
    let a = info[i];
    let u = (i - i0) / (i1 - i0);
    let taper = pow(max(0, sin(PI * u)), 0.22);
    let w = currentWidth(a.t, phase) * taper * 0.5;
    vertex(a.p.x - a.n.x * w, a.p.y - a.n.y * w);
  }
  endShape(CLOSE);

  for (let s = 0; s < 46; s++) {
    let q = random(-0.95, 0.95);
    setStroke(ink(pal), random(50, 145));
    strokeWeight(random(1.2, 5));
    noFill();
    beginShape();

    for (let i = i0; i <= i1; i++) {
      let a = info[i];
      let u = (i - i0) / (i1 - i0);
      let taper = pow(max(0, sin(PI * u)), 0.22);
      let p = strandPoint(info, i, q, phase);
      vertex(
        a.p.x + (p[0] - a.p.x) * taper,
        a.p.y + (p[1] - a.p.y) * taper
      );
    }
    endShape();
  }
}

function paintDissolve(info, pal, phase) {
  for (let i = 0; i < 230; i++) {
    let top = random() < 0.78;
    let t = top ? random(0.77, 1) : random(0, 0.14);
    let index = floor(t * (info.length - 1));
    let a = info[index];
    let w = currentWidth(a.t, phase);
    let off = random(-0.8, 0.8) * w;
    let x = a.p.x + a.n.x * off + random(-18, 18);
    let y = a.p.y + a.n.y * off;

    if (top) {
      y -= pow(random(), 2) * 190;
    } else {
      y += random(-20, 80);
    }

    let c = ink(pal);
    fill(red(c), green(c), blue(c), random(25, 130));
    noStroke();

    if (random() < 0.72) {
      ellipse(x, y, random(1, 5), random(2, 13));
    } else {
      push();
      translate(x, y);
      rotate(random(-0.5, 0.5));
      rect(0, 0, random(1, 3), random(8, 30));
      pop();
    }
  }
}

function paintOrbits() {
  push();
  translate(800, 1020);
  rotate(-0.1);
  noFill();

  for (let i = 0; i < 4; i++) {
    stroke(201, 176, 139, 10 + i * 3);
    strokeWeight(0.8 + i * 0.25);
    arc(
      0, 0,
      1050 + i * 105,
      1390 + i * 70,
      PI * 0.93,
      PI * 1.37
    );
    arc(
      0, 0,
      1050 + i * 105,
      1390 + i * 70,
      -PI * 0.15,
      PI * 0.27
    );
  }
  pop();
}

function centralLight() {
  blendMode(SCREEN);
  radialWash(800, 1040, 470, [
    [0, "rgba(255,225,165,0.27)"],
    [0.24, "rgba(247,181,122,0.11)"],
    [1, "rgba(247,181,122,0)"]
  ]);
  blendMode(BLEND);

  for (let i = 0; i < 48; i++) {
    let y = random(835, 1250);
    let d = abs(y - 1040) / 210;
    let x = 800 + random(-1, 1) * (25 + 90 * d);
    let len = random(12, 62);

    stroke(246, 207, 143, random(25, 92));
    strokeWeight(random(0.7, 2.8));
    noFill();
    bezier(
      x, y,
      x + random(-16, 16), y - len * 0.35,
      x + random(-18, 18), y - len * 0.72,
      x + random(-8, 8), y - len
    );
