function vignette() {
  let ctx = drawingContext;
  let v = ctx.createRadialGradient(800, 960, 480, 800, 960, 1280);
  v.addColorStop(0, "rgba(3,5,18,0)");
  v.addColorStop(0.72, "rgba(3,5,18,0.08)");
  v.addColorStop(1, "rgba(3,5,18,0.54)");
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, width, height);
}

function radialWash(x, y, r, stops) {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (let stop of stops) {
    g.addColorStop(stop[0], stop[1]);
  }
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

