function ribbonControls(side) {
  if (side === 0) {
    return [
      [160, 2050],
      [40, 1260],
      [770, 1130],
      [694, 128]
    ];
  }
  return [
    [1450, 2050],
    [1540, 1190],
    [884, 1150],
    [914, 180]
  ];
}

function ribbonColor(side, t) {
  const a = side === 0 ? [62, 25, 48] : [18, 42, 59];
  const b = side === 0 ? [164, 59, 65] : [54, 113, 119];
  const c = side === 0 ? [229, 146, 108] : [193, 207, 178];

  let p;
  let q;
  let f;

  if (t < 0.6) {
    p = a;
    q = b;
    f = t / 0.6;
  } else {
    p = b;
    q = c;
    f = (t - 0.6) / 0.4;
  }

  return color(
    lerp(p[0], q[0], f),
    lerp(p[1], q[1], f),
    lerp(p[2], q[2], f)
  );
}

function ribbonFrame(side, t) {
  const p = ribbonControls(side);
  const mt = 1 - t;

  const x =
    mt * mt * mt * p[0][0] +
    3 * mt * mt * t * p[1][0] +
    3 * mt * t * t * p[2][0] +
    t * t * t * p[3][0];

  const y =
    mt * mt * mt * p[0][1] +
    3 * mt * mt * t * p[1][1] +
    3 * mt * t * t * p[2][1] +
    t * t * t * p[3][1];

  const dx =
    3 * mt * mt * (p[1][0] - p[0][0]) +
    6 * mt * t * (p[2][0] - p[1][0]) +
    3 * t * t * (p[3][0] - p[2][0]);

  const dy =
    3 * mt * mt * (p[1][1] - p[0][1]) +
    6 * mt * t * (p[2][1] - p[1][1]) +
    3 * t * t * (p[3][1] - p[2][1]);

  const d = sqrt(dx * dx + dy * dy) || 1;

  return {
    x,
    y,
    tx: dx / d,
    ty: dy / d,
    nx: -dy / d,
    ny: dx / d
  };
}

function ribbonPoint(side, t, u, extra = 0) {
  const f = ribbonFrame(side, t);
  const base = side === 0 ? 570 : 535;
  const w =
    base *
    pow(max(0, 1 - t), 0.72) *
    (0.86 + 0.22 * sin(PI * t));
  const offset = u * (w * 0.5 + extra);

  return {
    x: f.x + f.nx * offset,
    y: f.y + f.ny * offset,
    tx: f.tx,
    ty: f.ty
  };
}

function ribbonShape(side, extra = 0) {
  beginShape();

  for (let i = 0; i <= 120; i++) {
    const p = ribbonPoint(side, i / 120, -1, extra);
    vertex(p.x, p.y);
  }

  for (let i = 120; i >= 0; i--) {
    const p = ribbonPoint(side, i / 120, 1, extra);
    vertex(p.x, p.y);
  }

  endShape(CLOSE);
}

function drawRibbon(side) {
  const inner = side === 0 ? 1 : -1;

  blendMode(SCREEN);
  noStroke();

  for (let k = 9; k > 0; k--) {
    if (side === 0) {
      fill(164, 64, 66, 2);
    } else {
      fill(80, 137, 139, 2);
    }
    ribbonShape(side, k * 5);
  }

  blendMode(BLEND);
  noStroke();
  fill(ribbonColor(side, 0.45));
  ribbonShape(side);

  const steps = 190;
  const across = 6;

  for (let i = 0; i < steps; i++) {
    const t0 = i / steps;
    const t1 = (i + 1) / steps;

    for (let j = 0; j < across; j++) {
      const u0 = -1 + (j / across) * 2;
      const u1 = -1 + ((j + 1) / across) * 2;
      const um = (u0 + u1) * 0.5;

      const a = ribbonPoint(side, t0, u0);
      const b = ribbonPoint(side, t0, u1);
      const c = ribbonPoint(side, t1, u1);
      const d = ribbonPoint(side, t1, u0);
      const col = ribbonColor(side, (t0 + t1) * 0.5);

      const shade =
        (noise(i * 0.075, j * 0.43, side * 4.1) - 0.5) * 20 +
        7 * (1 - abs(um)) +
        15 * pow(max(0, inner * um), 3);

      fill(
        constrain(red(col) + shade, 0, 255),
        constrain(green(col) + shade, 0, 255),
        constrain(blue(col) + shade, 0, 255)
      );

      quad(a.x, a.y, b.x, b.y, c.x, c.y, d.x, d.y);
    }
  }

  for (let k = 0; k < 470; k++) {
    const u = random(-1.035, 1.035);
    let t0;
    let t1;

    if (k < 90) {
      t0 = random(0, 0.12);
      t1 = random(0.68, 0.995);
    } else {
      t0 = random(0, 0.91);
      t1 = min(0.998, t0 + random(0.05, 0.32));
    }

    const col = ribbonColor(side, (t0 + t1) * 0.5);
    const gilded = random() < 0.16;
    const lift = random(-38, 58);
    let alpha = random(12, 43);
    let weight = random(1, 5.2);

    if (k % 19 === 0) {
      weight *= 3.2;
      alpha *= 0.42;
    }

    noFill();
    strokeWeight(weight);

    if (gilded) {
      if (side === 0) {
        stroke(246, 187, 129, alpha);
      } else {
        stroke(224, 229, 199, alpha);
      }
    } else {
      stroke(
        constrain(red(col) + lift, 0, 255),
        constrain(green(col) + lift, 0, 255),
        constrain(blue(col) + lift, 0, 255),
        alpha
      );
    }

    const phase = random(TWO_PI);
    const frequency = random(5, 15);

    beginShape();
    for (let j = 0; j <= 44; j++) {
      const s = j / 44;
      const t = lerp(t0, t1, s);
      const uu =
        u +
        0.026 *
          sin(phase + t * frequency) *
          sin(PI * s);
      const p = ribbonPoint(side, t, uu);
      vertex(p.x, p.y);
    }
    endShape();
  }

  for (let k = 0; k < 1000; k++) {
    const t = random(0.01, 0.985);
    const p = ribbonPoint(side, t, random(-1.08, 1.08));
    const col = ribbonColor(side, t);
    const lift = random() < 0.6 ? random(20, 70) : random(-45, -10);
    const len = random(3, 24) * (1 - 0.45 * t);

    stroke(
      constrain(red(col) + lift, 0, 255),
      constrain(green(col) + lift, 0, 255),
      constrain(blue(col) + lift, 0, 255),
      random(8, 35)
    );
    strokeWeight(random(0.5, 2.2));
    line(
      p.x - p.tx * len * 0.5,
      p.y - p.ty * len * 0.5,
      p.x + p.tx * len * 0.5,
      p.y + p.ty * len * 0.5
    );
  }

  noFill();

  for (let j = 0; j < 5; j++) {
    if (side === 0) {
      stroke(247, 184, 128, 34 - j * 5);
    } else {
      stroke(221, 229, 196, 34 - j * 5);
    }

    strokeWeight(1.2 + j * 0.9);
    beginShape();

    for (let i = 0; i <= 100; i++) {
      const t = lerp(0.008, 0.992, i / 100);
      const p = ribbonPoint(
        side,
        t,
        inner * (0.985 - j * 0.018)
      );
      vertex(p.x, p.y);
    }

    endShape();
  }
}

function seedPath() {
  beginShape();
  vertex(800, 875);
  bezierVertex(850, 907, 869, 958, 839, 1005);
  bezierVertex(817, 1038, 776, 1043, 751, 1004);
  bezierVertex(718, 954, 748, 905, 800, 875);
  endShape(CLOSE);
}

function paintSharedLight() {
  blendMode(SCREEN);
  noStroke();

  for (let i = 0; i < 85; i++) {
    const q = i / 84;
    const r = lerp(430, 28, q);
    fill(216, 137, 70, i < 70 ? 2 : 3);
    ellipse(800, 960, r * 1.12, r * 1.42);
  }

  blendMode(BLEND);

  for (let i = 0; i < 78; i++) {
    const y = random(520, 1400);
    const distance = abs(y - 960);
    if (distance < 115) continue;

    const spread = 24 + distance * 0.16;
    const x = randomGaussian(800, spread * 0.45);
    if (x < 650 || x > 950) continue;

    const alpha = constrain(110 - distance * 0.16, 12, 85);
    const radius = random(1.2, 4.8) * (random() < 0.08 ? 2 : 1);

    noStroke();
    fill(235, 185, 107, alpha);
    circle(x, y, radius);
  }

  push();
  drawingContext.save();
  drawingContext.shadowColor = "rgba(255, 184, 91, 0.8)";
  drawingContext.shadowBlur = 60;
  noStroke();
  fill(234, 161, 80);
  seedPath();
  drawingContext.restore();
  pop();

  push();
  translate(800, 960);
  scale(0.62);
  translate(-800, -960);
  noStroke();
  fill(255, 226, 161, 235);
  seedPath();
  pop();

  noStroke();
  fill(255, 244, 205, 210);
  ellipse(784, 928, 19, 42);
}

function paintSurface() {
  for (let i = 0; i < 6500; i++) {
    const x = random(width);
    const y = random(height);

    if (random() < 0.55) {
      stroke(238, 225, 204, random(2, 8));
    } else {
      stroke(0, 0, 12, random(2, 7));
    }

    strokeWeight(random(0.35, 1.1));
    point(x, y);
  }

  strokeWeight(0.45);

  for (let x = 2; x < width; x += 7) {
    stroke(225, 215, 198, 2);
    line(x, 0, x, height);
  }

  for (let y = 2; y < height; y += 7) {
    stroke(5, 7, 20, 2);
    line(0, y, width, y);
  }

  for (let i = 0; i < 180; i++) {
    const x = random(width);
    const y = random(height);
    stroke(225, 209, 185, random(2, 6));
    strokeWeight(random(0.4, 1));
    line(x, y, x + random(-3, 3), y + random(8, 42));
  }

  noFill();

  for (let i = 0; i < 42; i++) {
    const d = i * 5;
    stroke(2, 4, 14, 3);
    strokeWeight(16);
    rect(
      d - 8,
      d - 8,
      width - 2 * (d - 8),
      height - 2 * (d - 8)
    );
  }
}

const W = 1600;
const H = 2000;

const PATHS = [
  [
    [[360, 1780], [150, 1450], [700, 1420], [650, 1110]],
    [[650, 1110], [610, 870], [925, 830], [835, 575]],
    [[835, 575], [770, 390], [555, 365], [630, 155]]
  ],
  [
    [[1240, 1780], [1450, 1450], [900, 1420], [970, 1110]],
    [[970, 1110], [1030, 880], [675, 830], [765, 575]],
    [[765, 575], [830, 390], [1045, 365], [980, 155]]
  ]
];

let palette;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);

  palette = [
    [
      color(133, 32, 66),
      color(205, 52, 72),
      color(235, 84, 72),
      color(246, 145, 94),
      color(255, 211, 161)
    ],
    [
      color(24, 62, 103),
      color(27, 119, 139),
      color(44, 165, 160),
      color(100, 194, 184),
      color(176, 231, 213)
    ]
  ];
}

function draw() {
  paint();
  noLoop();
}

function paint() {
  const top = color(11, 17, 35);
  const middle = color(29, 20, 44);
  const bottom = color(9, 20, 31);

  for (let y = 0; y < H; y++) {
    const t = y / (H - 1);
    let c;
    if (t < 0.56) {
      c = lerpColor(top, middle, t / 0.56);
    } else {
      c = lerpColor(middle, bottom, (t - 0.56) / 0.44);
    }
    stroke(c);
    line(0, y, W, y);
  }

  softGlow(800, 960, 1540, 1880, color(89, 48, 91), 80, 0.8);
  softGlow(570, 1180, 720, 1050, color(142, 42, 66), 65, 0.45);
  softGlow(1050, 970, 680, 1100, color(24, 111, 123), 65, 0.42);
  softGlow(805, 850, 460, 540, color(235, 153, 117), 70, 0.38);

  drawAtmosphere();
  drawReflections();

  drawCurrent(0);
  drawCurrent(1);

  drawInterlace();
  drawBristles(0);
  drawBristles(1);
  drawFlecks();
  finalGrain();
}

function drawAtmosphere() {
  strokeCap(ROUND);

  for (let i = 0; i < 6500; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.0025, y * 0.0025);
    if (n > 0.34) {
      stroke(180, 156, 182, random(1.2, 4.2));
      strokeWeight(random(0.35, 1.1));
      line(x, y, x + random(-1.5, 1.5), y + random(4, 30));
    }
  }

  noFill();
  for (let i = 0; i < 95; i++) {
    const c = i % 2 === 0
      ? color(115, 91, 137)
      : color(45, 105, 119);
    stroke(red(c), green(c), blue(c), random(2, 6));
    strokeWeight(random(0.6, 2.2));

    const x = random(180, 1420);
    const y = random(100, 1900);
    const a = random(TWO_PI);
    arc(
      x, y,
      random(280, 1250),
      random(420, 1650),
      a,
      a + random(0.12, 0.62)
    );
  }
}

function drawCurrent(which) {
  const pal = palette[which];
  noFill();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  for (let s = 0; s < 84; s++) {
    const u = -1 + 2 * s / 83 + random(-0.008, 0.008);
    const phase = random(0, 200);
    const c = lerpColor(pal[0], pal[1], random());
    stroke(red(c), green(c), blue(c), random(5, 10));
    strokeWeight(random(18, 32));
    traceStrand(which, u, phase, 0, 1, 110);
  }

  for (let s = 0; s < 260; s++) {
    const u = -1 + 2 * s / 259 + random(-0.009, 0.009);
    const phase = random(0, 200);
    const index = s % (pal.length - 1);
    const c = lerpColor(pal[index], pal[index + 1], random());
    const inner = constrain(1 - abs(u), 0, 1);

    stroke(
      red(c), green(c), blue(c),
      random(14, 29) + 32 * inner
    );
    strokeWeight(random(0.65, 2.8) + inner * 0.8);

    const t0 = random(0, 0.022);
    const t1 = random(0.972, 1);
    traceStrand(which, u, phase, t0, t1, 118);
  }
}

function drawInterlace() {
  softGlow(805, 850, 330, 390, color(244, 181, 137), 45, 0.22);

  noFill();
  strokeCap(ROUND);

  for (let i = 0; i < 42; i++) {
    const which = i % 2;
    const t0 = random(0.38, 0.58);
    const t1 = min(0.97, t0 + random(0.025, 0.12));
    const c = which === 0
      ? color(255, 211, 161)
      : color(176, 231, 213);

    stroke(red(c), green(c), blue(c), random(18, 58));
    strokeWeight(random(0.6, 2.2));
    traceStrand(
      which,
      random(-0.75, 0.75),
      random(0, 200),
      t0,
      t1,
      36
    );
  }

  noStroke();
  for (let i = 0; i < 130; i++) {
    const x = constrain(805 + randomGaussian() * 90, 450, 1150);
    const y = constrain(850 + randomGaussian() * 130, 500, 1200);
    const c = i % 2 === 0
      ? color(255, 213, 166)
      : color(174, 229, 213);
    fill(red(c), green(c), blue(c), random(12, 48));
    const r = random(0.5, 2.8);
    ellipse(x, y, r * 2, r * random(1, 3));
  }
}

function drawBristles(which) {
  strokeCap(ROUND);

  for (let i = 0; i < 270; i++) {
    const t = random(0.015, 0.985);
    const sign = random() < 0.5 ? -1 : 1;
    const u = sign * random(0.88, 1.32);
    const phase = random(0, 200);
    const p = strandPoint(which, t, u, phase);
    const q = strandPoint(
      which,
      min(0.999, t + random(0.002, 0.012)),
      u,
      phase
    );
    const c = paletteColor(which);

    stroke(red(c), green(c), blue(c), random(12, 48));
    strokeWeight(random(0.45, 2.1));
    line(p.x, p.y, q.x, q.y);
  }
}

function drawReflections() {
  strokeCap(ROUND);

  for (let which = 0; which < 2; which++) {
    const baseX = which === 0 ? 360 : 1240;

    for (let i = 0; i < 230; i++) {
      const d = pow(random(), 1.8) * 190;
      const y = 1785 + d;
      const spread = 65 + d * 0.85;
      const x = baseX + randomGaussian() * spread * 0.45;
      const len = random(10, 130) * (1 - d / 240);
      const c = paletteColor(which);

      stroke(
        red(c), green(c), blue(c),
        random(5, 28) * (1 - d / 250)
      );
      strokeWeight(random(0.6, 3));
      line(
        x - len * 0.5,
        y,
        x + len * 0.5,
        y + random(-1.5, 1.5)
      );
    }
  }
}

function drawFlecks() {
  noStroke();

  for (let which = 0; which < 2; which++) {
    for (let i = 0; i < 250; i++) {
      const t = random(0.015, 0.985);
      const sign = random() < 0.5 ? -1 : 1;
      const u = sign * random(1.08, 1.75);
      const p = strandPoint(which, t, u, random(0, 200));

      if (p.x > 0 && p.x < W && p.y > 0 && p.y < H) {
        const c = paletteColor(which);
        fill(red(c), green(c), blue(c), random(8, 42));
        const r = random(0.6, 3.4);
        ellipse(p.x, p.y, r, r * random(0.7, 2.8));
      }
    }
  }

  for (let i = 0; i < 1800; i++) {
    const x = random(W);
    const y = random(H);
    fill(190, 180, 200, random(1, 5));
    const r = random(0.4, 1.5);
    ellipse(x, y, r, r);
  }
}

function finalGrain() {
  for (let i = 0; i < 26000; i++) {
    const x = random(W);
    const y = random(H);

    if (random() < 0.5) {
      stroke(235, 220, 205, random(1, 4.5));
    } else {
      stroke(2, 5, 15, random(1.5, 5));
    }

    strokeWeight(random(0.35, 1.25));
    point(x, y);
  }

  for (let i = 0; i < 2400; i++) {
    const x = random(W);
    const y = random(H);
    stroke(215, 196, 190, random(0.7, 2.2));
    strokeWeight(0.5);
    line(x, y, x + random(-0.6, 0.6), y + random(2, 12));
  }
}

function pathPoint(which, t) {
  const z = constrain(t, 0, 0.999999) * PATHS[which].length;
  const k = floor(z);
  const u = z - k;
  const a = PATHS[which][k];

  return {
    x: bezierPoint(a[0][0], a[1][0], a[2][0], a[3][0], u),
    y: bezierPoint(a[0][1], a[1][1], a[2][1], a[3][1], u)
  };
}

function strandPoint(which, t, u, phase) {
  const p = pathPoint(which, t);
  const before = pathPoint(which, max(0, t - 0.0015));
  const after = pathPoint(which, min(1, t + 0.0015));
  const angle = atan2(after.y - before.y, after.x - before.x) + HALF_PI;

  const envelope = pow(max(0, sin(PI * t)), 0.72);
  const width = 18 + 178 * envelope + 58 * (1 - t);
  const wave =
    0.92 +
    0.08 * sin(t * 9 + phase) +
    0.035 * sin(t * 23 + phase * 0.7);

  const offset =
    u * width * wave +
    (noise(phase * 0.071, t * 7.3) - 0.5) * 18;

  const flutter =
    (noise(phase * 0.113 + 20, t * 11) - 0.5) * 8;

  return {
    x: p.x + cos(angle) * offset + cos(angle - HALF_PI) * flutter,
    y: p.y + sin(angle) * offset + sin(angle - HALF_PI) * flutter
  };
}

function traceStrand(which, u, phase, t0, t1, steps) {
  beginShape();
  for (let j = 0; j <= steps; j++) {
    const t = lerp(t0, t1, j / steps);
    const p = strandPoint(which, t, u, phase);
    vertex(p.x, p.y);
  }
  endShape();
}

function softGlow(x, y, rx, ry, c, steps, alpha) {
  noStroke();
  for (let i = steps; i > 0; i--) {
    const f = i / steps;
    fill(red(c), green(c), blue(c), alpha);
    ellipse(x, y, rx * f, ry * f);
  }
}

function paletteColor(which) {
  const pal = palette[which];
  return pal[floor(random(pal.length))];
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();
}

function draw() {
  paintGround();

  const warmControls = [
    [-180, 1850],
    [190, 1690],
    [390, 1430],
    [360, 1150],
    [450, 930],
    [650, 770],
    [850, 760],
    [1010, 880],
    [960, 1040],
    [820, 1090]
  ];

  const coolControls = [
    [1770, 150],
    [1410, 260],
    [1210, 500],
    [1250, 760],
    [1150, 1010],
    [960, 1190],
    [740, 1210],
    [590, 1090],
    [650, 930],
    [790, 890]
  ];

  const warmColors = [
    "#7e3148",
    "#c85b62",
    "#ed8b68",
    "#f2bd7a",
    "#f7d6ad"
  ];

  const coolColors = [
    "#244f68",
    "#327d89",
    "#55aaa5",
    "#8dbbc0",
    "#b7a5cf"
  ];

  blendMode(SCREEN);
