  const cool = buildCurrent(coolControls, 72);
  const warm = buildCurrent(warmControls, 72);

  drawCurrent(cool, 355, coolColors, 7.3);
  drawCurrent(warm, 360, warmColors, 2.1);
  drawMeeting();
  surfaceGrain();
}

function paintGround() {
  const top = color(7, 21, 33);
  const middle = color(23, 24, 45);
  const bottom = color(36, 19, 34);

  noStroke();
  for (let y = 0; y < height; y += 4) {
    const t = y / (height - 1);
    let c;
    if (t < 0.55) {
      c = lerpColor(top, middle, t / 0.55);
    } else {
      c = lerpColor(middle, bottom, (t - 0.55) / 0.45);
    }
    fill(c);
    rect(0, y, width, 5);
  }

  blendMode(SCREEN);
  radialGlow(250, 1390, 720, 900, color(78, 38, 55), 0.7);
  radialGlow(1360, 500, 680, 850, color(25, 75, 86), 0.65);
  radialGlow(810, 1050, 740, 680, color(48, 36, 67), 0.35);

  blendMode(BLEND);
  for (let i = 0; i < 1500; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.0018, y * 0.0018);
    const len = random(20, 170);
    stroke(150, 130, 155, random(1.2, 4.8));
    strokeWeight(random(0.35, 1.4));
    line(x, y, x + len * (n - 0.5), y + random(-2, 2));
  }
}

function radialGlow(x, y, rx, ry, c, strength) {
  noStroke();
  const steps = 90;
  for (let i = 0; i < steps; i++) {
    const t = i / (steps - 1);
    const k = max(0.002, 1 - t);
    const a = (0.22 + 1.55 * t) * strength;
    fill(red(c), green(c), blue(c), a);
    ellipse(x, y, 2 * rx * k, 2 * ry * k);
  }
}

function drawEchoes() {
  push();
  translate(800, 980);
  rotate(-0.18);
  noFill();

  const warm = color(224, 150, 127);
  const cool = color(103, 160, 177);

  for (let i = 0; i < 18; i++) {
    const c = lerpColor(warm, cool, i / 17);
    stroke(red(c), green(c), blue(c), random(3, 9));
    strokeWeight(random(0.7, 2.1));

    const rx = 280 + i * 23;
    const ry = 190 + i * 28;
    const start = random(-PI, PI);
    arc(0, 0, rx * 2, ry * 2, start, start + random(1.2, 4.8));
  }
  pop();
}

function buildCurrent(controls, steps) {
  const points = [];

  for (let i = 0; i < controls.length - 1; i++) {
    const p0 = controls[max(0, i - 1)];
    const p1 = controls[i];
    const p2 = controls[i + 1];
    const p3 = controls[min(controls.length - 1, i + 2)];

    for (let j = 0; j < steps; j++) {
      const t = j / steps;
      points.push({
        x: catmull(p0[0], p1[0], p2[0], p3[0], t),
        y: catmull(p0[1], p1[1], p2[1], p3[1], t)
      });
    }
  }

  const last = controls[controls.length - 1];
  points.push({ x: last[0], y: last[1] });

  for (let i = 0; i < points.length; i++) {
    const previous = points[max(0, i - 1)];
    const next = points[min(points.length - 1, i + 1)];
    const dx = next.x - previous.x;
    const dy = next.y - previous.y;
    const magnitude = max(0.0001, sqrt(dx * dx + dy * dy));

    points[i].nx = -dy / magnitude;
    points[i].ny = dx / magnitude;
    points[i].u = i / (points.length - 1);
  }

  return points;
}

function catmull(a, b, c, d, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  return 0.5 * (
    2 * b +
    (-a + c) * t +
    (2 * a - 5 * b + 4 * c - d) * t2 +
    (-a + 3 * b - 3 * c + d) * t3
  );
}

function currentWidth(t, base, seedOffset) {
  const envelope = pow(max(0, sin(PI * t)), 0.55);
  const body = 0.82 + 0.18 * sin(PI * t);
  const grain = 0.93 + 0.12 * noise(t * 5 + seedOffset, seedOffset);
  return base * envelope * body * grain;
}

function paletteColor(colors, t) {
  t = constrain(t, 0, 1);
  if (t >= 1) {
    return color(colors[colors.length - 1]);
  }

  const position = t * (colors.length - 1);
  const index = floor(position);
  return lerpColor(
    color(colors[index]),
    color(colors[index + 1]),
    position - index
  );
}

function drawCurrent(points, base, colors, seedOffset) {
  const middle = paletteColor(colors, 0.5);

  blendMode(BLEND);
  noStroke();
  fill(red(middle), green(middle), blue(middle), 38);
  beginShape();

  for (const p of points) {
    const w = currentWidth(p.u, base, seedOffset);
    vertex(p.x + p.nx * w, p.y + p.ny * w);
  }

  for (let i = points.length - 1; i >= 0; i--) {
    const p = points[i];
    const w = currentWidth(p.u, base, seedOffset);
    vertex(p.x - p.nx * w, p.y - p.ny * w);
  }
  endShape(CLOSE);

  blendMode(SCREEN);
  for (let layer = 12; layer >= 1; layer--) {
    paintStrip(
      points,
      base,
      colors,
      seedOffset,
      1 + layer * 0.035,
      1.3
    );
  }

  blendMode(BLEND);
  paintStrip(points, base, colors, seedOffset, 1, 154);

  blendMode(SCREEN);
  paintStrip(points, base, colors, seedOffset, 0.78, 16);
  paintStrip(points, base, colors, seedOffset, 0.38, 12);

  drawFibers(points, base, colors, seedOffset);
  drawPigment(points, base, colors, seedOffset);
}

function paintStrip(points, base, colors, seedOffset, widthScale, alpha) {
  noStroke();

  for (let i = 0; i < points.length - 1; i++) {
    const p = points[i];
    const q = points[i + 1];
    const wp = currentWidth(p.u, base, seedOffset) * widthScale;
    const wq = currentWidth(q.u, base, seedOffset) * widthScale;
    const c = paletteColor(colors, (p.u + q.u) * 0.5);

    fill(red(c), green(c), blue(c), alpha);
    quad(
      p.x + p.nx * wp,
      p.y + p.ny * wp,
      q.x + q.nx * wq,
      q.y + q.ny * wq,
      q.x - q.nx * wq,
      q.y - q.ny * wq,
      p.x - p.nx * wp,
      p.y - p.ny * wp
    );
  }
}

function drawFibers(points, base, colors, seedOffset) {
  const count = points.length;
  noFill();

  for (let s = 0; s < 190; s++) {
    const side = random(-1.06, 1.06);
    let start;
    let end;

    if (random() < 0.38) {
      start = floor(random(0.02, 0.72) * (count - 1));
      end = min(
        count - 1,
        start + floor(random(0.1, 0.32) * (count - 1))
      );
    } else {
      start = floor(random(0, 0.06) * (count - 1));
      end = count - 1;
    }

    const middle = (start + end) / (2 * (count - 1));
    const c = paletteColor(colors, middle);

    stroke(red(c), green(c), blue(c), random(12, 48));
    strokeWeight(random(0.55, 2.6));
    beginShape();

    for (let i = start; i <= end; i += 2) {
      const p = points[i];
      const w = currentWidth(p.u, base, seedOffset);
      const flutter = (
        noise(seedOffset + s * 0.073 + p.u * 3.1, p.u * 8) - 0.5
      ) * w * 0.12;
      const offset = side * w + flutter;

      vertex(
        p.x + p.nx * offset,
        p.y + p.ny * offset
      );
    }
    endShape();
  }
}

function drawPigment(points, base, colors, seedOffset) {
  noStroke();

  for (let i = 0; i < 1400; i++) {
    const index = floor(random(1, points.length - 1));
    const p = points[index];
    const w = currentWidth(p.u, base, seedOffset);
    const offset = (random(-1, 1) + random(-1, 1)) * 0.55 * w;
    const x = p.x + p.nx * offset + random(-3, 3);
    const y = p.y + p.ny * offset + random(-3, 3);
    const c = paletteColor(colors, p.u);
    const size = random(0.5, 3.2) * (random() < 0.03 ? 3 : 1);

    fill(red(c), green(c), blue(c), random(5, 38));
    ellipse(x, y, size, size * random(0.5, 1.8));
  }
}

function drawMeeting() {
  blendMode(SCREEN);
  radialGlow(805, 985, 250, 280, color(246, 190, 157), 1.6);
  radialGlow(805, 985, 95, 120, color(255, 230, 197), 1.0);

  noFill();
  for (let i = 0; i < 42; i++) {
    const sx = 820 + random(-65, 65);
    const sy = 1060 + random(-25, 45);
    const ex = 790 + random(-60, 60);
    const ey = 920 + random(-45, 25);

    stroke(
      255,
      random(200, 235),
      random(180, 220),
      random(8, 35)
    );
    strokeWeight(random(0.6, 2));

    bezier(
      sx,
      sy,
      sx + random(-120, 100),
      sy - random(30, 160),
      ex + random(-100, 120),
      ey + random(30, 160),
      ex,
      ey
    );
  }

  noStroke();
  for (let i = 0; i < 520; i++) {
    const angle = random(TWO_PI);
    const radius = pow(random(), 0.65) * 240;
    const x = 805 + cos(angle) * radius;
    const y = 985 + sin(angle) * radius * 1.08;
    const size = random(0.5, 2.6);

    fill(255, random(211, 238), random(180, 217), random(5, 32));
    ellipse(x, y, size, size);
  }
}

function surfaceGrain() {
  blendMode(BLEND);

  for (let i = 0; i < 38000; i++) {
    const x = random(width);
    const y = random(height);

    if (random() < 0.48) {
      stroke(238, 220, 205, random(1.5, 5));
    } else {
      stroke(0, 5, 14, random(2, 7));
    }

    strokeWeight(random(0.45, 1.15));
    if (random() < 0.07) {
      line(x, y, x + random(-3, 3), y + random(2, 9));
    } else {
      point(x, y);
    }
  }
}

// =============================================================
//  « Deux feux, une flamme »
//  Peinture générative : deux courants de feu montent de la nuit,
//  s'enlacent, s'embrasent à chaque étreinte, puis fusionnent
//  en une seule flamme. Toute la lumière est construite par
//  accumulation de traits de pinceau en mode additif.
// =============================================================

const W = 1600;
const H = 2000;
const CX = 800;
const T_FUSION = 0.86;

// Palettes : de l'ombre au cœur lumineux
const PAL_GOLD  = [[62, 32, 10], [140, 82, 20], [213, 145, 48], [247, 200, 110], [255, 240, 200]];
const PAL_ROSE  = [[44, 8, 30], [120, 25, 60], [197, 62, 96], [242, 133, 152], [255, 215, 220]];
const PAL_FLAME = [[194, 72, 24], [232, 120, 44], [250, 172, 92], [255, 215, 152], [255, 249, 226]];

// Points d'incandescence : deux sources à la base, deux étreintes, la fusion
const EMBERS = [
  { t: 0.045, s: 0.020, i: 0.34 },
  { t: 0.227, s: 0.030, i: 0.55 },
  { t: 0.682, s: 0.045, i: 0.72 },
  { t: 0.878, s: 0.055, i: 1.00 },
];

const FXP = CX + sway(T_FUSION);   // pied de la flamme (point de fusion)
const FYP = H * (1 - T_FUSION);
const FLAME_TOP = 62;
const FLAME_LEN = FYP - FLAME_TOP;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255);
  strokeCap(ROUND);
  noLoop();

  paintBackground();           // la nuit et sa matière

  blendMode(ADD);              // lumière additive : la peinture s'embrase
  paintHalo();                 // l'air éclairé autour des feux
  paintCurrent(-1, PAL_GOLD);  // le feu d'or
  paintCurrent(1, PAL_ROSE);   // le feu de carmin
  paintFlame();                // la flamme née de leur fusion
  paintEmberBursts();          // gerbes de braises aux étreintes
  paintSparks();               // étincelles envolées, braises dormantes

  blendMode(BLEND);
  paintGrain();                // grain de toile
}

// ------------------------------------------------------------- géométrie

function smoothstep(x, a, b) {
  const u = Math.min(Math.max((x - a) / (b - a), 0), 1);
  return u * u * (3 - 2 * u);
}

function gauss() {
  return Math.sqrt(-2 * Math.log(Math.max(random(), 1e-9))) * Math.cos(TWO_PI * random());
}

function sway(t) {  // la danse commune, amortie vers le haut
  const damp = 1 - 0.55 * smoothstep(t, 0.45, 0.95);
  return 120 * Math.sin(t * Math.PI * 1.35 + 0.35) * damp;
}

function sep(t) {   // écart entre les deux feux (négatif = places échangées)
  const f = 1 - smoothstep(t, 0.70, T_FUSION);
  const wob = 1 + 0.12 * Math.sin(t * 9.1 + 1.7);
  return 400 * f * wob * Math.cos(t * Math.PI * 2.2);
}

function center(t, side) { return CX + sway(t) + side * sep(t) * 0.5; }
function yc(t) { return H * (1 - t); }

function tangent(t, side) {
  const e = 0.006;
  return Math.atan2(yc(t + e) - yc(t - e), center(t + e, side) - center(t - e, side));
}

function halfW(t, side) {
  const base = 124 - 62 * t;
  return base * (0.85 + 0.30 * noise(t * 4.3, side * 7.7));
}

function glowAt(t) {  // chaleur locale des étreintes
  let g = 0;
  for (let k = 0; k < EMBERS.length; k++) {
    const e = EMBERS[k];
    const d = (t - e.t) / e.s;
    g += e.i * Math.exp(-d * d * 0.5);
  }
  return Math.min(g, 1.25);
}

function emberPoints(e) {
  if (e.t < 0.12) {  // les deux sources, une par feu
    return [[center(e.t, -1), yc(e.t)], [center(e.t, 1), yc(e.t)]];
  }
  return [[(center(e.t, -1) + center(e.t, 1)) / 2, yc(e.t)]];
}

function flameAxis(u) {
  const lean = (CX - FXP) * u * u * 0.75;
  return FXP + lean + 40 * Math.sin(u * 5.2 + 1.2) * (1 - 0.55 * u)
       + (noise(u * 2.6, 9.1) - 0.5) * 70;
}

function flameHalfW(u) {
  return (58 - 52 * Math.pow(u, 0.8)) * (0.8 + 0.5 * noise(u * 3.5, 2.2));
}

// ------------------------------------------------------------- outils couleur

function paletteColor(pal, u) {
  const uu = Math.min(Math.max(u, 0), 1);
  const pos = uu * (pal.length - 1);
  const i = Math.min(Math.floor(pos), pal.length - 2);
  const f = pos - i;
  const a = pal[i], b = pal[i + 1];
  return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f];
}

function mix3(c1, c2, k) {
  return [c1[0] + (c2[0] - c1[0]) * k, c1[1] + (c2[1] - c1[1]) * k, c1[2] + (c2[2] - c1[2]) * k];
}

// un coup de pinceau : trois courts segments qui dérivent
function brushStroke(x, y, ang, col, alpha, wt, nz) {
  stroke(col[0], col[1], col[2], alpha);
  strokeWeight(wt);
  let px = x, py = y, a = ang;
  for (let s = 0; s < 3; s++) {
    const len = 8 + random(13);
    const qx = px + Math.cos(a) * len;
    const qy = py + Math.sin(a) * len;
    line(px, py, qx, qy);
    px = qx; py = qy;
    a += (noise(px * 0.003, py * 0.003, nz) - 0.5) * 0.9;
  }
}

// ------------------------------------------------------------- la nuit

function paintBackground() {
  noStroke();
  fill(9, 11, 23);
  rect(0, 0, W, H);

  // nappes tonales bruitées : la nuit respire
  const c1 = color(4, 5, 12), c2 = color(27, 33, 60);
  for (let i = 0; i < 1500; i++) {
    const x = random(-150, W + 150);
    const y = random(-150, H + 150);
    const cc = lerpColor(c1, c2, noise(x * 0.0013, y * 0.0013));
    fill(red(cc), green(cc), blue(cc), 4 + random(6));
    circle(x, y, 100 + random(280));
  }

  // voile violet du haut du ciel
  for (let i = 0; i < 260; i++) {
    fill(38, 28, 64, 4);
    circle(random(-200, W + 200), random(-200, H * 0.55), 200 + random(420));
  }

  // vignettage : les bords retombent dans l'ombre
  for (let i = 0; i < 520; i++) {
    const c = random();
    let x, y;
    if (c < 0.25)      { x = random(-250, 250);        y = random(-250, H + 250); }
    else if (c < 0.5)  { x = random(W - 250, W + 250); y = random(-250, H + 250); }
    else if (c < 0.75) { x = random(-250, W + 250);    y = random(-250, 320); }
    else               { x = random(-250, W + 250);    y = random(H - 320, H + 250); }
    fill(3, 4, 10, 6);
    circle(x, y, 260 + random(500));
  }

  // micro-fibres de la nuit
  for (let i = 0; i < 1800; i++) {
    const x = random(W), y = random(H);
    const a = random(TWO_PI);
    const len = 6 + random(26);
    if (random() < 0.5) stroke(60, 72, 110, 5);
    else                stroke(0, 0, 0, 7);
    strokeWeight(1);
    line(x, y, x + Math.cos(a) * len, y + Math.sin(a) * len);
  }
}

// ------------------------------------------------------------- l'air éclairé

function paintHalo() {
  noStroke();
  // aura de la flamme
  for (let i = 0; i < 430; i++) {
    const u = random();
    const y = 30 + u * 430;
    const x = flameAxis(Math.min(0.15 + u, 1.1)) + gauss() * (70 + 170 * u);
    if (random() < 0.6) fill(150, 105, 85, 3 + random(3));
    else                fill(95, 82, 145, 3 + random(3));
    circle(x, y, 70 + random(190));
  }
  // aures des étreintes et des sources
  for (let k = 0; k < EMBERS.length; k++) {
    const e = EMBERS[k];
    const pts = emberPoints(e);
    const strength = e.i / Math.sqrt(pts.length);
    for (let j = 0; j < pts.length; j++) {
      for (let i = 0; i < Math.floor(90 * strength); i++) {
        const ang = random(TWO_PI);
