/* La Mandorle — peinture fixe, p5.js 1.11, toile 1600 x 2000 */

const W = 1600, H = 2000;
const TIP_Y = 485, HEAD_Y = 930, HEAD_R = 445, BOT_Y = 2005, R_BOT = 175;

let warm, cool;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  buildForms();

  fond();
  sousCouche();
  coupsDePinceau();
  accents();
  enlacement();
  anneau();
  halo();
  mandorle();
  rayons();
