/* ——— construction des deux êtres (colonne + dôme + traîne) ——— */

function buildForms() {
  warm = makeForm(340, 430, 700, 636, 0);
  cool = makeForm(1260, 1170, 900, 964, 40);
}

function makeForm(x0, x1, x2, x3, nOff) {
  const N = 140;
  const spine = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const x = bezierPoint(x0, x1, x2, x3, t) + (noise(t * 3.3 + nOff) - 0.5) * 54;
    const y = bezierPoint(BOT_Y, 1600, 1200, TIP_Y, t);
    spine.push({ x, y, r: formRadius(y), ang: 0 });
  }
  for (let i = 0; i <= N; i++) {
    const a = spine[max(0, i - 1)], b = spine[min(N, i + 1)];
    spine[i].ang = atan2(b.y - a.y, b.x - a.x);
  }
  return { spine };
}

function formRadius(y) {
  if (y <= TIP_Y) return 0;
  if (y <= HEAD_Y) return sqrt(max(0, HEAD_R * HEAD_R - (y - HEAD_Y) * (y - HEAD_Y)));
  const v = (BOT_Y - y) / (BOT_Y - HEAD_Y);
  return R_BOT + (HEAD_R - R_BOT) * pow(sin(v * HALF_PI), 1.2);
}

function spineIndexAtY(f, y) {
  const s = f.spine;
  let lo = 0, hi = s.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (s[mid].y > y) lo = mid; else hi = mid;
  }
  return lo;
}

function insideForm(f, x, y, m) {
  const s = f.spine;
  const i = spineIndexAtY(f, y);
  for (let k = max(0, i - 6); k <= min(s.length - 1, i + 6); k++) {
    const dx = x - s[k].x, dy = y - s[k].y, rr = s[k].r + m;
    if (dx * dx + dy * dy < rr * rr) return true;
  }
  return false;
}

function sampleY(f, y) {
  const s = f.spine, i = spineIndexAtY(f, y);
  const j = min(i + 1, s.length - 1);
  return abs(s[i].y - y) < abs(s[j].y - y) ? s[i] : s[j];
}

/* ——— outils ——— */

function blob(x, y, r, c, a) {
  if (r < 2 || a <= 0) return;
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')');
  g.addColorStop(0.55, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + (a * 0.55) + ')');
  g.addColorStop(1, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0)');
