  for (let y = 0; y < H; y += 4) {
    let c = y < 1080 ? lerpColor(cTop, cMid, y / 1080)
                     : lerpColor(cMid, cBot, (y - 1080) / 920);
    fill(c);
    rect(0, y, W, 4.6);
  }

  // ---- poussière d'étoiles ----
  for (let i = 0; i < 240; i++) {
    let x = random(W), y = random(H * 0.72);
    let r = random(0.5, 2.1);
    let fade = 1 - y / (H * 0.8);
    fill(255, 243, 228, random(28, 150) * fade);
    circle(x, y, r * 2);
    if (random() < 0.07) {
      fill(255, 238, 214, 26 * fade);
      circle(x, y, r * 7);
    }
  }

  // ---- auras ----
  glow(800, 600, 640, 640, color(255, 206, 158), 46, 3.4);
  glow(560, 1330, 500, 1060, color(196, 48, 76), 40, 2.6);
  glow(1040, 1330, 500, 1060, color(220, 132, 44), 40, 2.6);

  // ---- le cercle qui veille ----
  drawEnso(800, 640, 470);

  // ---- les deux flammes ----
  drawFlame(-1, rose);
  drawFlame(1, gold);

  // ---- la lumière descend dans l'intervalle ----
  glow(800, 1250, 170, 950, color(255, 210, 175), 40, 1.5);

  // ---- ce qui s'allume entre elles ----
  weaveTop();
  weaveThreads();
  coreLight();
  risingSparks();
  fallingPetals();

  // ---- le sol ----
  ground();

  // ---- finitions ----
  vignette();
  grain();
}

function glow(x, y, rx, ry, c, layers, a0) {
  blendMode(ADD);
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let f = i / layers;
    fill(c, a0 * Math.pow(1 - f, 1.8));
    ellipse(x, y, rx * f, ry * f);
  }
}

function flamePoint(side, t) {
  let p0x = 800 + side * 310, p0y = 2012;
  let p1x = 800 + side * 402, p1y = 1262;
  let p2x = 800 + side * 30,  p2y = 566;
  let mt = 1 - t;
  let x = mt * mt * p0x + 2 * mt * t * p1x + t * t * p2x;
  let y = mt * mt * p0y + 2 * mt * t * p1y + t * t * p2y;
  x += (noise(t * 3.1 + side * 11.3 + 5) - 0.5) * 26;
  y += (noise(t * 2.7 + side * 77.7) - 0.5) * 16;
  let w = lerp(300, 46, Math.pow(t, 0.78)) + (noise(t * 4.4 + side * 31.7) - 0.5) * 44;
  return { x: x, y: y, w: w };
}

function drawFlame(side, pal) {
  // corps : petits coups de pinceau horizontaux
  blendMode(BLEND);
  noStroke();
  for (let t = 0; t < 0.999; t += 0.0042) {
    let p = flamePoint(side, t);
    let q = flamePoint(side, Math.min(1, t + 0.004));
    let ang = Math.atan2(q.y - p.y, q.x - p.x);
    for (let k = 0; k < 6; k++) {
      let u = k / 5;
      let off = (u - 0.5) * p.w * (0.88 + random(-0.12, 0.12));
      let x = p.x - side * off;
      let ci = Math.floor(map(u, 0, 1, 0, 4.4));
      if (random() < 0.28) ci += random() < 0.5 ? -1 : 1;
      if (random() < 0.045) ci = 4;
      ci = constrain(ci, 0, 4);
      push();
      translate(x + random(-5, 5), p.y + random(-3.5, 3.5));
      rotate(ang + HALF_PI + random(-0.14, 0.14));
      fill(pal[ci], random(36, 72));
      ellipse(0, 0, p.w * random(0.16, 0.3) + 7, random(5.5, 10.5));
      pop();
    }
  }
  // liseré intérieur : la lumière de l'autre
  blendMode(ADD);
  for (let t = 0.015; t < 0.999; t += 0.008) {
    let p = flamePoint(side, t);
    let q = flamePoint(side, Math.min(1, t + 0.004));
    let ang = Math.atan2(q.y - p.y, q.x - p.x);
    let s = Math.pow(t, 1.1);
    let u = 0.8 + random(-0.1, 0.14);
    let x = p.x - side * (u - 0.5) * p.w;
    push();
    translate(x + random(-4, 4), p.y + random(-3, 3));
    rotate(ang + HALF_PI + random(-0.16, 0.16));
    fill(pal[4], random(7, 22) * (0.3 + 0.7 * s));
    ellipse(0, 0, p.w * random(0.12, 0.24) + 4, random(4, 8));
    pop();
  }
  // lèches verticales : la flamme monte
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < 90; i++) {
    let t0 = random(0.05, 0.92);
    let t1 = Math.min(1, t0 + random(0.04, 0.1));
    let u = random(-0.42, 0.46);
    let p0 = flamePoint(side, t0);
    let p1 = flamePoint(side, t1);
    let x0 = p0.x - side * u * p0.w;
    let x1 = p1.x - side * u * p1.w;
    stroke(lerpColor(pal[2], pal[4], random()), random(5, 16));
    strokeWeight(random(1.2, 3.2));
    beginShape();
    vertex(x0, p0.y);
    quadraticVertex((x0 + x1) / 2 - side * random(4, 18), (p0.y + p1.y) / 2, x1, p1.y);
    endShape();
  }
  // la pointe s'embrase vers l'autre
  noStroke();
  let tip = flamePoint(side, 1);
  for (let i = 0; i < 40; i++) {
    fill(lerpColor(pal[3], pal[4], random()), random(18, 60));
    let a = random(TWO_PI);
    let d = random(0, 55);
    circle(tip.x + Math.cos(a) * d * 0.5, tip.y + Math.sin(a) * d, random(2, 9));
  }
  // souffles depuis la pointe
  noFill();
  for (let i = 0; i < 7; i++) {
    let p = flamePoint(side, random(0.88, 1));
    let dx = -side * random(10, 60);
    let dy = -random(40, 140);
    stroke(pal[4], random(12, 30));
    strokeWeight(random(1, 2.4));
    beginShape();
    vertex(p.x, p.y);
    quadraticVertex(p.x + dx * 0.4 + random(-15, 15), p.y + dy * 0.5, p.x + dx, p.y + dy);
    endShape();
  }
}

function drawEnso(cx, cy, R) {
  blendMode(BLEND);
  noFill();
  strokeCap(ROUND);
  let segs = 300;
  for (let pass = 0; pass < 2; pass++) {
    for (let i = 0; i < segs; i++) {
      let t = i / segs, t2 = (i + 1) / segs;
      if (t > 0.85 && t < 0.965) continue; // le souffle inachevé
      let a1 = t * TWO_PI - HALF_PI, a2 = t2 * TWO_PI - HALF_PI;
      let wob = function(a) {
        return (noise(Math.cos(a) * 1.8 + pass * 9.7, Math.sin(a) * 1.8 + 3.3) - 0.5) * 64;
      };
      let off = pass === 0 ? 0 : random(-12, 12);
      let x1 = cx + Math.cos(a1) * (R + wob(a1) + off);
      let y1 = cy + Math.sin(a1) * (R + wob(a1) + off);
      let x2 = cx + Math.cos(a2) * (R + wob(a2) + off);
      let y2 = cy + Math.sin(a2) * (R + wob(a2) + off);
      if (pass === 0) {
        stroke(244, 226, 196, lerp(56, 20, Math.pow(t, 0.75)) * random(0.65, 1.35));
        strokeWeight(lerp(30, 5, Math.pow(t, 0.8)) * random(0.75, 1.25));
      } else {
        stroke(255, 236, 206, 22 * random(0.5, 1.4));
        strokeWeight(random(2, 8));
      }
      line(x1, y1, x2, y2);
    }
  }
}

function weaveTop() {
  blendMode(ADD);
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < 70; i++) {
    let fromLeft = random() < 0.5;
    let x0 = fromLeft ? random(640, 762) : random(838, 960);
    let x1 = fromLeft ? random(845, 965) : random(635, 755);
    let y0 = random(420, 800);
    let y1 = y0 + random(-140, 140);
    let mx = (x0 + x1) / 2 + random(-80, 80);
    let my = (y0 + y1) / 2 + random(-100, 100);
    let c = fromLeft ? lerpColor(gold[2], gold[4], random())
                     : lerpColor(rose[2], rose[4], random());
    stroke(c, random(16, 52));
    strokeWeight(random(2, 8));
    beginShape();
    vertex(x0, y0);
    quadraticVertex(mx, my, x1, y1);
    endShape();
  }
}

function weaveThreads() {
  blendMode(ADD);
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < 30; i++) {
    let y = random(700, 1800);
    let t = constrain((2012 - y) / 1446, 0, 1);
    let L = flamePoint(-1, t), R = flamePoint(1, t);
    let inL = L.x + L.w * 0.32, inR = R.x - R.w * 0.32;
    if (inR - inL < 30) continue;
    let fromLeft = random() < 0.5;
    let x0 = fromLeft ? inL : inR;
    let x1 = fromLeft ? inR : inL;
    let y0 = y + random(-40, 40);
    let y1 = y + random(-70, 70);
    let c = fromLeft ? lerpColor(gold[1], gold[3], random())
                     : lerpColor(rose[1], rose[3], random());
    stroke(c, random(8, 24));
    strokeWeight(random(1.2, 3.2));
    beginShape();
    vertex(x0, y0);
    quadraticVertex((x0 + x1) / 2, (y0 + y1) / 2 + random(-150, 150), x1, y1);
    endShape();
  }
}

function coreLight() {
  blendMode(ADD);
  noStroke();
  // l'amande de lumière partagée
  for (let i = 0; i < 30; i++) {
    let f = i / 30;
    fill(255, 232, 186, 2 + 7 * f);
    ellipse(800, 588, lerp(84, 10, f), lerp(170, 16, f));
  }
  fill(255, 252, 238, 70);
  ellipse(800, 588, 16, 40);
  fill(255, 255, 250, 110);
  ellipse(800, 588, 7, 20);
  // rayons discrets
  for (let i = 0; i < 22; i++) {
    let a = random(TWO_PI);
    let r0 = random(24, 60), r1 = r0 + random(30, 120);
    stroke(255, 234, 196, random(10, 34));
    strokeWeight(random(1.5, 3.5));
    line(800 + Math.cos(a) * r0, 588 + Math.sin(a) * r0 * 0.7,
         800 + Math.cos(a) * r1, 588 + Math.sin(a) * r1 * 0.7);
  }
}

function risingSparks() {
  blendMode(ADD);
  noStroke();
  // halos flous
  for (let i = 0; i < 14; i++) {
    let h = random(0, 520);
    let y = 590 - h;
    let sp = 30 + (h / 520) * 330;
    let x = 800 + random(-1, 1) * sp * random(0.4, 1);
    fill(255, 214, 170, random(6, 14));
    circle(x, y, random(18, 44));
  }
  // étincelles
  for (let i = 0; i < 260; i++) {
    let u = Math.pow(random(), 1.5);
    let y = 590 - u * 560;
    let h = 590 - y;
    let sp = 14 + Math.pow(h / 560, 0.8) * 430;
    let x = 800 + random(-1, 1) * sp;
    x += (noise(x * 0.004, y * 0.006) - 0.5) * 130;
    let warm = random();
    let c = warm < 0.4 ? color(255, 170, 150)
           : warm < 0.8 ? color(255, 214, 150)
           : color(255, 246, 226);
    let a = random(40, 170) * (1 - u * 0.55);
    if (random() < 0.3) {
      stroke(c, a * 0.8);
      strokeWeight(random(1, 2.6));
      line(x, y, x + random(-4, 4), y + random(6, 16));
      noStroke();
    } else {
      fill(c, a);
      circle(x, y, random(1.5, 4.5));
    }
  }
  // pétales emportés vers le haut
  for (let i = 0; i < 16; i++) {
    let y = 590 - random(0, 300);
    let x = 800 + random(-1, 1) * (16 + (590 - y) * 0.5);
    let c = random() < 0.5 ? lerpColor(rose[3], rose[4], random())
                           : lerpColor(gold[3], gold[4], random());
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    fill(c, random(24, 55));
    ellipse(0, 0, random(9, 16), random(4.5, 8));
    pop();
  }
}

function fallingPetals() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 30; i++) {
    let y = random(680, 1880);
    let t = constrain((2012 - y) / 1446, 0, 1);
    let L = flamePoint(-1, t), R = flamePoint(1, t);
    let inL = L.x + L.w * 0.5, inR = R.x - R.w * 0.5;
    let gap = inR - inL;
    if (gap < 40) continue;
    let x = inL + gap * random(0.15, 0.85);
    let m = random();
    let c = m < 0.35 ? lerpColor(rose[3], gold[3], 0.5)
         : m < 0.7 ? lerpColor(rose[3], rose[4], random())
         : lerpColor(gold[3], gold[4], random());
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(c, random(16, 40));
    ellipse(0, 0, random(8, 15), random(4, 7.5));
    pop();
  }
}

function ground() {
  // flaques de lumière au pied de chacune
  glow(490, 1994, 560, 64, color(214, 62, 84), 26, 4.5);
  glow(1110, 1994, 560, 64, color(232, 148, 58), 26, 4.5);
  // braises éparses
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 110; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let x = 800 + side * random(50, 330);
    let y = random(1938, 1998);
    let c = side < 0 ? color(255, 176, 156) : color(255, 224, 156);
    fill(c, random(36, 130));
    circle(x, y, random(1.8, 4.6));
  }
  // la racine secrète : elles se joignent sous la terre
  noFill();
  strokeCap(ROUND);
  stroke(255, 186, 158, 20);
  strokeWeight(3.2);
  beginShape();
  vertex(470, 1996);
  quadraticVertex(800, 1972, 1130, 1996);
  endShape();
  for (let i = 0; i < 8; i++) {
    let tt = random(0.12, 0.88);
    let mt = 1 - tt;
    let px = mt * mt * 470 + 2 * mt * tt * 800 + tt * tt * 1130;
    let py = mt * mt * 1996 + 2 * mt * tt * 1972 + tt * tt * 1996;
    stroke(255, 186, 158, random(10, 20));
    strokeWeight(random(1.4, 2.8));
    line(px, py, px + random(-26, 26), py + random(5, 15));
  }
}

function vignette() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 90; i++) {
    let a = map(i, 0, 90, 58, 0);
    fill(8, 4, 14, a * 0.55); rect(0, i * 2, W, 2.3);
    fill(8, 4, 14, a * 0.8);  rect(0, H - i * 2 - 2.3, W, 2.4);
    fill(8, 4, 14, a * 0.65); rect(i * 2, 0, 2.3, H);
    fill(8, 4, 14, a * 0.65); rect(W - i * 2 - 2.3, 0, 2.4, H);
  }
}

function grain() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 22000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.5) fill(255, 246, 232, random(2, 6));
    else fill(6, 3, 10, random(2, 7));
    let s = random(1, 2.3);
    rect(x, y, s, s);
  }
}

// « Deux flammes, une lumière » — peinture fixe, p5.js 1.11

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  strokeCap(ROUND);
  paint();
}

function draw() {}

/* ---------- composition ---------- */
const W = 1600, H = 2000;
const HEADS = [
  { x: 690, y: 545, a: 85, b: 108 },
  { x: 910, y: 545, a: 85, b: 108 }
];
const BODY_TOP = 610, BODY_BOT = 1860;

const FIG_RAMP = [
  [0.00, 24, 7, 11],
  [0.22, 64, 12, 22],
  [0.45, 124, 26, 34],
  [0.65, 178, 52, 40],
  [0.82, 224, 110, 58],
  [1.00, 252, 232, 178]
];
const BG_RAMP = [
  [0.00, 58, 26, 24],
  [0.35, 42, 20, 21],
  [0.65, 31, 16, 20],
  [1.00, 17, 13, 23]
];

function paint() {
  background(21, 12, 14);
  ambience();
  floor();
  ring();
  figures();
  figureStrokes();
  washes();
  rimLight();
  channelFire();
  spark();
  embers();
  dust();
  vignette();
  grain();
}

/* ---------- géométrie ---------- */
function gapHalf(y) {
  const u = constrain((y - BODY_TOP) / (BODY_BOT - BODY_TOP), 0, 1);
  return 85 - 234.35 * u + 319.4 * u * u;
}

const OUTER = [[610, 600], [850, 505], [1150, 470], [1450, 445], [1700, 428], [1860, 425]];

function outerLeft(y) {
  const yy = constrain(y, 610, 1860);
  for (let i = 0; i < OUTER.length - 1; i++) {
    if (yy <= OUTER[i + 1][0]) {
      let t = (yy - OUTER[i][0]) / (OUTER[i + 1][0] - OUTER[i][0]);
      t = t * t * (3 - 2 * t);
      return lerp(OUTER[i][1], OUTER[i + 1][1], t);
    }
  }
  return 425;
}

function inHead(k, x, y) {
  const h = HEADS[k];
  const dx = (x - h.x) / h.a, dy = (y - h.y) / h.b;
  return dx * dx + dy * dy < 1;
}

function insideFigure(x, y) {
  for (let k = 0; k < 2; k++) if (inHead(k, x, y)) return true;
  if (y >= BODY_TOP && y <= BODY_BOT) {
    const g = gapHalf(y);
    const oL = outerLeft(y);
    if (x >= oL && x <= 800 - g) return true;
    if (x >= 800 + g && x <= 1600 - oL) return true;
  }
  return false;
}

function bodyOutline(mirror) {
  const pts = [];
  const N = 64;
  for (let i = 0; i <= N; i++) {
    const y = lerp(BODY_TOP, BODY_BOT, i / N);
    const x = 800 - gapHalf(y);
    pts.push([mirror ? 1600 - x : x, y]);
  }
  for (let i = N; i >= 0; i--) {
    const y = lerp(BODY_TOP, BODY_BOT, i / N);
    const x = outerLeft(y);
    pts.push([mirror ? 1600 - x : x, y]);
  }
  return pts;
}

/* ---------- lumière et couleurs ---------- */
function lightAt(x, y) {
  const w1 = max(0, 1 - dist(x, y, 800, 980) / 430);
  const w2 = max(0, 1 - dist(x, y, 800, 545) / 230);
  let w = max(w1, 0.85 * w2);
  w += 0.12 * (noise(x * 0.002, y * 0.002) - 0.5);
  return constrain(w, 0, 1);
}

function ramp(stops, t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    if (t <= stops[i + 1][0]) {
      const a = stops[i], b = stops[i + 1];
      const f = (t - a[0]) / (b[0] - a[0]);
      return [lerp(a[1], b[1], f), lerp(a[2], b[2], f), lerp(a[3], b[3], f)];
    }
  }
  const l = stops[stops.length - 1];
  return [l[1], l[2], l[3]];
}

function flowVec(x, y) {
  let vx = (noise(x * 0.0015, y * 0.0015, 4.7) - 0.5) * 1.4;
  let vy = -1;
  for (let k = 0; k < 2; k++) {
    const h = HEADS[k];
    const dx = x - h.x, dy = y - h.y;
    const d = sqrt(dx * dx + dy * dy);
    const rr = 190;
    if (d < rr && d > 0.01) {
      const f = ((rr - d) / rr) * 1.7;
      vx += (dx / d) * f;
      vy += (dy / d) * f;
    }
  }
  if (y > 620 && y < 1150) vx += (800 - x) * 0.0011;
  if (y < 400) vx += (x - 800) * 0.002;
  const m = sqrt(vx * vx + vy * vy);
  return [vx / m, vy / m];
}

/* ---------- couches ---------- */
function ambience() {
  noStroke();
  for (let i = 0; i < 55; i++) {
    const f = i / 54;
    const r = lerp(720, 70, f);
    const c = ramp(BG_RAMP, lerp(0.42, 0, f));
    fill(c[0], c[1], c[2], 7);
    ellipse(800, 980, r * 2, r * 2);
  }
  for (let i = 0; i < 26; i++) {
    const bx = random(0, W), by = random(0, H);
    const br = random(140, 430);
    fill(14, 8, 12, random(4, 10));
    ellipse(bx, by, br * 2, br * 2 * random(0.6, 1));
  }
  for (let i = 0; i < 12000; i++) {
    const x = random(W), y = random(H);
    const t = dist(x, y, 800, 1000) / 1150 + (noise(x * 0.0016, y * 0.0016) - 0.5) * 0.35;
    const c = ramp(BG_RAMP, t);
    const a = noise(x * 0.0011, y * 0.0011) * PI;
    const L = random(14, 46);
    stroke(c[0] + random(-7, 7), c[1] + random(-7, 7), c[2] + random(-7, 7), random(10, 24));
    strokeWeight(random(2, 6));
    line(x, y, x + cos(a) * L, y + sin(a) * L);
  }
  noStroke();
  for (let i = 0; i < 20; i++) {
    const r = lerp(330, 40, i / 19);
    fill(96, 42, 52, 4);
    ellipse(800, 560, r * 2, r * 2);
  }
}

function floor() {
  noStroke();
  fill(14, 8, 10, 235);
  rect(0, BODY_BOT, W, H - BODY_BOT);
  for (let i = 0; i < 24; i++) {
    const f = i / 23;
    const yy = lerp(BODY_BOT + 6, H - 12, f);
    fill(206, 108, 46, 4);
    ellipse(800, yy, lerp(250, 70, f) * 2, 26);
  }
  for (let i = 0; i < 430; i++) {
    const y = random(BODY_BOT + 3, H - 4);
    const x = random(0, W);
    const L = random(50, 300) * (random() < 0.5 ? -1 : 1);
    if (random() < 0.3 && abs(x - 800) < 340) {
      stroke(190 + random(60), 90 + random(60), 40, random(5, 14));
    } else {
      stroke(10 + random(10), 7 + random(6), 9 + random(8), random(12, 30));
    }
    strokeWeight(random(1, 3.4));
    line(x, y, x + L, y + random(-2, 2));
  }
}

function angDist(a, b) {
  let d = (a - b) % TWO_PI;
  if (d < 0) d += TWO_PI;
  if (d > PI) d = TWO_PI - d;
  return d;
}

function ringJit(t) {
  return (noise(cos(t) * 1.3 + 9.7, sin(t) * 1.3 + 3.9) - 0.5) * 24;
}

function ring() {
  const cx = 800, cy = 1000, R = 600;
  for (let pass = 0; pass < 3; pass++) {
    const baseW = [20, 7, 3.4][pass];
    const baseA = [7, 24, 60][pass];
    noFill();
    const steps = 850;
    for (let i = 0; i < steps; i++) {
      const t0 = (i / steps) * TWO_PI;
      const t1 = ((i + 1) / steps) * TWO_PI;
      const dd = angDist(t0, 4.712);
      if (dd < 0.5) continue; // l'ouverture, en haut
      const fade = constrain((dd - 0.5) / 0.45, 0, 1);
      if (random() < 0.03 + 0.3 * (1 - fade)) continue; // pinceau rompu
      const j0 = ringJit(t0), j1 = ringJit(t1);
      const x0 = cx + cos(t0) * (R + j0), y0 = cy + sin(t0) * (R + j0);
      const x1 = cx + cos(t1) * (R + j1), y1 = cy + sin(t1) * (R + j1);
      const nz = noise(cos(t0) * 2.2 + 7, sin(t0) * 2.2 + 2);
      let cr, cg, cb;
      if (pass === 2) {
        cr = lerp(118, 242, nz); cg = lerp(80, 208, nz); cb = lerp(38, 132, nz);
      } else {
        cr = lerp(92, 152, nz); cg = lerp(62, 106, nz); cb = lerp(30, 54, nz);
      }
      stroke(cr, cg, cb, baseA * (0.5 + 0.5 * nz) * lerp(0.25, 1, fade));
      strokeWeight(baseW * (0.5 + nz));
      line(x0, y0, x1, y1);
    }
  }
  for (let i = 0; i < 720; i++) {
    const t = (i / 720) * TWO_PI;
    if (angDist(t, 4.712) < 0.85) continue;
    if (noise(cos(t) * 2.6 + 1.2, sin(t) * 2.6 + 8.4) < 0.52) continue;
    const r = 656 + (noise(cos(t) * 1.1 + 4, sin(t) * 1.1 + 6) - 0.5) * 30;
    stroke(150, 104, 56, random(8, 20));
    strokeWeight(random(1, 2.4));
    point(cx + cos(t) * r, cy + sin(t) * r);
  }
}

function figures() {
  for (let m = 0; m < 2; m++) {
    const pts = bodyOutline(m === 1);
    noFill();
    stroke(15, 7, 10, 70);
    strokeWeight(26);
    beginShape();
    for (let i = 0; i < pts.length; i++) vertex(pts[i][0], pts[i][1]);
    endShape(CLOSE);
  }
  noStroke();
  fill(30, 9, 13);
  for (let m = 0; m < 2; m++) {
    const pts = bodyOutline(m === 1);
    beginShape();
    for (let i = 0; i < pts.length; i++) vertex(pts[i][0], pts[i][1]);
    endShape(CLOSE);
    const h = HEADS[m];
    ellipse(h.x, h.y, h.a * 2, h.b * 2);
  }
}

function figureStrokes() {
  let drawn = 0, tries = 0;
  while (drawn < 15200 && tries < 120000) {
    tries++;
    const side = random() < 0.5 ? 0 : 1;
    let x, y;
    const pick = random();
    if (pick < 0.3) { // près du bord intérieur, côté lumière
      y = random(BODY_TOP, BODY_BOT);
      const g = gapHalf(y);
      const off = random(2, 95);
      x = side === 0 ? 800 - g - off : 800 + g + off;
    } else if (pick < 0.45) { // têtes
      const h = HEADS[side];
      const th = random(TWO_PI);
      const rr = sqrt(random());
      x = h.x + cos(th) * rr * (h.a - 5);
      y = h.y + sin(th) * rr * (h.b - 5);
    } else {
      x = side === 0 ? random(415, 800) : random(800, 1185);
      y = random(430, BODY_BOT + 6);
    }
    if (!insideFigure(x, y)) continue;
    drawn++;
    const w = lightAt(x, y);
    const c = ramp(FIG_RAMP, w);
    const r = random();
    if (r < 0.08) { c[0] += 26; c[1] += 18; c[2] -= 6; }
    else if (r < 0.15) { c[0] += 12; c[2] += 16; }
    let a;
    let nearHead = -1;
    for (let k = 0; k < 2; k++) {
      const h = HEADS[k];
      if (abs(x - h.x) < h.a + 14 && abs(y - h.y) < h.b + 14) nearHead = k;
    }
    if (nearHead >= 0) {
      const h = HEADS[nearHead];
      a = atan2((y - h.y) / h.b, (x - h.x) / h.a) + HALF_PI;
    } else {
      a = HALF_PI + (noise(x * 0.0018, y * 0.0018) - 0.5) * 1.1;
      if (y < 780) a += (side === 0 ? 1 : -1) * map(y, 430, 780, 0.45, 0);
    }
    let L = random(14, 44), al = random(16, 42), sw = random(2, 6.5);
    if (random() < 0.05) { L = random(60, 110); al = 10; sw = 8; }
    stroke(
      constrain(c[0] + random(-14, 14), 0, 255),
      constrain(c[1] + random(-14, 14), 0, 255),
      constrain(c[2] + random(-14, 14), 0, 255),
      al
    );
    strokeWeight(sw);
    line(x, y, x + cos(a) * L, y + sin(a) * L);
  }
}

function washes() {
  noStroke();
  for (let i = 0; i < 7; i++) {
    fill(140, 36, 38, 4);
    ellipse(random(520, 1080), random(560, 1760), random(220, 520), random(320, 680));
  }
}

function rimLight() {
  for (let side = 0; side < 2; side++) {
    for (let y = BODY_TOP + 10; y < BODY_BOT - 6; y += 3.2) {
      const g = gapHalf(y);
      const x = side === 0 ? 800 - g - random(0, 10) : 800 + g + random(0, 10);
      const w = lightAt(x, y);
      const c = ramp(FIG_RAMP, min(1, w + 0.18));
      stroke(c[0] + random(-12, 12), c[1] + random(-10, 10), c[2] + random(-10, 10),
        random(28, 80) * (0.35 + 0.65 * w));
      strokeWeight(random(1.6, 4.4));
      const L = random(10, 26);
      line(x, y, x, y + L);
    }
  }
  // visages tournés l'un vers l'autre
  for (let side = 0; side < 2; side++) {
    const h = HEADS[side];
    const th0 = side === 0 ? 0 : PI;
    for (let i = 0; i < 80; i++) {
      const th = th0 + random(-1.15, 1.15);
      const x = h.x + cos(th) * (h.a - random(3, 12));
      const y = h.y + sin(th) * (h.b - random(4, 16));
      const c = ramp(FIG_RAMP, random(0.72, 1));
      stroke(c[0], c[1], c[2], random(35, 85));
      strokeWeight(random(1.5, 4));
      const ta = th + HALF_PI;
      const L = random(6, 16);
      line(x, y, x + cos(ta) * L, y + sin(ta) * L);
    }
  }
  // deux cœurs incandescents
  noStroke();
  for (const hx of [726, 874]) {
    for (let i = 0; i < 36; i++) {
      const th = random(TWO_PI);
      const rr = random(0, 44);
      const c = ramp(FIG_RAMP, random(0.72, 1));
      fill(c[0], c[1], c[2], random(12, 36));
      ellipse(hx + cos(th) * rr * 0.8, 985 + sin(th) * rr, random(3, 10), random(3, 10));
    }
  }
}

function channelFire() {
  noStroke();
  for (let i = 0; i < 46; i++) {
    const y = lerp(660, 1500, i / 45);
    const g = gapHalf(y);
    const inten = pow(max(0, 1 - abs(y - 980) / 520), 1.4);
    const c = ramp(FIG_RAMP, 0.55 + 0.45 * inten);
    fill(c[0], c[1], c[2], 5 + 9 * inten);
    ellipse(800, y, g * 1.6, 130);
  }
  for (let i = 0; i < 90; i++) {
    const y = random(660, 1440);
    const x = 800 + random(-1, 1) * random(0, gapHalf(y) * 0.55);
    const c = ramp(FIG_RAMP, random(0.62, 1));
    stroke(c[0], c[1], c[2], random(5, 13));
    strokeWeight(random(1, 2.6));
    line(x, y, x + random(-7, 7), y - random(80, 320));
  }
  noStroke();
  for (let i = 0; i < 60; i++) {
    const f = i / 59;
    const r = lerp(300, 4, pow(f, 0.8));
    const c = ramp(FIG_RAMP, pow(f, 0.75));
    fill(c[0], c[1], c[2], 6 + 22 * pow(f, 2));
    ellipse(800, 980, r * 1.5, r * 2.05);
  }
  noFill();
  for (let i = 0; i < 170; i++) {
    const th = random(TWO_PI);
    const up = sin(th) < 0;
    const r0 = random(8, 70);
    const L = random(24, 125) * (up ? 1.35 : 0.7);
    const x0 = 800 + cos(th) * r0;
    const y0 = 980 + sin(th) * r0 * 0.7;
    const x1 = x0 + cos(th) * L;
    const y1 = y0 + sin(th) * L;
    const px = cos(th + HALF_PI), py = sin(th + HALF_PI);
    const b = L * random(-0.35, 0.35);
    const c = ramp(FIG_RAMP, random(0.8, 1));
    stroke(c[0], c[1], c[2], random(20, 55));
    strokeWeight(random(2, 6.5));
    curve(x0 + px * b - cos(th) * 8, y0 + py * b - sin(th) * 8,
      x0, y0, x1, y1,
      x1 + px * b + cos(th) * 8, y1 + py * b + sin(th) * 8);
  }
}

function spark() {
  noStroke();
  for (let i = 0; i < 16; i++) {
    const f = i / 15;
    const r = lerp(52, 3, f);
    const c = ramp(FIG_RAMP, pow(f, 0.8));
    fill(c[0], c[1], c[2], 8 + 30 * pow(f, 2));
    ellipse(800, 545, r * 2, r * 2);
  }
  for (let i = 0; i < 30; i++) {
    const th = random(TWO_PI);
    const L = random(5, 22);
    const c = ramp(FIG_RAMP, random(0.85, 1));
    stroke(c[0], c[1], c[2], random(30, 70));
    strokeWeight(random(1, 2.6));
    line(800, 545, 800 + cos(th) * L, 545 + sin(th) * L);
  }
  // le feu monte vers l'étincelle
  let px = 800, py = 935;
  stroke(246, 214, 140, 9);
  strokeWeight(1.3);
  for (let y = 913; y > 575; y -= 22) {
    const x = 800 + (noise(y * 0.012) - 0.5) * 30;
    line(px, py, x, y);
    px = x; py = y;
  }
}

function embers() {
  const dots = [];
  for (let i = 0; i < 95; i++) {
    const y0 = random(880, 1300);
    const g = gapHalf(y0);
    let x = 800 + random(-1, 1) * random(0, g * 0.7);
    let y = y0;
    const pts = [];
    const maxSteps = floor(random(70, 260));
    for (let s = 0; s < maxSteps && y > 36; s++) {
      pts.push([x, y]);
      const v = flowVec(x, y);
      x += v[0] * 6.5 + random(-1.1, 1.1);
      y += v[1] * 6.5;
    }
    noFill();
    for (let s = 0; s < pts.length - 1; s++) {
      const prog = s / pts.length;
      const c = ramp(FIG_RAMP, lerp(0.95, 0.45, prog));
      stroke(c[0], c[1], c[2], lerp(38, 3, pow(prog, 0.65)));
      strokeWeight(1.2 + 1.1 * (1 - prog));
      line(pts[s][0], pts[s][1], pts[s + 1][0], pts[s + 1][1]);
    }
    for (let s = 0; s < pts.length; s += 3) {
      if (random() < 0.42) dots.push([pts[s][0], pts[s][1], s / pts.length]);
    }
  }
  noStroke();
  for (let i = 0; i < dots.length; i++) {
    const d = dots[i];
    const sz = random(1.6, 4.6) * (1 - d[2] * 0.55);
    const c = ramp(FIG_RAMP, random(0.72, 1));
    fill(c[0], c[1], c[2], random(22, 85) * (1 - d[2] * 0.7));
    ellipse(d[0], d[1], sz, sz);
  }
}

function dust() {
  noStroke();
  for (let i = 0; i < 170; i++) {
    const x = random(70, W - 70);
    const y = random(50, 1720);
    if (random() < 0.6) fill(214, 168, 96, random(8, 26));
    else fill(214, 118, 128, random(6, 18));
    ellipse(x, y, random(1, 3), random(1, 3));
  }
}

function vignette() {
  noStroke();
  const corners = [[-60, -60], [W + 60, -60], [-60, H + 60], [W + 60, H + 60]];
  for (let k = 0; k < 4; k++) {
    for (let i = 0; i < 24; i++) {
      const r = lerp(1080, 130, i / 23);
      fill(11, 6, 11, 3.5);
      ellipse(corners[k][0], corners[k][1], r * 2, r * 2);
    }
  }
}

function grain() {
  noStroke();
  for (let i = 0; i < 15000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) fill(255, 244, 226, 3);
    else fill(6, 4, 5, 4);
    rect(x, y, 1.4, 1.4);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // fond : dégradé vertical profond
  const cTop = color(12, 14, 40);
  const cBot = color(48, 12, 28);
  noStroke();
  for (let y = 0; y < height; y += 4) {
    fill(lerpColor(cTop, cBot, y / height));
    rect(0, y, width, 4);
  }

  // matière picturale : longs coups de pinceau
  const palette = [
    color(38, 46, 105),
    color(88, 30, 78),
    color(120, 44, 58),
    color(24, 28, 66),
    color(150, 70, 58),
    color(60, 30, 90)
  ];
  for (let i = 0; i < 650; i++) {
    const x = random(width);
    const y = random(height);
    const a = noise(x * 0.0018, y * 0.0018) * TWO_PI;
    const len = random(20, 95);
    const c = random(palette);
    stroke(red(c), green(c), blue(c), random(6, 20));
    strokeWeight(random(1, 3.2));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }

  // poussière lumineuse dans le haut
  noStroke();
  for (let i = 0; i < 170; i++) {
    fill(255, random(215, 255), random(190, 240), random(18, 85));
    const s = random(1, 3.2);
    ellipse(random(width), random(height * 0.72), s, s);
  }

  // halos : deux mondes qui se touchent
  glow(600, 850, 640, color(205, 42, 72), 85);
  glow(1000, 850, 640, color(86, 62, 205), 85);
  glow(800, 520, 520, color(255, 150, 92), 34);

  // cercles à peine visibles
  noFill();
  strokeWeight(2.5);
  stroke(255, 205, 175, 9);
  ellipse(612, 852, 900, 900);
  stroke(190, 185, 255, 9);
  ellipse(988, 852, 900, 900);

  // ombre douce au sol
  noStroke();
  fill(8, 5, 14, 150);
  ellipse(800, 2030, 2000, 300);

  // les deux courants
  ribbon(300, 2090, 800, 905, 150, 0.0, color(146, 22, 48), color(255, 198, 108), 240, false, false, false);
  ribbon(1300, 2090, 800, 905, 150, 2.6, color(52, 36, 112), color(255, 112, 172), 240, false, false, false);

  // la flamme née de leur rencontre
  ribbon(800, 915, 800, 430, 105, 4.2, color(255, 214, 140), color(255, 255, 255), 210, true, false, true);
  ribbon(798, 910, 545, 500, 30, 1.2, color(255, 190, 120), color(255, 130, 170), 130, true, false, true);
  ribbon(802, 910, 1065, 490, 30, 5.6, color(255, 150, 190), color(150, 130, 255), 130, true, false, true);

  // reflets internes
  ribbon(300, 2090, 800, 905, 150, 0.0, color(255, 120, 90), color(255, 235, 180), 110, false, true, false);
  ribbon(1300, 2090, 800, 905, 150, 2.6, color(150, 120, 255), color(255, 170, 220), 110, false, true, false);
  ribbon(800, 915, 800, 430, 105, 4.2, color(255, 240, 210), color(255, 255, 255), 130, true, true, true);

  // cœur de lumière
  glow(800, 895, 330, color(255, 210, 130), 150);
  glow(800, 895, 140, color(255, 248, 228), 210);

  // étincelles qui montent
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 340; i++) {
    const life = random(1);
    const y = 900 - life * life * 1300 - life * 120;
    const x = 800 + (noise(i * 0.113, 5.5) - 0.5) * (70 + life * 520) + sin(life * 12 + i * 0.7) * 24;
    const r = random(1, 5.4) * (1 - life * 0.55) + 0.6;
    let cr, cg, cb;
    if (random() > 0.42) {
      cr = 255; cg = random(150, 232); cb = random(90, 175);
    } else {
      cr = random(180, 255); cg = random(120, 195); cb = 255;
    }
    fill(cr, cg, cb, 235 * pow(1 - life, 2) + 8);
    ellipse(x, y, r * 2, r * 2);
  }
  pop();

  // grain de toile
  noStroke();
  for (let i = 0; i < 7000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.5) {
      fill(255, 240, 220, random(3, 8));
    } else {
      fill(0, 0, 12, random(3, 8));
    }
    const s = random(1, 2.4);
    rect(x, y, s, s);
  }

  // vignettage
  noStroke();
  const cx = width / 2;
  const cy = height * 0.46;
  const maxR = 1360;
  const minR = 600;
  for (let r = maxR; r > minR; r -= 16) {
    const f = (r - minR) / (maxR - minR);
    fill(4, 3, 12, 135 * f * f);
    ellipse(cx, cy, r * 2, r * 2);
  }
}

function glow(x, y, r, col, aMax) {
  push();
  blendMode(ADD);
  noStroke();
  const steps = 64;
  for (let i = steps; i >= 1; i--) {
    const f = i / steps;
    fill(red(col), green(col), blue(col), aMax * pow(1 - f, 2.4));
    ellipse(x, y, r * f * 2, r * f * 2);
  }
  pop();
}

function pointAt(x0, y0, x1, y1, t, phase, anchorStart) {
  const k = anchorStart ? pow(t, 1.2) : pow(1 - t, 1.25);
  const sway = (sin(t * PI * 1.25 + phase) * 140 + (noise(t * 4, phase * 3.1) - 0.5) * 60) * k;
  return { x: lerp(x0, x1, t) + sway, y: lerp(y0, y1, t) };
}

function ribbon(x0, y0, x1, y1, w0, phase, colA, colB, aMax, fade, highlight, anchorStart) {
  const N = 150;
  push();
  if (highlight) blendMode(ADD);
  noStroke();
  for (let i = 1; i <= N; i++) {
    const t = i / N;
    const tp = (i - 1) / N;
    const pt = pointAt(x0, y0, x1, y1, t, phase, anchorStart);
    const pp = pointAt(x0, y0, x1, y1, tp, phase, anchorStart);
    const dx = pt.x - pp.x;
    const dy = pt.y - pp.y;
    const len = max(0.0001, sqrt(dx * dx + dy * dy));
    const nx = -dy / len;
    const ny = dx / len;
    let w = w0 * (1 - 0.62 * t) * (0.85 + 0.3 * noise(t * 6 + phase * 7)) + 4;
    if (highlight) w *= 0.38;
    const col = lerpColor(colA, colB, t);
    let a = aMax * (0.7 + 0.3 * sin(t * PI));
    if (fade) a *= pow(1 - t, 1.5);
    if (highlight) {
      const hc = lerpColor(col, color(255, 255, 255), 0.55);
      fill(red(hc), green(hc), blue(hc), a * 0.55);
    } else {
      fill(red(col), green(col), blue(col), a);
    }
    quad(
      pp.x + nx * w / 2, pp.y + ny * w / 2,
      pt.x + nx * w / 2, pt.y + ny * w / 2,
      pt.x - nx * w / 2, pt.y - ny * w / 2,
      pp.x - nx * w / 2, pp.y - ny * w / 2
    );
  }
  pop();
}

const W = 1600;
const H = 2000;
const HORIZON = 1150;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  paintSky();
  paintClouds();
  paintStars();
  paintWater();
  paintHills();
  paintSunGlow();
  paintSun();
  paintWaterStreaks();
  paintSwanReflection(540, 1);
  paintSwanReflection(1060, -1);
  rippleLines();
  drawSwan(540, 1);
  drawSwan(1060, -1);
  drawHeartGlow(800, 712, 32);
  paintFireflies();
  paintReeds();
  paintGrain();
  paintVignette();
}

function skyColor(y) {
  const t = constrain(y / HORIZON, 0, 1);
  if (t < 0.4) return lerpColor(color(23, 17, 48), color(64, 38, 96), t / 0.4);
  if (t < 0.75) return lerpColor(color(64, 38, 96), color(150, 66, 104), (t - 0.4) / 0.35);
  return lerpColor(color(150, 66, 104), color(240, 160, 94), (t - 0.75) / 0.25);
}

function waterColor(y) {
  const t = constrain((y - HORIZON) / (H - HORIZON), 0, 1);
  if (t < 0.25) return lerpColor(color(224, 138, 88), color(156, 85, 112), t / 0.25);
  if (t < 0.6) return lerpColor(color(156, 85, 112), color(74, 52, 104), (t - 0.25) / 0.35);
  return lerpColor(color(74, 52, 104), color(26, 20, 50), (t - 0.6) / 0.4);
}

function paintSky() {
  noStroke();
  for (let y = 0; y < HORIZON; y += 3) {
    fill(skyColor(y));
    rect(0, y, W, 3.5);
  }
  for (let i = 0; i < 320; i++) {
