  bezierVertex(cx + 0.95 * s, cy - 0.95 * s, cx + 1.7 * s, cy + 0.15 * s, cx, cy + 0.95 * s);
  endShape(CLOSE);
}

function drawHeartGlow(cx, cy, s) {
  noStroke();
  const layers = [[3.6, 16], [2.8, 26], [2.1, 40], [1.6, 60], [1.25, 90], [1.0, 130]];
  for (const [k, a] of layers) {
    fill(255, 205, 150, a);
    heartPath(cx, cy, s * k);
  }
  fill(255, 244, 224, 255);
  heartPath(cx, cy, s * 0.62);
  for (let i = 0; i < 7; i++) {
    const ang = random(TWO_PI);
    const d = random(s * 1.6, s * 3.4);
    const x = cx + cos(ang) * d;
    const y = cy + sin(ang) * d * 0.8;
    const r = random(1.5, 4);
    if (random() < 0.4) {
      fill(255, 240, 215, 60);
      ellipse(x, y, r * 4, r * 4);
    }
    fill(255, 240, 215, random(120, 230));
    ellipse(x, y, r, r);
  }
  push();
  translate(cx, cy - s * 1.9);
  rotate(PI / 4);
  fill(255, 248, 230, 200);
  rect(-3.5, -3.5, 7, 7);
  pop();
}

