function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const W = 1600, H = 2000;
  const horizon = 1240;
  const waterLine = 1315;
  const cx = 800;
  const ctx = drawingContext;

  // ---- ciel en dégradé crépusculaire ----
  let g = ctx.createLinearGradient(0, 0, 0, horizon);
  g.addColorStop(0.00, '#100d2e');
  g.addColorStop(0.42, '#2c1e5e');
  g.addColorStop(0.72, '#6b3a76');
  g.addColorStop(0.90, '#c96a6d');
  g.addColorStop(1.00, '#f0a06a');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, horizon);

  // ---- étoiles ----
  for (let i = 0; i < 240; i++) {
    const x = random(W);
    const y = random(horizon * 0.8);
    const fade = 1 - y / (horizon * 0.9);
    const a = random(0.15, 0.9) * max(0.15, fade);
    const s = random(0.6, 2.4);
    noStroke();
    fill(255, 244, 224, a);
    ellipse(x, y, s, s);
    if (s > 1.7) {
      fill(255, 220, 180, a * 0.25);
      ellipse(x, y, s * 3, s * 3);
    }
  }

  // ---- rives lointaines ----
  noStroke();
  fill(24, 18, 52, 235);
  beginShape();
  vertex(0, horizon);
  for (let x = 0; x <= W; x += 40) {
    vertex(x, horizon - 6 - noise(x * 0.004) * 48);
  }
  vertex(W, horizon);
  endShape(CLOSE);

  // ---- halo et cœur de lumière ----
  function glowOrb(x, y, r) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 6; i >= 1; i--) {
      const rr = r * i * 0.55;
      const rg = ctx.createRadialGradient(x, y, 0, x, y, rr);
      rg.addColorStop(0, 'rgba(255,228,175,' + (0.16 / i) + ')');
      rg.addColorStop(1, 'rgba(255,150,80,0)');
      ctx.fillStyle = rg;
      ctx.beginPath();
      ctx.arc(x, y, rr, 0, TAU);
      ctx.fill();
    }
    const core = ctx.createRadialGradient(x, y, 0, x, y, r * 0.6);
    core.addColorStop(0, 'rgba(255,252,240,0.98)');
    core.addColorStop(0.55, 'rgba(255,214,150,0.9)');
    core.addColorStop(1, 'rgba(255,170,100,0)');
    ctx.fillStyle = core;
    ctx.beginPath();
    ctx.arc(x, y, r * 0.6, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
  glowOrb(cx, 1030, 150);

  // ---- eau ----
  let g2 = ctx.createLinearGradient(0, horizon, 0, H);
  g2.addColorStop(0.00, '#e89a6a');
  g2.addColorStop(0.10, '#8a4a6e');
  g2.addColorStop(0.35, '#2c2058');
  g2.addColorStop(1.00, '#0a0820');
  ctx.fillStyle = g2;
  ctx.fillRect(0, horizon, W, H - horizon);

  // ---- reflets des cygnes ----
  function thickCurve(p0, c1, c2, p1, w0, w1, col, a) {
    const N = 50;
    const L = [], R = [];
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const e = 0.012;
      const x = bezierPoint(p0[0], c1[0], c2[0], p1[0], t);
      const y = bezierPoint(p0[1], c1[1], c2[1], p1[1], t);
      const xa = bezierPoint(p0[0], c1[0], c2[0], p1[0], max(0, t - e));
      const ya = bezierPoint(p0[1], c1[1], c2[1], p1[1], max(0, t - e));
      const xb = bezierPoint(p0[0], c1[0], c2[0], p1[0], min(1, t + e));
      const yb = bezierPoint(p0[1], c1[1], c2[1], p1[1], min(1, t + e));
      let tx = xb - xa, ty = yb - ya;
      const m = Math.hypot(tx, ty) || 1;
      tx /= m; ty /= m;
      const nx = -ty, ny = tx;
      const w = lerp(w0, w1, pow(t, 0.85)) / 2;
      L.push([x + nx * w, y + ny * w]);
      R.push([x - nx * w, y - ny * w]);
    }
    let mL = 0, mR = 0;
    L.forEach(p => mL += p[0]);
    R.forEach(p => mR += p[0]);
    const inner = (mL > mR) ? L : R;
    fill(col[0], col[1], col[2], a);
    noStroke();
    beginShape();
    L.forEach(p => vertex(p[0], p[1]));
    for (let i = R.length - 1; i >= 0; i--) vertex(R[i][0], R[i][1]);
    endShape(CLOSE);
    return inner;
  }

  function swanLocal(a) {
    // corps
    noStroke();
    fill(245, 234, 217, a);
    beginShape();
    vertex(452, 1308);
    bezierVertex(468, 1238, 560, 1210, 642, 1236);
    bezierVertex(706, 1256, 706, 1300, 642, 1324);
    bezierVertex(566, 1344, 484, 1338, 452, 1308);
    endShape(CLOSE);
    // queue
    fill(240, 228, 208, a);
    beginShape();
    vertex(470, 1300); vertex(408, 1268); vertex(452, 1292);
    vertex(414, 1300); vertex(456, 1306); vertex(420, 1326); vertex(470, 1316);
    endShape(CLOSE);
    // aile
    noFill();
    stroke(196, 178, 158, 140 * a); strokeWeight(5);
    bezier(505, 1308, 560, 1246, 640, 1244, 668, 1292);
    strokeWeight(3);
    bezier(520, 1316, 575, 1268, 630, 1266, 655, 1300);
    noStroke();
    fill(120, 112, 152, 70 * a);
    ellipse(565, 1318, 250, 46);
    // cou
    const p0 = [612, 1264], c1 = [556, 1118], c2 = [646, 958], p1 = [792, 842];
    const inner = thickCurve(p0, c1, c2, p1, 68, 30, [247, 236, 219], a);
    // liseré doré côté lumière
    noFill();
    stroke(255, 190, 110, 70 * a); strokeWeight(18);
    beginShape(); inner.forEach(p => vertex(p[0], p[1])); endShape();
    stroke(255, 214, 150, 210 * a); strokeWeight(7);
    beginShape(); inner.forEach(p => vertex(p[0], p[1])); endShape();
    // tête
    const e = 0.012;
    const tx = bezierPoint(p0[0], c1[0], c2[0], p1[0], 1) - bezierPoint(p0[0], c1[0], c2[0], p1[0], 1 - e);
    const ty = bezierPoint(p0[1], c1[1], c2[1], p1[1], 1) - bezierPoint(p0[1], c1[1], c2[1], p1[1], 1 - e);
    const ang = Math.atan2(ty, tx);
    push();
    translate(p1[0], p1[1]);
    rotate(ang);
    fill(247, 236, 219, a);
    ellipse(12, 0, 60, 42);
    fill(122, 47, 58, a);
    beginShape();
    vertex(36, -8); vertex(74, 2); vertex(36, 10);
    endShape(CLOSE);
    fill(20, 14, 40, a);
    ellipse(18, -7, 9, 9);
    pop();
  }

  // reflets dans l'eau
  push();
  translate(0, 2 * waterLine);
  scale(1, -1);
  drawingContext.globalAlpha = 0.13;
  swanLocal(1);
  push();
  translate(cx, 0); scale(-1, 1); translate(-cx, 0);
  swanLocal(1);
  pop();
  pop();
  drawingContext.globalAlpha = 1;

  // fondu de profondeur sur l'eau
  let g3 = ctx.createLinearGradient(0, horizon, 0, H);
  g3.addColorStop(0, 'rgba(20,14,48,0)');
  g3.addColorStop(1, 'rgba(8,6,24,0.55)');
  ctx.fillStyle = g3;
  ctx.fillRect(0, horizon, W, H - horizon);

  // colonne dorée réfléchie
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let y = horizon + 4; y < H; y += 7) {
    const t = (y - horizon) / (H - horizon);
    const w = 90 * (1 - t) + 22 + noise(y * 0.03) * 46;
    const a = 0.22 * (1 - t) + 0.02;
    const x = cx + (noise(y * 0.013 + 5) - 0.5) * 80 * (0.4 + t);
    ctx.fillStyle = 'rgba(255,190,120,' + a + ')';
    ctx.fillRect(x - w / 2, y, w, 7);
  }
  ctx.restore();

  // rides de lumière sur l'eau
  for (let i = 0; i < 170; i++) {
    const y = horizon + random(H - horizon);
    const t = (y - horizon) / (H - horizon);
    const w = random(30, 260) * (1 - t * 0.6);
    const x = random(W);
    noStroke();
    fill(255, 205, 150, random(0.03, 0.12) * (1 - t));
    rect(x, y, w, random(1, 3));
  }

  // ombres des cygnes
  noStroke();
  fill(10, 8, 30, 0.35);
  ellipse(565, 1328, 360, 52);
  ellipse(1035, 1328, 360, 52);

  // ---- les deux cygnes ----
  swanLocal(1);
  push();
  translate(cx, 0); scale(-1, 1); translate(-cx, 0);
  swanLocal(1);
  pop();

  // voile de lumière au creux du cœur
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const hg = ctx.createRadialGradient(cx, 1030, 0, cx, 1030, 300);
  hg.addColorStop(0, 'rgba(255,220,160,0.35)');
  hg.addColorStop(1, 'rgba(255,170,100,0)');
  ctx.fillStyle = hg;
  ctx.fillRect(cx - 300, 730, 600, 600);
  ctx.restore();

  // étincelles
  function sparkle(x, y, s, a) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(255,246,220,' + a + ')';
    ctx.lineWidth = s * 0.35;
    ctx.beginPath();
    ctx.moveTo(x - s, y); ctx.lineTo(x + s, y);
    ctx.moveTo(x, y - s); ctx.lineTo(x, y + s);
    ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,245,' + a + ')';
    ctx.beginPath(); ctx.arc(x, y, s * 0.3, 0, TAU); ctx.fill();
    ctx.restore();
  }
  sparkle(cx, 1000, 26, 0.95);
  sparkle(742, 936, 12, 0.7);
  sparkle(858, 936, 12, 0.7);
  sparkle(768, 1122, 10, 0.6);
  sparkle(832, 1122, 10, 0.6);

  // lucioles
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 110; i++) {
    const x = random(W);
    const y = random(H * 0.96);
    const r = random(1, 3.4);
    const a = random(0.15, 0.75);
    noStroke();
    fill(255, 214, 150, a * 0.25);
    ellipse(x, y, r * 4, r * 4);
    fill(255, 236, 190, a);
    ellipse(x, y, r, r);
  }
  ctx.restore();

  // ---- roseaux en silhouette ----
  function reed(x0, h, lean) {
    const p0 = [x0, H + 20];
    const c1 = [x0 + lean * 0.3, H - h * 0.4];
    const c2 = [x0 + lean * 0.7, H - h * 0.75];
    const p1 = [x0 + lean, H - h];
    thickCurve(p0, c1, c2, p1, 16, 3, [10, 8, 26], 0.95);
    push();
    translate(p1[0], p1[1]);
    rotate(Math.atan2(-(H - h - (H + 20)) , lean) * 0.9 + HALF_PI * 0.0);
    rotate(Math.atan2(p1[1] - p0[1], p1[0] - p0[0]) + HALF_PI);
    noStroke();
    fill(26, 20, 48, 0.95);
    ellipse(0, -14, 16, 40);
    pop();
  }
  for (let i = 0; i < 7; i++) reed(random(30, 250), random(200, 540), random(-140, 60));
  for (let i = 0; i < 7; i++) reed(random(1350, 1570), random(200, 540), random(-60, 140));

  // ---- grain pictural ----
  for (let i = 0; i < 9000; i++) {
    const x = random(W), y = random(H);
    noStroke();
    if (random() < 0.5) fill(255, 240, 220, random(0.02, 0.05));
    else fill(0, 0, 20, random(0.02, 0.05));
    rect(x, y, random(1, 2.5), random(1, 2.5));
  }

  // ---- vignettage ----
  const vg = ctx.createRadialGradient(cx, H * 0.45, H * 0.25, cx, H * 0.45, H * 0.85);
  vg.addColorStop(0, 'rgba(8,6,24,0)');
  vg.addColorStop(1, 'rgba(8,6,24,0.6)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);

  noLoop();
}

// p5.js 1.11 — peinture fixe autonome, toile 1600 x 2000
const W = 1600, H = 2000;
const C = { x: 800, y: 1000 };
const SOUL_A = { x: 520, y: 740, r: 300 };
const SOUL_B = { x: 1080, y: 1260, r: 320 };
const GOLD = ['#fff3c4', '#ffd27a', '#ffb35e', '#ff8f5e', '#ffe9a8'];
const ROSE = ['#ffe0ec', '#ff9ec7', '#ff5e8a', '#e0559e', '#c86bff'];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  backgroundDeep();
  nebula();
  milkyWay();
  stars();
  soulGlow(SOUL_A, 255, 210, 122, 0.15);
  soulGlow(SOUL_B, 255, 120, 170, 0.15);
  streams();
  drawSoul(SOUL_A, GOLD);
  drawSoul(SOUL_B, ROSE);
  heartGlow();
  petals(140);
  branches();
  petals(36);
  vignette();
  grain();
}

function backgroundDeep() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.0, '#0b0722');
  g.addColorStop(0.45, '#1c0f3d');
  g.addColorStop(0.75, '#33123a');
  g.addColorStop(1.0, '#180a24');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function nebula() {
  blendMode(ADD);
  noStroke();
  const cols = ['#3b2a7a', '#5a2a72', '#7a2a5e', '#274a8a', '#8a3a6a', '#6a2a4a'];
  for (let i = 0; i < 46; i++) {
    const x = random(W);
    const y = random(H * 0.85);
    const r = random(180, 620);
    const c = color(cols[floor(random(cols.length))]);
    c.setAlpha(random(10, 26));
    fill(c);
    ellipse(x, y, r * 2, r * random(0.5, 1.1));
  }
  blendMode(BLEND);
}

function milkyWay() {
  blendMode(ADD);
  for (let i = 0; i < 900; i++) {
    const t = random(1);
    const x = t * W * 1.1 - 60;
    const y = t * H * 0.62 + randomGaussian() * 90 - 40;
    let a = random(4, 16) * (1 - abs(t - 0.45) * 1.2);
    a = max(a, 0);
    stroke(200, 210, 255, a);
    strokeWeight(random(0.5, 1.8));
    point(x, y);
  }
  blendMode(BLEND);
}

function stars() {
  noStroke();
  for (let i = 0; i < 240; i++) {
    const x = random(W);
    const y = random(H * 0.8);
    const r = random(0.6, 2.4);
    const warm = random(1) < 0.25;
    const c = warm ? color(255, 235, 200) : color(210, 220, 255);
    const a = random(60, 220);
    if (random(1) < 0.12) {
      blendMode(ADD);
      fill(red(c), green(c), blue(c), a * 0.22);
      circle(x, y, r * 7);
      blendMode(BLEND);
    }
    fill(red(c), green(c), blue(c), a);
    circle(x, y, r * 2);
  }
}

function soulGlow(s, r, g, b, a) {
  const ctx = drawingContext;
  blendMode(ADD);
  const grad = ctx.createRadialGradient(s.x, s.y, 10, s.x, s.y, s.r * 1.5);
  grad.addColorStop(0, 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')');
  grad.addColorStop(0.5, 'rgba(' + r + ',' + g + ',' + b + ',' + a * 0.45 + ')');
  grad.addColorStop(1, 'rgba(' + r + ',' + g + ',' + b + ',0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(s.x, s.y, s.r * 1.5, 0, TWO_PI);
  ctx.fill();
  blendMode(BLEND);
}

function drawSoul(s, palette) {
  blendMode(ADD);
  noStroke();
  const rings = 26;
  for (let k = 0; k < rings; k++) {
    const baseR = s.r * (k + 1) / rings;
    const wob = 0.16 + 0.1 * noise(k * 0.7);
    const pts = 40 + k * 3;
    for (let i = 0; i < pts; i++) {
      const a = (i / pts) * TWO_PI;
      const rr = baseR * (1 + wob * (noise(cos(a) * 2.1 + k * 0.35, sin(a) * 2.1) - 0.5) * 2);
      let x = s.x + cos(a) * rr;
      let y = s.y + sin(a) * rr * 0.92;
      const pull = 0.16 * (baseR / s.r);
      x = lerp(x, C.x, pull);
      y = lerp(y, C.y, pull);
      const n = noise(x * 0.004, y * 0.004 + k * 0.13);
      const col = color(palette[floor(n * palette.length) % palette.length]);
      col.setAlpha(random(14, 60) * (1 - (baseR / s.r) * 0.5));
      fill(col);
      const sz = random(1, 2.6) + (1 - baseR / s.r) * 2.2;
      circle(x, y, sz);
    }
  }
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(s.x, s.y, 2, s.x, s.y, s.r * 0.42);
  g.addColorStop(0, 'rgba(255,244,220,0.5)');
  g.addColorStop(1, 'rgba(255,244,220,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(s.x, s.y, s.r * 0.42, 0, TWO_PI);
  ctx.fill();
  blendMode(BLEND);
}

function streams() {
  blendMode(ADD);
  noFill();
  const n = 90;
  const cA = color(GOLD[1]);
  const cB = color(ROSE[2]);
  for (let i = 0; i < n; i++) {
    const x0 = lerp(SOUL_A.x, SOUL_B.x, random(-0.15, 0.35));
    const y0 = lerp(SOUL_A.y, SOUL_B.y, random(-0.15, 0.35)) + random(-120, 120);
    const x1 = lerp(SOUL_A.x, SOUL_B.x, random(0.65, 1.15));
    const y1 = lerp(SOUL_A.y, SOUL_B.y, random(0.65, 1.15)) + random(-120, 120);
    const cx1 = lerp(x0, x1, random(0.3, 0.45)) + random(-260, 260) + (C.x - (x0 + x1) / 2) * 0.5;
    const cy1 = lerp(y0, y1, random(0.25, 0.4)) + random(-260, 260) + (C.y - (y0 + y1) / 2) * 0.6;
    const cx2 = lerp(x0, x1, random(0.55, 0.7)) + random(-260, 260);
    const cy2 = lerp(y0, y1, random(0.6, 0.75)) + random(-260, 260);
    const steps = 26;
    let px = x0, py = y0;
    for (let s = 1; s <= steps; s++) {
      const t = s / steps;
      const mt = 1 - t;
      const x = mt * mt * mt * x0 + 3 * mt * mt * t * cx1 + 3 * mt * t * t * cx2 + t * t * t * x1;
      const y = mt * mt * mt * y0 + 3 * mt * mt * t * cy1 + 3 * mt * t * t * cy2 + t * t * t * y1;
      const col = lerpColor(cA, cB, t);
      col.setAlpha(random(8, 26));
      stroke(col);
      strokeWeight(random(0.5, 1.9));
      line(px, py, x, y);
      px = x; py = y;
    }
  }
  blendMode(BLEND);
}

function heartPath(x, y, s) {
  const ctx = drawingContext;
  ctx.beginPath();
  ctx.moveTo(x, y + s * 0.9);
  ctx.bezierCurveTo(x - s * 1.25, y + s * 0.05, x - s * 0.62, y - s * 0.75, x, y - s * 0.28);
  ctx.bezierCurveTo(x + s * 0.62, y - s * 0.75, x + s * 1.25, y + s * 0.05, x, y + s * 0.9);
  ctx.closePath();
}

function heartGlow() {
  const ctx = drawingContext;
  blendMode(ADD);
  const g = ctx.createRadialGradient(C.x, C.y, 10, C.x, C.y, 430);
  g.addColorStop(0, 'rgba(255,214,180,0.50)');
  g.addColorStop(0.35, 'rgba(255,160,180,0.30)');
  g.addColorStop(0.7, 'rgba(230,110,170,0.12)');
  g.addColorStop(1, 'rgba(230,110,170,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(C.x, C.y, 430, 0, TWO_PI);
  ctx.fill();
  for (let i = 6; i >= 1; i--) {
    const s = 300 * (i / 6) * 0.9 + 40;
    const a = 0.05 + (7 - i) * 0.03;
    ctx.fillStyle = 'rgba(255,' + (170 + (7 - i) * 10) + ',' + (190 + (7 - i) * 8) + ',' + a + ')';
    heartPath(C.x, C.y - 20, s * 0.62);
    ctx.fill();
  }
  const g2 = ctx.createRadialGradient(C.x, C.y - 10, 2, C.x, C.y - 10, 150);
  g2.addColorStop(0, 'rgba(255,250,235,0.85)');
  g2.addColorStop(1, 'rgba(255,200,190,0)');
  ctx.fillStyle = g2;
  ctx.beginPath();
  ctx.arc(C.x, C.y - 10, 150, 0, TWO_PI);
  ctx.fill();
  blendMode(BLEND);
}

function petals(count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(W);
    let y = random(H);
    const n = noise(x * 0.003, y * 0.003);
    if (n > 0.62) {
      x = lerp(x, C.x, 0.4);
      y = lerp(y, C.y, 0.4);
    }
    const pink = random(1) < 0.7;
    const pal = pink ? ROSE : GOLD;
    const c = color(pal[floor(random(pal.length))]);
    c.setAlpha(random(40, 160));
    fill(c);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    const s = random(4, 12);
    ellipse(0, 0, s, s * 0.55);
    pop();
  }
}

const BRANCH_COL = [14, 9, 28];

function branches() {
  strokeCap(ROUND);
  branch(240, H + 40, -PI / 2 + 0.5, 210, 26, 7);
  branch(W - 240, H + 40, -PI / 2 - 0.5, 210, 26, 7);
  branch(110, H + 60, -PI / 2 + 0.85, 160, 18, 6);
  branch(W - 110, H + 60, -PI / 2 - 0.85, 160, 18, 6);
  const ctx = drawingContext;
  blendMode(ADD);
  const g = ctx.createRadialGradient(800, 1520, 10, 800, 1520, 360);
  g.addColorStop(0, 'rgba(255,150,190,0.16)');
  g.addColorStop(1, 'rgba(255,150,190,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(800, 1520, 360, 0, TWO_PI);
  ctx.fill();
  blendMode(BLEND);
}

function branch(x, y, ang, len, wd, depth) {
  if (depth <= 0 || len < 6) {
    if (random(1) < 0.8) blossom(x, y, true);
    return;
  }
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  stroke(BRANCH_COL[0], BRANCH_COL[1], BRANCH_COL[2], 235);
  strokeWeight(wd);
  line(x, y, x2, y2);
  if (depth > 2 && depth < 7 && random(1) < 0.12) {
    blossom(x2 + random(-14, 14), y2 + random(-14, 14), true);
  }
  const n = depth > 6 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let na = ang + random(-0.5, 0.5) + (i - (n - 1) / 2) * 0.42;
    const target = atan2(1450 - y2, 800 - x2);
    na = lerpAngle(na, target, 0.16);
    branch(x2, y2, na, len * random(0.66, 0.8), wd * 0.66, depth - 1);
  }
}

function lerpAngle(a, b, t) {
  let d = b - a;
  while (d > PI) d -= TWO_PI;
  while (d < -PI) d += TWO_PI;
  return a + d * t;
}

function blossom(x, y, glow) {
  const s = random(7, 15);
  if (glow) {
    blendMode(ADD);
    noStroke();
    fill(255, 150, 200, 42);
    circle(x, y, s * 3.4);
    blendMode(BLEND);
  }
  const base = color(ROSE[1 + floor(random(3))]);
  for (let p = 0; p < 5; p++) {
    const a = (p / 5) * TWO_PI + random(0.4);
    push();
    translate(x, y);
    rotate(a);
    base.setAlpha(random(150, 240));
    noStroke();
    fill(base);
    ellipse(s * 0.62, 0, s * 0.78, s * 0.52);
    pop();
  }
  noStroke();
  fill(255, 230, 160, 240);
  circle(x, y, s * 0.36);
}

function vignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(W / 2, H * 0.46, H * 0.25, W / 2, H * 0.5, H * 0.78);
  g.addColorStop(0, 'rgba(4,2,12,0)');
  g.addColorStop(1, 'rgba(4,2,12,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function grain() {
  for (let i = 0; i < 6000; i++) {
    const x = random(W);
    const y = random(H);
    if (random(1) < 0.5) stroke(255, 255, 255, random(4, 14));
    else stroke(0, 0, 0, random(4, 14));
    strokeWeight(1);
    point(x, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  // Fond : nuit profonde en dégradé
  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0.0, '#060512');
  bg.addColorStop(0.4, '#120e2e');
  bg.addColorStop(0.72, '#1c1040');
  bg.addColorStop(1.0, '#090616');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  // Nébuleuse de violets
  noStroke();
  for (let i = 0; i < 240; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0011, y * 0.0011, i * 0.01);
    let r = 140 + n * 380;
    let c = lerpColor(color('#1a1245'), color('#3d1e63'), n);
    fill(red(c), green(c), blue(c), 16);
    push();
    translate(x, y);
    rotate(n * PI);
    ellipse(0, 0, r * 2, r * 1.3);
    pop();
  }

  // Cœur fantôme géant, à peine visible
  noFill();
  stroke(255, 170, 200, 10);
  strokeWeight(26);
  heartPath(800, 1010, 1.55);
  stroke(255, 205, 225, 5);
  strokeWeight(10);
  heartPath(800, 1010, 1.55);

  // Tout ce qui brille est dessiné en additif
  blendMode(ADD);

  // Anneaux ondulants autour du point de rencontre
  for (let r = 260; r <= 980; r += 92) {
    stroke(255, 205, 130, 14);
    strokeWeight(2.5);
    organicRing(800, 1000, r, 0.045, r * 0.013);
  }

  // Lumière froide, en haut à droite
  softOrganic(1055, 720, 500, 0.28, 3.7, color('#d9c8ff'), color('#232a6e'), 46, 1.08);

  // Lumière chaude, en bas à gauche
  softOrganic(545, 1290, 510, 0.30, 8.2, color('#ffe9b0'), color('#b0244a'), 46, 1.05);

  // Filaments dorés qui relient les deux êtres
  goldThreads();

  // Lueur centrale où tout fusionne en or
  radialGlow(800, 1000, 620, 'rgba(255,214,140,0.55)', 'rgba(255,170,100,0.18)', 'rgba(255,150,90,0)');
  radialGlow(800, 1000, 240, 'rgba(255,246,220,0.95)', 'rgba(255,210,140,0.40)', 'rgba(255,190,120,0)');

  // Grosses bulles de lumière floues
  for (let i = 0; i < 16; i++) {
    let x = constrain(800 + randomGaussian() * 420, 0, width);
    let y = constrain(1000 + randomGaussian() * 460, 0, height);
    let r = random(26, 95);
    noStroke();
    fill(255, 210, 150, random(8, 20));
    ellipse(x, y, r * 2, r * 2);
  }

  // Étincelles, plus denses au centre
  sparks();

  blendMode(BLEND);

  // Grain de pellicule
  strokeWeight(1);
  for (let i = 0; i < 16000; i++) {
    stroke(random(255), random(255), random(255), random(4, 10));
    point(random(width), random(height));
  }

  // Vignettage
  let vg = ctx.createRadialGradient(width / 2, height / 2, height * 0.28,
                                    width / 2, height / 2, height * 0.75);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(2,0,8,0.6)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

// Grand cœur tracés en bézier, sans remplissage
function heartPath(cx, cy, s) {
  beginShape();
  vertex(cx, cy + 300 * s);
  bezierVertex(cx - 430 * s, cy + 60 * s, cx - 330 * s, cy - 300 * s, cx, cy - 130 * s);
  bezierVertex(cx + 330 * s, cy - 300 * s, cx + 430 * s, cy + 60 * s, cx, cy + 300 * s);
  endShape();
}

// Forme organique douce : empilement de couches rétrécissantes
function softOrganic(cx, cy, R, wob, off, cIn, cOut, layers, sy) {
  const steps = 110;
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let f = i / layers;
    let g = 1 - f; // 0 au bord, 1 au centre
    let col = lerpColor(cOut, cIn, pow(g, 0.7));
    let a = map(i, 1, layers, 30, 7);
    fill(red(col), green(col), blue(col), a);
    beginShape();
    for (let s = 0; s <= steps; s++) {
      let ang = (s / steps) * TAU;
      let rr = R * f * (1 + wob * noise(off + cos(ang) * 1.7, off + sin(ang) * 1.7));
      vertex(cx + cos(ang) * rr, cy + sin(ang) * rr * sy);
    }
    endShape(CLOSE);
  }
}

// Anneau organique fin
function organicRing(cx, cy, R, wob, off) {
  const steps = 140;
  noFill();
  beginShape();
  for (let s = 0; s <= steps; s++) {
    let ang = (s / steps) * TAU;
    let rr = R * (1 + wob * noise(off + cos(ang) * 2, off + sin(ang) * 2));
    vertex(cx + cos(ang) * rr, cy + sin(ang) * rr * 0.98);
  }
  endShape(CLOSE);
}

// Filaments dorés sinueux entre les deux centres
function goldThreads() {
  noFill();
  for (let k = 0; k < 6; k++) {
    let off = k * 1.37;
    for (let pass = 0; pass < 3; pass++) {
      let w = [9, 4.5, 1.8][pass];
      let a = [10, 16, 34][pass];
      stroke(255, 205 + k * 6, 120, a);
      strokeWeight(w);
      beginShape();
      const N = 60;
      let dx = 1040 - 560, dy = 730 - 1280;
      let len = sqrt(dx * dx + dy * dy);
      let nx = -dy / len, ny = dx / len;
      for (let s = 0; s <= N; s++) {
        let t = s / N;
        let x = lerp(560, 1040, t);
        let y = lerp(1280, 730, t);
        let sway = noise(off + t * 3.1) * 160 - 80 + sin(t * PI * 2 + off) * 60;
        vertex(x + nx * sway, y + ny * sway);
      }
      endShape();
    }
  }
}

// Dégradé radial additif
function radialGlow(x, y, r, c0, c1, c2) {
  let g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, c0);
  g.addColorStop(0.45, c1);
  g.addColorStop(1, c2);
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);
}

// Étincelles dorées et roses
function sparks() {
  noStroke();
  for (let i = 0; i < 240; i++) {
    let x, y;
    if (random() < 0.55) {
      x = 800 + randomGaussian() * 300;
      y = 1000 + randomGaussian() * 340;
    } else {
      x = random(width);
      y = random(height);
    }
    x = constrain(x, 0, width);
    y = constrain(y, 0, height);
    let s = random(1.5, 6.5);
    let warm = random() < 0.72;
    let gC = warm ? random(190, 240) : random(150, 190);
    let bC = warm ? random(110, 170) : random(190, 230);
    let a = random(70, 230);
    fill(255, gC, bC, a * 0.22);
    ellipse(x, y, s * 4.5, s * 4.5);
    fill(255, gC, bC, a);
    ellipse(x, y, s, s);
  }
}
